(* [local] *)
let EVERY2_MAP_FST_SND = prove
 (`!xs. EVERY2 P (MAP FST xs) (MAP SND xs) = EVERY (\(x,y). P x y) xs`,
  (let aux = prove
    (`!(P:A->B->bool) xs.
        ALL2 P (MAP FST xs) (MAP SND xs) <=> ALL (\(x,y). P x y) xs`,
     GEN_TAC THEN LIST_INDUCT_TAC THEN
     REWRITE_TAC[MAP; ALL2; ALL] THEN
     STRUCT_CASES_TAC(ISPEC `h:A#B` PAIR_SURJECTIVE) THEN
     ASM_REWRITE_TAC[FST; SND] THEN
     CONV_TAC(ONCE_DEPTH_CONV GEN_BETA_CONV) THEN REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let fapply_fupdate_update = prove
 (`(FAPPLY) (f |+ p) = (FST p =+ SND p) ((FAPPLY) f)`,
  (let aux = prove
    (`!(f:(A,B)fmap) p. FAPPLY (f |+ p) = (FST p =+ SND p) (FAPPLY f)`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `p:A#B` PAIR_SURJECTIVE) THEN
     REWRITE_TAC[FUN_EQ_THM; UPDATE; FST; SND; FAPPLY_FUPDATE_THM] THEN
     GEN_TAC THEN REWRITE_TAC[EQ_SYM_EQ]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

(* [local] *)
let heap_lookup_APPEND1 = prove
 (`!h1 z h2.
     heap_length h1 <= z ==>
     (heap_lookup z (h1 ++ h2) = heap_lookup (z - heap_length h1)
       h2)`,
  (* past the first heap the lookup is the one of the second, and
     the two conditions of the clause are false by arithmetic *)
  (let hl = heap_lookup_def in
   let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) =
              el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   LIST_INDUCT_TAC THEN
   REWRITE_TAC[hlen_cl; APPEND; hl; SUB_0; LE_0] THEN
   REPEAT GEN_TAC THEN DISCH_TAC THEN
   MP_ISPEC_NAME "h" el_length_GT_0 THEN DISCH_TAC THEN
   COND_CASES_TAC THENL
    [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
   COND_CASES_TAC THENL
    [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
   REWRITE_TAC[ARITH_RULE `a - (b + c) = a - b - c`] THEN
   FIRST_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC));;

(* [local] *)
let heap_lookup_APPEND2 = prove
 (`!h1 z h2.
     z < heap_length h1 ==>
     (heap_lookup z (h1 ++ h2) = heap_lookup z h1)`,
  (* heap_length is the SUM of the el_lengths, so its clauses come
     first here too *)
  (let hl = heap_lookup_def in
   let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) =
              el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   LIST_INDUCT_TAC THEN
   REWRITE_TAC[hlen_cl; LT; APPEND; hl] THEN
   REPEAT GEN_TAC THEN COND_CASES_TAC THEN REWRITE_TAC[] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN
   DISCH_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC));;

(* heap_lookup_APPEND *)
let data_to_word_memoryProof_heap_lookup_APPEND = prove
 (`heap_lookup a (h1 ++ h2) =
    (if a < heap_length h1 then
    heap_lookup a h1 else
    heap_lookup (a - heap_length h1) h2)`,
  (COND_CASES_TAC THENL
    [MATCH_MP_TAC heap_lookup_APPEND2 THEN ASM_REWRITE_TAC[];
     MATCH_MP_TAC heap_lookup_APPEND1 THEN ASM_ARITH_TAC]));;

(* Prove refinement is maintained past GC calls *)

(* LENGTH_ADDR_MAP[local] *)
let data_to_word_memoryProof_LENGTH_ADDR_MAP = prove
 (`!xs f. LENGTH (ADDR_MAP f xs) = LENGTH xs`,
  (REPEAT GEN_TAC THEN
   MATCH_ACCEPT_TAC(GSYM (SPEC_ALL ADDR_MAP_LENGTH))));;

(* [local] *)
let EL_ADDR_MAP = prove
 (`!xs n f.
       n < LENGTH xs ==> (EL n (ADDR_MAP f xs) = ADDR_APPLY f (EL n
         xs))`,
  (let addrmap = ADDR_MAP_def in
   let addrapply = ADDR_APPLY_def in
   LIST_INDUCT_TAC THENL
   [REWRITE_TAC[LENGTH; LT];
    REPEAT GEN_TAC THEN CASES_BY_NAME "h" THEN
    STRUCT_CASES_TAC(SPEC `n:num` num_CASES) THEN
    ASM_REWRITE_TAC[addrmap; addrapply; EL; HD; TL; LENGTH;
                    LT_SUC; LT_0]]));;

(* HOL4 data_to_word_memoryProofScript.sml:719: ML code, not ported *)

let evaluated_thunk_ptr_def = cake_define
  `evaluated_thunk_ptr refs n <=> (?v. lookup n refs = SOME (Thunk
  Evaluated v))`;;

(* HOL4 data_to_word_memoryProofScript.sml:725-730: ML code, not
   ported *)

(* [local] *)
let v_inv_related_lemma = prove
 (`!ck w refs x f tf heap1.
     v_inv conf w refs (x,f,tf,heap1) /\
     gc_related g heap1 (heap2:(('a
       word_loc,data_to_word_memoryProof_tag#('a word_loc)
       list)heap_element) list) /\
     (!ptr u. (x = gc_shared_Pointer ptr u) ==> ptr IN FDOM g) ==>
       v_inv_ck ck conf w refs (ADDR_APPLY (FAPPLY g) x,g f_o_f f,g
         f_o_f tf,heap2) /\
       EVERY (\n. ~(n IN evaluated_thunk_ptr refs) ==> FAPPLY f n
         IN FDOM g) (get_refs w)`,
(* the induction of the source: on the counter, and on the value
   inside it (v_ind, which the port proves from the induction of
   the type with the list of a Block folded into ALL).  A Block
   has then two hypotheses to use: the counter below gives the
   invariant of each of its elements, and the value gives their
   references, which is what the second conjunct asks for, where
   the counter is of no help because it may be nought.
     A number or a word of sixty-four bits is small, and then the
   value itself moves (ADDR_APPLY), or it is an element of the
   heap without roots, which the collection keeps where its map
   sends it; a pointer of the code is no element of the heap at
   all.  A Block with elements has them as its roots, so they all
   move (ADDR_MAP of the list) and each of them is a root of the
   element, which is what the clause of gc_related asks for to
   keep its pointer.  A reference is a pointer through the map of
   the references, and the collection composes its own map with
   that one (FAPPLY_f_o_f); a thunk that the heap holds has the
   value of it as the single root of its element, and a thunk
   that was evaluated stands where its value stands, and then the
   map of the references has nothing to say about it *)
  ((let grab_asm p asl =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
  (* a lookup of a finite map that succeeds says that the key is
     in the domain and what the map gives it *)
  let flk = prove
   (`!f x y. FLOOKUP f x = SOME y
             ==> x IN FDOM f /\ FAPPLY f x = y`,
    REWRITE_TAC[FLOOKUP_DEF] THEN REPEAT GEN_TAC THEN
    COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]) in
  (* the references of a Block are those of its elements *)
  let all_flat = prove
   (`!P (ls:((A)list)list).
       EVERY P (FLAT ls) <=> EVERY (EVERY P) ls`,
    GEN_TAC THEN LIST_INDUCT_TAC THEN
    ASM_REWRITE_TAC[FLAT; ALL; ALL_APPEND]) in
  (* an element of the heap without roots the collection keeps as
     it is, and one with a single root it keeps with the root
     moved, which is the clause of gc_related in the two shapes
     that the invariant of a value asks for *)
  let gc_keep = prove
   (`gc_related g heap1 (heap2:(('a
       word_loc,data_to_word_memoryProof_tag#('a word_loc)
       list)heap_element) list)
     ==> !i l d. i IN FDOM g /\
           heap_lookup i heap1 = SOME (DataElement [] l d)
           ==> heap_lookup (FAPPLY g i) heap2 =
               SOME (DataElement [] l d)`,
    REWRITE_TAC[gc_related_def] THEN STRIP_TAC THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM (fun cl ->
      if not (is_forall (concl cl)) then fail() else
      FIRST_ASSUM (fun hl ->
        if not (try hd_is "heap_lookup" (lhs (concl hl))
                with Failure _ -> false) then fail() else
        FIRST_ASSUM (fun fd ->
          if not (hd_is "IN" (concl fd)) then fail() else
          MP_TAC (MATCH_MP cl (CONJ fd hl))))) THEN
    REWRITE_TAC[ADDR_MAP_def] THEN
    DISCH_THEN (fun th -> ACCEPT_TAC (CONJUNCT1 th))) in
  let addr_map1 = prove
   (`!f y. ADDR_MAP f [y:('a word_loc) heap_address] =
           [ADDR_APPLY f y]`,
    REPEAT GEN_TAC THEN
    STRUCT_CASES_TAC (ISPEC `y:('a word_loc) heap_address`
      (cases_of `:('a word_loc) heap_address`)) THEN
    REWRITE_TAC[ADDR_MAP_def; ADDR_APPLY_def]) in
  let gc_keep1 = prove
   (`gc_related g heap1 (heap2:(('a
       word_loc,data_to_word_memoryProof_tag#('a word_loc)
       list)heap_element) list)
     ==> !i y l d. i IN FDOM g /\
           heap_lookup i heap1 = SOME (DataElement [y] l d)
           ==> heap_lookup (FAPPLY g i) heap2 =
                 SOME (DataElement
                   [ADDR_APPLY (FAPPLY g) y] l d) /\
               (!ptr u. y = gc_shared_Pointer ptr u
                        ==> ptr IN FDOM g)`,
    REWRITE_TAC[gc_related_def] THEN STRIP_TAC THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM (fun cl ->
      if not (is_forall (concl cl)) then fail() else
      FIRST_ASSUM (fun hl ->
        if not (try hd_is "heap_lookup" (lhs (concl hl))
                with Failure _ -> false) then fail() else
        FIRST_ASSUM (fun fd ->
          if not (hd_is "IN" (concl fd)) then fail() else
          MP_TAC (MATCH_MP cl (CONJ fd hl))))) THEN
    REWRITE_TAC[addr_map1] THEN STRIP_TAC THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REPEAT GEN_TAC THEN DISCH_TAC THEN
      FIRST_ASSUM (fun mm ->
        if not (is_forall (concl mm)) then fail() else
        MATCH_MP_TAC mm) THEN
      FIRST_ASSUM (fun eq ->
        if not (try is_eq (concl eq) &&
                    hd_is "gc_shared_Pointer" (rhs (concl eq))
                with Failure _ -> false) then fail() else
        EXISTS_TAC (rand (rhs (concl eq))) THEN
        REWRITE_TAC[GSYM eq; MEM])]) in
  (* a number and a word of sixty-four bits take an element of
     the heap without roots *)
  let bignum_de = prove
   (`!i. ?l d. (Bignum i:(('a word_loc,
        data_to_word_memoryProof_tag#('a word_loc)
        list)heap_element)) = DataElement [] l d`,
    GEN_TAC THEN REWRITE_TAC[bignum_def] THEN
    PAIRARG_TAC THEN CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    MESON_TAC[]) in
  let w64_de = prove
   (`!w. ?l d. (Word64Rep (:'a) w:(('a word_loc,
        data_to_word_memoryProof_tag#('a word_loc)
        list)heap_element)) = DataElement [] l d`,
    GEN_TAC THEN
    MP_TAC (SPECL [`(:'a)`; `w:word64`] Word64Rep_DataElement) THEN
    MESON_TAC[]) in
  (* the induction of the values, with the hypothesis of a Block
     over its list *)
  let v_ind = prove
   (`!P. (!i. P (Number i)) /\ (!w. P (Word64 w)) /\
         (!ts t l. ALL P l ==> P (Block ts t l)) /\
         (!n. P (CodePtr n)) /\ (!b n. P (RefPtr b n)) ==>
         (!v. P (v:dataSem_v))`,
    GEN_TAC THEN DISCH_TAC THEN
    MP_TAC (ISPECL [`P:dataSem_v->bool`;
                    `ALL (P:dataSem_v->bool)`] dataSem_v_INDUCT) THEN
    ASM_REWRITE_TAC[ALL] THEN
    DISCH_THEN (ACCEPT_TAC o CONJUNCT1)) in
  (* the clauses of the invariant with a counter, one for each
     shape of a value, and the clause of the collection that
     moves the roots of an element *)
  let (vr,_,_) = v_inv_ck in
  let rl = CONJUNCTS vr in
  let gc_clause gr fd hl =
    MATCH_MP (CONJUNCT2 (CONJUNCT2
      (REWRITE_RULE[gc_related_def] gr))) (CONJ fd hl) in
  (* the pointer of the value is in the domain of the map of the
     collection, which the assumption of the lemma gives *)
  let ptr_in =
    W(fun (asl,gl) ->
      let fa = find_term (hd_is "fmap_apply") gl in
      SUBGOAL_THEN (list_mk_icomb "IN"
                      [rand fa; mk_icomb (`FDOM`, lhand fa)])
        ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN MESON_TAC[]; ALL_TAC]) in
  (* and an element without roots is where it was moved to *)
  let gc_move de =
    REPEAT_TCL CHOOSE_THEN (fun eq ->
      FIRST_ASSUM (fun gr ->
        if not (hd_is "gc_related" (concl gr)) then fail() else
        FIRST_ASSUM (fun hl ->
          if not (try hd_is "heap_lookup" (lhs (concl hl))
                  with Failure _ -> false) then fail() else
          FIRST_ASSUM (fun fd ->
            if not (hd_is "IN" (concl fd)) then fail() else
            let kp = MATCH_MP (MATCH_MP gc_keep gr)
                       (CONJ fd (REWRITE_RULE[eq] hl)) in
            ACCEPT_TAC (REWRITE_RULE[GSYM eq] kp))))) de in
  (* the map of the references after the collection is the
     composition, in the two directions *)
  let fof_rw =
    W(fun (asl,gl) ->
      let fd = grab_asm (fun th ->
        hd_is "IN" (concl th) && is_var (lhand (concl th))) asl in
      let inf = grab_asm (fun th ->
        hd_is "IN" (concl th) &&
        hd_is "fmap_apply" (lhand (concl th))) asl in
      REWRITE_TAC[GSYM (MATCH_MP FAPPLY_f_o_f (CONJ fd inf))]) in
  let fof_fwd =
    W(fun (asl,gl) ->
      let fd = grab_asm (fun th ->
        hd_is "IN" (concl th) && is_var (lhand (concl th))) asl in
      let inf = grab_asm (fun th ->
        hd_is "IN" (concl th) &&
        hd_is "fmap_apply" (lhand (concl th))) asl in
      REWRITE_TAC[MATCH_MP FAPPLY_f_o_f (CONJ fd inf)]) in
  (* and a key of the composition is a key of the two maps *)
  let in_fof =
    REWRITE_TAC[f_o_f_DEF; IN_ELIM_THM] THEN ASM_REWRITE_TAC[] in
  (* the element of a Block at an index: its root is one of the
     Block's, so the clause of gc_related keeps its pointer, the
     hypothesis of the counter carries the invariant of it over
     and the hypothesis of the value its references *)
  let elem_tac part =
    W(fun (asl,gl) ->
      let a2e = grab_asm (fun th -> hd_is "ALL2" (concl th)) asl in
      let eqn = REWRITE_RULE[LIST_REL_EL_EQN] a2e in
      let lt = grab_asm (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th)))
        asl in
      let ltx = MATCH_MP (ARITH_RULE
                  `!j la lx:num. j < la /\ la = lx ==> j < lx`)
                  (CONJ lt (CONJUNCT1 eqn)) in
      let vi = BETA_RULE (MP (SPEC (lhand (concl lt))
                 (CONJUNCT2 eqn)) lt) in
      let gr = grab_asm (fun th -> hd_is "gc_related" (concl th))
                 asl in
      let fd = grab_asm (fun th -> hd_is "IN" (concl th)) asl in
      let hl = grab_asm (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        hd_is "BlockRep" (rand (rhs (concl th)))) asl in
      let cl = gc_clause gr fd (REWRITE_RULE[BlockRep_def] hl) in
      let elt = lhand (rand (concl vi)) in
      let eqt = mk_eq (elt, list_mk_icomb "gc_shared_Pointer"
                              [`ptr':num`; `u:'a word_loc`]) in
      let pc = GENL [`ptr':num`; `u:'a word_loc`]
                 (DISCH eqt (MATCH_MP (CONJUNCT2 cl)
                    (REWRITE_RULE[ASSUME eqt]
                       (MATCH_MP MEM_EL ltx)))) in
      if part = 1 then
        USE_THEN "ckih" (fun ih ->
          let nz = grab_asm (fun th ->
            is_neg (concl th) && is_eq (rand (concl th)) &&
            rhs (rand (concl th)) = `0`) asl in
          let ck = lhs (rand (concl nz)) in
          let ltck = MP (SPEC ck (ARITH_RULE
                       `!n. ~(n = 0) ==> n - 1 < n`)) nz in
          let ih' = MP (SPEC (mk_binop `(-):num->num->num` ck `1`)
                       ih) ltck in
          let res = MATCH_MP ih' (CONJ vi (CONJ gr pc)) in
          MP_TAC (MATCH_MP EL_ADDR_MAP ltx) THEN
          DISCH_THEN (fun th -> REWRITE_TAC[th]) THEN
          MATCH_ACCEPT_TAC (CONJUNCT1 res))
      else
        USE_THEN "vih" (fun vih ->
          let ihe = BETA_RULE (MATCH_MP
                      (REWRITE_RULE[GSYM ALL_MEM] vih)
                      (MATCH_MP MEM_EL lt)) in
          let res = MATCH_MP ihe (CONJ vi (CONJ gr pc)) in
          MATCH_ACCEPT_TAC (CONJUNCT2 res))) in
  (* a number: it is small, and then the value itself moves, or it
     is an element of the heap that the collection keeps *)
  let c1 =
    COND_CASES_TAC THEN STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
    REWRITE_TAC[get_refs_def; ALL; ADDR_APPLY_def] THENL
     [MATCH_MP_TAC (el 0 rl) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC (el 1 rl) THEN ASM_REWRITE_TAC[] THEN
      ptr_in THEN
      W(fun (asl,gl) ->
        let elt = rand (rand gl) in
        gc_move (SPEC (rand elt) bignum_de))] in
  (* a word of sixty-four bits: the same, without the small case *)
  let c2 =
    STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
    REWRITE_TAC[get_refs_def; ALL; ADDR_APPLY_def] THEN
    MATCH_MP_TAC (el 2 rl) THEN ptr_in THEN
    W(fun (asl,gl) ->
      let elt = rand (rand gl) in
      gc_move (SPEC (rand elt) w64_de)) in
  (* a pointer of the code: it is no element of the heap *)
  let c4 =
    STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
    REWRITE_TAC[get_refs_def; ALL; ADDR_APPLY_def] THEN
    MATCH_ACCEPT_TAC (el 3 rl) in
  (* a Block: the empty one is a word, and one with elements is an
     element of the heap whose roots are the elements.  The
     collection moves them all (ADDR_MAP of the list), and each of
     them is a root of the element, so the clause of gc_related
     keeps its pointer and the two hypotheses of the induction
     give the invariant of it and its references *)
  let c3 =
    COND_CASES_TAC THEN STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
    REWRITE_TAC[get_refs_def] THENL
     [REWRITE_TAC[MAP; FLAT; ALL; ADDR_APPLY_def] THEN
      MATCH_MP_TAC (el 7 rl) THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[ADDR_APPLY_def] THEN ptr_in THEN
      CONJ_TAC THENL
       [W(fun (asl,gl) ->
          let hl = grab_asm (fun th ->
            hd_is "heap_lookup" (lhs (concl th)) &&
            hd_is "BlockRep" (rand (rhs (concl th)))) asl in
          let xs = rand (rand (rhs (concl hl))) in
          ONCE_REWRITE_TAC[ISPECL [xs; `FAPPLY (g:(num,num)fmap)`]
                             ADDR_MAP_LENGTH]) THEN
        MATCH_MP_TAC (el 8 rl) THEN REPEAT CONJ_TAC THENL
         [FIRST_ASSUM MATCH_ACCEPT_TAC;
          DISCH_TAC THEN REWRITE_TAC[LIST_REL_EL_EQN] THEN
          W(fun (asl,gl) ->
            let a2e = grab_asm (fun th ->
              hd_is "ALL2" (concl th)) asl in
            let eqn = REWRITE_RULE[LIST_REL_EL_EQN] a2e in
            CONJ_TAC THENL
             [REWRITE_TAC[GSYM ADDR_MAP_LENGTH] THEN
              ACCEPT_TAC (CONJUNCT1 eqn);
              X_GEN_TAC `j:num` THEN DISCH_TAC THEN elem_tac 1]);
          W(fun (asl,gl) ->
            let fl = grab_asm (fun th ->
              hd_is "FLOOKUP" (lhs (concl th))) asl in
            let fd = MATCH_MP flk fl in
            REWRITE_TAC[FLOOKUP_f_o_f; CONJUNCT1 fd;
                        CONJUNCT2 fd] THEN ASM_REWRITE_TAC[]);
          W(fun (asl,gl) ->
            let gr = grab_asm (fun th ->
              hd_is "gc_related" (concl th)) asl in
            let fd = grab_asm (fun th ->
              hd_is "IN" (concl th)) asl in
            let hl = grab_asm (fun th ->
              hd_is "heap_lookup" (lhs (concl th)) &&
              hd_is "BlockRep" (rand (rhs (concl th)))) asl in
            let xs = rand (rand (rhs (concl hl))) in
            let cl = gc_clause gr fd
                       (REWRITE_RULE[BlockRep_def] hl) in
            REWRITE_TAC[BlockRep_def] THEN
            REWRITE_TAC[GSYM (ISPECL [xs;
              `FAPPLY (g:(num,num)fmap)`] ADDR_MAP_LENGTH)] THEN
            ACCEPT_TAC (CONJUNCT1 cl))];
        REWRITE_TAC[all_flat; GSYM ALL_MEM; MEM_MAP] THEN
        X_GEN_TAC `rs:(num)list` THEN
        DISCH_THEN (X_CHOOSE_THEN `e:dataSem_v`
          (CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC)) THEN
        W(fun (asl,gl) ->
          let mm = grab_asm (fun th ->
            hd_is "MEM" (concl th)) asl in
          MP_TAC (REWRITE_RULE[MEM_EXISTS_EL] mm)) THEN
        DISCH_THEN (X_CHOOSE_THEN `j:num`
          (CONJUNCTS_THEN2 ASSUME_TAC (fun eq ->
             REWRITE_TAC[eq]))) THEN
        elem_tac 2]] in
  (* the three thunk clauses are about RefPtr false, and the flag
     is false by the assumption of the clause of v_inv *)
  let notb =
    FIRST_ASSUM (fun th ->
      if is_neg (concl th) && is_var (rand (concl th))
      then SUBST_ALL_TAC (EQF_INTRO th) else NO_TAC) in
  (* a reference that is no thunk: the pointer of it moves with
     the map of the references *)
  let d5 =
    REPEAT SUBST_LHS_TAC THEN
    REWRITE_TAC[get_refs_def; ALL; ADDR_APPLY_def] THEN
    ptr_in THEN CONJ_TAC THENL
     [fof_rw THEN MATCH_MP_TAC (el 4 rl) THEN
      REPEAT CONJ_TAC THEN TRY in_fof THEN
      TRY (FIRST_ASSUM MATCH_ACCEPT_TAC);
      DISCH_TAC THEN FIRST_ASSUM MATCH_ACCEPT_TAC] in
  (* a thunk that the heap holds: its element has the value of the
     thunk as its single root, which the collection keeps, and the
     hypothesis of the counter carries the invariant of the value
     over *)
  let d6 =
    notb THEN REPEAT SUBST_LHS_TAC THEN
    REWRITE_TAC[get_refs_def; ALL; ADDR_APPLY_def] THEN
    ptr_in THEN CONJ_TAC THENL
     [fof_rw THEN MATCH_MP_TAC (el 5 rl) THEN
      W(fun (asl,gl) ->
        let lk = grab_asm (fun th ->
          hd_is "sptree_lookup" (lhs (concl th)) &&
          hd_is "bvlSem_Thunk" (rand (rhs (concl th)))) asl in
        let thk = rand (rhs (concl lk)) in
        let hl = grab_asm (fun th ->
          hd_is "heap_lookup" (lhs (concl th)) &&
          hd_is "ThunkBlock" (rand (rhs (concl th)))) asl in
        let y = rand (rand (rhs (concl hl))) in
        MAP_EVERY EXISTS_TAC
          [lhand thk; rand thk;
           list_mk_icomb "ADDR_APPLY"
             [`FAPPLY (g:(num,num)fmap)`; y]]) THEN
      REPEAT CONJ_TAC THEN
      TRY (FIRST_ASSUM MATCH_ACCEPT_TAC) THEN TRY in_fof THEN
      TRY (W(fun (asl,gl) ->
        (* the thunk's element, which the gc carries over *)
        let gr = grab_asm (fun th ->
          hd_is "gc_related" (concl th)) asl in
        let fd = grab_asm (fun th ->
          hd_is "IN" (concl th) &&
          hd_is "fmap_apply" (lhand (concl th))) asl in
        let hl = grab_asm (fun th ->
          hd_is "heap_lookup" (lhs (concl th)) &&
          hd_is "ThunkBlock" (rand (rhs (concl th)))) asl in
        let kp = MATCH_MP (MATCH_MP gc_keep1 gr)
                   (CONJ fd (REWRITE_RULE[ThunkBlock_def] hl)) in
        fof_fwd THEN REWRITE_TAC[ThunkBlock_def] THEN
        ACCEPT_TAC (CONJUNCT1 kp)) THEN NO_TAC) THEN
      (* and the value of the thunk, by the hypothesis of the
         counter *)
      DISCH_TAC THEN
      W(fun (asl,gl) ->
        let gr = grab_asm (fun th ->
          hd_is "gc_related" (concl th)) asl in
        let fd = grab_asm (fun th ->
          hd_is "IN" (concl th) &&
          hd_is "fmap_apply" (lhand (concl th))) asl in
        let hl = grab_asm (fun th ->
          hd_is "heap_lookup" (lhs (concl th)) &&
          hd_is "ThunkBlock" (rand (rhs (concl th)))) asl in
        let kp = MATCH_MP (MATCH_MP gc_keep1 gr)
                   (CONJ fd (REWRITE_RULE[ThunkBlock_def] hl)) in
        let vi = grab_asm (fun th ->
          hd_is "v_inv" (concl th)) asl in
        let nz = grab_asm (fun th ->
          is_neg (concl th) && is_eq (rand (concl th)) &&
          rhs (rand (concl th)) = `0`) asl in
        let ck = lhs (rand (concl nz)) in
        let ltck = MP (SPEC ck (ARITH_RULE
                     `!n. ~(n = 0) ==> n - 1 < n`)) nz in
        let ih = grab_asm (fun th ->
          is_forall (concl th) &&
          hd_is "<" (lhand (body (rand (concl th))))) asl in
        let ih' = MP (SPEC (mk_binop `(-):num->num->num` ck `1`)
                     ih) ltck in
        MATCH_ACCEPT_TAC (CONJUNCT1
          (MATCH_MP ih' (CONJ vi (CONJ gr (CONJUNCT2 kp))))));
      DISCH_TAC THEN FIRST_ASSUM MATCH_ACCEPT_TAC] in
  (* and a thunk that was evaluated: the value of it stands where
     the thunk stood, and the reference is an evaluated one, so
     the map of it needs nothing *)
  let d7 =
    notb THEN REWRITE_TAC[get_refs_def; ALL] THEN CONJ_TAC THENL
     [MATCH_MP_TAC (el 6 rl) THEN
      W(fun (asl,gl) ->
        let lk = grab_asm (fun th ->
          hd_is "sptree_lookup" (lhs (concl th)) &&
          hd_is "bvlSem_Thunk" (rand (rhs (concl th)))) asl in
        EXISTS_TAC (rand (rand (rhs (concl lk))))) THEN
      REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
      DISCH_TAC THEN
      W(fun (asl,gl) ->
        let gr = grab_asm (fun th ->
          hd_is "gc_related" (concl th)) asl in
        let vi = grab_asm (fun th ->
          hd_is "v_inv" (concl th)) asl in
        let pc = grab_asm (fun th ->
          is_forall (concl th) &&
          hd_is "gc_shared_Pointer"
            (rhs (lhand (body (rand (body (rand (concl th))))))))
          asl in
        let nz = grab_asm (fun th ->
          is_neg (concl th) && is_eq (rand (concl th)) &&
          rhs (rand (concl th)) = `0`) asl in
        let ck = lhs (rand (concl nz)) in
        let ltck = MP (SPEC ck (ARITH_RULE
                     `!n. ~(n = 0) ==> n - 1 < n`)) nz in
        let ih = grab_asm (fun th ->
          is_forall (concl th) &&
          hd_is "<" (lhand (body (rand (concl th))))) asl in
        let ih' = MP (SPEC (mk_binop `(-):num->num->num` ck `1`)
                     ih) ltck in
        MATCH_ACCEPT_TAC (CONJUNCT1
          (MATCH_MP ih' (CONJ vi (CONJ gr pc)))));
      DISCH_TAC THEN
      FIRST_ASSUM (fun nn ->
        if not (is_neg (concl nn)) then fail() else
        MP_TAC (REWRITE_RULE[IN; evaluated_thunk_ptr_def] nn)) THEN
      ASM_MESON_TAC[]] in
  let c5 =
    DISCH_THEN (DISJ_CASES_THEN2 STRIP_ASSUME_TAC
      (DISJ_CASES_THEN2 STRIP_ASSUME_TAC STRIP_ASSUME_TAC)) THENL
     [d5; d6; d7] in
  (* the induction is the one of the source: on the counter, and
     on the value inside it, so that a Block has the invariant of
     its elements for the counter below and their references for
     the counter itself *)
  let setup =
    MATCH_MP_TAC num_WF THEN X_GEN_TAC `ck:num` THEN
    DISCH_THEN (LABEL_TAC "ckih") THEN
    W(fun (asl,gl) ->
      let v,bod = dest_forall gl in
      MATCH_MP_TAC (CONV_RULE (TOP_DEPTH_CONV BETA_CONV)
                      (ISPEC (mk_abs (v,bod)) v_ind))) THEN
    REPEAT CONJ_TAC in
  let pre = REPEAT GEN_TAC THEN STRIP_TAC THEN
            USE_CHANGED [v_inv_def] in
  let preb = REPEAT GEN_TAC THEN DISCH_THEN (LABEL_TAC "vih") THEN
             REPEAT GEN_TAC THEN STRIP_TAC THEN
             USE_CHANGED [v_inv_def] in
  setup THENL
   [pre THEN c1; pre THEN c2; preb THEN c3; pre THEN c4;
    pre THEN c5])));;

(* [local] *)
let v_inv_related = prove
 (`!w x f tf.
     gc_related g heap1 (heap2:(('a
       word_loc,data_to_word_memoryProof_tag#('a word_loc)
       list)heap_element) list) /\
     (!ptr u. (x = gc_shared_Pointer ptr u) ==> ptr IN FDOM g) /\
     v_inv conf w refs (x,f,tf,heap1) ==>
     v_inv conf w refs (ADDR_APPLY (FAPPLY g) x,g f_o_f f,g f_o_f
       tf,heap2) /\
     EVERY (\n. ~(n IN evaluated_thunk_ptr refs) ==> FAPPLY f n IN
       FDOM g)
           (get_refs w)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_related_lemma]));;

(* [local] *)
let EVERY2_ADDR_MAP = prove
 (`!zs l. EVERY2 P (ADDR_MAP g zs) l <=>
            EVERY2 (\x y. P (ADDR_APPLY g x) y) zs l`,
  (let aux = prove
    (`!P g zs l.
        ALL2 P (ADDR_MAP g zs) l <=>
        ALL2 (\x y. P (ADDR_APPLY g x) y) zs l`,
     GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
     REWRITE_TAC[ADDR_MAP_def; ALL2_DEF] THEN
     CASES_BY_NAME "h" THEN
     REWRITE_TAC[ADDR_MAP_def; ADDR_APPLY_def;
                 ALL2_DEF] THEN
     ASM_REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

(* the port's own: the arms of bc_ref_inv, one lemma each, and the
   steps that every lemma about a collection of the heap takes.
   They stand here because the proofs of this file share them (the
   first of them is bc_ref_inv_related): the two lookups of the
   invariant decide which arm it is, and the maps and the heap of
   the arm lemma stay free, so one lemma reads the old invariant
   and the new one alike (PORTING-GUIDE.md entry 43) *)

let arm_VA = prove
 (cake_as_vars (fun () ->
    `FLOOKUP f n = SOME x /\
     sptree_lookup n refs = SOME (bvlSem_ValueArray ys)
     ==> (bc_ref_inv conf n refs (f,tf,heap,be') <=>
          (?zs. heap_lookup x heap = SOME (RefBlock zs) /\
                EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap))
                  zs ys))`),
  STRIP_TAC THEN ASM_REWRITE_TAC[bc_ref_inv_def] THEN
  MATCH_REDUCE_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[]);;

let arm_BA = prove
 (cake_as_vars (fun () ->
    `FLOOKUP f n = SOME x /\
     sptree_lookup n refs = SOME (bvlSem_ByteArray flag bs)
     ==> (bc_ref_inv conf n refs (f,tf,heap,be') <=>
          (let ws = LENGTH bs DIV (dimindex (:'a) DIV 8) + 1 in
            (heap_lookup x heap = SOME (Bytes be' flag bs (REPLICATE
              ws ((n2w 0):'a word))))))`),
  STRIP_TAC THEN ASM_REWRITE_TAC[bc_ref_inv_def] THEN
  MATCH_REDUCE_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[]);;

let arm_TH = prove
 (cake_as_vars (fun () ->
    `FLOOKUP f n = SOME x /\
     sptree_lookup n refs = SOME (bvlSem_Thunk ev v)
     ==> (bc_ref_inv conf n refs (f,tf,heap,be') <=>
          (?(z:('a word_loc) heap_address).
             heap_lookup x heap = SOME (ThunkBlock ev z) /\
             (ev = Evaluated ==> dest_thunk v refs = NotThunk) /\
             v_inv conf v refs (z,f,tf,heap)))`),
  STRIP_TAC THEN ASM_REWRITE_TAC[bc_ref_inv_def] THEN
  MATCH_REDUCE_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[]);;

let arm_MB = prove
 (cake_as_vars (fun () ->
    `FLOOKUP f n = SOME x /\
     sptree_lookup n refs = SOME (bvlSem_MutBlock tg fin l c r)
     ==> (bc_ref_inv conf n refs (f,tf,heap,be') <=>
          ((!gs. ~(data_to_word_config_gc_kind conf =
                   data_to_word_Generational gs)) /\
           (~fin ==> ~(x IN IMAGE (FAPPLY tf) (FDOM tf))) /\
           (?zs. heap_lookup x heap = SOME (BlockRep tg zs) /\
                 EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap)) zs
                   (l ++ [c] ++ r))))`),
  STRIP_TAC THEN ASM_REWRITE_TAC[bc_ref_inv_def] THEN
  MATCH_REDUCE_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[]);;

(* the arm of the old invariant and the arm of the new one, from
   the two lookups that each of them goes by *)

let USE_ARM =
  W(fun (asl,w as gl) ->
    let lk2 = the_asm (fun c -> is_eq c &&
                hd_is "sptree_lookup" (lhand c) &&
                hd_is "SOME" (rand c)) gl in
    let lk1s = filter (fun (_,th) ->
                 let c = concl th in
                 is_eq c && hd_is "FLOOKUP" (lhand c) &&
                 hd_is "SOME" (rand c)) asl in
    let arms = [arm_VA; arm_BA; arm_TH; arm_MB] in
    let ths =
      itlist (fun (_,lk1) a ->
        itlist (fun arm b ->
          (try [MATCH_MP arm (CONJ lk1 lk2)] with Failure _ -> [])
          @ b) arms a) lk1s [] in
    RULE_ASSUM_TRY (REWRITE_RULE ths) THEN REWRITE_TAC ths);;

(* the collection takes the address of an element to its own and
   what lies there to the element with its pointers mapped *)

let heap_move = prove
 (`gc_related g heap1 heap2 /\ a IN FDOM g /\
   heap_lookup a heap1 = SOME (DataElement xs l d)
   ==> heap_lookup (FAPPLY g a) heap2 =
       SOME (DataElement (ADDR_MAP (FAPPLY g) xs) l d) /\
       (!ptr u. MEM (gc_shared_Pointer ptr u) xs ==> ptr IN FDOM g)`,
  REWRITE_TAC[gc_related_def] THEN MESON_TAC[]);;

let addr1 = prove
 (`!f (z:(A)heap_address). ADDR_MAP f [z] = [ADDR_APPLY f z]`,
  REPEAT GEN_TAC THEN
  STRUCT_CASES_TAC(ISPEC `z:(A)heap_address`
                     (cases_of `:(A)heap_address`)) THEN
  REWRITE_TAC[ADDR_MAP_def; ADDR_APPLY_def]);;

(* and it is injective on its domain *)

let G_INJ = prove
 (`gc_related g heap1 heap2
   ==> (!a b. a IN FDOM g /\ b IN FDOM g /\
              (FAPPLY g a:num) = FAPPLY g b ==> a = b)`,
  REWRITE_TAC[gc_related_def] THEN STRIP_TAC THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM (fun inj ->
    if not (hd_is "INJ" (concl inj)) then fail() else
    MATCH_MP_TAC (CONJUNCT2 (REWRITE_RULE[INJ] inj))) THEN
  ASM_REWRITE_TAC[]);;

let v_inv_moved = GEN_ALL (DISCH_ALL (CONJUNCT1
  (UNDISCH (SPEC_ALL (GEN_ALL v_inv_related)))));;

(* the element at the collected address, from the arm's own
   equation *)

let MOVE =
  W(fun (asl,w as gl) ->
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    let hl' = CONV_RULE(TOP_DEPTH_CONV let_CONV)
                (REWRITE_RULE[RefBlock_def; BlockRep_def;
                              ThunkBlock_def; bytes_def] hl) in
    let gc = the_asm (hd_is "gc_related") gl in
    let ins = filter (fun (_,th) -> hd_is "IN" (concl th)) asl in
    STRIP_ASSUME_TAC (tryfind (fun (_,i) ->
      MATCH_MP heap_move (CONJ gc (CONJ i hl'))) ins));;

(* and what the arm says of a value of the old heap says of the
   mapped value in the new one *)

let USE_V_REL =
  MATCH_MP_TAC v_inv_moved THEN
  W(fun gl ->
    let gc = the_asm (hd_is "gc_related") gl in
    EXISTS_TAC (el 1 (snd (strip_comb (concl gc))))) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM (fun mp ->
    let b = snd (strip_forall (concl mp)) in
    if not (is_imp b) || not (hd_is "MEM" (lhand b)) then fail()
    else MATCH_MP_TAC mp) THEN
  POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (filter
    (fun th -> let c = concl th in
       hd_is "MEM" c || (is_eq c && is_var (lhand c))) l)) THEN
  ASM_MESON_TAC[MEM];;

(* the port's own: what reaches a reference.  reachable_refs is a
   path of ref_edge from a reference of a value of the stack, so a
   value of the stack reaches no more than the stack does, and a
   value inside a reference that the stack reaches reaches no more
   either.  The proofs about a collection and about an update of the
   references share these *)

let reach_mem = prove
 (cake_as_vars (fun () ->
    `MEM v stack' /\ reachable_refs [v] refs n
     ==> reachable_refs stack' refs n`),
  REWRITE_TAC[reachable_refs_def; MEM] THEN
  STRIP_TAC THEN ASM_MESON_TAC[]);;

let reach_val = prove
 (cake_as_vars (fun () ->
    `reachable_refs stack' refs m /\
     (!r2. MEM r2 (get_refs v) ==> ref_edge refs m r2) /\
     reachable_refs [v] refs n
     ==> reachable_refs stack' refs n`),
  REWRITE_TAC[reachable_refs_def; MEM] THEN
  REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[RTC_RTC; RTC_RULES]);;

let refs_in_block = prove
 (cake_as_vars (fun () ->
    `MEM v ys /\ MEM r (get_refs v)
     ==> MEM r (get_refs (Block ts tag ys))`),
  REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
  ASM_MESON_TAC[]);;

(* ---- the helpers that the blocks below use ----------------------- *)

let domain_insert = prove
 (`!k (v:A) t. domain (sptree_insert k v t) = k INSERT domain t`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EXTENSION; domain_lookup; IN_INSERT; lookup_insert] THEN
  GEN_TAC THEN COND_CASES_TAC THEN
  ASM_REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  MESON_TAC[]);;

(* the pickers that the generic lemmas and their proofs go by *)
let a_vtr gl = the_asm (fun c ->
                 let vs,bd = strip_forall c in
                 length vs = 2 && is_imp bd &&
                 hd_is "v_inv" (rand bd)) gl;;

let a_dtr gl = the_asm (fun c ->
                 let vs,bd = strip_forall c in
                 length vs = 1 && is_imp bd &&
                 (try hd_is "dataSem_dest_thunk" (lhand (lhand bd))
                  with Failure _ -> false)) gl;;

let a_ltr gl = the_asm (fun c ->
                 let vs,bd = strip_forall c in
                 length vs = 1 && is_imp bd && is_eq (rand bd) &&
                 hd_is "sptree_lookup" (lhand (rand bd))) gl;;

(* the arm of the old invariant and the arm of the new one, from the
   two lookups that each of them goes by *)
let USE_ARMS =
  W(fun (asl,_) ->
    let pick p = filter (fun (_,th) -> p (concl th)) asl in
    let lk2s = pick (fun c -> is_eq c && hd_is "sptree_lookup" (lhand c)
                              && hd_is "SOME" (rand c)) in
    let lk1s = pick (fun c -> is_eq c && hd_is "FLOOKUP" (lhand c) &&
                              hd_is "SOME" (rand c)) in
    let arms = [arm_VA; arm_BA; arm_TH; arm_MB] in
    let ths =
      itlist (fun (_,lk1) a ->
        itlist (fun (_,lk2) b ->
          itlist (fun arm c ->
            (try [MATCH_MP arm (CONJ lk1 lk2)] with Failure _ -> [])
            @ c) arms b) lk2s a) lk1s [] in
    RULE_ASSUM_TRY (REWRITE_RULE ths) THEN REWRITE_TAC ths);;

(* the reduction of a match whose scrutinee the patterns cannot
   decide by themselves: the guards have the pattern on the left,
   so the distinctness of the constructors is needed in both
   directions (PORTING-GUIDE.md entry 45) *)
let REDUCE_MATCH_HARD =
  MATCH_REDUCE_TAC THEN
  (let ds = [distinctness "option"; distinctness "bvlSem_ref"] in
   REWRITE_TAC (injectivity "option" :: injectivity "bvlSem_ref" ::
                PAIR_EQ :: ds @ map GSYM ds)) THEN
  CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN
  REWRITE_TAC[SELECT_REFL; EXISTS_UNIQUE_REFL] THEN
  TRY MATCH_REDUCE_TAC THEN REWRITE_TAC[];;

(* the clauses of heap_length, which the lemmas of this block and
   of the ones after it rewrite with *)
let heap_length_clauses = prove
 (`heap_length [] = 0 /\
   (!x xs. heap_length (CONS x xs) =
           el_length x + heap_length xs)`,
  REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]);;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_ref_inv_related = prove
 (cake_as_vars (fun () ->
    `gc_related g heap1 heap2 /\
       bc_ref_inv conf n refs (f,tf,heap1,be) /\ (FAPPLY f n) IN
         FDOM g ==>
       bc_ref_inv conf n refs (g f_o_f f,g f_o_f tf,heap2,be)`),
  (* the arms of the invariant, the step over the collection and
     v_inv_related for the values of a block are above the
     statement (tools/overrides.py): the lemmas about a
     collection of the heap share them.  What is left is which
     arm it is, and that the two maps of the new invariant are
     the old ones after the map of the collection *)
  (STRIP_TAC THEN
  (* the key has an address and the references a value, or the
     invariant does not hold of them *)
  NAMED_CASES_TAC (cake_as_vars (fun () ->
    `FLOOKUP (f:(num,num)fmap) n`)) [[]; ["x"]] THEN
  NAMED_CASES_TAC (cake_as_vars (fun () ->
    `sptree_lookup n (refs:((dataSem_v)bvlSem_ref)spt)`))
    [[]; ["rv"]] THEN
  TRY (SOLVED (FIRST_X_ASSUM (fun inv ->
    if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
    MP_TAC (REWRITE_RULE[bc_ref_inv_def] inv)) THEN
    ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
    CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[])) THEN
  (* the key is in the old map and its address in the one of the
     collection *)
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `(n:num) IN FDOM (f:(num,num)fmap) /\ FAPPLY f n = x`))
    STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM (fun lk ->
      if not (hd_is "FLOOKUP" (lhand (concl lk))) then fail() else
      MP_TAC (REWRITE_RULE[FLOOKUP_DEF] lk)) THEN
    COND_CASES_TAC THEN
    ASM_REWRITE_TAC[distinctness "option"; injectivity "option"];
    ALL_TAC] THEN
  (* so the new map takes the key to the collected address *)
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `FLOOKUP ((g:(num,num)fmap) f_o_f (f:(num,num)fmap)) (n:num) =
     SOME (FAPPLY g x)`))
    ASSUME_TAC THENL
   [ASM_REWRITE_TAC[FLOOKUP_f_o_f];
    ALL_TAC] THEN
  (* and the addresses that the arms speak of are the collected
     ones *)
  FIRST_ASSUM (fun eq ->
    let c = concl eq in
    if not (is_eq c) || not (hd_is "fmap_apply" (lhand c))
    then fail() else RULE_ASSUM_TRY (REWRITE_RULE[eq])) THEN
  (* the arm of the invariant is the one of the value that the
     references hold *)
  NAMED_CASES_TAC (cake_as_vars (fun () ->
    `rv:(dataSem_v)bvlSem_ref`))
    [["ys"]; ["flag"; "bs"]; ["ev"; "vv"];
     ["tg"; "fin"; "ll"; "cc"; "rr"]] THEN
  USE_ARM THEN
  (* the arm with a let: the count of the words of a byte array *)
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
  TRY (CONV_TAC(TOP_DEPTH_CONV let_CONV)) THEN
  SPLIT_ASM_TAC THEN
  TRY (FIRST_X_ASSUM (fun ex ->
    if not (is_exists (concl ex)) then fail() else
    STRIP_ASSUME_TAC ex)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the element of the new heap is the old one with its pointers
     mapped *)
  TRY (W(fun gl ->
    let lk = the_asm (fun c -> is_eq c &&
               hd_is "FLOOKUP" (lhand c) &&
               hd_is "f_o_f" (lhand (lhand c))) gl in
    let ap = rator (rand (rand (concl lk))) in
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    let blk = rand (rand (concl hl)) in
    let z = last (snd (strip_comb blk)) in
    if hd_is "ThunkBlock" blk
    then EXISTS_TAC (list_mk_icomb "ADDR_APPLY" [ap; z])
    else if hd_is "Bytes" blk then fail()
    else EXISTS_TAC (list_mk_icomb "ADDR_MAP" [ap; z]))) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* its address *)
  TRY (SOLVED
        (REWRITE_TAC[RefBlock_def; BlockRep_def; ThunkBlock_def;
                     bytes_def] THEN
         TRY (CONV_TAC(TOP_DEPTH_CONV let_CONV)) THEN
         MOVE THEN
         ASM_REWRITE_TAC[addr1; ADDR_MAP_def;
           data_to_word_memoryProof_LENGTH_ADDR_MAP])) THEN
  (* the values of the elements of a block *)
  TRY (SOLVED
        (MOVE THEN
         REWRITE_TAC[EVERY2_ADDR_MAP] THEN
         FIRST_X_ASSUM (fun e2 ->
           if not (hd_is "ALL2" (concl e2)) then fail() else
           MP_TAC e2) THEN
         MATCH_MP_TAC EVERY2_IMP_EVERY2 THEN
         CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
         REPEAT STRIP_TAC THEN
         USE_V_REL)) THEN
  (* and the value of a thunk *)
  TRY (SOLVED (MOVE THEN USE_V_REL)) THEN
  (* the cell of a block that is not finalised is no timestamp's
     cell, and the map of the collection is injective on its
     domain, so the collected cell is none either *)
  DISCH_TAC THEN
  FIRST_X_ASSUM (fun imp ->
    let c = concl imp in
    if not (is_imp c) then fail() else
    MP_TAC (MATCH_MP imp (ASSUME (lhand c)))) THEN
  REWRITE_TAC[IN_IMAGE; CONJUNCT1 f_o_f_DEF; IN_ELIM_THM] THEN
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM (fun no ->
    let c = concl no in
    if not (is_neg c) || not (is_exists (rand c)) then fail() else
    MP_TAC no) THEN
  REWRITE_TAC[] THEN
  W(fun gl ->
    let eq = the_asm (fun c -> is_eq c &&
               hd_is "fmap_apply" (lhand c) &&
               hd_is "fmap_apply" (rand c) &&
               hd_is "f_o_f" (lhand (rand c))) gl in
    EXISTS_TAC (rand (rand (concl eq)))) THEN
  CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST_ASSUM (fun gc ->
    if not (hd_is "gc_related" (concl gc)) then fail() else
    MATCH_MP_TAC (MATCH_MP G_INJ gc)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  ASM_SIMP_TAC[FAPPLY_f_o_f]));;

let gc_inline_rel = cake_inductive
  `(gc_inline_rel inline h1 x x) /\
   (heap_lookup p h1 = SOME block /\
     inline block x ==>
       gc_inline_rel inline h1 (gc_shared_Pointer p u) x)`;;

let gc_heap_inline_rel = cake_inductive
  `(gc_heap_inline_rel inline h1 x x) /\
   (LIST_REL (gc_inline_rel inline h1) xs ys ==>
       gc_heap_inline_rel inline h1 (DataElement xs n d)
         (DataElement ys n d))`;;

let gc_inline_def = cake_define
  `gc_inline inline (r1,h1) (r2,h2) <=>
     LIST_REL (gc_inline_rel inline h1) r1 r2 /\
     LIST_REL (gc_heap_inline_rel inline h1) h1 h2`;;

let gc_related_roots_heap_def = cake_define
  `gc_related_roots_heap f (r1,h1) (r2,h2) <=>
     gc_related f h1 h2 /\
     r2 = ADDR_MAP ((FAPPLY) f) r1 /\
     (!ptr u. MEM (gc_shared_Pointer ptr u) r1 ==> ptr IN FDOM f)`;;

let gc_inline_related_def = cake_define
  `gc_inline_related inline f (r1,h1) (r2,h2) =
     (?ri hi. gc_inline inline (r1,h1) (ri,hi) /\
             gc_related_roots_heap f (ri,hi) (r2,h2))`;;

(* [local] *)
let gc_heap_inline_rel_heap_lookup = prove
 (`!heap1 heap2.
     LIST_REL (gc_heap_inline_rel dest_evaluated_thunk_rel heap)
       heap1 heap2 ==>
       (!a. isSomeDataElement (heap_lookup a heap1) <=>
           isSomeDataElement (heap_lookup a heap2))`,
  (* two heaps of which the elements are related have the same
     lengths of elements and the same elements that are data, which
     is what the cases of the relation say, so a lookup in the one is
     data exactly when the lookup in the other is *)
  (let (_,_,cases) = gc_heap_inline_rel in
   let isd = prove
    (`!xs n d. isSomeDataElement (SOME (DataElement xs n d))`,
     REWRITE_TAC[isSomeDataElement_def] THEN MESON_TAC[]) in
   let lem = prove
    (`!x y. gc_heap_inline_rel dest_evaluated_thunk_rel heap x y
        ==> el_length x = el_length y /\
            (isSomeDataElement (SOME x) <=>
             isSomeDataElement (SOME y))`,
     REPEAT GEN_TAC THEN GEN_REWRITE_TAC LAND_CONV [cases] THEN
     STRIP_TAC THEN
     ASM_REWRITE_TAC[el_length_def; isd]) in
   let lcases =
     W(fun (_,w) ->
       STRUCT_CASES_TAC(ISPEC (rand(lhand w)) list_CASES_v)) in
   LIST_INDUCT_TAC THEN GEN_TAC THEN lcases THEN
   REWRITE_TAC[ALL2; heap_lookup_def] THEN
   STRIP_TAC THEN
   FIRST_ASSUM(fun r -> MP_TAC(MATCH_MP lem r)) THEN
   DISCH_THEN(CONJUNCTS_THEN2 (fun e -> REWRITE_TAC[e])
     ASSUME_TAC) THEN
   GEN_TAC THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   FIRST_ASSUM(fun ih -> FIRST_ASSUM(fun r ->
     MATCH_ACCEPT_TAC(MATCH_MP ih r)))));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let ThunkBlock_not_EQ = prove
 (cake_as_vars (fun () ->
    `~(ThunkBlock ev x = Bignum i) /\ ~(ThunkBlock ev x = Word64Rep
  (:'a) w) /\ ~(ThunkBlock ev x = BlockRep n xs) /\ ~(ThunkBlock ev x
  = RefBlock zs) /\ ~(ThunkBlock ev x = Bytes be flag bs ys)`),
  (REWRITE_TAC[ThunkBlock_def; bignum_def;
               Word64Rep_def; BlockRep_def;
               RefBlock_def; bytes_def] THEN
   PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   COND_CASES_TAC THEN
   REWRITE_TAC[injectivity "heap_element"; PAIR_EQ;
               distinctness "data_to_word_memoryProof_tag";
               NOT_CONS_NIL]));;

(* [local] *)
let LIST_REL_gc_heap_inline_DataElement = prove
 (`!heap1 heap2.
     LIST_REL (gc_heap_inline_rel dest_evaluated_thunk_rel base)
       heap1 heap2 ==>
       (!ptr.
         heap_lookup ptr heap1 = SOME (DataElement xs n d) ==>
         (?ys.
           heap_lookup ptr heap2 = SOME (DataElement ys n d) /\
           LIST_REL (gc_inline_rel dest_evaluated_thunk_rel base)
             xs ys))`,
  (* the lookup of the one heap is data, so the element of the other
     at that address is the one the relation relates it to: either
     the same element, or the data of the same length and the same
     tag whose addresses the relation relates one by one *)
  (let (_,_,cases) = gc_heap_inline_rel in
   let (irules,_,_) = gc_inline_rel in
   let ellen = prove
    (`!inline h1 x y. gc_heap_inline_rel inline h1 x y
        ==> el_length x = el_length y`,
     REPEAT GEN_TAC THEN GEN_REWRITE_TAC LAND_CONV [cases] THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[el_length_def]) in
   let refl2 = prove
    (`!inline h1 l. ALL2 (gc_inline_rel inline h1) l l`,
     GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[ALL2; CONJUNCT1 irules]) in
   let lcases =
     W(fun (_,w) ->
       STRUCT_CASES_TAC(ISPEC (rand(lhand w)) list_CASES_v)) in
   (* the witness of the existential is what the first conjunct of
      its body equates the bound variable with *)
   let eq_exists =
     W(fun (_,w) ->
       let v,bod = dest_exists w in
       let eq = hd (conjuncts bod) in
       EXISTS_TAC (if rand eq = v then lhand eq else rand eq)) in
   LIST_INDUCT_TAC THEN GEN_TAC THEN lcases THEN
   REWRITE_TAC[ALL2; heap_lookup_def;
               distinctness "option"] THEN
   STRIP_TAC THEN GEN_TAC THEN
   FIRST_ASSUM(fun r -> REWRITE_TAC[MATCH_MP ellen r]) THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[] THENL
    [REWRITE_TAC[injectivity "option"] THEN
     DISCH_THEN SUBST_ALL_TAC THEN USE_CHANGED [cases] THEN
     REWRITE_TAC[injectivity "heap_element"] THEN STRIP_TAC THEN
     ASM_REWRITE_TAC[injectivity "heap_element"] THEN
     eq_exists THEN ASM_REWRITE_TAC[refl2];
     COND_CASES_TAC THEN
     REWRITE_TAC[distinctness "option"] THEN
     FIRST_ASSUM(fun ih -> FIRST_ASSUM(fun r ->
       MATCH_ACCEPT_TAC(MATCH_MP ih r)))]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let gc_heap_inline_rel_v_inv_lemma = prove
 (cake_as_vars (fun () ->
    `!ck v refs x1 x2 f tf heap1 heap2.
       v_inv conf v refs (x1,f,tf,heap1) ==>
         LIST_REL (gc_heap_inline_rel dest_evaluated_thunk_rel
           heap1) heap1 heap2 /\
         (!n.
           n IN FDOM f /\
           reachable_refs [v] refs n ==>
             bc_ref_inv conf n refs (f,tf,heap1,be)) /\
         gc_inline_rel dest_evaluated_thunk_rel heap1 x1 x2 ==>
           v_inv_ck ck conf v refs (x2,f,tf,heap2)`),
(* the induction of the source: on the counter, and then the cases
   of the value.  The inlining of a root either keeps it or takes
   the root of the element that the root points at, and that
   element is an evaluated thunk's (the cases of gc_inline_rel and
   of dest_evaluated_thunk_rel, in one lemma).  So every case has
   two branches, and the one of the inlining step is closed by
   ThunkBlock_not_EQ wherever the element at the pointer is a
   number, a word of sixty-four bits or a Block.
     Where the root is kept, the element of the value has to be
   found in the new heap: an element without roots stands where it
   stood and an element with one root keeps it inlined (two lemmas
   from LIST_REL_gc_heap_inline_DataElement), and the roots of a
   Block are related one by one.  The invariant of an element of a
   Block and of the value of a thunk then comes from the
   hypothesis of the counter, which asks for the invariant of the
   heap at that value: the references of an element of a Block are
   references of the Block, and the references of the value of a
   thunk are the references of the reference that holds it one
   edge further (RTC of ref_edge), which is what the three
   reachability lemmas say.
     A reference that holds no thunk is the one case where the
   inlining step is not about the value of the goal at all: there
   the invariant of the heap at that reference says which arm it
   is, and no arm of it is an element of a thunk *)
  ((let grab_asm p asl =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
  (* the cases of the two relations of the inlining and the rules
     of the invariant with a counter *)
  let (irules,_,ic) = gc_inline_rel in
  let (_,_,dc) = dest_evaluated_thunk_rel in
  let (vr,_,_) = v_inv_ck in
  let rl = CONJUNCTS vr in
  (* a root that the inlining relates to another is that root
     itself, or a pointer to the element of an evaluated thunk *)
  let inl_cases = prove
   (`!(h1:(('a word_loc,data_to_word_memoryProof_tag#('a word_loc)
      list)heap_element) list) x y.
      gc_inline_rel dest_evaluated_thunk_rel h1 x y
      ==> x = y \/
          ?p u. x = gc_shared_Pointer p u /\
                heap_lookup p h1 = SOME (ThunkBlock Evaluated y)`,
    REPEAT GEN_TAC THEN GEN_REWRITE_TAC LAND_CONV [ic] THEN
    REWRITE_TAC[dc] THEN MESON_TAC[]) in
  (* an element of the heap without roots the inlining of the heap
     keeps where it is *)
  let keep_de = prove
   (`LIST_REL (gc_heap_inline_rel dest_evaluated_thunk_rel heap1)
       heap1 (heap2:(('a word_loc,
         data_to_word_memoryProof_tag#('a word_loc)
         list)heap_element) list)
     ==> !ptr l d. heap_lookup ptr heap1 = SOME (DataElement [] l d)
           ==> heap_lookup ptr heap2 = SOME (DataElement [] l d)`,
    DISCH_THEN (fun lr ->
      REPEAT GEN_TAC THEN DISCH_THEN (fun hl ->
        MP_TAC (MATCH_MP (MATCH_MP
          LIST_REL_gc_heap_inline_DataElement lr) hl))) THEN
    REWRITE_TAC[ALL2_DEF] THEN
    DISCH_THEN (CHOOSE_THEN
      (CONJUNCTS_THEN2 MP_TAC SUBST1_TAC)) THEN
    REWRITE_TAC[]) in
  (* a list that a relation relates to a list of one element is a
     list of one element *)
  let all2_single = prove
   (`!R (y:A) (ys:(B)list).
       ALL2 R [y] ys <=> ?y'. ys = [y'] /\ R y y'`,
    REPEAT GEN_TAC THEN
    STRUCT_CASES_TAC (ISPEC `ys:(B)list` list_CASES) THEN
    REWRITE_TAC[ALL2_DEF; NOT_CONS_NIL; GSYM NOT_CONS_NIL;
                CONS_11; HD; TL] THEN
    MESON_TAC[]) in
  (* so an element with one root it keeps with the root inlined *)
  let keep_de1 = prove
   (`LIST_REL (gc_heap_inline_rel dest_evaluated_thunk_rel heap1)
       heap1 (heap2:(('a word_loc,
         data_to_word_memoryProof_tag#('a word_loc)
         list)heap_element) list)
     ==> !ptr y l d.
           heap_lookup ptr heap1 = SOME (DataElement [y] l d)
           ==> ?y'. heap_lookup ptr heap2 =
                      SOME (DataElement [y'] l d) /\
                    gc_inline_rel dest_evaluated_thunk_rel
                      heap1 y y'`,
    DISCH_THEN (fun lr ->
      REPEAT GEN_TAC THEN DISCH_THEN (fun hl ->
        MP_TAC (MATCH_MP (MATCH_MP
          LIST_REL_gc_heap_inline_DataElement lr) hl))) THEN
    REWRITE_TAC[all2_single] THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      let c = concl th in
      if is_eq c && is_var (lhs c) &&
         not (vfree_in (lhs c) (rhs c))
      then SUBST_ALL_TAC th else fail())) THEN
    W(fun (asl,gl) ->
      let r = grab_asm (fun th ->
        hd_is "gc_inline_rel" (concl th)) asl in
      EXISTS_TAC (rand (concl r))) THEN
    CONJ_TAC THEN FIRST_ASSUM MATCH_ACCEPT_TAC) in
  (* the element of a reference that holds no thunk is no element
     of a thunk, whichever arm of the invariant it is *)
  let not_thunk_elt = prove
   (cake_as_vars (fun () ->
     `n IN FDOM f /\
      (!ev vv. ~(sptree_lookup n refs = SOME (bvlSem_Thunk ev vv)))
      /\ bc_ref_inv conf n refs (f,tf,heap,be)
      ==> ~(heap_lookup (FAPPLY f n) heap =
            SOME (ThunkBlock ev' (y:('a word_loc)heap_address)))`),
    REPEAT STRIP_TAC THEN
    SUBGOAL_THEN (cake_as_vars (fun () ->
      `FLOOKUP (f:(num,num)fmap) n = SOME (FAPPLY f n)`))
      ASSUME_TAC THENL
     [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC] THEN
    NAMED_CASES_TAC (cake_as_vars (fun () ->
      `sptree_lookup n (refs:((dataSem_v)bvlSem_ref)spt)`))
      [[]; ["rv"]] THENL
     [FIRST_X_ASSUM (fun inv ->
        if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
        MP_TAC (REWRITE_RULE[bc_ref_inv_def] inv)) THEN
      ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
      CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    NAMED_CASES_TAC (cake_as_vars (fun () ->
      `rv:(dataSem_v)bvlSem_ref`))
      [["ys"]; ["flag"; "bs"]; ["ev"; "vv"];
       ["tg"; "fin"; "ll"; "cc"; "rr"]] THEN
    USE_ARM THEN
    RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
    ASM_MESON_TAC[ThunkBlock_not_EQ; injectivity "option"]) in
  (* a reference of an element of a Block is a reference of it *)
  let refs_block = prove
   (`!ts t vs e r. MEM (e:dataSem_v) vs /\ MEM r (get_refs e)
       ==> MEM r (get_refs (Block ts t vs))`,
    REPEAT GEN_TAC THEN
    REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
    STRIP_TAC THEN EXISTS_TAC `get_refs (e:dataSem_v)` THEN
    CONJ_TAC THENL
     [EXISTS_TAC `e:dataSem_v` THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM MATCH_ACCEPT_TAC]) in
  (* so the references that an element of a Block reaches the
     Block reaches as well *)
  let reach_block = prove
   (`!ts t vs e refs r. MEM (e:dataSem_v) vs /\
       reachable_refs [e] refs r
       ==> reachable_refs [Block ts t vs] refs r`,
    REWRITE_TAC[reachable_refs_def; MEM] THEN
    MESON_TAC[refs_block]) in
  (* the references of the value of a thunk the reference that
     holds it reaches, one edge further *)
  let reach_thunk = prove
   (cake_as_vars (fun () ->
     `!b n refs ev v r.
        sptree_lookup n refs = SOME (bvlSem_Thunk ev v) /\
        reachable_refs [v] refs r
        ==> reachable_refs [RefPtr b n] refs r`),
    REPEAT GEN_TAC THEN
    REWRITE_TAC[reachable_refs_def; get_refs_def; MEM] THEN
    STRIP_TAC THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      let c = concl th in
      if is_eq c && is_var (lhs c) &&
         not (vfree_in (lhs c) (rhs c))
      then SUBST_ALL_TAC th else fail())) THEN
    W(fun (asl,gl) ->
      let mm = grab_asm (fun th -> hd_is "MEM" (concl th)) asl in
      MAP_EVERY EXISTS_TAC
        [cake_as_vars (fun () -> `RefPtr b n:dataSem_v`);
         `n:num`] THEN
      REWRITE_TAC[get_refs_def; MEM] THEN
      MATCH_MP_TAC (CONJUNCT2 (SPEC_ALL RTC_RULES)) THEN
      EXISTS_TAC (lhand (concl mm))) THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[ref_edge_def] THEN MATCH_REDUCE_TAC THEN
      ASM_REWRITE_TAC[get_refs_def; FLAT; MAP; APPEND_NIL];
      FIRST_ASSUM MATCH_ACCEPT_TAC]) in
  (* and a reference reaches itself *)
  let reach_self = prove
   (cake_as_vars (fun () ->
     `!b n refs. reachable_refs [RefPtr b n] refs n`),
    REPEAT GEN_TAC THEN REWRITE_TAC[reachable_refs_def] THEN
    MAP_EVERY EXISTS_TAC
      [cake_as_vars (fun () -> `RefPtr b n:dataSem_v`);
       `n:num`] THEN
    REWRITE_TAC[get_refs_def; MEM] THEN
    MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL RTC_RULES))) in
  (* an equation of an assumption of which one side is a variable,
     substituted away *)
  let SUBST_VAR_ASM =
    FIRST_X_ASSUM (fun th ->
      let c = concl th in
      if not (is_eq c) then fail() else
      if is_var (lhs c) && not (vfree_in (lhs c) (rhs c))
      then SUBST_ALL_TAC th
      else if is_var (rhs c) && not (vfree_in (rhs c) (lhs c))
      then SUBST_ALL_TAC (SYM th) else fail()) in
  let dist2 = CONJ (distinctness "heap_address")
                   (GSYM (distinctness "heap_address")) in
  (* the inlining of the root of the value: it keeps it, or the
     root is a pointer and the element there is an evaluated
     thunk's *)
  let inl_step =
    W(fun (asl,gl) ->
      let gi = grab_asm (fun th ->
        hd_is "gc_inline_rel" (concl th)) asl in
      MP_TAC (REWRITE_RULE[injectivity "heap_address"; dist2]
                (MATCH_MP inl_cases gi))) THEN
    DISCH_THEN (REPEAT_TCL STRIP_THM_THEN STRIP_ASSUME_TAC) THEN
    REPEAT SUBST_VAR_ASM in
  (* and the element of a thunk is no element of a value of
     another kind *)
  let thunk_clash =
    W(fun (asl,gl) ->
      let t1 = grab_asm (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        hd_is "ThunkBlock" (rand (rhs (concl th)))) asl in
      let t2 = grab_asm (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        lhs (concl th) = lhs (concl t1) &&
        not (hd_is "ThunkBlock" (rand (rhs (concl th))))) asl in
      MP_TAC (REWRITE_RULE[injectivity "option"]
                (TRANS (SYM t1) t2)) THEN
      REWRITE_TAC[ThunkBlock_not_EQ]) in
  (* a number and a word of sixty-four bits take an element of the
     heap without roots, so the inlining keeps the element of one
     where it is.  The two lemmas say that of the element itself,
     because the equation that makes it one without roots cannot
     be used in the proof of the goal: it is an assumption of the
     step, and then the types of the goal are not the types of it
     (PORTING-GUIDE.md entry 86) *)
  let keep_bignum = prove
   (`LIST_REL (gc_heap_inline_rel dest_evaluated_thunk_rel heap1)
       heap1 (heap2:(('a word_loc,
         data_to_word_memoryProof_tag#('a word_loc)
         list)heap_element) list)
     ==> !ptr i. heap_lookup ptr heap1 = SOME (Bignum i)
           ==> heap_lookup ptr heap2 = SOME (Bignum i)`,
    DISCH_TAC THEN REPEAT GEN_TAC THEN
    MP_TAC (prove
     (`!i. ?l d. (Bignum i:(('a word_loc,
          data_to_word_memoryProof_tag#('a word_loc)
          list)heap_element)) = DataElement [] l d`,
      GEN_TAC THEN REWRITE_TAC[bignum_def] THEN
      PAIRARG_TAC THEN CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
      MESON_TAC[])) THEN
    DISCH_THEN (fun th ->
      REPEAT_TCL CHOOSE_THEN SUBST1_TAC (SPEC `i:int` th)) THEN
    FIRST_ASSUM (fun lr ->
      MATCH_ACCEPT_TAC (MATCH_MP keep_de lr))) in
  let keep_w64 = prove
   (`LIST_REL (gc_heap_inline_rel dest_evaluated_thunk_rel heap1)
       heap1 (heap2:(('a word_loc,
         data_to_word_memoryProof_tag#('a word_loc)
         list)heap_element) list)
     ==> !ptr w. heap_lookup ptr heap1 =
                   SOME (Word64Rep (:'a) w)
           ==> heap_lookup ptr heap2 = SOME (Word64Rep (:'a) w)`,
    DISCH_TAC THEN REPEAT GEN_TAC THEN
    MP_TAC (SPECL [`(:'a)`; `w:word64`] Word64Rep_DataElement) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN SUBST1_TAC) THEN
    FIRST_ASSUM (fun lr ->
      MATCH_ACCEPT_TAC (MATCH_MP keep_de lr))) in
  let keep_elt lem =
    W(fun (asl,gl) ->
      let lr = grab_asm (fun th -> hd_is "ALL2" (concl th)) asl in
      let hl = grab_asm (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        rhs (concl th) = rhs gl) asl in
      ACCEPT_TAC (MATCH_MP (MATCH_MP lem lr) hl)) in
  (* the references that the invariant of the heap speaks of, for
     one value that the value of the goal reaches *)
  let spec_bc elt trans =
    W(fun (asl,gl) ->
      let bc = grab_asm (fun th ->
        let _,bod = dest_forall (concl th) in
        hd_is "bc_ref_inv" (snd (dest_imp bod))) asl in
      let rr = find_term (hd_is "reachable_refs") (concl bc) in
      let roots = el 0 (snd (strip_comb rr)) in
      SUBGOAL_THEN (subst [mk_flist [elt], roots] (concl bc))
        (LABEL_TAC "bc2") THENL
       [GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC bc THEN
        CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; trans];
        ALL_TAC]) in
  let trans_block elt =
    MATCH_MP_TAC reach_block THEN EXISTS_TAC elt THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC MEM_EL THEN FIRST_ASSUM MATCH_ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC] in
  let trans_thunk =
    W(fun (asl,gl) ->
      let lk = grab_asm (fun th ->
        hd_is "sptree_lookup" (lhs (concl th)) &&
        hd_is "bvlSem_Thunk" (rand (rhs (concl th)))) asl in
      let thk = rand (rhs (concl lk)) in
      MATCH_MP_TAC reach_thunk THEN
      MAP_EVERY EXISTS_TAC [lhand thk; rand thk]) THEN
    CONJ_TAC THEN FIRST_ASSUM MATCH_ACCEPT_TAC in
  (* and the invariant of that value, by the hypothesis of the
     counter *)
  let use_ckih vi gi =
    W(fun (asl,gl) ->
      let lr = grab_asm (fun th ->
        hd_is "ALL2" (concl th) &&
        hd_is "gc_heap_inline_rel"
          (el 0 (snd (strip_comb (concl th))))) asl in
      let nz = grab_asm (fun th ->
        is_neg (concl th) && is_eq (rand (concl th)) &&
        rhs (rand (concl th)) = `0`) asl in
      let ck = lhs (rand (concl nz)) in
      let ltck = MP (SPEC ck (ARITH_RULE
                   `!n. ~(n = 0) ==> n - 1 < n`)) nz in
      USE_THEN "ckih" (fun ih ->
        USE_THEN "bc2" (fun bc2 ->
          let ih' = MP (SPEC (mk_binop `(-):num->num->num` ck `1`)
                       ih) ltck in
          MATCH_ACCEPT_TAC (MATCH_MP (MATCH_MP ih' vi)
            (CONJ lr (CONJ bc2 gi)))))) in
  (* the element of the Block in the new heap, with its roots *)
  let blk_move =
    W(fun (asl,gl) ->
      let lr = grab_asm (fun th ->
        hd_is "ALL2" (concl th) &&
        hd_is "gc_heap_inline_rel"
          (el 0 (snd (strip_comb (concl th))))) asl in
      let hl = grab_asm (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        hd_is "BlockRep" (rand (rhs (concl th)))) asl in
      MP_TAC (MATCH_MP (MATCH_MP
        LIST_REL_gc_heap_inline_DataElement lr)
        (REWRITE_RULE[BlockRep_def] hl))) THEN
    DISCH_THEN (CHOOSE_THEN
      (CONJUNCTS_THEN2 (LABEL_TAC "hl2") (LABEL_TAC "lr2"))) in
  (* an element of the Block: the invariant of it comes from the
     hypothesis of the counter, with the references of the Block
     for the ones of the element *)
  let elem_tac =
    W(fun (asl,gl) ->
      let elt = el 2 (snd (strip_comb gl)) in
      spec_bc elt (trans_block elt)) THEN
    W(fun (asl,gl) ->
      let lt = grab_asm (fun th ->
        hd_is "<" (concl th) &&
        hd_is "LENGTH" (rand (concl th))) asl in
      let j = lhand (concl lt) in
      let a2v = grab_asm (fun th ->
        hd_is "ALL2" (concl th) &&
        is_abs (el 0 (snd (strip_comb (concl th))))) asl in
      let eqv = REWRITE_RULE[LIST_REL_EL_EQN] a2v in
      let vi = BETA_RULE (MP (SPEC j (CONJUNCT2 eqv)) lt) in
      USE_THEN "lr2" (fun lr2 ->
        let eqx = REWRITE_RULE[LIST_REL_EL_EQN] lr2 in
        let ltx = MATCH_MP (ARITH_RULE
                    `!j la lx:num. j < la /\ la = lx ==> j < lx`)
                    (CONJ lt (CONJUNCT1 eqv)) in
        let gi = MP (SPEC j (CONJUNCT2 eqx)) ltx in
        use_ckih vi gi)) in
  (* the flag of a reference that holds a thunk is false *)
  let notb =
    FIRST_ASSUM (fun th ->
      if is_neg (concl th) && is_var (rand (concl th))
      then SUBST_ALL_TAC (EQF_INTRO th) else NO_TAC) in
  (* the invariant of the heap holds for the reference of the
     value itself *)
  let bc_self =
    W(fun (asl,gl) ->
      let bc = grab_asm (fun th ->
        let _,bod = dest_forall (concl th) in
        hd_is "bc_ref_inv" (snd (dest_imp bod))) asl in
      let rr = find_term (hd_is "reachable_refs") (concl bc) in
      let roots = el 0 (snd (strip_comb rr)) in
      let nterm = rand (hd (dest_list roots)) in
      let nv,bod = dest_forall (concl bc) in
      let _,con = dest_imp bod in
      SUBGOAL_THEN (subst [nterm, nv] con) ASSUME_TAC THENL
       [MATCH_MP_TAC bc THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC; MATCH_ACCEPT_TAC reach_self];
        ALL_TAC]) in
  (* so a reference that holds no thunk has no element of a thunk,
     and the inlining cannot take one for it *)
  let no_thunk_ref =
    bc_self THEN
    W(fun (asl,gl) ->
      let inv = grab_asm (fun th ->
        hd_is "bc_ref_inv" (concl th)) asl in
      let fd = grab_asm (fun th -> hd_is "IN" (concl th)) asl in
      let nt = grab_asm (fun th ->
        is_forall (concl th) &&
        can (find_term (hd_is "bvlSem_Thunk")) (concl th)) asl in
      let hl = grab_asm (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        hd_is "ThunkBlock" (rand (rhs (concl th)))) asl in
      let ntv = MATCH_MP not_thunk_elt (CONJ fd (CONJ nt inv)) in
      ACCEPT_TAC (CONTR gl (MATCH_MP (NOT_ELIM ntv) hl))) in
  (* a number: it is small, and then the root is a word that the
     inlining keeps, or it is an element of the heap without
     roots, which the inlining keeps where it is *)
  let c1 =
    COND_CASES_TAC THEN REPEAT STRIP_TAC THEN
    REPEAT SUBST_VAR_ASM THEN inl_step THEN
    TRY (SOLVED thunk_clash) THENL
     [MATCH_MP_TAC (el 0 rl) THEN FIRST_ASSUM MATCH_ACCEPT_TAC;
      MATCH_MP_TAC (el 1 rl) THEN CONJ_TAC THENL
       [FIRST_ASSUM MATCH_ACCEPT_TAC; keep_elt keep_bignum]] in
  (* a word of sixty-four bits: the same, without the small case *)
  let c2 =
    REPEAT STRIP_TAC THEN REPEAT SUBST_VAR_ASM THEN inl_step THEN
    TRY (SOLVED thunk_clash) THEN
    MATCH_MP_TAC (el 2 rl) THEN keep_elt keep_w64 in
  (* a Block: the empty one is a word, and one with elements is an
     element of the heap whose roots the inlining relates one by
     one to the roots of the element of the new heap *)
  let c3 =
    COND_CASES_TAC THEN REPEAT STRIP_TAC THEN
    REPEAT SUBST_VAR_ASM THEN inl_step THEN
    TRY (SOLVED thunk_clash) THENL
     [MATCH_MP_TAC (el 7 rl) THEN ASM_REWRITE_TAC[];
      blk_move THEN
      USE_THEN "lr2" (fun lr2 ->
        SUBST1_TAC (CONJUNCT1
          (REWRITE_RULE[LIST_REL_EL_EQN] lr2))) THEN
      MATCH_MP_TAC (el 8 rl) THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM MATCH_ACCEPT_TAC;
        DISCH_TAC THEN REWRITE_TAC[LIST_REL_EL_EQN] THEN
        CONJ_TAC THENL
         [W(fun (asl,gl) ->
            let a2v = grab_asm (fun th ->
              hd_is "ALL2" (concl th) &&
              is_abs (el 0 (snd (strip_comb (concl th))))) asl in
            USE_THEN "lr2" (fun lr2 ->
              ACCEPT_TAC (TRANS
                (CONJUNCT1 (REWRITE_RULE[LIST_REL_EL_EQN] a2v))
                (CONJUNCT1 (REWRITE_RULE[LIST_REL_EL_EQN] lr2)))));
          X_GEN_TAC `j:num` THEN DISCH_TAC THEN elem_tac];
        FIRST_ASSUM MATCH_ACCEPT_TAC;
        USE_THEN "hl2" (fun hl2 -> USE_THEN "lr2" (fun lr2 ->
          let len = CONJUNCT1
                      (REWRITE_RULE[LIST_REL_EL_EQN] lr2) in
          REWRITE_TAC[BlockRep_def] THEN
          ACCEPT_TAC (REWRITE_RULE[len] hl2)))]] in
  (* a pointer of the code: the root is a word *)
  let c4 =
    REPEAT STRIP_TAC THEN REPEAT SUBST_VAR_ASM THEN inl_step THEN
    MATCH_ACCEPT_TAC (el 3 rl) in
  (* a reference that holds no thunk: the invariant of the heap
     says what its element is, and it is no thunk's *)
  let d5a =
    REPEAT SUBST_VAR_ASM THEN inl_step THEN
    TRY (SOLVED no_thunk_ref) THEN
    MATCH_MP_TAC (el 4 rl) THEN REPEAT CONJ_TAC THEN
    FIRST_ASSUM MATCH_ACCEPT_TAC in
  (* a reference that holds a thunk which the heap holds: the
     inlining keeps the root, and then the element of the thunk
     moves with its own root, or it takes the root of the element
     for the root of the value, and then the value of the thunk
     stands where the thunk stood *)
  let d5b =
    notb THEN REPEAT SUBST_VAR_ASM THEN inl_step THENL
     [MATCH_MP_TAC (el 5 rl) THEN
      W(fun (asl,gl) ->
        let lr = grab_asm (fun th ->
          hd_is "ALL2" (concl th) &&
          hd_is "gc_heap_inline_rel"
            (el 0 (snd (strip_comb (concl th))))) asl in
        let hl = grab_asm (fun th ->
          hd_is "heap_lookup" (lhs (concl th)) &&
          hd_is "ThunkBlock" (rand (rhs (concl th)))) asl in
        MP_TAC (MATCH_MP (MATCH_MP keep_de1 lr)
                  (REWRITE_RULE[ThunkBlock_def] hl))) THEN
      DISCH_THEN (CHOOSE_THEN
        (CONJUNCTS_THEN2 (LABEL_TAC "hl2") (LABEL_TAC "gi"))) THEN
      W(fun (asl,gl) ->
        let lk = grab_asm (fun th ->
          hd_is "sptree_lookup" (lhs (concl th)) &&
          hd_is "bvlSem_Thunk" (rand (rhs (concl th)))) asl in
        let thk = rand (rhs (concl lk)) in
        USE_THEN "gi" (fun gi ->
          MAP_EVERY EXISTS_TAC
            [lhand thk; rand thk; rand (concl gi)])) THEN
      REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
      TRY (SOLVED (USE_THEN "hl2" (fun hl2 ->
        REWRITE_TAC[ThunkBlock_def] THEN ACCEPT_TAC hl2))) THEN
      DISCH_TAC THEN
      W(fun (asl,gl) ->
        let vi = grab_asm (fun th ->
          hd_is "v_inv" (concl th)) asl in
        spec_bc (el 1 (snd (strip_comb (concl vi)))) trans_thunk)
      THEN
      W(fun (asl,gl) ->
        let vi = grab_asm (fun th ->
          hd_is "v_inv" (concl th)) asl in
        USE_THEN "gi" (fun gi -> use_ckih vi gi));
      W(fun (asl,gl) ->
        let hls = filter (fun (_,th) ->
          (try hd_is "heap_lookup" (lhs (concl th)) &&
               hd_is "ThunkBlock" (rand (rhs (concl th)))
           with Failure _ -> false)) asl in
        MP_TAC (REWRITE_RULE[injectivity "option"; ThunkBlock_11]
                  (TRANS (SYM (snd (el 0 hls)))
                         (snd (el 1 hls))))) THEN
      DISCH_THEN STRIP_ASSUME_TAC THEN REPEAT SUBST_VAR_ASM THEN
      MATCH_MP_TAC (el 6 rl) THEN
      W(fun (asl,gl) ->
        let lk = grab_asm (fun th ->
          hd_is "sptree_lookup" (lhs (concl th)) &&
          hd_is "bvlSem_Thunk" (rand (rhs (concl th)))) asl in
        EXISTS_TAC (rand (rand (rhs (concl lk))))) THEN
      REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
      TRY (SOLVED (FIRST_ASSUM (fun im ->
        if not (is_imp (concl im)) then NO_TAC else
        MATCH_ACCEPT_TAC
          (MP im (REFL (lhs (lhand (concl im)))))))) THEN
      DISCH_TAC THEN
      W(fun (asl,gl) ->
        let vi = grab_asm (fun th ->
          hd_is "v_inv" (concl th)) asl in
        spec_bc (el 1 (snd (strip_comb (concl vi)))) trans_thunk)
      THEN
      W(fun (asl,gl) ->
        let vi = grab_asm (fun th ->
          hd_is "v_inv" (concl th)) asl in
        let gr = grab_asm (fun th ->
          hd_is "gc_inline_rel" (concl th)) asl in
        let ar = snd (strip_comb (concl gr)) in
        let x = el 0 (tparts (el 3 (snd (strip_comb (concl vi))))) in
        let gi = ISPECL [el 0 ar; el 1 ar; x] (CONJUNCT1 irules) in
        use_ckih vi gi)] in
  (* and a reference that holds a thunk which was evaluated: the
     value of it stands where the reference stands *)
  let d5c =
    notb THEN REPEAT SUBST_VAR_ASM THEN
    MATCH_MP_TAC (el 6 rl) THEN
    W(fun (asl,gl) ->
      let lk = grab_asm (fun th ->
        hd_is "sptree_lookup" (lhs (concl th)) &&
        hd_is "bvlSem_Thunk" (rand (rhs (concl th)))) asl in
      EXISTS_TAC (rand (rand (rhs (concl lk))))) THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
    DISCH_TAC THEN
    W(fun (asl,gl) ->
      let vi = grab_asm (fun th -> hd_is "v_inv" (concl th)) asl in
      spec_bc (el 1 (snd (strip_comb (concl vi)))) trans_thunk) THEN
    W(fun (asl,gl) ->
      let vi = grab_asm (fun th -> hd_is "v_inv" (concl th)) asl in
      let gi = grab_asm (fun th ->
        hd_is "gc_inline_rel" (concl th)) asl in
      use_ckih vi gi) in
  let c5 = REPEAT STRIP_TAC THENL [d5a; d5b; d5c] in
  (* the induction of the source: on the counter, and the cases of
     the value *)
  let setup =
    MATCH_MP_TAC num_WF THEN X_GEN_TAC `ck:num` THEN
    DISCH_THEN (LABEL_TAC "ckih") THEN REPEAT GEN_TAC THEN
    STRIP_TAC THEN CASES_ON_NAME "v" THEN
    USE_CHANGED [v_inv_def] in
  setup THENL [c1; c2; c3; c4; c5])));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let gc_heap_inline_rel_v_inv = prove
 (cake_as_vars (fun () ->
    `LIST_REL (gc_heap_inline_rel dest_evaluated_thunk_rel heap1) heap1
  heap2 /\
     (!n.
       n IN FDOM f /\
       reachable_refs [v] refs n ==>
         bc_ref_inv conf n refs (f,tf,heap1,be)) /\
     v_inv conf v refs (x1,f,tf,heap1) /\
     gc_inline_rel dest_evaluated_thunk_rel heap1 x1 x2 ==>
       v_inv conf v refs (x2,f,tf,heap2)`),
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; gc_heap_inline_rel_v_inv_lemma]));;

(* the port's own: the steps that a lemma about gc_inline takes.
   The relation of the two heaps moves an element and relates
   the values in it, and gc_heap_inline_rel_v_inv carries v_inv
   over for one of them; the proofs of this part of the file
   share them *)

(* that a value of a list is one of its elements *)
let MEM_CLOSE =
  FIRST
   [SOLVED (REWRITE_TAC[MEM] THEN ASM_REWRITE_TAC[]);
    SOLVED (REWRITE_TAC[MEM_EL] THEN EXISTS_TAC `i:num` THEN
            ASM_REWRITE_TAC[] THEN
            POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (filter
              (fun t -> let c = concl t in
                 hd_is "<" c ||
                 (is_eq c && (hd_is "LENGTH" (lhand c) ||
                              hd_is "LENGTH" (rand c)))) l)) THEN
            ASM_ARITH_TAC);
    SOLVED (MATCH_MP_TAC MEM_EL THEN ASM_ARITH_TAC);
    SOLVED (ASM_SIMP_TAC[MEM_EL])];;

let AT_I nm =
  (* the rest inside the search: two assumptions can be about the
     same relation, and only one of them has an index bound that
     the goal gives (PORTING-GUIDE.md entry 42) *)
  FIRST_X_ASSUM (fun th ->
    let b = snd (strip_forall (concl th)) in
    if not (is_imp b) || not (hd_is nm (rand b)) then fail() else
    MP_TAC (SPEC `i:num` th) THEN
    (ANTS_TAC THENL
      [POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (filter
         (fun t -> let c = concl t in
            hd_is "<" c ||
            (is_eq c && (hd_is "LENGTH" (lhand c) ||
                         hd_is "LENGTH" (rand c)))) l)) THEN
       ASM_ARITH_TAC;
       ALL_TAC]) THEN
    DISCH_TAC);;

(* the element of the new heap that the relation gives for the one
   the arm names *)
let MOVE_INLINE =
  W(fun (asl,w as gl) ->
    let lr = the_asm (fun c -> hd_is "ALL2" c &&
               hd_is "gc_heap_inline_rel"
                 (el 0 (snd (strip_comb c)))) gl in
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c) &&
               hd_is "SOME" (rand c)) gl in
    let hl' = CONV_RULE(TOP_DEPTH_CONV let_CONV)
                (REWRITE_RULE[RefBlock_def; BlockRep_def;
                              ThunkBlock_def; bytes_def] hl) in
    STRIP_ASSUME_TAC (MATCH_MP
      (MATCH_MP LIST_REL_gc_heap_inline_DataElement lr) hl'));;

(* the value of an element of the old heap, in the new one *)
let SURVIVES =
  MATCH_MP_TAC (GEN_ALL gc_heap_inline_rel_v_inv) THEN
  W(fun gl ->
    let vi = the_asm (hd_is "v_inv") gl in
    let xs = tparts (rand (concl vi)) in
    let bri = the_asm (fun c ->
      let b = snd (strip_forall c) in
      is_imp b && hd_is "bc_ref_inv" (rand b)) gl in
    let bs = tparts (rand (rand (snd (strip_forall (concl bri))))) in
    EXISTS_TAC (el 3 bs) THEN EXISTS_TAC (el 2 bs) THEN
    EXISTS_TAC (el 0 xs)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (SOLVED (REWRITE_TAC[LIST_REL_EL_EQN] THEN
               ASM_REWRITE_TAC[])) THEN
  (* and the references it reaches are reachable from the stack *)
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM (fun bri ->
    let b = snd (strip_forall (concl bri)) in
    if not (is_imp b) || not (hd_is "bc_ref_inv" (rand b))
    then fail() else MATCH_MP_TAC bri) THEN
  CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST
   [(* the value is on the stack *)
    SOLVED (MATCH_MP_TAC (GEN_ALL reach_mem) THEN
    W(fun gl ->
      let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                 hd_is "CONS" (el 0 (snd (strip_comb c)))) gl in
      EXISTS_TAC (lhand (el 0 (snd (strip_comb (concl rr)))))) THEN
    CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    MEM_CLOSE);
    (* or inside a reference that the stack reaches *)
    SOLVED (W(fun gl ->
      let rr2 = the_asm (fun c -> hd_is "reachable_refs" c &&
                  hd_is "CONS" (el 0 (snd (strip_comb c)))) gl in
      let v = lhand (el 0 (snd (strip_comb (concl rr2)))) in
      let rr1 = the_asm (fun c -> hd_is "reachable_refs" c &&
                  not (hd_is "CONS"
                         (el 0 (snd (strip_comb c))))) gl in
      let args = snd (strip_comb (concl rr1)) in
      let r2 = mk_var("r2", type_of (el 2 args)) in
      let tm = mk_forall (r2,
        mk_imp (list_mk_icomb "MEM" [r2; list_mk_icomb "get_refs" [v]],
                list_mk_icomb "ref_edge" [el 1 args; el 2 args; r2])) in
      SUBGOAL_THEN tm (fun edges ->
        ACCEPT_TAC (MATCH_MP reach_val
          (CONJ rr1 (CONJ edges rr2)))) THEN
      (* the value is one of the reference's own *)
      REWRITE_TAC[ref_edge_def] THEN ASM_REWRITE_TAC[] THEN
      MATCH_REDUCE_TAC THEN REPEAT STRIP_TAC THEN
      MATCH_MP_TAC (GEN_ALL refs_in_block) THEN
      EXISTS_TAC v THEN
      CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
      MEM_CLOSE))];;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_stack_ref_inv_gc_inline = prove
 (cake_as_vars (fun () ->
    `gc_inline dest_evaluated_thunk_rel (roots1,heap1) (roots2,heap2) /\
     bc_stack_ref_inv conf ts stack refs (roots1,heap1,be) ==>
       bc_stack_ref_inv conf ts stack refs (roots2,heap2,be)`),
  (* the steps over the relation of the two heaps are above the
     statement (tools/overrides.py), with what reaches a
     reference.  The two maps of the invariant are the same
     ones: what changes is the heap, and the addresses that
     hold data are the same in both
     (gc_heap_inline_rel_heap_lookup) *)
  (STRIP_TAC THEN
   FIRST_X_ASSUM (fun gi ->
     if not (hd_is "gc_inline" (concl gi)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[gc_inline_def] gi)) THEN
   FIRST_X_ASSUM (fun inv ->
     if not (hd_is "bc_stack_ref_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[bc_stack_ref_inv_def] inv)) THEN
   REWRITE_TAC[bc_stack_ref_inv_def] THEN
   W(fun gl ->
     let sub p = rand (lhand (concl (the_asm (fun c ->
       hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
     EXISTS_TAC (sub "domain") THEN EXISTS_TAC (sub "all_ts")) THEN
   (* the addresses that hold data are the same in the two heaps *)
   W(fun gl ->
     let lr = the_asm (fun c -> hd_is "ALL2" c &&
                hd_is "gc_heap_inline_rel"
                  (el 0 (snd (strip_comb c)))) gl in
     RULE_ASSUM_TRY (REWRITE_RULE
       [MATCH_MP gc_heap_inline_rel_heap_lookup lr])) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THENL
    [(* the roots of the new heap are the old ones' partners, and
        v_inv survives the relation *)
         (REWRITE_TAC[LIST_REL_EL_EQN] THEN
          RULE_ASSUM_TRY (REWRITE_RULE[LIST_REL_EL_EQN]) THEN
          SPLIT_ASM_TAC THEN
          CONJ_TAC THENL
           [ASM_MESON_TAC[];
            ALL_TAC] THEN
          X_GEN_TAC `i:num` THEN DISCH_TAC THEN
          CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
          AT_I "v_inv" THEN AT_I "gc_inline_rel" THEN
          RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) THEN
          SURVIVES);
     (* and the invariant of a reference that the stack reaches *)
     X_GEN_TAC `m:num` THEN STRIP_TAC THEN
     FIRST_ASSUM (fun bri ->
       let b = snd (strip_forall (concl bri)) in
       if not (is_imp b) || not (hd_is "bc_ref_inv" (rand b))
       then fail() else MP_TAC (SPEC `m:num` bri)) THEN
     (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
     DISCH_TAC THEN
     (* which arm of the invariant it is *)
     NAMED_CASES_TAC (cake_as_vars (fun () ->
       `FLOOKUP (f:(num,num)fmap) (m:num)`)) [[]; ["x"]] THEN
     NAMED_CASES_TAC (cake_as_vars (fun () ->
       `sptree_lookup m (refs:((dataSem_v)bvlSem_ref)spt)`))
       [[]; ["rv"]] THEN
     TRY (SOLVED (FIRST_X_ASSUM (fun inv ->
       if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
       MP_TAC (REWRITE_RULE[bc_ref_inv_def] inv)) THEN
       ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
       CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[])) THEN
     NAMED_CASES_TAC (cake_as_vars (fun () ->
       `rv:(dataSem_v)bvlSem_ref`))
       [["ys"]; ["flag"; "bs"]; ["ev"; "vv"];
        ["tg"; "fin"; "ll"; "cc"; "rr"]] THEN
     USE_ARM THEN
     SPLIT_ASM_TAC THEN
     TRY (FIRST_X_ASSUM (fun ex ->
       if not (is_exists (concl ex)) then fail() else
       STRIP_ASSUME_TAC ex)) THEN
     RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
     TRY (CONV_TAC(TOP_DEPTH_CONV let_CONV)) THEN
     REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
     MOVE_INLINE THEN
     (* a one-element list on the one side is one on the other *)
     TRY (W(fun gl ->
       let lr = the_asm (fun c -> hd_is "ALL2" c &&
                  hd_is "gc_inline_rel"
                    (el 0 (snd (strip_comb c)))) gl in
       let args = snd (strip_comb (concl lr)) in
       if not (hd_is "CONS" (el 1 args)) then fail() else
       CASES_ON_TAC (el 2 args))) THEN
     RULE_ASSUM_TRY (REWRITE_RULE[ALL2_DEF; HD; TL;
                                  NOT_CONS_NIL]) THEN
     TRY (FIRST_ASSUM CONTR_TAC) THEN
     SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
     (* the witness is what the relation gives for the element *)
     TRY (W(fun (asl,w as gl) ->
       let nh = the_asm (fun c -> is_eq c &&
                  hd_is "heap_lookup" (lhand c) &&
                  can (fun t -> hd_is "DataElement" (rand t))
                    (rand c)) gl in
       let ys2 = el 0 (snd (strip_comb (rand (rand (concl nh))))) in
       let v = fst (dest_exists w) in
       if type_of v = type_of ys2 then EXISTS_TAC ys2
       else EXISTS_TAC (lhand ys2))) THEN
     REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
     (* the element at the address *)
     W(fun (asl,w) ->
       if not (is_eq w && hd_is "heap_lookup" (lhand w)) then ALL_TAC
       else
        (REWRITE_TAC[RefBlock_def; BlockRep_def; ThunkBlock_def;
                     bytes_def] THEN
         TRY (CONV_TAC(TOP_DEPTH_CONV let_CONV)) THEN
         TRY (FIRST_ASSUM (fun lr ->
           if not (hd_is "ALL2" (concl lr)) then fail() else
           SUBST1_TAC (SYM (MATCH_MP LIST_REL_LENGTH lr)))) THEN
         ASM_REWRITE_TAC[])) THEN
     (* the values of the elements of a block *)
     W(fun (asl,w) -> if not (hd_is "ALL2" w) then ALL_TAC else
          (REWRITE_TAC[LIST_REL_EL_EQN] THEN
            RULE_ASSUM_TRY (REWRITE_RULE[LIST_REL_EL_EQN]) THEN
            SPLIT_ASM_TAC THEN
            REPEAT CONJ_TAC THEN
            TRY (SOLVED (POP_ASSUM_LIST (fun l ->
              MAP_EVERY ASSUME_TAC (filter
                (fun th -> let c = concl th in
                   hd_is "<" c ||
                   (is_eq c && (hd_is "LENGTH" (lhand c) ||
                                hd_is "LENGTH" (rand c)))) l)) THEN
              ASM_ARITH_TAC)) THEN
            X_GEN_TAC `i:num` THEN DISCH_TAC THEN
            CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
            AT_I "v_inv" THEN AT_I "gc_inline_rel" THEN
            RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) THEN
            SURVIVES)) THEN
     (* and the value of a thunk *)
     W(fun (asl,w) ->
       if not (hd_is "v_inv" w) then ALL_TAC else SURVIVES)]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_stack_ref_inv_gc_related_roots_heap = prove
 (cake_as_vars (fun () ->
    `gc_related_roots_heap g (roots1,heap1) (roots2,heap2) /\
     bc_stack_ref_inv conf ts stack refs (roots1,heap1,be) ==>
       bc_stack_ref_inv conf ts stack refs (roots2,heap2,be)`),
  (* the two maps of the new invariant are the old ones composed
     with the map of the collection (f_o_f, whose domain and whose
     application are f_o_f_DEF and FAPPLY_f_o_f of
     ml/lib/lemmas.ml).  The domains only shrink, the two
     injections compose, the roots of the new heap are the old ones
     mapped (EL_ADDR_MAP) with v_inv_related for each of them, and
     a reference that is reachable keeps its block by
     bc_ref_inv_related *)
  (STRIP_TAC THEN
   FIRST_X_ASSUM (fun gr ->
     if not (hd_is "gc_related_roots_heap" (concl gr)) then fail()
     else STRIP_ASSUME_TAC
            (REWRITE_RULE[gc_related_roots_heap_def] gr)) THEN
   FIRST_X_ASSUM (fun inv ->
     if not (hd_is "bc_stack_ref_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[bc_stack_ref_inv_def] inv)) THEN
   VAR_EQ_TAC THEN
   REWRITE_TAC[bc_stack_ref_inv_def] THEN
   (* the two maps of the new invariant are the old ones after the
      map of the collection *)
   W(fun (asl,w) ->
     let sub p = rand (lhand (concl (snd (find (fun (_,th) ->
       hd_is "SUBSET" (concl th) &&
       hd_is p (rand (concl th))) asl)))) in
     let gc = snd (find (fun (_,th) ->
       hd_is "gc_related" (concl th)) asl) in
     let g = el 0 (snd (strip_comb (concl gc))) in
     EXISTS_TAC (list_mk_icomb "f_o_f" [g; sub "domain"]) THEN
     EXISTS_TAC (list_mk_icomb "f_o_f" [g; sub "all_ts"])) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   (* the domains only shrink *)
   TRY (SOLVED
         (REWRITE_TAC[SUBSET; f_o_f_DEF; IN_ELIM_THM] THEN
          REPEAT STRIP_TAC THEN
          FIRST_ASSUM (fun sub ->
            if not (hd_is "SUBSET" (concl sub)) then fail() else
            MATCH_MP_TAC (REWRITE_RULE[SUBSET; IN_ELIM_THM] sub))
          THEN
          FIRST_ASSUM ACCEPT_TAC)) THEN
   (* and the two injections compose *)
   TRY (SOLVED
         (POP_ASSUM_LIST (fun l ->
            MAP_EVERY ASSUME_TAC
              (filter (fun th ->
                 let c = concl th in
                 hd_is "INJ" c || hd_is "gc_related" c) l)) THEN
          RULE_ASSUM_TRY (REWRITE_RULE[gc_related_def]) THEN
          SPLIT_ASM_TAC THEN
          RULE_ASSUM_TRY (REWRITE_RULE[INJ; IN_ELIM_THM]) THEN
          SPLIT_ASM_TAC THEN
          REWRITE_TAC[INJ; f_o_f_DEF; IN_ELIM_THM] THEN
          REPEAT STRIP_TAC THEN
          ASM_SIMP_TAC[FAPPLY_f_o_f] THEN
          RULE_ASSUM_TRY (REWRITE_RULE[FAPPLY_f_o_f]) THEN
          ASM_MESON_TAC[FAPPLY_f_o_f])) THEN
   (* the roots of the new heap are the old ones mapped, and
      v_inv_related says the relation survives the map *)
   TRY (SOLVED
         (REWRITE_TAC[LIST_REL_EL_EQN; LENGTH_ADDR_MAP] THEN
          RULE_ASSUM_TRY (REWRITE_RULE[LIST_REL_EL_EQN]) THEN
          SPLIT_ASM_TAC THEN
          CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
          X_GEN_TAC `i:num` THEN DISCH_TAC THEN
          W(fun (asl,w) ->
            let am = find_term (hd_is "ADDR_MAP") w in
            SUBGOAL_THEN (mk_binop `(<):num->num->bool` `i:num`
                            (list_mk_icomb "LENGTH" [rand am]))
              ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
          ASM_SIMP_TAC[EL_ADDR_MAP] THEN
          CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
          (* the old relation at the same index *)
          FIRST_ASSUM (fun lr ->
            let b = snd (strip_forall (concl lr)) in
            if not (is_imp b && can (find_term (hd_is "v_inv"))
                      (rand b)) then fail() else
            MP_TAC (SPEC `i:num` lr)) THEN
          (ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
          DISCH_TAC THEN
          MATCH_MP_TAC (GEN_ALL (DISCH_ALL (CONJUNCT1
            (UNDISCH (SPEC_ALL (GEN_ALL v_inv_related)))))) THEN
          W(fun (asl,w) ->
            let gc = snd (find (fun (_,th) ->
              hd_is "gc_related" (concl th)) asl) in
            EXISTS_TAC (el 1 (snd (strip_comb (concl gc))))) THEN
          REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
          REPEAT STRIP_TAC THEN
          FIRST_X_ASSUM MATCH_MP_TAC THEN
          ASM_MESON_TAC[MEM_EL])) THEN
   (* and the invariant of a reference that is reachable *)
   REPEAT STRIP_TAC THEN
   FIRST_ASSUM (fun gc ->
     if not (hd_is "gc_related" (concl gc)) then fail() else
     MATCH_MP_TAC (GEN_ALL bc_ref_inv_related) THEN
     EXISTS_TAC (el 1 (snd (strip_comb (concl gc))))) THEN
   CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
   CONJ_TAC THENL
    [FIRST_X_ASSUM MATCH_MP_TAC THEN
     CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
     ASM_MESON_TAC[f_o_f_DEF; IN_ELIM_THM];
     ASM_MESON_TAC[f_o_f_DEF; IN_ELIM_THM]]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_stack_ref_inv_related = prove
 (cake_as_vars (fun () ->
    `gc_inline_related dest_evaluated_thunk_rel g (roots1,heap1)
  (roots2,heap2) /\
     bc_stack_ref_inv conf ts stack refs (roots1,heap1,be) ==>
       bc_stack_ref_inv conf ts stack refs (roots2,heap2,be)`),
  (REWRITE_TAC[gc_inline_related_def] THEN REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[bc_stack_ref_inv_gc_inline;
                 bc_stack_ref_inv_gc_related_roots_heap]));;

(* [simp] *)
let data_up_to_APPEND = prove
 (`data_up_to (heap_length xs) (xs ++ ys) <=> EVERY isDataElement xs`,
  (REWRITE_TAC[data_up_to_def; heap_split_APPEND_if; LT_REFL;
               SUB_REFL; heap_split_0] THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[APPEND_NIL; injectivity "option"; PAIR_EQ] THEN
   MESON_TAC[]));;

let all_reachable_from_roots_def = cake_define
  `all_reachable_from_roots roots heap <=>
     (!p xs l d.
        heap_lookup p heap = SOME (DataElement xs l d) ==>
        p IN reachable_addresses roots heap)`;;

(* HOL4 data_to_word_memoryProofScript.sml:1196-1198: a theorem that
   HOL4 states as the value of an ML expression:
   IN_reachable_addresses *)

let reachable_addresses_related = prove
 (`k IN reachable_addresses roots heap /\ gc_related f heap heap2 /\
   reachable_addresses roots heap SUBSET FDOM f ==> FAPPLY
   f k IN reachable_addresses (ADDR_MAP ((FAPPLY) f) roots) heap2`,
  (* the root that reaches k reaches it over a path of the heap, and
     the map takes that path to one of the new heap: the first
     address is a key of the map because it is reachable itself (the
     path of no steps), and every step gives the next one *)
  ((* a pointer of the roots is a pointer of the mapped roots *)
   let mem_addr_map = prove
    (`!roots x t f.
        MEM (gc_shared_Pointer x t) roots
        ==> MEM (gc_shared_Pointer (f x) t) (ADDR_MAP f roots)`,
     LIST_INDUCT_TAC THEN REWRITE_TAC[MEM; ADDR_MAP_def] THEN
     REPEAT GEN_TAC THEN CASES_BY_NAME "h" THEN
     REWRITE_TAC[ADDR_MAP_def; MEM; injectivity "heap_address";
                 distinctness "heap_address"] THEN
     REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     TRY DISJ2_TAC THEN
     TRY(FIRST_ASSUM(fun ih -> FIRST_ASSUM(fun m ->
       MATCH_ACCEPT_TAC(MATCH_MP ih m))))) in
   (* and a path of the old heap is a path of the new one, address
      by address: the element that an edge comes from is the mapped
      element, so the edge is there, and the address it goes to is one
      that the map has *)
   let path = prove
    (`!hp hp2 g.
        gc_related g hp hp2 ==>
        !x k. RTC (gc_edge hp) x k ==> x IN FDOM g
              ==> RTC (gc_edge hp2) (FAPPLY g x) (FAPPLY g k)`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
      [REPEAT STRIP_TAC THEN
       MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
       ALL_TAC] THEN
     REPEAT GEN_TAC THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (MP_TAC o REWRITE_RULE[gc_edge_def]) ASSUME_TAC) THEN
     DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
     DISCH_TAC THEN
     FIRST_ASSUM(fun gr ->
       let g3 = CONJUNCT2(CONJUNCT2
                  (REWRITE_RULE[gc_related_def] gr)) in
       FIRST_ASSUM(fun hl -> FIRST_ASSUM(fun fd ->
         let th = MATCH_MP g3 (CONJ fd hl) in
         FIRST_ASSUM(fun m ->
           let yin = MATCH_MP (CONJUNCT2 th) m in
           FIRST_ASSUM(fun ih ->
             let rtc = MATCH_MP ih yin in
             MATCH_MP_TAC(CONJUNCT2(SPEC_ALL RTC_RULES)) THEN
             EXISTS_TAC (el 1 (snd(strip_comb(concl rtc)))) THEN
             CONJ_TAC THENL
              [REWRITE_TAC[gc_edge_def] THEN
               MAP_EVERY EXISTS_TAC
                 (snd(strip_comb(rand(rhs(concl(CONJUNCT1 th))))) @
                  [rand(el 0 (snd(strip_comb(concl m))))]) THEN
               CONJ_TAC THENL
                [ACCEPT_TAC(CONJUNCT1 th);
                 MATCH_ACCEPT_TAC(MATCH_MP mem_addr_map m)];
               ACCEPT_TAC rtc])))))) in
     REPEAT STRIP_TAC THEN
     (* the hypothesis: a pointer of the roots and a path to k *)
     FIRST_ASSUM(fun kin ->
       if not (hd_is "reachable_addresses" (rand(concl kin)))
       then fail() else
       MP_TAC(REWRITE_RULE[IN; reachable_addresses_def] kin)) THEN
     DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
     (* x is reachable, so it is a key of the map *)
     FIRST_ASSUM(fun m ->
       if not (hd_is "MEM" (concl m)) then fail() else
       FIRST_ASSUM(fun r ->
         if not (hd_is "RTC" (concl r)) then fail() else
         let args = snd(strip_comb(concl r)) in
         let x = el 1 args in
         FIRST_ASSUM(fun sub ->
           let impl = SPEC x (REWRITE_RULE[SUBSET] sub) in
           SUBGOAL_THEN (lhand(concl impl)) (fun a ->
             let xin = MATCH_MP impl a in
             FIRST_ASSUM(fun gr ->
               let rtc =
                 MATCH_MP (MATCH_MP (MATCH_MP path gr) r) xin in
               REWRITE_TAC[IN; reachable_addresses_def] THEN
               MAP_EVERY EXISTS_TAC
                 [rand(el 0 (snd(strip_comb(concl m))));
                  el 1 (snd(strip_comb(concl rtc)))] THEN
               CONJ_TAC THENL
                [MATCH_ACCEPT_TAC(MATCH_MP mem_addr_map m);
                 ACCEPT_TAC rtc]))))) THEN
     (* and the subgoal: x is reachable, by the path of no steps *)
     (REWRITE_TAC[IN; reachable_addresses_def] THEN
       FIRST_ASSUM(fun m ->
         if not (hd_is "MEM" (concl m)) then fail() else
         FIRST_ASSUM(fun r ->
           if not (hd_is "RTC" (concl r)) then fail() else
           MAP_EVERY EXISTS_TAC
             [rand(el 0 (snd(strip_comb(concl m))));
              el 1 (snd(strip_comb(concl r)))])) THEN
      CONJ_TAC THENL
       [FIRST_ASSUM MATCH_ACCEPT_TAC;
        MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES))])));;

let IMP_all_reachable_from_roots = prove
 (`FDOM f = reachable_addresses roots heap /\
   FRANGE f = {a | isSomeDataElement (heap_lookup a heap2)} /\
   gc_related f heap heap2 ==>
   all_reachable_from_roots (ADDR_MAP ((FAPPLY) f) roots) heap2`,
  (* an address of the second heap is in the range of f, so it is the
     image of an address of the first, which is reachable *)
  (REWRITE_TAC[all_reachable_from_roots_def] THEN
   REPEAT STRIP_TAC THEN
   SUBGOAL_THEN `(p:num) IN FRANGE (f:(num,num)fmap)` MP_TAC THENL
    [ASM_REWRITE_TAC[IN_ELIM_THM; isSomeDataElement_def] THEN
     ASM_MESON_TAC[];
     REWRITE_TAC[FMAP_IN_FRANGE] THEN STRIP_TAC THEN
     FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN
     MATCH_MP_TAC reachable_addresses_related THEN
     CONJ_TAC THENL
      [ASM_MESON_TAC[];
       CONJ_TAC THENL
        [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[SUBSET_REFL]]]]));;

let heap_lookup_expand_eq_SOME = prove
 (`heap_lookup a (heap ++ heap_expand n) = SOME (DataElement ys l d) <=>
   heap_lookup a heap = SOME (DataElement ys l d)`,
  (* past the heap the lookup is in the expansion, which is one
     Unused element, and that is not a DataElement *)
  (let hexp = heap_expand_def in
   let hlk = heap_lookup_def in
   let opt = [distinctness "option"; injectivity "option";
              distinctness "heap_element"] in
   REWRITE_TAC[heap_lookup_APPEND] THEN COND_CASES_TAC THEN
   REWRITE_TAC[] THEN
   MATCH_MP_TAC(TAUT `~a /\ ~b ==> (a <=> b)`) THEN CONJ_TAC THENL
    [REWRITE_TAC[hexp] THEN COND_CASES_TAC THEN REWRITE_TAC[hlk] THEN
     REPEAT COND_CASES_TAC THEN REWRITE_TAC opt;
     DISCH_TAC THEN
     FIRST_ASSUM(MP_TAC o MATCH_MP heap_lookup_LESS) THEN
     ASM_ARITH_TAC]));;

let isSomeDataElement_heap_lookup = prove
 (`isSomeDataElement (heap_lookup a (heap ++ heap_expand n)) =
   isSomeDataElement (heap_lookup a heap)`,
  (let hexp = heap_expand_def in
   let hlk = heap_lookup_def in
   let isde = isSomeDataElement_def in
   let opt = [distinctness "option"; injectivity "option";
              distinctness "heap_element"] in
   REWRITE_TAC[heap_lookup_APPEND] THEN COND_CASES_TAC THEN
   REWRITE_TAC[] THEN
   MATCH_MP_TAC(TAUT `~a /\ ~b ==> (a <=> b)`) THEN CONJ_TAC THENL
    [REWRITE_TAC[hexp] THEN COND_CASES_TAC THEN
     REWRITE_TAC[hlk; isde] THEN REPEAT COND_CASES_TAC THEN
     REWRITE_TAC(isde :: opt);
     REWRITE_TAC[isde] THEN STRIP_TAC THEN
     FIRST_ASSUM(MP_TAC o MATCH_MP heap_lookup_LESS) THEN
     ASM_ARITH_TAC]));;

let gc_related_APPEND_heap_expand = prove
 (`gc_related f heap (heap2 ++ heap_expand n) = gc_related f heap
  heap2`,
  (REWRITE_TAC[gc_related_def; isSomeDataElement_heap_lookup;
               heap_lookup_expand_eq_SOME]));;

(* full_gc_thm *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let data_to_word_memoryProof_full_gc_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,heap,be,a,sp,sp1,gens) limit ts
  /\ data_to_word_config_gc_kind
     conf = Simple ==>
      (?roots2 heap2 a2.
        (full_gc (roots,heap,limit) = (roots2,heap2,a2,T)) /\
         abs_ml_inv conf stack refs
          (roots2,heap2 ++ heap_expand (limit - a2),be,
           a2,limit - a2,0,gens) limit ts /\
        (heap_length heap2 = a2) /\
        (heap_length (heap_filter (reachable_addresses roots heap)
          heap) =
         heap_length heap2) /\
        all_reachable_from_roots roots2 (heap2 ++ heap_expand
          (limit - a2)) /\
        EVERY isDataElement heap2)`),
  (* what the collection leaves is what full_gc_related,
     full_gc_LENGTH and full_gc_ok say of it, and the three say it
     of one collection, so its value is one.  The heap it wrote
     holds data up to the space that is left, which is the
     expansion at its end; the stack and the references go over
     with bc_stack_ref_inv_related, where the inlining that its
     relation allows is the identity one and what is left is that
     the collection relates the roots and the heap; and the heap is
     reachable from the roots it returned
     (IMP_all_reachable_from_roots), because a pointer of the roots
     is an address that they reach *)
  ((* the values of a list are related to themselves by a reflexive
      relation *)
   let all2_refl = prove
    (`!(R:A->A->bool) l. (!x. R x x) ==> ALL2 R l l`,
     GEN_TAC THEN LIST_INDUCT_TAC THEN ASM_SIMP_TAC[ALL2]) in
   STRIP_TAC THEN SPLIT_ASM_TAC THEN
   (* what the invariant says of the stack *)
   FIRST_ASSUM (fun inv ->
     if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def] inv)) THEN
   (* what the collection leaves: the heap it wrote, the map of the
      addresses it moved, and that both are good *)
   W(fun gl ->
     let ro = the_asm (hd_is "roots_ok") gl in
     let ho = the_asm (hd_is "heap_ok") gl in
     STRIP_ASSUME_TAC (MATCH_MP full_gc_related (CONJ ro ho)) THEN
     STRIP_ASSUME_TAC (MATCH_MP full_gc_LENGTH (CONJ ro ho)) THEN
     STRIP_ASSUME_TAC (MATCH_MP full_gc_ok (CONJ ro ho))) THEN
   (* the three say it of one collection, so its value is one *)
   W(fun gl ->
     let eqs = mapfilter (fun (_,th) ->
                 let c = concl th in
                 if is_eq c && hd_is "full_gc" (lhand c)
                 then th else fail()) (fst gl) in
     let e0 = hd eqs in
     MAP_EVERY (fun e ->
       if e = e0 then ALL_TAC else
       STRIP_ASSUME_TAC (REWRITE_RULE[e0; PAIR_EQ] e)) (tl eqs)) THEN
   REPEAT (FIRST_X_ASSUM (fun th ->
     let c = concl th in
     if is_eq c && is_var (lhand c) then SUBST_ALL_TAC th
     else if is_eq c && is_var (rand c) then SUBST_ALL_TAC (SYM th)
     else fail())) THEN
   (* the witnesses: what the collection returned *)
   W(fun gl ->
     let e0 = the_asm (fun c -> is_eq c &&
                hd_is "full_gc" (lhand c)) gl in
     let ps = tparts (rand (concl e0)) in
     MAP_EVERY EXISTS_TAC [el 0 ps; el 1 ps; el 2 ps]) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the length of the heap it wrote is the length of what the
      roots reach *)
   TRY (SOLVED
         (W(fun gl ->
            let hl = the_asm (fun c -> is_eq c &&
                       hd_is "heap_length" (lhand c) &&
                       hd_is "heap_length" (rand c)) gl in
            let fd = the_asm (fun c -> is_eq c &&
                       hd_is "FDOM" (lhand c)) gl in
            ACCEPT_TAC (SYM (REWRITE_RULE[fd] hl))))) THEN
   (* the heap it wrote is reachable from the roots it returned *)
   TRY (SOLVED
         (MATCH_MP_TAC (GEN_ALL IMP_all_reachable_from_roots) THEN
          W(fun gl ->
            let fd = the_asm (fun c -> is_eq c &&
                       hd_is "FDOM" (lhand c)) gl in
            EXISTS_TAC (el 1 (snd (strip_comb
              (rand (concl fd)))))) THEN
          ASM_REWRITE_TAC[gc_related_APPEND_heap_expand;
                          isSomeDataElement_heap_lookup])) THEN
   (* and the invariant of the heap it wrote *)
   REWRITE_TAC[abs_ml_inv_def] THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the kind of the collection says only that the second part of
      the space is empty, and it is *)
   TRY (SOLVED
         (REWRITE_TAC[gc_kind_inv_def] THEN
          ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
          REWRITE_TAC[])) THEN
   (* the space that is left is the expansion at the end of the
      heap, and the heap holds data up to it *)
   TRY (SOLVED
         (W(fun gl ->
            let dl = the_asm (fun c -> hd_is "ALL" c &&
                       hd_is "isDataElement"
                         (el 0 (snd (strip_comb c)))) gl in
            REWRITE_TAC[unused_space_inv_def; ADD_CLAUSES] THEN
            REPEAT CONJ_TAC THEN
            TRY (SOLVED
                  (DISCH_TAC THEN
                   REWRITE_TAC[heap_lookup_APPEND; LT_REFL;
                               SUB_REFL; heap_expand_def] THEN
                   ASM_REWRITE_TAC[heap_lookup_def])) THEN
            TRY (SOLVED
                  (REWRITE_TAC[heap_length_APPEND;
                               heap_length_heap_expand] THEN
                   ASM_ARITH_TAC)) THEN
            REWRITE_TAC[data_up_to_APPEND] THEN
            ACCEPT_TAC dl))) THEN
   (* the stack and the references: the inlining that the relation
      of the collection allows is the identity one, so what is left
      is that the collection relates the roots and the heap *)
   MATCH_MP_TAC (GEN_ALL bc_stack_ref_inv_related) THEN
   W(fun gl ->
     let bsi = the_asm (hd_is "bc_stack_ref_inv") gl in
     let ps = tparts (el 4 (snd (strip_comb (concl bsi)))) in
     let gc = the_asm (hd_is "gc_related") gl in
     let fm = el 0 (snd (strip_comb (concl gc))) in
     MAP_EVERY EXISTS_TAC [fm; el 0 ps; el 1 ps]) THEN
   CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   REWRITE_TAC[gc_inline_related_def; gc_inline_def;
               gc_related_roots_heap_def] THEN
   W(fun (asl,w) ->
     let cs = conjuncts (snd (strip_exists w)) in
     EXISTS_TAC (el 1 (snd (strip_comb (el 0 cs)))) THEN
     EXISTS_TAC (el 1 (snd (strip_comb (el 1 cs))))) THEN
   REPEAT CONJ_TAC THEN
   (* the roots and the heap are related to themselves *)
   TRY (SOLVED
         (MATCH_MP_TAC all2_refl THEN
          MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL
            (let (r,_,_) = gc_inline_rel in r))))) THEN
   TRY (SOLVED
         (MATCH_MP_TAC all2_refl THEN
          MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL
            (let (r,_,_) = gc_heap_inline_rel in r))))) THEN
   (* the collection relates the heap it read and the heap it
      wrote, and the roots it returned are the ones it moved *)
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED (REFL_TAC)) THEN
   (* and a pointer of the roots is an address that they reach *)
   REPEAT GEN_TAC THEN DISCH_TAC THEN
   W(fun gl ->
     let fd = the_asm (fun c -> is_eq c &&
                hd_is "FDOM" (lhand c)) gl in
     let m = the_asm (hd_is "MEM") gl in
     REWRITE_TAC[fd; IN; reachable_addresses_def] THEN
     EXISTS_TAC (rand (el 0 (snd (strip_comb (concl m))))) THEN
     EXISTS_TAC (lhand (el 0 (snd (strip_comb (concl m))))) THEN
     CONJ_TAC THENL
      [ACCEPT_TAC m;
       MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL RTC_RULES))])));;

let make_gc_conf_def = cake_define
  `make_gc_conf limit' =
     (mk_gen_gc_conf limit' (isMutTag o
       FST):(data_to_word_memoryProof_tag#'a) gen_gc_conf)`;;

(* [local] *)
let gc_move_data_refs_split = prove
 (`(gen_gc_gc_move cc s x = (x1,s1)) /\ (!t r. isRef cc (t,r) <=>
  isMutTag t) /\
    EVERY isDataElement (gc_state_h2 s) /\ EVERY (\x.
      ~(data_to_word_memoryProof_isRef x)) (gc_state_h2 s) /\ EVERY
      data_to_word_memoryProof_isRef (gc_state_r4 s) ==>
    EVERY isDataElement (gc_state_h2 s1) /\
    (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h2
      s1) /\ EVERY data_to_word_memoryProof_isRef (gc_state_r4 s1)`,
  (* a move of the gc keeps the data in h2 and the references in
     r4: of a Data it changes nothing, of a Pointer at a
     DataElement it puts the element in r4 when its tag is a
     mutable one and at the end of h2 when it is not, and the
     statement's hypothesis says that isRef of the configuration
     is exactly that.  `record_simps` (ml/lib/tactics.ml) is what
     HOL4's record simp set does: the accessors of gc_state over
     its updates, which HOL Light's define_record does not give *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
   let gcsimps = record_simps "gc_state" ["h2"; "r4"] in
   (* a DataElement is a reference when its tag is a mutable one *)
   let isref = prove
    (`!ys l tag qs.
        data_to_word_memoryProof_isRef (DataElement ys l (tag,qs)) <=>
        isMutTag tag`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[isRef_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[injectivity "heap_element"; PAIR_EQ] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL]) in
   let isdata = prove
    (`!ys l d. isDataElement (DataElement ys l d)`,
     REWRITE_TAC[isDataElement_def] THEN MESON_TAC[]) in
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "gen_gc_gc_move" (lhs (concl th))
         with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   CASES_BY_NAME "x" THEN
   REWRITE_TAC[gen_gc_gc_move_def] THEN
   EVERY_CASE_TAC THEN
   TRY(CASES_BY_NAME "a2") THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   TRY COND_CASES_TAC THEN
   TRY(W(fun (asl,w) ->
     let t = find_term (fun u ->
       hd_is "gc_forward_ptr" u &&
       length (snd(strip_comb u)) = 5) w in
     MP_TAC(ISPEC t PAIR_SURJECTIVE)) THEN
     DISCH_THEN(CHOOSE_THEN(CHOOSE_THEN SUBST1_TAC))) THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   STRIP_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[PAIR_EQ]) THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
   VAR_EQ_TAC THEN
   ASM_REWRITE_TAC(gcsimps @
                   [K_DEF; ALL_APPEND; ALL; isdata; isref]) THEN
   TRY(FIRST_X_ASSUM(fun h ->
     if is_forall (concl h) then RULE_ASSUM_TAC(REWRITE_RULE[h])
     else fail())) THEN
   ASM_REWRITE_TAC[]));;

(* [local] *)
let gc_move_list_data_refs_split = prove
 (`!x x1 s s1.
   (gen_gc_gc_move_list cc s x = (x1,s1)) /\
    (!t r. (isRef cc (t,r) <=> isMutTag t)) /\ EVERY isDataElement
      (gc_state_h2 s) /\ (EVERY (\x. ~(data_to_word_memoryProof_isRef
      x))) (gc_state_h2 s) /\ EVERY data_to_word_memoryProof_isRef
      (gc_state_r4 s) ==>
    EVERY isDataElement (gc_state_h2 s1) /\ (EVERY (\x.
      ~(data_to_word_memoryProof_isRef x))) (gc_state_h2 s1) /\ EVERY
      data_to_word_memoryProof_isRef (gc_state_r4 s1)`,
  (* the move of a list is the move of its head and then of its
     tail, and each of them keeps the three invariants, which is
     what the theorem about one move says *)
  (let gmd = GEN_ALL gc_move_data_refs_split in
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[gen_gc_gc_move_list_def; PAIR_EQ] THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (CONJUNCTS_THEN2 (K ALL_TAC) (SUBST1_TAC o SYM))
       STRIP_ASSUME_TAC) THEN
     ASM_REWRITE_TAC[];
     REWRITE_TAC[gen_gc_gc_move_list_def] THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[PAIR_EQ] THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (CONJUNCTS_THEN2 (K ALL_TAC) (SUBST1_TAC o SYM))
       STRIP_ASSUME_TAC) THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_EXISTS_TAC THEN
     ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC gmd THEN ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[]]));;

(* [local] *)
let gc_move_refs_data_refs_split = prove
 (`!cc s s1.
   (gc_move_refs cc s = s1) /\
    (!t r. (isRef cc (t,r) <=> isMutTag t)) /\ EVERY isDataElement
      (gc_state_h1 s ++ gc_state_h2 s) /\ (EVERY (\x.
      ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s ++
      gc_state_h2 s) /\
    EVERY data_to_word_memoryProof_isRef (gc_state_r1 s ++
      gc_state_r2 s ++ gc_state_r3 s ++ gc_state_r4 s) ==>
    EVERY isDataElement (gc_state_h1 s1 ++ gc_state_h2 s1) /\
    (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s1
      ++ gc_state_h2 s1) /\
    EVERY data_to_word_memoryProof_isRef (gc_state_r1 s1 ++
      gc_state_r2 s1 ++ gc_state_r3 s1 ++ gc_state_r4 s1)`,
  (* the move of the references takes r2 apart element by element,
     so the induction is on the list that r2 is; the port has no
     induction theorem of the definition.  Of a DataElement the
     element moves into r3 and its list is moved, which is where
     the two theorems about the move of a list come in; of anything
     else the collector only takes the ok flag away *)
  (let gcsimps = record_simps "gc_state"
     ["h1"; "h2"; "r1"; "r2"; "r3"; "r4"] in
   (* a DataElement is a reference when its tag is a mutable one *)
   let isref = prove
    (`!ys l tag qs.
        data_to_word_memoryProof_isRef (DataElement ys l (tag,qs)) <=>
        isMutTag tag`,
     REPEAT GEN_TAC THEN REWRITE_TAC[isRef_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[injectivity "heap_element"; PAIR_EQ] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL]) in
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   (* an equation that says what a field of the state was *)
   let is_fld th =
     is_eq(concl th) &&
     (try let h = fst(dest_const(fst(strip_comb(lhs(concl th))))) in
          String.length h > 9 && String.sub h 0 9 = "gc_state_"
      with Failure _ -> false) in
   (* the statement generalised over the list that r2 is, built from
      the goal: the recursion takes that list apart, and the port
      has no induction theorem of the definition *)
   let r2_induct =
     W(fun (asl,w) ->
       let vs,bod = strip_forall w in
       let s = el 1 vs in
       let r2s = find_term
         (fun t -> hd_is "gc_state_r2" t && rand t = s) bod in
       let l = variant (vs @ frees bod) (mk_var("l",type_of r2s)) in
       let gen = list_mk_forall(l :: vs, mk_imp(mk_eq(r2s,l),bod)) in
       SUBGOAL_THEN gen (fun th ->
         MAP_EVERY X_GEN_TAC vs THEN
         ACCEPT_TAC(MP (SPECL (r2s :: vs) th) (REFL r2s)))) in
   (* an empty r2 moves r3 in front of r1 and stops *)
   let base =
     DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
       STRIP_ASSUME_TAC) THEN
     ASM_REWRITE_TAC(K_DEF :: gcsimps) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[ALL_APPEND; ALL]) THEN
     ASM_REWRITE_TAC[ALL_APPEND; ALL] THEN CONV_TAC TAUT in
   (* and an r2 that is no DataElement only takes the ok flag away *)
   let step_common =
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     ONCE_REWRITE_TAC[gc_move_refs_def] THEN ASM_REWRITE_TAC[] THEN
     MATCH_REDUCE_TAC THEN CASES_ON_NAME "h" THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[injectivity "heap_element";
                 distinctness "heap_element"] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL] THEN
     TRY(DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
           STRIP_ASSUME_TAC) THEN
         ASM_REWRITE_TAC(K_DEF :: gcsimps) THEN NO_TAC) in
   (* a DataElement moves into r3: what the move of its list leaves
      in h2 and r4 is what the induction hypothesis asks of them,
      and the other fields are the ones the move did not touch *)
   let data =
     CASES_ON_NAME "a2" THEN PAIRARG_TAC THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
       STRIP_ASSUME_TAC) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[ALL_APPEND; ALL]) THEN
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
     FIRST_ASSUM(fun a1 ->
       if not(is_pair(rhs(concl a1))) then fail() else
       MP_TAC(MATCH_MP
                (REWRITE_RULE[IMP_CONJ]
                   (GEN_ALL gc_move_list_data_refs_split)) a1) THEN
       MP_TAC(MATCH_MP gc_move_list_IMP a1)) THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN ASM_REWRITE_TAC[] THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN
     REWRITE_TAC[ALL_APPEND] THEN
     FIRST_ASSUM(fun ih ->
       MATCH_MP_TAC(REWRITE_RULE[GSYM IMP_CONJ] ih)) THEN
     W(fun (asl,w) ->
       let vs,bod = strip_exists w in
       let tm = rhs (el 1 (conjuncts bod)) in
       MAP_EVERY EXISTS_TAC [lhand tm; rand tm]) THEN
     ASSUM_LIST(fun ths ->
       RULE_ASSUM_TRY(REWRITE_RULE(filter is_fld ths))) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[isref]) THEN
     ASM_REWRITE_TAC(K_DEF :: gcsimps @ [ALL_APPEND; ALL; isref]) in
   r2_induct THEN LIST_INDUCT_TAC THENL
    [REPEAT GEN_TAC THEN DISCH_TAC THEN
     ONCE_REWRITE_TAC[gc_move_refs_def] THEN ASM_REWRITE_TAC[] THEN
     MATCH_REDUCE_TAC THEN base;
     step_common THEN data]));;

(* [local] *)
let gc_move_data_data_refs_split = prove
 (`!cc s s1.
   (gen_gc_gc_move_data cc s = s1) /\
    (!t r. (isRef cc (t,r) <=> isMutTag t)) /\ (EVERY (\x.
      ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s ++
      gc_state_h2 s) /\
    EVERY isDataElement (gc_state_h1 s ++ gc_state_h2 s) /\
    EVERY data_to_word_memoryProof_isRef (gc_state_r1 s ++
      gc_state_r2 s ++ gc_state_r3 s ++ gc_state_r4 s) ==>
    EVERY isDataElement (gc_state_h1 s1 ++ gc_state_h2 s1) /\
    (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s1
      ++ gc_state_h2 s1) /\
    EVERY data_to_word_memoryProof_isRef (gc_state_r1 s1 ++
      gc_state_r2 s1 ++ gc_state_r3 s1 ++ gc_state_r4 s1)`,
  (* the move of the data takes the head of h2 -- of the state
     after the move of its list, not of the state it started from,
     so the induction is not on a list but on the measure of the
     definition: the room that is left under the limit, which the
     element that moves into h1 makes smaller *)
  (let gcsimps = record_simps "gc_state"
     ["h1"; "h2"; "r1"; "r2"; "r3"; "r4"] in
   (* a DataElement is a reference when its tag is a mutable one,
      and is a data element whatever it holds *)
   let isref = prove
    (`!ys l tag qs.
        data_to_word_memoryProof_isRef (DataElement ys l (tag,qs)) <=>
        isMutTag tag`,
     REPEAT GEN_TAC THEN REWRITE_TAC[isRef_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[injectivity "heap_element"; PAIR_EQ] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL]) in
   let isdata = prove
    (`!ys l d. isDataElement (DataElement ys l d)`,
     REWRITE_TAC[isDataElement_def] THEN MESON_TAC[]) in
   (* what the recursion moves is the tail of h2, and the port's TL
      is HOL4's, which is the empty list of the empty list *)
   let all_tl = prove
    (`!p (l:(A)list). ALL p l ==> ALL p (TL l)`,
     GEN_TAC THEN LIST_INDUCT_TAC THEN
     REWRITE_TAC[hol4_TL; ALL] THEN CONV_TAC TAUT) in
   let hlen = [heap_length_APPEND; heap_length_CONS; heap_length_NIL;
               el_length_def] in
   (* an equation that says what a field of the state was *)
   let is_fld th =
     is_eq(concl th) &&
     (try let h = fst(dest_const(fst(strip_comb(lhs(concl th))))) in
          String.length h > 9 && String.sub h 0 9 = "gc_state_"
      with Failure _ -> false) in
   (* the statement generalised over the measure of the definition,
      built from the goal: what the recursion makes smaller is the
      room that is left under the limit, and the port has no
      induction theorem of the definition *)
   let meas_induct =
     W(fun (asl,w) ->
       let vs,bod = strip_forall w in
       let cc = el 0 vs and s = el 1 vs in
       let meas =
         mk_binop `(-):num->num->num`
           (list_mk_icomb "gen_gc_conf_limit" [cc])
           (list_mk_icomb "heap_length"
              [list_mk_icomb "gc_state_h1" [s]]) in
       let n = variant (vs @ frees bod) (mk_var("n",`:num`)) in
       let gen = list_mk_forall(n :: vs,
                   mk_imp(mk_binop `(<=):num->num->bool` meas n,
                          bod)) in
       SUBGOAL_THEN gen (fun th ->
         MAP_EVERY X_GEN_TAC vs THEN
         ACCEPT_TAC(MP (SPECL (meas :: vs) th)
                       (SPEC meas LE_REFL)))) in
   (* the states that the collector gives back without recursing:
      the state itself, or the state with the ok flag taken away *)
   let triv =
     DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
       STRIP_ASSUME_TAC) THEN
     ASM_REWRITE_TAC(K_DEF :: gcsimps) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[ALL_APPEND; ALL]) THEN
     ASM_REWRITE_TAC[ALL_APPEND; ALL] THEN TRY(CONV_TAC TAUT) in
   let common =
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     ONCE_REWRITE_TAC[gc_move_data_def] THEN EVERY_CASE_TAC THEN
     REWRITE_TAC[COND_ID] THEN TRY COND_CASES_TAC THEN
     TRY(triv THEN NO_TAC) in
   (* of a measure that is 0 there is no room for the element that
      the recursion moves, so the branch cannot be taken *)
   let absurd =
     SUBGOAL_THEN `F` CONTR_TAC THEN
     RULE_ASSUM_TRY(REWRITE_RULE hlen) THEN ASM_ARITH_TAC in
   (* and the element moves into h1, which leaves the room under the
      limit smaller by its own length: what the move of its list
      leaves in h2 and r4 is what the induction hypothesis asks of
      them, and the other fields are the ones the move did not
      touch *)
   let data =
     CASES_ON_NAME "a2" THEN PAIRARG_TAC THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
       STRIP_ASSUME_TAC) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[ALL_APPEND; ALL]) THEN
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th
       else fail())) THEN
     FIRST_ASSUM(fun a1 ->
       if not(is_pair(rhs(concl a1))) then fail() else
       MP_TAC(MATCH_MP
                (REWRITE_RULE[IMP_CONJ]
                   (GEN_ALL gc_move_list_data_refs_split)) a1) THEN
       MP_TAC(MATCH_MP gc_move_list_IMP a1)) THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN
     ASM_REWRITE_TAC[ALL; ALL_APPEND] THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN
     ASSUM_LIST(fun ths ->
       RULE_ASSUM_TRY(REWRITE_RULE(filter is_fld ths))) THEN
     ASSUM_LIST(fun ths ->
       MAP_EVERY ASSUME_TAC (mapfilter (MATCH_MP all_tl) ths)) THEN
     RULE_ASSUM_TRY(REWRITE_RULE[isref]) THEN
     REWRITE_TAC[ALL_APPEND] THEN
     FIRST_ASSUM(fun ih ->
       MATCH_MP_TAC(REWRITE_RULE[GSYM IMP_CONJ] ih)) THEN
     W(fun (asl,w) ->
       let vs,bod = strip_exists w in
       let tm = rhs (el 1 (conjuncts bod)) in
       MAP_EVERY EXISTS_TAC [lhand tm; rand tm]) THEN
     ASM_REWRITE_TAC(K_DEF :: gcsimps @
                     [ALL_APPEND; ALL; isref; isdata]) THEN
     RULE_ASSUM_TRY(REWRITE_RULE hlen) THEN
     REWRITE_TAC hlen THEN ASM_ARITH_TAC in
   meas_induct THEN INDUCT_TAC THENL
    [common THEN absurd; common THEN data]));;

(* [local] *)
let gc_move_loop_data_refs_split = prove
 (`!clock cc s s1.
   (gen_gc_gc_move_loop cc s clock = s1) /\
   (!t r. (isRef cc (t,r) <=> isMutTag t)) /\
   EVERY isDataElement (gc_state_h1 s ++ gc_state_h2 s) /\
   (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s
     ++ gc_state_h2 s) /\
   EVERY data_to_word_memoryProof_isRef (gc_state_r1 s ++ gc_state_r2
     s ++ gc_state_r3 s ++ gc_state_r4 s) ==>
   EVERY isDataElement (gc_state_h1 s1 ++ gc_state_h2 s1) /\
   (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s1
     ++ gc_state_h2 s1) /\
   EVERY data_to_word_memoryProof_isRef (gc_state_r1 s1 ++
     gc_state_r2 s1 ++ gc_state_r3 s1 ++ gc_state_r4 s1)`,
  (* the loop moves the refs or the data and goes round again, and
     each step keeps the three invariants: the clock is the
     induction, the two theorems above are the step, and an update
     of the ok, the r2 or the r4 field leaves the heaps alone *)
  (let okf = prove
     (`!f (s:('a,'b)gc_state).
         (gc_state_h1 (gc_state_ok_fupd f s) = gc_state_h1 s) /\
         (gc_state_h2 (gc_state_ok_fupd f s) = gc_state_h2 s) /\
         (gc_state_r1 (gc_state_ok_fupd f s) = gc_state_r1 s) /\
         (gc_state_r2 (gc_state_ok_fupd f s) = gc_state_r2 s) /\
         (gc_state_r3 (gc_state_ok_fupd f s) = gc_state_r3 s) /\
         (gc_state_r4 (gc_state_ok_fupd f s) = gc_state_r4 s)`,
      REPEAT GEN_TAC THEN RECORD_CASES_TAC `s:('a,'b)gc_state`) in
    let fupds = prove
     (`!(x:(('a,'b)heap_element)list) (s:('a,'b)gc_state).
         (gc_state_h1 (gc_state_r2_fupd (K x) s) = gc_state_h1 s) /\
         (gc_state_h2 (gc_state_r2_fupd (K x) s) = gc_state_h2 s) /\
         (gc_state_r1 (gc_state_r2_fupd (K x) s) = gc_state_r1 s) /\
         (gc_state_r2 (gc_state_r2_fupd (K x) s) = x) /\
         (gc_state_r3 (gc_state_r2_fupd (K x) s) = gc_state_r3 s) /\
         (gc_state_r4 (gc_state_r2_fupd (K x) s) = gc_state_r4 s) /\
         (gc_state_h1 (gc_state_r4_fupd (K x) s) = gc_state_h1 s) /\
         (gc_state_h2 (gc_state_r4_fupd (K x) s) = gc_state_h2 s) /\
         (gc_state_r1 (gc_state_r4_fupd (K x) s) = gc_state_r1 s) /\
         (gc_state_r2 (gc_state_r4_fupd (K x) s) = gc_state_r2 s) /\
         (gc_state_r3 (gc_state_r4_fupd (K x) s) = gc_state_r3 s) /\
         (gc_state_r4 (gc_state_r4_fupd (K x) s) = x)`,
      REPEAT GEN_TAC THEN RECORD_CASES_TAC `s:('a,'b)gc_state`) in
    let gmrd = GEN_ALL gc_move_refs_data_refs_split in
    let gmdd = GEN_ALL gc_move_data_data_refs_split in
    let refl_exists (asl,w as gl) =
      let vs,bod = strip_exists w in
      let l,r = dest_eq (hd (conjuncts bod)) in
      let i = term_match [] l r in
      MAP_EVERY EXISTS_TAC (map (instantiate i) vs) gl in
    INDUCT_TAC THEN REPEAT GEN_TAC THEN
    GEN_REWRITE_TAC (LAND_CONV o LAND_CONV o LAND_CONV)
      [gen_gc_gc_move_loop_def] THEN
    EVERY_CASE_TAC THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[NOT_SUC; ARITH_RULE `SUC n - 1 = n`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM) STRIP_ASSUME_TAC) THEN
    REWRITE_TAC[okf] THEN
    TRY(ASM_REWRITE_TAC[] THEN NO_TAC) THEN
    TRY(FIRST_X_ASSUM MATCH_MP_TAC THEN refl_exists THEN
        ASM_REWRITE_TAC[]) THEN
    TRY(MATCH_MP_TAC gmdd THEN refl_exists THEN ASM_REWRITE_TAC[]) THEN
    TRY(MATCH_MP_TAC gmrd THEN refl_exists THEN
        REWRITE_TAC[fupds] THEN
        RULE_ASSUM_TAC(REWRITE_RULE[ALL_APPEND]) THEN
        ASM_REWRITE_TAC[ALL_APPEND; ALL])));;

(* [local] *)
let gen_gc_data_refs_split = prove
 (`!cc roots heap.
   (gen_gc cc (roots,heap) = (roots1,s)) /\
   (!t r. (isRef cc (t,r) <=> isMutTag t)) ==>
   (EVERY (\x. ~(data_to_word_memoryProof_isRef x))) (gc_state_h1 s
     ++ gc_state_h2 s) /\
   EVERY isDataElement (gc_state_h1 s ++ gc_state_h2 s) /\
   EVERY data_to_word_memoryProof_isRef (gc_state_r1 s ++
     gc_state_r2 s ++ gc_state_r3 s ++ gc_state_r4 s)`,
  (* the collector starts from a state whose six heaps are empty,
     moves the roots and then runs the loop: what the move of a
     list leaves in h2 and r4 is what the loop asks of them, and
     the fields that the move does not touch are the empty ones of
     the state it started from *)
  (let rt = record_thms "gc_state" in
   (* the witnesses of a lemma about a step of the collector, which
      the equation of the goal gives *)
   let refl_exists (asl,w as gl) =
     let vs,bod = strip_exists w in
     let l,r = dest_eq (hd (conjuncts bod)) in
     let i = term_match [] l r in
     MAP_EVERY EXISTS_TAC (map (instantiate i) vs) gl in
   (* and the fields that the move of a list leaves alone, put
      back: a rewrite with the equations is slow, where the
      substitution is not *)
   let subst_imp =
     FIRST_ASSUM(fun a1 ->
       let imp = MATCH_MP gc_move_list_IMP a1 in
       MAP_EVERY (fun e -> SUBST1_TAC (SYM e))
         (filter (fun th -> is_eq(concl th)) (CONJUNCTS imp))) in
   REPEAT GEN_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
   REWRITE_TAC[gen_gc_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN PAIRARG_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[PAIR_EQ] THEN
   DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (SUBST1_TAC o SYM)) THEN
   MATCH_MP_TAC(TAUT `b /\ a /\ c ==> a /\ b /\ c`) THEN
   MATCH_MP_TAC(GEN_ALL gc_move_loop_data_refs_split) THEN
   refl_exists THEN REWRITE_TAC[] THEN subst_imp THEN
   REWRITE_TAC(empty_state_def :: rt) THEN REWRITE_TAC[APPEND] THEN
   CONJ_TAC THENL
    [FIRST_ASSUM MATCH_ACCEPT_TAC;
     MATCH_MP_TAC(GEN_ALL gc_move_list_data_refs_split) THEN
     ASM_EXISTS_TAC THEN
     ASM_REWRITE_TAC(empty_state_def :: rt) THEN REWRITE_TAC[ALL]]));;

let heap_expand_not_isRef = prove
 (`EVERY (\x. ~(data_to_word_memoryProof_isRef x)) (heap_expand n)`,
  (REWRITE_TAC[heap_expand_def] THEN COND_CASES_TAC THEN
   REWRITE_TAC[ALL; isRef_def] THEN
   MATCH_REDUCE_TAC THEN REWRITE_TAC[]));;

let reset_gens_def = cake_define
  `reset_gens conf a =
     (match data_to_word_config_gc_kind conf with
       data_to_word_Generational sizes -> GenState 0 (MAP (K a)
       sizes) | _25 -> GenState 0 [])`;;

let gen_state_ok_reset = prove
 (`heap_ok (h ++ heap_expand n ++ r) l ==>
    gen_state_ok (heap_length h) (n + heap_length h)
      (h ++ heap_expand n ++ r) (reset_gens conf (heap_length h))`,
  (* the generations that reset_gens makes all start where the first
     heap ends, and nothing of that heap points into the space that
     the expansion leaves: a pointer of a DataElement points at a
     DataElement, and what is in the expansion is an Unused *)
  (let notin = prove
    (`!(hh:((A,B)heap_element) list) rr n p.
        heap_length hh <= p /\ p < n + heap_length hh
        ==> ~(isSomeDataElement
                (heap_lookup p (hh ++ heap_expand n ++ rr)))`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND] THEN
     ASM_SIMP_TAC[ARITH_RULE `(h:num) <= p ==> ~(p < h)`;
                  gen_gc_heap_length_heap_expand] THEN
     SUBGOAL_THEN `p - heap_length (hh:((A,B)heap_element) list) < n`
       ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN `~(n = 0)` ASSUME_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[heap_expand_def] THEN
     REWRITE_TAC[heap_lookup_def; el_length_def] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[isSomeDataElement_def;
                     injectivity "option"; distinctness "option";
                     distinctness "heap_element"] THEN
     ASM_SIMP_TAC[ARITH_RULE
       `p - h < n /\ ~(n = 0) ==> p - h < (n - 1) + 1`] THEN
     REWRITE_TAC[isSomeDataElement_def; distinctness "option"]) in
   STRIP_TAC THEN
   REWRITE_TAC[reset_gens_def] THEN
   STRUCT_CASES_TAC (ISPEC `data_to_word_config_gc_kind conf`
     (cases "gc_kind")) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[gen_state_ok_def; ALL] THEN
   REWRITE_TAC[GSYM ALL_MEM; MEM_MAP; K_DEF] THEN
   REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[LE_REFL] THEN
   REWRITE_TAC[gen_start_ok_def] THEN
   ONCE_REWRITE_TAC[heap_split_APPEND_if] THEN
   REWRITE_TAC[LT_REFL; SUB_REFL; heap_split_0] THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[APPEND_NIL] THEN
   W(fun (asl,w) ->
     let bod = snd(strip_exists w) in
     let pr = rand(lhs(lhand bod)) in
     let a,b = dest_pair pr in
     MAP_EVERY EXISTS_TAC [a; b]) THEN
   REWRITE_TAC[] THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   MATCH_MP_TAC(TAUT `(~a /\ ~b ==> F) ==> a \/ b`) THEN
   STRIP_TAC THEN
   W(fun (asl,w) ->
     let ths = map snd asl in
     let hd_is n th =
       (try fst(dest_const(fst(strip_comb(concl th)))) = n
        with Failure _ -> false) in
     let arg_is n th =
       (try fst(dest_const(fst(strip_comb(
              el 0 (snd(strip_comb(concl th))))))) = n
        with Failure _ -> false) in
     let okth = find (hd_is "heap_ok") ths in
     let memd = find (fun th ->
       hd_is "MEM" th && arg_is "DataElement" th)
                  ths in
     let memp = find (fun th -> hd_is "MEM" th &&
                                arg_is "gc_shared_Pointer" th) ths in
     let dargs = snd(strip_comb(el 0 (snd(strip_comb(concl memd))))) in
     let pargs = snd(strip_comb(el 0 (snd(strip_comb(concl memp))))) in
     let cl = CONJUNCT2(CONJUNCT2
       (REWRITE_RULE[heap_ok_def] okth)) in
     MP_TAC(SPECL (dargs @ pargs) cl)) THEN
   ASM_REWRITE_TAC[MEM_APPEND] THEN
   DISCH_TAC THEN
   W(fun (asl,w) ->
     let ths = map snd asl in
     let hd_is n th =
       (try fst(dest_const(fst(strip_comb(concl th)))) = n
        with Failure _ -> false) in
     let sde = find (hd_is "isSomeDataElement") ths in
     let heap = rand(el 0 (snd(strip_comb(concl sde)))) in
     let hh = lhand heap in
     let rr = rand(rand heap) in
     MP_TAC(ISPECL [hh; rr] notin)) THEN
   ASM_SIMP_TAC[] THEN
   DISCH_THEN(fun th -> MP_TAC(SPEC_ALL th)) THEN
   ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC));;

(* gen_gc_thm *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let data_to_word_memoryProof_gen_gc_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,heap,be,a,sp,sp1,gens) limit ts
  ==>
      (?roots2 state2.
        (gen_gc (make_gc_conf limit) (roots,heap) =
          (roots2,state2)) /\
        abs_ml_inv conf stack refs
          (roots2,gc_state_h1 state2 ++ heap_expand (gc_state_n
            state2) ++ gc_state_r1 state2,be,gc_state_a
           state2,gc_state_n state2,0,reset_gens conf (gc_state_a
             state2)) limit ts /\ gc_state_ok state2 /\
        (heap_length (gc_state_h1 state2 ++ gc_state_r1 state2) =
         heap_length (heap_filter (reachable_addresses roots heap)
           heap)) /\
        EVERY isDataElement (gc_state_h1 state2) /\
        EVERY isDataElement (gc_state_r1 state2) /\
        all_reachable_from_roots roots2
          (gc_state_h1 state2 ++ heap_expand (gc_state_n state2)
            ++ gc_state_r1 state2))`),
  (* the same shape as full_gc_thm, with gen_gc_related and
     gen_gc_ok in place of the two of the full collection, and two
     things more: what the collection left in the heaps of its
     state (gen_gc_data_refs_split -- data that is no reference
     below the space, references above it), which is what the
     split of the kind of the collection asks for, and the
     generations that reset_gens makes, which all start where the
     first heap ends (gen_state_ok_reset) *)
  ((* the values of a list are related to themselves by a reflexive
      relation *)
   let all2_refl = prove
    (`!(R:A->A->bool) l. (!x. R x x) ==> ALL2 R l l`,
     GEN_TAC THEN LIST_INDUCT_TAC THEN ASM_SIMP_TAC[ALL2]) in
   (* the limit of the configuration that the collection is run
      with, and what it calls a reference *)
   let limit_make_gc_conf = prove
    (`gen_gc_conf_limit (make_gc_conf l) = l`,
     REWRITE_TAC (make_gc_conf_def :: record_thms "gen_gc_conf")) in
   STRIP_TAC THEN
   (* what the invariant says of the stack *)
   FIRST_ASSUM (fun inv ->
     if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def] inv)) THEN
   (* the heap is good for the configuration that the collection is
      run with *)
   W(fun (asl,w as gl) ->
     let ho = the_asm (hd_is "heap_ok") gl in
     let cc = find_term (hd_is "make_gc_conf") w in
     SUBGOAL_THEN (list_mk_icomb "heap_ok"
         [el 0 (snd (strip_comb (concl ho)));
          list_mk_icomb "gen_gc_conf_limit" [cc]]) ASSUME_TAC THENL
      [REWRITE_TAC[limit_make_gc_conf] THEN ACCEPT_TAC ho;
       ALL_TAC]) THEN
   (* what the collection leaves: the state it wrote, the map of
      the addresses it moved, and that both are good *)
   W(fun gl ->
     let ro = the_asm (hd_is "roots_ok") gl in
     let ho = the_asm (fun c -> hd_is "heap_ok" c &&
                hd_is "gen_gc_conf_limit"
                  (el 1 (snd (strip_comb c)))) gl in
     STRIP_ASSUME_TAC (MATCH_MP gen_gc_related (CONJ ro ho)) THEN
     STRIP_ASSUME_TAC (MATCH_MP gen_gc_ok (CONJ ro ho))) THEN
   (* the two say it of one collection, so its value is one *)
   W(fun gl ->
     let eqs = mapfilter (fun (_,th) ->
                 let c = concl th in
                 if is_eq c && hd_is "gen_gc" (lhand c)
                 then th else fail()) (fst gl) in
     let e0 = hd eqs in
     MAP_EVERY (fun e ->
       if e = e0 then ALL_TAC else
       STRIP_ASSUME_TAC (REWRITE_RULE[e0; PAIR_EQ] e)) (tl eqs)) THEN
   REPEAT (FIRST_X_ASSUM (fun th ->
     let c = concl th in
     if is_eq c && is_var (lhand c) then SUBST_ALL_TAC th
     else if is_eq c && is_var (rand c) then SUBST_ALL_TAC (SYM th)
     else fail())) THEN
   (* what the collection left in the heaps of the state: data that
      is no reference below the space, references above it *)
   W(fun gl ->
     let e0 = the_asm (fun c -> is_eq c &&
                hd_is "gen_gc" (lhand c)) gl in
     let cc = el 0 (snd (strip_comb (lhand (concl e0)))) in
     (* what the configuration calls a reference, at the type of
        the collection that was run (entry 64) *)
     let tys = snd (dest_type
                 (hd (snd (dest_type (type_of cc))))) in
     let tv = genvar (el 0 tys) and rv = genvar (el 1 tys) in
     SUBGOAL_THEN (list_mk_forall([tv; rv], mk_eq (
         list_mk_icomb "gen_gc_conf_isRef" [cc; mk_pair (tv, rv)],
         list_mk_icomb "isMutTag" [tv])))
       (fun ir -> STRIP_ASSUME_TAC
          (MATCH_MP (GEN_ALL gen_gc_data_refs_split)
             (CONJ e0 ir))) THENL
      [REWRITE_TAC (make_gc_conf_def ::
                    record_thms "gen_gc_conf") THEN
       REWRITE_TAC[o_THM; FST];
       ALL_TAC]) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[ALL_APPEND]) THEN
   SPLIT_ASM_TAC THEN
   (* the witnesses: what the collection returned *)
   W(fun gl ->
     let e0 = the_asm (fun c -> is_eq c &&
                hd_is "gen_gc" (lhand c)) gl in
     let ps = tparts (rand (concl e0)) in
     MAP_EVERY EXISTS_TAC [el 0 ps; el 1 ps]) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the length of the heaps it wrote is the length of what the
      roots reach *)
   TRY (SOLVED
         (W(fun gl ->
            let hl = the_asm (fun c -> is_eq c &&
                       hd_is "heap_length" (lhand c) &&
                       hd_is "heap_length" (rand c)) gl in
            let fd = the_asm (fun c -> is_eq c &&
                       hd_is "FDOM" (lhand c)) gl in
            ACCEPT_TAC (REWRITE_RULE[fd] hl)))) THEN
   (* the heap it wrote is reachable from the roots it returned *)
   TRY (SOLVED
         (MATCH_MP_TAC (GEN_ALL IMP_all_reachable_from_roots) THEN
          W(fun gl ->
            let fd = the_asm (fun c -> is_eq c &&
                       hd_is "FDOM" (lhand c)) gl in
            EXISTS_TAC (el 1 (snd (strip_comb
              (rand (concl fd)))))) THEN
          ASM_REWRITE_TAC[])) THEN
   (* and the invariant of the heap it wrote *)
   REWRITE_TAC[abs_ml_inv_def] THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the heap is good, for the limit of the invariant *)
   TRY (SOLVED
         (W(fun gl ->
            let ho = the_asm (fun c -> hd_is "heap_ok" c &&
                       hd_is "gen_gc_conf_limit"
                         (el 1 (snd (strip_comb c)))) gl in
            ACCEPT_TAC (REWRITE_RULE[limit_make_gc_conf] ho)))) THEN
   (* the kind of the collection: the generations that reset_gens
      makes are good (gen_state_ok_reset), and the split at the end
      of the space has the data below it and the references above *)
   TRY (SOLVED
         (REWRITE_TAC[gc_kind_inv_def] THEN
          W(fun (asl,w) ->
            CASES_ON_TAC (find_term
              (hd_is "data_to_word_config_gc_kind") w)) THEN
          MATCH_REDUCE_TAC THEN
          TRY (SOLVED (REWRITE_TAC[])) THEN
          CONJ_TAC THENL
           [(* the state of the generations: the ones that
                reset_gens makes all start where the first heap
                ends, which is where the collection got to *)
            W(fun (asl,w as gl) ->
              let hla = the_asm (fun c -> is_eq c &&
                          hd_is "gc_state_a" (lhand c)) gl in
              ONCE_REWRITE_TAC[hla]) THEN
            W(fun (asl,w as gl) ->
              let ho = the_asm (fun c -> hd_is "heap_ok" c &&
                         hd_is "APPEND"
                           (el 0 (snd (strip_comb c)))) gl in
              (* the configuration is not fixed by the heap, so
                 the quantifier that MATCH_MP leaves is stripped *)
              let th = SPEC_ALL
                         (MATCH_MP (GEN_ALL gen_state_ok_reset)
                            ho) in
              let addr = el 1 (snd (strip_comb w)) in
              let addr2 = el 1 (snd (strip_comb (concl th))) in
              SUBGOAL_THEN (mk_eq (addr, addr2)) SUBST1_TAC THENL
               [ARITH_TAC; MATCH_ACCEPT_TAC th]);
            ALL_TAC] THEN
          (* the split of the heap it wrote *)
          W(fun (asl,w as gl) ->
            let hla = the_asm (fun c -> is_eq c &&
                        hd_is "gc_state_a" (lhand c)) gl in
            let hp = el 1 (snd (strip_comb
                       (lhand (hd (conjuncts
                          (snd (strip_exists w))))))) in
            let h1 = lhand hp in
            let hx = lhand (rand hp) in
            let r1 = rand (rand hp) in
            let pre = list_mk_icomb "APPEND" [h1; hx] in
            EXISTS_TAC pre THEN EXISTS_TAC r1 THEN
            REPEAT CONJ_TAC THENL
             [SUBGOAL_THEN (mk_eq (hp,
                  list_mk_icomb "APPEND" [pre; r1]))
                (fun e -> ONCE_REWRITE_TAC[e]) THENL
               [REWRITE_TAC[APPEND_ASSOC]; ALL_TAC] THEN
              SUBGOAL_THEN (mk_eq (el 0 (snd (strip_comb
                  (lhand (hd (conjuncts (snd (strip_exists w))))))),
                  list_mk_icomb "heap_length" [pre]))
                (fun e -> ONCE_REWRITE_TAC[e]) THENL
               [REWRITE_TAC[heap_length_APPEND;
                            heap_length_heap_expand; hla] THEN
                ARITH_TAC;
                ALL_TAC] THEN
              MATCH_ACCEPT_TAC heap_split_length;
              REWRITE_TAC[ALL_APPEND] THEN
              CONJ_TAC THEN
              TRY (SOLVED (MATCH_ACCEPT_TAC heap_expand_not_isRef)) THEN
              FIRST_ASSUM ACCEPT_TAC;
              FIRST_ASSUM ACCEPT_TAC]))) THEN
   (* the space that is left is the expansion in the middle of the
      heap, and the heap holds data up to it *)
   TRY (SOLVED
         (W(fun gl ->
            let hla = the_asm (fun c -> is_eq c &&
                        hd_is "gc_state_a" (lhand c)) gl in
            let dl = the_asm (fun c -> hd_is "ALL" c &&
                       hd_is "isDataElement"
                         (el 0 (snd (strip_comb c))) &&
                       hd_is "gc_state_h1"
                         (el 1 (snd (strip_comb c)))) gl in
            REWRITE_TAC[unused_space_inv_def; ADD_CLAUSES] THEN
            ONCE_REWRITE_TAC[hla] THEN
            REPEAT CONJ_TAC THEN
            TRY (SOLVED
                  (DISCH_TAC THEN
                   REWRITE_TAC[heap_lookup_APPEND; LT_REFL;
                               SUB_REFL;
                               heap_length_heap_expand] THEN
                   COND_CASES_TAC THEN
                   TRY (SOLVED (ASM_ARITH_TAC)) THEN
                   ASM_REWRITE_TAC[heap_expand_def;
                                   heap_lookup_def])) THEN
            TRY (SOLVED
                  (REWRITE_TAC[heap_length_APPEND;
                               heap_length_heap_expand] THEN
                   ARITH_TAC)) THEN
            REWRITE_TAC[data_up_to_APPEND] THEN
            ACCEPT_TAC dl))) THEN
   (* the stack and the references: the inlining that the relation
      of the collection allows is the identity one, so what is left
      is that the collection relates the roots and the heap *)
   MATCH_MP_TAC (GEN_ALL bc_stack_ref_inv_related) THEN
   W(fun gl ->
     let bsi = the_asm (hd_is "bc_stack_ref_inv") gl in
     let ps = tparts (el 4 (snd (strip_comb (concl bsi)))) in
     let gc = the_asm (hd_is "gc_related") gl in
     let fm = el 0 (snd (strip_comb (concl gc))) in
     MAP_EVERY EXISTS_TAC [fm; el 0 ps; el 1 ps]) THEN
   CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   REWRITE_TAC[gc_inline_related_def; gc_inline_def;
               gc_related_roots_heap_def] THEN
   W(fun (asl,w) ->
     let cs = conjuncts (snd (strip_exists w)) in
     EXISTS_TAC (el 1 (snd (strip_comb (el 0 cs)))) THEN
     EXISTS_TAC (el 1 (snd (strip_comb (el 1 cs))))) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED
         (MATCH_MP_TAC all2_refl THEN
          MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL
            (let (r,_,_) = gc_inline_rel in r))))) THEN
   TRY (SOLVED
         (MATCH_MP_TAC all2_refl THEN
          MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL
            (let (r,_,_) = gc_heap_inline_rel in r))))) THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED (REFL_TAC)) THEN
   (* and a pointer of the roots is an address that they reach *)
   REPEAT GEN_TAC THEN DISCH_TAC THEN
   W(fun gl ->
     let fd = the_asm (fun c -> is_eq c &&
                hd_is "FDOM" (lhand c)) gl in
     let m = the_asm (hd_is "MEM") gl in
     REWRITE_TAC[fd; IN; reachable_addresses_def] THEN
     EXISTS_TAC (rand (el 0 (snd (strip_comb (concl m))))) THEN
     EXISTS_TAC (lhand (el 0 (snd (strip_comb (concl m))))) THEN
     CONJ_TAC THENL
      [ACCEPT_TAC m;
       MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL RTC_RULES))])));;

let has_gen_def = cake_define
  `has_gen (GenState _26 xs) <=> ~(xs = [])`;;

let heap_split_heap_split = prove
 (`!heap n1 n2 h1 h2 h3 h4.
      heap_split n2 heap = SOME (h3,h4) /\
      heap_split n1 heap = SOME (h1,h2) /\ n1 <= n2 ==>
      (?m.
        h2 = m ++ h4 /\ h3 = h1 ++ m /\ heap = h1 ++ m ++ h4 /\
        heap_split (n2 - heap_length h1) h2 = SOME (m,h4))`,
  (* the split at the later point goes through the earlier one: the
     middle piece is what the split of the second half gives, and
     the induction follows the two splits down the heap, one element
     at a time *)
  (let exwit = W(fun (asl,w) ->
     EXISTS_TAC (lhs (el 1 (conjuncts (snd(strip_exists w)))))) in
   let stripconj =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) in
   let aux = prove
    (`!(heap:((A,B)heap_element) list) n1 n2 h1 h2 h3 h4.
        heap_split n2 heap = SOME (h3,h4) /\
        heap_split n1 heap = SOME (h1,h2) /\ n1 <= n2
        ==> ?m. h2 = m ++ h4 /\ h3 = h1 ++ m /\
                heap = h1 ++ m ++ h4 /\
                heap_split (n2 - heap_length h1) h2 = SOME (m,h4)`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[heap_split_def] THENL
      [ASM_CASES_TAC `n2 = 0` THEN
       ASM_REWRITE_TAC[distinctness "option"] THEN
       ASM_CASES_TAC `n1 = 0` THEN
       ASM_REWRITE_TAC[distinctness "option"] THEN
       REWRITE_TAC[injectivity "option"; PAIR_EQ] THEN
       STRIP_TAC THEN VAR_EQ_TAC THEN
       EXISTS_TAC `[]:((A,B)heap_element) list` THEN
       REWRITE_TAC[APPEND; heap_length_NIL; SUB_0] THEN
       ASM_REWRITE_TAC[heap_split_def];
       ALL_TAC] THEN
     ASM_CASES_TAC `n2 = 0` THEN
     ASM_REWRITE_TAC[distinctness "option"] THENL
      [STRIP_TAC THEN
       SUBGOAL_THEN `n1 = 0` SUBST_ALL_TAC THENL
        [ASM_ARITH_TAC; ALL_TAC] THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option"; PAIR_EQ]) THEN
       stripconj THEN VAR_EQ_TAC THEN
       EXISTS_TAC `[]:((A,B)heap_element) list` THEN
       REWRITE_TAC[APPEND; heap_length_NIL; SUB_0;
                   heap_split_def];
       ALL_TAC] THEN
     ASM_CASES_TAC `n2 < el_length (h:(A,B)heap_element)` THEN
     ASM_REWRITE_TAC[distinctness "option"] THEN
     ASM_CASES_TAC `n1 = 0` THEN ASM_REWRITE_TAC[] THENL
      [EVERY_CASE_TAC THEN
       REWRITE_TAC[distinctness "option"; injectivity "option";
                   PAIR_EQ] THEN
       STRIP_TAC THEN stripconj THEN VAR_EQ_TAC THEN
       REWRITE_TAC[APPEND; heap_length_NIL; SUB_0] THEN
       exwit THEN
       FIRST_X_ASSUM(fun ih ->
         FIRST_ASSUM(fun a1 ->
           MP_TAC(MATCH_MP ih (CONJ a1 (CONJ
             (ISPEC `t:((A,B)heap_element) list`
                (GEN_ALL heap_split_0))
             (SPEC `n2 - el_length (h:(A,B)heap_element)`
                LE_0)))))) THEN
       REWRITE_TAC[APPEND] THEN
       DISCH_THEN(X_CHOOSE_THEN `mm:((A,B)heap_element) list`
         STRIP_ASSUME_TAC) THEN
       VAR_EQ_TAC THEN
       ASM_REWRITE_TAC[APPEND; CONS_11; heap_split_def] THEN
       MATCH_REDUCE_TAC THEN REWRITE_TAC[];
       ALL_TAC] THEN
     ASM_CASES_TAC `n1 < el_length (h:(A,B)heap_element)` THEN
     ASM_REWRITE_TAC[distinctness "option"] THEN
     EVERY_CASE_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option";
                 PAIR_EQ] THEN
     STRIP_TAC THEN stripconj THEN VAR_EQ_TAC THEN
     SUBGOAL_THEN `n1 - el_length (h:(A,B)heap_element) <=
                   n2 - el_length (h:(A,B)heap_element)`
       ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     FIRST_X_ASSUM(fun ih ->
       FIRST_ASSUM(fun a1 -> FIRST_ASSUM(fun a2 -> FIRST_ASSUM(fun a3 ->
         MP_TAC(MATCH_MP ih (CONJ a1 (CONJ a2 a3))) THEN
         DISCH_THEN(X_CHOOSE_THEN `mm:((A,B)heap_element) list`
           STRIP_ASSUME_TAC) THEN
         VAR_EQ_TAC THEN
         EXISTS_TAC `mm:((A,B)heap_element) list` THEN
         ASM_REWRITE_TAC[APPEND; CONS_11;
                         heap_length_CONS] THEN
         REWRITE_TAC[ARITH_RULE `a - (b + c) = (a - b) - c`] THEN
         ASM_REWRITE_TAC[]))))) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let heap_split_LESS_EQ = prove
 (`!heap n x. heap_split n heap = SOME x ==> n <= heap_length heap`,
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[heap_split_def; heap_length_NIL;
               heap_length_CONS] THEN
   EVERY_CASE_TAC THEN REPEAT COND_CASES_TAC THEN
   ASM_REWRITE_TAC[distinctness "option"; LE_0] THEN
   DISCH_TAC THEN USE_IH THEN ASM_ARITH_TAC));;

(* [local] *)
let isRef_heap_expand = prove
 (`!x. EVERY (\x. ~(data_to_word_memoryProof_isRef x)) (heap_expand x)`,
  (GEN_TAC THEN REWRITE_TAC[heap_expand_def] THEN
   COND_CASES_TAC THEN
   REWRITE_TAC[ALL; isRef_def] THEN
   MATCH_REDUCE_TAC THEN REWRITE_TAC[]));;

(* the port's own: what the theorem about the partial collection
   goes by.  The configuration it is run with is make_partial_conf
   of the generations, so its fields are read off once
   (pconf_fields); what the invariant of the generation says of the
   heap is heap_gen_ok of the collection's own theory, and the
   thirty lines of HOL4 that derive it are heap_gen_ok_inv, with
   the pieces of a split (split_EVERY, ref_part) and the elements
   of a list of references (isRef_EVERY_data, ref_EVERY_d) beside
   it; and what the collection copied holds a reference only where
   what it copied from does (similar_isRef) *)

let pconf_fields = prove
 (`(gen_gc_partial_conf_limit
     (make_partial_conf (make_gc_conf l) (GenState u ss) rs) = l) /\
  (gen_gc_partial_conf_gen_start
     (make_partial_conf (make_gc_conf l) (GenState u ss) rs)
       = HD ss) /\
  (gen_gc_partial_conf_refs_start
     (make_partial_conf (make_gc_conf l) (GenState u ss) rs) = rs) /\
  (!tag qs. gen_gc_partial_conf_isRef
     (make_partial_conf (make_gc_conf l) (GenState u ss) rs)
       (tag,qs) <=> isMutTag tag)`,
  (   REWRITE_TAC (make_partial_conf_def :: make_gc_conf_def ::
                record_thms "gen_gc_partial_conf" @
                record_thms "gen_gc_conf") THEN
   REWRITE_TAC[o_THM; FST]));;

let isRef_isDataElement = prove
 (`!x. data_to_word_memoryProof_isRef x ==> isDataElement x`,
  (   GEN_TAC THEN CASES_ON_NAME "x" THEN
   REWRITE_TAC[isRef_def] THEN SAFE_MATCH_REDUCE_TAC THEN
   REWRITE_TAC[isDataElement_def] THEN
   TRY (SOLVED (MESON_TAC[])) THEN
   REWRITE_TAC[]));;

let isRef_EVERY_data = prove
 (`!l. EVERY data_to_word_memoryProof_isRef l
      ==> EVERY isDataElement l`,
  (   LIST_INDUCT_TAC THEN REWRITE_TAC[ALL] THEN
   ASM_MESON_TAC[isRef_isDataElement]));;

let split_EVERY = prove
 (`!heap n1 n2 h1 h2 g1 g2 P.
    heap_split n1 heap = SOME (h1,h2) /\
    heap_split n2 heap = SOME (g1,g2) /\ n1 <= n2 /\ EVERY P g1
    ==> EVERY P h1`,
  (   REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM (fun le ->
     if not (is_binop `(<=):num->num->bool` (concl le)) then fail()
     else
     W(fun gl ->
       let s1 = the_asm (fun c -> is_eq c &&
                  hd_is "heap_split" (lhand c) &&
                  el 0 (snd (strip_comb (lhand c)))
                    = lhand (concl le)) gl in
       let s2 = the_asm (fun c -> is_eq c &&
                  hd_is "heap_split" (lhand c) &&
                  el 0 (snd (strip_comb (lhand c)))
                    = rand (concl le)) gl in
       STRIP_ASSUME_TAC (MATCH_MP heap_split_heap_split
         (CONJ s2 (CONJ s1 le))))) THEN
   REPEAT (FIRST_X_ASSUM (fun th ->
     let c = concl th in
     if is_eq c && is_var (lhand c) &&
        not (vfree_in (lhand c) (rand c))
     then SUBST_ALL_TAC th else fail())) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[ALL_APPEND]) THEN
   SPLIT_ASM_TAC THEN
   FIRST_ASSUM ACCEPT_TAC));;

let ref_part = prove
 (`(EVERY (\x. ~(data_to_word_memoryProof_isRef x)) l1
   ==> (!xs n tag qs. MEM (DataElement xs n (tag,qs)) l1
        ==> ~(gen_gc_partial_conf_isRef
                (make_partial_conf (make_gc_conf l)
                   (GenState u ss) rs) (tag,qs)))) /\
  (EVERY data_to_word_memoryProof_isRef l2
   ==> (!xs n tag qs. MEM (DataElement xs n (tag,qs)) l2
        ==> gen_gc_partial_conf_isRef
              (make_partial_conf (make_gc_conf l)
                 (GenState u ss) rs) (tag,qs)))`,
  (   REWRITE_TAC[GSYM ALL_MEM; pconf_fields] THEN
   CONJ_TAC THEN REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM (fun al ->
     FIRST_ASSUM (fun mm -> MP_TAC (MATCH_MP al mm))) THEN
   ONCE_REWRITE_TAC[isRef_def] THEN
   TRY SAFE_MATCH_REDUCE_TAC THEN
   REWRITE_TAC[] THEN
   (* and the direction where the strip left the reference itself
      as the goal *)
   ONCE_REWRITE_TAC[isRef_def] THEN
   TRY SAFE_MATCH_REDUCE_TAC THEN
   ASM_REWRITE_TAC[]));;

let ref_EVERY_d = prove
 (`(EVERY isDataElement l /\
   (!xs n d. MEM (DataElement xs n d) l
    ==> ~(gen_gc_partial_conf_isRef
            (make_partial_conf (make_gc_conf lm) (GenState u ss) rs)
            d))
   ==> EVERY (\x. ~(data_to_word_memoryProof_isRef x)) l) /\
  (EVERY isDataElement l /\
   (!xs n d. MEM (DataElement xs n d) l
    ==> gen_gc_partial_conf_isRef
          (make_partial_conf (make_gc_conf lm) (GenState u ss) rs)
          d)
   ==> EVERY data_to_word_memoryProof_isRef l)`,
  (   REWRITE_TAC[GSYM ALL_MEM] THEN
   CONJ_TAC THEN REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM (fun dl ->
     FIRST_ASSUM (fun mm ->
       STRIP_ASSUME_TAC
         (REWRITE_RULE[isDataElement_def] (MATCH_MP dl mm)))) THEN
   VAR_EQ_TAC THEN
   (* the data of the element, which both tests look into *)
   W(fun (asl,w as gl) ->
     let de = in_goal gl (fun t -> hd_is "DataElement" t &&
                (try let a = el 2 (snd (strip_comb t)) in
                     is_var a && prod_type (type_of a)
                 with Failure _ -> false)) in
     CASES_ON_TAC (el 2 (snd (strip_comb de)))) THEN
   VAR_EQ_TAC THEN
   RULE_ASSUM_TRY (fun th ->
     if hd_is "data_to_word_memoryProof_isRef" (concl th)
     then CONV_RULE (REDEPTH_CONV safe_match_conv)
            (ONCE_REWRITE_RULE[isRef_def] th) else fail()) THEN
   ONCE_REWRITE_TAC[isRef_def] THEN
   TRY SAFE_MATCH_REDUCE_TAC THEN
   RULE_ASSUM_TRY (REWRITE_RULE[pconf_fields]) THEN
   TRY (SOLVED CONTRA_TAC) THEN
   TRY (SOLVED
     (FIRST_X_ASSUM MATCH_MP_TAC THEN
      W(fun (asl,w as gl) ->
        let mm = the_asm (hd_is "MEM") gl in
        let args = snd (strip_comb
                     (el 0 (snd (strip_comb (concl mm))))) in
        MAP_EVERY EXISTS_TAC [el 0 args; el 1 args] THEN
        ACCEPT_TAC mm))) THEN
   W(fun gl ->
     let imp = the_asm (fun c -> is_forall c &&
                 can (find_term (hd_is
                   "gen_gc_partial_conf_isRef")) c) gl in
     let mm = the_asm (hd_is "MEM") gl in
     ASSUME_TAC (MATCH_MP (SPEC_ALL imp) mm)) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[pconf_fields]) THEN
   TRY (SOLVED CONTRA_TAC) THEN
   ASM_REWRITE_TAC[]));;

let similar_isRef = prove
 (`!l1 l2. EVERY2 (similar_data c) l1 l2 /\
          EVERY data_to_word_memoryProof_isRef l1
          ==> EVERY data_to_word_memoryProof_isRef l2`,
  (   LIST_INDUCT_TAC THEN GEN_TAC THEN
   CASES_ON_NAME "l2" THEN
   REWRITE_TAC[ALL2; ALL] THEN
   TRY (SOLVED (REWRITE_TAC[])) THEN
   REPEAT STRIP_TAC THEN
   (* the rest of the list, by the hypothesis *)
   TRY (SOLVED
     (W(fun gl ->
        let ih = the_asm (fun c -> is_forall c &&
                   can (find_term (hd_is "ALL2")) c) gl in
        MATCH_MP_TAC ih) THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC)) THEN
   (* and its first element: of two data elements the data is the
      same, and nothing else is a reference *)
   W(fun gl -> CASES_ON_TAC (var_by_name "h" gl)) THEN
   W(fun (asl,w as gl) ->
     let sd = the_asm (hd_is "similar_data") gl in
     CASES_ON_TAC (el 2 (snd (strip_comb (concl sd))))) THEN
   (* and the data of a data element, which the test looks into *)
   TRY (W(fun (asl,w as gl) ->
     let de = in_goal gl (fun t -> hd_is "DataElement" t &&
                (try let a = el 2 (snd (strip_comb t)) in
                     is_var a && prod_type (type_of a)
                 with Failure _ -> false)) in
     CASES_ON_TAC (el 2 (snd (strip_comb de))))) THEN
   (* the equations that the splits left, used up *)
   VAR_EQ_TAC THEN
   RULE_ASSUM_TRY (fun th ->
     if hd_is "similar_data" (concl th)
     then CONV_RULE (REDEPTH_CONV safe_match_conv)
            (REWRITE_RULE[similar_data_def] th) else fail()) THEN
   RULE_ASSUM_TRY (fun th ->
     if hd_is "data_to_word_memoryProof_isRef" (concl th)
     then CONV_RULE (REDEPTH_CONV safe_match_conv)
            (ONCE_REWRITE_RULE[isRef_def] th) else fail()) THEN
   ONCE_REWRITE_TAC[isRef_def] THEN
   TRY SAFE_MATCH_REDUCE_TAC THEN
   RULE_ASSUM_TRY (REWRITE_RULE[distinctness "heap_element";
                                injectivity "heap_element"]) THEN
   SPLIT_ASM_TAC THEN
   TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
   TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
   (* the data of the element, as the split of the pair gives it *)
   W(fun (asl,w as gl) ->
     let eq = the_asm (fun c -> is_eq c && is_pair (lhand c) &&
                is_var (rand c)) gl in
     RULE_ASSUM_TRY (REWRITE_RULE[SYM eq])) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[PAIR_EQ]) THEN
   RULE_ASSUM_TRY (CONV_RULE (REDEPTH_CONV UNWIND_CONV)) THEN
   TRY SAFE_MATCH_REDUCE_ASM_TAC THEN
   RULE_ASSUM_TRY (REWRITE_RULE[]) THEN
   ASM_REWRITE_TAC[]));;

let heap_gen_ok_inv = prove
 (cake_as_vars (fun () ->
    `gc_kind_inv conf a sp sp1 gens heap /\
     unused_space_inv a (sp + sp1) heap /\
     heap_ok heap limit /\ has_gen gens /\
     data_to_word_config_gc_kind conf = data_to_word_Generational xs
     ==> heap_gen_ok heap
           (make_partial_conf (make_gc_conf limit) gens
              (a + (sp + sp1)))`),
  (   (* the split of the heap at a point, as an assumption gives it *)
   let the_split t gl =
     the_asm (fun c -> is_eq c && hd_is "heap_split" (lhand c) &&
                el 0 (snd (strip_comb (lhand c))) = t) gl in
   STRIP_TAC THEN
   (* the generations, and the start of the one that is collected *)
   W(fun gl -> CASES_ON_TAC (var_by_name "gens" gl)) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[has_gen_def]) THEN
   W(fun gl ->
     let hg = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                (try fst (dest_const (rand (rand c))) = "NIL"
                 with Failure _ -> false)) gl in
     CASES_ON_TAC (lhand (rand (concl hg)))) THEN
   (* of no generation there is nothing to collect: has_gen said
      the starts are not the empty list *)
   RULE_ASSUM_TRY (REWRITE_RULE[]) THEN
   TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
   (* what the kind of the collection says of the heap *)
   W(fun gl ->
     let ke = the_asm (fun c -> is_eq c &&
                hd_is "data_to_word_config_gc_kind" (lhand c)) gl in
     let gk = the_asm (hd_is "gc_kind_inv") gl in
     STRIP_ASSUME_TAC (CONV_RULE (REDEPTH_CONV safe_match_conv)
       (REWRITE_RULE[gc_kind_inv_def; ke] gk))) THEN
   (* the starts are below the end of the data and each of them
      splits the heap, the data goes up to the end of the space,
      and the heap is as long as the limit *)
   W(fun gl ->
     let gs = the_asm (hd_is "gen_state_ok") gl in
     STRIP_ASSUME_TAC (REWRITE_RULE[gen_state_ok_def; ALL] gs)) THEN
   FIRST_ASSUM (fun th ->
     if not (hd_is "gen_start_ok" (concl th)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[gen_start_ok_def] th)) THEN
   W(fun gl ->
     let us = the_asm (hd_is "unused_space_inv") gl in
     let ho = the_asm (hd_is "heap_ok") gl in
     (STRIP_ASSUME_TAC (REWRITE_RULE[unused_space_inv_def;
                                     data_up_to_def] us) THEN
      STRIP_ASSUME_TAC (REWRITE_RULE[heap_ok_def] ho))) THEN
   REWRITE_TAC[heap_gen_ok_def; pconf_fields; HD] THEN
   (* the split at the start of the generation goes through the
      split at the end of the space, and the middle piece is the
      generation that is collected *)
   W(fun (asl,w as gl) ->
     let c0 = hd (conjuncts (snd (strip_exists w))) in
     let st = lhand c0 and en = rand c0 in
     SUBGOAL_THEN (mk_binop `(<=):num->num->bool` st en)
       (fun le -> STRIP_ASSUME_TAC (MATCH_MP heap_split_heap_split
          (CONJ (the_split en gl)
             (CONJ (the_split st gl) le))))) THENL
    [ARITH_ASM_TAC; ALL_TAC] THEN
   (* and through the split at the end of the data, so that what
      is below the start is data *)
   W(fun (asl,w as gl) ->
     let c0 = hd (conjuncts (snd (strip_exists w))) in
     let st = lhand c0 in
     let av = var_by_name "a" gl in
     SUBGOAL_THEN (mk_binop `(<=):num->num->bool` st av)
       (fun le -> STRIP_ASSUME_TAC (MATCH_MP heap_split_heap_split
          (CONJ (the_split av gl) (CONJ (the_split st gl) le))))) THENL
    [ARITH_ASM_TAC; ALL_TAC] THEN
   (* what holds of a piece of the heap holds of its parts *)
   W(fun (asl,w as gl) ->
     let hv = var_by_name "heap" gl in
     let eqs = mapfilter (fun (_,th) ->
                 let c = concl th in
                 if is_eq c && hd_is "APPEND" (rand c) &&
                    not (lhand c = hv) then th else fail()) asl in
     RULE_ASSUM_TRY (REWRITE_RULE (ALL_APPEND :: eqs))) THEN
   SPLIT_ASM_TAC THEN
   (* what is below the start, the generation, and what is above
      the space *)
   W(fun (asl,w as gl) ->
     let c0 = hd (conjuncts (snd (strip_exists w))) in
     let st = lhand c0 and en = rand c0 in
     let p1 = rand (rand (concl (the_split st gl))) in
     let s3 = the_asm (fun c -> is_eq c &&
                hd_is "heap_split" (lhand c) &&
                el 1 (snd (strip_comb (lhand c))) = rand p1 &&
                lhand (el 0 (snd (strip_comb (lhand c)))) = en) gl in
     MAP_EVERY EXISTS_TAC
       [lhand p1; lhand (rand (rand (concl s3)));
        rand (rand (rand (concl (the_split en gl))))]) THEN
   (* what is below the start of the generation and the generation
      itself hold no reference, because what is below the end of
      the space holds none *)
   TRY (W(fun (asl,w as gl) ->
     let al = the_asm (fun c -> hd_is "ALL" c &&
                is_abs (el 0 (snd (strip_comb c)))) gl in
     let lst = el 1 (snd (strip_comb (concl al))) in
     let eq = the_asm (fun c -> is_eq c && lhand c = lst &&
                hd_is "APPEND" (rand c)) gl in
     STRIP_ASSUME_TAC
       (REWRITE_RULE[ALL_APPEND] (REWRITE_RULE[eq] al)))) THEN
   REPEAT CONJ_TAC THEN
   (* the start is below the end of the space, and the space ends
      below the limit *)
   TRY (SOLVED ARITH_ASM_TAC) THEN
   (* what is below the start is data, and what is above the space
      is data because it is references *)
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED
     (W(fun gl ->
        let ir = the_asm (fun c -> hd_is "ALL" c &&
                   hd_is "data_to_word_memoryProof_isRef"
                     (el 0 (snd (strip_comb c)))) gl in
        ACCEPT_TAC (MATCH_MP isRef_EVERY_data ir)))) THEN
   (* the pointers of what is below the start go into itself or
      into the references *)
   TRY (SOLVED (FIRST_ASSUM MATCH_ACCEPT_TAC)) THEN
   (* and what is a reference and what is not: of the piece that
      the element is in, the invariant says which *)
   TRY (REPEAT GEN_TAC THEN DISCH_TAC THEN
   W(fun (asl,w as gl) ->
     let mm = the_asm (hd_is "MEM") gl in
     let el0 = el 0 (snd (strip_comb (concl mm))) in
     CASES_ON_TAC (el 2 (snd (strip_comb el0)))) THEN
   W(fun (asl,w as gl) ->
     let mm = the_asm (hd_is "MEM") gl in
     let lst = el 1 (snd (strip_comb (concl mm))) in
     let al = the_asm (fun c -> hd_is "ALL" c &&
                el 1 (snd (strip_comb c)) = lst) gl in
     let part = if is_abs (el 0 (snd (strip_comb (concl al))))
                then CONJUNCT1 ref_part else CONJUNCT2 ref_part in
     let args = snd (strip_comb (el 0 (snd (strip_comb
                  (concl mm))))) in
     MATCH_MP_TAC (MATCH_MP part al) THEN
     MAP_EVERY EXISTS_TAC [el 0 args; el 1 args] THEN
     ACCEPT_TAC mm)) THEN
   (* the three pieces are the segment of the heap between the
      start of the generation and the end of the space *)
   (
     (CONV_TAC SYM_CONV THEN
      W(fun (asl,w as gl) ->
        let seg = snd (strip_comb (lhand w)) in
        let st = lhand (el 0 seg) and en = rand (el 0 seg) in
        let s1 = the_split st gl in
        let s3 = the_asm (fun c -> is_eq c &&
                   hd_is "heap_split" (lhand c) &&
                   el 1 (snd (strip_comb (lhand c)))
                     = rand (rand (rand (concl s1))) &&
                   lhand (el 0 (snd (strip_comb (lhand c)))) = en) gl in
        REWRITE_TAC[heap_segment_def; s1] THEN
        TRY SAFE_MATCH_REDUCE_TAC THEN
        SUBGOAL_THEN (mk_neg (mk_binop `(<):num->num->bool` en st))
          (fun nl -> REWRITE_TAC[nl]) THENL
         [ARITH_ASM_TAC; ALL_TAC] THEN
        REWRITE_TAC[s3] THEN TRY SAFE_MATCH_REDUCE_TAC THEN
        REWRITE_TAC[distinctness "option"])))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let gen_gc_partial_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,heap,be,a,sp,sp1,gens) limit ts
  /\
     has_gen gens /\ data_to_word_config_gc_kind conf =
       data_to_word_Generational xs ==>
      (?roots2 state2.
        partial_gc
          (make_partial_conf (make_gc_conf limit) gens (a + (sp +
            sp1)))
          (roots,heap) = (roots2,state2) /\
        abs_ml_inv conf stack refs
          (roots2,gc_state_old state2 ++ gc_state_h1 state2 ++
            heap_expand (gc_state_n state2) ++ gc_state_r1
            state2,be,gc_state_a
           state2,gc_state_n state2,0,reset_gens conf (gc_state_a
             state2)) limit ts /\ gc_state_ok state2)`),
  (* the third of the collection template, and the same shape as
     full_gc_thm and gen_gc_thm with the old generation in front.
     The steps above the statement (tools/overrides.py) give the
     fields of the configuration and heap_gen_ok of the heap, which
     is what partial_gc_related asks for beside roots_ok and
     heap_ok; what the collection left is then its theorem and
     partial_gc_IMP, and the five parts of the invariant are taken
     one at a time (THENL, so that each says where it broke):

     - a pointer of the roots it returned is an address of the heap
       it wrote, because it is the image of a pointer of the roots
       it was given (MEM_ADDR_MAP), that one is in the map, and the
       map goes into the addresses of the heap (gc_related);
     - the heap is good for the limit of the invariant, which is
       the limit of the configuration;
     - the generations that reset_gens makes all start where the
       heap it wrote ends (gen_state_ok_reset), and the split at
       the end of the space has the data below it and the
       references above -- what was below the generation and what
       the collection wrote hold no reference (ref_EVERY_d; a
       reference in what it wrote would be one in the generation it
       copied), the expansion holds none (isRef_heap_expand), and
       what is above the space is a reference because it was copied
       from one (similar_isRef);
     - the space that is left is the expansion between the heap it
       wrote and the references;
     - and the stack and the references go over with the inlining
       that the relation of the collection allows, which is the
       identity one (bc_stack_ref_inv_related) *)
  (let plain_heap_ok gl =
    the_asm (fun c -> hd_is "heap_ok" c &&
               not (hd_is "gen_gc_partial_conf_limit"
                      (el 1 (snd (strip_comb c))))) gl in
  STRIP_TAC THEN
  W(fun gl -> CASES_ON_TAC (var_by_name "gens" gl)) THEN
  FIRST_ASSUM (fun inv ->
    if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
    STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def] inv)) THEN
  (* the heap is good for the limit of the configuration that the
     collection is run with *)
  W(fun (asl,w as gl) ->
    let cc = find_term (hd_is "make_partial_conf") w in
    let ho = plain_heap_ok gl in
    SUBGOAL_THEN (list_mk_icomb "heap_ok"
        [el 0 (snd (strip_comb (concl ho)));
         list_mk_icomb "gen_gc_partial_conf_limit" [cc]])
      ASSUME_TAC THENL
     [REWRITE_TAC[pconf_fields] THEN ACCEPT_TAC ho; ALL_TAC]) THEN
  (* and good for the generation it collects *)
  W(fun gl ->
    let gk = the_asm (hd_is "gc_kind_inv") gl in
    let us = the_asm (hd_is "unused_space_inv") gl in
    let ho = plain_heap_ok gl in
    let hg = the_asm (hd_is "has_gen") gl in
    let ke = the_asm (fun c -> is_eq c &&
               hd_is "data_to_word_config_gc_kind" (lhand c)) gl in
    ASSUME_TAC (MATCH_MP heap_gen_ok_inv
      (end_itlist CONJ [gk; us; ho; hg; ke]))) THEN
  (* what the collection leaves: the roots it mapped, the heap it
     wrote, the map of the addresses it moved, and that both the
     heap and the state are good *)
  W(fun gl ->
    let ro = the_asm (hd_is "roots_ok") gl in
    let ho = the_asm (fun c -> hd_is "heap_ok" c &&
               hd_is "gen_gc_partial_conf_limit"
                 (el 1 (snd (strip_comb c)))) gl in
    let hg = the_asm (hd_is "heap_gen_ok") gl in
    STRIP_ASSUME_TAC (MATCH_MP partial_gc_related
      (CONJ ro (CONJ ho hg)))) THEN
  (* and what it says of the lengths it wrote *)
  W(fun gl ->
    let pg = the_asm (fun c -> is_eq c &&
               hd_is "partial_gc" (lhand c)) gl in
    let ok = the_asm (hd_is "gc_state_ok") gl in
    STRIP_ASSUME_TAC (MATCH_MP
      (GEN_ALL gen_gc_partial_partial_gc_IMP) (CONJ pg ok))) THEN
  (* what the collection left below the generation is what was
     there: the segment of the heap that it names is the segment
     that heap_gen_ok names *)
  W(fun gl ->
    let hg = the_asm (hd_is "heap_gen_ok") gl in
    STRIP_ASSUME_TAC (REWRITE_RULE[heap_gen_ok_def] hg)) THEN
  W(fun gl ->
    let s1 = the_asm (fun c -> is_eq c &&
               hd_is "heap_segment" (rand c)) gl in
    let s2 = the_asm (fun c -> is_eq c &&
               hd_is "heap_segment" (lhand c)) gl in
    STRIP_ASSUME_TAC (REWRITE_RULE[injectivity "option"; PAIR_EQ]
      (TRANS s1 s2))) THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    let c = concl th in
    if is_eq c && is_var (lhand c) &&
       not (vfree_in (lhand c) (rand c))
    then SUBST_ALL_TAC th else fail())) THEN
  (* the witnesses: what the collection returned *)
  W(fun gl ->
    let e0 = the_asm (fun c -> is_eq c &&
               hd_is "partial_gc" (lhand c)) gl in
    let ps = tparts (rand (concl e0)) in
    MAP_EVERY EXISTS_TAC [el 0 ps; el 1 ps]) THEN
  REPEAT CONJ_TAC THENL
   [(* its value *)
    FIRST_ASSUM ACCEPT_TAC;
    (* the invariant of the heap it wrote *)
    REWRITE_TAC[abs_ml_inv_def] THEN REPEAT CONJ_TAC THENL
     [(* a pointer of the roots it returned is an address of the heap
     it wrote: it is the image of a pointer of the roots it was
     given (MEM_ADDR_MAP), that one is in the map (the condition
     of the collection) and the map goes into the addresses of the
     heap it wrote (gc_related) *)
  (REWRITE_TAC[roots_ok_def] THEN REPEAT GEN_TAC THEN
     DISCH_THEN (fun mm ->
       STRIP_ASSUME_TAC (MATCH_MP MEM_ADDR_MAP mm)) THEN
     W(fun gl ->
       let fd = the_asm (fun c -> is_forall c &&
                  can (find_term (hd_is "FDOM")) c &&
                  can (find_term (hd_is "MEM")) c) gl in
       let gr = the_asm (hd_is "gc_related") gl in
       let mm = the_asm (hd_is "MEM") gl in
       let inn = MATCH_MP (SPEC_ALL fd) mm in
       let inj = REWRITE_RULE[INJ; IN_ELIM_THM]
                   (CONJUNCT1 (REWRITE_RULE[gc_related_def] gr)) in
       MP_TAC (MATCH_MP (CONJUNCT1 inj) inn)) THEN
     ASM_REWRITE_TAC[])
      ;
  (* the heap is good, for the limit of the invariant *)
    (W(fun gl ->
       let ho = the_asm (fun c -> hd_is "heap_ok" c &&
                  hd_is "APPEND" (el 0 (snd (strip_comb c)))) gl in
       ACCEPT_TAC (REWRITE_RULE[pconf_fields] ho)))
      ;
  (* the kind of the collection: the generations that reset_gens
     makes all start where the heap it wrote ends, and the split
     at the end of the space has the data below it and the
     references above *)
  (W(fun (asl,w as gl) ->
     let av = el 1 (snd (strip_comb w)) in
     let hp = el 5 (snd (strip_comb w)) in
     SUBGOAL_THEN (mk_eq (av,
         list_mk_icomb "heap_length"
           [list_mk_icomb "APPEND"
              [lhand hp; lhand (rand hp)]])) SUBST1_TAC THENL
      [REWRITE_TAC[heap_length_APPEND] THEN ASM_ARITH_TAC;
       ALL_TAC]) THEN
   ONCE_REWRITE_TAC[APPEND_ASSOC] THEN
   REWRITE_TAC[gc_kind_inv_def] THEN
   W(fun gl ->
     let ke = the_asm (fun c -> is_eq c &&
                hd_is "data_to_word_config_gc_kind" (lhand c)) gl in
     REWRITE_TAC[ke]) THEN
   TRY SAFE_MATCH_REDUCE_TAC THEN
   CONJ_TAC THENL
    [(* the generations that reset_gens makes *)
     W(fun (asl,w as gl) ->
       let ho = the_asm (fun c -> hd_is "heap_ok" c &&
                  hd_is "APPEND" (el 0 (snd (strip_comb c)))) gl in
       let th = SPEC_ALL (MATCH_MP (GEN_ALL gen_state_ok_reset)
                  (ONCE_REWRITE_RULE[APPEND_ASSOC] ho)) in
       let addr = el 1 (snd (strip_comb w)) in
       let addr2 = el 1 (snd (strip_comb (concl th))) in
       SUBGOAL_THEN (mk_eq (addr, addr2)) SUBST1_TAC THENL
        [ARITH_TAC; MATCH_ACCEPT_TAC th]);
     (* and the split at the end of the space *)
     W(fun (asl,w as gl) ->
       let c0 = hd (conjuncts (snd (strip_exists w))) in
       let hp = el 1 (snd (strip_comb (lhand c0))) in
       let pre = list_mk_icomb "APPEND"
                   [lhand hp; lhand (rand hp)] in
       let r1 = rand (rand hp) in
       EXISTS_TAC pre THEN EXISTS_TAC r1 THEN
       REPEAT CONJ_TAC THENL
        [SUBGOAL_THEN (mk_eq (hp,
             list_mk_icomb "APPEND" [pre; r1]))
           (fun e -> ONCE_REWRITE_TAC[e]) THENL
          [REWRITE_TAC[APPEND_ASSOC]; ALL_TAC] THEN
         SUBGOAL_THEN (mk_eq (el 0 (snd (strip_comb (lhand c0))),
             list_mk_icomb "heap_length" [pre]))
           (fun e -> ONCE_REWRITE_TAC[e]) THENL
          [REWRITE_TAC[heap_length_APPEND;
                       heap_length_heap_expand] THEN ARITH_TAC;
           ALL_TAC] THEN
         MATCH_ACCEPT_TAC heap_split_length;
         (* nothing below the end of the space is a reference:
            what was below the generation, what the collection
            wrote, and the expansion *)
         REWRITE_TAC[ALL_APPEND] THEN
         REPEAT CONJ_TAC THEN
         TRY (SOLVED (MATCH_ACCEPT_TAC isRef_heap_expand)) THEN
         TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
         TRY (SOLVED
           (W(fun (asl,w as gl) ->
              let lst = el 1 (snd (strip_comb w)) in
              let dl = the_asm (fun c -> hd_is "ALL" c &&
                         hd_is "isDataElement"
                           (el 0 (snd (strip_comb c))) &&
                         el 1 (snd (strip_comb c)) = lst) gl in
              let cond = the_asm (fun c -> is_forall c &&
                           can (find_term (hd_is
                             "gen_gc_partial_conf_isRef")) c &&
                           can (find_term (fun t -> t = lst)) c &&
                           is_neg
                             (rand (snd (strip_forall c)))) gl in
              ACCEPT_TAC (MATCH_MP (CONJUNCT1 ref_EVERY_d)
                            (CONJ dl cond))))) THEN
         (* what the collection wrote holds no reference, because
            a reference in it would be one in the generation it
            copied *)
         W(fun (asl,w as gl) ->
           let lst = el 1 (snd (strip_comb w)) in
           let dl = the_asm (fun c -> hd_is "ALL" c &&
                      hd_is "isDataElement"
                        (el 0 (snd (strip_comb c))) &&
                      el 1 (snd (strip_comb c)) = lst) gl in
           let cl = the_asm (fun c -> is_forall c &&
                      can (find_term (fun t -> t = lst)) c &&
                      is_imp (snd (strip_forall c)) &&
                      is_exists (rand (snd (strip_forall c)))) gl in
           let cu = the_asm (fun c -> is_forall c &&
                      can (find_term (hd_is
                        "gen_gc_partial_conf_isRef")) c &&
                      is_neg (rand (snd (strip_forall c))) &&
                      not (can (find_term (fun t -> t = lst)) c)) gl in
           let cur = el 1 (snd (strip_comb
                       (lhand (snd (strip_forall (concl cu)))))) in
           SUBGOAL_THEN (subst [lst,cur] (concl cu))
             (fun cond -> ACCEPT_TAC
                (MATCH_MP (CONJUNCT1 ref_EVERY_d)
                   (CONJ dl cond))) THENL
            [MESON_TAC[cl; cu]]);
         (* and everything above the space is a reference: the
            collection copied the references of the generation *)
         W(fun (asl,w as gl) ->
           let lst = el 1 (snd (strip_comb w)) in
           let sim = the_asm (fun c -> hd_is "ALL2" c &&
                       el 2 (snd (strip_comb c)) = lst) gl in
           let refs = el 1 (snd (strip_comb (concl sim))) in
           let dl = the_asm (fun c -> hd_is "ALL" c &&
                      hd_is "isDataElement"
                        (el 0 (snd (strip_comb c))) &&
                      el 1 (snd (strip_comb c)) = refs) gl in
           let cond = the_asm (fun c -> is_forall c &&
                        can (find_term (hd_is
                          "gen_gc_partial_conf_isRef")) c &&
                        can (find_term (fun t -> t = refs)) c &&
                        not (is_neg
                          (rand (snd (strip_forall c))))) gl in
           ACCEPT_TAC (MATCH_MP similar_isRef
             (CONJ sim (MATCH_MP (CONJUNCT2 ref_EVERY_d)
                          (CONJ dl cond)))))])])

      ;
  (* the space that is left is the expansion between the heap it
     wrote and the references: the collection got to the end of
     the old generation and of the heap it wrote *)
  (W(fun (asl,w as gl) ->
       let av = el 0 (snd (strip_comb w)) in
       let hp = el 2 (snd (strip_comb w)) in
       let old = lhand hp and h1 = lhand (rand hp) in
       SUBGOAL_THEN (mk_eq (av,
           list_mk_icomb "heap_length"
             [list_mk_icomb "APPEND" [old; h1]]))
         SUBST1_TAC THENL
        [REWRITE_TAC[heap_length_APPEND] THEN ASM_ARITH_TAC;
         ALL_TAC]) THEN
     ONCE_REWRITE_TAC[APPEND_ASSOC] THEN
     W(fun gl ->
       let dl = the_asm (fun c -> hd_is "ALL" c &&
                  hd_is "isDataElement"
                    (el 0 (snd (strip_comb c))) &&
                  hd_is "gc_state_h1"
                    (el 1 (snd (strip_comb c)))) gl in
       let dold = the_asm (fun c -> hd_is "ALL" c &&
                    hd_is "isDataElement"
                      (el 0 (snd (strip_comb c))) &&
                    hd_is "gc_state_old"
                      (el 1 (snd (strip_comb c)))) gl in
       REWRITE_TAC[unused_space_inv_def; ADD_CLAUSES] THEN
       REPEAT CONJ_TAC THEN
       TRY (SOLVED
         (DISCH_TAC THEN
          REWRITE_TAC[heap_lookup_APPEND; LT_REFL; SUB_REFL;
                      heap_length_heap_expand] THEN
          COND_CASES_TAC THEN
          TRY (SOLVED (ASM_ARITH_TAC)) THEN
          ASM_REWRITE_TAC[heap_expand_def; heap_lookup_def])) THEN
       TRY (SOLVED
         (REWRITE_TAC[heap_length_APPEND;
                      heap_length_heap_expand] THEN
          ARITH_TAC)) THEN
       TRY (SOLVED
         (REWRITE_TAC[data_up_to_APPEND; ALL_APPEND] THEN
          CONJ_TAC THEN
          TRY (SOLVED (ACCEPT_TAC dold)) THEN
          ACCEPT_TAC dl)) THEN
       ALL_TAC))

      ;
  (* the stack and the references go over with the inlining that
     the relation of the collection allows, which is the identity
     one *)
  (let all2_refl = prove
      (`!(R:A->A->bool) l. (!x. R x x) ==> ALL2 R l l`,
       GEN_TAC THEN LIST_INDUCT_TAC THEN ASM_SIMP_TAC[ALL2]) in
     MATCH_MP_TAC (GEN_ALL bc_stack_ref_inv_related) THEN
     W(fun gl ->
       let bsi = the_asm (hd_is "bc_stack_ref_inv") gl in
       let ps = tparts (el 4 (snd (strip_comb (concl bsi)))) in
       let gc = the_asm (hd_is "gc_related") gl in
       let fm = el 0 (snd (strip_comb (concl gc))) in
       MAP_EVERY EXISTS_TAC [fm; el 0 ps; el 1 ps]) THEN
     CONJ_TAC THEN
     TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
     REWRITE_TAC[gc_inline_related_def; gc_inline_def;
                 gc_related_roots_heap_def] THEN
     W(fun (asl,w) ->
       let cs = conjuncts (snd (strip_exists w)) in
       EXISTS_TAC (el 1 (snd (strip_comb (el 0 cs)))) THEN
       EXISTS_TAC (el 1 (snd (strip_comb (el 1 cs))))) THEN
     REPEAT CONJ_TAC THEN
     TRY (SOLVED
       (MATCH_MP_TAC all2_refl THEN
        MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL
          (let (r,_,_) = gc_inline_rel in r))))) THEN
     TRY (SOLVED
       (MATCH_MP_TAC all2_refl THEN
        MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL
          (let (r,_,_) = gc_heap_inline_rel in r))))) THEN
     TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
     TRY (SOLVED (REFL_TAC)) THEN
     FIRST_ASSUM MATCH_ACCEPT_TAC)
      ];
    (* and that its state is good *)
    FIRST_ASSUM ACCEPT_TAC]));;

let data_pointers_def = cake_define
  `data_pointers x1 =
        match x1 with
          [] -> []
        | (DataElement x y z :: rest) ->
        0 :: MAP (\n. n + el_length (DataElement x y z))
          (data_pointers rest)
        | (x :: rest) ->
        MAP (\n. n + el_length x) (data_pointers rest)`;;

let lookup_len_def = cake_define
  `lookup_len heap p =
     (match heap_lookup p heap with NONE -> 0 | SOME x ->
       el_length x)`;;

let data_length_def = cake_define
  `data_length heap =
     SUM (MAP (lookup_len heap) (data_pointers heap))`;;

let data_pointers_heap_expand = prove
 (`data_pointers (heap ++ heap_expand n) = data_pointers heap`,
  (* the expansion is one element that is not a DataElement, so it
     contributes no pointer and shifts none *)
  (let dp = data_pointers_def in
   let aux = prove
    (`!heap n. data_pointers (APPEND heap (heap_expand n)) =
               data_pointers heap`,
     LIST_INDUCT_TAC THENL
      [GEN_TAC THEN REWRITE_TAC[APPEND; heap_expand_def] THEN
       COND_CASES_TAC THEN
       GEN_REWRITE_TAC LAND_CONV [dp] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[dp] THEN MATCH_REDUCE_TAC THEN REWRITE_TAC[MAP];
       GEN_TAC THEN REWRITE_TAC[APPEND] THEN CASES_BY_NAME "h" THEN
       GEN_REWRITE_TAC LAND_CONV [dp] THEN MATCH_REDUCE_TAC THEN
       GEN_REWRITE_TAC RAND_CONV [dp] THEN MATCH_REDUCE_TAC THEN
       ASM_REWRITE_TAC[]]) in
   MATCH_ACCEPT_TAC aux));;

let data_length_APPEND_heap_expand = prove
 (`data_length (heap ++ heap_expand n) = data_length heap`,
  (* the expansion contributes no data element, and the data length
     of a cons is the length of the head when it is one *)
  (let hl = heap_lookup_def in
   let dp = data_pointers_def in
   let dl = data_length_def in
   let ll = lookup_len_def in
   (* a lookup past the first element is one in the tail *)
   let shift_lookup = prove
    (`!(x:((A),(B))heap_element) xs n.
        heap_lookup (n + el_length x) (CONS x xs) = heap_lookup n xs`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [hl] THEN
     MP_TAC(ISPEC `x:((A),(B))heap_element` el_length_GT_0) THEN
     DISCH_TAC THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
     AP_THM_TAC THEN AP_TERM_TAC THEN ARITH_TAC) in
   let map_shift = prove
    (`!(x:((A),(B))heap_element) xs ps.
        MAP (lookup_len (CONS x xs)) (MAP (\n. n + el_length x) ps) =
        MAP (lookup_len xs) ps`,
     GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[MAP; ll; shift_lookup]) in
   let dl_cons = prove
    (`(!ys l d xs. data_length (CONS (DataElement ys l d) xs) =
                   el_length (DataElement ys l d) + data_length xs) /\
      (!k xs. data_length (CONS (Unused k:((A),(B))heap_element) xs) =
              data_length xs) /\
      (!n d l xs.
         data_length (CONS (ForwardPointer n d l:((A),(B))heap_element)
                           xs) = data_length xs)`,
     REPEAT CONJ_TAC THEN REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [dl] THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV) [dp] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[MAP; map_shift; SUM_DEF; ITLIST; dl; ll; hl] THEN
     REWRITE_TAC[ADD_CLAUSES]) in
   let aux = prove
    (`!heap n. data_length (APPEND heap (heap_expand n)) =
               data_length heap`,
     LIST_INDUCT_TAC THENL
      [GEN_TAC THEN REWRITE_TAC[APPEND; heap_expand_def] THEN
       COND_CASES_TAC THEN
       REWRITE_TAC[dl; dp; MAP; SUM_DEF; ITLIST] THEN
       MATCH_REDUCE_TAC THEN REWRITE_TAC[MAP; SUM_DEF; ITLIST];
       GEN_TAC THEN REWRITE_TAC[APPEND] THEN
       CASES_ON_NAME "h" THEN
       ASM_REWRITE_TAC[dl_cons]]) in
   MATCH_ACCEPT_TAC aux));;

let data_length_heap_length = prove
 (`EVERY isDataElement heap ==>
   data_length heap = heap_length heap`,
  (* every element is a data element, so each contributes its own
     length and the data length is the heap length *)
  (let hl = heap_lookup_def in
   let dp = data_pointers_def in
   let dl = data_length_def in
   let ll = lookup_len_def in
   (* a lookup past the first element is one in the tail *)
   let shift_lookup = prove
    (`!(x:((A),(B))heap_element) xs n.
        heap_lookup (n + el_length x) (CONS x xs) = heap_lookup n xs`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [hl] THEN
     MP_TAC(ISPEC `x:((A),(B))heap_element` el_length_GT_0) THEN
     DISCH_TAC THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
     AP_THM_TAC THEN AP_TERM_TAC THEN ARITH_TAC) in
   let map_shift = prove
    (`!(x:((A),(B))heap_element) xs ps.
        MAP (lookup_len (CONS x xs)) (MAP (\n. n + el_length x) ps) =
        MAP (lookup_len xs) ps`,
     GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[MAP; ll; shift_lookup]) in
   let dl_cons = prove
    (`(!ys l d xs. data_length (CONS (DataElement ys l d) xs) =
                   el_length (DataElement ys l d) + data_length xs) /\
      (!k xs. data_length (CONS (Unused k:((A),(B))heap_element) xs) =
              data_length xs) /\
      (!n d l xs.
         data_length (CONS (ForwardPointer n d l:((A),(B))heap_element)
                           xs) = data_length xs)`,
     REPEAT CONJ_TAC THEN REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [dl] THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV) [dp] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[MAP; map_shift; SUM_DEF; ITLIST; dl; ll; hl] THEN
     REWRITE_TAC[ADD_CLAUSES]) in
   let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) =
              el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   let aux = prove
    (`!heap. EVERY isDataElement heap
             ==> data_length heap = heap_length heap`,
     LIST_INDUCT_TAC THENL
      [REWRITE_TAC[dl; dp] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[MAP; SUM_DEF; ITLIST; hlen_cl];
       REWRITE_TAC[ALL] THEN STRIP_TAC THEN
       CASES_ON_NAME "h" THEN
       RULE_ASSUM_TAC(REWRITE_RULE[isDataElement_def;
                                   distinctness "heap_element";
                                   injectivity "heap_element"]) THEN
       TRY(FIRST_ASSUM CONTR_TAC) THEN
       ASM_SIMP_TAC[dl_cons; hlen_cl]]) in
   MATCH_ACCEPT_TAC aux));;

let data_length_CONS = prove
 (`!x xs. data_length (x :: xs) = data_length [x] + data_length xs`,
  (* what HOL4's simp set does with data_pointers and lookup_len: the
     pointers of the tail are shifted by the length of the head, and
     a lookup at a shifted pointer is the lookup in the tail *)
  (let dp = data_pointers_def in
   let dl = data_length_def in
   let ll = lookup_len_def in
   let dp_cl = prove
    (`data_pointers ([]:((A,B)heap_element)list) = [] /\
      (!xs l d (t:((A,B)heap_element)list).
         data_pointers (CONS (DataElement xs l d) t) =
         CONS 0 (MAP (\n. n + el_length
                             (DataElement xs l d:(A,B)heap_element))
                     (data_pointers t))) /\
      (!k (t:((A,B)heap_element)list).
         data_pointers (CONS (Unused k) t) =
         MAP (\n. n + el_length (Unused k:(A,B)heap_element))
             (data_pointers t)) /\
      (!a b c (t:((A,B)heap_element)list).
         data_pointers (CONS (ForwardPointer a b c) t) =
         MAP (\n. n + el_length
                        (ForwardPointer a b c:(A,B)heap_element))
             (data_pointers t))`,
     REPEAT CONJ_TAC THEN REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [dp] THEN MATCH_REDUCE_TAC THEN
     REWRITE_TAC[]) in
   let hl_sh = prove
    (`!n (x:(A,B)heap_element) xs.
        heap_lookup (n + el_length x) (CONS x xs) = heap_lookup n xs`,
     REPEAT GEN_TAC THEN
     MP_TAC(ISPEC `x:(A,B)heap_element` el_length_GT_0) THEN
     REWRITE_TAC[heap_lookup_def] THEN DISCH_TAC THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
     REWRITE_TAC[ARITH_RULE `(n + m) - m = n`]) in
   let map_sh = prove
    (`!l (x:(A,B)heap_element) xs.
        MAP (lookup_len (CONS x xs)) (MAP (\n. n + el_length x) l) =
        MAP (lookup_len xs) l`,
     LIST_INDUCT_TAC THEN ASM_REWRITE_TAC[MAP; ll; hl_sh]) in
   let ll_0 = prove
    (`!(x:(A,B)heap_element) xs.
        lookup_len (CONS x xs) 0 = el_length x`,
     REWRITE_TAC[ll; heap_lookup_def] THEN
     CONV_TAC(ONCE_DEPTH_CONV MATCH_CONV) THEN REWRITE_TAC[]) in
   let aux = prove
    (`!(x:(A,B)heap_element) xs.
        data_length (CONS x xs) = data_length [x] + data_length xs`,
     GEN_TAC THEN GEN_TAC THEN REWRITE_TAC[dl] THEN
     STRUCT_CASES_TAC
       (ISPEC `x:(A,B)heap_element`
              (cases_of `:(A,B)heap_element`)) THEN
     REWRITE_TAC[dp_cl; MAP; map_sh; ll_0; SUM_DEF; ITLIST] THEN
     ARITH_TAC) in
   MATCH_ACCEPT_TAC aux));;

let data_length_APPEND = prove
 (`!xs ys. data_length (xs ++ ys) = data_length xs + data_length ys`,
  (let dl_nil = prove
    (`data_length ([]:((A,B)heap_element)list) = 0`,
     REWRITE_TAC[data_length_def] THEN
     GEN_REWRITE_TAC ONCE_DEPTH_CONV [data_pointers_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[MAP; SUM_DEF; ITLIST]) in
   LIST_INDUCT_TAC THENL
    [REWRITE_TAC[APPEND; dl_nil] THEN ARITH_TAC;
     GEN_TAC THEN REWRITE_TAC[APPEND] THEN
     GEN_REWRITE_TAC LAND_CONV [data_length_CONS] THEN
     GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [data_length_CONS] THEN
     ASM_REWRITE_TAC[] THEN ARITH_TAC]));;

let data_length_heap_expand = prove
 (`data_length (heap_expand n) = 0`,
  (REWRITE_TAC[heap_expand_def] THEN COND_CASES_TAC THEN
   REWRITE_TAC[data_length_def] THEN
   GEN_REWRITE_TAC ONCE_DEPTH_CONV [data_pointers_def] THEN
   MATCH_REDUCE_TAC THEN
   GEN_REWRITE_TAC ONCE_DEPTH_CONV [data_pointers_def] THEN
   MATCH_REDUCE_TAC THEN REWRITE_TAC[MAP; SUM_DEF; ITLIST]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let gc_combined_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,heap,be,a,sp,sp1,gens) limit ts
  /\
     (do_partial ==> has_gen gens) ==>
      (?roots2 heap2 gens2 n2 a2.
        (gc_combined (make_gc_conf limit)
          (data_to_word_config_gc_kind conf)
              (roots,heap,gens,a + sp + sp1,do_partial) =
           (roots2,heap2,a2,n2,gens2,T)) /\
        abs_ml_inv conf stack refs (roots2,heap2,be,a2,n2,0,gens2)
          limit ts /\
        (~(data_to_word_config_gc_kind conf = None) /\
          (~(data_to_word_config_gc_kind conf = Simple) ==> ~do_partial)
          ==>
         all_reachable_from_roots roots2 heap2 /\
         heap_length heap2 = data_length heap2 + n2))`),
  (* the three kinds of collection, each of them a theorem of its
     own: the one that does nothing leaves the heap as it is and
     says only that the space is empty (and that what the
     invariant then asks of the heap is that it holds data up to
     its start, which is nothing), the full collection is
     full_gc_thm and the generational one is gen_gc_partial_thm
     when it is partial and gen_gc_thm when it is not.  What is
     left over is the arithmetic of the heap that the collection
     wrote: it holds data, so its data length is its heap length,
     and the space it left is what the expansion adds *)
  ((* the limit of the configuration that the collection is run
      with is the limit of the invariant *)
   let limit_make_gc_conf = prove
    (`gen_gc_conf_limit (make_gc_conf l) = l`,
     REWRITE_TAC (make_gc_conf_def :: record_thms "gen_gc_conf")) in
   STRIP_TAC THEN SPLIT_ASM_TAC THEN
   (* what the invariant says of the stack, and the kind of the
      collection, of which there are three *)
   FIRST_ASSUM (fun inv ->
     if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def] inv)) THEN
   W(fun (asl,w) ->
     CASES_ON_TAC (find_term
       (hd_is "data_to_word_config_gc_kind") w)) THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
   REWRITE_TAC[gc_combined_def] THEN
   MATCH_REDUCE_TAC THEN
   (* the witnesses of the first two cases are read off the
      collection's own value *)
   REWRITE_TAC[limit_make_gc_conf] THEN
   W(fun (asl,w as gl) ->
     if not (can (find_term (hd_is "full_gc")) w) then ALL_TAC else
     (* the full collection: what full_gc_thm says of its result *)
     (let inv = the_asm (hd_is "abs_ml_inv") gl in
      let kd = the_asm (fun c -> is_eq c &&
                 hd_is "data_to_word_config_gc_kind" (lhand c)) gl in
      STRIP_ASSUME_TAC
        (MATCH_MP data_to_word_memoryProof_full_gc_thm
           (CONJ inv kd)))) THEN
   W(fun (asl,w) ->
     if not (can (find_term (hd_is "partial_gc")) w) ||
        not (can (find_term (hd_is "COND")) w) then ALL_TAC else
     COND_CASES_TAC) THEN
   (* the two generational collections: what their theorems say *)
   W(fun (asl,w as gl) ->
     if not (can (find_term (hd_is "partial_gc")) w) then ALL_TAC else
     (let inv = the_asm (hd_is "abs_ml_inv") gl in
      let kd = the_asm (fun c -> is_eq c &&
                 hd_is "data_to_word_config_gc_kind" (lhand c)) gl in
      (* the partial collection asks for a generation, which the
         hypothesis gives when the collection is a partial one *)
      let imp = the_asm (fun c -> is_imp c &&
                  hd_is "has_gen" (rand c)) gl in
      let dp = the_asm is_var gl in
      let hg = MP imp dp in
      STRIP_ASSUME_TAC (MATCH_MP gen_gc_partial_thm
        (CONJ inv (CONJ hg kd))))) THEN
   W(fun (asl,w as gl) ->
     if not (can (find_term (hd_is "gen_gc")) w) then ALL_TAC else
     (let inv = the_asm (hd_is "abs_ml_inv") gl in
      STRIP_ASSUME_TAC
        (MATCH_MP data_to_word_memoryProof_gen_gc_thm inv))) THEN
   (* the value of the collection, with the result of the one that
      was run put in.  The configuration that the partial
      collection is run with is a let of its own, so the lets come
      first and the equation of the result after them *)
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   W(fun (asl,w) ->
     let eqs = mapfilter (fun (_,th) ->
                 let c = concl th in
                 if is_eq c &&
                    (hd_is "full_gc" (lhand c) ||
                     hd_is "partial_gc" (lhand c) ||
                     hd_is "gen_gc" (lhand c))
                 then th else fail()) asl in
     REWRITE_TAC eqs) THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   (* so the witnesses are the parts of that value *)
   W(fun (asl,w) ->
     let bod = snd (strip_exists w) in
     let vl = lhand (hd (conjuncts bod)) in
     let ps = tparts vl in
     MAP_EVERY EXISTS_TAC
       [el 0 ps; el 1 ps; el 4 ps; el 3 ps; el 2 ps]) THEN
   REWRITE_TAC[PAIR_EQ] THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (REWRITE_TAC[])) THEN
   (* a partial collection makes no claim about the heap it left:
      its kind is neither None nor Simple *)
   TRY (SOLVED (REWRITE_TAC[distinctness "gc_kind"])) THEN
   (* the invariant of the heap that the collection left *)
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* of a generational collection the generations are the ones
      that reset_gens makes, which for that kind is the list of its
      sizes with the address of the new heap in each *)
   TRY (SOLVED
         (W(fun gl ->
            let inv = the_asm (fun c -> hd_is "abs_ml_inv" c &&
                        can (find_term (hd_is "reset_gens")) c) gl in
            let kd = the_asm (fun c -> is_eq c &&
                       hd_is "data_to_word_config_gc_kind"
                         (lhand c)) gl in
            MATCH_ACCEPT_TAC
              (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)
                 (REWRITE_RULE[reset_gens_def; kd] inv))))) THEN
   (* of the collection that does nothing the space is empty, and
      what the invariant then asks of the heap is that it holds
      data up to its start, which is nothing *)
   TRY (SOLVED
         (REWRITE_TAC[abs_ml_inv_def] THEN
          REPEAT CONJ_TAC THEN
          TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
          TRY (SOLVED
                (REWRITE_TAC[gc_kind_inv_def] THEN
                 ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
                 W(fun gl ->
                   let gk = the_asm (hd_is "gc_kind_inv") gl in
                   MP_TAC (REWRITE_RULE[gc_kind_inv_def] gk)) THEN
                 ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
                 REWRITE_TAC[])) THEN
          REWRITE_TAC[unused_space_inv_def; data_up_to_def;
                      heap_split_0; ADD_CLAUSES; LE_0] THEN
          W(fun (asl,w) ->
            let pr = rand (lhand (hd (conjuncts (snd
                       (strip_exists w))))) in
            EXISTS_TAC (lhand pr) THEN EXISTS_TAC (rand pr)) THEN
          REWRITE_TAC[ALL])) THEN
   (* and the claims that a collection which moves data makes: the
      heap it left is reachable from its roots and holds data up to
      the space that is left *)
   DISCH_THEN (K ALL_TAC) THEN
   CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the heap that the collection left holds data, so its data
      length is its heap length *)
   W(fun (asl,w) ->
     let dls = mapfilter (fun (_,th) ->
                 let c = concl th in
                 if hd_is "ALL" c &&
                    hd_is "isDataElement"
                      (el 0 (snd (strip_comb c)))
                 then MATCH_MP data_length_heap_length th
                 else fail()) asl in
     let hls = mapfilter (fun (_,th) ->
                 let c = concl th in
                 if is_eq c && hd_is "heap_length" (lhand c)
                 then th else fail()) asl in
     REWRITE_TAC (heap_length_APPEND :: heap_length_heap_expand ::
                  data_length_APPEND ::
                  data_length_APPEND_heap_expand ::
                  data_length_heap_expand :: dls @ hls)) THEN
   ARITH_TAC));;

(* Write to unused heap space is fine, e.g. cons *)

let heap_store_def = cake_define_list
  [`heap_store a y [] = ([],F)`;
   `heap_store a y (x :: xs) =
        (if a = 0 then (y ++ xs,(el_length x = heap_length y)) else
        if a < el_length x then (x :: xs,F) else
          let (xs,c) = heap_store (a - el_length x) y xs in
            (x :: xs,c))`];;

let isUnused_def = cake_define
  `isUnused x = (?k. x = Unused k)`;;

let isSomeUnused_def = cake_define
  `isSomeUnused x = (?k. x = SOME (Unused k))`;;

let heap_store_unused_def = cake_define
  `heap_store_unused a sp x xs =
     (if (heap_lookup a xs = SOME (Unused (sp - 1))) /\ el_length x
       <= sp then
       heap_store a (heap_expand (sp - el_length x) ++ [x]) xs
         else (xs,F))`;;

let heap_store_unused_alt_def = cake_define
  `heap_store_unused_alt a sp x xs =
     (if (heap_lookup a xs = SOME (Unused (sp - 1))) /\ el_length x
       <= sp then
       heap_store a ([x] ++ heap_expand (sp - el_length x)) xs
         else (xs,F))`;;

let heap_store_lemma = prove
 (`!xs y x ys.
      heap_store (heap_length xs) y (xs ++ (x :: ys)) =
      (xs ++ y ++ ys,(heap_length y = el_length x))`,
  (LIST_INDUCT_TAC THENL
    [REPEAT GEN_TAC THEN
     REWRITE_TAC[heap_length_NIL; APPEND; heap_store_def] THEN
     REWRITE_TAC[PAIR_EQ; EQ_SYM_EQ];
     REPEAT GEN_TAC THEN
     REWRITE_TAC[heap_length_CONS; APPEND] THEN
     GEN_REWRITE_TAC LAND_CONV [heap_store_def] THEN
     MP_ISPEC_NAME "h" el_length_GT_0 THEN DISCH_TAC THEN
     ASM_SIMP_TAC[ARITH_RULE `1 <= a ==> ~(a + b = 0)`;
                  ARITH_RULE `1 <= a ==> ~(a + b < a)`;
                  ARITH_RULE `(a + b) - a = b`] THEN
     ASM_REWRITE_TAC[] THEN CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[PAIR_EQ]]));;

let heap_store_rel_def = cake_define
  `heap_store_rel heap heap2 <=>
     (!ptr. isSomeDataElement (heap_lookup ptr heap) ==>
            (heap_lookup ptr heap2 = heap_lookup ptr heap))`;;

(* [local] *)
let isSomeDataElement_heap_lookup_lemma1 = prove
 (`isSomeDataElement (heap_lookup n (Unused k :: xs)) <=>
     k < n /\ isSomeDataElement (heap_lookup (n - (k + 1)) xs)`,
  (let isde = isSomeDataElement_def in
   let opt = [distinctness "option"; injectivity "option";
              distinctness "heap_element"] in
   REWRITE_TAC[heap_lookup_def; el_length_def] THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC(isde :: opt) THENL
    [MATCH_MP_TAC(TAUT `~a ==> ~(a /\ b)`) THEN ASM_ARITH_TAC;
     COND_CASES_TAC THEN ASM_REWRITE_TAC(isde :: opt) THENL
      [MATCH_MP_TAC(TAUT `~a ==> ~(a /\ b)`) THEN ASM_ARITH_TAC;
       SUBGOAL_THEN `(k:num) < n` (fun th -> REWRITE_TAC[th]) THEN
       ASM_ARITH_TAC]]));;

(* [local] *)
let isSomeDataElement_heap_lookup_lemma2 = prove
 (`isSomeDataElement (heap_lookup n (heap_expand k ++ xs)) <=>
     k <= n /\ isSomeDataElement (heap_lookup (n - k) xs)`,
  (REWRITE_TAC[heap_expand_def] THEN COND_CASES_TAC THEN
   ASM_REWRITE_TAC[APPEND; SUB_0; LE_0] THEN
   REWRITE_TAC[isSomeDataElement_heap_lookup_lemma1] THEN
   ASM_SIMP_TAC[ARITH_RULE `~(k = 0) ==> (n - (k - 1 + 1) = n - k)`;
                ARITH_RULE `~(k = 0) ==> (k - 1 < n <=> k <= n)`]));;

(* [local] *)
let isSomeDataElement_heap_lookup_lemma3 = prove
 (`~(n = 0) ==>
       (isSomeDataElement (heap_lookup n (x :: xs)) <=>
        el_length x <= n /\ isSomeDataElement (heap_lookup (n -
          el_length x) xs))`,
  (let isde = isSomeDataElement_def in
   let opt = [distinctness "option"; injectivity "option";
              distinctness "heap_element"] in
   DISCH_TAC THEN REWRITE_TAC[heap_lookup_def] THEN
   ASM_REWRITE_TAC[] THEN COND_CASES_TAC THEN
   ASM_REWRITE_TAC(isde :: opt) THENL
    [MATCH_MP_TAC(TAUT `~a ==> ~(a /\ b)`) THEN ASM_ARITH_TAC;
     ASM_SIMP_TAC[ARITH_RULE `~(a:num < b) ==> (b <= a <=> T)`]]));;

(* the port's own: what the proof of IMP_heap_store_unused needs.
   A store into the unused space writes the space that is left, the
   element, and what followed the space -- an append of four, which
   the rewriter puts to the right.  The element is then at the end
   of what was unused (heap_lookup_at_end) and the space that is
   left in front of it (heap_lookup_unused_left); outside the space
   the heap is the one it was (heap_lookup_store_outside), because
   the space and what the store wrote into it are of one length,
   and inside it neither heap holds data
   (heap_lookup_store_inside, heap_lookup_in_unused).  The last two
   put those together into what the theorem says of the addresses
   that hold data (isSome_store_unused) and of the elements the
   heap keeps (heap_store_rel_store_unused) *)

(* a store into the unused space writes the space that is left, the
   element, and what followed; the element is at the end of what
   was unused and the space that is left is in front of it *)
let heap_lookup_at_end = prove
 (`!ha k x hb.
     heap_lookup (heap_length ha + k)
       (ha ++ ((heap_expand k ++ [x]) ++ hb)) = SOME x`,
  REPEAT GEN_TAC THEN
  W(fun (asl,w) ->
    MP_TAC (ISPEC (rand (rand w)) el_length_GT_0)) THEN
  DISCH_TAC THEN
  REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
              heap_length_APPEND; heap_length_heap_expand;
              heap_length_clauses; ADD_CLAUSES; LT_REFL; SUB_REFL;
              heap_lookup_def] THEN
  REPEAT (CHANGED_TAC
            (COND_CASES_TAC THEN
             ASM_REWRITE_TAC[heap_lookup_def; LT_REFL; SUB_REFL;
                             ADD_CLAUSES])) THEN
  TRY (SOLVED (ASM_ARITH_TAC)));;

let heap_lookup_unused_left = prove
 (`!ha k x hb.
     ~(k = 0) ==>
     heap_lookup (heap_length ha)
       (ha ++ ((heap_expand k ++ [x]) ++ hb)) = SOME (Unused (k - 1))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_REWRITE_TAC[heap_expand_def] THEN
  REWRITE_TAC[APPEND] THEN
  REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
              heap_length_APPEND; heap_length_clauses;
              ADD_CLAUSES; LT_REFL; SUB_REFL; heap_lookup_def;
              el_length_def] THEN
  REPEAT (CHANGED_TAC
            (COND_CASES_TAC THEN
             ASM_REWRITE_TAC[heap_lookup_def; LT_REFL; SUB_REFL;
                             ADD_CLAUSES; el_length_def])) THEN
  TRY (SOLVED (ASM_ARITH_TAC)));;

(* outside the space that the store wrote, the heap is the one it
   was: what is before it is where it was, and what follows it is
   as far from the front as it was, because the space and what was
   written into it are of one length *)
let heap_lookup_store_outside = prove
 (`!ha sp e x hb y.
     ~(sp = 0) /\ el_length x = e /\ e <= sp /\
     (y < heap_length ha \/ heap_length ha + sp <= y)
     ==> heap_lookup y (ha ++ ((heap_expand (sp - e) ++ [x]) ++ hb)) =
         heap_lookup y (ha ++ (Unused (sp - 1) :: hb))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THENL
   [(* before the space: the lookup lands in the front *)
    W(fun gl ->
      let lt = the_asm (fun c -> hd_is "<" c &&
                 hd_is "heap_length" (rand c)) gl in
      REWRITE_TAC[MATCH_MP LESS_IMP_heap_lookup lt]);
    (* and past it: the front and the space are as long as they
       were *)
    W(fun (asl,w as gl) ->
      let ge = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "+" (lhand c)) gl in
      let a = lhand (lhand (concl ge)) in
      let sp = rand (lhand (concl ge)) in
      let y = rand (concl ge) in
      let nlt = MP (ISPECL [a; sp; y] (ARITH_RULE
                  `!a s y. (a:num) + s <= y ==> ~(y < a)`)) ge in
      REWRITE_TAC[MATCH_MP NOT_LESS_IMP_heap_lookup nlt]) THEN
    W(fun gl ->
      let le = the_asm (fun c -> hd_is "<=" c &&
                 not (hd_is "+" (lhand c))) gl in
      let eq = the_asm (fun c -> is_eq c &&
                 hd_is "el_length" (lhand c)) gl in
      let sp = rand (concl le) in
      let e = lhand (concl le) in
      let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                  rand (rand c) = `0`) gl in
      let seq = MP (ISPECL [sp; e] (ARITH_RULE
                  `!s e. (e:num) <= s ==> (s - e) + e = s`)) le in
      let s1 = MP (ISPEC sp (ARITH_RULE
                 `!s. ~((s:num) = 0) ==> s - 1 + 1 = s`)) ne0 in
      REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
                  heap_length_APPEND; heap_length_heap_expand;
                  heap_length_clauses; ADD_CLAUSES; eq; seq; s1;
                  heap_lookup_def; el_length_def]) THEN
    W(fun gl ->
      let ge = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "+" (lhand c)) gl in
      let ne = the_asm (fun c -> hd_is "<=" c &&
                 not (hd_is "+" (lhand c))) gl in
      MP_TAC ge THEN MP_TAC ne) THEN
    REPEAT STRIP_TAC THEN
    REPEAT (CHANGED_TAC
              (COND_CASES_TAC THEN
               ASM_REWRITE_TAC[heap_lookup_def; ADD_CLAUSES])) THEN
    ASM_ARITH_TAC]);;

(* and inside that space, away from the element written, neither
   heap holds data: the one has what is left of the space there and
   the other the space it had *)
let heap_lookup_store_inside = prove
 (`!ha sp e x hb y.
     ~(sp = 0) /\ el_length x = e /\ 1 <= e /\ e <= sp /\
     ~(y < heap_length ha) /\ y < heap_length ha + sp /\
     ~(y = heap_length ha + (sp - e))
     ==> ~isSomeDataElement
           (heap_lookup y
              (ha ++ ((heap_expand (sp - e) ++ [x]) ++ hb))) /\
         ~isSomeDataElement
           (heap_lookup y (ha ++ (Unused (sp - 1) :: hb)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  W(fun gl ->
    let nlt = the_asm (fun c -> is_neg c && hd_is "<" (rand c) &&
                hd_is "heap_length" (rand (rand c))) gl in
    REWRITE_TAC[MATCH_MP NOT_LESS_IMP_heap_lookup nlt]) THEN
  W(fun gl ->
    let le = the_asm (fun c -> hd_is "<=" c && is_var (lhand c) &&
               is_var (rand c)) gl in
    let eq = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                rand (rand c) = `0`) gl in
    let sp = rand (concl le) in
    let e = lhand (concl le) in
    let seq = MP (ISPECL [sp; e] (ARITH_RULE
                `!s e. (e:num) <= s ==> (s - e) + e = s`)) le in
    let s1 = MP (ISPEC sp (ARITH_RULE
               `!s. ~((s:num) = 0) ==> s - 1 + 1 = s`)) ne0 in
    REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
                heap_length_APPEND; heap_length_heap_expand;
                heap_length_clauses; ADD_CLAUSES; eq; seq; s1;
                heap_expand_def; heap_lookup_def;
                el_length_def]) THEN
  CONJ_TAC THEN
  REPEAT (CHANGED_TAC
            (COND_CASES_TAC THEN
             ASM_REWRITE_TAC[heap_lookup_def; ADD_CLAUSES;
                             el_length_def])) THEN
  REWRITE_TAC[isSomeDataElement_def] THEN
  (let ds = [distinctness "heap_element"] in
   REWRITE_TAC (injectivity "option" :: distinctness "option" ::
                NOT_EXISTS_THM :: ds @ map GSYM ds)) THEN
  TRY (SOLVED (REWRITE_TAC[])) THEN
  TRY (SOLVED (ASM_ARITH_TAC)));;

(* the address that the store writes held no data: it is inside the
   unused element, which is no data element *)
let heap_lookup_in_unused = prove
 (`!ha sp e hb.
     ~(sp = 0) /\ 1 <= e /\ e <= sp
     ==> ~isSomeDataElement
           (heap_lookup (heap_length ha + (sp - e))
              (ha ++ (Unused (sp - 1) :: hb)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  W(fun (asl,w as gl) ->
    let lk = find_term (hd_is "heap_lookup") w in
    let j = el 0 (snd (strip_comb lk)) in
    let a = lhand j in
    let sp = lhand (rand j) in
    let e = rand (rand j) in
    let le = the_asm (fun c -> hd_is "<=" c && lhand c = e) gl in
    let nlt = MP (ISPECL [a; sp; e] (ARITH_RULE
                `!a s e. e <= s ==> ~((a:num) + (s - e) < a)`)) le in
    let seq = MP (ISPECL [a; sp; e] (ARITH_RULE
                `!a s e. e <= s
                         ==> ((a:num) + (s - e)) - a = s - e`)) le in
    REWRITE_TAC[MATCH_MP NOT_LESS_IMP_heap_lookup nlt; seq]) THEN
  REWRITE_TAC[heap_lookup_def; el_length_def] THEN
  REPEAT COND_CASES_TAC THEN
  REWRITE_TAC[isSomeDataElement_def] THEN
  (let ds = [distinctness "heap_element"] in
   REWRITE_TAC (injectivity "option" :: distinctness "option" ::
                NOT_EXISTS_THM :: ds @ map GSYM ds)) THEN
  TRY (SOLVED (REWRITE_TAC[])) THEN
  ASM_ARITH_TAC);;

(* the three regions of a store into the unused space, as the
   addresses that hold data: the ones the heap had and the one the
   store wrote *)
let isSome_store_unused = prove
 (`!ha sp e x hb.
     ~(sp = 0) /\ el_length x = e /\ 1 <= e /\ e <= sp /\
     isDataElement x
     ==> {a | isSomeDataElement
                (heap_lookup a
                   (ha ++ ((heap_expand (sp - e) ++ [x]) ++ hb)))} =
         (heap_length ha + (sp - e)) INSERT
         {a | isSomeDataElement
                (heap_lookup a (ha ++ (Unused (sp - 1) :: hb)))}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_INSERT; IN_ELIM_THM] THEN
  GEN_TAC THEN
  W(fun (asl,w as gl) ->
    let addr = rand (lhand (rand w)) in
    let y = lhand (lhand (rand w)) in
    let a = lhand addr in
    let sp = lhand (rand addr) in
    let e = rand (rand addr) in
    let hp = el 1 (snd (strip_comb
               (find_term (hd_is "heap_lookup") (lhand w)))) in
    let ha = lhand hp in
    let x = lhand (rand (lhand (rand hp))) in
    let hb = rand (rand hp) in
    let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                rand (rand c) = `0`) gl in
    let eq = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    let one = the_asm (fun c -> hd_is "<=" c &&
                lhand c = `1`) gl in
    let le = the_asm (fun c -> hd_is "<=" c && is_var (lhand c) &&
               is_var (rand c)) gl in
    let isd = the_asm (hd_is "isDataElement") gl in
    (* the address of the element written *)
    ASM_CASES_TAC (mk_eq (y, addr)) THENL
     [ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[ISPECL [ha; list_mk_icomb "-" [sp; e]; x; hb]
                    heap_lookup_at_end] THEN
      MP_TAC isd THEN
      REWRITE_TAC[isDataElement_def; isSomeDataElement_def] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    (* before the space or past it: the lookups are the ones they
       were; inside it, neither heap holds data *)
    DISJ_CASES_TAC (ISPECL [y; a; sp] (ARITH_RULE
      `!y a s. (y < a \/ a + s <= y) \/ (~(y < a) /\ y < a + s)`)) THENL
     [W(fun gl ->
        let d = the_asm is_disj gl in
        REWRITE_TAC[MATCH_MP (ISPECL [ha; sp; e; x; hb; y]
                                heap_lookup_store_outside)
                      (CONJ ne0 (CONJ eq (CONJ le d)))]);
      W(fun gl ->
        let d = the_asm (fun c -> is_conj c && is_neg (lhand c)) gl in
        let nq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                   rand (rand c) = addr) gl in
        let ins = MATCH_MP (ISPECL [ha; sp; e; x; hb; y]
                              heap_lookup_store_inside)
                    (CONJ ne0 (CONJ eq (CONJ one (CONJ le
                      (CONJ (CONJUNCT1 d) (CONJ (CONJUNCT2 d)
                        nq)))))) in
        REWRITE_TAC[CONJUNCT1 ins; CONJUNCT2 ins])]));;

(* and so a store into the unused space keeps every element that
   the heap had: the ones outside the space are where they were,
   and inside it the heap held none *)
let heap_store_rel_store_unused = prove
 (`!ha sp e x hb.
     ~(sp = 0) /\ el_length x = e /\ 1 <= e /\ e <= sp
     ==> heap_store_rel (ha ++ (Unused (sp - 1) :: hb))
           (ha ++ ((heap_expand (sp - e) ++ [x]) ++ hb))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  REWRITE_TAC[heap_store_rel_def] THEN
  GEN_TAC THEN DISCH_TAC THEN
  W(fun (asl,w as gl) ->
    let hp = el 1 (snd (strip_comb
               (find_term (hd_is "heap_lookup") (lhand w)))) in
    let ha = lhand hp in
    let x = lhand (rand (lhand (rand hp))) in
    let hb = rand (rand hp) in
    let a = list_mk_icomb "heap_length" [ha] in
    let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                rand (rand c) = `0`) gl in
    let eq = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    let one = the_asm (fun c -> hd_is "<=" c &&
                lhand c = `1`) gl in
    let le = the_asm (fun c -> hd_is "<=" c && is_var (lhand c) &&
               is_var (rand c)) gl in
    let sp = rand (concl le) in
    let e = lhand (concl le) in
    let ptr = el 0 (snd (strip_comb
                (find_term (hd_is "heap_lookup") (lhand w)))) in
    let addr = list_mk_icomb "+"
                 [a; list_mk_icomb "-" [sp; e]] in
    DISJ_CASES_TAC (ISPECL [ptr; a; sp] (ARITH_RULE
      `!y a s. (y < a \/ a + s <= y) \/
               (~(y < a) /\ y < a + s)`)) THENL
     [W(fun gl ->
        let d = the_asm is_disj gl in
        ACCEPT_TAC (MATCH_MP (ISPECL [ha; sp; e; x; hb; ptr]
                                heap_lookup_store_outside)
                      (CONJ ne0 (CONJ eq (CONJ le d)))));
      (* inside the space the old heap held no data, so there is
         nothing to keep *)
      ASM_CASES_TAC (mk_eq (ptr, addr)) THENL
       [W(fun gl ->
          let isd = the_asm (hd_is "isSomeDataElement") gl in
          let nd = MATCH_MP (ISPECL [ha; sp; e; hb]
                               heap_lookup_in_unused)
                     (CONJ ne0 (CONJ one le)) in
          let eqp = the_asm (fun c -> is_eq c && lhand c = ptr) gl in
          CONTR_TAC (MP (NOT_ELIM nd)
            (ONCE_REWRITE_RULE[eqp] isd)));
        W(fun gl ->
          let d = the_asm (fun c -> is_conj c &&
                    is_neg (lhand c)) gl in
          let nq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                     lhand (rand c) = ptr) gl in
          let isd = the_asm (hd_is "isSomeDataElement") gl in
          let ins = MATCH_MP (ISPECL [ha; sp; e; x; hb; ptr]
                                heap_lookup_store_inside)
                      (CONJ ne0 (CONJ eq (CONJ one (CONJ le
                        (CONJ (CONJUNCT1 d) (CONJ (CONJUNCT2 d)
                          nq)))))) in
          CONTR_TAC (MP (NOT_ELIM (CONJUNCT2 ins)) isd))]]));;

(* [local] *)
let IMP_heap_store_unused = prove
 (`unused_space_inv a sp (heap:(('a,'b)heap_element) list) /\
     el_length x <= sp ==>
     (?heap2. (heap_store_unused a sp x heap = (heap2,T)) /\
             unused_space_inv a (sp - el_length x) heap2 /\
             (heap_lookup ((a + sp) - el_length x) heap2 = SOME x) /\
             ~(isSomeDataElement (heap_lookup ((a + sp) - el_length
               x) heap)) /\
             (heap_length heap2 = heap_length heap) /\
             (~(isForwardPointer x) ==>
              (FILTER isForwardPointer heap2 = FILTER
                isForwardPointer heap)) /\
             (!xs l d.
                MEM (DataElement xs l d) heap2 <=>
                  (x = DataElement xs l d) \/
                  MEM (DataElement xs l d) heap) /\
             (isDataElement x ==>
              ({a | isSomeDataElement (heap_lookup a heap2)} =
                  ((
                a + sp) - el_length x) INSERT {a | isSomeDataElement
                  (heap_lookup a heap)})) /\
             heap_store_rel heap heap2)`,
  (* the steps are above the statement (tools/overrides.py).  The
     element fits in the unused space, so that space is not empty
     and the heap holds the unused element: heap_lookup_SPLIT cuts
     the heap at it and heap_store_lemma says what the store
     writes.  Of the ten things the theorem says, the lengths and
     the forward pointers and the data elements are arithmetic and
     rewriting, and the four lemmas about the regions of the store
     say the rest *)
  (STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* the unused space is not empty, because the element fits in it *)
    W(fun (asl,w as gl) ->
      let le = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "el_length" (lhand c)) gl in
      let x = rand (lhand (concl le)) in
      let sp = rand (concl le) in
      SUBGOAL_THEN (mk_neg (mk_eq (sp, `0`))) ASSUME_TAC THENL
       [MP_TAC (ISPEC x el_length_GT_0) THEN MP_TAC le THEN ARITH_TAC;
        ALL_TAC]) THEN
    (* so the heap holds the unused element, and is what is before
       it, it, and what follows *)
    W(fun gl ->
      let us = the_asm (hd_is "unused_space_inv") gl in
      STRIP_ASSUME_TAC (REWRITE_RULE[unused_space_inv_def] us)) THEN
    W(fun gl ->
      let imp = the_asm (fun c -> is_imp c && is_neg (lhand c) &&
                  is_eq (rand c) &&
                  hd_is "heap_lookup" (lhand (rand c))) gl in
      let ne = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                 rand (rand c) = `0`) gl in
      STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT (MP imp ne))) THEN
    REPEAT (FIRST_X_ASSUM (fun e ->
      let c = concl e in
      if not (is_eq c) || not (is_var (lhand c)) then fail() else
      SUBST_ALL_TAC e)) THEN
    (* and the store writes the element into that space *)
    REWRITE_TAC[heap_store_unused_def] THEN
    ASM_REWRITE_TAC[heap_lookup_PREFIX] THEN
    REWRITE_TAC[heap_store_lemma] THEN
    W(fun (asl,w) ->
      let pr = lhand (hd (conjuncts (snd (strip_exists w)))) in
      EXISTS_TAC (lhand pr)) THEN
    REWRITE_TAC[PAIR_EQ] THEN
    (* the element written is at the end of what was unused *)
    W(fun (asl,w as gl) ->
      let le = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "el_length" (lhand c)) gl in
      let e = lhand (concl le) in
      let sp = rand (concl le) in
      let hl = find_term (fun t -> hd_is "heap_length" t &&
                 is_var (rand t)) w in
      REWRITE_TAC[MP (ISPECL [hl; sp; e] (ARITH_RULE
        `!a s e. (e:num) <= s ==> (a + s) - e = a + (s - e)`)) le]) THEN
    (* what is before the space holds data, and the element written
       is no shorter than one *)
    W(fun gl ->
      let du = the_asm (hd_is "data_up_to") gl in
      let le = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "el_length" (lhand c)) gl in
      ASSUME_TAC (REWRITE_RULE[data_up_to_APPEND] du) THEN
      ASSUME_TAC (ISPEC (rand (lhand (concl le))) el_length_GT_0)) THEN
    REPEAT CONJ_TAC THEN
    (* the length of what the store writes is the length of the
       element it replaces, and the heap is as long as it was *)
    TRY (SOLVED
          (REWRITE_TAC[heap_length_APPEND; heap_length_heap_expand;
                       heap_length_clauses; el_length_def;
                       ADD_CLAUSES] THEN
           ASM_ARITH_TAC)) THEN
    (* the forward pointers are the ones it had *)
    TRY (SOLVED
          (DISCH_TAC THEN
           REWRITE_TAC[FILTER_APPEND; FILTER; heap_expand_def] THEN
           COND_CASES_TAC THEN
           ASM_REWRITE_TAC[FILTER; APPEND; APPEND_NIL;
                           isForwardPointer_def])) THEN
    (* and the data elements are the ones it had, and the one
       written *)
    TRY (SOLVED
          (REPEAT GEN_TAC THEN
           REWRITE_TAC[heap_expand_def] THEN
           COND_CASES_TAC THEN
           (let ds = [distinctness "heap_element"] in
            REWRITE_TAC (MEM_APPEND :: MEM :: APPEND ::
                         ds @ map GSYM ds)) THEN
           MESON_TAC[])) THEN
    (* the element written is where the goal says, the space it went
       into held no data, and what held data still does *)
    W(fun (asl,w as gl) ->
      let le = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "el_length" (lhand c)) gl in
      let one = the_asm (fun c -> hd_is "<=" c &&
                  lhand c = `1`) gl in
      let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                  rand (rand c) = `0`) gl in
      let e = lhand (concl le) in
      let sp = rand (concl le) in
      let x = rand e in
      let du = the_asm (hd_is "data_up_to") gl in
      let hp = el 1 (snd (strip_comb (concl du))) in
      let ha = lhand hp in
      let hb = rand (rand hp) in
      let args = [ha; sp; e; x; hb] in
      let hyp3 = CONJ ne0 (CONJ one le) in
      let hyp4 = CONJ ne0 (CONJ (REFL e) (CONJ one le)) in
      if hd_is "unused_space_inv" w then
        (* the space that is left is unused space, and what is before
           it still holds data *)
        (REWRITE_TAC[unused_space_inv_def] THEN
         REPEAT CONJ_TAC THENL
          [DISCH_TAC THEN
           W(fun gl ->
             let ne = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                        rand (rand c) = `0` &&
                        hd_is "-" (lhand (rand c))) gl in
             ACCEPT_TAC (MP (ISPECL [ha; lhand (rand (concl ne)); x; hb]
                               heap_lookup_unused_left) ne));
           W(fun gl ->
             let bd = the_asm (fun c -> hd_is "<=" c &&
                        hd_is "heap_length" (rand c)) gl in
             MP_TAC bd) THEN
           REWRITE_TAC[heap_length_APPEND; heap_length_clauses;
                       heap_length_heap_expand; el_length_def;
                       ADD_CLAUSES] THEN
           ASM_ARITH_TAC;
           REWRITE_TAC[data_up_to_APPEND] THEN
           FIRST_ASSUM ACCEPT_TAC])
      else if is_eq w && hd_is "heap_lookup" (lhand w) then
        REWRITE_TAC[heap_lookup_at_end]
      else if is_neg w && hd_is "isSomeDataElement" (rand w) then
        ACCEPT_TAC (MATCH_MP (ISPECL [ha; sp; e; hb]
                                heap_lookup_in_unused) hyp3)
      else if is_imp w && hd_is "isDataElement" (lhand w) then
        (DISCH_TAC THEN
         W(fun gl ->
           let isd = the_asm (hd_is "isDataElement") gl in
           ACCEPT_TAC (MATCH_MP (ISPECL args isSome_store_unused)
             (CONJ ne0 (CONJ (REFL e) (CONJ one (CONJ le isd)))))))
      else if hd_is "heap_store_rel" w then
        ACCEPT_TAC (MATCH_MP (ISPECL args
                                heap_store_rel_store_unused) hyp4)
      else ALL_TAC)));;

(* the port's own: what the proof of IMP_heap_store_unused_alt
   needs.  This store writes the element first and the space that
   is left after it, so the element is at the start of what was
   unused (heap_lookup_alt_at_start) and the space that is left
   behind it (heap_lookup_alt_unused); outside the space the heap
   is the one it was and inside it neither heap holds data, as for
   the other store, and the last three lemmas put that together
   into the addresses that hold data, the elements the heap keeps,
   and what is below the space that is left (the element written is
   data, which is why the theorem asks for isDataElement) *)

(* the other store into the unused space writes the element first
   and the space that is left after it *)
let heap_lookup_alt_at_start = prove
 (`!ha k x hb.
     heap_lookup (heap_length ha)
       (ha ++ (([x] ++ heap_expand k) ++ hb)) = SOME x`,
  REPEAT GEN_TAC THEN
  W(fun (asl,w) -> MP_TAC (ISPEC (rand (rand w)) el_length_GT_0)) THEN
  DISCH_TAC THEN
  REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
              LT_REFL; SUB_REFL; APPEND; heap_length_clauses;
              ADD_CLAUSES; heap_lookup_def] THEN
  REPEAT (CHANGED_TAC
            (COND_CASES_TAC THEN
             ASM_REWRITE_TAC[heap_lookup_def; ADD_CLAUSES])) THEN
  TRY (SOLVED (ASM_ARITH_TAC)));;

let heap_lookup_alt_unused = prove
 (`!ha k x hb.
     ~(k = 0) ==>
     heap_lookup (heap_length ha + el_length x)
       (ha ++ (([x] ++ heap_expand k) ++ hb)) = SOME (Unused (k - 1))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_REWRITE_TAC[heap_expand_def] THEN
  REWRITE_TAC[APPEND] THEN
  W(fun (asl,w) ->
    MP_TAC (ISPEC (rand (rand (el 0 (snd (strip_comb (lhand w))))))
              el_length_GT_0)) THEN
  DISCH_TAC THEN
  REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
              heap_length_APPEND; heap_length_clauses;
              ADD_CLAUSES; LT_REFL; SUB_REFL; heap_lookup_def;
              el_length_def] THEN
  REPEAT (CHANGED_TAC
            (COND_CASES_TAC THEN
             ASM_REWRITE_TAC[heap_lookup_def; LT_REFL; SUB_REFL;
                             ADD_CLAUSES; el_length_def])) THEN
  ASM_ARITH_TAC);;

(* outside the space that the store wrote, the heap is the one it
   was, as for the other store *)
let heap_lookup_alt_outside = prove
 (`!ha sp e x hb y.
     ~(sp = 0) /\ el_length x = e /\ e <= sp /\
     (y < heap_length ha \/ heap_length ha + sp <= y)
     ==> heap_lookup y (ha ++ (([x] ++ heap_expand (sp - e)) ++ hb)) =
         heap_lookup y (ha ++ (Unused (sp - 1) :: hb))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THENL
   [W(fun gl ->
      let lt = the_asm (fun c -> hd_is "<" c &&
                 hd_is "heap_length" (rand c)) gl in
      REWRITE_TAC[MATCH_MP LESS_IMP_heap_lookup lt]);
    W(fun (asl,w as gl) ->
      let ge = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "+" (lhand c)) gl in
      let a = lhand (lhand (concl ge)) in
      let sp = rand (lhand (concl ge)) in
      let y = rand (concl ge) in
      let nlt = MP (ISPECL [a; sp; y] (ARITH_RULE
                  `!a s y. (a:num) + s <= y ==> ~(y < a)`)) ge in
      REWRITE_TAC[MATCH_MP NOT_LESS_IMP_heap_lookup nlt]) THEN
    W(fun gl ->
      let le = the_asm (fun c -> hd_is "<=" c &&
                 not (hd_is "+" (lhand c))) gl in
      let eq = the_asm (fun c -> is_eq c &&
                 hd_is "el_length" (lhand c)) gl in
      let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                  rand (rand c) = `0`) gl in
      let sp = rand (concl le) in
      let e = lhand (concl le) in
      let seq = MP (ISPECL [sp; e] (ARITH_RULE
                  `!s e. (e:num) <= s ==> e + (s - e) = s`)) le in
      let s1 = MP (ISPEC sp (ARITH_RULE
                 `!s. ~((s:num) = 0) ==> s - 1 + 1 = s`)) ne0 in
      REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
                  heap_length_APPEND; heap_length_heap_expand;
                  heap_length_clauses; ADD_CLAUSES; eq; seq; s1;
                  heap_lookup_def; el_length_def]) THEN
    REPEAT (CHANGED_TAC
              (COND_CASES_TAC THEN
               ASM_REWRITE_TAC[heap_lookup_def; ADD_CLAUSES])) THEN
  ASM_ARITH_TAC]);;

(* and inside it, away from the element written, neither heap holds
   data *)
let heap_lookup_alt_inside = prove
 (`!ha sp e x hb y.
     ~(sp = 0) /\ el_length x = e /\ 1 <= e /\ e <= sp /\
     ~(y < heap_length ha) /\ y < heap_length ha + sp /\
     ~(y = heap_length ha)
     ==> ~isSomeDataElement
           (heap_lookup y
              (ha ++ (([x] ++ heap_expand (sp - e)) ++ hb))) /\
         ~isSomeDataElement
           (heap_lookup y (ha ++ (Unused (sp - 1) :: hb)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  W(fun gl ->
    let nlt = the_asm (fun c -> is_neg c && hd_is "<" (rand c) &&
                hd_is "heap_length" (rand (rand c))) gl in
    REWRITE_TAC[MATCH_MP NOT_LESS_IMP_heap_lookup nlt]) THEN
  W(fun gl ->
    let le = the_asm (fun c -> hd_is "<=" c && is_var (lhand c) &&
               is_var (rand c)) gl in
    let eq = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                rand (rand c) = `0`) gl in
    let sp = rand (concl le) in
    let e = lhand (concl le) in
    let seq = MP (ISPECL [sp; e] (ARITH_RULE
                `!s e. (e:num) <= s ==> e + (s - e) = s`)) le in
    let s1 = MP (ISPEC sp (ARITH_RULE
               `!s. ~((s:num) = 0) ==> s - 1 + 1 = s`)) ne0 in
    REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
                heap_length_APPEND; heap_length_heap_expand;
                heap_length_clauses; ADD_CLAUSES; eq; seq; s1;
                heap_expand_def; heap_lookup_def;
                el_length_def]) THEN
  CONJ_TAC THEN
  REPEAT (CHANGED_TAC
            (COND_CASES_TAC THEN
             ASM_REWRITE_TAC[heap_lookup_def; ADD_CLAUSES;
                             el_length_def])) THEN
  REWRITE_TAC[isSomeDataElement_def] THEN
  (let ds = [distinctness "heap_element"] in
   REWRITE_TAC (injectivity "option" :: distinctness "option" ::
                NOT_EXISTS_THM :: ds @ map GSYM ds)) THEN
  TRY (SOLVED (REWRITE_TAC[])) THEN
  ASM_ARITH_TAC);;

(* the addresses that hold data, after the other store: the ones
   the heap had and the one the store wrote *)
let isSome_store_unused_alt = prove
 (`!ha sp e x hb.
     ~(sp = 0) /\ el_length x = e /\ 1 <= e /\ e <= sp /\
     isDataElement x
     ==> {a | isSomeDataElement
                (heap_lookup a
                   (ha ++ (([x] ++ heap_expand (sp - e)) ++ hb)))} =
         heap_length ha INSERT
         {a | isSomeDataElement
                (heap_lookup a (ha ++ (Unused (sp - 1) :: hb)))}`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  REWRITE_TAC[EXTENSION; IN_INSERT; IN_ELIM_THM] THEN
  GEN_TAC THEN
  W(fun (asl,w as gl) ->
    let addr = rand (lhand (rand w)) in
    let y = lhand (lhand (rand w)) in
    let hp = el 1 (snd (strip_comb
               (find_term (hd_is "heap_lookup") (lhand w)))) in
    let ha = lhand hp in
    let x = lhand (lhand (lhand (rand hp))) in
    let hb = rand (rand hp) in
    let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                rand (rand c) = `0`) gl in
    let eq = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    let one = the_asm (fun c -> hd_is "<=" c &&
                lhand c = `1`) gl in
    let le = the_asm (fun c -> hd_is "<=" c && is_var (lhand c) &&
               is_var (rand c)) gl in
    let sp = rand (concl le) in
    let e = lhand (concl le) in
    let isd = the_asm (hd_is "isDataElement") gl in
    (* the address of the element written *)
    ASM_CASES_TAC (mk_eq (y, addr)) THENL
     [ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[ISPECL [ha; list_mk_icomb "-" [sp; e]; x; hb]
                    heap_lookup_alt_at_start] THEN
      MP_TAC isd THEN
      REWRITE_TAC[isDataElement_def; isSomeDataElement_def] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISJ_CASES_TAC (ISPECL [y; addr; sp] (ARITH_RULE
      `!y a s. (y < a \/ a + s <= y) \/
               (~(y < a) /\ y < a + s)`)) THENL
     [W(fun gl ->
        let d = the_asm is_disj gl in
        REWRITE_TAC[MATCH_MP (ISPECL [ha; sp; e; x; hb; y]
                                heap_lookup_alt_outside)
                      (CONJ ne0 (CONJ eq (CONJ le d)))]);
      W(fun gl ->
        let d = the_asm (fun c -> is_conj c &&
                  is_neg (lhand c)) gl in
        let nq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                   rand (rand c) = addr) gl in
        let ins = MATCH_MP (ISPECL [ha; sp; e; x; hb; y]
                              heap_lookup_alt_inside)
                    (CONJ ne0 (CONJ eq (CONJ one (CONJ le
                      (CONJ (CONJUNCT1 d) (CONJ (CONJUNCT2 d)
                        nq)))))) in
        REWRITE_TAC[CONJUNCT1 ins; CONJUNCT2 ins])]));;

(* and the elements that the heap had, it keeps *)
let heap_store_rel_alt = prove
 (`!ha sp e x hb.
     ~(sp = 0) /\ el_length x = e /\ 1 <= e /\ e <= sp
     ==> heap_store_rel (ha ++ (Unused (sp - 1) :: hb))
           (ha ++ (([x] ++ heap_expand (sp - e)) ++ hb))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  REWRITE_TAC[heap_store_rel_def] THEN
  GEN_TAC THEN DISCH_TAC THEN
  W(fun (asl,w as gl) ->
    let hp = el 1 (snd (strip_comb
               (find_term (hd_is "heap_lookup") (lhand w)))) in
    let ha = lhand hp in
    let x = lhand (lhand (lhand (rand hp))) in
    let hb = rand (rand hp) in
    let a = list_mk_icomb "heap_length" [ha] in
    let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                rand (rand c) = `0`) gl in
    let eq = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    let one = the_asm (fun c -> hd_is "<=" c &&
                lhand c = `1`) gl in
    let le = the_asm (fun c -> hd_is "<=" c && is_var (lhand c) &&
               is_var (rand c)) gl in
    let sp = rand (concl le) in
    let e = lhand (concl le) in
    let ptr = el 0 (snd (strip_comb
                (find_term (hd_is "heap_lookup") (lhand w)))) in
    DISJ_CASES_TAC (ISPECL [ptr; a; sp] (ARITH_RULE
      `!y a s. (y < a \/ a + s <= y) \/
               (~(y < a) /\ y < a + s)`)) THENL
     [W(fun gl ->
        let d = the_asm is_disj gl in
        ACCEPT_TAC (MATCH_MP (ISPECL [ha; sp; e; x; hb; ptr]
                                heap_lookup_alt_outside)
                      (CONJ ne0 (CONJ eq (CONJ le d)))));
      ASM_CASES_TAC (mk_eq (ptr, a)) THENL
       [W(fun gl ->
          let isd = the_asm (hd_is "isSomeDataElement") gl in
          let eqp = the_asm (fun c -> is_eq c && lhand c = ptr) gl in
          MP_TAC (ONCE_REWRITE_RULE[eqp] isd) THEN
          REWRITE_TAC[heap_lookup_PREFIX; isSomeDataElement_def] THEN
          (let ds = [distinctness "heap_element"] in
           REWRITE_TAC (injectivity "option" ::
                        NOT_EXISTS_THM :: ds @ map GSYM ds)) THEN
          REWRITE_TAC[]);
        W(fun gl ->
          let d = the_asm (fun c -> is_conj c &&
                    is_neg (lhand c)) gl in
          let nq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                     lhand (rand c) = ptr) gl in
          let isd = the_asm (hd_is "isSomeDataElement") gl in
          let ins = MATCH_MP (ISPECL [ha; sp; e; x; hb; ptr]
                                heap_lookup_alt_inside)
                      (CONJ ne0 (CONJ eq (CONJ one (CONJ le
                        (CONJ (CONJUNCT1 d) (CONJ (CONJUNCT2 d)
                          nq)))))) in
          CONTR_TAC (MP (NOT_ELIM (CONJUNCT2 ins)) isd))]]));;

(* what is below the unused space after the other store: what was
   below it and the element written *)
let data_up_to_alt = prove
 (`!ha x he hb.
     EVERY isDataElement ha /\ isDataElement x
     ==> data_up_to (heap_length ha + el_length x)
           (ha ++ (([x] ++ he) ++ hb))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  W(fun (asl,w) ->
    let args = snd (strip_comb w) in
    let addr = el 0 args in
    let hp = el 1 args in
    let ha = lhand hp in
    let x = lhand (lhand (lhand (rand hp))) in
    let he = rand (lhand (rand hp)) in
    let hb = rand (rand hp) in
    let front = list_mk_icomb "APPEND" [ha; mk_flist [x]] in
    let nw = list_mk_icomb "APPEND"
               [front; list_mk_icomb "APPEND" [he; hb]] in
    SUBGOAL_THEN (mk_eq (hp, nw))
      (fun e -> ONCE_REWRITE_TAC[e]) THENL
     [REWRITE_TAC[APPEND_ASSOC]; ALL_TAC] THEN
    SUBGOAL_THEN (mk_eq (addr, list_mk_icomb "heap_length" [front]))
      (fun e -> ONCE_REWRITE_TAC[e]) THENL
     [REWRITE_TAC[heap_length_APPEND; heap_length_clauses;
                  ADD_CLAUSES];
      ALL_TAC]) THEN
  REWRITE_TAC[data_up_to_APPEND; ALL_APPEND; ALL] THEN
  ASM_REWRITE_TAC[]);;

(* [local] *)
let IMP_heap_store_unused_alt = prove
 (`unused_space_inv a sp (heap:(('a,'b)heap_element) list) /\
     el_length x <= sp ==>
     (?heap2. (heap_store_unused_alt a sp x heap = (heap2,T)) /\
             (isDataElement x ==>
                unused_space_inv (a + el_length x) (sp - el_length x)
                  heap2) /\
             (heap_lookup a heap2 = SOME x) /\
             ~(isSomeDataElement (heap_lookup a heap)) /\
             (heap_length heap2 = heap_length heap) /\
             (~(isForwardPointer x) ==>
              (FILTER isForwardPointer heap2 = FILTER
                isForwardPointer heap)) /\
             (!xs l d.
                MEM (DataElement xs l d) heap2 <=>
                  (x = DataElement xs l d) \/
                  MEM (DataElement xs l d) heap) /\
             (isDataElement x ==>
              ({a | isSomeDataElement (heap_lookup a heap2)} =
                a INSERT {a | isSomeDataElement (heap_lookup a
                  heap)})) /\
             heap_store_rel heap heap2)`,
  (* the steps are above the statement (tools/overrides.py).  The
     same shape as IMP_heap_store_unused, with the element at the
     start of what was unused instead of at its end: the space is
     not empty, heap_lookup_SPLIT cuts the heap at the unused
     element, heap_store_lemma says what the store writes, and the
     lemmas about the regions of the store say the rest *)
  (STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* the unused space is not empty, because the element fits in it *)
    W(fun (asl,w as gl) ->
      let le = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "el_length" (lhand c)) gl in
      let x = rand (lhand (concl le)) in
      let sp = rand (concl le) in
      SUBGOAL_THEN (mk_neg (mk_eq (sp, `0`))) ASSUME_TAC THENL
       [MP_TAC (ISPEC x el_length_GT_0) THEN MP_TAC le THEN ARITH_TAC;
        ALL_TAC]) THEN
    (* so the heap holds the unused element, and is what is before
       it, it, and what follows *)
    W(fun gl ->
      let us = the_asm (hd_is "unused_space_inv") gl in
      STRIP_ASSUME_TAC (REWRITE_RULE[unused_space_inv_def] us)) THEN
    W(fun gl ->
      let imp = the_asm (fun c -> is_imp c && is_neg (lhand c) &&
                  is_eq (rand c) &&
                  hd_is "heap_lookup" (lhand (rand c))) gl in
      let ne = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                 rand (rand c) = `0`) gl in
      STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT (MP imp ne))) THEN
    REPEAT (FIRST_X_ASSUM (fun e ->
      let c = concl e in
      if not (is_eq c) || not (is_var (lhand c)) then fail() else
      SUBST_ALL_TAC e)) THEN
    (* and the store writes the element and the space that is left *)
    REWRITE_TAC[heap_store_unused_alt_def] THEN
    ASM_REWRITE_TAC[heap_lookup_PREFIX] THEN
    REWRITE_TAC[heap_store_lemma] THEN
    W(fun (asl,w) ->
      let pr = lhand (hd (conjuncts (snd (strip_exists w)))) in
      EXISTS_TAC (lhand pr)) THEN
    REWRITE_TAC[PAIR_EQ] THEN
    (* what is before the space holds data, and the element written
       is no shorter than one *)
    W(fun gl ->
      let du = the_asm (hd_is "data_up_to") gl in
      let le = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "el_length" (lhand c)) gl in
      ASSUME_TAC (REWRITE_RULE[data_up_to_APPEND] du) THEN
      ASSUME_TAC (ISPEC (rand (lhand (concl le))) el_length_GT_0)) THEN
    REPEAT CONJ_TAC THEN
    (* the length of what the store writes is the length of the
       element it replaces, and the heap is as long as it was *)
    TRY (SOLVED
          (REWRITE_TAC[heap_length_APPEND; heap_length_heap_expand;
                       heap_length_clauses; el_length_def;
                       ADD_CLAUSES] THEN
           ASM_ARITH_TAC)) THEN
    (* the forward pointers are the ones it had *)
    TRY (SOLVED
          (DISCH_TAC THEN
           REWRITE_TAC[heap_expand_def] THEN
           COND_CASES_TAC THEN
           ASM_REWRITE_TAC[FILTER_APPEND; FILTER; APPEND; APPEND_NIL;
                           isForwardPointer_def] THEN
           TRY MATCH_REDUCE_TAC THEN
           ASM_REWRITE_TAC[FILTER; APPEND; APPEND_NIL])) THEN
    (* and the data elements are the ones it had, and the one
       written *)
    TRY (SOLVED
          (REPEAT GEN_TAC THEN
           REWRITE_TAC[heap_expand_def] THEN
           COND_CASES_TAC THEN
           (let ds = [distinctness "heap_element"] in
            REWRITE_TAC (MEM_APPEND :: MEM :: APPEND ::
                         ds @ map GSYM ds)) THEN
           MESON_TAC[])) THEN
    (* the element written is where the goal says, the space it went
       into held no data, and what held data still does *)
    W(fun (asl,w as gl) ->
      let le = the_asm (fun c -> hd_is "<=" c &&
                 hd_is "el_length" (lhand c)) gl in
      let one = the_asm (fun c -> hd_is "<=" c &&
                  lhand c = `1`) gl in
      let ne0 = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                  rand (rand c) = `0`) gl in
      let ev = the_asm (fun c -> hd_is "ALL" c) gl in
      let e = lhand (concl le) in
      let sp = rand (concl le) in
      let x = rand e in
      let du = the_asm (hd_is "data_up_to") gl in
      let hp = el 1 (snd (strip_comb (concl du))) in
      let ha = lhand hp in
      let hb = rand (rand hp) in
      let args = [ha; sp; e; x; hb] in
      if is_imp w && hd_is "isDataElement" (lhand w) &&
         hd_is "unused_space_inv" (rand w) then
        (* the space that is left is unused space, and what is below
           it holds data: what was below it and the element *)
        (DISCH_TAC THEN
         REWRITE_TAC[unused_space_inv_def] THEN
         REPEAT CONJ_TAC THENL
          [DISCH_TAC THEN
           W(fun gl ->
             let ne = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                        rand (rand c) = `0` &&
                        hd_is "-" (lhand (rand c))) gl in
             ACCEPT_TAC (MP (ISPECL [ha; lhand (rand (concl ne));
                                     x; hb]
                               heap_lookup_alt_unused) ne));
           W(fun gl ->
             let bd = the_asm (fun c -> hd_is "<=" c &&
                        hd_is "heap_length" (rand c)) gl in
             MP_TAC bd) THEN
           REWRITE_TAC[heap_length_APPEND; heap_length_clauses;
                       heap_length_heap_expand; el_length_def;
                       ADD_CLAUSES] THEN
           ASM_ARITH_TAC;
           W(fun gl ->
             let isd = the_asm (hd_is "isDataElement") gl in
             let hpg = el 1 (snd (strip_comb (snd gl))) in
             let he = rand (lhand (rand hpg)) in
             ACCEPT_TAC (MATCH_MP (ISPECL [ha; x; he; hb]
                            data_up_to_alt) (CONJ ev isd)))])
      else if is_eq w && hd_is "heap_lookup" (lhand w) then
        REWRITE_TAC[heap_lookup_alt_at_start]
      else if is_neg w && hd_is "isSomeDataElement" (rand w) then
        (REWRITE_TAC[heap_lookup_PREFIX; isSomeDataElement_def] THEN
         (let ds = [distinctness "heap_element"] in
          REWRITE_TAC (injectivity "option" ::
                       NOT_EXISTS_THM :: ds @ map GSYM ds)) THEN
         REWRITE_TAC[])
      else if is_imp w && hd_is "isDataElement" (lhand w) then
        (DISCH_TAC THEN
         W(fun gl ->
           let isd = the_asm (hd_is "isDataElement") gl in
           ACCEPT_TAC (MATCH_MP (ISPECL args isSome_store_unused_alt)
             (CONJ ne0 (CONJ (REFL e) (CONJ one (CONJ le isd)))))))
      else if hd_is "heap_store_rel" w then
        ACCEPT_TAC (MATCH_MP (ISPECL args heap_store_rel_alt)
          (CONJ ne0 (CONJ (REFL e) (CONJ one le))))
      else ALL_TAC)));;

(* [local] *)
let heap_store_rel_lemma = prove
 (`heap_store_rel h1 h2 /\ (heap_lookup n h1 = SOME (DataElement ys l
  d)) ==>
     (heap_lookup n h2 = SOME (DataElement ys l d))`,
  (REWRITE_TAC[heap_store_rel_def;
               isSomeDataElement_def] THEN
   MESON_TAC[]));;

(* cons *)

(* [local] *)
let v_inv_SUBMAP_lemma = prove
 (`!ck w refs x f tf heap.
     v_inv conf w refs (x,f,tf,heap) ==>
       f SUBMAP f1 /\
       tf SUBMAP tf1 /\
       heap_store_rel heap heap1 ==>
         v_inv_ck ck conf w refs (x,f1,tf1,heap1)`,
  (* complete induction on the ck of the relation: the value of the
     invariant is taken apart with v_inv_def and the rule of the
     relation for that shape is applied, where the greater maps
     give the same values and the greater heap the same data
     elements.  What the rule asks of a value inside the value is
     the induction hypothesis at ck - 1 *)
  (let (vr,_,_) = v_inv_ck in
   let rl = CONJUNCTS vr in
   let vdef = v_inv_def in
   (* a data element of the heap is still there after the store *)
   let keep = prove
    (`!h1 h2 n e.
        heap_store_rel h1 h2 ==> heap_lookup n h1 = SOME e ==>
        isDataElement e ==> heap_lookup n h2 = SOME e`,
     REWRITE_TAC[heap_store_rel_def] THEN
     REPEAT STRIP_TAC THEN
     FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `n:num` th)) THEN
     ASM_REWRITE_TAC[isSomeDataElement_def;
                     injectivity "option"] THEN
     FIRST_X_ASSUM(MP_TAC o
                   REWRITE_RULE[isDataElement_def]) THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]) in
   (* the four shapes of a data element that the invariant uses.
      The theorem of the file that says this and more stands
      later in the file than this one does *)
   let isde4 = prove
    (`isDataElement (BlockRep tag ys1) /\
      isDataElement (Word64Rep (:'a) w) /\
      isDataElement (ThunkBlock ev v) /\
      isDataElement (Bignum i)`,
     REWRITE_TAC[isDataElement_def; BlockRep_def;
                 Word64Rep_def; ThunkBlock_def;
                 bignum_def] THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REPEAT CONJ_TAC THEN TRY COND_CASES_TAC THEN MESON_TAC[]) in
   let keep_of hsr hl =
     REWRITE_RULE[isde4] (MATCH_MP (MATCH_MP keep hsr) hl) in
   let KEEP_TAC =
     FIRST_ASSUM(fun hsr -> FIRST_ASSUM(fun hl ->
       MATCH_ACCEPT_TAC(keep_of hsr hl))) in
   let lt1 = ARITH_RULE `~(ck = 0) ==> ck - 1 < ck` in
   (* the b of a RefPtr that the two thunk rules ask to be false *)
   let NOT_VAR_TAC =
     FIRST_ASSUM(fun nb ->
       if is_neg(concl nb) && is_var(rand(concl nb))
       then SUBST_ALL_TAC(EQF_INTRO nb) else fail()) in
   let setup =
     MATCH_MP_TAC num_WF THEN X_GEN_TAC `ck:num` THEN
     DISCH_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN STRIP_TAC THEN
     CASES_ON_NAME "w" THEN USE_CHANGED [vdef] in
   (* a Number is a small one or a Bignum of the heap *)
   let c1 =
     COND_CASES_TAC THEN STRIP_TAC THEN SUBST_LHS_TAC THENL
      [MATCH_MP_TAC(el 0 rl) THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC(el 1 rl) THEN ASM_REWRITE_TAC[] THEN KEEP_TAC] in
   let c2 = STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
            MATCH_MP_TAC(el 2 rl) THEN KEEP_TAC in
   (* a Block is a BlockNil or a BlockRep whose elements the
      induction hypothesis carries over one by one *)
   let c3 =
     COND_CASES_TAC THEN STRIP_TAC THEN REPEAT SUBST_LHS_TAC THENL
      [MATCH_MP_TAC(el 7 rl) THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC(el 8 rl) THEN REPEAT CONJ_TAC THENL
        [FIRST_ASSUM MATCH_ACCEPT_TAC;
         DISCH_TAC THEN
         FIRST_ASSUM(fun a2th ->
           if can (term_match [] `EVERY2 (p:A->B->bool) l m`)
                  (concl a2th)
           then MP_TAC a2th else fail()) THEN
         MATCH_MP_TAC MONO_ALL2 THEN BETA_TAC THEN
         REPEAT STRIP_TAC THEN CK_IH_TAC;
         FIRST_ASSUM(fun sm -> FIRST_ASSUM(fun fl ->
           MATCH_ACCEPT_TAC(MATCH_MP FLOOKUP_SUBMAP (CONJ sm fl))));
         KEEP_TAC]] in
   let c4 = STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
            MATCH_ACCEPT_TAC(el 3 rl) in
   (* and a RefPtr is a plain reference or one of the two thunks,
      whose value and heap element the rule names and not its
      conclusion, so MESON applies the rule *)
   let d5 =
     FIRST_ASSUM(fun sm -> FIRST_ASSUM(fun fd ->
       let s = MATCH_MP (MATCH_MP SUBMAP_FAPPLY sm) fd in
       REPEAT SUBST_LHS_TAC THEN REWRITE_TAC[CONJUNCT2 s] THEN
       MATCH_MP_TAC(el 4 rl) THEN
       REWRITE_TAC[CONJUNCT1 s] THEN REPEAT CONJ_TAC THEN
       TRY(FIRST_ASSUM MATCH_ACCEPT_TAC))) in
   let d6 =
     NOT_VAR_TAC THEN
     FIRST_ASSUM(fun sm -> FIRST_ASSUM(fun fd ->
       let s = MATCH_MP (MATCH_MP SUBMAP_FAPPLY sm) fd in
       RULE_ASSUM_TRY(REWRITE_RULE[CONJUNCT2 s]) THEN
       REPEAT SUBST_LHS_TAC THEN
       REWRITE_TAC[CONJUNCT2 s] THEN
       FIRST_ASSUM(fun hsr -> FIRST_ASSUM(fun hl ->
         FIRST_ASSUM(fun ih ->
           ASM_MESON_TAC[el 5 rl; CONJUNCT1 s; keep_of hsr hl;
                         SPEC `ck - 1` ih; lt1]))))) in
   let d7 =
     NOT_VAR_TAC THEN
     FIRST_ASSUM(fun ih ->
       ASM_MESON_TAC[el 6 rl; SPEC `ck - 1` ih; lt1]) in
   let c5 =
     DISCH_THEN(DISJ_CASES_THEN2 STRIP_ASSUME_TAC
       (DISJ_CASES_THEN2 STRIP_ASSUME_TAC STRIP_ASSUME_TAC)) THENL
      [d5; d6; d7] in
   setup THENL [c1; c2; c3; c4; c5]));;

(* [local] *)
let v_inv_SUBMAP = prove
 (`!w x.
       f SUBMAP f1 /\ tf SUBMAP tf1 /\
       heap_store_rel heap heap1 /\
       v_inv conf w refs (x,f,tf,heap) ==>
       v_inv conf w refs (x,f1,tf1,heap1)`,
  (REPEAT STRIP_TAC THEN ASM_MESON_TAC[v_inv_eq; v_inv_SUBMAP_lemma]));;

let heap_store_rel_v_inv = prove
 (`!w x.
       heap_store_rel heap heap1 /\
       v_inv conf w refs (x,f,tf,heap) ==>
       v_inv conf w refs (x,f,tf,heap1)`,
  (REPEAT STRIP_TAC THEN MATCH_MP_TAC v_inv_SUBMAP THEN
   ASM_REWRITE_TAC[SUBMAP_REFL]));;

(* [local] *)
let heap_store_unused_alt_thm = prove
 (`!a n heap h1 h2 heap2 x.
     heap_split (a + n) heap = SOME (h1,h2) /\
     heap_store_unused_alt a n x heap = (heap2,T) /\
     unused_space_inv (a + el_length x) (n - el_length x) heap2 ==>
     (?h0. h1 = h0 ++ [Unused (n - 1)] /\
          heap = h1 ++ h2 /\ heap_length h0 = a /\
          heap2 = h0 ++ [x] ++ heap_expand (n - el_length x) ++ h2)`,
  (* the store goes where the unused element of the split sits: the
     split is as long as the space, so what is left of it after
     that element is empty, and then heap_store_lemma says what
     the heap becomes *)
  ((* the head constant of a term, by name *)
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   (* the assumption that a test picks out *)
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* an element of a heap is at least one word long *)
   let elpos = prove
    (`!y:(A,B)heap_element. 0 < el_length y`,
     GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `y:(A,B)heap_element`
       (cases_of `:(A,B)heap_element`)) THEN
     REWRITE_TAC[el_length_def] THEN ARITH_TAC) in
   (* the length of a heap, clause by clause *)
   let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) =
              el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   (* so a heap of no length is empty *)
   let hlen0 = prove
    (`!hb:((A,B)heap_element)list. heap_length hb = 0 ==> hb = []`,
     LIST_INDUCT_TAC THEN
     REWRITE_TAC[hlen_cl; NOT_CONS_NIL] THEN
     MP_TAC(ISPEC `h:(A,B)heap_element` elpos) THEN ARITH_TAC) in
   REPEAT GEN_TAC THEN
   REWRITE_TAC[heap_store_unused_alt_def] THEN
   COND_CASES_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
   POP_ASSUM(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
   STRIP_TAC THEN
   FIRST_ASSUM(fun hs ->
     MP_TAC(MATCH_MP heap_split_heap_length hs)) THEN
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   SUBGOAL_THEN `0 < n` ASSUME_TAC THENL
    [ASM_MESON_TAC[elpos; LTE_TRANS]; ALL_TAC] THEN
   FIRST_ASSUM(fun eq ->
     if is_eq (concl eq) && hd_is "APPEND" (lhand (concl eq))
     then SUBST_ALL_TAC (SYM eq) else fail()) THEN
   (* the lookup is inside the first half of the split *)
   W(fun (asl,w) ->
     let hl = grab asl (fun th ->
       hd_is "heap_lookup" (lhand (concl th))) in
     let ap = rand (lhand (concl hl)) in
     SUBGOAL_THEN (subst [lhand ap,ap] (concl hl)) ASSUME_TAC THENL
      [MP_TAC(REWRITE_RULE
         [data_to_word_memoryProof_heap_lookup_APPEND] hl) THEN
       ASM_SIMP_TAC[ARITH_RULE `0 < n ==> a < a + n`] THEN
       TRY(DISCH_THEN ACCEPT_TAC);
       ALL_TAC]) THEN
   FIRST_ASSUM(fun hl ->
     if hd_is "heap_lookup" (lhand (concl hl)) &&
        is_var (rand (lhand (concl hl)))
     then MP_TAC(MATCH_MP heap_lookup_SPLIT hl) else fail()) THEN
   DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
   FIRST_ASSUM(fun eq ->
     if is_eq (concl eq) && is_var (lhs (concl eq)) &&
        hd_is "APPEND" (rhs (concl eq))
     then SUBST_ALL_TAC eq else fail()) THEN
   (* what is left of the split after that element is empty *)
   W(fun (asl,w) ->
     MP_TAC(ISPEC (var_by_name "hb" (asl,w)) hlen0)) THEN
   ANTS_TAC THENL
    [FIRST_ASSUM(fun hl ->
       if is_eq (concl hl) &&
          hd_is "heap_length" (lhand (concl hl)) &&
          hd_is "+" (rand (concl hl))
       then MP_TAC(REWRITE_RULE[heap_length_APPEND; hlen_cl;
                                el_length_def] hl)
       else fail()) THEN
     MP_TAC(ASSUME `0 < n`) THEN
     FIRST_ASSUM(fun ae ->
       if is_eq (concl ae) && is_var (lhs (concl ae)) &&
          hd_is "heap_length" (rhs (concl ae))
       then SUBST1_TAC ae else fail()) THEN
     ARITH_TAC;
     ALL_TAC] THEN
   DISCH_THEN SUBST_ALL_TAC THEN
   W(fun (asl,w) -> EXISTS_TAC (var_by_name "ha" (asl,w))) THEN
   REPEAT CONJ_TAC THEN TRY(REWRITE_TAC[] THEN NO_TAC) THEN
   TRY(FIRST_ASSUM(fun ae -> ACCEPT_TAC (SYM ae))) THEN
   (* and the store puts what it stores where that element was *)
   FIRST_ASSUM(fun hs ->
     if hd_is "heap_store" (lhand (concl hs))
     then MP_TAC(REWRITE_RULE[GSYM APPEND_ASSOC; APPEND] hs)
     else fail()) THEN
   FIRST_ASSUM(fun ae ->
     if is_eq (concl ae) && is_var (lhs (concl ae)) &&
        hd_is "heap_length" (rhs (concl ae))
     then SUBST1_TAC ae else fail()) THEN
   REWRITE_TAC[heap_store_lemma; PAIR_EQ] THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM) (K ALL_TAC)) THEN
   REWRITE_TAC[GSYM APPEND_ASSOC; APPEND]));;

let heap_store_unused_alt_heap_lookup = prove
 (`!heap heap2 a k x n.
      heap_store_unused_alt a k x heap = (heap2,T) /\ n < a ==>
      heap_lookup n heap = heap_lookup n heap2`,
  (* the store into the unused space is a store at the address it
     keeps, so the lookup below that address gives the same; the
     induction is the one of the theorem about a store and a lookup
     that the file states further down, and HOL4 repeats it here as
     well *)
  (let hsl = prove
    (`!heap heap2 a (x:((A,B)heap_element)list) n.
        heap_store a x heap = (heap2,T) /\ n < a
        ==> heap_lookup n heap = heap_lookup n heap2`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
      [REWRITE_TAC[heap_store_def; PAIR_EQ];
       GEN_REWRITE_TAC (LAND_CONV o LAND_CONV o LAND_CONV)
         [heap_store_def] THEN
       COND_CASES_TAC THENL
        [ASM_REWRITE_TAC[ARITH_RULE `((n:num) < 0) <=> F`];
         ALL_TAC] THEN
       COND_CASES_TAC THENL
        [REWRITE_TAC[PAIR_EQ]; ALL_TAC] THEN
       PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
       REWRITE_TAC[PAIR_EQ] THEN
       DISCH_THEN(CONJUNCTS_THEN2
         (CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
            (fun th -> SUBST_ALL_TAC(EQT_INTRO th)))
         ASSUME_TAC) THEN
       ONCE_REWRITE_TAC[heap_lookup_def] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_EXISTS_TAC THEN
       ASM_REWRITE_TAC[] THEN ARITH_ASM_TAC]) in
   REPEAT GEN_TAC THEN
   REWRITE_TAC[heap_store_unused_alt_def] THEN
   COND_CASES_TAC THENL
    [MATCH_ACCEPT_TAC hsl;
     REWRITE_TAC[PAIR_EQ]]));;

(* [local] *)
let heap_split_heap_store = prove
 (`!heap e h1 h2 a y heap2.
     heap_split e heap = SOME (h1,h2) /\
     heap_store a y heap = (heap2,T) /\ e <= a ==>
     (?h3. heap_split e heap2 = SOME (h1,h3))`,
  (* a store above the split leaves the first half of the split as
     it was: the store goes down the heap one element at a time and
     the induction carries the split along *)
  (let stripconj =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) in
   let aux = prove
    (`!(heap:((A,B)heap_element) list) e h1 h2 a y heap2.
        heap_split e heap = SOME (h1,h2) /\
        heap_store a y heap = (heap2,T) /\ e <= a
        ==> ?h3. heap_split e heap2 = SOME (h1,h3)`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[heap_split_def; heap_store_def] THENL
      [REWRITE_TAC[PAIR_EQ];
       ALL_TAC] THEN
     ASM_CASES_TAC `e = 0` THEN ASM_REWRITE_TAC[] THENL
      [REWRITE_TAC[injectivity "option"; PAIR_EQ] THEN
       STRIP_TAC THEN stripconj THEN VAR_EQ_TAC THEN
       W(fun (asl,w) ->
         EXISTS_TAC (rand(lhs(snd(strip_exists w))))) THEN
       REWRITE_TAC[heap_split_0];
       ALL_TAC] THEN
     ASM_CASES_TAC `e < el_length (h:(A,B)heap_element)` THEN
     ASM_REWRITE_TAC[distinctness "option"] THEN
     STRIP_TAC THEN
     SUBGOAL_THEN
       `~(a = 0) /\ ~(a < el_length (h:(A,B)heap_element))`
       STRIP_ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     RULE_ASSUM_TAC(REWRITE_RULE
       [ASSUME `~(a = 0)`;
        ASSUME `~(a < el_length (h:(A,B)heap_element))`]) THEN
     FIRST_X_ASSUM(fun st ->
       if (try fst(dest_const(fst(strip_comb(rhs(concl st))))) =
                "," with Failure _ -> false)
       then MP_TAC st else fail()) THEN
     MP_TAC(ISPEC
       `heap_store (a - el_length (h:(A,B)heap_element))
          (y:((A,B)heap_element) list) t`
       PAIR_SURJECTIVE) THEN
     DISCH_THEN(X_CHOOSE_THEN `xs1:((A,B)heap_element) list`
       (X_CHOOSE_THEN `c1:bool` ASSUME_TAC)) THEN
     ASM_REWRITE_TAC[] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[PAIR_EQ] THEN STRIP_TAC THEN VAR_EQ_TAC THEN
     RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `c1:bool`]) THEN
     FIRST_X_ASSUM(fun sp ->
       if (try fst(dest_const(rator(rhs(concl sp)))) = "SOME"
           with Failure _ -> false)
       then MP_TAC sp else fail()) THEN
     EVERY_CASE_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option";
                 PAIR_EQ] THEN
     STRIP_TAC THEN stripconj THEN VAR_EQ_TAC THEN
     SUBGOAL_THEN `e - el_length (h:(A,B)heap_element) <=
                   a - el_length (h:(A,B)heap_element)`
       ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     FIRST_X_ASSUM(fun ih ->
       FIRST_ASSUM(fun a1 -> FIRST_ASSUM(fun a2 -> FIRST_ASSUM(fun a3 ->
         MP_TAC(MATCH_MP ih (CONJ a1 (CONJ a2 a3))) THEN
         DISCH_THEN(X_CHOOSE_TAC `h3:((A,B)heap_element) list`) THEN
         EXISTS_TAC `h3:((A,B)heap_element) list` THEN
         ASM_REWRITE_TAC[heap_split_def] THEN
         MATCH_REDUCE_TAC THEN REWRITE_TAC[]))))) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

(* [local] *)
let heap_store_unused_alt_gen_state_ok = prove
 (`heap_store_unused_alt a k x heap = (heap2,T) /\
   gen_state_ok a (a + k) heap gens ==>
   gen_state_ok (a + el_length x) (a + k) heap2 gens`,
  (* and the same of the store at the low end: the references start
     where they started, and a is higher by the element, which no
     start of a generation is above *)
  (
   let transfer = prove
    (`!(hp:((A,B)heap_element)list) hp2 aa kk xx ss.
        heap_store aa ([xx] ++ heap_expand (kk - el_length xx)) hp =
          (hp2,T) /\
        ss <= aa /\ gen_start_ok hp (aa + kk) ss
        ==> gen_start_ok hp2 (aa + kk) ss`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[gen_start_ok_def] THEN
     DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
       (REPEAT_TCL CHOOSE_THEN
         (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
     FIRST_ASSUM(fun hs -> FIRST_ASSUM(fun sp -> FIRST_ASSUM(fun le ->
       MP_TAC(MATCH_MP heap_split_heap_store
         (CONJ sp (CONJ hs le)))))) THEN
     DISCH_THEN(X_CHOOSE_THEN `h3:((A,B)heap_element)list`
       ASSUME_TAC) THEN
     ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[]) in
   STRIP_TAC THEN CASES_ON_NAME "gens" THEN
   RULE_ASSUM_TAC(REWRITE_RULE[gen_state_ok_def]) THEN
   REWRITE_TAC[gen_state_ok_def] THEN
   USE_CHANGED [heap_store_unused_alt_def] THEN
   COND_CASES_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
   FIRST [DISCH_THEN(fun th ->
            CONTR_TAC(REWRITE_RULE[] (CONJUNCT2 th)));
          DISCH_TAC] THEN
   FIRST_ASSUM(fun gs ->
     let c1 = CONJUNCT1 gs and c2 = CONJUNCT2 gs in
     CONJ_TAC THENL
      [MATCH_MP_TAC ALL_IMP THEN EXISTS_TAC (lhand (concl c1)) THEN
       CONJ_TAC THENL
        [GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN ASM_ARITH_TAC;
         ACCEPT_TAC c1];
       MATCH_MP_TAC ALL_IMP THEN
       EXISTS_TAC (lhand (concl c2)) THEN
       CONJ_TAC THENL
        [GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC transfer THEN
         W(fun (asl,w) ->
           let hs = find (fun (_,th) ->
             (try fst(dest_const(fst(strip_comb(lhand(concl th))))) =
                  "heap_store"
              with Failure _ -> false)) asl in
           EXISTS_TAC (el 2 (snd(strip_comb
             (lhand (concl (snd hs))))))) THEN
         W(fun gl -> EXISTS_TAC (var_by_name "x" gl)) THEN
         ASM_REWRITE_TAC[] THEN
         FIRST_ASSUM(fun m ->
           ACCEPT_TAC(MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] c1) m));
         ACCEPT_TAC c2]])));;

(* [simp] *)
let isDataElement_lemmas = prove
 (`isDataElement (DataElement x1 x2 x3) /\
    isDataElement (BlockRep tag ys1) /\
    isDataElement (Word64Rep (:'a) w) /\
    isDataElement (RefBlock ws) /\
    isDataElement (Bytes y1 y2 y3 y4) /\
    isDataElement (ThunkBlock ev v) /\
    isDataElement (Bignum i)`,
  (REWRITE_TAC[isDataElement_def; BlockRep_def;
               Word64Rep_def; RefBlock_def;
               bytes_def; ThunkBlock_def;
               bignum_def] THEN
   PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REPEAT CONJ_TAC THEN TRY COND_CASES_TAC THEN MESON_TAC[]));;

(* --- Allocating multiple cons-elements in one go --- *)

let list_to_BlockReps_def = cake_define_list
  [`list_to_BlockReps conf t a [] = ARB`;
   `list_to_BlockReps conf t a (h :: l) =
      (match l with
        [] -> [BlockRep cons_tag [h; t]] | _28 ->
          BlockRep cons_tag
            [h; gc_shared_Pointer (a + 3) (wordLang_Word (ptr_bits
              conf cons_tag 2))] ::
              list_to_BlockReps conf t (a + 3) l)`];;

let list_to_BlockReps_heap_length = prove
 (`!xs len.
     ~(xs = []) ==>
     heap_length (list_to_BlockReps conf x len xs) =
      3 * LENGTH xs`,
  (* the induction hypothesis has a hypothesis (the tail is not
     empty), so the step is a SIMP and not a REWRITE *)
  (LIST_INDUCT_TAC THEN REWRITE_TAC[NOT_CONS_NIL] THEN GEN_TAC THEN
   ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
   CASES_ON_NAME "t" THEN MATCH_REDUCE_TAC THEN
   ASM_SIMP_TAC[heap_length_NIL; heap_length_CONS;
                BlockRep_def; el_length_def;
                LENGTH; NOT_CONS_NIL] THEN
   ARITH_TAC));;

let heap_lookup_heap_length = prove
 (`heap_lookup (heap_length h1) (h1 ++ h2) = heap_lookup 0 h2`,
  (REWRITE_TAC[heap_lookup_APPEND; LT_REFL; SUB_REFL]));;

let list_to_BlockReps_heap_lookup_0 = prove
 (`~(xs = []) ==>
   isSomeDataElement (heap_lookup 0 (list_to_BlockReps conf x len
     xs))`,
  (LIST_CASES_TAC ["xs"] THEN REWRITE_TAC[NOT_CONS_NIL] THEN
   ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
   LIST_CASES_TAC ["t"] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[heap_lookup_def; isSomeDataElement_def;
               BlockRep_def] THEN
   MESON_TAC[]));;

let list_to_BlockReps_isDataElement = prove
 (`!xs x len.
     ~(xs = []) ==>
     EVERY isDataElement (list_to_BlockReps conf x len xs)`,
