(* HOL4 data_to_word_memoryProofScript.sml:2388-2390: a proof *)

let list_to_BlockReps_MEM = prove
 (`MEM v (list_to_BlockReps conf x len (h :: t)) ==>
     MEM v (list_to_BlockReps conf x (len + 3) t) \/
     v = BlockRep cons_tag
           [h; gc_shared_Pointer (len + 3) (wordLang_Word (ptr_bits
             conf cons_tag 2))] \/
     v = BlockRep cons_tag [h; x]`,
  (ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
   LIST_CASES_TAC ["t"] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[MEM] THEN MESON_TAC[]));;

(* [local] *)
let list_to_BlockReps_Pointer_lem = prove
 (`!xs len ys l d ptr u.
      let allocd = list_to_BlockReps conf x len xs in ~(xs = []) /\
        MEM (DataElement ys l d) allocd /\
        MEM (gc_shared_Pointer ptr u) ys ==>
          gc_shared_Pointer ptr u = x \/
          MEM (gc_shared_Pointer ptr u) xs \/
          (ptr < len + heap_length allocd /\
           ptr > len /\
           isSomeDataElement
             (heap_lookup (ptr - len) allocd))`,
  (* the induction of the source over the list.  The element is a
     block of the rest of the list, which the induction hypothesis
     is about, or the block that points at the next one (and then
     the pointer is the address of the next block, which
     list_to_BlockReps_heap_lookup_0 says is an element), or the
     last block, which holds the tail of the list *)
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   CONV_TAC(DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[NOT_CONS_NIL] THEN
   CASES_ON_NAME "t" THENL
    [(* one element, whose block holds the head and the tail *)
     ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[MEM; BlockRep_def; injectivity "heap_element"] THEN
     STRIP_TAC THEN VAR_EQ_TAC THEN
     RULE_ASSUM_TAC(REWRITE_RULE[MEM]) THEN
     ASM_REWRITE_TAC[MEM] THEN ASM_MESON_TAC[];
     ALL_TAC] THEN
   STRIP_TAC THEN
   (* the block of the element is one of the three that
      list_to_BlockReps_MEM gives *)
   FIRST_ASSUM (fun a1 ->
     if not (hd_is "MEM" (concl a1) &&
             hd_is "list_to_BlockReps" (rand (concl a1))) then fail()
     else STRIP_ASSUME_TAC
            (MATCH_MP (GEN_ALL list_to_BlockReps_MEM) a1)) THENL
    [(* a block of the rest, which the induction hypothesis is
         about *)
     FIRST_X_ASSUM (fun ih ->
       if not (is_forall (concl ih)) then fail() else
       let ih2 = REWRITE_RULE[NOT_CONS_NIL]
                   (CONV_RULE(DEPTH_CONV let_CONV) ih) in
       FIRST_ASSUM (fun a1 -> FIRST_ASSUM (fun a2 ->
         MP_TAC (MATCH_MP ih2 (CONJ a1 a2))))) THEN
     STRIP_TAC THENL
      [ASM_MESON_TAC[];
       ASM_REWRITE_TAC[MEM] THEN ASM_MESON_TAC[];
       DISJ2_TAC THEN DISJ2_TAC THEN
       ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
       MATCH_REDUCE_TAC THEN
       REWRITE_TAC[heap_length_CONS; BlockRep_def; el_length_def;
                   LENGTH; heap_lookup_def] THEN
       CONV_TAC NUM_REDUCE_CONV THEN
       REPEAT CONJ_TAC THENL
        [ASM_ARITH_TAC;
         ASM_ARITH_TAC;
         ASM_SIMP_TAC[ARITH_RULE
                        `ptr > len + 3 ==> ~(ptr - len = 0)`;
                      ARITH_RULE
                        `ptr > len + 3 ==> ~(ptr - len < 3)`;
                      ARITH_RULE
                        `ptr > len + 3
                         ==> ptr - len - 3 = ptr - (len + 3)`] THEN
         FIRST_ASSUM ACCEPT_TAC]];
     (* or the block that points at the next one *)
     RULE_ASSUM_TAC(REWRITE_RULE[BlockRep_def;
                                 injectivity "heap_element"]) THEN
     SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
     RULE_ASSUM_TAC(REWRITE_RULE[MEM]) THEN
     FIRST_X_ASSUM (fun mm ->
       if not (is_disj (concl mm)) then fail() else
       DISJ_CASES_THEN2 (fun e -> REWRITE_TAC[MEM] THEN
                                  MESON_TAC[e])
         (fun e ->
           MP_TAC (REWRITE_RULE[injectivity "heap_address"] e))
         mm) THEN
     STRIP_TAC THEN VAR_EQ_TAC THEN
     DISJ2_TAC THEN DISJ2_TAC THEN
     REPEAT CONJ_TAC THENL
      [ASM_SIMP_TAC[GEN_ALL list_to_BlockReps_heap_length;
                    NOT_CONS_NIL; LENGTH] THEN
       ARITH_TAC;
       ARITH_TAC;
       ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
       MATCH_REDUCE_TAC THEN
       REWRITE_TAC[heap_lookup_def; BlockRep_def; el_length_def;
                   LENGTH] THEN
       CONV_TAC NUM_REDUCE_CONV THEN
       REWRITE_TAC[ARITH_RULE `(len + 3) - len = 3`] THEN
       CONV_TAC NUM_REDUCE_CONV THEN
       MATCH_MP_TAC (GEN_ALL list_to_BlockReps_heap_lookup_0) THEN
       REWRITE_TAC[NOT_CONS_NIL]];
     (* or the block that holds the tail *)
     RULE_ASSUM_TAC(REWRITE_RULE[BlockRep_def;
                                 injectivity "heap_element"]) THEN
     SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
     RULE_ASSUM_TAC(REWRITE_RULE[MEM]) THEN
     ASM_REWRITE_TAC[MEM] THEN ASM_MESON_TAC[]]));;

(* HOL4 data_to_word_memoryProofScript.sml:2435-2437: a theorem that
   HOL4 states as the value of an ML expression:
   list_to_BlockReps_Pointer *)

let list_to_v_get_refs = prove
 (`!xs t r ts.
     MEM r (get_refs (list_to_v ts t xs)) ==>
       (?x. (MEM x xs \/ x = t) /\ MEM r (get_refs x))`,
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[dataSem_list_to_v_def] THEN DISCH_TAC THEN
     EXISTS_TAC `t:dataSem_v` THEN ASM_REWRITE_TAC[];
     REWRITE_TAC[dataSem_list_to_v_def; get_refs_def;
                 MAP; FLAT; APPEND_NIL; MEM_APPEND; MEM] THEN
     STRIP_TAC THEN ASM_MESON_TAC[]]));;

let v_inv_lemma = prove
 (`!ck v refs y x f tf.
     v_inv conf v refs (x,f,tf,ha ++ heap_expand sp ++ hb) ==>
       0 < heap_length hs /\
       heap_length hs <= sp ==>
         v_inv_ck ck conf v refs (x,f,tf,
                            ha ++ hs ++ heap_expand (sp -
                              heap_length hs) ++ hb)`,
  (* the heap grows by the hs that is taken out of its unused
     space, and that is a heap_store_rel: a data element of the old
     heap is in ha or in hb, the unused space holds none, and the
     two middle parts are of a length.  So v_inv_SUBMAP_lemma
     carries the invariant over, with the two maps unchanged *)
  (let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) =
              el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   let hlen_exp = prove
    (`!n. heap_length (heap_expand n) = n`,
     GEN_TAC THEN REWRITE_TAC[heap_expand_def] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[hlen_cl; el_length_def] THEN
     ASM_ARITH_TAC) in
   (* the unused space holds no data element at all: its one
      element is an Unused, and past it the lookup is of [] *)
   let isde_rws = [isSomeDataElement_def;
                   distinctness "option"; injectivity "option";
                   distinctness "heap_element"] in
   let exp_none = prove
    (`!n m. ~(isSomeDataElement
                (heap_lookup m
                   (heap_expand n:((A,B)heap_element)list)))`,
     REPEAT GEN_TAC THEN REWRITE_TAC[heap_expand_def] THEN
     COND_CASES_TAC THEN
     REWRITE_TAC(heap_lookup_def :: el_length_def ::
                 isde_rws) THEN
     REPEAT COND_CASES_TAC THEN
     REWRITE_TAC(heap_lookup_def :: isde_rws)) in
   let expand_rel = prove
    (`!ha hs hb sp.
        0 < heap_length hs /\ heap_length hs <= sp
        ==> heap_store_rel (ha ++ heap_expand sp ++ hb)
              (ha ++ hs ++ heap_expand (sp - heap_length hs) ++ hb)`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     REWRITE_TAC[heap_store_rel_def] THEN
     X_GEN_TAC `n:num` THEN
     REWRITE_TAC[GSYM APPEND_ASSOC] THEN
     REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND; hlen_exp;
                 heap_length_APPEND] THEN
     (* the three parts of the old heap, and of the new one: the
        splits are the same, because the lookup of a data element
        falls in ha or in hb either way *)
     COND_CASES_TAC THEN REWRITE_TAC[exp_none] THEN
     COND_CASES_TAC THEN REWRITE_TAC[exp_none] THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
     DISCH_TAC THEN AP_THM_TAC THEN AP_TERM_TAC THEN
     ASM_ARITH_TAC) in
   REPEAT GEN_TAC THEN DISCH_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun vi ->
     MATCH_MP_TAC(MATCH_MP v_inv_SUBMAP_lemma vi)) THEN
   REWRITE_TAC[SUBMAP_REFL] THEN
   MATCH_MP_TAC expand_rel THEN ASM_REWRITE_TAC[]));;

(* v_inv_lemma[allow_rebind] *)
let data_to_word_memoryProof_v_inv_lemma = prove
 (`!conf v refs x f tf hs ha hb sp.
    0 < heap_length hs /\
    heap_length hs <= sp /\
    v_inv conf v refs (x,f,tf,ha ++ heap_expand sp ++ hb) ==>
    v_inv conf v refs (x,f,tf,ha ++ hs ++ heap_expand (sp -
      heap_length hs) ++ hb)`,
  (REPEAT STRIP_TAC THEN ASM_MESON_TAC[v_inv_eq; v_inv_lemma]));;

let v_inv_LIST_REL = prove
 (`!l1 l2.
     0 < heap_length hs /\
     heap_length hs <= sp /\
     LIST_REL (\z y. v_inv conf y refs
       (z,f,tf,ha ++ heap_expand sp ++ hb)) l1 l2 ==>
     LIST_REL (\z y. v_inv conf y refs
       (z,f,tf,ha ++ hs ++ heap_expand (sp - heap_length hs) ++
         hb)) l1 l2`,
  (REWRITE_TAC[LIST_REL_EL_EQN] THEN REPEAT STRIP_TAC THEN
   ASM_REWRITE_TAC[] THEN
   MATCH_MP_TAC data_to_word_memoryProof_v_inv_lemma THEN
   ASM_SIMP_TAC[]));;

let bind_each_def = cake_define_list
  [`bind_each tf ts (k:num) i 0 = tf`;
   `bind_each tf ts (k:num) i (SUC n) = bind_each tf (ts + 1) (k +
  i) i n |+ (ts,k)`];;

let bind_each_MONO = prove
 (`!n t1 t2 tf k i.
    t1 < t2 /\ (!t. t IN FDOM tf ==> t < t1) ==> ~(t1 IN FDOM
      (bind_each tf t2 k i n))`,
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   REWRITE_TAC[bind_each_def] THENL
    [ASM_MESON_TAC[LT_REFL];
     REWRITE_TAC[FDOM_FUPDATE; IN_INSERT; DE_MORGAN_THM] THEN
     CONJ_TAC THENL
      [ASM_ARITH_TAC;
       FIRST_X_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
        [ASM_ARITH_TAC; ASM_REWRITE_TAC[]]]]));;

let bind_each_SUBMAP = prove
 (`!n tf ts k i.
    (!t. t IN FDOM tf ==> t < ts) ==> tf SUBMAP bind_each tf ts k i
      n`,
  (* every binding of tf is below ts and bind_each adds none below
     it, so what it adds is on top of tf *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
   REWRITE_TAC[bind_each_def] THENL
    [MATCH_ACCEPT_TAC SUBMAP_REFL;
     REWRITE_TAC[SUBMAP; FDOM_FUPDATE; IN_INSERT;
                 FAPPLY_FUPDATE_THM] THEN
     GEN_TAC THEN DISCH_TAC THEN
     SUBGOAL_THEN `~((x:num) = ts)` ASSUME_TAC THENL
      [FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `x:num` th)) THEN
       ASM_REWRITE_TAC[] THEN ARITH_TAC;
       ALL_TAC] THEN
     ASM_REWRITE_TAC[] THEN
     FIRST_X_ASSUM(fun ih ->
       MP_TAC(SPECL [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`]
                    ih)) THEN
     ANTS_TAC THENL
      [GEN_TAC THEN DISCH_TAC THEN
       FIRST_X_ASSUM(MP_TAC o SPEC `t:num`) THEN
       ASM_REWRITE_TAC[] THEN ARITH_TAC;
       REWRITE_TAC[SUBMAP] THEN
       DISCH_THEN(fun th -> MP_TAC(SPEC `x:num` th)) THEN
       ASM_REWRITE_TAC[]]]));;

let v_inv_list_to_v_lem = prove
 (`!rs xs t rt ha hb sp ts.
     let hm = list_to_BlockReps conf rt (heap_length ha) rs in
       ~(rs = []) /\
       v_inv conf t refs (rt,f,tf,ha ++ heap_expand sp ++ hb) /\
       LIST_REL (\v x. v_inv conf v refs (x,f,tf,ha ++ heap_expand sp
         ++ hb)) xs rs /\
       heap_length hm <= sp /\ (!t. t IN FDOM tf ==> t < ts) ==>
       v_inv conf (list_to_v ts t xs) refs
         (gc_shared_Pointer (heap_length ha) (wordLang_Word (ptr_bits
           conf cons_tag 2)),
          f,bind_each tf ts (heap_length ha) 3 (LENGTH xs),
          ha ++ hm ++ heap_expand (sp - heap_length hm) ++ hb)`,
(* the complete induction of the source, on the length of the list
   of the addresses, and then two cases.
     One address: the blocks of the cons are the one cons that
   holds the value and the tail of the list of the source, so the
   statement asks of that cons what the clause of v_inv for a Block
   asks -- the two values of it are the ones of the invariant that
   is given, over the heap that the cons was taken out of the
   unused space of (v_inv_lemma) and the timestamps that the cons
   binds (v_inv_SUBMAP with bind_each_SUBMAP, the timestamp of this
   cons being a new one); the timestamp of the cons is bound to the
   address of it (bind_each at one), the two words of it are what
   the pointer of the statement says, and the cell is the first one
   past ha (heap_lookup_APPEND1).
     More than one: the first cons holds the value and a pointer
   three words on, to the blocks of the tail, and the hypothesis of
   the induction gives the invariant of the tail at the heap that
   this cons left (its bounds are the bounds of the statement less
   the three words of the cons, its values are carried over by
   v_inv_LIST_REL -- which speaks of the addresses first, so the
   relation is swapped into it and back out -- and its timestamps
   start one later).  What is left of the goal is the same as in
   the case of one address, with the invariant of the tail in the
   place of the invariant of the tail's value: it is the one that
   the hypothesis gave, at the timestamp of this cons added to the
   map (bind_each_MONO says that the timestamp is not in it
   already) *)
  ((let hsr_refl = prove
   (`!heap:((A,B)heap_element)list. heap_store_rel heap heap`,
    REWRITE_TAC[heap_store_rel_def]) in
  let nrm = [GSYM APPEND_ASSOC; APPEND; heap_length_APPEND;
             heap_length_clauses; BlockRep_def; el_length_def;
             LENGTH;
             ARITH_RULE `!a b c. (a - b) - c = a - (b + c)`] in
  let red3 th =
    CONV_RULE NUM_REDUCE_CONV
      (REWRITE_RULE[heap_length_clauses; el_length_def; LENGTH]
        th) in
  (* the assumptions that the steps are built from *)
  let the_fdom asl =
    grab_asm (fun th ->
      is_forall (concl th) &&
      can (find_term (hd_is "FDOM")) (concl th)) asl in
  let the_vi_t asl =
    grab_asm (fun th ->
      hd_is "v_inv" (concl th) &&
      el 1 (snd (strip_comb (concl th))) = `t:dataSem_v`) asl in
  let the_bnd asl =
    grab_asm (fun th ->
      hd_is "<=" (concl th) && hd_is "+" (lhand (concl th)) &&
      can (find_term (hd_is "list_to_BlockReps")) (concl th)) asl in
  let from_bnd =
    W(fun (asl,gl) -> MP_TAC (the_bnd asl)) THEN ARITH_TAC in
  (* the part of the heap that the blocks of the cons take *)
  let goal_hs gl =
    lhand (find_term (fun t ->
      hd_is "APPEND" t &&
      (try hd_is "heap_expand" (lhand (rand t))
       with Failure _ -> false)) gl) in
  (* the induction of the source, on the length of the list of
     the addresses *)
  let IND_RS =
    W(fun (asl,gl) ->
      let rs = hd (fst (strip_forall gl)) in
      let el_ty = hd (snd (dest_type (type_of rs))) in
      MEASURE_INDUCT_TAC
        (inst [el_ty,`:A`] `LENGTH:(A)list->num`)) in
  (* a list is empty or a head and a tail, with names for the two;
     and a list that is not empty is a head and a tail *)
  let SPLIT_LIST vnm nm1 nm2 =
    W(fun (asl,gl) ->
      let all = list_mk_conj (gl :: map (concl o snd) asl) in
      let v = find_term (fun t ->
        is_var t && fst (dest_var t) = vnm) all in
      let ety = hd (snd (dest_type (type_of v))) in
      let fs = frees all in
      let a = variant fs (mk_var (nm1, ety)) in
      let b = variant (a :: fs) (mk_var (nm2, type_of v)) in
      MP_TAC (ISPEC v list_CASES) THEN
      DISCH_THEN (DISJ_CASES_THEN2 SUBST_ALL_TAC
        (X_CHOOSE_THEN a (X_CHOOSE_THEN b SUBST_ALL_TAC)))) in
  let CONS_SPLIT nm1 nm2 vnm =
    W(fun (asl,gl) ->
      let all = list_mk_conj (gl :: map (concl o snd) asl) in
      let v = find_term (fun t ->
        is_var t && fst (dest_var t) = vnm) all in
      let ety = hd (snd (dest_type (type_of v))) in
      let fs = frees all in
      let a = variant fs (mk_var (nm1, ety)) in
      let b = variant (a :: fs) (mk_var (nm2, type_of v)) in
      MP_TAC (ISPEC v list_CASES) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN (X_CHOOSE_THEN a
        (X_CHOOSE_THEN b SUBST_ALL_TAC))) in
  (* a list of no addresses is not one *)
  let base_vl =
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_X_ASSUM (fun th ->
      if not (hd_is "<=" (concl th)) then fail() else
      MP_TAC (MATCH_MP (ARITH_RULE `!n. n <= 0 ==> n = 0`) th)) THEN
    ASM_REWRITE_TAC[LENGTH_EQ_NIL] in
  (* the timestamp of this cons is a new one, and the list of the
     addresses is a head and a tail *)
  let pre_vl =
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    (SUBGOAL_THEN `~((ts:num) IN FDOM (tf:(num,num)fmap))`
       ASSUME_TAC THENL
      [FIRST_ASSUM (fun th ->
         if not (can (find_term (hd_is "FDOM")) (concl th)) ||
            not (is_forall (concl th)) then fail() else
         MP_TAC (SPEC `ts:num` th)) THEN
       REWRITE_TAC[LT_REFL] THEN DISCH_THEN ACCEPT_TAC;
       ALL_TAC]) THEN
    CONS_SPLIT "r" "rr" "rs" in
  (* the invariant of a value over the heap and the timestamps as
     they were, at the heap and the timestamps that the cons
     made *)
  let grow_tf =
    W(fun (asl,gl) ->
      let vi = grab_asm (fun th ->
        hd_is "v_inv" (concl th) &&
        el 1 (snd (strip_comb (concl th))) =
          el 1 (snd (strip_comb gl)) &&
        el 0 (tparts (el 3 (snd (strip_comb (concl th))))) =
          el 0 (tparts (el 3 (snd (strip_comb gl))))) asl in
      let be = find_term (hd_is "bind_each") gl in
      let args = snd (strip_comb be) in
      let sub = MP (SPECL [el 4 args; el 0 args; el 1 args;
        el 2 args; el 3 args] bind_each_SUBMAP) (the_fdom asl) in
      let ps = tparts (el 3 (snd (strip_comb (concl vi)))) in
      ACCEPT_TAC (MATCH_MP v_inv_SUBMAP
        (CONJ (ISPEC (el 1 ps) SUBMAP_REFL)
          (CONJ sub (CONJ (ISPEC (el 3 ps) hsr_refl) vi))))) in
  (* the bound of the unused space that the definition gave *)
  let the_spb =
    W(fun (asl,gl) ->
      let th = grab_asm (fun t ->
        hd_is "<=" (concl t) &&
        can (find_term (hd_is "list_to_BlockReps")) (concl t)) asl in
      ACCEPT_TAC (CONV_RULE (TOP_DEPTH_CONV MATCH_CONV)
        (ONCE_REWRITE_RULE[list_to_BlockReps_def] th))) in
  (* one address: the cons holds the value and the tail of the
     list of the source, which is the tail of the statement *)
  let single_pre =
    ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
    MATCH_REDUCE_TAC THEN
    SPLIT_LIST "xs" "x" "xs2" THEN
    RULE_ASSUM_TRY (REWRITE_RULE[ALL2]) THEN
    TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
    SPLIT_LIST "xs2" "x2" "xs3" THEN
    RULE_ASSUM_TRY (REWRITE_RULE[ALL2]) THEN
    TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
    REWRITE_TAC[dataSem_list_to_v_def; LENGTH] in
  let single_vl =
    single_pre THEN
    REWRITE_TAC[v_inv_def; NOT_CONS_NIL] THEN
    W(fun (asl,gl) ->
      let bl = find_term (fun t ->
        hd_is "BlockRep" t && hd_is "CONS" (rand t)) gl in
      let ptr = find_term (fun t ->
        hd_is "heap_length" t && is_var (rand t)) gl in
      MAP_EVERY EXISTS_TAC [ptr; rand bl]) THEN
    REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[ALL2] THEN CONJ_TAC THEN
      (MATCH_MP_TAC data_to_word_memoryProof_v_inv_lemma THEN
       REPEAT CONJ_TAC THENL
        [REWRITE_TAC[heap_length_clauses; BlockRep_def;
           el_length_def; LENGTH] THEN
         ARITH_TAC;
         the_spb;
         grow_tf]);
      REWRITE_TAC[ONE; bind_each_def; FLOOKUP_UPDATE];
      SIMP_TAC[heap_lookup_APPEND1; LE_REFL; SUB_REFL] THEN
      REWRITE_TAC[APPEND; heap_lookup_def]] in
  (* more than one address: the cons holds the value and a pointer
     to the blocks of the tail, three words on *)
  let cons_pre =
    ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
    MATCH_REDUCE_TAC THEN
    SPLIT_LIST "xs" "x" "xs2" THEN
    RULE_ASSUM_TRY (REWRITE_RULE[ALL2]) THEN
    TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
    ONCE_REWRITE_TAC[dataSem_list_to_v_def] THEN
    REWRITE_TAC[LENGTH] THEN
    FIRST_X_ASSUM (fun th ->
      if not (is_conj (concl th)) then fail() else
      CONJUNCTS_THEN ASSUME_TAC th) in
  let cons_bnd =
    FIRST_ASSUM (fun th ->
      if not (hd_is "<=" (concl th)) ||
         not (can (find_term (hd_is "list_to_BlockReps"))
                (concl th))
      then fail() else
      ASSUME_TAC (CONV_RULE NUM_REDUCE_CONV
        (REWRITE_RULE[heap_length_clauses; BlockRep_def;
           el_length_def; LENGTH]
          (CONV_RULE (TOP_DEPTH_CONV MATCH_CONV)
            (ONCE_REWRITE_RULE[list_to_BlockReps_def] th))))) in
  (* the invariant of the tail's value over the bigger heap *)
  let grow_t =
    W(fun (asl,gl) ->
      let vit = the_vi_t asl in
      let args = snd (strip_comb (concl vit)) in
      let ps = tparts (el 3 args) in
      let hp = el 3 ps in
      let ha = lhand hp and hb = rand (rand hp) in
      let sp = rand (lhand (rand hp)) in
      MP_TAC (red3 (REWRITE_RULE[GSYM APPEND_ASSOC]
        (ISPECL [el 0 args; el 1 args; el 2 args; el 0 ps; el 1 ps;
          el 2 ps; goal_hs gl; ha; hb; sp]
          data_to_word_memoryProof_v_inv_lemma)))) THEN
    (ANTS_TAC THENL
      [CONJ_TAC THENL [from_bnd; FIRST_ASSUM ACCEPT_TAC];
       DISCH_THEN ACCEPT_TAC]) in
  (* and the invariants of the values of the tail, which the lemma
     about a list of them carries over; it speaks of the addresses
     first, so the relation is swapped into it and back out *)
  let grow_list =
    W(fun (asl,gl) ->
      let ev = grab_asm (fun th -> hd_is "ALL2" (concl th)) asl in
      let args = snd (strip_comb (concl ev)) in
      let lr0 = ISPECL [el 2 args; el 1 args] v_inv_LIST_REL in
      let hsv = find_term (fun t ->
        is_var t && fst (dest_var t) = "hs") (concl lr0) in
      let lr = INST [goal_hs gl,hsv] lr0 in
      MP_TAC lr THEN
      (ANTS_TAC THENL
        [REPEAT CONJ_TAC THENL
          [REWRITE_TAC[heap_length_clauses; el_length_def;
             LENGTH] THEN
           ARITH_TAC;
           REWRITE_TAC[heap_length_clauses; el_length_def;
             LENGTH] THEN
           CONV_TAC NUM_REDUCE_CONV THEN from_bnd;
           ACCEPT_TAC (BETA_RULE (MATCH_MP EVERY2_SWAP ev))];
         DISCH_THEN (fun th ->
           ACCEPT_TAC (red3 (BETA_RULE
             (MATCH_MP EVERY2_SWAP th))))])) in
  (* the timestamps of the tail start one later *)
  let grow_fdom =
    GEN_TAC THEN DISCH_TAC THEN
    FIRST_ASSUM (fun th ->
      if not (is_forall (concl th)) ||
         not (can (find_term (hd_is "FDOM")) (concl th)) then fail()
      else FIRST_ASSUM (fun a ->
        if is_forall (concl a) ||
           not (can (find_term (hd_is "FDOM")) (concl a)) then fail()
        else MP_TAC (MP (SPEC (lhand (concl a)) th) a))) THEN
    ARITH_TAC in
  (* the hypothesis of the induction, at the tail of the list of
     the addresses and at the heap that this cons left *)
  let cons_ih =
    W(fun (asl,gl) ->
      let el0 = find_term (fun u ->
        hd_is "BlockRep" u && hd_is "CONS" (rand u)) gl in
      let app = rator (rator (find_term (hd_is "APPEND") gl)) in
      let vit = the_vi_t asl in
      let ps = tparts (rand (concl vit)) in
      let rt = el 0 ps and hp = el 3 ps in
      let haq = mk_comb (mk_comb (app, lhand hp),
                  mk_list ([el0], type_of el0)) in
      let hb = rand (rand hp) in
      let ne = grab_asm (fun th ->
        is_neg (concl th) && is_eq (rand (concl th)) &&
        hd_is "CONS" (lhs (rand (concl th)))) asl in
      let rs2 = rand (lhs (rand (concl ne))) in
      let ih = grab_asm (fun th ->
        is_forall (concl th) &&
        can (find_term (hd_is "list_to_BlockReps"))
          (concl th)) asl in
      MP_TAC (SPECL [rs2; `xs2:(dataSem_v)list`; `t:dataSem_v`; rt;
        haq; hb; `sp - 3`; `ts + 1`] ih)) THEN
    (ANTS_TAC THENL
      [REWRITE_TAC[GSYM APPEND_ASSOC; heap_length_APPEND;
         heap_length_clauses; BlockRep_def; el_length_def;
         LENGTH] THEN
       CONV_TAC NUM_REDUCE_CONV THEN REPEAT CONJ_TAC THENL
        [FIRST_ASSUM (fun th ->
           if not (hd_is "<=" (concl th)) ||
              not (hd_is "LENGTH" (lhand (concl th))) then fail()
           else MP_TAC th) THEN
         REWRITE_TAC[LENGTH] THEN ARITH_TAC;
         REWRITE_TAC[NOT_CONS_NIL];
         grow_t;
         grow_list;
         from_bnd;
         grow_fdom];
       ALL_TAC]) THEN
    DISCH_TAC in
  (* and the invariant that the hypothesis gave, at the timestamp
     of this cons added to the map *)
  let use_tail =
    ONCE_REWRITE_TAC[bind_each_def] THEN
    W(fun (asl,gl) ->
      let ih = grab_asm (fun th ->
        hd_is "v_inv" (concl th) &&
        can (find_term (hd_is "dataSem_list_to_v"))
          (concl th)) asl in
      let ihn = CONV_RULE NUM_REDUCE_CONV (REWRITE_RULE nrm ih) in
      let gtf = el 2 (tparts (el 3 (snd (strip_comb gl)))) in
      let inner = lhand gtf in
      let pr = rand gtf in
      let args = snd (strip_comb inner) in
      let nz = MP (SPECL [el 4 args; lhand pr; el 1 args;
        el 0 args; el 2 args; el 3 args] bind_each_MONO)
        (CONJ (ARITH_RULE `ts < ts + 1`) (the_fdom asl)) in
      let fu = SPEC (rand pr) (MATCH_MP FUPDATE_SUBMAP nz) in
      let ps = tparts (el 3 (snd (strip_comb (concl ihn)))) in
      MP_TAC (MATCH_MP v_inv_SUBMAP
        (CONJ (ISPEC (el 1 ps) SUBMAP_REFL)
          (CONJ fu (CONJ (ISPEC (el 3 ps) hsr_refl) ihn))))) THEN
    REWRITE_TAC nrm THEN CONV_TAC NUM_REDUCE_CONV THEN
    DISCH_THEN ACCEPT_TAC in
  let cons_fin =
    REWRITE_TAC[v_inv_def; NOT_CONS_NIL] THEN
    W(fun (asl,gl) ->
      let bl = find_term (fun u ->
        hd_is "BlockRep" u && hd_is "CONS" (rand u)) gl in
      let ptr = find_term (fun u ->
        hd_is "heap_length" u && is_var (rand u)) gl in
      MAP_EVERY EXISTS_TAC [ptr; rand bl]) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[ALL2] THEN CONJ_TAC THENL
       [(MATCH_MP_TAC data_to_word_memoryProof_v_inv_lemma THEN
         REPEAT CONJ_TAC THENL
          [REWRITE_TAC[heap_length_clauses; BlockRep_def;
             el_length_def; LENGTH] THEN
           CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC;
           REWRITE_TAC[heap_length_clauses; BlockRep_def;
             el_length_def; LENGTH] THEN
           CONV_TAC NUM_REDUCE_CONV THEN from_bnd;
           grow_tf]);
        use_tail];
      ONCE_REWRITE_TAC[bind_each_def] THEN
      REWRITE_TAC[FLOOKUP_UPDATE];
      REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV;
      SIMP_TAC[heap_lookup_APPEND1; LE_REFL; SUB_REFL] THEN
      REWRITE_TAC[APPEND; heap_lookup_def]] in
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN IND_RS THENL
   [base_vl;
    pre_vl THEN SPLIT_LIST "rr" "r2" "rr2" THENL
     [single_vl; cons_pre THEN cons_bnd THEN cons_ih THEN
      cons_fin]])));;

(* HOL4 data_to_word_memoryProofScript.sml:2670-2671: a theorem that
   HOL4 states as the value of an ML expression: v_inv_list_to_v *)

(* A timestamp that is not in the  *)

let all_ts_cons = prove
 (`!refs stack' ts tag xs.
     all_ts refs ((Block ts tag xs:dataSem_v) :: stack') = ts
       INSERT all_ts refs (xs ++ stack')`,
  (* the timestamps of a Block on the stack are its own timestamp
     and the ones of its payload, which the payload in front of the
     stack has; the set that the refs contribute is the same on
     both sides, so the proof is about the stack alone *)
  (let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let mems = [vats; MEM; MEM_FLAT; MEM_MAP] in
   let gen = prove
    (`!(s:dataSem_v->bool) ts tag xs stack.
        {t | ?x. (x IN s \/ MEM x (Block ts tag xs :: stack)) /\
                 MEM t (v_all_ts x)} =
        ts INSERT {t | ?x. (x IN s \/ MEM x (xs ++ stack)) /\
                           MEM t (v_all_ts x)}`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[EXTENSION; IN_INSERT; IN_ELIM_THM; MEM;
                 MEM_APPEND] THEN
     X_GEN_TAC `t:num` THEN EQ_TAC THENL
      [DISCH_THEN(X_CHOOSE_THEN `y:dataSem_v`
         (CONJUNCTS_THEN2 (REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC)
                          ASSUME_TAC)) THENL
        [DISJ2_TAC THEN EXISTS_TAC `y:dataSem_v` THEN
         ASM_REWRITE_TAC[];
         FIRST_X_ASSUM SUBST_ALL_TAC THEN
         FIRST_X_ASSUM(MP_TAC o REWRITE_RULE mems) THEN
         DISCH_THEN(DISJ_CASES_THEN2
           (fun th -> DISJ1_TAC THEN ACCEPT_TAC th)
           (X_CHOOSE_THEN `u:num list`
             (CONJUNCTS_THEN2
                (X_CHOOSE_THEN `z:dataSem_v`
                   (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))
                MP_TAC))) THEN
         ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
         DISJ2_TAC THEN EXISTS_TAC `z:dataSem_v` THEN
         ASM_REWRITE_TAC[];
         DISJ2_TAC THEN EXISTS_TAC `y:dataSem_v` THEN
         ASM_REWRITE_TAC[]];
       DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC
         (X_CHOOSE_THEN `y:dataSem_v`
           (CONJUNCTS_THEN2 (REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC)
                            ASSUME_TAC))) THENL
        [EXISTS_TAC `Block ts tag xs` THEN
         ASM_REWRITE_TAC[vats; MEM];
         EXISTS_TAC `y:dataSem_v` THEN ASM_REWRITE_TAC[];
         EXISTS_TAC `Block ts tag xs` THEN
         REWRITE_TAC mems THEN DISJ2_TAC THEN
         EXISTS_TAC `v_all_ts (y:dataSem_v)` THEN
         CONJ_TAC THENL
          [EXISTS_TAC `y:dataSem_v` THEN ASM_REWRITE_TAC[];
           ASM_REWRITE_TAC[]];
         EXISTS_TAC `y:dataSem_v` THEN ASM_REWRITE_TAC[]]]) in
   REPEAT GEN_TAC THEN REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   MATCH_ACCEPT_TAC gen));;

let all_ts_cons_no_block = prove
 (`!refs stack' v.
     (!ts tag xs. ~(v = Block ts tag xs)) ==> all_ts refs (v ::
       stack') = all_ts refs stack'`,
  (* a value that is not a Block has no timestamp in it, so the head
     of the stack adds nothing to the set *)
  (let keep = EXISTS_TAC `x:dataSem_v` THEN ASM_MESON_TAC[] in
   REPEAT STRIP_TAC THEN
   SUBGOAL_THEN `v_all_ts (v:dataSem_v) = []` ASSUME_TAC THENL
    [CASES_ON_NAME "v" THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_ts_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN ASM_MESON_TAC[];
     ALL_TAC] THEN
   REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[EXTENSION; IN_ELIM_THM; MEM] THEN
   X_GEN_TAC `t:num` THEN EQ_TAC THEN STRIP_TAC THENL
    [keep; ASM_MESON_TAC[MEM]; keep; keep; keep]));;

(* NOT USED *)
let all_ts_in_no_block = prove
 (`!refs stack' v t.
     (!ts tag xs. ~(v = Block ts tag xs)) /\
     t IN all_ts refs (v :: stack') ==> t IN all_ts refs stack'`,
  (REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM(fun th ->
     ASSUME_TAC(MATCH_MP all_ts_cons_no_block th)) THEN
   ASM_MESON_TAC[]));;

let all_ts_append = prove
 (`!refs x y. all_ts refs (x ++ y) = all_ts refs x UNION all_ts refs y`,
  (REPEAT GEN_TAC THEN REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[EXTENSION; IN_UNION; IN_ELIM_THM; MEM_APPEND] THEN
   MESON_TAC[]));;

let all_ts_head = prove
 (`!refs x xs. all_ts refs (x :: xs) = all_ts refs [x] UNION all_ts
  refs xs`,
  (REPEAT GEN_TAC THEN REWRITE_TAC[GSYM all_ts_append; APPEND]));;

let v_all_vs_MEM = prove
 (`!l ts tag xs.
     MEM (Block ts tag xs) (v_all_vs l) ==> (?x y. v_all_vs l = x
       ++ (Block ts tag xs :: v_all_vs xs) ++ y)`,
  (* the values of a list are the values of its head followed by
     the ones of its tail, and a Block among them is followed by
     the values of its payload: the induction of the type gives
     both halves at once, and what each case does to the two
     pieces of the append is what the three lemmas say *)
  (let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let ext0 = prove
    (`!b:dataSem_v list. ?p q. b = p ++ b ++ q`,
     GEN_TAC THEN EXISTS_TAC `[]:dataSem_v list` THEN
     EXISTS_TAC `[]:dataSem_v list` THEN
     REWRITE_TAC[APPEND; APPEND_NIL]) in
   let extc = prove
    (`!(h:dataSem_v) t b. (?p q. t = p ++ b ++ q)
                          ==> (?p q. CONS h t = p ++ b ++ q)`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(X_CHOOSE_THEN `p:dataSem_v list`
       (X_CHOOSE_THEN `q:dataSem_v list` SUBST1_TAC)) THEN
     EXISTS_TAC `CONS (h:dataSem_v) p` THEN
     EXISTS_TAC `q:dataSem_v list` THEN REWRITE_TAC[APPEND]) in
   let extl = prove
    (`!(s:dataSem_v list) t b. (?p q. t = p ++ b ++ q)
                               ==> (?p q. s ++ t = p ++ b ++ q)`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(X_CHOOSE_THEN `p:dataSem_v list`
       (X_CHOOSE_THEN `q:dataSem_v list` SUBST1_TAC)) THEN
     EXISTS_TAC `s ++ p:dataSem_v list` THEN
     EXISTS_TAC `q:dataSem_v list` THEN
     REWRITE_TAC[GSYM APPEND_ASSOC]) in
   let extr = prove
    (`!(s:dataSem_v list) t b. (?p q. t = p ++ b ++ q)
                               ==> (?p q. t ++ s = p ++ b ++ q)`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(X_CHOOSE_THEN `p:dataSem_v list`
       (X_CHOOSE_THEN `q:dataSem_v list` SUBST1_TAC)) THEN
     EXISTS_TAC `p:dataSem_v list` THEN
     EXISTS_TAC `q ++ s:dataSem_v list` THEN
     REWRITE_TAC[APPEND_ASSOC]) in
   let triv = REPEAT GEN_TAC THEN
     REWRITE_TAC[vsing; MEM; distinctness "dataSem_v"] in
   SUBGOAL_THEN
     `(!x ts tag xs.
         MEM (Block ts tag xs) (v_all_vs [x])
         ==> (?p q. v_all_vs [x] =
                    p ++ (Block ts tag xs :: v_all_vs xs) ++ q)) /\
      (!l ts tag xs.
         MEM (Block ts tag xs) (v_all_vs l)
         ==> (?p q. v_all_vs l =
                    p ++ (Block ts tag xs :: v_all_vs xs) ++ q))`
     (fun th -> MATCH_ACCEPT_TAC(CONJUNCT2 th)) THEN
   MATCH_MP_TAC (dataSem_v_induct ()) THEN REPEAT CONJ_TAC THENL
    [triv; triv;
     REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[vsing; MEM; injectivity "dataSem_v"] THEN
     DISCH_THEN(DISJ_CASES_THEN2
       (fun eq -> STRIP_ASSUME_TAC eq THEN ASM_REWRITE_TAC[] THEN
                  MATCH_ACCEPT_TAC ext0)
       (fun m -> FIRST_ASSUM(fun ih ->
                   MATCH_ACCEPT_TAC(MATCH_MP extc (MATCH_MP ih m)))));
     triv; triv;
     REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[vcons] THEN REWRITE_TAC[MEM_APPEND] THEN
     DISCH_THEN(DISJ_CASES_THEN2
       (fun m -> FIRST_ASSUM(fun ih ->
                   MATCH_ACCEPT_TAC(MATCH_MP extr (MATCH_MP ih m))))
       (fun m -> FIRST_ASSUM(fun ih ->
                   MATCH_ACCEPT_TAC(MATCH_MP extl
                     (MATCH_MP ih m)))))]));;

let v_in_all_vs = prove
 (`!x y stack' refs.
     x IN all_vs refs stack' /\ MEM y (v_all_vs [x]) ==> y IN
       all_vs refs stack'`,
  (* a value of a value of what the refs and the stack hold is one
     of them as well: each of the four parts of all_vs is a list
     and the values of a list are transitively closed *)
  (REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   REPEAT GEN_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC ASSUME_TAC) THEN
   FIRST_ASSUM(fun mx -> FIRST_ASSUM(fun my ->
     ASSUME_TAC(MATCH_MP (snd (v_all_vs_trans_thm ()))
                         (CONJ mx my)))) THEN
   ASM_MESON_TAC[]));;

let v_all_vs_MEM2 = prove
 (`!l ts tag xs.
     MEM (Block ts tag xs) (v_all_vs l) ==> (?x. MEM x l /\ MEM
       (Block ts tag xs) (v_all_vs [x]))`,
  (* the values of v_all_vs (x::xs) are x itself, the values of its
     payload where it is a Block, and the values of v_all_vs xs: the
     first two are the values of v_all_vs [x] and the third is what
     the induction hypothesis is about *)
  (let vav = v_all_vs_def in
   let vnil = prove
    (`v_all_vs ([]:dataSem_v list) = []`,
     GEN_REWRITE_TAC LAND_CONV [vav] THEN MATCH_REDUCE_TAC THEN
     REWRITE_TAC[]) in
   let vsing = prove
    (`!t tag xs y. MEM y (v_all_vs [Block t tag xs]) <=>
        y = Block t tag xs \/ MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [vav] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[vnil; APPEND_NIL; MEM; MEM_APPEND]) in
   LIST_INDUCT_TAC THENL
    [REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN CASES_ON_NAME "h" THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [vav] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[MEM; MEM_APPEND; distinctness "dataSem_v"] THEN
     ASM_MESON_TAC[vsing]]));;

let v_all_vs_ts = prove
 (`!x ts tag xs. MEM (Block ts tag xs) (v_all_vs [x]) ==> MEM ts
  (v_all_ts x)`,
  (* induction on the value and on a list of values at once, which
     is what define_datatype gives for a type that nests a list of
     itself: the timestamp of a Block among the values of a value is
     one of the timestamps of that value *)
  (let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let triv = REPEAT GEN_TAC THEN
     REWRITE_TAC[vsing; MEM; distinctness "dataSem_v"] in
   SUBGOAL_THEN
     `(!x ts tag xs.
         MEM (Block ts tag xs) (v_all_vs [x]) ==> MEM ts (v_all_ts x))
      /\
      (!l ts tag xs.
         MEM (Block ts tag xs) (v_all_vs l)
         ==> MEM ts (FLAT (MAP v_all_ts l)))`
     (fun th -> MATCH_ACCEPT_TAC(CONJUNCT1 th)) THEN
   MATCH_MP_TAC dataSem_v_INDUCT THEN REPEAT CONJ_TAC THENL
    [triv; triv;
     REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[vsing; vats; MEM; injectivity "dataSem_v"] THEN
     ASM_MESON_TAC[];
     triv; triv;
     REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[vcons] THEN
     REWRITE_TAC[MEM_APPEND; MAP; FLAT] THEN
     ASM_MESON_TAC[]]));;

let MEM_v_all_vs = prove
 (`!l v. MEM v l ==> MEM v (v_all_vs l)`,
  (let vav = v_all_vs_def in
   LIST_INDUCT_TAC THEN REWRITE_TAC[MEM] THEN GEN_TAC THEN
   CASES_ON_NAME "h" THEN
   GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [vav] THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[MEM_APPEND; MEM] THEN ASM_MESON_TAC[]));;

let MEM_stack_all_vs = prove
 (`!v stack' refs. MEM v stack' ==> v IN all_vs refs stack'`,
  (REPEAT STRIP_TAC THEN
   REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   REPEAT DISJ2_TAC THEN MATCH_MP_TAC MEM_v_all_vs THEN
   ASM_REWRITE_TAC[]));;

let v_all_vs_ts_MEM = prove
 (`!x y ts. MEM ts (v_all_ts x) /\ MEM x (v_all_vs [y]) ==> MEM ts
  (v_all_ts y)`,
  (* the induction that ml/lib/tactics.ml does for the proofs that
     need this before the file states it *)
  (let (c1,_) = v_all_vs_ts_thm () in
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun a2 -> FIRST_ASSUM(fun a1 ->
     MATCH_ACCEPT_TAC(MATCH_MP c1 (CONJ a1 a2))))));;

let v_all_vs_trans = prove
 (`!x y z. MEM y (v_all_vs x) /\ MEM z (v_all_vs [y]) ==> MEM z
  (v_all_vs x)`,
  (* the induction that ml/lib/tactics.ml does for the proofs that
     need this before the file states it *)
  (MATCH_ACCEPT_TAC (snd (v_all_vs_trans_thm ()))));;

let MEM_in_all_ts = prove
 (`!x ts stack' refs.
     x IN all_vs refs stack' /\ MEM ts (v_all_ts x) ==> ts IN
       all_ts refs stack'`,
  (* only a Block has a timestamp, and a Block among the values of
     what the refs and the stack hold is among the values of one of
     the values that a ref holds or of one on the stack, whose
     timestamps are therefore timestamps of the stack *)
  (let (c1,_) = v_all_vs_ts_thm () in
   let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let fr = prove
    (`(!l x. find_ref (bvlSem_ValueArray l) x <=> MEM x l) /\
      (!m v x. find_ref (Thunk m v) x <=> (v = x)) /\
      (!tg fin l c r x. find_ref (bvlSem_MutBlock tg fin l c r) x <=>
         MEM x (l ++ [c] ++ r))`,
     REPEAT CONJ_TAC THEN REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [find_ref_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   SUBGOAL_THEN `?t tag l. (x:dataSem_v) = Block t tag l`
     STRIP_ASSUME_TAC THENL
    [CASES_ON_NAME "x" THEN
     RULE_ASSUM_TAC(REWRITE_RULE[vats; MEM]) THEN
     TRY(FIRST_ASSUM CONTR_TAC) THEN MESON_TAC[];
     ALL_TAC] THEN
   FIRST_X_ASSUM SUBST_ALL_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[all_vs_def; IN_UNION;
                               IN_ELIM_THM]) THEN
   REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[IN_ELIM_THM] THEN
   ASM_MESON_TAC[v_all_vs_MEM2; c1; fr; MEM_APPEND]));;

let MEM_in_all_vs = prove
 (`!x y refs stack'. x IN all_vs refs stack' /\ MEM y (v_all_vs [x])
  ==> y IN all_vs refs stack'`,
  (REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   REPEAT STRIP_TAC THEN ASM_MESON_TAC[v_all_vs_trans]));;

(* NOT USED *)
let v_all_vs_ts_list = prove
 (`!x y ts. MEM x (v_all_vs y) /\ MEM ts (v_all_ts x) ==> MEM ts (FLAT
  (MAP v_all_ts y))`,
  (* the other half of that induction: the timestamps of a value
     among the values of a list are timestamps of the list *)
  (let (_,c2) = v_all_vs_ts_thm () in
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun a2 -> FIRST_ASSUM(fun a1 ->
     MATCH_ACCEPT_TAC(MATCH_MP c2 (CONJ a1 a2))))));;

let v_inv_tf_update_thm_lemma = prove
 (`!ck v refs y f tf heap ts' a.
     v_inv conf v refs (y,f,tf,heap) /\ ~(ts' IN FDOM tf) ==>
       v_inv_ck ck conf v refs (y,f,tf |+ (ts',a),heap)`,
  (* the same complete induction as v_inv_SUBMAP_lemma, but only the
     map of the timestamps changes and by an update at a timestamp
     that is not in its domain: a Block of the invariant has its
     timestamp in that domain, so its lookup is the one it was *)
  (let (vr,_,_) = v_inv_ck in
   let rl = CONJUNCTS vr in
   let vdef = v_inv_def in
   let NOT_VAR_TAC =
     FIRST_ASSUM(fun nb ->
       if is_neg(concl nb) && is_var(rand(concl nb))
       then SUBST_ALL_TAC(EQF_INTRO nb) else fail()) in
   let FLU_TAC =
     ASM_REWRITE_TAC[FLOOKUP_UPDATE] THEN COND_CASES_TAC THEN
     ASM_REWRITE_TAC[] THEN
     FIRST_ASSUM(fun fl -> MP_TAC(MATCH_MP FLOOKUP_IN_FDOM fl)) THEN
     ASM_REWRITE_TAC[] in
   let lt1 = ARITH_RULE `~(ck = 0) ==> ck - 1 < ck` in
   let setup =
     MATCH_MP_TAC num_WF THEN X_GEN_TAC `ck:num` THEN DISCH_TAC THEN
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     CASES_ON_NAME "v" THEN USE_CHANGED [vdef] in
   setup THENL
    [COND_CASES_TAC THEN STRIP_TAC THEN SUBST_LHS_TAC THENL
      [MATCH_MP_TAC(el 0 rl) THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC(el 1 rl) THEN ASM_REWRITE_TAC[]];
     STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
     MATCH_MP_TAC(el 2 rl) THEN ASM_REWRITE_TAC[];
     COND_CASES_TAC THEN STRIP_TAC THEN REPEAT SUBST_LHS_TAC THENL
      [MATCH_MP_TAC(el 7 rl) THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC(el 8 rl) THEN REPEAT CONJ_TAC THENL
        [FIRST_ASSUM MATCH_ACCEPT_TAC;
         DISCH_TAC THEN
         FIRST_ASSUM(fun a2th ->
           if can (term_match [] `EVERY2 (p:A->B->bool) l m`)
                  (concl a2th)
           then MP_TAC a2th else fail()) THEN
         MATCH_MP_TAC MONO_ALL2 THEN BETA_TAC THEN
         REPEAT STRIP_TAC THEN CK_IH_TAC;
         FLU_TAC;
         FIRST_ASSUM MATCH_ACCEPT_TAC]];
     STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
     MATCH_ACCEPT_TAC(el 3 rl);
     DISCH_THEN(DISJ_CASES_THEN2 STRIP_ASSUME_TAC
       (DISJ_CASES_THEN2 STRIP_ASSUME_TAC STRIP_ASSUME_TAC)) THENL
      [REPEAT SUBST_LHS_TAC THEN MATCH_MP_TAC(el 4 rl) THEN
       REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
       ASM_REWRITE_TAC[];
       NOT_VAR_TAC THEN
       FIRST_ASSUM(fun ih ->
         ASM_MESON_TAC[el 5 rl; SPEC `ck - 1` ih; lt1]);
       NOT_VAR_TAC THEN
       FIRST_ASSUM(fun ih ->
         ASM_MESON_TAC[el 6 rl; SPEC `ck - 1` ih; lt1])]]));;

let v_inv_tf_update_thm = prove
 (`!conf v refs y f tf heap ts' a.
     v_inv conf v refs (y,f,tf,heap) /\ ~(ts' IN FDOM tf) ==>
     v_inv conf v refs (y,f,tf |+ (ts',a),heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_tf_update_thm_lemma]));;

(* the port's own: what the lemmas about a change of the refs
   share.  Each of them says that the clocked relation holds of a
   value after a cell of the refs is put in or changed, and each is
   the same complete induction on the clock, with the same four
   facts about the lookups of the new refs to be proved of the cell
   in question. *)

(* the port's own: a key that the refs do not have has no lookup *)
let no_lk = prove
 (`~(ptr IN domain (refs:(A)spt)) ==> lookup ptr refs = NONE`,
  REWRITE_TAC[domain_lookup] THEN
  STRUCT_CASES_TAC(ISPEC `lookup ptr (refs:(A)spt)`
    (cases_of `:(A)option`)) THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  MESON_TAC[]);;

(* and a key of f is a key of the refs, so it is not one that the
   refs do not have *)
let notptr = prove
 (`lookup ptr refs = NONE /\
   (!x. x IN FDOM f ==> x IN domain refs) /\ k IN FDOM f
   ==> ~(k = ptr)`,
  REWRITE_TAC[domain_lookup] THEN
  MESON_TAC[distinctness "option"]);;

let v_inv_ck_rules = CONJUNCTS (let (vr,_,_) = v_inv_ck in vr);;

(* the b of a RefPtr that the two thunk rules ask to be false *)
let NOT_VAR_TAC =
  FIRST_ASSUM(fun nb ->
    if is_neg(concl nb) && is_var(rand(concl nb))
    then SUBST_ALL_TAC(EQF_INTRO nb) else fail());;

(* the four facts that such a lemma proves of its own refs -- the
   lookup of a thunk, the annotation of a pointer, the dest_thunk
   of a value and the condition of a plain reference, of the new
   refs against the old ones -- which its own `same` gives when it
   is applied to the assumption that says what the refs are *)
let v_inv_refs_parts same lk =
  let s = MATCH_MP same lk in
  (CONJUNCT1 s,CONJUNCT1(CONJUNCT2 s),
   CONJUNCT1(CONJUNCT2(CONJUNCT2 s)),
   CONJUNCT2(CONJUNCT2(CONJUNCT2 s)));;

(* the case of a plain reference, whose annotation is the one it
   was *)
let V_INV_REFS_PLAIN same =
  REPEAT SUBST_LHS_TAC THEN
  FIRST_ASSUM(fun lk ->
    let (t_eq,a_eq,_,m_imp) = v_inv_refs_parts same lk in
    REWRITE_TAC[GSYM a_eq] THEN
    MATCH_MP_TAC(el 4 v_inv_ck_rules) THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM MATCH_ACCEPT_TAC;
      ASM_REWRITE_TAC[t_eq];
      MATCH_MP_TAC m_imp THEN FIRST_ASSUM MATCH_ACCEPT_TAC]);;

(* and the case of a thunk, whose value and heap element the rule
   names and not its conclusion, so MESON applies the rule *)
let V_INV_REFS_THUNK same n =
  let lt1 = ARITH_RULE `~(ck = 0) ==> ck - 1 < ck` in
  NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
  FIRST_ASSUM(fun lk ->
    let (t_eq,_,dt,_) = v_inv_refs_parts same lk in
    FIRST_ASSUM(fun ih ->
      ASM_MESON_TAC[el n v_inv_ck_rules; t_eq; dt;
                    SPEC `ck - 1` ih; lt1]));;

(* the three cases of a RefPtr where the refs do not change and the
   heap does: a plain reference reads nothing of the heap, and the
   heap element of a thunk is the one that the lemma's own
   hypothesis about the two heaps carries over, which is the
   argument.  The witnesses of the two thunk rules are the ones
   that the assumptions name: the thunk of the refs and the
   element of the heap. *)

let V_INV_HEAP_PLAIN =
  REPEAT SUBST_LHS_TAC THEN
  MATCH_MP_TAC(el 4 v_inv_ck_rules) THEN ASM_REWRITE_TAC[];;

let V_INV_HEAP_THUNK hp n =
  let wit =
    W(fun (asl,w) ->
      let thunk = tryfind (fun (_,th) ->
        let t = concl th in
        if is_eq t && hd_is "bvlSem_Thunk" (rand(rhs t))
        then rand(rhs t) else fail()) asl in
      if n = 5 then
        let x = tryfind (fun (_,th) ->
          let t = concl th in
          if is_eq t && hd_is "ThunkBlock" (rand(rhs t))
          then rand(rand(rhs t)) else fail()) asl in
        MAP_EVERY EXISTS_TAC [lhand thunk; rand thunk; x]
      else EXISTS_TAC (rand thunk)) in
  NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
  MATCH_MP_TAC(el n v_inv_ck_rules) THEN wit THEN
  REPEAT CONJ_TAC THEN
  FIRST [FIRST_ASSUM MATCH_ACCEPT_TAC; hp;
         DISCH_TAC THEN CK_IH_TAC];;

(* the induction that the lemmas about a change of the refs share.
   It is the complete induction on the ck of the relation that
   v_inv_SUBMAP_lemma does by hand: the value is taken apart with
   v_inv_def and the rule of the relation for that shape is
   applied, where the maps are the ones they were and what a Block
   asks of its elements is the induction hypothesis at ck - 1.  The
   arguments are the tactic that applies the induction hypothesis
   (CK_IH_TAC where it takes the assumptions as they stand), the
   one that proves the FLOOKUP of tf of a Block (an assumption
   where tf does not change), the tactic that derives from the
   lemma's own hypothesis what its cases use, the one that proves a
   heap_lookup of the new heap (ALL_TAC where the heap does not
   change), and the three of a RefPtr: a plain reference and the
   two thunks. *)
let V_INV_REFS_TAC_IH ih tp prep hp d5 d6 d7 =
  let rl = v_inv_ck_rules in
  let VAL_CASES_TAC (asl,w) =
    CASES_ON_TAC (el 2 (snd(strip_comb w))) (asl,w) in
  let setup =
    MATCH_MP_TAC num_WF THEN X_GEN_TAC `ck:num` THEN
    DISCH_TAC THEN REPEAT GEN_TAC THEN
    (DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) ORELSE
     DISCH_TAC) THEN
    prep THEN VAL_CASES_TAC THEN USE_CHANGED [v_inv_def] in
  (* a Number is a small one or a Bignum of the heap *)
  let c1 =
    COND_CASES_TAC THEN STRIP_TAC THEN SUBST_LHS_TAC THENL
     [MATCH_MP_TAC(el 0 rl) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(el 1 rl) THEN ASM_REWRITE_TAC[] THEN hp] in
  let c2 =
    STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
    MATCH_MP_TAC(el 2 rl) THEN ASM_REWRITE_TAC[] THEN hp in
  (* a Block is a BlockNil or a BlockRep whose elements the
     induction hypothesis carries over one by one *)
  let c3 =
    COND_CASES_TAC THEN STRIP_TAC THEN REPEAT SUBST_LHS_TAC THENL
     [MATCH_MP_TAC(el 7 rl) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(el 8 rl) THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM MATCH_ACCEPT_TAC;
        DISCH_TAC THEN
        FIRST_ASSUM(fun a2th ->
          if can (term_match [] `EVERY2 (p:A->B->bool) l m`)
                 (concl a2th)
          then MP_TAC a2th else fail()) THEN
        (* the elements come with their membership of the two
           lists, which the hypothesis of a lemma about the
           timestamps asks for *)
        ONCE_REWRITE_TAC[LIST_REL_MEM] THEN
        MATCH_MP_TAC MONO_ALL2 THEN BETA_TAC THEN
        REPEAT STRIP_TAC THEN
        TRY(FIRST_ASSUM(fun imp ->
          FIRST_ASSUM(fun m1 -> FIRST_ASSUM(fun m2 ->
            ASSUME_TAC(MP imp (CONJ m1 m2)))))) THEN
        ih;
        tp;
        ASM_REWRITE_TAC[] THEN hp]] in
  let c4 = STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
           MATCH_ACCEPT_TAC(el 3 rl) in
  let c5 =
    DISCH_THEN(DISJ_CASES_THEN2 STRIP_ASSUME_TAC
      (DISJ_CASES_THEN2 STRIP_ASSUME_TAC STRIP_ASSUME_TAC)) THENL
     [d5; d6; d7] in
  setup THENL [c1; c2; c3; c4; c5];;

(* and the induction as the lemmas whose hypothesis the induction
   hypothesis takes as it stands use it *)

let V_INV_REFS_TAC =
  V_INV_REFS_TAC_IH CK_IH_TAC (FIRST_ASSUM MATCH_ACCEPT_TAC);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_tf_update_thm_alt_lemma = prove
 (cake_as_vars (fun () ->
    `!ck v refs y f tf heap ts' a.
       v_inv conf v refs (y,f,tf,heap) /\ ~(ts' IN (all_ts refs
         stack)) /\ ~(ts' IN set_of_list (v_all_ts v)) ==>
           v_inv_ck ck conf v refs (y,f,tf |+ (ts',a),heap)`),
  (* tf is what changes, and only a Block reads it: of the Block
     itself the timestamp of the update is not its own (the
     hypothesis says so), and of an element the induction
     hypothesis asks for the timestamps of the element, which are
     the Block's.  Of the value that a thunk of the refs holds they
     are the refs' (MEM_in_all_ts) *)
  (let rl = v_inv_ck_rules in
   let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let nlt = ARITH_RULE `!n. ~(n = 0) ==> n - 1 < n` in
   (* the value that a thunk of the refs holds is a value of the
      refs, so its timestamps are the refs' *)
   let in_av = prove
    (cake_as_vars (fun () ->
       `lookup n refs = SOME (Thunk ev v)
        ==> v IN all_vs refs stack`),
     DISCH_TAC THEN
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
     DISJ2_TAC THEN DISJ1_TAC THEN
     MAP_EVERY EXISTS_TAC
       [`n:num`; `ev:thunk_mode`; `v:dataSem_v`] THEN
     ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC MEM_v_all_vs THEN REWRITE_TAC[MEM]) in
   (* the assumption that says that the timestamp of the update is
      none of a value's *)
   let is_tsc c =
     is_neg c &&
     (try hd_is "set_of_list" (rand(rand c)) with Failure _ -> false) in
   (* the hypothesis of the lemma, conjunct by conjunct *)
   let prep =
     FIRST_ASSUM(fun c ->
       if is_conj (concl c) then MAP_EVERY ASSUME_TAC (CONJUNCTS c)
       else fail()) in
   (* the induction hypothesis at ck - 1, with the condition of the
      value it is applied to proved by the argument *)
   let ih_by tac =
     FIRST_ASSUM(fun nz ->
       let c = concl nz in
       if not(is_neg c) then fail() else
       let e = rand c in
       if not(is_eq e) || not(type_of(lhs e) = `:num`) ||
          not(rhs e = `0`) then fail() else
       let lt = MP (SPEC (lhs e) nlt) nz in
       FIRST_ASSUM(fun ihth ->
         let ih' = MP (SPEC (mk_binop `(-):num->num->num` (lhs e) `1`)
                         ihth) lt in
         MATCH_MP_TAC ih' THEN REPEAT CONJ_TAC THEN
         TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN tac)) in
   (* of an element of a Block its timestamps are the Block's *)
   let ih =
     ih_by
      (FIRST_ASSUM(fun tsc ->
         if not (is_tsc (concl tsc)) then fail() else
         MP_TAC(REWRITE_RULE[IN_SET_OF_LIST; vats; MEM; MEM_FLAT;
                             MEM_MAP] tsc)) THEN
       REWRITE_TAC[IN_SET_OF_LIST] THEN ASM_MESON_TAC[]) in
   (* and of the value of a thunk they are the refs' *)
   let ih_thunk =
     ih_by
      (REWRITE_TAC[IN_SET_OF_LIST] THEN DISCH_TAC THEN
       FIRST_ASSUM(fun m ->
         FIRST_ASSUM(fun lk ->
           MP_TAC(MATCH_MP MEM_in_all_ts
             (CONJ (MATCH_MP in_av lk) m)))) THEN
       ASM_REWRITE_TAC[]) in
   (* the timestamp of the update is no timestamp of the Block *)
   let tp =
     REWRITE_TAC[FLOOKUP_UPDATE] THEN COND_CASES_TAC THENL
      [FIRST_ASSUM(fun tsc ->
         if not (is_tsc (concl tsc)) then fail() else
         MP_TAC(REWRITE_RULE[IN_SET_OF_LIST; vats; MEM] tsc)) THEN
       ASM_REWRITE_TAC[];
       FIRST_ASSUM MATCH_ACCEPT_TAC] in
   let NOT_VAR_TAC =
     FIRST_ASSUM(fun nb ->
       if is_neg(concl nb) && is_var(rand(concl nb))
       then SUBST_ALL_TAC(EQF_INTRO nb) else fail()) in
   let wit n =
     W(fun (asl,w) ->
       let thunk = tryfind (fun (_,th) ->
         let t = concl th in
         if is_eq t && hd_is "bvlSem_Thunk" (rand(rhs t))
         then rand(rhs t) else fail()) asl in
       if n = 5 then
         let x = tryfind (fun (_,th) ->
           let t = concl th in
           if is_eq t && hd_is "ThunkBlock" (rand(rhs t))
           then rand(rand(rhs t)) else fail()) asl in
         MAP_EVERY EXISTS_TAC [lhand thunk; rand thunk; x]
       else EXISTS_TAC (rand thunk)) in
   let d_thunk n =
     NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
     MATCH_MP_TAC(el n rl) THEN wit n THEN REPEAT CONJ_TAC THEN
     FIRST [FIRST_ASSUM MATCH_ACCEPT_TAC;
            DISCH_TAC THEN ih_thunk] in
   V_INV_REFS_TAC_IH ih tp prep ALL_TAC V_INV_HEAP_PLAIN
     (d_thunk 5) (d_thunk 6)));;

let v_inv_tf_update_thm_alt = prove
 (`!conf v refs y f tf heap ts' a stack'.
     v_inv conf v refs (y,f,tf,heap) /\ ~(ts' IN (all_ts refs
       stack')) /\ ~(ts' IN set_of_list (v_all_ts v)) ==>
     v_inv conf v refs (y,f,tf |+ (ts',a),heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_tf_update_thm_alt_lemma]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_tf_update_lemma = prove
 (cake_as_vars (fun () ->
    `!ck v1 refs v2.
       v_inv conf v1 refs v2 ==>
         (!ts tag xs y f tf heap.
           v1 = (Block ts tag xs) /\
           v2 = (y,f,tf,heap) /\
           v1 IN (all_vs refs stack) /\ ~(ts' IN all_ts refs stack)
             ==>
             v_inv_ck ck conf v1 refs (y,f,tf |+ (ts',a),heap))`),
  (* a Block of the refs and the stack: its timestamps are among
     the stack's (MEM_in_all_ts), so the new one is none of them
     and v_inv_tf_update_thm_alt applies *)
  (let no_ts = prove
    (cake_as_vars (fun () ->
       `x IN all_vs refs stack /\ ~(ts' IN all_ts refs stack)
        ==> ~(ts' IN set_of_list (v_all_ts x))`),
     REWRITE_TAC[IN_SET_OF_LIST] THEN REPEAT STRIP_TAC THEN
     FIRST_ASSUM(fun m ->
       if not (hd_is "MEM" (concl m)) then fail() else
       FIRST_ASSUM(fun av ->
         if not (hd_is "all_vs" (rand(concl av))) then fail() else
         MP_TAC(MATCH_MP MEM_in_all_ts (CONJ av m)))) THEN
     ASM_REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
   (* the two equations of the antecedent are substituted, and the
      first of them in the two hypotheses that follow it *)
   DISCH_THEN(fun th ->
     let e1 = CONJUNCT1 th and r1 = CONJUNCT2 th in
     let e2 = CONJUNCT1 r1 in
     SUBST_ALL_TAC e1 THEN SUBST_ALL_TAC e2 THEN
     STRIP_ASSUME_TAC(REWRITE_RULE[e1] (CONJUNCT2 r1))) THEN
   FIRST_ASSUM(fun av ->
     if not (hd_is "all_vs" (rand(concl av))) then fail() else
     FIRST_ASSUM(fun nts ->
       if not (is_neg (concl nts)) then fail() else
       let ts = MATCH_MP no_ts (CONJ av nts) in
       FIRST_ASSUM(fun vi ->
         if not (hd_is "v_inv" (concl vi)) then fail() else
         MATCH_ACCEPT_TAC(SPEC_ALL(REWRITE_RULE[v_inv_eq]
           (MATCH_MP v_inv_tf_update_thm_alt
             (CONJ vi (CONJ nts ts))))))))));;

let v_inv_tf_update = prove
 (`!conf refs y f tf heap heap1 a stack' ts ts' tag xs.
      (Block ts tag xs) IN (all_vs refs stack') /\ ~(ts' IN all_ts
        refs stack') /\
      v_inv conf (Block ts tag xs) refs (y,f,tf,heap) ==> v_inv
        conf ((Block ts tag xs)) refs (y,f,tf |+ (ts',a),heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_tf_update_lemma]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_tf_restrict_lemma = prove
 (cake_as_vars (fun () ->
    `!ck v1 refs y f tf heap.
       v_inv conf v1 refs (y,f,tf,heap) ==>
           (!x. MEM x (v_all_ts v1) ==> x IN P) /\
           (!x. x IN (all_ts refs stack) ==> x IN P) ==>
             v_inv_ck ck conf v1 refs (y,f,DRESTRICT tf P,heap)`),
  (* the same of a tf whose domain is restricted: a Block keeps its
     timestamp, which the hypothesis says is in the set, and of an
     element the induction hypothesis asks for the timestamps of
     the element (the Block's) -- of the value of a thunk for the
     refs' (MEM_in_all_ts) *)
  (let rl = v_inv_ck_rules in
   let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let nlt = ARITH_RULE `!n. ~(n = 0) ==> n - 1 < n` in
   (* the value that a thunk of the refs holds is a value of the
      refs, so its timestamps are the refs' *)
   let in_av = prove
    (cake_as_vars (fun () ->
       `lookup n refs = SOME (Thunk ev v)
        ==> v IN all_vs refs stack`),
     DISCH_TAC THEN
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
     DISJ2_TAC THEN DISJ1_TAC THEN
     MAP_EVERY EXISTS_TAC
       [`n:num`; `ev:thunk_mode`; `v:dataSem_v`] THEN
     ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC MEM_v_all_vs THEN REWRITE_TAC[MEM]) in
   (* the two conditions of the lemma *)
   let prep = DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) in
   (* the induction hypothesis at ck - 1, with the condition of the
      value it is applied to proved by the argument *)
   let ih_by tac =
     FIRST_ASSUM(fun nz ->
       let c = concl nz in
       if not(is_neg c) then fail() else
       let e = rand c in
       if not(is_eq e) || not(type_of(lhs e) = `:num`) ||
          not(rhs e = `0`) then fail() else
       let lt = MP (SPEC (lhs e) nlt) nz in
       FIRST_ASSUM(fun ihth ->
         let ih' = REWRITE_RULE[GSYM IMP_CONJ]
                     (MP (SPEC (mk_binop `(-):num->num->num`
                                  (lhs e) `1`) ihth) lt) in
         MATCH_MP_TAC ih' THEN REPEAT CONJ_TAC THEN
         TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN tac)) in
   (* the assumption about the timestamps of the value and the one
      about the timestamps of the refs *)
   let is_val a =
     let c = concl a in
     is_forall c &&
     (let b = snd(strip_forall c) in
      is_imp b &&
      (try hd_is "MEM" (lhand b) with Failure _ -> false)) in
   let is_refs a =
     let c = concl a in
     is_forall c &&
     (let b = snd(strip_forall c) in
      is_imp b &&
      (try hd_is "all_ts" (rand(lhand b)) with Failure _ -> false)) in
   (* the timestamps of an element of a Block are the Block's *)
   let ih =
     ih_by
      (GEN_TAC THEN DISCH_TAC THEN
       FIRST_ASSUM(fun a ->
         if not (is_val a) then fail() else MATCH_MP_TAC a) THEN
       REWRITE_TAC[vats; MEM; MEM_FLAT; MEM_MAP] THEN
       ASM_MESON_TAC[]) in
   (* and those of the value of a thunk are the refs' *)
   let ih_thunk =
     ih_by
      (GEN_TAC THEN DISCH_TAC THEN
       FIRST_ASSUM(fun b ->
         if not (is_refs b) then fail() else MATCH_MP_TAC b) THEN
       FIRST_ASSUM(fun m ->
         FIRST_ASSUM(fun lk ->
           MATCH_ACCEPT_TAC(MATCH_MP MEM_in_all_ts
             (CONJ (MATCH_MP in_av lk) m))))) in
   (* a Block keeps its timestamp, so the restriction keeps it *)
   let tp =
     REWRITE_TAC[FLOOKUP_DRESTRICT] THEN COND_CASES_TAC THENL
      [FIRST_ASSUM MATCH_ACCEPT_TAC;
       FIRST_ASSUM(fun nin ->
         if not (is_neg (concl nin)) then fail() else
         let t = lhand(rand(concl nin)) in
         if not (type_of t = `:num`) then fail() else
         FIRST_ASSUM(fun a ->
           if not (is_val a) then fail() else
           MP_TAC(SPEC t a))) THEN
       REWRITE_TAC[vats; MEM] THEN ASM_REWRITE_TAC[]] in
   let NOT_VAR_TAC =
     FIRST_ASSUM(fun nb ->
       if is_neg(concl nb) && is_var(rand(concl nb))
       then SUBST_ALL_TAC(EQF_INTRO nb) else fail()) in
   let wit n =
     W(fun (asl,w) ->
       let thunk = tryfind (fun (_,th) ->
         let t = concl th in
         if is_eq t && hd_is "bvlSem_Thunk" (rand(rhs t))
         then rand(rhs t) else fail()) asl in
       if n = 5 then
         let x = tryfind (fun (_,th) ->
           let t = concl th in
           if is_eq t && hd_is "ThunkBlock" (rand(rhs t))
           then rand(rand(rhs t)) else fail()) asl in
         MAP_EVERY EXISTS_TAC [lhand thunk; rand thunk; x]
       else EXISTS_TAC (rand thunk)) in
   let d_thunk n =
     NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
     MATCH_MP_TAC(el n rl) THEN wit n THEN REPEAT CONJ_TAC THEN
     FIRST [FIRST_ASSUM MATCH_ACCEPT_TAC;
            DISCH_TAC THEN ih_thunk] in
   V_INV_REFS_TAC_IH ih tp prep ALL_TAC V_INV_HEAP_PLAIN
     (d_thunk 5) (d_thunk 6)));;

let v_inv_tf_restrict = prove
 (`!conf v refs stack' y f tf heap P.
      v_inv conf v refs (y,f,tf,heap) /\
      (!x. MEM x (v_all_ts v) ==> x IN P) /\
      (!x. x IN (all_ts refs stack') ==> x IN P) ==>
        v_inv conf v refs (y,f,DRESTRICT tf P,heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_tf_restrict_lemma]));;

let v_all_vs_append = prove
 (`!x y. v_all_vs (x ++ y) = v_all_vs x ++ v_all_vs y`,
  (let vav = v_all_vs_def in
   let vnil = prove
    (`v_all_vs ([]:dataSem_v list) = []`,
     GEN_REWRITE_TAC LAND_CONV [vav] THEN MATCH_REDUCE_TAC THEN
     REWRITE_TAC[]) in
   LIST_INDUCT_TAC THENL
    [REWRITE_TAC[APPEND; vnil];
     GEN_TAC THEN REWRITE_TAC[APPEND] THEN CASES_ON_NAME "h" THEN
     GEN_REWRITE_TAC LAND_CONV [vav] THEN MATCH_REDUCE_TAC THEN
     GEN_REWRITE_TAC (RAND_CONV o LAND_CONV) [vav] THEN
     MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[APPEND; GSYM APPEND_ASSOC]]));;

let MEM_v_all_vs_split = prove
 (`!x v xs. MEM x (v_all_vs (v :: xs)) ==> MEM x (v_all_vs [v]) \/ MEM
  x (v_all_vs xs)`,
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   REPEAT GEN_TAC THEN
   GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV) [cons_app] THEN
   REWRITE_TAC[v_all_vs_append; MEM_APPEND]));;

let MEM_v_all_vs_split2 = prove
 (`MEM x (v_all_vs (v :: y :: xs)) ==>
     MEM x (v_all_vs (v :: xs)) \/ MEM x (v_all_vs [y])`,
  (* v_all_vs of a cons splits into the values of the head and the
     values of the tail (v_all_vs_append, as the source has it), and
     the three parts of v :: y :: xs go where they belong *)
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   let vcons = prove
    (`!(v:dataSem_v) xs y. MEM y (v_all_vs (CONS v xs)) <=>
        MEM y (v_all_vs [v]) \/ MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [cons_app] THEN
     REWRITE_TAC[v_all_vs_append; MEM_APPEND]) in
   MESON_TAC[vcons]));;

let MEM_v_all_vs_extend_tl = prove
 (`!x v xs. MEM x (v_all_vs [v]) ==> MEM x (v_all_vs (v :: xs))`,
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   REPEAT GEN_TAC THEN
   GEN_REWRITE_TAC (RAND_CONV o RAND_CONV o RAND_CONV) [cons_app] THEN
   REWRITE_TAC[v_all_vs_append; MEM_APPEND] THEN CONV_TAC TAUT));;

let MEM_v_all_vs_extend_hd = prove
 (`!x v xs. MEM x (v_all_vs xs) ==> MEM x (v_all_vs (v :: xs))`,
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   REPEAT GEN_TAC THEN
   GEN_REWRITE_TAC (RAND_CONV o RAND_CONV o RAND_CONV) [cons_app] THEN
   REWRITE_TAC[v_all_vs_append; MEM_APPEND] THEN CONV_TAC TAUT));;

let MEM_v_all_vs_extend_append = prove
 (`MEM x (v_all_vs xs) ==> MEM x (v_all_vs (xs ++ ys))`,
  (REWRITE_TAC[v_all_vs_append; MEM_APPEND] THEN CONV_TAC TAUT));;

let MEM_v_all_vs_EL = prove
 (`!xs i x.
     i < LENGTH xs /\
     MEM x (v_all_vs [EL i xs]) ==>
       MEM x (v_all_vs xs)`,
  (LIST_INDUCT_TAC THENL
    [REWRITE_TAC[LENGTH; LT];
     GEN_TAC THEN STRUCT_CASES_TAC (SPEC `i:num` num_CASES) THEN
     REWRITE_TAC[EL; HD; TL; LENGTH; LT_SUC; LT_0] THEN
     ASM_MESON_TAC[MEM_v_all_vs_extend_hd; MEM_v_all_vs_extend_tl]]));;

let MEM_v_all_vs_LUPDATE = prove
 (`!xs i v x.
     MEM x (v_all_vs (LUPDATE v i xs)) ==>
       MEM x (v_all_vs [v]) \/ MEM x (v_all_vs xs)`,
  (* the LUPDATE puts v where the index says and leaves the rest,
     so a value of the result is one of v or one of the list *)
  (let vnil = prove
    (`v_all_vs ([]:dataSem_v list) = []`,
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   LIST_INDUCT_TAC THEN REWRITE_TAC[LUPDATE] THENL
    [REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN COND_CASES_TAC THEN
     DISCH_THEN(fun th -> MP_TAC(MATCH_MP MEM_v_all_vs_split th)) THEN
     STRIP_TAC THEN
     FIRST [DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
            DISJ2_TAC THEN MATCH_MP_TAC MEM_v_all_vs_extend_hd THEN
            FIRST_ASSUM ACCEPT_TAC;
            DISJ2_TAC THEN MATCH_MP_TAC MEM_v_all_vs_extend_tl THEN
            FIRST_ASSUM ACCEPT_TAC;
            FIRST_ASSUM(fun ih -> MP_TAC(SPECL
              [`i - 1`; `v:dataSem_v`; `x:dataSem_v`] ih)) THEN
            ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
            MATCH_MP_TAC(TAUT `(b ==> c) ==> (a \/ b ==> a \/ c)`) THEN
            MATCH_ACCEPT_TAC MEM_v_all_vs_extend_hd]]));;

let all_vs_Block = prove
 (`all_vs refs ((Block t tag xs:dataSem_v) :: ys) =
   Block t tag xs INSERT all_vs refs (xs ++ ys)`,
  (let vav_block = prove
    (`!t tag xs ys.
        v_all_vs (CONS (Block t tag xs) ys) =
        APPEND (CONS (Block t tag xs) (v_all_vs xs)) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   REWRITE_TAC[all_vs_def; v_all_vs_append; vav_block] THEN
   REWRITE_TAC[EXTENSION; IN_INSERT; IN_UNION; IN_ELIM_THM;
               MEM_APPEND; MEM] THEN
   MESON_TAC[]));;

let blocks_unique_cons_thm = prove
 (`blocks_unique ts s ==>
   blocks_unique (ts + 1) (Block ts tag xs INSERT s)`,
  (* the four cases of the two Blocks: both the new one (the goal is
     then an equation of the arguments), one of them the new one (the
     other has a timestamp below ts, so the two cannot be equal), or
     both in the set (which is what the hypothesis is about).  The
     instance of the hypothesis is written down, because its
     antecedent has to be discharged by the assumptions as they
     stand: rewriting with t = ts first would put the antecedent out
     of reach of them. *)
  (let inst a b c d =
     FIRST_ASSUM(fun h -> MP_TAC(SPECL [`t:num`; a; b; c; d] h)) THEN
     ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] in
   let a1 = `a1:num` and x1 = `xs1:dataSem_v list`
   and a2 = `a2:num` and x2 = `xs2:dataSem_v list` in
   REWRITE_TAC[blocks_unique_def; IN_INSERT;
               injectivity "dataSem_v"] THEN
   DISCH_TAC THEN REPEAT GEN_TAC THEN DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST
    [ASM_REWRITE_TAC[] THEN ARITH_TAC;
     inst a1 x1 a2 x2 THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     ASM_ARITH_TAC;
     inst a2 x2 a2 x2 THEN STRIP_TAC THEN
     SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC;
     inst a1 x1 a1 x1 THEN STRIP_TAC THEN
     SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC]));;

(* the kind of the collection when it is not a generational one:
   then it says nothing of the heap but that the second part of the
   space is empty, which an allocation does not touch *)
let gc_kind_not_gen_any = prove
 (cake_as_vars (fun () ->
    `gc_kind_inv conf a sp sp1 gens heap /\
     (!gs. ~(data_to_word_config_gc_kind conf =
             data_to_word_Generational gs))
     ==> gc_kind_inv conf a2 sp2 sp1 gens heap2`),
  REWRITE_TAC[gc_kind_inv_def] THEN STRIP_TAC THEN
  W(fun (asl,w) ->
    CASES_ON_TAC (find_term
      (hd_is "data_to_word_config_gc_kind") w)) THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
  MATCH_REDUCE_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  W(fun gl ->
    let ng = the_asm (fun c ->
               let vs,bd = strip_forall c in
               length vs = 1 && is_neg bd) gl in
    MP_TAC ng) THEN
  MESON_TAC[]);;

(* an element that the heap had, a store that keeps the elements
   keeps *)
let heap_store_rel_keep = prove
 (`heap_store_rel heap heap2 /\ isDataElement y /\
   heap_lookup n heap = SOME y
   ==> heap_lookup n heap2 = SOME y`,
  REWRITE_TAC[isDataElement_def] THEN
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (lhand c)) then fail() else
    SUBST_ALL_TAC e)) THEN
  W(fun gl ->
    let hsr = the_asm (hd_is "heap_store_rel") gl in
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    ACCEPT_TAC (MATCH_MP heap_store_rel_lemma (CONJ hsr hl))));;

(* the elements of the heap that the port builds are all data
   elements, and this is the one of them that a term is *)
let is_data_el t =
  tryfind (fun th ->
    PART_MATCH I th (list_mk_icomb "isDataElement" [t]))
    (CONJUNCTS isDataElement_lemmas);;

(* an address whose element is a data element holds data *)
let isSome_lookup = prove
 (`heap_lookup n heap = SOME y /\ isDataElement y
   ==> isSomeDataElement (heap_lookup n heap)`,
  REWRITE_TAC[isDataElement_def; isSomeDataElement_def] THEN
  MESON_TAC[]);;

(* and the values of an arm go over with the transfer *)
let EVERY2_v_inv_alloc = prove
 (cake_as_vars (fun () ->
    `(!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 refs2 (w2,f2,tf2,heap2)) /\
     EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap)) zs ys
     ==> EVERY2 (\z y. v_inv conf y refs2 (z,f2,tf2,heap2)) zs ys`),
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  W(fun (asl,w as gl) ->
    let old = the_asm (hd_is "ALL2") gl in
    let gargs = snd (strip_comb w) in
    let oargs = snd (strip_comb (concl old)) in
    let zs = el 1 gargs and ys = el 2 gargs in
    let p1 = el 0 oargs and p2 = el 0 gargs in
    let xv = genvar (hd (snd (dest_type (type_of zs)))) in
    let yv = genvar (hd (snd (dest_type (type_of ys)))) in
    let step = list_mk_forall([xv; yv],
                 mk_imp(list_mk_conj
                   [list_mk_icomb "MEM" [xv; zs];
                    list_mk_icomb "MEM" [yv; ys];
                    mk_comb(mk_comb(p1,xv),yv)],
                   mk_comb(mk_comb(p2,xv),yv))) in
    SUBGOAL_THEN step (fun st ->
      ACCEPT_TAC (MP (MP (ISPECL [zs; ys; p1; p2]
                            EVERY2_IMP_EVERY2) st) old)) THEN
    REPEAT GEN_TAC THEN
    CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    STRIP_TAC THEN
    W(fun gl ->
      let vi = the_asm (hd_is "v_inv") gl in
      MATCH_ACCEPT_TAC (MATCH_MP (a_vtr gl) vi))));;

(* the map with a fresh point, into the addresses that hold data
   with the one written added *)
let INJ_FUPDATE_fresh = prove
 (`!(f:(num,num)fmap) ptr aa s s2.
     INJ (FAPPLY f) (FDOM f) s /\ ~(ptr IN FDOM f) /\ ~(aa IN s) /\
     (!x. x IN s2 <=> x = aa \/ x IN s)
     ==> INJ (FAPPLY (f |+ (ptr,aa))) (FDOM (f |+ (ptr,aa))) s2`,
  REWRITE_TAC[INJ; FDOM_FUPDATE; IN_INSERT; FAPPLY_FUPDATE_THM] THEN
  MESON_TAC[]);;

(* and what its images are: the one of the fresh key is the
   address, which held no data, so the images of the addresses that
   do hold data are the ones they were *)
let IMAGE_FUPDATE_fresh = prove
 (`!(tf:(num,num)fmap) ts' aa heap.
     ~(ts' IN FDOM tf) /\
     ~(isSomeDataElement (heap_lookup aa heap))
     ==> !y. isSomeDataElement (heap_lookup y heap) /\
             ~(y IN IMAGE (FAPPLY tf) (FDOM tf))
             ==> ~(y IN IMAGE (FAPPLY (tf |+ (ts',aa)))
                     (FDOM (tf |+ (ts',aa))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[IN_IMAGE; FDOM_FUPDATE; IN_INSERT] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:num` MP_TAC) THEN
  REWRITE_TAC[FAPPLY_FUPDATE_THM] THEN
  COND_CASES_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[IN_IMAGE]);;

(* and a map into a bigger set of addresses *)
let INJ_bigger = prove
 (`!(g:A->B) d s s2.
     INJ g d s /\ (!x. x IN s ==> x IN s2) ==> INJ g d s2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[INJ] THEN MESON_TAC[]);;

(* an address that held data still does *)
let isSome_store_rel = prove
 (`heap_store_rel heap heap2 /\
   isSomeDataElement (heap_lookup n heap)
   ==> isSomeDataElement (heap_lookup n heap2)`,
  REWRITE_TAC[heap_store_rel_def] THEN MESON_TAC[]);;

(* and the values of a stack go over with it as well *)
let EVERY2_v_inv_alloc_stack = prove
 (cake_as_vars (fun () ->
    `(!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 refs2 (w2,f2,tf2,heap2)) /\
     EVERY2 (\v x. v_inv conf v refs (x,f,tf,heap)) vs rs
     ==> EVERY2 (\v x. v_inv conf v refs2 (x,f2,tf2,heap2)) vs rs`),
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  W(fun (asl,w as gl) ->
    let old = the_asm (hd_is "ALL2") gl in
    let gargs = snd (strip_comb w) in
    let oargs = snd (strip_comb (concl old)) in
    let zs = el 1 gargs and ys = el 2 gargs in
    let p1 = el 0 oargs and p2 = el 0 gargs in
    let xv = genvar (hd (snd (dest_type (type_of zs)))) in
    let yv = genvar (hd (snd (dest_type (type_of ys)))) in
    let step = list_mk_forall([xv; yv],
                 mk_imp(list_mk_conj
                   [list_mk_icomb "MEM" [xv; zs];
                    list_mk_icomb "MEM" [yv; ys];
                    mk_comb(mk_comb(p1,xv),yv)],
                   mk_comb(mk_comb(p2,xv),yv))) in
    SUBGOAL_THEN step (fun st ->
      ACCEPT_TAC (MP (MP (ISPECL [zs; ys; p1; p2]
                            EVERY2_IMP_EVERY2) st) old)) THEN
    REPEAT GEN_TAC THEN
    CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    STRIP_TAC THEN
    W(fun gl ->
      let vi = the_asm (hd_is "v_inv") gl in
      MATCH_ACCEPT_TAC (MATCH_MP (a_vtr gl) vi))));;

(* the invariant of a reference that a step did not touch: its
   element is where it was (heap_store_rel), the lookups of its
   key are what they were, and what the invariant says of a value
   is what the transfer says.  The last condition is what the arm
   of a mutable block asks: the cell of one that is not finalised
   holds data, so a map of timestamps that no address which holds
   data was added to points at it no more than the old one did.
   The hypotheses are an implication each (IMP_CONJ), so that
   a proof can hand over the ones it has and leave the two
   conditions about the maps to be proved of the maps the goal
   names *)
let bc_ref_inv_step = prove
 (cake_as_vars (fun () ->
    `(!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 refs2 (w2,f2,tf2,heap2)) /\
     n IN FDOM (f:(num,num)fmap) /\
     heap_store_rel heap heap2 /\
     bc_ref_inv conf n refs (f,tf,heap,be') /\
     sptree_lookup n refs2 = sptree_lookup n refs /\
     (!w. dest_thunk w refs = NotThunk
          ==> dest_thunk w refs2 = NotThunk) /\
     (!y. isSomeDataElement (heap_lookup y heap) /\
          ~(y IN IMAGE (FAPPLY tf) (FDOM tf))
          ==> ~(y IN IMAGE (FAPPLY tf2) (FDOM tf2))) /\
     FLOOKUP f2 n = FLOOKUP f n
     ==> bc_ref_inv conf n refs2 (f2,tf2,heap2,be')`),
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  (* the address of the key is the one it had, in the map it had
     and in the map the goal names *)
  W(fun (asl,w as gl) ->
    let inn = the_asm (fun c -> hd_is "IN" c &&
                hd_is "FDOM" (rand c)) gl in
    let n = el 0 (snd (strip_comb (concl inn))) in
    let fm = rand (rand (concl inn)) in
    let fm2 = el 0 (tparts (el 3 (snd (strip_comb w)))) in
    let x = list_mk_icomb "fmap_apply" [fm; n] in
    SUBGOAL_THEN (mk_eq (list_mk_icomb "FLOOKUP" [fm; n],
                         list_mk_icomb "SOME" [x])) ASSUME_TAC THENL
     [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC] THEN
    SUBGOAL_THEN (mk_eq (list_mk_icomb "FLOOKUP" [fm2; n],
                         list_mk_icomb "SOME" [x])) ASSUME_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (* and the kind of what the key holds says which arm it is *)
  W(fun gl ->
    let lk = the_asm (fun c -> is_eq c &&
               hd_is "sptree_lookup" (lhand c) &&
               hd_is "sptree_lookup" (rand c)) gl in
    NAMED_CASES_TAC (rand (concl lk)) [[]; ["rv"]]) THEN
  TRY (SOLVED (FIRST_X_ASSUM (fun inv ->
    if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
    MP_TAC (REWRITE_RULE[bc_ref_inv_def] inv)) THEN
    ASM_REWRITE_TAC[] THEN REDUCE_MATCH_HARD)) THEN
  NAMED_CASES_TAC (cake_as_vars (fun () ->
    `rv:(dataSem_v)bvlSem_ref`))
    [["l"]; ["flag"; "bs"]; ["ev"; "vv"];
     ["tg"; "fin"; "ll"; "cc"; "rr"]] THEN
  USE_ARMS THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  SPLIT_ASM_TAC THEN
  (* the array of bytes: only the element, which is where it was *)
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
  (* the element of every arm is where it was *)
  W(fun gl ->
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c) &&
               hd_is "SOME" (rand c)) gl in
    let hsr = the_asm (hd_is "heap_store_rel") gl in
    let el1 = rand (rand (concl hl)) in
    ASSUME_TAC (MATCH_MP heap_store_rel_keep
      (CONJ hsr (CONJ (is_data_el el1) hl)))) THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  (* the thunk: the element, that it is still not a thunk, and its
     value *)
  TRY (SOLVED
        (W(fun (asl,w as gl) ->
           let bod = snd (strip_exists w) in
           let heap2 = el 1 (snd (strip_comb
                         (lhand (hd (conjuncts bod))))) in
           let hl2 = the_asm (fun c -> is_eq c &&
                       hd_is "heap_lookup" (lhand c) &&
                       el 1 (snd (strip_comb (lhand c))) = heap2 &&
                       hd_is "SOME" (rand c)) gl in
           EXISTS_TAC (rand (rand (rand (concl hl2))))) THEN
         REPEAT CONJ_TAC THEN
         TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
         TRY (SOLVED
               (DISCH_THEN (fun ee ->
                  W(fun gl ->
                    let impl = the_asm (fun c -> is_imp c &&
                                 (try hd_is "dataSem_dest_thunk"
                                        (lhand (rand c))
                                  with Failure _ -> false)) gl in
                    ACCEPT_TAC (MATCH_MP (a_dtr gl)
                      (MP impl ee)))))) THEN
         W(fun gl ->
           let vi = the_asm (hd_is "v_inv") gl in
           MATCH_ACCEPT_TAC (MATCH_MP (a_vtr gl) vi)))) THEN
  (* the array of values and the mutable block: the element and its
     values *)
  REPEAT CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  (* no timestamp points at the cell of a mutable block that is
     not finalised: the cell holds data, and the map of the
     timestamps gained no address that does *)
  TRY (SOLVED
        (DISCH_THEN (fun nf ->
           W(fun (asl,w as gl) ->
             let hsr = the_asm (hd_is "heap_store_rel") gl in
             let old = el 0 (snd (strip_comb (concl hsr))) in
             let imp = the_asm (fun c -> is_imp c && is_neg (rand c) &&
                         hd_is "IN" (rand (rand c))) gl in
             let img = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_imp bd &&
                         is_conj (lhand bd) &&
                         hd_is "isSomeDataElement" (lhand (lhand bd)))
                         gl in
             let hl = the_asm (fun c -> is_eq c &&
                        hd_is "heap_lookup" (lhand c) &&
                        el 1 (snd (strip_comb (lhand c))) = old &&
                        hd_is "SOME" (rand c)) gl in
             let isd = MATCH_MP isSome_lookup
                         (CONJ hl
                           (is_data_el (rand (rand (concl hl))))) in
             MATCH_ACCEPT_TAC
               (MATCH_MP img (CONJ isd (MP imp nf))))))) THEN
  W(fun (asl,w as gl) ->
    let bod = snd (strip_exists w) in
    let heap2 = el 1 (snd (strip_comb
                  (lhand (hd (conjuncts bod))))) in
    let keep = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 el 1 (snd (strip_comb (lhand c))) = heap2 &&
                 hd_is "SOME" (rand c)) gl in
    EXISTS_TAC (rand (rand (rand (concl keep)))) THEN
    CONJ_TAC THENL
     [ACCEPT_TAC keep;
      W(fun gl ->
        let old = the_asm (hd_is "ALL2") gl in
        MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc
          (CONJ (a_vtr gl) old)))]));;

(* the split of a heap at the length of its first part is that
   part *)
let heap_split_pre = prove
 (`!(ha:(('a,'b)heap_element) list) hb n.
     heap_length ha = n ==> heap_split n (ha ++ hb) = SOME (ha,hb)`,
  REPEAT GEN_TAC THEN DISCH_THEN (SUBST1_TAC o SYM) THEN
  REWRITE_TAC[heap_split_APPEND_if; LT_REFL; SUB_REFL;
              heap_split_0] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[APPEND_NIL]);;

(* no block is a reference *)
let isRef_BlockRep = prove
 (`~(data_to_word_memoryProof_isRef (BlockRep tag ys))`,
  REWRITE_TAC[isRef_def; BlockRep_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[isMutTag_def] THEN
  MATCH_REDUCE_TAC THEN
  REWRITE_TAC[distinctness "data_to_word_memoryProof_tag"]);;

(* the kind of the collection survives a store into the unused
   space at its low end: the state of the generations is what
   heap_store_unused_alt_gen_state_ok says, and the split of the
   new heap is at the address the old one was split at, with the
   element written and the space that is left in its first part,
   where no element is a reference *)
let gc_kind_store_unused_alt = prove
 (cake_as_vars (fun () ->
    `~(data_to_word_memoryProof_isRef x) /\ el_length x <= sp /\
     gc_kind_inv conf a sp sp1 gens heap /\
     heap_store_unused_alt a (sp + sp1) x heap = (heap2,T) /\
     unused_space_inv (a + el_length x) ((sp + sp1) - el_length x)
       heap2
     ==> gc_kind_inv conf (a + el_length x) (sp - el_length x) sp1
           gens heap2`),
  REWRITE_TAC[gc_kind_inv_def] THEN STRIP_TAC THEN
  W(fun (asl,w) ->
    CASES_ON_TAC (find_term
      (hd_is "data_to_word_config_gc_kind") w)) THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
  MATCH_REDUCE_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  SPLIT_ASM_TAC THEN
  CONJ_TAC THENL
   [(* the state of the generations *)
    W(fun (asl,w as gl) ->
      let gs = the_asm (hd_is "gen_state_ok") gl in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let th = MATCH_MP heap_store_unused_alt_gen_state_ok
                 (CONJ st gs) in
      let addr = el 1 (snd (strip_comb w)) in
      let addr2 = el 1 (snd (strip_comb (concl th))) in
      SUBGOAL_THEN (mk_eq (addr, addr2)) SUBST1_TAC THENL
       [ASM_ARITH_TAC; MATCH_ACCEPT_TAC th]);
    ALL_TAC] THEN
  (* the shape of the new heap: what was below the space, the
     element written, the space that is left and the references *)
  W(fun (asl,w as gl) ->
    let hs = the_asm (fun c -> is_eq c &&
               hd_is "heap_split" (lhand c)) gl in
    let st = the_asm (fun c -> is_eq c &&
               hd_is "heap_store_unused_alt" (lhand c)) gl in
    let us = the_asm (fun c -> hd_is "unused_space_inv" c &&
               can (find_term (hd_is "-")) c) gl in
    STRIP_ASSUME_TAC (MATCH_MP heap_store_unused_alt_thm
      (CONJ hs (CONJ st us)))) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[APPEND_ASSOC]) THEN
  W(fun (asl,w as gl) ->
    let st = the_asm (fun c -> is_eq c &&
               hd_is "heap_store_unused_alt" (lhand c)) gl in
    let heap2 = lhand (rand (concl st)) in
    let sh = the_asm (fun c -> is_eq c && lhand c = heap2 &&
               hd_is "APPEND" (rand c)) gl in
    let pre = lhand (rand (concl sh)) in
    let rest = rand (rand (concl sh)) in
    let addr = el 0 (snd (strip_comb
                 (lhand (hd (conjuncts (snd (strip_exists w))))))) in
    EXISTS_TAC pre THEN EXISTS_TAC rest THEN
    REPEAT CONJ_TAC THENL
     [(* the split of the new heap is at the address the old one
          was split at *)
      SUBGOAL_THEN (mk_eq (list_mk_icomb "heap_length" [pre], addr))
        (fun le -> ONCE_REWRITE_TAC[sh] THEN
                   MATCH_ACCEPT_TAC (MATCH_MP heap_split_pre le)) THEN
      REWRITE_TAC[heap_length_APPEND; heap_length_clauses;
                  heap_length_heap_expand] THEN
      ASM_ARITH_TAC;
      (* and no element of its first part is a reference: of what
         was below the space the old split says so, the element
         written is no reference and the space holds none *)
      REWRITE_TAC[ALL_APPEND; ALL] THEN
      REPEAT CONJ_TAC THEN
      TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
      TRY (SOLVED (MATCH_ACCEPT_TAC isRef_heap_expand)) THEN
      W(fun gl ->
        let ev = the_asm (fun c -> hd_is "ALL" c &&
                   is_abs (el 0 (snd (strip_comb c)))) gl in
        let sh1 = the_asm (fun c -> is_eq c &&
                    el 1 (snd (strip_comb (concl ev))) = lhand c &&
                    hd_is "APPEND" (rand c)) gl in
        MP_TAC (REWRITE_RULE[sh1; ALL_APPEND] ev)) THEN
      DISCH_THEN (ACCEPT_TAC o CONJUNCT1);
      FIRST_ASSUM ACCEPT_TAC]));;

(* a reference of a value of a block is a reference of the block *)
let refs_of_block = prove
 (`!r ts tag xs. MEM r (get_refs (Block ts tag xs:dataSem_v))
                 ==> ?y. MEM y xs /\ MEM r (get_refs y)`,
  REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN MESON_TAC[]);;

(* so a reference that the stack with a block on it reaches is one
   that the values of the block and the rest of the stack reach *)
let reachable_refs_cons = prove
 (`!stack refs n ts tag xs.
     reachable_refs ((Block ts tag xs:dataSem_v) :: stack) refs n
     ==> reachable_refs (xs ++ stack) refs n`,
  (* the value that holds the reference is the block, and then one
     of its values holds it, or it is one of the stack's *)
  let wit =
    W(fun (asl,w as gl) ->
      let mm = the_asm (fun c -> hd_is "MEM" c &&
                 hd_is "get_refs" (rand c)) gl in
      EXISTS_TAC (el 0 (snd (strip_comb (rand (concl mm))))) THEN
      EXISTS_TAC (el 0 (snd (strip_comb (concl mm))))) in
  REPEAT GEN_TAC THEN REWRITE_TAC[reachable_refs_def; MEM] THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    FIRST_X_ASSUM (fun m ->
      if not (hd_is "MEM" (concl m)) then fail() else
      STRIP_ASSUME_TAC (MATCH_MP refs_of_block m)) THEN
    wit;
    wit] THEN
  ASM_REWRITE_TAC[MEM_APPEND]);;

(* and what the invariant says of a value it says of it with a
   block allocated and a timestamp for it that the map of the
   timestamps did not have *)
let v_inv_cons_step = prove
 (cake_as_vars (fun () ->
    `v_inv conf w1 refs (w2,f,tf,heap) /\ ~(ts' IN FDOM tf) /\
     heap_store_rel heap heap2 /\ tf2 = tf |+ (ts',aa)
     ==> v_inv conf w1 refs (w2,f,tf2,heap2)`),
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  FIRST_X_ASSUM SUBST_ALL_TAC THEN
  W(fun gl ->
    let vi = the_asm (hd_is "v_inv") gl in
    let hsr = the_asm (hd_is "heap_store_rel") gl in
    let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c)) gl in
    MATCH_ACCEPT_TAC (MATCH_MP v_inv_tf_update_thm
      (CONJ (MATCH_MP heap_store_rel_v_inv (CONJ hsr vi)) nd))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let cons_thm_alt = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ stack) refs (roots,heap,be,a,sp,sp1,gens)
  limit ts /\
      LENGTH xs < sp /\ ~(xs = []) ==>
      (?rs roots2 heap2.
        (roots = rs ++ roots2) /\ (LENGTH rs = LENGTH xs) /\
        (heap_store_unused_alt a (sp + sp1) (BlockRep tag rs) heap
          = (heap2,T)) /\
        abs_ml_inv conf
          ((Block ts tag xs) :: stack) refs
          (gc_shared_Pointer a (wordLang_Word (ptr_bits conf tag
            (LENGTH xs))) :: roots2,
           heap2,be,a + el_length (BlockRep tag rs),
           sp - el_length (BlockRep tag rs),sp1,gens) limit (ts +
             1))`),
  (* the steps are above the statement (tools/overrides.py).  The
     timestamp of the block is one that the map of the timestamps
     does not have, because every one of its is below it; the roots
     of the values of the block are the front of the roots of the
     stack (LIST_REL_SPLIT1), the block fits in the unused space
     and IMP_heap_store_unused_alt writes it there.  The heap, the
     roots and the space are then as good as they were
     (gc_kind_store_unused_alt of the kind of the collection), the
     map of the timestamps gains the one of the block with the
     address it was written at, and of every reference that the
     stack reaches the invariant holds as it did
     (bc_ref_inv_step) *)
  (STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* what the invariant says of the stack that the block is built
       from *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    (* the timestamp of the block is fresh: every timestamp of the
       map is below it *)
    W(fun (asl,w as gl) ->
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "GSPEC" (rand c)) gl in
      let tf = rand (lhand (concl su)) in
      let bl = find_term (hd_is "dataSem_Block") w in
      let ts = el 0 (snd (strip_comb bl)) in
      SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
                      [ts; list_mk_icomb "FDOM" [tf]])) ASSUME_TAC THENL
       [MP_TAC su THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
        MESON_TAC[LT_REFL];
        ALL_TAC]) THEN
    (* the roots of the values of the block, and the rest *)
    W(fun gl ->
      let e2 = the_asm (hd_is "ALL2") gl in
      STRIP_ASSUME_TAC (ONCE_REWRITE_RULE[LIST_REL_SPLIT1] e2)) THEN
    (* the roots of the block are as many as its values *)
    W(fun (asl,w as gl) ->
      let bl = find_term (hd_is "dataSem_Block") w in
      let xs = el 2 (snd (strip_comb bl)) in
      let e1 = the_asm (fun c -> hd_is "ALL2" c &&
                 el 1 (snd (strip_comb c)) = xs) gl in
      ASSUME_TAC (MATCH_MP LIST_REL_LENGTH e1)) THEN
    (* so the block fits in the unused space, and the store writes it
       there *)
    W(fun (asl,w as gl) ->
      let us = the_asm (hd_is "unused_space_inv") gl in
      let spsp = el 1 (snd (strip_comb (concl us))) in
      let bl = find_term (hd_is "dataSem_Block") w in
      let xs = el 2 (snd (strip_comb bl)) in
      let e1 = the_asm (fun c -> hd_is "ALL2" c &&
                 el 1 (snd (strip_comb c)) = xs) gl in
      let ys1 = el 2 (snd (strip_comb (concl e1))) in
      let br = rator (find_term (hd_is "BlockRep") w) in
      let el1 = mk_comb (br, ys1) in
      SUBGOAL_THEN (list_mk_icomb "<="
                      [list_mk_icomb "el_length" [el1]; spsp])
        (fun bd -> STRIP_ASSUME_TAC (MATCH_MP
           IMP_heap_store_unused_alt (CONJ us bd))) THENL
       [REWRITE_TAC[BlockRep_def; el_length_def] THEN
        ASM_ARITH_TAC;
        ALL_TAC]) THEN
    (* the block is a data element, which is what the two facts about
       the store ask for *)
    W(fun gl ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
      let isd = is_data_el el1 in
      MAP_EVERY (fun th -> ASSUME_TAC (MP th isd))
        (mapfilter (fun (_,th) ->
           let c = concl th in
           if is_imp c && hd_is "isDataElement" (lhand c) then th
           else fail()) (fst gl))) THEN
    (* the witnesses: the roots of the block, the rest of them, and
       the heap that the store wrote *)
    W(fun (asl,w as gl) ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let ys1 = el 1 (snd (strip_comb
                  (el 2 (snd (strip_comb (lhand (concl st))))))) in
      let heap2 = lhand (rand (concl st)) in
      let rts = the_asm (fun c -> is_eq c && is_var (lhand c) &&
                  hd_is "APPEND" (rand c)) gl in
      MAP_EVERY EXISTS_TAC [ys1; rand (rand (concl rts)); heap2]) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    TRY (SOLVED (W(fun gl ->
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "LENGTH" (lhand c) &&
                 hd_is "LENGTH" (rand c)) gl in
      ACCEPT_TAC (SYM le)))) THEN
    (* and the invariant of the new heap and stack *)
    REWRITE_TAC[abs_ml_inv_def] THEN
    (* the addresses that hold data are the ones that did, and the
       one the store wrote *)
    W(fun gl ->
      let seq = the_asm (fun c -> is_eq c &&
                  hd_is "INSERT" (rand c)) gl in
      let ro = the_asm (hd_is "roots_ok") gl in
      ASSUME_TAC (REWRITE_RULE[EXTENSION; IN_INSERT; IN_ELIM_THM]
                    seq) THEN
      ASSUME_TAC (REWRITE_RULE[roots_ok_def] ro)) THEN
    REPEAT CONJ_TAC THEN
    (* the roots: the one of the block is the address it was written
       at, and the others are the ones they were *)
    TRY (SOLVED
          (REWRITE_TAC[roots_ok_def; MEM] THEN
           REPEAT STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           TRY (SOLVED
                 (DISJ1_TAC THEN
                  FIRST_X_ASSUM (fun e ->
                    if not (is_eq (concl e)) ||
                       not (hd_is "gc_shared_Pointer" (rand (concl e)))
                    then fail() else
                    MP_TAC e) THEN
                  REWRITE_TAC[injectivity "heap_address"] THEN
                  MESON_TAC[])) THEN
           DISJ2_TAC THEN
           ASM_MESON_TAC[MEM_APPEND])) THEN
    (* the heap is good: it is as long as it was, it has no forward
       pointer, and the pointers of the block are roots of the stack *)
    TRY (SOLVED
          (REWRITE_TAC[heap_ok_def] THEN
           REPEAT CONJ_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let hl = the_asm (fun c -> is_eq c &&
                               hd_is "heap_length" (lhand c)) gl in
                    MP_TAC ho THEN REWRITE_TAC[hl] THEN
                    STRIP_TAC THEN ASM_REWRITE_TAC[]))) THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let impl = the_asm (fun c -> is_imp c &&
                                 is_neg (lhand c) &&
                                 hd_is "isForwardPointer"
                                   (rand (lhand c))) gl in
                    let st = the_asm (fun c -> is_eq c &&
                               hd_is "heap_store_unused_alt"
                                 (lhand c)) gl in
                    let el1 = el 2 (snd (strip_comb
                                (lhand (concl st)))) in
                    SUBGOAL_THEN (mk_neg (list_mk_icomb
                                    "isForwardPointer" [el1]))
                      (fun nf -> MP_TAC ho THEN
                         REWRITE_TAC[MP impl nf] THEN
                         STRIP_TAC THEN ASM_REWRITE_TAC[]) THEN
                    REWRITE_TAC[BlockRep_def; isForwardPointer_def] THEN
                    MATCH_REDUCE_TAC THEN REWRITE_TAC[]))) THEN
           (* the pointers: of the block they are its roots, which the
              stack had, and of any other element they are what they
              were *)
           REPEAT GEN_TAC THEN
           W(fun gl ->
             let mem = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 3 && is_eq bd &&
                         hd_is "MEM" (lhand bd)) gl in
             REWRITE_TAC[mem]) THEN
           STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           DISJ2_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let eq = the_asm (fun c -> is_eq c &&
                               hd_is "BlockRep" (lhand c)) gl in
                    MP_TAC eq) THEN
                  REWRITE_TAC[BlockRep_def;
                              injectivity "heap_element"] THEN
                  STRIP_TAC THEN
                  ASM_MESON_TAC[MEM_APPEND])) THEN
           W(fun gl ->
             let ho = REWRITE_RULE[heap_ok_def]
                        (the_asm (hd_is "heap_ok") gl) in
             MP_TAC ho) THEN
           ASM_MESON_TAC[])) THEN
    (* the kind of the collection: the store into the unused space
       keeps it (gc_kind_store_unused_alt).  The statement says
       el_length (BlockRep tag rs) of the pointer and of the space
       with a type variable of its own, so the length of the block
       is worked out on both sides before they are matched
       (entry 61) *)
    W(fun (asl,w as gl) ->
      if not (hd_is "gc_kind_inv" w) then ALL_TAC else
      (let gk = the_asm (hd_is "gc_kind_inv") gl in
       let st = the_asm (fun c -> is_eq c &&
                  hd_is "heap_store_unused_alt" (lhand c)) gl in
       let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
       let sp = el 2 (snd (strip_comb (concl gk))) in
       let us2 = the_asm (fun c -> hd_is "unused_space_inv" c &&
                   can (find_term (hd_is "-")) c) gl in
       let nr = PART_MATCH I isRef_BlockRep
                  (mk_neg (list_mk_icomb
                     "data_to_word_memoryProof_isRef" [el1])) in
       let reduce th = CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)
                         (REWRITE_RULE[BlockRep_def;
                                       el_length_def] th) in
       SUBGOAL_THEN (list_mk_icomb "<="
                       [list_mk_icomb "el_length" [el1]; sp])
         (fun bd ->
            REWRITE_TAC[BlockRep_def; el_length_def] THEN
            CONV_TAC(TOP_DEPTH_CONV MATCH_CONV) THEN
            MATCH_ACCEPT_TAC (reduce (MATCH_MP
              gc_kind_store_unused_alt
              (CONJ nr (CONJ bd (CONJ gk (CONJ st us2))))))) THEN
       REWRITE_TAC[BlockRep_def; el_length_def] THEN
       ASM_ARITH_TAC)) THEN
    (* the unused space: what the store lemma says, with the length
       of the block taken off the first part of it.  The statement
       says el_length (BlockRep tag rs) of the pointer and of the
       space with two type variables of its own, so both are reduced
       to the length of the block first (entry 61) *)
    W(fun (asl,w as gl) ->
      if not (hd_is "unused_space_inv" w) then ALL_TAC else
      (let us = the_asm (fun c -> hd_is "unused_space_inv" c &&
                  can (find_term (hd_is "-")) c) gl in
       REWRITE_TAC[BlockRep_def; el_length_def] THEN
       MP_TAC (REWRITE_RULE[BlockRep_def; el_length_def] us) THEN
       W(fun (asl,w) ->
         let usub = el 1 (snd (strip_comb (lhand w))) in
         let gsub = el 1 (snd (strip_comb (rand w))) in
         SUBGOAL_THEN (mk_eq (usub, gsub)) ASSUME_TAC THENL
          [ASM_ARITH_TAC; ASM_REWRITE_TAC[]]))) THEN
    (* the maps: the timestamp of the block into the one of the
       timestamps, and the addresses as they were *)
    REWRITE_TAC[bc_stack_ref_inv_def] THEN
    W(fun (asl,w as gl) ->
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let f = rand (lhand (concl su)) in
      let tfsu = the_asm (fun c -> hd_is "SUBSET" c &&
                   hd_is "all_ts" (rand c)) gl in
      let tf = rand (lhand (concl tfsu)) in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let aa = el 0 (snd (strip_comb (lhand (concl st)))) in
      let bl = find_term (hd_is "dataSem_Block") w in
      let ts = el 0 (snd (strip_comb bl)) in
      EXISTS_TAC f THEN
      EXISTS_TAC (list_mk_icomb "|+" [tf; mk_pair (ts, aa)])) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the map of the timestamps: the one of the block is fresh and
       its address the one the store wrote at *)
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) ||
         not (can (find_term (hd_is "|+")) w) then ALL_TAC else
      (let iso = the_asm (fun c ->
                   let vs,bd = strip_forall c in
                   length vs = 1 && is_eq bd &&
                   hd_is "isSomeDataElement" (lhand bd)) gl in
       let inj = the_asm (fun c -> hd_is "INJ" c &&
                   hd_is "fmap_apply" (el 0 (snd (strip_comb c))) &&
                   rand (el 0 (snd (strip_comb c))) =
                     lhand (rand (el 0 (snd (strip_comb w))))) gl in
       let nd = the_asm (fun c -> is_neg c &&
                  hd_is "isSomeDataElement" (rand c)) gl in
       MATCH_MP_TAC INJ_FUPDATE_fresh THEN
       EXISTS_TAC (rand (concl inj)) THEN
       REPEAT CONJ_TAC THEN
       TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
       TRY (SOLVED (MP_TAC nd THEN REWRITE_TAC[IN_ELIM_THM])) THEN
       REWRITE_TAC[IN_ELIM_THM] THEN
       MATCH_ACCEPT_TAC iso)) THEN
    (* and the map of the addresses goes into the bigger set of
       addresses *)
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) then ALL_TAC else
      (let iso = the_asm (fun c ->
                   let vs,bd = strip_forall c in
                   length vs = 1 && is_eq bd &&
                   hd_is "isSomeDataElement" (lhand bd)) gl in
       let inj = the_asm (fun c -> hd_is "INJ" c &&
                   el 0 (snd (strip_comb c)) =
                     el 0 (snd (strip_comb w))) gl in
       MATCH_MP_TAC INJ_bigger THEN
       EXISTS_TAC (rand (concl inj)) THEN
       CONJ_TAC THENL
        [ACCEPT_TAC inj;
         REWRITE_TAC[IN_ELIM_THM] THEN
         REWRITE_TAC[iso] THEN MESON_TAC[]])) THEN
    (* the timestamps of the stack with the block on it are the
       ones it had and the block's own (all_ts_cons) *)
    TRY (SOLVED
          (REWRITE_TAC[FDOM_FUPDATE; all_ts_cons] THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "all_ts" (rand c)) gl in
             MP_TAC su) THEN
           SET_TAC[])) THEN
    (* and they are below the timestamp that the new stack counts
       from *)
    TRY (SOLVED
          (REWRITE_TAC[FDOM_FUPDATE] THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "GSPEC" (rand c)) gl in
             MP_TAC su) THEN
           REWRITE_TAC[SUBSET; IN_INSERT; IN_ELIM_THM] THEN
           MESON_TAC[ARITH_RULE `!m n. m < n ==> m < n + 1`;
                     ARITH_RULE `!n. n < n + 1`])) THEN
    (* the blocks of the stack stay unique, because the block is a
       new one (blocks_unique_cons_thm) *)
    TRY (SOLVED
          (REWRITE_TAC[all_vs_Block] THEN
           W(fun gl ->
             let bu = the_asm (hd_is "blocks_unique") gl in
             MATCH_ACCEPT_TAC (MATCH_MP blocks_unique_cons_thm
               bu)))) THEN
    (* the transfer that the allocation leaves: what the invariant
       said of a value it says of it with the block allocated
       (v_inv_cons_step) *)
    W(fun (asl,w as gl) ->
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "FDOM" (rand (rand c))) gl in
      let hsr = the_asm (hd_is "heap_store_rel") gl in
      let old = the_asm (fun c -> hd_is "ALL2" c &&
                  is_var (el 1 (snd (strip_comb c)))) gl in
      let pred = el 0 (snd (strip_comb (concl old))) in
      let v,b1 = dest_abs pred in
      let x,vtm = dest_abs b1 in
      let tf2 = find_term (hd_is "|+") w in
      ASSUME_TAC (GENL [v; x] (DISCH vtm
        (MATCH_MP v_inv_cons_step
          (CONJ (ASSUME vtm)
            (CONJ nd (CONJ hsr (REFL tf2)))))))) THEN
    (* the values of the stack with the pointer of the block on
       it *)
    W(fun (asl,w) ->
      if not (hd_is "ALL2" w) then ALL_TAC else
      (REWRITE_TAC[ALL2] THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       CONJ_TAC THENL
        [(* the block: its pointer is the address that the store
             wrote at, and its values the roots of the front *)
         W(fun (asl,w as gl) ->
           let st = the_asm (fun c -> is_eq c &&
                      hd_is "heap_store_unused_alt" (lhand c)) gl in
           let aa = el 0 (snd (strip_comb (lhand (concl st)))) in
           let ys1 = el 1 (snd (strip_comb
                       (el 2 (snd (strip_comb
                         (lhand (concl st))))))) in
           REWRITE_TAC[v_inv_def] THEN ASM_REWRITE_TAC[] THEN
           EXISTS_TAC aa THEN EXISTS_TAC ys1 THEN
           REPEAT CONJ_TAC THEN
           TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
           TRY (SOLVED (REWRITE_TAC[FLOOKUP_UPDATE])) THEN
           TRY (SOLVED (W(fun gl ->
             let old = the_asm (fun c -> hd_is "ALL2" c &&
                         el 2 (snd (strip_comb c)) = ys1) gl in
             MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc_stack
               (CONJ (a_vtr gl) old))))) THEN
           W(fun gl ->
             let le = the_asm (fun c -> is_eq c &&
                        hd_is "LENGTH" (lhand c) &&
                        hd_is "LENGTH" (rand c)) gl in
             REWRITE_TAC[le]));
         (* and the rest of the stack, with the transfer *)
         W(fun (asl,w as gl) ->
           let stk = el 1 (snd (strip_comb w)) in
           let old = the_asm (fun c -> hd_is "ALL2" c &&
                       el 1 (snd (strip_comb c)) = stk) gl in
           MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc_stack
             (CONJ (a_vtr gl) old)))])) THEN
    (* and the invariant of every reference that the new stack
       reaches: the old stack reached it, and the allocation keeps
       what the invariant says of it (bc_ref_inv_step) *)
    REPEAT STRIP_TAC THEN
    W(fun (asl,w as gl) ->
      let rr = the_asm (fun c -> hd_is "reachable_refs" c) gl in
      ASSUME_TAC (MATCH_MP reachable_refs_cons rr)) THEN
    W(fun (asl,w as gl) ->
      let n = el 1 (snd (strip_comb w)) in
      let bri = the_asm (fun c ->
                  let vs,bd = strip_forall c in
                  length vs = 1 && is_imp bd &&
                  hd_is "bc_ref_inv" (rand bd)) gl in
      let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                 not (can (find_term (hd_is "dataSem_Block"))
                        (el 0 (snd (strip_comb c))))) gl in
      let inn = the_asm (fun c -> hd_is "IN" c &&
                  hd_is "FDOM" (rand c) &&
                  el 0 (snd (strip_comb c)) = n) gl in
      let inv = MP (SPEC n bri) (CONJ rr inn) in
      let hsr = the_asm (hd_is "heap_store_rel") gl in
      let stp = REWRITE_RULE[IMP_CONJ] bc_ref_inv_step in
      let th = MATCH_MP (MATCH_MP (MATCH_MP (MATCH_MP stp
                 (a_vtr gl)) inn) hsr) inv in
      MATCH_MP_TAC (REWRITE_RULE[IMP_IMP] th)) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (REWRITE_TAC[])) THEN
    TRY (SOLVED (W(fun gl ->
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "FDOM" (rand (rand c))) gl in
      let nsd = the_asm (fun c -> is_neg c &&
                  hd_is "isSomeDataElement" (rand c)) gl in
      MATCH_ACCEPT_TAC (MATCH_MP IMAGE_FUPDATE_fresh
        (CONJ nd nsd))))) THEN
    MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let cons_thm_EMPTY = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,(heap:(('a
  word_loc,data_to_word_memoryProof_tag#('a word_loc) list)heap_element)
  list),be,a,sp,sp1,gens) limit ts /\
      tag < dimword (:'a) DIV 16 ==>
      abs_ml_inv conf ((Block 0 tag []) :: stack) refs
        (gc_shared_Data (wordLang_Word (BlockNil tag)) ::
          roots,heap,be,a,sp,sp1,gens) limit ts`),
  (* the empty Block is a Data root, so the heap does not change at
     all: what the invariant asks of the new stack is what it asked
     of the old one, because blocks_unique says nothing of a Block
     whose payload is empty, the timestamps only grow, and the
     Block holds no reference *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   (* the witness that an assumption names *)
   let gv n =
     W(fun (asl,_) ->
       let tms = itlist (fun (_,th) acc ->
                   union (frees(concl th)) acc) asl [] in
       EXISTS_TAC (find (fun t -> fst(dest_var t) = n) tms)) in
   (* an empty Block holds no reference, so what the stack with it
      in front reaches is what the stack reaches *)
   let rr_nil = prove
    (`!stack refs n t tag.
        reachable_refs (Block t tag [] :: stack) refs n
        ==> reachable_refs stack refs n`,
     REWRITE_TAC[reachable_refs_def; MEM] THEN REPEAT GEN_TAC THEN
     DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THENL
      [FIRST_X_ASSUM SUBST_ALL_TAC THEN
       FIRST_X_ASSUM(fun m ->
         CONTR_TAC(REWRITE_RULE[get_refs_def; MAP; FLAT; MEM] m));
       MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
       ASM_REWRITE_TAC[]]) in
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   STRIP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
    [(* the new root is a Data, so the pointers are the old ones *)
     USE_CHANGED [roots_ok_def] THEN
     REWRITE_TAC[roots_ok_def; MEM;
                 distinctness "heap_address"];
     ALL_TAC] THEN
   gv "f" THEN gv "tf" THEN ASM_REWRITE_TAC[] THEN
   REPEAT CONJ_TAC THENL
    [(* the timestamps of the stack grow by the Block's own *)
     FIRST_ASSUM(fun sub ->
       let t = rand(concl sub) in
       if hd_is "all_ts" t
       then MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC t THEN
            CONJ_TAC THENL [ACCEPT_TAC sub; ALL_TAC]
       else fail()) THEN
     REWRITE_TAC[all_ts_cons; APPEND; SUBSET; IN_INSERT] THEN
     GEN_TAC THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
     (* blocks_unique says nothing of a Block whose payload is
        empty *)
     REWRITE_TAC[all_vs_Block; APPEND] THEN
     FIRST_ASSUM(fun bu ->
       if hd_is "blocks_unique" (concl bu) then MP_TAC bu
       else fail()) THEN
     REWRITE_TAC[blocks_unique_def; IN_INSERT;
                 injectivity "dataSem_v"] THEN
     DISCH_TAC THEN REPEAT GEN_TAC THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN TRY CONTRA_TAC THEN
     FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
     (* and its root is the BlockNil word of its tag *)
     REWRITE_TAC[ALL2; v_inv_def] THEN ASM_REWRITE_TAC[];
     (* a reference that the new stack reaches the old one reaches,
        because the Block holds none *)
     GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
     CONJ_TAC THENL
      [FIRST_ASSUM(fun rr ->
         if not (hd_is "reachable_refs" (concl rr)) then fail() else
         MATCH_ACCEPT_TAC(MATCH_MP rr_nil rr));
       FIRST_ASSUM ACCEPT_TAC]]));;

(* word64 *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_Word64 = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (ws ++ stack)) ==>
       blocks_unique ts (all_vs refs (Word64 w64 :: stack))`),
  (* a Block of all_vs refs (Word64 w :: stack) is one of
     all_vs refs (ws ++ stack): the Word64 is no Block, and the rest
     of v_all_vs (Word64 w :: stack) is v_all_vs stack *)
  (let vw64 = prove
    (`!(w:word64) ys. v_all_vs (CONS (Word64 w) ys) =
        CONS (Word64 w) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let inc = prove
    (`!refs ws stack' (w:word64) t a xs.
        Block t a xs IN all_vs refs (CONS (Word64 w) stack') ==>
        Block t a xs IN all_vs refs (APPEND ws stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; vw64;
                 v_all_vs_append; MEM; MEM_APPEND;
                 distinctness "dataSem_v"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: what the two lemmas about the allocation of one
   element into the unused space share.  The steps are the ones
   that the proofs of cons_thm_alt and of new_byte_alt_thm take,
   with one difference: the values that the allocation replaces are
   taken off the stack, so the timestamps that the stack uses
   shrink, and the map of them is restricted to the ones that the
   new stack uses.  The lemmas below carry the invariant of a
   value, of a list of values and of a reference over that
   restriction (v_inv_tf_restrict above is the one for a value,
   with the condition that the timestamps of it are kept) *)

let v_inv_restrict = prove
 (`!v y stack2.
    v IN all_vs refs stack2 /\
    v_inv conf v refs (y:(('a word_loc)heap_address),f,tf,heap)
    ==> v_inv conf v refs
          (y,f,DRESTRICT tf (all_ts refs stack2),heap)`,
 (REPEAT GEN_TAC THEN STRIP_TAC THEN
  W(fun (asl,gl) ->
    let vi = grab_asm (fun th -> hd_is "v_inv" (concl th)) asl in
    let args = snd (strip_comb (concl vi)) in
    let ps = tparts (el 3 args) in
    let inn = grab_asm (fun th ->
      hd_is "IN" (concl th) &&
      hd_is "all_vs" (rand (concl th))) asl in
    let stack2 = rand (rand (concl inn)) in
    let pset = rand (el 2 (tparts (el 3 (snd (strip_comb gl))))) in
    MP_TAC (ISPECL [el 0 args; el 1 args; el 2 args; stack2;
      el 0 ps; el 1 ps; el 2 ps; el 3 ps; pset]
      v_inv_tf_restrict)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
    MATCH_MP_TAC MEM_in_all_ts THEN ASM_MESON_TAC[];
    DISCH_THEN ACCEPT_TAC]));;

let EVERY2_v_inv_restrict = prove
 (`!vs (rs:(('a word_loc)heap_address)list) stack2.
    (!v. MEM v vs ==> v IN all_vs refs stack2) /\
    EVERY2 (\v x. v_inv conf v refs (x,f,tf,heap)) vs rs
    ==> EVERY2 (\v x. v_inv conf v refs
          (x,f,DRESTRICT tf (all_ts refs stack2),heap)) vs rs`,
 (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
  STRUCT_CASES_TAC (ISPEC `rs:(('a word_loc)heap_address)list`
    list_CASES) THEN
  REWRITE_TAC[ALL2; MEM] THEN STRIP_TAC THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC v_inv_restrict THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN REWRITE_TAC[];
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]));;

let EVERY2_v_inv_restrict2 = prove
 (`!(zs:(('a word_loc)heap_address)list) vs stack2.
    (!v. MEM v vs ==> v IN all_vs refs stack2) /\
    EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap)) zs vs
    ==> EVERY2 (\z y. v_inv conf y refs
          (z,f,DRESTRICT tf (all_ts refs stack2),heap)) zs vs`,
 (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
  STRUCT_CASES_TAC (ISPEC `vs:(dataSem_v)list` list_CASES) THEN
  REWRITE_TAC[ALL2; MEM] THEN STRIP_TAC THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC v_inv_restrict THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN REWRITE_TAC[];
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]));;

(* and what the restriction does to the map itself: it is one to
   one into the addresses that hold data as it was, and the
   addresses it points at are among the ones that the whole map
   pointed at *)

let INJ_DRESTRICT = prove
 (`!(tf:(num,num)fmap) P s s2.
    INJ (FAPPLY tf) (FDOM tf) s /\ (!x. x IN s ==> x IN s2)
    ==> INJ (FAPPLY (DRESTRICT tf P)) (FDOM (DRESTRICT tf P)) s2`,
 (REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; FDOM_DRESTRICT; IN_INTER] THEN
  STRIP_TAC THEN SPLIT_ASM_TAC THEN CONJ_TAC THENL
   [REPEAT STRIP_TAC THEN ASM_SIMP_TAC[FAPPLY_DRESTRICT] THEN
    ASM_MESON_TAC[];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_X_ASSUM (fun eq ->
      if not (is_eq (concl eq)) ||
         not (hd_is "fmap_apply" (lhs (concl eq))) then fail() else
      MP_TAC eq) THEN
    ASM_SIMP_TAC[FAPPLY_DRESTRICT] THEN ASM_MESON_TAC[]]));;

let IMAGE_DRESTRICT_SUBSET = prove
 (`!(tf:(num,num)fmap) P y.
    y IN IMAGE (FAPPLY (DRESTRICT tf P)) (FDOM (DRESTRICT tf P))
    ==> y IN IMAGE (FAPPLY tf) (FDOM tf)`,
 (REWRITE_TAC[IN_IMAGE; FDOM_DRESTRICT; IN_INTER] THEN
  REPEAT STRIP_TAC THEN EXISTS_TAC `x:num` THEN
  ASM_SIMP_TAC[FAPPLY_DRESTRICT]));;

(* the values that a reference holds are among the values that the
   refs and any stack hold, whichever stack that is *)

let ref_vals_all_vs = prove
 (`(!n l v stack2.
     lookup n refs = SOME (bvlSem_ValueArray l) /\ MEM v l
     ==> v IN all_vs refs stack2) /\
  (!n ev x stack2.
     lookup n refs = SOME (Thunk ev x)
     ==> x IN all_vs refs stack2) /\
  (!n tg fin l c r v stack2.
     lookup n refs = SOME (bvlSem_MutBlock tg fin l c r) /\
     MEM v (l ++ [c] ++ r) ==> v IN all_vs refs stack2)`,
 (REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  REPEAT CONJ_TAC THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[MEM_v_all_vs; MEM]));;

(* a word of sixty-four bits is no reference and no forward
   pointer, and it holds no reference either, so a reference that
   the stack with one on top reaches is one that the stack
   reached *)

let isRef_Word64Rep = prove
 (`~(data_to_word_memoryProof_isRef (Word64Rep (:'a) w))`,
 (REWRITE_TAC[Word64Rep_def] THEN COND_CASES_TAC THEN
  REWRITE_TAC[isRef_def] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[isMutTag_def; distinctness
    "data_to_word_memoryProof_tag"]));;

let isFwd_Word64Rep = prove
 (`~(isForwardPointer (Word64Rep (:'a) w))`,
 (REWRITE_TAC[Word64Rep_def] THEN COND_CASES_TAC THEN
  REWRITE_TAC[isForwardPointer_def] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[]));;

let reachable_refs_w64 = prove
 (`!stack2 refs n (w:word64) ws.
    reachable_refs (Word64 w :: stack2) refs n
    ==> reachable_refs (ws ++ stack2) refs n`,
 (let gr = prove
   (`get_refs (Word64 w) = []`,
    GEN_REWRITE_TAC LAND_CONV [get_refs_def] THEN
    MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
  REPEAT GEN_TAC THEN
  REWRITE_TAC[reachable_refs_def; MEM; MEM_APPEND] THEN
  STRIP_TAC THEN ASM_MESON_TAC[gr; MEM]));;

(* the steps of the invariant of a reference that the allocation
   did not touch: its cell is where it was and its values keep
   their invariant *)

let the_hsr asl =
  grab_asm (fun th -> hd_is "heap_store_rel" (concl th)) asl;;
let the_hl asl =
  grab_asm (fun th ->
    is_eq (concl th) && hd_is "heap_lookup" (lhs (concl th))) asl;;
let the_lkref asl =
  grab_asm (fun th ->
    is_eq (concl th) && hd_is "sptree_lookup" (lhs (concl th)) &&
    hd_is "SOME" (rhs (concl th))) asl;;
(* the transport of the growth of the heap, as the lemmas about a
   value and about a list of them ask for it *)
let grow_tr asl =
  let sp = SPEC_ALL heap_store_rel_v_inv in
  let tr0 = REWRITE_RULE
    [TAUT `(a /\ b ==> c) <=> (a ==> b ==> c)`] sp in
  let tr1 = MATCH_MP tr0 (the_hsr asl) in
  let vs = frees (concl tr1) in
  let fv n = find (fun v -> fst (dest_var v) = n) vs in
  GENL [fv "w"; fv "x"] tr1;;
(* the cell of the reference is where it was *)
let keep_cell =
  W(fun (asl,_) ->
    let hl = the_hl asl in
    ASSUME_TAC (MATCH_MP heap_store_rel_keep
      (CONJ (the_hsr asl)
        (CONJ (is_data_el (rand (rhs (concl hl)))) hl))));;
let grow_vals =
  W(fun (asl,_) ->
    let ev = grab_asm (fun th -> hd_is "ALL2" (concl th)) asl in
    ASSUME_TAC (MATCH_MP EVERY2_v_inv_alloc
      (CONJ (grow_tr asl) ev)));;
let grow_val =
  W(fun (asl,_) ->
    let vi = grab_asm (fun th -> hd_is "v_inv" (concl th)) asl in
    ASSUME_TAC (MATCH_MP heap_store_rel_v_inv
      (CONJ (the_hsr asl) vi)));;
let the_zs asl =
  last (snd (strip_comb (rand (rhs (concl (the_hl asl))))));;
let restrict_vals =
  MATCH_MP_TAC EVERY2_v_inv_restrict2 THEN
  CONJ_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN ASM_MESON_TAC[ref_vals_all_vs];
    FIRST_ASSUM ACCEPT_TAC];;

let bc_ref_inv_grow_restrict = prove
 (`!conf n refs f tf heap heap2 be2 stack2.
    heap_store_rel heap heap2 /\
    bc_ref_inv conf n refs
      (f,tf,heap:((('a word_loc),data_to_word_memoryProof_tag#('a
        word_loc)list)heap_element)list,be2)
    ==> bc_ref_inv conf n refs
          (f,DRESTRICT tf (all_ts refs stack2),heap2,be2)`,
 (REPEAT GEN_TAC THEN
  REWRITE_TAC[bc_ref_inv_def] THEN
  W(fun (asl,gl) ->
    NAMED_CASES_TAC (find_term (hd_is "FLOOKUP") gl) [[]; ["x"]]) THEN
  REDUCE_MATCH_HARD THEN
  W(fun (asl,gl) ->
    NAMED_CASES_TAC (find_term (hd_is "sptree_lookup") gl)
      [[]; ["rv"]]) THEN
  REDUCE_MATCH_HARD THEN
  CASES_ON_NAME "rv" THEN REDUCE_MATCH_HARD THEN
  STRIP_TAC THENL
   [(* the values of a reference *)
    keep_cell THEN grow_vals THEN
    W(fun (asl,_) -> EXISTS_TAC (the_zs asl)) THEN
    ASM_REWRITE_TAC[] THEN restrict_vals;
    (* the byte array: only its cell *)
    RULE_ASSUM_TRY (CONV_RULE (TOP_DEPTH_CONV let_CONV)) THEN
    keep_cell THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    FIRST_ASSUM ACCEPT_TAC;
    (* the value of a thunk *)
    keep_cell THEN grow_val THEN
    W(fun (asl,_) ->
      EXISTS_TAC (rand (rand (rhs (concl (the_hl asl)))))) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC v_inv_restrict THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ref_vals_all_vs];
    (* and the values of a mutable block *)
    keep_cell THEN grow_vals THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    TRY (SOLVED (REPEAT STRIP_TAC THEN
      FIRST_X_ASSUM (fun th ->
        if not (is_imp (concl th)) then fail() else
        MP_TAC (MP th (ASSUME (lhand (concl th))))) THEN
      ASM_MESON_TAC[IMAGE_DRESTRICT_SUBSET])) THEN
    W(fun (asl,_) -> EXISTS_TAC (the_zs asl)) THEN
    ASM_REWRITE_TAC[] THEN restrict_vals]));;

(* the element fits in the unused space, so the store writes it
   there, and what the store gives of a data element is given *)
let store_el =
  W(fun (asl,gl) ->
    let us = the_asm (hd_is "unused_space_inv") (asl,gl) in
    let spsp = el 1 (snd (strip_comb (concl us))) in
    let le = grab_asm (fun th ->
      is_eq (concl th) && hd_is "el_length" (lhs (concl th))) asl in
    let el1 = el 0 (snd (strip_comb (lhs (concl le)))) in
    SUBGOAL_THEN (list_mk_icomb "<="
      [list_mk_icomb "el_length" [el1]; spsp])
      (fun bd -> STRIP_ASSUME_TAC (MATCH_MP
         IMP_heap_store_unused_alt (CONJ us bd))) THENL
     [REWRITE_TAC[le] THEN ASM_ARITH_TAC;
      ALL_TAC]) THEN
  W(fun gl ->
    let st = the_asm (fun c -> is_eq c &&
               hd_is "heap_store_unused_alt" (lhand c)) gl in
    let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
    let isd = is_data_el el1 in
    MAP_EVERY (fun th -> ASSUME_TAC (MP th isd))
      (mapfilter (fun (_,th) ->
         let c = concl th in
         if is_imp c && hd_is "isDataElement" (lhand c) then th
         else fail()) (fst gl))) THEN
  W(fun (asl,gl) ->
    let st = the_asm (fun c -> is_eq c &&
               hd_is "heap_store_unused_alt" (lhand c)) (asl,gl) in
    EXISTS_TAC (lhand (rand (concl st)))) THEN
  REPEAT CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  REWRITE_TAC[abs_ml_inv_def] THEN REPEAT CONJ_TAC;;

(* what the store says of the addresses that hold data, and what
   the roots of the stack were *)
let prep_el =
  W(fun gl ->
    let seq = the_asm (fun c -> is_eq c &&
                hd_is "INSERT" (rand c)) gl in
    let ro = the_asm (hd_is "roots_ok") gl in
    ASSUME_TAC (REWRITE_RULE[EXTENSION; IN_INSERT; IN_ELIM_THM]
                  seq) THEN
    ASSUME_TAC (REWRITE_RULE[roots_ok_def] ro));;
let the_iso gl =
  the_asm (fun c ->
    let vs,bd = strip_forall c in
    length vs = 1 && is_eq bd &&
    hd_is "isSomeDataElement" (lhand bd)) gl;;
(* the roots: the one of the word is the address it was written
   at, and the others are the ones they were *)
let roots_el =
  REWRITE_TAC[roots_ok_def; MEM] THEN
  REPEAT STRIP_TAC THEN
  W(fun gl -> REWRITE_TAC[the_iso gl]) THEN
  TRY (SOLVED
        (DISJ1_TAC THEN
         FIRST_X_ASSUM (fun e ->
           if not (is_eq (concl e)) ||
              not (hd_is "gc_shared_Pointer" (rand (concl e)))
           then fail() else MP_TAC e) THEN
         REWRITE_TAC[injectivity "heap_address"] THEN
         MESON_TAC[])) THEN
  DISJ2_TAC THEN ASM_MESON_TAC[MEM_APPEND];;

(* the unused space: what the store lemma says, with the length of
   the element taken off *)
let unused_el =
  W(fun (asl,w as gl) ->
    let us = the_asm (fun c -> hd_is "unused_space_inv" c &&
               can (find_term (hd_is "-")) c) gl in
    let le = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    MP_TAC (REWRITE_RULE[le] us) THEN
    W(fun (asl,w) ->
      let usub = el 1 (snd (strip_comb (lhand w))) in
      let gsub = el 1 (snd (strip_comb (rand w))) in
      let uadd = el 0 (snd (strip_comb (lhand w))) in
      let gadd = el 0 (snd (strip_comb (rand w))) in
      SUBGOAL_THEN (mk_eq (uadd, gadd)) ASSUME_TAC THENL
       [ASM_ARITH_TAC;
        SUBGOAL_THEN (mk_eq (usub, gsub)) ASSUME_TAC THENL
         [ASM_ARITH_TAC;
          ASM_REWRITE_TAC[] THEN
          TRY (DISCH_THEN ACCEPT_TAC)]]));;

(* the addresses that held data still do *)
let data_incl =
  W(fun (asl,w as gl) ->
    let inj = the_asm (fun c -> hd_is "INJ" c &&
                hd_is "fmap_apply" (el 0 (snd (strip_comb c)))) gl in
    let st = the_asm (fun c -> is_eq c &&
               hd_is "heap_store_unused_alt" (lhand c)) gl in
    let hp2 = lhand (rand (concl st)) in
    let hp = el 3 (snd (strip_comb (lhand (concl st)))) in
    let s = rand (concl inj) in
    let xv = genvar `:num` in
    SUBGOAL_THEN (mk_forall (xv,
      mk_imp (list_mk_icomb "IN" [xv; s],
              list_mk_icomb "IN" [xv; subst [hp2,hp] s])))
      ASSUME_TAC THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN
      W(fun g2 -> REWRITE_TAC[the_iso g2]) THEN MESON_TAC[];
      ALL_TAC]);;
let the_incl asl =
  grab_asm (fun th ->
    is_forall (concl th) &&
    (let bd = snd (strip_forall (concl th)) in
     is_imp bd && hd_is "IN" (lhand bd) && hd_is "IN" (rand bd)))
    asl;;

(* ---- the generic steps of an allocation of one element ---- *)
let the_eleq asl =
  grab_asm (fun th ->
    is_eq (concl th) && hd_is "DataElement" (rhs (concl th))) asl;;
let el_lens pretac =
  W(fun (asl,_) ->
    let eleq = the_eleq asl in
    let elt = list_mk_icomb "el_length" [lhs (concl eleq)] in
    let elen = REWRITE_RULE[el_length_def]
      (AP_TERM (rator elt) eleq) in
    let args = snd (strip_comb (rand (concl eleq))) in
    let xs = rand (el 2 args) and len = el 1 args in
    ASSUME_TAC elen THEN
    SUBGOAL_THEN (mk_eq (list_mk_icomb "LENGTH" [xs], len))
      ASSUME_TAC THENL [pretac; ALL_TAC]);;
let vhead_ptr =
  REWRITE_TAC[v_inv_def] THEN ASM_REWRITE_TAC[] THEN
  W(fun (asl,w) ->
    EXISTS_TAC (lhand (lhs (el 0
      (conjuncts (snd (strip_exists w))))))) THEN
  ASM_REWRITE_TAC[];;
let alloc_el pretac isfwd isref bunique reach vhead =
  (* the invariant of the stack, and the element written *)
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  FIRST_X_ASSUM (fun inv ->
    if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
    STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
      bc_stack_ref_inv_def] inv)) THEN
  el_lens pretac THEN
  store_el THEN prep_el THENL
   [roots_el;
    (* the heap is good, with this element's forward pointer *)
    REWRITE_TAC[heap_ok_def] THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED
          (W(fun gl ->
             let ho = REWRITE_RULE[heap_ok_def]
                        (the_asm (hd_is "heap_ok") gl) in
             let hl = the_asm (fun c -> is_eq c &&
                        hd_is "heap_length" (lhand c)) gl in
             MP_TAC ho THEN REWRITE_TAC[hl] THEN
             STRIP_TAC THEN ASM_REWRITE_TAC[]))) THEN
    TRY (SOLVED
          (W(fun gl ->
             let ho = REWRITE_RULE[heap_ok_def]
                        (the_asm (hd_is "heap_ok") gl) in
             let impl = the_asm (fun c -> is_imp c &&
                          is_neg (lhand c) &&
                          hd_is "isForwardPointer"
                            (rand (lhand c))) gl in
             let nf = PART_MATCH I isfwd (lhand (concl impl)) in
             MP_TAC ho THEN REWRITE_TAC[MP impl nf] THEN
             STRIP_TAC THEN ASM_REWRITE_TAC[]))) THEN
    REPEAT GEN_TAC THEN
    W(fun gl ->
      let mem = the_asm (fun c ->
                  let vs,bd = strip_forall c in
                  length vs = 3 && is_eq bd &&
                  hd_is "MEM" (lhand bd)) gl in
      REWRITE_TAC[mem]) THEN
    STRIP_TAC THEN
    W(fun gl -> REWRITE_TAC[the_iso gl]) THEN
    DISJ2_TAC THEN
    TRY (SOLVED
          (W(fun (asl,_) -> MP_TAC (the_eleq asl)) THEN
           ASM_REWRITE_TAC[injectivity "heap_element"] THEN
           STRIP_TAC THEN ASM_MESON_TAC[MEM])) THEN
    W(fun gl ->
      let ho = REWRITE_RULE[heap_ok_def]
                 (the_asm (hd_is "heap_ok") gl) in
      MP_TAC ho) THEN
    ASM_MESON_TAC[];
    (* the kind of the collection, this element being no
       reference *)
    W(fun (asl,w as gl) ->
      let gk = the_asm (hd_is "gc_kind_inv") gl in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
      let sp = el 2 (snd (strip_comb (concl gk))) in
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "el_length" (lhand c)) gl in
      let us2 = the_asm (fun c -> hd_is "unused_space_inv" c &&
                  can (find_term (hd_is "-")) c) gl in
      SUBGOAL_THEN (list_mk_icomb "<="
                      [list_mk_icomb "el_length" [el1]; sp])
        (fun bd -> MP_TAC (REWRITE_RULE[le] (MATCH_MP
           gc_kind_store_unused_alt
           (CONJ (PART_MATCH I isref
                    (mk_neg (list_mk_icomb
                       "data_to_word_memoryProof_isRef" [el1])))
              (CONJ bd (CONJ gk (CONJ st us2)))))) THEN
         W(fun (asl,w) ->
           let ua = el 1 (snd (strip_comb (lhand w)))
           and ga = el 1 (snd (strip_comb (rand w)))
           and us = el 2 (snd (strip_comb (lhand w)))
           and gs = el 2 (snd (strip_comb (rand w))) in
           SUBGOAL_THEN (mk_eq (ua, ga)) ASSUME_TAC THENL
            [ARITH_TAC;
             SUBGOAL_THEN (mk_eq (us, gs)) ASSUME_TAC THENL
              [ARITH_TAC;
               ASM_REWRITE_TAC[] THEN
               TRY (DISCH_THEN ACCEPT_TAC)]])) THEN
      REWRITE_TAC[le] THEN ASM_ARITH_TAC);
    unused_el;
    (* and the maps, the stack and the references *)
    REWRITE_TAC[bc_stack_ref_inv_def] THEN
    data_incl THEN
    W(fun (asl,w as gl) ->
      let fsu = the_asm (fun c -> hd_is "SUBSET" c &&
                  hd_is "domain" (rand c)) gl in
      let f = rand (lhand (concl fsu)) in
      let tfsu = the_asm (fun c -> hd_is "SUBSET" c &&
                   hd_is "all_ts" (rand c)) gl in
      let tf = rand (lhand (concl tfsu)) in
      let ats = find_term (fun t ->
        hd_is "all_ts" t && hd_is "CONS" (rand t)) w in
      let ats2 = mk_comb (rator ats, rand (rand ats)) in
      EXISTS_TAC f THEN
      EXISTS_TAC (list_mk_icomb "DRESTRICT" [tf; ats2])) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) ||
         can (find_term (hd_is "DRESTRICT")) w then ALL_TAC else
      (let inj = the_asm (fun c -> hd_is "INJ" c &&
                   el 0 (snd (strip_comb c)) =
                     el 0 (snd (strip_comb w))) gl in
       MATCH_ACCEPT_TAC (MATCH_MP INJ_bigger
         (CONJ inj (the_incl asl))))) THEN
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) then ALL_TAC else
      (let inj = the_asm (fun c -> hd_is "INJ" c &&
                   hd_is "fmap_apply" (el 0 (snd (strip_comb c))) &&
                   rand (el 0 (snd (strip_comb c))) =
                     lhand (rand (el 0 (snd (strip_comb w))))) gl in
       MATCH_ACCEPT_TAC (MATCH_MP INJ_DRESTRICT
         (CONJ inj (the_incl asl))))) THEN
    W(fun (asl,w) ->
      if not (hd_is "SUBSET" w) ||
         not (can (find_term (fun t ->
           hd_is "all_ts" t && hd_is "CONS" (rand t))) w)
      then ALL_TAC else
      (let ats = find_term (fun t ->
         hd_is "all_ts" t && hd_is "CONS" (rand t)) w in
       let rf = rand (rator ats) in
       let stk = rand (rand ats) in
       let v = lhand (rand ats) in
       let inst = ISPECL [rf; stk; v] all_ts_cons_no_block in
       let cnd = prove (lhand (concl inst),
         REWRITE_TAC[distinctness "dataSem_v"]) in
       REWRITE_TAC[MP inst cnd; FDOM_DRESTRICT] THEN SET_TAC[])) THEN
    W(fun (asl,w as gl) ->
      if not (hd_is "SUBSET" w) then ALL_TAC else
      (MP_TAC (the_asm (fun c -> hd_is "SUBSET" c &&
         can (find_term (hd_is "<")) c) gl) THEN
       REWRITE_TAC[FDOM_DRESTRICT] THEN SET_TAC[])) THEN
    W(fun (asl,w as gl) ->
      if not (hd_is "blocks_unique" w) then ALL_TAC else
      MATCH_ACCEPT_TAC (MATCH_MP bunique
        (the_asm (hd_is "blocks_unique") gl))) THEN
    W(fun (asl,w) ->
      if not (hd_is "ALL2" w) then ALL_TAC else
      (REWRITE_TAC[ALL2] THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       CONJ_TAC THENL
        [vhead;
         W(fun (asl2,w2 as gl2) ->
           let ev = the_asm (hd_is "ALL2") gl2 in
           let lens = the_asm (fun c -> is_eq c &&
                        hd_is "LENGTH" (lhand c) &&
                        hd_is "LENGTH" (rand c)) gl2 in
           let spl = CONJUNCT2 (MATCH_MP LIST_REL_APPEND_IMP
                       (CONJ ev lens)) in
           MP_TAC (MATCH_MP EVERY2_v_inv_alloc_stack
                     (CONJ (grow_tr asl2) spl))) THEN
         DISCH_TAC THEN
         MATCH_MP_TAC EVERY2_v_inv_restrict THEN
         CONJ_TAC THENL
          [GEN_TAC THEN DISCH_TAC THEN
           MATCH_MP_TAC MEM_stack_all_vs THEN ASM_REWRITE_TAC[];
           FIRST_ASSUM ACCEPT_TAC]])) THEN
    REPEAT STRIP_TAC THEN
    W(fun (asl,w as gl) ->
      let old = the_asm (fun c -> is_forall c &&
                  can (find_term (hd_is "bc_ref_inv")) c) gl in
      let rr = the_asm (hd_is "reachable_refs") gl in
      let inn = the_asm (fun c -> hd_is "IN" c &&
                  hd_is "FDOM" (rand c)) gl in
      let n = el 0 (snd (strip_comb (concl inn))) in
      let spo = SPEC n old in
      let wsl = lhand (el 0 (snd (strip_comb
                  (lhand (lhand (concl spo)))))) in
      let bri = MP spo
        (CONJ (SPEC wsl (MATCH_MP reach rr)) inn) in
      MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_grow_restrict
        (CONJ (the_asm (hd_is "heap_store_rel") gl) bri)))];;

let w64_pre =
  W(fun (asl,_) ->
    MP_TAC (REWRITE_RULE[Word64Rep_def] (the_eleq asl))) THEN
  COND_CASES_TAC THEN
  REWRITE_TAC[injectivity "heap_element"; PAIR_EQ] THEN
  DISCH_THEN (fun th -> REWRITE_TAC[GSYM th]) THEN
  REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV;;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word64_alt_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (ws ++ stack) refs (rs ++
  roots,heap,be,a,sp,sp1,gens) limit ts /\
     LENGTH ws = LENGTH rs /\
     (Word64Rep (:'a) w64:('a
       word_loc,data_to_word_memoryProof_tag#('a word_loc)
       list)heap_element) = DataElement [] len (Word64Tag,xs) /\
      LENGTH xs < sp ==>
     (?heap2.
       heap_store_unused_alt a (sp + sp1) (Word64Rep (:'a) w64)
         heap = (heap2,T) /\
       abs_ml_inv conf (Word64 w64 :: stack) refs
         (gc_shared_Pointer a (wordLang_Word (n2w 0)) ::
           roots,heap2,
          be,a + len + 1,sp - len - 1,sp1,gens) limit ts)`),
(* the steps are above the statement (tools/overrides.py), and
   they are the ones that cons_thm_alt and new_byte_alt_thm take:
   the element is a word longer than the words it holds, so it fits
   in the unused space and IMP_heap_store_unused_alt writes it
   there; the heap, the roots and the space are then as good as
   they were, and of every reference that the stack reaches the
   invariant holds as it did.  The two maps are the ones they were,
   except that the map of the timestamps is restricted to the ones
   of the new stack -- the values that this allocation replaces are
   taken off, so a timestamp of one of them is no longer a
   timestamp of the stack *)
  ((alloc_el w64_pre isFwd_Word64Rep isRef_Word64Rep
    blocks_unique_Word64 reachable_refs_w64 vhead_ptr)));;

(* bignum *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_Number = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (ws ++ stack)) ==>
       blocks_unique ts (all_vs refs (Number i :: stack))`),
  (let vnum = prove
    (`!(i:int) ys. v_all_vs (CONS (Number i) ys) =
        CONS (Number i) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let inc = prove
    (`!refs ws stack' (i:int) t a xs.
        Block t a xs IN all_vs refs (CONS (Number i) stack') ==>
        Block t a xs IN all_vs refs (APPEND ws stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; vnum;
                 v_all_vs_append; MEM; MEM_APPEND;
                 distinctness "dataSem_v"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: a bignum is no reference and no forward pointer
   either, and it holds no reference; the steps of the allocation
   are above word64_alt_thm (tools/overrides.py) *)

let isRef_Bignum = prove
 (`~(data_to_word_memoryProof_isRef (Bignum i:('a
    word_loc,data_to_word_memoryProof_tag#('a word_loc)
    list)heap_element))`,
 (REWRITE_TAC[bignum_def] THEN PAIRARG_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[isRef_def] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[isMutTag_def;
    distinctness "data_to_word_memoryProof_tag"]));;

let isFwd_Bignum = prove
 (`~(isForwardPointer (Bignum i:('a
    word_loc,data_to_word_memoryProof_tag#('a word_loc)
    list)heap_element))`,
 (REWRITE_TAC[bignum_def] THEN PAIRARG_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[isForwardPointer_def] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[]));;

let reachable_refs_num = prove
 (`!stack2 refs n (i:int) ws.
    reachable_refs (Number i :: stack2) refs n
    ==> reachable_refs (ws ++ stack2) refs n`,
 (let gr = prove
   (`get_refs (Number i) = []`,
    GEN_REWRITE_TAC LAND_CONV [get_refs_def] THEN
    MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
  REPEAT GEN_TAC THEN
  REWRITE_TAC[reachable_refs_def; MEM; MEM_APPEND] THEN
  STRIP_TAC THEN ASM_MESON_TAC[gr; MEM]));;

let bignum_pre =
  W(fun (asl,gl) ->
    MP_TAC (REWRITE_RULE[bignum_def] (the_eleq asl))) THEN
  PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[injectivity "heap_element"; PAIR_EQ] THEN
  DISCH_THEN (fun th -> REWRITE_TAC[GSYM th]) THEN
  REWRITE_TAC[LENGTH_MAP];;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bignum_alt_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (ws ++ stack) refs (rs ++
  roots,heap,be,a,sp,sp1,gens) limit ts /\
     LENGTH ws = LENGTH rs /\ ~(small_int (:'a) i) /\
     (Bignum i:('a word_loc,data_to_word_memoryProof_tag#('a
       word_loc) list)heap_element) = DataElement [] len (tag,xs) /\
     LENGTH xs < sp ==>
     (?heap2.
       heap_store_unused_alt a (sp + sp1) (Bignum i) heap =
         (heap2,T) /\
       abs_ml_inv conf (Number i :: stack) refs
         (gc_shared_Pointer a (wordLang_Word ((n2w 0):'a word))
           :: roots,heap2,be,a + len + 1,sp - len - 1,sp1,gens) limit
           ts)`),
(* the same steps as word64_alt_thm, of a bignum instead of a word
   of sixty-four bits: the number is not small, so the value of the
   statement is the pointer to the cell that the allocation
   wrote *)
  ((alloc_el bignum_pre isFwd_Bignum isRef_Bignum
    blocks_unique_Number reachable_refs_num vhead_ptr)));;

(* update ref *)

(* [local] *)
let ref_edge_ValueArray = prove
 (`ref_edge (insert ptr (ValueArray xs) refs) x y =
     (if x = ptr then MEM y (get_refs (Block 0 ARB xs)) else
       ref_edge refs x y)`,
  (REWRITE_TAC[ref_edge_def; lookup_insert] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[]));;

(* [local] *)
let ref_edge_Thunk = prove
 (`ref_edge (insert ptr (Thunk ev v) refs) x y =
     (if x = ptr then MEM y (get_refs (Block 0 ARB [v])) else
       ref_edge refs x y)`,
  (REWRITE_TAC[ref_edge_def; lookup_insert] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_UPDATE = prove
 (cake_as_vars (fun () ->
    `reachable_refs (xs ++ (RefPtr b ptr :: stack)) (insert ptr
  (ValueArray xs) refs) n ==>
       reachable_refs (xs ++ (RefPtr b ptr :: stack)) refs n`),
  (* induction along the reflexive transitive closure: an edge of
     the new references is one of the old ones, or it leaves ptr
     and lands in the array, whose values are roots of their own
     (they are the xs at the front of the stack) *)
  (let rtcpath = prove
    (`!r1 n.
        RTC (ref_edge (insert ptr (ValueArray xs) refs)) r1 n ==>
        RTC (ref_edge refs) r1 n \/
        (?s. MEM s (get_refs (Block 0 ARB xs)) /\
             RTC (ref_edge refs) s n)`,
     MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
      [GEN_TAC THEN DISJ1_TAC THEN
       MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
       REPEAT GEN_TAC THEN REWRITE_TAC[ref_edge_ValueArray] THEN
       COND_CASES_TAC THEN STRIP_TAC THEN
       ASM_MESON_TAC[RTC_RULES]]) in
   let mem_block_refs = prove
    (`!(ys:(dataSem_v)list) ss tt aa.
        MEM ss (get_refs (Block tt aa ys))
        ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   REWRITE_TAC[reachable_refs_def] THEN
   DISCH_THEN(X_CHOOSE_THEN `x:dataSem_v`
     (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC)) THEN
   FIRST_ASSUM(fun rtc -> MP_TAC(MATCH_MP rtcpath rtc)) THEN
   DISCH_THEN(DISJ_CASES_THEN2
     (fun old ->
        MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
        ASM_REWRITE_TAC[old])
     (X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)) THEN
   FIRST_ASSUM(fun m -> MP_TAC(MATCH_MP mem_block_refs m)) THEN
   DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v` STRIP_ASSUME_TAC) THEN
   MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `s:num`] THEN
   ASM_REWRITE_TAC[MEM_APPEND]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_Thunk_UPDATE = prove
 (cake_as_vars (fun () ->
    `reachable_refs (v :: RefPtr b ptr :: stack) (insert ptr (Thunk ev
  v) refs) n ==>
       reachable_refs (v :: RefPtr b ptr :: stack) refs n`),
  (* the same, with the thunk's value for the array: the payload of
     the edge that leaves ptr is the one value v, which is the
     root at the front of the stack *)
  (let rtcpath = prove
    (`!r1 n.
        RTC (ref_edge (insert ptr (Thunk ev v) refs)) r1 n ==>
        RTC (ref_edge refs) r1 n \/
        (?s. MEM s (get_refs v) /\ RTC (ref_edge refs) s n)`,
     MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
      [GEN_TAC THEN DISJ1_TAC THEN
       MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
       REPEAT GEN_TAC THEN REWRITE_TAC[ref_edge_Thunk] THEN
       REWRITE_TAC[get_refs_def; MAP; FLAT; APPEND_NIL] THEN
       COND_CASES_TAC THEN STRIP_TAC THEN
       ASM_MESON_TAC[RTC_RULES]]) in
   REWRITE_TAC[reachable_refs_def] THEN
   DISCH_THEN(X_CHOOSE_THEN `x:dataSem_v`
     (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC)) THEN
   FIRST_ASSUM(fun rtc -> MP_TAC(MATCH_MP rtcpath rtc)) THEN
   DISCH_THEN(DISJ_CASES_THEN2
     (fun old ->
        MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
        ASM_REWRITE_TAC[old])
     (X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)) THEN
   MAP_EVERY EXISTS_TAC [`v:dataSem_v`; `s:num`] THEN
   ASM_REWRITE_TAC[MEM]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_UPDATE1 = prove
 (cake_as_vars (fun () ->
    `reachable_refs (xs ++ (RefPtr b ptr :: stack)) (insert ptr
  (ValueArray xs1) refs) n ==>
       (!v. MEM v xs1 ==> ~(MEM v xs) ==> (?xs2. (lookup ptr refs =
         SOME (ValueArray xs2)) /\ MEM v xs2)) ==>
       reachable_refs (xs ++ (RefPtr b ptr :: stack)) refs n`),
  (* the array that is written is not the stack's xs here, so a
     value of it that was not on the stack has to have sat in the
     old array at ptr -- and then the edge that leaves ptr is an
     edge of the old references too, with ptr itself as the root *)
  (let rtcpath = prove
    (`!r1 n.
        RTC (ref_edge (insert ptr (ValueArray xs1) refs)) r1 n ==>
        RTC (ref_edge refs) r1 n \/
        (?s. MEM s (get_refs (Block 0 ARB xs1)) /\
             RTC (ref_edge refs) s n)`,
     MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
      [GEN_TAC THEN DISJ1_TAC THEN
       MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
       REPEAT GEN_TAC THEN REWRITE_TAC[ref_edge_ValueArray] THEN
       COND_CASES_TAC THEN STRIP_TAC THEN
       ASM_MESON_TAC[RTC_RULES]]) in
   let mem_block_refs = prove
    (`!(ys:(dataSem_v)list) ss tt aa.
        MEM ss (get_refs (Block tt aa ys))
        ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   let oldedge = prove
    (`!xs2 s. (lookup ptr refs = SOME (ValueArray xs2)) /\
              MEM s (get_refs (Block 0 ARB xs2))
              ==> ref_edge refs ptr s`,
     REWRITE_TAC[ref_edge_def] THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[]) in
   REWRITE_TAC[reachable_refs_def] THEN
   DISCH_THEN(X_CHOOSE_THEN `x:dataSem_v`
     (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC)) THEN
   DISCH_TAC THEN
   FIRST_ASSUM(fun rtc -> MP_TAC(MATCH_MP rtcpath rtc)) THEN
   DISCH_THEN(DISJ_CASES_THEN2
     (fun old ->
        MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
        ASM_REWRITE_TAC[old])
     (X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)) THEN
   FIRST_ASSUM(fun m -> MP_TAC(MATCH_MP mem_block_refs m)) THEN
   DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v` STRIP_ASSUME_TAC) THEN
   ASM_CASES_TAC `MEM (yy:dataSem_v) xs` THENL
    [MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `s:num`] THEN
     ASM_REWRITE_TAC[MEM_APPEND];
     FIRST_X_ASSUM(fun side ->
       MP_TAC(MATCH_MP (MATCH_MP side (ASSUME `MEM (yy:dataSem_v)
         xs1`)) (ASSUME `~(MEM (yy:dataSem_v) xs)`))) THEN
     DISCH_THEN(X_CHOOSE_THEN `xs2:(dataSem_v)list`
       STRIP_ASSUME_TAC) THEN
     MAP_EVERY EXISTS_TAC
       [`RefPtr b ptr:dataSem_v`; `ptr:num`] THEN
     REWRITE_TAC[MEM_APPEND; MEM; get_refs_def] THEN
     MATCH_MP_TAC(CONJUNCT2(SPEC_ALL RTC_RULES)) THEN
     EXISTS_TAC `s:num` THEN ASM_REWRITE_TAC[] THEN
     MATCH_MP_TAC oldedge THEN EXISTS_TAC `xs2:(dataSem_v)list` THEN
     CONJ_TAC THENL
      [FIRST_ASSUM ACCEPT_TAC;
       REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
       EXISTS_TAC `get_refs (yy:dataSem_v)` THEN CONJ_TAC THENL
        [EXISTS_TAC `yy:dataSem_v` THEN ASM_REWRITE_TAC[];
         FIRST_ASSUM ACCEPT_TAC]]]));;

let v_inv_ByteArray_insert_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
       (ptr IN domain refs ==> (?a b. lookup ptr refs = SOME
         (ByteArray a b))) ==>
         v_inv_ck ck conf v1 (insert ptr (ByteArray fl xs) refs)
           (y,f,tf,heap)`,
  (* the refs that the lemma puts a byte array into: v_inv reads
     the cell at ptr to see whether it is a thunk, to annotate a
     pointer to it and in the dest_thunk of a value, and a byte
     array is no thunk and no MutBlock, as what was there is not
     either *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`(ptr IN domain refs ==>
       ?a b. lookup ptr refs = SOME (ByteArray a b)) ==>
      (!k ev v.
         lookup k (insert ptr (ByteArray fl xs) refs) =
           SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ref_ptr_annot conf
             (lookup k (insert ptr (ByteArray fl xs) refs)) =
           ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v refs = NotThunk ==>
           dest_thunk v (insert ptr (ByteArray fl xs) refs) =
             NotThunk) /\
      (!k bb.
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (ByteArray fl xs) refs) =
              SOME (bvlSem_MutBlock t2 g2 m2 d2 s2) ==> ~bb))`,
     DISCH_TAC THEN
     (* the cell at ptr is a byte array, or the refs have no cell
        there: the two are what the rules of a RefPtr read *)
     (SUBGOAL_THEN
       `lookup ptr (refs:(dataSem_v bvlSem_ref) spt) = NONE \/
        ?a b. lookup ptr refs = SOME (ByteArray a b)`
       STRIP_ASSUME_TAC THENL
      [FIRST_ASSUM(fun h ->
         let d = lhand(concl h) in
         ASM_CASES_TAC d THENL
          [DISJ2_TAC THEN MATCH_ACCEPT_TAC(MP h (ASSUME d));
           DISJ1_TAC THEN
           MATCH_ACCEPT_TAC(MATCH_MP no_lk (ASSUME(mk_neg d)))]);
       ALL_TAC; ALL_TAC]) THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[ref_ptr_annot_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
       TRY(CONV_TAC TAUT);
       REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
       REWRITE_TAC[lookup_insert] THEN COND_CASES_TAC THEN
       ASM_REWRITE_TAC(opt @ rfs) THEN
       TRY(FIRST_ASSUM MATCH_ACCEPT_TAC)])) in
   V_INV_REFS_TAC ALL_TAC ALL_TAC (V_INV_REFS_PLAIN same)
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

let v_inv_ByteArray_insert = prove
 (`!conf v1 refs v2 f tf heap ptr fl xs.
     v_inv conf v1 refs (v2,f,tf,heap) /\
     (ptr IN domain refs ==> (?a b. lookup ptr refs = SOME (ByteArray
       a b))) ==>
       v_inv conf v1 (insert ptr (ByteArray fl xs) refs)
         (v2,f,tf,heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_ByteArray_insert_lemma]));;

let isRefBlock_def = cake_define
  `isRefBlock x = (?p. x = RefBlock p)`;;

let RefBlock_inv_def = cake_define
  `RefBlock_inv heap heap2 <=>
     (!n x. (heap_lookup n heap = SOME x) /\ ~(isRefBlock x) ==>
            (heap_lookup n heap2 = SOME x)) /\
     (!n x. (heap_lookup n heap2 = SOME x) /\ ~(isRefBlock x) ==>
            (heap_lookup n heap = SOME x))`;;

let heap_store_RefBlock_thm = prove
 (`!ha. (LENGTH x = LENGTH y) ==>
         (heap_store (heap_length ha) [RefBlock x] (ha ++ (RefBlock y
           :: hb)) =
           (ha ++ (RefBlock x :: hb),T))`,
  (* heap_store_lemma stores at the length of the prefix, and the
     condition it leaves is that the two RefBlocks are of a length *)
  (let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   GEN_TAC THEN DISCH_TAC THEN
   REWRITE_TAC[heap_store_lemma; APPEND; PAIR_EQ; hlen_cl;
               RefBlock_def; el_length_def] THEN
   ASM_ARITH_TAC));;

(* [local] *)
let heap_lookup_RefBlock_lemma = prove
 (`(heap_lookup n (ha ++ (RefBlock y :: hb)) = SOME x) =
       (if n < heap_length ha then
         (heap_lookup n ha = SOME x) else if n = heap_length ha then
         (x = RefBlock y) else if heap_length ha + (LENGTH y + 1) <=
           n then
         (heap_lookup (n - heap_length ha - (LENGTH y + 1)) hb =
           SOME x) else F)`,
  (* the lookup in the append is the one in ha or the one in the
     RefBlock and what follows it, and a RefBlock is LENGTH y + 1
     long *)
  (REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
               heap_lookup_def; RefBlock_def;
               el_length_def] THEN
   REPEAT COND_CASES_TAC THEN
   ASM_REWRITE_TAC[injectivity "option"; distinctness "option"] THEN
   TRY(POP_ASSUM_LIST(fun ths ->
     MP_TAC(end_itlist CONJ (rev ths))) THEN ARITH_TAC) THEN
   TRY(MATCH_ACCEPT_TAC EQ_SYM_EQ) THEN
   REWRITE_TAC[]));;

(* [local] *)
let heap_store_RefBlock = prove
 (`(LENGTH y = LENGTH h) /\
     (heap_lookup n heap = SOME (RefBlock y)) ==>
     (?heap2. (heap_store n [RefBlock h] heap = (heap2,T)) /\
             RefBlock_inv heap heap2 /\
             (heap_lookup n heap2 = SOME (RefBlock h)) /\
             (heap_length heap2 = heap_length heap) /\
             (FILTER isForwardPointer heap2 = FILTER isForwardPointer
               heap) /\
             (!xs l d.
                MEM (DataElement xs l d) heap2 ==> (DataElement xs l
                  d = RefBlock h) \/
                              MEM (DataElement xs l d) heap) /\
             (!a. isSomeDataElement (heap_lookup a heap2) =
                  isSomeDataElement (heap_lookup a heap)) /\
             (!m x. ~(m = n) /\ (heap_lookup m heap = SOME x) ==>
                   (heap_lookup m heap2 = SOME x)))`,
  (* a store into a RefBlock: heap_lookup_SPLIT cuts the heap at
     the element, heap_store_RefBlock_thm does the store, and
     heap_lookup_RefBlock_lemma says where an address falls -- in
     the part before the element, at the element itself, or past
     it -- which is the same of both heaps, because the two
     RefBlocks are of a length.  So the two heaps have the same
     length, the same forward pointers and the same data elements
     but the one stored into, their lookups agree away from it,
     and a RefBlock_inv holds, because an element that is not a
     RefBlock is not the one that changed *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    (* the clauses of heap_length *)
    let hlen_cl = prove
     (`heap_length [] = 0 /\
       (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
      REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
    (* a RefBlock is one *)
    let isrb = prove
     (`!p. isRefBlock (RefBlock p)`,
      REWRITE_TAC[isRefBlock_def] THEN MESON_TAC[]) in
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    FIRST_ASSUM(fun hl ->
      MP_TAC(MATCH_MP heap_lookup_SPLIT hl)) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "APPEND" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "heap_length" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    W(fun (asl,w) ->
      let hs = find_term (hd_is "heap_store") (snd(strip_exists w)) in
      let args = snd(strip_comb hs) in
      let nb = lhand (el 1 args) in
      let hp = el 2 args in
      let ap = rator (rator hp) in
      let rest = rand hp in
      let cs = rator (rator rest) in
      EXISTS_TAC (mk_comb(mk_comb(ap,lhand hp),
                          mk_comb(mk_comb(cs,nb),rand rest)))) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC heap_store_RefBlock_thm THEN
      FIRST_ASSUM(ACCEPT_TAC o SYM);
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[RefBlock_inv_def;
                  heap_lookup_RefBlock_lemma] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THEN REPEAT GEN_TAC THEN
      REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
      STRIP_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      REPEAT(FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) && is_var (lhs (concl e)) &&
           hd_is "RefBlock" (rhs (concl e))
        then SUBST_ALL_TAC e else fail())) THEN
      RULE_ASSUM_TAC(REWRITE_RULE[isrb]) THEN
      FIRST_X_ASSUM CONTR_TAC;
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_lookup_RefBlock_lemma; LT_REFL];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_length_APPEND; hlen_cl;
                  RefBlock_def; el_length_def] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[FILTER_APPEND; FILTER; isForwardPointer_def;
                  RefBlock_def] THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[MEM_APPEND; MEM] THEN MESON_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [GEN_TAC THEN
      REWRITE_TAC[isSomeDataElement_def] THEN
      REWRITE_TAC[heap_lookup_RefBlock_lemma] THEN
      ASM_REWRITE_TAC[] THEN
      REPEAT COND_CASES_TAC THEN
      REWRITE_TAC[RefBlock_def] THEN MESON_TAC[];
      ALL_TAC] THEN
    REPEAT GEN_TAC THEN
    REWRITE_TAC[heap_lookup_RefBlock_lemma] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]));;

(* [local] *)
let NOT_isRefBlock = prove
 (`~(isRefBlock (Bignum x)) /\
     ~(isRefBlock (Word64Rep a w)) /\
     ~(isRefBlock (DataElement xs (LENGTH xs) (BlockTag n,[])))`,
  (* the tag of a RefBlock is RefTag, and the three shapes have
     another one; the conditional of Word64Rep is split after the
     first rewrite, so the injectivity is used again under it *)
  (let rws = [injectivity "heap_element"; PAIR_EQ;
              distinctness "data_to_word_memoryProof_tag"] in
   REWRITE_TAC[isRefBlock_def; RefBlock_def;
               bignum_def; cake_raw "Word64Rep"] THEN
   PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC rws THEN
   REPEAT CONJ_TAC THEN TRY COND_CASES_TAC THEN
   REWRITE_TAC rws));;

(* [local] *)
let v_inv_Ref_lemma = prove
 (`!ck w refs x f tf heap.
     v_inv conf w refs (x,f,tf,heap) /\
     RefBlock_inv heap heap2 ==>
       v_inv_ck ck conf w refs (x,f,tf,heap) = v_inv_ck ck conf w
         refs (x,f,tf,heap2)`,
  (* the two heaps agree on every element that is no RefBlock, and
     the elements that the relation looks up are none of them: so
     one direction of the equation is the induction with that
     carried over, and the other is the hypothesis itself, which
     says the relation holds at the old heap for every clock *)
  ((* the two heaps agree on every element that is no RefBlock, and
      the elements that the relation looks up are none *)
   let hp =
     FIRST_ASSUM(fun rb ->
       let (f1,_) = CONJ_PAIR (REWRITE_RULE[RefBlock_inv_def] rb) in
       MATCH_MP_TAC f1 THEN CONJ_TAC THENL
        [FIRST_ASSUM MATCH_ACCEPT_TAC;
         REWRITE_TAC[isRefBlock_def; RefBlock_def; BlockRep_def;
                     bignum_def; Word64Rep_def; ThunkBlock_def] THEN
         CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
         TRY PAIRARG_TAC THEN
         CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
         TRY COND_CASES_TAC THEN
         REWRITE_TAC[injectivity "heap_element"; PAIR_EQ;
                     distinctness "data_to_word_memoryProof_tag"] THEN
         REWRITE_TAC[NOT_EXISTS_THM; DE_MORGAN_THM]]) in
   (* one direction of the equation: the relation at the new heap *)
   let dir = prove
    (`!ck w refs x f tf heap.
        v_inv conf w refs (x,f,tf,heap) /\ RefBlock_inv heap heap2
        ==> v_inv_ck ck conf w refs (x,f,tf,heap2)`,
     V_INV_REFS_TAC ALL_TAC hp V_INV_HEAP_PLAIN
       (V_INV_HEAP_THUNK hp 5) (V_INV_HEAP_THUNK hp 6)) in
   (* and the other one is the hypothesis itself, which says the
      relation holds at the old heap for every clock *)
   REPEAT GEN_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
   EQ_TAC THEN DISCH_THEN(K ALL_TAC) THENL
    [FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun rb ->
       MATCH_ACCEPT_TAC(SPEC_ALL(MATCH_MP dir (CONJ vi rb)))));
     FIRST_ASSUM(fun vi ->
       MATCH_ACCEPT_TAC(SPEC_ALL(REWRITE_RULE[v_inv_eq] vi)))]));;

(* [local] *)
let v_inv_Ref = prove
 (`RefBlock_inv heap heap2 ==>
     (!x h f tf. (v_inv conf x refs (h,f,tf,heap2) =
                 v_inv conf x refs (h,f,tf,heap)))`,
  (* v_inv_Ref_lemma says that the clocked relation does not see the
     difference between the two heaps, of a value that the relation
     holds of; the unclocked one is the clocked one at every clock,
     so each side gives the other.  The lemma's heap2 is a free
     variable, so the other direction is the lemma with the two
     heaps exchanged, and RefBlock_inv is symmetric *)
  (let lem = v_inv_Ref_lemma in
   let hp = find_term (fun t -> is_var t && fst(dest_var t) = "heap")
              (concl lem) in
   let hp2 = find_term
               (fun t -> is_var t && fst(dest_var t) = "heap2")
               (concl lem) in
   let swapped = INST [hp2,hp; hp,hp2] lem in
   let sym_rb = prove
    (`!h1 h2. RefBlock_inv h1 h2 ==> RefBlock_inv h2 h1`,
     REWRITE_TAC[RefBlock_inv_def] THEN MESON_TAC[]) in
   let step lemm rbt =
     ONCE_REWRITE_TAC[v_inv_eq] THEN
     FIRST_ASSUM(fun rb -> FIRST_ASSUM(fun vi ->
       let th = MATCH_MP lemm (CONJ vi (rbt rb)) in
       let ckv = find_term
                   (fun t -> is_var t && fst(dest_var t) = "ck")
                   (concl th) in
       MP_TAC(GEN ckv th))) THEN
     DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
     FIRST_ASSUM(fun vi -> ACCEPT_TAC(REWRITE_RULE[v_inv_eq] vi)) in
   DISCH_TAC THEN REPEAT GEN_TAC THEN EQ_TAC THEN DISCH_TAC THENL
    [step swapped (MATCH_MP sym_rb);
     step lem (fun th -> th)]));;

let v_inv_ValueArray_insert_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
       RefBlock_inv heap heap2 /\
       (ptr IN domain refs ==> (?as. lookup ptr refs = SOME
         (ValueArray as))) ==>
         v_inv_ck ck conf v1 (insert ptr (ValueArray xs) refs)
           (y,f,tf,heap)`,
  (* the same of an array of values, whose annotation is zero as
     well.  The hypothesis about the cell at ptr is the second
     conjunct of what the lemma assumes, and prep gives it by
     itself *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`(ptr IN domain refs ==>
       ?as. lookup ptr refs = SOME (ValueArray as)) ==>
      (!k ev v.
         lookup k (insert ptr (ValueArray xs) refs) =
           SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ref_ptr_annot conf
             (lookup k (insert ptr (ValueArray xs) refs)) =
           ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v refs = NotThunk ==>
           dest_thunk v (insert ptr (ValueArray xs) refs) =
             NotThunk) /\
      (!k bb.
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (ValueArray xs) refs) =
              SOME (bvlSem_MutBlock t2 g2 m2 d2 s2) ==> ~bb))`,
     DISCH_TAC THEN
     (* the cell at ptr is an array of values, or the refs have no
        cell there: the two are what the rules of a RefPtr read *)
     (SUBGOAL_THEN
       `lookup ptr (refs:(dataSem_v bvlSem_ref) spt) = NONE \/
        ?as. lookup ptr refs = SOME (ValueArray as)`
       STRIP_ASSUME_TAC THENL
      [FIRST_ASSUM(fun h ->
         let d = lhand(concl h) in
         ASM_CASES_TAC d THENL
          [DISJ2_TAC THEN MATCH_ACCEPT_TAC(MP h (ASSUME d));
           DISJ1_TAC THEN
           MATCH_ACCEPT_TAC(MATCH_MP no_lk (ASSUME(mk_neg d)))]);
       ALL_TAC; ALL_TAC]) THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[ref_ptr_annot_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
       TRY(CONV_TAC TAUT);
       REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
       REWRITE_TAC[lookup_insert] THEN COND_CASES_TAC THEN
       ASM_REWRITE_TAC(opt @ rfs) THEN
       TRY(FIRST_ASSUM MATCH_ACCEPT_TAC)])) in
   let prep = FIRST_ASSUM(fun a -> ASSUME_TAC(CONJUNCT2 a)) in
   V_INV_REFS_TAC prep ALL_TAC (V_INV_REFS_PLAIN same)
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

let v_inv_ValueArray_insert = prove
 (`!conf v1 refs v2 f tf heap ptr xs heap2.
     RefBlock_inv heap heap2 /\
     v_inv conf v1 refs (v2,f,tf,heap) /\
     (ptr IN domain refs ==> (?as. lookup ptr refs = SOME (ValueArray
       as))) ==>
       v_inv conf v1 (insert ptr (ValueArray xs) refs)
         (v2,f,tf,heap2)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_ValueArray_insert_lemma;
                 v_inv_Ref]));;

(* inserting a *fresh* MutBlock ref cannot disturb any existing v_inv: the only
   way v_inv inspects refs is through a RefPtr, and those are confined to
   FDOM f, which sits inside domain refs *)
let v_inv_MutBlock_insert_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
     ~(ptr IN domain refs) /\ FDOM f SUBSET domain refs ==>
       v_inv_ck ck conf v1 (insert ptr (bvlSem_MutBlock tag fin l
         cv r) refs) (y,f,tf,heap)`,
  (* here the cell is put at a key that the refs do not have, so a
     MutBlock appears where there was nothing: the annotation of a
     pointer and the condition of a plain reference are the old
     ones away from ptr, and a pointer of the relation is a key of
     f, which is a key of the refs *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`lookup ptr refs = NONE ==>
      (!k ev v.
         lookup k (insert ptr (bvlSem_MutBlock tag fin l cv r)
           refs) = SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ~(k = ptr) ==>
         ref_ptr_annot conf
           (lookup k (insert ptr (bvlSem_MutBlock tag fin l cv r)
             refs)) =
         ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v refs = NotThunk ==>
           dest_thunk v (insert ptr
             (bvlSem_MutBlock tag fin l cv r) refs) = NotThunk) /\
      (!k bb.
         ~(k = ptr) /\
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (bvlSem_MutBlock tag fin l cv r)
              refs) = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
                ==> ~bb))`,
     DISCH_TAC THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       REPEAT STRIP_TAC THEN REWRITE_TAC[lookup_insert] THEN
       ASM_REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
       TRY(CONV_TAC TAUT);
       REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
       REWRITE_TAC[lookup_insert] THEN ASM_REWRITE_TAC[] THEN
       TRY(FIRST_ASSUM MATCH_ACCEPT_TAC)])) in
   let prep =
     FIRST_ASSUM(fun ds ->
       ASSUME_TAC(MATCH_MP no_lk (CONJUNCT1 ds)) THEN
       ASSUME_TAC(REWRITE_RULE[SUBSET] (CONJUNCT2 ds))) in
   let d5 =
     REPEAT SUBST_LHS_TAC THEN
     FIRST_ASSUM(fun nolk ->
       let (t_eq,a_eq,_,m_imp) = v_inv_refs_parts same nolk in
       FIRST_ASSUM(fun sub -> FIRST_ASSUM(fun fd ->
         let np = MATCH_MP notptr (CONJ nolk (CONJ sub fd)) in
         REWRITE_TAC[GSYM (MATCH_MP a_eq np)] THEN
         MATCH_MP_TAC(el 4 v_inv_ck_rules) THEN
         REPEAT CONJ_TAC THENL
          [FIRST_ASSUM MATCH_ACCEPT_TAC;
           ASM_REWRITE_TAC[t_eq];
           MATCH_MP_TAC m_imp THEN CONJ_TAC THENL
            [ACCEPT_TAC np; FIRST_ASSUM MATCH_ACCEPT_TAC]]))) in
   V_INV_REFS_TAC prep ALL_TAC d5
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

let v_inv_MutBlock_insert = prove
 (`!conf v1 refs v2 f tf heap ptr tag fin l cv r.
     v_inv conf v1 refs (v2,f,tf,heap) /\
     ~(ptr IN domain refs) /\ FDOM f SUBSET domain refs ==>
       v_inv conf v1 (insert ptr (bvlSem_MutBlock tag fin l cv r)
         refs) (v2,f,tf,heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_MutBlock_insert_lemma]));;

(* v_inv cannot see a MutBlock's finalised flag: ref_ptr_annot ignores it and
   dest_thunk sends every MutBlock to NotThunk.  Flipping the flag therefore
   preserves v_inv -- this is what makes FinaliseCons a no-op at word level. *)
(* [local] *)
let v_inv_MutBlock_fin_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
     lookup ptr refs = SOME (bvlSem_MutBlock tag fin1 ll cv rr) ==>
       v_inv_ck ck conf v1 (insert ptr (bvlSem_MutBlock tag fin2 ll
         cv rr) refs)
         (y,f,tf,heap)`,
  (* the cell at ptr keeps its tag and its payload, so all four
     lookups of the new refs are the old ones: the annotation is
     the ptr_bits of the tag and the two lengths, which the flag
     does not enter, and a MutBlock is no thunk *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`lookup ptr refs = SOME (bvlSem_MutBlock tag fin1 ll cv rr) ==>
      (!k ev v.
         lookup k (insert ptr (bvlSem_MutBlock tag fin2 ll cv rr)
           refs) = SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ref_ptr_annot conf
             (lookup k (insert ptr
               (bvlSem_MutBlock tag fin2 ll cv rr) refs)) =
           ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v (insert ptr
             (bvlSem_MutBlock tag fin2 ll cv rr) refs) =
           dest_thunk v refs) /\
      (!k bb.
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (bvlSem_MutBlock tag fin2 ll cv rr)
              refs) = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
                ==> ~bb))`,
     DISCH_TAC THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[ref_ptr_annot_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[];
       REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
       (REWRITE_TAC[lookup_insert] THEN COND_CASES_TAC THENL
         [FIRST_X_ASSUM SUBST_ALL_TAC THEN
          DISCH_THEN(K ALL_TAC) THEN
          FIRST_ASSUM(fun a -> FIRST_ASSUM(fun lk ->
            ACCEPT_TAC(MATCH_MP a lk)));
          FIRST_ASSUM MATCH_ACCEPT_TAC])])) in
   V_INV_REFS_TAC ALL_TAC ALL_TAC (V_INV_REFS_PLAIN same)
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

(* bound variables deliberately avoid the names used at the use sites, so that
   irule/MATCH_MP_TAC does not fail on a free/bound name clash *)
let v_inv_MutBlock_fin = prove
 (`!cnf vv rfs yy ff tff hp pp tg b1 b2 l1 c1 r1.
     v_inv cnf vv rfs (yy,ff,tff,hp) /\
     lookup pp rfs = SOME (bvlSem_MutBlock tg b1 l1 c1 r1) ==>
       v_inv cnf vv (insert pp (bvlSem_MutBlock tg b2 l1 c1 r1)
         rfs) (yy,ff,tff,hp)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_MutBlock_fin_lemma]));;

(* ---- MutCons: the Cons allocation, but the value handed back is a fresh ref *)

(* [local] *)
let all_ts_SUBSET_gen = prove
 (`(!x. ((?n r'. lookup n refs1 = SOME r' /\ find_ref r' x) \/ MEM x
  stack1) ==>
        ((?n r'. lookup n refs2 = SOME r' /\ find_ref r' x) \/ MEM x
          stack2)) ==>
   all_ts refs1 stack1 SUBSET all_ts refs2 stack2`,
  (REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]));;

(* like all_ts_SUBSET_gen, but the witness on the right may be a different
   value, as long as it carries the timestamp -- needed when a value only
   survives inside a newly built Block *)
(* [local] *)
let all_ts_SUBSET_ts = prove
 (`(!x t. (((?n r'. lookup n refs1 = SOME r' /\ find_ref r' x) \/ MEM x
  stack1) /\
           MEM t (v_all_ts x)) ==>
          (?x'. ((?n r'. lookup n refs2 = SOME r' /\ find_ref r' x')
            \/
                MEM x' stack2) /\ MEM t (v_all_ts x'))) ==>
   all_ts refs1 stack1 SUBSET all_ts refs2 stack2`,
  (REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN MESON_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let all_ts_mutcons = prove
 (cake_as_vars (fun () ->
    `~(ptr IN domain refs) ==>
       all_ts refs ((l ++ [c] ++ r) ++ stack) SUBSET
       all_ts (insert ptr (bvlSem_MutBlock tag F l c r) refs)
         (RefPtr F ptr :: stack)`),
  (* every value that the old refs and stack reach is reached by the
     new ones: one of the refs is not the fresh pointer, because the
     fresh one has no value in refs at all, and the three parts of
     the MutBlock are what find_ref gives of it *)
  (let fr = prove
    (`!tg fin l c r x.
        find_ref (bvlSem_MutBlock tg fin l c r) x <=>
        MEM x l \/ x = c \/ MEM x r`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [find_ref_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[MEM_APPEND; MEM]) in
   let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN
     CONV_TAC TAUT) in
   DISCH_THEN(fun hyp ->
     MATCH_MP_TAC all_ts_SUBSET_gen THEN GEN_TAC THEN
     REWRITE_TAC[MEM_APPEND; MEM; li] THEN
     MESON_TAC[fr; REWRITE_RULE[GSYM lookup_NONE_domain] hyp;
               distinctness "option"])));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_mutcons = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs ((l ++ [c] ++ r) ++ stack)) ==>
     blocks_unique ts
       (all_vs (insert ptr (bvlSem_MutBlock tag F l c r) refs)
         (RefPtr F ptr :: stack))`),
  (* a Block of the new refs and stack is one of the old ones: the
     MutBlock at the fresh pointer holds the values that the old
     stack has in front of it, and the RefPtr is no Block *)
  (let vrefptr = prove
    (`!b p ys. v_all_vs (CONS (RefPtr b p) ys) =
        CONS (RefPtr b p) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let inc = prove
    (`!refs ptr tag l c r stack' t a xs.
        Block t a xs IN
          all_vs (insert ptr (bvlSem_MutBlock tag F l c r) refs)
                 (CONS (RefPtr F ptr) stack') ==>
        Block t a xs IN
          all_vs refs (APPEND (APPEND l (APPEND [c] r)) stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; vrefptr;
                 v_all_vs_append; MEM; MEM_APPEND; li;
                 distinctness "dataSem_v"; distinctness "bvlSem_ref";
                 injectivity "bvlSem_ref"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* [local] *)
let ref_edge_MutBlock = prove
 (`ref_edge (insert ptr (bvlSem_MutBlock tag fin l c r) refs) x y =
     (if x = ptr then MEM y (get_refs (Block 0 ARB (l ++ [c] ++
       r))) else ref_edge refs x y)`,
  (REWRITE_TAC[ref_edge_def; lookup_insert] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[]));;

(* the only new edge leaves ptr and lands inside the payload, which is exactly
   what used to sit on the stack *)
(* [local] *)
let reachable_refs_MutCons_lemma = prove
 (`!r1 n.
     RTC (ref_edge (insert ptr (bvlSem_MutBlock tag F l c r) refs))
       r1 n ==> ~(n = ptr) ==>
     RTC (ref_edge refs) r1 n \/
     (?s. MEM s (get_refs (Block 0 ARB (l ++ [c] ++ r))) /\ RTC
       (ref_edge refs) s n)`,
  (* induction along the reflexive transitive closure: an edge of
     the new refs is one of the old ones, or it leaves ptr and
     lands in the payload of the MutBlock *)
  (MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN DISJ1_TAC THEN
    MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
    REPEAT GEN_TAC THEN
    REWRITE_TAC[ref_edge_MutBlock] THEN
    COND_CASES_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
    ASM_MESON_TAC[RTC_RULES]]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_MutCons = prove
 (cake_as_vars (fun () ->
    `reachable_refs (RefPtr F ptr :: stack)
       (insert ptr (bvlSem_MutBlock tag F l c r) refs) n /\ ~(n =
         ptr) /\ ~(ptr IN domain refs) ==>
     reachable_refs ((l ++ [c] ++ r) ++ stack) refs n`),
  (* reachable_refs_MutCons_lemma says of a path through the new
     references that it is one of the old ones or that it starts
     inside the payload of the MutBlock.  A root of the stack keeps
     its path; the only other root is the pointer to the MutBlock,
     whose path cannot start at all, because ptr is fresh and so has
     no edge; and a path from the payload has its root among the
     payload's values *)
  (
   let mem_block_refs = prove
    (`!(ys:(dataSem_v)list) ss tt aa.
        MEM ss (get_refs (Block tt aa ys))
        ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   let subst_vars =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_eq(concl th) && is_var(lhand(concl th))
       then SUBST_ALL_TAC th else fail())) in
   let payload b =
     X_CHOOSE_THEN `ss:num` (CONJUNCTS_THEN2
       (fun m -> MP_TAC(MATCH_MP mem_block_refs m)) ASSUME_TAC) b THEN
     DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v` STRIP_ASSUME_TAC) THEN
     MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `ss:num`] THEN
     ASM_REWRITE_TAC[MEM_APPEND] in
   let noedge a =
     MP_TAC(ONCE_REWRITE_RULE[RTC_CASES] a) THEN
     FIRST_ASSUM(fun nd ->
       let th = REWRITE_RULE[GSYM lookup_NONE_domain] nd in
       if concl th = concl nd then fail()
       else REWRITE_TAC[ref_edge_def; th]) THEN
     MATCH_REDUCE_TAC THEN ASM_REWRITE_TAC[] in
   let stackcase a =
     ASSUME_TAC a THEN
     W(fun gl -> MAP_EVERY (fun n -> EXISTS_TAC (var_by_name n gl))
                   ["x"; "r'"]) THEN
     ASM_REWRITE_TAC[MEM_APPEND] in
   let uselemma =
     FIRST_ASSUM(fun rtc -> FIRST_ASSUM(fun ne ->
       MP_TAC(MATCH_MP (MATCH_MP
         reachable_refs_MutCons_lemma rtc) ne))) in
   REWRITE_TAC[reachable_refs_def; MEM] THEN STRIP_TAC THENL
    [subst_vars THEN
     RULE_ASSUM_TAC(REWRITE_RULE[get_refs_def; MEM]) THEN
     subst_vars THEN uselemma THEN
     DISCH_THEN(DISJ_CASES_THEN2 noedge payload);
     uselemma THEN DISCH_THEN(DISJ_CASES_THEN2 stackcase payload)]));;

(* lifting a v_inv across the MutCons allocation: refs gains a fresh ref and f
   gains its binding, and the heap only grew *)
(* [local] *)
let v_inv_MutCons_step = prove
 (`v_inv conf v refs (y,f,tf,heap) /\ ~(ptr IN domain refs) /\
   FDOM f SUBSET domain refs /\ heap_store_rel heap heap2 ==>
     v_inv conf v (insert ptr (bvlSem_MutBlock tag F l c r) refs)
       (y,f |+ (ptr,a),tf,heap2)`,
  (* the point is fresh in the references, so it is not in the
     domain of the map and the map is a SUBMAP of its update there;
     v_inv_MutBlock_insert adds the MutBlock to the references and
     v_inv_SUBMAP takes the relation to the bigger map and the
     bigger heap *)
  (
   let submap_fupd = prove
    (`!(g:(A,B)fmap) k v. ~(k IN FDOM g) ==> g SUBMAP (g |+ (k,v))`,
     REWRITE_TAC[SUBMAP; FDOM_FUPDATE; IN_INSERT;
                 FAPPLY_FUPDATE_THM] THEN MESON_TAC[]) in
   STRIP_TAC THEN
   SUBGOAL_THEN `~(ptr IN FDOM (f:(num,num)fmap))` ASSUME_TAC THENL
    [ASM_MESON_TAC[SUBSET]; ALL_TAC] THEN
   FIRST_ASSUM(fun nf -> ASSUME_TAC(MATCH_MP submap_fupd nf)) THEN
   FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun nd -> FIRST_ASSUM(fun sub ->
     ASSUME_TAC(MATCH_MP v_inv_MutBlock_insert
       (CONJ vi (CONJ nd sub)))))) THEN
   MATCH_MP_TAC (GEN_ALL v_inv_SUBMAP) THEN
   W(fun gl -> MAP_EVERY (fun n -> EXISTS_TAC (var_by_name n gl))
                 ["f"; "tf"; "heap"]) THEN
   ASM_REWRITE_TAC[SUBMAP_REFL]));;

(* [local] *)
let take_el_drop = prove
 (`!index vals. index < LENGTH vals ==>
     TAKE index vals ++ [EL index vals] ++ DROP (index + 1) vals =
       vals`,
  (* DROP_EL_CONS puts the element and the DROP after it back
     together, and TAKE_DROP puts the two halves back together *)
  (REPEAT STRIP_TAC THEN REWRITE_TAC[APPEND] THEN
   FIRST_ASSUM(fun th ->
     MP_TAC(REWRITE_RULE[ADD1] (MATCH_MP DROP_EL_CONS th))) THEN
   DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[TAKE_DROP]));;

(* a value that is not a thunk cannot become one by adding a fresh ref *)
(* [local] *)
let dest_thunk_insert_fresh = prove
 (`~(ptr IN domain refs) /\ dest_thunk v refs = NotThunk ==>
     dest_thunk v (insert ptr x refs) = NotThunk`,
  (* only a RefPtr reads the refs, and at a pointer that the refs
     have no value for the old dest_thunk is BadRef, which the
     assumption says it is not; away from the pointer the lookup is
     the one it was *)
  (let dt_def = dataSem_dest_thunk_def in
   let dtr = [distinctness "dataSem_dest_thunk_ret";
              injectivity "dataSem_dest_thunk_ret"] in
   let opt_rws = [distinctness "option"; injectivity "option"] in
   STRIP_TAC THEN CASES_ON_NAME "v" THEN
   ONCE_REWRITE_TAC[dt_def] THEN
   RULE_ASSUM_TAC(ONCE_REWRITE_RULE[dt_def]) THEN
   SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
   RULE_ASSUM_TAC(REWRITE_RULE[GSYM lookup_NONE_domain]) THEN
   REWRITE_TAC[lookup_insert] THEN
   ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
   EVERY_CASE_TAC THEN ASM_REWRITE_TAC dtr THEN
   REPEAT COND_CASES_TAC THEN
   ASM_MESON_TAC (dtr @ opt_rws)));;

(* mirrors cons_thm_alt: the allocation is the Cons allocation, but the value
   handed back is a RefPtr into refs, so f (not tf) gains a binding and no
   timestamp is consumed *)
(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let mutcons_thm_alt = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (l ++ [c] ++ r ++ stack) refs
                (roots,heap,be,a,sp,sp1,gens) limit ts /\
     LENGTH (l ++ [c] ++ r) < sp /\ ~(ptr IN domain refs) /\
     (!gs. ~(data_to_word_config_gc_kind conf =
       data_to_word_Generational gs)) ==>
     (?rs roots2 heap2.
       (roots = rs ++ roots2) /\ (LENGTH rs = LENGTH (l ++ [c] ++
         r)) /\
       (heap_store_unused_alt a (sp + sp1) (BlockRep tag rs) heap =
         (heap2,T)) /\
       abs_ml_inv conf (RefPtr F ptr :: stack)
         (insert ptr (bvlSem_MutBlock tag F l c r) refs)
         (gc_shared_Pointer a (wordLang_Word (ptr_bits conf tag
           (LENGTH (l ++ [c] ++ r)))) :: roots2,
          heap2,be,a + el_length (BlockRep tag rs),
          sp - el_length (BlockRep tag rs),sp1,gens) limit ts)`),
  (* the steps are above the statement (tools/overrides.py).  The
     roots of the values of the block are the front of the roots
     of the stack (LIST_REL_SPLIT1, after the appends are put to
     the left), the block fits in the unused space and
     IMP_heap_store_unused_alt writes it there; the heap, the
     roots and the space are then as good as they were, the map of
     the addresses gains the point of the block, and of the
     references the one written is the block itself while the
     others are what they were (bc_ref_inv_step) *)
  (STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* what the invariant says of the stack that the block is built
       from *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    (* the appends to the left, so that the values of the block and
       the rest of the stack are the two sides of one *)
    REWRITE_TAC[APPEND_ASSOC] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[APPEND_ASSOC]) THEN
    (* the roots of the values of the block, and the rest *)
    W(fun gl ->
      let e2 = the_asm (hd_is "ALL2") gl in
      STRIP_ASSUME_TAC (ONCE_REWRITE_RULE[LIST_REL_SPLIT1] e2)) THEN
    (* the roots of the block are as many as its values *)
    W(fun gl ->
      let e1 = the_asm (fun c -> hd_is "ALL2" c &&
                 hd_is "APPEND" (el 1 (snd (strip_comb c)))) gl in
      ASSUME_TAC (MATCH_MP LIST_REL_LENGTH e1)) THEN
    (* so the block fits in the unused space, and the store writes it
       there *)
    W(fun (asl,w as gl) ->
      let us = the_asm (hd_is "unused_space_inv") gl in
      let spsp = el 1 (snd (strip_comb (concl us))) in
      let e1 = the_asm (fun c -> hd_is "ALL2" c &&
                 hd_is "APPEND" (el 1 (snd (strip_comb c)))) gl in
      let ys1 = el 2 (snd (strip_comb (concl e1))) in
      let bl = rator (find_term (hd_is "BlockRep") w) in
      let el1 = mk_comb (bl, ys1) in
      SUBGOAL_THEN (list_mk_icomb "<="
                      [list_mk_icomb "el_length" [el1]; spsp])
        (fun bd -> STRIP_ASSUME_TAC (MATCH_MP
           IMP_heap_store_unused_alt (CONJ us bd))) THENL
       [REWRITE_TAC[BlockRep_def; el_length_def] THEN
        ASM_ARITH_TAC;
        ALL_TAC]) THEN
    (* the block is a data element, which is what the two facts about
       the store ask for *)
    W(fun gl ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
      let isd = is_data_el el1 in
      MAP_EVERY (fun th -> ASSUME_TAC (MP th isd))
        (mapfilter (fun (_,th) ->
           let c = concl th in
           if is_imp c && hd_is "isDataElement" (lhand c) then th
           else fail()) (fst gl))) THEN
    (* the witnesses: the roots of the block, the rest of them, and
       the heap that the store wrote *)
    W(fun (asl,w as gl) ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let ys1 = el 1 (snd (strip_comb
                  (el 2 (snd (strip_comb (lhand (concl st))))))) in
      let heap2 = lhand (rand (concl st)) in
      let rts = the_asm (fun c -> is_eq c && is_var (lhand c) &&
                  hd_is "APPEND" (rand c)) gl in
      MAP_EVERY EXISTS_TAC [ys1; rand (rand (concl rts)); heap2]) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    TRY (SOLVED (W(fun gl ->
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "LENGTH" (lhand c) &&
                 hd_is "LENGTH" (rand c)) gl in
      ACCEPT_TAC (SYM le)))) THEN
    (* and the invariant of the new heap and references *)
    REWRITE_TAC[abs_ml_inv_def] THEN
    (* the addresses that hold data are the ones that did, and the
       one the store wrote *)
    W(fun gl ->
      let seq = the_asm (fun c -> is_eq c &&
                  hd_is "INSERT" (rand c)) gl in
      let ro = the_asm (hd_is "roots_ok") gl in
      ASSUME_TAC (REWRITE_RULE[EXTENSION; IN_INSERT; IN_ELIM_THM]
                    seq) THEN
      ASSUME_TAC (REWRITE_RULE[roots_ok_def] ro)) THEN
    REPEAT CONJ_TAC THEN
    (* the roots: the one of the block is the address it was written
       at, and the others are the ones they were *)
    TRY (SOLVED
          (REWRITE_TAC[roots_ok_def; MEM] THEN
           REPEAT STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           TRY (SOLVED
                 (DISJ1_TAC THEN
                  FIRST_X_ASSUM (fun e ->
                    if not (is_eq (concl e)) ||
                       not (hd_is "gc_shared_Pointer" (rand (concl e)))
                    then fail() else
                    MP_TAC e) THEN
                  REWRITE_TAC[injectivity "heap_address"] THEN
                  MESON_TAC[])) THEN
           DISJ2_TAC THEN
           ASM_MESON_TAC[MEM_APPEND])) THEN
    (* the heap is good: it is as long as it was, it has no forward
       pointer, and the pointers of the block are roots of the stack *)
    TRY (SOLVED
          (REWRITE_TAC[heap_ok_def] THEN
           REPEAT CONJ_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let hl = the_asm (fun c -> is_eq c &&
                               hd_is "heap_length" (lhand c)) gl in
                    MP_TAC ho THEN REWRITE_TAC[hl] THEN
                    STRIP_TAC THEN ASM_REWRITE_TAC[]))) THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let impl = the_asm (fun c -> is_imp c &&
                                 is_neg (lhand c) &&
                                 hd_is "isForwardPointer"
                                   (rand (lhand c))) gl in
                    let st = the_asm (fun c -> is_eq c &&
                               hd_is "heap_store_unused_alt"
                                 (lhand c)) gl in
                    let el1 = el 2 (snd (strip_comb
                                (lhand (concl st)))) in
                    SUBGOAL_THEN (mk_neg (list_mk_icomb
                                    "isForwardPointer" [el1]))
                      (fun nf -> MP_TAC ho THEN
                         REWRITE_TAC[MP impl nf] THEN
                         STRIP_TAC THEN ASM_REWRITE_TAC[]) THEN
                    REWRITE_TAC[BlockRep_def; isForwardPointer_def] THEN
                    MATCH_REDUCE_TAC THEN REWRITE_TAC[]))) THEN
           (* the pointers: of the block they are its roots, which the
              stack had, and of any other element they are what they
              were *)
           REPEAT GEN_TAC THEN
           W(fun gl ->
             let mem = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 3 && is_eq bd &&
                         hd_is "MEM" (lhand bd)) gl in
             REWRITE_TAC[mem]) THEN
           STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           DISJ2_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let eq = the_asm (fun c -> is_eq c &&
                               hd_is "BlockRep" (lhand c)) gl in
                    MP_TAC eq) THEN
                  REWRITE_TAC[BlockRep_def;
                              injectivity "heap_element"] THEN
                  STRIP_TAC THEN
                  ASM_MESON_TAC[MEM_APPEND])) THEN
           W(fun gl ->
             let ho = REWRITE_RULE[heap_ok_def]
                        (the_asm (hd_is "heap_ok") gl) in
             MP_TAC ho) THEN
           ASM_MESON_TAC[])) THEN
    (* the kind of the collection: this block is not in a heap that a
       generational collection goes through *)
    TRY (SOLVED
          (W(fun gl ->
             let gk = the_asm (hd_is "gc_kind_inv") gl in
             let ng = the_asm (fun c ->
                        let vs,bd = strip_forall c in
                        length vs = 1 && is_neg bd) gl in
             MATCH_ACCEPT_TAC (MATCH_MP gc_kind_not_gen_any
               (CONJ gk ng))))) THEN
    (* the unused space: what the store lemma says, with the length
       of the block taken off the first part of it.  The statement
       says el_length (BlockRep tag rs) of the pointer and of the
       space with two type variables of its own, so both are reduced
       to the length of the block first (entry 61) *)
    W(fun (asl,w as gl) ->
      if not (hd_is "unused_space_inv" w) then ALL_TAC else
      (let us = the_asm (fun c -> hd_is "unused_space_inv" c &&
                  can (find_term (hd_is "-")) c) gl in
       REWRITE_TAC[BlockRep_def; el_length_def] THEN
       MP_TAC (REWRITE_RULE[BlockRep_def; el_length_def] us) THEN
       W(fun (asl,w) ->
         let usub = el 1 (snd (strip_comb (lhand w))) in
         let gsub = el 1 (snd (strip_comb (rand w))) in
         SUBGOAL_THEN (mk_eq (usub, gsub)) ASSUME_TAC THENL
          [ASM_ARITH_TAC; ASM_REWRITE_TAC[]]))) THEN
    (* the maps: the address of the block put into the first one, and
       the timestamps as they were *)
    REWRITE_TAC[bc_stack_ref_inv_def] THEN
    W(fun (asl,w as gl) ->
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let f = rand (lhand (concl su)) in
      let tfsu = the_asm (fun c -> hd_is "SUBSET" c &&
                   hd_is "all_ts" (rand c)) gl in
      let tf = rand (lhand (concl tfsu)) in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let aa = el 0 (snd (strip_comb (lhand (concl st)))) in
      let ins = find_term (hd_is "sptree_insert") w in
      let ptr = el 0 (snd (strip_comb ins)) in
      EXISTS_TAC (list_mk_icomb "|+" [f; mk_pair (ptr, aa)]) THEN
      EXISTS_TAC tf) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the point is fresh in the map, because the references have no
       value for it *)
    W(fun gl ->
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "domain" (rand (rand c))) gl in
      let fm = rand (lhand (concl su)) in
      let ptr = el 0 (snd (strip_comb (rand (concl nd)))) in
      SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
                      [ptr; list_mk_icomb "FDOM" [fm]]))
        ASSUME_TAC THENL
       [MP_TAC su THEN MP_TAC nd THEN REWRITE_TAC[SUBSET] THEN
        MESON_TAC[];
        ALL_TAC]) THEN
    (* the addresses of the maps: the one of the block is fresh *)
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) ||
         not (can (find_term (hd_is "|+")) w) then ALL_TAC else
      (let iso = the_asm (fun c ->
                   let vs,bd = strip_forall c in
                   length vs = 1 && is_eq bd &&
                   hd_is "isSomeDataElement" (lhand bd)) gl in
       let inj = the_asm (fun c -> hd_is "INJ" c &&
                   hd_is "fmap_apply" (el 0 (snd (strip_comb c))) &&
                   rand (el 0 (snd (strip_comb c))) =
                     lhand (rand (el 0 (snd (strip_comb w))))) gl in
       let nd = the_asm (fun c -> is_neg c &&
                  hd_is "isSomeDataElement" (rand c)) gl in
       MATCH_MP_TAC INJ_FUPDATE_fresh THEN
       EXISTS_TAC (rand (concl inj)) THEN
       REPEAT CONJ_TAC THEN
       TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
       TRY (SOLVED (MP_TAC nd THEN REWRITE_TAC[IN_ELIM_THM])) THEN
       REWRITE_TAC[IN_ELIM_THM] THEN
       MATCH_ACCEPT_TAC iso)) THEN
    (* the domain of the references has the new point in it *)
    TRY (SOLVED
          (REWRITE_TAC[FDOM_FUPDATE; domain_insert] THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "domain" (rand c)) gl in
             MP_TAC su) THEN
           SET_TAC[])) THEN
    (* the timestamps are in the bigger set of addresses *)
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) then ALL_TAC else
      (let iso = the_asm (fun c ->
                   let vs,bd = strip_forall c in
                   length vs = 1 && is_eq bd &&
                   hd_is "isSomeDataElement" (lhand bd)) gl in
       let inj = the_asm (fun c -> hd_is "INJ" c &&
                   el 0 (snd (strip_comb c)) =
                     el 0 (snd (strip_comb w))) gl in
       MATCH_MP_TAC INJ_bigger THEN
       EXISTS_TAC (rand (concl inj)) THEN
       CONJ_TAC THENL
        [ACCEPT_TAC inj;
         REWRITE_TAC[IN_ELIM_THM] THEN
         REWRITE_TAC[iso] THEN MESON_TAC[]])) THEN
    (* the timestamps of the stack with the block on it *)
    TRY (SOLVED
          (MATCH_MP_TAC SUBSET_TRANS THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "all_ts" (rand c)) gl in
             let nd = the_asm (fun c -> is_neg c &&
                        hd_is "IN" (rand c) &&
                        hd_is "domain" (rand (rand c))) gl in
             EXISTS_TAC (rand (concl su)) THEN
             CONJ_TAC THENL
              [ACCEPT_TAC su;
               MATCH_ACCEPT_TAC (MATCH_MP
                 (REWRITE_RULE[APPEND_ASSOC] all_ts_mutcons)
                 nd)]))) THEN
    (* and the blocks of the stack stay unique *)
    TRY (SOLVED
          (W(fun gl ->
             let bu = the_asm (hd_is "blocks_unique") gl in
             MATCH_ACCEPT_TAC (MATCH_MP
               (REWRITE_RULE[APPEND_ASSOC] blocks_unique_mutcons)
               bu)))) THEN
    (* the transfer that the allocation leaves: what the invariant
       said of a value it says of it with the block allocated
       (v_inv_MutCons_step) *)
    W(fun (asl,w as gl) ->
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "domain" (rand (rand c))) gl in
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let hsr = the_asm (hd_is "heap_store_rel") gl in
      let old = the_asm (fun c -> hd_is "ALL2" c &&
                  is_var (el 1 (snd (strip_comb c)))) gl in
      let pred = el 0 (snd (strip_comb (concl old))) in
      let v,b1 = dest_abs pred in
      let x,vtm = dest_abs b1 in
      ASSUME_TAC (GENL [v; x] (DISCH vtm
        (MATCH_MP v_inv_MutCons_step
          (CONJ (ASSUME vtm) (CONJ nd (CONJ su hsr))))))) THEN
    (* and the two other transfers: what a value says of a thunk,
       and what the references hold at another point *)
    W(fun (asl,w as gl) ->
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "domain" (rand (rand c))) gl in
      let ins = find_term (hd_is "sptree_insert") w in
      let iargs = snd (strip_comb ins) in
      let fvs = frees (concl dest_thunk_insert_fresh) in
      let pk n = find (fun u -> fst (dest_var u) = n) fvs in
      let dtf = INST [el 2 iargs, pk "refs"; el 0 iargs, pk "ptr";
                      el 1 iargs, pk "x"] dest_thunk_insert_fresh in
      let hyp = rand (lhand (concl dtf)) in
      ASSUME_TAC (GEN (pk "v")
        (DISCH hyp (MATCH_MP dtf (CONJ nd (ASSUME hyp))))) THEN
      W(fun (asl,w) ->
        let m = genvar `:num` in
        let tr = mk_forall(m,
                   mk_imp(mk_neg (mk_eq (m, el 0 iargs)),
                          mk_eq (list_mk_icomb "sptree_lookup"
                                   [m; ins],
                                 list_mk_icomb "sptree_lookup"
                                   [m; el 2 iargs]))) in
        SUBGOAL_THEN tr ASSUME_TAC THENL
         [REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[lookup_insert];
          ALL_TAC])) THEN
    (* the values of the stack with the pointer of the block on it *)
    W(fun (asl,w) ->
      if not (hd_is "ALL2" w) then ALL_TAC else
      (REWRITE_TAC[ALL2] THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       CONJ_TAC THENL
        [REWRITE_TAC[v_inv_def] THEN DISJ1_TAC THEN
         REWRITE_TAC[FDOM_FUPDATE; IN_INSERT; lookup_insert;
                     FAPPLY_FUPDATE_THM; ref_ptr_annot_def] THEN
         REPEAT CONJ_TAC THEN
         TRY MATCH_REDUCE_TAC THEN
         (let ds = [distinctness "option"; distinctness "bvlSem_ref"] in
          REWRITE_TAC (injectivity "option" ::
                       injectivity "heap_address" ::
                       LENGTH_APPEND :: LENGTH ::
                       ds @ map GSYM ds)) THEN
         TRY (SOLVED (REWRITE_TAC[])) THEN
         TRY (SOLVED (ARITH_TAC)) THEN
         AP_TERM_TAC THEN AP_TERM_TAC THEN ARITH_TAC;
         W(fun gl ->
           let old = the_asm (fun c -> hd_is "ALL2" c &&
                       is_var (el 1 (snd (strip_comb c)))) gl in
           MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc_stack
             (CONJ (a_vtr gl) old)))])) THEN
    (* and the invariant of each reference that the new stack
       reaches: the point of the block, or one that the old stack
       reached *)
    W(fun (asl,w) ->
      if not (is_forall w) then ALL_TAC else
      (REPEAT STRIP_TAC THEN
       W(fun (asl,w) ->
         let ins = find_term (hd_is "sptree_insert") w in
         let ptr = el 0 (snd (strip_comb ins)) in
         let n = el 1 (snd (strip_comb w)) in
         ASM_CASES_TAC (mk_eq (n, ptr))) THEN
       TRY VAR_EQ_TAC THEN
       W(fun (asl,w) ->
         let n = el 1 (snd (strip_comb w)) in
         let ins = find_term (hd_is "sptree_insert") w in
         if not (n = el 0 (snd (strip_comb ins))) then ALL_TAC else
       (* the point of the block: its element is the block, and no
          timestamp has its address *)
             (W(fun (asl,w as gl) ->
                let ins = find_term (hd_is "sptree_insert") w in
                let iargs = snd (strip_comb ins) in
                let ptr = el 0 iargs in
                let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
                let st = the_asm (fun c -> is_eq c &&
                           hd_is "heap_store_unused_alt"
                             (lhand c)) gl in
                let aa = el 0 (snd (strip_comb (lhand (concl st)))) in
                SUBGOAL_THEN (mk_eq (list_mk_icomb "FLOOKUP" [fm; ptr],
                                list_mk_icomb "SOME" [aa]))
                  ASSUME_TAC THENL
                 [REWRITE_TAC[FLOOKUP_UPDATE]; ALL_TAC] THEN
                SUBGOAL_THEN
                  (mk_eq (list_mk_icomb "sptree_lookup" [ptr; ins],
                          list_mk_icomb "SOME" [el 1 iargs]))
                  ASSUME_TAC THENL
                 [REWRITE_TAC[lookup_insert]; ALL_TAC]) THEN
              W(fun gl ->
                let lk1 = the_asm (fun c -> is_eq c &&
                            hd_is "FLOOKUP" (lhand c)) gl in
                let lk2 = the_asm (fun c -> is_eq c &&
                            hd_is "sptree_lookup" (lhand c) &&
                            hd_is "sptree_insert"
                              (rand (lhand c))) gl in
                REWRITE_TAC[MATCH_MP arm_MB (CONJ lk1 lk2)]) THEN
              REWRITE_TAC[APPEND_ASSOC] THEN
              REPEAT CONJ_TAC THEN
              TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
              (* no timestamp has the address of the block, because it
                 held no data *)
              W(fun (asl,w) ->
                if not (is_neg w) ||
                   not (hd_is "IN" (rand w)) then ALL_TAC else
                (REWRITE_TAC[IN_IMAGE] THEN
                 STRIP_TAC THEN
                 W(fun gl ->
                   let inj = the_asm (fun c -> hd_is "INJ" c &&
                               hd_is "fmap_apply"
                                 (el 0 (snd (strip_comb c))) &&
                               not (can (find_term
                                 (hd_is "|+")) c)) gl in
                   let nd = the_asm (fun c -> is_neg c &&
                              hd_is "isSomeDataElement"
                                (rand c)) gl in
                   let eqa = the_asm (fun c -> is_eq c &&
                               hd_is "fmap_apply" (rand c)) gl in
                   let inn = the_asm (fun c -> hd_is "IN" c &&
                               hd_is "FDOM" (rand c)) gl in
                   POP_ASSUM_LIST (K ALL_TAC) THEN
                   MP_TAC (REWRITE_RULE[INJ; IN_ELIM_THM] inj) THEN
                   MP_TAC nd THEN MP_TAC eqa THEN MP_TAC inn THEN
                   MESON_TAC[]))) THEN
              (* and the element is the block, with the values that
                 the stack gave it *)
              W(fun (asl,w as gl) ->
                let hl = the_asm (fun c -> is_eq c &&
                           hd_is "heap_lookup" (lhand c) &&
                           hd_is "SOME" (rand c) &&
                           hd_is "BlockRep" (rand (rand c))) gl in
                let ys1 = el 1 (snd (strip_comb
                            (rand (rand (concl hl))))) in
                let old = the_asm (fun c -> hd_is "ALL2" c &&
                            el 2 (snd (strip_comb c)) = ys1) gl in
                let sw = CONV_RULE(TOP_DEPTH_CONV BETA_CONV)
                           (MATCH_MP EVERY2_SWAP old) in
                EXISTS_TAC ys1 THEN
                CONJ_TAC THENL
                 [ACCEPT_TAC hl;
                  MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc
                    (CONJ (a_vtr gl) sw))]))) THEN
       W(fun (asl,w) ->
         let n = el 1 (snd (strip_comb w)) in
         let ins = find_term (hd_is "sptree_insert") w in
         if n = el 0 (snd (strip_comb ins)) then ALL_TAC else
       (* and a reference that the old stack reached: it is in the
          domain of the map that the block was not put into *)
       (W(fun (asl,w as gl) ->
                let n = el 1 (snd (strip_comb w)) in
                let innu = the_asm (fun c -> hd_is "IN" c &&
                             hd_is "FDOM" (rand c) &&
                             el 0 (snd (strip_comb c)) = n) gl in
                let fm = lhand (rand (rand (concl innu))) in
                SUBGOAL_THEN (list_mk_icomb "IN"
                                [n; list_mk_icomb "FDOM" [fm]])
                  ASSUME_TAC THENL
                 [MP_TAC innu THEN
                  REWRITE_TAC[FDOM_FUPDATE; IN_INSERT] THEN
                  ASM_MESON_TAC[];
                  ALL_TAC]) THEN
        W(fun (asl,w as gl) ->
                let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                           hd_is "sptree_insert"
                             (el 1 (snd (strip_comb c)))) gl in
                let neq = the_asm (fun c -> is_neg c &&
                            is_eq (rand c)) gl in
                let nd = the_asm (fun c -> is_neg c &&
                           hd_is "IN" (rand c) &&
                           hd_is "domain" (rand (rand c))) gl in
                ASSUME_TAC (MATCH_MP
                  (REWRITE_RULE[APPEND_ASSOC] reachable_refs_MutCons)
                  (CONJ rr (CONJ neq nd)))) THEN
              W(fun (asl,w as gl) ->
                let n = el 1 (snd (strip_comb w)) in
                let bri = the_asm (fun c ->
                  let vs,bd = strip_forall c in
                  length vs = 1 && is_imp bd &&
                  hd_is "bc_ref_inv" (rand bd)) gl in
                let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                  not (hd_is "sptree_insert"
                         (el 1 (snd (strip_comb c))))) gl in
                let nin = the_asm (fun c -> hd_is "IN" c &&
                  hd_is "FDOM" (rand c) &&
                  el 0 (snd (strip_comb c)) = n &&
                  not (can (find_term (hd_is "|+")) c)) gl in
                let inv = MP (SPEC n bri) (CONJ rr nin) in
                let neq = the_asm (fun c -> is_neg c &&
                            is_eq (rand c) &&
                            lhand (rand c) = n) gl in
                let hsr = the_asm (hd_is "heap_store_rel") gl in
                let inn = the_asm (fun c -> hd_is "IN" c &&
                            hd_is "FDOM" (rand c) &&
                            el 0 (snd (strip_comb c)) = n &&
                            not (can (find_term (hd_is "|+")) c)) gl in
                (MATCH_MP_TAC (REWRITE_RULE[IMP_IMP]
                   (MATCH_MP (MATCH_MP (MATCH_MP (MATCH_MP
                     (REWRITE_RULE[IMP_CONJ] bc_ref_inv_step)
                     (a_vtr gl)) inn) hsr) inv)) THEN
                 REPEAT CONJ_TAC THEN
                 TRY (SOLVED
                       (ACCEPT_TAC (MATCH_MP (a_ltr gl) neq))) THEN
                 TRY (SOLVED (ACCEPT_TAC (a_dtr gl))) THEN
                 TRY (SOLVED (MESON_TAC[])) THEN
                 ASM_REWRITE_TAC[FLOOKUP_UPDATE])))))) THEN
    ALL_TAC));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let mutcons_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ stack) refs (roots,heap,be,a,sp,sp1,gens)
  limit ts /\
     LENGTH xs < sp /\ index < LENGTH xs /\ ~(ptr IN domain refs)
       /\
     (!gs. ~(data_to_word_config_gc_kind conf =
       data_to_word_Generational gs)) ==>
     (?rs roots2 heap2.
       (roots = rs ++ roots2) /\ (LENGTH rs = LENGTH xs) /\
       (heap_store_unused_alt a (sp + sp1) (BlockRep tag rs) heap =
         (heap2,T)) /\
       abs_ml_inv conf (RefPtr F ptr :: stack)
         (insert ptr (bvlSem_MutBlock tag F (TAKE index xs) (EL
           index xs)
                              (DROP (index + 1) xs)) refs)
         (gc_shared_Pointer a (wordLang_Word (ptr_bits conf tag
           (LENGTH xs))) :: roots2,
          heap2,be,a + el_length (BlockRep tag rs),
          sp - el_length (BlockRep tag rs),sp1,gens) limit ts)`),
  (* take_el_drop writes the values as the three parts of the
     MutBlock, which is what mutcons_thm_alt is about, and its
     statement with those three parts in is the goal *)
  (
   STRIP_TAC THEN
   FIRST_ASSUM(fun ix ->
     let eq = REWRITE_RULE[APPEND_ASSOC]
                (MATCH_MP take_el_drop ix) in
     W(fun (asl,w) ->
       let hd_is n t = (try fst(dest_const(fst(strip_comb t))) = n
                        with Failure _ -> false) in
       let alt = mutcons_thm_alt in
       let fv n = find_term
         (fun t -> is_var t && fst(dest_var t) = n) (concl alt) in
       let args = snd(strip_comb
         (find_term (hd_is "bvlSem_MutBlock") w)) in
       let alt = REWRITE_RULE[APPEND_ASSOC; eq]
         (INST [el 2 args, fv "l"; el 3 args, fv "c";
                el 4 args, fv "r"] alt) in
       (* the statement of the theorem and the statement of the goal
          invented type variables of their own, so the one is
          instantiated at the other: with the three parts in, the two
          conclusions are the same term but for those variables *)
       MP_TAC(INSTANTIATE (term_match [] (rand (concl alt)) w)
                alt))) THEN
   ASM_REWRITE_TAC[] THEN TRY(DISCH_THEN ACCEPT_TAC)));;

let heap_store_ThunkBlock_thm = prove
 (`!ha.
     (heap_store (heap_length ha) [ThunkBlock ev1 v1] (ha ++
       (ThunkBlock ev2 v2 :: hb)) =
     (ha ++ (ThunkBlock ev1 v1 :: hb),T))`,
  (* a ThunkBlock is one element long whatever it holds, so the
     store leaves the lengths to agree *)
  (let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   GEN_TAC THEN
   REWRITE_TAC[heap_store_lemma; APPEND; PAIR_EQ; hlen_cl;
               ThunkBlock_def; el_length_def] THEN
   ARITH_TAC));;

(* [local] *)
let heap_lookup_ThunkBlock_lemma = prove
 (`(heap_lookup n (ha ++ (ThunkBlock ev v :: hb)) = SOME x) =
       (if n < heap_length ha then
         (heap_lookup n ha = SOME x) else if n = heap_length ha then
         (x = ThunkBlock ev v) else if heap_length ha + 2 <= n then
         (heap_lookup (n - heap_length ha - 2) hb = SOME x) else F)`,
  (* and a ThunkBlock is two long *)
  (REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND;
               heap_lookup_def; ThunkBlock_def;
               el_length_def] THEN
   REPEAT COND_CASES_TAC THEN
   ASM_REWRITE_TAC[injectivity "option"; distinctness "option"] THEN
   TRY(POP_ASSUM_LIST(fun ths ->
     MP_TAC(end_itlist CONJ (rev ths))) THEN ARITH_TAC) THEN
   TRY(MATCH_ACCEPT_TAC EQ_SYM_EQ) THEN
   REWRITE_TAC[]));;

(* [local] *)
let heap_store_ThunkBlock = prove
 (`(heap_lookup n heap = SOME (ThunkBlock NotEvaluated y)) ==>
   (?heap2.
     heap_store n [ThunkBlock ev h] heap = (heap2,T) /\
     (heap_lookup n heap2 = SOME (ThunkBlock ev h)) /\
     (heap_length heap2 = heap_length heap) /\
     (FILTER isForwardPointer heap2 = FILTER isForwardPointer heap)
       /\
     (!xs l d.
        MEM (DataElement xs l d) heap2 ==>
          (DataElement xs l d = ThunkBlock ev h) \/
          MEM (DataElement xs l d) heap) /\
     (!a. isSomeDataElement (heap_lookup a heap2) =
          isSomeDataElement (heap_lookup a heap)) /\
     (!m x. ~(m = n) /\ (heap_lookup m heap = SOME x) ==>
           (heap_lookup m heap2 = SOME x)))`,
  (* a store into a ThunkBlock: as the store into a BlockRep,
     where the lengths need no hypothesis, because a ThunkBlock
     holds one value whatever its tag says *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    (* the clauses of heap_length *)
    let hlen_cl = prove
     (`heap_length [] = 0 /\
       (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
      REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
  DISCH_TAC THEN
    FIRST_ASSUM(fun hl ->
      MP_TAC(MATCH_MP heap_lookup_SPLIT hl)) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "APPEND" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "heap_length" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    W(fun (asl,w) ->
      let hs = find_term (hd_is "heap_store") (snd(strip_exists w)) in
      let args = snd(strip_comb hs) in
      let nb = lhand (el 1 args) in
      let hp = el 2 args in
      let ap = rator (rator hp) in
      let rest = rand hp in
      let cs = rator (rator rest) in
      EXISTS_TAC (mk_comb(mk_comb(ap,lhand hp),
                          mk_comb(mk_comb(cs,nb),rand rest)))) THEN
    CONJ_TAC THENL
     [MATCH_ACCEPT_TAC heap_store_ThunkBlock_thm;
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_lookup_ThunkBlock_lemma; LT_REFL];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_length_APPEND; hlen_cl;
                  ThunkBlock_def; el_length_def] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[FILTER_APPEND; FILTER; isForwardPointer_def;
                  ThunkBlock_def] THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[MEM_APPEND; MEM] THEN MESON_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [GEN_TAC THEN
      REWRITE_TAC[isSomeDataElement_def] THEN
      REWRITE_TAC[heap_lookup_ThunkBlock_lemma] THEN
      ASM_REWRITE_TAC[] THEN
      REPEAT COND_CASES_TAC THEN
      REWRITE_TAC[ThunkBlock_def] THEN MESON_TAC[];
      ALL_TAC] THEN
    REPEAT GEN_TAC THEN
    REWRITE_TAC[heap_lookup_ThunkBlock_lemma] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]));;

let INJ_NEQ = prove
 (`INJ (FAPPLY f) (FDOM f) {a | isSomeDataElement (heap_lookup a heap)}
  /\
   n IN FDOM f /\
   ptr IN FDOM f /\ ~(n = ptr) ==> ~((FAPPLY f n) = (FAPPLY f ptr))`,
  (REWRITE_TAC[INJ] THEN REPEAT STRIP_TAC THEN ASM_MESON_TAC[]));;

(* [local] *)
let v_inv_Thunk_insert_lemma = prove
 (`!ck v1 refs x f tf heap ptr v y q.
     v_inv conf v1 refs (x,f,tf,heap) /\
     INJ (FAPPLY f) (FDOM f) {a | isSomeDataElement (heap_lookup a
       heap)} /\
     ptr IN FDOM f /\
     lookup ptr refs = SOME (Thunk NotEvaluated v) /\
     heap_lookup (FAPPLY f ptr) heap = SOME (ThunkBlock NotEvaluated
       y) /\
     v_inv conf v refs (y,f,tf,heap) /\
     (ev = Evaluated ==> dest_thunk h refs = NotThunk) /\
     heap_store (FAPPLY f ptr) [ThunkBlock ev q] heap = (heap2,T) /\
     heap_lookup (FAPPLY f ptr) heap2 = SOME (ThunkBlock ev q) /\
     (!m x. ~(m = FAPPLY f ptr) /\ heap_lookup m heap = SOME x ==>
        heap_lookup m heap2 = SOME x) /\
     v_inv conf h refs (q,f,tf,heap) ==>
       v_inv_ck ck conf v1 (insert ptr (Thunk ev h) refs)
         (x,f,tf,heap2)`,
(* the thunk that the store wrote holds the new value, and the
   invariant of a value survives it: the induction is the one that
   the lemmas about a change of the refs share
   (V_INV_REFS_TAC_IH), where the induction hypothesis asks for
   everything the lemma asks and for the v_inv of the value.  Of a
   Number, a Word64 or a Block the element is where it was, because
   the element that the store wrote is a thunk and theirs is not
   (the tags differ), and of a reference there are the three cases
   of v_inv: a plain reference is not the thunk of the insert (that
   one is a thunk already) and the refs say of it what they said; a
   thunk is either the one that the insert changes, whose value is
   the new one and whose element is the one the store wrote, or
   another one, whose element the store left (the map of the
   addresses is one to one, so its address is not the one that was
   written); and a thunk whose value the root is was evaluated,
   which the one of the insert is not.  That a value which is no
   thunk of the refs is none of the new refs is the local lemma *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let rl = v_inv_ck_rules in
  let opt = [distinctness "option"; injectivity "option"] in
  let rfs = [distinctness "bvlSem_ref"; injectivity "bvlSem_ref";
             distinctness "dataSem_dest_thunk_ret"] in
  (* a value that is no thunk of the refs is none of the new refs:
     a reference to the thunk that the insert changes was one
     already *)
  let dtp = prove
   (`!u. dest_thunk u refs = NotThunk /\
         lookup ptr refs = SOME (Thunk NotEvaluated v)
         ==> dest_thunk u (insert ptr (Thunk ev h) refs) =
             NotThunk`,
    GEN_TAC THEN CASES_ON_NAME "u" THEN
    ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
    CONV_TAC (ONCE_DEPTH_CONV MATCH_CONV) THEN
    REWRITE_TAC[] THEN STRIP_TAC THEN
    ASM_CASES_TAC `a1:num = ptr` THEN
    ASM_REWRITE_TAC[lookup_insert] THEN
    (* the thunk that the insert changes was a thunk already *)
    SUBGOAL_THEN `F` CONTR_TAC THEN
    FIRST_X_ASSUM (fun dt ->
      if hd_is "_MATCH" (lhand (concl dt)) then MP_TAC dt
      else fail()) THEN
    ASM_REWRITE_TAC[] THEN
    CONV_TAC (ONCE_DEPTH_CONV MATCH_CONV) THEN
    COND_CASES_TAC THEN REWRITE_TAC(opt @ rfs)) in
  (* the address of another reference is not the one of the thunk
     that the store wrote, because the map of the addresses is one
     to one *)
  let addr_ne =
    W(fun (asl,gl) ->
      let inj = grab asl (fun th -> hd_is "INJ" (concl th)) in
      let fd = CONJUNCT2 (REWRITE_RULE[INJ] inj) in
      let nn = rand (lhand (dest_neg gl)) in
      MP_TAC (SPECL [nn; `ptr:num`] fd) THEN
      ASM_REWRITE_TAC[] THEN CONV_TAC TAUT) in
  (* a lookup of the old heap is one of the new heap, away from
     the thunk that the store wrote: away from it because the
     element there is a thunk and the elements of the cases are
     not *)
  let notp =
    DISCH_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
    FIRST_ASSUM (fun thk ->
      if not (hd_is "ThunkBlock" (rand (rhs (concl thk))))
      then fail() else
      FIRST_ASSUM (fun l ->
        if concl l = concl thk then fail() else
        MP_TAC (TRANS (SYM l) thk))) THEN
    REWRITE_TAC[injectivity "option"; ThunkBlock_def; bignum_def;
                Word64Rep_def; BlockRep_def] THEN
    TRY PAIRARG_TAC THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    TRY COND_CASES_TAC THEN
    REWRITE_TAC[injectivity "heap_element"; PAIR_EQ;
                distinctness "data_to_word_memoryProof_tag"] in
  let hp =
    FIRST_ASSUM (fun pres ->
      MATCH_MP_TAC pres THEN CONJ_TAC THENL
       [notp; FIRST_ASSUM MATCH_ACCEPT_TAC]) in
  (* the induction hypothesis, which asks for the v_inv of the
     value and for everything the lemma asks *)
  let ih_tac =
    W(fun (asl,gl) ->
      let nz = grab asl (fun th ->
        try is_neg (concl th) && is_eq (rand (concl th)) &&
            rhs (rand (concl th)) = `0`
        with Failure _ -> false) in
      let ck = lhs (rand (concl nz)) in
      let lt = MP (SPEC ck (ARITH_RULE
                 `!n. ~(n = 0) ==> n - 1 < n`)) nz in
      let ih = grab asl (fun th ->
        try is_forall (concl th) &&
            hd_is "<" (lhand (body (rand (concl th))))
        with Failure _ -> false) in
      let ih' = MP (SPEC (mk_binop `(-):num->num->num` ck `1`) ih)
                  lt in
      let big = grab asl (fun th -> is_conj (concl th)) in
      FIRST_ASSUM (fun vi ->
        if not (hd_is "v_inv" (concl vi)) then fail() else
        ACCEPT_TAC (MATCH_MP ih' (CONJ vi big)))) in
  (* the lemma's own hypotheses, one by one *)
  let prep =
    FIRST_ASSUM (fun ds ->
      if is_conj (concl ds) then MAP_EVERY ASSUME_TAC (CONJUNCTS ds)
      else fail()) in
  (* a plain reference is not the thunk that the insert changes, so
     the refs say of it what they said *)
  let d5 =
    REPEAT SUBST_LHS_TAC THEN
    W(fun (asl,gl) ->
      let nn = rand (el 2 (snd (strip_comb gl))) in
      let nq = mk_neg (mk_eq (nn, `ptr:num`)) in
      SUBGOAL_THEN nq ASSUME_TAC THENL
       [DISCH_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
        ASM_MESON_TAC[];
        ALL_TAC]) THEN
    W(fun (asl,gl) ->
      let nn = rand (el 2 (snd (strip_comb gl))) in
      let nq = mk_neg (mk_eq (nn, `ptr:num`)) in
      let lkeq = MP (prove (mk_imp (nq,
                    mk_eq (list_mk_icomb "sptree_lookup"
                      [nn; el 3 (snd (strip_comb gl))],
                      list_mk_icomb "sptree_lookup"
                        [nn; `refs:(dataSem_v bvlSem_ref) spt`])),
                    DISCH_TAC THEN REWRITE_TAC[lookup_insert] THEN
                    ASM_REWRITE_TAC[])) (ASSUME nq) in
      SUBST1_TAC (SYM lkeq) THEN
      MATCH_MP_TAC (el 4 rl) THEN
      ASM_REWRITE_TAC[lkeq]) in
  (* the thunk of a reference: the one that the insert changes
     holds the new value, whose v_inv the lemma gives, and another
     one holds what it held, at an address that the store left *)
  let d6 =
    NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
    W(fun (asl,gl) ->
      let nn = rand (el 2 (snd (strip_comb gl))) in
      ASM_CASES_TAC (mk_eq (nn, `ptr:num`))) THEN
    POP_ASSUM (fun pq ->
      if is_neg (concl pq) then ASSUME_TAC pq else
      SUBST_ALL_TAC pq) THENL
     [(* the thunk that the insert changes *)
      FIRST_ASSUM (fun lk ->
        if not (try hd_is "sptree_lookup" (lhs (concl lk)) &&
                    lhand (lhs (concl lk)) = `ptr:num`
                with Failure _ -> false) then fail() else
        FIRST_ASSUM (fun lk2 ->
          if concl lk2 = concl lk then fail() else
          if not (try hd_is "sptree_lookup" (lhs (concl lk2)) &&
                      lhand (lhs (concl lk2)) = `ptr:num`
                  with Failure _ -> false) then fail() else
          MP_TAC (TRANS (SYM lk2) lk))) THEN
      REWRITE_TAC(opt @ rfs) THEN
      DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
        (fun th -> TRY (SUBST_ALL_TAC (SYM th)))) THEN
      MATCH_MP_TAC (el 5 rl) THEN
      W(fun (asl,gl) ->
        (* the element that the store wrote, whose mode is the
           variable of the statement *)
        let hl2 = grab asl (fun th ->
          try hd_is "heap_lookup" (lhs (concl th)) &&
              hd_is "ThunkBlock" (rand (rhs (concl th))) &&
              is_var (el 0 (snd (strip_comb
                (rand (rhs (concl th))))))
          with Failure _ -> false) in
        let tbs = snd (strip_comb (rand (rhs (concl hl2)))) in
        let ins = find_term (hd_is "sptree_insert") gl in
        let thk = el 1 (snd (strip_comb ins)) in
        MAP_EVERY EXISTS_TAC
          [el 0 tbs; rand thk; el 1 tbs]) THEN
      REPEAT CONJ_TAC THENL
       [REWRITE_TAC[lookup_insert];
        DISCH_TAC THEN
        FIRST_ASSUM (fun dt ->
          if not (is_imp (concl dt)) then fail() else
          MATCH_MP_TAC dtp THEN CONJ_TAC THENL
           [MATCH_MP_TAC dt THEN FIRST_ASSUM MATCH_ACCEPT_TAC;
            FIRST_ASSUM MATCH_ACCEPT_TAC]);
        FIRST_ASSUM MATCH_ACCEPT_TAC;
        FIRST_ASSUM MATCH_ACCEPT_TAC;
        DISCH_TAC THEN ih_tac];
      (* another reference, whose element the store left *)
      MATCH_MP_TAC (el 5 rl) THEN
      W(fun (asl,gl) ->
        let lk = grab asl (fun th ->
          try hd_is "sptree_lookup" (lhs (concl th)) &&
              hd_is "bvlSem_Thunk" (rand (rhs (concl th)))
          with Failure _ -> false) in
        let hl = grab asl (fun th ->
          try hd_is "heap_lookup" (lhs (concl th)) &&
              hd_is "ThunkBlock" (rand (rhs (concl th))) &&
              not (rand (lhand (lhs (concl th))) = `ptr:num`)
          with Failure _ -> false) in
        MAP_EVERY EXISTS_TAC
          [lhand (rand (rhs (concl lk)));
           rand (rand (rhs (concl lk)));
           rand (rand (rhs (concl hl)))]) THEN
      REPEAT CONJ_TAC THENL
       [W(fun (asl,gl) ->
          REWRITE_TAC[lookup_insert] THEN
          ASM_REWRITE_TAC[] THEN FIRST_ASSUM MATCH_ACCEPT_TAC);
        DISCH_TAC THEN
        MATCH_MP_TAC dtp THEN CONJ_TAC THENL
         [FIRST_ASSUM (fun dt ->
            if not (is_imp (concl dt)) then fail() else
            MATCH_MP_TAC dt THEN FIRST_ASSUM MATCH_ACCEPT_TAC);
          FIRST_ASSUM MATCH_ACCEPT_TAC];
        FIRST_ASSUM MATCH_ACCEPT_TAC;
        FIRST_ASSUM (fun pres ->
          MATCH_MP_TAC pres THEN CONJ_TAC THENL
           [addr_ne; FIRST_ASSUM MATCH_ACCEPT_TAC]);
        DISCH_TAC THEN ih_tac]] in
  (* and the thunk whose value the root is: it is not the one that
     the insert changes, because that one is not evaluated *)
  let d7 =
    NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
    W(fun (asl,gl) ->
      let nn = rand (el 2 (snd (strip_comb gl))) in
      let nq = mk_neg (mk_eq (nn, `ptr:num`)) in
      SUBGOAL_THEN nq ASSUME_TAC THENL
       [DISCH_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
        FIRST_ASSUM (fun lk ->
          if not (try hd_is "sptree_lookup" (lhs (concl lk)) &&
                      hd_is "bvlSem_Thunk" (rand (rhs (concl lk)))
                  with Failure _ -> false) then fail() else
          FIRST_ASSUM (fun lk2 ->
            if concl lk2 = concl lk then fail() else
            if not (try hd_is "sptree_lookup" (lhs (concl lk2)) &&
                        hd_is "bvlSem_Thunk"
                          (rand (rhs (concl lk2)))
                    with Failure _ -> false) then fail() else
            MP_TAC (TRANS (SYM lk2) lk))) THEN
        REWRITE_TAC(opt @ rfs) THEN
        REWRITE_TAC[distinctness "thunk_mode"];
        ALL_TAC]) THEN
    MATCH_MP_TAC (el 6 rl) THEN
    W(fun (asl,gl) ->
      let lk = grab asl (fun th ->
        try hd_is "sptree_lookup" (lhs (concl th)) &&
            hd_is "bvlSem_Thunk" (rand (rhs (concl th)))
        with Failure _ -> false) in
      EXISTS_TAC (rand (rand (rhs (concl lk))))) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[lookup_insert] THEN
      ASM_REWRITE_TAC[] THEN FIRST_ASSUM MATCH_ACCEPT_TAC;
      MATCH_MP_TAC dtp THEN CONJ_TAC THEN
      FIRST_ASSUM MATCH_ACCEPT_TAC;
      DISCH_TAC THEN ih_tac] in
  V_INV_REFS_TAC_IH ih_tac (FIRST_ASSUM MATCH_ACCEPT_TAC) prep hp
    d5 d6 d7)));;

(* HOL4 data_to_word_memoryProofScript.sml:4636-4640: a theorem that
   HOL4 states as the value of an ML expression: v_inv_Thunk_insert *)

(* [local] *)
let heap_lookup_heap_split = prove
 (`!heap a b h1 h2 x.
     heap_split a heap = SOME (h1,h2) /\
     heap_lookup b heap = SOME x ==>
     (if b < a then MEM x h1 else MEM x h2)`,
  (* the element that a lookup finds is in the half of the split
     that its address falls in: heap_lookup_SPLIT cuts the heap at
     the element, and the split of that append is the one of the
     first part or the one that keeps the element *)
  (let stripconj =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) in
   let aux = prove
    (`!(heap:((A,B)heap_element) list) a b h1 h2 x.
        heap_split a heap = SOME (h1,h2) /\
        heap_lookup b heap = SOME x
        ==> (if b < a then MEM x h1 else MEM x h2)`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     FIRST_X_ASSUM(fun th ->
       if (try fst(dest_const(fst(strip_comb(lhs(concl th))))) =
                "heap_lookup"
           with Failure _ -> false)
       then MP_TAC(MATCH_MP heap_lookup_SPLIT th)
       else fail()) THEN
     DISCH_THEN(X_CHOOSE_THEN `ha:((A,B)heap_element) list`
       (X_CHOOSE_THEN `hb:((A,B)heap_element) list`
         STRIP_ASSUME_TAC)) THEN
     VAR_EQ_TAC THEN
     FIRST_X_ASSUM(fun th ->
       MP_TAC(ONCE_REWRITE_RULE
         [heap_split_APPEND_if] th)) THEN
     COND_CASES_TAC THEN
     REWRITE_TAC[heap_split_def] THEN
     ASM_CASES_TAC
       `a - heap_length (ha:((A,B)heap_element) list) = 0` THEN
     ASM_REWRITE_TAC[] THEN
     ASM_CASES_TAC
       `a - heap_length (ha:((A,B)heap_element) list) <
        el_length (x:(A,B)heap_element)` THEN
     ASM_REWRITE_TAC[distinctness "option"] THEN
     EVERY_CASE_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option";
                 PAIR_EQ] THEN
     STRIP_TAC THEN stripconj THEN VAR_EQ_TAC THEN
     ASM_REWRITE_TAC[MEM_APPEND; MEM] THEN
     TRY(CONV_TAC TAUT) THEN TRY ASM_ARITH_TAC) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let heap_store_heap_lookup = prove
 (`!heap heap2 a x n.
      heap_store a x heap = (heap2,T) /\ n < a ==>
      heap_lookup n heap = heap_lookup n heap2`,
  (* the store leaves the elements before the address it writes at
     where they are, so the lookup below it gives the same *)
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[heap_store_def; PAIR_EQ];
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV o LAND_CONV)
       [heap_store_def] THEN
     COND_CASES_TAC THENL
      [ASM_REWRITE_TAC[ARITH_RULE `((n:num) < 0) <=> F`];
       ALL_TAC] THEN
     COND_CASES_TAC THENL
      [REWRITE_TAC[PAIR_EQ]; ALL_TAC] THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[PAIR_EQ] THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
          (fun th -> SUBST_ALL_TAC(EQT_INTRO th)))
       ASSUME_TAC) THEN
     ONCE_REWRITE_TAC[heap_lookup_def] THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_EXISTS_TAC THEN
     ASM_REWRITE_TAC[] THEN ARITH_ASM_TAC]));;

let update_ref_gen_state_ok = prove
 (`heap_store b [RefBlock t1] heap = (heap2,T) /\ a <= b /\
       gen_state_ok a (a + (sp + sp1)) heap gens ==>
       gen_state_ok a (a + (sp + sp1)) heap2 gens`,
  ((* the head constant of a term, by name, and the assumption
      that a test picks out *)
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* the generations are all below a and the pointers of the part
     below each of them stay where they were: the store is at b,
     which is at or above a, so the split at a generation's start
     gives the same first half (heap_split_heap_store) *)
  STRUCT_CASES_TAC(ISPEC `gens:gen_state`
    (cases_of `:gen_state`)) THEN
  REWRITE_TAC[gen_state_ok_def] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(fun ev ->
    if hd_is "ALL" (concl ev) &&
       hd_is "gen_start_ok" (lhand (concl ev))
    then MP_TAC(REWRITE_RULE[GSYM ALL_MEM] ev) else fail()) THEN
  REWRITE_TAC[GSYM ALL_MEM] THEN
  DISCH_TAC THEN GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(fun ev ->
    FIRST_ASSUM(fun mm -> MP_TAC(MATCH_MP ev mm))) THEN
  REWRITE_TAC[gen_start_ok_def] THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
  W(fun (asl,w) ->
    let ev = grab asl (fun th -> hd_is "ALL" (concl th)) in
    let m  = grab asl (fun th -> hd_is "MEM" (concl th) &&
               rand (concl th) = rand (concl ev)) in
    let ab = grab asl (fun th -> hd_is "<=" (concl th)) in
    let sp = grab asl (fun th ->
               hd_is "heap_split" (lhand (concl th))) in
    let st = grab asl (fun th ->
               hd_is "heap_store" (lhand (concl th))) in
    let xa = BETA_RULE(MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev) m) in
    let xb = MATCH_MP (MATCH_MP (ARITH_RULE
               `(x:num) <= a ==> a <= b ==> x <= b`) xa) ab in
    MP_TAC(MATCH_MP heap_split_heap_store
             (CONJ sp (CONJ st xb)))) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN ASSUME_TAC) THEN
  ASM_MESON_TAC[]));;

(* [local] *)
let data_up_to_alt = prove
 (`(data_up_to n [] <=> (n = 0)) /\
   (data_up_to n (x :: xs) <=>
      (if n = 0 then T else
      if n < el_length x \/ ~(isDataElement x) then F else
        data_up_to (n - el_length x) xs))`,
  (let opt = [injectivity "option"; distinctness "option";
              PAIR_EQ] in
   REWRITE_TAC[data_up_to_def; heap_split_def] THEN
   CONJ_TAC THEN COND_CASES_TAC THEN
   ASM_REWRITE_TAC(ALL :: opt) THENL
    [CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[ALL];
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[ALL];
     COND_CASES_TAC THEN ASM_REWRITE_TAC(ALL :: opt) THEN
     EVERY_CASE_TAC THEN ASM_REWRITE_TAC(ALL :: opt) THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     ASM_REWRITE_TAC(ALL :: opt) THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC[]]));;

let update_thunk_gen_state_ok = prove
 (`heap_store b [ThunkBlock ev t1] heap = (heap2,T) /\ a <= b /\
       gen_state_ok a (a + (sp + sp1)) heap gens ==>
       gen_state_ok a (a + (sp + sp1)) heap2 gens`,
  ((* the head constant of a term, by name, and the assumption
      that a test picks out *)
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* the generations are all below a and the pointers of the part
     below each of them stay where they were: the store is at b,
     which is at or above a, so the split at a generation's start
     gives the same first half (heap_split_heap_store) *)
  STRUCT_CASES_TAC(ISPEC `gens:gen_state`
    (cases_of `:gen_state`)) THEN
  REWRITE_TAC[gen_state_ok_def] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(fun ev ->
    if hd_is "ALL" (concl ev) &&
       hd_is "gen_start_ok" (lhand (concl ev))
    then MP_TAC(REWRITE_RULE[GSYM ALL_MEM] ev) else fail()) THEN
  REWRITE_TAC[GSYM ALL_MEM] THEN
  DISCH_TAC THEN GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(fun ev ->
    FIRST_ASSUM(fun mm -> MP_TAC(MATCH_MP ev mm))) THEN
  REWRITE_TAC[gen_start_ok_def] THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
  W(fun (asl,w) ->
    let ev = grab asl (fun th -> hd_is "ALL" (concl th)) in
    let m  = grab asl (fun th -> hd_is "MEM" (concl th) &&
               rand (concl th) = rand (concl ev)) in
    let ab = grab asl (fun th -> hd_is "<=" (concl th)) in
    let sp = grab asl (fun th ->
               hd_is "heap_split" (lhand (concl th))) in
    let st = grab asl (fun th ->
               hd_is "heap_store" (lhand (concl th))) in
    let xa = BETA_RULE(MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev) m) in
    let xb = MATCH_MP (MATCH_MP (ARITH_RULE
               `(x:num) <= a ==> a <= b ==> x <= b`) xa) ab in
    MP_TAC(MATCH_MP heap_split_heap_store
             (CONJ sp (CONJ st xb)))) THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN ASSUME_TAC) THEN
  ASM_MESON_TAC[]));;

let data_up_to_heap_store = prove
 (`!heap a b heap2 y.
      data_up_to a heap /\ heap_store b [y] heap = (heap2,T) /\
      isDataElement y ==> data_up_to a heap2`,
  (* the store of a data element keeps the elements below the
     address it writes at, and writes a data element where it
     writes, so the heap stays data up to the address it was *)
  (let hl1 = prove
    (`!y:(A,B)heap_element. heap_length [y] = el_length y`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST] THEN
     ARITH_TAC) in
   let dac1 = prove
    (`!a (h:(A,B)heap_element) t.
        data_up_to a (CONS h t) /\ ~(a = 0)
        ==> ~(a < el_length h) /\ isDataElement h /\
            data_up_to (a - el_length h) t`,
     REPEAT GEN_TAC THEN ONCE_REWRITE_TAC[data_up_to_alt] THEN
     COND_CASES_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
     COND_CASES_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
     POP_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[DE_MORGAN_THM]) THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[]) in
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[heap_store_def; PAIR_EQ];
     GEN_REWRITE_TAC
       (LAND_CONV o RAND_CONV o LAND_CONV o LAND_CONV)
       [heap_store_def] THEN
     COND_CASES_TAC THENL
      [REWRITE_TAC[PAIR_EQ; APPEND; hl1] THEN
       DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
         (CONJUNCTS_THEN2
            (CONJUNCTS_THEN2 (SUBST1_TAC o SYM) ASSUME_TAC)
            ASSUME_TAC)) THEN
       ONCE_REWRITE_TAC[data_up_to_alt] THEN
       COND_CASES_TAC THEN REWRITE_TAC[] THEN
       FIRST_ASSUM(fun du -> FIRST_ASSUM(fun ne ->
         MP_TAC(MATCH_MP dac1 (CONJ du ne)))) THEN
       ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     COND_CASES_TAC THENL
      [REWRITE_TAC[PAIR_EQ]; ALL_TAC] THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[PAIR_EQ] THEN
     DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2
          (CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
             (fun th -> SUBST_ALL_TAC(EQT_INTRO th)))
          ASSUME_TAC)) THEN
     ONCE_REWRITE_TAC[data_up_to_alt] THEN
     COND_CASES_TAC THEN REWRITE_TAC[] THEN
     FIRST_ASSUM(fun du -> FIRST_ASSUM(fun ne ->
       MP_TAC(MATCH_MP dac1 (CONJ du ne)))) THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_update_ref = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (xs ++ (RefPtr b ptr :: stack))) ==>
       blocks_unique ts
         (all_vs (insert ptr (ValueArray xs) refs)
            (xs ++ (RefPtr b ptr :: stack)))`),
  (* the ValueArray that the pointer is given holds the values that
     the stack has in front of it *)
  (let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let inc = prove
    (`!refs ptr xs b stack' t a q.
        Block t a q IN
          all_vs (insert ptr (ValueArray xs) refs)
                 (APPEND xs (CONS (RefPtr b ptr) stack')) ==>
        Block t a q IN
          all_vs refs (APPEND xs (CONS (RefPtr b ptr) stack'))`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM;
                 v_all_vs_append; MEM_APPEND; li;
                 distinctness "bvlSem_ref";
                 injectivity "bvlSem_ref"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: the steps that the proofs of update_ref_thm and
   of the four update theorems after it take.  A store into the
   element of a reference leaves the heap as good as it was
   (heap_ok_store_el, unused_store_el, roots_ok_iso,
   heap_split_store_ref, gc_kind_store_ref), and an update of the
   references that leaves what the invariant says of every value
   (the three transfers of VA_trans) leaves the invariant of every
   reference that it did not write (bc_ref_inv_update_gen over the
   four arms of bc_ref_inv, with the INJ of f to tell the two
   addresses apart).  The lemmas with gen in the name take the
   transfers as hypotheses, so that the update of a thunk and the
   one of a mutable block can take the same steps *)

(* the rewrites that decide a guard whose pattern is a reference
   (PORTING-GUIDE.md entry 45) *)
let ref_rws =
  let ds = CONJUNCTS (distinctness "bvlSem_ref") in
  injectivity "option" :: distinctness "option" ::
  injectivity "bvlSem_ref" :: ds @ map GSYM ds;;

let reach_refptr = prove
 (cake_as_vars (fun () ->
    `MEM (RefPtr b ptr) stack' ==> reachable_refs stack' refs ptr`),
  REWRITE_TAC[reachable_refs_def] THEN STRIP_TAC THEN
  EXISTS_TAC (cake_as_vars (fun () -> `RefPtr b ptr:dataSem_v`)) THEN
  EXISTS_TAC `ptr:num` THEN
  ASM_REWRITE_TAC[get_refs_def; MEM] THEN
  MESON_TAC[RTC_RULES]);;

let roots_ok_iso = prove
 (`roots_ok roots heap /\
   (!a. isSomeDataElement (heap_lookup a heap2) =
        isSomeDataElement (heap_lookup a heap))
   ==> roots_ok roots heap2`,
  REWRITE_TAC[roots_ok_def] THEN STRIP_TAC THEN
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

(* the heap after a store of any element whose pointers are
   addresses of the heap *)
let heap_ok_store_el = prove
 (`heap_ok heap limit' /\
   (!ptr u. MEM (gc_shared_Pointer ptr u) ws
            ==> isSomeDataElement (heap_lookup ptr heap)) /\
   (!a. isSomeDataElement (heap_lookup a heap2) =
        isSomeDataElement (heap_lookup a heap)) /\
   heap_length heap2 = heap_length heap /\
   FILTER isForwardPointer heap2 = FILTER isForwardPointer heap /\
   (!xs l d. MEM (DataElement xs l d) heap2
             ==> (DataElement xs l d = DataElement ws l2 d2) \/
                 MEM (DataElement xs l d) heap)
   ==> heap_ok heap2 limit'`,
  REWRITE_TAC[heap_ok_def] THEN STRIP_TAC THEN
  SPLIT_ASM_TAC THEN
  REPEAT CONJ_TAC THEN TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  W(fun gl ->
    let mm = the_asm (fun c ->
      let bd = snd (strip_forall c) in
      is_imp bd && is_disj (rand bd)) gl in
    let mh = the_asm (fun c -> hd_is "MEM" c &&
      hd_is "DataElement" (el 0 (snd (strip_comb c)))) gl in
    STRIP_ASSUME_TAC (MATCH_MP (SPEC_ALL mm) mh)) THENL
   [(* the element written: its pointers are addresses of their own *)
    RULE_ASSUM_TRY (REWRITE_RULE[injectivity "heap_element"]) THEN
    SPLIT_ASM_TAC THEN
    REPEAT (FIRST_X_ASSUM (fun e ->
      let c = concl e in
      if not (is_eq c) || not (is_var (lhand c)) then fail() else
      SUBST_ALL_TAC e)) THEN
    W(fun gl ->
      let m = the_asm (fun c -> hd_is "MEM" c &&
        hd_is "gc_shared_Pointer" (el 0 (snd (strip_comb c)))) gl in
      let pw = the_asm (fun c ->
        let vs,bd = strip_forall c in
        length vs = 2 && is_imp bd &&
        hd_is "isSomeDataElement" (rand bd)) gl in
      ACCEPT_TAC (MATCH_MP pw m));
    (* an old element of a heap that was good *)
    W(fun gl ->
      let ho = the_asm (fun c ->
        length (fst (strip_forall c)) = 5) gl in
      let md = the_asm (fun c -> hd_is "MEM" c &&
        hd_is "DataElement" (el 0 (snd (strip_comb c)))) gl in
      let mp = the_asm (fun c -> hd_is "MEM" c &&
        hd_is "gc_shared_Pointer" (el 0 (snd (strip_comb c)))) gl in
      ACCEPT_TAC (MATCH_MP ho (CONJ md mp)))]);;

(* and so the one for a store of a RefBlock *)
let heap_ok_store_ws = prove
 (`heap_ok heap limit' /\
   (!ptr u. MEM (gc_shared_Pointer ptr u) ws
            ==> isSomeDataElement (heap_lookup ptr heap)) /\
   (!a. isSomeDataElement (heap_lookup a heap2) =
        isSomeDataElement (heap_lookup a heap)) /\
   heap_length heap2 = heap_length heap /\
   FILTER isForwardPointer heap2 = FILTER isForwardPointer heap /\
   (!xs l d. MEM (DataElement xs l d) heap2
             ==> (DataElement xs l d = RefBlock ws) \/
                 MEM (DataElement xs l d) heap)
   ==> heap_ok heap2 limit'`,
  REWRITE_TAC[RefBlock_def] THEN MATCH_ACCEPT_TAC heap_ok_store_el);;

(* and so the heap after a store of the roots of the new values,
   whose pointers are addresses because the roots are good *)

let heap_ok_store_ref = prove
 (`heap_ok heap limit' /\ roots_ok (rs ++ (r :: roots2)) heap /\
   (!a. isSomeDataElement (heap_lookup a heap2) =
        isSomeDataElement (heap_lookup a heap)) /\
   heap_length heap2 = heap_length heap /\
   FILTER isForwardPointer heap2 = FILTER isForwardPointer heap /\
   (!xs l d. MEM (DataElement xs l d) heap2
             ==> (DataElement xs l d = RefBlock rs) \/
                 MEM (DataElement xs l d) heap)
   ==> heap_ok heap2 limit'`,
  STRIP_TAC THEN
  W(fun gl ->
    let ho = the_asm (hd_is "heap_ok") gl in
    let ro = REWRITE_RULE[roots_ok_def]
               (the_asm (hd_is "roots_ok") gl) in
    let rs = lhand (el 0 (snd (strip_comb
               (concl (the_asm (hd_is "roots_ok") gl))))) in
    let iso = the_asm (fun c ->
      let vs,bd = strip_forall c in
      length vs = 1 && is_eq bd) gl in
    let hlen = the_asm (fun c -> is_eq c &&
                 hd_is "heap_length" (lhand c)) gl in
    let flt = the_asm (fun c -> is_eq c &&
                hd_is "FILTER" (lhand c)) gl in
    let mm = the_asm (fun c ->
      let bd = snd (strip_forall c) in
      is_imp bd && is_disj (rand bd)) gl in
    let vs,bd = strip_forall (concl ro) in
    let pw = list_mk_forall(vs,
               mk_imp(list_mk_icomb "MEM" [lhand (lhand bd); rs],
                      rand bd)) in
    SUBGOAL_THEN pw (fun pwt ->
      ACCEPT_TAC (MATCH_MP heap_ok_store_ws
        (CONJ ho (CONJ pwt (CONJ iso (CONJ hlen (CONJ flt mm))))))) THEN
    MP_TAC ro THEN POP_ASSUM_LIST (K ALL_TAC) THEN
    REWRITE_TAC[MEM_APPEND] THEN MESON_TAC[]));;

(* the unused space after a store of a data element where a data
   element was: the unused one is not a data element, so it is not
   the one written and the store left it where it was *)
let unused_store_el = prove
 (`unused_space_inv a l heap /\
   heap_length heap2 = heap_length heap /\
   heap_lookup p heap = SOME el1 /\ isDataElement el1 /\
   isDataElement el2 /\
   (!m x. ~(m = p) /\ heap_lookup m heap = SOME x
          ==> heap_lookup m heap2 = SOME x) /\
   heap_store p [el2] heap = (heap2,T)
   ==> unused_space_inv a l heap2`,
  REWRITE_TAC[unused_space_inv_def] THEN STRIP_TAC THEN
  SPLIT_ASM_TAC THEN
  REPEAT CONJ_TAC THEN TRY (SOLVED (ASM_REWRITE_TAC[])) THENL
   [(* the unused element is not the one written, so the store left
        it where it was *)
    DISCH_TAC THEN
    W(fun (asl,w as gl) ->
      let nz = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                 rand (rand c) = `0`) gl in
      let impl = the_asm (fun c -> is_imp c && is_eq (rand c) &&
                   (try hd_is "heap_lookup" (lhand (rand c))
                    with Failure _ -> false)) gl in
      let lk = MP impl nz in
      let tr = the_asm (fun c ->
                 length (fst (strip_forall c)) = 2) gl in
      let hl1 = the_asm (fun c -> is_eq c &&
                  hd_is "heap_lookup" (lhand c) &&
                  hd_is "SOME" (rand c)) gl in
      let isd = the_asm (fun c -> hd_is "isDataElement" c &&
                  rand c = rand (rand (concl hl1))) gl in
      let a = el 0 (snd (strip_comb (lhand (concl lk)))) in
      let p = el 0 (snd (strip_comb (lhand (concl hl1)))) in
      SUBGOAL_THEN (mk_neg (mk_eq (a,p)))
        (fun ne -> ACCEPT_TAC (MATCH_MP tr (CONJ ne lk))) THEN
      POP_ASSUM_LIST (K ALL_TAC) THEN
      MP_TAC isd THEN MP_TAC hl1 THEN MP_TAC lk THEN
      REWRITE_TAC[isDataElement_def] THEN
      MESON_TAC[injectivity "option"; distinctness "heap_element"]);
    (* and the data below it is still data *)
    W(fun gl ->
      let du = the_asm (hd_is "data_up_to") gl in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let el2 = lhand (el 1 (snd (strip_comb (lhand (concl st))))) in
      let isd = the_asm (fun c -> hd_is "isDataElement" c &&
                  rand c = el2) gl in
      ACCEPT_TAC (MATCH_MP data_up_to_heap_store
        (CONJ du (CONJ st isd))))]);;

let unused_store_ref = prove
 (`unused_space_inv a l heap /\ RefBlock_inv heap heap2 /\
   heap_length heap2 = heap_length heap /\
   heap_store p [RefBlock rs] heap = (heap2,T)
   ==> unused_space_inv a l heap2`,
  REWRITE_TAC[unused_space_inv_def] THEN STRIP_TAC THEN
  SPLIT_ASM_TAC THEN
  REPEAT CONJ_TAC THEN TRY (SOLVED (ASM_REWRITE_TAC[])) THENL
   [(* the unused element is not a reference, so it is still there *)
    DISCH_TAC THEN
    FIRST_X_ASSUM (fun ri ->
      if not (hd_is "RefBlock_inv" (concl ri)) then fail() else
      MATCH_MP_TAC (CONJUNCT1 (REWRITE_RULE[RefBlock_inv_def] ri))) THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[isRefBlock_def; RefBlock_def] THEN
      REWRITE_TAC[distinctness "heap_element"] THEN MESON_TAC[]];
    (* and the data before it is still data *)
    W(fun gl ->
      let du = the_asm (hd_is "data_up_to") gl in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let y = lhand (el 1 (snd (strip_comb (lhand (concl st))))) in
      SUBGOAL_THEN (list_mk_icomb "isDataElement" [y])
        (fun isd -> ACCEPT_TAC (MATCH_MP data_up_to_heap_store
          (CONJ du (CONJ st isd)))) THEN
      REWRITE_TAC[isDataElement_def; RefBlock_def] THEN
      MESON_TAC[])]);;

let DRESTRICT_DEF = prove
 (`!(fm:(A,B)fmap) s.
     FDOM (DRESTRICT fm s) = FDOM fm INTER s /\
     (!x. x IN s ==> FAPPLY (DRESTRICT fm s) x = FAPPLY fm x)`,
  REPEAT GEN_TAC THEN CONJ_TAC THENL
   [REWRITE_TAC[FDOM; FMAP_FN_DRESTRICT; EXTENSION; IN_INTER;
                IN_ELIM_THM] THEN
    GEN_TAC THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[];
    REPEAT STRIP_TAC THEN
    REWRITE_TAC[fmap_apply; FMAP_FN_DRESTRICT] THEN
    ASM_REWRITE_TAC[]]);;

let INJ_SUBSET_DOM = prove
 (`!(g:A->B) s t u. INJ g s u /\ t SUBSET s ==> INJ g t u`,
  REWRITE_TAC[INJ; SUBSET] THEN MESON_TAC[]);;

let INJ_DRESTRICT = prove
 (`!(tf:(A,B)fmap) s P.
     INJ (FAPPLY tf) (FDOM tf) s
     ==> INJ (FAPPLY (DRESTRICT tf P)) (FDOM (DRESTRICT tf P)) s`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[INJ; (CONJUNCT1 o SPEC_ALL) DRESTRICT_DEF;
              IN_INTER] THEN
  STRIP_TAC THEN CONJ_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_SIMP_TAC[(CONJUNCT2 o SPEC_ALL) DRESTRICT_DEF] THEN
  ASM_MESON_TAC[(CONJUNCT2 o SPEC_ALL) DRESTRICT_DEF]);;

let mem_zip_left = prove
 (`!(l1:A list) (l2:B list) x y.
     LENGTH l1 = LENGTH l2 /\ MEM (x,y) (ZIP l1 l2) ==> MEM x l1`,
  LIST_INDUCT_TAC THEN X_GEN_TAC `l2:B list` THEN
  STRUCT_CASES_TAC(ISPEC `l2:B list` (cases_of `:(B)list`)) THEN
  REWRITE_TAC[ZIP; MEM; PAIR_EQ; LENGTH; NOT_SUC;
              ARITH_RULE `~(0 = SUC n)`; SUC_INJ] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

let mem_zip_right = prove
 (`!(l1:A list) (l2:B list) x y.
     LENGTH l1 = LENGTH l2 /\ MEM (x,y) (ZIP l1 l2) ==> MEM y l2`,
  LIST_INDUCT_TAC THEN X_GEN_TAC `l2:B list` THEN
  STRUCT_CASES_TAC(ISPEC `l2:B list` (cases_of `:(B)list`)) THEN
  REWRITE_TAC[ZIP; MEM; PAIR_EQ; LENGTH; NOT_SUC;
              ARITH_RULE `~(0 = SUC n)`; SUC_INJ] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

let MEM_ref_all_vs = prove
 (cake_as_vars (fun () ->
    `sptree_lookup n refs = SOME (bvlSem_ValueArray l) /\ MEM v l
     ==> v IN all_vs refs stack'`),
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  REPEAT DISJ1_TAC THEN
  EXISTS_TAC `n:num` THEN
  EXISTS_TAC (cake_as_vars (fun () -> `l:(dataSem_v)list`)) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MEM_v_all_vs THEN FIRST_ASSUM ACCEPT_TAC);;

(* the halves of the split after a store above the first one: the
   second half is the old one with the element replaced, so it is
   still all references (HOL4 does this inline, with
   heap_split_length of gen_gc_partialTheory) *)

let heap_split_store_ref = prove
 (`heap_split k heap = SOME (h1,h2) /\
   heap_lookup p heap = SOME (RefBlock zs) /\
   ~(p < k) /\ LENGTH rs = LENGTH zs /\
   heap_store p [RefBlock rs] heap = (heap2,T) /\
   EVERY isRef h2
   ==> (?h3. heap_split k heap2 = SOME (h1,h3) /\ EVERY isRef h3)`,
  STRIP_TAC THEN
  (* the heap is its two halves, and the first is of the length *)
  FIRST_ASSUM (fun hs ->
    if not (is_eq (concl hs)) ||
       not (hd_is "heap_split" (lhand (concl hs))) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_split_heap_length hs)) THEN
  FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (hd_is "APPEND" (lhand c)) ||
       not (is_var (rand c)) then fail() else
    SUBST_ALL_TAC (SYM e)) THEN
  (* so the element written is in the second half *)
  FIRST_X_ASSUM (fun hl ->
    let c = concl hl in
    if not (is_eq c) || not (hd_is "heap_lookup" (lhand c))
    then fail() else
    ASSUME_TAC (REWRITE_RULE[heap_lookup_APPEND] hl)) THEN
  ASM_FS_TAC THEN
  (* and the second half splits there *)
  W(fun gl ->
    let hl2 = the_asm (fun c -> is_eq c &&
                hd_is "heap_lookup" (lhand c) &&
                hd_is "SOME" (rand c)) gl in
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl2)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (lhand c)) then fail() else
    SUBST_ALL_TAC e)) THEN
  (* the address written is the length of what lies before it *)
  W(fun gl ->
    let e = the_asm (fun c -> is_eq c &&
              hd_is "-" (lhand c) &&
              hd_is "heap_length" (rand c)) gl in
    let ha = rand (rand (concl e)) in
    let hl1 = the_asm (fun c -> is_eq c &&
                hd_is "heap_length" (lhand c) &&
                not (hd_is "APPEND" (rand (lhand c)))) gl in
    let h1 = rand (lhand (concl hl1)) in
    let p = lhand (lhand (concl e)) in
    SUBGOAL_THEN (mk_eq (p, list_mk_icomb "heap_length"
                              [list_mk_icomb "APPEND" [h1; ha]]))
      ASSUME_TAC THENL
     [REWRITE_TAC[heap_length_APPEND] THEN ASM_ARITH_TAC;
      ALL_TAC]) THEN
  FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (lhand c)) ||
       not (hd_is "heap_length" (rand c)) then fail() else
    SUBST_ALL_TAC e) THEN
  (* so the store writes the new element in the middle *)
  RULE_ASSUM_TRY (REWRITE_RULE[APPEND_ASSOC]) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[heap_store_lemma; PAIR_EQ]) THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (rand c)) ||
       not (hd_is "APPEND" (lhand c)) then fail() else
    SUBST_ALL_TAC (SYM e))) THEN
  (* so the split of the new heap keeps the first half *)
  REWRITE_TAC[GSYM APPEND_ASSOC] THEN
  W(fun gl ->
    let e = the_asm (fun c -> is_eq c &&
              hd_is "heap_length" (lhand c) &&
              is_var (rand (lhand c)) && is_var (rand c)) gl in
    ONCE_REWRITE_TAC[SYM e]) THEN
  REWRITE_TAC[heap_split_length] THEN
  W(fun (asl,w) ->
    let bod = snd (strip_exists w) in
    let sm = rand (lhand (hd (conjuncts bod))) in
    EXISTS_TAC (rand sm)) THEN
  REWRITE_TAC[] THEN
  (* and the second half is the old one with the new element *)
  RULE_ASSUM_TRY (REWRITE_RULE[ALL_APPEND; ALL]) THEN
  REWRITE_TAC[ALL_APPEND; ALL] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[isRef_def; RefBlock_def] THEN
  MATCH_REDUCE_TAC THEN
  REWRITE_TAC[isMutTag_def]);;

(* and so the kind of the collection survives the store *)

let gc_kind_store_ref = prove
 (cake_as_vars (fun () ->
    `gc_kind_inv conf a sp sp1 gens heap /\
     heap_store p [RefBlock rs] heap = (heap2,T) /\
     heap_lookup p heap = SOME (RefBlock zs) /\
     LENGTH rs = LENGTH zs
     ==> gc_kind_inv conf a sp sp1 gens heap2`),
  REWRITE_TAC[gc_kind_inv_def] THEN STRIP_TAC THEN
  W(fun (asl,w) ->
    CASES_ON_TAC (find_term
      (hd_is "data_to_word_config_gc_kind") w)) THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
  MATCH_REDUCE_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  SPLIT_ASM_TAC THEN
  FIRST_X_ASSUM (fun ex ->
    if not (is_exists (concl ex)) then fail() else
    STRIP_ASSUME_TAC ex) THEN
  (* a RefBlock is a reference, so the element written is not in
     the half of the split that holds none *)
  W(fun (asl,w as gl) ->
    let hs = the_asm (fun c -> is_eq c &&
               hd_is "heap_split" (lhand c)) gl in
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    let k = el 0 (snd (strip_comb (lhand (concl hs)))) in
    let p = el 0 (snd (strip_comb (lhand (concl hl)))) in
    SUBGOAL_THEN (mk_neg (mk_binop `(<):num->num->bool` p k))
      ASSUME_TAC THENL
     [DISCH_TAC THEN
      MP_TAC (MATCH_MP heap_lookup_heap_split (CONJ hs hl)) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      W(fun (asl,w as gl) ->
        let m = the_asm (hd_is "MEM") gl in
        let ev = the_asm (fun c -> hd_is "ALL" c &&
                   el 1 (snd (strip_comb c)) = rand (concl m)) gl in
        MP_TAC (MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev) m)) THEN
      REWRITE_TAC[isRef_def; RefBlock_def] THEN
      MATCH_REDUCE_TAC THEN
      REWRITE_TAC[isMutTag_def];
      ALL_TAC]) THEN
  CONJ_TAC THENL
   [(* the generation state: the store is above the nursery *)
    W(fun gl ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let gs = the_asm (hd_is "gen_state_ok") gl in
      let p = el 0 (snd (strip_comb (lhand (concl st)))) in
      let a = el 0 (snd (strip_comb (concl gs))) in
      SUBGOAL_THEN (mk_binop `(<=):num->num->bool` a p)
        (fun le -> MATCH_ACCEPT_TAC
          (MATCH_MP update_ref_gen_state_ok
            (CONJ st (CONJ le gs)))) THEN
      POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (filter
        (fun t -> let c = concl t in
           hd_is "<" c || (is_neg c && hd_is "<" (rand c)) ||
           hd_is "<=" c) l)) THEN
      ASM_ARITH_TAC);
    (* and the two halves of the new heap *)
    W(fun gl ->
      let hs = the_asm (fun c -> is_eq c &&
                 hd_is "heap_split" (lhand c)) gl in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c)) gl in
      let nlt = the_asm (fun c -> is_neg c && hd_is "<" (rand c)) gl in
      let len = the_asm (fun c -> is_eq c &&
                  hd_is "LENGTH" (lhand c)) gl in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let h2 = rand (rand (rand (concl hs))) in
      let ev = the_asm (fun c -> hd_is "ALL" c &&
                 el 1 (snd (strip_comb c)) = h2) gl in
      STRIP_ASSUME_TAC (MATCH_MP heap_split_store_ref
        (CONJ hs (CONJ hl (CONJ nlt (CONJ len (CONJ st ev))))))) THEN
    W(fun gl ->
      let hs2 = the_asm (fun c -> is_eq c &&
                  hd_is "heap_split" (lhand c) &&
                  hd_is "SOME" (rand c)) gl in
      EXISTS_TAC (lhand (rand (rand (concl hs2)))) THEN
      EXISTS_TAC (rand (rand (rand (concl hs2))))) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* an insert of an array where an array was leaves what a value
   says of a thunk *)
let dest_thunk_insert_ValueArray = prove
 ((cake_as_vars (fun () ->
    `sptree_lookup ptr refs = SOME (bvlSem_ValueArray as1)
     ==> dest_thunk v (insert ptr (ValueArray vls) refs) =
         dest_thunk v refs`)),
  STRIP_TAC THEN
  STRUCT_CASES_TAC(ISPEC (cake_as_vars (fun () -> `v:dataSem_v`))
                     (cases_of `:dataSem_v`)) THEN
  REWRITE_TAC[dataSem_dest_thunk_def] THEN
  MATCH_REDUCE_TAC THEN TRY (SOLVED (REWRITE_TAC[])) THEN
  ASM_CASES_TAC `a1:num = ptr` THEN
  ASM_REWRITE_TAC[lookup_insert] THEN
  (let ds = [distinctness "option"; distinctness "bvlSem_ref"] in
   REWRITE_TAC (injectivity "option" :: ds @ map GSYM ds)) THEN
  CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN
  REWRITE_TAC[SELECT_REFL; EXISTS_UNIQUE_REFL] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

(* the value of a thunk of the references is one of the values *)
let MEM_thunk_all_vs = prove
 ((cake_as_vars (fun () ->
    `sptree_lookup n refs = SOME (bvlSem_Thunk ev x)
     ==> x IN all_vs refs stack'`)),
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  DISJ2_TAC THEN DISJ1_TAC THEN
  EXISTS_TAC `n:num` THEN
  EXISTS_TAC (cake_as_vars (fun () -> `ev:thunk_mode`)) THEN
  EXISTS_TAC (cake_as_vars (fun () -> `x:dataSem_v`)) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MEM_v_all_vs THEN REWRITE_TAC[MEM]);;

(* and so is a value of a MutBlock *)
let MEM_mutblock_all_vs = prove
 ((cake_as_vars (fun () ->
    `sptree_lookup n refs = SOME (bvlSem_MutBlock tg fin l c r) /\
     MEM v (l ++ [c] ++ r)
     ==> v IN all_vs refs stack'`)),
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
  EXISTS_TAC `n:num` THEN
  MAP_EVERY EXISTS_TAC
    [cake_as_vars (fun () -> `tg:num`);
     cake_as_vars (fun () -> `fin:bool`);
     cake_as_vars (fun () -> `l:(dataSem_v)list`);
     cake_as_vars (fun () -> `c:dataSem_v`);
     cake_as_vars (fun () -> `r:(dataSem_v)list`)] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MEM_v_all_vs THEN FIRST_ASSUM ACCEPT_TAC);;

(* two keys of an injective map have two addresses *)
let INJ_FAPPLY_NEQ = prove
 (`!(f:(A,B)fmap) s n m.
     INJ (FAPPLY f) (FDOM f) s /\ n IN FDOM f /\ m IN FDOM f /\
     ~(n = m) ==> ~(FAPPLY f n = FAPPLY f m)`,
  REWRITE_TAC[INJ] THEN MESON_TAC[]);;

(* an address that no timestamp has still has none when the map of
   the timestamps is cut down *)
let IMAGE_DRESTRICT_NOT = prove
 (`!(tf:(A,B)fmap) P x.
     ~(x IN IMAGE (FAPPLY tf) (FDOM tf))
     ==> ~(x IN IMAGE (FAPPLY (DRESTRICT tf P))
                  (FDOM (DRESTRICT tf P)))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_IMAGE; (CONJUNCT1 o SPEC_ALL) DRESTRICT_DEF;
              IN_INTER] THEN
  MESON_TAC[(CONJUNCT2 o SPEC_ALL) DRESTRICT_DEF]);;

(* ---- the assumptions that each arm goes by ----------------------- *)

let g_ins (asl,w) = find_term (hd_is "sptree_insert") w;;

let g_ptr gl = el 0 (snd (strip_comb (g_ins gl)));;

let a_ri gl = the_asm (hd_is "RefBlock_inv") gl;;

let a_neq gl = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                 hd_is "fmap_apply" (rand (rand c))) gl;;

let a_tr gl = the_asm (fun c ->
                let vs,bd = strip_forall c in
                length vs = 2 && is_imp bd &&
                hd_is "heap_lookup" (lhand (rand bd))) gl;;

let a_lkptr gl = the_asm (fun c -> is_eq c &&
                   hd_is "sptree_lookup" (lhand c) &&
                   el 0 (snd (strip_comb (lhand c))) = g_ptr gl &&
                   not (hd_is "sptree_insert" (rand (lhand c)))) gl;;

let a_lknew gl = the_asm (fun c -> is_eq c &&
                   hd_is "sptree_lookup" (lhand c) &&
                   hd_is "sptree_insert" (rand (lhand c))) gl;;

let a_hlold gl =
  let heap = el 0 (snd (strip_comb (concl (a_ri gl)))) in
  the_asm (fun c -> is_eq c && hd_is "heap_lookup" (lhand c) &&
             el 1 (snd (strip_comb (lhand c))) = heap &&
             hd_is "SOME" (rand c)) gl;;

let a_heap2 gl = el 1 (snd (strip_comb (concl (a_ri gl))));;

let a_hlnew gl =
  let h2 = a_heap2 gl in
  the_asm (fun c -> is_eq c && hd_is "heap_lookup" (lhand c) &&
             el 1 (snd (strip_comb (lhand c))) = h2 &&
             hd_is "SOME" (rand c)) gl;;

let g_heap gl =
  let bd = snd (strip_forall (concl (a_tr gl))) in
  el 1 (snd (strip_comb (lhand (rand (lhand bd)))));;
let a_hlgen gl =
  let heap = g_heap gl in
  the_asm (fun c -> is_eq c && hd_is "heap_lookup" (lhand c) &&
             el 1 (snd (strip_comb (lhand c))) = heap &&
             hd_is "SOME" (rand c)) gl;;
let a_lkref r gl = the_asm (fun c -> is_eq c &&
                     hd_is "sptree_lookup" (lhand c) &&
                     el 1 (snd (strip_comb (lhand c))) = r &&
                     hd_is "SOME" (rand c)) gl;;

(* what the invariant says of a value survives an update of the
   references that keeps it, and the cut of the timestamps to the
   ones of the new references and the stack *)
let v_inv_update_gen = prove
 (cake_as_vars (fun () ->
    `(!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 refs2 (w2,f,tf,heap2)) /\
     v_inv conf v1 refs (v2,f,tf,heap) /\
     v1 IN all_vs refs2 stack'
     ==> v_inv conf v1 refs2
           (v2,f,DRESTRICT tf (all_ts refs2 stack'),heap2)`),
  STRIP_TAC THEN
  MATCH_MP_TAC v_inv_tf_restrict THEN
  EXISTS_TAC (cake_as_vars (fun () -> `stack':(dataSem_v)list`)) THEN
  REPEAT CONJ_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    REPEAT STRIP_TAC THEN
    MATCH_MP_TAC (GEN_ALL MEM_in_all_ts) THEN
    EXISTS_TAC (cake_as_vars (fun () -> `v1:dataSem_v`)) THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[]]);;

(* and so does what it says of the values of a list *)
let EVERY2_v_inv_update_gen = prove
 (cake_as_vars (fun () ->
    `(!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 refs2 (w2,f,tf,heap2)) /\
     (!v. MEM v ys ==> v IN all_vs refs2 stack') /\
     EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap)) zs ys
     ==> EVERY2 (\z y. v_inv conf y refs2
           (z,f,DRESTRICT tf (all_ts refs2 stack'),heap2)) zs ys`),
  STRIP_TAC THEN
  MATCH_MP_TAC EVERY2_MEM_MONO THEN
  W(fun gl ->
    let old = the_asm (hd_is "ALL2") gl in
    EXISTS_TAC (el 0 (snd (strip_comb (concl old))))) THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    STRIP_TAC THEN
    W(fun gl ->
      let old = the_asm (hd_is "ALL2") gl in
      let len = MATCH_MP LIST_REL_LENGTH old in
      let mz = the_asm (fun c -> hd_is "MEM" c &&
                 hd_is "ZIP" (rand c)) gl in
      let mem = the_asm (fun c ->
                  length (fst (strip_forall c)) = 1) gl in
      let vi = the_asm (hd_is "v_inv") gl in
      let inn = MATCH_MP mem (MATCH_MP mem_zip_right (CONJ len mz)) in
      MATCH_ACCEPT_TAC (MATCH_MP v_inv_update_gen
        (CONJ (a_vtr gl) (CONJ vi inn))));
    FIRST_ASSUM ACCEPT_TAC]);;

(* the values of a list of an arm, from the transfer that the
   update leaves *)
let EVERY2_ARM_GEN_TAC memlem =
  W(fun (asl,w as gl) ->
    let gargs = snd (strip_comb w) in
    let old = the_asm (fun c -> hd_is "ALL2" c &&
                el 1 (snd (strip_comb c)) = el 1 gargs &&
                el 2 (snd (strip_comb c)) = el 2 gargs) gl in
    let ys = el 2 gargs in
    let ats = find_term (hd_is "all_ts") w in
    let refs2 = lhand ats in
    let v = genvar (hd (snd (dest_type (type_of (rand ats))))) in
    SUBGOAL_THEN
      (mk_forall(v, mk_imp(list_mk_icomb "MEM" [v; ys],
         list_mk_icomb "IN"
           [v; list_mk_icomb "all_vs" [refs2; rand ats]])))
      (fun mem -> ACCEPT_TAC (MATCH_MP EVERY2_v_inv_update_gen
         (CONJ (a_vtr gl) (CONJ mem old)))) THEN
    REPEAT STRIP_TAC THEN
    W(fun gl ->
      let mm = the_asm (hd_is "MEM") gl in
      MATCH_ACCEPT_TAC (MATCH_MP memlem
        (CONJ (a_lkref refs2 gl) mm))));;

(* and so the invariant of a reference that the update did not
   write: its element is where it was, because the store only
   touched the address of the one written *)
let bc_ref_inv_update_gen = prove
 (cake_as_vars (fun () ->
    `INJ (FAPPLY (f:(num,num)fmap)) (FDOM f) s /\
     n IN FDOM f /\ ptr IN FDOM f /\ ~(n = ptr) /\
     FLOOKUP f n = SOME x /\
     (!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 refs2 (w2,f,tf,heap2)) /\
     (!w. dest_thunk w refs = NotThunk
          ==> dest_thunk w refs2 = NotThunk) /\
     (!m. ~(m = ptr)
          ==> sptree_lookup m refs2 = sptree_lookup m refs) /\
     (!m y. ~(m = FAPPLY f ptr) /\ heap_lookup m heap = SOME y
            ==> heap_lookup m heap2 = SOME y) /\
     bc_ref_inv conf n refs (f,tf,heap,be')
     ==> bc_ref_inv conf n refs2
           (f,DRESTRICT tf (all_ts refs2 stack'),heap2,be')`),
  STRIP_TAC THEN
  (* the address of the key, and so the two addresses are not one *)
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `FAPPLY (f:(num,num)fmap) (n:num) = x`)) ASSUME_TAC THENL
   [FIRST_ASSUM (fun lk ->
      if not (is_eq (concl lk)) ||
         not (hd_is "FLOOKUP" (lhand (concl lk))) then fail() else
      MP_TAC (REWRITE_RULE[FLOOKUP_DEF] lk)) THEN
    COND_CASES_TAC THEN
    ASM_REWRITE_TAC[distinctness "option"; injectivity "option"];
    ALL_TAC] THEN
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `~((x:num) = FAPPLY (f:(num,num)fmap) ptr)`)) ASSUME_TAC THENL
   [POP_ASSUM_LIST (fun l ->
      MAP_EVERY ASSUME_TAC (mapfilter (fun th ->
        let c = concl th in
        if hd_is "INJ" c then REWRITE_RULE[INJ] th
        else if hd_is "IN" c ||
                (is_eq c && hd_is "fmap_apply" (lhand c)) ||
                (is_neg c && is_eq (rand c) && is_var (lhand (rand c)))
        then th
        else fail()) l)) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* the new references hold at the key what the old ones held *)
  W(fun (asl,w as gl) ->
    let n = el 1 (snd (strip_comb (concl (the_asm
              (hd_is "bc_ref_inv") gl)))) in
    let neq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                lhand (rand c) = n) gl in
    ASSUME_TAC (MATCH_MP (a_ltr gl) neq)) THEN
  (* and the kind of what it holds says which arm the invariant is *)
  W(fun gl ->
    let lk = the_asm (fun c -> is_eq c &&
               hd_is "sptree_lookup" (lhand c) &&
               hd_is "sptree_lookup" (rand c)) gl in
    NAMED_CASES_TAC (rand (concl lk)) [[]; ["rv"]]) THEN
  TRY (SOLVED (FIRST_X_ASSUM (fun inv ->
    if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
    MP_TAC (REWRITE_RULE[bc_ref_inv_def] inv)) THEN
    ASM_REWRITE_TAC[] THEN REDUCE_MATCH_HARD)) THEN
  NAMED_CASES_TAC (cake_as_vars (fun () ->
    `rv:(dataSem_v)bvlSem_ref`))
    [["l"]; ["flag"; "bs"]; ["ev"; "vv"];
     ["tg"; "fin"; "ll"; "cc"; "rr"]] THEN
  USE_ARMS THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  SPLIT_ASM_TAC THEN
  (* the array of values: the element is where it was and its values
     are values of the new references *)
  TRY (SOLVED
        (W(fun gl ->
           let hl = a_hlgen gl in
           EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
           CONJ_TAC THENL
            [ACCEPT_TAC (MATCH_MP (a_tr gl) (CONJ (a_neq gl) hl));
             EVERY2_ARM_GEN_TAC MEM_ref_all_vs]))) THEN
  (* the array of bytes: only the element *)
  TRY (SOLVED
        (CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
         RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
         W(fun gl ->
           ACCEPT_TAC (MATCH_MP (a_tr gl)
             (CONJ (a_neq gl) (a_hlgen gl)))))) THEN
  (* the thunk: the element, that it is still not a thunk, and its
     value *)
  TRY (SOLVED
        (W(fun gl ->
           let hl = a_hlgen gl in
           EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
           REPEAT CONJ_TAC THENL
            [ACCEPT_TAC (MATCH_MP (a_tr gl) (CONJ (a_neq gl) hl));
             DISCH_THEN (fun ee ->
               W(fun gl ->
                 let impl = the_asm (fun c -> is_imp c &&
                              (try hd_is "dataSem_dest_thunk"
                                     (lhand (rand c))
                               with Failure _ -> false)) gl in
                 ACCEPT_TAC (MATCH_MP (a_dtr gl) (MP impl ee))));
             W(fun (asl,w as gl) ->
               let vi = the_asm (hd_is "v_inv") gl in
               let refs2 = lhand (find_term (hd_is "all_ts") w) in
               let inn = MATCH_MP MEM_thunk_all_vs
                           (a_lkref refs2 gl) in
               MATCH_ACCEPT_TAC (MATCH_MP v_inv_update_gen
                 (CONJ (a_vtr gl) (CONJ vi inn))))]))) THEN
  (* the mutable block: the kind of the collection, the address that
     no timestamp has, the element and its values *)
  TRY (SOLVED
        (REPEAT CONJ_TAC THEN
         TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
         TRY (SOLVED
               (W(fun gl ->
                  let impl = the_asm (fun c -> is_imp c &&
                               is_neg (lhand c) &&
                               is_neg (rand c)) gl in
                  DISCH_THEN (fun nf -> MATCH_ACCEPT_TAC
                    (MATCH_MP IMAGE_DRESTRICT_NOT (MP impl nf)))))) THEN
         W(fun gl ->
           let hl = a_hlgen gl in
           EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
           CONJ_TAC THENL
            [ACCEPT_TAC (MATCH_MP (a_tr gl) (CONJ (a_neq gl) hl));
             EVERY2_ARM_GEN_TAC MEM_mutblock_all_vs]))));;

(* a reference of the invariant has an address *)
let bc_ref_inv_FLOOKUP = prove
 ((cake_as_vars (fun () ->
    `bc_ref_inv conf n refs ((f:(num,num)fmap),tf,heap,be')
     ==> ?x. FLOOKUP f n = SOME x`)),
  STRIP_TAC THEN
  NAMED_CASES_TAC (cake_as_vars (fun () ->
    `FLOOKUP (f:(num,num)fmap) (n:num)`)) [[]; ["x"]] THENL
   [FIRST_X_ASSUM (fun inv ->
      if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
      MP_TAC (REWRITE_RULE[bc_ref_inv_def] inv)) THEN
    ASM_REWRITE_TAC[] THEN REDUCE_MATCH_HARD;
    EXISTS_TAC `x:num` THEN REWRITE_TAC[]]);;

(* the invariant of a reference that an update did not write, with
   no hypothesis about the address of the key: the invariant of the
   reference has one *)
let bc_ref_inv_update_other_gen = prove
 (cake_as_vars (fun () ->
    `INJ (FAPPLY (f:(num,num)fmap)) (FDOM f) s /\
     ptr IN FDOM f /\ ~(n = ptr) /\
     (!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 refs2 (w2,f,tf,heap2)) /\
     (!w. dest_thunk w refs = NotThunk
          ==> dest_thunk w refs2 = NotThunk) /\
     (!m. ~(m = ptr)
          ==> sptree_lookup m refs2 = sptree_lookup m refs) /\
     (!m y. ~(m = FAPPLY f ptr) /\ heap_lookup m heap = SOME y
            ==> heap_lookup m heap2 = SOME y) /\
     bc_ref_inv conf n refs (f,tf,heap,be')
     ==> bc_ref_inv conf n refs2
           (f,DRESTRICT tf (all_ts refs2 stack'),heap2,be')`),
  STRIP_TAC THEN
  FIRST_ASSUM (fun inv ->
    if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
    CHOOSE_THEN ASSUME_TAC (MATCH_MP bc_ref_inv_FLOOKUP inv)) THEN
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `(n:num) IN FDOM (f:(num,num)fmap)`)) ASSUME_TAC THENL
   [FIRST_ASSUM (fun lk ->
      let c = concl lk in
      if not (is_eq c) || not (hd_is "FLOOKUP" (lhand c)) then fail()
      else MP_TAC (REWRITE_RULE[FLOOKUP_DEF] lk)) THEN
    COND_CASES_TAC THEN
    ASM_REWRITE_TAC[distinctness "option"];
    ALL_TAC] THEN
  W(fun (asl,w as gl) ->
    let bargs = snd (strip_comb (concl (the_asm
                 (hd_is "bc_ref_inv") gl))) in
    let n = el 1 bargs in
    let fm = el 0 (tparts (el 3 bargs)) in
    let inj = the_asm (fun c -> hd_is "INJ" c &&
                rand (el 0 (snd (strip_comb c))) = fm) gl in
    let nin = the_asm (fun c -> hd_is "IN" c &&
                hd_is "FDOM" (rand c) &&
                el 0 (snd (strip_comb c)) = n) gl in
    let pin = the_asm (fun c -> hd_is "IN" c &&
                hd_is "FDOM" (rand c) &&
                not (el 0 (snd (strip_comb c)) = n)) gl in
    let neq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                lhand (rand c) = n) gl in
    let lk1 = the_asm (fun c -> is_eq c &&
                hd_is "FLOOKUP" (lhand c)) gl in
    let inv = the_asm (hd_is "bc_ref_inv") gl in
    MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_gen
      (CONJ inj (CONJ nin (CONJ pin (CONJ neq (CONJ lk1
        (CONJ (a_vtr gl) (CONJ (a_dtr gl) (CONJ (a_ltr gl)
          (CONJ (a_tr gl) inv))))))))))));;

(* the three transfers that an insert of an array of values leaves:
   what the invariant says of a value, what a value says of a
   thunk, and what the references hold at another key *)
let VA_trans = prove
 (cake_as_vars (fun () ->
    `RefBlock_inv heap heap2 /\
     sptree_lookup ptr refs = SOME (bvlSem_ValueArray as1)
     ==> (!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
                  ==> v_inv conf w1 (insert ptr (ValueArray vls) refs)
                        (w2,f,tf,heap2)) /\
         (!w. dest_thunk w refs = NotThunk
              ==> dest_thunk w (insert ptr (ValueArray vls) refs) =
                  NotThunk) /\
         (!m. ~(m = ptr)
              ==> sptree_lookup m
                    (insert ptr (ValueArray vls) refs) =
                  sptree_lookup m refs)`),
  STRIP_TAC THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    MATCH_MP_TAC v_inv_ValueArray_insert THEN
    W(fun gl ->
      EXISTS_TAC (el 0 (snd (strip_comb (concl (a_ri gl)))))) THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    ASM_MESON_TAC[];
    GEN_TAC THEN
    W(fun gl ->
      REWRITE_TAC[MATCH_MP dest_thunk_insert_ValueArray
                    (a_lkptr gl)]) THEN
    DISCH_THEN ACCEPT_TAC;
    REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[lookup_insert]]);;

(* the values of a list of an arm, for an insert of an array *)
let EVERY2_ARM_TAC memlem =
  W(fun (asl,w as gl) ->
    let ins = find_term (hd_is "sptree_insert") w in
    let tr = CONJUNCT1 (MATCH_MP VA_trans
               (CONJ (a_ri gl) (a_lkptr gl))) in
    let v = find_term (fun t -> is_var t &&
              fst (dest_var t) = "vls") (concl tr) in
    ASSUME_TAC (INST [rand (el 1 (snd (strip_comb ins))),v] tr)) THEN
  EVERY2_ARM_GEN_TAC memlem;;

(* what the invariant says of a value of the stack survives the
   update of the reference and the cut of the timestamps *)
let v_inv_update_ref = prove
 (cake_as_vars (fun () ->
    `RefBlock_inv heap heap2 /\
     sptree_lookup ptr refs = SOME (bvlSem_ValueArray as1) /\
     v_inv conf v1 refs (v2,f,tf,heap) /\ MEM v1 stack'
     ==> v_inv conf v1 (insert ptr (ValueArray vls) refs)
           (v2,f,
            DRESTRICT tf (all_ts (insert ptr (ValueArray vls) refs)
                            stack'),heap2)`),
  STRIP_TAC THEN
  W(fun (asl,w as gl) ->
    let ins = find_term (hd_is "sptree_insert") w in
    let tr = CONJUNCT1 (MATCH_MP VA_trans
               (CONJ (a_ri gl) (a_lkptr gl))) in
    let vi = the_asm (hd_is "v_inv") gl in
    let mm = the_asm (hd_is "MEM") gl in
    let margs = snd (strip_comb (concl mm)) in
    let inn = MP (SPECL [el 0 margs; el 1 margs; ins]
                    MEM_stack_all_vs) mm in
    MATCH_ACCEPT_TAC (MATCH_MP v_inv_update_gen
      (CONJ tr (CONJ vi inn)))));;

(* and the invariant of a reference that is not the one written *)
let bc_ref_inv_update_ref_other = prove
 (cake_as_vars (fun () ->
    `INJ (FAPPLY (f:(num,num)fmap)) (FDOM f) s /\
     ptr IN FDOM f /\ ~(n = ptr) /\
     RefBlock_inv heap heap2 /\
     (!m y. ~(m = FAPPLY f ptr) /\ heap_lookup m heap = SOME y
            ==> heap_lookup m heap2 = SOME y) /\
     sptree_lookup ptr refs = SOME (bvlSem_ValueArray as1) /\
     bc_ref_inv conf n refs (f,tf,heap,be')
     ==> bc_ref_inv conf n (insert ptr (ValueArray vls) refs)
           (f,DRESTRICT tf (all_ts (insert ptr (ValueArray vls) refs)
                              stack'),heap2,be')`),
  STRIP_TAC THEN
  FIRST_ASSUM (fun inv ->
    if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
    CHOOSE_THEN ASSUME_TAC (MATCH_MP bc_ref_inv_FLOOKUP inv)) THEN
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `(n:num) IN FDOM (f:(num,num)fmap)`)) ASSUME_TAC THENL
   [FIRST_ASSUM (fun lk ->
      let c = concl lk in
      if not (is_eq c) || not (hd_is "FLOOKUP" (lhand c)) then fail()
      else MP_TAC (REWRITE_RULE[FLOOKUP_DEF] lk)) THEN
    COND_CASES_TAC THEN
    ASM_REWRITE_TAC[distinctness "option"];
    ALL_TAC] THEN
  W(fun (asl,w as gl) ->
    let pt = g_ptr gl in
    let inj = the_asm (hd_is "INJ") gl in
    let pin = the_asm (fun c -> hd_is "IN" c && hd_is "FDOM" (rand c) &&
                el 0 (snd (strip_comb c)) = pt) gl in
    let nin = the_asm (fun c -> hd_is "IN" c && hd_is "FDOM" (rand c) &&
                not (el 0 (snd (strip_comb c)) = pt)) gl in
    let neq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                rand (rand c) = pt) gl in
    let lk1 = the_asm (fun c -> is_eq c &&
                hd_is "FLOOKUP" (lhand c)) gl in
    let inv = the_asm (hd_is "bc_ref_inv") gl in
    let trs = CONJUNCTS (MATCH_MP VA_trans
                (CONJ (a_ri gl) (a_lkptr gl))) in
    MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_gen
      (CONJ inj (CONJ nin (CONJ pin (CONJ neq (CONJ lk1
        (CONJ (el 0 trs) (CONJ (el 1 trs) (CONJ (el 2 trs)
          (CONJ (a_tr gl) inv))))))))))));;

(* the invariant of the reference written: it is the array of the
   new values, and its element is the one stored *)
let bc_ref_inv_update_ref_at = prove
 ((cake_as_vars (fun () ->
    `RefBlock_inv heap heap2 /\
     FLOOKUP (f:(num,num)fmap) ptr = SOME p /\
     heap_lookup p heap2 = SOME (RefBlock t1) /\
     sptree_lookup ptr refs = SOME (bvlSem_ValueArray as1) /\
     EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap)) t1 vls
     ==> bc_ref_inv conf ptr (insert ptr (ValueArray vls) refs)
           (f,DRESTRICT tf (all_ts (insert ptr (ValueArray vls) refs)
                              stack'),heap2,be')`)),
  STRIP_TAC THEN
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `sptree_lookup (ptr:num)
       (insert ptr (ValueArray vls)
          (refs:((dataSem_v)bvlSem_ref)spt)) =
     SOME (bvlSem_ValueArray vls)`)) ASSUME_TAC THENL
   [REWRITE_TAC[lookup_insert]; ALL_TAC] THEN
  W(fun gl ->
    let lk1 = the_asm (fun c -> is_eq c &&
                hd_is "FLOOKUP" (lhand c)) gl in
    REWRITE_TAC[MATCH_MP arm_VA (CONJ lk1 (a_lknew gl))]) THEN
  W(fun gl ->
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
    CONJ_TAC THENL
     [ACCEPT_TAC hl;
      EVERY2_ARM_TAC MEM_ref_all_vs]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let update_ref_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ ((RefPtr b ptr) :: stack)) refs
      (roots,heap,be,a,sp,sp1,gens) limit ts /\
      (lookup ptr refs = SOME (ValueArray xs1)) /\ (LENGTH xs =
        LENGTH xs1) ==>
      (?p rs roots2 heap2 u.
        (roots = rs ++ (gc_shared_Pointer p u :: roots2)) /\
        (heap_store p [RefBlock rs] heap = (heap2,T)) /\
        abs_ml_inv conf (xs ++ ((RefPtr b ptr) :: stack)) (insert
          ptr (ValueArray xs) refs)
          (roots,heap2,be,a,sp,sp1,gens) limit ts)`),
  (* the steps that this proof and the three after it take are
     above the statement (tools/overrides.py).  The roots split
     where the pointer of the reference is, the store writes the
     new values into its element, and the heap and the references
     are then as good as they were; of the reference written the
     invariant is the array of the new values and of any other one
     its element, which the store did not touch *)
  (STRIP_TAC THEN
   (* what the invariant says of the stack with the pointer in it *)
   FIRST_X_ASSUM (fun inv ->
     if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                    bc_stack_ref_inv_def] inv)) THEN
   (* the roots split where the pointer is *)
   FIRST_ASSUM (fun lr ->
     if not (hd_is "ALL2" (concl lr)) then fail() else
     STRIP_ASSUME_TAC (MATCH_MP EVERY2_APPEND_CONS lr)) THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) THEN
   (* and the root of the pointer is the address of its reference *)
   FIRST_ASSUM (fun vr ->
     let c = concl vr in
     if not (hd_is "v_inv" c) ||
        not (hd_is "dataSem_RefPtr"
               (el 1 (snd (strip_comb c))))
        then fail()
     else STRIP_ASSUME_TAC (REWRITE_RULE[v_inv_def] vr)) THEN
   RULE_ASSUM_TRY (REWRITE_RULE ref_rws) THEN
   ASM_FS_TAC THEN
   RULE_ASSUM_TRY (REWRITE_RULE ref_rws) THEN
   TRY (FIRST_ASSUM CONTR_TAC) THEN
   SPLIT_ASM_TAC THEN
   (* the reference has an address, and it is reachable, so the
      invariant holds of it *)
   SUBGOAL_THEN (cake_as_vars (fun () ->
     `FLOOKUP (f:(num,num)fmap) (ptr:num) = SOME (FAPPLY f ptr:num)`))
     ASSUME_TAC THENL
    [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC] THEN
   SUBGOAL_THEN (cake_as_vars (fun () ->
     `reachable_refs (xs ++ (RefPtr b ptr :: stack)) refs ptr`))
     ASSUME_TAC THENL
    [FIRST
      [SOLVED (MATCH_MP_TAC (GEN_ALL reach_refptr) THEN
               REWRITE_TAC[MEM_APPEND; MEM]);
       SOLVED (MATCH_MP_TAC (GEN_ALL reach_refptr) THEN
               EXISTS_TAC `b:bool` THEN
               REWRITE_TAC[MEM_APPEND; MEM]);
       SOLVED (REWRITE_TAC[reachable_refs_def] THEN
               EXISTS_TAC (cake_as_vars (fun () ->
                 `RefPtr b ptr:dataSem_v`)) THEN
               EXISTS_TAC `ptr:num` THEN
               REWRITE_TAC[MEM_APPEND; MEM; get_refs_def] THEN
               MESON_TAC[RTC_RULES])];
     ALL_TAC] THEN
   FIRST_ASSUM (fun bri ->
     let bd = snd (strip_forall (concl bri)) in
     if not (is_imp bd) || not (hd_is "bc_ref_inv" (rand bd))
     then fail() else MP_TAC (SPEC `ptr:num` bri)) THEN
   (ANTS_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
   (* which is the arm of a ValueArray *)
   W(fun gl ->
     let lk1 = the_asm (fun c -> is_eq c &&
                 hd_is "FLOOKUP" (lhand c)) gl in
     let lk2 = the_asm (fun c -> is_eq c &&
                 hd_is "sptree_lookup" (lhand c)) gl in
     DISCH_THEN (fun inv ->
       STRIP_ASSUME_TAC
         (REWRITE_RULE[MATCH_MP arm_VA (CONJ lk1 lk2)] inv))) THEN
   (* the lengths of the array, of its values and of their roots *)
   ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC
     (mapfilter (MATCH_MP LIST_REL_LENGTH) l)) THEN
   (* the store of the new values into the reference *)
   W(fun gl ->
     let sp = the_asm (fun c -> is_eq c &&
                hd_is "APPEND" (rand c)) gl in
     let t1 = lhand (rand (concl sp)) in
     let hl = the_asm (fun c -> is_eq c &&
                hd_is "heap_lookup" (lhand c) &&
                can (fun t -> hd_is "RefBlock" (rand t)) (rand c)) gl in
     let zs = rand (rand (rand (concl hl))) in
     SUBGOAL_THEN (mk_eq (list_mk_icomb "LENGTH" [zs],
                          list_mk_icomb "LENGTH" [t1]))
       (fun le -> STRIP_ASSUME_TAC
         (MATCH_MP heap_store_RefBlock (CONJ le hl)) THEN
         ASSUME_TAC le THEN ASSUME_TAC (SYM le)) THENL
      [POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (filter
         (fun t -> let c = concl t in
            is_eq c && (hd_is "LENGTH" (lhand c) ||
                        hd_is "LENGTH" (rand c))) l)) THEN
       ASM_ARITH_TAC;
       ALL_TAC]) THEN
   (* the witnesses: the address of the reference, the roots of the
      new values, the rest of the roots and the new heap *)
   W(fun gl ->
     let sp = the_asm (fun c -> is_eq c &&
                hd_is "APPEND" (rand c)) gl in
     let t1 = lhand (rand (concl sp)) in
     let t2 = rand (rand (rand (concl sp))) in
     let pt = the_asm (fun c -> is_eq c &&
                hd_is "gc_shared_Pointer" (rand c)) gl in
     let p = lhand (rand (concl pt)) in
     let u = rand (rand (concl pt)) in
     let st = the_asm (fun c -> is_eq c &&
                hd_is "heap_store" (lhand c)) gl in
     let h2 = lhand (rand (concl st)) in
     MAP_EVERY EXISTS_TAC [p; t1; t2; h2; u]) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
   (* and the invariant of the new heap and references *)
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   REPEAT CONJ_TAC THEN TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
   (* the roots and the heap are as good as they were *)
   (* the roots are the ones of the split *)
   W(fun gl ->
     let sp = the_asm (fun c -> is_eq c &&
                hd_is "APPEND" (rand c)) gl in
     ONCE_REWRITE_TAC[sp]) THEN
   TRY (SOLVED
         (W(fun gl ->
            let iso = the_asm (fun c ->
              let bd = snd (strip_forall c) in
              is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
            let ro = the_asm (hd_is "roots_ok") gl in
            ACCEPT_TAC (MATCH_MP roots_ok_iso (CONJ ro iso))))) THEN
   TRY (SOLVED
         (W(fun gl ->
            let sp = the_asm (fun c -> is_eq c &&
                       hd_is "APPEND" (rand c)) gl in
            let iso = the_asm (fun c ->
              let bd = snd (strip_forall c) in
              is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
            let ro = REWRITE_RULE[sp] (the_asm (hd_is "roots_ok") gl) in
            let ho = the_asm (hd_is "heap_ok") gl in
            let hlen = the_asm (fun c -> is_eq c &&
                         hd_is "heap_length" (lhand c)) gl in
            let flt = the_asm (fun c -> is_eq c &&
                        hd_is "FILTER" (lhand c)) gl in
            let mm = the_asm (fun c ->
              let bd = snd (strip_forall c) in
              is_imp bd && is_disj (rand bd)) gl in
            ACCEPT_TAC (MATCH_MP heap_ok_store_ref
              (CONJ ho (CONJ ro (CONJ iso (CONJ hlen
                (CONJ flt mm))))))))) THEN
   (* and the unused space is where it was *)
   TRY (SOLVED
         (W(fun gl ->
            let us = the_asm (hd_is "unused_space_inv") gl in
            let ri = the_asm (hd_is "RefBlock_inv") gl in
            let hlen = the_asm (fun c -> is_eq c &&
                         hd_is "heap_length" (lhand c)) gl in
            let st = the_asm (fun c -> is_eq c &&
                       hd_is "heap_store" (lhand c)) gl in
            ACCEPT_TAC (MATCH_MP unused_store_ref
              (CONJ us (CONJ ri (CONJ hlen st))))))) THEN
   (* the kind of the collection: the store is above the nursery and
      writes a reference where one was (gc_kind_store_ref) *)
   TRY (SOLVED
         (W(fun gl ->
            let gk = the_asm (hd_is "gc_kind_inv") gl in
            let st = the_asm (fun c -> is_eq c &&
                       hd_is "heap_store" (lhand c)) gl in
            let hl = the_asm (fun c -> is_eq c &&
                       hd_is "heap_lookup" (lhand c) &&
                       can (fun t -> hd_is "RefBlock" (rand t))
                         (rand c) &&
                       el 1 (snd (strip_comb (lhand c))) =
                         el 2 (snd (strip_comb
                                  (lhand (concl st))))) gl in
            let zs = rand (rand (rand (concl hl))) in
            let len = the_asm (fun c -> is_eq c &&
                        hd_is "LENGTH" (lhand c) &&
                        rand c = list_mk_icomb "LENGTH" [zs]) gl in
            MATCH_ACCEPT_TAC (MATCH_MP gc_kind_store_ref
              (CONJ gk (CONJ st (CONJ hl len))))))) THEN
   (* the maps of the new invariant: the addresses are the ones they
      were, and the timestamps are cut to the ones of the new
      references and stack *)
   W(fun (asl,w as gl) ->
     if not (is_exists w) then ALL_TAC else
     (let sub p = rand (lhand (concl (the_asm (fun c ->
        hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
      let ats = find_term (hd_is "all_ts") w in
      EXISTS_TAC (sub "domain") THEN
      EXISTS_TAC (list_mk_icomb "DRESTRICT" [sub "all_ts"; ats]))) THEN
   REPEAT CONJ_TAC THEN TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the addresses of the maps are the ones of the old heap *)
   TRY (SOLVED
         (W(fun gl ->
            let iso = the_asm (fun c ->
              let bd = snd (strip_forall c) in
              is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
            ONCE_REWRITE_TAC[iso]) THEN
          FIRST [SOLVED (FIRST_ASSUM ACCEPT_TAC);
                 SOLVED (W(fun (asl,w as gl) ->
                   let dr = find_term (hd_is "DRESTRICT") w in
                   let inj = the_asm (fun c -> hd_is "INJ" c &&
                     rand (el 0 (snd (strip_comb c))) = lhand dr) gl in
                   MATCH_ACCEPT_TAC
                     (MATCH_MP INJ_DRESTRICT inj)))])) THEN
   (* the domain of the references has the key in it *)
   TRY (SOLVED
         (REWRITE_TAC[domain_insert] THEN
          MATCH_MP_TAC SUBSET_TRANS THEN
          W(fun gl ->
            let su = the_asm (fun c -> hd_is "SUBSET" c &&
                       hd_is "domain" (rand c)) gl in
            EXISTS_TAC (rand (concl su))) THEN
          CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
          SET_TAC[])) THEN
   (* the timestamps of the restricted map are of the stack, and
      below the counter *)
   TRY (SOLVED
         (REWRITE_TAC[(CONJUNCT1 o SPEC_ALL) DRESTRICT_DEF] THEN
          FIRST [SOLVED (REWRITE_TAC[INTER_SUBSET]);
                 SOLVED (MATCH_MP_TAC SUBSET_TRANS THEN
                         W(fun gl ->
                           let su = the_asm (fun c ->
                             hd_is "SUBSET" c &&
                             hd_is "FDOM" (lhand c)) gl in
                           EXISTS_TAC (lhand (concl su))) THEN
                         CONJ_TAC THEN
                         TRY (FIRST_ASSUM ACCEPT_TAC) THEN
                         REWRITE_TAC[INTER_SUBSET])])) THEN
   (* the blocks of the stack stay unique *)
   TRY (SOLVED
         (W(fun gl ->
            let bu = the_asm (hd_is "blocks_unique") gl in
            ACCEPT_TAC (MATCH_MP blocks_unique_update_ref bu)))) THEN
   (* the values of the stack: the update of the reference and the
      cut of the timestamps leave what the invariant says of them
      (v_inv_update_ref) *)
   W(fun (asl,w) -> if not (hd_is "ALL2" w) then ALL_TAC else
         (MATCH_MP_TAC EVERY2_MEM_MONO THEN
          W(fun (asl,w as gl) ->
            let bod = snd (strip_exists w) in
            let l1 = el 1 (snd (strip_comb (last (conjuncts bod)))) in
            let old = the_asm (fun c -> hd_is "ALL2" c &&
                        el 1 (snd (strip_comb c)) = l1) gl in
            EXISTS_TAC (el 0 (snd (strip_comb (concl old))))) THEN
          CONJ_TAC THENL
           [REPEAT GEN_TAC THEN
            CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
            STRIP_TAC THEN
            W(fun (asl,w as gl) ->
              let gargs = snd (strip_comb w) in
              let x = el 1 gargs in
              let y = el 0 (tparts (el 3 gargs)) in
              let vi = the_asm (fun c -> hd_is "v_inv" c &&
                         el 1 (snd (strip_comb c)) = x &&
                         el 0 (tparts (el 3 (snd (strip_comb c))))
                           = y) gl in
              let ri = the_asm (hd_is "RefBlock_inv") gl in
              let lk = the_asm (fun c -> is_eq c &&
                         hd_is "sptree_lookup" (lhand c)) gl in
              let mz = the_asm (fun c -> hd_is "MEM" c &&
                         hd_is "ZIP" (rand c)) gl in
              let l1 = el 0 (snd (strip_comb (rand (concl mz)))) in
              let le = the_asm (fun c -> is_eq c &&
                         lhand c = list_mk_icomb "LENGTH" [l1]) gl in
              MATCH_ACCEPT_TAC (MATCH_MP v_inv_update_ref
                (CONJ ri (CONJ lk (CONJ vi
                  (MATCH_MP mem_zip_left (CONJ le mz)))))));
            FIRST_ASSUM ACCEPT_TAC])) THEN
   (* and the invariant of each reference that the stack reaches:
      it was reachable before the update (reachable_refs_UPDATE) *)
   W(fun (asl,w) -> if not (is_forall w) then ALL_TAC else
     (REPEAT STRIP_TAC THEN
      FIRST_X_ASSUM (fun rr ->
        if not (hd_is "reachable_refs" (concl rr)) then fail() else
        ASSUME_TAC (MATCH_MP reachable_refs_UPDATE rr)) THEN
      (* what the old invariant says of it *)
      W(fun (asl,w as gl) ->
        let n = el 1 (snd (strip_comb w)) in
        let bri = the_asm (fun c ->
          let vs,bd = strip_forall c in
          length vs = 1 && is_imp bd &&
          hd_is "bc_ref_inv" (rand bd)) gl in
        let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
          not (hd_is "sptree_insert"
                 (el 1 (snd (strip_comb c))))) gl in
        let nin = the_asm (fun c -> hd_is "IN" c &&
          hd_is "FDOM" (rand c) &&
          el 0 (snd (strip_comb c)) = n) gl in
        ASSUME_TAC (MP (SPEC n bri) (CONJ rr nin))) THEN
      (* the reference written, or another one *)
      W(fun (asl,w as gl) ->
        ASM_CASES_TAC (mk_eq (el 1 (snd (strip_comb w)),
                              g_ptr gl))) THEN
      TRY VAR_EQ_TAC THEN
      (* the one written: its values are the new ones
         (bc_ref_inv_update_ref_at) *)
      TRY (SOLVED
            (W(fun gl ->
               let lk1 = the_asm (fun c -> is_eq c &&
                           hd_is "FLOOKUP" (lhand c)) gl in
               let hl2 = a_hlnew gl in
               let rs = rand (rand (rand (concl hl2))) in
               let ev = CONV_RULE(TOP_DEPTH_CONV BETA_CONV)
                          (MATCH_MP EVERY2_SWAP
                            (the_asm (fun c -> hd_is "ALL2" c &&
                               el 2 (snd (strip_comb c)) = rs) gl)) in
               MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_ref_at
                 (CONJ (a_ri gl) (CONJ lk1 (CONJ hl2
                   (CONJ (a_lkptr gl) ev)))))))) THEN
      (* another one: its element did not move, because the store
         only touched the address of the one written
         (bc_ref_inv_update_ref_other) *)
      TRY (SOLVED
            (W(fun (asl,w as gl) ->
               let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
               let inj = the_asm (fun c -> hd_is "INJ" c &&
                           rand (el 0 (snd (strip_comb c))) = fm) gl in
               let pin = the_asm (fun c -> hd_is "IN" c &&
                           hd_is "FDOM" (rand c) &&
                           el 0 (snd (strip_comb c)) = g_ptr gl) gl in
               let neq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                           rand (rand c) = g_ptr gl) gl in
               let inv = the_asm (fun c -> hd_is "bc_ref_inv" c) gl in
               MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_ref_other
                 (CONJ inj (CONJ pin (CONJ neq (CONJ (a_ri gl)
                   (CONJ (a_tr gl) (CONJ (a_lkptr gl) inv)))))))))) THEN
      ALL_TAC))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_update_ref1 = prove
 (cake_as_vars (fun () ->
    `0 < LENGTH xs /\
     lookup ptr refs = SOME (ValueArray xs1) /\
     blocks_unique ts (all_vs refs (xs ++ (RefPtr b ptr :: stack)))
       ==>
       blocks_unique ts
         (all_vs (insert ptr (ValueArray (LUPDATE (HD xs) i xs1))
           refs)
            (xs ++ (RefPtr b ptr :: stack)))`),
  (* the values of the updated array are the old ones and the head
     of the list, which the stack already holds, so every value of
     the new store is one of the old store, and what was unique
     there stays unique *)
  (let lk_ins = prove
    (`!n p (y:(dataSem_v)bvlSem_ref) rfs z.
        lookup n (insert p y rfs) = SOME z <=>
        (n = p /\ y = z) \/ (~(n = p) /\ lookup n rfs = SOME z)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"; distinctness "option"] THEN
     CONV_TAC TAUT) in
   let hd_cons = prove
    (`!(xs:dataSem_v list). 0 < LENGTH xs
        ==> ?t. xs = CONS (HD xs) t`,
     LIST_INDUCT_TAC THEN
     REWRITE_TAC[LENGTH; LT_REFL; HD; LT_0] THEN
     EXISTS_TAC `t:dataSem_v list` THEN REWRITE_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
   FIRST_ASSUM(fun th -> MP_TAC(MATCH_MP hd_cons th)) THEN
   DISCH_THEN(X_CHOOSE_TAC `tt:dataSem_v list`) THEN
   SUBGOAL_THEN
     `!v. MEM v (v_all_vs (LUPDATE (HD (xs:dataSem_v list)) i xs1))
          ==> MEM v (v_all_vs xs1) \/ MEM v (v_all_vs xs)`
     ASSUME_TAC THENL
    [GEN_TAC THEN DISCH_TAC THEN
     FIRST_ASSUM(fun th ->
       MP_TAC(MATCH_MP MEM_v_all_vs_LUPDATE th)) THEN
     DISCH_THEN(DISJ_CASES_THEN2
       (fun hd1 -> DISJ2_TAC THEN
         FIRST_ASSUM(fun xe ->
           if (try fst(dest_var(lhs(concl xe))) = "xs"
               with Failure _ -> false)
           then GEN_REWRITE_TAC (RAND_CONV o RAND_CONV) [xe]
           else fail()) THEN
         MATCH_MP_TAC MEM_v_all_vs_extend_tl THEN
         ACCEPT_TAC hd1)
       (fun t2 -> DISJ1_TAC THEN ACCEPT_TAC t2));
     ALL_TAC] THEN
   W(fun (asl,w) ->
     let hd_is n t =
       (try fst(dest_const(fst(strip_comb t))) = n
        with Failure _ -> false) in
     let allvs t = hd_is "all_vs" t &&
                   length (snd(strip_comb t)) = 2 in
     let newset = find_term allvs w in
     let oldset = find_term allvs
       (concl (find (fun th -> can (find_term allvs) (concl th))
                 (map snd asl))) in
     let vv = mk_var("v",hd(snd(dest_type(type_of newset)))) in
     let inn a s =
       mk_comb(mk_comb(inst [type_of a,`:A`]
         `(IN):A->(A->bool)->bool`, a), s) in
     SUBGOAL_THEN
       (mk_forall(vv, mk_imp(inn vv newset, inn vv oldset)))
       ASSUME_TAC) THENL
    [GEN_TAC THEN
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; lk_ins;
                 injectivity "bvlSem_ref"; distinctness "bvlSem_ref";
                 v_all_vs_append; MEM_APPEND] THEN
     STRIP_TAC THEN ASM_MESON_TAC[];
     ALL_TAC] THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   ASM_REWRITE_TAC[] THEN CONJ_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   FIRST_ASSUM ACCEPT_TAC));;

let heap_deref_def = cake_define
  `(heap_deref a heap =
     (match heap_lookup a heap with SOME (DataElement xs l
       (RefTag,[])) -> SOME xs | _29 -> NONE))`;;

(* the port's own: what the proofs of the four update theorems
   after update_ref_thm add to the block above its statement.  A
   store of one value writes the root of it into the element's
   place for it (LUPDATE), so the pointers of the element written
   are that root and the ones it had (ptrs_store_LUPDATE), the
   values of the new array are the one written and the old ones
   (reach_refs_update_ref1), and the arm of the reference written
   is the old relation with one pair replaced
   (bc_ref_inv_update_ref_at1) *)

(* the head of a list that is not empty is one of its values *)
let MEM_HD = prove
 (`!(l:A list). 0 < LENGTH l ==> MEM (HD l) l`,
  LIST_INDUCT_TAC THEN REWRITE_TAC[LENGTH; HD; MEM; LT_REFL]);;

(* the pointers of the element that an update of one value writes:
   the root put in, or a pointer that the element had *)
let ptrs_store_LUPDATE = prove
 (`heap_ok heap limit' /\ roots_ok (rs ++ (r :: roots2)) heap /\
   0 < LENGTH rs /\ heap_lookup p heap = SOME (RefBlock zs)
   ==> (!ptr u. MEM (gc_shared_Pointer ptr u) (LUPDATE (HD rs) i zs)
                ==> isSomeDataElement (heap_lookup ptr heap))`,
  REWRITE_TAC[heap_ok_def; roots_ok_def] THEN STRIP_TAC THEN
  SPLIT_ASM_TAC THEN
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM (fun m ->
    if not (hd_is "MEM" (concl m)) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP MEM_LUPDATE_E m)) THENL
   [(* the root written *)
    POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (mapfilter (fun th ->
      let c = concl th in
      if (let vs,bd = strip_forall c in
          length vs = 2 && is_imp bd && hd_is "MEM" (lhand bd) &&
          hd_is "APPEND" (rand (lhand bd))) ||
         (is_eq c && hd_is "HD" (rand c)) || hd_is "<" c
      then th else fail()) l)) THEN
    ASM_MESON_TAC[MEM_HD; MEM_APPEND];
    (* a pointer of the element, which was in a good heap *)
    W(fun gl ->
      let ho = the_asm (fun c ->
        length (fst (strip_forall c)) = 5) gl in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c)) gl in
      let md = REWRITE_RULE[RefBlock_def]
                 (MATCH_MP heap_lookup_MEM hl) in
      let mp = the_asm (fun c -> hd_is "MEM" c &&
                 hd_is "gc_shared_Pointer"
                   (el 0 (snd (strip_comb c)))) gl in
      ACCEPT_TAC (MATCH_MP ho (CONJ md mp)))]);;

(* the first pair of two lists that a relation relates *)
let EVERY2_HD = prove
 (`!(P:A->B->bool) xs ys. EVERY2 P xs ys /\ 0 < LENGTH xs
                          ==> P (HD xs) (HD ys)`,
  GEN_TAC THEN LIST_INDUCT_TAC THEN
  REWRITE_TAC[LENGTH; LT_REFL] THEN REPEAT GEN_TAC THEN
  STRUCT_CASES_TAC(ISPEC `ys:B list` (cases_of `:(B)list`)) THEN
  REWRITE_TAC[ALL2_DEF; HD; TL; NOT_CONS_NIL] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* a reference that the stack reaches through the array with one
   value replaced was reachable before the update: a value of the
   new array is the one written, which is on the stack, or one that
   the old array held (reachable_refs_UPDATE1) *)
let reach_refs_update_ref1 = prove
 (cake_as_vars (fun () ->
    `reachable_refs (xs ++ (RefPtr b ptr :: stack))
       (insert ptr (ValueArray (LUPDATE (HD xs) i xs1)) refs) n /\
     sptree_lookup ptr refs = SOME (bvlSem_ValueArray xs1) /\
     0 < LENGTH xs
     ==> reachable_refs (xs ++ (RefPtr b ptr :: stack)) refs n`),
  STRIP_TAC THEN
  FIRST_ASSUM (fun rr ->
    if not (hd_is "reachable_refs" (concl rr)) then fail() else
    MATCH_MP_TAC (MATCH_MP reachable_refs_UPDATE1 rr)) THEN
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM (fun m ->
    if not (hd_is "MEM" (concl m)) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP MEM_LUPDATE_E m)) THENL
   [(* the value written, which is on the stack *)
    POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (mapfilter (fun th ->
      let c = concl th in
      if (is_neg c && hd_is "MEM" (rand c)) ||
         (is_eq c && hd_is "HD" (rand c)) || hd_is "<" c
      then th else fail()) l)) THEN
    ASM_MESON_TAC[MEM_HD];
    (* a value that the old array held *)
    W(fun gl ->
      let lk = the_asm (fun c -> is_eq c &&
                 hd_is "sptree_lookup" (lhand c) &&
                 not (hd_is "sptree_insert" (rand (lhand c)))) gl in
      EXISTS_TAC (rand (rand (rand (concl lk))))) THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* the invariant of the reference written when one of its values is
   replaced: the array with that value replaced, and the element
   with the root of it replaced (EVERY2_LUPDATE_same) *)
let bc_ref_inv_update_ref_at1 = prove
 (cake_as_vars (fun () ->
    `RefBlock_inv heap heap2 /\
     FLOOKUP (f:(num,num)fmap) ptr = SOME p /\
     heap_lookup p heap2 = SOME (RefBlock (LUPDATE t i zs)) /\
     sptree_lookup ptr refs = SOME (bvlSem_ValueArray xs1) /\
     EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap)) zs xs1 /\
     v_inv conf v refs (t,f,tf,heap)
     ==> bc_ref_inv conf ptr
           (insert ptr (ValueArray (LUPDATE v i xs1)) refs)
           (f,DRESTRICT tf
                (all_ts (insert ptr
                   (ValueArray (LUPDATE v i xs1)) refs) stack'),
            heap2,be')`),
  STRIP_TAC THEN
  (* the new references hold the array with the value replaced *)
  W(fun (asl,w) ->
    let ins = find_term (hd_is "sptree_insert") w in
    let args = snd (strip_comb ins) in
    SUBGOAL_THEN
      (mk_eq (list_mk_icomb "sptree_lookup" [el 0 args; ins],
              list_mk_icomb "SOME" [el 1 args]))
      ASSUME_TAC THENL
     [REWRITE_TAC[lookup_insert]; ALL_TAC]) THEN
  (* which is the arm of a ValueArray *)
  W(fun gl ->
    let lk1 = the_asm (fun c -> is_eq c &&
                hd_is "FLOOKUP" (lhand c)) gl in
    REWRITE_TAC[MATCH_MP arm_VA (CONJ lk1 (a_lknew gl))]) THEN
  (* the element is the one stored, and its values are the old ones
     with the value written in its place *)
  W(fun (asl,w as gl) ->
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    let old = the_asm (hd_is "ALL2") gl in
    let vi = the_asm (hd_is "v_inv") gl in
    let oargs = snd (strip_comb (concl old)) in
    let vargs = snd (strip_comb (concl vi)) in
    let lup = find_term (hd_is "LUPDATE") (rand (concl hl)) in
    let i = el 1 (snd (strip_comb lup)) in
    let th = CONV_RULE(TOP_DEPTH_CONV BETA_CONV)
               (ISPECL [el 0 oargs; el 1 oargs; el 2 oargs; i;
                        el 0 (tparts (el 3 vargs)); el 1 vargs]
                  EVERY2_LUPDATE_same) in
    EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
    CONJ_TAC THENL
     [ACCEPT_TAC hl;
      ASSUME_TAC (MATCH_MP th (CONJ vi old)) THEN
      EVERY2_ARM_TAC MEM_ref_all_vs]));;

(* the assumption that a list is not empty *)
let a_pos t gl = the_asm (fun c -> hd_is "<" c && lhand c = `0` &&
                   rand c = list_mk_icomb "LENGTH" [t]) gl;;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let update_ref_thm1 = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ (RefPtr b ptr :: stack)) refs
      (roots,heap,be,a,sp,sp1,gens) limit ts /\
      (lookup ptr refs = SOME (ValueArray xs1)) /\ i < LENGTH xs1
        /\ 0 < LENGTH xs ==>
      (?p rs roots2 vs1 heap2 u.
        (roots = rs ++ (gc_shared_Pointer p u :: roots2)) /\
          (LENGTH rs = LENGTH xs) /\
        (heap_deref p heap = SOME vs1) /\ LENGTH vs1 = LENGTH xs1
          /\
        (heap_store p [RefBlock (LUPDATE (HD rs) i vs1)] heap =
          (heap2,T)) /\
        abs_ml_inv conf (xs ++ ((RefPtr b ptr) :: stack))
          (insert ptr (ValueArray (LUPDATE (HD xs) i xs1)) refs)
          (roots,heap2,be,a,sp,sp1,gens) limit ts)`),
  (* the steps are above the statement and above update_ref_thm
     (tools/overrides.py).  The proof is the one of update_ref_thm
     with the store of one value in place of the store of the whole
     array: the element keeps its values but the one written, whose
     root is the head of the roots of the stack's values, and the
     array of the new references keeps its values but that one *)
  (STRIP_TAC THEN
   (* what the invariant says of the stack with the pointer in it *)
   FIRST_X_ASSUM (fun inv ->
     if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                    bc_stack_ref_inv_def] inv)) THEN
   (* the roots split where the pointer is *)
   FIRST_ASSUM (fun lr ->
     if not (hd_is "ALL2" (concl lr)) then fail() else
     STRIP_ASSUME_TAC (MATCH_MP EVERY2_APPEND_CONS lr)) THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) THEN
   (* and the root of the pointer is the address of its reference *)
   FIRST_ASSUM (fun vr ->
     let c = concl vr in
     if not (hd_is "v_inv" c) ||
        not (hd_is "dataSem_RefPtr"
               (el 1 (snd (strip_comb c))))
        then fail()
     else STRIP_ASSUME_TAC (REWRITE_RULE[v_inv_def] vr)) THEN
   RULE_ASSUM_TRY (REWRITE_RULE ref_rws) THEN
   ASM_FS_TAC THEN
   RULE_ASSUM_TRY (REWRITE_RULE ref_rws) THEN
   TRY (FIRST_ASSUM CONTR_TAC) THEN
   SPLIT_ASM_TAC THEN
   (* the reference has an address, and it is reachable, so the
      invariant holds of it *)
   SUBGOAL_THEN (cake_as_vars (fun () ->
     `FLOOKUP (f:(num,num)fmap) (ptr:num) = SOME (FAPPLY f ptr:num)`))
     ASSUME_TAC THENL
    [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC] THEN
   SUBGOAL_THEN (cake_as_vars (fun () ->
     `reachable_refs (xs ++ (RefPtr b ptr :: stack)) refs ptr`))
     ASSUME_TAC THENL
    [FIRST
      [SOLVED (MATCH_MP_TAC (GEN_ALL reach_refptr) THEN
               REWRITE_TAC[MEM_APPEND; MEM]);
       SOLVED (MATCH_MP_TAC (GEN_ALL reach_refptr) THEN
               EXISTS_TAC `b:bool` THEN
               REWRITE_TAC[MEM_APPEND; MEM]);
       SOLVED (REWRITE_TAC[reachable_refs_def] THEN
               EXISTS_TAC (cake_as_vars (fun () ->
                 `RefPtr b ptr:dataSem_v`)) THEN
               EXISTS_TAC `ptr:num` THEN
               REWRITE_TAC[MEM_APPEND; MEM; get_refs_def] THEN
               MESON_TAC[RTC_RULES])];
     ALL_TAC] THEN
   FIRST_ASSUM (fun bri ->
     let bd = snd (strip_forall (concl bri)) in
     if not (is_imp bd) || not (hd_is "bc_ref_inv" (rand bd))
     then fail() else MP_TAC (SPEC `ptr:num` bri)) THEN
   (ANTS_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
   (* which is the arm of a ValueArray *)
   W(fun gl ->
     let lk1 = the_asm (fun c -> is_eq c &&
                 hd_is "FLOOKUP" (lhand c)) gl in
     let lk2 = the_asm (fun c -> is_eq c &&
                 hd_is "sptree_lookup" (lhand c)) gl in
     DISCH_THEN (fun inv ->
       STRIP_ASSUME_TAC
         (REWRITE_RULE[MATCH_MP arm_VA (CONJ lk1 lk2)] inv))) THEN
   (* the lengths of the array, of its values and of their roots *)
   ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC
     (mapfilter (MATCH_MP LIST_REL_LENGTH) l)) THEN
   (* the roots of the stack's values are not empty either *)
   W(fun gl ->
     let sp = the_asm (fun c -> is_eq c &&
                hd_is "APPEND" (rand c)) gl in
     let t1 = lhand (rand (concl sp)) in
     SUBGOAL_THEN (list_mk_icomb "<"
                     [`0`; list_mk_icomb "LENGTH" [t1]])
       ASSUME_TAC THENL
      [POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (filter
         (fun t -> let c = concl t in
            (is_eq c && (hd_is "LENGTH" (lhand c) ||
                         hd_is "LENGTH" (rand c))) ||
            hd_is "<" c) l)) THEN
       ASM_ARITH_TAC;
       ALL_TAC]) THEN
   (* the store of the new value into its place in the element *)
   W(fun (asl,w as gl) ->
     let sp = the_asm (fun c -> is_eq c &&
                hd_is "APPEND" (rand c)) gl in
     let t1 = lhand (rand (concl sp)) in
     let hl = the_asm (fun c -> is_eq c &&
                hd_is "heap_lookup" (lhand c) &&
                can (fun t -> hd_is "RefBlock" (rand t)) (rand c)) gl in
     let zs = rand (rand (rand (concl hl))) in
     let i = el 1 (snd (strip_comb
               (find_term (hd_is "LUPDATE") w))) in
     let ws = list_mk_icomb "LUPDATE"
                [list_mk_icomb "HD" [t1]; i; zs] in
     SUBGOAL_THEN (mk_eq (list_mk_icomb "LENGTH" [zs],
                          list_mk_icomb "LENGTH" [ws]))
       (fun le -> STRIP_ASSUME_TAC
         (MATCH_MP heap_store_RefBlock (CONJ le hl)) THEN
         ASSUME_TAC le THEN ASSUME_TAC (SYM le)) THENL
      [REWRITE_TAC[LENGTH_LUPDATE];
       ALL_TAC]) THEN
   (* the witnesses: the address of the reference, the roots of the
      new values, the rest of the roots and the new heap *)
   W(fun gl ->
     let sp = the_asm (fun c -> is_eq c &&
                hd_is "APPEND" (rand c)) gl in
     let t1 = lhand (rand (concl sp)) in
     let t2 = rand (rand (rand (concl sp))) in
     let pt = the_asm (fun c -> is_eq c &&
                hd_is "gc_shared_Pointer" (rand c)) gl in
     let p = lhand (rand (concl pt)) in
     let u = rand (rand (concl pt)) in
     let st = the_asm (fun c -> is_eq c &&
                hd_is "heap_store" (lhand c)) gl in
     let h2 = lhand (rand (concl st)) in
     let zs = rand (rand (rand (concl (a_hlold gl)))) in
     MAP_EVERY EXISTS_TAC [p; t1; t2; zs; h2; u]) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
   (* the values of the element are the ones the heap holds there *)
   TRY (SOLVED
         (W(fun gl ->
            REWRITE_TAC[heap_deref_def; a_hlold gl; RefBlock_def]) THEN
          MATCH_REDUCE_TAC THEN REWRITE_TAC[])) THEN
   (* and the invariant of the new heap and references *)
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
   (* the roots and the heap are as good as they were *)
   (* the roots are the ones of the split *)
   W(fun gl ->
     let sp = the_asm (fun c -> is_eq c &&
                hd_is "APPEND" (rand c)) gl in
     ONCE_REWRITE_TAC[sp]) THEN
   TRY (SOLVED
         (W(fun gl ->
            let iso = the_asm (fun c ->
              let bd = snd (strip_forall c) in
              is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
            let ro = the_asm (hd_is "roots_ok") gl in
            ACCEPT_TAC (MATCH_MP roots_ok_iso (CONJ ro iso))))) THEN
   TRY (SOLVED
         (W(fun gl ->
            let sp = the_asm (fun c -> is_eq c &&
                       hd_is "APPEND" (rand c)) gl in
            let iso = the_asm (fun c ->
              let bd = snd (strip_forall c) in
              is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
            let ro = REWRITE_RULE[sp] (the_asm (hd_is "roots_ok") gl) in
            let ho = the_asm (hd_is "heap_ok") gl in
            let hlen = the_asm (fun c -> is_eq c &&
                         hd_is "heap_length" (lhand c)) gl in
            let flt = the_asm (fun c -> is_eq c &&
                        hd_is "FILTER" (lhand c)) gl in
            let mm = the_asm (fun c ->
              let bd = snd (strip_forall c) in
              is_imp bd && is_disj (rand bd)) gl in
            let rs = lhand (el 0 (snd (strip_comb (concl ro)))) in
            let i = el 1 (snd (strip_comb (find_term
                      (hd_is "LUPDATE") (concl mm)))) in
            let pw = INST [i,`i:num`]
                       (MATCH_MP ptrs_store_LUPDATE
                         (CONJ ho (CONJ ro (CONJ (a_pos rs gl)
                           (a_hlold gl))))) in
            ACCEPT_TAC (MATCH_MP heap_ok_store_ws
              (CONJ ho (CONJ pw (CONJ iso (CONJ hlen
                (CONJ flt mm))))))))) THEN
   (* and the unused space is where it was *)
   TRY (SOLVED
         (W(fun gl ->
            let us = the_asm (hd_is "unused_space_inv") gl in
            let ri = the_asm (hd_is "RefBlock_inv") gl in
            let hlen = the_asm (fun c -> is_eq c &&
                         hd_is "heap_length" (lhand c)) gl in
            let st = the_asm (fun c -> is_eq c &&
                       hd_is "heap_store" (lhand c)) gl in
            ACCEPT_TAC (MATCH_MP unused_store_ref
              (CONJ us (CONJ ri (CONJ hlen st))))))) THEN
   (* the kind of the collection: the store is above the nursery and
      writes a reference where one was (gc_kind_store_ref) *)
   TRY (SOLVED
         (W(fun gl ->
            let gk = the_asm (hd_is "gc_kind_inv") gl in
            let st = the_asm (fun c -> is_eq c &&
                       hd_is "heap_store" (lhand c)) gl in
            let hl = the_asm (fun c -> is_eq c &&
                       hd_is "heap_lookup" (lhand c) &&
                       can (fun t -> hd_is "RefBlock" (rand t))
                         (rand c) &&
                       el 1 (snd (strip_comb (lhand c))) =
                         el 2 (snd (strip_comb
                                  (lhand (concl st))))) gl in
            let zs = rand (rand (rand (concl hl))) in
            let len = the_asm (fun c -> is_eq c &&
                        hd_is "LENGTH" (lhand c) &&
                        rand c = list_mk_icomb "LENGTH" [zs]) gl in
            MATCH_ACCEPT_TAC (MATCH_MP gc_kind_store_ref
              (CONJ gk (CONJ st (CONJ hl len))))))) THEN
   (* the maps of the new invariant: the addresses are the ones they
      were, and the timestamps are cut to the ones of the new
      references and stack *)
   W(fun (asl,w as gl) ->
     if not (is_exists w) then ALL_TAC else
     (let sub p = rand (lhand (concl (the_asm (fun c ->
        hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
      let ats = find_term (hd_is "all_ts") w in
      EXISTS_TAC (sub "domain") THEN
      EXISTS_TAC (list_mk_icomb "DRESTRICT" [sub "all_ts"; ats]))) THEN
   REPEAT CONJ_TAC THEN TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the addresses of the maps are the ones of the old heap *)
   TRY (SOLVED
         (W(fun gl ->
            let iso = the_asm (fun c ->
              let bd = snd (strip_forall c) in
              is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
            ONCE_REWRITE_TAC[iso]) THEN
          FIRST [SOLVED (FIRST_ASSUM ACCEPT_TAC);
                 SOLVED (W(fun (asl,w as gl) ->
                   let dr = find_term (hd_is "DRESTRICT") w in
                   let inj = the_asm (fun c -> hd_is "INJ" c &&
                     rand (el 0 (snd (strip_comb c))) = lhand dr) gl in
                   MATCH_ACCEPT_TAC
                     (MATCH_MP INJ_DRESTRICT inj)))])) THEN
   (* the domain of the references has the key in it *)
   TRY (SOLVED
         (REWRITE_TAC[domain_insert] THEN
          MATCH_MP_TAC SUBSET_TRANS THEN
          W(fun gl ->
            let su = the_asm (fun c -> hd_is "SUBSET" c &&
                       hd_is "domain" (rand c)) gl in
            EXISTS_TAC (rand (concl su))) THEN
          CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
          SET_TAC[])) THEN
   (* the timestamps of the restricted map are of the stack, and
      below the counter *)
   TRY (SOLVED
         (REWRITE_TAC[(CONJUNCT1 o SPEC_ALL) DRESTRICT_DEF] THEN
          FIRST [SOLVED (REWRITE_TAC[INTER_SUBSET]);
                 SOLVED (MATCH_MP_TAC SUBSET_TRANS THEN
                         W(fun gl ->
                           let su = the_asm (fun c ->
                             hd_is "SUBSET" c &&
                             hd_is "FDOM" (lhand c)) gl in
                           EXISTS_TAC (lhand (concl su))) THEN
                         CONJ_TAC THEN
                         TRY (FIRST_ASSUM ACCEPT_TAC) THEN
                         REWRITE_TAC[INTER_SUBSET])])) THEN
   (* the blocks of the stack stay unique *)
   TRY (SOLVED
         (W(fun (asl,w as gl) ->
            let bu = the_asm (hd_is "blocks_unique") gl in
            let le = a_pos (rand (el 0 (snd (strip_comb
                       (find_term (hd_is "LUPDATE") w))))) gl in
            ACCEPT_TAC (MATCH_MP blocks_unique_update_ref1
              (CONJ le (CONJ (a_lkptr gl) bu)))))) THEN
   (* the values of the stack: the update of the reference and the
      cut of the timestamps leave what the invariant says of them
      (v_inv_update_ref) *)
   W(fun (asl,w) -> if not (hd_is "ALL2" w) then ALL_TAC else
         (MATCH_MP_TAC EVERY2_MEM_MONO THEN
          W(fun (asl,w as gl) ->
            let bod = snd (strip_exists w) in
            let l1 = el 1 (snd (strip_comb (last (conjuncts bod)))) in
            let old = the_asm (fun c -> hd_is "ALL2" c &&
                        el 1 (snd (strip_comb c)) = l1) gl in
            EXISTS_TAC (el 0 (snd (strip_comb (concl old))))) THEN
          CONJ_TAC THENL
           [REPEAT GEN_TAC THEN
            CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
            STRIP_TAC THEN
            W(fun (asl,w as gl) ->
              let gargs = snd (strip_comb w) in
              let x = el 1 gargs in
              let y = el 0 (tparts (el 3 gargs)) in
              let vi = the_asm (fun c -> hd_is "v_inv" c &&
                         el 1 (snd (strip_comb c)) = x &&
                         el 0 (tparts (el 3 (snd (strip_comb c))))
                           = y) gl in
              let ri = the_asm (hd_is "RefBlock_inv") gl in
              let lk = the_asm (fun c -> is_eq c &&
                         hd_is "sptree_lookup" (lhand c)) gl in
              let mz = the_asm (fun c -> hd_is "MEM" c &&
                         hd_is "ZIP" (rand c)) gl in
              let l1 = el 0 (snd (strip_comb (rand (concl mz)))) in
              let le = the_asm (fun c -> is_eq c &&
                         lhand c = list_mk_icomb "LENGTH" [l1]) gl in
              MATCH_ACCEPT_TAC (MATCH_MP v_inv_update_ref
                (CONJ ri (CONJ lk (CONJ vi
                  (MATCH_MP mem_zip_left (CONJ le mz)))))));
            FIRST_ASSUM ACCEPT_TAC])) THEN
   (* and the invariant of each reference that the stack reaches:
      it was reachable before the update (reachable_refs_UPDATE) *)
   W(fun (asl,w) -> if not (is_forall w) then ALL_TAC else
     (REPEAT STRIP_TAC THEN
      W(fun gl ->
        let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                   hd_is "sptree_insert"
                     (el 1 (snd (strip_comb c)))) gl in
        let le = a_pos (rand (el 0 (snd (strip_comb (find_term
                   (hd_is "LUPDATE") (concl rr)))))) gl in
        ASSUME_TAC (MATCH_MP reach_refs_update_ref1
          (CONJ rr (CONJ (a_lkptr gl) le)))) THEN
      (* what the old invariant says of it *)
      W(fun (asl,w as gl) ->
        let n = el 1 (snd (strip_comb w)) in
        let bri = the_asm (fun c ->
          let vs,bd = strip_forall c in
          length vs = 1 && is_imp bd &&
          hd_is "bc_ref_inv" (rand bd)) gl in
        let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
          not (hd_is "sptree_insert"
                 (el 1 (snd (strip_comb c))))) gl in
        let nin = the_asm (fun c -> hd_is "IN" c &&
          hd_is "FDOM" (rand c) &&
          el 0 (snd (strip_comb c)) = n) gl in
        ASSUME_TAC (MP (SPEC n bri) (CONJ rr nin))) THEN
      (* the reference written, or another one *)
      W(fun (asl,w as gl) ->
        ASM_CASES_TAC (mk_eq (el 1 (snd (strip_comb w)),
                              g_ptr gl))) THEN
      TRY VAR_EQ_TAC THEN
      (* the one written: its values are the new ones
         (bc_ref_inv_update_ref_at) *)
      TRY (SOLVED
            (W(fun gl ->
               let lk1 = the_asm (fun c -> is_eq c &&
                           hd_is "FLOOKUP" (lhand c)) gl in
               let hl2 = a_hlnew gl in
               let largs = snd (strip_comb
                             (rand (rand (rand (concl hl2))))) in
               let t1 = rand (el 0 largs) in
               let zs = el 2 largs in
               let old = the_asm (fun c -> hd_is "ALL2" c &&
                           el 1 (snd (strip_comb c)) = zs) gl in
               let spl = the_asm (fun c -> hd_is "ALL2" c &&
                           el 2 (snd (strip_comb c)) = t1) gl in
               let ev = CONV_RULE(TOP_DEPTH_CONV BETA_CONV)
                          (MATCH_MP EVERY2_HD
                            (CONJ spl (a_pos
                               (el 1 (snd (strip_comb (concl spl))))
                               gl))) in
               MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_ref_at1
                 (CONJ (a_ri gl) (CONJ lk1 (CONJ hl2
                   (CONJ (a_lkptr gl) (CONJ old ev))))))))) THEN
      (* another one: its element did not move, because the store
         only touched the address of the one written
         (bc_ref_inv_update_ref_other) *)
      TRY (SOLVED
            (W(fun (asl,w as gl) ->
               let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
               let inj = the_asm (fun c -> hd_is "INJ" c &&
                           rand (el 0 (snd (strip_comb c))) = fm) gl in
               let pin = the_asm (fun c -> hd_is "IN" c &&
                           hd_is "FDOM" (rand c) &&
                           el 0 (snd (strip_comb c)) = g_ptr gl) gl in
               let neq = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                           rand (rand c) = g_ptr gl) gl in
               let inv = the_asm (fun c -> hd_is "bc_ref_inv" c) gl in
               MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_ref_other
                 (CONJ inj (CONJ pin (CONJ neq (CONJ (a_ri gl)
                   (CONJ (a_tr gl) (CONJ (a_lkptr gl) inv)))))))))) THEN
      ALL_TAC))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_update_thunk = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (h :: RefPtr F ptr :: stack)) ==>
       blocks_unique ts
         (all_vs (insert ptr (Thunk ev h) refs) (h :: RefPtr F
           ptr :: stack))`),
  (* the value that the thunk is given is on the stack already *)
  (let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let vcons = prove
    (`!(v:dataSem_v) xs y. MEM y (v_all_vs (CONS v xs)) <=>
        MEM y (v_all_vs [v]) \/ MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [prove(`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
              REWRITE_TAC[APPEND])] THEN
     REWRITE_TAC[v_all_vs_append; MEM_APPEND]) in
   let inc = prove
    (`!refs ptr ev h stack' t a q.
        Block t a q IN
          all_vs (insert ptr (Thunk ev h) refs)
                 (CONS h (CONS (RefPtr F ptr) stack')) ==>
        Block t a q IN
          all_vs refs (CONS h (CONS (RefPtr F ptr) stack'))`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; li;
                 distinctness "bvlSem_ref";
                 injectivity "bvlSem_ref"] THEN
     MESON_TAC[vcons]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

let thunk_deref_def = cake_define
  `(thunk_deref a heap =
     (match heap_lookup a heap with SOME (DataElement xs l
       (ThunkTag NotEvaluated,[])) -> SOME xs | _30 -> NONE))`;;

(* the port's own: what the proof of update_thunk_thm adds to the
   block above update_ref_thm.  The store writes a thunk where a
   thunk that was not evaluated was, so the halves of the split and
   the kind of the collection behave as they do for a store of a
   reference (heap_split_store_thunk, gc_kind_store_thunk), and the
   three transfers that the update leaves are TH_trans, over HOL4's
   v_inv_Thunk_insert and dest_thunk_insert_Thunk *)

let heap_split_store_thunk = prove
 (`heap_split k heap = SOME (h1,h2) /\
   heap_lookup p heap = SOME (ThunkBlock m y) /\
   ~(p < k) /\
   heap_store p [ThunkBlock ev r] heap = (heap2,T) /\
   EVERY isRef h2
   ==> (?h3. heap_split k heap2 = SOME (h1,h3) /\ EVERY isRef h3)`,
  STRIP_TAC THEN
  (* the heap is its two halves, and the first is of the length *)
  FIRST_ASSUM (fun hs ->
    if not (is_eq (concl hs)) ||
       not (hd_is "heap_split" (lhand (concl hs))) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_split_heap_length hs)) THEN
  FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (hd_is "APPEND" (lhand c)) ||
       not (is_var (rand c)) then fail() else
    SUBST_ALL_TAC (SYM e)) THEN
  (* so the element written is in the second half *)
  FIRST_X_ASSUM (fun hl ->
    let c = concl hl in
    if not (is_eq c) || not (hd_is "heap_lookup" (lhand c))
    then fail() else
    ASSUME_TAC (REWRITE_RULE[heap_lookup_APPEND] hl)) THEN
  ASM_FS_TAC THEN
  (* and the second half splits there *)
  W(fun gl ->
    let hl2 = the_asm (fun c -> is_eq c &&
                hd_is "heap_lookup" (lhand c) &&
                hd_is "SOME" (rand c)) gl in
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl2)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (lhand c)) then fail() else
    SUBST_ALL_TAC e)) THEN
  (* the address written is the length of what lies before it *)
  W(fun gl ->
    let e = the_asm (fun c -> is_eq c &&
              hd_is "-" (lhand c) &&
              hd_is "heap_length" (rand c)) gl in
    let ha = rand (rand (concl e)) in
    let hl1 = the_asm (fun c -> is_eq c &&
                hd_is "heap_length" (lhand c) &&
                not (hd_is "APPEND" (rand (lhand c)))) gl in
    let h1 = rand (lhand (concl hl1)) in
    let p = lhand (lhand (concl e)) in
    SUBGOAL_THEN (mk_eq (p, list_mk_icomb "heap_length"
                              [list_mk_icomb "APPEND" [h1; ha]]))
      ASSUME_TAC THENL
     [REWRITE_TAC[heap_length_APPEND] THEN ASM_ARITH_TAC;
      ALL_TAC]) THEN
  FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (lhand c)) ||
       not (hd_is "heap_length" (rand c)) then fail() else
    SUBST_ALL_TAC e) THEN
  (* so the store writes the new element in the middle *)
  RULE_ASSUM_TRY (REWRITE_RULE[APPEND_ASSOC]) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[heap_store_lemma; PAIR_EQ]) THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (rand c)) ||
       not (hd_is "APPEND" (lhand c)) then fail() else
    SUBST_ALL_TAC (SYM e))) THEN
  (* so the split of the new heap keeps the first half *)
  REWRITE_TAC[GSYM APPEND_ASSOC] THEN
  W(fun gl ->
    let e = the_asm (fun c -> is_eq c &&
              hd_is "heap_length" (lhand c) &&
              is_var (rand (lhand c)) && is_var (rand c)) gl in
    ONCE_REWRITE_TAC[SYM e]) THEN
  REWRITE_TAC[heap_split_length] THEN
  W(fun (asl,w) ->
    let bod = snd (strip_exists w) in
    let sm = rand (lhand (hd (conjuncts bod))) in
    EXISTS_TAC (rand sm)) THEN
  REWRITE_TAC[] THEN
  (* and the second half is the old one with the new element *)
  RULE_ASSUM_TRY (REWRITE_RULE[ALL_APPEND; ALL]) THEN
  REWRITE_TAC[ALL_APPEND; ALL] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[isRef_def; ThunkBlock_def] THEN
  MATCH_REDUCE_TAC THEN
  REWRITE_TAC[isMutTag_def] THEN MESON_TAC[]);;

(* and so the kind of the collection survives the store *)

let gc_kind_store_thunk = prove
 (cake_as_vars (fun () ->
    `gc_kind_inv conf a sp sp1 gens heap /\
     heap_store p [ThunkBlock ev r] heap = (heap2,T) /\
     heap_lookup p heap = SOME (ThunkBlock m y)
     ==> gc_kind_inv conf a sp sp1 gens heap2`),
  REWRITE_TAC[gc_kind_inv_def] THEN STRIP_TAC THEN
  W(fun (asl,w) ->
    CASES_ON_TAC (find_term
      (hd_is "data_to_word_config_gc_kind") w)) THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
  MATCH_REDUCE_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  SPLIT_ASM_TAC THEN
  FIRST_X_ASSUM (fun ex ->
    if not (is_exists (concl ex)) then fail() else
    STRIP_ASSUME_TAC ex) THEN
  (* a RefBlock is a reference, so the element written is not in
     the half of the split that holds none *)
  W(fun (asl,w as gl) ->
    let hs = the_asm (fun c -> is_eq c &&
               hd_is "heap_split" (lhand c)) gl in
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    let k = el 0 (snd (strip_comb (lhand (concl hs)))) in
    let p = el 0 (snd (strip_comb (lhand (concl hl)))) in
    SUBGOAL_THEN (mk_neg (mk_binop `(<):num->num->bool` p k))
      ASSUME_TAC THENL
     [DISCH_TAC THEN
      MP_TAC (MATCH_MP heap_lookup_heap_split (CONJ hs hl)) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      W(fun (asl,w as gl) ->
        let m = the_asm (hd_is "MEM") gl in
        let ev = the_asm (fun c -> hd_is "ALL" c &&
                   el 1 (snd (strip_comb c)) = rand (concl m)) gl in
        MP_TAC (MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev) m)) THEN
      REWRITE_TAC[isRef_def; ThunkBlock_def] THEN
      MATCH_REDUCE_TAC THEN
      REWRITE_TAC[isMutTag_def] THEN MESON_TAC[];
      ALL_TAC]) THEN
  CONJ_TAC THENL
   [(* the generation state: the store is above the nursery *)
    W(fun gl ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let gs = the_asm (hd_is "gen_state_ok") gl in
      let p = el 0 (snd (strip_comb (lhand (concl st)))) in
      let a = el 0 (snd (strip_comb (concl gs))) in
      SUBGOAL_THEN (mk_binop `(<=):num->num->bool` a p)
        (fun le -> MATCH_ACCEPT_TAC
          (MATCH_MP update_thunk_gen_state_ok
            (CONJ st (CONJ le gs)))) THEN
      POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (filter
        (fun t -> let c = concl t in
           hd_is "<" c || (is_neg c && hd_is "<" (rand c)) ||
           hd_is "<=" c) l)) THEN
      ASM_ARITH_TAC);
    (* and the two halves of the new heap *)
    W(fun gl ->
      let hs = the_asm (fun c -> is_eq c &&
                 hd_is "heap_split" (lhand c)) gl in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c)) gl in
      let nlt = the_asm (fun c -> is_neg c && hd_is "<" (rand c)) gl in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let h2 = rand (rand (rand (concl hs))) in
      let ev = the_asm (fun c -> hd_is "ALL" c &&
                 el 1 (snd (strip_comb c)) = h2) gl in
      STRIP_ASSUME_TAC (MATCH_MP heap_split_store_thunk
        (CONJ hs (CONJ hl (CONJ nlt (CONJ st ev)))))) THEN
    W(fun gl ->
      let hs2 = the_asm (fun c -> is_eq c &&
                  hd_is "heap_split" (lhand c) &&
                  hd_is "SOME" (rand c)) gl in
      EXISTS_TAC (lhand (rand (rand (concl hs2)))) THEN
      EXISTS_TAC (rand (rand (rand (concl hs2))))) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* what the invariant says of the values of the stack, which it
   relates to the roots the other way round *)
let EVERY2_v_inv_update_stack = prove
 (cake_as_vars (fun () ->
    `(!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 refs2 (w2,f,tf,heap2)) /\
     (!v. MEM v vs ==> v IN all_vs refs2 stack') /\
     EVERY2 (\v x. v_inv conf v refs (x,f,tf,heap)) vs rs
     ==> EVERY2 (\v x. v_inv conf v refs2
           (x,f,DRESTRICT tf (all_ts refs2 stack'),heap2)) vs rs`),
  STRIP_TAC THEN
  MATCH_MP_TAC EVERY2_MEM_MONO THEN
  W(fun gl ->
    let old = the_asm (hd_is "ALL2") gl in
    EXISTS_TAC (el 0 (snd (strip_comb (concl old))))) THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    STRIP_TAC THEN
    W(fun gl ->
      let old = the_asm (hd_is "ALL2") gl in
      let len = MATCH_MP LIST_REL_LENGTH old in
      let mz = the_asm (fun c -> hd_is "MEM" c &&
                 hd_is "ZIP" (rand c)) gl in
      let mem = the_asm (fun c ->
                  length (fst (strip_forall c)) = 1) gl in
      let vi = the_asm (hd_is "v_inv") gl in
      let inn = MATCH_MP mem (MATCH_MP mem_zip_left (CONJ len mz)) in
      MATCH_ACCEPT_TAC (MATCH_MP v_inv_update_gen
        (CONJ (a_vtr gl) (CONJ vi inn))));
    FIRST_ASSUM ACCEPT_TAC]);;

(* HOL4 data_to_word_memoryProofScript.sml:4636-4640: the theorem
   that HOL4 states as the value of an ML expression, which is the
   lemma with the counter of the induction generalised away *)
let v_inv_Thunk_insert =
  let ckv,_ = dest_forall (concl v_inv_Thunk_insert_lemma) in
  GEN_ALL (DISCH_ALL (REWRITE_RULE[GSYM v_inv_eq]
    (GEN ckv (UNDISCH (SPEC_ALL v_inv_Thunk_insert_lemma)))));;

(* an insert of a thunk where a thunk that was not evaluated was
   leaves what a value says of a thunk: a value that said NotThunk
   is not a pointer to that reference *)
let dest_thunk_insert_Thunk = prove
 (cake_as_vars (fun () ->
    `dest_thunk w refs = NotThunk /\
     sptree_lookup ptr refs = SOME (bvlSem_Thunk NotEvaluated v)
     ==> dest_thunk w (insert ptr (Thunk ev h) refs) = NotThunk`),
  STRIP_TAC THEN
  CASES_ON_TAC (cake_as_vars (fun () -> `w:dataSem_v`)) THEN
  REWRITE_TAC[dataSem_dest_thunk_def] THEN
  MATCH_REDUCE_TAC THEN TRY (SOLVED (REWRITE_TAC[])) THEN
  ASM_CASES_TAC `a1:num = ptr` THENL
   [(* the reference written: the value did not say NotThunk *)
    FIRST_X_ASSUM (fun dt ->
      let c = concl dt in
      if not (is_eq c) ||
         not (hd_is "dataSem_dest_thunk" (lhand c)) then fail()
      else MP_TAC dt) THEN
    ASM_REWRITE_TAC[dataSem_dest_thunk_def] THEN
    REDUCE_MATCH_HARD THEN
    COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "dataSem_dest_thunk_ret"];
    (* another one: the references hold there what they held *)
    ASM_REWRITE_TAC[lookup_insert] THEN
    FIRST_X_ASSUM (fun dt ->
      let c = concl dt in
      if not (is_eq c) ||
         not (hd_is "dataSem_dest_thunk" (lhand c)) then fail()
      else MP_TAC dt) THEN
    REWRITE_TAC[dataSem_dest_thunk_def] THEN
    MATCH_REDUCE_TAC THEN REWRITE_TAC[]]);;

(* the three transfers that an insert of a thunk leaves *)
let TH_trans = prove
 (cake_as_vars (fun () ->
    `INJ (FAPPLY (f:(num,num)fmap)) (FDOM f)
       {a | isSomeDataElement (heap_lookup a heap)} /\
     ptr IN FDOM f /\
     sptree_lookup ptr refs = SOME (bvlSem_Thunk NotEvaluated v) /\
     heap_lookup (FAPPLY f ptr) heap =
       SOME (ThunkBlock NotEvaluated y) /\
     v_inv conf v refs (y,f,tf,heap) /\
     (ev = Evaluated ==> dest_thunk h refs = NotThunk) /\
     heap_store (FAPPLY f ptr) [ThunkBlock ev q] heap = (heap2,T) /\
     heap_lookup (FAPPLY f ptr) heap2 = SOME (ThunkBlock ev q) /\
     (!m x. ~(m = FAPPLY f ptr) /\ heap_lookup m heap = SOME x
            ==> heap_lookup m heap2 = SOME x) /\
     v_inv conf h refs (q,f,tf,heap)
     ==> (!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
                  ==> v_inv conf w1 (insert ptr (Thunk ev h) refs)
                        (w2,f,tf,heap2)) /\
         (!w. dest_thunk w refs = NotThunk
              ==> dest_thunk w (insert ptr (Thunk ev h) refs) =
                  NotThunk) /\
         (!m. ~(m = ptr)
              ==> sptree_lookup m (insert ptr (Thunk ev h) refs) =
                  sptree_lookup m refs)`),
  DISCH_THEN (fun hs ->
    REPEAT CONJ_TAC THENL
     [REPEAT GEN_TAC THEN
      DISCH_THEN (fun vi ->
        MATCH_ACCEPT_TAC (MATCH_MP v_inv_Thunk_insert (CONJ vi hs)));
      GEN_TAC THEN DISCH_THEN (fun dt ->
        MATCH_ACCEPT_TAC (MATCH_MP dest_thunk_insert_Thunk
          (CONJ dt (CONJUNCT1 (CONJUNCT2 (CONJUNCT2 hs))))));
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[lookup_insert]]));;

(* the invariant of the reference written when a thunk is updated:
   the element is the thunk stored, the value put in is the one of
   the stack, and that it says nothing of a thunk is what the
   update was given *)
let bc_ref_inv_update_thunk_at = prove
 (cake_as_vars (fun () ->
    `FLOOKUP (f:(num,num)fmap) ptr = SOME p /\
     heap_lookup p heap2 = SOME (ThunkBlock ev q) /\
     (ev = Evaluated ==> dest_thunk h refs = NotThunk) /\
     v_inv conf h refs (q,f,tf,heap) /\
     MEM h stack' /\
     (!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1 (insert ptr (Thunk ev h) refs)
                    (w2,f,tf,heap2)) /\
     (!w. dest_thunk w refs = NotThunk
          ==> dest_thunk w (insert ptr (Thunk ev h) refs) = NotThunk)
     ==> bc_ref_inv conf ptr (insert ptr (Thunk ev h) refs)
           (f,DRESTRICT tf
                (all_ts (insert ptr (Thunk ev h) refs) stack'),
            heap2,be')`),
  STRIP_TAC THEN
  (* the new references hold the thunk at the key *)
  W(fun (asl,w) ->
    let ins = find_term (hd_is "sptree_insert") w in
    let args = snd (strip_comb ins) in
    SUBGOAL_THEN
      (mk_eq (list_mk_icomb "sptree_lookup" [el 0 args; ins],
              list_mk_icomb "SOME" [el 1 args]))
      ASSUME_TAC THENL
     [REWRITE_TAC[lookup_insert]; ALL_TAC]) THEN
  (* which is the arm of a thunk *)
  W(fun (asl,w as gl) ->
    let lk1 = the_asm (fun c -> is_eq c &&
                hd_is "FLOOKUP" (lhand c)) gl in
    let ins = find_term (hd_is "sptree_insert") w in
    REWRITE_TAC[MATCH_MP arm_TH (CONJ lk1 (a_lkref ins gl))]) THEN
  (* the element stored, the thunk it says nothing of, and the
     value put in *)
  W(fun gl ->
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
    REPEAT CONJ_TAC THENL
     [ACCEPT_TAC hl;
      DISCH_THEN (fun ee ->
        W(fun gl ->
          let impl = the_asm (fun c -> is_imp c &&
                       (try hd_is "dataSem_dest_thunk"
                              (lhand (rand c))
                        with Failure _ -> false)) gl in
          ACCEPT_TAC (MATCH_MP (a_dtr gl) (MP impl ee))));
      W(fun (asl,w as gl) ->
        let vi = the_asm (hd_is "v_inv") gl in
        let mm = the_asm (hd_is "MEM") gl in
        let margs = snd (strip_comb (concl mm)) in
        let ins = lhand (find_term (hd_is "all_ts") w) in
        let inn = MP (SPECL [el 0 margs; el 1 margs; ins]
                        MEM_stack_all_vs) mm in
        MATCH_ACCEPT_TAC (MATCH_MP v_inv_update_gen
          (CONJ (a_vtr gl) (CONJ vi inn))))]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let update_thunk_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (h :: RefPtr F ptr :: stack) refs
                (roots,heap,be,a,sp,sp1,gens) limit ts /\
     (lookup ptr refs = SOME (Thunk NotEvaluated v)) /\
     (ev = Evaluated ==> dest_thunk h refs = NotThunk) ==>
       (?p r roots2 v1 heap2 u.
         (roots = r :: gc_shared_Pointer p u :: roots2) /\
         (thunk_deref p heap = SOME v1) /\
         (heap_store p [ThunkBlock ev r] heap = (heap2,T)) /\
         abs_ml_inv conf (h :: (RefPtr F ptr) :: stack)
           (insert ptr (Thunk ev h) refs)
           (roots,heap2,be,a,sp,sp1,gens) limit ts)`),
  (* the steps are above the statement and above update_ref_thm
     (tools/overrides.py).  The two roots in front of the rest are
     the root of the value and the address of the reference, which
     the relation of the pointer gives together with the thunk in
     the heap and the relation of its value; the store writes the
     new thunk into that element, and the heap and the references
     are then as good as they were.  Of the reference written the
     invariant is the thunk stored and of any other one its
     element, which the store did not touch *)
  (STRIP_TAC THEN
    (* what the invariant says of the stack with the thunk and the
       pointer on it *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    (* the roots are the two of the values in front and the rest *)
    SPLIT_ROOTS_TAC THEN SPLIT_ROOTS_TAC THEN
    (* and the root of the pointer is the address of its reference *)
    FIRST_ASSUM (fun vr ->
      let c = concl vr in
      if not (hd_is "v_inv" c) ||
         not (hd_is "dataSem_RefPtr" (el 1 (snd (strip_comb c))))
      then fail()
      else STRIP_ASSUME_TAC (REWRITE_RULE[v_inv_def] vr)) THEN
    (* of the three ways a pointer is related -- the reference is no
       thunk, it is one and the root is its address, or it is an
       evaluated one and the root is its value's -- only the second
       is left, because the reference holds a thunk that was not
       evaluated *)
    (let rws = distinctness "thunk_mode" :: ref_rws in
     RULE_ASSUM_TRY (REWRITE_RULE rws) THEN
     TRY (FIRST_ASSUM CONTR_TAC) THEN
     (* the reference is a thunk, so the first way is out *)
     TRY (SOLVED
           (W(fun gl ->
              let nt = the_asm (fun c ->
                         length (fst (strip_forall c)) = 2 &&
                         is_neg (snd (strip_forall c))) gl in
              let lk = the_asm (fun c -> is_eq c &&
                         hd_is "sptree_lookup" (lhand c) &&
                         hd_is "SOME" (rand c)) gl in
              let args = snd (strip_comb (rand (rand (concl lk)))) in
              CONTR_TAC (MP (NOT_ELIM
                (SPECL [el 0 args; el 1 args] nt)) lk)))) THEN
     (* and the two lookups of the key agree, which leaves the
        second way and puts the third out *)
     TRY (W(fun (asl,_) ->
       let lks = mapfilter (fun (_,th) ->
                   let c = concl th in
                   if is_eq c && hd_is "sptree_lookup" (lhand c) &&
                      hd_is "SOME" (rand c) then th else fail()) asl in
       if length lks < 2 then fail() else
       MP_TAC (TRANS (SYM (el 0 lks)) (el 1 lks)) THEN
       REWRITE_TAC (injectivity "option" ::
                    injectivity "bvlSem_ref" :: rws) THEN
       STRIP_TAC)) THEN
     SPLIT_ASM_TAC THEN
     TRY VAR_EQ_TAC) THEN
    (* the reference has an address *)
    (SUBGOAL_THEN (cake_as_vars (fun () ->
       `FLOOKUP (f:(num,num)fmap) (ptr:num) = SOME (FAPPLY f ptr:num)`))
       ASSUME_TAC THENL
      [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC]) THEN
    (* the root of the value on the stack and the element that the
       reference holds are what the pointer's relation gives: the
       thunk that was not evaluated is in the heap and its value is
       related (v_inv_def, the second of the three ways) *)
    (* the store of the new thunk into the element *)
    W(fun (asl,w as gl) ->
      let rts = lhand (hd (conjuncts (snd (strip_exists w)))) in
      let r = el 0 (snd (strip_comb rts)) in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 can (fun t -> hd_is "ThunkBlock" (rand t))
                   (rand c)) gl in
      let th0 = MATCH_MP heap_store_ThunkBlock hl in
      let hv = find_term (fun t -> is_var t &&
                 fst (dest_var t) = "h") (concl th0) in
      STRIP_ASSUME_TAC (INST [r,hv] th0)) THEN
    (* the witnesses: the root of the value, the address of the
       reference, the rest of the roots, the value the element held
       and the new heap *)
    W(fun (asl,w as gl) ->
      let rts = lhand (hd (conjuncts (snd (strip_exists w)))) in
      let rargs = snd (strip_comb rts) in
      let r = el 0 rargs in
      let targs = snd (strip_comb (el 1 rargs)) in
      let pargs = snd (strip_comb (el 0 targs)) in
      let p = el 0 pargs in
      let u = el 1 pargs in
      let roots2 = el 1 targs in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
      let h2 = lhand (rand (concl st)) in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 el 1 (snd (strip_comb (lhand c))) = heap &&
                 can (fun t -> hd_is "ThunkBlock" (rand t))
                   (rand c)) gl in
      let hlD = REWRITE_RULE[ThunkBlock_def] hl in
      let lst = el 0 (snd (strip_comb (rand (rand (concl hlD))))) in
      MAP_EVERY EXISTS_TAC [p; r; roots2; lst; h2; u]) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
    (* the value that the element held *)
    TRY (SOLVED
          (W(fun gl ->
             let st = the_asm (fun c -> is_eq c &&
                        hd_is "heap_store" (lhand c)) gl in
             let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
             let hl = the_asm (fun c -> is_eq c &&
                        hd_is "heap_lookup" (lhand c) &&
                        el 1 (snd (strip_comb (lhand c))) = heap &&
                        can (fun t -> hd_is "ThunkBlock" (rand t))
                          (rand c)) gl in
             REWRITE_TAC[thunk_deref_def; hl; ThunkBlock_def]) THEN
           MATCH_REDUCE_TAC THEN REWRITE_TAC[])) THEN
    (* and the invariant of the new heap and references *)
    REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
    (* the roots are the ones they were, of a heap as good *)
    TRY (SOLVED
          (W(fun gl ->
             let iso = the_asm (fun c ->
               let bd = snd (strip_forall c) in
               is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
             let ro = the_asm (hd_is "roots_ok") gl in
             ACCEPT_TAC (MATCH_MP roots_ok_iso (CONJ ro iso))))) THEN
    (* the heap is good: the pointer written is a root *)
    TRY (SOLVED
          (W(fun gl ->
             let ho = the_asm (hd_is "heap_ok") gl in
             let ro = REWRITE_RULE[roots_ok_def]
                        (the_asm (hd_is "roots_ok") gl) in
             let iso = the_asm (fun c ->
               let bd = snd (strip_forall c) in
               is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
             let hlen = the_asm (fun c -> is_eq c &&
                          hd_is "heap_length" (lhand c)) gl in
             let flt = the_asm (fun c -> is_eq c &&
                         hd_is "FILTER" (lhand c)) gl in
             let mm = REWRITE_RULE[ThunkBlock_def] (the_asm (fun c ->
                        let bd = snd (strip_forall c) in
                        is_imp bd && is_disj (rand bd)) gl) in
             let dj = hd (disjuncts
                        (rand (snd (strip_forall (concl mm))))) in
             let ws = el 0 (snd (strip_comb (rand dj))) in
             let vs,bd = strip_forall (concl ro) in
             let pw = list_mk_forall(vs,
                        mk_imp(list_mk_icomb "MEM"
                                 [lhand (lhand bd); ws], rand bd)) in
             SUBGOAL_THEN pw (fun pwt ->
               ACCEPT_TAC (MATCH_MP heap_ok_store_el
                 (CONJ ho (CONJ pwt (CONJ iso (CONJ hlen
                   (CONJ flt mm))))))) THEN
             MP_TAC ro THEN POP_ASSUM_LIST (K ALL_TAC) THEN
             REWRITE_TAC[MEM] THEN MESON_TAC[]))) THEN
    (* the kind of the collection survives the store *)
    TRY (SOLVED
          (W(fun gl ->
             let gk = the_asm (hd_is "gc_kind_inv") gl in
             let st = the_asm (fun c -> is_eq c &&
                        hd_is "heap_store" (lhand c)) gl in
             let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
             let hl = the_asm (fun c -> is_eq c &&
                        hd_is "heap_lookup" (lhand c) &&
                        el 1 (snd (strip_comb (lhand c))) = heap &&
                        can (fun t -> hd_is "ThunkBlock" (rand t))
                          (rand c)) gl in
             MATCH_ACCEPT_TAC (MATCH_MP gc_kind_store_thunk
               (CONJ gk (CONJ st hl)))))) THEN
    (* and the unused space is where it was: the unused element is
       not a data element, so it is not the thunk written *)
    TRY (SOLVED
          (W(fun gl ->
             let us = the_asm (hd_is "unused_space_inv") gl in
             let hlen = the_asm (fun c -> is_eq c &&
                          hd_is "heap_length" (lhand c)) gl in
             let st = the_asm (fun c -> is_eq c &&
                        hd_is "heap_store" (lhand c)) gl in
             let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
             let el2 = lhand (el 1 (snd (strip_comb
                         (lhand (concl st))))) in
             let hl = the_asm (fun c -> is_eq c &&
                        hd_is "heap_lookup" (lhand c) &&
                        el 1 (snd (strip_comb (lhand c))) = heap &&
                        can (fun t -> hd_is "ThunkBlock" (rand t))
                          (rand c)) gl in
             let el1 = rand (rand (concl hl)) in
             SUBGOAL_THEN (list_mk_icomb "isDataElement" [el1])
               (fun isd1 ->
                  SUBGOAL_THEN (list_mk_icomb "isDataElement" [el2])
                    (fun isd2 -> ACCEPT_TAC (MATCH_MP unused_store_el
                      (CONJ us (CONJ hlen (CONJ hl (CONJ isd1
                        (CONJ isd2 (CONJ (a_tr gl) st)))))))) THEN
                  REWRITE_TAC[isDataElement_def; ThunkBlock_def] THEN
                  MESON_TAC[]) THEN
             REWRITE_TAC[isDataElement_def; ThunkBlock_def] THEN
             MESON_TAC[]))) THEN
    (* the maps of the new invariant: the addresses are the ones they
       were, and the timestamps are cut to the ones of the new
       references and stack *)
    W(fun (asl,w as gl) ->
      if not (is_exists w) then ALL_TAC else
      (let sub p = rand (lhand (concl (the_asm (fun c ->
         hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
       let ats = find_term (hd_is "all_ts") w in
       EXISTS_TAC (sub "domain") THEN
       EXISTS_TAC (list_mk_icomb "DRESTRICT" [sub "all_ts"; ats]))) THEN
    REPEAT CONJ_TAC THEN TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the addresses of the maps are the ones of the old heap *)
    TRY (SOLVED
          (W(fun gl ->
             let iso = the_asm (fun c ->
               let bd = snd (strip_forall c) in
               is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
             ONCE_REWRITE_TAC[iso]) THEN
           FIRST [SOLVED (FIRST_ASSUM ACCEPT_TAC);
                  SOLVED (W(fun (asl,w as gl) ->
                    let dr = find_term (hd_is "DRESTRICT") w in
                    let inj = the_asm (fun c -> hd_is "INJ" c &&
                      rand (el 0 (snd (strip_comb c))) = lhand dr) gl in
                    MATCH_ACCEPT_TAC
                      (MATCH_MP INJ_DRESTRICT inj)))])) THEN
    (* the domain of the references has the key in it *)
    TRY (SOLVED
          (REWRITE_TAC[domain_insert] THEN
           MATCH_MP_TAC SUBSET_TRANS THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "domain" (rand c)) gl in
             EXISTS_TAC (rand (concl su))) THEN
           CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
           SET_TAC[])) THEN
    (* the timestamps of the restricted map are of the stack, and
       below the counter *)
    TRY (SOLVED
          (REWRITE_TAC[(CONJUNCT1 o SPEC_ALL) DRESTRICT_DEF] THEN
           FIRST [SOLVED (REWRITE_TAC[INTER_SUBSET]);
                  SOLVED (MATCH_MP_TAC SUBSET_TRANS THEN
                          W(fun gl ->
                            let su = the_asm (fun c ->
                              hd_is "SUBSET" c &&
                              hd_is "FDOM" (lhand c)) gl in
                            EXISTS_TAC (lhand (concl su))) THEN
                          CONJ_TAC THEN
                          TRY (FIRST_ASSUM ACCEPT_TAC) THEN
                          REWRITE_TAC[INTER_SUBSET])])) THEN
    (* the blocks of the stack stay unique *)
    TRY (SOLVED
          (W(fun gl ->
             let bu = the_asm (hd_is "blocks_unique") gl in
             MATCH_ACCEPT_TAC
               (MATCH_MP blocks_unique_update_thunk bu)))) THEN
    (* the transfers that the update of the thunk leaves: what the
       invariant says of a value, what a value says of a thunk, and
       what the references hold at another key (TH_trans) *)
    W(fun (asl,w as gl) ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 el 1 (snd (strip_comb (lhand c))) = heap &&
                 can (fun t -> hd_is "ThunkBlock" (rand t))
                   (rand c)) gl in
      let hl2 = the_asm (fun c -> is_eq c &&
                  hd_is "heap_lookup" (lhand c) &&
                  not (el 1 (snd (strip_comb (lhand c))) = heap) &&
                  can (fun t -> hd_is "ThunkBlock" (rand t))
                    (rand c)) gl in
      let y = el 1 (snd (strip_comb (rand (rand (concl hl))))) in
      let q = el 1 (snd (strip_comb (rand (rand (concl hl2))))) in
      let lk = the_asm (fun c -> is_eq c &&
                 hd_is "sptree_lookup" (lhand c) &&
                 not (hd_is "sptree_insert" (rand (lhand c)))) gl in
      let ptr = el 0 (snd (strip_comb (lhand (concl lk)))) in
      let fm = el 0 (snd (strip_comb (lhand (concl
                 (the_asm (fun c -> is_eq c &&
                    hd_is "FLOOKUP" (lhand c)) gl))))) in
      let inj = the_asm (fun c -> hd_is "INJ" c &&
                  rand (el 0 (snd (strip_comb c))) = fm) gl in
      let pin = the_asm (fun c -> hd_is "IN" c &&
                  hd_is "FDOM" (rand c) &&
                  el 0 (snd (strip_comb c)) = ptr) gl in
      let viy = the_asm (fun c -> hd_is "v_inv" c &&
                  el 0 (tparts (el 3 (snd (strip_comb c)))) = y) gl in
      let viq = the_asm (fun c -> hd_is "v_inv" c &&
                  el 0 (tparts (el 3 (snd (strip_comb c)))) = q) gl in
      let hv = el 1 (snd (strip_comb (concl viq))) in
      let dt = the_asm (fun c -> is_imp c &&
                 (try hd_is "dataSem_dest_thunk" (lhand (rand c)) &&
                      el 0 (snd (strip_comb (lhand (rand c)))) = hv
                  with Failure _ -> false)) gl in
      MAP_EVERY ASSUME_TAC (CONJUNCTS (MATCH_MP TH_trans
        (CONJ inj (CONJ pin (CONJ lk (CONJ hl (CONJ viy
          (CONJ dt (CONJ st (CONJ hl2
            (CONJ (a_tr gl) viq)))))))))))) THEN
    (* the values of the stack: the thunk's value and the pointer in
       front of it, and the rest *)
    W(fun (asl,w) -> if not (hd_is "ALL2" w) then ALL_TAC else
      (REWRITE_TAC[ALL2] THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       REPEAT CONJ_TAC THEN
       TRY (SOLVED
             (W(fun (asl,w as gl) ->
                let args = snd (strip_comb w) in
                let v1 = el 1 args in
                let ats = find_term (hd_is "all_ts") w in
                let vi = the_asm (fun c -> hd_is "v_inv" c &&
                           el 1 (snd (strip_comb c)) = v1 &&
                           not (el 2 (snd (strip_comb c)) =
                                  lhand ats)) gl in
                SUBGOAL_THEN
                  (list_mk_icomb "MEM" [v1; rand ats])
                  (fun mm -> MATCH_ACCEPT_TAC (MATCH_MP
                     v_inv_update_gen
                     (CONJ (a_vtr gl) (CONJ vi
                       (MP (SPECL [v1; rand ats; lhand ats]
                             MEM_stack_all_vs) mm))))) THEN
                REWRITE_TAC[MEM]))) THEN
       W(fun (asl,w as gl) ->
         let old = the_asm (fun c -> hd_is "ALL2" c &&
                     el 1 (snd (strip_comb c)) =
                       el 1 (snd (strip_comb w))) gl in
         let ats = find_term (hd_is "all_ts") w in
         let vs = el 1 (snd (strip_comb w)) in
         let v = genvar (hd (snd (dest_type (type_of (rand ats))))) in
         SUBGOAL_THEN
           (mk_forall(v, mk_imp(list_mk_icomb "MEM" [v; vs],
              list_mk_icomb "IN"
                [v; list_mk_icomb "all_vs" [lhand ats; rand ats]])))
           (fun mem -> ACCEPT_TAC (MATCH_MP EVERY2_v_inv_update_stack
              (CONJ (a_vtr gl) (CONJ mem old)))) THEN
         REPEAT STRIP_TAC THEN
         W(fun gl ->
           let mm = the_asm (hd_is "MEM") gl in
           let v1 = el 0 (snd (strip_comb (concl mm))) in
           SUBGOAL_THEN (list_mk_icomb "MEM" [v1; rand ats])
             (fun m2 -> MATCH_ACCEPT_TAC (MP (SPECL [v1; rand ats;
                          lhand ats] MEM_stack_all_vs) m2)) THEN
           ASM_REWRITE_TAC[MEM])))) THEN
    (* and the invariant of each reference that the stack reaches:
       it was reachable before the update
       (reachable_refs_Thunk_UPDATE) *)
    W(fun (asl,w) -> if not (is_forall w) then ALL_TAC else
      (REPEAT STRIP_TAC THEN
       W(fun gl ->
         let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                    hd_is "sptree_insert"
                      (el 1 (snd (strip_comb c)))) gl in
         ASSUME_TAC (MATCH_MP reachable_refs_Thunk_UPDATE rr)) THEN
       W(fun (asl,w as gl) ->
         let n = el 1 (snd (strip_comb w)) in
         let bri = the_asm (fun c ->
           let vs,bd = strip_forall c in
           length vs = 1 && is_imp bd &&
           hd_is "bc_ref_inv" (rand bd)) gl in
         let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
           not (hd_is "sptree_insert"
                  (el 1 (snd (strip_comb c))))) gl in
         let nin = the_asm (fun c -> hd_is "IN" c &&
           hd_is "FDOM" (rand c) &&
           el 0 (snd (strip_comb c)) = n) gl in
         ASSUME_TAC (MP (SPEC n bri) (CONJ rr nin))) THEN
       (* the reference written, or another one *)
       W(fun (asl,w as gl) ->
         ASM_CASES_TAC (mk_eq (el 1 (snd (strip_comb w)),
                               g_ptr gl))) THEN
       TRY VAR_EQ_TAC THEN
       (* the one written: the thunk that the update stored *)
       TRY (SOLVED
             (W(fun (asl,w as gl) ->
                let lk1 = the_asm (fun c -> is_eq c &&
                            hd_is "FLOOKUP" (lhand c)) gl in
                let p = rand (rand (concl lk1)) in
                let hl2 = the_asm (fun c -> is_eq c &&
                            hd_is "heap_lookup" (lhand c) &&
                            el 0 (snd (strip_comb (lhand c))) = p &&
                            can (fun t -> hd_is "ThunkBlock" (rand t))
                              (rand c)) gl in
                let q = el 1 (snd (strip_comb
                          (rand (rand (concl hl2))))) in
                let viq = the_asm (fun c -> hd_is "v_inv" c &&
                            el 0 (tparts (el 3 (snd (strip_comb c))))
                              = q) gl in
                let hv = el 1 (snd (strip_comb (concl viq))) in
                let dt = the_asm (fun c -> is_imp c &&
                           (try hd_is "dataSem_dest_thunk"
                                  (lhand (rand c)) &&
                                el 0 (snd (strip_comb
                                  (lhand (rand c)))) = hv
                            with Failure _ -> false)) gl in
                let ats = find_term (hd_is "all_ts") w in
                SUBGOAL_THEN (list_mk_icomb "MEM" [hv; rand ats])
                  (fun mm -> MATCH_ACCEPT_TAC (MATCH_MP
                     bc_ref_inv_update_thunk_at
                     (CONJ lk1 (CONJ hl2 (CONJ dt (CONJ viq
                       (CONJ mm (CONJ (a_vtr gl) (a_dtr gl))))))))) THEN
                REWRITE_TAC[MEM]))) THEN
       (* another one: its element did not move *)
       TRY (SOLVED
             (W(fun (asl,w as gl) ->
                let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
                let inj = the_asm (fun c -> hd_is "INJ" c &&
                            rand (el 0 (snd (strip_comb c))) = fm) gl in
                let pin = the_asm (fun c -> hd_is "IN" c &&
                            hd_is "FDOM" (rand c) &&
                            el 0 (snd (strip_comb c)) = g_ptr gl) gl in
                let neq = the_asm (fun c -> is_neg c &&
                            is_eq (rand c) &&
                            rand (rand c) = g_ptr gl) gl in
                let inv = the_asm (hd_is "bc_ref_inv") gl in
                MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_other_gen
                  (CONJ inj (CONJ pin (CONJ neq (CONJ (a_vtr gl)
                    (CONJ (a_dtr gl) (CONJ (a_ltr gl)
                      (CONJ (a_tr gl) inv))))))))))))) THEN
    ALL_TAC));;

(* ---- UpdateCons: writing the hole of an unfinalised MutBlock.  The cell is
   laid out as a BlockRep, so the heap-level machinery is the RefBlock/
   ThunkBlock machinery transposed to BlockRep.  What is new is that v_inv can
   read BlockRep cells, so rewriting one is only safe because no timestamp
   points at an unfinalised MutBlock -- exactly what bc_ref_inv records. *)

(* [local] *)
let heap_store_BlockRep_thm = prove
 (`!ha. (LENGTH x = LENGTH y) ==>
        (heap_store (heap_length ha) [BlockRep tag x] (ha ++
          (BlockRep tag y :: hb)) =
          (ha ++ (BlockRep tag x :: hb),T))`,
  (* as the store into a RefBlock above: heap_store_lemma stores at
     the length of the prefix and leaves the lengths to agree *)
  (let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   GEN_TAC THEN DISCH_TAC THEN
   REWRITE_TAC[heap_store_lemma; APPEND; PAIR_EQ; hlen_cl;
               BlockRep_def; el_length_def] THEN
   ASM_ARITH_TAC));;

(* [local] *)
let heap_lookup_BlockRep_lemma = prove
 (`(heap_lookup n (ha ++ (BlockRep tag y :: hb)) = SOME x) =
       (if n < heap_length ha then
         (heap_lookup n ha = SOME x) else if n = heap_length ha then
         (x = BlockRep tag y) else if heap_length ha + (LENGTH y + 1)
           <= n then
         (heap_lookup (n - heap_length ha - (LENGTH y + 1)) hb =
           SOME x) else F)`,
  (* where an address falls in a heap that a BlockRep splits: below
     the first part, at the element itself, or past the element,
     whose el_length is one more than the length of its list *)
  (let pick = W(fun (asl,w) ->
     ASM_CASES_TAC (el 0 (snd(strip_comb (rhs w))))) in
   let contra = SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC in
   pick THENL
    [ASM_SIMP_TAC[gen_gc_LESS_IMP_heap_lookup];
     ASM_SIMP_TAC[NOT_LESS_IMP_heap_lookup] THEN
     REWRITE_TAC[heap_lookup_def; BlockRep_def;
                 el_length_def] THEN
     pick THENL
      [ASM_REWRITE_TAC[SUB_REFL] THEN
       REWRITE_TAC[injectivity "option"] THEN
       MATCH_ACCEPT_TAC EQ_SYM_EQ;
       ASM_REWRITE_TAC[] THEN pick THEN ASM_REWRITE_TAC[] THENL
        [COND_CASES_TAC THENL [contra; ALL_TAC] THEN
         COND_CASES_TAC THENL [contra; ALL_TAC] THEN
         REWRITE_TAC[];
         COND_CASES_TAC THENL [contra; ALL_TAC] THEN
         COND_CASES_TAC THENL
          [REWRITE_TAC[distinctness "option"]; contra]]]]));;

(* [local] *)
let heap_store_BlockRep = prove
 (`(LENGTH y = LENGTH h) /\
   (heap_lookup n heap = SOME (BlockRep tag y)) ==>
   (?heap2. (heap_store n [BlockRep tag h] heap = (heap2,T)) /\
           (heap_lookup n heap2 = SOME (BlockRep tag h)) /\
           (heap_length heap2 = heap_length heap) /\
           (FILTER isForwardPointer heap2 = FILTER isForwardPointer
             heap) /\
           (!xs l d.
              MEM (DataElement xs l d) heap2 ==>
                (DataElement xs l d = BlockRep tag h) \/
                MEM (DataElement xs l d) heap) /\
           (!a. isSomeDataElement (heap_lookup a heap2) =
                isSomeDataElement (heap_lookup a heap)) /\
           (!m x. ~(m = n) /\ (heap_lookup m heap = SOME x) ==>
                 (heap_lookup m heap2 = SOME x)))`,
  (* a store into a BlockRep: as the store into a RefBlock above,
     with heap_store_BlockRep_thm and heap_lookup_BlockRep_lemma,
     and without the RefBlock_inv *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    (* the clauses of heap_length *)
    let hlen_cl = prove
     (`heap_length [] = 0 /\
       (!x xs. heap_length (CONS x xs) = el_length x + heap_length xs)`,
      REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    FIRST_ASSUM(fun hl ->
      MP_TAC(MATCH_MP heap_lookup_SPLIT hl)) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "APPEND" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "heap_length" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    W(fun (asl,w) ->
      let hs = find_term (hd_is "heap_store") (snd(strip_exists w)) in
      let args = snd(strip_comb hs) in
      let nb = lhand (el 1 args) in
      let hp = el 2 args in
      let ap = rator (rator hp) in
      let rest = rand hp in
      let cs = rator (rator rest) in
      EXISTS_TAC (mk_comb(mk_comb(ap,lhand hp),
                          mk_comb(mk_comb(cs,nb),rand rest)))) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC heap_store_BlockRep_thm THEN
      FIRST_ASSUM(ACCEPT_TAC o SYM);
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_lookup_BlockRep_lemma; LT_REFL];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[heap_length_APPEND; hlen_cl;
                  BlockRep_def; el_length_def] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[FILTER_APPEND; FILTER; isForwardPointer_def;
                  BlockRep_def] THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [REWRITE_TAC[MEM_APPEND; MEM] THEN MESON_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [GEN_TAC THEN
      REWRITE_TAC[isSomeDataElement_def] THEN
      REWRITE_TAC[heap_lookup_BlockRep_lemma] THEN
      ASM_REWRITE_TAC[] THEN
      REPEAT COND_CASES_TAC THEN
      REWRITE_TAC[BlockRep_def] THEN MESON_TAC[];
      ALL_TAC] THEN
    REPEAT GEN_TAC THEN
    REWRITE_TAC[heap_lookup_BlockRep_lemma] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]));;

(* v_inv survives an in-place rewrite of a BlockRep cell that no timestamp
   points at: Bignum/Word64Rep/ThunkBlock cells cannot be that cell because
   their tags differ, and a Block's cell is in the range of tf *)
(* [local] *)
let v_inv_BlockRep_upd_lemma = prove
 (`!ck conf v1 refs x f tf heap heap2 p tag zs.
     v_inv conf v1 refs (x,f,tf,heap) /\
     heap_lookup p heap = SOME (BlockRep tag zs) /\
     (!t. t IN FDOM tf ==> ~(FAPPLY tf t = p)) /\
     (!m y. ~(m = p) /\ heap_lookup m heap = SOME y ==> heap_lookup m
       heap2 = SOME y) ==>
       v_inv_ck ck conf v1 refs (x,f,tf,heap2)`,
  (* the refs do not change and the heap does: every lookup of the
     old heap that the relation makes is a lookup away from p, so
     the hypothesis about the two heaps carries it over.  Away from
     p because the element at p is a BlockRep: of a Block the
     pointer is one that tf gives, which the hypothesis about tf
     keeps off p, and of anything else the shape of the element
     settles it *)
  (let flk = prove
    (`!f x y. FLOOKUP f x = SOME y ==> x IN FDOM f /\ FAPPLY f x = y`,
     REWRITE_TAC[FLOOKUP_DEF] THEN REPEAT GEN_TAC THEN
     COND_CASES_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[]) in
   let notp =
     FIRST
      [FIRST_ASSUM(fun fl ->
         let fd = MATCH_MP flk fl in
         FIRST_ASSUM(fun tfc ->
           ACCEPT_TAC(REWRITE_RULE[CONJUNCT2 fd]
             (MATCH_MP tfc (CONJUNCT1 fd)))));
       DISCH_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
       FIRST_ASSUM(fun blk ->
         if not (hd_is "BlockRep" (rand(rhs(concl blk)))) then fail()
         else FIRST_ASSUM(fun l ->
           if concl l = concl blk then fail() else
           MP_TAC(TRANS (SYM l) blk))) THEN
       REWRITE_TAC[injectivity "option"; BlockRep_def; bignum_def;
                   Word64Rep_def; ThunkBlock_def] THEN
       TRY PAIRARG_TAC THEN
       CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
       TRY COND_CASES_TAC THEN
       REWRITE_TAC[injectivity "heap_element"; PAIR_EQ;
                   distinctness "data_to_word_memoryProof_tag"]] in
   (* a lookup of the old heap is one of the new heap, away from p *)
   let hp =
     FIRST_ASSUM(fun pres ->
       MATCH_MP_TAC pres THEN CONJ_TAC THENL
        [notp; FIRST_ASSUM MATCH_ACCEPT_TAC]) in
   (* the hypothesis about the heaps, conjunct by conjunct *)
   let prep =
     FIRST_ASSUM(fun ds ->
       if is_conj (concl ds) then MAP_EVERY ASSUME_TAC (CONJUNCTS ds)
       else fail()) in
   V_INV_REFS_TAC prep hp V_INV_HEAP_PLAIN
     (V_INV_HEAP_THUNK hp 5) (V_INV_HEAP_THUNK hp 6)));;

(* the binders are renamed apart from the names used at the application sites,
   so that qexists can name the witnesses *)
(* HOL4 data_to_word_memoryProofScript.sml:5514-5518: a theorem that
   HOL4 states as the value of an ML expression: v_inv_BlockRep_upd *)

(* v_inv cannot see what sits in a MutBlock's hole, only how long the two
   sides of it are *)
(* [local] *)
let v_inv_MutBlock_hole_lemma = prove
 (`!ck v1 refs y f tf heap.
     v_inv conf v1 refs (y,f,tf,heap) /\
     lookup ptr refs = SOME (bvlSem_MutBlock tag fin1 ll cv1 rr) ==>
       v_inv_ck ck conf v1 (insert ptr (bvlSem_MutBlock tag fin2 ll
         cv2 rr) refs)
         (y,f,tf,heap)`,
  (* and the same where what sits in the hole changes as well: the
     annotation counts the two sides of the hole and not what is in
     it *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let same = prove
    (`lookup ptr refs = SOME (bvlSem_MutBlock tag fin1 ll cv1 rr) ==>
      (!k ev v.
         lookup k (insert ptr (bvlSem_MutBlock tag fin2 ll cv2 rr)
           refs) = SOME (Thunk ev v) <=>
         lookup k refs = SOME (Thunk ev v)) /\
      (!k. ref_ptr_annot conf
             (lookup k (insert ptr
               (bvlSem_MutBlock tag fin2 ll cv2 rr) refs)) =
           ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v (insert ptr
             (bvlSem_MutBlock tag fin2 ll cv2 rr) refs) =
           dest_thunk v refs) /\
      (!k bb.
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (bvlSem_MutBlock tag fin2 ll cv2 rr)
              refs) = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
                ==> ~bb))`,
     DISCH_TAC THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs);
       GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
       COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[ref_ptr_annot_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[];
       REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
       (REWRITE_TAC[lookup_insert] THEN COND_CASES_TAC THENL
         [FIRST_X_ASSUM SUBST_ALL_TAC THEN
          DISCH_THEN(K ALL_TAC) THEN
          FIRST_ASSUM(fun a -> FIRST_ASSUM(fun lk ->
            ACCEPT_TAC(MATCH_MP a lk)));
          FIRST_ASSUM MATCH_ACCEPT_TAC])])) in
   V_INV_REFS_TAC ALL_TAC ALL_TAC (V_INV_REFS_PLAIN same)
     (V_INV_REFS_THUNK same 5) (V_INV_REFS_THUNK same 6)));;

(* [local] *)
let v_inv_MutBlock_hole = prove
 (`!cnf vv rfs yy ff tff hp pp tg b1 b2 l1 c1 c2 r1.
     v_inv cnf vv rfs (yy,ff,tff,hp) /\
     lookup pp rfs = SOME (bvlSem_MutBlock tg b1 l1 c1 r1) ==>
       v_inv cnf vv (insert pp (bvlSem_MutBlock tg b2 l1 c2 r1)
         rfs) (yy,ff,tff,hp)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_MutBlock_hole_lemma]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_update_mutblock = prove
 (cake_as_vars (fun () ->
    `lookup ptr refs = SOME (bvlSem_MutBlock tag fin l cv r) /\
     blocks_unique ts (all_vs refs (h :: RefPtr F ptr :: stack))
       ==>
       blocks_unique ts
         (all_vs (insert ptr (bvlSem_MutBlock tag fin l h r) refs)
                 (h :: RefPtr F ptr :: stack))`),
  (* the elements of the updated reference are among the ones of
     the old store, so what was unique there stays unique: the
     block that the update puts in has its head and its tail in
     the elements of the store it replaces *)
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   let lk_ins = prove
    (`!n p (y:(dataSem_v)bvlSem_ref) rfs z.
        lookup n (insert p y rfs) = SOME z <=>
        (n = p /\ y = z) \/ (~(n = p) /\ lookup n rfs = SOME z)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"; distinctness "option"] THEN
     CONV_TAC TAUT) in
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   REWRITE_TAC[blocks_unique_def] THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
   W(fun (asl,w) ->
     let gel = el 0 (snd(strip_comb w)) in
     FIRST_ASSUM(fun inm ->
       let c = concl inm in
       if not (hd_is "IN" c) || not (el 0 (snd(strip_comb c)) = gel)
       then fail() else
       FIRST_ASSUM(fun lk ->
         if not (hd_is "=" (concl lk)) then fail() else
         MP_TAC(REWRITE_RULE[all_vs_def; IN_UNION; IN_ELIM_THM;
                             lk_ins; v_all_vs_append; MEM_APPEND;
                             injectivity "bvlSem_ref";
                             distinctness "bvlSem_ref"]
                  (ONCE_REWRITE_RULE[cons_app] inm)) THEN
         MP_TAC lk THEN
         REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM;
                     v_all_vs_append; MEM_APPEND] THEN
         MESON_TAC[MEM_v_all_vs_extend_tl;
                   MEM_v_all_vs_extend_hd])))));;

(* [local] *)
let ref_edge_MutBlock_UPDATE = prove
 (`lookup ptr refs = SOME (bvlSem_MutBlock tg fin ll cc rr) /\
   ref_edge (insert ptr (bvlSem_MutBlock tg fin ll h rr) refs) r1 z
     /\
   ~(MEM z (get_refs h)) ==> ref_edge refs r1 z`,
  (* the edge of the updated reference is an edge of the old one:
     the payload of the MutBlock differs in the hole only, and the
     element of the hole is not z *)
  (let flat_app = prove
    (`!(l1:((A)list)list) l2.
        FLAT (APPEND l1 l2) = APPEND (FLAT l1) (FLAT l2)`,
     LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[FLAT; APPEND; APPEND_ASSOC]) in
   let mem_refs = prove
    (`!z ll a rr.
        MEM z (get_refs (Block 0 ARB (APPEND ll (APPEND [a] rr)))) <=>
        MEM z (get_refs (Block 0 ARB ll)) \/ MEM z (get_refs a) \/
        MEM z (get_refs (Block 0 ARB rr))`,
     REWRITE_TAC[get_refs_def; MAP_APPEND; MAP; flat_app;
                 FLAT; MEM_APPEND; APPEND_NIL]) in
   let swap_refs = prove
    (`!z ll a b rr.
        MEM z (get_refs (Block 0 ARB (APPEND ll (APPEND [a] rr)))) /\
        ~MEM z (get_refs a)
        ==> MEM z (get_refs (Block 0 ARB (APPEND ll
                                           (APPEND [b] rr))))`,
     REWRITE_TAC[mem_refs] THEN MESON_TAC[]) in
   REWRITE_TAC[ref_edge_MutBlock] THEN COND_CASES_TAC THEN
   REPEAT STRIP_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
   SUBGOAL_THEN
     `sptree_lookup r1 (refs:(dataSem_v bvlSem_ref) spt) =
      SOME (bvlSem_MutBlock tg fin ll cc rr)`
     (fun th -> ONCE_REWRITE_TAC[ref_edge_def] THEN
                REWRITE_TAC[th]) THENL
    [ASM_MESON_TAC[]; ALL_TAC] THEN
   MATCH_REDUCE_TAC THEN
   FIRST_ASSUM(fun th1 -> FIRST_ASSUM(fun th2 ->
     MATCH_ACCEPT_TAC(MATCH_MP swap_refs (CONJ th1 th2))))));;

(* the only new edges out of ptr land in the value that was written, which is
   itself on the stack *)
(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let reachable_refs_MutBlock_UPDATE = prove
 (cake_as_vars (fun () ->
    `lookup ptr refs = SOME (bvlSem_MutBlock tg fin ll cc rr) /\
     reachable_refs (h :: RefPtr b ptr :: stack)
                    (insert ptr (bvlSem_MutBlock tg fin ll h rr)
                      refs) n ==>
       reachable_refs (h :: RefPtr b ptr :: stack) refs n`),
  (* the update replaces the centre of the MutBlock by h,
     which is the root at the front of the stack: a path
     through the new references is one through the old ones
     unless it leaves ptr into h, and then it starts at a
     root of its own *)
  ((* the head constant of a term, by name *)
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let mem_block_refs = prove
   (`!(ys:(dataSem_v)list) ss tt aa.
       MEM ss (get_refs (Block tt aa ys))
       ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
    REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
    MESON_TAC[]) in
  let block_refs = prove
   (`!(ys:(dataSem_v)list) ss tt aa yy.
       MEM yy ys /\ MEM ss (get_refs yy)
       ==> MEM ss (get_refs (Block tt aa ys))`,
    REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
    MESON_TAC[]) in
  (* an edge that leaves ptr in the old references *)
  let oldedge = prove
   (`lookup ptr refs = SOME (bvlSem_MutBlock tg fin ll cc rr) /\
     MEM (s:num) (get_refs (Block 0 ARB (ll ++ [cc] ++ rr)))
     ==> ref_edge refs ptr (s:num)`,
    REWRITE_TAC[ref_edge_def] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
    ASM_REWRITE_TAC[]) in
  (* a path through the new references is one through the old ones,
     or it leaves ptr into h -- and h is a root of its own *)
  let rtcpath = prove
   (`lookup ptr refs = SOME (bvlSem_MutBlock tg fin ll cc rr)
     ==> !u w. RTC (ref_edge (insert ptr
                 (bvlSem_MutBlock tg fin ll h rr) refs)) u w
               ==> RTC (ref_edge refs) u w \/
                   (?s. MEM s (get_refs h) /\
                        RTC (ref_edge refs) s w)`,
    DISCH_TAC THEN MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
     [GEN_TAC THEN DISJ1_TAC THEN
      MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
      MAP_EVERY X_GEN_TAC [`u:num`; `v:num`; `w:num`] THEN
      REWRITE_TAC[ref_edge_MutBlock] THEN
      COND_CASES_TAC THEN STRIP_TAC THEN
      (* the induction hypothesis gives the right half already *)
      TRY(DISJ2_TAC THEN EXISTS_TAC `s:num` THEN
          ASM_REWRITE_TAC[] THEN NO_TAC) THEN
      (* an edge that does not leave ptr is an old edge *)
      TRY(DISJ1_TAC THEN
          MATCH_MP_TAC(CONJUNCT2(SPEC_ALL RTC_RULES)) THEN
          EXISTS_TAC `v:num` THEN ASM_REWRITE_TAC[] THEN NO_TAC) THEN
      FIRST_ASSUM(fun m -> MP_TAC(MATCH_MP mem_block_refs m)) THEN
      DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v` STRIP_ASSUME_TAC) THEN
      FIRST_X_ASSUM(fun mm ->
        if hd_is "MEM" (concl mm) && hd_is "APPEND" (rand (concl mm))
        then MP_TAC(REWRITE_RULE[MEM_APPEND; MEM] mm) else fail()) THEN
      STRIP_TAC THEN
      (* it lands in h, which is a root *)
      TRY(DISJ2_TAC THEN EXISTS_TAC `v:num` THEN
          FIRST_X_ASSUM(fun eq ->
            if is_eq (concl eq) && is_var (lhs (concl eq)) &&
               is_var (rhs (concl eq))
            then SUBST_ALL_TAC eq else fail()) THEN
          ASM_REWRITE_TAC[] THEN NO_TAC) THEN
      (* or in a part that the old payload has too *)
      DISJ1_TAC THEN
      MATCH_MP_TAC(CONJUNCT2(SPEC_ALL RTC_RULES)) THEN
      EXISTS_TAC `v:num` THEN CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MATCH_MP_TAC oldedge THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC block_refs THEN EXISTS_TAC `yy:dataSem_v` THEN
      ASM_REWRITE_TAC[MEM_APPEND; MEM]]) in
  DISCH_THEN(CONJUNCTS_THEN2 (fun lk ->
      ASSUME_TAC lk THEN ASSUME_TAC(MATCH_MP rtcpath lk)) MP_TAC) THEN
  REWRITE_TAC[reachable_refs_def] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:dataSem_v`
    (X_CHOOSE_THEN `r:num` STRIP_ASSUME_TAC)) THEN
  FIRST_ASSUM(fun pth ->
    if not (is_forall (concl pth)) then fail() else
    FIRST_ASSUM(fun rtc -> MP_TAC(MATCH_MP (SPEC_ALL pth) rtc))) THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (fun old ->
       MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
       ASM_REWRITE_TAC[old])
    (X_CHOOSE_THEN `s:num` STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`h:dataSem_v`; `s:num`] THEN
  ASM_REWRITE_TAC[MEM]));;

(* mirrors update_thunk_thm: the hole is rewritten in place, so f and the heap
   layout are untouched and only tf shrinks *)
(* the port's own: what the proof of update_mutblock_thm adds to
   the block above update_ref_thm.  The update fills the hole of a
   mutable block, so the store writes a BlockRep where one was and
   the three transfers it leaves are MB_trans, over HOL4's
   v_inv_BlockRep_upd (which asks that no timestamp points at the
   cell, which the arm of an unfinalised block gives) and
   v_inv_MutBlock_hole; of the kind of the collection there is
   nothing to say, because such a block is not in a heap that a
   generational collection goes through (gc_kind_not_gen) *)

(* a cell that no timestamp has is not the value of the map *)
let IMAGE_NOT_point = prove
 (`!(tf:(A,B)fmap) p. ~(p IN IMAGE (FAPPLY tf) (FDOM tf))
                      ==> (!t. t IN FDOM tf ==> ~(FAPPLY tf t = p))`,
  REWRITE_TAC[IN_IMAGE] THEN MESON_TAC[]);;

(* a heap that no generational collection goes through says no more
   of the kind of the collection than the unused space, which a
   store does not touch *)
let gc_kind_not_gen = prove
 (cake_as_vars (fun () ->
    `gc_kind_inv conf a sp sp1 gens heap /\
     (!gs. ~(data_to_word_config_gc_kind conf =
             data_to_word_Generational gs))
     ==> gc_kind_inv conf a sp sp1 gens heap2`),
  REWRITE_TAC[gc_kind_inv_def] THEN STRIP_TAC THEN
  W(fun (asl,w) ->
    CASES_ON_TAC (find_term
      (hd_is "data_to_word_config_gc_kind") w)) THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
  MATCH_REDUCE_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  (* the case of a generational collection is out: the kind of this
     one is not that, and the case analysis put the kind into the
     assumption that says so *)
  W(fun gl ->
    let ng = the_asm (fun c ->
               let vs,bd = strip_forall c in
               length vs = 1 && is_neg bd) gl in
    MP_TAC ng) THEN
  MESON_TAC[]);;

(* HOL4 data_to_word_memoryProofScript.sml: the theorem that HOL4
   states as the value of an ML expression, which is the lemma with
   the counter of the induction generalised away *)
let v_inv_BlockRep_upd =
  let ckv,_ = dest_forall (concl v_inv_BlockRep_upd_lemma) in
  GEN_ALL (DISCH_ALL (REWRITE_RULE[GSYM v_inv_eq]
    (GEN ckv (UNDISCH (SPEC_ALL v_inv_BlockRep_upd_lemma)))));;

(* an insert of a mutable block where one was leaves what a value
   says of a thunk *)
let dest_thunk_insert_MutBlock = prove
 (cake_as_vars (fun () ->
    `sptree_lookup ptr refs = SOME (bvlSem_MutBlock tag fin l cv r)
     ==> dest_thunk v (insert ptr (MutBlock tag fin2 l h r) refs) =
         dest_thunk v refs`),
  STRIP_TAC THEN
  CASES_ON_TAC (cake_as_vars (fun () -> `v:dataSem_v`)) THEN
  REWRITE_TAC[dataSem_dest_thunk_def] THEN
  MATCH_REDUCE_TAC THEN TRY (SOLVED (REWRITE_TAC[])) THEN
  ASM_CASES_TAC `a1:num = ptr` THEN
  ASM_REWRITE_TAC[lookup_insert] THEN
  (let ds = [distinctness "option"; distinctness "bvlSem_ref"] in
   REWRITE_TAC (injectivity "option" :: ds @ map GSYM ds)) THEN
  CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN
  REWRITE_TAC[SELECT_REFL; EXISTS_UNIQUE_REFL] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

(* the pointers of the element that an update of one value writes:
   the pointer put in, or one that the element had *)
let ptrs_store_el = prove
 (`heap_ok heap limit' /\
   (!pt u. w = gc_shared_Pointer pt u
           ==> isSomeDataElement (heap_lookup pt heap)) /\
   heap_lookup p heap = SOME (DataElement zs l2 d2)
   ==> (!pt u. MEM (gc_shared_Pointer pt u) (LUPDATE w i zs)
               ==> isSomeDataElement (heap_lookup pt heap))`,
  REWRITE_TAC[heap_ok_def] THEN STRIP_TAC THEN
  SPLIT_ASM_TAC THEN
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM (fun m ->
    if not (hd_is "MEM" (concl m)) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP MEM_LUPDATE_E m)) THENL
   [(* the pointer written *)
    W(fun gl ->
      let pw = the_asm (fun c ->
                 let vs,bd = strip_forall c in
                 length vs = 2 && is_imp bd &&
                 hd_is "isSomeDataElement" (rand bd)) gl in
      let eq = the_asm (fun c -> is_eq c &&
                 hd_is "gc_shared_Pointer" (lhand c)) gl in
      ACCEPT_TAC (MATCH_MP pw (SYM eq)));
    (* a pointer of the element, which was in a good heap *)
    W(fun gl ->
      let ho = the_asm (fun c ->
        length (fst (strip_forall c)) = 5) gl in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c)) gl in
      let md = MATCH_MP heap_lookup_MEM hl in
      let mp = the_asm (fun c -> hd_is "MEM" c &&
                 hd_is "gc_shared_Pointer"
                   (el 0 (snd (strip_comb c)))) gl in
      ACCEPT_TAC (MATCH_MP ho (CONJ md mp)))]);;

(* the three transfers that an update of the hole of a mutable
   block leaves: over the heap (v_inv_BlockRep_upd, which asks that
   no timestamp points at the cell) and over the references
   (v_inv_MutBlock_hole) *)
let MB_trans = prove
 (cake_as_vars (fun () ->
    `heap_lookup p heap = SOME (BlockRep tag zs) /\
     (!t. t IN FDOM (tf:(num,num)fmap) ==> ~(FAPPLY tf t = p)) /\
     (!m y. ~(m = p) /\ heap_lookup m heap = SOME y
            ==> heap_lookup m heap2 = SOME y) /\
     sptree_lookup ptr refs = SOME (bvlSem_MutBlock tag2 fin l cv r)
     ==> (!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
                  ==> v_inv conf w1
                        (insert ptr (MutBlock tag2 fin2 l h r) refs)
                        (w2,f,tf,heap2)) /\
         (!w. dest_thunk w refs = NotThunk
              ==> dest_thunk w (insert ptr
                    (MutBlock tag2 fin2 l h r) refs) = NotThunk) /\
         (!m. ~(m = ptr)
              ==> sptree_lookup m
                    (insert ptr (MutBlock tag2 fin2 l h r) refs) =
                  sptree_lookup m refs)`),
  DISCH_THEN (fun hs ->
    let hl = CONJUNCT1 hs in
    let tfc = CONJUNCT1 (CONJUNCT2 hs) in
    let tr = CONJUNCT1 (CONJUNCT2 (CONJUNCT2 hs)) in
    let lk = CONJUNCT2 (CONJUNCT2 (CONJUNCT2 hs)) in
    REPEAT CONJ_TAC THENL
     [REPEAT GEN_TAC THEN
      DISCH_THEN (fun vi ->
        MATCH_ACCEPT_TAC (MATCH_MP v_inv_MutBlock_hole
          (CONJ (MATCH_MP v_inv_BlockRep_upd
                   (CONJ vi (CONJ hl (CONJ tfc tr)))) lk)));
      GEN_TAC THEN
      REWRITE_TAC[MATCH_MP dest_thunk_insert_MutBlock lk] THEN
      DISCH_THEN ACCEPT_TAC;
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[lookup_insert]]));;

(* the invariant of the reference written when the hole of a
   mutable block is filled: the element is the one stored, and its
   values are the old ones with the value put in its place *)
let bc_ref_inv_update_mutblock_at = prove
 (cake_as_vars (fun () ->
    `FLOOKUP (f:(num,num)fmap) ptr = SOME p /\
     heap_lookup p heap2 =
       SOME (BlockRep tag (LUPDATE rr (LENGTH l) zs)) /\
     sptree_lookup ptr refs = SOME (bvlSem_MutBlock tag F l cv r) /\
     EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap)) zs
       (l ++ [cv] ++ r) /\
     v_inv conf h refs (rr,f,tf,heap) /\
     (!gs. ~(data_to_word_config_gc_kind conf =
             data_to_word_Generational gs)) /\
     ~(p IN IMAGE (FAPPLY (tf:(num,num)fmap)) (FDOM tf)) /\
     (!w1 w2. v_inv conf w1 refs (w2,f,tf,heap)
              ==> v_inv conf w1
                    (insert ptr (MutBlock tag F l h r) refs)
                    (w2,f,tf,heap2)) /\
     (!v. MEM v (l ++ [h] ++ r)
          ==> v IN all_vs (insert ptr (MutBlock tag F l h r) refs)
                    stack')
     ==> bc_ref_inv conf ptr
           (insert ptr (MutBlock tag F l h r) refs)
           (f,DRESTRICT tf
                (all_ts (insert ptr (MutBlock tag F l h r) refs)
                   stack'),heap2,be')`),
  STRIP_TAC THEN
  (* the new references hold the block with the hole filled *)
  W(fun (asl,w) ->
    let ins = find_term (hd_is "sptree_insert") w in
    let args = snd (strip_comb ins) in
    SUBGOAL_THEN
      (mk_eq (list_mk_icomb "sptree_lookup" [el 0 args; ins],
              list_mk_icomb "SOME" [el 1 args]))
      ASSUME_TAC THENL
     [REWRITE_TAC[lookup_insert]; ALL_TAC]) THEN
  (* which is the arm of a mutable block *)
  W(fun (asl,w as gl) ->
    let lk1 = the_asm (fun c -> is_eq c &&
                hd_is "FLOOKUP" (lhand c)) gl in
    let ins = find_term (hd_is "sptree_insert") w in
    REWRITE_TAC[MATCH_MP arm_MB (CONJ lk1 (a_lkref ins gl))]) THEN
  REPEAT CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  (* no timestamp points at the cell, and the map only shrinks *)
  TRY (SOLVED
        (W(fun gl ->
           let nim = the_asm (fun c -> is_neg c &&
                       hd_is "IN" (rand c)) gl in
           MATCH_ACCEPT_TAC
             (MATCH_MP IMAGE_DRESTRICT_NOT nim)))) THEN
  (* the element is the one stored, and its values are the old ones
     with the value put in the place of the hole *)
  W(fun (asl,w as gl) ->
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    let lup = rand (rand (rand (concl hl))) in
    let old = the_asm (fun c -> hd_is "ALL2" c) gl in
    let oargs = snd (strip_comb (concl old)) in
    let vi = the_asm (hd_is "v_inv") gl in
    let vargs = snd (strip_comb (concl vi)) in
    let i = el 1 (snd (strip_comb lup)) in
    let hv = el 1 vargs in
    let newys = list_mk_icomb "LUPDATE" [hv; i; el 2 oargs] in
    let bod = snd (strip_exists w) in
    let goalys = el 2 (snd (strip_comb (rand bod))) in
    EXISTS_TAC lup THEN
    CONJ_TAC THENL
     [ACCEPT_TAC hl;
      SUBGOAL_THEN (mk_eq (goalys,newys))
        (fun e -> ONCE_REWRITE_TAC[e]) THENL
       [REWRITE_TAC[APPEND; LUPDATE_LENGTH];
        ALL_TAC] THEN
      W(fun (asl,w as gl) ->
        let th = CONV_RULE(TOP_DEPTH_CONV BETA_CONV)
                   (ISPECL [el 0 oargs; el 1 oargs; el 2 oargs; i;
                            el 0 (tparts (el 3 vargs)); hv]
                      EVERY2_LUPDATE_same) in
        let old2 = MATCH_MP th (CONJ vi old) in
        let mem = ONCE_REWRITE_RULE[ASSUME (mk_eq (goalys,newys))]
                    (the_asm (fun c ->
                       length (fst (strip_forall c)) = 1 &&
                       is_imp (snd (strip_forall c)) &&
                       hd_is "MEM" (lhand (snd (strip_forall c))))
                       gl) in
        ACCEPT_TAC (MATCH_MP EVERY2_v_inv_update_gen
          (CONJ (a_vtr gl) (CONJ mem old2))))]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let update_mutblock_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (h :: RefPtr F ptr :: stack) refs
                (roots,heap,be,a,sp,sp1,gens) limit ts /\
     (lookup ptr refs = SOME (bvlSem_MutBlock tag F l cv r)) ==>
       (?p rr roots2 vs1 heap2 u.
         (roots = rr :: gc_shared_Pointer p u :: roots2) /\
         (heap_lookup p heap = SOME (BlockRep tag vs1)) /\
         (LENGTH vs1 = LENGTH l + 1 + LENGTH r) /\
         (heap_store p [BlockRep tag (LUPDATE rr (LENGTH l) vs1)]
           heap = (heap2,T)) /\
         abs_ml_inv conf (h :: RefPtr F ptr :: stack)
           (insert ptr (bvlSem_MutBlock tag F l h r) refs)
           (roots,heap2,be,a,sp,sp1,gens) limit ts)`),
  (* the steps are above the statement and above update_ref_thm
     (tools/overrides.py).  The two roots in front of the rest are
     the root of the value and the address of the reference, which
     v_inv of the pointer gives in the first of its three ways,
     because the reference holds a mutable block; the invariant of
     that reference gives the element of the heap and the values it
     holds, the store writes the value into the place of the hole
     (LUPDATE), and the heap and the references are then as good as
     they were.  Of the reference written the invariant is the
     block with the hole filled and of any other one its element,
     which the store did not touch *)
  (STRIP_TAC THEN
    (* what the invariant says of the stack with the value and the
       pointer on it *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    (* the roots are the two of the values in front and the rest *)
    SPLIT_ROOTS_TAC THEN SPLIT_ROOTS_TAC THEN
    (* and the root of the pointer is the address of its reference *)
    FIRST_ASSUM (fun vr ->
      let c = concl vr in
      if not (hd_is "v_inv" c) ||
         not (hd_is "dataSem_RefPtr" (el 1 (snd (strip_comb c))))
      then fail()
      else STRIP_ASSUME_TAC (REWRITE_RULE[v_inv_def] vr)) THEN
    (* of the three ways a pointer is related only the first is
       left, because the reference holds a mutable block: the two
       that are about a thunk say the reference holds one *)
    (let rws = distinctness "thunk_mode" :: ref_rws in
     RULE_ASSUM_TRY (REWRITE_RULE rws) THEN
     TRY (FIRST_ASSUM CONTR_TAC) THEN
     (* the reference is no thunk, so the first way is the one *)
     TRY (SOLVED
           (W(fun gl ->
              let nt = the_asm (fun c ->
                         length (fst (strip_forall c)) = 2 &&
                         is_neg (snd (strip_forall c))) gl in
              let lk = the_asm (fun c -> is_eq c &&
                         hd_is "sptree_lookup" (lhand c) &&
                         hd_is "SOME" (rand c)) gl in
              let args = snd (strip_comb (rand (rand (concl lk)))) in
              CONTR_TAC (MP (NOT_ELIM
                (SPECL [el 0 args; el 1 args] nt)) lk)))) THEN
     (* and the two lookups of the key agree, which leaves the
        second way and puts the third out *)
     TRY (W(fun (asl,_) ->
       let lks = mapfilter (fun (_,th) ->
                   let c = concl th in
                   if is_eq c && hd_is "sptree_lookup" (lhand c) &&
                      hd_is "SOME" (rand c) then th else fail()) asl in
       if length lks < 2 then fail() else
       MP_TAC (TRANS (SYM (el 0 lks)) (el 1 lks)) THEN
       REWRITE_TAC (injectivity "option" ::
                    injectivity "bvlSem_ref" :: rws) THEN
       STRIP_TAC)) THEN
     SPLIT_ASM_TAC THEN
     TRY VAR_EQ_TAC) THEN
    (* the reference has an address *)
    (SUBGOAL_THEN (cake_as_vars (fun () ->
       `FLOOKUP (f:(num,num)fmap) (ptr:num) = SOME (FAPPLY f ptr:num)`))
       ASSUME_TAC THENL
      [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC]) THEN
    (* and it is reachable, so the invariant holds of it *)
    (SUBGOAL_THEN (cake_as_vars (fun () ->
       `reachable_refs (h :: RefPtr F ptr :: stack) refs ptr`))
       ASSUME_TAC THENL
      [MATCH_MP_TAC (GEN_ALL reach_refptr) THEN
       FIRST [EXISTS_TAC `F`; ALL_TAC] THEN
       REWRITE_TAC[MEM];
       ALL_TAC]) THEN
    W(fun (asl,w as gl) ->
      let bri = the_asm (fun c ->
        let vs,bd = strip_forall c in
        length vs = 1 && is_imp bd &&
        hd_is "bc_ref_inv" (rand bd)) gl in
      let rr = the_asm (hd_is "reachable_refs") gl in
      let n = el 2 (snd (strip_comb (concl rr))) in
      let nin = the_asm (fun c -> hd_is "IN" c &&
                  hd_is "FDOM" (rand c) &&
                  el 0 (snd (strip_comb c)) = n) gl in
      ASSUME_TAC (MP (SPEC n bri) (CONJ rr nin))) THEN
    (* which is the arm of a mutable block: the element of the heap,
       the values it holds, and that no timestamp points at it *)
    W(fun gl ->
      let lk1 = the_asm (fun c -> is_eq c &&
                  hd_is "FLOOKUP" (lhand c)) gl in
      let lk2 = the_asm (fun c -> is_eq c &&
                  hd_is "sptree_lookup" (lhand c)) gl in
      FIRST_X_ASSUM (fun inv ->
        if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
        STRIP_ASSUME_TAC
          (REWRITE_RULE[MATCH_MP arm_MB (CONJ lk1 lk2)] inv))) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[]) THEN
    (* the store of the value into the hole of the block *)
    W(fun (asl,w as gl) ->
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 can (fun t -> hd_is "BlockRep" (rand t))
                   (rand c)) gl in
      let zs = rand (rand (rand (concl hl))) in
      let rts = lhand (hd (conjuncts (snd (strip_exists w)))) in
      let rr = el 0 (snd (strip_comb rts)) in
      let i = el 1 (snd (strip_comb
                (find_term (hd_is "LUPDATE") w))) in
      let ws = list_mk_icomb "LUPDATE" [rr; i; zs] in
      SUBGOAL_THEN (mk_eq (list_mk_icomb "LENGTH" [zs],
                           list_mk_icomb "LENGTH" [ws]))
        (fun le -> STRIP_ASSUME_TAC
          (MATCH_MP heap_store_BlockRep (CONJ le hl)) THEN
          ASSUME_TAC le THEN ASSUME_TAC (SYM le)) THENL
       [REWRITE_TAC[LENGTH_LUPDATE];
        ALL_TAC]) THEN
    (* the witnesses: the address of the reference, the root of the
       value, the rest of the roots, the values the element held and
       the new heap *)
    W(fun (asl,w as gl) ->
      let rts = lhand (hd (conjuncts (snd (strip_exists w)))) in
      let rargs = snd (strip_comb rts) in
      let rr = el 0 rargs in
      let targs = snd (strip_comb (el 1 rargs)) in
      let pargs = snd (strip_comb (el 0 targs)) in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 el 1 (snd (strip_comb (lhand c))) = heap &&
                 can (fun t -> hd_is "BlockRep" (rand t))
                   (rand c)) gl in
      MAP_EVERY EXISTS_TAC
        [el 0 pargs; rr; el 1 targs;
         rand (rand (rand (concl hl))); lhand (rand (concl st));
         el 1 pargs]) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the number of the values of the element, which a rewrite with
       the assumptions cannot be let at: the lengths of the element
       and of the list stored are each other's *)
    TRY (SOLVED
          (W(fun gl ->
             let old = the_asm (fun c -> hd_is "ALL2" c &&
                         hd_is "APPEND"
                           (el 2 (snd (strip_comb c)))) gl in
             MP_TAC (MATCH_MP LIST_REL_LENGTH old)) THEN
           REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN ARITH_TAC)) THEN
    TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
    (* and the invariant of the new heap and references *)
    REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
    (* the roots are the ones they were, of a heap as good *)
    TRY (SOLVED
          (W(fun gl ->
             let iso = the_asm (fun c ->
               let bd = snd (strip_forall c) in
               is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
             let ro = the_asm (hd_is "roots_ok") gl in
             ACCEPT_TAC (MATCH_MP roots_ok_iso (CONJ ro iso))))) THEN
    (* the heap is good: the pointers of the element written are the
       root put in and the ones it had (ptrs_store_el) *)
    TRY (SOLVED
          (W(fun gl ->
             let ho = the_asm (hd_is "heap_ok") gl in
             let ro = REWRITE_RULE[roots_ok_def]
                        (the_asm (hd_is "roots_ok") gl) in
             let iso = the_asm (fun c ->
               let bd = snd (strip_forall c) in
               is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
             let hlen = the_asm (fun c -> is_eq c &&
                          hd_is "heap_length" (lhand c)) gl in
             let flt = the_asm (fun c -> is_eq c &&
                         hd_is "FILTER" (lhand c)) gl in
             let mm = REWRITE_RULE[BlockRep_def] (the_asm (fun c ->
                        let bd = snd (strip_forall c) in
                        is_imp bd && is_disj (rand bd)) gl) in
             let dj = hd (disjuncts
                        (rand (snd (strip_forall (concl mm))))) in
             let ws = el 0 (snd (strip_comb (rand dj))) in
             let st = the_asm (fun c -> is_eq c &&
                        hd_is "heap_store" (lhand c)) gl in
             let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
             let hl = REWRITE_RULE[BlockRep_def] (the_asm (fun c ->
                        is_eq c && hd_is "heap_lookup" (lhand c) &&
                        el 1 (snd (strip_comb (lhand c))) = heap &&
                        can (fun t -> hd_is "BlockRep" (rand t))
                          (rand c)) gl) in
             let w0 = el 0 (snd (strip_comb ws)) in
             let vs,bd = strip_forall (concl ro) in
             let pt = list_mk_forall(vs,
                        mk_imp(mk_eq (w0, lhand (lhand bd)),
                               rand bd)) in
             SUBGOAL_THEN pt (fun ptt ->
               let p1 = MATCH_MP ptrs_store_el
                          (CONJ ho (CONJ ptt hl)) in
               let iv = find_term (fun t -> is_var t &&
                          fst (dest_var t) = "i") (concl p1) in
               ACCEPT_TAC (MATCH_MP heap_ok_store_el
                 (CONJ ho (CONJ (INST [el 1 (snd (strip_comb ws)),iv]
                                   p1)
                   (CONJ iso (CONJ hlen (CONJ flt mm))))))) THEN
             MP_TAC ro THEN POP_ASSUM_LIST (K ALL_TAC) THEN
             REWRITE_TAC[MEM] THEN MESON_TAC[]))) THEN
    (* the kind of the collection: a mutable block is not in a heap
       that a generational collection goes through (gc_kind_not_gen) *)
    TRY (SOLVED
          (W(fun gl ->
             let gk = the_asm (hd_is "gc_kind_inv") gl in
             let ng = the_asm (fun c ->
                        let vs,bd = strip_forall c in
                        length vs = 1 && is_neg bd) gl in
             MATCH_ACCEPT_TAC (MATCH_MP gc_kind_not_gen
               (CONJ gk ng))))) THEN
    (* and the unused space is where it was: the unused element is
       not a data element, so it is not the block written *)
    TRY (SOLVED
          (W(fun gl ->
             let us = the_asm (hd_is "unused_space_inv") gl in
             let hlen = the_asm (fun c -> is_eq c &&
                          hd_is "heap_length" (lhand c)) gl in
             let st = the_asm (fun c -> is_eq c &&
                        hd_is "heap_store" (lhand c)) gl in
             let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
             let el2 = lhand (el 1 (snd (strip_comb
                         (lhand (concl st))))) in
             let hl = the_asm (fun c -> is_eq c &&
                        hd_is "heap_lookup" (lhand c) &&
                        el 1 (snd (strip_comb (lhand c))) = heap &&
                        can (fun t -> hd_is "BlockRep" (rand t))
                          (rand c)) gl in
             let el1 = rand (rand (concl hl)) in
             SUBGOAL_THEN (list_mk_icomb "isDataElement" [el1])
               (fun isd1 ->
                  SUBGOAL_THEN (list_mk_icomb "isDataElement" [el2])
                    (fun isd2 -> ACCEPT_TAC (MATCH_MP unused_store_el
                      (CONJ us (CONJ hlen (CONJ hl (CONJ isd1
                        (CONJ isd2 (CONJ (a_tr gl) st)))))))) THEN
                  REWRITE_TAC[isDataElement_def; BlockRep_def] THEN
                  MESON_TAC[]) THEN
             REWRITE_TAC[isDataElement_def; BlockRep_def] THEN
             MESON_TAC[]))) THEN
    (* the maps of the new invariant: the addresses are the ones they
       were, and the timestamps are cut to the ones of the new
       references and stack *)
    W(fun (asl,w as gl) ->
      if not (is_exists w) then ALL_TAC else
      (let sub p = rand (lhand (concl (the_asm (fun c ->
         hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
       let ats = find_term (hd_is "all_ts") w in
       EXISTS_TAC (sub "domain") THEN
       EXISTS_TAC (list_mk_icomb "DRESTRICT" [sub "all_ts"; ats]))) THEN
    REPEAT CONJ_TAC THEN TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the addresses of the maps are the ones of the old heap *)
    TRY (SOLVED
          (W(fun gl ->
             let iso = the_asm (fun c ->
               let bd = snd (strip_forall c) in
               is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
             ONCE_REWRITE_TAC[iso]) THEN
           FIRST [SOLVED (FIRST_ASSUM ACCEPT_TAC);
                  SOLVED (W(fun (asl,w as gl) ->
                    let dr = find_term (hd_is "DRESTRICT") w in
                    let inj = the_asm (fun c -> hd_is "INJ" c &&
                      rand (el 0 (snd (strip_comb c))) = lhand dr) gl in
                    MATCH_ACCEPT_TAC
                      (MATCH_MP INJ_DRESTRICT inj)))])) THEN
    (* the domain of the references has the key in it *)
    TRY (SOLVED
          (REWRITE_TAC[domain_insert] THEN
           MATCH_MP_TAC SUBSET_TRANS THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "domain" (rand c)) gl in
             EXISTS_TAC (rand (concl su))) THEN
           CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
           SET_TAC[])) THEN
    (* the timestamps of the restricted map are of the stack, and
       below the counter *)
    TRY (SOLVED
          (REWRITE_TAC[(CONJUNCT1 o SPEC_ALL) DRESTRICT_DEF] THEN
           FIRST [SOLVED (REWRITE_TAC[INTER_SUBSET]);
                  SOLVED (MATCH_MP_TAC SUBSET_TRANS THEN
                          W(fun gl ->
                            let su = the_asm (fun c ->
                              hd_is "SUBSET" c &&
                              hd_is "FDOM" (lhand c)) gl in
                            EXISTS_TAC (lhand (concl su))) THEN
                          CONJ_TAC THEN
                          TRY (FIRST_ASSUM ACCEPT_TAC) THEN
                          REWRITE_TAC[INTER_SUBSET])])) THEN
    (* the blocks of the stack stay unique *)
    TRY (SOLVED
          (W(fun gl ->
             let bu = the_asm (hd_is "blocks_unique") gl in
             MATCH_ACCEPT_TAC (MATCH_MP blocks_unique_update_mutblock
               (CONJ (a_lkptr gl) bu))))) THEN
    (* the transfers that the update of the hole leaves: what the
       invariant says of a value, what a value says of a thunk, and
       what the references hold at another key (MB_trans) *)
    W(fun (asl,w as gl) ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store" (lhand c)) gl in
      let heap = el 2 (snd (strip_comb (lhand (concl st)))) in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 el 1 (snd (strip_comb (lhand c))) = heap &&
                 can (fun t -> hd_is "BlockRep" (rand t))
                   (rand c)) gl in
      let nim = the_asm (fun c -> is_neg c &&
                  hd_is "IN" (rand c)) gl in
      let trs = CONJUNCTS (MATCH_MP MB_trans
                  (CONJ hl (CONJ (MATCH_MP IMAGE_NOT_point nim)
                    (CONJ (a_tr gl) (a_lkptr gl))))) in
      (* the block that the update puts in is as unfinalised as the
         one it replaces, which only the conclusion of MB_trans
         says, so the transfers have to be told (entry 55) *)
      let fv = find_term (fun t -> is_var t &&
                 fst (dest_var t) = "fin2") (concl (hd trs)) in
      let fin = el 1 (snd (strip_comb
                  (rand (rand (concl (a_lkptr gl)))))) in
      MAP_EVERY ASSUME_TAC (map (INST [fin,fv]) trs)) THEN
    (* the values of the stack: the value put in the hole and the
       pointer in front of it, and the rest *)
    W(fun (asl,w) -> if not (hd_is "ALL2" w) then ALL_TAC else
      (REWRITE_TAC[ALL2] THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       REPEAT CONJ_TAC THEN
       TRY (SOLVED
             (W(fun (asl,w as gl) ->
                let args = snd (strip_comb w) in
                let v1 = el 1 args in
                let ats = find_term (hd_is "all_ts") w in
                let vi = the_asm (fun c -> hd_is "v_inv" c &&
                           el 1 (snd (strip_comb c)) = v1 &&
                           not (el 2 (snd (strip_comb c)) =
                                  lhand ats)) gl in
                SUBGOAL_THEN
                  (list_mk_icomb "MEM" [v1; rand ats])
                  (fun mm -> MATCH_ACCEPT_TAC (MATCH_MP
                     v_inv_update_gen
                     (CONJ (a_vtr gl) (CONJ vi
                       (MP (SPECL [v1; rand ats; lhand ats]
                             MEM_stack_all_vs) mm))))) THEN
                REWRITE_TAC[MEM]))) THEN
       W(fun (asl,w as gl) ->
         let old = the_asm (fun c -> hd_is "ALL2" c &&
                     el 1 (snd (strip_comb c)) =
                       el 1 (snd (strip_comb w))) gl in
         let ats = find_term (hd_is "all_ts") w in
         let vs = el 1 (snd (strip_comb w)) in
         let v = genvar (hd (snd (dest_type (type_of (rand ats))))) in
         SUBGOAL_THEN
           (mk_forall(v, mk_imp(list_mk_icomb "MEM" [v; vs],
              list_mk_icomb "IN"
                [v; list_mk_icomb "all_vs" [lhand ats; rand ats]])))
           (fun mem -> ACCEPT_TAC (MATCH_MP EVERY2_v_inv_update_stack
              (CONJ (a_vtr gl) (CONJ mem old)))) THEN
         REPEAT STRIP_TAC THEN
         W(fun gl ->
           let mm = the_asm (hd_is "MEM") gl in
           let v1 = el 0 (snd (strip_comb (concl mm))) in
           SUBGOAL_THEN (list_mk_icomb "MEM" [v1; rand ats])
             (fun m2 -> MATCH_ACCEPT_TAC (MP (SPECL [v1; rand ats;
                          lhand ats] MEM_stack_all_vs) m2)) THEN
           ASM_REWRITE_TAC[MEM])))) THEN
    (* and the invariant of each reference that the stack reaches:
       it was reachable before the update
       (reachable_refs_MutBlock_UPDATE) *)
    W(fun (asl,w) -> if not (is_forall w) then ALL_TAC else
      (REPEAT STRIP_TAC THEN
       W(fun gl ->
         let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                    hd_is "sptree_insert"
                      (el 1 (snd (strip_comb c)))) gl in
         ASSUME_TAC (MATCH_MP reachable_refs_MutBlock_UPDATE
           (CONJ (a_lkptr gl) rr))) THEN
       W(fun (asl,w as gl) ->
         let n = el 1 (snd (strip_comb w)) in
         let bri = the_asm (fun c ->
           let vs,bd = strip_forall c in
           length vs = 1 && is_imp bd &&
           hd_is "bc_ref_inv" (rand bd)) gl in
         let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
           not (hd_is "sptree_insert"
                  (el 1 (snd (strip_comb c))))) gl in
         let nin = the_asm (fun c -> hd_is "IN" c &&
           hd_is "FDOM" (rand c) &&
           el 0 (snd (strip_comb c)) = n) gl in
         ASSUME_TAC (MP (SPEC n bri) (CONJ rr nin))) THEN
       (* the reference written, or another one *)
       W(fun (asl,w as gl) ->
         ASM_CASES_TAC (mk_eq (el 1 (snd (strip_comb w)),
                               g_ptr gl))) THEN
       TRY VAR_EQ_TAC THEN
       (* the one written: the block with the hole filled *)
       TRY (SOLVED
             (W(fun (asl,w as gl) ->
                let lk1 = the_asm (fun c -> is_eq c &&
                            hd_is "FLOOKUP" (lhand c)) gl in
                let p = rand (rand (concl lk1)) in
                let hl2 = the_asm (fun c -> is_eq c &&
                            hd_is "heap_lookup" (lhand c) &&
                            el 0 (snd (strip_comb (lhand c))) = p &&
                            can (fun t -> hd_is "BlockRep" (rand t))
                              (rand c) &&
                            can (find_term (hd_is "LUPDATE"))
                              (rand c)) gl in
                let lup = find_term (hd_is "LUPDATE") (concl hl2) in
                let old = the_asm (fun c -> hd_is "ALL2" c &&
                            el 1 (snd (strip_comb c)) =
                              el 2 (snd (strip_comb lup))) gl in
                let vi = the_asm (fun c -> hd_is "v_inv" c &&
                           el 0 (tparts (el 3 (snd (strip_comb c)))) =
                             el 0 (snd (strip_comb lup))) gl in
                let gk = the_asm (fun c ->
                           length (fst (strip_forall c)) = 1 &&
                           is_neg (snd (strip_forall c))) gl in
                let nim = the_asm (fun c -> is_neg c &&
                            hd_is "IN" (rand c)) gl in
                let ats = find_term (hd_is "all_ts") w in
                let ins = lhand ats in
                let bargs = snd (strip_comb
                              (el 1 (snd (strip_comb ins)))) in
                let vls = list_mk_icomb "APPEND"
                            [el 2 bargs; list_mk_icomb "APPEND"
                              [mk_flist [el 3 bargs]; el 4 bargs]] in
                let v = genvar (type_of (el 3 bargs)) in
                SUBGOAL_THEN
                  (mk_forall(v, mk_imp(list_mk_icomb "MEM" [v; vls],
                     list_mk_icomb "IN"
                       [v; list_mk_icomb "all_vs" [ins; rand ats]])))
                  (fun mem -> MATCH_ACCEPT_TAC (MATCH_MP
                     bc_ref_inv_update_mutblock_at
                     (CONJ lk1 (CONJ hl2 (CONJ (a_lkptr gl)
                       (CONJ old (CONJ vi (CONJ gk (CONJ nim
                         (CONJ (a_vtr gl) mem)))))))))) THEN
                REPEAT STRIP_TAC THEN
                W(fun (asl,w as gl) ->
                  let iargs = snd (strip_comb
                                (find_term (hd_is "sptree_insert")
                                   w)) in
                  let mm = the_asm (hd_is "MEM") gl in
                  SUBGOAL_THEN
                    (mk_eq (list_mk_icomb "sptree_lookup"
                              [el 0 iargs;
                               find_term (hd_is "sptree_insert") w],
                            list_mk_icomb "SOME" [el 1 iargs]))
                    (fun lkn -> MATCH_ACCEPT_TAC
                       (MATCH_MP MEM_mutblock_all_vs
                         (CONJ lkn mm))) THEN
                  REWRITE_TAC[lookup_insert])))) THEN
       (* another one: its element did not move *)
       TRY (SOLVED
             (W(fun (asl,w as gl) ->
                let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
                let inj = the_asm (fun c -> hd_is "INJ" c &&
                            rand (el 0 (snd (strip_comb c))) = fm) gl in
                let pin = the_asm (fun c -> hd_is "IN" c &&
                            hd_is "FDOM" (rand c) &&
                            el 0 (snd (strip_comb c)) = g_ptr gl) gl in
                let neq = the_asm (fun c -> is_neg c &&
                            is_eq (rand c) &&
                            rand (rand c) = g_ptr gl) gl in
                let inv = the_asm (hd_is "bc_ref_inv") gl in
                MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_other_gen
                  (CONJ inj (CONJ pin (CONJ neq (CONJ (a_vtr gl)
                    (CONJ (a_dtr gl) (CONJ (a_ltr gl)
                      (CONJ (a_tr gl) inv))))))))))))) THEN
    ALL_TAC));;

(* update byte ref *)

(* [simp] *)
let LENGTH_write_bytes = prove
 (`!ws bs be'. LENGTH (write_bytes bs ws be') = LENGTH ws`,
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[write_bytes_def] THEN
   CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
   ASM_REWRITE_TAC[LENGTH]));;

(* [local] *)
let LIST_REL_IMP_LIST_REL = prove
 (`!xs ys.
       (!x y. MEM x xs ==> P x y ==> Q x y) ==>
       LIST_REL P xs ys ==> LIST_REL Q xs ys`,
  (let aux = prove
    (`!(P:A->B->bool) Q xs ys.
        (!x y. MEM x xs /\ P x y ==> Q x y) /\ ALL2 P xs ys
        ==> ALL2 Q xs ys`,
     GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
     X_GEN_TAC `ys:B list` THEN
     STRUCT_CASES_TAC(ISPEC `ys:B list` list_CASES_v) THEN
     REWRITE_TAC[ALL2; MEM] THEN REPEAT STRIP_TAC THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
     REPEAT STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
     ASM_REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN
   REWRITE_TAC[TAUT `(p ==> q ==> r) <=> (p /\ q ==> r)`] THEN
   MATCH_ACCEPT_TAC aux));;

(* [local] *)
let v_size_LESS_EQ = prove
 (`!l x. MEM x l ==> dataSem_v_size x <= list_size dataSem_v_size l`,
  (REPEAT STRIP_TAC THEN MATCH_MP_TAC misc_MEM_list_size THEN
   ASM_REWRITE_TAC[]));;

(* the port's own: a heap in which one element is replaced by one
   of the same length.  A split of it gives the halves of the old
   heap, up to that element, and a lookup in it is the old one
   unless it is that element that is found.  Both are used by the
   theorems about a store into a byte array, of which
   v_inv_IMP_lemma is the first. *)

let heap_split_replace = prove
 (`!e ha u v hb h1 h2.
     heap_split e (ha ++ [u] ++ hb) = SOME (h1,h2) /\
     el_length u = el_length v
     ==> ?h1' h2'. heap_split e (ha ++ [v] ++ hb) = SOME (h1',h2') /\
                   (!z. MEM z h1' ==> MEM z h1 \/ z = v)`,
  (* the witnesses are what the equations of the goal say *)
  let witness =
    W(fun (asl,w) ->
      let vs,bod = strip_exists w in
      MAP_EVERY EXISTS_TAC (map lhs (conjuncts (lhand bod)))) THEN
    REWRITE_TAC[] THEN
    REPEAT(FIRST_X_ASSUM(fun eq ->
      if is_eq (concl eq) && is_var (rhs (concl eq)) &&
         not (lhs (concl eq) = rhs (concl eq))
      then SUBST_ALL_TAC (SYM eq) else fail())) THEN
    REPEAT GEN_TAC THEN
    REWRITE_TAC[APPEND_NIL; APPEND; MEM_APPEND; MEM] THEN
    CONV_TAC TAUT in
  REPEAT GEN_TAC THEN REWRITE_TAC[GSYM APPEND_ASSOC] THEN
  REWRITE_TAC[heap_split_APPEND_if] THEN COND_CASES_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
  ASM_REWRITE_TAC[heap_length_clauses; heap_split_def] THEN
  REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN
  EVERY_CASE_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option";
              PAIR_EQ] THEN
  REPEAT STRIP_TAC THEN witness);;

let heap_lookup_replace = prove
 (`!n ha u v hb z.
     heap_lookup n (ha ++ [u] ++ hb) = SOME z /\
     el_length u = el_length v /\ ~(z = u)
     ==> heap_lookup n (ha ++ [v] ++ hb) = SOME z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[GSYM APPEND_ASSOC] THEN
  REWRITE_TAC[data_to_word_memoryProof_heap_lookup_APPEND] THEN
  COND_CASES_TAC THEN REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 MP_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  ASM_REWRITE_TAC[heap_lookup_def; heap_length_clauses] THEN
  REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN
  REWRITE_TAC[injectivity "option"; distinctness "option"] THEN
  ASM_MESON_TAC[]);;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_IMP_lemma = prove
 (cake_as_vars (fun () ->
    `!ck w refs x f tf.
       v_inv conf w refs (x,f,tf,ha ++ [Bytes be fl xs ws] ++ hb)
         ==>
         v_inv_ck ck conf w refs (x,f,tf,ha ++ [Bytes be fl ys
           ws] ++ hb)`),
  (* the store replaces the contents of a byte array by another, and
     the element it writes is as long as the one that was there (a
     write keeps the words), so a lookup that finds something else
     finds it in the new heap as well (heap_lookup_replace) *)
  ((* the element that the store replaces is a Bytes, and what the
      relation looks up is none: so the lookup is the old one
      (heap_lookup_replace), because the two elements are as long *)
   let notbytes = prove
    (cake_as_vars (fun () ->
       `~(Bignum i = Bytes be flag bs (ys:('a word)list)) /\
        ~(Word64Rep (:'a) w = Bytes be flag bs ys) /\
        ~(BlockRep n xs = Bytes be flag bs ys) /\
        ~(ThunkBlock ev x = Bytes be flag bs ys)`),
     REWRITE_TAC[ThunkBlock_def; bignum_def; Word64Rep_def;
                 BlockRep_def; bytes_def] THEN
     PAIRARG_TAC THEN CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     COND_CASES_TAC THEN
     REWRITE_TAC[injectivity "heap_element"; PAIR_EQ;
                 distinctness "data_to_word_memoryProof_tag";
                 NOT_CONS_NIL]) in
   let hp =
     MATCH_MP_TAC heap_lookup_replace THEN ASM_EXISTS_TAC THEN
     REPEAT CONJ_TAC THENL
      [FIRST_ASSUM MATCH_ACCEPT_TAC;
       (* the two elements are as long: a write keeps the words *)
       REWRITE_TAC[bytes_def] THEN
       CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
       REWRITE_TAC[el_length_def; LENGTH_write_bytes];
       REWRITE_TAC[notbytes]] in
   V_INV_REFS_TAC ALL_TAC hp V_INV_HEAP_PLAIN
     (V_INV_HEAP_THUNK hp 5) (V_INV_HEAP_THUNK hp 6)));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_IMP = prove
 (cake_as_vars (fun () ->
    `!y x f tf ha.
         v_inv conf y refs (x,f,tf,ha ++ [Bytes be fl xs ws] ++ hb)
           ==>
         v_inv conf y refs (x,f,tf,ha ++ [Bytes be fl ys ws] ++
           hb)`),
  (* the lemma is applied to the assumption and not to the goal:
     where a type variable of the statement stands only in the
     antecedent, MATCH_MP_TAC leaves the lemma's own one there *)
  (REWRITE_TAC[v_inv_eq] THEN REPEAT GEN_TAC THEN
   DISCH_THEN(fun th ->
     GEN_TAC THEN
     MATCH_ACCEPT_TAC(MATCH_MP v_inv_IMP_lemma
       (REWRITE_RULE[GSYM v_inv_eq] th)))));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let gen_state_ok_update_byte = prove
 (cake_as_vars (fun () ->
    `gen_state_ok a k (ha ++ [Bytes be fl xs ws] ++ hb) gens ==>
     gen_state_ok a k (ha ++ [Bytes be fl ys ws] ++ hb) gens`),
  (* the two elements are of the same length and the one that is
     written holds no pointer, so a split of the heap gives the
     halves of the old one, up to that element *)
  ((* the head constant of a term, by name, and the assumption
      that a test picks out *)
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   let samelen b =
     prove(b,
       REWRITE_TAC[bytes_def] THEN
       CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
       REWRITE_TAC[el_length_def; LENGTH_write_bytes]) in
   let use_split =
     W(fun (asl,w) ->
       let sp = grab asl (fun th ->
                  hd_is "heap_split" (lhand (concl th))) in
       let c = concl sp in
       let e = rand (rator (lhand c)) in
       let old = rand (lhand c) in
       let ha = lhand old in
       let u = rand (rator (lhand (rand old))) in
       let hb = rand (rand old) in
       let h1,h2 = dest_pair (rand (rand c)) in
       let _,bod = strip_exists w in
       let newh = rand (lhand (lhand bod)) in
       let v = rand (rator (lhand (rand newh))) in
       MP_TAC(ISPECL [e; ha; u; v; hb; h1; h2]
                heap_split_replace)) THEN
     DISCH_THEN(fun imp ->
       FIRST_ASSUM(fun sp ->
         if not (hd_is "heap_split" (lhand (concl sp)))
         then fail() else
         MP_TAC(MATCH_MP imp
                  (CONJ sp (samelen (rand (lhand (concl imp)))))))) THEN
     DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) in
   let bytes_nopt =
     W(fun (asl,w) ->
       let eqv = grab asl (fun th -> is_eq (concl th) &&
                   hd_is "DataElement" (lhs (concl th))) in
       let r3 = REWRITE_RULE[injectivity "heap_element"]
                  (CONV_RULE(TOP_DEPTH_CONV let_CONV)
                     (REWRITE_RULE[bytes_def] eqv)) in
       let m = grab asl (fun th ->
                 hd_is "MEM" (concl th) &&
                 not (hd_is "DataElement"
                        (rand (rator (concl th))))) in
       MP_TAC(REWRITE_RULE[CONJUNCT1 r3; MEM] m)) THEN
     REWRITE_TAC[] in
   STRUCT_CASES_TAC(ISPEC `gens:gen_state`
     (cases_of `:gen_state`)) THEN
   REWRITE_TAC[gen_state_ok_def] THEN
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   ASM_REWRITE_TAC[] THEN
   FIRST_X_ASSUM(fun ev ->
     if hd_is "ALL" (concl ev) &&
        hd_is "gen_start_ok" (lhand (concl ev))
     then MP_TAC(REWRITE_RULE[GSYM ALL_MEM] ev) else fail()) THEN
   REWRITE_TAC[GSYM ALL_MEM] THEN
   DISCH_TAC THEN GEN_TAC THEN DISCH_TAC THEN
   FIRST_ASSUM(fun ev ->
     FIRST_ASSUM(fun mm -> MP_TAC(MATCH_MP ev mm))) THEN
   REWRITE_TAC[gen_start_ok_def] THEN
   DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
   use_split THEN
   W(fun (asl,w) ->
     let sp2 = grab asl (fun th ->
                 hd_is "heap_split" (lhand (concl th))) in
     let a,b = dest_pair (rand (rand (concl sp2))) in
     MAP_EVERY EXISTS_TAC [a; b]) THEN
   ASM_REWRITE_TAC[] THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM(fun tr ->
     if not (is_forall (concl tr)) then fail() else
     FIRST_ASSUM(fun m ->
       if not (hd_is "MEM" (concl m)) then fail() else
       MP_TAC(MATCH_MP (SPEC_ALL tr) m))) THEN
   DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC ASSUME_TAC) THENL
    [(* the element is one of the old half, so the old condition
        says what the goal says *)
     ASM_MESON_TAC[];
     (* or it is the one that was written, which holds no pointer *)
     bytes_nopt]));;

(* HOL4 data_to_word_memoryProofScript.sml:5900-5902: a theorem that
   HOL4 states as the value of an ML expression: heap_length_Bytes *)

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let unused_space_inv_byte_update = prove
 (cake_as_vars (fun () ->
    `unused_space_inv a (sp + sp1)
         (ha ++ [Bytes be fl xs (REPLICATE ws (n2w 0))] ++ hb) ==>
     unused_space_inv a (sp + sp1)
         (ha ++ [Bytes be fl ys (REPLICATE ws (n2w 0))] ++ hb)`),
  (* the unused element is not the one that was written, the heap
     is as long as it was, and the part below the pointer still
     holds data *)
  ((* the head constant of a term, by name, and the assumption
      that a test picks out *)
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   let bytefacts =
     REWRITE_TAC[bytes_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) in
   let samelen b =
     prove(b, bytefacts THEN
              REWRITE_TAC[el_length_def; LENGTH_write_bytes]) in
   REWRITE_TAC[unused_space_inv_def] THEN
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   REPEAT CONJ_TAC THENL
    [DISCH_TAC THEN
     FIRST_ASSUM(fun imp ->
       if not (is_imp (concl imp)) then fail() else
       FIRST_ASSUM(fun ne -> MP_TAC(MATCH_MP imp ne))) THEN
     DISCH_TAC THEN
     W(fun (asl,w) ->
       let lk = grab asl (fun th ->
                  hd_is "heap_lookup" (lhand (concl th))) in
       let c = concl lk in
       let n = rand (rator (lhand c)) in
       let old = rand (lhand c) in
       let ha = lhand old in
       let u = rand (rator (lhand (rand old))) in
       let hb = rand (rand old) in
       let z = rand (rand c) in
       let newh = rand (lhand w) in
       let v = rand (rator (lhand (rand newh))) in
       MP_TAC(ISPECL [n; ha; u; v; hb; z] heap_lookup_replace)) THEN
     DISCH_THEN(fun imp ->
       FIRST_ASSUM(fun lk ->
         if not (hd_is "heap_lookup" (lhand (concl lk)))
         then fail() else
         let ants = conjuncts (lhand (concl imp)) in
         let notit = prove(el 2 ants,
           bytefacts THEN
           REWRITE_TAC[distinctness "heap_element"]) in
         ACCEPT_TAC(MATCH_MP imp
           (CONJ lk (CONJ (samelen (el 1 ants)) notit)))));
     FIRST_ASSUM(fun le ->
       if hd_is "<=" (concl le) then MP_TAC le else fail()) THEN
     REWRITE_TAC[heap_length_APPEND; heap_length_clauses;
                 bytes_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[el_length_def; LENGTH_write_bytes];
     FIRST_ASSUM(fun du ->
       if hd_is "data_up_to" (concl du) then MP_TAC du
       else fail()) THEN
     REWRITE_TAC[data_up_to_def] THEN
     DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
     W(fun (asl,w) ->
       let sp = grab asl (fun th ->
                  hd_is "heap_split" (lhand (concl th))) in
       let c = concl sp in
       let e = rand (rator (lhand c)) in
       let old = rand (lhand c) in
       let ha = lhand old in
       let u = rand (rator (lhand (rand old))) in
       let hb = rand (rand old) in
       let h1,h2 = dest_pair (rand (rand c)) in
       let _,bod = strip_exists w in
       let newh = rand (lhand (lhand bod)) in
       let v = rand (rator (lhand (rand newh))) in
       MP_TAC(ISPECL [e; ha; u; v; hb; h1; h2]
                heap_split_replace)) THEN
     DISCH_THEN(fun imp ->
       FIRST_ASSUM(fun sp ->
         if not (hd_is "heap_split" (lhand (concl sp)))
         then fail() else
         MP_TAC(MATCH_MP imp
           (CONJ sp (samelen (rand (lhand (concl imp)))))))) THEN
     DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
     W(fun (asl,w) ->
       let sp2 = grab asl (fun th ->
                   hd_is "heap_split" (lhand (concl th))) in
       let a,b = dest_pair (rand (rand (concl sp2))) in
       MAP_EVERY EXISTS_TAC [a; b]) THEN
     ASM_REWRITE_TAC[] THEN
     REWRITE_TAC[GSYM ALL_MEM] THEN
     GEN_TAC THEN DISCH_TAC THEN
     FIRST_ASSUM(fun tr ->
       if not (is_forall (concl tr)) then fail() else
       FIRST_ASSUM(fun m ->
         if not (hd_is "MEM" (concl m)) then fail() else
         MP_TAC(MATCH_MP (SPEC_ALL tr) m))) THEN
     DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC) THENL
      [FIRST_ASSUM(fun ev ->
         if hd_is "ALL" (concl ev)
         then ASM_MESON_TAC[REWRITE_RULE[GSYM ALL_MEM] ev]
         else fail());
       bytefacts THEN REWRITE_TAC[isDataElement_def] THEN
       W(fun (asl,w) ->
         let _,bod = strip_exists w in
         MAP_EVERY EXISTS_TAC (snd(strip_comb (lhs bod)))) THEN
       REFL_TAC]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_insert_ByteArray = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (RefPtr b ptr :: stack)) ==>
       blocks_unique ts
         (all_vs (insert ptr (ByteArray fl ys) refs) (RefPtr b
           ptr :: stack))`),
  (* a ByteArray holds no value of the language *)
  (let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let inc = prove
    (`!refs p fl ys s t a q.
        Block t a q IN all_vs (insert p (ByteArray fl ys) refs) s ==>
        Block t a q IN all_vs refs s`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; li;
                 distinctness "bvlSem_ref";
                 injectivity "bvlSem_ref"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: what the proof of update_byte_ref_thm adds to
   the block above update_ref_thm.  The update writes an array of
   bytes where one of the same length was, so the heap is given as
   an append and not by a heap_store: the element replaced is of
   the length it had (samelen_bytes), whence the addresses that
   hold data are the ones that held data, the heap and the unused
   space stay good, and the kind of the collection survives
   (gc_kind_byte_update, over the halves of a split of the new
   heap).  The three transfers of such a store are BA_trans, over
   HOL4's v_inv_IMP and v_inv_ByteArray_insert *)

(* the heap of a store into a byte array, out of a term that holds
   it: the append whose middle element is the array of bytes *)
let byte_heap t =
  find_term (fun s -> hd_is "APPEND" s &&
    (try hd_is "Bytes" (lhand (lhand (rand s)))
     with Failure _ -> false)) t;;

(* and the one whose element is not the element given *)
let byte_heap_not u t =
  find_term (fun s -> hd_is "APPEND" s &&
    (try hd_is "Bytes" (lhand (lhand (rand s))) &&
         not (lhand (lhand (rand s)) = u)
     with Failure _ -> false)) t;;

(* tools/wip-update_byte.ml: the lemmas that the proof of
   update_byte_ref_thm of data_to_word_memoryProof needs, each
   proved in a session cut at the statement (tools/bin/trybase) and
   waiting for the proof itself.  Nothing loads this file: the
   lemmas go into the EXTRA_BEFORE block of the statement when the
   proof is done, and the file is deleted then.

   What is still to write: gc_kind_byte_update (the halves of the
   split of the new heap, over the port's own heap_split_replace),
   bc_ref_inv_update_byte_at (the arm of the reference written) and
   the proof itself, which is update_thunk_thm's with a byte array
   for the thunk -- except that the heap is given as an append
   (h1 ++ [Bytes ...] ++ h2) and not by a heap_store. *)

(* the two elements of a byte array that is written are of a
   length, whatever the bytes are *)
let samelen_bytes = prove
 (cake_as_vars (fun () ->
    `el_length (Bytes be fl ys ws) = el_length (Bytes be fl xs ws)`),
  REWRITE_TAC[bytes_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[el_length_def; LENGTH_write_bytes]);;

(* the element of a byte array is data *)
let isSomeDataElement_Bytes = prove
 (cake_as_vars (fun () ->
    `isSomeDataElement (SOME (Bytes be fl bs ws))`),
  REWRITE_TAC[isSomeDataElement_def; bytes_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  W(fun (asl,w) ->
    let vs,bod = strip_exists w in
    MAP_EVERY EXISTS_TAC
      (snd (strip_comb (rand (lhand bod))))) THEN
  REWRITE_TAC[]);;

(* so the addresses that hold data are the ones that held data *)
let isSomeDataElement_byte_update = prove
 (cake_as_vars (fun () ->
    `!n. isSomeDataElement
           (heap_lookup n (ha ++ [Bytes be fl ys ws] ++ hb)) =
         isSomeDataElement
           (heap_lookup n (ha ++ [Bytes be fl xs ws] ++ hb))`),
  GEN_TAC THEN
  REWRITE_TAC[GSYM APPEND_ASSOC;
              data_to_word_memoryProof_heap_lookup_APPEND;
              heap_length_clauses; ADD_CLAUSES; heap_lookup_def;
              samelen_bytes] THEN
  REPEAT (COND_CASES_TAC THEN
          ASM_REWRITE_TAC[isSomeDataElement_Bytes]) THEN
  REWRITE_TAC[isSomeDataElement_Bytes]);;

(* the heap stays good when a byte array is written: it is as long
   as it was, it has the forward pointers it had, and the element
   written holds no pointer *)
let heap_ok_byte_update = prove
 (cake_as_vars (fun () ->
    `heap_ok (ha ++ [Bytes be fl xs ws] ++ hb) limit' /\
     LENGTH xs = LENGTH ys
     ==> heap_ok (ha ++ [Bytes be fl ys ws] ++ hb) limit'`),
  REWRITE_TAC[heap_ok_def; heap_length_APPEND;
              heap_length_clauses; ADD_CLAUSES; samelen_bytes;
              FILTER_APPEND; FILTER] THEN
  REWRITE_TAC[bytes_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[isForwardPointer_def; LENGTH_write_bytes] THEN
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT GEN_TAC THEN
  REWRITE_TAC[MEM_APPEND; MEM] THEN
  STRIP_TAC THEN
  (let isd = REWRITE_RULE[LENGTH_write_bytes]
               (CONV_RULE(TOP_DEPTH_CONV let_CONV)
                 (REWRITE_RULE[bytes_def]
                    isSomeDataElement_byte_update)) in
   REWRITE_TAC[isd]) THEN
  FIRST_ASSUM (fun ho ->
    if not (length (fst (strip_forall (concl ho))) = 5) then fail()
    else MATCH_MP_TAC ho) THEN
  REWRITE_TAC[MEM_APPEND; MEM] THEN
  RULE_ASSUM_TRY (REWRITE_RULE[injectivity "heap_element"]) THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (lhand c)) then fail() else
    SUBST_ALL_TAC e)) THEN
  TRY (SOLVED (ASM_MESON_TAC[MEM])) THEN
  ASM_MESON_TAC[MEM]);;

(* an insert of a byte array where one was leaves what a value says
   of a thunk *)
let dest_thunk_insert_ByteArray = prove
 (cake_as_vars (fun () ->
    `sptree_lookup ptr refs = SOME (bvlSem_ByteArray fl xs)
     ==> dest_thunk v (insert ptr (ByteArray fl ys) refs) =
         dest_thunk v refs`),
  STRIP_TAC THEN
  CASES_ON_TAC (cake_as_vars (fun () -> `v:dataSem_v`)) THEN
  REWRITE_TAC[dataSem_dest_thunk_def] THEN
  MATCH_REDUCE_TAC THEN TRY (SOLVED (REWRITE_TAC[])) THEN
  ASM_CASES_TAC `a1:num = ptr` THEN
  ASM_REWRITE_TAC[lookup_insert] THEN
  (let ds = [distinctness "option"; distinctness "bvlSem_ref"] in
   REWRITE_TAC (injectivity "option" :: ds @ map GSYM ds)) THEN
  CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN
  REWRITE_TAC[SELECT_REFL; EXISTS_UNIQUE_REFL] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

(* what the insert of a byte array asks of the cell it writes *)
let ByteArray_in_domain = prove
 (cake_as_vars (fun () ->
    `sptree_lookup ptr refs = SOME (bvlSem_ByteArray fl xs)
     ==> (ptr IN domain refs
          ==> ?a b. sptree_lookup ptr refs =
                    SOME (bvlSem_ByteArray a b))`),
  STRIP_TAC THEN DISCH_THEN (K ALL_TAC) THEN
  EXISTS_TAC (cake_as_vars (fun () -> `fl:bool`)) THEN
  EXISTS_TAC (cake_as_vars (fun () -> `xs:(word8)list`)) THEN
  FIRST_ASSUM ACCEPT_TAC);;

(* a byte array has no edge to another reference, so a reference
   that the stack reaches after the update it reached before *)
let reach_refs_update_byte = prove
 (cake_as_vars (fun () ->
    `reachable_refs stack' (insert ptr (ByteArray fl ys) refs) n /\
     sptree_lookup ptr refs = SOME (bvlSem_ByteArray fl xs)
     ==> reachable_refs stack' refs n`),
  STRIP_TAC THEN
  REWRITE_TAC[reachable_refs_def] THEN
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `ref_edge (insert ptr (ByteArray fl ys)
       (refs:((dataSem_v)bvlSem_ref)spt)) = ref_edge refs`))
    (fun e -> FIRST_X_ASSUM (fun rr ->
       if not (hd_is "reachable_refs" (concl rr)) then fail() else
       ACCEPT_TAC (REWRITE_RULE[e]
         (REWRITE_RULE[reachable_refs_def] rr)))) THEN
  REWRITE_TAC[FUN_EQ_THM; ref_edge_def; lookup_insert] THEN
  REPEAT GEN_TAC THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

(* the three transfers that a store into a byte array leaves: of
   the element written the lookup of the heap says which one it is,
   so the heaps of the transfers are the ones of the store *)
let BA_trans = prove
 (cake_as_vars (fun () ->
    `sptree_lookup ptr refs = SOME (bvlSem_ByteArray fl xs) /\
     heap_lookup p (ha ++ [Bytes be fl xs ws] ++ hb) =
       SOME (Bytes be fl xs ws) /\
     LENGTH xs = LENGTH ys
     ==> (!w1 w2. v_inv conf w1 refs
                    (w2,f,tf,ha ++ [Bytes be fl xs ws] ++ hb)
                  ==> v_inv conf w1
                        (insert ptr (ByteArray fl ys) refs)
                        (w2,f,tf,ha ++ [Bytes be fl ys ws] ++ hb)) /\
         (!w. dest_thunk w refs = NotThunk
              ==> dest_thunk w (insert ptr (ByteArray fl ys) refs) =
                  NotThunk) /\
         (!m. ~(m = ptr)
              ==> sptree_lookup m
                    (insert ptr (ByteArray fl ys) refs) =
                  sptree_lookup m refs)`),
  DISCH_THEN (fun hs ->
    let lk = CONJUNCT1 hs in
    REPEAT CONJ_TAC THENL
     [REPEAT GEN_TAC THEN
      DISCH_THEN (fun vi ->
        MATCH_ACCEPT_TAC (MATCH_MP v_inv_ByteArray_insert
          (CONJ (MATCH_MP v_inv_IMP vi)
            (MATCH_MP ByteArray_in_domain lk))));
      GEN_TAC THEN
      REWRITE_TAC[MATCH_MP dest_thunk_insert_ByteArray lk] THEN
      DISCH_THEN ACCEPT_TAC;
      REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[lookup_insert]]));;

(* the element that a heap holds at the length of a prefix *)
let heap_lookup_at = prove
 (  `!ha u hb. heap_lookup (heap_length ha) (ha ++ [u] ++ hb) = SOME u`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[GSYM APPEND_ASSOC;
              data_to_word_memoryProof_heap_lookup_APPEND;
              LT_REFL; SUB_REFL; heap_length_clauses;
              ADD_CLAUSES] THEN
  COND_CASES_TAC THEN
  REWRITE_TAC[APPEND; heap_lookup_def] THEN
  POP_ASSUM MP_TAC THEN
  REWRITE_TAC[] THEN
  MESON_TAC[el_length_NOT_0; ARITH_RULE
    `!n. ~(n = 0) ==> 0 < n`]);;

(* the halves of the split of a heap whose element is replaced by
   one of its length, when the cut is above the element: the second
   half is the one it was, and the first is the one it was with the
   element replaced *)
let heap_split_replace2 = prove
 (`!e ha u v hb h1 h2.
     heap_split e (ha ++ [u] ++ hb) = SOME (h1,h2) /\
     el_length u = el_length v /\ heap_length ha < e
     ==> ?h1'. heap_split e (ha ++ [v] ++ hb) = SOME (h1',h2) /\
               (!z. MEM z h1' ==> MEM z h1 \/ z = v)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* the lengths of the halves of the old split, and their append *)
  FIRST_ASSUM (fun hs ->
    if not (is_eq (concl hs)) ||
       not (hd_is "heap_split" (lhand (concl hs))) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_split_heap_length hs)) THEN
  (* so the first half is ha and a piece of what follows it, or ha
     is the first half and a piece, which the cut's place forbids *)
  W(fun (asl,w as gl) ->
    let ap = the_asm (fun c -> is_eq c &&
               hd_is "APPEND" (lhand c) &&
               hd_is "APPEND" (rand c)) gl in
    STRIP_ASSUME_TAC (MATCH_MP APPEND_EQ_APPEND ap)) THEN
  TRY (SOLVED
        (W(fun (asl,w as gl) ->
           let eq = the_asm (fun c -> is_eq c &&
                      hd_is "heap_length" (lhand c) &&
                      is_var (rand c)) gl in
           let lf = rator (lhand (concl eq)) in
           let aps = mapfilter (fun (_,th) ->
             let c = concl th in
             if is_eq c && is_var (lhand c) &&
                type_of (lhand c) = type_of (rand (lhand (concl eq)))
             then AP_TERM lf th else fail()) asl in
           let lt = the_asm (fun c -> hd_is "<" c) gl in
           MAP_EVERY MP_TAC (eq :: lt :: aps)) THEN
         REWRITE_TAC[heap_length_APPEND] THEN ARITH_TAC)) THEN
  (* the piece that the first half has past ha begins with the
     element, so the first half is ha, the element and the rest *)
  W(fun (asl,w as gl) ->
    let eq = the_asm (fun c -> is_eq c && is_var (lhand c) &&
               hd_is "APPEND" (rand c)) gl in
    CASES_ON_TAC (rand (rand (concl eq)))) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[APPEND; APPEND_NIL; CONS_11]) THEN
  SPLIT_ASM_TAC THEN
  TRY (SOLVED
        (W(fun (asl,w as gl) ->
           let eq = the_asm (fun c -> is_eq c &&
                      hd_is "heap_length" (lhand c) &&
                      is_var (rand c)) gl in
           let lf = rator (lhand (concl eq)) in
           let aps = mapfilter (fun (_,th) ->
             let c = concl th in
             if is_eq c && is_var (lhand c) &&
                type_of (lhand c) = type_of (rand (lhand (concl eq)))
             then AP_TERM lf th else fail()) asl in
           let lt = the_asm (fun c -> hd_is "<" c) gl in
           MAP_EVERY MP_TAC (eq :: lt :: aps)) THEN
         REWRITE_TAC[heap_length_APPEND; heap_length_clauses;
                     ADD_CLAUSES] THEN ARITH_TAC)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (lhand c)) ||
       is_var (rand c) then fail() else SUBST_ALL_TAC e)) THEN
  (* so the new heap is ha, the new element and the rest, and the
     split of it at the length of that front is what the goal says
     (heap_split_length) *)
  W(fun (asl,w as gl) ->
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_length" (lhand c) &&
               is_var (rand c)) gl in
    let front = rand (lhand (concl hl)) in
    let ha = lhand front in
    let p = rand (rand front) in
    let vt = find_term (fun t -> is_var t &&
               fst (dest_var t) = "v") w in
    let newfront = list_mk_icomb "APPEND"
                     [ha; list_mk_icomb "CONS" [vt; p]] in
    EXISTS_TAC newfront THEN
    SUBGOAL_THEN (mk_eq (rand (concl hl),
                         list_mk_icomb "heap_length" [newfront]))
      (fun e -> ONCE_REWRITE_TAC[e]) THENL
     [MP_TAC hl THEN
      (let el = the_asm (fun c -> is_eq c &&
                  hd_is "el_length" (lhand c)) gl in
       let ue = mapfilter (fun (_,th) ->
         let c = concl th in
         if not (is_eq c) || not (is_var (lhand c)) ||
            not (is_var (rand c)) ||
            not (type_of (lhand c) = type_of vt) then fail()
         else if fst (dest_var (lhand c)) = "u" then GSYM th
         else th) asl in
       REWRITE_TAC (heap_length_APPEND :: heap_length_clauses ::
                    el :: ue)) THEN
      ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[APPEND] THEN
    REWRITE_TAC[GSYM (CONJUNCT2 APPEND)] THEN
    REWRITE_TAC[APPEND_ASSOC] THEN
    REWRITE_TAC[heap_split_length] THEN
    REWRITE_TAC[MEM_APPEND; MEM] THEN
    MESON_TAC[]));;

(* a byte array is no reference *)
let isRef_Bytes = prove
 (cake_as_vars (fun () ->
    `~(data_to_word_memoryProof_isRef (Bytes be fl bs ws))`),
  REWRITE_TAC[isRef_def; bytes_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  MATCH_REDUCE_TAC THEN
  (let ds = [distinctness "data_to_word_memoryProof_tag"] in
   REWRITE_TAC (isMutTag_def :: ds @ map GSYM ds)));;

(* the kind of the collection survives a store into a byte array:
   the element replaced is no reference, so it is in the first half
   of the split, and the second half is the one it was *)
let gc_kind_byte_update = prove
 (cake_as_vars (fun () ->
    `gc_kind_inv conf a sp sp1 gens
       (ha ++ [Bytes be fl xs ws] ++ hb) /\
     LENGTH xs = LENGTH ys
     ==> gc_kind_inv conf a sp sp1 gens
           (ha ++ [Bytes be fl ys ws] ++ hb)`),
  REWRITE_TAC[gc_kind_inv_def] THEN STRIP_TAC THEN
  W(fun (asl,w) ->
    CASES_ON_TAC (find_term
      (hd_is "data_to_word_config_gc_kind") w)) THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
  MATCH_REDUCE_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  SPLIT_ASM_TAC THEN
  CONJ_TAC THENL
   [(* the generation state (gen_state_ok_update_byte) *)
    W(fun gl ->
      let gs = the_asm (hd_is "gen_state_ok") gl in
      MATCH_ACCEPT_TAC (MATCH_MP gen_state_ok_update_byte gs));
    ALL_TAC] THEN
  (* the element replaced is in the first half, because the second
     holds references only and a byte array is none *)
  W(fun (asl,w as gl) ->
    let hs = the_asm (fun c -> is_eq c &&
               hd_is "heap_split" (lhand c)) gl in
    let args = snd (strip_comb (lhand (concl hs))) in
    let k = el 0 args in
    let hp = el 1 args in
    let lk = ISPECL [lhand hp; lhand (lhand (rand hp));
                     rand (rand hp)] heap_lookup_at in
    SUBGOAL_THEN (list_mk_icomb "<"
                    [list_mk_icomb "heap_length" [lhand hp]; k])
      ASSUME_TAC THENL
     [MP_TAC (MATCH_MP heap_lookup_heap_split (CONJ hs lk)) THEN
      COND_CASES_TAC THENL
       [DISCH_THEN (K ALL_TAC) THEN REWRITE_TAC[];
        DISCH_TAC THEN
        W(fun gl ->
          let ev = the_asm (fun c -> hd_is "ALL" c &&
                     not (is_abs (el 0 (snd (strip_comb c))))) gl in
          let m = the_asm (hd_is "MEM") gl in
          MP_TAC (MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev) m)) THEN
        REWRITE_TAC[isRef_Bytes]];
      ALL_TAC]) THEN
  (* so the split of the new heap keeps the second half *)
  W(fun (asl,w as gl) ->
    let hs = the_asm (fun c -> is_eq c &&
               hd_is "heap_split" (lhand c)) gl in
    let lt = the_asm (fun c -> hd_is "<" c &&
               hd_is "heap_length" (lhand c)) gl in
    let hp = el 1 (snd (strip_comb (lhand (concl hs)))) in
    let k = el 0 (snd (strip_comb (lhand (concl hs)))) in
    let u = lhand (lhand (rand hp)) in
    let vt = find_term (fun t -> hd_is "Bytes" t &&
               not (t = u)) w in
    let pr = rand (rand (concl hs)) in
    let th = ISPECL [k; lhand hp; u; vt; rand (rand hp);
                     lhand pr; rand pr] heap_split_replace2 in
    (* samelen_bytes carries the type variable of the proof that
       made it, so it is matched against the element of the goal *)
    let sl = PART_MATCH lhs (GSYM samelen_bytes)
               (list_mk_icomb "el_length" [u]) in
    STRIP_ASSUME_TAC (MP th (CONJ hs (CONJ sl lt)))) THEN
  W(fun (asl,w as gl) ->
    let hs2 = the_asm (fun c -> is_eq c &&
                hd_is "heap_split" (lhand c) &&
                not (can (find_term (fun t -> is_var t &&
                       fst (dest_var t) = "xs")) (lhand c))) gl in
    let pr = rand (rand (concl hs2)) in
    EXISTS_TAC (lhand pr) THEN EXISTS_TAC (rand pr) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the first half holds no reference: its elements are the old
       ones or the byte array written *)
    REWRITE_TAC[GSYM ALL_MEM] THEN
    REPEAT STRIP_TAC THEN
    W(fun gl ->
      let bd = the_asm (fun c ->
                 length (fst (strip_forall c)) = 1 &&
                 is_imp (snd (strip_forall c)) &&
                 is_disj (rand (snd (strip_forall c)))) gl in
      let m = the_asm (hd_is "MEM") gl in
      STRIP_ASSUME_TAC (MATCH_MP (SPEC_ALL bd) m)) THEN
    TRY (SOLVED
          (W(fun gl ->
             let ev = the_asm (fun c -> hd_is "ALL" c &&
                        is_abs (el 0 (snd (strip_comb c)))) gl in
             let m = the_asm (fun c -> hd_is "MEM" c) gl in
             MP_TAC (MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev) m)) THEN
           CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
           ASM_REWRITE_TAC[])) THEN
    ASM_MESON_TAC[isRef_Bytes]));;

(* the element singled out of a heap, as an append of three *)
let APPEND_SINGLE = prove
 (`!(ha:A list) x hb. ha ++ (x :: hb) = ha ++ [x] ++ hb`,
  REWRITE_TAC[APPEND]);;

(* the annotation that the root of a reference carries is zero
   unless the reference holds a mutable block *)
let ref_ptr_annot_ByteArray = prove
 (cake_as_vars (fun () ->
    `sptree_lookup ptr refs = SOME (bvlSem_ByteArray fl xs)
     ==> ref_ptr_annot conf (sptree_lookup ptr refs) =
         (wordLang_Word (n2w 0):'a word_loc)`),
  DISCH_THEN (fun lk -> REWRITE_TAC[lk; ref_ptr_annot_def]) THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

(* the elements of a heap other than the one replaced are where
   they were: a lookup below the element lands in the front, and
   one above it skips an element of the length it had *)
let heap_lookup_other_replace = prove
 (`!ha u v hb.
     el_length u = el_length v
     ==> !m y. ~(m = heap_length ha) /\
               heap_lookup m (ha ++ [u] ++ hb) = SOME y
               ==> heap_lookup m (ha ++ [v] ++ hb) = SOME y`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[GSYM APPEND_ASSOC;
              data_to_word_memoryProof_heap_lookup_APPEND;
              heap_length_clauses; ADD_CLAUSES; heap_lookup_def] THEN
  REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
  POP_ASSUM MP_TAC THEN
  COND_CASES_TAC THEN REWRITE_TAC[] THEN
  (* the element itself is not looked up, so the lookup is past it *)
  W(fun (asl,w) ->
    let c = find_term (fun t -> is_eq t && hd_is "-" (lhand t) &&
              rand t = `0`) w in
    SUBGOAL_THEN (mk_neg c) ASSUME_TAC) THENL
   [W(fun gl ->
      let lt = the_asm (fun c -> is_neg c && hd_is "<" (rand c)) gl in
      let ne = the_asm (fun c -> is_neg c && is_eq (rand c) &&
                 hd_is "heap_length" (rand (rand c))) gl in
      MP_TAC lt THEN MP_TAC ne) THEN ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* which for a store into a byte array is the heap transfer that
   the lemmas about the invariant of another reference ask for *)
let heap_lookup_byte_other = prove
 (cake_as_vars (fun () ->
    `heap_lookup p (ha ++ [Bytes be fl xs ws] ++ hb) =
       SOME (Bytes be fl xs ws) /\
     p = heap_length ha /\
     LENGTH xs = LENGTH ys
     ==> !m y. ~(m = p) /\
               heap_lookup m (ha ++ [Bytes be fl xs ws] ++ hb) =
                 SOME y
               ==> heap_lookup m (ha ++ [Bytes be fl ys ws] ++ hb) =
                     SOME y`),
  STRIP_TAC THEN
  FIRST_X_ASSUM (fun e ->
    let c = concl e in
    if not (is_eq c) || not (is_var (lhand c)) ||
       not (hd_is "heap_length" (rand c)) then fail() else
    SUBST_ALL_TAC e) THEN
  W(fun (asl,w as gl) ->
    let hl = the_asm (fun c -> is_eq c &&
               hd_is "heap_lookup" (lhand c)) gl in
    let old = el 1 (snd (strip_comb (lhand (concl hl)))) in
    let u = lhand (lhand (rand old)) in
    let nw = byte_heap_not u w in
    let v = lhand (lhand (rand nw)) in
    MATCH_ACCEPT_TAC (MP (ISPECL [lhand old; u; v; rand (rand old)]
                            heap_lookup_other_replace)
      (PART_MATCH lhs (GSYM samelen_bytes)
         (list_mk_icomb "el_length" [u])))));;

(* the invariant of the reference written when a byte array is
   stored: the element is the one the store wrote, and the bytes
   are as many as they were *)
let bc_ref_inv_update_byte_at = prove
 (cake_as_vars (fun () ->
    `FLOOKUP (f:(num,num)fmap) ptr = SOME p /\
     heap_lookup p (ha ++ [Bytes be fl xs ws] ++ hb) =
       SOME (Bytes be fl xs ws) /\
     p = heap_length ha /\
     sptree_lookup ptr refs = SOME (bvlSem_ByteArray fl xs) /\
     LENGTH xs = LENGTH ys /\
     ws = REPLICATE (LENGTH xs DIV (dimindex (:'a) DIV 8) + 1)
            ((n2w 0):'a word)
     ==> bc_ref_inv conf ptr (insert ptr (ByteArray fl ys) refs)
           (f,tf2,ha ++ [Bytes be fl ys ws] ++ hb,be)`),
  STRIP_TAC THEN
  W(fun (asl,w as gl) ->
    let lk1 = the_asm (fun c -> is_eq c &&
                hd_is "FLOOKUP" (lhand c)) gl in
    let ins = find_term (hd_is "sptree_insert") w in
    let iargs = snd (strip_comb ins) in
    SUBGOAL_THEN (mk_eq (list_mk_icomb "sptree_lookup"
                           [el 0 iargs; ins],
                         list_mk_icomb "SOME" [el 1 iargs]))
      (fun lkn -> REWRITE_TAC[MATCH_MP arm_BA (CONJ lk1 lkn)]) THENL
     [REWRITE_TAC[lookup_insert]; ALL_TAC]) THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  W(fun gl ->
    let pe = the_asm (fun c -> is_eq c && is_var (lhand c) &&
               hd_is "heap_length" (rand c)) gl in
    ONCE_REWRITE_TAC[pe]) THEN
  ASM_REWRITE_TAC[heap_lookup_at]);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let update_byte_ref_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf ((RefPtr b ptr) :: stack) refs
  (roots,heap,be,a,sp,sp1,gens) limit ts /\
      (lookup ptr refs = SOME (ByteArray fl xs)) /\ (LENGTH xs =
        LENGTH ys) ==>
      (?roots2 h1 h2 ws.
        (roots = gc_shared_Pointer (heap_length h1) ((wordLang_Word
          (n2w 0)):'a word_loc) :: roots2) /\
        heap = h1 ++ [Bytes be fl xs ws] ++ h2 /\
        LENGTH ws = LENGTH xs DIV (dimindex (:'a) DIV 8) + 1 /\
        abs_ml_inv conf ((RefPtr b ptr) :: stack) (insert ptr
          (ByteArray fl ys) refs)
          (roots,h1 ++ [Bytes be fl ys ws] ++
            h2,be,a,sp,sp1,gens) limit ts)`),
  (* the steps are above the statement (tools/overrides.py).  The
     root of the pointer is the address of its reference, which
     v_inv of a pointer gives in the first of its three ways,
     because the reference holds an array of bytes, and the
     annotation that such a root carries is zero; the invariant of
     the reference gives the element of the heap that holds the
     bytes, and heap_lookup_SPLIT cuts the heap at it.  The store
     writes an element of the length it replaces, so the heap, the
     roots and the unused space are as good as they were, and of
     the reference written the invariant is the element with the
     bytes put in while of any other one it is the element it had,
     which the store did not touch *)
  (STRIP_TAC THEN
    (* what the invariant says of the stack with the pointer on it *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    (* the roots are the one of the pointer and the rest *)
    SPLIT_ROOTS_TAC THEN
    (* and the root of the pointer is the address of its reference *)
    FIRST_ASSUM (fun vr ->
      let c = concl vr in
      if not (hd_is "v_inv" c) ||
         not (hd_is "dataSem_RefPtr" (el 1 (snd (strip_comb c))))
      then fail()
      else STRIP_ASSUME_TAC (REWRITE_RULE[v_inv_def] vr)) THEN
    (* of the three ways a pointer is related only the first is left,
       because the reference holds an array of bytes: the two that
       are about a thunk say the reference holds one *)
    (let rws = distinctness "thunk_mode" :: ref_rws in
     RULE_ASSUM_TRY (REWRITE_RULE rws) THEN
     TRY (FIRST_ASSUM CONTR_TAC) THEN
     TRY (W(fun (asl,_) ->
       let lks = mapfilter (fun (_,th) ->
                   let c = concl th in
                   if is_eq c && hd_is "sptree_lookup" (lhand c) &&
                      hd_is "SOME" (rand c) then th else fail()) asl in
       if length lks < 2 then fail() else
       MP_TAC (TRANS (SYM (el 0 lks)) (el 1 lks)) THEN
       REWRITE_TAC (injectivity "option" ::
                    injectivity "bvlSem_ref" :: rws) THEN
       STRIP_TAC)) THEN
     SPLIT_ASM_TAC THEN
     TRY VAR_EQ_TAC) THEN
    (* the annotation that the root of an array of bytes carries is
       zero *)
    W(fun gl ->
      let lk = the_asm (fun c -> is_eq c &&
                 hd_is "sptree_lookup" (lhand c) &&
                 hd_is "SOME" (rand c)) gl in
      let an = MATCH_MP ref_ptr_annot_ByteArray lk in
      RULE_ASSUM_TRY (REWRITE_RULE[an]) THEN REWRITE_TAC[an]) THEN
    (* the reference has an address *)
    (SUBGOAL_THEN (cake_as_vars (fun () ->
       `FLOOKUP (f:(num,num)fmap) (ptr:num) = SOME (FAPPLY f ptr:num)`))
       ASSUME_TAC THENL
      [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC]) THEN
    (* and it is reachable, so the invariant holds of it *)
    (SUBGOAL_THEN (cake_as_vars (fun () ->
       `reachable_refs (RefPtr b ptr :: stack) refs ptr`))
       ASSUME_TAC THENL
      [MATCH_MP_TAC (GEN_ALL reach_refptr) THEN
       FIRST [EXISTS_TAC (cake_as_vars (fun () -> `b:bool`));
              ALL_TAC] THEN
       REWRITE_TAC[MEM];
       ALL_TAC]) THEN
    W(fun (asl,w as gl) ->
      let bri = the_asm (fun c ->
        let vs,bd = strip_forall c in
        length vs = 1 && is_imp bd &&
        hd_is "bc_ref_inv" (rand bd)) gl in
      let rr = the_asm (hd_is "reachable_refs") gl in
      let n = el 2 (snd (strip_comb (concl rr))) in
      let nin = the_asm (fun c -> hd_is "IN" c &&
                  hd_is "FDOM" (rand c) &&
                  el 0 (snd (strip_comb c)) = n) gl in
      ASSUME_TAC (MP (SPEC n bri) (CONJ rr nin))) THEN
    (* which is the arm of an array of bytes: the element of the heap
       that holds the bytes *)
    W(fun gl ->
      let lk1 = the_asm (fun c -> is_eq c &&
                  hd_is "FLOOKUP" (lhand c)) gl in
      let lk2 = the_asm (fun c -> is_eq c &&
                  hd_is "sptree_lookup" (lhand c) &&
                  hd_is "SOME" (rand c)) gl in
      FIRST_X_ASSUM (fun inv ->
        if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
        ASSUME_TAC (CONV_RULE(TOP_DEPTH_CONV let_CONV)
          (REWRITE_RULE[MATCH_MP arm_BA (CONJ lk1 lk2)] inv)))) THEN
    (* so the heap is the element and what is around it *)
    W(fun gl ->
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 hd_is "SOME" (rand c)) gl in
      STRIP_ASSUME_TAC (ONCE_REWRITE_RULE[APPEND_SINGLE]
        (MATCH_MP heap_lookup_SPLIT hl))) THEN
    FIRST_X_ASSUM (fun e ->
      let c = concl e in
      if not (is_eq c) || not (is_var (lhand c)) ||
         not (hd_is "APPEND" (rand c)) then fail() else
      SUBST_ALL_TAC e) THEN
    (* the witnesses: the rest of the roots, the heap around the
       element, and the bytes that the element holds *)
    W(fun (asl,w as gl) ->
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 hd_is "SOME" (rand c)) gl in
      let old = el 1 (snd (strip_comb (lhand (concl hl)))) in
      let u = lhand (lhand (rand old)) in
      let rts = lhand (hd (conjuncts (snd (strip_exists w)))) in
      let rts = if not (is_var rts) then rts else
                rand (concl (the_asm (fun c -> is_eq c &&
                               lhand c = rts) gl)) in
      MAP_EVERY EXISTS_TAC
        [rand rts; lhand old; rand (rand old);
         el 3 (snd (strip_comb u))]) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
    TRY (SOLVED (REWRITE_TAC[LENGTH_REPLICATE])) THEN
    (* the addresses that hold data are the ones that held data *)
    (W(fun (asl,w as gl) ->
       let nw = byte_heap w in
       let old = byte_heap (concl (the_asm (hd_is "heap_ok") gl)) in
       let n = genvar `:num` in
       let iso h = list_mk_icomb "isSomeDataElement"
                     [list_mk_icomb "heap_lookup" [n; h]] in
       SUBGOAL_THEN (mk_forall(n, mk_eq (iso nw, iso old)))
         ASSUME_TAC) THENL
     [MATCH_ACCEPT_TAC isSomeDataElement_byte_update; ALL_TAC]) THEN
    (* the elements that the store did not write are where they were
       (heap_lookup_byte_other), and what the invariant, a thunk and
       the other references say is what they said (BA_trans) *)
    W(fun gl ->
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 hd_is "SOME" (rand c)) gl in
      let pe = the_asm (fun c -> is_eq c &&
                 hd_is "fmap_apply" (lhand c) &&
                 hd_is "heap_length" (rand c)) gl in
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "LENGTH" (lhand c)) gl in
      let lk = the_asm (fun c -> is_eq c &&
                 hd_is "sptree_lookup" (lhand c) &&
                 hd_is "SOME" (rand c)) gl in
      MAP_EVERY ASSUME_TAC
        (MATCH_MP heap_lookup_byte_other (CONJ hl (CONJ pe le)) ::
         CONJUNCTS (MATCH_MP BA_trans (CONJ lk (CONJ hl le))))) THEN
    (* and the invariant of the new heap and references *)
    REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the roots are the ones they were, of a heap as good *)
    TRY (SOLVED
          (W(fun gl ->
             let iso = the_asm (fun c ->
               let bd = snd (strip_forall c) in
               is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
             let ro = the_asm (hd_is "roots_ok") gl in
             ACCEPT_TAC (MATCH_MP roots_ok_iso (CONJ ro iso))))) THEN
    (* the heap stays good (heap_ok_byte_update) *)
    TRY (SOLVED
          (W(fun gl ->
             let ho = the_asm (hd_is "heap_ok") gl in
             let le = the_asm (fun c -> is_eq c &&
                        hd_is "LENGTH" (lhand c)) gl in
             MATCH_ACCEPT_TAC (MATCH_MP heap_ok_byte_update
               (CONJ ho le))))) THEN
    (* the kind of the collection (gc_kind_byte_update) *)
    TRY (SOLVED
          (W(fun gl ->
             let gk = the_asm (hd_is "gc_kind_inv") gl in
             let le = the_asm (fun c -> is_eq c &&
                        hd_is "LENGTH" (lhand c)) gl in
             MATCH_ACCEPT_TAC (MATCH_MP gc_kind_byte_update
               (CONJ gk le))))) THEN
    (* and the unused space (unused_space_inv_byte_update) *)
    TRY (SOLVED
          (W(fun gl ->
             let us = the_asm (hd_is "unused_space_inv") gl in
             MATCH_ACCEPT_TAC (MATCH_MP unused_space_inv_byte_update
               us)))) THEN
    (* the maps of the new invariant: the addresses are the ones they
       were, and the timestamps are cut to the ones of the new
       references and stack *)
    W(fun (asl,w as gl) ->
      if not (is_exists w) then ALL_TAC else
      (let sub p = rand (lhand (concl (the_asm (fun c ->
         hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
       let ats = find_term (hd_is "all_ts") w in
       EXISTS_TAC (sub "domain") THEN
       EXISTS_TAC (list_mk_icomb "DRESTRICT" [sub "all_ts"; ats]))) THEN
    REPEAT CONJ_TAC THEN TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the addresses of the maps are the ones of the old heap *)
    TRY (SOLVED
          (W(fun gl ->
             let iso = the_asm (fun c ->
               let bd = snd (strip_forall c) in
               is_eq bd && hd_is "isSomeDataElement" (lhand bd)) gl in
             ONCE_REWRITE_TAC[iso]) THEN
           FIRST [SOLVED (FIRST_ASSUM ACCEPT_TAC);
                  SOLVED (W(fun (asl,w as gl) ->
                    let dr = find_term (hd_is "DRESTRICT") w in
                    let inj = the_asm (fun c -> hd_is "INJ" c &&
                      rand (el 0 (snd (strip_comb c))) = lhand dr) gl in
                    MATCH_ACCEPT_TAC
                      (MATCH_MP INJ_DRESTRICT inj)))])) THEN
    (* the domain of the references has the key in it *)
    TRY (SOLVED
          (REWRITE_TAC[domain_insert] THEN
           MATCH_MP_TAC SUBSET_TRANS THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "domain" (rand c)) gl in
             EXISTS_TAC (rand (concl su))) THEN
           CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
           SET_TAC[])) THEN
    (* the timestamps of the restricted map are of the stack, and
       below the counter *)
    TRY (SOLVED
          (REWRITE_TAC[(CONJUNCT1 o SPEC_ALL) DRESTRICT_DEF] THEN
           FIRST [SOLVED (REWRITE_TAC[INTER_SUBSET]);
                  SOLVED (MATCH_MP_TAC SUBSET_TRANS THEN
                          W(fun gl ->
                            let su = the_asm (fun c ->
                              hd_is "SUBSET" c &&
                              hd_is "FDOM" (lhand c)) gl in
                            EXISTS_TAC (lhand (concl su))) THEN
                          CONJ_TAC THEN
                          TRY (FIRST_ASSUM ACCEPT_TAC) THEN
                          REWRITE_TAC[INTER_SUBSET])])) THEN
    (* the blocks of the stack stay unique *)
    TRY (SOLVED
          (W(fun gl ->
             let bu = the_asm (hd_is "blocks_unique") gl in
             MATCH_ACCEPT_TAC (MATCH_MP blocks_unique_insert_ByteArray
               bu)))) THEN
    (* the values of the stack: the pointer in front and the rest *)
    W(fun (asl,w) -> if not (hd_is "ALL2" w) then ALL_TAC else
      (REWRITE_TAC[ALL2] THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       REPEAT CONJ_TAC THEN
       TRY (SOLVED
             (W(fun (asl,w as gl) ->
                let args = snd (strip_comb w) in
                let v1 = el 1 args in
                let ats = find_term (hd_is "all_ts") w in
                let vi = the_asm (fun c -> hd_is "v_inv" c &&
                           el 1 (snd (strip_comb c)) = v1 &&
                           not (el 2 (snd (strip_comb c)) =
                                  lhand ats)) gl in
                SUBGOAL_THEN
                  (list_mk_icomb "MEM" [v1; rand ats])
                  (fun mm -> MATCH_ACCEPT_TAC (MATCH_MP
                     v_inv_update_gen
                     (CONJ (a_vtr gl) (CONJ vi
                       (MP (SPECL [v1; rand ats; lhand ats]
                             MEM_stack_all_vs) mm))))) THEN
                REWRITE_TAC[MEM]))) THEN
       W(fun (asl,w as gl) ->
         let old = the_asm (fun c -> hd_is "ALL2" c &&
                     el 1 (snd (strip_comb c)) =
                       el 1 (snd (strip_comb w))) gl in
         let ats = find_term (hd_is "all_ts") w in
         let vs = el 1 (snd (strip_comb w)) in
         let v = genvar (hd (snd (dest_type (type_of (rand ats))))) in
         SUBGOAL_THEN
           (mk_forall(v, mk_imp(list_mk_icomb "MEM" [v; vs],
              list_mk_icomb "IN"
                [v; list_mk_icomb "all_vs" [lhand ats; rand ats]])))
           (fun mem -> ACCEPT_TAC (MATCH_MP EVERY2_v_inv_update_stack
              (CONJ (a_vtr gl) (CONJ mem old)))) THEN
         REPEAT STRIP_TAC THEN
         W(fun gl ->
           let mm = the_asm (hd_is "MEM") gl in
           let v1 = el 0 (snd (strip_comb (concl mm))) in
           SUBGOAL_THEN (list_mk_icomb "MEM" [v1; rand ats])
             (fun m2 -> MATCH_ACCEPT_TAC (MP (SPECL [v1; rand ats;
                          lhand ats] MEM_stack_all_vs) m2)) THEN
           ASM_REWRITE_TAC[MEM])))) THEN
    (* and the invariant of each reference that the stack reaches: it
       was reachable before the store (reach_refs_update_byte) *)
    W(fun (asl,w) -> if not (is_forall w) then ALL_TAC else
      (REPEAT STRIP_TAC THEN
       W(fun gl ->
         let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                    hd_is "sptree_insert"
                      (el 1 (snd (strip_comb c)))) gl in
         ASSUME_TAC (MATCH_MP reach_refs_update_byte
           (CONJ rr (a_lkptr gl)))) THEN
       W(fun (asl,w as gl) ->
         let n = el 1 (snd (strip_comb w)) in
         let bri = the_asm (fun c ->
           let vs,bd = strip_forall c in
           length vs = 1 && is_imp bd &&
           hd_is "bc_ref_inv" (rand bd)) gl in
         let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
           not (hd_is "sptree_insert"
                  (el 1 (snd (strip_comb c))))) gl in
         let nin = the_asm (fun c -> hd_is "IN" c &&
           hd_is "FDOM" (rand c) &&
           el 0 (snd (strip_comb c)) = n) gl in
         ASSUME_TAC (MP (SPEC n bri) (CONJ rr nin))) THEN
       (* the reference written, or another one *)
       W(fun (asl,w as gl) ->
         ASM_CASES_TAC (mk_eq (el 1 (snd (strip_comb w)),
                               g_ptr gl))) THEN
       TRY VAR_EQ_TAC THEN
       (* the one written: the element holds the bytes put in *)
       TRY (SOLVED
             (W(fun gl ->
                let lk1 = the_asm (fun c -> is_eq c &&
                            hd_is "FLOOKUP" (lhand c)) gl in
                let hl = the_asm (fun c -> is_eq c &&
                           hd_is "heap_lookup" (lhand c) &&
                           hd_is "SOME" (rand c)) gl in
                let pe = the_asm (fun c -> is_eq c &&
                           hd_is "fmap_apply" (lhand c) &&
                           hd_is "heap_length" (rand c)) gl in
                let le = the_asm (fun c -> is_eq c &&
                           hd_is "LENGTH" (lhand c)) gl in
                let ws = el 3 (snd (strip_comb
                           (rand (rand (concl hl))))) in
                MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_byte_at
                  (CONJ lk1 (CONJ hl (CONJ pe (CONJ (a_lkptr gl)
                    (CONJ le (REFL ws)))))))))) THEN
       (* another one: its element did not move *)
       TRY (SOLVED
             (W(fun (asl,w as gl) ->
                let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
                let inj = the_asm (fun c -> hd_is "INJ" c &&
                            rand (el 0 (snd (strip_comb c))) = fm) gl in
                let pin = the_asm (fun c -> hd_is "IN" c &&
                            hd_is "FDOM" (rand c) &&
                            el 0 (snd (strip_comb c)) = g_ptr gl) gl in
                let neq = the_asm (fun c -> is_neg c &&
                            is_eq (rand c) &&
                            rand (rand c) = g_ptr gl) gl in
                let inv = the_asm (hd_is "bc_ref_inv") gl in
                MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_update_other_gen
                  (CONJ inj (CONJ pin (CONJ neq (CONJ (a_vtr gl)
                    (CONJ (a_dtr gl) (CONJ (a_ltr gl)
                      (CONJ (a_tr gl) inv))))))))))))) THEN
    ALL_TAC));;

(* [local] *)
let heap_store_unused_thm = prove
 (`!a n heap h1 h2 heap2 x.
     heap_split (a + n) heap = SOME (h1,h2) /\
     heap_store_unused a n x heap = (heap2,T) /\
     unused_space_inv a (n - el_length x) heap2 ==>
     (?h0. h1 = h0 ++ [Unused (n - 1)] /\
          heap = h1 ++ h2 /\ heap_length h0 = a /\
          heap2 = h0 ++ heap_expand (n - el_length x) ++ [x] ++ h2)`,
  (* the store goes where the unused element of the split sits: the
     split is as long as the space, so what is left of it after
     that element is empty, and then heap_store_lemma says what
     the heap becomes *)
  ((* the head constant of a term, by name *)
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   (* the assumption that a test picks out *)
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* an element of a heap is at least one word long *)
   let elpos = prove
    (`!y:(A,B)heap_element. 0 < el_length y`,
     GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `y:(A,B)heap_element`
       (cases_of `:(A,B)heap_element`)) THEN
     REWRITE_TAC[el_length_def] THEN ARITH_TAC) in
   (* the length of a heap, clause by clause *)
   let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) =
              el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   (* so a heap of no length is empty *)
   let hlen0 = prove
    (`!hb:((A,B)heap_element)list. heap_length hb = 0 ==> hb = []`,
     LIST_INDUCT_TAC THEN
     REWRITE_TAC[hlen_cl; NOT_CONS_NIL] THEN
     MP_TAC(ISPEC `h:(A,B)heap_element` elpos) THEN ARITH_TAC) in
   REPEAT GEN_TAC THEN
   REWRITE_TAC[heap_store_unused_def] THEN
   COND_CASES_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
   POP_ASSUM(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
   STRIP_TAC THEN
   FIRST_ASSUM(fun hs ->
     MP_TAC(MATCH_MP heap_split_heap_length hs)) THEN
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   SUBGOAL_THEN `0 < n` ASSUME_TAC THENL
    [ASM_MESON_TAC[elpos; LTE_TRANS]; ALL_TAC] THEN
   FIRST_ASSUM(fun eq ->
     if is_eq (concl eq) && hd_is "APPEND" (lhand (concl eq))
     then SUBST_ALL_TAC (SYM eq) else fail()) THEN
   (* the lookup is inside the first half of the split *)
   W(fun (asl,w) ->
     let hl = grab asl (fun th ->
       hd_is "heap_lookup" (lhand (concl th))) in
     let ap = rand (lhand (concl hl)) in
     SUBGOAL_THEN (subst [lhand ap,ap] (concl hl)) ASSUME_TAC THENL
      [MP_TAC(REWRITE_RULE
         [data_to_word_memoryProof_heap_lookup_APPEND] hl) THEN
       ASM_SIMP_TAC[ARITH_RULE `0 < n ==> a < a + n`] THEN
       TRY(DISCH_THEN ACCEPT_TAC);
       ALL_TAC]) THEN
   FIRST_ASSUM(fun hl ->
     if hd_is "heap_lookup" (lhand (concl hl)) &&
        is_var (rand (lhand (concl hl)))
     then MP_TAC(MATCH_MP heap_lookup_SPLIT hl) else fail()) THEN
   DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
   FIRST_ASSUM(fun eq ->
     if is_eq (concl eq) && is_var (lhs (concl eq)) &&
        hd_is "APPEND" (rhs (concl eq))
     then SUBST_ALL_TAC eq else fail()) THEN
   (* what is left of the split after that element is empty *)
   W(fun (asl,w) ->
     MP_TAC(ISPEC (var_by_name "hb" (asl,w)) hlen0)) THEN
   ANTS_TAC THENL
    [FIRST_ASSUM(fun hl ->
       if is_eq (concl hl) &&
          hd_is "heap_length" (lhand (concl hl)) &&
          hd_is "+" (rand (concl hl))
       then MP_TAC(REWRITE_RULE[heap_length_APPEND; hlen_cl;
                                el_length_def] hl)
       else fail()) THEN
     MP_TAC(ASSUME `0 < n`) THEN
     FIRST_ASSUM(fun ae ->
       if is_eq (concl ae) && is_var (lhs (concl ae)) &&
          hd_is "heap_length" (rhs (concl ae))
       then SUBST1_TAC ae else fail()) THEN
     ARITH_TAC;
     ALL_TAC] THEN
   DISCH_THEN SUBST_ALL_TAC THEN
   W(fun (asl,w) -> EXISTS_TAC (var_by_name "ha" (asl,w))) THEN
   REPEAT CONJ_TAC THEN TRY(REWRITE_TAC[] THEN NO_TAC) THEN
   TRY(FIRST_ASSUM(fun ae -> ACCEPT_TAC (SYM ae))) THEN
   (* and the store puts what it stores where that element was *)
   FIRST_ASSUM(fun hs ->
     if hd_is "heap_store" (lhand (concl hs))
     then MP_TAC(REWRITE_RULE[GSYM APPEND_ASSOC; APPEND] hs)
     else fail()) THEN
   FIRST_ASSUM(fun ae ->
     if is_eq (concl ae) && is_var (lhs (concl ae)) &&
        hd_is "heap_length" (rhs (concl ae))
     then SUBST1_TAC ae else fail()) THEN
   REWRITE_TAC[heap_store_lemma; PAIR_EQ] THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM) (K ALL_TAC)) THEN
   REWRITE_TAC[GSYM APPEND_ASSOC; APPEND]));;

let heap_store_unused_heap_lookup = prove
 (`!heap heap2 a k x n.
      heap_store_unused a k x heap = (heap2,T) /\ n < a ==>
      heap_lookup n heap = heap_lookup n heap2`,
  (* and the same for the store that keeps the unused space at the
     end *)
  (REPEAT GEN_TAC THEN
   REWRITE_TAC[heap_store_unused_def] THEN
   COND_CASES_TAC THENL
    [MATCH_ACCEPT_TAC heap_store_heap_lookup;
     REWRITE_TAC[PAIR_EQ]]));;

(* [local] *)
let heap_store_unused_gen_state_ok = prove
 (`heap_store_unused a k x heap = (heap2,T) /\
   gen_state_ok a (a + k) heap gens ==>
   gen_state_ok a ((a + k) - el_length x) heap2 gens`,
  (* a start of a generation is below a, so the split of the heap
     there is the split of the stored heap (heap_split_heap_store),
     with the same first half; and the references start lower than
     before, which is a weaker bound on the pointers.  The transfer
     is a lemma with type variables of its own, so that it can be
     used on the heaps of the goal (PORTING-GUIDE.md entry 25) *)
  (
   let transfer = prove
    (`!(hp:((A,B)heap_element)list) hp2 aa kk xx ss.
        heap_store aa (heap_expand (kk - el_length xx) ++ [xx]) hp =
          (hp2,T) /\
        ss <= aa /\ gen_start_ok hp (aa + kk) ss
        ==> gen_start_ok hp2 ((aa + kk) - el_length xx) ss`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[gen_start_ok_def] THEN
     DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
       (REPEAT_TCL CHOOSE_THEN
         (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
     FIRST_ASSUM(fun hs -> FIRST_ASSUM(fun sp -> FIRST_ASSUM(fun le ->
       MP_TAC(MATCH_MP heap_split_heap_store
         (CONJ sp (CONJ hs le)))))) THEN
     DISCH_THEN(X_CHOOSE_THEN `h3:((A,B)heap_element)list`
       ASSUME_TAC) THEN
     ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[] THEN
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     FIRST_ASSUM(fun pc -> FIRST_ASSUM(fun m1 -> FIRST_ASSUM(fun m2 ->
       MP_TAC(MATCH_MP pc (CONJ m1 m2))))) THEN
     ARITH_TAC) in
   STRIP_TAC THEN CASES_ON_NAME "gens" THEN
   RULE_ASSUM_TAC(REWRITE_RULE[gen_state_ok_def]) THEN
   REWRITE_TAC[gen_state_ok_def] THEN
   USE_CHANGED [heap_store_unused_def] THEN
   COND_CASES_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
   FIRST [DISCH_THEN(fun th ->
            CONTR_TAC(REWRITE_RULE[] (CONJUNCT2 th)));
          DISCH_TAC] THEN
   FIRST_ASSUM(fun gs ->
     let c1 = CONJUNCT1 gs and c2 = CONJUNCT2 gs in
     CONJ_TAC THENL
      [ACCEPT_TAC c1;
       MATCH_MP_TAC ALL_IMP THEN
       EXISTS_TAC (lhand (concl c2)) THEN
       CONJ_TAC THENL
        [GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC transfer THEN
         W(fun (asl,w) ->
           let hs = find (fun (_,th) ->
             (try fst(dest_const(fst(strip_comb(lhand(concl th))))) =
                  "heap_store"
              with Failure _ -> false)) asl in
           EXISTS_TAC (el 2 (snd(strip_comb
             (lhand (concl (snd hs))))))) THEN
         ASM_REWRITE_TAC[] THEN
         FIRST_ASSUM(fun m ->
           ACCEPT_TAC(MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] c1) m));
         ACCEPT_TAC c2]])));;

(* new ref *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_new_ref = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (xs ++ stack)) ==>
       blocks_unique ts
         (all_vs (insert ptr (ValueArray xs) refs)
            (xs ++ (RefPtr T ptr :: stack)))`),
  (* the ValueArray of the new reference holds the values that the
     stack has in front of it already *)
  (let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let vrefptr = prove
    (`!b p ys. v_all_vs (CONS (RefPtr b p) ys) =
        CONS (RefPtr b p) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let inc = prove
    (`!refs p xs stack' t a q.
        Block t a q IN
          all_vs (insert p (ValueArray xs) refs)
                 (APPEND xs (CONS (RefPtr T p) stack')) ==>
        Block t a q IN all_vs refs (APPEND xs stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; li;
                 vrefptr; v_all_vs_append; MEM; MEM_APPEND;
                 distinctness "dataSem_v";
                 distinctness "bvlSem_ref";
                 injectivity "bvlSem_ref"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: what the proof of new_ref_thm needs.  The
   element is written at the top of the unused space, where it is
   a reference and so belongs to the second half of the split that
   a generational collection goes by (gc_kind_store_unused); the
   references gain a key that they did not have, which holds the
   values that the stack has in front of it, so a path through the
   new references is one of the old ones or starts inside those
   values (reachable_refs_new_ref), and what the invariant said of
   a value it says of it with the key written and the store done
   (v_inv_new_ref_step) *)

(* the kind of the collection survives a store into the unused
   space at its top: the state of the generations is what
   heap_store_unused_gen_state_ok says, and the split of the new
   heap is lower by the element, which is a reference and so goes
   into the second half *)
let gc_kind_store_unused = prove
 (cake_as_vars (fun () ->
    `data_to_word_memoryProof_isRef x /\ el_length x <= sp /\
     gc_kind_inv conf a sp sp1 gens heap /\
     heap_store_unused a (sp + sp1) x heap = (heap2,T) /\
     unused_space_inv a ((sp + sp1) - el_length x) heap2
     ==> gc_kind_inv conf a (sp - el_length x) sp1 gens heap2`),
  REWRITE_TAC[gc_kind_inv_def] THEN STRIP_TAC THEN
  W(fun (asl,w) ->
    CASES_ON_TAC (find_term
      (hd_is "data_to_word_config_gc_kind") w)) THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
  MATCH_REDUCE_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  SPLIT_ASM_TAC THEN
  CONJ_TAC THENL
   [(* the state of the generations *)
    W(fun (asl,w as gl) ->
      let gs = the_asm (hd_is "gen_state_ok") gl in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused" (lhand c)) gl in
      let th = MATCH_MP heap_store_unused_gen_state_ok
                 (CONJ st gs) in
      let addr = el 1 (snd (strip_comb w)) in
      let addr2 = el 1 (snd (strip_comb (concl th))) in
      SUBGOAL_THEN (mk_eq (addr, addr2)) SUBST1_TAC THENL
       [ASM_ARITH_TAC; MATCH_ACCEPT_TAC th]);
    ALL_TAC] THEN
  (* the shape of the new heap: what was below the space, the space
     that is left, the element written and the references *)
  W(fun (asl,w as gl) ->
    let hs = the_asm (fun c -> is_eq c &&
               hd_is "heap_split" (lhand c)) gl in
    let st = the_asm (fun c -> is_eq c &&
               hd_is "heap_store_unused" (lhand c)) gl in
    let us = the_asm (fun c -> hd_is "unused_space_inv" c &&
               can (find_term (hd_is "-")) c) gl in
    STRIP_ASSUME_TAC (MATCH_MP heap_store_unused_thm
      (CONJ hs (CONJ st us)))) THEN
  W(fun (asl,w as gl) ->
    let st = the_asm (fun c -> is_eq c &&
               hd_is "heap_store_unused" (lhand c)) gl in
    let heap2 = lhand (rand (concl st)) in
    let sh = the_asm (fun c -> is_eq c && lhand c = heap2 &&
               hd_is "APPEND" (rand c)) gl in
    let rhs = rand (concl sh) in
    let pre = list_mk_icomb "APPEND" [lhand rhs; lhand (rand rhs)] in
    let rest = rand (rand rhs) in
    let addr = el 0 (snd (strip_comb
                 (lhand (hd (conjuncts (snd (strip_exists w))))))) in
    EXISTS_TAC pre THEN EXISTS_TAC rest THEN
    REPEAT CONJ_TAC THENL
     [(* the split of the new heap is lower by the element *)
      SUBGOAL_THEN (mk_eq (heap2,
                      list_mk_icomb "APPEND" [pre; rest]))
        (fun e -> ONCE_REWRITE_TAC[e]) THENL
       [ONCE_REWRITE_TAC[sh] THEN REWRITE_TAC[APPEND_ASSOC];
        ALL_TAC] THEN
      SUBGOAL_THEN (mk_eq (list_mk_icomb "heap_length" [pre], addr))
        (fun le -> MATCH_ACCEPT_TAC (MATCH_MP heap_split_pre le)) THEN
      REWRITE_TAC[heap_length_APPEND; heap_length_clauses;
                  heap_length_heap_expand] THEN
      ASM_ARITH_TAC;
      (* no element below the split is a reference: of what was
         below the space the old split says so, and the space holds
         no element *)
      REWRITE_TAC[ALL_APPEND] THEN
      CONJ_TAC THEN
      TRY (SOLVED (MATCH_ACCEPT_TAC isRef_heap_expand)) THEN
      W(fun gl ->
        let ev = the_asm (fun c -> hd_is "ALL" c &&
                   is_abs (el 0 (snd (strip_comb c)))) gl in
        let sh1 = the_asm (fun c -> is_eq c &&
                    el 1 (snd (strip_comb (concl ev))) = lhand c &&
                    hd_is "APPEND" (rand c)) gl in
        MP_TAC (REWRITE_RULE[sh1; ALL_APPEND] ev)) THEN
      DISCH_THEN (ACCEPT_TAC o CONJUNCT1);
      (* and the element written is a reference, as are the ones
         that were above the space *)
      REWRITE_TAC[ALL_APPEND; ALL] THEN
      REPEAT CONJ_TAC THEN
      TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC))]));;

(* the edges that the references gain when an array of values is
   written at a key they did not have leave that key and land
   inside the values *)
let ref_edge_ValueArray = prove
 (cake_as_vars (fun () ->
    `ref_edge (sptree_insert ptr (ValueArray xs) refs) x y =
     (if x = ptr then MEM y (get_refs (Block 0 ARB xs))
      else ref_edge refs x y)`),
  REWRITE_TAC[ref_edge_def; lookup_insert] THEN
  COND_CASES_TAC THEN REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[]);;

(* [local] *)
let reachable_refs_new_ref_lemma = prove
 (cake_as_vars (fun () ->
    `!r1 n.
       RTC (ref_edge (sptree_insert ptr (ValueArray xs) refs)) r1 n
       ==> ~(n = ptr) ==>
       RTC (ref_edge refs) r1 n \/
       (?s. MEM s (get_refs (Block 0 ARB xs)) /\
            RTC (ref_edge refs) s n)`),
  (* induction along the reflexive transitive closure: an edge of
     the new references is one of the old ones, or it leaves the
     key and lands inside the values *)
  MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN DISJ1_TAC THEN
    MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
    REPEAT GEN_TAC THEN
    REWRITE_TAC[ref_edge_ValueArray] THEN
    COND_CASES_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
    ASM_MESON_TAC[RTC_RULES]]);;

(* so a reference that the stack with the pointer of the array on
   it reaches is one that the values of the array and the rest of
   the stack reach *)
let reachable_refs_new_ref = prove
 (cake_as_vars (fun () ->
    `reachable_refs (xs ++ (RefPtr T ptr :: stack))
       (sptree_insert ptr (ValueArray xs) refs) n /\ ~(n = ptr) /\
     ~(ptr IN domain refs)
     ==> reachable_refs (xs ++ stack) refs n`),
  (* reachable_refs_new_ref_lemma says of a path through the new
     references that it is one of the old ones or that it starts
     inside the values of the array.  A root of the stack keeps its
     path; the only other root is the pointer of the array, whose
     path cannot start at all, because the key is fresh and so has
     no edge; and a path from the values has its root among them *)
  (let mem_block_refs = prove
    (`!(ys:(dataSem_v)list) ss tt aa.
        MEM ss (get_refs (Block tt aa ys))
        ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   let subst_vars =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_eq(concl th) && is_var(lhand(concl th))
       then SUBST_ALL_TAC th else fail())) in
   let payload b =
     X_CHOOSE_THEN `ss:num` (CONJUNCTS_THEN2
       (fun m -> MP_TAC(MATCH_MP mem_block_refs m)) ASSUME_TAC) b THEN
     DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v` STRIP_ASSUME_TAC) THEN
     MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `ss:num`] THEN
     ASM_REWRITE_TAC[MEM_APPEND] in
   let noedge a =
     MP_TAC(ONCE_REWRITE_RULE[RTC_CASES] a) THEN
     FIRST_ASSUM(fun nd ->
       let th = REWRITE_RULE[GSYM lookup_NONE_domain] nd in
       if concl th = concl nd then fail()
       else REWRITE_TAC[ref_edge_def; th]) THEN
     MATCH_REDUCE_TAC THEN ASM_REWRITE_TAC[] in
   let stackcase a =
     ASSUME_TAC a THEN
     W(fun gl ->
       let m = the_asm (fun c -> hd_is "MEM" c &&
                 hd_is "get_refs" (rand c)) gl in
       EXISTS_TAC (el 0 (snd (strip_comb (rand (concl m))))) THEN
       EXISTS_TAC (el 0 (snd (strip_comb (concl m))))) THEN
     ASM_REWRITE_TAC[MEM_APPEND] in
   let uselemma =
     FIRST_ASSUM(fun rtc -> FIRST_ASSUM(fun ne ->
       MP_TAC(MATCH_MP (MATCH_MP
         reachable_refs_new_ref_lemma rtc) ne))) in
   REWRITE_TAC[reachable_refs_def; MEM_APPEND; MEM] THEN
   STRIP_TAC THENL
    [uselemma THEN DISCH_THEN(DISJ_CASES_THEN2 stackcase payload);
     subst_vars THEN
     RULE_ASSUM_TAC(REWRITE_RULE[get_refs_def; MEM]) THEN
     subst_vars THEN uselemma THEN
     DISCH_THEN(DISJ_CASES_THEN2 noedge payload);
     uselemma THEN DISCH_THEN(DISJ_CASES_THEN2 stackcase payload)]));;

(* and what the invariant says of a value it says of it with the
   array written and the store done *)
let v_inv_new_ref_step = prove
 (cake_as_vars (fun () ->
    `v_inv conf w1 refs (w2,f,tf,heap) /\ ~(ptr IN domain refs) /\
     FDOM f SUBSET domain refs /\ heap_store_rel heap heap2 /\
     f2 = f |+ (ptr,aa) /\
     refs2 = sptree_insert ptr (ValueArray xs) refs
     ==> v_inv conf w1 refs2 (w2,f2,tf,heap2)`),
  (* the key is fresh in the references, so it is not in the domain
     of the map and the map is a SUBMAP of its update there;
     v_inv_SUBMAP takes the relation to the bigger map and the
     bigger heap, and v_inv_ValueArray_insert writes the array into
     the references, with the heap it had (RefBlock_inv is then
     nothing) *)
  (let submap_fupd = prove
    (`!(g:(A,B)fmap) k v. ~(k IN FDOM g) ==> g SUBMAP (g |+ (k,v))`,
     REWRITE_TAC[SUBMAP; FDOM_FUPDATE; IN_INSERT;
                 FAPPLY_FUPDATE_THM] THEN MESON_TAC[]) in
   STRIP_TAC THEN SPLIT_ASM_TAC THEN
   REPEAT (FIRST_X_ASSUM (fun e ->
     let c = concl e in
     if is_eq c && is_var (lhand c) then SUBST_ALL_TAC e
     else fail())) THEN
   W(fun gl ->
     let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                hd_is "domain" (rand (rand c))) gl in
     let su = the_asm (fun c -> hd_is "SUBSET" c) gl in
     SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
                     [el 0 (snd (strip_comb (rand (concl nd))));
                      list_mk_icomb "FDOM"
                        [rand (lhand (concl su))]])) ASSUME_TAC THENL
      [MP_TAC nd THEN MP_TAC su THEN REWRITE_TAC[SUBSET] THEN
       MESON_TAC[];
       ALL_TAC]) THEN
   MATCH_MP_TAC (GEN_ALL v_inv_SUBMAP) THEN
   W(fun gl -> MAP_EVERY (fun n -> EXISTS_TAC (var_by_name n gl))
                 ["f"; "tf"; "heap"]) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED (MATCH_ACCEPT_TAC SUBMAP_REFL)) THEN
   TRY (SOLVED (W(fun gl ->
     let nf = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                hd_is "FDOM" (rand (rand c))) gl in
     MATCH_ACCEPT_TAC (MATCH_MP submap_fupd nf)))) THEN
   MATCH_MP_TAC v_inv_ValueArray_insert THEN
   W(fun gl -> EXISTS_TAC (var_by_name "heap" gl)) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED (REWRITE_TAC[RefBlock_inv_def] THEN MESON_TAC[])) THEN
   ASM_MESON_TAC[]));;

(* a reference is a reference *)
let isRef_RefBlock = prove
 (`data_to_word_memoryProof_isRef (RefBlock xs)`,
  REWRITE_TAC[isRef_def; RefBlock_def] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[isMutTag_def]);;

(* the values of a stack with a value put in the middle of it *)
let EVERY2_APPEND_CONS_IMP = prove
 (`!(P:A->B->bool) xs1 ys1 x y xs2 ys2.
     ALL2 P xs1 ys1 /\ P x y /\ ALL2 P xs2 ys2
     ==> ALL2 P (APPEND xs1 (CONS x xs2))
           (APPEND ys1 (CONS y ys2))`,
  GEN_TAC THEN LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
  CASES_BY_NAME "ys1" THEN
  REWRITE_TAC[ALL2; APPEND] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* the timestamps of the references and the stack only grow when a
   key the references did not have is written and the stack keeps
   the values it had *)
let all_ts_insert_SUBSET = prove
 (cake_as_vars (fun () ->
    `!ptr rr refs stack1 stack2.
       ~(ptr IN domain refs) /\ (!x. MEM x stack1 ==> MEM x stack2)
       ==> all_ts refs stack1 SUBSET
           all_ts (sptree_insert ptr rr refs) stack2`),
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC all_ts_SUBSET_gen THEN
  W(fun (asl,w as gl) ->
    let nd = the_asm (fun c -> is_neg c) gl in
    let ptr = el 0 (snd (strip_comb (rand (concl nd)))) in
    let ins = find_term (hd_is "sptree_insert") w in
    let refs = el 2 (snd (strip_comb ins)) in
    let nv = genvar `:num` in
    let rv = genvar (type_of (el 1 (snd (strip_comb ins)))) in
    SUBGOAL_THEN
      (list_mk_forall([nv; rv],
         mk_imp(mk_eq (list_mk_icomb "sptree_lookup" [nv; refs],
                       list_mk_icomb "SOME" [rv]),
                mk_eq (list_mk_icomb "sptree_lookup" [nv; ins],
                       list_mk_icomb "SOME" [rv]))))
      (fun th -> ASM_MESON_TAC[th]) THEN
    REPEAT STRIP_TAC THEN
    ASM_CASES_TAC (mk_eq (nv, ptr)) THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      MP_TAC (REWRITE_RULE[GSYM lookup_NONE_domain] nd) THEN
      ASM_REWRITE_TAC[distinctness "option"];
      ASM_REWRITE_TAC[lookup_insert]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let new_ref_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ stack) refs (roots,heap,be,a,sp,sp1,gens)
  limit ts /\
      ~(ptr IN (domain refs)) /\ LENGTH xs + 1 <= sp ==>
      (?p rs roots2 heap2.
        (roots = rs ++ roots2) /\ LENGTH rs = LENGTH xs /\
        (heap_store_unused a (sp + sp1) (RefBlock rs) heap =
          (heap2,T)) /\
        abs_ml_inv conf (xs ++ ((RefPtr T ptr) :: stack)) (insert
          ptr (ValueArray xs) refs)
                   (rs ++ (gc_shared_Pointer ((a + sp + sp1) -
                     (LENGTH xs + 1)) (wordLang_Word (n2w 0)) ::
                     roots2),heap2,be,a,
                    sp - (LENGTH xs + 1),sp1,gens) limit ts)`),
  (* the steps are above the statement (tools/overrides.py).  The
     roots of the values of the array are the front of the roots of
     the stack (EVERY2_APPEND_IMP_APPEND), the array fits in the
     unused space and IMP_heap_store_unused writes it at the top of
     it; the heap, the roots and the space are then as good as they
     were (gc_kind_store_unused of the kind of the collection,
     where the array is a reference and so belongs below the
     split), the map of the addresses gains the key of the array
     with the address it was written at, and of every reference
     that the stack reaches the invariant holds as it did
     (bc_ref_inv_step) -- while the array itself is the element
     that the store wrote, with the values that the stack gave
     it *)
  (STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* what the invariant says of the stack that the array is
       built from *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    (* the roots of the values of the array, and the rest *)
    W(fun gl ->
      let e2 = the_asm (hd_is "ALL2") gl in
      STRIP_ASSUME_TAC (MATCH_MP EVERY2_APPEND_IMP_APPEND e2)) THEN
    (* the roots of the array are as many as its values, and its
       element is a word longer than they are *)
    W(fun (asl,w as gl) ->
      let va = find_term (hd_is "bvlSem_ValueArray") w in
      let xs = el 0 (snd (strip_comb va)) in
      let e1 = the_asm (fun c -> hd_is "ALL2" c &&
                 el 1 (snd (strip_comb c)) = xs) gl in
      let ys1 = el 2 (snd (strip_comb (concl e1))) in
      let rb = rator (find_term (hd_is "RefBlock") w) in
      let el1 = mk_comb (rb, ys1) in
      ASSUME_TAC (MATCH_MP LIST_REL_LENGTH e1) THEN
      SUBGOAL_THEN (mk_eq (list_mk_icomb "el_length" [el1],
                      list_mk_icomb "+"
                        [list_mk_icomb "LENGTH" [ys1];
                         mk_small_numeral 1])) ASSUME_TAC THENL
       [REWRITE_TAC[RefBlock_def; el_length_def] THEN
        MATCH_REDUCE_TAC THEN REWRITE_TAC[];
        ALL_TAC]) THEN
    (* so it fits in the unused space, and the store writes it at
       the top of it *)
    W(fun (asl,w as gl) ->
      let us = the_asm (hd_is "unused_space_inv") gl in
      let spsp = el 1 (snd (strip_comb (concl us))) in
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "el_length" (lhand c)) gl in
      let el1 = el 0 (snd (strip_comb (lhand (concl le)))) in
      SUBGOAL_THEN (list_mk_icomb "<="
                      [list_mk_icomb "el_length" [el1]; spsp])
        (fun bd -> STRIP_ASSUME_TAC (MATCH_MP
           IMP_heap_store_unused (CONJ us bd))) THENL
       [REWRITE_TAC[le] THEN ASM_ARITH_TAC;
        ALL_TAC]) THEN
    (* the element is a data element, which is what the two facts
       about the store ask for *)
    W(fun gl ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused" (lhand c)) gl in
      let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
      let isd = is_data_el el1 in
      MAP_EVERY (fun th -> ASSUME_TAC (MP th isd))
        (mapfilter (fun (_,th) ->
           let c = concl th in
           if is_imp c && hd_is "isDataElement" (lhand c) then th
           else fail()) (fst gl))) THEN
    (* the witnesses: the roots of the array, the rest of them and
       the heap that the store wrote *)
    W(fun (asl,w as gl) ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused" (lhand c)) gl in
      let ys1 = el 0 (snd (strip_comb
                  (el 2 (snd (strip_comb (lhand (concl st))))))) in
      let heap2 = lhand (rand (concl st)) in
      let rts = the_asm (fun c -> is_eq c && is_var (lhand c) &&
                  hd_is "APPEND" (rand c)) gl in
      EXISTS_TAC (genvar (type_of (fst (dest_exists w)))) THEN
      MAP_EVERY EXISTS_TAC
        [ys1; rand (rand (concl rts)); heap2]) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    TRY (SOLVED (W(fun gl ->
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "LENGTH" (lhand c) &&
                 hd_is "LENGTH" (rand c)) gl in
      ACCEPT_TAC (SYM le)))) THEN
    (* and the invariant of the new heap, stack and references *)
    REWRITE_TAC[abs_ml_inv_def] THEN
    (* the length of the element in the terms that the statement
       uses: the roots of the array are as many as its values, so
       the address the store wrote at is the one the statement
       names *)
    W(fun gl ->
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "el_length" (lhand c)) gl in
      let lenq = the_asm (fun c -> is_eq c &&
                   hd_is "LENGTH" (lhand c) &&
                   hd_is "LENGTH" (rand c)) gl in
      let le2 = REWRITE_RULE[GSYM lenq] le in
      RULE_ASSUM_TRY (REWRITE_RULE[le2]) THEN ASSUME_TAC le2) THEN
    (* the addresses that hold data are the ones that did, and the
       one the store wrote *)
    W(fun gl ->
      let seq = the_asm (fun c -> is_eq c &&
                  hd_is "INSERT" (rand c)) gl in
      let ro = the_asm (hd_is "roots_ok") gl in
      ASSUME_TAC (REWRITE_RULE[EXTENSION; IN_INSERT; IN_ELIM_THM]
                    seq) THEN
      ASSUME_TAC (REWRITE_RULE[roots_ok_def] ro)) THEN
    REPEAT CONJ_TAC THEN
    (* the roots: the one of the array is the address it was
       written at, and the others are the ones they were *)
    TRY (SOLVED
          (REWRITE_TAC[roots_ok_def; MEM_APPEND; MEM] THEN
           REPEAT STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           TRY (SOLVED
                 (DISJ1_TAC THEN
                  FIRST_X_ASSUM (fun e ->
                    if not (is_eq (concl e)) ||
                       not (hd_is "gc_shared_Pointer"
                              (rand (concl e)))
                    then fail() else
                    MP_TAC e) THEN
                  REWRITE_TAC[injectivity "heap_address"] THEN
                  MESON_TAC[])) THEN
           DISJ2_TAC THEN
           W(fun gl ->
             let ro = the_asm (fun c ->
                        let vs,bd = strip_forall c in
                        length vs = 2 && is_imp bd &&
                        hd_is "MEM" (lhand bd)) gl in
             let m = the_asm (fun c -> hd_is "MEM" c &&
                       hd_is "gc_shared_Pointer"
                         (el 0 (snd (strip_comb c)))) gl in
             let rts = the_asm (fun c -> is_eq c &&
                         is_var (lhand c) &&
                         hd_is "APPEND" (rand c)) gl in
             SUBGOAL_THEN (list_mk_icomb "MEM"
                 [el 0 (snd (strip_comb (concl m)));
                  lhand (concl rts)])
               (fun mr -> ACCEPT_TAC (MATCH_MP ro mr)) THEN
             ASM_REWRITE_TAC[MEM_APPEND]))) THEN
    (* the heap is good: it is as long as it was, it has no forward
       pointer, and the pointers of the array are roots of the
       stack *)
    TRY (SOLVED
          (REWRITE_TAC[heap_ok_def] THEN
           REPEAT CONJ_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let hl = the_asm (fun c -> is_eq c &&
                               hd_is "heap_length" (lhand c)) gl in
                    MP_TAC ho THEN REWRITE_TAC[hl] THEN
                    STRIP_TAC THEN ASM_REWRITE_TAC[]))) THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let impl = the_asm (fun c -> is_imp c &&
                                 is_neg (lhand c) &&
                                 hd_is "isForwardPointer"
                                   (rand (lhand c))) gl in
                    let st = the_asm (fun c -> is_eq c &&
                               hd_is "heap_store_unused"
                                 (lhand c)) gl in
                    let el1 = el 2 (snd (strip_comb
                                (lhand (concl st)))) in
                    SUBGOAL_THEN (mk_neg (list_mk_icomb
                                    "isForwardPointer" [el1]))
                      (fun nf -> MP_TAC ho THEN
                         REWRITE_TAC[MP impl nf] THEN
                         STRIP_TAC THEN ASM_REWRITE_TAC[]) THEN
                    REWRITE_TAC[RefBlock_def;
                                isForwardPointer_def] THEN
                    MATCH_REDUCE_TAC THEN REWRITE_TAC[]))) THEN
           REPEAT GEN_TAC THEN
           W(fun gl ->
             let mem = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 3 && is_eq bd &&
                         hd_is "MEM" (lhand bd)) gl in
             REWRITE_TAC[mem]) THEN
           STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           DISJ2_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let eq = the_asm (fun c -> is_eq c &&
                               hd_is "RefBlock" (lhand c)) gl in
                    MP_TAC eq) THEN
                  REWRITE_TAC[RefBlock_def;
                              injectivity "heap_element"] THEN
                  STRIP_TAC THEN
                  W(fun gl ->
                    let ro = the_asm (fun c ->
                               let vs,bd = strip_forall c in
                               length vs = 2 && is_imp bd &&
                               hd_is "MEM" (lhand bd)) gl in
                    let m = the_asm (fun c -> hd_is "MEM" c &&
                              hd_is "gc_shared_Pointer"
                                (el 0 (snd (strip_comb c)))) gl in
                    let rts = the_asm (fun c -> is_eq c &&
                                is_var (lhand c) &&
                                hd_is "APPEND" (rand c)) gl in
                    SUBGOAL_THEN (list_mk_icomb "MEM"
                        [el 0 (snd (strip_comb (concl m)));
                         lhand (concl rts)])
                      (fun mr -> ACCEPT_TAC (MATCH_MP ro mr)) THEN
                    ASM_REWRITE_TAC[MEM_APPEND]))) THEN
           W(fun gl ->
             let ho = REWRITE_RULE[heap_ok_def]
                        (the_asm (hd_is "heap_ok") gl) in
             let m1 = the_asm (fun c -> hd_is "MEM" c &&
                        hd_is "DataElement"
                          (el 0 (snd (strip_comb c)))) gl in
             let m2 = the_asm (fun c -> hd_is "MEM" c &&
                        hd_is "gc_shared_Pointer"
                          (el 0 (snd (strip_comb c)))) gl in
             MESON_TAC[ho; m1; m2]))) THEN
    (* the kind of the collection: the store at the top of the
       unused space keeps it, and the array is a reference *)
    W(fun (asl,w as gl) ->
      if not (hd_is "gc_kind_inv" w) then ALL_TAC else
      (let gk = the_asm (hd_is "gc_kind_inv") gl in
       let st = the_asm (fun c -> is_eq c &&
                  hd_is "heap_store_unused" (lhand c)) gl in
       let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
       let sp = el 2 (snd (strip_comb (concl gk))) in
       let le = the_asm (fun c -> is_eq c &&
                  hd_is "el_length" (lhand c)) gl in
       let us2 = REWRITE_RULE[GSYM le]
                   (the_asm (fun c -> hd_is "unused_space_inv" c &&
                      can (find_term (hd_is "-")) c) gl) in
       let ir = PART_MATCH I isRef_RefBlock
                  (list_mk_icomb
                     "data_to_word_memoryProof_isRef" [el1]) in
       SUBGOAL_THEN (list_mk_icomb "<="
                       [list_mk_icomb "el_length" [el1]; sp])
         (fun bd -> MATCH_ACCEPT_TAC (REWRITE_RULE[le] (MATCH_MP
            gc_kind_store_unused
            (CONJ ir (CONJ bd (CONJ gk (CONJ st us2))))))) THEN
       REWRITE_TAC[le] THEN ASM_ARITH_TAC)) THEN
    (* the unused space: what the store lemma says, with the length
       of the array taken off *)
    W(fun (asl,w as gl) ->
      if not (hd_is "unused_space_inv" w) then ALL_TAC else
      (let us = the_asm (fun c -> hd_is "unused_space_inv" c &&
                  can (find_term (hd_is "-")) c) gl in
       MP_TAC us THEN
       W(fun (asl,w) ->
         let usub = el 1 (snd (strip_comb (lhand w))) in
         let gsub = el 1 (snd (strip_comb (rand w))) in
         (* the two spaces are the same, and only that equation is
            rewritten with: the lengths of the values and of the
            roots are equal as well, and rewriting with that would
            take the two sides apart again *)
         SUBGOAL_THEN (mk_eq (usub, gsub))
           (fun e -> REWRITE_TAC[e]) THEN
         ASM_ARITH_TAC))) THEN
    (* the maps: the key of the array with the address it was
       written at, and the timestamps as they were *)
    REWRITE_TAC[bc_stack_ref_inv_def] THEN
    (* the key is fresh in the map of the addresses *)
    W(fun (asl,w as gl) ->
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "domain" (rand (rand c))) gl in
      let fm = rand (lhand (concl su)) in
      let ptr = el 0 (snd (strip_comb (rand (concl nd)))) in
      SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
                      [ptr; list_mk_icomb "FDOM" [fm]]))
        ASSUME_TAC THENL
       [MP_TAC su THEN MP_TAC nd THEN REWRITE_TAC[SUBSET] THEN
        MESON_TAC[];
        ALL_TAC]) THEN
    W(fun (asl,w as gl) ->
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let f = rand (lhand (concl su)) in
      let tfsu = the_asm (fun c -> hd_is "SUBSET" c &&
                   hd_is "all_ts" (rand c)) gl in
      let tf = rand (lhand (concl tfsu)) in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c) &&
                 hd_is "SOME" (rand c) &&
                 hd_is "RefBlock" (rand (rand c))) gl in
      let aa = el 0 (snd (strip_comb (lhand (concl hl)))) in
      let ins = find_term (hd_is "sptree_insert") w in
      let ptr = el 0 (snd (strip_comb ins)) in
      EXISTS_TAC (list_mk_icomb "|+" [f; mk_pair (ptr, aa)]) THEN
      EXISTS_TAC tf) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the map of the addresses with the key at the address, which
       held no data *)
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) ||
         not (can (find_term (hd_is "|+")) w) then ALL_TAC else
      (let iso = the_asm (fun c ->
                   let vs,bd = strip_forall c in
                   length vs = 1 && is_eq bd &&
                   hd_is "isSomeDataElement" (lhand bd)) gl in
       let inj = the_asm (fun c -> hd_is "INJ" c &&
                   hd_is "fmap_apply" (el 0 (snd (strip_comb c))) &&
                   rand (el 0 (snd (strip_comb c))) =
                     lhand (rand (el 0 (snd (strip_comb w))))) gl in
       let nd = the_asm (fun c -> is_neg c &&
                  hd_is "isSomeDataElement" (rand c)) gl in
       MATCH_MP_TAC INJ_FUPDATE_fresh THEN
       EXISTS_TAC (rand (concl inj)) THEN
       REPEAT CONJ_TAC THEN
       TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
       TRY (SOLVED (MP_TAC nd THEN REWRITE_TAC[IN_ELIM_THM])) THEN
       REWRITE_TAC[IN_ELIM_THM] THEN
       MATCH_ACCEPT_TAC iso)) THEN
    (* and the map of the timestamps goes into the bigger set of
       addresses *)
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) then ALL_TAC else
      (let iso = the_asm (fun c ->
                   let vs,bd = strip_forall c in
                   length vs = 1 && is_eq bd &&
                   hd_is "isSomeDataElement" (lhand bd)) gl in
       let inj = the_asm (fun c -> hd_is "INJ" c &&
                   el 0 (snd (strip_comb c)) =
                     el 0 (snd (strip_comb w))) gl in
       MATCH_MP_TAC INJ_bigger THEN
       EXISTS_TAC (rand (concl inj)) THEN
       CONJ_TAC THENL
        [ACCEPT_TAC inj;
         REWRITE_TAC[IN_ELIM_THM] THEN
         REWRITE_TAC[iso] THEN MESON_TAC[]])) THEN
    (* the domain of the references has the key of the array *)
    TRY (SOLVED
          (REWRITE_TAC[FDOM_FUPDATE; domain_insert] THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "domain" (rand c)) gl in
             MP_TAC su) THEN
           SET_TAC[])) THEN
    (* the timestamps of the new references and stack are more than
       the ones of the old (all_ts_insert_SUBSET) *)
    TRY (SOLVED
          (MATCH_MP_TAC SUBSET_TRANS THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "all_ts" (rand c)) gl in
             let nd = the_asm (fun c -> is_neg c &&
                        hd_is "IN" (rand c) &&
                        hd_is "domain" (rand (rand c))) gl in
             EXISTS_TAC (rand (concl su)) THEN
             CONJ_TAC THENL
              [ACCEPT_TAC su;
               MATCH_MP_TAC all_ts_insert_SUBSET THEN
               CONJ_TAC THENL
                [ACCEPT_TAC nd;
                 REWRITE_TAC[MEM_APPEND; MEM] THEN
                 MESON_TAC[]]]))) THEN
    (* and the blocks of the stack stay unique *)
    TRY (SOLVED
          (W(fun gl ->
             let bu = the_asm (hd_is "blocks_unique") gl in
             MATCH_ACCEPT_TAC (MATCH_MP blocks_unique_new_ref
               bu)))) THEN
    (* the transfer that the allocation leaves: what the invariant
       said of a value it says of it with the array written
       (v_inv_new_ref_step) *)
    W(fun (asl,w as gl) ->
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "domain" (rand (rand c))) gl in
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let hsr = the_asm (hd_is "heap_store_rel") gl in
      let old = the_asm (hd_is "ALL2") gl in
      let pred = el 0 (snd (strip_comb (concl old))) in
      let v,b1 = dest_abs pred in
      let x,vtm = dest_abs b1 in
      let f2 = find_term (hd_is "|+") w in
      let refs2 = find_term (hd_is "sptree_insert") w in
      ASSUME_TAC (GENL [v; x] (DISCH vtm
        (MATCH_MP v_inv_new_ref_step
          (CONJ (ASSUME vtm) (CONJ nd (CONJ su (CONJ hsr
            (CONJ (REFL f2) (REFL refs2)))))))))) THEN
    (* the values of the stack with the pointer of the array in
       the middle of it *)
    W(fun (asl,w) ->
      if not (hd_is "ALL2" w) then ALL_TAC else
      (MATCH_MP_TAC EVERY2_APPEND_CONS_IMP THEN
       REPEAT CONJ_TAC THEN
       (* the values of the array and the rest of the stack, with
          the transfer *)
       TRY (SOLVED (W(fun (asl,w as gl) ->
         let vs = el 1 (snd (strip_comb w)) in
         let old = the_asm (fun c -> hd_is "ALL2" c &&
                     el 1 (snd (strip_comb c)) = vs) gl in
         MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc_stack
           (CONJ (a_vtr gl) old))))) THEN
       (* and the pointer of the array itself *)
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       (* of a pointer that is no thunk only the first disjunct of
          the relation is left *)
       REWRITE_TAC[v_inv_def] THEN TRY DISJ1_TAC THEN
       REWRITE_TAC[FDOM_FUPDATE; IN_INSERT; lookup_insert;
                   FAPPLY_FUPDATE_THM; ref_ptr_annot_def] THEN
       REPEAT CONJ_TAC THEN
       TRY MATCH_REDUCE_TAC THEN
       (let ds = [distinctness "option";
                  distinctness "bvlSem_ref"] in
        REWRITE_TAC (injectivity "option" ::
                     injectivity "heap_address" ::
                     ds @ map GSYM ds)) THEN
       REWRITE_TAC[])) THEN
    (* and the invariant of every reference that the new stack
       reaches: the array itself, or one that the old stack
       reached *)
    REPEAT STRIP_TAC THEN
    W(fun (asl,w) ->
      let ins = find_term (hd_is "sptree_insert") w in
      let ptr = el 0 (snd (strip_comb ins)) in
      let n = el 1 (snd (strip_comb w)) in
      ASM_CASES_TAC (mk_eq (n, ptr))) THENL
     [(* the array itself: its key has the address the store wrote
          at, and its element is the one it wrote, with the values
          that the stack gave it *)
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      W(fun (asl,w as gl) ->
        let hl = the_asm (fun c -> is_eq c &&
                   hd_is "heap_lookup" (lhand c) &&
                   hd_is "SOME" (rand c) &&
                   hd_is "RefBlock" (rand (rand c))) gl in
        let aa = el 0 (snd (strip_comb (lhand (concl hl)))) in
        let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
        let ptr = el 1 (snd (strip_comb w)) in
        let ins = el 2 (snd (strip_comb w)) in
        SUBGOAL_THEN (mk_eq (list_mk_icomb "FLOOKUP" [fm; ptr],
                             list_mk_icomb "SOME" [aa]))
          ASSUME_TAC THENL
         [REWRITE_TAC[FLOOKUP_UPDATE]; ALL_TAC] THEN
        SUBGOAL_THEN
          (mk_eq (list_mk_icomb "sptree_lookup" [ptr; ins],
                  list_mk_icomb "SOME"
                    [el 1 (snd (strip_comb ins))])) ASSUME_TAC THENL
         [REWRITE_TAC[lookup_insert]; ALL_TAC]) THEN
      W(fun gl ->
        let lk1 = the_asm (fun c -> is_eq c &&
                    hd_is "FLOOKUP" (lhand c)) gl in
        let lk2 = the_asm (fun c -> is_eq c &&
                    hd_is "sptree_lookup" (lhand c) &&
                    hd_is "sptree_insert" (rand (lhand c))) gl in
        REWRITE_TAC[MATCH_MP arm_VA (CONJ lk1 lk2)]) THEN
      W(fun (asl,w as gl) ->
        let hl = the_asm (fun c -> is_eq c &&
                   hd_is "heap_lookup" (lhand c) &&
                   hd_is "SOME" (rand c) &&
                   hd_is "RefBlock" (rand (rand c))) gl in
        let ys1 = el 0 (snd (strip_comb (rand (rand (concl hl))))) in
        let old = the_asm (fun c -> hd_is "ALL2" c &&
                    el 2 (snd (strip_comb c)) = ys1) gl in
        let sw = CONV_RULE(TOP_DEPTH_CONV BETA_CONV)
                   (MATCH_MP EVERY2_SWAP old) in
        EXISTS_TAC ys1 THEN
        CONJ_TAC THENL
         [ACCEPT_TAC hl;
          MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc
            (CONJ (a_vtr gl) sw))]);
      (* and a reference that the old stack reached: it is in the
         domain of the map that the key was not in *)
      W(fun (asl,w as gl) ->
        let rr = the_asm (hd_is "reachable_refs") gl in
        let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                   hd_is "domain" (rand (rand c))) gl in
        let neq = the_asm (fun c -> is_neg c && is_eq (rand c)) gl in
        ASSUME_TAC (MATCH_MP reachable_refs_new_ref
          (CONJ rr (CONJ neq nd)))) THEN
      W(fun (asl,w as gl) ->
        let n = el 1 (snd (strip_comb w)) in
        let innu = the_asm (fun c -> hd_is "IN" c &&
                     hd_is "FDOM" (rand c) &&
                     el 0 (snd (strip_comb c)) = n) gl in
        let fm = lhand (rand (rand (concl innu))) in
        SUBGOAL_THEN (list_mk_icomb "IN"
                        [n; list_mk_icomb "FDOM" [fm]])
          ASSUME_TAC THENL
         [MP_TAC innu THEN
          REWRITE_TAC[FDOM_FUPDATE; IN_INSERT] THEN
          ASM_REWRITE_TAC[];
          ALL_TAC]) THEN
      W(fun (asl,w as gl) ->
        let n = el 1 (snd (strip_comb w)) in
        let bri = the_asm (fun c ->
          let vs,bd = strip_forall c in
          length vs = 1 && is_imp bd &&
          hd_is "bc_ref_inv" (rand bd)) gl in
        let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
          not (can (find_term (hd_is "sptree_insert")) c)) gl in
        let inn = the_asm (fun c -> hd_is "IN" c &&
          hd_is "FDOM" (rand c) &&
          el 0 (snd (strip_comb c)) = n &&
          not (can (find_term (hd_is "|+")) c)) gl in
        let inv = MP (SPEC n bri) (CONJ rr inn) in
        let hsr = the_asm (hd_is "heap_store_rel") gl in
        let stp = REWRITE_RULE[IMP_CONJ] bc_ref_inv_step in
        let th = MATCH_MP (MATCH_MP (MATCH_MP (MATCH_MP stp
                   (a_vtr gl)) inn) hsr) inv in
        MATCH_MP_TAC (REWRITE_RULE[IMP_IMP] th)) THEN
      REPEAT CONJ_TAC THEN
      (* the lookup of the references away from the key *)
      TRY (SOLVED (ASM_REWRITE_TAC[lookup_insert])) THEN
      (* the lookup of the map away from the key *)
      TRY (SOLVED (ASM_REWRITE_TAC[FLOOKUP_UPDATE])) THEN
      (* the timestamps did not change *)
      TRY (SOLVED (MESON_TAC[])) THEN
      (* and a thunk of the old references is one of the new *)
      W(fun gl ->
        let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                   hd_is "domain" (rand (rand c))) gl in
        GEN_TAC THEN DISCH_THEN (fun dt ->
          MATCH_ACCEPT_TAC (MATCH_MP dest_thunk_insert_fresh
            (CONJ nd dt))))]));;

(* [local] *)
let v_inv_new_Thunk_insert_lemma = prove
 (`!ck v refs x f tf heap ptr.
     v_inv conf v refs (x,f,tf,heap) /\ ~(ptr IN FDOM f) /\ ~(ptr IN
       domain refs) /\
     (ev = Evaluated ==> dest_thunk h refs = NotThunk) ==>
       v_inv_ck ck conf v (insert ptr (Thunk ev h) refs)
         (x,f,tf,heap)`,
  (* a thunk at a key that the refs do not have: now a lookup of
     the new refs does find a thunk where the old ones found
     nothing, so the facts hold away from ptr -- and a pointer of
     the relation is a key of f, which ptr is not, while a thunk of
     the old refs is one of the new refs wherever it is *)
  (let opt = [distinctness "option"; injectivity "option"] in
   let rfs = [distinctness "bvlSem_ref";
              injectivity "bvlSem_ref";
              distinctness "dataSem_dest_thunk_ret"] in
   let notptr3 = prove
    (`~(ptr IN FDOM f) /\ k IN FDOM f ==> ~(k = ptr)`,
     MESON_TAC[]) in
   let thunk_tr = prove
    (`lookup ptr refs = NONE ==>
      (!k ev2 v2. lookup k refs = SOME (Thunk ev2 v2) ==>
         lookup k (insert ptr (Thunk ev h) refs) =
           SOME (Thunk ev2 v2))`,
     DISCH_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC(opt @ rfs)) in
   let same = prove
    (`lookup ptr refs = NONE ==>
      (!k. ~(k = ptr) ==>
         (!ev2 v2.
            lookup k (insert ptr (Thunk ev h) refs) =
              SOME (Thunk ev2 v2) <=>
            lookup k refs = SOME (Thunk ev2 v2))) /\
      (!k. ~(k = ptr) ==>
         ref_ptr_annot conf
           (lookup k (insert ptr (Thunk ev h) refs)) =
         ref_ptr_annot conf (lookup k refs)) /\
      (!v. dest_thunk v refs = NotThunk ==>
           dest_thunk v (insert ptr (Thunk ev h) refs) = NotThunk) /\
      (!k bb.
         (!t2 g2 m2 d2 s2.
            lookup k refs = SOME (bvlSem_MutBlock t2 g2 m2 d2 s2)
              ==> ~bb)
         ==> (!t2 g2 m2 d2 s2.
            lookup k (insert ptr (Thunk ev h) refs) =
              SOME (bvlSem_MutBlock t2 g2 m2 d2 s2) ==> ~bb))`,
     DISCH_TAC THEN
     (REPEAT CONJ_TAC THENL
      [REPEAT STRIP_TAC THEN REWRITE_TAC[lookup_insert] THEN
       ASM_REWRITE_TAC[];
       REPEAT STRIP_TAC THEN REWRITE_TAC[lookup_insert] THEN
       ASM_REWRITE_TAC[];
       GEN_TAC THEN CASES_ON_NAME "v" THEN
       ONCE_REWRITE_TAC[dataSem_dest_thunk_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
       REWRITE_TAC[lookup_insert] THEN
       ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
       TRY MATCH_REDUCE_TAC THEN REWRITE_TAC(opt @ rfs) THEN
       REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
       TRY(CONV_TAC TAUT);
       REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
       REWRITE_TAC[lookup_insert] THEN COND_CASES_TAC THEN
       ASM_REWRITE_TAC(opt @ rfs) THEN
       TRY(FIRST_ASSUM MATCH_ACCEPT_TAC)])) in
   let lt1 = ARITH_RULE `~(ck = 0) ==> ck - 1 < ck` in
   let prep =
     FIRST_ASSUM(fun ds ->
       ASSUME_TAC(CONJUNCT1 ds) THEN
       ASSUME_TAC(MATCH_MP no_lk (CONJUNCT1(CONJUNCT2 ds)))) in
   let d5 =
     REPEAT SUBST_LHS_TAC THEN
     FIRST_ASSUM(fun nolk ->
       let (t_eq,a_eq,_,m_imp) = v_inv_refs_parts same nolk in
       FIRST_ASSUM(fun nf -> FIRST_ASSUM(fun fd ->
         let np = MATCH_MP notptr3 (CONJ nf fd) in
         REWRITE_TAC[GSYM (MATCH_MP a_eq np)] THEN
         MATCH_MP_TAC(el 4 v_inv_ck_rules) THEN
         REPEAT CONJ_TAC THENL
          [FIRST_ASSUM MATCH_ACCEPT_TAC;
           ASM_REWRITE_TAC[MATCH_MP t_eq np];
           MATCH_MP_TAC m_imp THEN
           FIRST_ASSUM MATCH_ACCEPT_TAC]))) in
   let d_nt n =
     NOT_VAR_TAC THEN REPEAT SUBST_LHS_TAC THEN
     FIRST_ASSUM(fun nolk ->
       let (_,_,dt,_) = v_inv_refs_parts same nolk in
       let tr = MATCH_MP thunk_tr nolk in
       FIRST_ASSUM(fun ih ->
         ASM_MESON_TAC[el n v_inv_ck_rules; tr; dt;
                       SPEC `ck - 1` ih; lt1])) in
   V_INV_REFS_TAC prep ALL_TAC d5 (d_nt 5) (d_nt 6)));;

(* HOL4 data_to_word_memoryProofScript.sml:6472-6476: a theorem that
   HOL4 states as the value of an ML expression:
   v_inv_new_Thunk_insert *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_new_thunk = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (v :: stack)) ==>
       blocks_unique ts
         (all_vs (insert ptr (Thunk ev v) refs) (v :: RefPtr F
           ptr :: stack))`),
  (* the value that the thunk holds is on the stack already,
     and the RefPtr that is put there is no Block *)
  (let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   let vrefptr = prove
    (`!b p ys. v_all_vs (CONS (RefPtr b p) ys) =
        CONS (RefPtr b p) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let f1 = prove
    (`!(v:dataSem_v) p xs y.
        MEM y (v_all_vs (CONS v (CONS (RefPtr F p) xs))) <=>
        MEM y (v_all_vs [v]) \/ y = RefPtr F p \/
        MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [cons_app] THEN
     REWRITE_TAC[v_all_vs_append; MEM_APPEND; vrefptr; MEM]) in
   let inc = prove
    (`!refs ptr ev v stack' t a q.
        Block t a q IN
          all_vs (insert ptr (Thunk ev v) refs)
                 (CONS v (CONS (RefPtr F ptr) stack')) ==>
        Block t a q IN all_vs refs (CONS v stack')`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; li; f1;
                 distinctness "bvlSem_ref"; injectivity "bvlSem_ref";
                 distinctness "dataSem_v"] THEN
     MESON_TAC[MEM_v_all_vs_extend_tl; MEM_v_all_vs_extend_hd]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: what the proof of new_thunk_thm needs.  The
   element is written at the top of the unused space, where it is a
   reference (gc_kind_store_unused); the references gain a key that
   they did not have, holding the value that the stack has in front
   of it, so a path through the new references is one of the old
   ones or starts at that value (reachable_refs_new_thunk), and
   what the invariant said of a value it says of it with the key
   written and the store done (v_inv_new_thunk_step) *)

(* a thunk is a reference, and its element is two words long *)
let isRef_ThunkBlock = prove
 (`data_to_word_memoryProof_isRef (ThunkBlock ev x)`,
  REWRITE_TAC[isRef_def; ThunkBlock_def] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[isMutTag_def] THEN MESON_TAC[]);;

let el_length_ThunkBlock = prove
 (`!ev x. el_length (ThunkBlock ev x) = 2`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[ThunkBlock_def; el_length_def] THEN
  MATCH_REDUCE_TAC THEN ARITH_TAC);;

(* the values of a stack whose head is given *)
let EVERY2_CONS_IMP = prove
 (`!(P:A->B->bool) x xs ys.
     ALL2 P (CONS x xs) ys
     ==> ?y ys2. ys = CONS y ys2 /\ P x y /\ ALL2 P xs ys2`,
  REPEAT GEN_TAC THEN
  STRUCT_CASES_TAC(ISPEC `ys:B list` list_CASES_v) THEN
  REWRITE_TAC[ALL2] THEN MESON_TAC[]);;

(* what the invariant says of a value with a thunk written at a key
   that the references do not have *)
let v_inv_new_Thunk_insert = prove
 (`v_inv conf v refs (x,f,tf,heap) /\ ~(ptr IN FDOM f) /\
   ~(ptr IN domain refs) /\
   (ev = Evaluated ==> dest_thunk h refs = NotThunk)
   ==> v_inv conf v (insert ptr (Thunk ev h) refs) (x,f,tf,heap)`,
  (REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[v_inv_eq; v_inv_new_Thunk_insert_lemma]));;

(* the edges that the references gain when a thunk is written at a
   key they did not have leave that key and land at its value *)
let ref_edge_Thunk = prove
 (cake_as_vars (fun () ->
    `ref_edge (sptree_insert ptr (Thunk ev h) refs) x y =
     (if x = ptr then MEM y (get_refs (Block 0 ARB [h]))
      else ref_edge refs x y)`),
  REWRITE_TAC[ref_edge_def; lookup_insert] THEN
  COND_CASES_TAC THEN REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[]);;

(* [local] *)
let reachable_refs_new_thunk_lemma = prove
 (cake_as_vars (fun () ->
    `!r1 n.
       RTC (ref_edge (sptree_insert ptr (Thunk ev h) refs)) r1 n
       ==> ~(n = ptr) ==>
       RTC (ref_edge refs) r1 n \/
       (?s. MEM s (get_refs (Block 0 ARB [h])) /\
            RTC (ref_edge refs) s n)`),
  MATCH_MP_TAC RTC_INDUCT THEN CONJ_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN DISJ1_TAC THEN
    MATCH_ACCEPT_TAC(CONJUNCT1(SPEC_ALL RTC_RULES));
    REPEAT GEN_TAC THEN
    REWRITE_TAC[ref_edge_Thunk] THEN
    COND_CASES_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
    ASM_MESON_TAC[RTC_RULES]]);;

(* so a reference that the stack with the pointer of the thunk on
   it reaches is one that the value of the thunk and the rest of
   the stack reach *)
let reachable_refs_new_thunk = prove
 (cake_as_vars (fun () ->
    `reachable_refs (h :: (RefPtr F ptr :: stack))
       (sptree_insert ptr (Thunk ev h) refs) n /\ ~(n = ptr) /\
     ~(ptr IN domain refs)
     ==> reachable_refs (h :: stack) refs n`),
  (let mem_block_refs = prove
    (`!(ys:(dataSem_v)list) ss tt aa.
        MEM ss (get_refs (Block tt aa ys))
        ==> ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   let subst_vars =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_eq(concl th) && is_var(lhand(concl th))
       then SUBST_ALL_TAC th else fail())) in
   let payload b =
     X_CHOOSE_THEN `ss:num` (CONJUNCTS_THEN2
       (fun m -> MP_TAC(MATCH_MP mem_block_refs m)) ASSUME_TAC) b THEN
     DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v`
       (fun th -> STRIP_ASSUME_TAC (REWRITE_RULE[MEM] th))) THEN
     MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `ss:num`] THEN
     ASM_REWRITE_TAC[MEM] in
   let noedge a =
     MP_TAC(ONCE_REWRITE_RULE[RTC_CASES] a) THEN
     FIRST_ASSUM(fun nd ->
       let th = REWRITE_RULE[GSYM lookup_NONE_domain] nd in
       if concl th = concl nd then fail()
       else REWRITE_TAC[ref_edge_def; th]) THEN
     MATCH_REDUCE_TAC THEN ASM_REWRITE_TAC[] in
   let stackcase a =
     ASSUME_TAC a THEN
     W(fun gl ->
       let m = the_asm (fun c -> hd_is "MEM" c &&
                 hd_is "get_refs" (rand c)) gl in
       EXISTS_TAC (el 0 (snd (strip_comb (rand (concl m))))) THEN
       EXISTS_TAC (el 0 (snd (strip_comb (concl m))))) THEN
     ASM_REWRITE_TAC[MEM] in
   let uselemma =
     FIRST_ASSUM(fun rtc -> FIRST_ASSUM(fun ne ->
       MP_TAC(MATCH_MP (MATCH_MP
         reachable_refs_new_thunk_lemma rtc) ne))) in
   REWRITE_TAC[reachable_refs_def; MEM] THEN
   STRIP_TAC THENL
    [uselemma THEN DISCH_THEN(DISJ_CASES_THEN2 stackcase payload);
     subst_vars THEN
     RULE_ASSUM_TAC(REWRITE_RULE[get_refs_def; MEM]) THEN
     subst_vars THEN uselemma THEN
     DISCH_THEN(DISJ_CASES_THEN2 noedge payload);
     uselemma THEN DISCH_THEN(DISJ_CASES_THEN2 stackcase payload)]));;

(* and what the invariant says of a value it says of it with the
   thunk written and the store done *)
let v_inv_new_thunk_step = prove
 (cake_as_vars (fun () ->
    `v_inv conf w1 refs (w2,f,tf,heap) /\ ~(ptr IN domain refs) /\
     FDOM f SUBSET domain refs /\ heap_store_rel heap heap2 /\
     (ev = Evaluated ==> dest_thunk h refs = NotThunk) /\
     f2 = f |+ (ptr,aa) /\
     refs2 = sptree_insert ptr (Thunk ev h) refs
     ==> v_inv conf w1 refs2 (w2,f2,tf,heap2)`),
  (let submap_fupd = prove
    (`!(g:(A,B)fmap) k v. ~(k IN FDOM g) ==> g SUBMAP (g |+ (k,v))`,
     REWRITE_TAC[SUBMAP; FDOM_FUPDATE; IN_INSERT;
                 FAPPLY_FUPDATE_THM] THEN MESON_TAC[]) in
   STRIP_TAC THEN SPLIT_ASM_TAC THEN
   REPEAT (FIRST_X_ASSUM (fun e ->
     let c = concl e in
     if is_eq c && is_var (lhand c) then SUBST_ALL_TAC e
     else fail())) THEN
   W(fun gl ->
     let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                hd_is "domain" (rand (rand c))) gl in
     let su = the_asm (fun c -> hd_is "SUBSET" c) gl in
     SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
                     [el 0 (snd (strip_comb (rand (concl nd))));
                      list_mk_icomb "FDOM"
                        [rand (lhand (concl su))]])) ASSUME_TAC THENL
      [MP_TAC nd THEN MP_TAC su THEN REWRITE_TAC[SUBSET] THEN
       MESON_TAC[];
       ALL_TAC]) THEN
   MATCH_MP_TAC (GEN_ALL v_inv_SUBMAP) THEN
   W(fun gl -> MAP_EVERY (fun n -> EXISTS_TAC (var_by_name n gl))
                 ["f"; "tf"; "heap"]) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED (MATCH_ACCEPT_TAC SUBMAP_REFL)) THEN
   TRY (SOLVED (W(fun gl ->
     let nf = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                hd_is "FDOM" (rand (rand c))) gl in
     MATCH_ACCEPT_TAC (MATCH_MP submap_fupd nf)))) THEN
   MATCH_MP_TAC v_inv_new_Thunk_insert THEN
   REPEAT CONJ_TAC THEN
   FIRST_ASSUM ACCEPT_TAC));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let new_thunk_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (v :: stack) refs (roots,heap,be,a,sp,sp1,gens)
  limit ts /\
      ~(ptr IN (domain refs)) /\ 2 <= sp /\
      (ev = Evaluated ==> dest_thunk v refs = NotThunk) ==>
      (?p r roots2 heap2.
        (roots = r :: roots2) /\
        (heap_store_unused a (sp + sp1) (ThunkBlock ev r) heap =
          (heap2,T)) /\
        abs_ml_inv conf (v :: (RefPtr F ptr) :: stack) (insert ptr
          (Thunk ev v) refs)
                   (r :: gc_shared_Pointer ((a + sp + sp1) - 2)
                     (wordLang_Word (n2w 0)) :: roots2,heap2,be,a,
                    sp - 2,sp1,gens) limit ts)`),
  (* the steps are above the statement (tools/overrides.py).  The
     root of the value of the thunk is the first of the roots of
     the stack (EVERY2_CONS_IMP), the element is two words long and
     IMP_heap_store_unused writes it at the top of the unused
     space; the heap, the roots and the space are then as good as
     they were (gc_kind_store_unused of the kind of the collection,
     where the thunk is a reference), the map of the addresses
     gains the key of the thunk with the address it was written at,
     and of every reference that the stack reaches the invariant
     holds as it did (bc_ref_inv_step) -- while the thunk itself is
     the element that the store wrote, with the value that the
     stack gave it *)
  (let DT_TAC =
     (* the value of the thunk is no thunk of the new references
        either: it is none of the old ones, and the key is fresh *)
     DISCH_TAC THEN
     MATCH_MP_TAC dest_thunk_insert_fresh THEN
     CONJ_TAC THENL
      [FIRST_ASSUM ACCEPT_TAC;
       W(fun gl ->
         let impl = the_asm (fun c -> is_imp c && is_eq (lhand c) &&
                      (try hd_is "Evaluated" (rand (lhand c))
                       with Failure _ -> false)) gl in
         let ee = the_asm (fun c -> is_eq c &&
                    hd_is "Evaluated" (rand c)) gl in
         ACCEPT_TAC (MP impl ee))] in
   STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* what the invariant says of the stack that the thunk is
       built from *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    (* the root of the value of the thunk, and the rest *)
    W(fun gl ->
      let e2 = the_asm (hd_is "ALL2") gl in
      STRIP_ASSUME_TAC (MATCH_MP EVERY2_CONS_IMP e2)) THEN
    (* the element is two words long, so it fits in the unused
       space, and the store writes it at the top of it *)
    W(fun (asl,w as gl) ->
      let us = the_asm (hd_is "unused_space_inv") gl in
      let spsp = el 1 (snd (strip_comb (concl us))) in
      let rts = the_asm (fun c -> is_eq c && is_var (lhand c) &&
                  hd_is "CONS" (rand c)) gl in
      let tb = rator (find_term (hd_is "ThunkBlock") w) in
      let el1 = mk_comb (tb, lhand (rand (concl rts))) in
      SUBGOAL_THEN (list_mk_icomb "<="
                      [list_mk_icomb "el_length" [el1]; spsp])
        (fun bd -> STRIP_ASSUME_TAC (MATCH_MP
           IMP_heap_store_unused (CONJ us bd))) THENL
       [REWRITE_TAC[el_length_ThunkBlock] THEN ASM_ARITH_TAC;
        ALL_TAC]) THEN
    (* the element is a data element, which is what the two facts
       about the store ask for *)
    W(fun gl ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused" (lhand c)) gl in
      let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
      let isd = is_data_el el1 in
      MAP_EVERY (fun th -> ASSUME_TAC (MP th isd))
        (mapfilter (fun (_,th) ->
           let c = concl th in
           if is_imp c && hd_is "isDataElement" (lhand c) then th
           else fail()) (fst gl))) THEN
    (* the witnesses: the root of the value, the rest of the roots
       and the heap that the store wrote *)
    W(fun (asl,w as gl) ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused" (lhand c)) gl in
      let heap2 = lhand (rand (concl st)) in
      let rts = the_asm (fun c -> is_eq c && is_var (lhand c) &&
                  hd_is "CONS" (rand c)) gl in
      EXISTS_TAC (genvar (type_of (fst (dest_exists w)))) THEN
      MAP_EVERY EXISTS_TAC
        [lhand (rand (concl rts)); rand (rand (concl rts)); heap2]) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* and the invariant of the new heap, stack and references *)
    REWRITE_TAC[abs_ml_inv_def] THEN
    (* the length of the element in the terms that the statement
       uses *)
    RULE_ASSUM_TRY (REWRITE_RULE[el_length_ThunkBlock]) THEN
    (* the addresses that hold data are the ones that did, and the
       one the store wrote *)
    W(fun gl ->
      let seq = the_asm (fun c -> is_eq c &&
                  hd_is "INSERT" (rand c)) gl in
      let ro = the_asm (hd_is "roots_ok") gl in
      ASSUME_TAC (REWRITE_RULE[EXTENSION; IN_INSERT; IN_ELIM_THM]
                    seq) THEN
      ASSUME_TAC (REWRITE_RULE[roots_ok_def] ro)) THEN
    REPEAT CONJ_TAC THEN
    (* the roots: the one of the thunk is the address it was
       written at, and the others are the ones they were *)
    TRY (SOLVED
          (REWRITE_TAC[roots_ok_def; MEM] THEN
           REPEAT STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           TRY (SOLVED
                 (DISJ1_TAC THEN
                  FIRST_X_ASSUM (fun e ->
                    if not (is_eq (concl e)) ||
                       not (hd_is "gc_shared_Pointer"
                              (rand (concl e)))
                    then fail() else
                    MP_TAC e) THEN
                  REWRITE_TAC[injectivity "heap_address"] THEN
                  MESON_TAC[])) THEN
           DISJ2_TAC THEN
           W(fun gl ->
             let ro = the_asm (fun c ->
                        let vs,bd = strip_forall c in
                        length vs = 2 && is_imp bd &&
                        hd_is "MEM" (lhand bd)) gl in
             let rts = the_asm (fun c -> is_eq c &&
                         is_var (lhand c) &&
                         hd_is "CONS" (rand c)) gl in
             (* the root is the value of the thunk, which the old
                roots had in front, or one of the others *)
             let pt = tryfind (fun (_,th) ->
                        let c = concl th in
                        if hd_is "MEM" c &&
                           hd_is "gc_shared_Pointer"
                             (el 0 (snd (strip_comb c)))
                        then el 0 (snd (strip_comb c))
                        else if is_eq c &&
                           hd_is "gc_shared_Pointer" (lhand c)
                        then lhand c
                        else fail()) (fst gl) in
             SUBGOAL_THEN (list_mk_icomb "MEM"
                 [pt; lhand (concl rts)])
               (fun mr -> ACCEPT_TAC (MATCH_MP ro mr)) THEN
             ASM_REWRITE_TAC[MEM]))) THEN
    (* the heap is good: it is as long as it was, it has no forward
       pointer, and the pointer of the thunk is a root of the
       stack *)
    TRY (SOLVED
          (REWRITE_TAC[heap_ok_def] THEN
           REPEAT CONJ_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let hl = the_asm (fun c -> is_eq c &&
                               hd_is "heap_length" (lhand c)) gl in
                    MP_TAC ho THEN REWRITE_TAC[hl] THEN
                    STRIP_TAC THEN ASM_REWRITE_TAC[]))) THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let impl = the_asm (fun c -> is_imp c &&
                                 is_neg (lhand c) &&
                                 hd_is "isForwardPointer"
                                   (rand (lhand c))) gl in
                    let st = the_asm (fun c -> is_eq c &&
                               hd_is "heap_store_unused"
                                 (lhand c)) gl in
                    let el1 = el 2 (snd (strip_comb
                                (lhand (concl st)))) in
                    SUBGOAL_THEN (mk_neg (list_mk_icomb
                                    "isForwardPointer" [el1]))
                      (fun nf -> MP_TAC ho THEN
                         REWRITE_TAC[MP impl nf] THEN
                         STRIP_TAC THEN ASM_REWRITE_TAC[]) THEN
                    REWRITE_TAC[ThunkBlock_def;
                                isForwardPointer_def] THEN
                    MATCH_REDUCE_TAC THEN REWRITE_TAC[]))) THEN
           REPEAT GEN_TAC THEN
           W(fun gl ->
             let mem = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 3 && is_eq bd &&
                         hd_is "MEM" (lhand bd)) gl in
             REWRITE_TAC[mem]) THEN
           STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           DISJ2_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let eq = the_asm (fun c -> is_eq c &&
                               hd_is "ThunkBlock" (lhand c)) gl in
                    MP_TAC eq) THEN
                  REWRITE_TAC[ThunkBlock_def;
                              injectivity "heap_element"] THEN
                  STRIP_TAC THEN
                  W(fun gl ->
                    let ro = the_asm (fun c ->
                               let vs,bd = strip_forall c in
                               length vs = 2 && is_imp bd &&
                               hd_is "MEM" (lhand bd)) gl in
                    let m = the_asm (fun c -> hd_is "MEM" c &&
                              hd_is "gc_shared_Pointer"
                                (el 0 (snd (strip_comb c)))) gl in
                    let rts = the_asm (fun c -> is_eq c &&
                                is_var (lhand c) &&
                                hd_is "CONS" (rand c)) gl in
                    let eq = the_asm (fun c -> is_eq c &&
                               hd_is "CONS" (lhand c)) gl in
                    SUBGOAL_THEN (list_mk_icomb "MEM"
                        [el 0 (snd (strip_comb (concl m)));
                         lhand (concl rts)])
                      (fun mr -> ACCEPT_TAC (MATCH_MP ro mr)) THEN
                    MESON_TAC[m; rts; eq; MEM]))) THEN
           W(fun gl ->
             let ho = REWRITE_RULE[heap_ok_def]
                        (the_asm (hd_is "heap_ok") gl) in
             let m1 = the_asm (fun c -> hd_is "MEM" c &&
                        hd_is "DataElement"
                          (el 0 (snd (strip_comb c)))) gl in
             let m2 = the_asm (fun c -> hd_is "MEM" c &&
                        hd_is "gc_shared_Pointer"
                          (el 0 (snd (strip_comb c)))) gl in
             MESON_TAC[ho; m1; m2]))) THEN
    (* the kind of the collection: the store at the top of the
       unused space keeps it, and the thunk is a reference *)
    W(fun (asl,w as gl) ->
      if not (hd_is "gc_kind_inv" w) then ALL_TAC else
      (let gk = the_asm (hd_is "gc_kind_inv") gl in
       let st = the_asm (fun c -> is_eq c &&
                  hd_is "heap_store_unused" (lhand c)) gl in
       let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
       let sp = el 2 (snd (strip_comb (concl gk))) in
