      let v1 = genvar (type_of v0) and x1 = genvar (type_of x0) in
      let vtm = vsubst [v1,v0; x1,x0] bod in
      let f2 = find_term (hd_is "|+") w in
      let refs2 = find_term (hd_is "sptree_insert") w in
      ASSUME_TAC (GENL [v1; x1] (DISCH vtm
        (MATCH_MP v_inv_new_thunk_step
          (CONJ (ASSUME vtm) (CONJ nd (CONJ su (CONJ hsr
