    (* the values of the stack with the pointer of the thunk in
       it *)
    W(fun (asl,w) ->
      if not (hd_is "ALL2" w) then ALL_TAC else
      (REWRITE_TAC[ALL2] THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       REPEAT CONJ_TAC THEN
