         let vargs = snd (strip_comb (concl vi)) in
         REWRITE_TAC[v_inv_def] THEN
         DISJ2_TAC THEN DISJ1_TAC THEN
         MAP_EVERY EXISTS_TAC
           [md; el 1 vargs; el 0 (tparts (el 3 vargs))]) THEN
       REWRITE_TAC[FDOM_FUPDATE; IN_INSERT; lookup_insert;
                   FAPPLY_FUPDATE_THM] THEN
       REPEAT CONJ_TAC THEN
       TRY MATCH_REDUCE_TAC THEN
       TRY (SOLVED (REWRITE_TAC[])) THEN
       TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
       (* the value of the thunk is still no thunk *)
       TRY (SOLVED DT_TAC) THEN
       (* and what the invariant says of the value goes over with
          the transfer *)
       W(fun gl ->
         let vi = the_asm (fun c -> hd_is "v_inv" c &&
                    not (can (find_term (hd_is "|+")) c)) gl in
         MATCH_ACCEPT_TAC (MATCH_MP (a_vtr gl) vi)))) THEN
    (* and the invariant of every reference that the new stack
       reaches: the thunk itself, or one that the old stack
       reached *)
    REPEAT STRIP_TAC THEN
    W(fun (asl,w) ->
      let ins = find_term (hd_is "sptree_insert") w in
      let ptr = el 0 (snd (strip_comb ins)) in
      let n = el 1 (snd (strip_comb w)) in
      ASM_CASES_TAC (mk_eq (n, ptr))) THENL
     [(* the thunk itself: its key has the address the store wrote
          at, and its element is the one it wrote, with the value
          that the stack gave it *)
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      W(fun (asl,w as gl) ->
        let hl = the_asm (fun c -> is_eq c &&
                   hd_is "heap_lookup" (lhand c) &&
                   hd_is "SOME" (rand c) &&
                   hd_is "ThunkBlock" (rand (rand c))) gl in
        let aa = el 0 (snd (strip_comb (lhand (concl hl)))) in
        let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
        let ptr = el 1 (snd (strip_comb w)) in
        let ins = el 2 (snd (strip_comb w)) in
        SUBGOAL_THEN (mk_eq (list_mk_icomb "FLOOKUP" [fm; ptr],
                             list_mk_icomb "SOME" [aa]))
          ASSUME_TAC THENL
         [REWRITE_TAC[FLOOKUP_UPDATE]; ALL_TAC] THEN
        SUBGOAL_THEN
          (mk_eq (list_mk_icomb "sptree_lookup" [ptr; ins],
                  list_mk_icomb "SOME"
                    [el 1 (snd (strip_comb ins))])) ASSUME_TAC THENL
         [REWRITE_TAC[lookup_insert]; ALL_TAC]) THEN
      W(fun gl ->
        let lk1 = the_asm (fun c -> is_eq c &&
                    hd_is "FLOOKUP" (lhand c)) gl in
        let lk2 = the_asm (fun c -> is_eq c &&
                    hd_is "sptree_lookup" (lhand c) &&
                    hd_is "sptree_insert" (rand (lhand c))) gl in
        REWRITE_TAC[MATCH_MP arm_TH (CONJ lk1 lk2)]) THEN
      W(fun (asl,w as gl) ->
        let hl = the_asm (fun c -> is_eq c &&
                   hd_is "heap_lookup" (lhand c) &&
                   hd_is "SOME" (rand c) &&
                   hd_is "ThunkBlock" (rand (rand c))) gl in
        EXISTS_TAC (rand (rand (rand (concl hl))))) THEN
      REPEAT CONJ_TAC THEN
      TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
      (* the value of the thunk is still no thunk, and what the
         invariant says of it goes over with the transfer *)
      TRY (SOLVED DT_TAC) THEN
      W(fun gl ->
        let vi = the_asm (hd_is "v_inv") gl in
        MATCH_ACCEPT_TAC (MATCH_MP (a_vtr gl) vi));
      (* and a reference that the old stack reached: it is in the
         domain of the map that the key was not in *)
      W(fun (asl,w as gl) ->
        let rr = the_asm (hd_is "reachable_refs") gl in
        let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                   hd_is "domain" (rand (rand c))) gl in
        let neq = the_asm (fun c -> is_neg c && is_eq (rand c)) gl in
        ASSUME_TAC (MATCH_MP reachable_refs_new_thunk
          (CONJ rr (CONJ neq nd)))) THEN
      W(fun (asl,w as gl) ->
        let n = el 1 (snd (strip_comb w)) in
        let innu = the_asm (fun c -> hd_is "IN" c &&
                     hd_is "FDOM" (rand c) &&
                     el 0 (snd (strip_comb c)) = n) gl in
        let fm = lhand (rand (rand (concl innu))) in
        SUBGOAL_THEN (list_mk_icomb "IN"
                        [n; list_mk_icomb "FDOM" [fm]])
          ASSUME_TAC THENL
         [MP_TAC innu THEN
          REWRITE_TAC[FDOM_FUPDATE; IN_INSERT] THEN
          ASM_REWRITE_TAC[];
          ALL_TAC]) THEN
      W(fun (asl,w as gl) ->
        let n = el 1 (snd (strip_comb w)) in
        let bri = the_asm (fun c ->
          let vs,bd = strip_forall c in
          length vs = 1 && is_imp bd &&
          hd_is "bc_ref_inv" (rand bd)) gl in
        let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
          not (can (find_term (hd_is "sptree_insert")) c)) gl in
        let inn = the_asm (fun c -> hd_is "IN" c &&
          hd_is "FDOM" (rand c) &&
          el 0 (snd (strip_comb c)) = n &&
          not (can (find_term (hd_is "|+")) c)) gl in
        let inv = MP (SPEC n bri) (CONJ rr inn) in
        let hsr = the_asm (hd_is "heap_store_rel") gl in
        let stp = REWRITE_RULE[IMP_CONJ] bc_ref_inv_step in
        let th = MATCH_MP (MATCH_MP (MATCH_MP (MATCH_MP stp
                   (a_vtr gl)) inn) hsr) inv in
        MATCH_MP_TAC (REWRITE_RULE[IMP_IMP] th)) THEN
      REPEAT CONJ_TAC THEN
      (* the lookup of the references away from the key *)
      TRY (SOLVED (ASM_REWRITE_TAC[lookup_insert])) THEN
      (* the lookup of the map away from the key *)
      TRY (SOLVED (ASM_REWRITE_TAC[FLOOKUP_UPDATE])) THEN
      (* the timestamps did not change *)
      TRY (SOLVED (MESON_TAC[])) THEN
      (* and a thunk of the old references is one of the new *)
      W(fun gl ->
        let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                   hd_is "domain" (rand (rand c))) gl in
        GEN_TAC THEN DISCH_THEN (fun dt ->
          MATCH_ACCEPT_TAC (MATCH_MP dest_thunk_insert_fresh
            (CONJ nd dt))))]));;

(* deref *)

let heap_el_def = cake_define
  `heap_el x1 n heap =
        match x1 with
          gc_shared_Pointer a u ->
       (match heap_lookup a heap with SOME (DataElement xs l d) ->
           (if n < LENGTH xs then (EL n xs,T) else (ARB,F)) | _31 ->
             (ARB,F))
        | _32 -> (ARB,F)`;;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_deref1 = prove
 (cake_as_vars (fun () ->
    `lookup ptr refs = SOME (Thunk NotEvaluated a') /\
     blocks_unique ts (all_vs refs (RefPtr F ptr :: stack)) ==>
       blocks_unique ts (all_vs refs (a' :: RefPtr F ptr ::
         stack))`),
  (* the value of the thunk is a value of the refs already *)
  (let vcons = prove
    (`!(v:dataSem_v) xs y. MEM y (v_all_vs (CONS v xs)) <=>
        MEM y (v_all_vs [v]) \/ MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [prove(`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
              REWRITE_TAC[APPEND])] THEN
     REWRITE_TAC[v_all_vs_append; MEM_APPEND]) in
   let inc = prove
    (`!refs ptr a' stack' t a q.
        sptree_lookup ptr refs = SOME (Thunk NotEvaluated a') /\
        Block t a q IN all_vs refs (CONS a' (CONS (RefPtr F ptr)
          stack')) ==>
        Block t a q IN all_vs refs (CONS (RefPtr F ptr) stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
     MESON_TAC[vcons]) in
   REWRITE_TAC[blocks_unique_def] THEN STRIP_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_deref2 = prove
 (cake_as_vars (fun () ->
    `n < LENGTH l /\
     lookup ptr refs = SOME (ValueArray l) /\
     blocks_unique ts (all_vs refs (RefPtr b ptr :: stack)) ==>
       blocks_unique ts (all_vs refs (EL n l :: RefPtr b ptr ::
         stack))`),
  (* the value that the dereference puts on the stack is one
     of the ValueArray that the pointer holds *)
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   let vrefptr = prove
    (`!b p ys. v_all_vs (CONS (RefPtr b p) ys) =
        CONS (RefPtr b p) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let fref = prove
    (`!(v:dataSem_v) p b xs y.
        MEM y (v_all_vs (CONS v (CONS (RefPtr b p) xs))) <=>
        MEM y (v_all_vs [v]) \/ y = RefPtr b p \/ MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [cons_app] THEN
     REWRITE_TAC[v_all_vs_append; MEM_APPEND; vrefptr; MEM]) in
   let inc = prove
    (`!refs ptr b l n stack' t a q.
        n < LENGTH l /\
        sptree_lookup ptr refs = SOME (ValueArray l) /\
        Block t a q IN
          all_vs refs (CONS (EL n l) (CONS (RefPtr b ptr) stack')) ==>
        Block t a q IN all_vs refs (CONS (RefPtr b ptr) stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; fref;
                 distinctness "dataSem_v"] THEN
     MESON_TAC[MEM_v_all_vs_EL; MEM_v_all_vs_extend_hd]) in
   REWRITE_TAC[blocks_unique_def] THEN STRIP_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: what the proof of deref_thm needs, and what the
   lemmas about abs_ml_inv of a stack share with it.  A value put
   on the stack only adds timestamps (all_ts_mono); the pointers of
   an element of a good heap are addresses of it (heap_ok_in),
   which is what the new root of such a lemma asks for
   (roots_ok_data); heap_el reads an element of a data element
   (heap_el_data); the values of the two stacks are related
   elementwise (all2_el_cons); and a reference that the value of a
   reference reaches is one that a pointer to that reference
   reaches, because the pointer has an edge to it (reach_ref) *)

let all_ts_mono = prove
 (cake_as_vars (fun () ->
    `all_ts refs stack' SUBSET all_ts refs (v :: stack')`),
  REWRITE_TAC[all_ts_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[SUBSET; IN_ELIM_THM; MEM] THEN
  MESON_TAC[]);;

let heap_ok_in = prove
 (`heap_ok heap limit' /\
   heap_lookup a heap = SOME (DataElement xs l d)
   ==> (!ptr u. MEM (gc_shared_Pointer ptr u) xs
                ==> isSomeDataElement (heap_lookup ptr heap))`,
  REWRITE_TAC[heap_ok_def] THEN
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN
  ASM_MESON_TAC[heap_lookup_MEM]);;

(* heap_el reads the element of a data element at an index *)
let heap_el_data = prove
 (`heap_lookup ptr heap = SOME (DataElement ys l d) /\ i < LENGTH ys
   ==> heap_el (gc_shared_Pointer ptr u) i heap = (EL i ys,T)`,
  STRIP_TAC THEN
  ASM_REWRITE_TAC[heap_el_def] THEN
  SAFE_MATCH_REDUCE_TAC THEN
  ASM_REWRITE_TAC[]);;

(* and the root it reads is an address of a good heap *)
let roots_ok_data = prove
 (`heap_ok heap limit' /\
   heap_lookup ptr heap = SOME (DataElement ys l d) /\
   i < LENGTH ys /\ roots_ok rs heap
   ==> roots_ok (EL i ys :: rs) heap`,
  STRIP_TAC THEN
  FIRST_X_ASSUM (fun ro ->
    if not (hd_is "roots_ok" (concl ro)) then fail() else
    MP_TAC (REWRITE_RULE[roots_ok_def] ro)) THEN
  REWRITE_TAC[roots_ok_def; MEM] THEN
  DISCH_TAC THEN
  REPEAT GEN_TAC THEN STRIP_TAC THENL
   [(* the new root is a pointer of the element *)
    W(fun gl ->
      let ho = the_asm (hd_is "heap_ok") gl in
      let hl = the_asm (fun c -> is_eq c &&
                 hd_is "heap_lookup" (lhand c)) gl in
      MP_TAC (MATCH_MP heap_ok_in (CONJ ho hl))) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    W(fun gl ->
      let e = the_asm (fun c -> is_eq c &&
                hd_is "gc_shared_Pointer" (lhand c)) gl in
      EXISTS_TAC (rand (lhand (concl e))) THEN
      ONCE_REWRITE_TAC[e]) THEN
    FIRST [SOLVED (REWRITE_TAC[MEM_EL] THEN EXISTS_TAC `i:num` THEN
                   ASM_REWRITE_TAC[]);
           SOLVED (MATCH_MP_TAC MEM_EL THEN ASM_ARITH_TAC);
           SOLVED (ASM_SIMP_TAC[MEM_EL])];
    (* and the old roots are what they were *)
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    W(fun gl ->
      let m = the_asm (hd_is "MEM") gl in
      EXISTS_TAC (rand (el 0 (snd (strip_comb (concl m)))))) THEN
    FIRST_ASSUM ACCEPT_TAC]);;

let all2_el_cons = prove
 (`!(P:A->B->bool) xs ys i a b st rs.
     EVERY2 P xs ys /\ i < LENGTH xs /\ P a b /\ EVERY2 P st rs
     ==> EVERY2 P (EL i xs :: a :: st) (EL i ys :: b :: rs)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[ALL2_DEF; HD; TL; NOT_CONS_NIL] THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  MP_TAC (SPEC `i:num` (CONJUNCT2 (REWRITE_RULE[LIST_REL_EL_EQN]
    (ASSUME `EVERY2 (P:A->B->bool) xs ys`)))) THEN
  ASM_REWRITE_TAC[]);;

(* a reference that a value of a reference reaches is one that a
   pointer to that reference reaches: the pointer has an edge to
   everything the value's references are *)
let reach_ref = prove
 (cake_as_vars (fun () ->
    `(!y. MEM y (get_refs v) ==> ref_edge refs ptr y) /\
     reachable_refs (v :: RefPtr b ptr :: stack') refs n
     ==> reachable_refs (RefPtr b ptr :: stack') refs n`),
  REWRITE_TAC[reachable_refs_def; MEM] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC)) THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    let c = concl th in
    if is_eq c && is_var (lhand c) then SUBST_ALL_TAC th
    else fail())) THEN
  W(fun (asl,w as gl) ->
    let ed = the_asm (fun c ->
               let vs,bd = strip_forall c in
               length vs = 1 && is_imp bd &&
               hd_is "ref_edge" (rand bd)) gl in
    let gr = rand (lhand (snd (strip_forall (concl ed)))) in
    let m = the_asm (fun c -> hd_is "MEM" c &&
              hd_is "get_refs" (rand c)) gl in
    let rv = el 0 (snd (strip_comb (concl m))) in
    let rtc = the_asm (hd_is "RTC") gl in
    if rand (concl m) = gr then
      (* the path starts inside the value: then it starts at the
         pointer of the reference, with the edge of the pointer in
         front of it *)
      (let rp = find_term (hd_is "dataSem_RefPtr") w in
       EXISTS_TAC rp THEN EXISTS_TAC (rand rp) THEN
       REWRITE_TAC[get_refs_def; MEM] THEN
       MATCH_MP_TAC (CONJUNCT2 (SPEC_ALL RTC_RULES)) THEN
       EXISTS_TAC rv THEN
       CONJ_TAC THENL
        [ACCEPT_TAC (MATCH_MP ed m); ACCEPT_TAC rtc])
    else
      (* or at a root of the stack, which keeps its path *)
      (EXISTS_TAC (el 0 (snd (strip_comb (rand (concl m))))) THEN
       EXISTS_TAC rv THEN
       ASM_REWRITE_TAC[MEM])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let deref_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (RefPtr b ptr :: stack) refs
  (roots,heap,be,a,sp,sp1,gens) limit ts ==>
      (?r roots2.
        (roots = r :: roots2) /\ ptr IN (domain refs) /\
        (match THE (lookup ptr refs) with ByteArray _40 _41 -> T |
          bvlSem_MutBlock _42 _43 _44 _45 _46 -> T | ValueArray vs ->
        (!n. n < LENGTH vs ==>
            (?y. (heap_el r n heap = (y,T)) /\
                  abs_ml_inv conf (EL n vs :: RefPtr b ptr ::
                    stack) refs
                    (y :: roots,heap,be,a,sp,sp1,gens) limit ts)) |
                      Thunk Evaluated v -> T | Thunk NotEvaluated v ->
        (?y. (heap_el r 0 heap = (y,T)) /\
              abs_ml_inv conf (v :: RefPtr b ptr :: stack) refs
                (y :: roots,heap,be,a,sp,sp1,gens) limit ts)))`),
  (* the steps are above the statement (tools/overrides.py).  The
     roots are a cons whose head is what the relation gives the
     pointer: of a pointer to a reference the address of its
     element, and of a pointer to a thunk the address of the thunk
     -- while a thunk that has been evaluated away is the value
     itself, and of that kind the claim is nothing.  The references
     reach the key, because the pointer is a root of the stack, so
     bc_ref_inv says what the heap holds at the address: of an
     array of values a RefBlock, of a thunk a ThunkBlock.  The
     value that the dereference reads is the element of that at the
     index (heap_el_data), it is a pointer of a good heap
     (roots_ok_data), the timestamps only grow (all_ts_mono), the
     blocks stay unique (blocks_unique_deref1 and the second of
     them) and a reference that the value reaches is one that the
     pointer reaches (reach_ref) *)
  (STRIP_TAC THEN
   (* what the invariant says of the stack with the pointer at its
      head *)
   FIRST_X_ASSUM (fun inv ->
     if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                    bc_stack_ref_inv_def] inv)) THEN
   (* the roots are a cons, and its head is the pointer's *)
   W(fun gl ->
     let lr = the_asm (fun c -> hd_is "ALL2" c) gl in
     CASES_ON_TAC (el 2 (snd (strip_comb (concl lr))))) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[ALL2_DEF; HD; TL; NOT_CONS_NIL]) THEN
   TRY (FIRST_ASSUM CONTR_TAC) THEN
   SPLIT_ASM_TAC THEN
   (* the witnesses: the head of the roots and its tail *)
   W(fun (asl,w) ->
     let cns = lhs (hd (conjuncts (snd (strip_exists w)))) in
     EXISTS_TAC (lhand cns) THEN EXISTS_TAC (rand cns)) THEN
   (* the relation of the pointer: a pointer to the reference, a
      pointer to a thunk, or the value of a thunk that has been
      evaluated away *)
   FIRST_ASSUM (fun vi ->
     if not (hd_is "v_inv" (concl vi)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[v_inv_def] vi)) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED REFL_TAC) THEN
   (* the key of the pointer is one of the references: it is a key
      of the map of the addresses, or the references hold a thunk
      for it *)
   TRY (SOLVED
         (W(fun gl ->
            let inn = the_asm (fun c -> hd_is "IN" c &&
                        hd_is "FDOM" (rand c)) gl in
            let su = the_asm (fun c -> hd_is "SUBSET" c &&
                       hd_is "domain" (rand c)) gl in
            MP_TAC inn THEN MP_TAC su) THEN
          REWRITE_TAC[SUBSET] THEN MESON_TAC[])) THEN
   TRY (SOLVED
         (REWRITE_TAC[domain_lookup] THEN
          W(fun gl ->
            let lk = the_asm (fun c -> is_eq c &&
                       hd_is "sptree_lookup" (lhand c)) gl in
            MESON_TAC[lk]))) THEN
   (* and what the references hold at the key decides the claim *)
   W(fun (asl,w) ->
     NAMED_CASES_TAC (find_term (hd_is "sptree_lookup") w)
       [[]; ["rv"]]) THEN
   (* the references have a value for the key, so the lookup is no
      NONE *)
   TRY (SOLVED
         (W(fun gl ->
            let lk = the_asm (fun c -> is_eq c &&
                       hd_is "sptree_lookup" (lhand c) &&
                       not (hd_is "SOME" (rand c))) gl in
            let inn = the_asm (fun c -> hd_is "IN" c &&
                        hd_is "FDOM" (rand c)) gl in
            let su = the_asm (fun c -> hd_is "SUBSET" c &&
                       hd_is "domain" (rand c)) gl in
            MP_TAC (REWRITE_RULE[lookup_NONE_domain] lk) THEN
            MP_TAC inn THEN MP_TAC su THEN
            REWRITE_TAC[SUBSET] THEN MESON_TAC[]))) THEN
   TRY (SOLVED
         (W(fun gl ->
            let lk = the_asm (fun c -> is_eq c &&
                       hd_is "sptree_lookup" (lhand c) &&
                       not (hd_is "SOME" (rand c))) gl in
            let lk2 = the_asm (fun c -> is_eq c &&
                        hd_is "sptree_lookup" (lhand c) &&
                        hd_is "SOME" (rand c)) gl in
            MP_TAC lk THEN MP_TAC lk2 THEN
            REWRITE_TAC[distinctness "option"] THEN
            MESON_TAC[]))) THEN
   NAMED_CASES_TAC (cake_as_vars (fun () ->
     `rv:(dataSem_v)bvlSem_ref`))
     [["vl"]; ["flag"; "bs"]; ["md"; "vv"]; ["tg"; "fin"; "ll";
      "cc"; "rr"]] THEN
   (* of an array of bytes and of a mutable block there is nothing
      to say, and of a thunk only when it has not been evaluated *)
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
   (* the kind that the case gives and the one of the relation are
      the same, so their fields are the same as well *)
   RULE_ASSUM_TRY (REWRITE_RULE[injectivity "option";
                               injectivity "bvlSem_ref";
                               distinctness "option";
                               distinctness "bvlSem_ref"]) THEN
   TRY (FIRST_ASSUM CONTR_TAC) THEN
   SPLIT_ASM_TAC THEN
   REPEAT (FIRST_X_ASSUM (fun th ->
     let c = concl th in
     if is_eq c && is_var (lhand c) &&
        (is_var (rand c) ||
         (try fst (dest_type (type_of (lhand c))) = "thunk_mode"
          with Failure _ -> false))
     then SUBST_ALL_TAC th else fail())) THEN
   (* a pointer to a thunk is one that the source marks with F *)
   REPEAT (FIRST_X_ASSUM (fun th ->
     let c = concl th in
     if is_neg c && is_var (rand c)
     then SUBST_ALL_TAC (EQF_INTRO th) else fail())) THEN
   (* the value of the key, which THE of its lookup is *)
   REWRITE_TAC[THE] THEN
   MATCH_REDUCE_TAC THEN
   TRY (SOLVED (REWRITE_TAC[])) THEN
   (* and of a thunk whether it has been evaluated: of one that
      has there is nothing to say either *)
   W(fun (asl,w) ->
     let md = fun t -> is_var t &&
                (try fst (dest_type (type_of t)) = "thunk_mode"
                 with Failure _ -> false) in
     if not (can (find_term md) w) then ALL_TAC else
     CASES_ON_TAC (find_term md w)) THEN
   REWRITE_TAC[distinctness "thunk_mode"] THEN
   MATCH_REDUCE_TAC THEN
   TRY (SOLVED (REWRITE_TAC[])) THEN
   (* the kind that the case gives and the kind that the relation
      of the pointer gives are the same one *)
   TRY (SOLVED
         (W(fun gl ->
            let bad = the_asm (fun c ->
                        let vs,bd = strip_forall c in
                        length vs = 2 && is_neg bd &&
                        is_conj (rand bd)) gl in
            MP_TAC bad) THEN
          MESON_TAC[])) THEN
   (* the references reach the key, because the pointer of the
      stack is a root that has it *)
   W(fun (asl,w as gl) ->
     let bri = the_asm (fun c ->
                 let vs,bd = strip_forall c in
                 length vs = 1 && is_imp bd &&
                 hd_is "bc_ref_inv" (rand bd)) gl in
     let inn = the_asm (fun c -> hd_is "IN" c &&
                 hd_is "FDOM" (rand c)) gl in
     let n = el 0 (snd (strip_comb (concl inn))) in
     SUBGOAL_THEN (lhand (lhand (concl (SPEC n bri))))
       ASSUME_TAC THENL
      [REWRITE_TAC[reachable_refs_def] THEN
       W(fun (asl,w) ->
         let rp = find_term (hd_is "dataSem_RefPtr") w in
         EXISTS_TAC rp THEN EXISTS_TAC (rand rp)) THEN
       REWRITE_TAC[MEM; get_refs_def] THEN
       MATCH_ACCEPT_TAC (CONJUNCT1 (SPEC_ALL RTC_RULES));
       ALL_TAC]) THEN
   (* what the heap holds at the address of the key: of an array of
      values a RefBlock, of a thunk a ThunkBlock *)
   W(fun (asl,w as gl) ->
     let inn = the_asm (fun c -> hd_is "IN" c &&
                 hd_is "FDOM" (rand c)) gl in
     let n = el 0 (snd (strip_comb (concl inn))) in
     let fm = rand (rand (concl inn)) in
     let bri = the_asm (fun c ->
                 let vs,bd = strip_forall c in
                 length vs = 1 && is_imp bd &&
                 hd_is "bc_ref_inv" (rand bd)) gl in
     let rr = the_asm (hd_is "reachable_refs") gl in
     let flk = ASSUME (mk_eq (list_mk_icomb "FLOOKUP" [fm; n],
                 list_mk_icomb "SOME"
                   [list_mk_icomb "fmap_apply" [fm; n]])) in
     SUBGOAL_THEN (concl flk) ASSUME_TAC THENL
      [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC] THEN
     ASSUME_TAC (MP (SPEC n bri) (CONJ rr inn))) THEN
   W(fun gl ->
     let lk = the_asm (fun c -> is_eq c &&
                hd_is "sptree_lookup" (lhand c) &&
                hd_is "SOME" (rand c)) gl in
     let flk = the_asm (fun c -> is_eq c &&
                 hd_is "FLOOKUP" (lhand c)) gl in
     let inv = the_asm (hd_is "bc_ref_inv") gl in
     let arm = tryfind (fun a -> MATCH_MP a (CONJ flk lk))
                 [arm_VA; arm_TH] in
     STRIP_ASSUME_TAC (REWRITE_RULE[arm] inv)) THEN
   (* the index is below the length of the element, which is as
      long as the array of values *)
   W(fun gl ->
     let e2 = the_asm (fun c -> hd_is "ALL2" c &&
                is_abs (el 0 (snd (strip_comb c)))) gl in
     ASSUME_TAC (MATCH_MP LIST_REL_LENGTH e2)) THEN
   REPEAT STRIP_TAC THEN
   (* the root to add is the element of the heap's element at the
      index, and of a thunk it is the one value it holds *)
   W(fun (asl,w as gl) ->
     let hl = the_asm (fun c -> is_eq c &&
                hd_is "heap_lookup" (lhand c) &&
                hd_is "SOME" (rand c)) gl in
     let el1 = rand (rand (concl hl)) in
     let args = snd (strip_comb el1) in
     let zs = last args in
     let bod = snd (strip_exists w) in
     let idx = lhand (lhand (hd (conjuncts bod))) in
     if hd_is "ThunkBlock" el1
     then EXISTS_TAC zs
     else EXISTS_TAC (list_mk_icomb "EL" [idx; zs])) THEN
   CONJ_TAC THEN
   (* what the heap reads at the index *)
   TRY (SOLVED
         (W(fun (asl,w as gl) ->
            let hl = the_asm (fun c -> is_eq c &&
                       hd_is "heap_lookup" (lhand c) &&
                       hd_is "SOME" (rand c)) gl in
            let rq = the_asm (fun c -> is_eq c && is_var (lhand c) &&
                       hd_is "gc_shared_Pointer" (rand c)) gl in
            let hl2 = REWRITE_RULE[RefBlock_def;
                                   ThunkBlock_def] hl in
            let ys = el 0 (snd (strip_comb
                       (rand (rand (concl hl2))))) in
            let idx = lhand (lhand w) in
            SUBGOAL_THEN (list_mk_icomb "<"
                [idx; list_mk_icomb "LENGTH" [ys]])
              (fun ltx ->
                 ONCE_REWRITE_TAC[rq] THEN
                 MATCH_ACCEPT_TAC (REWRITE_RULE[EL; HD]
                   (MATCH_MP heap_el_data (CONJ hl2 ltx)))) THEN
            REWRITE_TAC[LENGTH] THEN ASM_ARITH_TAC))) THEN
   (* and the invariant of the stack with that value in front *)
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the new root is a pointer of a good heap *)
   TRY (SOLVED
         (W(fun (asl,w as gl) ->
            let ho = the_asm (hd_is "heap_ok") gl in
            let hl = the_asm (fun c -> is_eq c &&
                       hd_is "heap_lookup" (lhand c) &&
                       hd_is "SOME" (rand c)) gl in
            let hl2 = REWRITE_RULE[RefBlock_def;
                                   ThunkBlock_def] hl in
            let ys = el 0 (snd (strip_comb
                       (rand (rand (concl hl2))))) in
            let ro = the_asm (hd_is "roots_ok") gl in
            let hd0 = lhand (el 0 (snd (strip_comb w))) in
            let idx = if hd_is "EL" hd0 then lhand hd0
                      else mk_small_numeral 0 in
            SUBGOAL_THEN (list_mk_icomb "<"
                [idx; list_mk_icomb "LENGTH" [ys]])
              (fun ltx -> MATCH_ACCEPT_TAC (REWRITE_RULE[EL; HD]
                 (MATCH_MP roots_ok_data
                    (CONJ ho (CONJ hl2 (CONJ ltx ro)))))) THEN
            REWRITE_TAC[LENGTH] THEN ASM_ARITH_TAC))) THEN
   (* the two maps are the ones they were *)
   W(fun gl ->
     let sub p = rand (lhand (concl (the_asm (fun c ->
       hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
     EXISTS_TAC (sub "domain") THEN EXISTS_TAC (sub "all_ts")) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the timestamps of the stack only grow *)
   TRY (SOLVED
         (MATCH_MP_TAC SUBSET_TRANS THEN
          W(fun gl ->
            let s = the_asm (fun c -> hd_is "SUBSET" c &&
                      hd_is "all_ts" (rand c)) gl in
            EXISTS_TAC (rand (concl s))) THEN
          CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
          MATCH_ACCEPT_TAC all_ts_mono)) THEN
   (* the blocks of the stack stay unique, because the value is one
      of a reference that the stack has already *)
   TRY (SOLVED
         (W(fun gl ->
            let lk = the_asm (fun c -> is_eq c &&
                       hd_is "sptree_lookup" (lhand c) &&
                       hd_is "SOME" (rand c)) gl in
            let bu = the_asm (hd_is "blocks_unique") gl in
            let lt = try [the_asm (hd_is "<") gl]
                     with Failure _ -> [] in
            MATCH_ACCEPT_TAC (tryfind (fun f -> f ())
              [(fun () -> MATCH_MP blocks_unique_deref1
                  (CONJ lk bu));
               (fun () -> MATCH_MP blocks_unique_deref2
                  (CONJ (hd lt) (CONJ lk bu)))])))) THEN
   (* the values of the stack with the value in front: of an array
      of values the relation of its values, the other way round
      (entry 53), gives it at the index; of a thunk the relation of
      its value is the one the arm gave *)
   W(fun (asl,w) ->
     if not (hd_is "ALL2" w) then ALL_TAC else
     (let gp = el 0 (snd (strip_comb w)) in
      let olds = mapfilter (fun (_,th) ->
                   let c = concl th in
                   if hd_is "ALL2" c &&
                      not (el 0 (snd (strip_comb c)) = gp)
                   then CONV_RULE(TOP_DEPTH_CONV BETA_CONV)
                          (MATCH_MP EVERY2_SWAP th)
                   else fail()) asl in
      MAP_EVERY ASSUME_TAC olds THEN
      FIRST
       [(MATCH_MP_TAC all2_el_cons THEN
         CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
         REPEAT CONJ_TAC THEN
         TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
         ASM_ARITH_TAC);
        (REWRITE_TAC[ALL2] THEN
         CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
         REPEAT CONJ_TAC THEN
         TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)))])) THEN
   (* and a reference that the value reaches is one that the
      pointer reaches, because the pointer has an edge to it *)
   REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM (fun bri ->
     let b = snd (strip_forall (concl bri)) in
     if not (is_imp b) || not (hd_is "bc_ref_inv" (rand b))
     then fail() else MATCH_MP_TAC bri) THEN
   CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   MATCH_MP_TAC (GEN_ALL reach_ref) THEN
   (* the value whose references are the ones to account for *)
   W(fun (asl,w as gl) ->
     if not (is_exists w) then ALL_TAC else
     (let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
                 not (hd_is "dataSem_RefPtr"
                        (lhand (el 0 (snd (strip_comb c)))))) gl in
      EXISTS_TAC (lhand (el 0 (snd (strip_comb (concl rr))))))) THEN
   CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the edge of the pointer lands at every reference of the
      value, because what the key holds has the value in it *)
   GEN_TAC THEN DISCH_TAC THEN
   W(fun gl ->
     let lk = the_asm (fun c -> is_eq c &&
                hd_is "sptree_lookup" (lhand c) &&
                hd_is "SOME" (rand c)) gl in
     REWRITE_TAC[ref_edge_def; lk]) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[EL; HD] THEN
   W(fun gl ->
     let m = the_asm (fun c -> hd_is "MEM" c &&
               hd_is "get_refs" (rand c)) gl in
     let vv = el 0 (snd (strip_comb (rand (concl m)))) in
     MATCH_MP_TAC (GEN_ALL refs_in_block) THEN
     EXISTS_TAC vv THEN
     CONJ_TAC THENL
      [FIRST [SOLVED (MATCH_MP_TAC MEM_EL THEN ASM_ARITH_TAC);
              SOLVED (REWRITE_TAC[MEM])];
       ACCEPT_TAC m])));;

(* el *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_el = prove
 (cake_as_vars (fun () ->
    `i < LENGTH xs /\
     blocks_unique ts (all_vs refs (Block t0 n xs :: stack)) ==>
       blocks_unique ts (all_vs refs (EL i xs :: Block t0 n xs ::
         stack))`),
  (* and the element of a Block is one of its payload *)
  (let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   let vblk = prove
    (`!t tag xs ys. v_all_vs (CONS (Block t tag xs) ys) =
        APPEND (CONS (Block t tag xs) (v_all_vs xs)) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let fblk = prove
    (`!(v:dataSem_v) t tag xs ys y.
        MEM y (v_all_vs (CONS v (CONS (Block t tag xs) ys))) <=>
        MEM y (v_all_vs [v]) \/ y = Block t tag xs \/
        MEM y (v_all_vs xs) \/ MEM y (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [cons_app] THEN
     REWRITE_TAC[v_all_vs_append; MEM_APPEND; vblk; MEM;
                 DISJ_ASSOC]) in

   let inc = prove
    (`!refs t0 n xs i stack' t a q.
        i < LENGTH xs /\
        Block t a q IN
          all_vs refs (CONS (EL i xs) (CONS (Block t0 n xs)
            stack')) ==>
        Block t a q IN all_vs refs (CONS (Block t0 n xs) stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; fblk;
                 vblk; MEM; MEM_APPEND] THEN
     MESON_TAC[MEM_v_all_vs_EL]) in
   REWRITE_TAC[blocks_unique_def] THEN STRIP_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: the steps that the lemmas about abs_ml_inv of a
   stack take, over the ones of deref_thm's block.  heap_el reads
   the element of a Block's representation (heap_el_block) and the
   root it reads is an address of a good heap (roots_ok_el), which
   are the two generic lemmas with the Block's shape put in; and a
   value put on the stack reaches no more references than the Block
   it comes out of (reach_block) *)

let heap_el_block = prove
 (`heap_lookup ptr heap = SOME (BlockRep n ys) /\ i < LENGTH ys
   ==> heap_el (gc_shared_Pointer ptr u) i heap = (EL i ys,T)`,
  REWRITE_TAC[BlockRep_def] THEN MATCH_ACCEPT_TAC heap_el_data);;

let roots_ok_el = prove
 (`heap_ok heap limit' /\
   heap_lookup ptr heap = SOME (BlockRep n ys) /\
   i < LENGTH ys /\ roots_ok rs heap
   ==> roots_ok (EL i ys :: rs) heap`,
  REWRITE_TAC[BlockRep_def] THEN MATCH_ACCEPT_TAC roots_ok_data);;

let reach_block = prove
 (cake_as_vars (fun () ->
    `MEM v ys /\ reachable_refs (v :: Block ts tag ys :: stack') refs n
     ==> reachable_refs (Block ts tag ys :: stack') refs n`),
  REWRITE_TAC[reachable_refs_def; MEM] THEN
  REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[refs_in_block]);;

(* the assumption that says what the heap holds for a Block *)

let blockrep_asm =
  the_asm (fun c -> is_eq c && hd_is "heap_lookup" (lhand c) &&
             can (fun t -> hd_is "BlockRep" (rand t)) (rand c));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let el_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (Block t0 n xs :: stack) refs
  (roots,heap,be,a,sp,sp1,gens) limit ts /\
      i < LENGTH xs ==>
      (?r roots2 y.
        (roots = r :: roots2) /\ (heap_el r i heap = (y,T)) /\
        abs_ml_inv conf (EL i xs :: Block t0 n xs :: stack) refs
                        (y :: roots,heap,be,a,sp,sp1,gens) limit
                          ts)`),
  (* the steps that this lemma and the ones after it take are
     above the statement (tools/overrides.py).  The roots are a
     cons whose head is the Block's pointer, the element of the
     payload at the index is the element of its representation
     there, and the invariant of the new stack is the old one
     with that value in front *)
  (STRIP_TAC THEN
   (* what the invariant says of the stack with the Block at its
      head *)
   FIRST_X_ASSUM (fun inv ->
     if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                    bc_stack_ref_inv_def] inv)) THEN
   (* the roots are a cons, and its head is the Block's *)
   W(fun gl ->
     let lr = the_asm (fun c -> hd_is "ALL2" c) gl in
     CASES_ON_TAC (el 2 (snd (strip_comb (concl lr))))) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[ALL2_DEF; HD; TL; NOT_CONS_NIL]) THEN
   TRY (FIRST_ASSUM CONTR_TAC) THEN
   SPLIT_ASM_TAC THEN
   (* the payload is not empty, because the index is below its
      length *)
   SUBGOAL_THEN `~((xs:dataSem_v list) = [])` ASSUME_TAC THENL
    [REWRITE_TAC[GSYM LENGTH_EQ_NIL] THEN ASM_ARITH_TAC;
     ALL_TAC] THEN
   (* the Block is a pointer at its representation in the heap; the
      invariant of the Block itself is kept, because the values of
      the new stack ask for it *)
   FIRST_ASSUM (fun vb ->
     if not (hd_is "v_inv" (concl vb)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[v_inv_def;
       ASSUME `~((xs:dataSem_v list) = [])`] vb)) THEN
   VAR_EQ_TAC THEN
   (* the witnesses: the head of the roots, its tail, and the
      element of the Block's representation at the index *)
   W(fun (asl,w as gl) ->
     let cns = lhs (hd (conjuncts (snd (strip_exists w)))) in
     let ys = el 1 (snd (strip_comb (rand (rand
                (concl (blockrep_asm gl)))))) in
     EXISTS_TAC (lhand cns) THEN EXISTS_TAC (rand cns) THEN
     EXISTS_TAC (list_mk_icomb "EL" [`i:num`; ys])) THEN
   (* the payload and its representation are of a length *)
   FIRST_ASSUM (fun lr ->
     if not (hd_is "ALL2" (concl lr)) then fail() else
     ASSUME_TAC (MATCH_MP LIST_REL_LENGTH lr)) THEN
   (* so the index is below the length of the representation *)
   W(fun gl ->
     let lt = the_asm (hd_is "<") gl in
     let le = the_asm (fun c -> is_eq c &&
                hd_is "LENGTH" (lhand c)) gl in
     SUBGOAL_THEN (mk_binop `(<):num->num->bool`
                     (lhand (concl lt)) (rand (concl le)))
       ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED REFL_TAC) THEN
   (* what the heap holds at the index *)
   TRY (SOLVED
         (W(fun gl ->
            let hl = blockrep_asm gl in
            let lt = the_asm (fun c -> hd_is "<" c &&
                       hd_is "LENGTH" (rand c)) gl in
            MATCH_ACCEPT_TAC (MATCH_MP heap_el_block
              (CONJ hl lt))))) THEN
   (* the invariant with the element on the stack *)
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   (* the new root is a pointer of the Block's element, and the
      pointers of a good heap are addresses of it *)
   TRY (SOLVED
         (W(fun gl ->
            let ho = the_asm (hd_is "heap_ok") gl in
            let hl = blockrep_asm gl in
            let lt = the_asm (fun c -> hd_is "<" c &&
                       hd_is "LENGTH" (rand c)) gl in
            let ro = the_asm (hd_is "roots_ok") gl in
            MATCH_ACCEPT_TAC (MATCH_MP roots_ok_el
              (CONJ ho (CONJ hl (CONJ lt ro))))))) THEN
   (* the two maps are the same ones *)
   W(fun gl ->
     let sub p = rand (lhand (concl (the_asm (fun c ->
       hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
     EXISTS_TAC (sub "domain") THEN EXISTS_TAC (sub "all_ts")) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   (* the timestamps of the stack only grow *)
   TRY (SOLVED
         (MATCH_MP_TAC SUBSET_TRANS THEN
          W(fun gl ->
            let s = the_asm (fun c -> hd_is "SUBSET" c &&
                      hd_is "all_ts" (rand c)) gl in
            EXISTS_TAC (rand (concl s))) THEN
          CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
          MATCH_ACCEPT_TAC all_ts_mono)) THEN
   (* the blocks of the stack stay unique *)
   TRY (SOLVED
         (MATCH_MP_TAC (GEN_ALL blocks_unique_el) THEN
          CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC)) THEN
   (* the values of the stack are the old ones and the element *)
   (* the values of the stack are the old ones and the element,
      which the relation of the payload gives at the index
      (all2_el_cons) *)
   TRY (SOLVED
         (MATCH_MP_TAC all2_el_cons THEN
          CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
          REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
          POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC (filter
            (fun t -> let c = concl t in
               hd_is "<" c ||
               (is_eq c && (hd_is "LENGTH" (lhand c) ||
                            hd_is "LENGTH" (rand c)))) l)) THEN
          ASM_ARITH_TAC)) THEN
   (* and a reference that the element reaches is one that the
      Block reaches *)
   REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM (fun bri ->
     let b = snd (strip_forall (concl bri)) in
     if not (is_imp b) || not (hd_is "bc_ref_inv" (rand b))
     then fail() else MATCH_MP_TAC bri) THEN
   CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   MATCH_MP_TAC (GEN_ALL reach_block) THEN
   W(fun gl ->
     let rr = the_asm (hd_is "reachable_refs") gl in
     EXISTS_TAC (lhand (el 0 (snd (strip_comb (concl rr)))))) THEN
   CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   MEM_CLOSE));;

(* new byte array *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_new_byte_alt = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs stack) ==>
       blocks_unique ts
         (all_vs (insert ptr (ByteArray fl bs) refs) (RefPtr b
           ptr :: stack))`),
  (* and the RefPtr that the stack is given is no Block *)
  (let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let vrefptr = prove
    (`!b p ys. v_all_vs (CONS (RefPtr b p) ys) =
        CONS (RefPtr b p) (v_all_vs ys)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let inc = prove
    (`!refs p fl bs b stack' t a q.
        Block t a q IN
          all_vs (insert p (ByteArray fl bs) refs)
                 (CONS (RefPtr b p) stack') ==>
        Block t a q IN all_vs refs stack'`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; li;
                 vrefptr; MEM; distinctness "dataSem_v";
                 distinctness "bvlSem_ref";
                 injectivity "bvlSem_ref"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: what the proof of new_byte_alt_thm needs of an
   array of bytes written at a key that the references do not have.
   What sits at the key holds no value, so the paths through the
   new references are the ones there were (ref_edge_ByteArray) and
   a reference that the new stack reaches is the key or one that
   the old stack reached; the timestamps of the references and the
   stack only grow, and what the invariant said of a value it says
   of it with the key written and the store done *)

(* a path cannot leave an address that has no edge *)
let RTC_dead = prove
 (`!(R:A->A->bool) x y. RTC R x y /\ (!z. ~(R x z)) ==> x = y`,
  MESON_TAC[RTC_CASES]);;

(* the edges of the references with an array of bytes written at a
   key they did not have are the ones they had *)
let ref_edge_ByteArray = prove
 (cake_as_vars (fun () ->
    `~(ptr IN domain refs)
     ==> ref_edge (sptree_insert ptr (ByteArray fl xs) refs) =
         ref_edge refs`),
  REWRITE_TAC[GSYM lookup_NONE_domain] THEN DISCH_TAC THEN
  REWRITE_TAC[FUN_EQ_THM] THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[ref_edge_def; lookup_insert] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

(* so a reference that the stack with the pointer of the array on
   it reaches is the key of the array or one that the stack
   reached *)
let reachable_refs_new_byte = prove
 (cake_as_vars (fun () ->
    `reachable_refs (RefPtr b ptr :: stack)
       (sptree_insert ptr (ByteArray fl xs) refs) n /\
     ~(ptr IN domain refs)
     ==> n = ptr \/ reachable_refs stack refs n`),
  (* the path starts at a root of the stack, which keeps it, or at
     the pointer of the array, and then it does not start at all,
     because the key is fresh and so has no edge *)
  STRIP_TAC THEN
  W(fun gl ->
    let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c)) gl in
    let rr = the_asm (hd_is "reachable_refs") gl in
    MP_TAC (REWRITE_RULE[GSYM lookup_NONE_domain] nd) THEN
    MP_TAC (REWRITE_RULE[reachable_refs_def; MEM;
                         MATCH_MP ref_edge_ByteArray nd] rr)) THEN
  REWRITE_TAC[reachable_refs_def] THEN
  DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
  DISCH_TAC THENL
   [(* the pointer of the array: the path starts at the key, which
        has no edge, so it does not go anywhere *)
    DISJ1_TAC THEN
    W(fun gl ->
      let xe = the_asm (fun c -> is_eq c && is_var (lhand c) &&
                 hd_is "dataSem_RefPtr" (rand c)) gl in
      let m = the_asm (fun c -> hd_is "MEM" c &&
                hd_is "get_refs" (rand c)) gl in
      let rtc = the_asm (hd_is "RTC") gl in
      let req = REWRITE_RULE[xe; get_refs_def; MEM] m in
      let rfs = rand (el 0 (snd (strip_comb (concl rtc)))) in
      let ptr = rand (concl req) in
      let zv = genvar `:num` in
      SUBGOAL_THEN (mk_forall (zv, mk_neg (list_mk_icomb "ref_edge"
                      [rfs; ptr; zv])))
        (fun ne -> ACCEPT_TAC (SYM (MATCH_MP RTC_dead
           (CONJ (REWRITE_RULE[req] rtc) ne)))) THEN
      GEN_TAC THEN REWRITE_TAC[ref_edge_def] THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[]);
    (* or a root of the stack, which keeps its path *)
    DISJ2_TAC THEN
    W(fun gl ->
      let m = the_asm (fun c -> hd_is "MEM" c &&
                hd_is "get_refs" (rand c)) gl in
      EXISTS_TAC (el 0 (snd (strip_comb (rand (concl m))))) THEN
      EXISTS_TAC (el 0 (snd (strip_comb (concl m))))) THEN
    ASM_REWRITE_TAC[]]);;

(* and what the invariant says of a value it says of it with the
   array written and the store done *)
let v_inv_new_byte_step = prove
 (cake_as_vars (fun () ->
    `v_inv conf w1 refs (w2,f,tf,heap) /\ ~(ptr IN domain refs) /\
     FDOM f SUBSET domain refs /\ heap_store_rel heap heap2 /\
     f2 = f |+ (ptr,aa) /\
     refs2 = sptree_insert ptr (ByteArray fl xs) refs
     ==> v_inv conf w1 refs2 (w2,f2,tf,heap2)`),
  (* the key is fresh in the references, so it is not in the domain
     of the map and the map is a SUBMAP of its update there;
     v_inv_SUBMAP takes the relation to the bigger map and the
     bigger heap, and v_inv_ByteArray_insert writes the array into
     the references *)
  (let submap_fupd = prove
    (`!(g:(A,B)fmap) k v. ~(k IN FDOM g) ==> g SUBMAP (g |+ (k,v))`,
     REWRITE_TAC[SUBMAP; FDOM_FUPDATE; IN_INSERT;
                 FAPPLY_FUPDATE_THM] THEN MESON_TAC[]) in
   STRIP_TAC THEN SPLIT_ASM_TAC THEN
   REPEAT (FIRST_X_ASSUM (fun e ->
     let c = concl e in
     if is_eq c && is_var (lhand c) then SUBST_ALL_TAC e
     else fail())) THEN
   (* the key is in neither domain *)
   W(fun gl ->
     let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                hd_is "domain" (rand (rand c))) gl in
     let su = the_asm (fun c -> hd_is "SUBSET" c) gl in
     SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
                     [el 0 (snd (strip_comb (rand (concl nd))));
                      list_mk_icomb "FDOM"
                        [rand (lhand (concl su))]])) ASSUME_TAC THENL
      [MP_TAC nd THEN MP_TAC su THEN REWRITE_TAC[SUBSET] THEN
       MESON_TAC[];
       ALL_TAC]) THEN
   MATCH_MP_TAC (GEN_ALL v_inv_SUBMAP) THEN
   W(fun gl -> MAP_EVERY (fun n -> EXISTS_TAC (var_by_name n gl))
                 ["f"; "tf"; "heap"]) THEN
   REPEAT CONJ_TAC THEN
   TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
   TRY (SOLVED (MATCH_ACCEPT_TAC SUBMAP_REFL)) THEN
   TRY (SOLVED (W(fun gl ->
     let nf = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                hd_is "FDOM" (rand (rand c))) gl in
     MATCH_ACCEPT_TAC (MATCH_MP submap_fupd nf)))) THEN
   MATCH_MP_TAC v_inv_ByteArray_insert THEN
   ASM_MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let new_byte_alt_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,heap,be,a,sp,sp1,gens) limit ts
  /\
     Abbrev (ws = LENGTH bs DIV (dimindex (:'a) DIV 8) + 1) /\
     ~(ptr IN (domain refs)) /\ ws + 1 <= sp ==>
     (?heap2.
       (heap_store_unused_alt a (sp + sp1)
         (Bytes be fl bs (REPLICATE ws ((n2w 0):'a word))) heap =
           (heap2,T)) /\
       abs_ml_inv conf ((RefPtr b ptr) :: stack) (insert ptr
         (ByteArray fl bs) refs)
                  (gc_shared_Pointer a (wordLang_Word (n2w 0)) ::
                    roots,heap2,be,a + ws + 1,
                   sp - (ws + 1),sp1,gens) limit ts)`),
  (* the steps are above the statement (tools/overrides.py).  The
     element is a word longer than the words it holds, so it fits
     in the unused space and IMP_heap_store_unused_alt writes it
     there; the heap, the roots and the space are then as good as
     they were (gc_kind_store_unused_alt of the kind of the
     collection, where an array of bytes is no reference), the map
     of the addresses gains the key of the array with the address
     it was written at, and of every reference that the stack
     reaches the invariant holds as it did (bc_ref_inv_step) --
     while the array itself is the element that the store wrote *)
  (STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* what the invariant says of the stack *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    (* the element written is a word longer than the words it
       holds *)
    W(fun (asl,w) ->
      let byt = find_term (hd_is "Bytes") w in
      let wsn = el 0 (snd (strip_comb
                  (el 3 (snd (strip_comb byt))))) in
      SUBGOAL_THEN (mk_eq (list_mk_icomb "el_length" [byt],
                      list_mk_icomb "+" [wsn; mk_small_numeral 1]))
        ASSUME_TAC THENL
       [REWRITE_TAC[bytes_def] THEN
        CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
        REWRITE_TAC[el_length_def] THEN MATCH_REDUCE_TAC THEN
        REWRITE_TAC[LENGTH_write_bytes; LENGTH_REPLICATE];
        ALL_TAC]) THEN
    (* so it fits in the unused space, and the store writes it
       there *)
    W(fun (asl,w as gl) ->
      let us = the_asm (hd_is "unused_space_inv") gl in
      let spsp = el 1 (snd (strip_comb (concl us))) in
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "el_length" (lhand c)) gl in
      let el1 = el 0 (snd (strip_comb (lhand (concl le)))) in
      SUBGOAL_THEN (list_mk_icomb "<="
                      [list_mk_icomb "el_length" [el1]; spsp])
        (fun bd -> STRIP_ASSUME_TAC (MATCH_MP
           IMP_heap_store_unused_alt (CONJ us bd))) THENL
       [REWRITE_TAC[le] THEN ASM_ARITH_TAC;
        ALL_TAC]) THEN
    (* the element is a data element, which is what the two facts
       about the store ask for *)
    W(fun gl ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
      let isd = is_data_el el1 in
      MAP_EVERY (fun th -> ASSUME_TAC (MP th isd))
        (mapfilter (fun (_,th) ->
           let c = concl th in
           if is_imp c && hd_is "isDataElement" (lhand c) then th
           else fail()) (fst gl))) THEN
    (* the witness: the heap that the store wrote *)
    W(fun (asl,w as gl) ->
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      EXISTS_TAC (lhand (rand (concl st)))) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* and the invariant of the new heap, stack and references *)
    REWRITE_TAC[abs_ml_inv_def] THEN
    (* the addresses that hold data are the ones that did, and the
       one the store wrote *)
    W(fun gl ->
      let seq = the_asm (fun c -> is_eq c &&
                  hd_is "INSERT" (rand c)) gl in
      let ro = the_asm (hd_is "roots_ok") gl in
      ASSUME_TAC (REWRITE_RULE[EXTENSION; IN_INSERT; IN_ELIM_THM]
                    seq) THEN
      ASSUME_TAC (REWRITE_RULE[roots_ok_def] ro)) THEN
    REPEAT CONJ_TAC THEN
    (* the roots: the one of the array is the address it was
       written at, and the others are the ones they were *)
    TRY (SOLVED
          (REWRITE_TAC[roots_ok_def; MEM] THEN
           REPEAT STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           TRY (SOLVED
                 (DISJ1_TAC THEN
                  FIRST_X_ASSUM (fun e ->
                    if not (is_eq (concl e)) ||
                       not (hd_is "gc_shared_Pointer" (rand (concl e)))
                    then fail() else
                    MP_TAC e) THEN
                  REWRITE_TAC[injectivity "heap_address"] THEN
                  MESON_TAC[])) THEN
           DISJ2_TAC THEN
           ASM_MESON_TAC[MEM_APPEND])) THEN
    (* the heap is good: it is as long as it was, it has no forward
       pointer, and the element written holds no pointer at all *)
    TRY (SOLVED
          (REWRITE_TAC[heap_ok_def] THEN
           REPEAT CONJ_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let hl = the_asm (fun c -> is_eq c &&
                               hd_is "heap_length" (lhand c)) gl in
                    MP_TAC ho THEN REWRITE_TAC[hl] THEN
                    STRIP_TAC THEN ASM_REWRITE_TAC[]))) THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let ho = REWRITE_RULE[heap_ok_def]
                               (the_asm (hd_is "heap_ok") gl) in
                    let impl = the_asm (fun c -> is_imp c &&
                                 is_neg (lhand c) &&
                                 hd_is "isForwardPointer"
                                   (rand (lhand c))) gl in
                    let st = the_asm (fun c -> is_eq c &&
                               hd_is "heap_store_unused_alt"
                                 (lhand c)) gl in
                    let el1 = el 2 (snd (strip_comb
                                (lhand (concl st)))) in
                    SUBGOAL_THEN (mk_neg (list_mk_icomb
                                    "isForwardPointer" [el1]))
                      (fun nf -> MP_TAC ho THEN
                         REWRITE_TAC[MP impl nf] THEN
                         STRIP_TAC THEN ASM_REWRITE_TAC[]) THEN
                    REWRITE_TAC[bytes_def] THEN
                    CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
                    REWRITE_TAC[isForwardPointer_def] THEN
                    MATCH_REDUCE_TAC THEN REWRITE_TAC[]))) THEN
           (* the pointers: the element written holds none, and of
              any other element they are what they were *)
           REPEAT GEN_TAC THEN
           W(fun gl ->
             let mem = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 3 && is_eq bd &&
                         hd_is "MEM" (lhand bd)) gl in
             REWRITE_TAC[mem]) THEN
           STRIP_TAC THEN
           W(fun gl ->
             let iso = the_asm (fun c ->
                         let vs,bd = strip_forall c in
                         length vs = 1 && is_eq bd &&
                         hd_is "isSomeDataElement" (lhand bd)) gl in
             REWRITE_TAC[iso]) THEN
           DISJ2_TAC THEN
           TRY (SOLVED
                 (W(fun gl ->
                    let eq = the_asm (fun c -> is_eq c &&
                               hd_is "Bytes" (lhand c)) gl in
                    MP_TAC eq) THEN
                  REWRITE_TAC[bytes_def] THEN
                  CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
                  REWRITE_TAC[injectivity "heap_element"] THEN
                  STRIP_TAC THEN
                  ASM_MESON_TAC[MEM])) THEN
           W(fun gl ->
             let ho = REWRITE_RULE[heap_ok_def]
                        (the_asm (hd_is "heap_ok") gl) in
             MP_TAC ho) THEN
           ASM_MESON_TAC[])) THEN
    (* the kind of the collection: the store into the unused space
       keeps it, and an array of bytes is no reference *)
    W(fun (asl,w as gl) ->
      if not (hd_is "gc_kind_inv" w) then ALL_TAC else
      (let gk = the_asm (hd_is "gc_kind_inv") gl in
       let st = the_asm (fun c -> is_eq c &&
                  hd_is "heap_store_unused_alt" (lhand c)) gl in
       let el1 = el 2 (snd (strip_comb (lhand (concl st)))) in
       let sp = el 2 (snd (strip_comb (concl gk))) in
       let le = the_asm (fun c -> is_eq c &&
                  hd_is "el_length" (lhand c)) gl in
       let us2 = the_asm (fun c -> hd_is "unused_space_inv" c &&
                   can (find_term (hd_is "-")) c) gl in
       let nr = PART_MATCH I isRef_Bytes
                  (mk_neg (list_mk_icomb
                     "data_to_word_memoryProof_isRef" [el1])) in
       SUBGOAL_THEN (list_mk_icomb "<="
                       [list_mk_icomb "el_length" [el1]; sp])
         (fun bd -> MATCH_ACCEPT_TAC (REWRITE_RULE[le] (MATCH_MP
            gc_kind_store_unused_alt
            (CONJ nr (CONJ bd (CONJ gk (CONJ st us2))))))) THEN
       REWRITE_TAC[le] THEN ASM_ARITH_TAC)) THEN
    (* the unused space: what the store lemma says, with the length
       of the element taken off *)
    W(fun (asl,w as gl) ->
      if not (hd_is "unused_space_inv" w) then ALL_TAC else
      (let us = the_asm (fun c -> hd_is "unused_space_inv" c &&
                  can (find_term (hd_is "-")) c) gl in
       let le = the_asm (fun c -> is_eq c &&
                  hd_is "el_length" (lhand c)) gl in
       MP_TAC (REWRITE_RULE[le] us) THEN
       W(fun (asl,w) ->
         let usub = el 1 (snd (strip_comb (lhand w))) in
         let gsub = el 1 (snd (strip_comb (rand w))) in
         let uadd = el 0 (snd (strip_comb (lhand w))) in
         let gadd = el 0 (snd (strip_comb (rand w))) in
         SUBGOAL_THEN (mk_eq (uadd, gadd)) ASSUME_TAC THENL
          [ASM_ARITH_TAC;
           SUBGOAL_THEN (mk_eq (usub, gsub)) ASSUME_TAC THENL
            [ASM_ARITH_TAC; ASM_REWRITE_TAC[]]]))) THEN
    (* the maps: the key of the array with the address it was
       written at, and the timestamps as they were *)
    REWRITE_TAC[bc_stack_ref_inv_def] THEN
    (* the key is fresh in the map of the addresses *)
    W(fun (asl,w as gl) ->
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "domain" (rand (rand c))) gl in
      let fm = rand (lhand (concl su)) in
      let ptr = el 0 (snd (strip_comb (rand (concl nd)))) in
      SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
                      [ptr; list_mk_icomb "FDOM" [fm]]))
        ASSUME_TAC THENL
       [MP_TAC su THEN MP_TAC nd THEN REWRITE_TAC[SUBSET] THEN
        MESON_TAC[];
        ALL_TAC]) THEN
    W(fun (asl,w as gl) ->
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let f = rand (lhand (concl su)) in
      let tfsu = the_asm (fun c -> hd_is "SUBSET" c &&
                   hd_is "all_ts" (rand c)) gl in
      let tf = rand (lhand (concl tfsu)) in
      let st = the_asm (fun c -> is_eq c &&
                 hd_is "heap_store_unused_alt" (lhand c)) gl in
      let aa = el 0 (snd (strip_comb (lhand (concl st)))) in
      let ins = find_term (hd_is "sptree_insert") w in
      let ptr = el 0 (snd (strip_comb ins)) in
      EXISTS_TAC (list_mk_icomb "|+" [f; mk_pair (ptr, aa)]) THEN
      EXISTS_TAC tf) THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the map of the addresses with the key at the address, which
       held no data *)
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) ||
         not (can (find_term (hd_is "|+")) w) then ALL_TAC else
      (let iso = the_asm (fun c ->
                   let vs,bd = strip_forall c in
                   length vs = 1 && is_eq bd &&
                   hd_is "isSomeDataElement" (lhand bd)) gl in
       let inj = the_asm (fun c -> hd_is "INJ" c &&
                   hd_is "fmap_apply" (el 0 (snd (strip_comb c))) &&
                   rand (el 0 (snd (strip_comb c))) =
                     lhand (rand (el 0 (snd (strip_comb w))))) gl in
       let nd = the_asm (fun c -> is_neg c &&
                  hd_is "isSomeDataElement" (rand c)) gl in
       MATCH_MP_TAC INJ_FUPDATE_fresh THEN
       EXISTS_TAC (rand (concl inj)) THEN
       REPEAT CONJ_TAC THEN
       TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
       TRY (SOLVED (MP_TAC nd THEN REWRITE_TAC[IN_ELIM_THM])) THEN
       REWRITE_TAC[IN_ELIM_THM] THEN
       MATCH_ACCEPT_TAC iso)) THEN
    (* and the map of the timestamps goes into the bigger set of
       addresses *)
    W(fun (asl,w as gl) ->
      if not (hd_is "INJ" w) then ALL_TAC else
      (let iso = the_asm (fun c ->
                   let vs,bd = strip_forall c in
                   length vs = 1 && is_eq bd &&
                   hd_is "isSomeDataElement" (lhand bd)) gl in
       let inj = the_asm (fun c -> hd_is "INJ" c &&
                   el 0 (snd (strip_comb c)) =
                     el 0 (snd (strip_comb w))) gl in
       MATCH_MP_TAC INJ_bigger THEN
       EXISTS_TAC (rand (concl inj)) THEN
       CONJ_TAC THENL
        [ACCEPT_TAC inj;
         REWRITE_TAC[IN_ELIM_THM] THEN
         REWRITE_TAC[iso] THEN MESON_TAC[]])) THEN
    (* the domain of the references has the key of the array *)
    TRY (SOLVED
          (REWRITE_TAC[FDOM_FUPDATE; domain_insert] THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "domain" (rand c)) gl in
             MP_TAC su) THEN
           SET_TAC[])) THEN
    (* the timestamps of the new references and stack are more than
       the ones of the old (all_ts_insert_SUBSET) *)
    TRY (SOLVED
          (MATCH_MP_TAC SUBSET_TRANS THEN
           W(fun gl ->
             let su = the_asm (fun c -> hd_is "SUBSET" c &&
                        hd_is "all_ts" (rand c)) gl in
             let nd = the_asm (fun c -> is_neg c &&
                        hd_is "IN" (rand c) &&
                        hd_is "domain" (rand (rand c))) gl in
             EXISTS_TAC (rand (concl su)) THEN
             CONJ_TAC THENL
              [ACCEPT_TAC su;
               MATCH_MP_TAC all_ts_insert_SUBSET THEN
               CONJ_TAC THENL
                [ACCEPT_TAC nd;
                 REWRITE_TAC[MEM] THEN MESON_TAC[]]]))) THEN
    (* and the blocks of the stack stay unique *)
    TRY (SOLVED
          (W(fun gl ->
             let bu = the_asm (hd_is "blocks_unique") gl in
             MATCH_ACCEPT_TAC (MATCH_MP blocks_unique_new_byte_alt
               bu)))) THEN
    (* the transfer that the allocation leaves: what the invariant
       said of a value it says of it with the array written
       (v_inv_new_byte_step) *)
    W(fun (asl,w as gl) ->
      let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                 hd_is "domain" (rand (rand c))) gl in
      let su = the_asm (fun c -> hd_is "SUBSET" c &&
                 hd_is "domain" (rand c)) gl in
      let hsr = the_asm (hd_is "heap_store_rel") gl in
      let old = the_asm (hd_is "ALL2") gl in
      let pred = el 0 (snd (strip_comb (concl old))) in
      let v,b1 = dest_abs pred in
      let x,vtm = dest_abs b1 in
      let f2 = find_term (hd_is "|+") w in
      let refs2 = find_term (hd_is "sptree_insert") w in
      ASSUME_TAC (GENL [v; x] (DISCH vtm
        (MATCH_MP v_inv_new_byte_step
          (CONJ (ASSUME vtm) (CONJ nd (CONJ su (CONJ hsr
            (CONJ (REFL f2) (REFL refs2)))))))))) THEN
    (* the values of the stack with the pointer of the array on
       it *)
    W(fun (asl,w) ->
      if not (hd_is "ALL2" w) then ALL_TAC else
      (REWRITE_TAC[ALL2] THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       CONJ_TAC THENL
        [REWRITE_TAC[v_inv_def] THEN DISJ1_TAC THEN
         REWRITE_TAC[FDOM_FUPDATE; IN_INSERT; lookup_insert;
                     FAPPLY_FUPDATE_THM; ref_ptr_annot_def] THEN
         REPEAT CONJ_TAC THEN
         TRY MATCH_REDUCE_TAC THEN
         (let ds = [distinctness "option";
                    distinctness "bvlSem_ref"] in
          REWRITE_TAC (injectivity "option" ::
                       injectivity "heap_address" ::
                       ds @ map GSYM ds)) THEN
         REWRITE_TAC[];
         W(fun gl ->
           let old = the_asm (hd_is "ALL2") gl in
           MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc_stack
             (CONJ (a_vtr gl) old)))])) THEN
    (* and the invariant of every reference that the new stack
       reaches: the array itself, or one that the old stack
       reached *)
    REPEAT STRIP_TAC THEN
    W(fun (asl,w) ->
      let ins = find_term (hd_is "sptree_insert") w in
      let ptr = el 0 (snd (strip_comb ins)) in
      let n = el 1 (snd (strip_comb w)) in
      ASM_CASES_TAC (mk_eq (n, ptr))) THENL
     [(* the array itself: its key has the address the store wrote
          at, and the element is the one it wrote *)
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      W(fun (asl,w as gl) ->
        let st = the_asm (fun c -> is_eq c &&
                   hd_is "heap_store_unused_alt" (lhand c)) gl in
        let aa = el 0 (snd (strip_comb (lhand (concl st)))) in
        let fm = el 0 (tparts (el 3 (snd (strip_comb w)))) in
        let ptr = el 1 (snd (strip_comb w)) in
        let ins = el 2 (snd (strip_comb w)) in
        SUBGOAL_THEN (mk_eq (list_mk_icomb "FLOOKUP" [fm; ptr],
                             list_mk_icomb "SOME" [aa]))
          ASSUME_TAC THENL
         [REWRITE_TAC[FLOOKUP_UPDATE]; ALL_TAC] THEN
        SUBGOAL_THEN
          (mk_eq (list_mk_icomb "sptree_lookup" [ptr; ins],
                  list_mk_icomb "SOME"
                    [el 1 (snd (strip_comb ins))])) ASSUME_TAC THENL
         [REWRITE_TAC[lookup_insert]; ALL_TAC]) THEN
      W(fun gl ->
        let lk1 = the_asm (fun c -> is_eq c &&
                    hd_is "FLOOKUP" (lhand c)) gl in
        let lk2 = the_asm (fun c -> is_eq c &&
                    hd_is "sptree_lookup" (lhand c) &&
                    hd_is "sptree_insert" (rand (lhand c))) gl in
        REWRITE_TAC[MATCH_MP arm_BA (CONJ lk1 lk2)]) THEN
      CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
      W(fun gl ->
        let ab = the_asm (hd_is "Abbrev") gl in
        REWRITE_TAC[GSYM (REWRITE_RULE[abbrev_def] ab)]) THEN
      FIRST_ASSUM ACCEPT_TAC;
      (* and a reference that the old stack reached: it is in the
         domain of the map that the key was not in *)
      W(fun (asl,w as gl) ->
        let rr = the_asm (hd_is "reachable_refs") gl in
        let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                   hd_is "domain" (rand (rand c))) gl in
        let neq = the_asm (fun c -> is_neg c && is_eq (rand c)) gl in
        ASSUME_TAC (REWRITE_RULE[EQF_INTRO neq]
          (MATCH_MP reachable_refs_new_byte (CONJ rr nd)))) THEN
      W(fun (asl,w as gl) ->
        let n = el 1 (snd (strip_comb w)) in
        let innu = the_asm (fun c -> hd_is "IN" c &&
                     hd_is "FDOM" (rand c) &&
                     el 0 (snd (strip_comb c)) = n) gl in
        let fm = lhand (rand (rand (concl innu))) in
        SUBGOAL_THEN (list_mk_icomb "IN"
                        [n; list_mk_icomb "FDOM" [fm]])
          ASSUME_TAC THENL
         [MP_TAC innu THEN
          REWRITE_TAC[FDOM_FUPDATE; IN_INSERT] THEN
          ASM_MESON_TAC[];
          ALL_TAC]) THEN
      W(fun (asl,w as gl) ->
        let n = el 1 (snd (strip_comb w)) in
        let bri = the_asm (fun c ->
          let vs,bd = strip_forall c in
          length vs = 1 && is_imp bd &&
          hd_is "bc_ref_inv" (rand bd)) gl in
        let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
          not (can (find_term (hd_is "sptree_insert")) c)) gl in
        let inn = the_asm (fun c -> hd_is "IN" c &&
          hd_is "FDOM" (rand c) &&
          el 0 (snd (strip_comb c)) = n &&
          not (can (find_term (hd_is "|+")) c)) gl in
        let inv = MP (SPEC n bri) (CONJ rr inn) in
        let hsr = the_asm (hd_is "heap_store_rel") gl in
        let stp = REWRITE_RULE[IMP_CONJ] bc_ref_inv_step in
        let th = MATCH_MP (MATCH_MP (MATCH_MP (MATCH_MP stp
                   (a_vtr gl)) inn) hsr) inv in
        MATCH_MP_TAC (REWRITE_RULE[IMP_IMP] th)) THEN
      REPEAT CONJ_TAC THEN
      (* the lookup of the references away from the key *)
      TRY (SOLVED (ASM_REWRITE_TAC[lookup_insert])) THEN
      (* the lookup of the map away from the key *)
      TRY (SOLVED (ASM_REWRITE_TAC[FLOOKUP_UPDATE])) THEN
      (* the timestamps did not change *)
      TRY (SOLVED (MESON_TAC[])) THEN
      (* and a thunk of the old references is one of the new *)
      W(fun gl ->
        let nd = the_asm (fun c -> is_neg c && hd_is "IN" (rand c) &&
                   hd_is "domain" (rand (rand c))) gl in
        GEN_TAC THEN DISCH_THEN (fun dt ->
          MATCH_ACCEPT_TAC (MATCH_MP dest_thunk_insert_fresh
            (CONJ nd dt))))]));;

(* equality *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let ref_eq_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (RefPtr T p1 :: RefPtr T p2 :: stack) refs
        (r1 :: r2 :: roots,heap,be,a,sp,sp1,gens) limit ts ==>
      ((p1 = p2) <=> (r1 = r2)) /\
      (?p1 p2. r1 = gc_shared_Pointer p1 (wordLang_Word (n2w 0))
        /\ r2 = gc_shared_Pointer p2 (wordLang_Word (n2w 0)))`),
  (REWRITE_TAC[abs_ml_inv_def;
               bc_stack_ref_inv_def] THEN
   STRIP_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[ALL2; v_inv_RefPtr_T; INJ]) THEN
   ASM_MESON_TAC[injectivity "heap_address"]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let num_eq_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (Number i1 :: Number i2 :: stack) refs
       (r1 :: r2 :: roots,heap,be,a,sp,sp1,gens) limit ts /\
     small_int (:'a) i1 /\
     small_int (:'a) i2 ==>
     ((i1 = i2) <=> (r1 = r2)) /\
     r1 = gc_shared_Data (wordLang_Word (Smallnum i1:'a word)) /\
     r2 = gc_shared_Data (wordLang_Word (Smallnum i2))`),
  (* the roots of two small integers are the words of four times
     them, and such a word determines the integer because four
     times a small one is within the range of the word: an eighth
     part of the dimword times four is half of it *)
  ((* Smallnum as an i2w, which the file proves a few theorems
      later (smallnum_i2w of the source): a section may only name
      what stands before it, so the proof stands here as well *)
   let as_i2w = prove
    (`Smallnum i = i2w ((&4) * i)`,
     REWRITE_TAC[smallnum_def] THEN COND_CASES_TAC THENL
      [REWRITE_TAC[WORD_SUB_LZERO] THEN
       ONCE_REWRITE_TAC[WORD_IWORD] THEN
       REWRITE_TAC[GSYM IWORD_INT_NEG] THEN AP_TERM_TAC THEN
       SUBGOAL_THEN `&0 <= &4 * ((&0) - (i:int))` (fun th ->
         REWRITE_TAC[MATCH_MP INT_OF_NUM_OF_INT th]) THENL
        [ASM_INT_ARITH_TAC; INT_ARITH_TAC];
       ONCE_REWRITE_TAC[WORD_IWORD] THEN AP_TERM_TAC THEN
       MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC]) in
   (* four times a small integer is within the range of the word *)
   let bnds = prove
    (`small_int (:'a) i ==>
       --(&2 pow (dimindex (:'a) - 1)) <= (&4) * i /\
       (&4) * i < &2 pow (dimindex (:'a) - 1)`,
     let exp1 = prove
      (`!d. 1 <= d ==> 2 EXP d = 2 * 2 EXP (d - 1)`,
       INDUCT_TAC THEN
       REWRITE_TAC[ARITH_RULE `~(1 <= 0)`; SUC_SUB1; EXP]) in
     let key = prove
      (`4 * (2 EXP (dimindex (:'a)) DIV 8)
        <= 2 EXP (dimindex (:'a) - 1)`,
       MP_TAC(SPECL [`2 EXP (dimindex (:'a))`; `8`] DIVISION) THEN
       REWRITE_TAC[ARITH_EQ] THEN
       MP_TAC(MATCH_MP exp1 (ISPEC `(:'a)` DIMINDEX_GE_1)) THEN
       ARITH_TAC) in
     REWRITE_TAC[small_int_def; dimword] THEN
     MP_TAC key THEN
     REWRITE_TAC[GSYM INT_OF_NUM_POW; GSYM INT_OF_NUM_LE;
                 GSYM INT_OF_NUM_MUL] THEN
     INT_ARITH_TAC) in
   (* so the word of a small integer determines it *)
   let num_eq = prove
    (`small_int (:'a) i1 /\ small_int (:'a) i2 ==>
       ((i1 = i2) <=> (Smallnum i1 = (Smallnum i2:'a word)))`,
     STRIP_TAC THEN
     REWRITE_TAC[as_i2w; GSYM IVAL_EQ] THEN
     ASSUM_LIST(fun ths ->
       REWRITE_TAC(mapfilter
         (fun a -> MATCH_MP IVAL_IWORD (MATCH_MP bnds a)) ths)) THEN
     INT_ARITH_TAC) in
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   STRIP_TAC THEN
   RULE_ASSUM_TRY(REWRITE_RULE[ALL2; v_inv_def]) THEN
   (* the two roots are the words of the integers *)
   FIRST_ASSUM(fun c ->
     if not (is_conj (concl c)) then fail() else
     FIRST_ASSUM(fun s1 -> FIRST_ASSUM(fun s2 ->
       if concl s1 = concl s2 then fail() else
       STRIP_ASSUME_TAC(REWRITE_RULE[s1; s2] c)))) THEN
   ASM_REWRITE_TAC[injectivity "heap_address";
                   injectivity "word_loc"] THEN
   FIRST_ASSUM(fun s1 -> FIRST_ASSUM(fun s2 ->
     if concl s1 = concl s2 then fail() else
     ACCEPT_TAC(MATCH_MP num_eq (CONJ s1 s2))))));;

(* Smallnum_i2w *)
let smallnum_i2w = prove
 (`Smallnum i = i2w ((&4) * i)`,
  (* Smallnum writes the two cases of i2w out: a negative integer
     is the negation of the word of its absolute value, and & of
     the number of a non-negative integer is the integer itself *)
  (REWRITE_TAC[smallnum_def] THEN COND_CASES_TAC THENL
    [REWRITE_TAC[WORD_SUB_LZERO] THEN
     ONCE_REWRITE_TAC[WORD_IWORD] THEN
     REWRITE_TAC[GSYM IWORD_INT_NEG] THEN AP_TERM_TAC THEN
     SUBGOAL_THEN `&0 <= &4 * ((&0) - (i:int))` (fun th ->
       REWRITE_TAC[MATCH_MP INT_OF_NUM_OF_INT th]) THENL
      [ASM_INT_ARITH_TAC; INT_ARITH_TAC];
     ONCE_REWRITE_TAC[WORD_IWORD] THEN AP_TERM_TAC THEN
     MATCH_MP_TAC INT_OF_NUM_OF_INT THEN ASM_INT_ARITH_TAC]));;

let small_int_IMP_MIN_MAX = prove
 (`good_dimindex (:'a) /\ small_int (:'a) i ==>
    INT_MIN (:'a) <= (&4) * i /\ (&4) * i <= INT_MAX (:'a)`,
  (* the bound of a small integer is a quarter of the dimword and
     INT_MIN and INT_MAX are a half of it, so four times a small
     integer is between them *)
  (REWRITE_TAC[good_dimindex_def; small_int_def;
               dimword; integer_word_INT_MIN; integer_word_INT_MAX;
               INT_MIN] THEN
   STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
   RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
   CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC));;

let num_less_thm = prove
 (`good_dimindex (:'a) /\ small_int (:'a) i1 /\ small_int (:'a) i2 ==>
    ((i1 < i2) <=> (Smallnum i1 < (Smallnum i2:'a word)))`,
  (* the words are the i2w of four times the integers, whose
     ival is the integer itself because a small integer times
     four is between INT_MIN and INT_MAX *)
  (let bnds = prove
    (`good_dimindex (:'a) /\ small_int (:'a) i ==>
       --(&2 pow (dimindex (:'a) - 1)) <= (&4) * i /\
       (&4) * i < &2 pow (dimindex (:'a) - 1)`,
     REWRITE_TAC[good_dimindex_def; small_int_def;
                 dimword] THEN
     STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
     RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
     CONV_TAC NUM_REDUCE_CONV THEN
     CONV_TAC(ONCE_DEPTH_CONV INT_POW_CONV) THEN
     ASM_INT_ARITH_TAC) in
   STRIP_TAC THEN
   REWRITE_TAC[smallnum_i2w; word_ilt; irelational2] THEN
   CONV_TAC(DEPTH_CONV BETA_CONV) THEN
   ASSUM_LIST(fun ths ->
     REWRITE_TAC(mapfilter (fun (a,b) ->
       MATCH_MP IVAL_IWORD (MATCH_MP bnds (CONJ a b)))
       (allpairs (fun a b -> (a,b)) ths ths))) THEN
   INT_ARITH_TAC));;

(* permute stack *)

let all_ts_permute = prove
 (`!(refs:(dataSem_v bvlSem_ref) spt) stack' stack'.
     PERM stack' stack' ==> all_ts refs stack' = all_ts refs stack'`,
  (* the two variables of HOL4's statement, `stack` and `stack'`,
     became one name in the port, so what it states here is that
     the timestamps of a list are the timestamps of that same list
     (see ISSUES.md, "A statement whose two variables became one
     name"): nothing uses it, in the port or in HOL4, and the
     statement is what has to be put right, not the proof *)
  (REWRITE_TAC[]));;

let reachable_refs_stack_subset = prove
 (`!x y refs n. reachable_refs y refs n /\ set_of_list y SUBSET
  set_of_list x ==> reachable_refs x refs n`,
  (* the roots of the one stack are roots of the other, and
     reachable_refs asks for nothing else of them *)
  (REWRITE_TAC[reachable_refs_def] THEN
   REPEAT GEN_TAC THEN REWRITE_TAC[SUBSET; IN_SET_OF_LIST] THEN
   STRIP_TAC THEN ASM_MESON_TAC[]));;

let MEM_v_all_vs_FST = prove
 (`!xs h0 h1 x.
   MEM (h0,h1) xs /\
   MEM x (v_all_vs [h0]) ==>
     MEM x (v_all_vs (MAP FST xs))`,
  (* the head of the list is the pair that holds the value, or the
     value is one of the tail *)
  (LIST_INDUCT_TAC THEN REWRITE_TAC[MAP; MEM] THEN
   REPEAT GEN_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC ASSUME_TAC) THENL
    [FIRST_X_ASSUM(SUBST_ALL_TAC o SYM) THEN
     REWRITE_TAC[FST] THEN
     MATCH_MP_TAC MEM_v_all_vs_extend_tl THEN
     FIRST_ASSUM ACCEPT_TAC;
     MATCH_MP_TAC MEM_v_all_vs_extend_hd THEN
     FIRST_ASSUM(fun ih -> FIRST_ASSUM(fun a1 ->
       FIRST_ASSUM(fun a2 ->
         ACCEPT_TAC(MATCH_MP ih (CONJ a1 a2)))))]));;

let MEM_v_all_vs_SUBSET = prove
 (`!ys xs x.
     set_of_list ys SUBSET set_of_list xs /\
     MEM x (v_all_vs (MAP FST ys)) ==>
       MEM x (v_all_vs (MAP FST xs))`,
  (* the head of ys is a pair of xs, so its value is one of the
     values of xs; the tail is the induction hypothesis *)
  (let vnil = prove
    (`v_all_vs ([]:dataSem_v list) = []`,
     GEN_REWRITE_TAC LAND_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   let pairit = CONV_RULE(ONCE_DEPTH_CONV(REWR_CONV(GSYM PAIR))) in
   LIST_INDUCT_TAC THEN REWRITE_TAC[MAP] THENL
    [REWRITE_TAC[vnil; MEM];
     REPEAT GEN_TAC THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (ASSUME_TAC o REWRITE_RULE[SUBSET; IN_SET_OF_LIST; MEM])
       (fun th -> MP_TAC(MATCH_MP MEM_v_all_vs_split th))) THEN
     STRIP_TAC THENL
      [FIRST_X_ASSUM(fun sub ->
         let v,bod = dest_forall(concl sub) in
         let dis = lhand bod in
         let p = rand(lhand dis) in
         ASSUME_TAC(MP (SPEC p sub)
           (DISJ1 (REFL p) (vsubst [p,v] (rand dis))))) THEN
       FIRST_ASSUM(fun m1 -> FIRST_ASSUM(fun m2 ->
         ACCEPT_TAC(MATCH_MP MEM_v_all_vs_FST
           (CONJ (pairit m1) m2))));
       FIRST_X_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
        [REWRITE_TAC[SUBSET; IN_SET_OF_LIST] THEN
         GEN_TAC THEN DISCH_TAC THEN
         FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
         FIRST_ASSUM ACCEPT_TAC]]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_stack_permute = prove
 (cake_as_vars (fun () ->
    `set_of_list ys SUBSET set_of_list xs /\
     blocks_unique ts (all_vs refs (MAP FST xs ++ stack)) ==>
       blocks_unique ts (all_vs refs (MAP FST ys ++ stack))`),
  (* and a sublist of the pairs has a sublist of the values *)
  (let inc = prove
    (`!refs (ys:(dataSem_v#A)list) xs stack' t a q.
        set_of_list ys SUBSET set_of_list xs /\
        Block t a q IN all_vs refs (APPEND (MAP FST ys) stack') ==>
        Block t a q IN all_vs refs (APPEND (MAP FST xs) stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM;
                 v_all_vs_append; MEM_APPEND] THEN
     MESON_TAC[MEM_v_all_vs_SUBSET]) in
   REWRITE_TAC[blocks_unique_def] THEN STRIP_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the port's own: what the proof of abs_ml_inv_stack_permute
   needs.  The stack changes and the references and the heap do
   not, so every transfer of the generic machinery above
   update_ref_thm is the identity here and what is left is the
   timestamps: they are cut to the ones of the new stack, which is
   what v_inv_restrict_gen, EVERY2_v_inv_restrict (the values of a
   stack), EVERY2_v_inv_restrict_gen (the values of the arm of a
   reference, the other way round -- entry 53) and
   bc_ref_inv_restrict say.  The pairs of the new stack are pairs
   of the old one, which is what the four after them say of the
   roots, of a map and of the relation between the values and the
   roots *)

(* what the invariant says of a value, of the values of a stack and
   of the values of the arm of a reference, with the timestamps cut
   to the ones of a stack: the references and the heap are the ones
   they were, so the transfer of each generic lemma is the identity *)
let v_inv_restrict_gen = prove
 (cake_as_vars (fun () ->
    `v_inv conf v1 refs (v2,f,tf,heap) /\
     v1 IN all_vs refs stack'
     ==> v_inv conf v1 refs
           (v2,f,DRESTRICT tf (all_ts refs stack'),heap)`),
  STRIP_TAC THEN
  MATCH_MP_TAC v_inv_update_gen THEN
  REPEAT CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  REPEAT STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

let EVERY2_v_inv_restrict = prove
 (cake_as_vars (fun () ->
    `(!v. MEM v vs ==> v IN all_vs refs stack') /\
     EVERY2 (\v x. v_inv conf v refs (x,f,tf,heap)) vs rs
     ==> EVERY2 (\v x. v_inv conf v refs
           (x,f,DRESTRICT tf (all_ts refs stack'),heap)) vs rs`),
  STRIP_TAC THEN
  MATCH_MP_TAC EVERY2_v_inv_update_stack THEN
  REPEAT CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  REPEAT STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

let EVERY2_v_inv_restrict_gen = prove
 (cake_as_vars (fun () ->
    `(!v. MEM v ys ==> v IN all_vs refs stack') /\
     EVERY2 (\z y. v_inv conf y refs (z,f,tf,heap)) zs ys
     ==> EVERY2 (\z y. v_inv conf y refs
           (z,f,DRESTRICT tf (all_ts refs stack'),heap)) zs ys`),
  STRIP_TAC THEN
  MATCH_MP_TAC EVERY2_v_inv_update_gen THEN
  REPEAT CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  REPEAT STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* the values of the arm of a reference are values of the stack,
   whichever arm it is: the lemma that says so is the argument *)
let EVERY2_ARM_RESTRICT_TAC memlem =
  W(fun (asl,w as gl) ->
    let ats = find_term (hd_is "all_ts") w in
    let refs2 = lhand ats in
    let ys = el 2 (snd (strip_comb w)) in
    let v = genvar (hd (snd (dest_type (type_of (rand ats))))) in
    SUBGOAL_THEN
      (mk_forall(v, mk_imp(list_mk_icomb "MEM" [v; ys],
         list_mk_icomb "IN"
           [v; list_mk_icomb "all_vs" [refs2; rand ats]])))
      (fun mem ->
         let old = the_asm (hd_is "ALL2") gl in
         MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_restrict_gen
           (CONJ mem old))) THEN
    REPEAT STRIP_TAC THEN
    W(fun gl ->
      let mm = the_asm (hd_is "MEM") gl in
      MATCH_ACCEPT_TAC (MATCH_MP memlem
        (CONJ (a_lkref refs2 gl) mm))));;

(* and so the invariant of a reference with the timestamps cut *)
let bc_ref_inv_restrict = prove
 (cake_as_vars (fun () ->
    `bc_ref_inv conf n refs ((f:(num,num)fmap),tf,heap,be')
     ==> bc_ref_inv conf n refs
           (f,DRESTRICT tf (all_ts refs stack'),heap,be')`),
  STRIP_TAC THEN
  (* the key has an address *)
  FIRST_ASSUM (fun inv ->
    if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
    CHOOSE_THEN ASSUME_TAC (MATCH_MP bc_ref_inv_FLOOKUP inv)) THEN
  (* and the kind of what the key holds says which arm it is *)
  W(fun gl ->
    let inv = the_asm (hd_is "bc_ref_inv") gl in
    let args = snd (strip_comb (concl inv)) in
    NAMED_CASES_TAC (list_mk_icomb "sptree_lookup"
                       [el 1 args; el 2 args]) [[]; ["rv"]]) THEN
  TRY (SOLVED (FIRST_X_ASSUM (fun inv ->
    if not (hd_is "bc_ref_inv" (concl inv)) then fail() else
    MP_TAC (REWRITE_RULE[bc_ref_inv_def] inv)) THEN
    ASM_REWRITE_TAC[] THEN REDUCE_MATCH_HARD)) THEN
  NAMED_CASES_TAC (cake_as_vars (fun () ->
    `rv:(dataSem_v)bvlSem_ref`))
    [["l"]; ["flag"; "bs"]; ["ev"; "vv"];
     ["tg"; "fin"; "ll"; "cc"; "rr"]] THEN
  USE_ARMS THEN
  SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  SPLIT_ASM_TAC THEN
  (* the array of values: the element is where it was and its
     values are values of the stack *)
  TRY (SOLVED
        (W(fun gl ->
           let hl = the_asm (fun c -> is_eq c &&
                      hd_is "heap_lookup" (lhand c) &&
                      hd_is "SOME" (rand c)) gl in
           EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
           CONJ_TAC THENL
            [ACCEPT_TAC hl;
             EVERY2_ARM_RESTRICT_TAC MEM_ref_all_vs]))) THEN
  (* the array of bytes: only the element *)
  TRY (SOLVED
        (CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
         RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
         FIRST_ASSUM ACCEPT_TAC)) THEN
  (* the thunk: the element, that it is still not a thunk, and its
     value *)
  TRY (SOLVED
        (W(fun gl ->
           let hl = the_asm (fun c -> is_eq c &&
                      hd_is "heap_lookup" (lhand c) &&
                      hd_is "SOME" (rand c)) gl in
           EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
           REPEAT CONJ_TAC THEN
           TRY (SOLVED (ACCEPT_TAC hl)) THEN
           TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
           W(fun (asl,w as gl) ->
             let vi = the_asm (hd_is "v_inv") gl in
             let refs2 = lhand (find_term (hd_is "all_ts") w) in
             let inn = MATCH_MP MEM_thunk_all_vs
                         (a_lkref refs2 gl) in
             MATCH_ACCEPT_TAC (MATCH_MP v_inv_restrict_gen
               (CONJ vi inn)))))) THEN
  (* the mutable block: the kind of the collection, the address
     that no timestamp has, the element and its values *)
  TRY (SOLVED
        (REPEAT CONJ_TAC THEN
         TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
         TRY (SOLVED
               (W(fun gl ->
                  let impl = the_asm (fun c -> is_imp c &&
                               is_neg (lhand c) &&
                               is_neg (rand c)) gl in
                  DISCH_THEN (fun nf -> MATCH_ACCEPT_TAC
                    (MATCH_MP IMAGE_DRESTRICT_NOT (MP impl nf)))))) THEN
         W(fun gl ->
           let hl = the_asm (fun c -> is_eq c &&
                      hd_is "heap_lookup" (lhand c) &&
                      hd_is "SOME" (rand c)) gl in
           EXISTS_TAC (rand (rand (rand (concl hl)))) THEN
           CONJ_TAC THENL
            [ACCEPT_TAC hl;
             EVERY2_ARM_RESTRICT_TAC MEM_mutblock_all_vs]))));;

(* the roots of a stack that the other stack has are good when the
   other's are *)
let roots_ok_subset = prove
 (`(!x. MEM x rs2 ==> MEM x rs1) /\ roots_ok rs1 heap
   ==> roots_ok rs2 heap`,
  REWRITE_TAC[roots_ok_def] THEN MESON_TAC[]);;

(* and what one list of pairs has of the other, after a map *)
let MEM_MAP_subset = prove
 (`!(g:A->B) ys xs l.
     (!p. MEM p ys ==> MEM p xs)
     ==> !x. MEM x (MAP g ys ++ l) ==> MEM x (MAP g xs ++ l)`,
  REWRITE_TAC[MEM_APPEND; MEM_MAP] THEN MESON_TAC[]);;

(* a relation between the values and the roots of a list of pairs
   holds of every list of its pairs *)
let EVERY2_FST_SND_subset = prove
 (`!(P:A->B->bool) ys xs.
     (!p. MEM p ys ==> MEM p xs) /\
     EVERY2 P (MAP FST xs) (MAP SND xs)
     ==> EVERY2 P (MAP FST ys) (MAP SND ys)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[EVERY2_MAP_FST_SND; GSYM ALL_MEM] THEN
  MESON_TAC[]);;

(* so the values of a stack that the other stack has are related to
   their roots when the other's are *)
let EVERY2_stack_permute = prove
 (cake_as_vars (fun () ->
    `(!p. MEM p ys ==> MEM p xs) /\
     EVERY2 P (MAP FST xs ++ stack) (MAP SND xs ++ roots)
     ==> EVERY2 P (MAP FST ys ++ stack) (MAP SND ys ++ roots)`),
  STRIP_TAC THEN
  W(fun gl ->
    let old = the_asm (hd_is "ALL2") gl in
    let args = snd (strip_comb (concl old)) in
    let l1 = lhand (el 1 args) in
    let l2 = lhand (el 2 args) in
    let leq = prove(mk_eq (list_mk_icomb "LENGTH" [l1],
                           list_mk_icomb "LENGTH" [l2]),
                    REWRITE_TAC[LENGTH_MAP]) in
    STRIP_ASSUME_TAC (MATCH_MP LIST_REL_APPEND_IMP
      (CONJ old leq))) THEN
  MATCH_MP_TAC LIST_REL_APPEND_I THEN
  CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  W(fun gl ->
    let sub = the_asm (fun c ->
                length (fst (strip_forall c)) = 1 &&
                is_imp (snd (strip_forall c)) &&
                hd_is "MEM" (lhand (snd (strip_forall c)))) gl in
    let e2 = the_asm (fun c -> hd_is "ALL2" c &&
               hd_is "MAP" (el 1 (snd (strip_comb c)))) gl in
    MATCH_ACCEPT_TAC (MATCH_MP EVERY2_FST_SND_subset
      (CONJ sub e2))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let abs_ml_inv_stack_permute = prove
 (cake_as_vars (fun () ->
    `!xs ys.
         abs_ml_inv conf (MAP FST xs ++ stack) refs
           (MAP SND xs ++ roots,heap,be,a,sp,sp1,gens) limit ts /\
         set_of_list ys SUBSET set_of_list xs ==>
         abs_ml_inv conf (MAP FST ys ++ stack) refs
           (MAP SND ys ++ roots,heap,be,a,sp,sp1,gens) limit ts`),
  (* the steps are above the statement (tools/overrides.py).  The
     heap and the references are the ones they were, so the heap,
     the unused space and the kind of the collection say what they
     said; the roots of the new stack are among the old ones
     (roots_ok_subset), its pairs are pairs of the old stack
     (EVERY2_stack_permute, blocks_unique_stack_permute) and what
     it reaches the old stack reached
     (reachable_refs_stack_subset); and the timestamps are cut to
     the ones of the new stack, which the invariant of a value and
     of a reference survive (EVERY2_v_inv_restrict,
     bc_ref_inv_restrict) *)
  (REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* the pairs of the new stack are pairs of the old *)
    W(fun gl ->
      let sub = the_asm (hd_is "SUBSET") gl in
      ASSUME_TAC (REWRITE_RULE[SUBSET; IN_SET_OF_LIST] sub)) THEN
    (* and what the invariant says of the old stack *)
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "abs_ml_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
                                     bc_stack_ref_inv_def] inv)) THEN
    REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the roots are good, because they are among the old ones *)
    TRY (SOLVED
          (W(fun (asl,w as gl) ->
             let ro = the_asm (hd_is "roots_ok") gl in
             let sub = the_asm (fun c ->
                         length (fst (strip_forall c)) = 1 &&
                         is_imp (snd (strip_forall c)) &&
                         hd_is "MEM"
                           (lhand (snd (strip_forall c)))) gl in
             let xs = el 1 (snd (strip_comb
                        (rand (snd (strip_forall (concl sub)))))) in
             let rs2 = el 0 (snd (strip_comb w)) in
             let margs = snd (strip_comb (lhand rs2)) in
             let mem = MP (ISPECL [el 0 margs; el 1 margs; xs;
                                   rand rs2] MEM_MAP_subset) sub in
             ACCEPT_TAC (MATCH_MP roots_ok_subset (CONJ mem ro))))) THEN
    (* the maps: the addresses are the ones they were and the
       timestamps are cut to the ones of the new stack *)
    W(fun (asl,w as gl) ->
      if not (is_exists w) then ALL_TAC else
      (let sub p = rand (lhand (concl (the_asm (fun c ->
         hd_is "SUBSET" c && hd_is p (rand c)) gl))) in
       let ats = find_term (hd_is "all_ts") w in
       EXISTS_TAC (sub "domain") THEN
       EXISTS_TAC (list_mk_icomb "DRESTRICT" [sub "all_ts"; ats]))) THEN
    REPEAT CONJ_TAC THEN TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    (* the addresses of the restricted map are the ones it had *)
    TRY (SOLVED
          (W(fun (asl,w as gl) ->
             let dr = find_term (hd_is "DRESTRICT") w in
             let inj = the_asm (fun c -> hd_is "INJ" c &&
               rand (el 0 (snd (strip_comb c))) = lhand dr) gl in
             MATCH_ACCEPT_TAC (MATCH_MP INJ_DRESTRICT inj)))) THEN
    (* the timestamps of the restricted map are of the new stack, and
       below the counter *)
    TRY (SOLVED
          (REWRITE_TAC[(CONJUNCT1 o SPEC_ALL) DRESTRICT_DEF] THEN
           FIRST [SOLVED (REWRITE_TAC[INTER_SUBSET]);
                  SOLVED (MATCH_MP_TAC SUBSET_TRANS THEN
                          W(fun gl ->
                            let su = the_asm (fun c ->
                              hd_is "SUBSET" c &&
                              hd_is "FDOM" (lhand c)) gl in
                            EXISTS_TAC (lhand (concl su))) THEN
                          CONJ_TAC THEN
                          TRY (FIRST_ASSUM ACCEPT_TAC) THEN
                          REWRITE_TAC[INTER_SUBSET])])) THEN
    (* the blocks of the stack stay unique *)
    TRY (SOLVED
          (W(fun gl ->
             let bu = the_asm (hd_is "blocks_unique") gl in
             let sub = the_asm (fun c -> hd_is "SUBSET" c &&
                         hd_is "set_of_list" (lhand c)) gl in
             MATCH_ACCEPT_TAC (MATCH_MP blocks_unique_stack_permute
               (CONJ sub bu))))) THEN
    (* the values of the new stack are related to their roots, with
       the timestamps cut *)
    W(fun (asl,w as gl) ->
      if not (hd_is "ALL2" w) then ALL_TAC else
      (let ats = find_term (hd_is "all_ts") w in
       let vs = el 1 (snd (strip_comb w)) in
       let old = the_asm (fun c -> hd_is "ALL2" c) gl in
       let sub = the_asm (fun c ->
                   length (fst (strip_forall c)) = 1 &&
                   is_imp (snd (strip_forall c)) &&
                   hd_is "MEM" (lhand (snd (strip_forall c)))) gl in
       let perm = MATCH_MP EVERY2_stack_permute (CONJ sub old) in
       let v = genvar (hd (snd (dest_type (type_of vs)))) in
       SUBGOAL_THEN
         (mk_forall(v, mk_imp(list_mk_icomb "MEM" [v; vs],
            list_mk_icomb "IN"
              [v; list_mk_icomb "all_vs" [lhand ats; rand ats]])))
         (fun mem -> ACCEPT_TAC (MATCH_MP EVERY2_v_inv_restrict
            (CONJ mem perm))) THEN
       REPEAT STRIP_TAC THEN
       W(fun gl ->
         let mm = the_asm (hd_is "MEM") gl in
         let v1 = el 0 (snd (strip_comb (concl mm))) in
         MATCH_ACCEPT_TAC (MP (SPECL [v1; rand ats; lhand ats]
                                 MEM_stack_all_vs) mm)))) THEN
    (* and the invariant of each reference that the new stack
       reaches: the old stack reached it as well *)
    W(fun (asl,w) -> if not (is_forall w) then ALL_TAC else
      (REPEAT STRIP_TAC THEN
       W(fun (asl,w as gl) ->
         let rr = the_asm (hd_is "reachable_refs") gl in
         let sub = the_asm (fun c ->
                     length (fst (strip_forall c)) = 1 &&
                     is_imp (snd (strip_forall c)) &&
                     hd_is "MEM" (lhand (snd (strip_forall c)))) gl in
         let xs = el 1 (snd (strip_comb
                    (rand (snd (strip_forall (concl sub)))))) in
         let st = el 0 (snd (strip_comb (concl rr))) in
         let margs = snd (strip_comb (lhand st)) in
         let mem = MP (ISPECL [el 0 margs; el 1 margs; xs; rand st]
                         MEM_MAP_subset) sub in
         let old = list_mk_icomb "APPEND"
                     [list_mk_icomb "MAP" [el 0 margs; xs];
                      rand st] in
         SUBGOAL_THEN (list_mk_icomb "SUBSET"
                         [list_mk_icomb "set_of_list" [st];
                          list_mk_icomb "set_of_list" [old]])
           (fun ss -> ASSUME_TAC (MATCH_MP reachable_refs_stack_subset
              (CONJ rr ss))) THENL
          [REWRITE_TAC[SUBSET; IN_SET_OF_LIST] THEN ACCEPT_TAC mem;
           ALL_TAC]) THEN
       W(fun (asl,w as gl) ->
         let n = el 1 (snd (strip_comb w)) in
         let bri = the_asm (fun c ->
           let vs,bd = strip_forall c in
           length vs = 1 && is_imp bd &&
           hd_is "bc_ref_inv" (rand bd)) gl in
         let rr = the_asm (fun c -> hd_is "reachable_refs" c &&
           can (find_term (fun t -> is_var t &&
                  fst (dest_var t) = "xs")) c) gl in
         let nin = the_asm (fun c -> hd_is "IN" c &&
           hd_is "FDOM" (rand c) &&
           el 0 (snd (strip_comb c)) = n) gl in
         MATCH_ACCEPT_TAC (MATCH_MP bc_ref_inv_restrict
           (MP (SPEC n bri) (CONJ rr nin))))))));;

(* pop *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let pop_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ stack) refs (rs ++
  roots,heap,be,a,sp,sp1,gens) limit ts /\
      (LENGTH xs = LENGTH rs) ==>
      abs_ml_inv conf (stack) refs (roots,heap,be,a,sp,sp1,gens)
        limit ts`),
  (* the stack permutation that keeps none of the values that are
     popped: the pairs of the two lists are the ZIP of them *)
  (let pop = prove
    (`!conf (xs:(dataSem_v)list) (rs:(('a word_loc)heap_address)list)
         stack roots heap be a sp sp1 gens limit ts refs.
        abs_ml_inv conf (xs ++ stack) refs
          (rs ++ roots,heap,be,a,sp,sp1,gens) limit ts /\
        LENGTH xs = LENGTH rs
        ==> abs_ml_inv conf stack refs
              (roots,heap,be,a,sp,sp1,gens) limit ts`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     MP_TAC(ISPECL
       [`ZIP (xs:(dataSem_v)list)
             (rs:(('a word_loc)heap_address)list)`;
        `[]:(dataSem_v#('a word_loc)heap_address)list`]
       abs_ml_inv_stack_permute) THEN
     ASM_SIMP_TAC[MAP_FST_ZIP; MAP_SND_ZIP; MAP; APPEND;
                  set_of_list; EMPTY_SUBSET]) in
   MATCH_ACCEPT_TAC pop));;

(* duplicate *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_duplicate = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (xs ++ stack)) ==>
       blocks_unique ts (all_vs refs (xs ++ xs ++ stack))`),
  (* the values of xs ++ xs ++ stack are the values of xs ++ stack *)
  (let inc = prove
    (`!refs xs stack' t a q.
        Block t a q IN all_vs refs (APPEND xs (APPEND xs stack')) ==>
        Block t a q IN all_vs refs (APPEND xs stack')`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM;
                 v_all_vs_append; MEM_APPEND] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let duplicate_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf (xs ++ stack) refs (rs ++
  roots,heap,be,a,sp,sp1,gens) limit ts /\
     (LENGTH xs = LENGTH rs) ==>
     abs_ml_inv conf (xs ++ xs ++ stack) refs (rs ++ rs ++
       roots,heap,be,a,sp,sp1,gens) limit ts`),
  (* the invariant of the doubled stack: the roots and the
     reachable references are the ones of the stack it doubles,
     blocks_unique_duplicate gives the uniqueness, the timestamps of
     the doubled stack are more and the relation of the values is
     the one of the two parts, which the split of a LIST_REL over an
     append gives *)
  (let gv n =
     W(fun (asl,_) ->
       let tms = itlist (fun (_,th) acc -> union (frees(concl th)) acc)
                   asl [] in
       EXISTS_TAC (find (fun t -> fst(dest_var t) = n) tms)) in
   let rel_app_eq = prove
    (`!(P:A->B->bool) xs1 ys1 xs2 ys2. LENGTH xs1 = LENGTH ys1
        ==> (ALL2 P (xs1 ++ xs2) (ys1 ++ ys2) <=>
             ALL2 P xs1 ys1 /\ ALL2 P xs2 ys2)`,
     GEN_TAC THEN LIST_INDUCT_TAC THEN X_GEN_TAC `ys1:B list` THEN
     STRUCT_CASES_TAC(ISPEC `ys1:B list` list_CASES_v) THEN
     REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC; SUC_INJ;
                 ARITH_RULE `~(SUC n = 0)`;
                 ARITH_RULE `~(0 = SUC n)`] THEN
     REPEAT GEN_TAC THEN DISCH_TAC THEN ASM_SIMP_TAC[] THEN
     CONV_TAC TAUT) in
   let rr_mono = prove
    (`!(as:(dataSem_v)list) bs rfs n.
        (!x. MEM x as ==> MEM x bs) /\ reachable_refs as rfs n
        ==> reachable_refs bs rfs n`,
     REWRITE_TAC[reachable_refs_def] THEN MESON_TAC[]) in
   REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
   STRIP_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
    [USE_CHANGED [roots_ok_def] THEN
     REWRITE_TAC[roots_ok_def; MEM_APPEND] THEN MESON_TAC[];
     ALL_TAC] THEN
   gv "f" THEN gv "tf" THEN ASM_REWRITE_TAC[] THEN
   REPEAT CONJ_TAC THENL
    [FIRST_ASSUM(fun sub ->
       let t = rand(concl sub) in
       if (try fst(dest_const(fst(strip_comb t))) = "all_ts"
           with Failure _ -> false)
       then MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC t THEN
            CONJ_TAC THENL [ACCEPT_TAC sub; ALL_TAC]
       else fail()) THEN
     REWRITE_TAC[all_ts_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[SUBSET; IN_ELIM_THM; MEM_APPEND] THEN
     GEN_TAC THEN MATCH_MP_TAC MONO_EXISTS THEN GEN_TAC THEN
     CONV_TAC TAUT;
     MATCH_MP_TAC blocks_unique_duplicate THEN
     ASM_REWRITE_TAC[];
     W(fun (asl,_) ->
       let eqs = mapfilter (fun (_,th) -> MATCH_MP rel_app_eq th) asl in
       RULE_ASSUM_TAC(REWRITE_RULE eqs) THEN REWRITE_TAC eqs) THEN
     ASM_REWRITE_TAC[];
     GEN_TAC THEN STRIP_TAC THEN
     FIRST_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
      [FIRST_ASSUM(fun rr ->
         MATCH_MP_TAC rr_mono THEN
         EXISTS_TAC (rand(rator(rator(concl rr)))) THEN
         CONJ_TAC THENL
          [REWRITE_TAC[MEM_APPEND] THEN GEN_TAC THEN CONV_TAC TAUT;
           ACCEPT_TAC rr]);
       FIRST_ASSUM ACCEPT_TAC]]));;

