(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let abs_ml_inv_Num = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf stack refs (roots,heap,be,a,sp,sp1,gens) limit ts
  /\ small_int (:'a) i ==>
      abs_ml_inv conf (Number i :: stack) refs
        (gc_shared_Data (wordLang_Word ((Smallnum i):'a word)) ::
          roots,heap,be,a,sp,sp1,gens) limit ts`),
  (* the new root is a Data, so the roots stay ok; the value has no
     refs and no timestamps of its own, so what the stack reaches
     and what the timestamps are stay as they are, and v_inv of a
     small Number is its Smallnum *)
  (let gr0 = CONJUNCT1 get_refs_def in
  let reach = prove
   (`!(sk:(dataSem_v)list) rfs n i.
       reachable_refs (Number i :: sk) rfs n
       ==> reachable_refs sk rfs n`,
    REWRITE_TAC[reachable_refs_def; MEM] THEN
    MESON_TAC[gr0; MEM]) in
  REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def] THEN
  DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC ASSUME_TAC) THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THENL
   [RULE_ASSUM_TAC(REWRITE_RULE[roots_ok_def]) THEN
    REWRITE_TAC[roots_ok_def; MEM;
                distinctness "heap_address"] THEN
    FIRST_ASSUM MATCH_ACCEPT_TAC;
    MAP_EVERY EXISTS_TAC [`f:(num,num)fmap`; `tf:(num,num)fmap`] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THENL
     [(fun (asl,w) ->
        let ats = rand w in
        let wit = mk_comb(rator ats, rand(rand ats)) in
        (MATCH_MP_TAC SUBSET_TRANS THEN EXISTS_TAC wit) (asl,w)) THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC all_ts_SUBSET_gen THEN
      REWRITE_TAC[MEM] THEN GEN_TAC THEN
      DISCH_THEN(DISJ_CASES_THEN2
        (fun p -> DISJ1_TAC THEN ACCEPT_TAC p)
        (fun m -> DISJ2_TAC THEN DISJ2_TAC THEN ACCEPT_TAC m));
      MATCH_MP_TAC (INST [`[]:(dataSem_v)list`,`ws:(dataSem_v)list`]
        blocks_unique_Number) THEN
      ASM_REWRITE_TAC[APPEND];
      REWRITE_TAC[ALL2] THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[v_inv_def] THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `nn:num` THEN STRIP_TAC THEN
      FIRST_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
       [FIRST_ASSUM(fun rr -> MATCH_ACCEPT_TAC(MATCH_MP reach rr));
        FIRST_ASSUM MATCH_ACCEPT_TAC]]]));;

let heap_store_unused_IMP_length = prove
 (`heap_store_unused a sp' x heap = (heap2,T) ==>
     heap_length heap2 = heap_length heap`,
  (* the lookup splits the heap at the unused element, the store
     lemma says what the store gives back, and the lengths add up *)
  (REWRITE_TAC[heap_store_unused_def] THEN
   COND_CASES_TAC THENL
    [FIRST_X_ASSUM STRIP_ASSUME_TAC THEN
     FIRST_ASSUM(fun th -> MP_TAC(MATCH_MP heap_lookup_SPLIT th)) THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN VAR_EQ_TAC THEN
     ASM_REWRITE_TAC[heap_store_lemma; PAIR_EQ] THEN
     STRIP_TAC THEN VAR_EQ_TAC THEN
     ASM_REWRITE_TAC[heap_length_APPEND; heap_length_CONS] THEN
     ASM_ARITH_TAC;
     REWRITE_TAC[PAIR_EQ] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]]));;

let heap_store_unused_alt_IMP_length = prove
 (`heap_store_unused_alt a sp' x heap = (heap2,T) ==>
    heap_length heap2 = heap_length heap`,
  (REWRITE_TAC[heap_store_unused_alt_def] THEN
   COND_CASES_TAC THENL
    [FIRST_X_ASSUM STRIP_ASSUME_TAC THEN
     FIRST_ASSUM(fun th -> MP_TAC(MATCH_MP heap_lookup_SPLIT th)) THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN VAR_EQ_TAC THEN
     ASM_REWRITE_TAC[heap_store_lemma; PAIR_EQ] THEN
     STRIP_TAC THEN VAR_EQ_TAC THEN
     ASM_REWRITE_TAC[heap_length_APPEND; heap_length_CONS] THEN
     ASM_ARITH_TAC;
     REWRITE_TAC[PAIR_EQ] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]]));;


(* -------------------------------------------------------
    representation in memory
   ------------------------------------------------------- *)

let pointer_bits_def = cake_define
  `// pointers have tag and len bits
   pointer_bits conf abs_heap n =
     (match heap_lookup n abs_heap with SOME (DataElement xs l
       (BlockTag tag,[])) ->
         maxout_bits (LENGTH xs) (data_to_word_config_len_bits conf)
           (data_to_word_config_tag_bits conf + 2) ||
         maxout_bits tag (data_to_word_config_tag_bits conf) 2 ||
           (n2w 1) | _47 -> all_ones (data_to_word_config_len_bits
           conf + data_to_word_config_tag_bits conf + 1) 0)`;;

let is_all_ones_def = cake_define
  `is_all_ones m n w = ((all_ones m n && w) = all_ones m n)`;;

let decode_maxout_def = cake_define
  `decode_maxout l n w =
     (if is_all_ones (n + l) n w then NONE else SOME ((word_bits
       (n + l) n) w >> n))`;;

let decode_addr_def = cake_define
  `decode_addr conf w =
     (decode_maxout (data_to_word_config_len_bits conf)
       (data_to_word_config_tag_bits conf + 2) w,
      decode_maxout (data_to_word_config_tag_bits conf) 2 w)`;;

let get_addr_def = cake_define
  `get_addr conf n w =
     ((n2w n << shift_length conf) || get_lowerbits conf w)`;;

let word_addr_def = cake_define
  `word_addr conf x2 =
        match x2 with
          gc_shared_Data (Loc l1 l2) -> Loc l1 0
        | (gc_shared_Data (wordLang_Word v)) -> wordLang_Word (v &&
          (word_not (n2w 1)))
        | (gc_shared_Pointer n w) -> wordLang_Word (get_addr conf
          n w)`;;

(* b2w_def *)
let data_to_word_memoryProof_b2w_def = prove
 (`(b2w T = (n2w 1)) /\ (b2w F = (n2w 0))`,
  (REWRITE_TAC[b2w_def; b2n_def]));;

let thunk_tag_to_bits_def = cake_define_list
  [`thunk_tag_to_bits Evaluated = (n2w 1)`;
   `thunk_tag_to_bits NotEvaluated = (n2w 0)`];;

let word_payload_def = cake_define_list
  [`word_payload ys l (BlockTag n) qs conf =
         (
          // header: ...00[11] here i in ...i[11] must be 0 for the GC
          make_header conf (n2w n << 2) (LENGTH ys),
          MAP (word_addr conf) ys,(
          (qs = []) /\ (LENGTH ys = l) /\
          encode_header conf (n * 4) (LENGTH ys) =
            SOME (make_header conf (n2w n << 2) (LENGTH ys):'a
              word)))`;
   `word_payload ys l RefTag qs conf =
         (
          // header: ...010[11] here i in ...i[11] must be 0 for the GC
          make_header conf (n2w 2) (LENGTH ys),
          MAP (word_addr conf) ys,(
          (qs = []) /\ (LENGTH ys = l)))`;
   `word_payload ys l (ThunkTag e) qs conf =
         (
          // header: ...e110[11] here i in ...i[11] must be 0 for the GC
          make_header conf (thunk_tag_to_bits e << 3 || (n2w 6))
            (LENGTH ys),
          MAP (word_addr conf) ys,(
          (qs = []) /\ (LENGTH ys = 1) /\ l = 1))`;
   `word_payload ys l Word64Tag qs conf =
         (
          // header: ...011[11] here i in ...i[11] must be 1 for the GC
          make_header conf (n2w 3) l,
          qs,((ys = []) /\ (LENGTH qs = l) /\
              IS_SOME ((encode_header conf 3 l):('a word)
                option)))`;
   `word_payload ys l (NumTag b) qs conf =
         (
          // header: ...111[11] or ...011[11]
          // here i in ...i[11] must be 1 for GC
          make_header conf (b2w b << 2 || ((n2w 3):'a word)) (LENGTH
            qs),
          qs,((ys = []) /\ (LENGTH qs = l) /\
              IS_SOME ((encode_header conf (w2n (b2w b << 2 || ((n2w
                3):'a word)))
                          (LENGTH qs)):('a word) option)))`;
   `word_payload ys l (BytesTag fl n) qs conf =
         (((
           // header: ...101[11] or ...001[11] (compare-by-contents)
           // here i in ...i[11] must be 1 for the GC
           make_byte_header conf fl n):'a word),
          qs,((ys = []) /\ (LENGTH qs = l) /\
              (let k = (if dimindex (:'a) = 32 then 2 else 3) in
              n + 2 EXP k < 2 EXP (data_to_word_config_len_size
                conf + k))))`];;

let word_payload_T_IMP = prove
 (`word_payload l5 n5 tag r conf = ((h:'a word),ts,T) /\
    good_dimindex (:'a) /\ data_to_word_config_len_size conf + 2 <
      dimindex (:'a) ==>
    n5 = LENGTH ts /\
    (if word_bit 2 h then l5 = [] else ts = MAP (word_addr conf)
      l5)`,
  (* the six tags each give a header of make_header or of
     make_byte_header, and the third component of the payload says
     what the length is.  The bit two of a header is the bit zero of
     its tag, because the length sits above the bit two (the length
     size and two are below the dimindex) and the three at the
     bottom has the bit two clear; of make_byte_header it is set,
     whichever of the two tags it takes *)
  (let hdr_bit2 = prove
    (`!conf tg len.
        data_to_word_config_len_size conf + 2 < dimindex (:'a)
        ==> (word_bit 2 (make_header conf (tg:'a word) len) <=>
             word_bit 0 tg)`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     FIRST_ASSUM(fun th ->
       ASSUME_TAC(MATCH_MP
         (ARITH_RULE `k + 2 < d ==> 2 < d`) th)) THEN
     REWRITE_TAC[make_header_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[BIT_WORD_OR; BIT_WORD_SHL; BIT_WORD] THEN
     CONV_TAC NUM_REDUCE_CONV THEN
     ASM_SIMP_TAC[ARITH_RULE `k + 2 < d ==> ~(d - k <= 2)`] THEN
     ASM_REWRITE_TAC[]) in
   let byte_hdr_bit2 = prove
    (`!conf fl n. 2 < dimindex (:'a)
        ==> word_bit 2 (make_byte_header conf fl n:'a word)`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[make_byte_header_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REPEAT COND_CASES_TAC THEN
     ASM_REWRITE_TAC[BIT_WORD_OR; BIT_WORD] THEN
     CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[]) in
   STRIP_TAC THEN
   FIRST_ASSUM(fun th ->
     ASSUME_TAC(MATCH_MP (ARITH_RULE `k + 2 < d ==> 2 < d`) th) THEN
     ASSUME_TAC(MATCH_MP (ARITH_RULE `k + 2 < d ==> 0 < d`) th)) THEN
   CASES_ON_NAME "tag" THEN
   RULE_ASSUM_TAC(REWRITE_RULE[word_payload_def; PAIR_EQ;
                               EQ_CLAUSES]) THEN
   REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC)) THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     let c = concl th in
     if is_eq c && is_var(rand c) && not(is_var(lhand c))
     then SUBST_ALL_TAC(SYM th) else fail())) THEN
   ASM_SIMP_TAC[hdr_bit2; byte_hdr_bit2; LENGTH_MAP; BIT_WORD_SHL;
                BIT_WORD; BIT_WORD_OR] THEN
   CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[]));;

let word_el_def = cake_define_list
  [`word_el (a:'a word) (Unused l) conf = word_list_exists (a:'a
  word) (l + 1)`;
   `word_el (a:'a word) (ForwardPointer n d l) conf =
         set_sep_one (a,wordLang_Word (n2w n << 2)) *
         word_list_exists (a + bytes_in_word) l`;
   `word_el (a:'a word) (DataElement ys l (tag,qs)) conf =
         (let (h,ts,c) = word_payload ys l tag qs conf in
           misc_word_list a (wordLang_Word h :: ts) *
           cond (LENGTH ts < 2 EXP (dimindex (:'a) - 4) /\
                 decode_length conf h = n2w (LENGTH ts) /\ c))`];;

let word_heap_def = cake_define_list
  [`word_heap a ([]:(('a word_loc,data_to_word_memoryProof_tag#('a
  word_loc) list)heap_element) list) conf = emp`;
   `word_heap a (x :: xs) conf =
         word_el a x conf *
         word_heap (a + bytes_in_word * n2w (el_length x)) xs
           conf`];;

let gen_starts_in_store_def = cake_define
  `gen_starts_in_store c x2 x3 =
      match (x2,x3) with
        (GenState _48 gen_starts,SOME (wordLang_Word w)) ->
     (!gen_sizes. data_to_word_config_gc_kind
        c = data_to_word_Generational gen_sizes ==>
        LENGTH gen_starts = LENGTH gen_sizes /\
        (!x xs. gen_starts = x :: xs ==>
               w = (bytes_in_word * n2w x)))
      | (_49,_50) -> F`;;

let gen_starts_in_store_IMP = prove
 (`gen_starts_in_store c gens x ==> (?w. x = SOME (wordLang_Word w))`,
  (CASES_ON_NAME "x" THEN CASES_ON_NAME "gens" THEN
   REWRITE_TAC[gen_starts_in_store_def] THEN
   SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
   TRY(CASES_ON_NAME "a" THEN
       REWRITE_TAC[gen_starts_in_store_def] THEN
       SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[]) THEN
   MESON_TAC[]));;

let glob_real_inv_def = cake_define
  `glob_real_inv c (curr:'a word) globals globreal <=>
     (?w. globals = SOME (wordLang_Word w) /\
         globreal = SOME (wordLang_Word (curr + (w >>>
           (shift_length c) << backend_common_word_shift (:'a)))))`;;

let heap_in_memory_store_def = cake_define
  `heap_in_memory_store heap a sp sp1 gens c s m dm limit' <=>
     heap_length heap <= dimword (:'a) DIV 2 EXP shift_length c /\
     (
      // +3 is breathing room for lists:
      heap_length heap + 3) * (dimindex (:'a) DIV 8) < dimword (:'a)
        /\
     backend_common_word_shift (:'a) <= shift_length c /\
       ~(data_to_word_config_len_size c = 0) /\
       data_to_word_config_len_size
     c + 7 <
             // 5 tag bits + 2-3 bits for byte arrays
             dimindex (:'a) /\
     shift_length c < dimindex (:'a) /\ Globals IN FDOM s /\
     (?curr other.
       byte_aligned curr /\ byte_aligned other /\
       (FLOOKUP s CurrHeap = SOME (wordLang_Word (curr:'a word))) /\
       (FLOOKUP s OtherHeap = SOME (wordLang_Word other)) /\
       (FLOOKUP s NextFree = SOME (wordLang_Word (curr +
         bytes_in_word * n2w a))) /\
       (FLOOKUP s TriggerGC = SOME (wordLang_Word (curr +
         bytes_in_word * n2w (a + sp)))) /\
       (FLOOKUP s EndOfHeap = SOME (wordLang_Word (curr +
         bytes_in_word * n2w (a + sp + sp1)))) /\
       (FLOOKUP s HeapLength = SOME (wordLang_Word (bytes_in_word *
         n2w limit'))) /\
       glob_real_inv c curr (FLOOKUP s Globals) (FLOOKUP s GlobReal)
         /\
       gen_starts_in_store c gens (FLOOKUP s GenStart) /\
       (word_heap curr heap c *
        word_heap other (heap_expand limit') c) (fun2set (m,dm)))`;;

let word_ml_inv_def = cake_define
  `word_ml_inv (heap,be',a,sp,sp1,gens) limit' ts c refs stack' <=>
     (?hs. abs_ml_inv c (MAP FST stack') refs
       (hs,heap,be',a,sp,sp1,gens) limit' ts /\
          EVERY2 (\v w. word_addr c v = w) hs (MAP SND stack'))`;;

let IMP_THE_EQ = prove
 (`x = SOME w ==> THE x = w`,
  (DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[THE]));;

let memory_rel_def = cake_define
  `memory_rel c be' ts refs space' st (m:'a word->'a word_loc) dm vars'
  <=>
     (?heap limit' a sp sp1 gens.
        heap_in_memory_store heap a sp sp1 gens c st m dm limit' /\
        word_ml_inv (heap,be',a,sp,sp1,gens) limit' ts c refs vars'
          /\
        (limit' + 3) * (dimindex (:'a) DIV 8) + 1 < dimword (:'a)
          /\ space' <= sp)`;;

let EVERY2_MAP_MAP = prove
 (`!xs. EVERY2 P (MAP f xs) (MAP g xs) = EVERY (\x. P (f x) (g x)) xs`,
  (let aux = prove
    (`!(P:B->C->bool) f g (xs:A list).
        ALL2 P (MAP f xs) (MAP g xs) <=> ALL (\x. P (f x) (g x)) xs`,
     GEN_TAC THEN GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[MAP; ALL2; ALL]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let MEM_FIRST_EL = prove
 (`!xs x.
      MEM x xs <=>
      (?n. n < LENGTH xs /\ (EL n xs = x) /\
          (!m. m < n ==> (~(EL m xs = EL n xs))))`,
  (* a member of a list is at some index, and the least such index
     is one where no earlier element is that element *)
  (let lemma = prove
    (`!(xs:A list) x.
        MEM x xs <=>
        (?n. n < LENGTH xs /\ EL n xs = x /\
             (!m. m < n ==> ~(EL m xs = EL n xs)))`,
     REPEAT GEN_TAC THEN EQ_TAC THENL
      [DISCH_TAC THEN
       MP_TAC(SPEC `\n. n < LENGTH (xs:A list) /\ EL n xs = x`
         num_WOP) THEN
       REWRITE_TAC[] THEN
       DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
       ANTS_TAC THENL
        [FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[MEM_EXISTS_EL]) THEN
         MESON_TAC[];
         ALL_TAC] THEN
       DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
       EXISTS_TAC `n:num` THEN ASM_REWRITE_TAC[] THEN
       X_GEN_TAC `m:num` THEN DISCH_TAC THEN
       FIRST_X_ASSUM(MP_TAC o SPEC `m:num`) THEN
       ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC(TAUT `p ==> (~(p /\ q) ==> ~q)`) THEN
       ASM_ARITH_TAC;
       DISCH_THEN(X_CHOOSE_THEN `n:num` STRIP_ASSUME_TAC) THEN
       REWRITE_TAC[MEM_EXISTS_EL] THEN EXISTS_TAC `n:num` THEN
       ASM_REWRITE_TAC[]]) in
   MATCH_ACCEPT_TAC lemma));;

let ALOOKUP_ZIP_EL = prove
 (`!xs hs n.
      n < LENGTH xs /\ LENGTH hs = LENGTH xs /\
      (!m. m < n ==> ~(EL m xs = EL n xs)) ==>
      ALOOKUP (ZIP xs hs) (EL n xs) = SOME (EL n hs)`,
  (* the lookup of the nth key walks past the n keys before it,
     which the hypothesis says are not that key, and the pair that
     the zip has there is the nth key with the nth value *)
  (let split = prove
    (`!(h:A) t k. (!m. m < SUC k ==> ~(EL m (CONS h t) = EL k t))
        ==> ~(h = EL k t) /\ (!m. m < k ==> ~(EL m t = EL k t))`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN CONJ_TAC THENL
      [FIRST_X_ASSUM(MP_TAC o SPEC `0`) THEN
       REWRITE_TAC[LT_0; EL; HD];
       GEN_TAC THEN DISCH_TAC THEN
       FIRST_X_ASSUM(MP_TAC o SPEC `SUC m`) THEN
       REWRITE_TAC[EL; TL; LT_SUC] THEN ASM_REWRITE_TAC[]]) in
   LIST_INDUCT_TAC THENL
    [REWRITE_TAC[LENGTH; ARITH_RULE `((n:num) < 0) <=> F`];
     (fun (asl,w as gl) ->
        let hsv = fst(dest_forall w) in
        (X_GEN_TAC hsv THEN
         STRUCT_CASES_TAC(ISPEC hsv list_CASES_v)) gl) THEN
     GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `n:num` num_CASES) THEN
     REWRITE_TAC[LENGTH; ZIP; ALOOKUP; EL; HD; TL; FST; SND;
                 ARITH_RULE `(0 = SUC n) <=> F`;
                 ARITH_RULE `(SUC n = 0) <=> F`] THEN
     TRY(CONV_TAC TAUT) THEN
     STRIP_TAC THEN
     FIRST_ASSUM(fun th -> STRIP_ASSUME_TAC (MATCH_MP split th)) THEN
     ASM_REWRITE_TAC[] THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN
     REPEAT CONJ_TAC THEN TRY ASM_ARITH_TAC THEN
     ASM_REWRITE_TAC[]]));;

(* the port's own: what the proof of word_ml_inv_rearrange needs.
   The roots of the new stack are the ones the old stack gave its
   pairs, which the lookup of a pair in the association of the old
   stack with its roots finds (ALOOKUP_root); the relation between
   the values and the roots then holds pair by pair
   (EVERY2_rearrange_roots), and the invariant itself is
   abs_ml_inv_stack_permute with nothing on the stack but the pairs
   (abs_ml_inv_rearrange, which has to say the stack of the one and
   of the other as a MAP over one list of pairs) *)

(* the root that a pair of the stack has: the pairs before the
   first one that is it are not it, so the lookup lands there *)
let ALOOKUP_root = prove
 (`!(xs:(A)list) (hs:(B)list) y.
     LENGTH hs = LENGTH xs /\ MEM y xs
     ==> ?n. n < LENGTH xs /\ EL n xs = y /\
             THE (ALOOKUP (ZIP xs hs) y) = EL n hs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  FIRST_X_ASSUM (fun m ->
    if not (hd_is "MEM" (concl m)) then fail() else
    STRIP_ASSUME_TAC (REWRITE_RULE[MEM_FIRST_EL] m)) THEN
  W(fun gl ->
    let eq = the_asm (fun c -> is_eq c && hd_is "EL" (lhand c)) gl in
    EXISTS_TAC (lhand (lhand (concl eq)))) THEN
  REPEAT CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  W(fun gl ->
    let eq = the_asm (fun c -> is_eq c && hd_is "EL" (lhand c)) gl in
    let lt = the_asm (fun c -> hd_is "<" c) gl in
    let le = the_asm (fun c -> is_eq c &&
               hd_is "LENGTH" (lhand c)) gl in
    let mn = the_asm (fun c ->
               length (fst (strip_forall c)) = 1 &&
               is_imp (snd (strip_forall c)) &&
               is_neg (rand (snd (strip_forall c)))) gl in
    let al = MATCH_MP ALOOKUP_ZIP_EL (CONJ lt (CONJ le mn)) in
    MATCH_ACCEPT_TAC (MATCH_MP IMP_THE_EQ
      (ONCE_REWRITE_RULE[eq] al))));;

(* the roots of a stack that the other stack has: each pair of the
   one is a pair of the other, and the lookup finds its root *)
let EVERY2_rearrange_roots = prove
 (`!(P:C->B->bool) (ys:(A#B)list) xs (hs:(C)list).
     (!x. MEM x ys ==> MEM x xs) /\ LENGTH hs = LENGTH xs /\
     ALL2 P hs (MAP SND xs)
     ==> ALL2 P (MAP (\y. THE (ALOOKUP (ZIP xs hs) y)) ys)
                (MAP SND ys)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN SPLIT_ASM_TAC THEN
  REWRITE_TAC[EVERY2_MAP_MAP; GSYM ALL_MEM] THEN
  CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  REPEAT STRIP_TAC THEN
  (* the pair is one of the old stack, so the lookup finds the
     root that the old stack gave it *)
  W(fun gl ->
    let m = the_asm (hd_is "MEM") gl in
    let sub = the_asm (fun c ->
                length (fst (strip_forall c)) = 1 &&
                is_imp (snd (strip_forall c)) &&
                hd_is "MEM" (rand (snd (strip_forall c)))) gl in
    let le = the_asm (fun c -> is_eq c &&
               hd_is "LENGTH" (lhand c)) gl in
    STRIP_ASSUME_TAC (MATCH_MP ALOOKUP_root
      (CONJ le (MP (SPEC (el 0 (snd (strip_comb (concl m)))) sub)
                  m)))) THEN
  W(fun gl ->
    let thq = the_asm (fun c -> is_eq c &&
                hd_is "THE" (lhand c)) gl in
    let eqy = the_asm (fun c -> is_eq c &&
                hd_is "EL" (lhand c)) gl in
    let e2 = the_asm (hd_is "ALL2") gl in
    let le = the_asm (fun c -> is_eq c &&
               hd_is "LENGTH" (lhand c)) gl in
    let lt = the_asm (fun c -> hd_is "<" c) gl in
    let n = lhand (lhand (concl eqy)) in
    let xs = rand (lhand (concl eqy)) in
    let el = MATCH_MP ALL2_EL
               (CONJ e2 (ONCE_REWRITE_RULE[GSYM le] lt)) in
    let mp = MP (ISPECL [lhand (rand (concl e2)); n; xs]
                   EL_MAP) lt in
    ONCE_REWRITE_TAC[thq] THEN
    ACCEPT_TAC (REWRITE_RULE[mp; eqy] el)));;

(* abs_ml_inv_stack_permute with nothing on the stack but the
   pairs, which is how HOL4 instantiates it as well *)
let abs_ml_inv_stack_permute_nil =
  let th = abs_ml_inv_stack_permute in
  let fvs = frees (concl th) in
  let pick n = find (fun v -> fst (dest_var v) = n) fvs in
  let nil_like v = rand (lhand (concl (ISPEC v APPEND_NIL))) in
  let st = pick "stack" and rt = pick "roots" in
  REWRITE_RULE[APPEND_NIL]
    (INST [nil_like st,st; nil_like rt,rt] th);;

(* the invariant over a stack that the other stack has: the pairs
   of the one are pairs of the other, with the root that the lookup
   finds, so the lemma above says it *)
let abs_ml_inv_rearrange = prove
 (cake_as_vars (fun () ->
    `(!x. MEM x ys ==> MEM x xs) /\ LENGTH hs = LENGTH xs /\
     abs_ml_inv conf (MAP FST xs) refs
       (hs,heap,be,a,sp,sp1,gens) limit ts
     ==> abs_ml_inv conf (MAP FST ys) refs
           (MAP (\y. THE (ALOOKUP (ZIP xs hs) y)) ys,
            heap,be,a,sp,sp1,gens) limit ts`),
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  W(fun (asl,w as gl) ->
    let inv = the_asm (hd_is "abs_ml_inv") gl in
    let iargs = snd (strip_comb (concl inv)) in
    let fstm = lhand (el 1 iargs) in
    let xs = rand (el 1 iargs) in
    let hs = el 0 (tparts (el 3 iargs)) in
    let gargs = snd (strip_comb w) in
    let ys = rand (el 1 gargs) in
    let rts = el 0 (tparts (el 3 gargs)) in
    let g = lhand rts in
    let v,bod = dest_abs g in
    let pairf = mk_abs (v, mk_pair (mk_comb (fstm,v), bod)) in
    let pty = type_of v in
    let vty = hd (snd (dest_type pty)) in
    let rty = type_of bod in
    let zpty = mk_type("prod",[vty; rty]) in
    let fstz = mk_mconst("FST", mk_fun_ty zpty vty) in
    let sndz = mk_mconst("SND", mk_fun_ty zpty rty) in

    let zs = list_mk_icomb "MAP" [pairf; ys] in

    let ws = list_mk_icomb "ZIP"
               [list_mk_icomb "MAP" [fstm; xs]; hs] in
    let le = the_asm (fun c -> is_eq c &&
               hd_is "LENGTH" (lhand c)) gl in
    let lz = TRANS (ISPECL [xs; fstm] LENGTH_MAP) (SYM le) in

    let maps = [MATCH_MP MAP_FST_ZIP lz; MATCH_MP MAP_SND_ZIP lz] in

    let lv = genvar (type_of ys) in
    let mapstep = LIST_INDUCT_TAC THEN REWRITE_TAC[MAP] THEN
                  CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
                  ASM_REWRITE_TAC[FST; SND] in
    let eq1 = SPEC ys (prove(mk_forall(lv,
                 mk_eq (list_mk_icomb "MAP"
                          [fstz; list_mk_icomb "MAP" [pairf; lv]],
                        list_mk_icomb "MAP" [fstm; lv])),
                 mapstep)) in
    let eq2 = SPEC ys (prove(mk_forall(lv,
                 mk_eq (list_mk_icomb "MAP"
                          [sndz; list_mk_icomb "MAP" [pairf; lv]],
                        list_mk_icomb "MAP" [g; lv])),
                 mapstep)) in

    let perm = REWRITE_RULE (eq1 :: eq2 :: maps)
                 (ISPECL [ws; zs] abs_ml_inv_stack_permute_nil) in
    (* the pairs of the new stack are pairs of the old one: the
       root of each is the one the lookup finds *)
    SUBGOAL_THEN (list_mk_icomb "SUBSET"
                    [list_mk_icomb "set_of_list" [zs];
                     list_mk_icomb "set_of_list" [ws]])
      (fun ss -> MATCH_ACCEPT_TAC (MATCH_MP perm (CONJ inv ss))) THEN
    (REWRITE_TAC[SUBSET; IN_SET_OF_LIST; MEM_MAP] THEN
      REPEAT STRIP_TAC THEN
      W(fun gl ->
        let m = the_asm (fun c -> hd_is "MEM" c) gl in
        let sub = the_asm (fun c ->
                    length (fst (strip_forall c)) = 1 &&
                    is_imp (snd (strip_forall c)) &&
                    hd_is "MEM" (rand (snd (strip_forall c)))) gl in
        STRIP_ASSUME_TAC (MATCH_MP ALOOKUP_root
          (CONJ le (MP (SPEC (el 0 (snd (strip_comb (concl m)))) sub)
                      m)))) THEN
      W(fun (asl,w as gl) ->
        let eqy = the_asm (fun c -> is_eq c &&
                    hd_is "EL" (lhand c)) gl in
        let thq = the_asm (fun c -> is_eq c &&
                    hd_is "THE" (lhand c)) gl in
        let lt = the_asm (fun c -> hd_is "<" c) gl in
        let n = lhand (lhand (concl eqy)) in
        let ltm = ONCE_REWRITE_RULE
                    [SYM (ISPECL [xs; fstm] LENGTH_MAP)] lt in
        let mem = MP (ISPECL [list_mk_icomb "MAP" [fstm; xs]; hs; n]
                        MEM_ZIP_EL) (CONJ ltm (SYM lz)) in
        let elm = MP (ISPECL [fstm; n; xs] EL_MAP) lt in
        ASM_REWRITE_TAC[] THEN
        CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
        ASM_REWRITE_TAC[] THEN
        ACCEPT_TAC (REWRITE_RULE[elm; eqy; thq] mem)))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_ml_inv_rearrange = prove
 (cake_as_vars (fun () ->
    `(!x. MEM x ys ==> MEM x xs) ==>
     word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c refs xs ==>
     word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c refs ys`),
  (* the steps are above the statement (tools/overrides.py).  The
     roots of the new stack are the ones that the old stack gave
     its pairs: the lookup of a pair in the association of the old
     stack with its roots finds it, and the invariant and the
     relation between the values and the roots then come from
     abs_ml_inv_rearrange and EVERY2_rearrange_roots *)
  (STRIP_TAC THEN
    REWRITE_TAC[word_ml_inv_def] THEN
    DISCH_THEN (CHOOSE_THEN STRIP_ASSUME_TAC) THEN
    (* the roots are as many as the pairs of the stack *)
    W(fun gl ->
      let e2 = the_asm (hd_is "ALL2") gl in
      ASSUME_TAC (REWRITE_RULE[LENGTH_MAP]
                    (MATCH_MP LIST_REL_LENGTH e2))) THEN
    (* and the root of a pair of the new stack is the one that the
       old stack gave it *)
    W(fun (asl,w as gl) ->
      let inv = the_asm (hd_is "abs_ml_inv") gl in
      let iargs = snd (strip_comb (concl inv)) in
      let xs = rand (el 1 iargs) in
      let hs = el 0 (tparts (el 3 iargs)) in
      let e2 = the_asm (hd_is "ALL2") gl in
      let le = the_asm (fun c -> is_eq c &&
                 hd_is "LENGTH" (lhand c)) gl in
      let sub = the_asm (fun c ->
                  length (fst (strip_forall c)) = 1 &&
                  is_imp (snd (strip_forall c)) &&
                  hd_is "MEM" (rand (snd (strip_forall c)))) gl in
      let ys = el 1 (snd (strip_comb
                 (lhand (snd (strip_forall (concl sub)))))) in
      let v = genvar (hd (snd (dest_type (type_of ys)))) in
      let g = mk_abs (v, list_mk_icomb "THE"
                [list_mk_icomb "ALOOKUP"
                   [list_mk_icomb "ZIP" [xs; hs]; v]]) in
      EXISTS_TAC (list_mk_icomb "MAP" [g; ys]) THEN
      CONJ_TAC THENL
       [MATCH_ACCEPT_TAC (MATCH_MP abs_ml_inv_rearrange
          (CONJ sub (CONJ le inv)));
        MATCH_ACCEPT_TAC (MATCH_MP EVERY2_rearrange_roots
          (CONJ sub (CONJ le e2)))])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_rearrange = prove
 (cake_as_vars (fun () ->
    `(!x. MEM x ys ==> MEM x xs) ==>
     memory_rel c be ts refs sp st m dm xs ==>
     memory_rel c be ts refs sp st m dm ys`),
  (* the witnesses of the goal's existential are the ones the
     assumption has: HOL4's asm_exists_tac, ml/lib/tactics.ml *)
  (REWRITE_TAC[memory_rel_def] THEN REPEAT STRIP_TAC THEN
   ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[] THEN
   FIRST_X_ASSUM(fun th -> MP_TAC th THEN
     MATCH_MP_TAC word_ml_inv_rearrange) THEN
   ASM_REWRITE_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_tl = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm (x :: xs) ==>
     memory_rel c be ts refs sp st m dm xs`),
  (* the source's match_mp_tac takes the lemma's second antecedent
     for the goal's; HOL Light's takes the conclusion, so the two
     antecedents are swapped first and the assumption discharges
     the one that says what the memory holds *)
  (DISCH_TAC THEN
   FIRST_ASSUM(fun th ->
     MATCH_MP_TAC(MATCH_MP
       (ONCE_REWRITE_RULE[TAUT `(p ==> q ==> r) <=> (q ==> p ==> r)`]
          memory_rel_rearrange) th)) THEN
   REWRITE_TAC[MEM] THEN MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_ml_inv_Unit = prove
 (cake_as_vars (fun () ->
    `word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c refs ws /\
      good_dimindex (:'a) ==>
      word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c refs
        ((Unit,wordLang_Word ((n2w 2):'a word)) :: ws)`),
  (* Unit is the empty Block of the tuple tag, which cons_thm_EMPTY
     puts on the stack with the root Data (Word (BlockNil 0)), and
     that word is two, whose lowest bit word_addr takes off *)
  (let blocknil0 = prove
    (`BlockNil 0 = (n2w 2:'a word)`,
     REWRITE_TAC[BlockNil_def] THEN CONV_TAC WORD_RULE) in
   let and2 = prove
    (`(n2w 2:(N)word) && word_not (n2w 1) = n2w 2`,
     WORD_NUM_BIT_TAC 2) in
   let dimword16 = prove
    (`good_dimindex (:'a) ==> 0 < dimword (:'a) DIV 16`,
     REWRITE_TAC[good_dimindex_def; dimword] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
     CONV_TAC NUM_REDUCE_CONV) in
   let waddr = hd (word_addr_clauses ()) in
   let cons0 = REWRITE_RULE[blocknil0]
     (INST [`0`,`tag:num`] cons_thm_EMPTY) in
   REWRITE_TAC[word_ml_inv_def] THEN REPEAT STRIP_TAC THEN
   EXISTS_TAC
     `CONS (gc_shared_Data (wordLang_Word (n2w 2:'a word))) hs` THEN
   REWRITE_TAC[MAP; ALL2; waddr; and2] THEN
   ASM_REWRITE_TAC[dataSem_Unit_def;
                   tuple_tag_def] THEN
   MATCH_MP_TAC cons0 THEN
   ASM_SIMP_TAC[dimword16]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Unit = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm xs /\ good_dimindex (:'a) ==>
     memory_rel c be ts refs sp st m dm ((Unit,wordLang_Word
       ((n2w 2):'a word)) :: xs)`),
  (REWRITE_TAC[memory_rel_def] THEN REPEAT STRIP_TAC THEN
   ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[] THEN
   MATCH_MP_TAC word_ml_inv_Unit THEN ASM_REWRITE_TAC[]));;

let get_lowerbits_LSL_shift_length = prove
 (`get_lowerbits conf a >>> shift_length conf = (n2w 0)`,
  (* the lower bits are below small_shift_length, which is below
     shift_length, so the shift leaves nothing *)
  (CASES_ON_NAME "a" THEN
   REWRITE_TAC[get_lowerbits_def] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_0; BIT_WORD_USHR;
               BIT_WORD_OR; BIT_WORD_1; word_bits; BIT_WORD_SUBWORD;
               small_shift_length_def;
               shift_length_def] THEN
   REPEAT STRIP_TAC THEN ASM_ARITH_TAC));;

let get_real_addr_def = cake_define
  `get_real_addr conf st (w:'a word) =
     (let k = backend_common_word_shift (:'a) in
       match FLOOKUP st CurrHeap with SOME (wordLang_Word curr) ->
           (if k = shift_length conf /\ data_to_word_config_len_bits
             conf = 0 /\ data_to_word_config_tag_bits conf = 0 then SOME
             ((curr + w) - (n2w 1)) else
             if k <= data_to_word_config_pad_bits conf + 1 then
               SOME (curr + (w >>> (shift_length conf - k))) else
               SOME (curr + (w >>> (shift_length conf) << k))) | _51
               -> NONE)`;;

let get_real_offset_def = cake_define
  `get_real_offset (w:'a word) =
     (if dimindex (:'a) = 32 then SOME (w + bytes_in_word) else
       SOME (w << 1 + bytes_in_word))`;;

let get_real_simple_addr_def = cake_define
  `get_real_simple_addr conf st (w:'a word) =
     (match FLOOKUP st CurrHeap with SOME (wordLang_Word curr) ->
       SOME (curr + w >>> shift_length conf <<
       backend_common_word_shift (:'a)) | _52 -> NONE)`;;

(* [local] *)
let or_1 = prove
 (`!w. (word_bits 0 0) w || (n2w 1) = ((n2w 1):'a word)`,
  (* the lowest bit of a word, or one, is one *)
  (GEN_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_OR; word_bits;
               BIT_WORD_SUBWORD; BIT_WORD_1] THEN
   X_GEN_TAC `i:num` THEN DISCH_TAC THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   ASM_CASES_TAC `i = 0` THEN ASM_REWRITE_TAC[] THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   TRY(REWRITE_TAC[ARITH_RULE `0 < d <=> 1 <= d`; DIMINDEX_GE_1]) THEN
   POP_ASSUM_LIST(fun ths -> MAP_EVERY MP_TAC ths) THEN ARITH_TAC));;

let get_real_addr_get_addr = prove
 (`heap_length heap <= dimword (:'a) DIV 2 EXP shift_length c /\
    heap_lookup n heap = SOME anything /\
    FLOOKUP st CurrHeap = SOME (wordLang_Word (curr:'a word)) /\
    good_dimindex (:'a) ==>
    get_real_simple_addr c st (get_addr c n w) = SOME (curr + n2w n *
      bytes_in_word) /\
    get_real_addr c st (get_addr c n w) = SOME (curr + n2w n *
      bytes_in_word)`,
(* the address of a pointer: the heap fits below the shift
   (LE_RDIV_EQ of the bound of the statement) and the pointer is
   inside the heap (heap_lookup_LESS), so no bit of it is as high
   as the shift, and the shift down of the address that get_addr
   built gives the pointer back -- the lower bits that get_addr
   put in are below the small shift and the shift down loses them
   (the local lemma, by the bits of the two sides).  The simple
   address shifts the pointer up by the word shift again, which is
   the multiplication by bytes_in_word
   (bytes_in_word_mul_eq_shift), and get_real_addr does the same
   in the two cases where the shift it uses leaves the word shift;
   where the shift is the word shift itself the address is the
   pointer and the one bit that get_addr adds (or_1,
   WORD_ADD_OR), which the subtraction of the one takes off *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  (* a word that is not shifted *)
  let shl0 = prove
   (`!(x:'a word). x << 0 = x`,
    GEN_TAC THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_SHL; SUB_0; LE_0] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN ASM_REWRITE_TAC[]) in
  let divlt = prove
   (`!m n. m < n ==> m DIV n = 0`,
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `~(n = 0)` (fun nz ->
      REWRITE_TAC[MP (SPECL [`m:num`; `n:num`] DIV_EQ_0) nz]) THENL
     [ASM_ARITH_TAC; FIRST_ASSUM ACCEPT_TAC]) in
  (* a pointer that fits below the shift has no bit that high *)
  let ptbits = prove
   (`!n s. n * 2 EXP s < dimword (:'a)
           ==> !i. word_bit i ((n2w n):'a word)
                   ==> i + s < dimindex (:'a)`,
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    X_GEN_TAC `i:num` THEN REWRITE_TAC[BIT_WORD] THEN STRIP_TAC THEN
    SUBGOAL_THEN `2 EXP i <= n` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM NOT_LT] THEN DISCH_TAC THEN
      FIRST_X_ASSUM (fun odd ->
        if not (hd_is "ODD" (concl odd)) then fail() else
        MP_TAC odd) THEN
      ASM_SIMP_TAC[divlt; ODD];
      ALL_TAC] THEN
    SUBGOAL_THEN `2 EXP (i + s) <= n * 2 EXP s` MP_TAC THENL
     [REWRITE_TAC[EXP_ADD] THEN ASM_SIMP_TAC[LE_MULT_RCANCEL];
      ALL_TAC] THEN
    MP_TAC (SPECL [`2`; `dimindex (:'a)`; `i + s`] LE_EXP) THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    MP_TAC (ASSUME `n * 2 EXP s < dimword (:'a)`) THEN
    REWRITE_TAC[dimword] THEN ARITH_TAC) in
  (* and the lower bits of a pointer are below the small shift *)
  let lowbits = prove
   (`!i x. word_bit i (get_lowerbits c x)
           ==> i < small_shift_length c`,
    REPEAT GEN_TAC THEN CASES_ON_NAME "x" THEN
    REWRITE_TAC[get_lowerbits_def] THEN
    TRY SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[BIT_WORD_OR; BIT_WORD_1; word_bits;
                BIT_WORD_SUBWORD; small_shift_length_def] THEN
    STRIP_TAC THEN ASM_ARITH_TAC) in
  (* so the shift down of a pointer that was shifted up leaves the
     pointer shifted up by what is left: the lower bits vanish and
     the bits of the pointer are low enough that the shift up kept
     them *)
  let l1 = prove
   (`!n (lw:'a word) k t.
       (!i. word_bit i lw ==> i < t) /\
       (!i. word_bit i ((n2w n):'a word)
            ==> i + (k + t) < dimindex (:'a))
       ==> ((n2w n) << (k + t) || lw) >>> t =
           ((n2w n):'a word) << k`,
    REPEAT GEN_TAC THEN
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "lw")
      (LABEL_TAC "pt")) THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    REWRITE_TAC[BIT_WORD_USHR; BIT_WORD_OR; BIT_WORD_SHL] THEN
    SUBGOAL_THEN `~(word_bit (i + t) (lw:'a word))`
      (fun th -> REWRITE_TAC[th]) THENL
     [USE_THEN "lw" (fun h1 -> MP_TAC (SPEC `i + t` h1)) THEN
      MATCH_MP_TAC (TAUT `~q ==> (p ==> q) ==> ~p`) THEN ARITH_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[ARITH_RULE `(i + t) - (k + t) = i - k`;
                ARITH_RULE `(k + t <= i + t) <=> k <= i`] THEN
    ASM_CASES_TAC `word_bit (i - k) ((n2w n):'a word)` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "pt" (fun h2 ->
      MP_TAC (MP (SPEC `i - k` h2)
        (ASSUME `word_bit (i - k) ((n2w n):'a word)`))) THEN
    MP_TAC (ASSUME `i < dimindex (:'a)`) THEN ARITH_TAC) in
  (* the address that the shift down and up gives *)
  let shift_step kk extra =
    W(fun (asl,gl) ->
      let ushr = find_term (hd_is "word_ushr") gl in
      let x = lhand ushr and tt = rand ushr in
      let shl = lhand x and lw = rand x in
      let s = rand shl in
      let nn = rand (lhand shl) in
      let ptf = grab asl (fun th ->
        try is_forall (concl th) &&
            hd_is "bit" (lhand (body (rand (concl th))))
        with Failure _ -> false) in
      let mkp tm tac =
        if extra = [] then prove (tm, tac) else
        MP (prove (mk_imp (end_itlist (curry mk_conj)
                             (map concl extra), tm),
             DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
             tac))
           (end_itlist CONJ extra) in
      let lwf = mkp (mk_forall (`i:num`,
                  mk_imp (list_mk_icomb "bit" [`i:num`; lw],
                    mk_binop `(<):num->num->bool` `i:num` tt)))
                  (GEN_TAC THEN
                   DISCH_THEN (fun b ->
                     MP_TAC (MATCH_MP lowbits b)) THEN
                   REWRITE_TAC[small_shift_length_def;
                               shift_length_def] THEN
                   ASM_ARITH_TAC) in
      let seq = mkp (mk_eq (mk_binop `(+):num->num->num` kk tt, s))
                  (REWRITE_TAC[shift_length_def] THEN
                   ASM_ARITH_TAC) in
      let inst = REWRITE_RULE[seq] (SPECL [nn; lw; kk; tt] l1) in
      REWRITE_TAC[MP inst (CONJ lwf ptf); shl0]) in
  (* and the address that the word shift of a pointer is *)
  let fin =
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      REWRITE_TAC[GSYM (MATCH_MP bytes_in_word_mul_eq_shift gd)] THEN
      CONV_TAC WORD_RULE) in
  STRIP_TAC THEN
  (* the pointer is inside the heap, which fits below the shift *)
  SUBGOAL_THEN `n * 2 EXP shift_length c < dimword (:'a)`
    ASSUME_TAC THENL
   [W(fun (asl,gl) ->
      let hl = grab asl (fun th ->
        try hd_is "<=" (concl th) &&
            hd_is "heap_length" (lhand (concl th))
        with Failure _ -> false) in
      let lk = grab asl (fun th ->
        try hd_is "heap_lookup" (lhs (concl th))
        with Failure _ -> false) in
      let tp = rand (rand (concl hl)) in
      let hh = lhand (concl hl) in
      let nz = prove (mk_neg (mk_eq (tp, `0`)),
                REWRITE_TAC[EXP_EQ_0] THEN ARITH_TAC) in
      let hl2 = REWRITE_RULE[MP (SPECL [tp; `dimword (:'a)`; hh]
                                  LE_RDIV_EQ) nz] hl in
      let lt = MATCH_MP heap_lookup_LESS lk in
      let mono = EQ_MP (SYM (SPECL [`n:num`; hh; tp]
                          LT_MULT_RCANCEL)) (CONJ lt nz) in
      MP_TAC hl2 THEN MP_TAC mono THEN
      REWRITE_TAC[MULT_SYM] THEN ARITH_TAC);
    ALL_TAC] THEN
  (* so no bit of it is as high as the shift *)
  SUBGOAL_THEN
    `!i. word_bit i ((n2w n):'a word)
         ==> i + shift_length c < dimindex (:'a)` ASSUME_TAC THENL
   [FIRST_ASSUM (fun th ->
      if not (try hd_is "<" (concl th) &&
                  hd_is "dimword" (rand (concl th))
              with Failure _ -> false) then fail() else
      ACCEPT_TAC (MATCH_MP ptbits th));
    ALL_TAC] THEN
  (* the two addresses that the store of the heap gives *)
  W(fun (asl,gl) ->
    let flk = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th))
      with Failure _ -> false) in
    REWRITE_TAC[get_real_simple_addr_def; get_real_addr_def;
                flk]) THEN
  TRY SAFE_MATCH_REDUCE_TAC THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[get_addr_def; injectivity "option"] THEN
  CONJ_TAC THENL
   [(* the simple address: the shift down gives the pointer and
        the shift up the bytes it stands for *)
    shift_step `0` [] THEN fin;
    ALL_TAC] THEN
  COND_CASES_TAC THEN
  TRY (REWRITE_TAC[injectivity "option"]) THENL
   [(* the pointer is the address and the one bit, which the
        subtraction takes off *)
    W(fun (asl,gl) ->
      let cnd = grab asl (fun th ->
        try is_conj (concl th) &&
            hd_is "backend_common_word_shift" (lhs (lhand (concl th)))
        with Failure _ -> false) in
      let cs = CONJUNCTS cnd in
      let lb = MP (prove (mk_imp (mk_conj (concl (el 1 cs),
                                           concl (el 2 cs)),
                    `get_lowerbits c w = ((n2w 1):'a word)`),
                    CASES_ON_NAME "w" THEN
                    REWRITE_TAC[get_lowerbits_def] THEN
                    TRY SAFE_MATCH_REDUCE_TAC THEN
                    STRIP_TAC THEN
                    ASM_REWRITE_TAC[small_shift_length_def] THEN
                    CONV_TAC NUM_REDUCE_CONV THEN
                    REWRITE_TAC[or_1]))
                (CONJ (el 1 cs) (el 2 cs)) in
      let dis = prove
                 (`((n2w n) << shift_length c) && (n2w 1) =
                   ((n2w 0):'a word)`,
                  MP_TAC (prove (`1 <= shift_length c`,
                    REWRITE_TAC[shift_length_def] THEN
                    ARITH_TAC)) THEN
                  REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND;
                              BIT_WORD_1; BIT_WORD_0;
                              BIT_WORD_SHL] THEN
                  REPEAT STRIP_TAC THEN ASM_ARITH_TAC) in
      REWRITE_TAC[lb] THEN
      REWRITE_TAC[GSYM (MATCH_MP WORD_ADD_OR dis)] THEN
      REWRITE_TAC[GSYM (el 0 cs)]) THEN
    fin;
    ALL_TAC] THEN
  COND_CASES_TAC THEN
  TRY (REWRITE_TAC[injectivity "option"]) THENL
   [(* the shift down is the one that leaves the word shift *)
    W(fun (asl,gl) ->
      let cnd = grab asl (fun th ->
        try hd_is "<=" (concl th) &&
            hd_is "backend_common_word_shift" (lhand (concl th))
        with Failure _ -> false) in
      shift_step (lhand (concl cnd)) [cnd]) THEN
    fin;
    (* and above the word shift the two shifts are the simple
       address again *)
    shift_step `0` [] THEN fin])));;

let get_real_offset_thm = prove
 (`good_dimindex (:'a) ==>
    get_real_offset (n2w (4 * index)) =
      SOME (bytes_in_word + n2w index * (bytes_in_word:'a word))`,
  (* the offset of an index is four times it, which a dimindex of
     32 adds to the bytes in a word as it stands and one of 64
     doubles first *)
  (let shl1 = prove
    (`!(v:(N)word). word_shl v 1 = word 2 * v`,
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
     REWRITE_TAC[MULT_AC]) in
   REWRITE_TAC[good_dimindex_def; get_real_offset_def;
               bytes_in_word_def] THEN
   DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   REWRITE_TAC[injectivity "option"; shl1; WORD_MUL] THEN
   CONV_TAC WORD_RULE));;

let word_heap_APPEND = prove
 (`!xs ys a.
      word_heap a (xs ++ ys) conf =
      word_heap a xs conf *
      word_heap (a + bytes_in_word * n2w (heap_length xs)) ys conf`,
  (* the address of the second half is the first address shifted by
     the length of the first half, which is a word ring identity *)
  (LIST_INDUCT_TAC THEN
   ASM_REWRITE_TAC[APPEND; word_heap_def; heap_length_NIL;
                   heap_length_CONS; emp_STAR; STAR_ASSOC;
                   WORD_ADD_MUL_SPLIT; WORD_ADD_MUL_0]));;

(* FORALL_WORD *)
let data_to_word_memoryProof_FORALL_WORD = prove
 (`(!(v:'a word). P v) <=> (!n. n < dimword (:'a) ==> P (n2w n))`,
  (EQ_TAC THEN REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
   ONCE_REWRITE_TAC[GSYM WORD_VAL] THEN
   FIRST_X_ASSUM MATCH_MP_TAC THEN
   REWRITE_TAC[dimword; VAL_BOUND]));;

let BlockNil_and_lemma = prove
 (`good_dimindex (:'a) ==>
    (--(n2w 2) && (n2w 16) * tag + (n2w 2)) = (n2w 16) * tag +
      ((n2w 2):'a word)`,
  (* sixteen times a word has its four lowest bits clear, so the
     and with the complement of one leaves it alone; the port reads
     the statement as the and of that complement with the multiple
     of sixteen, and HOL4 as the and with the sum, because the two
     give the bitwise operators another precedence (see ISSUES.md,
     "The precedence of a word's bitwise operators") -- both are
     true, and this is the one the port states *)
  (let shl16 = prove
    (`!(v:(N)word). word 16 * v = word_shl v 4`,
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
     REWRITE_TAC[MULT_AC]) in
   let not1 = WORD_RULE `--(word 2):(N)word = word_not (word 1)` in
   DISCH_TAC THEN
   REWRITE_TAC[shl16; not1] THEN
   AP_THM_TAC THEN AP_TERM_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
               BIT_WORD_1; BIT_WORD_SHL] THEN
   X_GEN_TAC `i:num` THEN DISCH_TAC THEN
   ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
   CONV_TAC NUM_REDUCE_CONV THEN TRY(CONV_TAC TAUT)));;

let word_ml_inv_num_lemma = prove
 (`good_dimindex (:'a) ==> (--(n2w 2) && (n2w 4) * v) = (n2w 4) *
  (v:'a word)`,
  (* four times a word has its two lowest bits clear, and -2 is the
     complement of 1, which has only the lowest *)
  (let shl4 = prove
    (`!(v:(N)word). word 4 * v = word_shl v 2`,
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
     REWRITE_TAC[MULT_AC]) in
   let neg2 = prove
    (`word_neg (word 2):(N)word = word_not (word 1)`,
     CONV_TAC WORD_RULE) in
   DISCH_TAC THEN
   REWRITE_TAC[neg2; shl4] THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
               BIT_WORD_1; BIT_WORD_SHL] THEN
   REPEAT STRIP_TAC THEN ASM_CASES_TAC `2 <= i` THEN
   ASM_REWRITE_TAC[] THEN
   ASM_SIMP_TAC[ARITH_RULE `2 <= i ==> ~(i = 0)`]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_ml_inv_num = prove
 (cake_as_vars (fun () ->
    `word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c (dataSem_state_refs
  s) ws /\
      good_dimindex (:'a) /\
      small_enough_int (&n) ==>
      word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c
        (dataSem_state_refs s)
        ((Number (&n),wordLang_Word (n2w (4 * n):'a word)) :: ws)`),
  (* a small enough integer as a root of word_ml_inv: its root is
     the Data of its Smallnum, which abs_ml_inv_Num adds to the
     roots of the abs_ml_inv, and word_addr of that Data is four
     times the integer, because Smallnum of a natural number is
     four times it and the and with the complement of one leaves
     such a word alone *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    let smn = prove
     (`!n. Smallnum (&n) = (n2w (4 * n)):(N)word`,
      GEN_TAC THEN REWRITE_TAC[smallnum_def] THEN
      REWRITE_TAC[INT_ARITH `~((&n:int) < &0)`] THEN
      REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM]) in
    let and4 = prove
     (`!n. word_and (n2w (4 * n)) (word_not (word 1)) =
           (n2w (4 * n)):(N)word`,
      GEN_TAC THEN
      REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
                  BIT_WORD_1] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
      TRY(REWRITE_TAC[BIT_WORD; EXP; DIV_1; ODD_MULT] THEN
        CONV_TAC NUM_REDUCE_CONV THEN NO_TAC) THEN
      TRY(CONV_TAC TAUT)) in
    REWRITE_TAC[word_ml_inv_def] THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    FIRST_X_ASSUM(fun th ->
      if is_exists (concl th) then STRIP_ASSUME_TAC th else fail()) THEN
    SUBGOAL_THEN `small_int (:'a) (&n)` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun se ->
        if hd_is "small_enough_int" (concl se) then MP_TAC se
        else fail()) THEN
      FIRST_ASSUM(fun gd ->
        if hd_is "good_dimindex" (concl gd)
        then MP_TAC(REWRITE_RULE[good_dimindex_def] gd)
        else fail()) THEN
      REWRITE_TAC[small_enough_int_def;
                  small_int_def; dimword] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
      CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC;
      ALL_TAC] THEN
    W(fun (asl,w) ->
      let am = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
      let si = grab asl (fun th -> hd_is "small_int" (concl th)) in
      let nw = MATCH_MP abs_ml_inv_Num (CONJ am si) in
      ASSUME_TAC nw THEN
      EXISTS_TAC
        (fst(dest_pair (el 3 (snd(strip_comb (concl nw))))))) THEN
    ASM_REWRITE_TAC[MAP; FST; SND; ALL2] THEN
    REWRITE_TAC(word_addr_clauses () @ [smn; and4])));;

(* HOL4 data_to_word_memoryProofScript.sml:8032-8033: a theorem that
   HOL4 states as the value of an ML expression: word_ml_inv_zero *)

let word_ml_inv_neg_num_lemma = prove
 (`good_dimindex (:'a) ==> (--(n2w 2) && --(n2w 4) * v) = --(n2w 4) *
  (v:'a word)`,
  (* and so does minus four times a word *)
  (let shl4 = prove
    (`!(v:(N)word). word 4 * v = word_shl v 2`,
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
     REWRITE_TAC[MULT_AC]) in
   let neg2 = prove
    (`word_neg (word 2):(N)word = word_not (word 1)`,
     CONV_TAC WORD_RULE) in
   let nshl4 = prove
    (`!(v:(N)word). word_neg (word 4) * v = word_shl (word_neg v) 2`,
     REWRITE_TAC[GSYM shl4] THEN CONV_TAC WORD_RULE) in
   DISCH_TAC THEN
   REWRITE_TAC[neg2; nshl4] THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
               BIT_WORD_1; BIT_WORD_SHL] THEN
   REPEAT STRIP_TAC THEN ASM_CASES_TAC `2 <= i` THEN
   ASM_REWRITE_TAC[] THEN
   ASM_SIMP_TAC[ARITH_RULE `2 <= i ==> ~(i = 0)`]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_ml_inv_neg_num = prove
 (cake_as_vars (fun () ->
    `word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c (dataSem_state_refs
  s) ws /\
      good_dimindex (:'a) /\
      small_enough_int (--(&n)) /\ ~(n = 0) ==>
      word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c
        (dataSem_state_refs s)
        ((Number (--(&n)),wordLang_Word (--(n2w (4 * n):'a
          word))) :: ws)`),
  (* the root of a negative small number is the Data of its
     Smallnum, which is minus four times the number; its two lowest
     bits are clear, so the complement of one takes nothing off, and
     abs_ml_inv_Num adds the Number to the stack once the bound of
     small_enough_int gives the one of small_int *)
  (
   let waddr = hd (word_addr_clauses ()) in
   let smallneg = prove
    (`~(n = 0) ==> Smallnum (--(&n)) = --(n2w (4 * n)):'a word`,
     DISCH_TAC THEN REWRITE_TAC[smallnum_def] THEN
     SUBGOAL_THEN `--(&n) < (&0:int)` (fun th -> REWRITE_TAC[th]) THENL
      [SUBGOAL_THEN `(&0:int) < &n` MP_TAC THENL
        [REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC;
         INT_ARITH_TAC];
       ALL_TAC] THEN
     SUBGOAL_THEN `num_of_int (&4 * (&0 - --(&n))) = 4 * n`
       SUBST1_TAC THENL
      [REWRITE_TAC[INT_ARITH `&0 - --(&n) = &n:int`;
                   INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM];
       CONV_TAC WORD_RULE]) in
   let andneg = prove
    (`(--(n2w (4 * n)):(N)word) && word_not (n2w 1) =
       --(n2w (4 * n))`,
     let shl4 = prove
      (`!(v:(N)word). word 4 * v = word_shl v 2`,
       REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
       CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
       REWRITE_TAC[MULT_AC]) in
     let nshl = prove
      (`!(k:num). --(n2w (4 * k)):(N)word = word_shl (--(n2w k)) 2`,
       GEN_TAC THEN REWRITE_TAC[GSYM shl4] THEN CONV_TAC WORD_RULE) in
     let and_shl = prove
      (`!(v:(N)word). word_shl v 2 && word_not (word 1) =
                      word_shl v 2`,
       REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
                   BIT_WORD_1; BIT_WORD_SHL] THEN
       REPEAT STRIP_TAC THEN ASM_CASES_TAC `2 <= i` THEN
       ASM_REWRITE_TAC[] THEN
       ASM_SIMP_TAC[ARITH_RULE `2 <= i ==> ~(i = 0)`]) in
     ONCE_REWRITE_TAC[nshl] THEN MATCH_ACCEPT_TAC and_shl) in
   let smalln = prove
    (`good_dimindex (:'a) /\ small_enough_int (--(&n))
        ==> small_int (:'a) (--(&n))`,
     REWRITE_TAC[good_dimindex_def; small_int_def;
                 small_enough_int_def; dimword] THEN
     DISCH_THEN(CONJUNCTS_THEN2
       (DISJ_CASES_THEN SUBST1_TAC) MP_TAC) THEN
     CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC) in
   REWRITE_TAC[word_ml_inv_def] THEN REPEAT STRIP_TAC THEN
   EXISTS_TAC
     `CONS (gc_shared_Data (wordLang_Word
        (Smallnum (--(&n)):'a word))) hs` THEN
   REWRITE_TAC[MAP; ALL2; waddr] THEN REPEAT CONJ_TAC THENL
    [MATCH_MP_TAC abs_ml_inv_Num THEN
     ASM_SIMP_TAC[smalln];
     ASM_SIMP_TAC[smallneg] THEN REWRITE_TAC[andneg];
     FIRST_ASSUM ACCEPT_TAC]));;

let word_list_APPEND = prove
 (`!xs ys a. misc_word_list a (xs ++ ys) =
              misc_word_list a xs * misc_word_list (a + n2w (LENGTH
                xs) * bytes_in_word) ys`,
  (LIST_INDUCT_TAC THEN
   ASM_REWRITE_TAC[APPEND; word_list_def; LENGTH;
                   emp_STAR; STAR_ASSOC; WORD_ADD_SUC_MUL;
                   WORD_ADD_0_MUL]));;

let all_ts_head_eq = prove
 (`!v refs stack' ts.
    v IN all_vs refs stack' ==> all_ts refs stack' = all_ts refs (v
      :: stack')`,
  (* a value that the refs or the stack already hold adds no
     timestamp to the stack, which is what MEM_in_all_ts says of
     the value itself and all_ts_head of the head of a stack *)
  (REPEAT GEN_TAC THEN DISCH_TAC THEN
   ONCE_REWRITE_TAC[all_ts_head] THEN
   MATCH_MP_TAC(SET_RULE `s SUBSET t ==> t = s UNION t`) THEN
   REWRITE_TAC[SUBSET] THEN X_GEN_TAC `u:num` THEN
   REWRITE_TAC[all_ts_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[IN_ELIM_THM; MEM] THEN
   DISCH_THEN(X_CHOOSE_THEN `y:dataSem_v`
     (CONJUNCTS_THEN2
        (DISJ_CASES_THEN2 ASSUME_TAC (SUBST_ALL_TAC o SYM))
        ASSUME_TAC)) THENL
    [EXISTS_TAC `y:dataSem_v` THEN ASM_REWRITE_TAC[];
     MP_TAC(SPECL [`y:dataSem_v`; `u:num`; `stack':(dataSem_v)list`;
                   `refs:(dataSem_v bvlSem_ref) spt`]
       MEM_in_all_ts) THEN
     ASM_REWRITE_TAC[] THEN
     REWRITE_TAC[all_ts_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[IN_ELIM_THM]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_El' = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((Block ts' tag vals,ptr) :: vars) /\
      good_dimindex (:'a) /\
      index < LENGTH vals ==>
      (?ptr_w i_w (x:'a word).
        ptr = wordLang_Word ptr_w /\
        get_real_addr c st ptr_w = SOME x /\
        (x + bytes_in_word + bytes_in_word * n2w index) IN dm /\
        memory_rel c be ts refs sp st m dm
          ((EL index vals,m (x + bytes_in_word + bytes_in_word *
            n2w index)) ::
           (Block ts' tag vals,ptr) :: vars))`),
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
 let rec facs t =
   if hd_is "STAR" t then
     let args = snd(strip_comb t) in
     facs (el 0 args) @ facs (el 1 args)
   else [t] in
 let rec remove1 t = function
     [] -> []
   | h :: rest -> if h = t then rest else h :: remove1 t rest in
 let grab asl p =
   tryfind (fun (_,th) ->
     if (try p th with Failure _ -> false) then th else fail())
     asl in
 let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
 let swapmul a =
   let args = snd(strip_comb (rand a)) in
   let mul = fst(strip_comb (rand a)) in
   mk_comb(rator a, mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
 let realaddr =
   W(fun (asl,w) ->
     let hl = grab asl is_hl in
     let hlen = grab asl (fun th ->
       hd_is "heap_length" (lhand (concl th))) in
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
     let gd = grab asl (fun th ->
       hd_is "good_dimindex" (concl th)) in
     let gat = tryfind (fun t ->
       find_term (fun u ->
         hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
       (w :: map (fun (_,th) -> concl th) asl) in
     let mm = MATCH_MP get_real_addr_get_addr
                (CONJ hlen (CONJ hl (CONJ cu gd))) in
     let wv = find (fun v -> fst(dest_var v) = "w")
                (frees (concl mm)) in
     let th = SPEC (last (snd(strip_comb gat))) (GEN wv mm) in
     let a = rand (rhs (concl (CONJUNCT1 th))) in
     EXISTS_TAC (swapmul a) THEN
     STRIP_ASSUME_TAC(REWRITE_RULE[WORD_RULE (mk_eq(a,swapmul a))]
                        th)) in
   let all2cons = prove
    (`!P h t (l:(A)list).
        ALL2 P l (CONS (h:B) t) <=>
        ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   let addreq = WORD_RULE
     `!(a:(N)word) i.
        (a + bytes_in_word) + n2w i * bytes_in_word =
        a + bytes_in_word + bytes_in_word * n2w i` in
   (* the element of a heap that an address and an index name *)
   let heapel = prove
    (`!a u n (heap:(('a,'b)heap_element)list) xs l d y.
        heap_lookup a heap = SOME (DataElement xs l d) /\
        n < LENGTH xs /\
        heap_el (gc_shared_Pointer a u) n heap = (y,T)
        ==> y = EL n xs`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
     REWRITE_TAC[heap_el_def] THEN
     MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[] THEN
     MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[PAIR_EQ] THEN
     REWRITE_TAC[injectivity "option"; injectivity "heap_element";
                 PAIR_EQ] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL] THEN
     ASM_REWRITE_TAC[PAIR_EQ] THEN
     DISCH_THEN(ACCEPT_TAC o SYM)) in
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   SUBGOAL_THEN `~(vals:(dataSem_v)list = [])` ASSUME_TAC THENL
    [DISCH_TAC THEN VAR_EQ_TAC THEN
     FIRST_X_ASSUM(fun th ->
       if (try hd_is "<" (concl th) with Failure _ -> false)
       then MP_TAC(REWRITE_RULE[LENGTH; LT] th) else fail()) THEN
     REWRITE_TAC[];
     ALL_TAC] THEN
   FIRST_ASSUM(fun mr ->
     if hd_is "memory_rel" (concl mr)
     then MP_TAC(REWRITE_RULE[memory_rel_def;
                              word_ml_inv_def; MAP; FST] mr)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[MAP; all2cons] a2) else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_ASSUM(fun am ->
     if hd_is "abs_ml_inv" (concl am)
     then MP_TAC(REWRITE_RULE[abs_ml_inv_def;
                              bc_stack_ref_inv_def] am)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2) &&
        can (find_term (hd_is "v_inv")) (concl a2)
     then MP_TAC(REWRITE_RULE[ALL2; NOT_CONS_NIL; HD; TL] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi)
     then MP_TAC(REWRITE_RULE[v_inv_def] vi)
     else fail()) THEN
   ASM_REWRITE_TAC[] THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
   REWRITE_TAC(word_addr_clauses ()) THEN
   W(fun (asl,w) ->
     let vs,bod = strip_exists w in
     EXISTS_TAC (rand (lhs (hd (conjuncts bod))))) THEN
   REWRITE_TAC[] THEN
   FIRST_ASSUM(fun th ->
     if hd_is "heap_in_memory_store" (concl th)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   realaddr THEN
   FIRST_ASSUM(fun lr ->
     if hd_is "ALL2" (concl lr) &&
        can (find_term (hd_is "v_inv")) (concl lr)
     then ASSUME_TAC(MATCH_MP LIST_REL_LENGTH lr) else fail()) THEN
   W(fun (asl,w) ->
     let lt = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
     let le = grab asl (fun th ->
       hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
       hd_is "LENGTH" (rhs (concl th))) in
     MP_TAC(MATCH_MP LESS_LENGTH
              (REWRITE_RULE[le] lt))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   W(fun (asl,w) ->
     MP_TAC(MATCH_MP heap_lookup_SPLIT
              (grab asl is_hl))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def;
               BlockRep_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
               word_list_def; LENGTH_MAP] THEN
   ASM_REWRITE_TAC[addreq] THEN
   W(fun (asl,w) ->
     let addr = lhand (hd (conjuncts (rand w))) in
     let pred = rator (lhand w) in
     let fs = facs pred in
     let one = find (fun t ->
       hd_is "set_sep_one" t && fst(dest_pair (rand t)) = addr) fs in
     let rest = remove1 one fs in
     let st = fst(strip_comb pred) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     SUBGOAL_THEN (mk_eq(pred, mk one (end_itlist mk rest)))
       SUBST1_TAC THENL [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
   DISCH_THEN(fun sep ->
     STRIP_ASSUME_TAC(MATCH_MP read_fun2set sep)) THEN
   ASM_REWRITE_TAC[] THEN
   W(fun (asl,w) ->
     let am = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
     let lt = grab asl (fun th ->
       hd_is "<" (concl th) &&
       hd_is "LENGTH" (rand (concl th)) &&
       fst(dest_var(rand(rand(concl th)))) = "vals") in
     MP_TAC(MATCH_MP el_thm (CONJ am lt))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[CONS_11]) THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
   VAR_EQ_TAC THEN
   W(fun (asl,w) ->
     let hl = REWRITE_RULE[BlockRep_def] (grab asl is_hl) in
     let he = REWRITE_RULE[BlockRep_def]
                (grab asl (fun th ->
                   hd_is "heap_el" (lhs (concl th)))) in
     let le = grab asl (fun th ->
       hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
       hd_is "LENGTH" (rhs (concl th))) in
     let n = el 1 (snd(strip_comb (lhs (concl he)))) in
     let lt = prove(mk_binop `(<):num->num->bool` n
                      (rhs (concl le)),
                    REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
                    ARITH_TAC) in
     SUBST_ALL_TAC(REWRITE_RULE[EL_APPEND; LT_REFL; SUB_REFL; EL; HD]
       (MATCH_MP heapel (CONJ hl (CONJ lt he))))) THEN
   REWRITE_TAC[memory_rel_def] THEN
   W(fun (asl,w) ->
     let hm = grab asl (fun th ->
       hd_is "heap_in_memory_store" (concl th)) in
     let args = snd(strip_comb (concl hm)) in
     EXISTS_TAC (el 0 args) THEN EXISTS_TAC (el 9 args) THEN
     EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
     EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args)) THEN
   ASM_REWRITE_TAC[word_ml_inv_def] THEN
   REWRITE_TAC[MAP; FST; SND] THEN
   W(fun (asl,w) ->
     let am = grab asl (fun th ->
       hd_is "abs_ml_inv" (concl th) &&
       hd_is "EL" (lhand (el 1 (snd(strip_comb (concl th)))))) in
     EXISTS_TAC
       (fst(dest_pair (el 3 (snd(strip_comb (concl am))))))) THEN
   ASM_REWRITE_TAC[MAP; ALL2; HD; TL; NOT_CONS_NIL] THEN
   REWRITE_TAC(word_addr_clauses ())));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_El = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((Block ts' tag vals,ptr) :: (Number (&index),i) :: vars) /\
      good_dimindex (:'a) /\
      index < LENGTH vals ==>
      (?ptr_w i_w x (y:'a word).
        ptr = wordLang_Word ptr_w /\ i = wordLang_Word i_w /\
        get_real_addr c st ptr_w = SOME x /\
        get_real_offset i_w = SOME y /\
        (x + y) IN dm /\
        memory_rel c be ts refs sp st m dm
          ((EL index vals,m (x + y)) ::
           (Block ts' tag vals,ptr) :: (Number (&index),i) ::
             vars))`),
  (* an element of a block at an index that a Number root holds:
     memory_rel_El' with the index read off that root.  Its v_inv
     is the small-integer case, because the condition of the
     payload says that the header encodes the length of the block,
     which is above the index, and such a length is below two to
     the dimindex less four; and then the word of the root is four
     times the index, which get_real_offset_thm turns into the
     offset of the element *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let rec facs t =
      if hd_is "STAR" t then
        let args = snd(strip_comb t) in
        facs (el 0 args) @ facs (el 1 args)
      else [t] in
    let rec remove1 t = function
        [] -> []
      | h :: rest -> if h = t then rest else h :: remove1 t rest in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
    let swapmul a =
      let args = snd(strip_comb (rand a)) in
      let mul = fst(strip_comb (rand a)) in
      mk_comb(rator a, mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
    let sepfront names =
      W(fun (asl,w) ->
        let pred = rator (lhand w) in
        let fs = facs pred in
        let picked = map (fun n -> find (hd_is n) fs) names in
        let rest = filter (fun t -> not (mem t picked)) fs in
        let st = fst(strip_comb pred) in
        let mk a b = mk_comb(mk_comb(st,a),b) in
        let target = itlist mk picked (end_itlist mk rest) in
        SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
         [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
    let all2cons = prove
     (`!P h t (l:(A)list).
         ALL2 P l (CONS (h:B) t) <=>
         ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
      REPEAT GEN_TAC THEN
      STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
      REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
    let addreq = WORD_RULE
      `!(a:(N)word) i.
         (a + bytes_in_word) + n2w i * bytes_in_word =
         a + bytes_in_word + bytes_in_word * n2w i` in
    (* the element of a heap that an address and an index name *)
    let heapel = prove
     (`!a u n (heap:(('a,'b)heap_element)list) xs l d y.
         heap_lookup a heap = SOME (DataElement xs l d) /\
         n < LENGTH xs /\
         heap_el (gc_shared_Pointer a u) n heap = (y,T)
         ==> y = EL n xs`,
      REPEAT GEN_TAC THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
      REWRITE_TAC[heap_el_def] THEN
      MATCH_REDUCE_TAC THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_REDUCE_TAC THEN
      ASM_REWRITE_TAC[PAIR_EQ] THEN
      REWRITE_TAC[injectivity "option"; injectivity "heap_element";
                  PAIR_EQ] THEN
      CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
      REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL] THEN
      ASM_REWRITE_TAC[PAIR_EQ] THEN
      DISCH_THEN(ACCEPT_TAC o SYM)) in
    (* the Smallnum of a natural number is four times it, and the and
       with the complement of one leaves such a word alone *)
    let smn = prove
     (`!n. Smallnum (&n) = (n2w (4 * n)):(N)word`,
      GEN_TAC THEN REWRITE_TAC[smallnum_def] THEN
      REWRITE_TAC[INT_ARITH `~((&n:int) < &0)`] THEN
      REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM]) in
    let and4 = prove
     (`!n. word_and (n2w (4 * n)) (word_not (word 1)) =
           (n2w (4 * n)):(N)word`,
      GEN_TAC THEN
      REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
                  BIT_WORD_1] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
      TRY(REWRITE_TAC[BIT_WORD; EXP; DIV_1; ODD_MULT] THEN
        CONV_TAC NUM_REDUCE_CONV THEN NO_TAC) THEN
      TRY(CONV_TAC TAUT)) in
    (* the address of the heap element, without the existential of
       the goal: this proof fills the existentials at the end *)
    let realaddr_noex =
      W(fun (asl,w) ->
        let hl = grab asl is_hl in
        let hlen = grab asl (fun th ->
          hd_is "heap_length" (lhand (concl th))) in
        let cu = grab asl (fun th ->
          hd_is "FLOOKUP" (lhs (concl th)) &&
          fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
        let gd = grab asl (fun th ->
          hd_is "good_dimindex" (concl th)) in
        let gat = tryfind (fun t ->
          find_term (fun u ->
            hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
          (w :: map (fun (_,th) -> concl th) asl) in
        let mm = MATCH_MP get_real_addr_get_addr
                   (CONJ hlen (CONJ hl (CONJ cu gd))) in
        let wv = find (fun v -> fst(dest_var v) = "w")
                   (frees (concl mm)) in
        let th = SPEC (last (snd(strip_comb gat))) (GEN wv mm) in
        let a = rand (rhs (concl (CONJUNCT1 th))) in
        STRIP_ASSUME_TAC(REWRITE_RULE[WORD_RULE (mk_eq(a,swapmul a))]
                           th)) in
    let offeq = WORD_RULE
      `!(x:(N)word) i.
         x + (bytes_in_word + n2w i * bytes_in_word) =
         x + bytes_in_word + bytes_in_word * n2w i` in
    (* the length a header encodes is below two to the dimindex less
       four, and an index into such a list is a small integer *)
    let enchdr = prove
     (`!c tag len (h:'a word).
         encode_header c tag len = SOME h
         ==> len < 2 EXP (dimindex (:'a) - 4)`,
      REPEAT GEN_TAC THEN REWRITE_TAC[encode_header_def] THEN
      COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
      DISCH_THEN(K ALL_TAC) THEN ASM_REWRITE_TAC[]) in
    let smallidx = prove
     (`!(i:num) n.
         good_dimindex (:'a) /\ i < n /\
         n < 2 EXP (dimindex (:'a) - 4)
         ==> small_int (:'a) (&i)`,
      REPEAT GEN_TAC THEN
      REWRITE_TAC[small_int_def; dimword;
                  good_dimindex_def] THEN
      DISCH_THEN(CONJUNCTS_THEN2 MP_TAC STRIP_ASSUME_TAC) THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
      RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
      CONV_TAC NUM_REDUCE_CONV THEN
      CONJ_TAC THEN
      TRY(MATCH_MP_TAC INT_LE_TRANS THEN EXISTS_TAC `&0:int` THEN
          REWRITE_TAC[INT_POS; INT_NEG_LE0; INT_POS] THEN NO_TAC) THEN
      REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    SUBGOAL_THEN `~(vals:(dataSem_v)list = [])` ASSUME_TAC THENL
     [DISCH_TAC THEN VAR_EQ_TAC THEN
      FIRST_X_ASSUM(fun th ->
        if (try hd_is "<" (concl th) with Failure _ -> false)
        then MP_TAC(REWRITE_RULE[LENGTH; LT] th) else fail()) THEN
      REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_ASSUM(fun mr ->
      if hd_is "memory_rel" (concl mr)
      then MP_TAC(REWRITE_RULE[memory_rel_def;
                               word_ml_inv_def; MAP; FST] mr)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun a2 ->
      if hd_is "ALL2" (concl a2)
      then MP_TAC(REWRITE_RULE[MAP; all2cons] a2) else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    VAR_EQ_TAC THEN
    FIRST_ASSUM(fun am ->
      if hd_is "abs_ml_inv" (concl am)
      then MP_TAC(REWRITE_RULE[abs_ml_inv_def;
                               bc_stack_ref_inv_def] am)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun a2 ->
      if hd_is "ALL2" (concl a2) &&
         can (find_term (hd_is "v_inv")) (concl a2)
      then MP_TAC(REWRITE_RULE[ALL2; NOT_CONS_NIL; HD; TL] a2)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun vi ->
      if hd_is "v_inv" (concl vi) &&
         hd_is "dataSem_Block" (el 1 (snd(strip_comb (concl vi))))
      then MP_TAC(REWRITE_RULE[v_inv_def] vi)
      else fail()) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "gc_shared_Pointer" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
    REWRITE_TAC(word_addr_clauses ()) THEN
    FIRST_ASSUM(fun th ->
      if hd_is "heap_in_memory_store" (concl th)
      then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    realaddr_noex THEN
    FIRST_ASSUM(fun lr ->
      if hd_is "ALL2" (concl lr) &&
         can (find_term (hd_is "v_inv")) (concl lr)
      then ASSUME_TAC(MATCH_MP LIST_REL_LENGTH lr) else fail()) THEN
    W(fun (asl,w) ->
      let lt = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
      let le = grab asl (fun th ->
        hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
        hd_is "LENGTH" (rhs (concl th))) in
      MP_TAC(MATCH_MP LESS_LENGTH
               (REWRITE_RULE[le] lt))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    VAR_EQ_TAC THEN
    W(fun (asl,w) ->
      MP_TAC(MATCH_MP heap_lookup_SPLIT
               (grab asl is_hl))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    VAR_EQ_TAC THEN
    FIRST_X_ASSUM(fun th ->
      if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
      then MP_TAC th else fail()) THEN
    REWRITE_TAC[word_heap_APPEND; word_heap_def;
                BlockRep_def] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_el_def] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_payload_def] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
                word_list_def; LENGTH_MAP] THEN
    ASM_REWRITE_TAC[addreq] THEN
    (* the condition of the payload says what the header encodes *)
    REPEAT(sepfront ["cond"] THEN REWRITE_TAC[cond_STAR] THEN
           DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC)) THEN
    W(fun (asl,w) ->
      let ga = grab asl (fun th ->
        hd_is "get_real_addr" (lhs (concl th))) in
      let base = rand (rhs (concl ga)) in
      let pred = rator (lhand w) in
      let fs = facs pred in
      let one = find (fun t ->
        hd_is "set_sep_one" t &&
        not (fst(dest_pair (rand t)) = base)) fs in
      let rest = remove1 one fs in
      let st = fst(strip_comb pred) in
      let mk a b = mk_comb(mk_comb(st,a),b) in
      SUBGOAL_THEN (mk_eq(pred, mk one (end_itlist mk rest)))
        SUBST1_TAC THENL [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
    DISCH_THEN(fun sep ->
      STRIP_ASSUME_TAC(MATCH_MP read_fun2set sep)) THEN
    ASM_REWRITE_TAC[] THEN
    (* the index is a small integer, because it is below the length
       that the header of the block encodes *)
    W(fun (asl,w) ->
      let eh = grab asl (fun th ->
        hd_is "encode_header" (lhs (concl th))) in
      let lt = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th)) &&
        hd_is "LENGTH" (rand (concl th))) in
      let le = grab asl (fun th ->
        hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
        hd_is "LENGTH" (rhs (concl th))) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      ASSUME_TAC(MATCH_MP smallidx
        (CONJ gd (CONJ (REWRITE_RULE[le] lt)
                       (MATCH_MP enchdr eh))))) THEN
    FIRST_X_ASSUM(fun vi ->
      if hd_is "v_inv" (concl vi) &&
         hd_is "dataSem_Number" (el 1 (snd(strip_comb (concl vi))))
      then MP_TAC(REWRITE_RULE[v_inv_def] vi)
      else fail()) THEN
    FIRST_ASSUM(fun si ->
      if hd_is "small_int" (concl si) then REWRITE_TAC[si]
      else fail()) THEN
    DISCH_THEN(fun eq ->
      RULE_ASSUM_TAC(REWRITE_RULE[eq]) THEN REWRITE_TAC[eq]) THEN
    RULE_ASSUM_TAC(REWRITE_RULE
      (word_addr_clauses () @ [smn; and4])) THEN
    REWRITE_TAC(word_addr_clauses () @ [smn; and4]) THEN
    W(fun (asl,w) ->
      let am = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
      let lt = grab asl (fun th ->
        hd_is "<" (concl th) &&
        hd_is "LENGTH" (rand (concl th)) &&
        fst(dest_var(rand(rand(concl th)))) = "vals") in
      MP_TAC(MATCH_MP el_thm (CONJ am lt))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[CONS_11]) THEN
    REPEAT(FIRST_X_ASSUM(fun th ->
      if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
    VAR_EQ_TAC THEN
    W(fun (asl,w) ->
      let hl = REWRITE_RULE[BlockRep_def] (grab asl is_hl) in
      let he = REWRITE_RULE[BlockRep_def]
                 (grab asl (fun th ->
                    hd_is "heap_el" (lhs (concl th)))) in
      let le = grab asl (fun th ->
        hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
        hd_is "LENGTH" (rhs (concl th))) in
      let n = el 1 (snd(strip_comb (lhs (concl he)))) in
      let lt = prove(mk_binop `(<):num->num->bool` n
                       (rhs (concl le)),
                     REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
                     ARITH_TAC) in
      SUBST_ALL_TAC(REWRITE_RULE[EL_APPEND; LT_REFL; SUB_REFL; EL; HD]
        (MATCH_MP heapel (CONJ hl (CONJ lt he))))) THEN
    W(fun (asl,w) ->
      let cs = conjuncts (snd(strip_exists w)) in
      let ga = grab asl (fun th ->
        hd_is "get_real_addr" (lhs (concl th))) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let ro0 = MATCH_MP get_real_offset_thm gd in
      let iv = find (fun v -> type_of v = `:num`) (frees (concl ro0)) in
      let ro = INST [rand (rand (rand (lhs (el 1 cs)))),iv] ro0 in
      EXISTS_TAC (rand (lhs (el 0 cs))) THEN
      EXISTS_TAC (rand (lhs (el 1 cs))) THEN
      EXISTS_TAC (rand (rhs (concl ga))) THEN
      EXISTS_TAC (rand (rhs (concl ro))) THEN
      ASM_REWRITE_TAC[ro; offeq]) THEN
    REWRITE_TAC[memory_rel_def] THEN
    W(fun (asl,w) ->
      let hm = grab asl (fun th ->
        hd_is "heap_in_memory_store" (concl th)) in
      let args = snd(strip_comb (concl hm)) in
      EXISTS_TAC (el 0 args) THEN EXISTS_TAC (el 9 args) THEN
      EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
      EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args)) THEN
    ASM_REWRITE_TAC[word_ml_inv_def] THEN
    REWRITE_TAC[MAP; FST; SND] THEN
    W(fun (asl,w) ->
      let am = grab asl (fun th ->
        hd_is "abs_ml_inv" (concl th) &&
        hd_is "EL" (lhand (el 1 (snd(strip_comb (concl th)))))) in
      EXISTS_TAC
        (fst(dest_pair (el 3 (snd(strip_comb (concl am))))))) THEN
    ASM_REWRITE_TAC[MAP; ALL2; HD; TL; NOT_CONS_NIL] THEN
    REWRITE_TAC(word_addr_clauses () @ [and4])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_swap = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm (x :: y :: z) ==>
     memory_rel c be ts refs sp st m dm (y :: x :: z)`),
  (DISCH_TAC THEN
   FIRST_ASSUM(fun th ->
     MATCH_MP_TAC(MATCH_MP
       (ONCE_REWRITE_RULE[TAUT `(p ==> q ==> r) <=> (q ==> p ==> r)`]
          memory_rel_rearrange) th)) THEN
   REWRITE_TAC[MEM] THEN MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Deref' = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl nn,ptr) :: vars) /\
      lookup nn refs = SOME (ValueArray vals) /\
      good_dimindex (:'a) /\
      index < LENGTH vals ==>
      (?ptr_w (x:'a word).
        ptr = wordLang_Word ptr_w /\
        get_real_addr c st ptr_w = SOME x /\
        (x + bytes_in_word + bytes_in_word * n2w index) IN dm /\
        memory_rel c be ts refs sp st m dm
          ((EL index vals,m (x + bytes_in_word + bytes_in_word *
            n2w index)) ::
           (RefPtr bl nn,ptr) :: vars))`),
  (* an element of a reference's array, read out of the memory: the
     same shape as memory_rel_El', with bc_ref_inv's RefBlock in
     place of the Block's BlockRep and deref_thm in place of
     el_thm.  The thunk rules of v_inv are out because the
     reference holds a ValueArray, and the address of the element
     is the pointer of the root, which is not a variable here, so
     the heap's split has to be substituted by hand *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
 let rec facs t =
   if hd_is "STAR" t then
     let args = snd(strip_comb t) in
     facs (el 0 args) @ facs (el 1 args)
   else [t] in
 let rec remove1 t = function
     [] -> []
   | h :: rest -> if h = t then rest else h :: remove1 t rest in
 let grab asl p =
   tryfind (fun (_,th) ->
     if (try p th with Failure _ -> false) then th else fail())
     asl in
 let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
 let killthunk =
   TRY(FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 ->
     CONTR_TAC(REWRITE_RULE[injectivity "option";
                            distinctness "bvlSem_ref"]
                 (TRANS (SYM t1) t2))))) in
 let refinv ptr root =
   FIRST_X_ASSUM(fun th ->
     if is_forall (concl th) &&
        hd_is "bc_ref_inv" (rand (snd(strip_forall(concl th))))
     then MP_TAC(SPEC ptr th) else fail()) THEN
   ANTS_TAC THENL
    [CONJ_TAC THENL
      [REWRITE_TAC[reachable_refs_def; MEM] THEN
       EXISTS_TAC root THEN EXISTS_TAC ptr THEN
       REWRITE_TAC[get_refs_def; MEM;
                   CONJUNCT1(SPEC_ALL RTC_RULES)];
       ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
   REWRITE_TAC[bc_ref_inv_def] THEN
   ASM_SIMP_TAC[FLOOKUP_DEF] THEN
   MATCH_REDUCE_TAC in
 let swapmul a =
   let args = snd(strip_comb (rand a)) in
   let mul = fst(strip_comb (rand a)) in
   mk_comb(rator a, mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
 let realaddr =
   W(fun (asl,w) ->
     let hl = grab asl is_hl in
     let hlen = grab asl (fun th ->
       hd_is "heap_length" (lhand (concl th))) in
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
     let gd = grab asl (fun th ->
       hd_is "good_dimindex" (concl th)) in
     let gat = tryfind (fun t ->
       find_term (fun u ->
         hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
       (w :: map (fun (_,th) -> concl th) asl) in
     let mm = MATCH_MP get_real_addr_get_addr
                (CONJ hlen (CONJ hl (CONJ cu gd))) in
     let wv = find (fun v -> fst(dest_var v) = "w")
                (frees (concl mm)) in
     let th = SPEC (last (snd(strip_comb gat))) (GEN wv mm) in
     let a = rand (rhs (concl (CONJUNCT1 th))) in
     EXISTS_TAC (swapmul a) THEN
     STRIP_ASSUME_TAC(REWRITE_RULE[WORD_RULE (mk_eq(a,swapmul a))]
                        th)) in
   let all2cons = prove
    (`!P h t (l:(A)list).
        ALL2 P l (CONS (h:B) t) <=>
        ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   let addreq = WORD_RULE
     `!(a:(N)word) i.
        (a + bytes_in_word) + n2w i * bytes_in_word =
        a + bytes_in_word + bytes_in_word * n2w i` in
   (* the element of a heap that an address and an index name *)
   let heapel = prove
    (`!a u n (heap:(('a,'b)heap_element)list) xs l d y.
        heap_lookup a heap = SOME (DataElement xs l d) /\
        n < LENGTH xs /\
        heap_el (gc_shared_Pointer a u) n heap = (y,T)
        ==> y = EL n xs`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
     REWRITE_TAC[heap_el_def] THEN
     MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[] THEN
     MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[PAIR_EQ] THEN
     REWRITE_TAC[injectivity "option"; injectivity "heap_element";
                 PAIR_EQ] THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
     REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL] THEN
     ASM_REWRITE_TAC[PAIR_EQ] THEN
     DISCH_THEN(ACCEPT_TAC o SYM)) in
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   SUBGOAL_THEN `~(vals:(dataSem_v)list = [])` ASSUME_TAC THENL
    [DISCH_TAC THEN VAR_EQ_TAC THEN
     FIRST_X_ASSUM(fun th ->
       if (try hd_is "<" (concl th) with Failure _ -> false)
       then MP_TAC(REWRITE_RULE[LENGTH; LT] th) else fail()) THEN
     REWRITE_TAC[];
     ALL_TAC] THEN
   FIRST_ASSUM(fun mr ->
     if hd_is "memory_rel" (concl mr)
     then MP_TAC(REWRITE_RULE[memory_rel_def;
                              word_ml_inv_def; MAP; FST] mr)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[MAP; all2cons] a2) else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_ASSUM(fun am ->
     if hd_is "abs_ml_inv" (concl am)
     then MP_TAC(REWRITE_RULE[abs_ml_inv_def;
                              bc_stack_ref_inv_def] am)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2) &&
        can (find_term (hd_is "v_inv")) (concl a2)
     then MP_TAC(REWRITE_RULE[ALL2; NOT_CONS_NIL; HD; TL] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi)
     then MP_TAC(REWRITE_RULE[v_inv_def] vi)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   killthunk THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
   REWRITE_TAC(word_addr_clauses ()) THEN
   W(fun (asl,w) ->
     let vs,bod = strip_exists w in
     EXISTS_TAC (rand (lhs (hd (conjuncts bod))))) THEN
   REWRITE_TAC[] THEN
   refinv `nn:num` `RefPtr bl nn:dataSem_v` THEN
   ASM_REWRITE_TAC[] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_ASSUM(fun th ->
     if hd_is "heap_in_memory_store" (concl th)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   realaddr THEN
   FIRST_ASSUM(fun lr ->
     if hd_is "ALL2" (concl lr) &&
        can (find_term (hd_is "v_inv")) (concl lr)
     then ASSUME_TAC(MATCH_MP LIST_REL_LENGTH lr) else fail()) THEN
   W(fun (asl,w) ->
     let lt = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
     let le = grab asl (fun th ->
       hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
       hd_is "LENGTH" (rhs (concl th))) in
     MP_TAC(MATCH_MP LESS_LENGTH
              (REWRITE_RULE[GSYM le] lt))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   W(fun (asl,w) ->
     MP_TAC(MATCH_MP heap_lookup_SPLIT
              (grab asl is_hl))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   TRY(FIRST_X_ASSUM(fun th ->
     if (try hd_is "fmap_apply" (lhs (concl th))
         with Failure _ -> false)
     then SUBST_ALL_TAC th else fail())) THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def;
               RefBlock_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
               word_list_def; LENGTH_MAP] THEN
   ASM_REWRITE_TAC[addreq] THEN
   W(fun (asl,w) ->
     let addr = lhand (hd (conjuncts (rand w))) in
     let pred = rator (lhand w) in
     let fs = facs pred in
     let one = find (fun t ->
       hd_is "set_sep_one" t && fst(dest_pair (rand t)) = addr) fs in
     let rest = remove1 one fs in
     let st = fst(strip_comb pred) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     SUBGOAL_THEN (mk_eq(pred, mk one (end_itlist mk rest)))
       SUBST1_TAC THENL [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
   DISCH_THEN(fun sep ->
     STRIP_ASSUME_TAC(MATCH_MP read_fun2set sep)) THEN
   ASM_REWRITE_TAC[] THEN
   W(fun (asl,w) ->
     let am = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
     MP_TAC(MATCH_MP deref_thm am)) THEN
   ASM_REWRITE_TAC[THE] THEN
   MATCH_REDUCE_TAC THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   W(fun (asl,w) ->
     let fa = grab asl (fun th ->
       is_forall (concl th) &&
       can (find_term (hd_is "heap_el")) (concl th)) in
     let lt = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
     MP_TAC(MP (SPEC (lhand (concl lt)) fa) lt)) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[CONS_11]) THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
   VAR_EQ_TAC THEN
   W(fun (asl,w) ->
     let hl = REWRITE_RULE[RefBlock_def] (grab asl is_hl) in
     let he = REWRITE_RULE[RefBlock_def]
                (grab asl (fun th ->
                   hd_is "heap_el" (lhs (concl th)))) in
     let n = el 1 (snd(strip_comb (lhs (concl he)))) in
     let len = el 1 (snd(strip_comb (rand (rhs (concl hl))))) in
     let lt = prove(mk_binop `(<):num->num->bool` n len,
                    REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
                    ARITH_TAC) in
     SUBST_ALL_TAC(REWRITE_RULE[EL_APPEND; LT_REFL; SUB_REFL; EL; HD]
       (MATCH_MP heapel (CONJ hl (CONJ lt he))))) THEN
   REWRITE_TAC[memory_rel_def] THEN
   W(fun (asl,w) ->
     let hm = grab asl (fun th ->
       hd_is "heap_in_memory_store" (concl th)) in
     let args = snd(strip_comb (concl hm)) in
     EXISTS_TAC (el 0 args) THEN EXISTS_TAC (el 9 args) THEN
     EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
     EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args)) THEN
   ASM_REWRITE_TAC[word_ml_inv_def] THEN
   REWRITE_TAC[MAP; FST; SND] THEN
   W(fun (asl,w) ->
     let am = grab asl (fun th ->
       hd_is "abs_ml_inv" (concl th) &&
       hd_is "EL" (lhand (el 1 (snd(strip_comb (concl th)))))) in
     EXISTS_TAC
       (fst(dest_pair (el 3 (snd(strip_comb (concl am))))))) THEN
   ASM_REWRITE_TAC[MAP; ALL2; HD; TL; NOT_CONS_NIL] THEN
   REWRITE_TAC(word_addr_clauses ())));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Deref = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((RefPtr bl nn,ptr) :: (Number (&index),i) :: vars) /\
      lookup nn refs = SOME (ValueArray vals) /\
      good_dimindex (:'a) /\
      index < LENGTH vals ==>
      (?ptr_w i_w x (y:'a word).
        ptr = wordLang_Word ptr_w /\ i = wordLang_Word i_w /\
        get_real_addr c st ptr_w = SOME x /\
        get_real_offset i_w = SOME y /\
        (x + y) IN dm /\
        memory_rel c be ts refs sp st m dm
          ((EL index vals,m (x + y)) ::
           (RefPtr bl nn,ptr) :: (Number (&index),i) :: vars))`),
  (* an element of a reference's array at an index that a Number
     root holds: memory_rel_Deref' with the index read off that
     root, the same way as memory_rel_El reads it off its own *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let rec facs t =
      if hd_is "STAR" t then
        let args = snd(strip_comb t) in
        facs (el 0 args) @ facs (el 1 args)
      else [t] in
    let rec remove1 t = function
        [] -> []
      | h :: rest -> if h = t then rest else h :: remove1 t rest in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
    let swapmul a =
      let args = snd(strip_comb (rand a)) in
      let mul = fst(strip_comb (rand a)) in
      mk_comb(rator a, mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
    let sepfront names =
      W(fun (asl,w) ->
        let pred = rator (lhand w) in
        let fs = facs pred in
        let picked = map (fun n -> find (hd_is n) fs) names in
        let rest = filter (fun t -> not (mem t picked)) fs in
        let st = fst(strip_comb pred) in
        let mk a b = mk_comb(mk_comb(st,a),b) in
        let target = itlist mk picked (end_itlist mk rest) in
        SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
         [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
    let killthunk =
      TRY(FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 ->
        CONTR_TAC(REWRITE_RULE[injectivity "option";
                               distinctness "bvlSem_ref"]
                    (TRANS (SYM t1) t2))))) in
    let refinv ptr root =
      FIRST_X_ASSUM(fun th ->
        if is_forall (concl th) &&
           hd_is "bc_ref_inv" (rand (snd(strip_forall(concl th))))
        then MP_TAC(SPEC ptr th) else fail()) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [REWRITE_TAC[reachable_refs_def; MEM] THEN
          EXISTS_TAC root THEN EXISTS_TAC ptr THEN
          REWRITE_TAC[get_refs_def; MEM;
                      CONJUNCT1(SPEC_ALL RTC_RULES)];
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      REWRITE_TAC[bc_ref_inv_def] THEN
      ASM_SIMP_TAC[FLOOKUP_DEF] THEN
      MATCH_REDUCE_TAC in
    let all2cons = prove
     (`!P h t (l:(A)list).
         ALL2 P l (CONS (h:B) t) <=>
         ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
      REPEAT GEN_TAC THEN
      STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
      REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
    let addreq = WORD_RULE
      `!(a:(N)word) i.
         (a + bytes_in_word) + n2w i * bytes_in_word =
         a + bytes_in_word + bytes_in_word * n2w i` in
    (* the element of a heap that an address and an index name *)
    let heapel = prove
     (`!a u n (heap:(('a,'b)heap_element)list) xs l d y.
         heap_lookup a heap = SOME (DataElement xs l d) /\
         n < LENGTH xs /\
         heap_el (gc_shared_Pointer a u) n heap = (y,T)
         ==> y = EL n xs`,
      REPEAT GEN_TAC THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
      REWRITE_TAC[heap_el_def] THEN
      MATCH_REDUCE_TAC THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_REDUCE_TAC THEN
      ASM_REWRITE_TAC[PAIR_EQ] THEN
      REWRITE_TAC[injectivity "option"; injectivity "heap_element";
                  PAIR_EQ] THEN
      CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
      REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL] THEN
      ASM_REWRITE_TAC[PAIR_EQ] THEN
      DISCH_THEN(ACCEPT_TAC o SYM)) in
    (* the Smallnum of a natural number is four times it, and the and
       with the complement of one leaves such a word alone *)
    let smn = prove
     (`!n. Smallnum (&n) = (n2w (4 * n)):(N)word`,
      GEN_TAC THEN REWRITE_TAC[smallnum_def] THEN
      REWRITE_TAC[INT_ARITH `~((&n:int) < &0)`] THEN
      REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM]) in
    let and4 = prove
     (`!n. word_and (n2w (4 * n)) (word_not (word 1)) =
           (n2w (4 * n)):(N)word`,
      GEN_TAC THEN
      REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
                  BIT_WORD_1] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
      TRY(REWRITE_TAC[BIT_WORD; EXP; DIV_1; ODD_MULT] THEN
        CONV_TAC NUM_REDUCE_CONV THEN NO_TAC) THEN
      TRY(CONV_TAC TAUT)) in
    (* the address of the heap element, without the existential of
       the goal: this proof fills the existentials at the end *)
    let realaddr_noex =
      W(fun (asl,w) ->
        let hl = grab asl is_hl in
        let hlen = grab asl (fun th ->
          hd_is "heap_length" (lhand (concl th))) in
        let cu = grab asl (fun th ->
          hd_is "FLOOKUP" (lhs (concl th)) &&
          fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
        let gd = grab asl (fun th ->
          hd_is "good_dimindex" (concl th)) in
        let gat = tryfind (fun t ->
          find_term (fun u ->
            hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
          (w :: map (fun (_,th) -> concl th) asl) in
        let mm = MATCH_MP get_real_addr_get_addr
                   (CONJ hlen (CONJ hl (CONJ cu gd))) in
        let wv = find (fun v -> fst(dest_var v) = "w")
                   (frees (concl mm)) in
        let th = SPEC (last (snd(strip_comb gat))) (GEN wv mm) in
        let a = rand (rhs (concl (CONJUNCT1 th))) in
        STRIP_ASSUME_TAC(REWRITE_RULE[WORD_RULE (mk_eq(a,swapmul a))]
                           th)) in
    let offeq = WORD_RULE
      `!(x:(N)word) i.
         x + (bytes_in_word + n2w i * bytes_in_word) =
         x + bytes_in_word + bytes_in_word * n2w i` in
    let smallidx = prove
     (`!(i:num) n.
         good_dimindex (:'a) /\ i < n /\
         n < 2 EXP (dimindex (:'a) - 4)
         ==> small_int (:'a) (&i)`,
      REPEAT GEN_TAC THEN
      REWRITE_TAC[small_int_def; dimword;
                  good_dimindex_def] THEN
      DISCH_THEN(CONJUNCTS_THEN2 MP_TAC STRIP_ASSUME_TAC) THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
      RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
      CONV_TAC NUM_REDUCE_CONV THEN
      CONJ_TAC THEN
      TRY(MATCH_MP_TAC INT_LE_TRANS THEN EXISTS_TAC `&0:int` THEN
          REWRITE_TAC[INT_POS; INT_NEG_LE0; INT_POS] THEN NO_TAC) THEN
      REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    SUBGOAL_THEN `~(vals:(dataSem_v)list = [])` ASSUME_TAC THENL
     [DISCH_TAC THEN VAR_EQ_TAC THEN
      FIRST_X_ASSUM(fun th ->
        if (try hd_is "<" (concl th) with Failure _ -> false)
        then MP_TAC(REWRITE_RULE[LENGTH; LT] th) else fail()) THEN
      REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_ASSUM(fun mr ->
      if hd_is "memory_rel" (concl mr)
      then MP_TAC(REWRITE_RULE[memory_rel_def;
                               word_ml_inv_def; MAP; FST] mr)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun a2 ->
      if hd_is "ALL2" (concl a2)
      then MP_TAC(REWRITE_RULE[MAP; all2cons] a2) else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    VAR_EQ_TAC THEN
    FIRST_ASSUM(fun am ->
      if hd_is "abs_ml_inv" (concl am)
      then MP_TAC(REWRITE_RULE[abs_ml_inv_def;
                               bc_stack_ref_inv_def] am)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun a2 ->
      if hd_is "ALL2" (concl a2) &&
         can (find_term (hd_is "v_inv")) (concl a2)
      then MP_TAC(REWRITE_RULE[ALL2; NOT_CONS_NIL; HD; TL] a2)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun vi ->
      if hd_is "v_inv" (concl vi) &&
         hd_is "dataSem_RefPtr" (el 1 (snd(strip_comb (concl vi))))
      then MP_TAC(REWRITE_RULE[v_inv_def] vi)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    killthunk THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "gc_shared_Pointer" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
    REWRITE_TAC(word_addr_clauses ()) THEN
    refinv `nn:num` `RefPtr bl nn:dataSem_v` THEN
    ASM_REWRITE_TAC[] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_ASSUM(fun th ->
      if hd_is "heap_in_memory_store" (concl th)
      then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    realaddr_noex THEN
    FIRST_ASSUM(fun lr ->
      if hd_is "ALL2" (concl lr) &&
         can (find_term (hd_is "v_inv")) (concl lr)
      then ASSUME_TAC(MATCH_MP LIST_REL_LENGTH lr) else fail()) THEN
    W(fun (asl,w) ->
      let lt = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
      let le = grab asl (fun th ->
        hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
        hd_is "LENGTH" (rhs (concl th))) in
      MP_TAC(MATCH_MP LESS_LENGTH
               (REWRITE_RULE[GSYM le] lt))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    VAR_EQ_TAC THEN
    W(fun (asl,w) ->
      MP_TAC(MATCH_MP heap_lookup_SPLIT
               (grab asl is_hl))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    VAR_EQ_TAC THEN
    TRY(FIRST_X_ASSUM(fun th ->
      if (try hd_is "fmap_apply" (lhs (concl th))
          with Failure _ -> false)
      then SUBST_ALL_TAC th else fail())) THEN
    FIRST_X_ASSUM(fun th ->
      if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
      then MP_TAC th else fail()) THEN
    REWRITE_TAC[word_heap_APPEND; word_heap_def;
                RefBlock_def] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_el_def] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_payload_def] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
                word_list_def; LENGTH_MAP] THEN
    ASM_REWRITE_TAC[addreq] THEN
    (* the condition of the payload bounds the length of the block *)
    REPEAT(sepfront ["cond"] THEN REWRITE_TAC[cond_STAR] THEN
           DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC)) THEN
    W(fun (asl,w) ->
      let ga = grab asl (fun th ->
        hd_is "get_real_addr" (lhs (concl th))) in
      let base = rand (rhs (concl ga)) in
      let pred = rator (lhand w) in
      let fs = facs pred in
      let one = find (fun t ->
        hd_is "set_sep_one" t &&
        not (fst(dest_pair (rand t)) = base)) fs in
      let rest = remove1 one fs in
      let st = fst(strip_comb pred) in
      let mk a b = mk_comb(mk_comb(st,a),b) in
      SUBGOAL_THEN (mk_eq(pred, mk one (end_itlist mk rest)))
        SUBST1_TAC THENL [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
    DISCH_THEN(fun sep ->
      STRIP_ASSUME_TAC(MATCH_MP read_fun2set sep)) THEN
    ASM_REWRITE_TAC[] THEN
    (* the index is a small integer, because it is below the length
       that the header of the block encodes *)
    W(fun (asl,w) ->
      let bd = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th)) &&
        hd_is "EXP" (rand (concl th))) in
      let lt0 = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th)) &&
        hd_is "LENGTH" (rand (concl th))) in
      let lt = try REWRITE_RULE[grab asl (fun th ->
                     hd_is "=" (concl th) &&
                     hd_is "LENGTH" (lhs (concl th)) &&
                     hd_is "LENGTH" (rhs (concl th)))] lt0
               with Failure _ -> lt0 in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      ASSUME_TAC(MATCH_MP smallidx (CONJ gd (CONJ lt bd)))) THEN
    FIRST_X_ASSUM(fun vi ->
      if hd_is "v_inv" (concl vi) &&
         hd_is "dataSem_Number" (el 1 (snd(strip_comb (concl vi))))
      then MP_TAC(REWRITE_RULE[v_inv_def] vi)
      else fail()) THEN
    FIRST_ASSUM(fun si ->
      if hd_is "small_int" (concl si) then REWRITE_TAC[si]
      else fail()) THEN
    DISCH_THEN(fun eq ->
      RULE_ASSUM_TAC(REWRITE_RULE[eq]) THEN REWRITE_TAC[eq]) THEN
    RULE_ASSUM_TAC(REWRITE_RULE
      (word_addr_clauses () @ [smn; and4])) THEN
    REWRITE_TAC(word_addr_clauses () @ [smn; and4]) THEN
    W(fun (asl,w) ->
      let am = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
      MP_TAC(MATCH_MP deref_thm am)) THEN
    ASM_REWRITE_TAC[THE] THEN
    MATCH_REDUCE_TAC THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    W(fun (asl,w) ->
      let fa = grab asl (fun th ->
        is_forall (concl th) &&
        can (find_term (hd_is "heap_el")) (concl th)) in
      let lt = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
      MP_TAC(MP (SPEC (lhand (concl lt)) fa) lt)) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[CONS_11]) THEN
    REPEAT(FIRST_X_ASSUM(fun th ->
      if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
    VAR_EQ_TAC THEN
    W(fun (asl,w) ->
      let hl = REWRITE_RULE[RefBlock_def] (grab asl is_hl) in
      let he = REWRITE_RULE[RefBlock_def]
                 (grab asl (fun th ->
                    hd_is "heap_el" (lhs (concl th)))) in
      let n = el 1 (snd(strip_comb (lhs (concl he)))) in
      let len = el 1 (snd(strip_comb (rand (rhs (concl hl))))) in
      let lt = prove(mk_binop `(<):num->num->bool` n len,
                     REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
                     ARITH_TAC) in
      SUBST_ALL_TAC(REWRITE_RULE[EL_APPEND; LT_REFL; SUB_REFL; EL; HD]
        (MATCH_MP heapel (CONJ hl (CONJ lt he))))) THEN
    W(fun (asl,w) ->
      let cs = conjuncts (snd(strip_exists w)) in
      let ga = grab asl (fun th ->
        hd_is "get_real_addr" (lhs (concl th))) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let ro0 = MATCH_MP get_real_offset_thm gd in
      let iv = find (fun v -> type_of v = `:num`) (frees (concl ro0)) in
      let ro = INST [rand (rand (rand (lhs (el 1 cs)))),iv] ro0 in
      EXISTS_TAC (rand (lhs (el 0 cs))) THEN
      EXISTS_TAC (rand (lhs (el 1 cs))) THEN
      EXISTS_TAC (rand (rhs (concl ga))) THEN
      EXISTS_TAC (rand (rhs (concl ro))) THEN
      ASM_REWRITE_TAC[ro; offeq]) THEN
    REWRITE_TAC[memory_rel_def] THEN
    W(fun (asl,w) ->
      let hm = grab asl (fun th ->
        hd_is "heap_in_memory_store" (concl th)) in
      let args = snd(strip_comb (concl hm)) in
      EXISTS_TAC (el 0 args) THEN EXISTS_TAC (el 9 args) THEN
      EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
      EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args)) THEN
    ASM_REWRITE_TAC[word_ml_inv_def] THEN
    REWRITE_TAC[MAP; FST; SND] THEN
    W(fun (asl,w) ->
      let am = grab asl (fun th ->
        hd_is "abs_ml_inv" (concl th) &&
        hd_is "EL" (lhand (el 1 (snd(strip_comb (concl th)))))) in
      EXISTS_TAC
        (fst(dest_pair (el 3 (snd(strip_comb (concl am))))))) THEN
    ASM_REWRITE_TAC[MAP; ALL2; HD; TL; NOT_CONS_NIL] THEN
    REWRITE_TAC(word_addr_clauses () @ [and4])));;

let LENGTH_EQ_1 = prove
 (`(LENGTH xs = 1 <=> (?a1. xs = [a1])) /\
    (1 = LENGTH xs <=> (?a1. xs = [a1]))`,
  (let lrw = [LENGTH; CONS_11; NOT_CONS_NIL; LENGTH_EQ_NIL;
              EQ_SYM_EQ; ARITH_RULE `~(0 = 1)`;
              ARITH_RULE `(SUC n = 1) <=> (n = 0)`] in
   let aux = prove
    (`!xs:A list. (LENGTH xs = 1 <=> ?a1. xs = [a1]) /\
                  (1 = LENGTH xs <=> ?a1. xs = [a1])`,
     GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `xs:A list` list_CASES_v) THEN
     REWRITE_TAC lrw THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let LENGTH_EQ_2 = prove
 (`(LENGTH xs = 2 <=> (?a1 a2. xs = [a1; a2])) /\
    (2 = LENGTH xs <=> (?a1 a2. xs = [a1; a2]))`,
  (let lrw = [LENGTH; CONS_11; NOT_CONS_NIL; LENGTH_EQ_NIL;
              EQ_SYM_EQ; ARITH_RULE `~(0 = 1)`;
              ARITH_RULE `~(0 = 2)`;
              ARITH_RULE `(SUC n = 1) <=> (n = 0)`;
              ARITH_RULE `(SUC n = 2) <=> (n = 1)`] in
   let aux = prove
    (`!xs:A list. (LENGTH xs = 2 <=> ?a1 a2. xs = [a1; a2]) /\
                  (2 = LENGTH xs <=> ?a1 a2. xs = [a1; a2])`,
     GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `xs:A list` list_CASES_v) THEN
     REWRITE_TAC lrw THEN
     TRY(CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[]) THEN
     STRUCT_CASES_TAC(ISPEC `vs:A list` list_CASES_v) THEN
     REWRITE_TAC lrw THEN
     CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let LENGTH_EQ_3 = prove
 (`(LENGTH xs = 3 <=> (?a1 a2 a3. xs = [a1; a2; a3])) /\
    (3 = LENGTH xs <=> (?a1 a2 a3. xs = [a1; a2; a3]))`,
  (* one element off the front and LENGTH_EQ_2 says the rest *)
  (let lrw = [LENGTH; CONS_11; NOT_CONS_NIL; LENGTH_EQ_NIL;
              EQ_SYM_EQ; ARITH_RULE `~(0 = 3)`;
              ARITH_RULE `(SUC n = 3) <=> (n = 2)`] in
   let aux = prove
    (`!xs:A list. (LENGTH xs = 3 <=> ?a1 a2 a3. xs = [a1; a2; a3]) /\
                  (3 = LENGTH xs <=> ?a1 a2 a3. xs = [a1; a2; a3])`,
     GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `xs:A list` list_CASES_v) THEN
     REWRITE_TAC lrw THEN
     TRY(CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN REWRITE_TAC[]) THEN
     MATCH_ACCEPT_TAC(CONJUNCT1 LENGTH_EQ_2)) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let heap_split_SOME_APPEND = prove
 (`!xs ys a h1 h2.
      heap_split a (xs ++ ys) = SOME (h1,h2) <=>
      (if a < heap_length xs then
        ?ha hb. heap_split a xs = SOME (ha,hb) /\
                h1 = ha /\ h2 = hb ++ ys else
        ?ha hb. heap_split (a - heap_length xs) ys = SOME (ha,hb) /\
                h1 = xs ++ ha /\ h2 = hb)`,
  (REWRITE_TAC[heap_split_APPEND_if] THEN REPEAT GEN_TAC THEN
   COND_CASES_TAC THEN EVERY_CASE_TAC THEN
   ASM_REWRITE_TAC[injectivity "option"; distinctness "option";
                   PAIR_EQ] THEN
   MESON_TAC[]));;

(* the port's own: what the proof of gc_kind_update_Ref needs.  The
   store writes an element of the length it replaces, and the
   element is a reference, so it is at or above the pointer -- the
   first half of the split of a generational heap holds no
   reference.  The halves of the new split are then the first one
   it was and the second with the element written in it
   (heap_split_replace3), and the state of the generations is the
   one it was, because every start of one is at or below the
   pointer (gen_start_ok_replace, gen_state_ok_replace) *)

(* two elements of one length and one tag are of one length *)
let el_length_DataElement = prove
 (`!(xs:((A)heap_address)list) (ys:((A)heap_address)list) l (d:B).
     el_length (DataElement xs l d) = el_length (DataElement ys l d)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[el_length_def]);;

(* an element of a reference is a reference *)
let isRef_RefTag = prove
 (`data_to_word_memoryProof_isRef (DataElement xs l (RefTag,[]))`,
  REWRITE_TAC[isRef_def] THEN MATCH_REDUCE_TAC THEN
  REWRITE_TAC[isMutTag_def]);;

(* the halves of the split of a heap whose element is replaced by
   one of its length, when the cut is at or before the element: the
   first half is the one it was, and the second is the one it was
   with the element replaced *)
let heap_split_replace3 = prove
 (`!e ha u v hb h1 h2.
     heap_split e (ha ++ [u] ++ hb) = SOME (h1,h2) /\
     el_length u = el_length v /\ ~(heap_length ha < e)
     ==> ?h2'. heap_split e (ha ++ [v] ++ hb) = SOME (h1,h2') /\
               (!z. MEM z h2' ==> MEM z h2 \/ z = v)`,
  REPEAT GEN_TAC THEN
  (* the element and what follows it, as one list: a split of the
     heap is then a split of the front or of that list *)
  REWRITE_TAC[APPEND] THEN
  REWRITE_TAC[heap_split_SOME_APPEND] THEN
  COND_CASES_TAC THEN
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  SPLIT_ASM_TAC THENL
   [(* the cut is below the element, so the halves of the front are
       the ones they were and the element is in the second *)
    W(fun (asl,w as gl) ->
      let hs = the_asm (fun c -> is_eq c &&
                 hd_is "heap_split" (lhand c)) gl in
      let pr = rand (rand (concl hs)) in
      let vt = find_term (fun t -> is_var t &&
                 fst (dest_var t) = "v") w in
      let hb = find_term (fun t -> is_var t &&
                 fst (dest_var t) = "hb") w in
      let tail = list_mk_icomb "CONS" [vt; hb] in
      EXISTS_TAC (list_mk_icomb "APPEND" [rand pr; tail]) THEN
      CONJ_TAC THENL
       [REWRITE_TAC[] THEN
        EXISTS_TAC (lhand pr) THEN EXISTS_TAC (rand pr) THEN
        ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[MEM_APPEND; MEM] THEN MESON_TAC[]]);
    (* and the cut is at the element, so the first half is what is
       before it and the second begins with the element *)
    W(fun (asl,w as gl) ->
      let sub = in_goal gl (fun t -> hd_is "-" t &&
                  hd_is "heap_length" (rand t)) in
      SUBGOAL_THEN (mk_eq (sub, `0`)) ASSUME_TAC THENL
       [W(fun (asl,_) ->
          MAP_EVERY MP_TAC (mapfilter (fun (_,th) ->
            let c = concl th in
            if is_neg c && hd_is "<" (rand c) then th else fail())
            asl)) THEN
        ARITH_TAC;
        ALL_TAC]) THEN
    W(fun gl ->
      let z = the_asm (fun c -> is_eq c && hd_is "-" (lhand c) &&
                rand c = `0`) gl in
      RULE_ASSUM_TRY (REWRITE_RULE[z; heap_split_def;
        injectivity "option"; PAIR_EQ]) THEN
      REWRITE_TAC[z]) THEN
    SPLIT_ASM_TAC THEN
    REPEAT (FIRST_X_ASSUM (fun e ->
      let c = concl e in
      if not (is_eq c) || not (is_var (rand c)) then fail() else
      SUBST_ALL_TAC (SYM e))) THEN
    W(fun (asl,w) ->
      let vt = find_term (fun t -> is_var t &&
                 fst (dest_var t) = "v") w in
      let hb = find_term (fun t -> is_var t &&
                 fst (dest_var t) = "hb") w in
      EXISTS_TAC (list_mk_icomb "CONS" [vt; hb])) THEN
    CONJ_TAC THENL
     [ASM_REWRITE_TAC[heap_split_def; injectivity "option";
                      PAIR_EQ] THEN
      CONV_TAC(TOP_DEPTH_CONV UNWIND_CONV) THEN
      ASM_REWRITE_TAC[APPEND_NIL];
      ASM_REWRITE_TAC[MEM] THEN MESON_TAC[]]]);;

(* the pointer condition of a generation survives a store that
   writes an element of the length it replaces at or above the
   start of the generation: the half that the condition is about is
   the one it was (heap_split_replace3) *)
let gen_start_ok_replace = prove
 (cake_as_vars (fun () ->
    `gen_start_ok (ha ++ [u] ++ hb) k s /\
     el_length u = el_length v /\ ~(heap_length ha < s)
     ==> gen_start_ok (ha ++ [v] ++ hb) k s`),
  REWRITE_TAC[gen_start_ok_def] THEN
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  SPLIT_ASM_TAC THEN
  W(fun gl ->
    let hs = the_asm (fun c -> is_eq c &&
               hd_is "heap_split" (lhand c)) gl in
    let le = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    let lt = the_asm (fun c -> is_neg c && hd_is "<" (rand c)) gl in
    STRIP_ASSUME_TAC (MATCH_MP heap_split_replace3
      (CONJ hs (CONJ le lt)))) THEN
  W(fun (asl,w as gl) ->
    let vt = find_term (fun t -> is_var t &&
               fst (dest_var t) = "v") w in
    let hs2 = the_asm (fun c -> is_eq c &&
                hd_is "heap_split" (lhand c) &&
                can (find_term (fun t -> t = vt)) (lhand c)) gl in
    let pr = rand (rand (concl hs2)) in
    EXISTS_TAC (lhand pr) THEN EXISTS_TAC (rand pr) THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC));;

(* and so does the state of the generations, because every start of
   one is at or below the pointer and the element is above it *)
let gen_state_ok_replace = prove
 (cake_as_vars (fun () ->
    `gen_state_ok a k (ha ++ [u] ++ hb) gens /\
     el_length u = el_length v /\ ~(heap_length ha < a)
     ==> gen_state_ok a k (ha ++ [v] ++ hb) gens`),
  W(fun (asl,w) ->
    let gens = find_term (fun t -> is_var t &&
                 fst (dest_var t) = "gens") w in
    STRUCT_CASES_TAC (ISPEC gens (cases_of `:gen_state`))) THEN
  REWRITE_TAC[gen_state_ok_def] THEN
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  REWRITE_TAC[GSYM ALL_MEM] THEN
  CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  REPEAT STRIP_TAC THEN
  W(fun gl ->
    let mm = the_asm (hd_is "MEM") gl in
    let s = el 0 (snd (strip_comb (concl mm))) in
    let evs = mapfilter (fun (_,th) ->
      let c = concl th in
      if hd_is "ALL" c then
        MP (SPEC s (REWRITE_RULE[GSYM ALL_MEM] th)) mm
      else fail()) (fst gl) in
    MAP_EVERY (fun th ->
      ASSUME_TAC (CONV_RULE(TOP_DEPTH_CONV BETA_CONV) th)) evs) THEN
  W(fun gl ->
    let le = the_asm (fun c -> is_eq c &&
               hd_is "el_length" (lhand c)) gl in
    let gs = the_asm (hd_is "gen_start_ok") gl in
    let s = el 2 (snd (strip_comb (concl gs))) in
    let lt = the_asm (fun c -> is_neg c && hd_is "<" (rand c)) gl in
    let sle = the_asm (fun c -> hd_is "<=" c && lhand c = s) gl in
    let hl = lhand (rand (concl lt)) in
    SUBGOAL_THEN (mk_neg (list_mk_icomb "<" [hl; s]))
      (fun nlt -> MATCH_ACCEPT_TAC (MATCH_MP gen_start_ok_replace
         (CONJ gs (CONJ le nlt)))) THEN
    MP_TAC lt THEN MP_TAC sle THEN ARITH_TAC));;

(* [local] *)
let gc_kind_update_Ref = prove
 (`gc_kind_inv c a sp sp1 gens
       (ha ++ (DataElement (ys1 ++ (y :: ys2)) l (RefTag,[]) :: hb))
         ==>
   gc_kind_inv c a sp sp1 gens
       (ha ++ (DataElement (ys1 ++ (z :: ys2)) l (RefTag,[]) ::
         hb))`,
  (* the steps are above the statement (tools/overrides.py).  The
     element written is a reference of the length of the one it
     replaces, so it is at or above the pointer (heap_lookup_at and
     heap_lookup_heap_split put it in the half that holds the
     references), and the halves of the split and the state of the
     generations are then the ones they were *)
    (* the element and what follows it, as an append of three *)
  (REWRITE_TAC[gc_kind_inv_def; APPEND_SINGLE] THEN
    STRIP_TAC THEN
    RULE_ASSUM_TRY (REWRITE_RULE[APPEND_SINGLE]) THEN
    W(fun (asl,w) ->
      CASES_ON_TAC (find_term
        (hd_is "data_to_word_config_gc_kind") w)) THEN
    RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV MATCH_CONV)) THEN
    MATCH_REDUCE_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    SPLIT_ASM_TAC THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
    SPLIT_ASM_TAC THEN
    (* the element is at or above the pointer, because the first half
       of the split holds no reference and this element is one *)
    W(fun (asl,w as gl) ->
      let hs = the_asm (fun c -> is_eq c &&
                 hd_is "heap_split" (lhand c)) gl in
      let args = snd (strip_comb (lhand (concl hs))) in
      let k = el 0 args in
      let hp = el 1 args in
      let lk = ISPECL [lhand hp; lhand (lhand (rand hp));
                       rand (rand hp)] heap_lookup_at in
      SUBGOAL_THEN (mk_neg (list_mk_icomb "<"
                      [list_mk_icomb "heap_length" [lhand hp]; k]))
        ASSUME_TAC THENL
       [MP_TAC (MATCH_MP heap_lookup_heap_split (CONJ hs lk)) THEN
        COND_CASES_TAC THENL
         [DISCH_TAC THEN
          W(fun gl ->
            let ev = the_asm (fun c -> hd_is "ALL" c &&
                       is_abs (el 0 (snd (strip_comb c)))) gl in
            let m = the_asm (hd_is "MEM") gl in
            MP_TAC (MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev) m)) THEN
          CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
          REWRITE_TAC[isRef_RefTag];
          DISCH_THEN (K ALL_TAC) THEN ASM_REWRITE_TAC[]];
        ALL_TAC]) THEN
    (* the two elements are of one length *)
    W(fun (asl,w as gl) ->
      let hs = the_asm (fun c -> is_eq c &&
                 hd_is "heap_split" (lhand c)) gl in
      let hp = el 1 (snd (strip_comb (lhand (concl hs)))) in
      let u = lhand (lhand (rand hp)) in
      let uargs = snd (strip_comb u) in
      let vt = find_term (fun t -> hd_is "DataElement" t &&
                 not (t = u)) w in
      ASSUME_TAC (ISPECL [el 0 uargs; el 0 (snd (strip_comb vt));
                          el 1 uargs; el 2 uargs]
                    el_length_DataElement)) THEN
    CONJ_TAC THENL
     [(* the state of the generations (gen_state_ok_replace) *)
      W(fun (asl,w as gl) ->
        let gs = the_asm (hd_is "gen_state_ok") gl in
        let le = the_asm (fun c -> is_eq c &&
                   hd_is "el_length" (lhand c)) gl in
        let nlt = the_asm (fun c -> is_neg c && hd_is "<" (rand c) &&
                    hd_is "heap_length" (lhand (rand c))) gl in
        let a = el 0 (snd (strip_comb (concl gs))) in
        let hl = lhand (rand (concl nlt)) in
        SUBGOAL_THEN (mk_neg (list_mk_icomb "<" [hl; a]))
          (fun n2 -> MATCH_ACCEPT_TAC (MATCH_MP gen_state_ok_replace
             (CONJ gs (CONJ le n2)))) THEN
        MP_TAC nlt THEN ARITH_TAC);
      (* and the halves of the split: the first is the one it was and
         the second has the element written in it, which is a
         reference as the one it replaces was *)
      W(fun (asl,w as gl) ->
        let hs = the_asm (fun c -> is_eq c &&
                   hd_is "heap_split" (lhand c)) gl in
        let le = the_asm (fun c -> is_eq c &&
                   hd_is "el_length" (lhand c)) gl in
        let nlt = the_asm (fun c -> is_neg c && hd_is "<" (rand c) &&
                    hd_is "heap_length" (lhand (rand c))) gl in
        STRIP_ASSUME_TAC (MATCH_MP heap_split_replace3
          (CONJ hs (CONJ le nlt)))) THEN
      W(fun (asl,w as gl) ->
        let vt = find_term (fun t -> hd_is "DataElement" t &&
                   not (can (find_term (fun s -> is_var s &&
                          fst (dest_var s) = "y")) t)) w in
        let hs2 = the_asm (fun c -> is_eq c &&
                    hd_is "heap_split" (lhand c) &&
                    can (find_term (fun t -> t = vt)) (lhand c)) gl in
        let pr = rand (rand (concl hs2)) in
        EXISTS_TAC (lhand pr) THEN EXISTS_TAC (rand pr)) THEN
      REPEAT CONJ_TAC THEN
      TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
      REWRITE_TAC[GSYM ALL_MEM] THEN
      REPEAT STRIP_TAC THEN
      W(fun gl ->
        let bd = the_asm (fun c ->
                   length (fst (strip_forall c)) = 1 &&
                   is_imp (snd (strip_forall c)) &&
                   is_disj (rand (snd (strip_forall c)))) gl in
        let m = the_asm (hd_is "MEM") gl in
        STRIP_ASSUME_TAC (MATCH_MP (SPEC_ALL bd) m)) THEN
      TRY (SOLVED
            (W(fun gl ->
               let ev = the_asm (fun c -> hd_is "ALL" c &&
                          not (is_abs
                                 (el 0 (snd (strip_comb c))))) gl in
               let m = the_asm (fun c -> hd_is "MEM" c) gl in
               ACCEPT_TAC (MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ev)
                 m)))) THEN
      ASM_REWRITE_TAC[isRef_RefTag]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Update' = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((h,w) :: (RefPtr bl nn,ptr) :: vars) /\
      lookup nn refs = SOME (ValueArray vals) /\
      good_dimindex (:'a) /\
      index < LENGTH vals ==>
      (?ptr_w (x:'a word).
        ptr = wordLang_Word ptr_w /\
        get_real_addr c st ptr_w = SOME x /\
        (x + bytes_in_word + bytes_in_word * n2w index) IN dm /\
        memory_rel c be ts (insert nn (ValueArray (LUPDATE h index
          vals)) refs) sp st
          (((x + bytes_in_word + bytes_in_word * n2w index) =+ w)
            m) dm
          ((h,w) :: (RefPtr bl nn,ptr) :: vars))`),
(* the same write as memory_rel_Update, of which this is the
   statement with the offset of the index in place of the Number
   root that holds it: so the proof is that one without the step
   that reads the index off a root (no small integer, no
   get_real_offset_thm), and the cell of the write is the one that
   the split of the payload at the index puts in front *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let rec facs t =
     if hd_is "STAR" t then
       let args = snd(strip_comb t) in
       facs (el 0 args) @ facs (el 1 args)
     else [t] in
   let rec remove1 t = function
       [] -> []
     | h :: rest -> if h = t then rest else h :: remove1 t rest in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
   let swapmul a =
     let args = snd(strip_comb (rand a)) in
     let mul = fst(strip_comb (rand a)) in
     mk_comb(rator a, mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
   let sepfront names =
     W(fun (asl,w) ->
       let pred = rator (lhand w) in
       let fs = facs pred in
       let picked = map (fun n -> find (hd_is n) fs) names in
       let rest = filter (fun t -> not (mem t picked)) fs in
       let st = fst(strip_comb pred) in
       let mk a b = mk_comb(mk_comb(st,a),b) in
       let target = itlist mk picked (end_itlist mk rest) in
       SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
        [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
   let killthunk =
     TRY(FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 ->
       CONTR_TAC(REWRITE_RULE[injectivity "option";
                              distinctness "bvlSem_ref"]
                   (TRANS (SYM t1) t2))))) in
   let refinv ptr root =
     FIRST_X_ASSUM(fun th ->
       if is_forall (concl th) &&
          hd_is "bc_ref_inv" (rand (snd(strip_forall(concl th))))
       then MP_TAC(SPEC ptr th) else fail()) THEN
     ANTS_TAC THENL
      [CONJ_TAC THENL
        [REWRITE_TAC[reachable_refs_def; MEM] THEN
         EXISTS_TAC root THEN EXISTS_TAC ptr THEN
         REWRITE_TAC[get_refs_def; MEM;
                     CONJUNCT1(SPEC_ALL RTC_RULES)];
         ASM_REWRITE_TAC[]];
       ALL_TAC] THEN
     REWRITE_TAC[bc_ref_inv_def] THEN
     ASM_SIMP_TAC[FLOOKUP_DEF] THEN
     MATCH_REDUCE_TAC in
   let all2cons = prove
    (`!P h t (l:(A)list).
        ALL2 P l (CONS (h:B) t) <=>
        ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   let addreq = WORD_RULE
     `!(a:(N)word) i.
        (a + bytes_in_word) + n2w i * bytes_in_word =
        a + bytes_in_word + bytes_in_word * n2w i` in
   (* the address of the heap element, without the existential of
      the goal: this proof fills the existentials at the end *)
   let realaddr_noex =
     W(fun (asl,w) ->
       let hl = grab asl is_hl in
       let hlen = grab asl (fun th ->
         hd_is "heap_length" (lhand (concl th))) in
       let cu = grab asl (fun th ->
         hd_is "FLOOKUP" (lhs (concl th)) &&
         fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
       let gd = grab asl (fun th ->
         hd_is "good_dimindex" (concl th)) in
       let gat = tryfind (fun t ->
         find_term (fun u ->
           hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
         (w :: map (fun (_,th) -> concl th) asl) in
       let mm = MATCH_MP get_real_addr_get_addr
                  (CONJ hlen (CONJ hl (CONJ cu gd))) in
       let wv = find (fun v -> fst(dest_var v) = "w")
                  (frees (concl mm)) in
       let th = SPEC (last (snd(strip_comb gat))) (GEN wv mm) in
       let a = rand (rhs (concl (CONJUNCT1 th))) in
       STRIP_ASSUME_TAC(REWRITE_RULE[WORD_RULE (mk_eq(a,swapmul a))]
                          th)) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   SUBGOAL_THEN `~(vals:(dataSem_v)list = [])` ASSUME_TAC THENL
    [DISCH_TAC THEN VAR_EQ_TAC THEN
     FIRST_X_ASSUM(fun th ->
       if (try hd_is "<" (concl th) with Failure _ -> false)
       then MP_TAC(REWRITE_RULE[LENGTH; LT] th) else fail()) THEN
     REWRITE_TAC[];
     ALL_TAC] THEN
   FIRST_ASSUM(fun mr ->
     if hd_is "memory_rel" (concl mr)
     then MP_TAC(REWRITE_RULE[memory_rel_def;
                              word_ml_inv_def; MAP; FST] mr)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[MAP; all2cons] a2) else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_ASSUM(fun am ->
     if hd_is "abs_ml_inv" (concl am)
     then MP_TAC(REWRITE_RULE[abs_ml_inv_def;
                              bc_stack_ref_inv_def] am)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2) &&
        can (find_term (hd_is "v_inv")) (concl a2)
     then MP_TAC(REWRITE_RULE[ALL2; NOT_CONS_NIL; HD; TL] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi) &&
        hd_is "dataSem_RefPtr" (el 1 (snd(strip_comb (concl vi))))
     then MP_TAC(REWRITE_RULE[v_inv_def] vi)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   killthunk THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
   REWRITE_TAC(word_addr_clauses ()) THEN
   refinv `nn:num` `RefPtr bl nn:dataSem_v` THEN
   ASM_REWRITE_TAC[] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_ASSUM(fun th ->
     if hd_is "heap_in_memory_store" (concl th)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   realaddr_noex THEN
   FIRST_ASSUM(fun lr ->
     if hd_is "ALL2" (concl lr) &&
        can (find_term (hd_is "v_inv")) (concl lr)
     then ASSUME_TAC(MATCH_MP LIST_REL_LENGTH lr) else fail()) THEN
   W(fun (asl,w) ->
     let lt = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
     let le = grab asl (fun th ->
       hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
       hd_is "LENGTH" (rhs (concl th))) in
     MP_TAC(MATCH_MP LESS_LENGTH
              (REWRITE_RULE[GSYM le] lt))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   W(fun (asl,w) ->
     MP_TAC(MATCH_MP heap_lookup_SPLIT
              (grab asl is_hl))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   TRY(FIRST_X_ASSUM(fun th ->
     if (try hd_is "fmap_apply" (lhs (concl th))
         with Failure _ -> false)
     then SUBST_ALL_TAC th else fail())) THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def;
               RefBlock_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
               word_list_def; LENGTH_MAP] THEN
   ASM_REWRITE_TAC[addreq] THEN
   (* the condition of the payload bounds the length of the block *)
   REPEAT(sepfront ["cond"] THEN REWRITE_TAC[cond_STAR] THEN
          DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC)) THEN
   W(fun (asl,w) ->
     let ga = grab asl (fun th ->
       hd_is "get_real_addr" (lhs (concl th))) in
     let base = rand (rhs (concl ga)) in
     let pred = rator (lhand w) in
     let fs = facs pred in
     let one = find (fun t ->
       hd_is "set_sep_one" t &&
       not (fst(dest_pair (rand t)) = base)) fs in
     let rest = remove1 one fs in
     let st = fst(strip_comb pred) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     SUBGOAL_THEN (mk_eq(pred, mk one (end_itlist mk rest)))
       SUBST1_TAC THENL [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
   DISCH_THEN(fun sep ->
     STRIP_ASSUME_TAC(MATCH_MP read_fun2set sep) THEN
     ASSUME_TAC sep) THEN
   ASM_REWRITE_TAC[] THEN
   RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
   REWRITE_TAC(word_addr_clauses ()) THEN
   (* the invariant with the value stored in the reference *)
   W(fun (asl,gl) ->
     let am = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
     let stk = el 1 (snd(strip_comb (concl am))) in
     let hv = lhand stk in
     let xsv = find (fun v -> fst(dest_var v) = "xs")
                 (frees (concl update_ref_thm1)) in
     let urt = REWRITE_RULE[LENGTH_EQ_1]
                 (CONV_RULE NUM_REDUCE_CONV
                   (REWRITE_RULE[APPEND; HD; LENGTH]
                     (INST [mk_list([hv],type_of hv),xsv]
                       update_ref_thm1))) in
     let lk = grab asl (fun th ->
       hd_is "sptree_lookup" (lhs (concl th))) in
     let lt = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
     MP_TAC(MATCH_MP urt (CONJ am (CONJ lk lt)))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   (* the existentials: the root of the pointer and the address *)
   W(fun (asl,w) ->
     let cs = conjuncts (snd(strip_exists w)) in
     let ga = grab asl (fun th ->
       hd_is "get_real_addr" (lhs (concl th))) in
     EXISTS_TAC (rand (lhs (el 0 cs))) THEN
     EXISTS_TAC (rand (rhs (concl ga))) THEN
     ASM_REWRITE_TAC[]) THEN
   (* the root of the value, and the pointer of the store is the
      address of the element *)
   REPEAT (FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                 hd_is "CONS" (rhs (concl e))
             with Failure _ -> false) then fail() else
     SUBST_ALL_TAC e)) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[APPEND; HD]) THEN
   FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && hd_is "CONS" (lhs (concl e)) &&
                 hd_is "CONS" (rhs (concl e)) &&
                 can (find_term (hd_is "gc_shared_Pointer"))
                   (rhs (concl e))
             with Failure _ -> false) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[CONS_11;
       injectivity "heap_address"] e)) THEN
   REPEAT (FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                 is_var (rhs (concl e)) &&
                 not (lhs (concl e) = rhs (concl e))
             with Failure _ -> false) then fail() else
     SUBST_ALL_TAC e)) THEN
   FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && is_var (rhs (concl e)) &&
                 hd_is "heap_length" (lhs (concl e))
             with Failure _ -> false) then fail() else
     SUBST_ALL_TAC (SYM e)) THEN
   (* the payload of the element is the list that the index split *)
   W(fun (asl,gl) ->
     let hd0 = grab asl (fun th ->
       hd_is "heap_deref" (lhs (concl th))) in
     let hl = grab asl is_hl in
     MP_TAC (REWRITE_RULE[heap_deref_def; hl; RefBlock_def] hd0)) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[injectivity "option"] THEN
   DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
   (* the new heap is the old one with the element written *)
   W(fun (asl,gl) ->
     let hs = grab asl (fun th ->
       hd_is "heap_store" (lhs (concl th))) in
     let args = snd(strip_comb (lhs (concl hs))) in
     let xs = rand (lhand (el 1 args)) in
     let ys = rand (lhand (rand (el 2 args))) in
     let hap = lhand (el 2 args) in
     let lenth = prove (mk_eq (mk_icomb (`LENGTH`,xs),
                               mk_icomb (`LENGTH`,ys)),
                  REWRITE_TAC[LENGTH_LUPDATE]) in
     let inst = MATCH_MP (ISPEC hap heap_store_RefBlock_thm)
                  lenth in
     SUBST_ALL_TAC (SYM (REWRITE_RULE[PAIR_EQ]
       (REWRITE_RULE[inst] hs)))) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[LUPDATE_LENGTH]) THEN
   (* the invariant of the new heap *)
   REWRITE_TAC[memory_rel_def] THEN
   W(fun (asl,gl) ->
     let hm = grab asl (fun th ->
       hd_is "heap_in_memory_store" (concl th)) in
     let args = snd(strip_comb (concl hm)) in
     let ai = grab asl (fun th ->
       hd_is "abs_ml_inv" (concl th) &&
       (try hd_is "sptree_insert"
              (el 2 (snd(strip_comb (concl th))))
        with Failure _ -> false)) in
     let nh = el 1 (tparts (el 3 (snd(strip_comb (concl ai))))) in
     EXISTS_TAC nh THEN EXISTS_TAC (el 9 args) THEN
     EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
     EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args)) THEN
   REPEAT CONJ_TAC THENL
    [ALL_TAC;
     (* the roots of the invariant, with the root of the value *)
     REWRITE_TAC[word_ml_inv_def] THEN
     W(fun (asl,gl) ->
       let ai = grab asl (fun th ->
         hd_is "abs_ml_inv" (concl th) &&
         (try hd_is "sptree_insert"
                (el 2 (snd(strip_comb (concl th))))
          with Failure _ -> false)) in
       EXISTS_TAC
         (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
     REWRITE_TAC[MAP; FST; SND; ALL2; HD; TL; NOT_CONS_NIL] THEN
     CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
     REWRITE_TAC(word_addr_clauses ()) THEN
     (* the annotation of the pointer is the one of the array *)
     TRY (FIRST_ASSUM (fun an ->
       if not (try hd_is "ref_ptr_annot" (lhs (concl an))
               with Failure _ -> false) then fail() else
       FIRST_ASSUM (fun lk ->
         if not (try hd_is "sptree_lookup" (lhs (concl lk))
                 with Failure _ -> false) then fail() else
         REWRITE_TAC[REWRITE_RULE[lk] an]))) THEN
     ASM_REWRITE_TAC[] THEN
     REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC);
     FIRST_ASSUM ACCEPT_TAC;
     FIRST_ASSUM ACCEPT_TAC] THEN
   (* the store, whose memory is the one written *)
   REWRITE_TAC[heap_in_memory_store_def] THEN
   W(fun (asl,gl) ->
     let nh = rand (find_term (fun t ->
       hd_is "heap_length" t && hd_is "APPEND" (rand t)) gl) in
     let oh = rand (lhs (concl (grab asl is_hl))) in
     if nh = oh then ALL_TAC else
     SUBGOAL_THEN (mk_eq (mk_icomb (`heap_length`,nh),
                          mk_icomb (`heap_length`,oh)))
       (fun le -> REWRITE_TAC[le]) THENL
      [REWRITE_TAC[heap_length_APPEND; heap_length_CONS;
                   heap_length_NIL; RefBlock_def; el_length_def;
                   LENGTH_APPEND; LENGTH] THEN ARITH_TAC;
       ALL_TAC]) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   W(fun (asl,gl) ->
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const (rand (lhs (concl th)))) = "CurrHeap") in
     let ot = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const (rand (lhs (concl th)))) = "OtherHeap") in
     MAP_EVERY EXISTS_TAC [rand (rand (rhs (concl cu)));
                           rand (rand (rhs (concl ot)))]) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   (* the heap of the write, with the cell of the new root *)
   REWRITE_TAC[word_heap_APPEND; word_heap_def; RefBlock_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
               word_list_def; LENGTH_MAP] THEN
   ASM_REWRITE_TAC[addreq] THEN
   REWRITE_TAC[emp_STAR; STAR_emp; STAR_ASSOC] THEN
   (* the element is as long as the array of the reference *)
   RULE_ASSUM_TRY (REWRITE_RULE[el_length_def]) THEN
   REWRITE_TAC[el_length_def; LENGTH_APPEND; LENGTH] THEN
   W(fun (asl,gl) ->
     let le = grab asl (fun th ->
       is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
       hd_is "APPEND" (rand (lhs (concl th))) &&
       hd_is "LENGTH" (rhs (concl th))) in
     REWRITE_TAC[REWRITE_RULE[LENGTH_APPEND; LENGTH] le]) THEN
   W(fun (asl,gl) ->
     let pred = rator gl in
     let fs = facs pred in
     let cell = find (hd_is "cond") fs in
     let rest = filter (fun t -> not (t = cell)) fs in
     let st = fst(strip_comb pred) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     SUBGOAL_THEN (mk_eq (pred, mk cell (end_itlist mk rest)))
       SUBST1_TAC THENL
      [REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]; ALL_TAC]) THEN
   REWRITE_TAC[cond_STAR] THEN
   CONJ_TAC THENL
    [REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
     RULE_ASSUM_TRY (REWRITE_RULE[LENGTH_APPEND; LENGTH]) THEN
     ASM_REWRITE_TAC[] THEN TRY ASM_ARITH_TAC;
     ALL_TAC] THEN
   (* the write of the root into the cell of the element *)
   W(fun (asl,gl) ->
     let wv = rand (rator (fst (dest_pair (rand (rand gl))))) in
     FIRST_ASSUM (fun sep ->
       if not (try hd_is "STAR" (rator (concl sep))
               with Failure _ -> false) then fail() else
       let th = SPEC wv (MATCH_MP write_fun2set sep) in
       let eq = prove (mk_eq (rator gl, rator (concl th)),
                 REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
       ACCEPT_TAC (REWRITE_RULE[GSYM eq] th))))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Update = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((h,w) :: (RefPtr bl nn,ptr) :: (Number (&index),i) :: vars)
         /\
      lookup nn refs = SOME (ValueArray vals) /\
      good_dimindex (:'a) /\
      index < LENGTH vals ==>
      (?ptr_w i_w x (y:'a word).
        ptr = wordLang_Word ptr_w /\ i = wordLang_Word i_w /\
        get_real_addr c st ptr_w = SOME x /\
        get_real_offset i_w = SOME y /\
        (x + y) IN dm /\
        memory_rel c be ts (insert nn (ValueArray (LUPDATE h index
          vals)) refs) sp st
          (((x + y) =+ w) m) dm
          ((h,w) :: (RefPtr bl nn,ptr) :: (Number (&index),i) ::
            vars))`),
(* the write of one value into the array of a reference: the whole
   opening of memory_rel_Deref carries over, because the statements
   agree up to what is done with the cell -- the roots, bc_ref_inv
   (through reachable_refs) for the element of the reference,
   get_real_addr_get_addr for its address, LESS_LENGTH to split the
   payload at the index, and the small-integer case of the v_inv of
   the Number root, whose word is four times the index, for
   get_real_offset_thm.  Then update_ref_thm1 at a stack of one
   value (what the source writes as an instance at [xx], with
   LENGTH_EQ_1 for its root) gives the invariant of the stored
   array; the pointer of its store is the address of the element,
   because the roots of the two agree, and heap_deref says its
   payload is the list that the index split.  So
   heap_store_RefBlock_thm (whose condition is LENGTH_LUPDATE)
   makes the new heap, LUPDATE_LENGTH puts the root in the place of
   the index, and the write of write_fun2set is the cell that
   read_fun2set read -- the element keeps its header, because the
   array keeps its length *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let rec facs t =
     if hd_is "STAR" t then
       let args = snd(strip_comb t) in
       facs (el 0 args) @ facs (el 1 args)
     else [t] in
   let rec remove1 t = function
       [] -> []
     | h :: rest -> if h = t then rest else h :: remove1 t rest in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
   let swapmul a =
     let args = snd(strip_comb (rand a)) in
     let mul = fst(strip_comb (rand a)) in
     mk_comb(rator a, mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
   let sepfront names =
     W(fun (asl,w) ->
       let pred = rator (lhand w) in
       let fs = facs pred in
       let picked = map (fun n -> find (hd_is n) fs) names in
       let rest = filter (fun t -> not (mem t picked)) fs in
       let st = fst(strip_comb pred) in
       let mk a b = mk_comb(mk_comb(st,a),b) in
       let target = itlist mk picked (end_itlist mk rest) in
       SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
        [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
   let killthunk =
     TRY(FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 ->
       CONTR_TAC(REWRITE_RULE[injectivity "option";
                              distinctness "bvlSem_ref"]
                   (TRANS (SYM t1) t2))))) in
   let refinv ptr root =
     FIRST_X_ASSUM(fun th ->
       if is_forall (concl th) &&
          hd_is "bc_ref_inv" (rand (snd(strip_forall(concl th))))
       then MP_TAC(SPEC ptr th) else fail()) THEN
     ANTS_TAC THENL
      [CONJ_TAC THENL
        [REWRITE_TAC[reachable_refs_def; MEM] THEN
         EXISTS_TAC root THEN EXISTS_TAC ptr THEN
         REWRITE_TAC[get_refs_def; MEM;
                     CONJUNCT1(SPEC_ALL RTC_RULES)];
         ASM_REWRITE_TAC[]];
       ALL_TAC] THEN
     REWRITE_TAC[bc_ref_inv_def] THEN
     ASM_SIMP_TAC[FLOOKUP_DEF] THEN
     MATCH_REDUCE_TAC in
   let all2cons = prove
    (`!P h t (l:(A)list).
        ALL2 P l (CONS (h:B) t) <=>
        ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   let addreq = WORD_RULE
     `!(a:(N)word) i.
        (a + bytes_in_word) + n2w i * bytes_in_word =
        a + bytes_in_word + bytes_in_word * n2w i` in
   (* the Smallnum of a natural number is four times it, and the and
      with the complement of one leaves such a word alone *)
   let smn = prove
    (`!n. Smallnum (&n) = (n2w (4 * n)):(N)word`,
     GEN_TAC THEN REWRITE_TAC[smallnum_def] THEN
     REWRITE_TAC[INT_ARITH `~((&n:int) < &0)`] THEN
     REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM]) in
   let and4 = prove
    (`!n. word_and (n2w (4 * n)) (word_not (word 1)) =
          (n2w (4 * n)):(N)word`,
     GEN_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
                 BIT_WORD_1] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
     TRY(REWRITE_TAC[BIT_WORD; EXP; DIV_1; ODD_MULT] THEN
       CONV_TAC NUM_REDUCE_CONV THEN NO_TAC) THEN
     TRY(CONV_TAC TAUT)) in
   (* the address of the heap element, without the existential of
      the goal: this proof fills the existentials at the end *)
   let realaddr_noex =
     W(fun (asl,w) ->
       let hl = grab asl is_hl in
       let hlen = grab asl (fun th ->
         hd_is "heap_length" (lhand (concl th))) in
       let cu = grab asl (fun th ->
         hd_is "FLOOKUP" (lhs (concl th)) &&
         fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
       let gd = grab asl (fun th ->
         hd_is "good_dimindex" (concl th)) in
       let gat = tryfind (fun t ->
         find_term (fun u ->
           hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
         (w :: map (fun (_,th) -> concl th) asl) in
       let mm = MATCH_MP get_real_addr_get_addr
                  (CONJ hlen (CONJ hl (CONJ cu gd))) in
       let wv = find (fun v -> fst(dest_var v) = "w")
                  (frees (concl mm)) in
       let th = SPEC (last (snd(strip_comb gat))) (GEN wv mm) in
       let a = rand (rhs (concl (CONJUNCT1 th))) in
       STRIP_ASSUME_TAC(REWRITE_RULE[WORD_RULE (mk_eq(a,swapmul a))]
                          th)) in
   let offeq = WORD_RULE
     `!(x:(N)word) i.
        x + (bytes_in_word + n2w i * bytes_in_word) =
        x + bytes_in_word + bytes_in_word * n2w i` in
   let smallidx = prove
    (`!(i:num) n.
        good_dimindex (:'a) /\ i < n /\
        n < 2 EXP (dimindex (:'a) - 4)
        ==> small_int (:'a) (&i)`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[small_int_def; dimword;
                 good_dimindex_def] THEN
     DISCH_THEN(CONJUNCTS_THEN2 MP_TAC STRIP_ASSUME_TAC) THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
     RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
     CONV_TAC NUM_REDUCE_CONV THEN
     CONJ_TAC THEN
     TRY(MATCH_MP_TAC INT_LE_TRANS THEN EXISTS_TAC `&0:int` THEN
         REWRITE_TAC[INT_POS; INT_NEG_LE0; INT_POS] THEN NO_TAC) THEN
     REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   SUBGOAL_THEN `~(vals:(dataSem_v)list = [])` ASSUME_TAC THENL
    [DISCH_TAC THEN VAR_EQ_TAC THEN
     FIRST_X_ASSUM(fun th ->
       if (try hd_is "<" (concl th) with Failure _ -> false)
       then MP_TAC(REWRITE_RULE[LENGTH; LT] th) else fail()) THEN
     REWRITE_TAC[];
     ALL_TAC] THEN
   FIRST_ASSUM(fun mr ->
     if hd_is "memory_rel" (concl mr)
     then MP_TAC(REWRITE_RULE[memory_rel_def;
                              word_ml_inv_def; MAP; FST] mr)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[MAP; all2cons] a2) else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_ASSUM(fun am ->
     if hd_is "abs_ml_inv" (concl am)
     then MP_TAC(REWRITE_RULE[abs_ml_inv_def;
                              bc_stack_ref_inv_def] am)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2) &&
        can (find_term (hd_is "v_inv")) (concl a2)
     then MP_TAC(REWRITE_RULE[ALL2; NOT_CONS_NIL; HD; TL] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi) &&
        hd_is "dataSem_RefPtr" (el 1 (snd(strip_comb (concl vi))))
     then MP_TAC(REWRITE_RULE[v_inv_def] vi)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   killthunk THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
   REWRITE_TAC(word_addr_clauses ()) THEN
   refinv `nn:num` `RefPtr bl nn:dataSem_v` THEN
   ASM_REWRITE_TAC[] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_ASSUM(fun th ->
     if hd_is "heap_in_memory_store" (concl th)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   realaddr_noex THEN
   FIRST_ASSUM(fun lr ->
     if hd_is "ALL2" (concl lr) &&
        can (find_term (hd_is "v_inv")) (concl lr)
     then ASSUME_TAC(MATCH_MP LIST_REL_LENGTH lr) else fail()) THEN
   W(fun (asl,w) ->
     let lt = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
     let le = grab asl (fun th ->
       hd_is "=" (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
       hd_is "LENGTH" (rhs (concl th))) in
     MP_TAC(MATCH_MP LESS_LENGTH
              (REWRITE_RULE[GSYM le] lt))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   W(fun (asl,w) ->
     MP_TAC(MATCH_MP heap_lookup_SPLIT
              (grab asl is_hl))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   TRY(FIRST_X_ASSUM(fun th ->
     if (try hd_is "fmap_apply" (lhs (concl th))
         with Failure _ -> false)
     then SUBST_ALL_TAC th else fail())) THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def;
               RefBlock_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
               word_list_def; LENGTH_MAP] THEN
   ASM_REWRITE_TAC[addreq] THEN
   (* the condition of the payload bounds the length of the block *)
   REPEAT(sepfront ["cond"] THEN REWRITE_TAC[cond_STAR] THEN
          DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC)) THEN
   W(fun (asl,w) ->
     let ga = grab asl (fun th ->
       hd_is "get_real_addr" (lhs (concl th))) in
     let base = rand (rhs (concl ga)) in
     let pred = rator (lhand w) in
     let fs = facs pred in
     let one = find (fun t ->
       hd_is "set_sep_one" t &&
       not (fst(dest_pair (rand t)) = base)) fs in
     let rest = remove1 one fs in
     let st = fst(strip_comb pred) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     SUBGOAL_THEN (mk_eq(pred, mk one (end_itlist mk rest)))
       SUBST1_TAC THENL [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
   DISCH_THEN(fun sep ->
     STRIP_ASSUME_TAC(MATCH_MP read_fun2set sep) THEN
     ASSUME_TAC sep) THEN
   ASM_REWRITE_TAC[] THEN
   (* the index is a small integer, because it is below the length
      that the header of the block encodes *)
   W(fun (asl,w) ->
     let bd = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th)) &&
       hd_is "EXP" (rand (concl th))) in
     let lt0 = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th)) &&
       hd_is "LENGTH" (rand (concl th))) in
     let lt = try REWRITE_RULE[grab asl (fun th ->
                    hd_is "=" (concl th) &&
                    hd_is "LENGTH" (lhs (concl th)) &&
                    hd_is "LENGTH" (rhs (concl th)))] lt0
              with Failure _ -> lt0 in
     let gd = grab asl (fun th ->
       hd_is "good_dimindex" (concl th)) in
     ASSUME_TAC(MATCH_MP smallidx (CONJ gd (CONJ lt bd)))) THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi) &&
        hd_is "dataSem_Number" (el 1 (snd(strip_comb (concl vi))))
     then MP_TAC(REWRITE_RULE[v_inv_def] vi)
     else fail()) THEN
   FIRST_ASSUM(fun si ->
     if hd_is "small_int" (concl si) then REWRITE_TAC[si]
     else fail()) THEN
   DISCH_THEN(fun eq ->
     RULE_ASSUM_TAC(REWRITE_RULE[eq]) THEN REWRITE_TAC[eq]) THEN
   RULE_ASSUM_TAC(REWRITE_RULE
     (word_addr_clauses () @ [smn; and4])) THEN
   REWRITE_TAC(word_addr_clauses () @ [smn; and4]) THEN
   (* the invariant with the value stored in the reference *)
   W(fun (asl,gl) ->
     let am = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
     let stk = el 1 (snd(strip_comb (concl am))) in
     let hv = lhand stk in
     let xsv = find (fun v -> fst(dest_var v) = "xs")
                 (frees (concl update_ref_thm1)) in
     let urt = REWRITE_RULE[LENGTH_EQ_1]
                 (CONV_RULE NUM_REDUCE_CONV
                   (REWRITE_RULE[APPEND; HD; LENGTH]
                     (INST [mk_list([hv],type_of hv),xsv]
                       update_ref_thm1))) in
     let lk = grab asl (fun th ->
       hd_is "sptree_lookup" (lhs (concl th))) in
     let lt = grab asl (fun th ->
       hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
     MP_TAC(MATCH_MP urt (CONJ am (CONJ lk lt)))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   (* the existentials: the roots, the address and the offset *)
   W(fun (asl,w) ->
     let cs = conjuncts (snd(strip_exists w)) in
     let ga = grab asl (fun th ->
       hd_is "get_real_addr" (lhs (concl th))) in
     let gd = grab asl (fun th ->
       hd_is "good_dimindex" (concl th)) in
     let ro0 = MATCH_MP get_real_offset_thm gd in
     let iv = find (fun v -> type_of v = `:num`) (frees (concl ro0)) in
     let ro = INST [rand (rand (rand (lhs (el 1 cs)))),iv] ro0 in
     EXISTS_TAC (rand (lhs (el 0 cs))) THEN
     EXISTS_TAC (rand (lhs (el 1 cs))) THEN
     EXISTS_TAC (rand (rhs (concl ga))) THEN
     EXISTS_TAC (rand (rhs (concl ro))) THEN
     ASM_REWRITE_TAC[ro; offeq]) THEN
   (* the root of the value, and the pointer of the store is the
      address of the element *)
   REPEAT (FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                 hd_is "CONS" (rhs (concl e))
             with Failure _ -> false) then fail() else
     SUBST_ALL_TAC e)) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[APPEND; HD]) THEN
   FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && hd_is "CONS" (lhs (concl e)) &&
                 hd_is "CONS" (rhs (concl e)) &&
                 can (find_term (hd_is "gc_shared_Pointer"))
                   (rhs (concl e))
             with Failure _ -> false) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[CONS_11;
       injectivity "heap_address"] e)) THEN
   REPEAT (FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                 is_var (rhs (concl e)) &&
                 not (lhs (concl e) = rhs (concl e))
             with Failure _ -> false) then fail() else
     SUBST_ALL_TAC e)) THEN
   FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && is_var (rhs (concl e)) &&
                 hd_is "heap_length" (lhs (concl e))
             with Failure _ -> false) then fail() else
     SUBST_ALL_TAC (SYM e)) THEN
   (* the payload of the element is the list that the index split *)
   W(fun (asl,gl) ->
     let hd0 = grab asl (fun th ->
       hd_is "heap_deref" (lhs (concl th))) in
     let hl = grab asl is_hl in
     MP_TAC (REWRITE_RULE[heap_deref_def; hl; RefBlock_def] hd0)) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[injectivity "option"] THEN
   DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
   (* the new heap is the old one with the element written *)
   W(fun (asl,gl) ->
     let hs = grab asl (fun th ->
       hd_is "heap_store" (lhs (concl th))) in
     let args = snd(strip_comb (lhs (concl hs))) in
     let xs = rand (lhand (el 1 args)) in
     let ys = rand (lhand (rand (el 2 args))) in
     let hap = lhand (el 2 args) in
     let lenth = prove (mk_eq (mk_icomb (`LENGTH`,xs),
                               mk_icomb (`LENGTH`,ys)),
                  REWRITE_TAC[LENGTH_LUPDATE]) in
     let inst = MATCH_MP (ISPEC hap heap_store_RefBlock_thm)
                  lenth in
     SUBST_ALL_TAC (SYM (REWRITE_RULE[PAIR_EQ]
       (REWRITE_RULE[inst] hs)))) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[LUPDATE_LENGTH]) THEN
   (* the invariant of the new heap *)
   REWRITE_TAC[memory_rel_def] THEN
   W(fun (asl,gl) ->
     let hm = grab asl (fun th ->
       hd_is "heap_in_memory_store" (concl th)) in
     let args = snd(strip_comb (concl hm)) in
     let ai = grab asl (fun th ->
       hd_is "abs_ml_inv" (concl th) &&
       (try hd_is "sptree_insert"
              (el 2 (snd(strip_comb (concl th))))
        with Failure _ -> false)) in
     let nh = el 1 (tparts (el 3 (snd(strip_comb (concl ai))))) in
     EXISTS_TAC nh THEN EXISTS_TAC (el 9 args) THEN
     EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
     EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args)) THEN
   REPEAT CONJ_TAC THENL
    [ALL_TAC;
     (* the roots of the invariant, with the root of the value *)
     REWRITE_TAC[word_ml_inv_def] THEN
     W(fun (asl,gl) ->
       let ai = grab asl (fun th ->
         hd_is "abs_ml_inv" (concl th) &&
         (try hd_is "sptree_insert"
                (el 2 (snd(strip_comb (concl th))))
          with Failure _ -> false)) in
       EXISTS_TAC
         (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
     REWRITE_TAC[MAP; FST; SND; ALL2; HD; TL; NOT_CONS_NIL] THEN
     CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
     REWRITE_TAC(word_addr_clauses () @ [smn; and4]) THEN
     (* the annotation of the pointer is the one of the array *)
     TRY (FIRST_ASSUM (fun an ->
       if not (try hd_is "ref_ptr_annot" (lhs (concl an))
               with Failure _ -> false) then fail() else
       FIRST_ASSUM (fun lk ->
         if not (try hd_is "sptree_lookup" (lhs (concl lk))
                 with Failure _ -> false) then fail() else
         REWRITE_TAC[REWRITE_RULE[lk] an]))) THEN
     ASM_REWRITE_TAC[] THEN
     REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC);
     FIRST_ASSUM ACCEPT_TAC;
     FIRST_ASSUM ACCEPT_TAC] THEN
   (* the store, whose memory is the one written *)
   REWRITE_TAC[heap_in_memory_store_def] THEN
   W(fun (asl,gl) ->
     let nh = rand (find_term (fun t ->
       hd_is "heap_length" t && hd_is "APPEND" (rand t)) gl) in
     let oh = rand (lhs (concl (grab asl is_hl))) in
     if nh = oh then ALL_TAC else
     SUBGOAL_THEN (mk_eq (mk_icomb (`heap_length`,nh),
                          mk_icomb (`heap_length`,oh)))
       (fun le -> REWRITE_TAC[le]) THENL
      [REWRITE_TAC[heap_length_APPEND; heap_length_CONS;
                   heap_length_NIL; RefBlock_def; el_length_def;
                   LENGTH_APPEND; LENGTH] THEN ARITH_TAC;
       ALL_TAC]) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   W(fun (asl,gl) ->
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const (rand (lhs (concl th)))) = "CurrHeap") in
     let ot = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const (rand (lhs (concl th)))) = "OtherHeap") in
     MAP_EVERY EXISTS_TAC [rand (rand (rhs (concl cu)));
                           rand (rand (rhs (concl ot)))]) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   (* the heap of the write, with the cell of the new root *)
   REWRITE_TAC[word_heap_APPEND; word_heap_def; RefBlock_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
               word_list_def; LENGTH_MAP] THEN
   ASM_REWRITE_TAC[addreq] THEN
   REWRITE_TAC[emp_STAR; STAR_emp; STAR_ASSOC] THEN
   (* the element is as long as the array of the reference *)
   RULE_ASSUM_TRY (REWRITE_RULE[el_length_def]) THEN
   REWRITE_TAC[el_length_def; LENGTH_APPEND; LENGTH] THEN
   W(fun (asl,gl) ->
     let le = grab asl (fun th ->
       is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
       hd_is "APPEND" (rand (lhs (concl th))) &&
       hd_is "LENGTH" (rhs (concl th))) in
     REWRITE_TAC[REWRITE_RULE[LENGTH_APPEND; LENGTH] le]) THEN
   W(fun (asl,gl) ->
     let pred = rator gl in
     let fs = facs pred in
     let cell = find (hd_is "cond") fs in
     let rest = filter (fun t -> not (t = cell)) fs in
     let st = fst(strip_comb pred) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     SUBGOAL_THEN (mk_eq (pred, mk cell (end_itlist mk rest)))
       SUBST1_TAC THENL
      [REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]; ALL_TAC]) THEN
   REWRITE_TAC[cond_STAR] THEN
   CONJ_TAC THENL
    [REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
     RULE_ASSUM_TRY (REWRITE_RULE[LENGTH_APPEND; LENGTH]) THEN
     ASM_REWRITE_TAC[] THEN TRY ASM_ARITH_TAC;
     ALL_TAC] THEN
   (* the write of the root into the cell of the element *)
   W(fun (asl,gl) ->
     let wv = rand (rator (fst (dest_pair (rand (rand gl))))) in
     FIRST_ASSUM (fun sep ->
       if not (try hd_is "STAR" (rator (concl sep))
               with Failure _ -> false) then fail() else
       let th = SPEC wv (MATCH_MP write_fun2set sep) in
       let eq = prove (mk_eq (rator gl, rator (concl th)),
                 REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
       ACCEPT_TAC (REWRITE_RULE[GSYM eq] th))))));;

(* mirrors memory_rel_Update: writing the hole of an unfinalised MutBlock is
   the same single memory write as updating a reference's payload *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_UpdateCons = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((h,w) :: (RefPtr bl nn,ptr) :: (Number (&index),i) :: vars)
         /\
      lookup nn refs = SOME (bvlSem_MutBlock tag F l cv r) /\
      good_dimindex (:'a) /\
      index = LENGTH l ==>
      (?ptr_w i_w x (y:'a word).
        ptr = wordLang_Word ptr_w /\ i = wordLang_Word i_w /\
        get_real_addr c st ptr_w = SOME x /\
        get_real_offset i_w = SOME y /\
        (x + y) IN dm /\
        memory_rel c be ts (insert nn (bvlSem_MutBlock tag F l h r)
          refs) sp st
          (((x + y) =+ w) m) dm
          ((h,w) :: (RefPtr bl nn,ptr) :: (Number (&index),i) ::
            vars))`),
(* the write into the hole of an unfinalised mutable block, which
   mirrors memory_rel_Update: the same opening (the roots, the
   address of the element, the payload split at the index and the
   small-integer case of the Number root, with get_real_offset_thm
   for its offset), but the pointer of a mutable block is never
   compare-by-pointer -- the source argues that by contradiction,
   and so does this, with v_inv_RefPtr_T, which says a RefPtr T is
   no mutable block.  Then update_mutblock_thm gives the invariant
   of the stored block together with the element of the heap and
   the roots of the two values in front, so no bc_ref_inv is
   needed here; the length of the payload is the one the header
   encodes (encode_header, as in memory_rel_El) and the index is
   below it, which makes it a small integer.
   heap_store_BlockRep_thm makes the new heap, LUPDATE_LENGTH puts
   the root in the place of the hole, and the write of
   write_fun2set is the cell that read_fun2set read *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let rec facs t =
     if hd_is "STAR" t then
       let args = snd(strip_comb t) in
       facs (el 0 args) @ facs (el 1 args)
     else [t] in
   let rec remove1 t = function
       [] -> []
     | h :: rest -> if h = t then rest else h :: remove1 t rest in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
   let swapmul a =
     let args = snd(strip_comb (rand a)) in
     let mul = fst(strip_comb (rand a)) in
     mk_comb(rator a, mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
   let sepfront names =
     W(fun (asl,w) ->
       let pred = rator (lhand w) in
       let fs = facs pred in
       let picked = map (fun n -> find (hd_is n) fs) names in
       let rest = filter (fun t -> not (mem t picked)) fs in
       let st = fst(strip_comb pred) in
       let mk a b = mk_comb(mk_comb(st,a),b) in
       let target = itlist mk picked (end_itlist mk rest) in
       SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
        [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
   let all2cons = prove
    (`!P h t (l:(A)list).
        ALL2 P l (CONS (h:B) t) <=>
        ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   let addreq = WORD_RULE
     `!(a:(N)word) i.
        (a + bytes_in_word) + n2w i * bytes_in_word =
        a + bytes_in_word + bytes_in_word * n2w i` in
   (* the Smallnum of a natural number is four times it, and the and
      with the complement of one leaves such a word alone *)
   let smn = prove
    (`!n. Smallnum (&n) = (n2w (4 * n)):(N)word`,
     GEN_TAC THEN REWRITE_TAC[smallnum_def] THEN
     REWRITE_TAC[INT_ARITH `~((&n:int) < &0)`] THEN
     REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM]) in
   let and4 = prove
    (`!n. word_and (n2w (4 * n)) (word_not (word 1)) =
          (n2w (4 * n)):(N)word`,
     GEN_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
                 BIT_WORD_1] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
     TRY(REWRITE_TAC[BIT_WORD; EXP; DIV_1; ODD_MULT] THEN
       CONV_TAC NUM_REDUCE_CONV THEN NO_TAC) THEN
     TRY(CONV_TAC TAUT)) in
   (* the address of the heap element, without the existential of
      the goal: this proof fills the existentials at the end *)
   let realaddr_noex =
     W(fun (asl,w) ->
       let hl = grab asl is_hl in
       let hlen = grab asl (fun th ->
         hd_is "heap_length" (lhand (concl th))) in
       let cu = grab asl (fun th ->
         hd_is "FLOOKUP" (lhs (concl th)) &&
         fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
       let gd = grab asl (fun th ->
         hd_is "good_dimindex" (concl th)) in
       let gat = tryfind (fun t ->
         find_term (fun u ->
           hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
         (w :: map (fun (_,th) -> concl th) asl) in
       let mm = MATCH_MP get_real_addr_get_addr
                  (CONJ hlen (CONJ hl (CONJ cu gd))) in
       let wv = find (fun v -> fst(dest_var v) = "w")
                  (frees (concl mm)) in
       let th = SPEC (last (snd(strip_comb gat))) (GEN wv mm) in
       let a = rand (rhs (concl (CONJUNCT1 th))) in
       STRIP_ASSUME_TAC(REWRITE_RULE[WORD_RULE (mk_eq(a,swapmul a))]
                          th)) in
   let offeq = WORD_RULE
     `!(x:(N)word) i.
        x + (bytes_in_word + n2w i * bytes_in_word) =
        x + bytes_in_word + bytes_in_word * n2w i` in
   (* the length a header encodes is below two to the dimindex
      less four, and an index into such a list is a small integer *)
   let enchdr = prove
    (`!c tag len (h:'a word).
        encode_header c tag len = SOME h
        ==> len < 2 EXP (dimindex (:'a) - 4)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[encode_header_def] THEN
     COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
     DISCH_THEN(K ALL_TAC) THEN ASM_REWRITE_TAC[]) in
   let smallidx = prove
    (`!(i:num) n.
        good_dimindex (:'a) /\ i < n /\
        n < 2 EXP (dimindex (:'a) - 4)
        ==> small_int (:'a) (&i)`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[small_int_def; dimword;
                 good_dimindex_def] THEN
     DISCH_THEN(CONJUNCTS_THEN2 MP_TAC STRIP_ASSUME_TAC) THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
     RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
     CONV_TAC NUM_REDUCE_CONV THEN
     CONJ_TAC THEN
     TRY(MATCH_MP_TAC INT_LE_TRANS THEN EXISTS_TAC `&0:int` THEN
         REWRITE_TAC[INT_POS; INT_NEG_LE0; INT_POS] THEN NO_TAC) THEN
     REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   (* the index is the length of the values before the hole *)
   FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                 hd_is "LENGTH" (rhs (concl e))
             with Failure _ -> false) then fail() else
     SUBST_ALL_TAC e) THEN
   (* the invariant of the stack *)
   FIRST_ASSUM(fun mr ->
     if hd_is "memory_rel" (concl mr)
     then MP_TAC(REWRITE_RULE[memory_rel_def;
                              word_ml_inv_def; MAP; FST] mr)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[MAP; all2cons] a2) else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   (* a pointer to a mutable block is never compare-by-pointer *)
   W(fun (asl,gl) ->
     let ai = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
     let stk = el 1 (snd(strip_comb (concl ai))) in
     let blv = lhand (lhand (rand stk)) in
     SUBGOAL_THEN (mk_eq (blv,`F`)) SUBST_ALL_TAC THENL
      [ASM_CASES_TAC blv THENL
        [RULE_ASSUM_TAC (REWRITE_RULE[ASSUME blv]) THEN
         FIRST_ASSUM (fun ai2 ->
           if not (hd_is "abs_ml_inv" (concl ai2)) then fail() else
           STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def;
             bc_stack_ref_inv_def] ai2)) THEN
         FIRST_X_ASSUM (fun a2 ->
           if not (hd_is "ALL2" (concl a2) &&
                   can (find_term (hd_is "v_inv")) (concl a2))
           then fail() else
           STRIP_ASSUME_TAC (REWRITE_RULE[ALL2; NOT_CONS_NIL;
             HD; TL] a2)) THEN
         FIRST_X_ASSUM (fun vi ->
           if not (hd_is "v_inv" (concl vi) &&
                   hd_is "dataSem_RefPtr"
                     (el 1 (snd(strip_comb (concl vi)))))
           then fail() else
           STRIP_ASSUME_TAC (REWRITE_RULE[v_inv_RefPtr_T] vi)) THEN
         FIRST_ASSUM (fun fa ->
           if not (is_forall (concl fa)) then fail() else
           FIRST_ASSUM (fun lk ->
             if not (try hd_is "sptree_lookup" (lhs (concl lk))
                     with Failure _ -> false) then fail() else
             let args = snd(strip_comb (rand (rhs (concl lk)))) in
             CONTR_TAC (REWRITE_RULE[lk] (SPECL args fa))));
         ASM_REWRITE_TAC[]];
       ALL_TAC]) THEN
   (* what the invariant says of the values of the stack *)
   FIRST_ASSUM(fun am ->
     if hd_is "abs_ml_inv" (concl am)
     then MP_TAC(REWRITE_RULE[abs_ml_inv_def;
                              bc_stack_ref_inv_def] am)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2) &&
        can (find_term (hd_is "v_inv")) (concl a2)
     then MP_TAC(REWRITE_RULE[ALL2; NOT_CONS_NIL; HD; TL] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   (* the store of the value into the hole of the block *)
   W(fun (asl,gl) ->
     let ai = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
     let lk = grab asl (fun th ->
       try hd_is "sptree_lookup" (lhs (concl th))
       with Failure _ -> false) in
     MP_TAC (MATCH_MP (GEN_ALL update_mutblock_thm) (CONJ ai lk))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   (* the two roots in front are the value and the block *)
   FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && hd_is "CONS" (lhs (concl e)) &&
                 hd_is "CONS" (rhs (concl e)) &&
                 can (find_term (hd_is "gc_shared_Pointer"))
                   (rhs (concl e))
             with Failure _ -> false) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[CONS_11] e)) THEN
   REPEAT (FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                 (is_var (rhs (concl e)) ||
                  hd_is "gc_shared_Pointer" (rhs (concl e)))
             with Failure _ -> false) then fail() else
     SUBST_ALL_TAC e)) THEN
   RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
   REWRITE_TAC(word_addr_clauses ()) THEN
   FIRST_ASSUM(fun th ->
     if hd_is "heap_in_memory_store" (concl th)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   realaddr_noex THEN
   (* the payload of the block splits at the hole *)
   W(fun (asl,gl) ->
     let le = grab asl (fun th ->
       try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
           hd_is "+" (rhs (concl th))
       with Failure _ -> false) in
     let lt = REWRITE_RULE[GSYM le]
                (ARITH_RULE (mk_binop `(<):num->num->bool`
                   (lhand (rhs (concl le))) (rhs (concl le)))) in
     MP_TAC (MATCH_MP LESS_LENGTH lt)) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_X_ASSUM (fun e ->
     if not (try is_eq (concl e) && hd_is "LENGTH" (lhs (concl e)) &&
                 hd_is "LENGTH" (rhs (concl e))
             with Failure _ -> false) then fail() else
     RULE_ASSUM_TRY (REWRITE_RULE[SYM e]) THEN
     REWRITE_TAC[SYM e]) THEN
   (* and the heap splits at the block *)
   W(fun (asl,gl) ->
     MP_TAC (MATCH_MP heap_lookup_SPLIT (grab asl is_hl))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def; BlockRep_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
               word_list_def; LENGTH_MAP] THEN
   ASM_REWRITE_TAC[addreq] THEN
   REPEAT(sepfront ["cond"] THEN REWRITE_TAC[cond_STAR] THEN
          DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC)) THEN
   W(fun (asl,w) ->
     let ga = grab asl (fun th ->
       hd_is "get_real_addr" (lhs (concl th))) in
     let base = rand (rhs (concl ga)) in
     let pred = rator (lhand w) in
     let fs = facs pred in
     let one = find (fun t ->
       hd_is "set_sep_one" t &&
       not (fst(dest_pair (rand t)) = base)) fs in
     let rest = remove1 one fs in
     let st = fst(strip_comb pred) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     SUBGOAL_THEN (mk_eq(pred, mk one (end_itlist mk rest)))
       SUBST1_TAC THENL [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
   DISCH_THEN(fun sep ->
     STRIP_ASSUME_TAC(MATCH_MP read_fun2set sep) THEN
     ASSUME_TAC sep) THEN
   ASM_REWRITE_TAC[] THEN
   (* the index is a small integer, because it is below the length
      that the header of the block encodes *)
   W(fun (asl,w) ->
     let eh = grab asl (fun th ->
       hd_is "encode_header" (lhs (concl th))) in
     let le = grab asl (fun th ->
       try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
           hd_is "+" (rhs (concl th))
       with Failure _ -> false) in
     let bd = MATCH_MP enchdr eh in
     let lt = prove (mk_binop `(<):num->num->bool`
                       (lhand (rhs (concl le))) (lhand (concl bd)),
                REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN ARITH_TAC) in
     let gd = grab asl (fun th ->
       hd_is "good_dimindex" (concl th)) in
     ASSUME_TAC(MATCH_MP smallidx (CONJ gd (CONJ lt bd)))) THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi) &&
        hd_is "dataSem_Number" (el 1 (snd(strip_comb (concl vi))))
     then MP_TAC(REWRITE_RULE[v_inv_def] vi)
     else fail()) THEN
   FIRST_ASSUM(fun si ->
     if hd_is "small_int" (concl si) then REWRITE_TAC[si]
     else fail()) THEN
   DISCH_THEN(fun eq ->
     RULE_ASSUM_TAC(REWRITE_RULE[eq]) THEN REWRITE_TAC[eq]) THEN
   RULE_ASSUM_TAC(REWRITE_RULE
     (word_addr_clauses () @ [smn; and4])) THEN
   REWRITE_TAC(word_addr_clauses () @ [smn; and4]) THEN
   (* the existentials: the roots, the address and the offset *)
   W(fun (asl,w) ->
     let cs = conjuncts (snd(strip_exists w)) in
     let ga = grab asl (fun th ->
       hd_is "get_real_addr" (lhs (concl th))) in
     let gd = grab asl (fun th ->
       hd_is "good_dimindex" (concl th)) in
     let ro0 = MATCH_MP get_real_offset_thm gd in
     let iv = find (fun v -> type_of v = `:num`) (frees (concl ro0)) in
     let ro = INST [rand (rand (rand (lhs (el 1 cs)))),iv] ro0 in
     EXISTS_TAC (rand (lhs (el 0 cs))) THEN
     EXISTS_TAC (rand (lhs (el 1 cs))) THEN
     EXISTS_TAC (rand (rhs (concl ga))) THEN
     EXISTS_TAC (rand (rhs (concl ro))) THEN
     ASM_REWRITE_TAC[ro; offeq]) THEN
   (* the new heap is the old one with the hole written *)
   W(fun (asl,gl) ->
     let hs = grab asl (fun th ->
       hd_is "heap_store" (lhs (concl th))) in
     let args = snd(strip_comb (lhs (concl hs))) in
     let xs = rand (lhand (el 1 args)) in
     let ys = rand (lhand (rand (el 2 args))) in
     let hap = lhand (el 2 args) in
     let lenth = prove (mk_eq (mk_icomb (`LENGTH`,xs),
                               mk_icomb (`LENGTH`,ys)),
                  REWRITE_TAC[LENGTH_LUPDATE]) in
     let inst = MATCH_MP (ISPEC hap heap_store_BlockRep_thm)
                  lenth in
     SUBST_ALL_TAC (SYM (REWRITE_RULE[PAIR_EQ]
       (REWRITE_RULE[inst] hs)))) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[LUPDATE_LENGTH]) THEN
   (* the invariant of the new heap *)
   REWRITE_TAC[memory_rel_def] THEN
   W(fun (asl,gl) ->
     let hm = grab asl (fun th ->
       hd_is "heap_in_memory_store" (concl th)) in
     let args = snd(strip_comb (concl hm)) in
     let ai = grab asl (fun th ->
       hd_is "abs_ml_inv" (concl th) &&
       (try hd_is "sptree_insert"
              (el 2 (snd(strip_comb (concl th))))
        with Failure _ -> false)) in
     let nh = el 1 (tparts (el 3 (snd(strip_comb (concl ai))))) in
     EXISTS_TAC nh THEN EXISTS_TAC (el 9 args) THEN
     EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
     EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args)) THEN
   REPEAT CONJ_TAC THENL
    [ALL_TAC;
     (* the roots of the invariant, with the root of the value *)
     REWRITE_TAC[word_ml_inv_def] THEN
     W(fun (asl,gl) ->
       let ai = grab asl (fun th ->
         hd_is "abs_ml_inv" (concl th) &&
         (try hd_is "sptree_insert"
                (el 2 (snd(strip_comb (concl th))))
          with Failure _ -> false)) in
       EXISTS_TAC
         (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
     REWRITE_TAC[MAP; FST; SND; ALL2; HD; TL; NOT_CONS_NIL] THEN
     CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
     REWRITE_TAC(word_addr_clauses () @ [smn; and4]) THEN
     TRY (FIRST_ASSUM (fun an ->
       if not (try hd_is "ref_ptr_annot" (lhs (concl an))
               with Failure _ -> false) then fail() else
       FIRST_ASSUM (fun lk ->
         if not (try hd_is "sptree_lookup" (lhs (concl lk))
                 with Failure _ -> false) then fail() else
         REWRITE_TAC[REWRITE_RULE[lk] an]))) THEN
     ASM_REWRITE_TAC[] THEN
     REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC);
     FIRST_ASSUM ACCEPT_TAC;
     FIRST_ASSUM ACCEPT_TAC] THEN
   (* the store, whose memory is the one written *)
   REWRITE_TAC[heap_in_memory_store_def] THEN
   W(fun (asl,gl) ->
     let nh = rand (find_term (fun t ->
       hd_is "heap_length" t && hd_is "APPEND" (rand t)) gl) in
     let oh = rand (lhs (concl (grab asl is_hl))) in
     if nh = oh then ALL_TAC else
     SUBGOAL_THEN (mk_eq (mk_icomb (`heap_length`,nh),
                          mk_icomb (`heap_length`,oh)))
       (fun le -> REWRITE_TAC[le]) THENL
      [REWRITE_TAC[heap_length_APPEND; heap_length_CONS;
                   heap_length_NIL; BlockRep_def; el_length_def;
                   LENGTH_APPEND; LENGTH] THEN ARITH_TAC;
       ALL_TAC]) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   W(fun (asl,gl) ->
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const (rand (lhs (concl th)))) = "CurrHeap") in
     let ot = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const (rand (lhs (concl th)))) = "OtherHeap") in
     MAP_EVERY EXISTS_TAC [rand (rand (rhs (concl cu)));
                           rand (rand (rhs (concl ot)))]) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   (* the heap of the write, with the cell of the new root *)
   REWRITE_TAC[word_heap_APPEND; word_heap_def; BlockRep_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[MAP_APPEND; MAP; word_list_APPEND;
               word_list_def; LENGTH_MAP] THEN
   ASM_REWRITE_TAC[addreq] THEN
   REWRITE_TAC[emp_STAR; STAR_emp; STAR_ASSOC] THEN
   (* the element is as long as it was *)
   RULE_ASSUM_TRY (REWRITE_RULE[el_length_def]) THEN
   REWRITE_TAC[el_length_def; LENGTH_APPEND; LENGTH] THEN
   W(fun (asl,gl) ->
     let le = grab asl (fun th ->
       is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
       hd_is "APPEND" (rand (lhs (concl th)))) in
     REWRITE_TAC[REWRITE_RULE[LENGTH_APPEND; LENGTH] le]) THEN
   W(fun (asl,gl) ->
     let pred = rator gl in
     let fs = facs pred in
     let cell = find (hd_is "cond") fs in
     let rest = filter (fun t -> not (t = cell)) fs in
     let st = fst(strip_comb pred) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     SUBGOAL_THEN (mk_eq (pred, mk cell (end_itlist mk rest)))
       SUBST1_TAC THENL
      [REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]; ALL_TAC]) THEN
   REWRITE_TAC[cond_STAR] THEN
   CONJ_TAC THENL
    [REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
     ASM_REWRITE_TAC[] THEN TRY ASM_ARITH_TAC;
     ALL_TAC] THEN
   (* the write of the root into the cell of the hole *)
   W(fun (asl,gl) ->
     let wv = rand (rator (fst (dest_pair (rand (rand gl))))) in
     FIRST_ASSUM (fun sep ->
       if not (try hd_is "STAR" (rator (concl sep))
               with Failure _ -> false) then fail() else
       let th = SPEC wv (MATCH_MP write_fun2set sep) in
       let eq = prove (mk_eq (rator gl, rator (concl th)),
                 REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
       ACCEPT_TAC (REWRITE_RULE[GSYM eq] th))))));;

let data_to_word_memoryProof_store_list_def = cake_define_list
  [`data_to_word_memoryProof_store_list a [] (m:'a word->'a word_loc)
  dm = SOME m`;
   `data_to_word_memoryProof_store_list a (w :: ws) (m:'a word->'a
  word_loc) dm =
         (if a IN dm then
           data_to_word_memoryProof_store_list (a +
             bytes_in_word) ws ((a =+ w) m) dm else NONE)`];;
hol4_overload "store_list" "data_to_word_memoryProof_store_list";;

let store_list_append = prove
 (`!xs ys a dm m m1.
     data_to_word_memoryProof_store_list a (xs ++ ys) m dm = SOME m1
       <=>
     (?m0. data_to_word_memoryProof_store_list a xs m dm = SOME m0 /\
          data_to_word_memoryProof_store_list (a + bytes_in_word *
            n2w (LENGTH xs)) ys m0 dm = SOME m1)`,
  (* the store of the append stores xs and then ys, at the address
     that the length of xs moves on to *)
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   ASM_REWRITE_TAC[APPEND;
                   data_to_word_memoryProof_store_list_def;
                   LENGTH; WORD_ADD_MUL_0; WORD_ADD_MUL_SUC] THEN
   TRY(COND_CASES_TAC) THEN
   ASM_REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
   MESON_TAC[]));;

(* [local] *)
let minus_lemma = prove
 (`--(n2w 1) * (bytes_in_word * w) = bytes_in_word * --w`,
  (CONV_TAC WORD_RULE));;

let n2w_lsr_eq_0 = prove
 (`n DIV 2 EXP k = 0 /\ n < dimword (:'a) ==> n2w n >>> k = ((n2w
  0):'a word)`,
  (REPEAT STRIP_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[dimword]) THEN
   ASM_SIMP_TAC[GSYM VAL_EQ_0; VAL_WORD_USHR; VAL_WORD; MOD_LT]));;

(* [local] *)
let LESS_EXO_SUB = prove
 (`n < 2 EXP (k - m) ==> n < 2 EXP k`,
  (DISCH_TAC THEN MATCH_MP_TAC LTE_TRANS THEN
   EXISTS_TAC `2 EXP (k - m)` THEN
   ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN ARITH_TAC));;

(* [local] *)
let LESS_EXO_SUB_ALT = prove
 (`m <= k ==> n < 2 EXP (k - m) ==> n * 2 EXP m < 2 EXP k`,
  (REPEAT STRIP_TAC THEN
   SUBGOAL_THEN `2 EXP k = 2 EXP (k - m) * 2 EXP m` SUBST1_TAC THENL
    [REWRITE_TAC[GSYM EXP_ADD] THEN AP_TERM_TAC THEN ASM_ARITH_TAC;
     ASM_REWRITE_TAC[LT_MULT_RCANCEL; EXP_EQ_0; ARITH_EQ]]));;

(* [local] *)
let less_pow_dimindex_sub_imp = prove
 (`n < 2 EXP (dimindex (:'a) - k) ==> n < dimword (:'a)`,
  (REWRITE_TAC[dimword] THEN MATCH_ACCEPT_TAC LESS_EXO_SUB));;

let encode_header_NEQ_0 = prove
 (`encode_header c n k = SOME w ==> ~(w = (n2w 0))`,
  (* the header has the lowest bit of its three set, and a word
     with a bit is not zero *)
  (REWRITE_TAC[encode_header_def] THEN
   COND_CASES_TAC THEN
   REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
   DISCH_THEN(SUBST1_TAC o SYM) THEN
   REWRITE_TAC[make_header_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
   DISCH_THEN(MP_TAC o SPEC `0`) THEN
   REWRITE_TAC[BIT_WORD_OR; BIT_WORD_0; BIT_WORD] THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   REWRITE_TAC[ARITH_RULE `0 < d <=> 1 <= d`; DIMINDEX_GE_1]));;

(* [local] *)
let encode_header_IMP = prove
 (`encode_header c tag len = SOME (hd:'a word) /\
  data_to_word_config_len_size
     c + 5 < dimindex (:'a) /\ good_dimindex (:'a) ==>
     len < 2 EXP (dimindex (:'a) - 4) /\
     decode_length c hd = n2w len`,
  (* what encode_header gives back is make_header of the tag and the
     length, so the length is the one of its condition and the shift
     down of decode_length undoes the shift up that make_header did:
     the tag and the three are below the shift, so the shift down
     loses them *)
  (let hi = prove
    (`!n r (i:num). n < 2 EXP r /\ r <= i
        ==> ~(bit i ((n2w n):'a word))`,
     MATCH_ACCEPT_TAC BIT_WORD_HI) in
   let b3 = prove
    (`!j. j < dimindex (:'a)
          ==> (bit j ((n2w 3):'a word) <=> j < 2)`,
     GEN_TAC THEN DISCH_TAC THEN
     ASM_CASES_TAC `(j:num) < 2` THEN ASM_REWRITE_TAC[] THENL
      [FIRST_ASSUM(DISJ_CASES_THEN SUBST_ALL_TAC o MATCH_MP
         (ARITH_RULE `(j:num) < 2 ==> j = 0 \/ j = 1`)) THEN
       ASM_REWRITE_TAC[BIT_WORD] THEN CONV_TAC NUM_REDUCE_CONV THEN
       ASM_ARITH_TAC;
       MP_TAC(ISPECL [`3`; `2`; `j:num`] hi) THEN
       ASM_SIMP_TAC[ARITH_RULE `~((j:num) < 2) ==> 2 <= j`] THEN
       CONV_TAC NUM_REDUCE_CONV]) in
   REWRITE_TAC[encode_header_def] THEN
   COND_CASES_TAC THEN
   REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM) STRIP_ASSUME_TAC) THEN
   CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC;
     REWRITE_TAC[decode_length_def; make_header_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     SUBGOAL_THEN
       `!j. bit j (((n2w tag) << 2 || (n2w 3)):'a word)
            ==> j < dimindex (:'a) -
                    data_to_word_config_len_size c`
       (fun th -> REWRITE_TAC[MATCH_MP USHR_OR_LOW th]) THENL
      [X_GEN_TAC `j:num` THEN
       REWRITE_TAC[BIT_WORD_OR; BIT_WORD_SHL] THEN STRIP_TAC THENL
        [MP_TAC(ISPECL
           [`tag:num`;
            `dimindex (:'a) - data_to_word_config_len_size c - 2`;
            `j - 2`] hi) THEN
         ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC;
         MP_TAC(MATCH_MP b3 (ASSUME `j < dimindex (:'a)`)) THEN
         ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC];
       MATCH_MP_TAC USHR_SHL_CANCEL THEN
       X_GEN_TAC `j:num` THEN
       ASM_CASES_TAC `bit j ((n2w len):'a word)` THEN
       ASM_REWRITE_TAC[] THEN
       MP_TAC(ISPECL
         [`len:num`; `data_to_word_config_len_size c`; `j:num`] hi) THEN
       ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_UpdateThunk_NotEvaluated = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((h,w) :: (RefPtr F nn,ptr) :: vars) /\
      lookup nn refs = SOME (Thunk NotEvaluated v) /\
      good_dimindex (:'a) ==>
      (?ptr_w (x:'a word).
        ptr = wordLang_Word ptr_w /\
        get_real_addr c st ptr_w = SOME x /\
        (x + bytes_in_word) IN dm /\
        memory_rel c be ts (insert nn (Thunk NotEvaluated h) refs)
          sp st
          (((x + bytes_in_word) =+ w) m) dm
          ((h,w) :: (RefPtr F nn,ptr) :: vars))`),
(* the proof of the source names memory_rel_def, word_ml_inv_def,
   update_thunk_thm, LENGTH_EQ_1 and word_addr_def, and writes the
   cell with HOL4's SEP_W_TAC.  Here update_thunk_thm (at
   NotEvaluated, where its last hypothesis is vacuous) gives the
   roots -- the root of the value and the pointer of the reference
   -- and the store of the new thunk; roots_ok says the heap has a
   data element at that pointer, which thunk_deref makes the thunk
   that was not evaluated, and heap_lookup_SPLIT and
   heap_store_lemma make the old heap and the new one the same but
   for that element.  The address is get_real_addr_get_addr's, the
   cell of the value is the second of the element (its cond says
   the element has one word), and the write of the root into it is
   write_fun2set: the header of the new element is the header of
   the old one, because both hold one word *)
  (let len1 = prove
   (`!l. LENGTH (l:(A)list) = 1 <=> ?x. l = [x]`,
    GEN_TAC THEN
    STRUCT_CASES_TAC (ISPEC `l:(A)list` list_CASES) THEN
    REWRITE_TAC[LENGTH; CONS_11; NOT_CONS_NIL; ARITH_EQ] THEN
    REWRITE_TAC[ARITH_RULE `SUC n = 1 <=> n = 0`; LENGTH_EQ_NIL] THEN
    MESON_TAC[]) in

  let rec facs t =
    if hd_is "STAR" t then
      let args = snd (strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in

  let sfront nm sep =
    let pred = rator (concl sep) in
    let fs = facs pred in
    let cell = find (hd_is nm) fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst (strip_comb pred) in
    let mk x y = mk_comb (mk_comb (st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target), REWRITE_TAC[STAR_AC]) in
    REWRITE_RULE[eq] sep in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let nev = prove (`~(NotEvaluated = Evaluated)`,
    MESON_TAC[distinctness "thunk_mode"]) in
  let utn = REWRITE_RULE[EQF_INTRO nev]
    (INST [`NotEvaluated`,`ev:thunk_mode`] update_thunk_thm) in
  STRIP_TAC THEN
  FIRST_ASSUM (fun mr ->
    if hd_is "memory_rel" (concl mr)
    then STRIP_ASSUME_TAC (REWRITE_RULE[memory_rel_def] mr)
    else fail()) THEN
  FIRST_ASSUM (fun h ->
    if hd_is "heap_in_memory_store" (concl h)
    then STRIP_ASSUME_TAC
           (REWRITE_RULE[heap_in_memory_store_def] h)
    else fail()) THEN
  FIRST_ASSUM (fun wi ->
    if hd_is "word_ml_inv" (concl wi)
    then STRIP_ASSUME_TAC (REWRITE_RULE[word_ml_inv_def] wi)
    else fail()) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[MAP; FST; SND]) THEN
  FIRST_ASSUM (fun ai ->
    if not (hd_is "abs_ml_inv" (concl ai)) then fail() else
    FIRST_ASSUM (fun lk ->
      if not (try hd_is "sptree_lookup" (lhs (concl lk))
              with Failure _ -> false) then fail() else
      STRIP_ASSUME_TAC (MATCH_MP (GEN_ALL utn) (CONJ ai lk)))) THEN
  (* the roots are the root of the value and the pointer *)
  FIRST_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                hd_is "CONS" (rhs (concl e))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[ALL2]) THEN
  REPEAT (FIRST_X_ASSUM (CONJUNCTS_THEN ASSUME_TAC)) THEN
  (* the heap has a data element at the pointer *)
  FIRST_ASSUM (fun ai ->
    if not (hd_is "abs_ml_inv" (concl ai) &&
            not (hd_is "sptree_insert"
                   (el 2 (snd (strip_comb (concl ai))))))
    then fail() else
    STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def] ai)) THEN
  FIRST_ASSUM (fun rk ->
    if not (hd_is "roots_ok" (concl rk)) then fail() else
    MP_TAC (REWRITE_RULE[roots_ok_def; MEM] rk)) THEN
  W(fun (asl,gl) ->
    let td = grab asl (fun th ->
      try hd_is "thunk_deref" (lhs (concl th))
      with Failure _ -> false) in
    let pp = lhand (lhs (concl td)) in
    let wa = grab asl (fun th ->
      try hd_is "word_addr" (lhs (concl th)) &&
          hd_is "gc_shared_Pointer" (rand (lhs (concl th))) &&
          lhand (rand (lhs (concl th))) = pp
      with Failure _ -> false) in
    let uu = rand (rand (lhs (concl wa))) in
    DISCH_THEN (fun rk -> MP_TAC (SPECL [pp; uu] rk))) THEN
  REWRITE_TAC[] THEN
  REWRITE_TAC[isSomeDataElement_def] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* which is the thunk that was not evaluated *)
  FIRST_ASSUM (fun hl ->
    if not (try is_eq (concl hl) &&
                hd_is "heap_lookup" (lhs (concl hl))
            with Failure _ -> false) then fail() else
    FIRST_ASSUM (fun td ->
      if not (try hd_is "thunk_deref" (lhs (concl td))
              with Failure _ -> false) then fail() else
      MP_TAC (REWRITE_RULE[thunk_deref_def; hl] td))) THEN
  EVERY_CASE_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
  (* the heap splits at the pointer *)
  FIRST_ASSUM (fun hl ->
    if not (try is_eq (concl hl) &&
                hd_is "heap_lookup" (lhs (concl hl))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                (hd_is "APPEND" (rhs (concl e)) ||
                 hd_is "heap_length" (rhs (concl e)))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  (* and the store put the new thunk there *)
  FIRST_ASSUM (fun hs ->
    if not (try is_eq (concl hs) &&
                hd_is "heap_store" (lhs (concl hs))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_lemma; PAIR_EQ;
              ThunkBlock_def; heap_length_def; el_length_def; MAP;
              SUM_DEF; ITLIST] hs)) THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the element has one word *)
  SUBGOAL_THEN `l = 1` SUBST_ALL_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  (* the address of the pointer *)
  FIRST_ASSUM (fun hb ->
    if not (try hd_is "<=" (concl hb) with Failure _ -> false)
    then fail() else
    FIRST_ASSUM (fun hl ->
      if not (try is_eq (concl hl) &&
                  hd_is "heap_lookup" (lhs (concl hl))
              with Failure _ -> false) then fail() else
      FIRST_ASSUM (fun ch ->
        if not (try is_eq (concl ch) &&
                    hd_is "FLOOKUP" (lhs (concl ch))
                with Failure _ -> false) then fail() else
        FIRST_ASSUM (fun gd ->
          if not (hd_is "good_dimindex" (concl gd)) then fail() else
          STRIP_ASSUME_TAC (MATCH_MP (GEN_ALL get_real_addr_get_addr)
            (CONJ hb (CONJ hl (CONJ ch gd)))))))) THEN
  RULE_ASSUM_TRY (REWRITE_RULE(word_addr_clauses ())) THEN
  W(fun (asl,gl) ->
    let wa = grab asl (fun th ->
      try is_eq (concl th) &&
          hd_is "wordLang_Word" (lhs (concl th)) &&
          hd_is "get_addr" (rand (lhs (concl th)))
      with Failure _ -> false) in
    let uu = rand (rand (lhs (concl wa))) in
    let fa = grab asl (fun th ->
      is_forall (concl th) &&
      (try can (find_term (hd_is "get_real_addr")) (concl th)
       with Failure _ -> false)) in
    STRIP_ASSUME_TAC (SPEC uu fa)) THEN
  (* so the goal is about that address *)
  W(fun (asl,gl) ->
    let wa = grab asl (fun th ->
      try is_eq (concl th) &&
          hd_is "wordLang_Word" (lhs (concl th)) &&
          hd_is "get_addr" (rand (lhs (concl th)))
      with Failure _ -> false) in
    let pw = rand (lhs (concl wa)) in
    let gra = grab asl (fun th ->
      try is_eq (concl th) &&
          hd_is "get_real_addr" (lhs (concl th))
      with Failure _ -> false) in
    let xv = rand (rhs (concl gra)) in
    MAP_EVERY EXISTS_TAC [pw; xv]) THEN
  (* the two cells of the thunk *)
  FIRST_ASSUM (fun sep ->
    if not (try hd_is "STAR" (rator (concl sep))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[word_heap_APPEND; word_heap_def;
      word_el_def; el_length_def] sep)) THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; STAR_ASSOC] THEN
  DISCH_THEN (fun sep ->
     STRIP_ASSUME_TAC (REWRITE_RULE[cond_STAR]
       (sfront "cond" sep))) THEN
  FIRST_ASSUM (fun le ->
    if not (try is_eq (concl le) && hd_is "LENGTH" (lhs (concl le))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC (REWRITE_RULE[len1] le)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                hd_is "CONS" (rhs (concl e))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[MAP; word_list_def; STAR_ASSOC;
                              emp_STAR; STAR_emp]) THEN
  (* the cell of the value is in the memory and can be written *)
  FIRST_ASSUM (fun sep ->
    if not (try hd_is "STAR" (rator (concl sep))
            with Failure _ -> false) then fail() else
    let isp t = hd_is "set_sep_one" t &&
      (try let a = fst (dest_pair (rand t)) in
           hd_is "word_add" a && hd_is "bytes_in_word" (rand a)
       with Failure _ -> false) in
    let pred = rator (concl sep) in
    let fs = facs pred in
    let cell = find isp fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst (strip_comb pred) in
    let mk x y = mk_comb (mk_comb (st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target), REWRITE_TAC[STAR_AC]) in
    let sep' = REWRITE_RULE[eq] sep in
    STRIP_ASSUME_TAC (MATCH_MP read_fun2set sep') THEN
    ASSUME_TAC (MATCH_MP write_fun2set sep')) THEN
  (* the first three conjuncts *)
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM (fun wa ->
      if not (try is_eq (concl wa) &&
                  hd_is "wordLang_Word" (lhs (concl wa)) &&
                  hd_is "get_addr" (rand (lhs (concl wa)))
              with Failure _ -> false) then fail() else
      ACCEPT_TAC (SYM wa));
    FIRST_ASSUM ACCEPT_TAC;
    W(fun (asl,gl) ->
      let ind = grab asl (fun th ->
         try hd_is "IN" (concl th) &&
             hd_is "word_add" (lhand (concl th))
        with Failure _ -> false) in
      SUBST1_TAC (WORD_RULE (mk_eq (lhand gl, lhand (concl ind)))) THEN
      ACCEPT_TAC ind);
    ALL_TAC] THEN
  (* the invariant with the new thunk in the heap *)
  REWRITE_TAC[memory_rel_def] THEN
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "sptree_insert"
             (el 2 (snd (strip_comb (concl th))))
       with Failure _ -> false)) in
    let args = snd (strip_comb (concl ai)) in
    let ps = tparts (el 3 args) in
    MAP_EVERY EXISTS_TAC [el 1 ps; el 4 args; el 3 ps; el 4 ps;
                          el 5 ps; el 6 ps]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (REWRITE_TAC[word_ml_inv_def] THEN
       W(fun (asl,gl) ->
         let ai = grab asl (fun th ->
           hd_is "abs_ml_inv" (concl th) &&
           (try hd_is "sptree_insert"
                  (el 2 (snd (strip_comb (concl th))))
            with Failure _ -> false)) in
         EXISTS_TAC (el 0 (tparts (el 3 (snd (strip_comb
           (concl ai))))))) THEN
       REWRITE_TAC[MAP; FST; SND; ALL2] THEN
       REWRITE_TAC(word_addr_clauses ()) THEN
       ASM_REWRITE_TAC[] THEN NO_TAC) THEN
  (* the store, whose memory is the written one *)
  REWRITE_TAC[heap_in_memory_store_def] THEN
  RULE_ASSUM_TRY (REWRITE_RULE[LENGTH]) THEN
  (* the new heap is as long as the old one *)
  W(fun (asl,gl) ->
    let h2 = grab asl (fun th ->
      try is_eq (concl th) && hd_is "APPEND" (lhs (concl th))
      with Failure _ -> false) in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          length (filter (hd_is "word_heap")
                    (facs (rator (concl th)))) = 2
      with Failure _ -> false) in
    let oldheap = el 1 (snd (strip_comb
      (hd (filter (hd_is "word_heap")
             (facs (rator (concl sep))))))) in
    let hl t = mk_icomb (`heap_length`, t) in
    SUBGOAL_THEN (mk_eq (hl (rhs (concl h2)), hl oldheap))
      (fun le -> REWRITE_TAC[le]) THENL
     [REWRITE_TAC[SYM h2; APPEND] THEN
      REWRITE_TAC[heap_length_APPEND] THEN
      REWRITE_TAC[heap_length_CONS; el_length_def] THEN
      ARITH_TAC;
      ALL_TAC]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST_ASSUM (fun sep ->
    if not (try hd_is "STAR" (rator (concl sep))
            with Failure _ -> false) then fail() else
    let fs = facs (rator (concl sep)) in
    let whs = filter (hd_is "word_heap") fs in
    if not (length whs = 2) then fail() else
    MAP_EVERY EXISTS_TAC
      [el 0 (snd (strip_comb (el 0 whs)));
       el 0 (snd (strip_comb (el 1 whs)))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST_ASSUM (fun h2 ->
    if not (try is_eq (concl h2) && hd_is "APPEND" (lhs (concl h2))
            with Failure _ -> false) then fail() else
    REWRITE_TAC[SYM h2]) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_def; word_el_def;
              el_length_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; MAP; LENGTH; STAR_ASSOC] THEN
  W(fun (asl,gl) ->
    let pred = rator gl in
    let fs = facs pred in
    let cell = find (hd_is "cond") fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst (strip_comb pred) in
    let mk x y = mk_comb (mk_comb (st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    SUBGOAL_THEN (mk_eq (pred,target)) SUBST1_TAC THENL
     [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
  REWRITE_TAC[cond_STAR] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
    RULE_ASSUM_TRY (REWRITE_RULE[LENGTH]) THEN
    RULE_ASSUM_TRY (CONV_RULE NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[] THEN TRY (CONV_TAC NUM_REDUCE_CONV);
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[heap_length_CONS; heap_length_NIL; el_length_def] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[emp_STAR; STAR_emp; STAR_ASSOC] THEN
  RULE_ASSUM_TRY (CONV_RULE NUM_REDUCE_CONV) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[emp_STAR; STAR_emp; STAR_ASSOC]) THEN
  (* the address of the write, as the cell of the thunk has it *)
  W(fun (asl,gl) ->
    let upd = fst (dest_pair (rand (rand gl))) in
    let gaddr = lhand (rator upd) in
    let ind = grab asl (fun th ->
      try hd_is "IN" (concl th) &&
          hd_is "word_add" (lhand (concl th))
      with Failure _ -> false) in
    let taddr = lhand (concl ind) in
    if gaddr = taddr then ALL_TAC
    else SUBST1_TAC (WORD_RULE (mk_eq (gaddr, taddr)))) THEN
  W(fun (asl,gl) ->
    let pred = rator gl in
    let wv = rand (rator (fst (dest_pair (rand (rand gl))))) in
    FIRST_ASSUM (fun wth ->
      let th = (try SPEC wv wth with Failure _ -> wth) in
      let wp = rator (concl th) in
      if not (hd_is "STAR" wp) then fail() else
      let eq = prove (mk_eq (pred,wp),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      ACCEPT_TAC (REWRITE_RULE[GSYM eq] th)))));;

(* [local] *)
let thunk_tag_bits_lemma = prove
 (`(thunk_tag_to_bits Evaluated << 3 || (n2w 6)) = ((n2w 14):'a word)`,
  (* three is the tag of an evaluated thunk, so the word is 8 or 6 *)
  (REWRITE_TAC[thunk_tag_to_bits_def] THEN
   MATCH_REDUCE_TAC THEN
   WORD_NUM_BIT_TAC 4));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_UpdateThunk_Evaluated = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((h,w) :: (RefPtr F nn,ptr) :: vars) /\
      lookup nn refs = SOME (Thunk NotEvaluated v) /\
      encode_header c (8 + 6) 1 = SOME hdr /\
      dest_thunk h refs = NotThunk /\
      good_dimindex (:'a) ==>
      (?ptr_w (x:'a word).
        ptr = wordLang_Word ptr_w /\
        get_real_addr c st ptr_w = SOME x /\
        x IN dm /\ (x + bytes_in_word) IN dm /\
        memory_rel c be ts (insert nn (Thunk Evaluated h) refs) sp
          st
          (UPDATE_LIST m [x,wordLang_Word hdr; x +
            bytes_in_word,w]) dm
          ((h,w) :: (RefPtr F nn,ptr) :: vars))`),
(* the same proof as memory_rel_UpdateThunk_NotEvaluated, which the
   source names the same theorems for -- memory_rel_def,
   word_ml_inv_def, update_thunk_thm, LENGTH_EQ_1, word_addr_def,
   thunk_deref_def, get_real_addr_get_addr, heap_lookup_SPLIT and
   the store lemma -- but now the mode of the thunk changes, so the
   header of the new element is another word than the header of the
   old one: encode_header_def says the hdr of the statement is
   make_header of n2w 14, thunk_tag_bits_lemma says the bits of an
   evaluated thunk with the six are that same word, and so the two
   cells that write_fun2set writes are the header and the root of
   the value; the cond of the new element is the length that
   encode_header_IMP reads back off the hdr (what HOL4 does with
   SEP_R_TAC and SEP_W_TAC) *)
  (let len1 = prove
   (`!l. LENGTH (l:(A)list) = 1 <=> ?x. l = [x]`,
    GEN_TAC THEN
    STRUCT_CASES_TAC (ISPEC `l:(A)list` list_CASES) THEN
    REWRITE_TAC[LENGTH; CONS_11; NOT_CONS_NIL; ARITH_EQ] THEN
    REWRITE_TAC[ARITH_RULE `SUC n = 1 <=> n = 0`; LENGTH_EQ_NIL] THEN
    MESON_TAC[]) in

  let rec facs t =
    if hd_is "STAR" t then
      let args = snd (strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in

  let sfront nm sep =
    let pred = rator (concl sep) in
    let fs = facs pred in
    let cell = find (hd_is nm) fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst (strip_comb pred) in
    let mk x y = mk_comb (mk_comb (st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target), REWRITE_TAC[STAR_AC]) in
    REWRITE_RULE[eq] sep in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let utn = INST [`Evaluated`,`ev:thunk_mode`] update_thunk_thm in
  let indm =
    W(fun (asl,gl) ->
      tryfind (fun (_,th) ->
        if not (try hd_is "IN" (concl th)
                with Failure _ -> false) then fail() else
        let eq = WORD_RULE (mk_eq (lhand gl, lhand (concl th))) in
        SUBST1_TAC eq THEN ACCEPT_TAC th) asl) in
  let someif = prove
   (`!p (x:A) y. (if p then SOME x else NONE) = SOME y ==> x = y`,
    REPEAT GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"]) in
  STRIP_TAC THEN
  (* what encode_header gave back is make_header of the tag *)
  FIRST_ASSUM (fun eh ->
    if not (try hd_is "encode_header" (lhs (concl eh))
            with Failure _ -> false) then fail() else
    ASSUME_TAC (CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
      (REWRITE_RULE[encode_header_def] eh)))) THEN
  FIRST_ASSUM (fun mr ->
    if hd_is "memory_rel" (concl mr)
    then STRIP_ASSUME_TAC (REWRITE_RULE[memory_rel_def] mr)
    else fail()) THEN
  FIRST_ASSUM (fun h ->
    if hd_is "heap_in_memory_store" (concl h)
    then STRIP_ASSUME_TAC
           (REWRITE_RULE[heap_in_memory_store_def] h)
    else fail()) THEN
  FIRST_ASSUM (fun wi ->
    if hd_is "word_ml_inv" (concl wi)
    then STRIP_ASSUME_TAC (REWRITE_RULE[word_ml_inv_def] wi)
    else fail()) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[MAP; FST; SND]) THEN
  FIRST_ASSUM (fun ai ->
    if not (hd_is "abs_ml_inv" (concl ai)) then fail() else
    FIRST_ASSUM (fun lk ->
      if not (try hd_is "sptree_lookup" (lhs (concl lk))
              with Failure _ -> false) then fail() else
      FIRST_ASSUM (fun dt ->
        if not (try hd_is "dataSem_dest_thunk" (lhs (concl dt)) ||
                    hd_is "dest_thunk" (lhs (concl dt))
                with Failure _ -> false) then fail() else
        STRIP_ASSUME_TAC (MATCH_MP (GEN_ALL utn)
          (CONJ ai (CONJ lk
             (DISCH `(Evaluated:thunk_mode) = Evaluated` dt))))))) THEN
  REWRITE_TAC[UPDATE_LIST_THM; FST; SND] THEN
  (* the roots are the root of the value and the pointer *)
  FIRST_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                hd_is "CONS" (rhs (concl e))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[ALL2]) THEN
  REPEAT (FIRST_X_ASSUM (CONJUNCTS_THEN ASSUME_TAC)) THEN
  (* the heap has a data element at the pointer *)
  FIRST_ASSUM (fun ai ->
    if not (hd_is "abs_ml_inv" (concl ai) &&
            not (hd_is "sptree_insert"
                   (el 2 (snd (strip_comb (concl ai))))))
    then fail() else
    STRIP_ASSUME_TAC (REWRITE_RULE[abs_ml_inv_def] ai)) THEN
  FIRST_ASSUM (fun rk ->
    if not (hd_is "roots_ok" (concl rk)) then fail() else
    MP_TAC (REWRITE_RULE[roots_ok_def; MEM] rk)) THEN
  W(fun (asl,gl) ->
    let td = grab asl (fun th ->
      try hd_is "thunk_deref" (lhs (concl th))
      with Failure _ -> false) in
    let pp = lhand (lhs (concl td)) in
    let wa = grab asl (fun th ->
      try hd_is "word_addr" (lhs (concl th)) &&
          hd_is "gc_shared_Pointer" (rand (lhs (concl th))) &&
          lhand (rand (lhs (concl th))) = pp
      with Failure _ -> false) in
    let uu = rand (rand (lhs (concl wa))) in
    DISCH_THEN (fun rk -> MP_TAC (SPECL [pp; uu] rk))) THEN
  REWRITE_TAC[] THEN
  REWRITE_TAC[isSomeDataElement_def] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* which is the thunk that was not evaluated *)
  FIRST_ASSUM (fun hl ->
    if not (try is_eq (concl hl) &&
                hd_is "heap_lookup" (lhs (concl hl))
            with Failure _ -> false) then fail() else
    FIRST_ASSUM (fun td ->
      if not (try hd_is "thunk_deref" (lhs (concl td))
              with Failure _ -> false) then fail() else
      MP_TAC (REWRITE_RULE[thunk_deref_def; hl] td))) THEN
  EVERY_CASE_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
  (* the heap splits at the pointer *)
  FIRST_ASSUM (fun hl ->
    if not (try is_eq (concl hl) &&
                hd_is "heap_lookup" (lhs (concl hl))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                (hd_is "APPEND" (rhs (concl e)) ||
                 hd_is "heap_length" (rhs (concl e)))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  (* and the store put the new thunk there *)
  FIRST_ASSUM (fun hs ->
    if not (try is_eq (concl hs) &&
                hd_is "heap_store" (lhs (concl hs))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_lemma; PAIR_EQ;
              ThunkBlock_def; heap_length_def; el_length_def; MAP;
              SUM_DEF; ITLIST] hs)) THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the element has one word *)
  SUBGOAL_THEN `l = 1` SUBST_ALL_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  (* the address of the pointer *)
  FIRST_ASSUM (fun hb ->
    if not (try hd_is "<=" (concl hb) with Failure _ -> false)
    then fail() else
    FIRST_ASSUM (fun hl ->
      if not (try is_eq (concl hl) &&
                  hd_is "heap_lookup" (lhs (concl hl))
              with Failure _ -> false) then fail() else
      FIRST_ASSUM (fun ch ->
        if not (try is_eq (concl ch) &&
                    hd_is "FLOOKUP" (lhs (concl ch))
                with Failure _ -> false) then fail() else
        FIRST_ASSUM (fun gd ->
          if not (hd_is "good_dimindex" (concl gd)) then fail() else
          STRIP_ASSUME_TAC (MATCH_MP (GEN_ALL get_real_addr_get_addr)
            (CONJ hb (CONJ hl (CONJ ch gd)))))))) THEN
  RULE_ASSUM_TRY (REWRITE_RULE(word_addr_clauses ())) THEN
  W(fun (asl,gl) ->
    let wa = grab asl (fun th ->
      try is_eq (concl th) &&
          hd_is "wordLang_Word" (lhs (concl th)) &&
          hd_is "get_addr" (rand (lhs (concl th)))
      with Failure _ -> false) in
    let uu = rand (rand (lhs (concl wa))) in
    let fa = grab asl (fun th ->
      is_forall (concl th) &&
      (try can (find_term (hd_is "get_real_addr")) (concl th)
       with Failure _ -> false)) in
    STRIP_ASSUME_TAC (SPEC uu fa)) THEN
  (* so the goal is about that address *)
  W(fun (asl,gl) ->
    let wa = grab asl (fun th ->
      try is_eq (concl th) &&
          hd_is "wordLang_Word" (lhs (concl th)) &&
          hd_is "get_addr" (rand (lhs (concl th)))
      with Failure _ -> false) in
    let pw = rand (lhs (concl wa)) in
    let gra = grab asl (fun th ->
      try is_eq (concl th) &&
          hd_is "get_real_addr" (lhs (concl th))
      with Failure _ -> false) in
    let xv = rand (rhs (concl gra)) in
    MAP_EVERY EXISTS_TAC [pw; xv]) THEN
  (* the two cells of the thunk *)
  FIRST_ASSUM (fun sep ->
    if not (try hd_is "STAR" (rator (concl sep))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[word_heap_APPEND; word_heap_def;
      word_el_def; el_length_def] sep)) THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; STAR_ASSOC] THEN
  DISCH_THEN (fun sep ->
     STRIP_ASSUME_TAC (REWRITE_RULE[cond_STAR]
       (sfront "cond" sep))) THEN
  FIRST_ASSUM (fun le ->
    if not (try is_eq (concl le) && hd_is "LENGTH" (lhs (concl le))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC (REWRITE_RULE[len1] le)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                hd_is "CONS" (rhs (concl e))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[MAP; word_list_def; STAR_ASSOC;
                              emp_STAR; STAR_emp]) THEN
  (* the two cells of the thunk, read and then written *)
  FIRST_ASSUM (fun sep ->
    if not (try hd_is "STAR" (rator (concl sep))
            with Failure _ -> false) then fail() else
    let front sp cell =
      let pred = rator (concl sp) in
      let fs = facs pred in
      let rest = filter (fun t -> not (t = cell)) fs in
      let st = fst (strip_comb pred) in
      let mk x y = mk_comb (mk_comb (st,x),y) in
      let target = mk cell (end_itlist mk rest) in
      let eq = prove (mk_eq (pred,target),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      REWRITE_RULE[eq] sp in
    let ispay t = (try let a = fst (dest_pair (rand t)) in
                       hd_is "word_add" a &&
                       hd_is "bytes_in_word" (rand a)
                   with Failure _ -> false) in
    let cells = filter (hd_is "set_sep_one")
                  (facs (rator (concl sep))) in
    let hdrc = find (fun t -> not (ispay t)) cells in
    MAP_EVERY STRIP_ASSUME_TAC
      (map (fun c -> MATCH_MP read_fun2set (front sep c)) cells) THEN
    W(fun (asl,gl) ->
      let mrl = last (conjuncts gl) in
      let upd1 = el 6 (snd (strip_comb mrl)) in
      let wv1 = rand (rator (rand upd1)) in
      let wh1 = SPEC wv1 (MATCH_MP write_fun2set (front sep hdrc)) in
      let payc = find ispay (facs (rator (concl wh1))) in
      ASSUME_TAC (MATCH_MP write_fun2set (front wh1 payc)))) THEN
  (* the first four conjuncts *)
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM (fun wa ->
      if not (try is_eq (concl wa) &&
                  hd_is "wordLang_Word" (lhs (concl wa)) &&
                  hd_is "get_addr" (rand (lhs (concl wa)))
              with Failure _ -> false) then fail() else
      ACCEPT_TAC (SYM wa));
    FIRST_ASSUM ACCEPT_TAC;
    indm; indm;
    ALL_TAC] THEN
  (* the invariant with the new thunk in the heap *)
  REWRITE_TAC[memory_rel_def] THEN
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "sptree_insert"
             (el 2 (snd (strip_comb (concl th))))
       with Failure _ -> false)) in
    let args = snd (strip_comb (concl ai)) in
    let ps = tparts (el 3 args) in
    MAP_EVERY EXISTS_TAC [el 1 ps; el 4 args; el 3 ps; el 4 ps;
                          el 5 ps; el 6 ps]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (REWRITE_TAC[word_ml_inv_def] THEN
       W(fun (asl,gl) ->
         let ai = grab asl (fun th ->
           hd_is "abs_ml_inv" (concl th) &&
           (try hd_is "sptree_insert"
                  (el 2 (snd (strip_comb (concl th))))
            with Failure _ -> false)) in
         EXISTS_TAC (el 0 (tparts (el 3 (snd (strip_comb
           (concl ai))))))) THEN
       REWRITE_TAC[MAP; FST; SND; ALL2] THEN
       REWRITE_TAC(word_addr_clauses ()) THEN
       ASM_REWRITE_TAC[] THEN NO_TAC) THEN
  (* the store, whose memory is the written one *)
  REWRITE_TAC[heap_in_memory_store_def] THEN
  RULE_ASSUM_TRY (REWRITE_RULE[LENGTH]) THEN
  (* the new heap is as long as the old one *)
  W(fun (asl,gl) ->
    let h2 = grab asl (fun th ->
      try is_eq (concl th) && hd_is "APPEND" (lhs (concl th))
      with Failure _ -> false) in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          length (filter (hd_is "word_heap")
                    (facs (rator (concl th)))) = 2
      with Failure _ -> false) in
    let oldheap = el 1 (snd (strip_comb
      (hd (filter (hd_is "word_heap")
             (facs (rator (concl sep))))))) in
    let hl t = mk_icomb (`heap_length`, t) in
    SUBGOAL_THEN (mk_eq (hl (rhs (concl h2)), hl oldheap))
      (fun le -> REWRITE_TAC[le]) THENL
     [REWRITE_TAC[SYM h2; APPEND] THEN
      REWRITE_TAC[heap_length_APPEND] THEN
      REWRITE_TAC[heap_length_CONS; el_length_def] THEN
      ARITH_TAC;
      ALL_TAC]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST_ASSUM (fun sep ->
    if not (try hd_is "STAR" (rator (concl sep))
            with Failure _ -> false) then fail() else
    let fs = facs (rator (concl sep)) in
    let whs = filter (hd_is "word_heap") fs in
    if not (length whs = 2) then fail() else
    MAP_EVERY EXISTS_TAC
      [el 0 (snd (strip_comb (el 0 whs)));
       el 0 (snd (strip_comb (el 1 whs)))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST_ASSUM (fun h2 ->
    if not (try is_eq (concl h2) && hd_is "APPEND" (lhs (concl h2))
            with Failure _ -> false) then fail() else
    REWRITE_TAC[SYM h2]) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_def; word_el_def;
              el_length_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; MAP; LENGTH; STAR_ASSOC] THEN
  REWRITE_TAC[thunk_tag_bits_lemma] THEN
  FIRST_ASSUM (fun mh ->
    if not (try is_eq (concl mh) &&
                hd_is "make_header" (lhs (concl mh))
            with Failure _ -> false) then fail() else
    REWRITE_TAC[mh]) THEN
  W(fun (asl,gl) ->
    let pred = rator gl in
    let fs = facs pred in
    let cell = find (hd_is "cond") fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst (strip_comb pred) in
    let mk x y = mk_comb (mk_comb (st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    SUBGOAL_THEN (mk_eq (pred,target)) SUBST1_TAC THENL
     [REWRITE_TAC[STAR_AC]; ALL_TAC]) THEN
  REWRITE_TAC[cond_STAR] THEN
  CONJ_TAC THENL
   [(* the length that encode_header_IMP reads back off the hdr *)
    REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
    SUBGOAL_THEN (cake_as_vars (fun () ->
      `data_to_word_config_len_size c + 5 < dimindex (:'a)`))
      ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM (fun eh ->
      if not (try hd_is "encode_header" (lhs (concl eh))
              with Failure _ -> false) then fail() else
      FIRST_ASSUM (fun c2 ->
        if not (try hd_is "<" (concl c2) &&
                    hd_is "+" (lhand (concl c2))
                with Failure _ -> false) then fail() else
        FIRST_ASSUM (fun gd ->
          if not (hd_is "good_dimindex" (concl gd)) then fail()
          else STRIP_ASSUME_TAC (MATCH_MP encode_header_IMP
            (CONJ eh (CONJ c2 gd)))))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[heap_length_CONS; heap_length_NIL; el_length_def] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[emp_STAR; STAR_emp; STAR_ASSOC] THEN
  RULE_ASSUM_TRY (CONV_RULE NUM_REDUCE_CONV) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[emp_STAR; STAR_emp; STAR_ASSOC]) THEN
  (* the address of the write, as the cell of the thunk has it *)
  W(fun (asl,gl) ->
    let upd = fst (dest_pair (rand (rand gl))) in
    let ia = lhand (rator (rand upd)) in
    let cells = filter (hd_is "set_sep_one") (facs (rator gl)) in
    let addrs = map (fun c -> fst (dest_pair (rand c))) cells in
    let targ = find (fun a ->
      can WORD_RULE (mk_eq (ia,a))) addrs in
    if targ = ia then ALL_TAC
    else SUBST1_TAC (WORD_RULE (mk_eq (ia,targ)))) THEN
  W(fun (asl,gl) ->
    let upd = fst (dest_pair (rand (rand gl))) in
    let gaddr = lhand (rator upd) in
    let ind = grab asl (fun th ->
      try hd_is "IN" (concl th) &&
          hd_is "word_add" (lhand (concl th))
      with Failure _ -> false) in
    let taddr = lhand (concl ind) in
    if gaddr = taddr then ALL_TAC
    else SUBST1_TAC (WORD_RULE (mk_eq (gaddr, taddr)))) THEN
  W(fun (asl,gl) ->
    let pred = rator gl in
    let wv = rand (rator (fst (dest_pair (rand (rand gl))))) in
    FIRST_ASSUM (fun wth ->
      let th = (try SPEC wv wth with Failure _ -> wth) in
      let wp = rator (concl th) in
      if not (hd_is "STAR" wp) then fail() else
      let eq = prove (mk_eq (pred,wp),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      ACCEPT_TAC (REWRITE_RULE[GSYM eq] th)))));;

let word_list_exists_thm = prove
 (`(word_list_exists a 0 = emp) /\
    (word_list_exists a (SUC n) =
     SEP_EXISTS (\w. set_sep_one (a,w) * word_list_exists (a +
       bytes_in_word) n))`,
  (* the two clauses of word_list_exists: at zero it is emp, and at
     a successor it is the cell at the address beside the list of
     the rest -- the existential of the definition is over the list
     of the words, and the condition on its length picks the empty
     list or a cons *)
  (CONJ_TAC THEN ONCE_REWRITE_TAC[FUN_EQ_THM] THEN GEN_TAC THEN
   REWRITE_TAC[word_list_exists_def] THEN
   REWRITE_TAC[STAR_SEP_EXISTS; SEP_EXISTS_THM] THEN
   REWRITE_TAC[STAR_ASSOC; STAR_cond] THEN
   REWRITE_TAC[GSYM(CONJUNCT2 word_list_def)] THEN
   REWRITE_TAC[LENGTH_EQ_NIL; emp_def] THENL
    [REWRITE_TAC[UNWIND_THM2; word_list_def; emp_def];
     MESON_TAC[LENGTH_EQ_CONS; LENGTH]]));;

let word_list_exists_ADD = prove
 (`!m n a.
      word_list_exists a (m + n) =
      word_list_exists a m *
      word_list_exists (a + bytes_in_word * n2w m) n`,
  (* the SEP_EXISTS of the head comes out of the separating
     conjunction (the first clause of HOL4's SEP_CLAUSES), and the
     address of the tail is the head's address shifted once *)
  (INDUCT_TAC THEN
   ASM_REWRITE_TAC[word_list_exists_thm; ADD; emp_STAR; STAR_ASSOC;
                   SEP_EXISTS_STAR; WORD_ADD_MUL_SUC;
                   WORD_ADD_MUL_0]));;

let store_list_thm = prove
 (`!xs a frame m dm.
      (word_list_exists a (LENGTH xs) * frame) (fun2set (m,dm)) ==>
      (?m1.
        data_to_word_memoryProof_store_list a xs m dm = SOME m1 /\
        (misc_word_list a xs * frame) (fun2set (m1,dm)))`,
  (* the store of a list of words into a space that word_list_exists
     describes: the space of a cons is a cell and the space of the
     rest, read_fun2set says the address of the cell is in the
     domain, write_fun2set says what the store at it leaves, and the
     induction hypothesis stores the rest with the cell in the frame *)
  (let aux = prove
    (`!(xs:((N)word_loc) list) (a:(N)word) frame m dm.
        (word_list_exists a (LENGTH xs) * frame) (fun2set (m,dm))
        ==> ?m1. data_to_word_memoryProof_store_list a xs m dm =
                 SOME m1 /\
                 (misc_word_list a xs * frame) (fun2set (m1,dm))`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
      [REWRITE_TAC[LENGTH; word_list_exists_thm;
                   word_list_def;
                   data_to_word_memoryProof_store_list_def] THEN
       DISCH_TAC THEN
       EXISTS_TAC `m:(N)word->(N)word_loc` THEN
       ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     REWRITE_TAC[LENGTH; word_list_exists_thm;
                 word_list_def;
                 data_to_word_memoryProof_store_list_def] THEN
     REWRITE_TAC[SEP_EXISTS_STAR; SEP_EXISTS_THM] THEN
     DISCH_THEN(X_CHOOSE_THEN `w:(N)word_loc` MP_TAC) THEN
     REWRITE_TAC[GSYM STAR_ASSOC] THEN DISCH_TAC THEN
     FIRST_ASSUM(fun th -> MP_TAC(MATCH_MP read_fun2set th)) THEN
     DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ASSUME_TAC) THEN
     ASM_REWRITE_TAC[] THEN
     FIRST_ASSUM(fun th ->
       MP_TAC(MATCH_MP (ISPEC `h:(N)word_loc` write_fun2set) th)) THEN
     DISCH_TAC THEN
     FIRST_X_ASSUM(fun ih ->
       MP_TAC(SPECL [`a + bytes_in_word:(N)word`;
                     `set_sep_one (a:(N)word,h:(N)word_loc) * frame`;
                     `(a =+ (h:(N)word_loc)) (m:(N)word->(N)word_loc)`;
                     `dm:(N)word->bool`] ih)) THEN
     ANTS_TAC THENL
      [FIRST_X_ASSUM(fun th -> MP_TAC th) THEN
       REWRITE_TAC[STAR_AC];
       ALL_TAC] THEN
     DISCH_THEN(X_CHOOSE_THEN `m1:(N)word->(N)word_loc`
       STRIP_ASSUME_TAC) THEN
     EXISTS_TAC `m1:(N)word->(N)word_loc` THEN
     ASM_REWRITE_TAC[] THEN
     FIRST_X_ASSUM(fun th -> MP_TAC th) THEN
     REWRITE_TAC[STAR_AC]) in
   MATCH_ACCEPT_TAC aux));;

let store_list_domain = prove
 (`!a xs m dm m1.
   data_to_word_memoryProof_store_list a xs m dm = SOME m1 ==>
   (!n. n < LENGTH xs ==> a + n2w n * bytes_in_word IN dm)`,
  (* the n-th address of the store is the first one shifted n
     times, which the induction over the list takes apart *)
  (let aux = prove
    (`!xs (a:(N)word) m dm m1.
        data_to_word_memoryProof_store_list a xs m dm = SOME m1
        ==> !n. n < LENGTH xs
                ==> a + n2w n * bytes_in_word IN dm`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[data_to_word_memoryProof_store_list_def;
                 LENGTH; CONJUNCT1 LT] THEN
     COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
     DISCH_TAC THEN X_GEN_TAC `k:num` THEN
     STRUCT_CASES_TAC(SPEC `k:num` num_CASES) THEN
     ASM_REWRITE_TAC[WORD_ADD_0_MUL; LT_SUC; WORD_ADD_SUC_MUL;
                     LT_0] THEN
     DISCH_TAC THEN USE_IH THEN DISCH_THEN MATCH_MP_TAC THEN
     FIRST_ASSUM ACCEPT_TAC) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let store_list_append_imp = prove
 (`!w1 a m dm m' w2.
   data_to_word_memoryProof_store_list a (w1 ++ w2) m dm = SOME m'
     ==>
   (?m''. data_to_word_memoryProof_store_list a w1 m dm = SOME m'' /\
         data_to_word_memoryProof_store_list (a + n2w (LENGTH w1) *
           bytes_in_word) w2 m'' dm = SOME m')`,
  (let aux = prove
    (`!w1 (a:(N)word) m dm m' w2.
        data_to_word_memoryProof_store_list a (APPEND w1 w2) m dm =
          SOME m'
        ==> ?m''.
              data_to_word_memoryProof_store_list a w1 m dm =
                SOME m'' /\
              data_to_word_memoryProof_store_list
                (a + n2w (LENGTH w1) * bytes_in_word) w2 m'' dm =
                SOME m'`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[APPEND;
                 data_to_word_memoryProof_store_list_def;
                 LENGTH; WORD_ADD_0_MUL; WORD_ADD_SUC_MUL] THEN
     TRY COND_CASES_TAC THEN
     REWRITE_TAC[distinctness "option"] THEN DISCH_TAC THEN
     TRY USE_IH THEN ASM_MESON_TAC[]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let store_list_update_m_outside = prove
 (`!ws a m dm m'.
   data_to_word_memoryProof_store_list a ws m dm = SOME m' /\
   (!i. i < LENGTH ws ==> ~(a + n2w i * bytes_in_word = a')) ==>
   data_to_word_memoryProof_store_list a ws ((a' =+ v) m) dm = SOME
     ((a' =+ v) m')`,
  (* the store of a list of words does not disturb an address that
     none of its stores touches, and the update of the memory at
     such an address commutes with every store of the list; the
     address of the i-th store of the tail is the one of the
     (i+1)-th store of the list *)
  (let upd_comm = prove
    (`!a b x y (f:A->B). ~(a = b)
        ==> (a =+ x) ((b =+ y) f) = (b =+ y) ((a =+ x) f)`,
     REPEAT STRIP_TAC THEN REWRITE_TAC[FUN_EQ_THM; UPDATE] THEN
     GEN_TAC THEN REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
     ASM_MESON_TAC[]) in
   let wzero = prove
    (`!(a:(N)word). a + n2w 0 * bytes_in_word = a`,
     CONV_TAC WORD_RULE) in
   let wsuc = prove
    (`!(a:(N)word) i.
        (a + bytes_in_word) + n2w i * bytes_in_word =
        a + n2w (SUC i) * bytes_in_word`,
     REWRITE_TAC[ADD1; WORD_ADD] THEN CONV_TAC WORD_RULE) in
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[data_to_word_memoryProof_store_list_def] THENL
    [REWRITE_TAC[injectivity "option"] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[SYM(CONJUNCT1 th)]);
     COND_CASES_TAC THEN
     REWRITE_TAC[distinctness "option"] THEN STRIP_TAC THEN
     FIRST_ASSUM(fun th ->
       let th' = REWRITE_RULE[wzero; LENGTH; LT_0] (SPEC `0` th) in
       if is_neg (concl th') then ASSUME_TAC th' else fail()) THEN
     FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP upd_comm th]) THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN
     ASM_REWRITE_TAC[wsuc] THEN
     GEN_TAC THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
     ASM_REWRITE_TAC[LENGTH; LT_SUC]]));;

let word_payload_IMP = prove
 (`word_payload addrs ll tags tt1 conf = (h,ts,T) ==> LENGTH ts = ll`,
  (* every clause of word_payload gives the payload as a list of
     the same length as the one it is made of; the equation that
     says what ts is has to be used the other way round, and MESON
     does not get past the header of the clause *)
  (let use_ts (asl,w as gl) =
     let v = var_by_name "ts" gl in
     let ok t = can rhs (concl t) && rhs(concl t) = v in
     let th = tryfind (fun (_,t) -> if ok t then t else fail()) asl in
     (SUBST1_TAC(SYM th) THEN ASM_REWRITE_TAC[LENGTH_MAP]) gl in
   CASES_ON_NAME "tags" THEN
   REWRITE_TAC[word_payload_def; PAIR_EQ] THEN
   EVERY_CASE_TAC THEN REPEAT STRIP_TAC THEN use_ts));;

let word_el_IMP_word_list_exists = prove
 (`!temp p curr.
      (p * word_el curr temp conf) s ==>
      (p * word_list_exists curr (el_length temp)) s`,
  (* whatever a heap element says of the memory, the space it takes
     is free space of its own length: an Unused element is that
     space already, a ForwardPointer is a cell and the space after
     it, and a DataElement is a word_list, whose length the
     condition of word_el and word_payload_IMP give *)
  (let wlie = prove
    (`!(xs:((M)word_loc) list) (a:(N)word) p s.
        (p * misc_word_list a xs) s
        ==> (p * word_list_exists a (LENGTH xs)) s`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[word_list_exists_def; STAR_SEP_EXISTS;
                 SEP_EXISTS_THM] THEN
     DISCH_TAC THEN EXISTS_TAC `xs:((M)word_loc) list` THEN
     REWRITE_TAC[STAR_ASSOC; STAR_cond] THEN
     ASM_REWRITE_TAC[]) in
   let aux = prove
    (`!conf s (temp:((M)word_loc,
                     data_to_word_memoryProof_tag #
                     ((M)word_loc) list)heap_element) p (curr:(N)word).
        (p * word_el curr temp conf) s
        ==> (p * word_list_exists curr (el_length temp)) s`,
     REPEAT GEN_TAC THEN CASES_ON_NAME "temp" THENL
      [REWRITE_TAC[word_el_def; el_length_def];
       REWRITE_TAC[word_el_def; el_length_def] THEN
       REWRITE_TAC[GSYM ADD1; word_list_exists_thm] THEN
       REWRITE_TAC[STAR_SEP_EXISTS; SEP_EXISTS_THM] THEN
       DISCH_TAC THEN
       EXISTS_TAC `wordLang_Word ((n2w a0 << 2):(M)word)` THEN
       FIRST_ASSUM ACCEPT_TAC;
       MP_TAC(ISPEC `a2:data_to_word_memoryProof_tag #
                        ((M)word_loc) list` PAIR_SURJECTIVE) THEN
       DISCH_THEN(X_CHOOSE_THEN `tag:data_to_word_memoryProof_tag`
         (X_CHOOSE_THEN `qs:((M)word_loc) list` SUBST1_TAC)) THEN
       REWRITE_TAC[word_el_def; el_length_def] THEN
       W(fun (asl,w) ->
         let pr = find_term (fun t ->
           (try fst(dest_const(fst(strip_comb t))) = "word_payload"
            with Failure _ -> false)) w in
         MP_TAC(ISPEC pr PAIR_SURJECTIVE)) THEN
       DISCH_THEN(X_CHOOSE_THEN `hh:(M)word`
         (X_CHOOSE_THEN `rest:((M)word_loc) list # bool`
           ASSUME_TAC)) THEN
       MP_TAC(ISPEC `rest:((M)word_loc) list # bool`
         PAIR_SURJECTIVE) THEN
       DISCH_THEN(X_CHOOSE_THEN `ts:((M)word_loc) list`
         (X_CHOOSE_THEN `cc:bool` SUBST_ALL_TAC)) THEN
       ASM_REWRITE_TAC[] THEN
       CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
       REWRITE_TAC[STAR_ASSOC; STAR_cond] THEN
       STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `cc:bool`]) THEN
       FIRST_ASSUM(fun pay ->
         MP_TAC(MATCH_MP word_payload_IMP pay)) THEN
       DISCH_TAC THEN
       FIRST_ASSUM(fun st ->
         MP_TAC(MATCH_MP wlie
           (REWRITE_RULE[GSYM STAR_ASSOC] st))) THEN
       ASM_REWRITE_TAC[LENGTH; ADD1]]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let word_heap_IMP_word_list_exists = prove
 (`!temp p curr.
      (p * word_heap curr temp conf) s ==>
      (p * word_list_exists curr (heap_length temp)) s`,
  (* and the same of a whole heap, element by element: the space of
     a cons splits by word_list_exists_ADD, and the induction
     hypothesis takes the rest with the first element's space in the
     frame *)
  (let swap2 = prove
    (`!(p:((A)->bool)->bool) q r. (p * q) * r = (p * r) * q`,
     REWRITE_TAC[STAR_AC]) in
   let aux = prove
    (`!(temp:(((M)word_loc,
               data_to_word_memoryProof_tag #
               ((M)word_loc) list)heap_element) list) conf s p
        (curr:(N)word).
        (p * word_heap curr temp conf) s
        ==> (p * word_list_exists curr (heap_length temp)) s`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
      [REWRITE_TAC[word_heap_def; heap_length_NIL;
                   word_list_exists_thm];
       ALL_TAC] THEN
     REWRITE_TAC[word_heap_def;
                 heap_length_CONS] THEN
     REWRITE_TAC[word_list_exists_ADD] THEN
     REWRITE_TAC[STAR_ASSOC] THEN
     DISCH_TAC THEN
     FIRST_ASSUM(fun st ->
       MP_TAC(ONCE_REWRITE_RULE[swap2] st)) THEN
     DISCH_THEN(fun st ->
       MP_TAC(MATCH_MP word_el_IMP_word_list_exists
         st)) THEN
     DISCH_THEN(fun st -> MP_TAC(ONCE_REWRITE_RULE[swap2] st)) THEN
     FIRST_X_ASSUM(fun ih ->
       DISCH_THEN(fun st -> MP_TAC(MATCH_MP ih st))) THEN
     REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

(* [local] *)
let EVERY2_f_EQ = prove
 (`!rs ws f. EVERY2 (\v w. f v = w) rs ws <=> MAP f rs = ws`,
  (let aux = prove
    (`!(f:A->B) rs ws. ALL2 (\v w. f v = w) rs ws <=> MAP f rs = ws`,
     GEN_TAC THEN LIST_INDUCT_TAC THEN X_GEN_TAC `ws:B list` THEN
     STRUCT_CASES_TAC(ISPEC `ws:B list` list_CASES_v) THEN
     ASM_REWRITE_TAC[ALL2; MAP; CONS_11; NOT_CONS_NIL;
                     EQ_SYM_EQ]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

let word_heap_heap_expand = prove
 (`word_heap a (heap_expand n) conf = word_list_exists a n`,
  (STRUCT_CASES_TAC(SPEC `n:num` num_CASES) THEN
   ASM_REWRITE_TAC[heap_expand_def; NOT_SUC;
                   word_heap_def; word_el_def;
                   STAR_emp; CONJUNCT1 word_list_exists_thm;
                   ARITH_RULE `SUC n - 1 = n`; ADD1]));;

(* [local] *)
let get_lowerbits_or_1 = prove
 (`get_lowerbits c v = (get_lowerbits c v || (n2w 1))`,
  (CASES_ON_NAME "v" THEN
   REWRITE_TAC[get_lowerbits_def] THEN
   MATCH_REDUCE_TAC THEN WORD_BITWISE_TAC));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Word64_alt = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm (vs ++ vars) /\ good_dimindex
  (:'a) /\
     (Word64Rep (:'a) w64:('a
       word_loc,data_to_word_memoryProof_tag#('a word_loc)
       list)heap_element) = DataElement [] (LENGTH ws) (Word64Tag,ws) /\
     LENGTH ws < sp /\
     encode_header c 3 (LENGTH ws) = SOME hd ==>
     (?ne curr m1.
       FLOOKUP st NextFree = SOME (wordLang_Word ne) /\
       FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
       data_to_word_memoryProof_store_list ne (wordLang_Word hd ::
         ws) m dm = SOME m1 /\
       memory_rel c be ts refs (sp - (LENGTH ws + 1))
          (st |+ (NextFree,wordLang_Word (ne + bytes_in_word * n2w
            (LENGTH ws + 1)))) m1 dm
          ((Word64 w64,make_ptr c (ne - curr) ((n2w 0):'a word)
            (LENGTH ws)) :: vars))`),
(* the allocation of a word of sixty-four bits, which is
   memory_rel_Cons1 with word64_alt_thm in place of cons_thm_alt:
   the roots of the values of the stack split off the rest
   (EVERY2_SWAP and EVERY2_APPEND_IMP_APPEND), the element is the
   Word64Rep that the statement says it is -- its words are the
   data of its tag, so no root of it is a pointer -- and the words
   that store_list_thm writes are the header and those.  The
   pointer is make_ptr of the offset, as in memory_rel_Ref, and
   the condition of the payload is that the header encodes the
   length (encode_header_IMP) and is a SOME *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let front sp cell =
    let pred = rator (concl sp) in
    let fs = facs pred in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk x y = mk_comb(mk_comb(st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target),
              REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
    REWRITE_RULE[eq] sp in
  (* two steps of an address in one *)
  let addsum = prove
   (`!(a:'a word) x y.
       a + bytes_in_word * n2w x + bytes_in_word * n2w y =
       a + bytes_in_word * n2w (x + y)`,
    REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE) in
  (* the bits of a zero word are zero *)
  let bits0 = prove
   (`!h l. word_bits h l ((n2w 0):(N)word) = n2w 0`,
    REWRITE_TAC[word_bits; WORD_EQ_BITS_ALT; BIT_WORD_SUBWORD;
                BIT_WORD_0] THEN
    CONV_TAC TAUT) in
  let someif = prove
   (`!p (x:A) y. (if p then SOME x else NONE) = SOME y ==> x = y`,
    REPEAT GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"]) in
  (* the numeric facts that the assumptions give *)
  let numfacts asl =
    mapfilter (fun (_,th) ->
      let c = concl th in
      if (try hd_is "<=" c || hd_is "<" c ||
              (is_eq c && hd_is "LENGTH" (lhs c) &&
               hd_is "LENGTH" (rhs c))
          with Failure _ -> false) then th else fail()) asl in
  let addreq asl t1 t2 =
      let fs = numfacts asl in
      let extra = (try
        let lt = grab asl (fun th ->
          try hd_is "<" (concl th) &&
              hd_is "LENGTH" (lhand (concl th))
          with Failure _ -> false) in
        let spe = grab asl (fun th ->
          try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
              is_var (rand (concl th))
          with Failure _ -> false) in
        [MATCH_MP (ARITH_RULE
           `!a b c:num. a < b /\ b <= c ==> a + 1 <= c`)
           (CONJ lt spe)]
        with Failure _ -> []) in
      let cnd = end_itlist CONJ (fs @ extra) in
      MP (prove (mk_imp (concl cnd, mk_eq (t1,t2)),
            DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
              (fun th -> ASSUME_TAC
                 (REWRITE_RULE[LENGTH; ADD1] th))) THEN
            ASM_REWRITE_TAC[el_length_def; LENGTH; ADD1] THEN
            REWRITE_TAC[WORD_SUB; WORD_ADD] THEN
            ASM_SIMP_TAC[ARITH_RULE
              `!l s h:num. l <= s ==> l <= h + s`;
              ARITH_RULE
              `!a b c:num. a <= b /\ b <= c ==> a <= c`] THEN
            CONV_TAC WORD_RULE)) cnd in
  let wordeq =
    W(fun (asl,gl) ->
      REWRITE_TAC[addreq asl (rand (rand (lhs gl)))
                    (rand (rand (rhs gl)))]) in
  (* a store that says the same of a key, with the numbers of the
     new element in place of the old ones *)
  let numeq =
    W(fun (asl,gl) ->
      let fl = grab asl (fun th ->
        try hd_is "FLOOKUP" (lhs (concl th)) &&
            rand (lhs (concl th)) = rand (lhs gl) &&
            not (concl th = gl)
        with Failure _ -> false) in
      let isn t = (try hd_is "word" t &&
                       type_of (rand t) = `:num` &&
                       not (is_numeral (rand t))
                   with Failure _ -> false) in
      let ge = find_term isn (rhs gl) in
      let fe = find_term isn (rhs (concl fl)) in
      let fs = numfacts asl in
      let cnd = end_itlist CONJ fs in
      let eq = MP (prove (mk_imp (concl cnd,
                    mk_eq (rand ge, rand fe)),
                  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
                    ASSUME_TAC) THEN
                  REWRITE_TAC[el_length_def; LENGTH; ADD1] THEN
                  ASM_ARITH_TAC)) cnd in
      REWRITE_TAC[eq] THEN FIRST_ASSUM ACCEPT_TAC) in
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* what the invariant says of the stack *)
  FIRST_ASSUM (fun mr ->
    if hd_is "memory_rel" (concl mr)
    then MP_TAC (REWRITE_RULE[memory_rel_def; word_ml_inv_def] mr)
    else fail()) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the roots of the values and the roots of the stack *)
  RULE_ASSUM_TRY (REWRITE_RULE[MAP_APPEND]) THEN
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      try hd_is "ALL2" (concl th) &&
          hd_is "APPEND" (el 2 (snd(strip_comb (concl th))))
      with Failure _ -> false) in
    STRIP_ASSUME_TAC (MATCH_MP EVERY2_APPEND_IMP_APPEND
      (MATCH_MP EVERY2_SWAP a2))) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                hd_is "APPEND" (rhs (concl e))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  REPEAT (FIRST_X_ASSUM (fun a2 ->
    if not (try hd_is "ALL2" (concl a2) &&
                hd_is "MAP" (el 1 (snd(strip_comb (concl a2))))
            with Failure _ -> false) then fail() else
    ASSUME_TAC (CONV_RULE (TOP_DEPTH_CONV BETA_CONV)
      (MATCH_MP EVERY2_SWAP a2)) THEN
    ASSUME_TAC (MATCH_MP LIST_REL_LENGTH a2))) THEN
  (* the element that holds the word *)
  W(fun (asl,gl) ->
    let ai = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
    let lt = grab asl (fun th ->
      try hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false) in
    let spe = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          lhand (concl th) = rand (concl lt)
      with Failure _ -> false) in
    let bnd = MATCH_MP (ARITH_RULE
                `!b c d:num. b < c /\ c <= d ==> b < d`)
                (CONJ lt spe) in
    let mfst = lhand (el 1 (snd(strip_comb (concl ai)))) in
    let rts = lhand (el 0 (tparts
                (el 3 (snd(strip_comb (concl ai)))))) in
    let lmap = REWRITE_CONV[LENGTH_MAP]
                 (mk_icomb (`LENGTH`,mfst)) in
    let leq = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          rhs (concl th) = mk_icomb (`LENGTH`,rts)
      with Failure _ -> false) in
    let le = TRANS lmap (REWRITE_RULE[LENGTH_MAP] leq) in
    let wr = grab asl (fun th ->
      try is_eq (concl th) && hd_is "Word64Rep" (lhs (concl th))
      with Failure _ -> false) in
    MP_TAC (MATCH_MP (GEN_ALL word64_alt_thm)
      (CONJ ai (CONJ le (CONJ wr bnd))))) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the element is the one the statement says it is *)
  W(fun (asl,gl) ->
    let wr = grab asl (fun th ->
      try is_eq (concl th) && hd_is "Word64Rep" (lhs (concl th))
      with Failure _ -> false) in
    RULE_ASSUM_TRY (REWRITE_RULE[wr]) THEN REWRITE_TAC[wr]) THEN
  (* the ends of the heap that the store holds *)
  FIRST_ASSUM (fun hs ->
    if hd_is "heap_in_memory_store" (concl hs)
    then STRIP_ASSUME_TAC
           (REWRITE_RULE[heap_in_memory_store_def] hs)
    else fail()) THEN
  (* the unused space of the heap, where the element goes *)
  FIRST_ASSUM (fun hu ->
    if not (try hd_is "heap_store_unused_alt" (lhs (concl hu))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_unused_alt_def] hu)) THEN
  COND_CASES_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  FIRST_X_ASSUM (fun cnd ->
    if not (is_conj (concl cnd)) then fail() else
    if not (try hd_is "heap_lookup" (lhs (lhand (concl cnd)))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC cnd) THEN
  (* so the heap splits there *)
  FIRST_ASSUM (fun hl ->
    if not (try hd_is "heap_lookup" (lhs (concl hl))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                (hd_is "APPEND" (rhs (concl e)) ||
                 hd_is "heap_length" (rhs (concl e)))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  (* and the store writes the element at the end of the space *)
  FIRST_ASSUM (fun hs ->
    if not (try hd_is "heap_store" (lhs (concl hs))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_lemma; PAIR_EQ] hs)) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the words of the unused space, and its end where the element
     goes *)
  W(fun (asl,gl) ->
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "el_length" (lhand (concl th))
      with Failure _ -> false) in
    let e1 = CONV_RULE NUM_REDUCE_CONV
               (REWRITE_RULE[el_length_def] bnd) in
    let eq1 = MATCH_MP (ARITH_RULE
                `!k s:num. k + 1 <= s ==> (s - 1) + 1 = s`) e1 in
    let eq3 = MATCH_MP (ARITH_RULE
                `!k s:num. k + 1 <= s
                           ==> (k + 1) + (s - (k + 1)) = s`) e1 in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th))
      with Failure _ -> false) in
    let sep1 = REWRITE_RULE[word_heap_APPEND; word_heap_def;
                 word_el_def; el_length_def; eq1] sep in
    let addr = el 0 (snd(strip_comb (find (fun t ->
                 hd_is "word_list_exists" t)
                 (facs (rator (concl sep1)))))) in
    let wle = REWRITE_RULE[eq3]
                (ISPECL [lhand (lhs (concl eq3));
                         rand (lhs (concl eq3)); addr]
                   word_list_exists_ADD) in
    let sep2 = REWRITE_RULE[wle; STAR_ASSOC] sep1 in
    ASSUME_TAC sep2) THEN
  (* the words of the element are as many as its roots, and its
     address is the end of the heap less them *)
  W(fun (asl,gl) ->
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          length (filter (hd_is "word_list_exists")
                   (facs (rator (concl th)))) = 2
      with Failure _ -> false) in
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "el_length" (lhand (concl th))
      with Failure _ -> false) in
    let e1 = CONV_RULE NUM_REDUCE_CONV
               (REWRITE_RULE[el_length_def] bnd) in
    let cells = filter (hd_is "word_list_exists")
                  (facs (rator (concl sep))) in
    let count = el 1 (snd(strip_comb (el 0 cells))) in
    let xs = el 1 (snd(strip_comb (find_term
               (hd_is "data_to_word_memoryProof_store_list") gl))) in
    let lenq = prove (mk_eq (count, mk_icomb (`LENGTH`,xs)),
                REWRITE_TAC[LENGTH] THEN ARITH_TAC) in
    let sep4 = REWRITE_RULE[lenq] sep in
    let bnd2 = REWRITE_RULE[lenq] e1 in
    ASSUME_TAC sep4 THEN ASSUME_TAC bnd2 THEN
    REWRITE_TAC[lenq]) THEN
  (* which the store writes there *)
  W(fun (asl,gl) ->
    let iscell t = hd_is "word_list_exists" t &&
                   hd_is "LENGTH" (el 1 (snd(strip_comb t))) in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let cell = find iscell (facs (rator (concl sep))) in
    STRIP_ASSUME_TAC (MATCH_MP store_list_thm (front sep cell))) THEN
  (* the ends of the heap, and the memory that the store wrote *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    let sl = grab asl (fun th ->
      try hd_is "data_to_word_memoryProof_store_list"
            (lhs (concl th))
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "NextFree"))));
       rand (rand (rhs (concl (flk "CurrHeap"))));
       rand (rhs (concl sl))]) THEN
  (* the address of the element is the end of the heap less the
     words it takes *)
  W(fun (asl,gl) ->
    let sl = find_term
               (hd_is "data_to_word_memoryProof_store_list") gl in
    let t1 = el 0 (snd(strip_comb sl)) in
    let iscell t = hd_is "misc_word_list" t &&
                   hd_is "CONS" (el 1 (snd(strip_comb t))) in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let t2 = el 0 (snd(strip_comb
               (find iscell (facs (rator (concl sep)))))) in
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false) in
    let eq = MP (prove (mk_imp (concl bnd, mk_eq (t1,t2)),
                  DISCH_TAC THEN ASM_SIMP_TAC[WORD_SUB] THEN
                  REWRITE_TAC[WORD_ADD] THEN
                  CONV_TAC WORD_RULE)) bnd in
    REWRITE_TAC[eq]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the invariant with the new element in the heap *)
  REWRITE_TAC[memory_rel_def] THEN
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
       with Failure _ -> false)) in
    let args = snd(strip_comb (concl ai)) in
    let ps = tparts (el 3 args) in
    MAP_EVERY EXISTS_TAC
      [el 1 ps; el 4 args; el 3 ps; el 4 ps; el 5 ps; el 6 ps]) THEN
  REPEAT CONJ_TAC THENL
   [ALL_TAC;
    (* the roots: the pointer of the new reference and the rest *)
    REWRITE_TAC[word_ml_inv_def] THEN
    W(fun (asl,gl) ->
      let ai = grab asl (fun th ->
        hd_is "abs_ml_inv" (concl th) &&
        (try hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
         with Failure _ -> false)) in
      EXISTS_TAC
        (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
    REWRITE_TAC[MAP; FST; SND; ALL2] THEN
    CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    (* the word of the pointer is the one make_ptr builds *)
    W(fun (asl,gl) ->
      let mp = rhs gl in
      let sub = el 1 (snd(strip_comb mp)) in
      let aterm = lhand sub in
      let bwterm = rand aterm in
      let pt = lhand (rand (lhs gl)) in
      let mulp = mk_comb (rator bwterm,
                   mk_comb (rator (rand bwterm), pt)) in
      SUBST1_TAC (addreq asl sub mulp)) THEN
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      REWRITE_TAC(word_addr_clauses ()) THEN
      REWRITE_TAC[make_ptr_def; get_addr_def;
                  get_lowerbits_def] THEN
      MATCH_REDUCE_TAC THEN
      REWRITE_TAC[MATCH_MP bytes_in_word_mul_eq_shift gd;
                  WORD_SHL_COMPOSE; bits0] THEN
      ASM_SIMP_TAC[ARITH_RULE
        `!a b:num. a <= b ==> a + (b - a) = b`] THEN
      REWRITE_TAC[WORD_OR_0; WORD_ADD_0]);
    FIRST_ASSUM ACCEPT_TAC;
    W(fun (asl,gl) ->
      let spe = grab asl (fun th ->
        try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
            is_var (rand (concl th))
        with Failure _ -> false) in
      let les = mapfilter (fun (_,th) ->
        if (try is_eq (concl th) &&
                hd_is "LENGTH" (lhs (concl th)) &&
                hd_is "LENGTH" (rhs (concl th))
            with Failure _ -> false) then th else fail()) asl in
      MP_TAC (end_itlist CONJ (spe :: les))) THEN
    REWRITE_TAC[el_length_def; LENGTH; ADD1] THEN
    ARITH_TAC] THEN
  (* the store of the new heap: its length is the old one *)
  REWRITE_TAC[heap_in_memory_store_def] THEN
  W(fun (asl,gl) ->
    let hu = grab asl (fun th ->
      try hd_is "heap_store_unused_alt" (lhs (concl th))
      with Failure _ -> false) in
    REWRITE_TAC[MATCH_MP heap_store_unused_alt_IMP_length hu]) THEN
  W(fun (asl,gl) ->
    let dis = CONJUNCTS (distinctness "store_name") in
    REWRITE_TAC([FLOOKUP_UPDATE; FDOM_FUPDATE; IN_INSERT] @
                dis @ map GSYM dis)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the two heaps of the store *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "CurrHeap"))));
       rand (rand (rhs (concl (flk "OtherHeap"))))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (wordeq THEN NO_TAC) THEN
  TRY (numeq THEN NO_TAC) THEN
  (* the heap with the new element, which the store wrote *)
  FIRST_ASSUM (fun h2 ->
    if not (try is_eq (concl h2) && hd_is "APPEND" (lhs (concl h2)) &&
                is_var (rhs (concl h2))
            with Failure _ -> false) then fail() else
    SUBST1_TAC (SYM h2)) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_heap_expand;
              word_heap_def; heap_length_APPEND;
              heap_length_heap_expand] THEN
  REWRITE_TAC[word_el_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; LENGTH_MAP; el_length_def;
              heap_length_NIL; STAR_ASSOC; emp_STAR; STAR_emp] THEN
  (* the words of the element are the roots of the values, and its
     header is the one that encode_header gave *)
  W(fun (asl,gl) ->
    let eh = grab asl (fun th ->
      try hd_is "encode_header" (lhs (concl th))
      with Failure _ -> false) in
    let mh = CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
               (REWRITE_RULE[encode_header_def] eh)) in
    let les = mapfilter (fun (_,th) ->
      if (try is_eq (concl th) &&
              hd_is "LENGTH" (lhs (concl th)) &&
              hd_is "LENGTH" (rhs (concl th))
          with Failure _ -> false) then th else fail()) asl in
    REWRITE_TAC(mh :: les)) THEN
  (* the condition of the payload, which the header's length says *)
  W(fun (asl,gl) ->
    let pred = rator gl in
    let fs = facs pred in
    let cell = find (hd_is "cond") fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk a b = mk_comb(mk_comb(st,a),b) in
    SUBGOAL_THEN (mk_eq (pred, mk cell (end_itlist mk rest)))
