    let le = TRANS lmap (REWRITE_RULE[LENGTH_MAP] leq) in
    let wr = grab asl (fun th ->
      try is_eq (concl th) && hd_is "Bignum" (lhs (concl th))
      with Failure _ -> false) in
    let si = grab asl (fun th ->
      try hd_is "small_int" (dest_neg (concl th))
