      with Failure _ -> false) in
    STRIP_ASSUME_TAC
      (REWRITE_RULE[MATCH_MP all2app (TRANS l1 l2)] a2)) THEN

  (* the invariant with the new element in the heap *)
  REWRITE_TAC[memory_rel_def] THEN
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "CONS" (el 1 (snd(strip_comb (concl th)))) &&
           hd_is "dataSem_Block"
             (lhand (el 1 (snd(strip_comb (concl th)))))
       with Failure _ -> false)) in
    let args = snd(strip_comb (concl ai)) in
    let ps = tparts (el 3 args) in
    MAP_EVERY EXISTS_TAC
      [el 1 ps; el 4 args; el 3 ps; el 4 ps; el 5 ps; el 6 ps]) THEN
  REPEAT CONJ_TAC THENL
   [ALL_TAC;
    (* the roots: the pointer of the new reference and the rest *)
    REWRITE_TAC[word_ml_inv_def] THEN
    W(fun (asl,gl) ->
      let ai = grab asl (fun th ->
        hd_is "abs_ml_inv" (concl th) &&
        (try hd_is "CONS" (el 1 (snd(strip_comb (concl th)))) &&
             hd_is "dataSem_Block"
               (lhand (el 1 (snd(strip_comb (concl th)))))
         with Failure _ -> false)) in
      EXISTS_TAC
        (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
    REWRITE_TAC[MAP; FST; SND; ALL2] THEN
    CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    (* the word of the pointer is the one make_ptr builds *)
    W(fun (asl,gl) ->
      let mp = rhs gl in
      let sub = el 1 (snd(strip_comb mp)) in
      let aterm = lhand sub in
      let bwterm = rand aterm in
      let pt = lhand (rand (lhs gl)) in
      let mulp = mk_comb (rator bwterm,
                   mk_comb (rator (rand bwterm), pt)) in
      SUBST1_TAC (addreq asl sub mulp)) THEN
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      REWRITE_TAC(word_addr_clauses ()) THEN
      REWRITE_TAC[make_cons_ptr_def; get_addr_def] THEN
      REWRITE_TAC[MATCH_MP bytes_in_word_mul_eq_shift gd;
                  WORD_SHL_COMPOSE] THEN
      ASM_SIMP_TAC[ARITH_RULE
        `!a b:num. a <= b ==> a + (b - a) = b`] THEN
      AP_TERM_TAC THEN
      GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV)
        [get_lowerbits_or_1] THEN
      WORD_BITWISE_TAC);
    FIRST_ASSUM ACCEPT_TAC;
    W(fun (asl,gl) ->
      let spe = grab asl (fun th ->
        try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
            is_var (rand (concl th))
        with Failure _ -> false) in
      let les = mapfilter (fun (_,th) ->
        if (try is_eq (concl th) &&
                hd_is "LENGTH" (lhs (concl th)) &&
                hd_is "LENGTH" (rhs (concl th))
            with Failure _ -> false) then th else fail()) asl in
      MP_TAC (end_itlist CONJ (spe :: les))) THEN
    REWRITE_TAC[BlockRep_def; el_length_def; LENGTH; ADD1] THEN
    ARITH_TAC] THEN
  (* the store of the new heap: its length is the old one *)
  REWRITE_TAC[heap_in_memory_store_def] THEN
  W(fun (asl,gl) ->
    let hu = grab asl (fun th ->
      try hd_is "heap_store_unused_alt" (lhs (concl th))
      with Failure _ -> false) in
    REWRITE_TAC[MATCH_MP heap_store_unused_alt_IMP_length hu]) THEN
  W(fun (asl,gl) ->
    let dis = CONJUNCTS (distinctness "store_name") in
    REWRITE_TAC([FLOOKUP_UPDATE; FDOM_FUPDATE; IN_INSERT] @
                dis @ map GSYM dis)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the two heaps of the store *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "CurrHeap"))));
       rand (rand (rhs (concl (flk "OtherHeap"))))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (wordeq THEN NO_TAC) THEN
  TRY (numeq THEN NO_TAC) THEN
  (* the heap with the new element, which the store wrote *)
  FIRST_ASSUM (fun h2 ->
    if not (try is_eq (concl h2) && hd_is "APPEND" (lhs (concl h2)) &&
                is_var (rhs (concl h2))
            with Failure _ -> false) then fail() else
    SUBST1_TAC (SYM h2)) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_heap_expand;
              word_heap_def; heap_length_APPEND;
              heap_length_heap_expand; BlockRep_def] THEN
  REWRITE_TAC[word_el_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; LENGTH_MAP; el_length_def;
              heap_length_NIL; STAR_ASSOC; emp_STAR; STAR_emp] THEN
  (* the words of the element are the roots of the values, and its
     header is the one that encode_header gave *)
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      try hd_is "ALL2" (concl th) &&
          not (hd_is "MAP" (el 2 (snd(strip_comb (concl th)))))
      with Failure _ -> false) in
    let a2args = snd(strip_comb (concl a2)) in
    let fterm = rator (lhs (snd(strip_abs (el 0 a2args)))) in
    let mapeq = EQ_MP (ISPECL [el 1 a2args; el 2 a2args; fterm]
                  EVERY2_f_EQ) a2 in
    let eh = grab asl (fun th ->
      try hd_is "encode_header" (lhs (concl th))
      with Failure _ -> false) in
    let mh = CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
               (REWRITE_RULE[encode_header_def] eh)) in
    let les = mapfilter (fun (_,th) ->
      if (try is_eq (concl th) &&
              hd_is "LENGTH" (lhs (concl th)) &&
              hd_is "LENGTH" (rhs (concl th))
          with Failure _ -> false) then th else fail()) asl in
    REWRITE_TAC(shl2 :: mapeq :: mh :: les)) THEN
  (* the condition of the payload, which the header's length says *)
  W(fun (asl,gl) ->
    let pred = rator gl in
    let fs = facs pred in
    let cell = find (hd_is "cond") fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk a b = mk_comb(mk_comb(st,a),b) in
    SUBGOAL_THEN (mk_eq (pred, mk cell (end_itlist mk rest)))
      SUBST1_TAC THENL
     [REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]; ALL_TAC]) THEN
  REWRITE_TAC[cond_STAR] THEN
  CONJ_TAC THENL
   [W(fun (asl,gl) ->
      let eh = grab asl (fun th ->
        try hd_is "encode_header" (lhs (concl th))
        with Failure _ -> false) in
      let ls7 = grab asl (fun th ->
        try hd_is "<" (concl th) &&
            hd_is "+" (lhand (concl th)) &&
            hd_is "data_to_word_config_len_size"
              (lhand (lhand (concl th)))
        with Failure _ -> false) in
      let ls = MATCH_MP (ARITH_RULE
                 `!a b:num. a + 7 < b ==> a + 5 < b`) ls7 in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      STRIP_ASSUME_TAC (MATCH_MP encode_header_IMP
        (CONJ eh (CONJ ls gd)))) THEN
    W(fun (asl,gl) ->
      let eh = grab asl (fun th ->
        try hd_is "encode_header" (lhs (concl th))
        with Failure _ -> false) in
      let mh = CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
                 (REWRITE_RULE[encode_header_def] eh)) in
      REWRITE_TAC[shl2; ARITH_RULE `!t:num. t * 4 = 4 * t`;
                  mh]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* and the words at the address the store wrote them to *)
  W(fun (asl,gl) ->
    let iscell t = hd_is "misc_word_list" t &&
                   hd_is "CONS" (el 1 (snd(strip_comb t))) in
    let sl = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let bnd = REWRITE_RULE[LENGTH; ADD1] (grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false)) in
    let arith = MATCH_MP (ARITH_RULE
                  `!l s:num. l <= s ==> l + (s - l) = s`) bnd in
    let sl2 = REWRITE_RULE[LENGTH; ADD1; word_list_def;
                word_heap_heap_expand; STAR_ASSOC; emp_STAR;
                STAR_emp; addsum] sl in
    REWRITE_TAC[heap_length_CONS; heap_length_NIL; el_length_def;
                ARITH_RULE `!n:num. n + 0 = n`; addsum;
                arith] THEN
    W(fun (asl2,gl2) ->
      let eq = prove (mk_eq (rator gl2, rator (concl sl2)),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      ACCEPT_TAC (REWRITE_RULE[GSYM eq] sl2))))));;

(* mirrors memory_rel_Cons1: a MutBlock is laid out exactly like the Block it
   finalises to, so the allocation is the Cons allocation; what differs is that
   the abstract value handed back is a RefPtr into refs rather than a Block,
   and no timestamp is consumed *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_MutCons = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm (ZIP vals ws ++ vars) /\
      LENGTH vals = LENGTH (ws:('a word_loc) list) /\ ~(vals = [])
        /\
      encode_header c (4 * tag) (LENGTH ws) = SOME hd /\
      LENGTH ws < sp /\ good_dimindex (:'a) /\
      index < LENGTH vals /\ ~(ptr IN domain refs) /\
      (!gs. ~(data_to_word_config_gc_kind c =
        data_to_word_Generational gs)) ==>
      (?free' (curr:'a word) m1.
        FLOOKUP st NextFree = SOME (wordLang_Word free') /\
        FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
        (let w = free' + bytes_in_word * n2w (LENGTH ws + 1) in
          data_to_word_memoryProof_store_list free' (wordLang_Word
            hd :: ws) m dm = SOME m1 /\
          memory_rel c be ts
            (insert ptr (bvlSem_MutBlock tag F (TAKE index vals)
              (EL index vals)
                              (DROP (index + 1) vals)) refs)
            (sp - (LENGTH ws + 1))
            (st |+ (NextFree,wordLang_Word w)) m1 dm
            ((RefPtr F ptr,make_cons_ptr c (free' - curr) tag
              (LENGTH ws)) :: vars)))`),
(* the allocation of an unfinalised mutable block, which is
   memory_rel_Cons1 with mutcons_thm in place of cons_thm_alt: the
   values of the block are the three parts that the index splits
   them into, the reference of the statement holds the block, and
   the pointer of it is make_cons_ptr of the offset as it is there *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let front sp cell =
    let pred = rator (concl sp) in
    let fs = facs pred in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk x y = mk_comb(mk_comb(st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target),
              REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
    REWRITE_RULE[eq] sp in
  (* an ALL2 over two appends of matching lengths *)
  let all2app = prove
   (`!(P:A->B->bool) xs1 ys1 xs2 ys2.
       LENGTH xs1 = LENGTH ys1
       ==> (ALL2 P (xs1 ++ xs2) (ys1 ++ ys2) <=>
            ALL2 P xs1 ys1 /\ ALL2 P xs2 ys2)`,
    GEN_TAC THEN LIST_INDUCT_TAC THENL
     [X_GEN_TAC `ys1:(B)list` THEN
      STRUCT_CASES_TAC (ISPEC `ys1:(B)list` list_CASES) THEN
      REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC;
                  ARITH_RULE `~(0 = SUC n)`];
      X_GEN_TAC `ys1:(B)list` THEN
      STRUCT_CASES_TAC (ISPEC `ys1:(B)list` list_CASES) THEN
      REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC;
                  ARITH_RULE `~(SUC n = 0)`; SUC_INJ] THEN
      REPEAT GEN_TAC THEN DISCH_TAC THEN
      ASM_SIMP_TAC[] THEN CONV_TAC TAUT]) in
  (* two steps of an address in one *)
  let addsum = prove
   (`!(a:'a word) x y.
       a + bytes_in_word * n2w x + bytes_in_word * n2w y =
       a + bytes_in_word * n2w (x + y)`,
    REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE) in
  (* the shift of two that the tag of a block is encoded with *)
  let shl2 = prove
   (`!t. ((n2w t):(N)word) << 2 = n2w (4 * t)`,
    GEN_TAC THEN REWRITE_TAC[word_shl; VAL_WORD] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[WORD_EQ; CONG] THEN CONV_TAC MOD_DOWN_CONV THEN
    REWRITE_TAC[MULT_AC]) in
  let someif = prove
   (`!p (x:A) y. (if p then SOME x else NONE) = SOME y ==> x = y`,
    REPEAT GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"]) in
  (* the numeric facts that the assumptions give *)
  let numfacts asl =
    mapfilter (fun (_,th) ->
      let c = concl th in
      if (try hd_is "<=" c || hd_is "<" c ||
              (is_eq c && hd_is "LENGTH" (lhs c) &&
               hd_is "LENGTH" (rhs c))
          with Failure _ -> false) then th else fail()) asl in
  let addreq asl t1 t2 =
      let fs = numfacts asl in
      let extra = (try
        let lt = grab asl (fun th ->
          try hd_is "<" (concl th) &&
              hd_is "LENGTH" (lhand (concl th))
          with Failure _ -> false) in
        let spe = grab asl (fun th ->
          try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
              is_var (rand (concl th))
          with Failure _ -> false) in
        [MATCH_MP (ARITH_RULE
           `!a b c:num. a < b /\ b <= c ==> a + 1 <= c`)
           (CONJ lt spe)]
        with Failure _ -> []) in
      let cnd = end_itlist CONJ (fs @ extra) in
      MP (prove (mk_imp (concl cnd, mk_eq (t1,t2)),
            DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
              (fun th -> ASSUME_TAC
                 (REWRITE_RULE[LENGTH; ADD1] th))) THEN
            ASM_REWRITE_TAC[BlockRep_def; el_length_def;
                            LENGTH; ADD1] THEN
            REWRITE_TAC[WORD_SUB; WORD_ADD] THEN
            ASM_SIMP_TAC[ARITH_RULE
              `!l s h:num. l <= s ==> l <= h + s`;
              ARITH_RULE
              `!a b c:num. a <= b /\ b <= c ==> a <= c`] THEN
            CONV_TAC WORD_RULE)) cnd in
  let wordeq =
    W(fun (asl,gl) ->
      REWRITE_TAC[addreq asl (rand (rand (lhs gl)))
                    (rand (rand (rhs gl)))]) in
  (* a store that says the same of a key, with the numbers of the
     new element in place of the old ones *)
  let numeq =
    W(fun (asl,gl) ->
      let fl = grab asl (fun th ->
        try hd_is "FLOOKUP" (lhs (concl th)) &&
            rand (lhs (concl th)) = rand (lhs gl) &&
            not (concl th = gl)
        with Failure _ -> false) in
      let isn t = (try hd_is "word" t &&
                       type_of (rand t) = `:num` &&
                       not (is_numeral (rand t))
                   with Failure _ -> false) in
      let ge = find_term isn (rhs gl) in
      let fe = find_term isn (rhs (concl fl)) in
      let fs = numfacts asl in
      let cnd = end_itlist CONJ fs in
      let eq = MP (prove (mk_imp (concl cnd,
                    mk_eq (rand ge, rand fe)),
                  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
                    ASSUME_TAC) THEN
                  REWRITE_TAC[BlockRep_def; el_length_def;
                              LENGTH; ADD1] THEN
                  ASM_ARITH_TAC)) cnd in
      REWRITE_TAC[eq] THEN FIRST_ASSUM ACCEPT_TAC) in
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* what the invariant says of the stack *)
  FIRST_ASSUM (fun mr ->
    if hd_is "memory_rel" (concl mr)
    then MP_TAC (REWRITE_RULE[memory_rel_def; word_ml_inv_def] mr)
    else fail()) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the values and the words that the ZIP of the stack holds *)
  W(fun (asl,gl) ->
    let le = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    RULE_ASSUM_TRY (REWRITE_RULE[MAP_APPEND;
      MATCH_MP MAP_FST_ZIP le; MATCH_MP MAP_SND_ZIP le])) THEN
  (* the block that the cons makes of the values *)
  W(fun (asl,gl) ->
    let ai = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
    let lt = grab asl (fun th ->
      try hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false) in
    let le = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    let spe = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          lhand (concl th) = rand (concl lt)
      with Failure _ -> false) in
    let bnd = MATCH_MP (ARITH_RULE
                `!a b c d:num. a = b /\ b < c /\ c <= d
                               ==> a < d`)
                (CONJ le (CONJ lt spe)) in
    let ix = grab asl (fun th ->
      try hd_is "<" (concl th) && is_var (lhand (concl th)) &&
          hd_is "LENGTH" (rand (concl th))
      with Failure _ -> false) in
    let nd = grab asl (fun th ->
      try hd_is "IN" (dest_neg (concl th))
      with Failure _ -> false) in
    let gk = grab asl (fun th -> is_forall (concl th)) in
    let tg = el 2 (snd(strip_comb (find_term
               (hd_is "make_cons_ptr") gl))) in
    MP_TAC (SPEC tg (MATCH_MP (GEN_ALL mutcons_thm)
      (CONJ ai (CONJ bnd (CONJ ix (CONJ nd gk))))))) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the ends of the heap that the store holds *)
  FIRST_ASSUM (fun hs ->
    if hd_is "heap_in_memory_store" (concl hs)
    then STRIP_ASSUME_TAC
           (REWRITE_RULE[heap_in_memory_store_def] hs)
    else fail()) THEN
  (* the unused space of the heap, where the element goes *)
  FIRST_ASSUM (fun hu ->
    if not (try hd_is "heap_store_unused_alt" (lhs (concl hu))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_unused_alt_def] hu)) THEN
  COND_CASES_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  FIRST_X_ASSUM (fun cnd ->
    if not (is_conj (concl cnd)) then fail() else
    if not (try hd_is "heap_lookup" (lhs (lhand (concl cnd)))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC cnd) THEN
  (* so the heap splits there *)
  FIRST_ASSUM (fun hl ->
    if not (try hd_is "heap_lookup" (lhs (concl hl))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                (hd_is "APPEND" (rhs (concl e)) ||
                 hd_is "heap_length" (rhs (concl e)))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  (* and the store writes the element at the end of the space *)
  FIRST_ASSUM (fun hs ->
    if not (try hd_is "heap_store" (lhs (concl hs))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_lemma; PAIR_EQ] hs)) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the words of the unused space, and its end where the element
     goes *)
  W(fun (asl,gl) ->
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "el_length" (lhand (concl th))
      with Failure _ -> false) in
    let e1 = REWRITE_RULE[BlockRep_def; el_length_def] bnd in
    let eq1 = MATCH_MP (ARITH_RULE
                `!k s:num. k + 1 <= s ==> (s - 1) + 1 = s`) e1 in
    let eq3 = MATCH_MP (ARITH_RULE
                `!k s:num. k + 1 <= s
                           ==> (k + 1) + (s - (k + 1)) = s`) e1 in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th))
      with Failure _ -> false) in
    let sep1 = REWRITE_RULE[word_heap_APPEND; word_heap_def;
                 word_el_def; el_length_def; eq1] sep in
    let addr = el 0 (snd(strip_comb (find (fun t ->
                 hd_is "word_list_exists" t)
                 (facs (rator (concl sep1)))))) in
    let wle = REWRITE_RULE[eq3]
                (ISPECL [lhand (lhs (concl eq3));
                         rand (lhs (concl eq3)); addr]
                   word_list_exists_ADD) in
    let sep2 = REWRITE_RULE[wle; STAR_ASSOC] sep1 in
    ASSUME_TAC sep2) THEN
  (* the words of the element are as many as its roots, and its
     address is the end of the heap less them *)
  W(fun (asl,gl) ->
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          length (filter (hd_is "word_list_exists")
                   (facs (rator (concl th)))) = 2
      with Failure _ -> false) in
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "el_length" (lhand (concl th))
      with Failure _ -> false) in
    let e1 = REWRITE_RULE[BlockRep_def; el_length_def] bnd in
    let rsl = rand (lhand (lhand (concl e1))) in
    let l1 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) =
            mk_icomb (`LENGTH`,rsl)
      with Failure _ -> false) in
    let l2 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) = rhs (concl l1) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    let rw = TRANS l1 l2 in
    let xs = el 1 (snd(strip_comb (find_term
               (hd_is "data_to_word_memoryProof_store_list") gl))) in
    let lenq = prove (mk_eq (mk_binop `(+):num->num->num`
                  (rhs (concl rw)) `1`, mk_icomb (`LENGTH`,xs)),
                REWRITE_TAC[LENGTH] THEN ARITH_TAC) in
    let sep4 = REWRITE_RULE[lenq] (REWRITE_RULE[rw] sep) in
    let bnd2 = REWRITE_RULE[lenq] (REWRITE_RULE[rw] e1) in
    ASSUME_TAC sep4 THEN ASSUME_TAC bnd2 THEN
    REWRITE_TAC[lenq]) THEN
  (* which the store writes there *)
  W(fun (asl,gl) ->
    let iscell t = hd_is "word_list_exists" t &&
                   hd_is "LENGTH" (el 1 (snd(strip_comb t))) in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let cell = find iscell (facs (rator (concl sep))) in
    STRIP_ASSUME_TAC (MATCH_MP store_list_thm (front sep cell))) THEN
  (* the ends of the heap, and the memory that the store wrote *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    let sl = grab asl (fun th ->
      try hd_is "data_to_word_memoryProof_store_list"
            (lhs (concl th))
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "NextFree"))));
       rand (rand (rhs (concl (flk "CurrHeap"))));
       rand (rhs (concl sl))]) THEN
  (* the address of the element is the end of the heap less the
     words it takes *)
  W(fun (asl,gl) ->
    let sl = find_term
               (hd_is "data_to_word_memoryProof_store_list") gl in
    let t1 = el 0 (snd(strip_comb sl)) in
    let iscell t = hd_is "misc_word_list" t &&
                   hd_is "CONS" (el 1 (snd(strip_comb t))) in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let t2 = el 0 (snd(strip_comb
               (find iscell (facs (rator (concl sep)))))) in
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false) in
    let eq = MP (prove (mk_imp (concl bnd, mk_eq (t1,t2)),
                  DISCH_TAC THEN ASM_SIMP_TAC[WORD_SUB] THEN
                  REWRITE_TAC[WORD_ADD] THEN
                  CONV_TAC WORD_RULE)) bnd in
    REWRITE_TAC[eq]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the roots of the element and the roots of the stack *)
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                hd_is "APPEND" (rhs (concl e))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      hd_is "ALL2" (concl th) &&
      hd_is "APPEND" (el 1 (snd(strip_comb (concl th))))) in
    let rsl = lhand (el 1 (snd(strip_comb (concl a2)))) in
    let l1 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) =
            mk_icomb (`LENGTH`,rsl)
      with Failure _ -> false) in
    let l2 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) = rhs (concl l1) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    STRIP_ASSUME_TAC
      (REWRITE_RULE[MATCH_MP all2app (TRANS l1 l2)] a2)) THEN

  (* the invariant with the new element in the heap *)
  REWRITE_TAC[memory_rel_def] THEN
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
       with Failure _ -> false)) in
    let args = snd(strip_comb (concl ai)) in
    let ps = tparts (el 3 args) in
    MAP_EVERY EXISTS_TAC
      [el 1 ps; el 4 args; el 3 ps; el 4 ps; el 5 ps; el 6 ps]) THEN
  REPEAT CONJ_TAC THENL
   [ALL_TAC;
    (* the roots: the pointer of the new reference and the rest *)
    REWRITE_TAC[word_ml_inv_def] THEN
    W(fun (asl,gl) ->
      let ai = grab asl (fun th ->
        hd_is "abs_ml_inv" (concl th) &&
        (try hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
         with Failure _ -> false)) in
      EXISTS_TAC
        (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
    REWRITE_TAC[MAP; FST; SND; ALL2] THEN
    CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    (* the word of the pointer is the one make_ptr builds *)
    W(fun (asl,gl) ->
      let mp = rhs gl in
      let sub = el 1 (snd(strip_comb mp)) in
      let aterm = lhand sub in
      let bwterm = rand aterm in
      let pt = lhand (rand (lhs gl)) in
      let mulp = mk_comb (rator bwterm,
                   mk_comb (rator (rand bwterm), pt)) in
      SUBST1_TAC (addreq asl sub mulp)) THEN
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      REWRITE_TAC(word_addr_clauses ()) THEN
      REWRITE_TAC[make_cons_ptr_def; get_addr_def] THEN
      REWRITE_TAC[MATCH_MP bytes_in_word_mul_eq_shift gd;
                  WORD_SHL_COMPOSE] THEN
      ASM_SIMP_TAC[ARITH_RULE
        `!a b:num. a <= b ==> a + (b - a) = b`] THEN
      AP_TERM_TAC THEN
      GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV)
        [get_lowerbits_or_1] THEN
      WORD_BITWISE_TAC);
    FIRST_ASSUM ACCEPT_TAC;
    W(fun (asl,gl) ->
      let spe = grab asl (fun th ->
        try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
            is_var (rand (concl th))
        with Failure _ -> false) in
      let les = mapfilter (fun (_,th) ->
        if (try is_eq (concl th) &&
                hd_is "LENGTH" (lhs (concl th)) &&
                hd_is "LENGTH" (rhs (concl th))
            with Failure _ -> false) then th else fail()) asl in
      MP_TAC (end_itlist CONJ (spe :: les))) THEN
    REWRITE_TAC[BlockRep_def; el_length_def; LENGTH; ADD1] THEN
    ARITH_TAC] THEN
  (* the store of the new heap: its length is the old one *)
  REWRITE_TAC[heap_in_memory_store_def] THEN
  W(fun (asl,gl) ->
    let hu = grab asl (fun th ->
      try hd_is "heap_store_unused_alt" (lhs (concl th))
      with Failure _ -> false) in
    REWRITE_TAC[MATCH_MP heap_store_unused_alt_IMP_length hu]) THEN
  W(fun (asl,gl) ->
    let dis = CONJUNCTS (distinctness "store_name") in
    REWRITE_TAC([FLOOKUP_UPDATE; FDOM_FUPDATE; IN_INSERT] @
                dis @ map GSYM dis)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the two heaps of the store *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "CurrHeap"))));
       rand (rand (rhs (concl (flk "OtherHeap"))))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (wordeq THEN NO_TAC) THEN
  TRY (numeq THEN NO_TAC) THEN
  (* the heap with the new element, which the store wrote *)
  FIRST_ASSUM (fun h2 ->
    if not (try is_eq (concl h2) && hd_is "APPEND" (lhs (concl h2)) &&
                is_var (rhs (concl h2))
            with Failure _ -> false) then fail() else
    SUBST1_TAC (SYM h2)) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_heap_expand;
              word_heap_def; heap_length_APPEND;
              heap_length_heap_expand; BlockRep_def] THEN
  REWRITE_TAC[word_el_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; LENGTH_MAP; el_length_def;
              heap_length_NIL; STAR_ASSOC; emp_STAR; STAR_emp] THEN
  (* the words of the element are the roots of the values, and its
     header is the one that encode_header gave *)
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      try hd_is "ALL2" (concl th) &&
          not (hd_is "MAP" (el 2 (snd(strip_comb (concl th)))))
      with Failure _ -> false) in
    let a2args = snd(strip_comb (concl a2)) in
    let fterm = rator (lhs (snd(strip_abs (el 0 a2args)))) in
    let mapeq = EQ_MP (ISPECL [el 1 a2args; el 2 a2args; fterm]
                  EVERY2_f_EQ) a2 in
    let eh = grab asl (fun th ->
      try hd_is "encode_header" (lhs (concl th))
      with Failure _ -> false) in
    let mh = CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
               (REWRITE_RULE[encode_header_def] eh)) in
    let les = mapfilter (fun (_,th) ->
      if (try is_eq (concl th) &&
              hd_is "LENGTH" (lhs (concl th)) &&
              hd_is "LENGTH" (rhs (concl th))
          with Failure _ -> false) then th else fail()) asl in
    REWRITE_TAC(shl2 :: mapeq :: mh :: les)) THEN
  (* the condition of the payload, which the header's length says *)
  W(fun (asl,gl) ->
    let pred = rator gl in
    let fs = facs pred in
    let cell = find (hd_is "cond") fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk a b = mk_comb(mk_comb(st,a),b) in
    SUBGOAL_THEN (mk_eq (pred, mk cell (end_itlist mk rest)))
      SUBST1_TAC THENL
     [REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]; ALL_TAC]) THEN
  REWRITE_TAC[cond_STAR] THEN
  CONJ_TAC THENL
   [W(fun (asl,gl) ->
      let eh = grab asl (fun th ->
        try hd_is "encode_header" (lhs (concl th))
        with Failure _ -> false) in
      let ls7 = grab asl (fun th ->
        try hd_is "<" (concl th) &&
            hd_is "+" (lhand (concl th)) &&
            hd_is "data_to_word_config_len_size"
              (lhand (lhand (concl th)))
        with Failure _ -> false) in
      let ls = MATCH_MP (ARITH_RULE
                 `!a b:num. a + 7 < b ==> a + 5 < b`) ls7 in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      STRIP_ASSUME_TAC (MATCH_MP encode_header_IMP
        (CONJ eh (CONJ ls gd)))) THEN
    W(fun (asl,gl) ->
      let eh = grab asl (fun th ->
        try hd_is "encode_header" (lhs (concl th))
        with Failure _ -> false) in
      let mh = CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
                 (REWRITE_RULE[encode_header_def] eh)) in
      REWRITE_TAC[shl2; ARITH_RULE `!t:num. t * 4 = 4 * t`;
                  mh]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* and the words at the address the store wrote them to *)
  W(fun (asl,gl) ->
    let iscell t = hd_is "misc_word_list" t &&
                   hd_is "CONS" (el 1 (snd(strip_comb t))) in
    let sl = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let bnd = REWRITE_RULE[LENGTH; ADD1] (grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false)) in
    let arith = MATCH_MP (ARITH_RULE
                  `!l s:num. l <= s ==> l + (s - l) = s`) bnd in
    let sl2 = REWRITE_RULE[LENGTH; ADD1; word_list_def;
                word_heap_heap_expand; STAR_ASSOC; emp_STAR;
                STAR_emp; addsum] sl in
    REWRITE_TAC[heap_length_CONS; heap_length_NIL; el_length_def;
                ARITH_RULE `!n:num. n + 0 = n`; addsum;
                arith] THEN
    W(fun (asl2,gl2) ->
      let eq = prove (mk_eq (rator gl2, rator (concl sl2)),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      ACCEPT_TAC (REWRITE_RULE[GSYM eq] sl2))))));;

let INJ_FUPDATE = prove
 (`INJ (FAPPLY tf) (FDOM tf) s /\ ~(ts2 IN FDOM tf) /\ ~(x IN FRANGE tf)
  /\ x IN s ==>
   INJ (FAPPLY (tf |+ (ts2,x))) (FDOM (tf |+ (ts2,x))) s`,
  (* the new key is not in the domain and the new value not in the
     range, so the update stays injective.  The negated existential
     of the range is turned into an implication, which is what
     ASM_SIMP_TAC can use of it *)
  (REWRITE_TAC[INJ; FDOM_FUPDATE; IN_INSERT; FMAP_IN_FRANGE;
               NOT_EXISTS_THM; DE_MORGAN_THM;
               TAUT `(~a \/ ~b) <=> (a ==> ~b)`;
               FAPPLY_FUPDATE_THM] THEN
   REPEAT STRIP_TAC THEN REPEAT COND_CASES_TAC THEN
   ASM_SIMP_TAC[] THEN ASM_MESON_TAC[]));;

(* [local] *)
let finalise_cons_none = prove
 (`!v refs ts_opt v' refs' ts'.
     dataSem_finalise_cons v refs ts_opt = SOME (v',refs',ts') /\
     lookup ptr refs = NONE ==>
     lookup ptr refs' = NONE`,
  (* the clauses of the definition decide on the value and on what
     the references hold under the pointer, and the recursion is on
     the references with that key deleted, so the induction is on
     their size (HOL4's finalise_cons_ind, which the port does not
     have) *)
  (* the size of a tree under a delete, which the measure needs:
     HOL4 has it as size_delete of sptreeTheory
     (sptreeScript.sml:1940) and that a tree something is in is not
     empty as lookup_zero of miscTheory (miscScript.sml:3977, which
     ml/misc/misc.ml assumes).  They stand here because this is the
     only proof of the port that needs them; the size of the two
     smart constructors is the size of the plain ones, as their
     lookup is (lookup_mk_BN of ml/lib/sptree.ml) *)
  (let size_mk_BN = prove
     (`!t1 (t2:(A)spt).
         sptree_size (mk_BN t1 t2) = sptree_size (BN t1 t2)`,
      REPEAT GEN_TAC THEN
      GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [mk_BN_def] THEN
      STRUCT_CASES_TAC(ISPEC `t1:(A)spt` (cases_of `:(A)spt`)) THEN
      STRUCT_CASES_TAC(ISPEC `t2:(A)spt` (cases_of `:(A)spt`)) THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[size_def] THEN ARITH_TAC) in
   let size_mk_BS = prove
     (`!t1 (x:A) t2.
         sptree_size (mk_BS t1 x t2) = sptree_size (BS t1 x t2)`,
      REPEAT GEN_TAC THEN
      GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [mk_BS_def] THEN
      STRUCT_CASES_TAC(ISPEC `t1:(A)spt` (cases_of `:(A)spt`)) THEN
      STRUCT_CASES_TAC(ISPEC `t2:(A)spt` (cases_of `:(A)spt`)) THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[size_def] THEN ARITH_TAC) in
   let lookup_zero = prove
     (`!(t:(A)spt) n x.
         sptree_lookup n t = SOME x ==> ~(sptree_size t = 0)`,
      MATCH_MP_TAC spt_INDUCT THEN REPEAT CONJ_TAC THENL
       [REWRITE_TAC[lookup_def; distinctness "option"];
        REPEAT GEN_TAC THEN REWRITE_TAC[lookup_def; size_def] THEN
        DISCH_TAC THEN ARITH_TAC;
        (* the key of a BN goes down one of the two subtrees, and
           the size of that one is not zero by its hypothesis *)
        REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
        REWRITE_TAC[lookup_def; size_def] THEN
        COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
        COND_CASES_TAC THEN DISCH_TAC THEN
        FIRST_X_ASSUM (fun ih -> FIRST_ASSUM (fun lk ->
          MP_TAC (MATCH_MP (GEN_ALL ih) lk))) THEN ARITH_TAC;
        (* and a BS holds one itself *)
        REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
        REWRITE_TAC[lookup_def; size_def] THEN
        DISCH_TAC THEN ARITH_TAC]) in
   let size_delete = prove
     (`!(t:(A)spt) n.
         sptree_size (sptree_delete n t) =
         (if sptree_lookup n t = NONE then sptree_size t
          else sptree_size t - 1)`,
      let FIN =
        W(fun (asl,w) ->
          CASES_ON_TAC (find_term (hd_is "sptree_lookup") w)) THEN
        REWRITE_TAC[distinctness "option"] THEN
        TRY (FIRST_ASSUM (fun th ->
          MP_TAC (MATCH_MP (GEN_ALL lookup_zero) th))) THEN
        ARITH_TAC in
      MATCH_MP_TAC spt_INDUCT THEN REPEAT CONJ_TAC THEN
      REPEAT STRIP_TAC THEN
      REWRITE_TAC[delete_def; lookup_def; size_def] THEN
      COND_CASES_TAC THEN
      ASM_REWRITE_TAC[size_def; distinctness "option"] THEN
      TRY ARITH_TAC THEN
      COND_CASES_TAC THEN
      ASM_REWRITE_TAC[size_mk_BN; size_mk_BS; size_def] THEN
      FIN) in
   let size_delete_LESS = prove
     (`!(t:(A)spt) n x.
         sptree_lookup n t = SOME x
         ==> sptree_size (sptree_delete n t) < sptree_size t`,
      REPEAT GEN_TAC THEN DISCH_TAC THEN
      ASM_SIMP_TAC[size_delete; distinctness "option"] THEN
      FIRST_ASSUM (fun th ->
        MP_TAC (MATCH_MP (GEN_ALL lookup_zero) th)) THEN
      ARITH_TAC) in
   let ref_rws =
     let ds = CONJUNCTS (distinctness "bvlSem_ref") in
     injectivity "option" :: distinctness "option" ::
     injectivity "bvlSem_ref" :: ds @ map GSYM ds in
   (* the equation of the definition, in the one assumption that is
      about the call: a rewrite of every assumption would open the
      call of the induction hypothesis as well *)
   let OPEN_FC =
     FIRST_X_ASSUM (fun fc ->
       let c = concl fc in
       if not (is_eq c) ||
          not (hd_is "dataSem_finalise_cons" (lhs c)) then fail() else
       ASSUME_TAC (ONCE_REWRITE_RULE[dataSem_finalise_cons_def] fc)) in
   (* a pattern that MATCH_CONV leaves as a guard is decided by the
      constructors of the reference, in both orders: the guard has
      the pattern on the left *)
   let TIDY =
     RULE_ASSUM_TRY (REWRITE_RULE ref_rws) THEN
     MATCH_TIDY_TAC THEN
     TRY SAFE_MATCH_REDUCE_ASM_TAC THEN
     MATCH_TIDY_TAC in
   let CLOSE_ARM = TRY (SOLVED (VAR_EQ_TAC THEN ASM_REWRITE_TAC[])) in
   let the_asm p (asl,w) =
     snd (find (fun (_,th) -> p (concl th)) asl) in
   (* the assumption that says what the call gives: a COND by its
      head constant, because the file redefines is_cond *)
   let big_asm = the_asm (fun c -> is_eq c && hd_is "COND" (lhand c)) in
   let SPLIT_LOOKUP =
     W(fun gl ->
       CASES_ON_TAC (find_term (hd_is "sptree_lookup")
                       (concl (big_asm gl)))) in
   let SPLIT_REF =
     W(fun gl ->
       let lk = the_asm (fun c -> is_eq c &&
                  hd_is "sptree_lookup" (lhand c) &&
                  hd_is "SOME" (rand c)) gl in
       CASES_ON_TAC (rand (rand (concl lk)))) in
   (* the result of the call is a triple, and the arm of the match
      only reduces once its components are there *)
   let SPLIT_PAIR_ARG =
     W(fun gl ->
       let fc = the_asm (fun c -> is_eq c &&
                  hd_is "dataSem_finalise_cons" (lhand c) &&
                  hd_is "SOME" (rand c)) gl in
       let rec pv t =
         if is_var t && prod_type (type_of t) then t
         else if hd_is "," t then pv (rand t)
         else failwith "pv" in
       CASES_ON_TAC (pv (rand (rand (concl fc))))) in
   let aux = prove
    (`!n v (refs:((dataSem_v)bvlSem_ref)spt) ts_opt v' refs' ts'.
        sptree_size refs = n /\
        dataSem_finalise_cons v refs ts_opt = SOME (v',refs',ts') /\
        sptree_lookup ptr refs = NONE
        ==> sptree_lookup ptr refs' = NONE`,
     MATCH_MP_TAC num_WF THEN
     X_GEN_TAC `n:num` THEN DISCH_TAC THEN
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     (* a value that is not a pointer leaves the references alone *)
     CASES_ON_TAC `v:dataSem_v` THEN
     OPEN_FC THEN
     SAFE_MATCH_REDUCE_ASM_TAC THEN MATCH_TIDY_TAC THEN CLOSE_ARM THEN
     (* and so does a pointer at anything but an unfinalised
        MutBlock *)
     SPLIT_LOOKUP THEN TIDY THEN CLOSE_ARM THEN
     SPLIT_REF THEN TIDY THEN CLOSE_ARM THEN
     (* the block is not finalised yet, or the result would be
        NONE *)
     W(fun gl ->
       ASM_CASES_TAC (lhand (rator (lhand (concl (big_asm gl)))))) THEN
     ASM_FS_TAC THEN TIDY THEN CLOSE_ARM THEN
     (* and the call on its centre goes through *)
     W(fun gl ->
       CASES_ON_TAC (find_term (hd_is "dataSem_finalise_cons")
                       (concl (big_asm gl)))) THEN
                       TIDY THEN CLOSE_ARM THEN
     REPEAT SPLIT_PAIR_ARG THEN TIDY THEN CLOSE_ARM THEN
     (* the pointer is not the key of the block that is finalised,
        because the references have nothing under it *)
     VAR_EQ_TAC THEN
     ASM_REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THENL
      [POP_ASSUM_LIST (fun l -> MAP_EVERY ASSUME_TAC
         (filter (fun th -> not (is_forall (concl th))) l)) THEN
       ASM_MESON_TAC[distinctness "option"];
       ALL_TAC] THEN
     (* and the references of the call have nothing under it
        either *)
     W(fun gl ->
       let lk = the_asm (fun c -> is_eq c &&
                  hd_is "sptree_lookup" (lhand c) &&
                  hd_is "NONE" (rand c)) gl in
       let fc = the_asm (fun c -> is_eq c &&
                  hd_is "dataSem_finalise_cons" (lhand c)) gl in
       let dl = el 1 (snd (strip_comb (lhand (concl fc)))) in
       SUBGOAL_THEN (mk_eq (mk_comb (rator (lhand (concl lk)), dl),
                            rand (concl lk))) ASSUME_TAC THENL
        [ASM_REWRITE_TAC[lookup_delete]; ALL_TAC]) THEN
     (* so the hypothesis of the induction applies to the call: the
        delete makes the references smaller *)
     FIRST_X_ASSUM (fun ih ->
       if not (is_forall (concl ih)) then fail() else
       W(fun gl ->
         let fc = the_asm (fun c -> is_eq c &&
                    hd_is "dataSem_finalise_cons" (lhand c)) gl in
         let dl = el 1 (snd (strip_comb (lhand (concl fc)))) in
         MP_TAC (SPEC (list_mk_icomb "sptree_size" [dl]) ih))) THEN
     (ANTS_TAC THENL
       [FIRST_ASSUM (fun lk ->
          let c = concl lk in
          if not (is_eq c) || not (hd_is "sptree_lookup" (lhand c)) ||
             not (hd_is "SOME" (rand c)) then fail() else
          MP_TAC (MATCH_MP (GEN_ALL size_delete_LESS) lk)) THEN
        ASM_ARITH_TAC;
        ALL_TAC]) THEN
     DISCH_THEN MATCH_MP_TAC THEN
     ASM_MESON_TAC[]) in
   REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[aux]));;

let v_inv_swap_refs = prove
 (`!c v refs1 x f tf heap refs.
     v_inv c v refs1 (x,f,tf,heap) /\
     (!n. sptree_lookup n refs = lookup n refs1) ==>
     v_inv c v refs (x,f,tf,heap)`,
  (* rule induction on v_inv_ck.  Every premise of a rule reads the
     refs through a lookup only, dest_thunk included, so lookups
     that agree at every pointer let the derivation be replayed
     with the other refs; the ck of the relation is untouched, and
     v_inv is the relation for every ck *)
  (let (vr,vi,vcases) = v_inv_ck in
   let rl = CONJUNCTS vr in
   let _ = vcases in
   let dt = prove
    (`!(v:dataSem_v) refs refs1.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> dataSem_dest_thunk v refs = dataSem_dest_thunk v refs1`,
     REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[dataSem_dest_thunk_def]) in
   (* the assumption that the two lookups agree, which the cases of
      the induction each need in both directions *)
   let is_cnd th =
     let t = concl th in
     is_forall t &&
     (let b = snd(dest_forall t) in
      is_eq b &&
      (try fst(dest_const(fst(strip_comb(lhs b)))) = "sptree_lookup"
       with Failure _ -> false)) in
   let CND ttac =
     FIRST_ASSUM(fun th -> if is_cnd th then ttac th else fail()) in
   let PRE_TAC = REPEAT GEN_TAC THEN REPEAT STRIP_TAC in
   let swap = prove
    (`!ck conf (v:dataSem_v) refs1 y.
        v_inv_ck ck conf v refs1 y
        ==> !refs. (!n. sptree_lookup n refs = sptree_lookup n refs1)
                   ==> v_inv_ck ck conf v refs y`,
     MATCH_MP_TAC vi THEN REPEAT CONJ_TAC THENL
      [PRE_TAC THEN MATCH_MP_TAC(el 0 rl) THEN ASM_REWRITE_TAC[];
       PRE_TAC THEN MATCH_MP_TAC(el 1 rl) THEN ASM_REWRITE_TAC[];
       PRE_TAC THEN MATCH_MP_TAC(el 2 rl) THEN ASM_REWRITE_TAC[];
       PRE_TAC THEN MATCH_ACCEPT_TAC(el 3 rl);
       (* the annotation of the pointer is a lookup of the refs *)
       PRE_TAC THEN CND(fun cnd ->
         REWRITE_TAC[GSYM cnd] THEN MATCH_MP_TAC(el 4 rl) THEN
         REWRITE_TAC[cnd] THEN ASM_REWRITE_TAC[] THEN
         REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM MATCH_ACCEPT_TAC));
       (* the thunk of the rule is named by its lookup, which is
          what MESON takes from the assumptions *)
       PRE_TAC THEN CND(fun cnd ->
         ASM_MESON_TAC[el 5 rl; MATCH_MP dt cnd]);
       PRE_TAC THEN CND(fun cnd ->
         ASM_MESON_TAC[el 6 rl; MATCH_MP dt cnd]);
       PRE_TAC THEN MATCH_MP_TAC(el 7 rl) THEN ASM_REWRITE_TAC[];
       (* and the elements of a Block are carried over one by one *)
       PRE_TAC THEN CND(fun cnd ->
         MATCH_MP_TAC(el 8 rl) THEN ASM_REWRITE_TAC[] THEN
         REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
         DISCH_TAC THEN
         FIRST_X_ASSUM(fun ih ->
           FIRST_ASSUM(fun nz -> MP_TAC(MATCH_MP ih nz))) THEN
         MATCH_MP_TAC MONO_ALL2 THEN BETA_TAC THEN
         REPEAT STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
         ASM_REWRITE_TAC[])]) in
   REWRITE_TAC[v_inv_eq] THEN REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[swap]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_stack_ref_inv_swap_refs = prove
 (cake_as_vars (fun () ->
    `bc_stack_ref_inv c ts vars refs (xs,heap,be) /\
     (!n. sptree_lookup n refs = lookup n refs1) ==>
     bc_stack_ref_inv c ts vars refs1 (xs,heap,be)`),
  (* each part of the invariant reads the refs through a lookup
     only: the domain by domain_lookup, all_ts, all_vs and ref_edge
     by their definitions, and v_inv by v_inv_swap_refs.  So the
     whole of it is rewritten from the one refs to the other and
     the assumption is the goal *)
  (let domq = prove
    (`!refs refs1:(A)spt.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> domain refs = domain refs1`,
     REPEAT STRIP_TAC THEN
     REWRITE_TAC[EXTENSION; domain_lookup] THEN ASM_REWRITE_TAC[]) in
   let atq = prove
    (`!refs refs1 stack.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> all_ts refs stack = all_ts refs1 stack`,
     REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[all_ts_def]) in
   let avq = prove
    (`!refs refs1 stack.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> all_vs refs stack = all_vs refs1 stack`,
     REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[all_vs_def]) in
   let reqq = prove
    (`!refs refs1.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> ref_edge refs = ref_edge refs1`,
     REPEAT STRIP_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
     REPEAT GEN_TAC THEN ASM_REWRITE_TAC[ref_edge_def]) in
   let rchq = prove
    (`!refs refs1.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> !roots t. reachable_refs roots refs t <=>
                      reachable_refs roots refs1 t`,
     REPEAT STRIP_TAC THEN
     REWRITE_TAC[reachable_refs_def] THEN
     FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP reqq th])) in
   let viq = prove
    (`!refs refs1.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> !c (v:dataSem_v) y. v_inv c v refs y <=>
                                v_inv c v refs1 y`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[FORALL_PAIR_THM] THEN REPEAT GEN_TAC THEN
     EQ_TAC THEN ASM_MESON_TAC[v_inv_swap_refs]) in
   let dtq = prove
    (`!refs refs1.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> !v. dataSem_dest_thunk v refs =
                dataSem_dest_thunk v refs1`,
     REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[dataSem_dest_thunk_def]) in
   let brq = prove
    (`!refs refs1.
        (!n. sptree_lookup n refs = sptree_lookup n refs1)
        ==> !c n x. bc_ref_inv c n refs x <=> bc_ref_inv c n refs1 x`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[FORALL_PAIR_THM] THEN REPEAT GEN_TAC THEN
     FIRST_ASSUM(fun th ->
       ASM_REWRITE_TAC[bc_ref_inv_def; MATCH_MP viq th;
                       MATCH_MP dtq th])) in
   DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
   FIRST_ASSUM(fun cnd ->
     DISCH_THEN(MP_TAC o REWRITE_RULE
       [bc_stack_ref_inv_def; MATCH_MP domq cnd;
        MATCH_MP atq cnd; MATCH_MP avq cnd; MATCH_MP rchq cnd;
        MATCH_MP viq cnd; MATCH_MP brq cnd]) THEN
     REWRITE_TAC[bc_stack_ref_inv_def])));;

(* ---- FinaliseCons: the MutBlock at ptr keeps its payload and only flips its
   fin flag, and the value handed back is the Block that payload denotes.
   Neither all_ts, all_vs, ref_edge nor dest_thunk can observe fin, so the
   only real work is relocating the payload from the ref into the new Block. *)

(* [local] *)
let blocks_unique_SUBSET = prove
 (`blocks_unique ts vs2 /\ vs1 SUBSET vs2 ==> blocks_unique ts vs1`,
  (REWRITE_TAC[blocks_unique_def; SUBSET] THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   ASM_SIMP_TAC[]));;

(* [local] *)
let blocks_unique_INSERT = prove
 (`blocks_unique ts vs ==> blocks_unique (SUC ts) (Block ts tag l
  INSERT vs)`,
  (let inst a b c d =
     FIRST_ASSUM(fun h -> MP_TAC(SPECL [`t:num`; a; b; c; d] h)) THEN
     ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] in
   let a1 = `a1:num` and x1 = `xs1:dataSem_v list`
   and a2 = `a2:num` and x2 = `xs2:dataSem_v list` in
   REWRITE_TAC[blocks_unique_def; IN_INSERT;
               injectivity "dataSem_v"] THEN
   DISCH_TAC THEN REPEAT GEN_TAC THEN DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST
    [ASM_REWRITE_TAC[] THEN ARITH_TAC;
     inst a1 x1 a2 x2 THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     ASM_ARITH_TAC;
     inst a2 x2 a2 x2 THEN STRIP_TAC THEN
     SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC;
     inst a1 x1 a1 x1 THEN STRIP_TAC THEN
     SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let all_ts_CONS_SUBSET = prove
 (cake_as_vars (fun () ->
    `all_ts refs stack SUBSET all_ts refs (x :: stack)`),
  (MATCH_MP_TAC all_ts_SUBSET_gen THEN REWRITE_TAC[MEM] THEN
   MESON_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let in_all_vs_stack = prove
 (cake_as_vars (fun () ->
    `MEM v (v_all_vs stack) ==> v IN all_vs refs stack`),
  (DISCH_TAC THEN
   REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   REPEAT DISJ2_TAC THEN ASM_REWRITE_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let in_all_vs_MutBlock = prove
 (cake_as_vars (fun () ->
    `lookup n refs = SOME (bvlSem_MutBlock tg fin l c r) /\
     MEM v (v_all_vs (l ++ [c] ++ r)) ==>
     v IN all_vs refs stack`),
  (REPEAT STRIP_TAC THEN
   REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN ASM_MESON_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let all_vs_CONS_SUBSET = prove
 (cake_as_vars (fun () ->
    `x IN all_vs refs stack ==> all_vs refs (x :: stack) SUBSET all_vs
  refs stack`),
  (* the three parts of all_vs that read the refs are the same, and
     a value of the head is a value of the refs or of the stack
     already, because the head itself is *)
  (let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   DISCH_TAC THEN REWRITE_TAC[SUBSET] THEN GEN_TAC THEN
   GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [all_vs_def] THEN
   REWRITE_TAC[IN_UNION; IN_ELIM_THM] THEN
   GEN_REWRITE_TAC ONCE_DEPTH_CONV [vcons] THEN
   REWRITE_TAC[MEM_APPEND] THEN STRIP_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[vnil; MEM]) THEN
   TRY(FIRST_ASSUM CONTR_TAC) THEN
   TRY(FIRST_ASSUM(fun m -> FIRST_ASSUM(fun xm ->
     MATCH_ACCEPT_TAC(MATCH_MP v_in_all_vs
       (CONJ xm m))))) THEN
   REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   ASM_MESON_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let all_vs_MutBlock_centre = prove
 (cake_as_vars (fun () ->
    `lookup ptr refs = SOME (bvlSem_MutBlock tag fin left cen right) ==>
     all_vs refs (cen :: stack) SUBSET all_vs refs stack`),
  (* the centre of the MutBlock is a value of the refs already, so
     putting it on the stack adds nothing *)
  (DISCH_TAC THEN MATCH_MP_TAC all_vs_CONS_SUBSET THEN
   ASM_MESON_TAC[in_all_vs_MutBlock; MEM_v_all_vs; MEM_APPEND; MEM]));;

(* every value reachable after finalisation was reachable before, except the
   new Block itself *)
(* [local] *)
let all_vs_MutBlock_T = prove
 (`lookup ptr refs = SOME (bvlSem_MutBlock tag F left cen right) ==>
   all_vs (insert ptr (bvlSem_MutBlock tag T left cen right) refs)
          (Block ts2 tag (left ++ [res] ++ right) :: vars) SUBSET
   Block ts2 tag (left ++ [res] ++ right) INSERT
   all_vs refs (res :: RefPtr b ptr :: vars)`,
  (* the three parts of all_vs that read the refs see the cell at
     ptr with the payload it had, and the new stack carries that
     payload and the written value: so a value of the left side is
     a value of the refs, a value of the new stack, or the new
     Block itself *)
  (let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   (* the values of the stack with the new Block in front: the
      Block itself, the three parts of its payload, and the rest *)
   let stack_mem = prove
    (`MEM (w:dataSem_v)
        (v_all_vs (Block t2 g (p ++ [q] ++ s) :: l)) <=>
      w = Block t2 g (p ++ [q] ++ s) \/ MEM w (v_all_vs p) \/
      MEM w (v_all_vs [q]) \/ MEM w (v_all_vs s) \/
      MEM w (v_all_vs l)`,
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [vcons] THEN
     REWRITE_TAC[vsing; MEM_APPEND; MEM; v_all_vs_append] THEN
     CONV_TAC TAUT) in
   (* and the values of a stack of two values in front of a rest *)
   let vmem2 = prove
    (`MEM (w:dataSem_v) (v_all_vs (a :: aa :: l)) <=>
      MEM w (v_all_vs [a]) \/ MEM w (v_all_vs [aa]) \/
      MEM w (v_all_vs l)`,
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [vcons] THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [vcons] THEN
     REWRITE_TAC[MEM_APPEND]) in
   (* the cell that the lookup of a part of all_vs found: at ptr it
      is the one the insert put there and away from ptr the one of
      the refs *)
   let open_lk =
     FIRST_X_ASSUM(fun th ->
       MP_TAC(CONV_RULE(LAND_CONV(REWR_CONV lookup_insert)) th)) THEN
     COND_CASES_TAC in
   let by_mut tac =
     SUBGOAL_THEN `MEM w (v_all_vs (left ++ [cen] ++ right))`
       (fun m -> FIRST_ASSUM(fun lk ->
          MATCH_ACCEPT_TAC(MATCH_MP in_all_vs_MutBlock (CONJ lk m))))
     THEN tac in
   let by_stack =
     SUBGOAL_THEN `MEM w (v_all_vs (res :: RefPtr b ptr :: vars))`
       (fun m -> MATCH_ACCEPT_TAC(MATCH_MP in_all_vs_stack m)) THEN
     ASM_REWRITE_TAC[vmem2] in
   (* a cell that is no MutBlock is not the one at ptr, and is the
      cell it was *)
   let plain =
     open_lk THENL
      [REWRITE_TAC[injectivity "option";
                   distinctness "bvlSem_ref"];
       DISCH_TAC THEN DISJ2_TAC THEN
       REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
       ASM_MESON_TAC[]] in
   DISCH_TAC THEN REWRITE_TAC[SUBSET] THEN
   X_GEN_TAC `w:dataSem_v` THEN
   GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [all_vs_def] THEN
   REWRITE_TAC[IN_UNION; IN_ELIM_THM; IN_INSERT; stack_mem] THEN
   DISCH_THEN STRIP_ASSUME_TAC THENL
    [(* the ValueArrays and the Thunks of the refs are untouched *)
     plain;
     plain;
     (* the cell at ptr keeps its payload, and the other MutBlocks
        are the ones they were *)
     open_lk THENL
      [REWRITE_TAC[injectivity "option";
                   injectivity "bvlSem_ref"] THEN
       STRIP_TAC THEN DISJ2_TAC THEN by_mut (ASM_REWRITE_TAC[]);
       DISCH_TAC THEN DISJ2_TAC THEN
       FIRST_ASSUM(fun m -> FIRST_ASSUM(fun lk ->
         MATCH_ACCEPT_TAC(MATCH_MP in_all_vs_MutBlock
           (CONJ lk m))))];
     (* the new Block itself *)
     ASM_REWRITE_TAC[];
     (* its left part and its right part are the payload of the
        cell at ptr *)
     DISJ2_TAC THEN
     by_mut (ASM_REWRITE_TAC[v_all_vs_append; MEM_APPEND]);
     (* and the written value and the rest of the stack are roots
        of the right side *)
     DISJ2_TAC THEN by_stack;
     DISJ2_TAC THEN
     by_mut (ASM_REWRITE_TAC[v_all_vs_append; MEM_APPEND]);
     DISJ2_TAC THEN by_stack]));;

(* the hole of a MutBlock is reachable from the pointer to it *)
(* [local] *)
let reachable_refs_MutBlock_centre = prove
 (`lookup ptr refs = SOME (bvlSem_MutBlock tag fin left cen right) /\
   reachable_refs (cen :: RefPtr b ptr :: vars) refs n ==>
   reachable_refs (RefPtr b ptr :: vars) refs n`,
  (* the centre of the MutBlock is reachable from the pointer to it
     in one step of ref_edge, because it is inside the payload, so
     what the centre reaches the pointer reaches as well; a root
     other than the centre is a root of the shorter list *)
  (REWRITE_TAC[reachable_refs_def; MEM] THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
     (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC)) THENL
    [FIRST_X_ASSUM(fun th ->
       if is_eq(concl th) && is_var(lhand(concl th))
       then SUBST_ALL_TAC th else fail()) THEN
     MAP_EVERY EXISTS_TAC [`RefPtr b ptr:dataSem_v`; `ptr:num`] THEN
     REWRITE_TAC[get_refs_def; MEM] THEN
     MATCH_MP_TAC(CONJUNCT2 (SPEC_ALL RTC_RULES)) THEN
     EXISTS_TAC `r:num` THEN ASM_REWRITE_TAC[] THEN
     ASM_REWRITE_TAC[ref_edge_def] THEN MATCH_REDUCE_TAC THEN
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP; MEM_APPEND;
                 MEM] THEN
     ASM_MESON_TAC[];
     MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
     ASM_REWRITE_TAC[];
     MAP_EVERY EXISTS_TAC [`x:dataSem_v`; `r:num`] THEN
     ASM_REWRITE_TAC[]]));;

(* [local] *)
let ref_edge_insert_MutBlock = prove
 (`lookup ptr refs = SOME (bvlSem_MutBlock tg fin1 l c r) ==>
   ref_edge (insert ptr (bvlSem_MutBlock tg fin2 l c r) refs) =
     ref_edge refs`,
  (DISCH_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[ref_edge_MutBlock] THEN COND_CASES_TAC THENL
    [SUBGOAL_THEN
       `sptree_lookup x (refs:(dataSem_v bvlSem_ref) spt) =
        SOME (bvlSem_MutBlock tg fin1 l c r)`
       ASSUME_TAC THENL
      [ASM_MESON_TAC[]; ALL_TAC] THEN
     ONCE_REWRITE_TAC[ref_edge_def] THEN ASM_REWRITE_TAC[] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[];
     REWRITE_TAC[]]));;

(* the payload of the finalised cell moves into the new Block, so the refs it
   reaches are the ones the pointer used to reach *)
(* [local] *)
let reachable_refs_MutBlock_T = prove
 (`lookup ptr refs = SOME (bvlSem_MutBlock tag F left cen right) /\
   reachable_refs (Block ts2 tag (left ++ [res] ++ right) :: vars)
                  (insert ptr (bvlSem_MutBlock tag T left cen right)
                    refs) n ==>
   reachable_refs (res :: RefPtr b ptr :: vars) refs n`,
  (* the payload of the cell at ptr is the one it was, so the edges
     are the old ones; a ref that the new Block reaches it reaches
     through its left part, the written value or its right part,
     and the first and the last of those are in the payload of the
     cell, which the pointer reaches in one step *)
  (let blk_refs = prove
    (`MEM ss (get_refs (Block tt aa ys)) <=>
      ?yy. MEM yy ys /\ MEM ss (get_refs yy)`,
     REWRITE_TAC[get_refs_def; MEM_FLAT; MEM_MAP] THEN
     MESON_TAC[]) in
   let by_ptr =
     MAP_EVERY EXISTS_TAC [`RefPtr b ptr:dataSem_v`; `ptr:num`] THEN
     REWRITE_TAC[get_refs_def; MEM] THEN
     MATCH_MP_TAC(CONJUNCT2(SPEC_ALL RTC_RULES)) THEN
     EXISTS_TAC `rr:num` THEN ASM_REWRITE_TAC[] THEN
     ASM_REWRITE_TAC[ref_edge_def] THEN MATCH_REDUCE_TAC THEN
     REWRITE_TAC[blk_refs; MEM_APPEND; MEM] THEN
     EXISTS_TAC `yy:dataSem_v` THEN ASM_REWRITE_TAC[] in
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
   FIRST_ASSUM(fun th ->
     REWRITE_TAC[reachable_refs_def; MEM;
                 MATCH_MP ref_edge_insert_MutBlock th]) THEN
   DISCH_THEN(X_CHOOSE_THEN `xx:dataSem_v`
     (X_CHOOSE_THEN `rr:num` STRIP_ASSUME_TAC)) THEN
   REWRITE_TAC[reachable_refs_def; MEM] THENL
    [FIRST_X_ASSUM SUBST_ALL_TAC THEN
     FIRST_X_ASSUM(fun th ->
       MP_TAC(CONV_RULE(REWR_CONV blk_refs) th)) THEN
     REWRITE_TAC[MEM_APPEND; MEM] THEN
     DISCH_THEN(X_CHOOSE_THEN `yy:dataSem_v`
       STRIP_ASSUME_TAC) THENL
      [by_ptr;
       MAP_EVERY EXISTS_TAC [`yy:dataSem_v`; `rr:num`] THEN
       ASM_REWRITE_TAC[];
       by_ptr];
     MAP_EVERY EXISTS_TAC [`xx:dataSem_v`; `rr:num`] THEN
     ASM_REWRITE_TAC[]]));;

(* [local] *)
let dest_thunk_insert_MutBlock = prove
 (`lookup ptr refs = SOME (bvlSem_MutBlock tg fin1 l c r) ==>
   dest_thunk v (insert ptr (bvlSem_MutBlock tg fin2 l c r) refs) =
     dest_thunk v refs`,
  (* and a MutBlock is no Thunk, so the dest_thunk of the pointer
     is NotThunk before the insert and after it *)
  (let dt_def = dataSem_dest_thunk_def in
   let opt_rws = [distinctness "option"; injectivity "option"] in
   let ref_rws = [distinctness "bvlSem_ref"; injectivity "bvlSem_ref";
                  distinctness "thunk_mode"] in
   DISCH_TAC THEN CASES_ON_NAME "v" THEN
   ONCE_REWRITE_TAC[dt_def] THEN
   SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
   REWRITE_TAC[lookup_insert] THEN
   ASM_CASES_TAC `a1:num = ptr` THEN ASM_REWRITE_TAC[] THEN
   TRY MATCH_REDUCE_TAC THEN
   REWRITE_TAC(opt_rws @ ref_rws) THEN
   REPEAT COND_CASES_TAC THEN REWRITE_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_stack_ref_inv_MutBlock_centre = prove
 (cake_as_vars (fun () ->
    `bc_stack_ref_inv c ts (RefPtr b ptr :: vars) refs (x :: xs,heap,be)
  /\
     lookup ptr refs = SOME (bvlSem_MutBlock tag F left cen right)
       ==>
     (?ptr_n zs.
       x = gc_shared_Pointer ptr_n (ref_ptr_annot c (lookup ptr
         refs)) /\
       heap_lookup ptr_n heap = SOME (BlockRep tag zs) /\
       LENGTH zs = LENGTH left + 1 + LENGTH right /\
       bc_stack_ref_inv c ts (cen :: RefPtr b ptr :: vars) refs
                             (EL (LENGTH left) zs :: x ::
                               xs,heap,be))`),
  (* the invariant of the longer stack holds of the same f and tf:
     the pointer of the reference is what v_inv gives (its Thunk
     cases are out because the reference is a MutBlock), the block
     is what bc_ref_inv gives for the reference, which is reachable
     from the stack, and the centre of the payload is the value at
     the index that the goal reads.  The three parts of the
     invariant that the longer stack changes are all_ts (which only
     grows), all_vs (where the centre is a value of the refs
     already) and the reachability (where the centre reaches no
     more than the pointer does) *)
  (let el_mid = prove
    (`!(l1:(A)list) c l2.
        EL (LENGTH l1) (APPEND l1 (CONS c l2)) = c`,
    LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[LENGTH; APPEND; EL; HD; TL] THEN
    ASM_REWRITE_TAC[]) in
   STRIP_TAC THEN
   FIRST_X_ASSUM (fun inv ->
     if not (hd_is "bc_stack_ref_inv" (concl inv)) then fail() else
     STRIP_ASSUME_TAC
       (REWRITE_RULE[bc_stack_ref_inv_def; ALL2] inv)) THEN
   CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) THEN
   (* the pointer of the reference *)
   FIRST_ASSUM (fun lk ->
     if not (is_eq (concl lk) &&
             hd_is "bvlSem_MutBlock" (rand (rhs (concl lk))))
     then fail() else
     FIRST_ASSUM (fun vi ->
       if not (hd_is "v_inv" (concl vi)) then fail() else
       MP_TAC (REWRITE_RULE[lk; injectivity "option";
                            distinctness "bvlSem_ref"]
                 (ONCE_REWRITE_RULE[v_inv_def] vi)))) THEN
   STRIP_TAC THEN
   (* the reference is reachable from the stack, so the invariant
      holds of its block *)
   FIRST_ASSUM (fun rr ->
     let bod = snd (strip_forall (concl rr)) in
     if not (is_imp bod && hd_is "bc_ref_inv" (rand bod)) then fail()
     else MP_TAC (SPEC `ptr:num` rr)) THEN
   (ANTS_TAC THENL
    [CONJ_TAC THENL
      [REWRITE_TAC[reachable_refs_def] THEN
       EXISTS_TAC `RefPtr b ptr` THEN EXISTS_TAC `ptr:num` THEN
       REWRITE_TAC[MEM; get_refs_def] THEN
       MESON_TAC[RTC_RULES];
       FIRST_ASSUM ACCEPT_TAC];
     ALL_TAC]) THEN
   ASM_SIMP_TAC[bc_ref_inv_def; FLOOKUP_DEF] THEN
   MATCH_REDUCE_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   STRIP_TAC THEN
   (* the block, whose payload holds the centre *)
   FIRST_ASSUM (fun lr ->
     if not (hd_is "ALL2" (concl lr)) then fail() else
     MP_TAC (REWRITE_RULE[LIST_REL_EL_EQN] lr)) THEN
   REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   DISCH_THEN (CONJUNCTS_THEN2 ASSUME_TAC
     (fun el -> MP_TAC (SPEC `LENGTH (left:(dataSem_v)list)` el))) THEN
   (ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
   REWRITE_TAC[APPEND; el_mid] THEN
   CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
   STRIP_TAC THEN
   (* and then the invariant of the longer stack *)
   W(fun (asl,w) ->
     let hl = find (fun (_,th) -> is_eq (concl th) &&
                      hd_is "heap_lookup" (lhs (concl th))) asl in
     let ptr_n = rand (rator (lhs (concl (snd hl)))) in
     let zs = rand (rand (rand (concl (snd hl)))) in
     EXISTS_TAC ptr_n THEN EXISTS_TAC zs) THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   TRY ASM_ARITH_TAC THEN
   (W(fun (asl,w) ->
       let sub p = rand (lhand (concl (snd (find (fun (_,th) ->
         hd_is "SUBSET" (concl th) &&
         hd_is p (rand (concl th))) asl)))) in
       REWRITE_TAC[bc_stack_ref_inv_def] THEN
       EXISTS_TAC (sub "domain") THEN EXISTS_TAC (sub "all_ts")) THEN
     REWRITE_TAC[ALL2] THEN
     CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
     REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
     TRY (ASM_MESON_TAC[SUBSET_TRANS; GEN_ALL all_ts_CONS_SUBSET]) THEN
     TRY (ASM_MESON_TAC[blocks_unique_SUBSET;
                        GEN_ALL all_vs_MutBlock_centre]) THEN
     REPEAT STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
     ASM_MESON_TAC[GEN_ALL reachable_refs_MutBlock_centre])));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_stack_ref_inv_union_del_ins_lemma = prove
 (cake_as_vars (fun () ->
    `bc_stack_ref_inv c ts vars (union refs frame) (xs,heap,be) /\
     lookup ptr refs = SOME x ==>
     bc_stack_ref_inv c ts vars (union (delete ptr refs) (insert
       ptr x frame)) (xs,heap,be)`),
  (* the two refs have the same lookup everywhere: at ptr the delete
     takes the value out of the left half and the insert puts the
     same value in the right one, and away from ptr neither changes
     anything *)
  (STRIP_TAC THEN
   SUBGOAL_THEN
     `!n. sptree_lookup n
            (sptree_union (refs:(dataSem_v bvlSem_ref) spt) frame) =
          sptree_lookup n (sptree_union (sptree_delete ptr refs)
                             (sptree_insert ptr x frame))`
     ASSUME_TAC THENL
    [GEN_TAC THEN
     REWRITE_TAC[lookup_union; OPT_MATCH_COND; lookup_delete;
                 lookup_insert] THEN
     ASM_CASES_TAC `n:num = ptr` THEN
     ASM_REWRITE_TAC[distinctness "option"];
     ALL_TAC] THEN
   FIRST_ASSUM(fun c -> FIRST_ASSUM(fun h ->
     MATCH_ACCEPT_TAC(MATCH_MP
       bc_stack_ref_inv_swap_refs (CONJ h c))))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_stack_ref_inv_MutBlock_F = prove
 (cake_as_vars (fun () ->
    `bc_stack_ref_inv c ts2
       (res :: RefPtr b ptr :: vars) refs
       (EL (LENGTH left) zs :: gc_shared_Pointer ptr_n
          (wordLang_Word (ptr_bits c tag (LENGTH left + (LENGTH
            right + 1)))) :: xs,heap,be) /\
     heap_lookup ptr_n heap = SOME (BlockRep tag zs) /\
     lookup ptr refs = SOME (bvlSem_MutBlock tag F left cen right)
       ==>
     bc_stack_ref_inv c (SUC ts2)
       (Block ts2 tag (left ++ [res] ++ right) :: vars)
       (insert ptr (bvlSem_MutBlock tag T left cen right) refs)
       (gc_shared_Pointer ptr_n
          (wordLang_Word (ptr_bits c tag (LENGTH left + (LENGTH
            right + 1)))) :: xs,heap,be)`),
(* the step keeps the addresses of the references and adds the
   timestamp of the block to the map of the timestamps, with the
   address of the block it finalises for a value: the pointer of
   the stack is that address (v_inv of a RefPtr), and what the old
   invariant says of that key is the cell of the block, the
   invariant of its payload, and that no timestamp points at it --
   which, with the timestamp of the step being a new one, is what
   INJ of the grown map needs.
   Of the nine parts of the invariant the addresses and the byte
   order are the ones of the assumptions, the domain grows with
   the key, the timestamps stay below the one of the step, the
   blocks stay unique (all_vs_MutBlock_T), and the timestamps of
   the refs and the stack carry over (all_ts_SUBSET_ts, whose four
   cases are a value of a reference, the value that was written,
   the pointer of the block and the rest of the stack).  The new
   stack is the block, whose payload has the written value in the
   middle (el_mid_at) and the values the reference had away from it
   (el_mid), and the old stack transported.  And the invariant of a
   key that the new stack reaches is the old one of that key
   (reachable_refs_MutBlock_T) with its arm carried over: a
   ByteArray says nothing about the references, the values of the
   other arms go over one by one (v_inv_SUBMAP with
   v_inv_MutBlock_fin), a Thunk keeps its dest_thunk
   (dest_thunk_insert_MutBlock), and a MutBlock other than this one
   keeps its condition about the timestamps, because INJ of the
   addresses gives it an address of its own *)
  ((let the_lkmb asl =
    grab_asm (fun th ->
      is_eq (concl th) && hd_is "sptree_lookup" (lhs (concl th)) &&
      hd_is "SOME" (rhs (concl th))) asl in
  let the_inn asl =
    grab_asm (fun th ->
      hd_is "IN" (concl th) && hd_is "FDOM" (rand (concl th))) asl in
  let the_hlmb asl =
    grab_asm (fun th ->
      is_eq (concl th) && hd_is "heap_lookup" (lhs (concl th))) asl in
  let hsr_refl = prove
   (`!heap:((A,B)heap_element)list. heap_store_rel heap heap`,
    REWRITE_TAC[heap_store_rel_def]) in
  let el_mid_at = prove
   (`!(l:(A)list) x r. EL (LENGTH l) (l ++ [x] ++ r) = x`,
    REPEAT GEN_TAC THEN REWRITE_TAC[EL_APPEND] THEN
    REWRITE_TAC[LT_REFL; SUB_REFL; LENGTH; LT_0; EL; HD]) in
  let el_mid = prove
   (`!(l:(A)list) x y r n. ~(n = LENGTH l)
       ==> EL n (l ++ [x] ++ r) = EL n (l ++ [y] ++ r)`,
    REPEAT STRIP_TAC THEN REWRITE_TAC[EL_APPEND] THEN
    COND_CASES_TAC THEN REWRITE_TAC[LENGTH] THEN
    SUBGOAL_THEN `~(n - LENGTH (l:(A)list) < SUC 0)` ASSUME_TAC THENL
     [ASM_ARITH_TAC; ASM_REWRITE_TAC[]]) in
  let setupmb =
    STRIP_TAC THEN SPLIT_ASM_TAC THEN
    FIRST_X_ASSUM (fun inv ->
      if not (hd_is "bc_stack_ref_inv" (concl inv)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[bc_stack_ref_inv_def] inv)) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[ALL2]) THEN
    SPLIT_ASM_TAC in
  let the_ptr =
    FIRST_X_ASSUM (fun vi ->
      if not (hd_is "v_inv" (concl vi)) ||
         not (hd_is "dataSem_RefPtr"
           (el 1 (snd (strip_comb (concl vi)))))
      then fail() else
      MP_TAC (REWRITE_RULE[v_inv_def] vi)) THEN
    ASM_REWRITE_TAC[ref_ptr_annot_def; distinctness "bvlSem_ref";
                    injectivity "option"] THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[distinctness "bvlSem_ref"; injectivity "option";
                GSYM (distinctness "bvlSem_ref")] THEN
    STRIP_TAC THEN SPLIT_ASM_TAC in
  let subst_ptr =
    FIRST_X_ASSUM (fun eq ->
      if not (is_eq (concl eq)) ||
         not (hd_is "gc_shared_Pointer" (lhs (concl eq))) then fail()
      else MP_TAC (REWRITE_RULE[injectivity "heap_address"] eq)) THEN
    STRIP_TAC THEN
    FIRST_X_ASSUM (fun eq ->
      if not (is_eq (concl eq)) || not (is_var (lhs (concl eq)))
      then fail() else SUBST_ALL_TAC eq) in
  let the_bri =
    W(fun (asl,gl) ->
      let old = grab_asm (fun th ->
        is_forall (concl th) &&
        can (find_term (hd_is "bc_ref_inv")) (concl th)) asl in
      let inn = grab_asm (fun th ->
        hd_is "IN" (concl th) &&
        hd_is "FDOM" (rand (concl th))) asl in
      let ptr = el 0 (snd (strip_comb (concl inn))) in
      let spo = SPEC ptr old in
      let lst = el 0 (snd (strip_comb (lhand (lhand (concl spo))))) in
      let rp = rand (rator (rand lst)) in
      SUBGOAL_THEN (lhand (lhand (concl spo)))
        (fun rr -> ASSUME_TAC (MP spo (CONJ rr inn))) THENL
       [REWRITE_TAC[reachable_refs_def] THEN
        MAP_EVERY EXISTS_TAC [rp; ptr] THEN
        REWRITE_TAC[MEM; get_refs_def] THEN MATCH_REDUCE_TAC THEN
        REWRITE_TAC[MEM; CONJUNCT1 (SPEC_ALL RTC_RULES)];
        ALL_TAC]) in
  let open_bri =
    W(fun (asl,gl) ->
      let inn = grab_asm (fun th ->
        hd_is "IN" (concl th) &&
        hd_is "FDOM" (rand (concl th))) asl in
      let ptr = el 0 (snd (strip_comb (concl inn))) in
      let fm = rand (rand (concl inn)) in
      SUBGOAL_THEN (mk_eq (list_mk_icomb "FLOOKUP" [fm; ptr],
        list_mk_icomb "SOME" [list_mk_icomb "fmap_apply" [fm; ptr]]))
        ASSUME_TAC THENL
       [ASM_REWRITE_TAC[FLOOKUP_DEF]; ALL_TAC]) THEN
    FIRST_X_ASSUM (fun bri ->
      if not (hd_is "bc_ref_inv" (concl bri)) then fail() else
      MP_TAC (REWRITE_RULE[bc_ref_inv_def] bri)) THEN
    ASM_REWRITE_TAC[] THEN REDUCE_MATCH_HARD THEN
    STRIP_TAC THEN SPLIT_ASM_TAC in
  let mb_facts =
    FIRST_X_ASSUM (fun eq ->
      if not (is_eq (concl eq)) ||
         not (hd_is "BlockRep" (lhs (concl eq))) then fail() else
      SUBST_ALL_TAC (SYM (CONJUNCT1 (REWRITE_RULE[BlockRep_def;
        injectivity "heap_element"] eq)))) THEN
    W(fun (asl,gl) ->
      let su = grab_asm (fun th ->
        hd_is "SUBSET" (concl th) &&
        can (find_term (hd_is "<")) (concl th)) asl in
      let tf = rand (lhand (concl su)) in
      SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
        [`ts2:num`; list_mk_icomb "FDOM" [tf]])) ASSUME_TAC THENL
       [MP_TAC su THEN REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
        DISCH_THEN (fun th -> MP_TAC (SPEC `ts2:num` th)) THEN
        REWRITE_TAC[LT_REFL] THEN DISCH_THEN ACCEPT_TAC;
        ALL_TAC]) THEN
    W(fun (asl,gl) ->
      let img = grab_asm (fun th ->
        is_neg (concl th) && hd_is "IN" (rand (concl th)) &&
        hd_is "IMAGE" (rand (rand (concl th)))) asl in
      let x = lhand (rand (concl img)) in
      let tf = rand (rand (rand (rand (concl img)))) in
      SUBGOAL_THEN (mk_neg (list_mk_icomb "IN"
        [x; list_mk_icomb "FRANGE" [tf]])) ASSUME_TAC THENL
       [MP_TAC img THEN
        REWRITE_TAC[FMAP_IN_FRANGE; IN_IMAGE] THEN MESON_TAC[];
        ALL_TAC]) in
  let mb_wit =
    REWRITE_TAC[bc_stack_ref_inv_def] THEN
    W(fun (asl,gl) ->
      let inn = grab_asm (fun th ->
        hd_is "IN" (concl th) &&
        hd_is "FDOM" (rand (concl th))) asl in
      let ptr = el 0 (snd (strip_comb (concl inn))) in
      let fm = rand (rand (concl inn)) in
      let su = grab_asm (fun th ->
        hd_is "SUBSET" (concl th) &&
        can (find_term (hd_is "<")) (concl th)) asl in
      let tf = rand (lhand (concl su)) in
      EXISTS_TAC fm THEN
      EXISTS_TAC (list_mk_icomb "|+" [tf;
        mk_pair (`ts2:num`, list_mk_icomb "fmap_apply" [fm; ptr])])) in
  let mb_dom =
    W(fun (asl,gl) ->
      MP_TAC (grab_asm (fun th ->
        hd_is "SUBSET" (concl th) &&
        hd_is "domain" (rand (concl th))) asl)) THEN
    REWRITE_TAC[domain_insert] THEN SET_TAC[] in
  let mb_inj =
    W(fun (asl,gl) ->
      let inj = grab_asm (fun th ->
        hd_is "INJ" (concl th) &&
        rand (el 0 (snd (strip_comb (concl th)))) =
          lhand (rand (el 0 (snd (strip_comb gl))))) asl in
      let nts = grab_asm (fun th ->
        is_neg (concl th) && hd_is "IN" (rand (concl th)) &&
        hd_is "FDOM" (rand (rand (concl th)))) asl in
      let nfr = grab_asm (fun th ->
        is_neg (concl th) && hd_is "IN" (rand (concl th)) &&
        hd_is "FRANGE" (rand (rand (concl th)))) asl in
      let x = rand (rand (rand (el 0 (snd (strip_comb gl))))) in
      SUBGOAL_THEN (list_mk_icomb "IN" [x; rand gl])
        (fun isd -> MATCH_ACCEPT_TAC (MATCH_MP INJ_FUPDATE
           (CONJ inj (CONJ nts (CONJ nfr isd))))) THEN
      REWRITE_TAC[IN_ELIM_THM] THEN
      W(fun (asl2,gl2) ->
        let hl = the_hlmb asl2 in
        ACCEPT_TAC (MATCH_MP isSome_lookup
          (CONJ hl (is_data_el (rand (rhs (concl hl)))))))) in
  let mb_below =
    W(fun (asl,gl) ->
      MP_TAC (grab_asm (fun th ->
        hd_is "SUBSET" (concl th) &&
        can (find_term (hd_is "<")) (concl th)) asl)) THEN
    REWRITE_TAC[FDOM_FUPDATE; SUBSET; IN_INSERT; IN_ELIM_THM] THEN
    DISCH_TAC THEN GEN_TAC THEN STRIP_TAC THEN
    TRY (SOLVED (ASM_REWRITE_TAC[] THEN ARITH_TAC)) THEN
    FIRST_X_ASSUM (fun th ->
      if not (is_forall (concl th)) then fail() else
      W(fun (asl2,gl2) -> MP_TAC (SPEC (lhand gl2) th))) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC in
  let mb_unique =
    W(fun (asl,gl) ->
      let bu = grab_asm (fun th ->
        hd_is "blocks_unique" (concl th)) asl in
      let sub = MATCH_MP all_vs_MutBlock_T (the_lkmb asl) in
      let tgt = list_mk_icomb "blocks_unique"
        [el 0 (snd (strip_comb gl)); rand (concl sub)] in
      let bu2 = PART_MATCH I (MATCH_MP blocks_unique_INSERT bu) tgt in
      MATCH_ACCEPT_TAC (MATCH_MP blocks_unique_SUBSET
        (CONJ bu2 sub))) in
  let mb_tr asl th =
    let lk = the_lkmb asl in
    let nts = grab_asm (fun t ->
      is_neg (concl t) && hd_is "IN" (rand (concl t)) &&
      hd_is "FDOM" (rand (rand (concl t)))) asl in
    let inn = the_inn asl in
    let fv = rand (rand (concl inn)) in
    let ptr = el 0 (snd (strip_comb (concl inn))) in
    let x = list_mk_icomb "fmap_apply" [fv; ptr] in
    let fu = SPEC x (MATCH_MP FUPDATE_SUBMAP nts) in
    let ps = tparts (el 3 (snd (strip_comb (concl th)))) in
    MATCH_MP v_inv_SUBMAP
      (CONJ (ISPEC fv SUBMAP_REFL)
        (CONJ fu (CONJ (ISPEC (el 3 ps) hsr_refl)
          (SPEC `T` (MATCH_MP v_inv_MutBlock_fin (CONJ th lk)))))) in
  let the_stackev asl =
    grab_asm (fun th ->
      hd_is "ALL2" (concl th) &&
      (try
        let pred = el 0 (snd (strip_comb (concl th))) in
        let v,b1 = dest_abs pred in
        let _,vtm = dest_abs b1 in
        hd_is "v_inv" vtm && el 1 (snd (strip_comb vtm)) = v
       with Failure _ -> false)) asl in
  let the_payev asl =
    grab_asm (fun th ->
      hd_is "ALL2" (concl th) &&
      (try
        let pred = el 0 (snd (strip_comb (concl th))) in
        let _,b1 = dest_abs pred in
        let x,vtm = dest_abs b1 in
        hd_is "v_inv" vtm && el 1 (snd (strip_comb vtm)) = x
       with Failure _ -> false)) asl in
  let mb_payload =
    REWRITE_TAC[LIST_REL_EL_EQN] THEN
    CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    CONJ_TAC THENL
     [W(fun (asl,gl) ->
        MP_TAC (MATCH_MP LIST_REL_LENGTH (the_payev asl))) THEN
      REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN ARITH_TAC;
      GEN_TAC THEN DISCH_TAC THEN
      W(fun (asl,gl) ->
        let el1 = el 1 (snd (strip_comb gl)) in
        ASM_CASES_TAC (mk_eq (lhand el1,
          list_mk_icomb "LENGTH" [lhand (rand el1)]))) THENL
       [(* the value that was written *)
        ASM_REWRITE_TAC[el_mid_at] THEN
        W(fun (asl,gl) ->
          let vres = grab_asm (fun th ->
            hd_is "v_inv" (concl th) &&
            el 1 (snd (strip_comb (concl th))) =
              el 1 (snd (strip_comb gl))) asl in
          MATCH_ACCEPT_TAC (mb_tr asl vres));
        (* and the ones that were there *)
        W(fun (asl,gl) ->
          let pev = the_payev asl in
          let el1 = el 1 (snd (strip_comb gl)) in
          let n = lhand el1 in
          let lst = rand el1 in
          let res = lhand (lhand (rand lst)) in
          let right = rand (rand lst) in
          let ne = grab_asm (fun th ->
            is_neg (concl th) && is_eq (rand (concl th)) &&
            lhand (rand (concl th)) = n) asl in
          let eqs = CONJUNCTS (CONV_RULE (TOP_DEPTH_CONV BETA_CONV)
            (REWRITE_RULE[LIST_REL_EL_EQN] pev)) in
          let sp = SPEC n (el 1 eqs) in
          let cen = lhand (lhand (rand (rand (el 1 (snd (strip_comb
                      (rand (concl sp)))))))) in
          let swap = SPECL [cen; res; right] (MATCH_MP el_mid ne) in
          SUBGOAL_THEN (lhand (concl sp))
            (fun lt -> MATCH_ACCEPT_TAC
               (mb_tr asl (SUBS [swap] (MP sp lt)))) THEN
          MP_TAC (MATCH_MP LIST_REL_LENGTH pev) THEN
          W(fun (asl2,gl2) ->
            MP_TAC (grab_asm (fun th ->
              hd_is "<" (concl th)) asl2)) THEN
          REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN ARITH_TAC)]] in
  let mb_stack =
    REWRITE_TAC[ALL2] THEN
    CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    CONJ_TAC THENL
     [(* the block of the step, which is no empty one *)
      REWRITE_TAC[v_inv_def] THEN COND_CASES_TAC THENL
       [FIRST_X_ASSUM MP_TAC THEN
        REWRITE_TAC[APPEND_EQ_NIL; APPEND; NOT_CONS_NIL];
        ALL_TAC] THEN
      W(fun (asl,gl) ->
        let hl = the_hlmb asl in
        MAP_EVERY EXISTS_TAC
          [lhand (lhs (concl hl)); rand (rand (rhs (concl hl)))]) THEN
      REWRITE_TAC[FLOOKUP_UPDATE] THEN
      REPEAT CONJ_TAC THEN
      TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
      (* the words of the pointer count the payload *)
      TRY (SOLVED
            (W(fun (asl,gl) ->
               MP_TAC (MATCH_MP LIST_REL_LENGTH (the_payev asl))) THEN
             REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
             DISCH_THEN (fun th -> REWRITE_TAC[th]) THEN
             REWRITE_TAC[injectivity "heap_address";
                         injectivity "word_loc"] THEN
             AP_TERM_TAC THEN ARITH_TAC)) THEN
      mb_payload;
      (* and the values of the stack *)
      W(fun (asl,gl) ->
        let ev = the_stackev asl in
        let pred = el 0 (snd (strip_comb (concl ev))) in
        let v,b1 = dest_abs pred in
        let x,vtm = dest_abs b1 in
        MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc_stack
          (CONJ (GENL [v; x] (DISCH vtm (mb_tr asl (ASSUME vtm))))
            ev)))] in
  let the_fr asl =
    grab_asm (fun th -> hd_is "find_ref" (concl th)) asl in
  let the_lk fr asl =
    grab_asm (fun th ->
      is_eq (concl th) &&
      hd_is "sptree_lookup" (lhs (concl th)) &&
      hd_is "SOME" (rhs (concl th)) &&
      rand (rhs (concl th)) = lhand (concl fr)) asl in
  let the_mb asl =
    grab_asm (fun th ->
      is_eq (concl th) &&
      hd_is "sptree_lookup" (lhs (concl th)) &&
      hd_is "SOME" (rhs (concl th)) &&
      hd_is "bvlSem_MutBlock" (rand (rhs (concl th)))) asl in
  let the_vt asl =
    grab_asm (fun th ->
      hd_is "MEM" (concl th) &&
      hd_is "v_all_ts" (rand (concl th))) asl in
  let allts_ref =
    W(fun (asl,_) ->
      let fr = the_fr asl in
      let lk = the_lk fr asl in
      let n = lhand (lhs (concl lk)) in
      EXISTS_TAC (rand (concl fr)) THEN
      (CONJ_TAC THENL
        [DISJ1_TAC THEN EXISTS_TAC n THEN
         ASM_CASES_TAC (mk_eq (n, `ptr:num`)) THENL
          [(* the block of the new refs, taken from the goal: a block
              written out here would have a type variable of its own *)
           W(fun (_,gl) ->
             EXISTS_TAC (lhand (rand (lhs (lhand
               (snd (dest_exists gl))))))) THEN
           ASM_REWRITE_TAC[lookup_insert; find_ref_def] THEN
           MATCH_REDUCE_TAC THEN
           (* the value of the reference is the payload of the block
              of the old refs, which is the payload of the new one *)
           W(fun (asl2,_) ->
             let mb = the_mb asl2 in
             let np = grab_asm (fun th ->
               concl th = mk_eq (n, `ptr:num`)) asl2 in
             let req = REWRITE_RULE[injectivity "option"]
                         (TRANS (SYM (SUBS [np] lk)) mb) in
             MP_TAC (SUBS [req] fr)) THEN
           REWRITE_TAC[find_ref_def] THEN MATCH_REDUCE_TAC THEN
           DISCH_THEN ACCEPT_TAC;
           EXISTS_TAC (rand (rhs (concl lk))) THEN
           ASM_REWRITE_TAC[lookup_insert]];
         FIRST_ASSUM ACCEPT_TAC])) in
  let allts_res =
    W(fun (_,gl) ->
      EXISTS_TAC
        (rand (lhand (rand (lhand (snd (dest_exists gl))))))) THEN
    CONJ_TAC THENL
     [DISJ2_TAC THEN REWRITE_TAC[MEM];
      GEN_REWRITE_TAC RAND_CONV [v_all_ts_def] THEN
      MATCH_REDUCE_TAC THEN
      REWRITE_TAC[MEM; MEM_FLAT; MEM_MAP] THEN
      DISJ2_TAC THEN
      W(fun (asl,_) ->
        let vt = the_vt asl in
        EXISTS_TAC (rand (concl vt)) THEN
        (CONJ_TAC THENL
          [EXISTS_TAC (rand (rand (concl vt))) THEN
           ASM_REWRITE_TAC[MEM_APPEND; MEM];
           FIRST_ASSUM ACCEPT_TAC]))] in
  let allts_ptr =
    FIRST_X_ASSUM (fun eq ->
      if not (is_eq (concl eq)) then fail() else
      SUBST_ALL_TAC eq) THEN
    FIRST_X_ASSUM (fun vt ->
      if not (hd_is "MEM" (concl vt)) ||
         not (hd_is "v_all_ts" (rand (concl vt))) then fail()
      else MP_TAC vt) THEN
    GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [v_all_ts_def] THEN
    MATCH_REDUCE_TAC THEN REWRITE_TAC[MEM] in
  let allts_var =
    W(fun (asl,_) ->
      let vt = the_vt asl in
      EXISTS_TAC (rand (rand (concl vt)))) THEN
    CONJ_TAC THENL
     [DISJ2_TAC THEN ASM_REWRITE_TAC[MEM];
      FIRST_ASSUM ACCEPT_TAC] in
  let allts_cases =
    MATCH_MP_TAC all_ts_SUBSET_ts THEN
    REPEAT GEN_TAC THEN REWRITE_TAC[MEM] THEN STRIP_TAC THEN
    SPLIT_ASM_TAC THEN
    FIRST [SOLVED allts_ref; SOLVED allts_res; SOLVED allts_ptr;
           SOLVED allts_var] in
  let mb_allts =
    REWRITE_TAC[SUBSET; FDOM_FUPDATE; IN_INSERT] THEN
    GEN_TAC THEN
    DISCH_THEN (DISJ_CASES_THEN2 SUBST1_TAC ASSUME_TAC) THENL
     [(* the timestamp of this block is its own *)
      REWRITE_TAC[all_ts_def] THEN
      CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
      REWRITE_TAC[IN_ELIM_THM] THEN
      W(fun (_,gl) ->
        EXISTS_TAC (lhand (rand (rand (lhand
          (snd (dest_exists gl))))))) THEN
      CONJ_TAC THENL
       [DISJ2_TAC THEN REWRITE_TAC[MEM];
        GEN_REWRITE_TAC RAND_CONV [v_all_ts_def] THEN
        MATCH_REDUCE_TAC THEN REWRITE_TAC[MEM]];
      (* and the others were timestamps of the old refs and stack *)
      W(fun (asl,gl) ->
        let su = grab_asm (fun th ->
          hd_is "SUBSET" (concl th) &&
          hd_is "all_ts" (rand (concl th))) asl in
        let inx = grab_asm (fun th ->
          hd_is "IN" (concl th) &&
          hd_is "FDOM" (rand (concl th)) &&
          lhand (concl th) = lhand gl) asl in
        let old = MP (SPEC (lhand gl) (REWRITE_RULE[SUBSET] su)) inx in
        SUBGOAL_THEN (list_mk_icomb "SUBSET"
          [rand (concl su); rand gl])
          (fun sub -> ACCEPT_TAC (MP
             (SPEC (lhand gl) (REWRITE_RULE[SUBSET] sub)) old))) THEN
      allts_cases] in
  let the_big asl =
    grab_asm (fun th ->
      is_forall (concl th) &&
      (let b = snd (strip_forall (concl th)) in
       is_imp b && hd_is "bc_ref_inv" (rand b))) asl in
  let the_nin n asl =
    grab_asm (fun th ->
      hd_is "IN" (concl th) &&
      hd_is "FDOM" (rand (concl th)) &&
      lhand (concl th) = n) asl in
  let the_mbF asl =
    grab_asm (fun th ->
      is_eq (concl th) && hd_is "sptree_lookup" (lhs (concl th)) &&
      hd_is "SOME" (rhs (concl th)) &&
      hd_is "bvlSem_MutBlock" (rand (rhs (concl th))) &&
      el 1 (snd (strip_comb (rand (rhs (concl th))))) = `F`) asl in
  let the_innp lk asl =
    grab_asm (fun th ->
      hd_is "IN" (concl th) && hd_is "FDOM" (rand (concl th)) &&
      lhand (concl th) = lhand (lhs (concl lk))) asl in
  let mb_tr9 asl th =
    let lk = the_mbF asl in
    let nts = grab_asm (fun t ->
      is_neg (concl t) && hd_is "IN" (rand (concl t)) &&
      hd_is "FDOM" (rand (rand (concl t)))) asl in
    let inn = the_innp lk asl in
    let fv = rand (rand (concl inn)) in
    let p = lhand (concl inn) in
    let x = list_mk_icomb "fmap_apply" [fv; p] in
    let fu = SPEC x (MATCH_MP FUPDATE_SUBMAP nts) in
    let ps = tparts (el 3 (snd (strip_comb (concl th)))) in
    MATCH_MP v_inv_SUBMAP
      (CONJ (ISPEC fv SUBMAP_REFL)
        (CONJ fu (CONJ (ISPEC (el 3 ps) hsr_refl)
          (SPEC `T` (MATCH_MP v_inv_MutBlock_fin (CONJ th lk)))))) in
  let image_fupd = prove
   (`!(tf:(A,B)fmap) k v x.
       ~(x = v) /\ ~(x IN IMAGE (FAPPLY tf) (FDOM tf))
       ==> ~(x IN IMAGE (FAPPLY (tf |+ (k,v))) (FDOM (tf |+ (k,v))))`,
    REWRITE_TAC[IN_IMAGE; FDOM_FUPDATE; IN_INSERT; FAPPLY_FUPDATE_THM;
                NOT_EXISTS_THM; DE_MORGAN_THM] THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `y:A` THEN
    ASM_CASES_TAC `(y:A) = k` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]) in
  let r9_same = DISCH_THEN ACCEPT_TAC in
  let r9_thunk =
    STRIP_TAC THEN
    W(fun (asl,_) ->
      let hl = grab_asm (fun th ->
        is_eq (concl th) && hd_is "heap_lookup" (lhs (concl th))) asl in
      EXISTS_TAC (rand (rand (rhs (concl hl))))) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      W(fun (asl,_) ->
        REWRITE_TAC[MATCH_MP dest_thunk_insert_MutBlock
                      (the_mbF asl)]) THEN
      FIRST_ASSUM ACCEPT_TAC;
      W(fun (asl,_) ->
        let vi = grab_asm (fun th -> hd_is "v_inv" (concl th)) asl in
        MATCH_ACCEPT_TAC (mb_tr9 asl vi))] in
  let r9_blk =
    W(fun (asl,gl) ->
      let l = el 2 (snd (strip_comb (rand (snd (dest_exists gl))))) in
      let ev = grab_asm (fun th ->
        hd_is "ALL2" (concl th) &&
        el 2 (snd (strip_comb (concl th))) = l) asl in
      let pred = el 0 (snd (strip_comb (concl ev))) in
      let z,b1 = dest_abs pred in
      let y,vtm = dest_abs b1 in
      EXISTS_TAC (el 1 (snd (strip_comb (concl ev)))) THEN
      (CONJ_TAC THENL
        [FIRST_ASSUM ACCEPT_TAC;
         MATCH_ACCEPT_TAC (MATCH_MP EVERY2_v_inv_alloc
           (CONJ (GENL [y; z] (DISCH vtm (mb_tr9 asl (ASSUME vtm))))
             ev))])) in
  let r9_va = STRIP_TAC THEN r9_blk in
  let r9_mb =
    STRIP_TAC THEN
    CONJ_TAC THENL
     [W(fun (asl,_) ->
        let lk = the_mbF asl in
        let p = lhand (lhs (concl lk)) in
        let inn = the_innp lk asl in
        let fv = rand (rand (concl inn)) in
        let nin = grab_asm (fun th ->
          hd_is "IN" (concl th) && rand (concl th) = rand (concl inn) &&
          not (lhand (concl th) = p)) asl in
        let n = lhand (concl nin) in
        let np = grab_asm (fun th ->
          is_neg (concl th) && is_eq (rand (concl th)) &&
          lhand (rand (concl th)) = n &&
          rand (rand (concl th)) = p) asl in
        let inj = REWRITE_RULE[INJ]
          (grab_asm (fun th -> hd_is "INJ" (concl th) &&
             rand (el 0 (snd (strip_comb (concl th)))) = fv) asl) in
        let imp0 = SPECL [n; p] (CONJUNCT2 inj) in
        let eqt = rand (rand (lhand (concl imp0))) in
        let imp = DISCH eqt
                    (MP imp0 (CONJ nin (CONJ inn (ASSUME eqt)))) in
        let ne = MP (MATCH_MP
                       (TAUT `(a ==> b) ==> ~b ==> ~a`) imp) np in
        let old = grab_asm (fun th ->
          is_imp (concl th) && is_neg (rand (concl th)) &&
          hd_is "IN" (rand (rand (concl th))) &&
          hd_is "IMAGE" (rand (rand (rand (concl th))))) asl in
        DISCH_THEN (fun nf -> MATCH_ACCEPT_TAC
          (MATCH_MP image_fupd (CONJ ne (MP old nf)))));
      r9_blk] in
  let mb_ref9 =
    REPEAT STRIP_TAC THEN
    (* the key is reachable in the old refs and stack, so the old
       invariant has it *)
    W(fun (asl,gl) ->
      let n = el 1 (snd (strip_comb gl)) in
      let rr = grab_asm (fun th ->
        hd_is "reachable_refs" (concl th)) asl in
      let lkp = the_lkmb asl in
      let nin = the_nin n asl in
      let old = MP (SPEC n (the_big asl))
                   (CONJ (MATCH_MP reachable_refs_MutBlock_T
                            (CONJ lkp rr)) nin) in
      let fl = REWRITE_RULE[nin]
                 (ISPECL [rand (rand (concl nin)); n] FLOOKUP_DEF) in
      MP_TAC (REWRITE_RULE[fl] (ONCE_REWRITE_RULE[bc_ref_inv_def] old))
        THEN
      ONCE_REWRITE_TAC[bc_ref_inv_def] THEN
      REWRITE_TAC[fl] THEN
      ASM_CASES_TAC (mk_eq (n, `ptr:num`))) THENL
     [(* the block that was finalised: the same payload, and nothing
         to prove about the timestamps of a finalised one *)
      FIRST_ASSUM (fun np -> REWRITE_TAC[np]) THEN
      ASM_REWRITE_TAC[lookup_insert] THEN MATCH_REDUCE_TAC THEN
      STRIP_TAC THEN r9_blk;
      (* and a reference that the insert did not touch: a ByteArray
         says nothing about the refs, and the values of the others go
         over one by one *)
      ASM_REWRITE_TAC[lookup_insert] THEN
      W(fun (asl,_) ->
        let lkp = the_mbF asl in
        let p = lhand (lhs (concl lkp)) in
        let np = grab_asm (fun th ->
          is_neg (concl th) && is_eq (rand (concl th)) &&
          rand (rand (concl th)) = p) asl in
        let n = lhand (rand (concl np)) in
        NAMED_CASES_TAC (subst [n, p] (lhs (concl lkp)))
          [[]; ["rv"]]) THEN
      TRY (CASES_ON_NAME "rv") THEN
      TRY MATCH_REDUCE_TAC THEN
      FIRST [SOLVED r9_same; SOLVED r9_va; SOLVED r9_thunk;
             SOLVED r9_mb]] in
  setupmb THEN the_ptr THEN subst_ptr THEN the_bri THEN
  open_bri THEN mb_facts THEN
  (mb_wit THEN REPEAT CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; mb_dom; mb_inj; mb_allts; mb_below;
     FIRST_ASSUM ACCEPT_TAC; mb_unique; mb_stack; mb_ref9]))));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bc_stack_ref_inv_FinaliseCons_lemma = prove
 (cake_as_vars (fun () ->
    `!v refs ts_opt v' refs' ts' ts vars' w frame x xs.
       dataSem_finalise_cons v refs ts_opt = SOME (v',refs',ts') /\
         ts_opt = SOME ts /\
       bc_stack_ref_inv c ts (v :: vars') (union refs frame) (x ::
         xs,heap,be) ==>
       IS_SOME ts' /\
       bc_stack_ref_inv c (THE ts') (v' :: vars') (union refs'
         frame) (x :: xs,heap,be)`),
(* the induction of the source is the one of the definition
   (finalise_cons_ind), which the port does not have, so the proof
   goes by the size of the references: the recursion is on them
   with the pointer of the block deleted, which makes them smaller
   (the lemmas of finalise_cons_none above, for the same reason).
     A value that is no pointer, and a pointer at anything but an
   unfinalised MutBlock, leaves the references and the timestamp
   as they are, and there the goal is the assumption.  For the
   block: the stack holds its pointer, so the invariant gives the
   element of the heap and the invariant of its centre
   (bc_stack_ref_inv_MutBlock_centre), and moving the reference
   from the references to the frame keeps that
   (bc_stack_ref_inv_union_del_ins_lemma) -- which is what the
   call is about, so the hypothesis of the induction applies to it
   and gives the invariant of the finalised centre with the
   timestamp of the call.  That timestamp is one (IS_SOME), and
   the one of the step is its successor; the invariant of the
   block then comes from bc_stack_ref_inv_MutBlock_F, and the
   references of the goal have the same lookup at every key as the
   ones of that step (bc_stack_ref_inv_swap_refs): at the pointer
   both give the finalised block, and away from it the call's
   references answer first in both *)
  ((let grab_asm p asl =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
  (* the size of a tree under a delete, which the measure of the
     induction needs: the recursion of finalise_cons is on the
     references with the pointer of the block deleted.  HOL4 has
     the induction of the definition (finalise_cons_ind), which
     the port does not have, and the proof of finalise_cons_none
     above has the same lemmas for the same reason *)
  let size_mk_BN = prove
   (`!t1 (t2:(A)spt).
       sptree_size (mk_BN t1 t2) = sptree_size (BN t1 t2)`,
    REPEAT GEN_TAC THEN
    GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [mk_BN_def] THEN
    STRUCT_CASES_TAC(ISPEC `t1:(A)spt` (cases_of `:(A)spt`)) THEN
    STRUCT_CASES_TAC(ISPEC `t2:(A)spt` (cases_of `:(A)spt`)) THEN
    MATCH_REDUCE_TAC THEN REWRITE_TAC[size_def] THEN ARITH_TAC) in
  let size_mk_BS = prove
   (`!t1 (x:A) t2.
       sptree_size (mk_BS t1 x t2) = sptree_size (BS t1 x t2)`,
    REPEAT GEN_TAC THEN
    GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [mk_BS_def] THEN
    STRUCT_CASES_TAC(ISPEC `t1:(A)spt` (cases_of `:(A)spt`)) THEN
    STRUCT_CASES_TAC(ISPEC `t2:(A)spt` (cases_of `:(A)spt`)) THEN
    MATCH_REDUCE_TAC THEN REWRITE_TAC[size_def] THEN ARITH_TAC) in
  let lookup_zero = prove
   (`!(t:(A)spt) n x.
       sptree_lookup n t = SOME x ==> ~(sptree_size t = 0)`,
    MATCH_MP_TAC spt_INDUCT THEN REPEAT CONJ_TAC THENL
     [REWRITE_TAC[lookup_def; distinctness "option"];
      REPEAT GEN_TAC THEN REWRITE_TAC[lookup_def; size_def] THEN
      DISCH_TAC THEN ARITH_TAC;
      REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
      REWRITE_TAC[lookup_def; size_def] THEN
      COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
      COND_CASES_TAC THEN DISCH_TAC THEN
      FIRST_X_ASSUM (fun ih -> FIRST_ASSUM (fun lk ->
        MP_TAC (MATCH_MP (GEN_ALL ih) lk))) THEN ARITH_TAC;
      REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
      REWRITE_TAC[lookup_def; size_def] THEN
      DISCH_TAC THEN ARITH_TAC]) in
  let size_delete = prove
   (`!(t:(A)spt) n.
       sptree_size (sptree_delete n t) =
       (if sptree_lookup n t = NONE then sptree_size t
        else sptree_size t - 1)`,
    let FIN =
      W(fun (asl,w) ->
        CASES_ON_TAC (find_term (hd_is "sptree_lookup") w)) THEN
      REWRITE_TAC[distinctness "option"] THEN
      TRY (FIRST_ASSUM (fun th ->
        MP_TAC (MATCH_MP (GEN_ALL lookup_zero) th))) THEN
      ARITH_TAC in
    MATCH_MP_TAC spt_INDUCT THEN REPEAT CONJ_TAC THEN
    REPEAT STRIP_TAC THEN
    REWRITE_TAC[delete_def; lookup_def; size_def] THEN
    COND_CASES_TAC THEN
    ASM_REWRITE_TAC[size_def; distinctness "option"] THEN
    TRY ARITH_TAC THEN
    COND_CASES_TAC THEN
    ASM_REWRITE_TAC[size_mk_BN; size_mk_BS; size_def] THEN
    FIN) in
  let size_delete_LESS = prove
   (`!(t:(A)spt) n x.
       sptree_lookup n t = SOME x
       ==> sptree_size (sptree_delete n t) < sptree_size t`,
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    ASM_SIMP_TAC[size_delete; distinctness "option"] THEN
    FIRST_ASSUM (fun th ->
      MP_TAC (MATCH_MP (GEN_ALL lookup_zero) th)) THEN
    ARITH_TAC) in
  (* a lookup of a union that the left half answers, and one that
     it leaves to the right half *)
  let lu_left = prove
   (`!m1 m2 k (x:A). sptree_lookup k m1 = SOME x
       ==> sptree_lookup k (sptree_union m1 m2) = SOME x`,
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    ASM_REWRITE_TAC[lookup_union] THEN MATCH_REDUCE_TAC) in
  let lu_none = prove
   (`!m1 m2 k. sptree_lookup k m1 = NONE
       ==> sptree_lookup k (sptree_union m1 (m2:(A)spt)) =
           sptree_lookup k m2`,
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    ASM_REWRITE_TAC[lookup_union] THEN MATCH_REDUCE_TAC) in
  let ref_rws =
    let ds = CONJUNCTS (distinctness "bvlSem_ref") in
    injectivity "option" :: distinctness "option" ::
    injectivity "bvlSem_ref" :: ds @ map GSYM ds in
  (* the equation of the definition, in the one assumption that is
     about the call: a rewrite of every assumption would open the
     call of the induction hypothesis as well *)
  let OPEN_FC =
    FIRST_X_ASSUM (fun fc ->
      let c = concl fc in
      if not (is_eq c) ||
         not (hd_is "dataSem_finalise_cons" (lhs c)) then fail()
      else
      ASSUME_TAC (ONCE_REWRITE_RULE[dataSem_finalise_cons_def] fc))
    in
  let TIDY =
    RULE_ASSUM_TRY (REWRITE_RULE ref_rws) THEN
    MATCH_TIDY_TAC THEN
    TRY SAFE_MATCH_REDUCE_ASM_TAC THEN
    MATCH_TIDY_TAC in
  (* the arms where the references are untouched: there the goal
     is the assumption, with the timestamp of the call *)
  let CLOSE2 =
    TRY (SOLVED (VAR_EQ_TAC THEN
      ASM_REWRITE_TAC[IS_SOME; THE; distinctness "option";
                      injectivity "option"])) in
  let the_asm p (asl,w) =
    snd (find (fun (_,th) -> p (concl th)) asl) in
  let big_asm = the_asm (fun c -> is_eq c && hd_is "COND" (lhand c))
    in
  let SPLIT_LOOKUP =
    W(fun gl ->
      CASES_ON_TAC (find_term (hd_is "sptree_lookup")
                      (concl (big_asm gl)))) in
  let SPLIT_REF =
    W(fun gl ->
      let lk = the_asm (fun c -> is_eq c &&
                 hd_is "sptree_lookup" (lhand c) &&
                 hd_is "SOME" (rand c)) gl in
      CASES_ON_TAC (rand (rand (concl lk)))) in
  let SPLIT_PAIR_ARG =
    W(fun gl ->
      let fc = the_asm (fun c -> is_eq c &&
                 hd_is "dataSem_finalise_cons" (lhand c) &&
                 hd_is "SOME" (rand c)) gl in
      let rec pv t =
        if is_var t && prod_type (type_of t) then t
        else if hd_is "," t then pv (rand t)
        else failwith "pv" in
      CASES_ON_TAC (pv (rand (rand (concl fc))))) in
  (* the assumptions of the step that the lemmas of the invariant
     are applied to *)
  let the_lk asl =
    grab_asm (fun th ->
      hd_is "sptree_lookup" (lhs (concl th)) &&
      hd_is "bvlSem_MutBlock" (rand (rhs (concl th)))) asl in
  let the_fc asl =
    grab_asm (fun th ->
      hd_is "dataSem_finalise_cons" (lhs (concl th))) asl in
  let rec conses t =
    if hd_is "CONS" t then 1 + conses (rand t) else 0 in
  let the_inv_n n asl =
    grab_asm (fun th ->
      hd_is "bc_stack_ref_inv" (concl th) &&
      conses (el 2 (snd (strip_comb (concl th)))) = n) asl in
  let the_invdel asl =
    grab_asm (fun th ->
      hd_is "bc_stack_ref_inv" (concl th) &&
      (let r = el 3 (snd (strip_comb (concl th))) in
       hd_is "sptree_union" r && hd_is "sptree_delete" (lhand r)))
      asl in
  let the_invdel2 asl =
    grab_asm (fun th ->
      hd_is "bc_stack_ref_inv" (concl th) &&
      (let r = el 3 (snd (strip_comb (concl th))) in
       hd_is "sptree_union" r && hd_is "sptree_insert" (rand r)))
      asl in
  (* the centre of the block, whose invariant the step is about *)
  let centre =
    W(fun (asl,gl) ->
      let lk = the_lk asl in
      let inv = the_inv_n 1 asl in
      let fr = rand (el 3 (snd (strip_comb (concl inv)))) in
      let lu = SPEC fr (MATCH_MP lu_left lk) in
      MP_TAC (MATCH_MP bc_stack_ref_inv_MutBlock_centre
                (CONJ inv lu))) in
  (* with the reference moved from the references to the frame,
     which is what the recursive call is about *)
  let delins =
    W(fun (asl,gl) ->
      let lk = the_lk asl in
      let inv = the_inv_n 2 asl in
      MP_TAC (MATCH_MP bc_stack_ref_inv_union_del_ins_lemma
                (CONJ inv lk))) in
  (* the hypothesis of the induction, which the delete lets in *)
  let useih =
    W(fun (asl,gl) ->
      let ih = grab_asm (fun th -> is_forall (concl th) &&
                 hd_is "<" (lhand (body (rand (concl th))))) asl in
      let fc = the_fc asl in
      let dl = el 1 (snd (strip_comb (lhs (concl fc)))) in
      MP_TAC (SPEC (list_mk_icomb "sptree_size" [dl]) ih)) THEN
    (ANTS_TAC THENL
      [W(fun (asl,gl) ->
         let lk = the_lk asl in
         MP_TAC (MATCH_MP (GEN_ALL size_delete_LESS) lk)) THEN
       ASM_ARITH_TAC;
       ALL_TAC]) THEN
    W(fun (asl,gl) ->
      let fc = the_fc asl in
      let inv = the_invdel asl in
      let dl = el 1 (snd (strip_comb (lhs (concl fc)))) in
      let tso = el 2 (snd (strip_comb (lhs (concl fc)))) in
      DISCH_THEN (fun ih ->
        MP_TAC (MATCH_MP ih
          (CONJ (REFL (list_mk_icomb "sptree_size" [dl]))
            (CONJ fc (CONJ (REFL tso) inv)))))) THEN
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "issome")
                                (LABEL_TAC "ihc")) in
  (* the timestamp of the call is one, so the one of the step is
     its successor *)
  let doy =
    USE_THEN "issome" (fun is -> CASES_ON_TAC (rand (concl is))) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[IS_SOME; THE; OPTION_MAP;
                                 distinctness "option"]) THEN
    TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
    RULE_ASSUM_TRY (CONV_RULE (TOP_DEPTH_CONV MATCH_CONV)) THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      let c = concl th in
      if is_eq c && is_var (rhs c) && not (vfree_in (rhs c) (lhs c))
      then SUBST_ALL_TAC (SYM th) else fail())) THEN
    REWRITE_TAC[IS_SOME; THE] in
  (* the root of the reference, which the annotation of the
     pointer spells out *)
  let doroot =
    W(fun (asl,gl) ->
      let lk = the_lk asl in
      let xe = grab_asm (fun th ->
        is_eq (concl th) && is_var (lhs (concl th)) &&
        hd_is "gc_shared_Pointer" (rhs (concl th))) asl in
      let fr = rand (el 3 (snd (strip_comb
                 (concl (the_inv_n 1 asl))))) in
      let lu = SPEC fr (MATCH_MP lu_left lk) in
      SUBST_ALL_TAC (CONV_RULE (TOP_DEPTH_CONV MATCH_CONV)
        (REWRITE_RULE[lu; ref_ptr_annot_def] xe))) in
  let addnorm = ARITH_RULE `!a b. a + 1 + b = a + (b + 1)` in
  (* the block is finalised: the invariant of it comes from the
     one of its centre (bc_stack_ref_inv_MutBlock_F), and the
     references of the goal have the same lookups as the ones of
     that step (bc_stack_ref_inv_swap_refs) *)
  let finish =
    REWRITE_TAC[addnorm] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[addnorm]) THEN
    W(fun (asl,gl) ->
      let gr = el 3 (snd (strip_comb gl)) in
      let ihc = the_invdel2 asl in
      let r = el 3 (snd (strip_comb (concl ihc))) in
      MATCH_MP_TAC (GEN_ALL bc_stack_ref_inv_swap_refs) THEN
      EXISTS_TAC (mk_comb (rator (lhand gr), r))) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC (GEN_ALL bc_stack_ref_inv_MutBlock_F) THEN
      W(fun (asl,gl) ->
        let ihc = the_invdel2 asl in
        let rp = lhand (rand (el 2 (snd (strip_comb (concl ihc)))))
          in
        let hl = grab_asm (fun th ->
          hd_is "heap_lookup" (lhs (concl th)) &&
          hd_is "BlockRep" (rand (rhs (concl th)))) asl in
        MAP_EVERY EXISTS_TAC
          [lhand rp; rand (rand (rhs (concl hl)))]) THEN
      REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
      (* the reference is still the unfinalised block under the
         pointer: the call left nothing there
         (finalise_cons_none), so the lookup goes to the frame *)
      W(fun (asl,gl) ->
        let fc = the_fc asl in
        let args = snd (strip_comb
                    (el 1 (snd (strip_comb (lhs (concl fc)))))) in
        let pt = el 0 args in
        let dnone = REWRITE_RULE[]
                      (ISPECL [el 1 args; pt; pt] lookup_delete) in
        let none = MATCH_MP (GEN_ALL finalise_cons_none)
                     (CONJ fc dnone) in
        REWRITE_TAC[MATCH_MP lu_none none; lookup_insert]);
      GEN_TAC THEN REWRITE_TAC[lookup_insert; lookup_union] THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      TRY MATCH_REDUCE_TAC] in
  let aux = prove
   (cake_as_vars (fun () ->
     `!n v (refs:((dataSem_v)bvlSem_ref)spt) ts_opt v' refs' ts' ts
         vars' frame x xs.
        sptree_size refs = n /\
        dataSem_finalise_cons v refs ts_opt = SOME (v',refs',ts') /\
        ts_opt = SOME ts /\
        bc_stack_ref_inv c ts (v :: vars') (sptree_union refs frame)
          (x :: xs,heap,be)
        ==> IS_SOME ts' /\
            bc_stack_ref_inv c (THE ts') (v' :: vars')
              (sptree_union refs' frame) (x :: xs,heap,be)`),
    MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN DISCH_TAC THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    CASES_ON_NAME "v" THEN OPEN_FC THEN
    SAFE_MATCH_REDUCE_ASM_TAC THEN MATCH_TIDY_TAC THEN CLOSE2 THEN
    SPLIT_LOOKUP THEN TIDY THEN CLOSE2 THEN
    SPLIT_REF THEN TIDY THEN CLOSE2 THEN
    W(fun gl ->
      ASM_CASES_TAC (lhand (rator (lhand (concl (big_asm gl)))))) THEN
    ASM_FS_TAC THEN TIDY THEN CLOSE2 THEN
    W(fun gl ->
      CASES_ON_TAC (find_term (hd_is "dataSem_finalise_cons")
                      (concl (big_asm gl)))) THEN
    TIDY THEN CLOSE2 THEN
    REPEAT SPLIT_PAIR_ARG THEN TIDY THEN CLOSE2 THEN
    centre THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
    delins THEN DISCH_TAC THEN
    useih THEN doy THEN doroot THEN finish) in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  W(fun (asl,gl) ->
    let fc = the_fc asl in
    let rf = el 1 (snd (strip_comb (lhs (concl fc)))) in
    let tseq = grab_asm (fun th ->
      is_eq (concl th) && is_var (lhs (concl th)) &&
      hd_is "SOME" (rhs (concl th))) asl in
    let inv = grab_asm (fun th ->
      hd_is "bc_stack_ref_inv" (concl th)) asl in
    let sz = list_mk_icomb "sptree_size" [rf] in
    MATCH_ACCEPT_TAC (MATCH_MP (SPEC sz aux)
      (CONJ (REFL sz) (CONJ fc (CONJ tseq inv))))))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_FinaliseCons = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((v,w) :: vars) /\
      dataSem_finalise_cons v refs (SOME ts) = SOME (v',refs',ts')
        ==>
      IS_SOME ts' /\
      memory_rel c be (THE ts') refs' sp st m dm ((v',w) :: vars)`),
  (* the finalisation of a cons: what it does to the refs and to
     the timestamp is what bc_stack_ref_inv_FinaliseCons_lemma
     says of the invariant of the stack, with no frame beside the
     refs (the union with the empty tree is the tree).  The heap,
     the roots and the words of the roots are the same, so the
     memory_rel goes back together as it came apart *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* an ALL2 whose second list is a cons *)
    let all2cons = prove
     (`!P h t (l:(A)list).
         ALL2 P l (CONS (h:B) t) <=>
         ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
      REPEAT GEN_TAC THEN
      STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
      REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
    (* the union with the empty tree on the right *)
    let union_LN = prove
     (`!t. sptree_union t (LN:(A)spt) = t`,
      MATCH_MP_TAC spt_INDUCT THEN REPEAT CONJ_TAC THEN
      REPEAT GEN_TAC THEN TRY(DISCH_THEN(K ALL_TAC)) THEN
      REWRITE_TAC[union_def] THEN
      TRY MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
  DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
    REWRITE_TAC[memory_rel_def; word_ml_inv_def;
                abs_ml_inv_def; MAP; FST] THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun a2 ->
      if hd_is "ALL2" (concl a2)
      then MP_TAC(REWRITE_RULE[MAP; SND; all2cons] a2) else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "CONS" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    W(fun (asl,w) ->
      let th0 = bc_stack_ref_inv_FinaliseCons_lemma in
      let vs = fst(strip_forall (concl th0)) in
      let th1 = REWRITE_RULE[union_LN]
        (SPECL (map (fun v ->
           if fst(dest_var v) = "frame"
           then `LN:((dataSem_v)bvlSem_ref)spt` else v) vs) th0) in
      let bs = grab asl (fun th ->
        hd_is "bc_stack_ref_inv" (concl th)) in
      let fc = grab asl (fun th ->
        hd_is "dataSem_finalise_cons" (lhs (concl th))) in
      MP_TAC(MATCH_MP th1
        (CONJ fc (CONJ (REFL (rand (lhs (concl fc)))) bs)))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[memory_rel_def; word_ml_inv_def;
                abs_ml_inv_def; MAP; FST] THEN
    W(fun (asl,w) ->
      let hm = grab asl (fun th ->
        hd_is "heap_in_memory_store" (concl th)) in
      let args = snd(strip_comb (concl hm)) in
      EXISTS_TAC (el 0 args) THEN EXISTS_TAC (el 9 args) THEN
      EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
      EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args)) THEN
    ASM_REWRITE_TAC[] THEN
    W(fun (asl,w) ->
      let bs = grab asl (fun th ->
        hd_is "bc_stack_ref_inv" (concl th)) in
      EXISTS_TAC (fst(dest_pair
        (el 4 (snd(strip_comb (concl bs))))))) THEN
    ASM_REWRITE_TAC[ALL2]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Cons_empty = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m (dm:'a word->bool) vars /\
      tag < dimword (:'a) DIV 16 /\ good_dimindex (:'a) ==>
      memory_rel c be ts refs sp st m dm
        ((Block 0 tag [],wordLang_Word (BlockNil tag)) :: vars)`),
  (* the empty Block of a tag has the root Data (Word (BlockNil
     tag)), which cons_thm_EMPTY adds, and the BlockNil is sixteen
     times the tag plus two, whose lowest bit is clear.  HOL4 has
     that last fact as BlockNil_and_lemma; the port's statement of
     that lemma is the and of the complement with the multiple of
     sixteen, not with the sum (see ISSUES.md, "The precedence of a
     word's bitwise operators"), so the fact is proved again here *)
  (let bw2 = prove
     (`!i. bit i (word 2:(N)word) <=> i = 1 /\ 1 < dimindex(:N)`,
      GEN_TAC THEN
      GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
        [ARITH_RULE `2 = 2 EXP 1`] THEN
      REWRITE_TAC[BIT_WORD_POW2]) in
    let addor = prove
     (`!(v:(N)word). word_shl v 4 + word 2 = word_shl v 4 || word 2`,
      GEN_TAC THEN MATCH_MP_TAC WORD_ADD_OR THEN
      REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
                  BIT_WORD_SHL; bw2] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `(i:num) = 1` THEN ASM_REWRITE_TAC[] THEN
      CONV_TAC NUM_REDUCE_CONV THEN TRY(CONV_TAC TAUT)) in
    let andsum = prove
     (`!(tag:(N)word).
         (word_shl tag 4 + word 2) && word_not (word 1) =
         word_shl tag 4 + word 2`,
      GEN_TAC THEN REWRITE_TAC[addor] THEN
      REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
                  BIT_WORD_1; BIT_WORD_OR; BIT_WORD_SHL; bw2] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
      CONV_TAC NUM_REDUCE_CONV THEN TRY(CONV_TAC TAUT)) in
    let waddr = hd (word_addr_clauses ()) in
    REWRITE_TAC[memory_rel_def; word_ml_inv_def] THEN
    REPEAT STRIP_TAC THEN ASM_EXISTS_TAC THEN
    ASM_REWRITE_TAC[] THEN
    EXISTS_TAC
      `CONS (gc_shared_Data (wordLang_Word (BlockNil tag:'a word))) hs`
    THEN
    REWRITE_TAC[MAP; ALL2; waddr] THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC cons_thm_EMPTY THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[BlockNil_def] THEN AP_TERM_TAC THEN
      MATCH_ACCEPT_TAC andsum]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Ref = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm (ZIP vals ws ++ vars) /\
      LENGTH vals = LENGTH (ws:('a word_loc) list) /\
      encode_header c 2 (LENGTH ws) = SOME hd /\ ~(new IN (domain
        refs)) /\
      LENGTH ws < sp /\ good_dimindex (:'a) ==>
      (?eoh (curr:'a word) trig m1.
        FLOOKUP st EndOfHeap = SOME (wordLang_Word eoh) /\
        FLOOKUP st TriggerGC = SOME (wordLang_Word trig) /\
        FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
        (let w = eoh - bytes_in_word * n2w (LENGTH ws + 1) in
        let w1 = trig - bytes_in_word * n2w (LENGTH ws + 1) in
          data_to_word_memoryProof_store_list w (wordLang_Word hd
            :: ws) m dm = SOME m1 /\
          memory_rel c be ts (insert new (ValueArray vals) refs)
            (sp - (LENGTH ws + 1))
            (st |+ (EndOfHeap,wordLang_Word w) |+
              (TriggerGC,wordLang_Word w1)) m1 dm
            ((RefPtr T new,make_ptr c (w - curr) (n2w 0) (LENGTH
              ws)) :: vars)))`),
(* the allocation of a reference in the unused space: new_ref_thm
   gives the invariant of the stack with the new pointer pushed and
   the store of the element into the unused space, and pop_thm takes
   the values that the element holds off that stack again, which is
   the invariant the statement wants.  Of the heap the condition of
   heap_store_unused says where the space is, so heap_lookup_SPLIT
   and heap_store_lemma make the new heap, and the words of the
   space split (word_list_exists_ADD) into what stays unused and the
   element's own words, which store_list_thm writes -- the header
   that encode_header gave (its length is the condition of the
   payload, by encode_header_IMP) and the roots of the values, which
   EVERY2_f_EQ says are the words of the statement.  The ends of the
   heap that the store holds move down by those words, and the
   pointer of the new reference is make_ptr of the offset: the shift
   of bytes_in_word_mul_eq_shift composed with the one of make_ptr
   is the shift of get_addr, and the lower bits of a zero
   annotation are the one bit *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let front sp cell =
    let pred = rator (concl sp) in
    let fs = facs pred in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk x y = mk_comb(mk_comb(st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target),
              REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
    REWRITE_RULE[eq] sp in
  (* the bits of a zero word are zero *)
  let bits0 = prove
   (`!h l. word_bits h l ((n2w 0):(N)word) = n2w 0`,
    REWRITE_TAC[word_bits; WORD_EQ_BITS_ALT; BIT_WORD_SUBWORD;
                BIT_WORD_0] THEN
    CONV_TAC TAUT) in
  (* an ALL2 over two appends of matching lengths *)
  let all2app = prove
   (`!(P:A->B->bool) xs1 ys1 xs2 ys2.
       LENGTH xs1 = LENGTH ys1
       ==> (ALL2 P (xs1 ++ xs2) (ys1 ++ ys2) <=>
            ALL2 P xs1 ys1 /\ ALL2 P xs2 ys2)`,
    GEN_TAC THEN LIST_INDUCT_TAC THENL
     [X_GEN_TAC `ys1:(B)list` THEN
      STRUCT_CASES_TAC (ISPEC `ys1:(B)list` list_CASES) THEN
      REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC;
                  ARITH_RULE `~(0 = SUC n)`];
      X_GEN_TAC `ys1:(B)list` THEN
      STRUCT_CASES_TAC (ISPEC `ys1:(B)list` list_CASES) THEN
      REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC;
                  ARITH_RULE `~(SUC n = 0)`; SUC_INJ] THEN
      REPEAT GEN_TAC THEN DISCH_TAC THEN
      ASM_SIMP_TAC[] THEN CONV_TAC TAUT]) in
  (* an equation of two addresses, from the numeric facts *)
  let numfacts asl =
    mapfilter (fun (_,th) ->
      let c = concl th in
      if (try hd_is "<=" c || hd_is "<" c ||
              (is_eq c && hd_is "LENGTH" (lhs c) &&
               hd_is "LENGTH" (rhs c))
          with Failure _ -> false) then th else fail()) asl in
  (* two steps of an address in one *)
  let addsum = prove
   (`!(a:'a word) x y.
       a + bytes_in_word * n2w x + bytes_in_word * n2w y =
       a + bytes_in_word * n2w (x + y)`,
    REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE) in
  let someif = prove
   (`!p (x:A) y. (if p then SOME x else NONE) = SOME y ==> x = y`,
    REPEAT GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"]) in
  let addreq asl t1 t2 =
      let fs = numfacts asl in
      let extra = (try
        let lt = grab asl (fun th ->
          try hd_is "<" (concl th) &&
              hd_is "LENGTH" (lhand (concl th))
          with Failure _ -> false) in
        let spe = grab asl (fun th ->
          try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
              is_var (rand (concl th))
          with Failure _ -> false) in
        [MATCH_MP (ARITH_RULE
           `!a b c:num. a < b /\ b <= c ==> a + 1 <= c`)
           (CONJ lt spe)]
        with Failure _ -> []) in
      let cnd = end_itlist CONJ (fs @ extra) in
      MP (prove (mk_imp (concl cnd, mk_eq (t1,t2)),
            DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
              (fun th -> ASSUME_TAC
                 (REWRITE_RULE[LENGTH; ADD1] th))) THEN
            ASM_REWRITE_TAC[LENGTH; ADD1] THEN
            REWRITE_TAC[WORD_SUB; WORD_ADD] THEN
            ASM_SIMP_TAC[ARITH_RULE
              `!l s h:num. l <= s ==> l <= h + s`;
              ARITH_RULE
              `!a b c:num. a <= b /\ b <= c ==> a <= c`] THEN
            CONV_TAC WORD_RULE)) cnd in
  let wordeq =
    W(fun (asl,gl) ->
      REWRITE_TAC[addreq asl (rand (rand (lhs gl)))
                    (rand (rand (rhs gl)))]) in
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* what the invariant says of the stack *)
  FIRST_ASSUM (fun mr ->
    if hd_is "memory_rel" (concl mr)
    then MP_TAC (REWRITE_RULE[memory_rel_def; word_ml_inv_def] mr)
    else fail()) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the values and the words that the ZIP of the stack holds *)
  W(fun (asl,gl) ->
    let le = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    RULE_ASSUM_TRY (REWRITE_RULE[MAP_APPEND;
      MATCH_MP MAP_FST_ZIP le; MATCH_MP MAP_SND_ZIP le])) THEN
  (* the store of the new reference *)
  W(fun (asl,gl) ->
    let ai = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
    let nd = grab asl (fun th ->
      try hd_is "IN" (dest_neg (concl th)) with Failure _ -> false) in
    let lt = grab asl (fun th ->
      try hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false) in
    let le = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    let spe = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          lhand (concl th) = rand (concl lt)
      with Failure _ -> false) in
    let bnd = MATCH_MP (ARITH_RULE
                `!a b c d:num. a = b /\ b < c /\ c <= d
                               ==> a + 1 <= d`)
                (CONJ le (CONJ lt spe)) in
    MP_TAC (MATCH_MP (GEN_ALL new_ref_thm)
      (CONJ ai (CONJ nd bnd)))) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the ends of the heap that the store holds *)
  FIRST_ASSUM (fun hs ->
    if hd_is "heap_in_memory_store" (concl hs)
    then STRIP_ASSUME_TAC
           (REWRITE_RULE[heap_in_memory_store_def] hs)
    else fail()) THEN
  (* the unused space of the heap, where the element goes *)
  FIRST_ASSUM (fun hu ->
    if not (try hd_is "heap_store_unused" (lhs (concl hu))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_unused_def] hu)) THEN
  COND_CASES_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  FIRST_X_ASSUM (fun cnd ->
    if not (is_conj (concl cnd)) then fail() else
    if not (try hd_is "heap_lookup" (lhs (lhand (concl cnd)))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC cnd) THEN
  (* so the heap splits there *)
  FIRST_ASSUM (fun hl ->
    if not (try hd_is "heap_lookup" (lhs (concl hl))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                (hd_is "APPEND" (rhs (concl e)) ||
                 hd_is "heap_length" (rhs (concl e)))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  (* and the store writes the element at the end of the space *)
  FIRST_ASSUM (fun hs ->
    if not (try hd_is "heap_store" (lhs (concl hs))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_lemma; PAIR_EQ] hs)) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the words of the unused space, and its end where the element
     goes *)
  W(fun (asl,gl) ->
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "el_length" (lhand (concl th))
      with Failure _ -> false) in
    let e1 = REWRITE_RULE[RefBlock_def; el_length_def] bnd in
    let eq1 = MATCH_MP (ARITH_RULE
                `!k s:num. k + 1 <= s ==> (s - 1) + 1 = s`) e1 in
    let eq3 = MATCH_MP (ARITH_RULE
                `!k s:num. k + 1 <= s
                           ==> (s - (k + 1)) + (k + 1) = s`) e1 in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th))
      with Failure _ -> false) in
    let sep1 = REWRITE_RULE[word_heap_APPEND; word_heap_def;
                 word_el_def; el_length_def; eq1] sep in
    let addr = el 0 (snd(strip_comb (find (fun t ->
                 hd_is "word_list_exists" t)
                 (facs (rator (concl sep1)))))) in
    let wle = REWRITE_RULE[eq3]
                (ISPECL [lhand (lhs (concl eq3));
                         rand (lhs (concl eq3)); addr]
                   word_list_exists_ADD) in
    let sep2 = REWRITE_RULE[wle; STAR_ASSOC] sep1 in
    ASSUME_TAC sep2) THEN
  (* the words of the element are as many as its roots, and its
     address is the end of the heap less them *)
  W(fun (asl,gl) ->
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          length (filter (hd_is "word_list_exists")
                   (facs (rator (concl th)))) = 2
      with Failure _ -> false) in
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "el_length" (lhand (concl th))
      with Failure _ -> false) in
    let e1 = REWRITE_RULE[RefBlock_def; el_length_def] bnd in
    let rsl = rand (lhand (lhand (concl e1))) in
    let l1 = grab asl (fun th ->
