    let t1 = el 0 (snd(strip_comb sl)) in
    let iscell t = hd_is "misc_word_list" t &&
                   hd_is "CONS" (el 1 (snd(strip_comb t))) in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let t2 = el 0 (snd(strip_comb
               (find iscell (facs (rator (concl sep)))))) in
    REWRITE_TAC[addreq asl t1 t2]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the root of the value and the roots of the stack *)
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                hd_is "CONS" (rhs (concl e))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      try hd_is "ALL2" (concl th) &&
          hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
      with Failure _ -> false) in
    STRIP_ASSUME_TAC (REWRITE_RULE[ALL2] a2)) THEN
  (* the invariant of the stack without the value *)
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "sptree_insert"
             (el 2 (snd(strip_comb (concl th))))
       with Failure _ -> false)) in
    let ai2 = CONV_RULE (ONCE_DEPTH_CONV
                (REWR_CONV conapp)) ai in
    let lenq = prove (mk_eq (mk_icomb (`LENGTH`,
                  lhand (el 1 (snd(strip_comb (concl ai2))))),
                mk_icomb (`LENGTH`,
                  lhand (el 0 (tparts (el 3 (snd(strip_comb
                    (concl ai2)))))))),
                REWRITE_TAC[LENGTH]) in
    ASSUME_TAC (MATCH_MP (GEN_ALL pop_thm) (CONJ ai2 lenq))) THEN
  (* the invariant with the new element in the heap *)
  REWRITE_TAC[memory_rel_def] THEN
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
       with Failure _ -> false)) in
    let args = snd(strip_comb (concl ai)) in
    let ps = tparts (el 3 args) in
    MAP_EVERY EXISTS_TAC
      [el 1 ps; el 4 args; el 3 ps; el 4 ps; el 5 ps; el 6 ps]) THEN
  REPEAT CONJ_TAC THENL
   [ALL_TAC;
    (* the roots: the pointer of the new reference and the rest *)
    REWRITE_TAC[word_ml_inv_def] THEN
    W(fun (asl,gl) ->
      let ai = grab asl (fun th ->
        hd_is "abs_ml_inv" (concl th) &&
        (try hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
         with Failure _ -> false)) in
      EXISTS_TAC
        (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
    REWRITE_TAC[MAP; FST; SND; ALL2] THEN
    CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    (* the word of the pointer is the one make_ptr builds *)
    W(fun (asl,gl) ->
      let mp = rhs gl in
      let sub = el 1 (snd(strip_comb mp)) in
      let aterm = lhand sub in
      let bwterm = rand aterm in
      let pt = lhand (rand (lhs gl)) in
      let mulp = mk_comb (rator bwterm,
                   mk_comb (rator (rand bwterm), pt)) in
      SUBST1_TAC (addreq asl sub mulp)) THEN
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      REWRITE_TAC(word_addr_clauses ()) THEN
      REWRITE_TAC[make_ptr_def; get_addr_def; get_lowerbits_def] THEN
      MATCH_REDUCE_TAC THEN
      REWRITE_TAC[MATCH_MP bytes_in_word_mul_eq_shift gd;
                  WORD_SHL_COMPOSE; bits0] THEN
      ASM_SIMP_TAC[ARITH_RULE
        `!a b:num. a <= b ==> a + (b - a) = b`] THEN
      REWRITE_TAC[WORD_OR_0; WORD_ADD_0]);
    FIRST_ASSUM ACCEPT_TAC;
    W(fun (asl,gl) ->
      let spe = grab asl (fun th ->
        try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
            is_var (rand (concl th))
        with Failure _ -> false) in
      let les = mapfilter (fun (_,th) ->
        if (try is_eq (concl th) &&
                hd_is "LENGTH" (lhs (concl th)) &&
                hd_is "LENGTH" (rhs (concl th))
            with Failure _ -> false) then th else fail()) asl in
      MP_TAC (end_itlist CONJ (spe :: les))) THEN
    REWRITE_TAC[LENGTH; ADD1] THEN ARITH_TAC] THEN
  (* the store of the new heap: its length is the old one *)
  REWRITE_TAC[heap_in_memory_store_def] THEN
  W(fun (asl,gl) ->
    let hu = grab asl (fun th ->
      try hd_is "heap_store_unused" (lhs (concl th))
      with Failure _ -> false) in
    REWRITE_TAC[MATCH_MP heap_store_unused_IMP_length hu]) THEN
  W(fun (asl,gl) ->
    let dis = CONJUNCTS (distinctness "store_name") in
    REWRITE_TAC([FLOOKUP_UPDATE; FDOM_FUPDATE; IN_INSERT] @
                dis @ map GSYM dis)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the two heaps of the store *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "CurrHeap"))));
       rand (rand (rhs (concl (flk "OtherHeap"))))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (wordeq THEN NO_TAC) THEN
  (* the two modes of the thunk, which the header tells apart *)
  CASES_ON_NAME "ev" THEN
  RULE_ASSUM_TRY (CONV_RULE (TOP_DEPTH_CONV MATCH_CONV)) THEN
  RULE_ASSUM_TRY (CONV_RULE NUM_REDUCE_CONV) THEN
  (* the heap with the new element, which the store wrote *)
  FIRST_ASSUM (fun h2 ->
    if not (try is_eq (concl h2) && hd_is "APPEND" (lhs (concl h2)) &&
                is_var (rhs (concl h2))
            with Failure _ -> false) then fail() else
    SUBST1_TAC (SYM h2)) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_heap_expand;
              word_heap_def; heap_length_APPEND;
              heap_length_heap_expand; ThunkBlock_def] THEN
  REWRITE_TAC[word_el_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; LENGTH_MAP; el_length_def;
              heap_length_NIL; thunk_tag_bits_lemma; notevbits;
              MAP; LENGTH; STAR_ASSOC; emp_STAR; STAR_emp] THEN
  TRY (CONV_TAC NUM_REDUCE_CONV) THEN
  (* the word of the value and the header that encode_header gave *)
  W(fun (asl,gl) ->
    let wr = grab asl (fun th ->
      try is_eq (concl th) && hd_is "word_addr" (lhs (concl th))
      with Failure _ -> false) in
    let eh = grab asl (fun th ->
      try hd_is "encode_header" (lhs (concl th))
      with Failure _ -> false) in
    let mh = CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
               (REWRITE_RULE[encode_header_def] eh)) in
    REWRITE_TAC[wr; mh]) THEN
  (* the condition of the payload, which the header's length says *)
  TRY (W(fun (asl,gl) ->
    let pred = rator gl in
    let fs = facs pred in
    let cell = find (hd_is "cond") fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk a b = mk_comb(mk_comb(st,a),b) in
    SUBGOAL_THEN (mk_eq (pred, mk cell (end_itlist mk rest)))
      SUBST1_TAC THENL
     [REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]; ALL_TAC]) THEN
   REWRITE_TAC[cond_STAR] THEN
   CONJ_TAC THENL
    [W(fun (asl,gl) ->
       let eh = grab asl (fun th ->
         try hd_is "encode_header" (lhs (concl th))
         with Failure _ -> false) in
       let ls7 = grab asl (fun th ->
         try hd_is "<" (concl th) &&
             hd_is "+" (lhand (concl th)) &&
             hd_is "data_to_word_config_len_size"
               (lhand (lhand (concl th)))
         with Failure _ -> false) in
       let ls = MATCH_MP (ARITH_RULE
                  `!a b:num. a + 7 < b ==> a + 5 < b`) ls7 in
       let gd = grab asl (fun th ->
         hd_is "good_dimindex" (concl th)) in
       STRIP_ASSUME_TAC (MATCH_MP encode_header_IMP
         (CONJ eh (CONJ ls gd)))) THEN
     ASM_REWRITE_TAC[];
     ALL_TAC]) THEN
  (* and the words at the address the store wrote them to *)
  W(fun (asl,gl) ->
    let iscell t = hd_is "misc_word_list" t &&
                   hd_is "CONS" (el 1 (snd(strip_comb t))) in
    let sl = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let bnd = CONV_RULE NUM_REDUCE_CONV
                (REWRITE_RULE[LENGTH; ADD1] (grab asl (fun th ->
                   try hd_is "<=" (concl th) &&
                       (hd_is "LENGTH" (lhand (concl th)) ||
                        (hd_is "NUMERAL" (lhand (concl th)) &&
                         hd_is "+" (rand (concl th))))
                   with Failure _ -> false))) in
    let arith = MATCH_MP (ARITH_RULE
                  `!l s:num. l <= s ==> (s - l) + l = s`) bnd in
    let sl2 = REWRITE_RULE[LENGTH; ADD1; word_list_def;
                word_heap_heap_expand; STAR_ASSOC; emp_STAR;
                STAR_emp; addsum] sl in
    REWRITE_TAC[heap_length_CONS; heap_length_NIL; el_length_def;
                ARITH_RULE `!n:num. n + 0 = n`] THEN
    TRY (CONV_TAC NUM_REDUCE_CONV) THEN
    REWRITE_TAC[addsum; arith] THEN
    W(fun (asl2,gl2) ->
      let eq = prove (mk_eq (rator gl2, rator (concl sl2)),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      ACCEPT_TAC (REWRITE_RULE[GSYM eq] sl2))))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_write = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm vars ==>
      (?(free':'a word).
        FLOOKUP st NextFree = SOME (wordLang_Word free') /\
        (!n.
          n < sp ==>
          (let a = free' + bytes_in_word * n2w n in
            a IN dm /\ memory_rel c be ts refs sp st ((a =+ w) m)
              dm vars)))`),
(* the proof of the source names memory_rel_def,
   heap_in_memory_store_def, word_ml_inv_def, abs_ml_inv_def,
   unused_space_inv_def and heap_lookup_SPLIT, and writes the cell
   with HOL4's SEP_W_TAC.  Here the next free address is the one
   the store says and the space from it is the Unused element that
   unused_space_inv puts at the end of the data of the heap; a
   write below the space keeps the invariant, because nothing of it
   but the memory of heap_in_memory_store has the memory in it, and
   what that says of the written memory is the lemma below, which
   is read_fun2set and write_fun2set over a whole space *)
  ((* the factors of a separation predicate, and the predicate with
     the factor of a kind brought to the front *)
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd (strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let sfront nm sep =
    let pred = rator (concl sep) in
    let fs = facs pred in
    let cell = find (hd_is nm) fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst (strip_comb pred) in
    let mk x y = mk_comb (mk_comb (st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target), REWRITE_TAC[STAR_AC]) in
    REWRITE_RULE[eq] sep in
  let cfront = prove
   (`!(q:(A->bool)->bool) r c. (q * cond c) * r = cond c * (q * r)`,
    REWRITE_TAC[STAR_AC]) in
  let mswap = WORD_RULE
    `!(a:'a word) n.
       a + n2w n * bytes_in_word = a + bytes_in_word * n2w n` in
  let is_heapeq th =
    try is_eq (concl th) && is_var (lhs (concl th)) &&
        hd_is "APPEND" (rand (concl th))
    with Failure _ -> false in
  let is_aeq th =
    try is_eq (concl th) && is_var (lhs (concl th)) &&
        hd_is "heap_length" (rand (concl th))
    with Failure _ -> false in
  let is_sep th =
    try hd_is "STAR" (rator (concl th)) with Failure _ -> false in
  let sepof wv th =
    let th1 = (try SPEC wv th with Failure _ -> th) in
    let th2 = (try CONJUNCT2 th1 with Failure _ -> th1) in
    if is_sep th2 then th2 else failwith "sepof" in
  (* the port's own: a cell of an unused space of the heap is in
     the memory and can be written, and what the space says of the
     memory it says of the written one -- the list of the words of
     the space is the old list with one word replaced, which is as
     long as it was.  This is what HOL4's SEP_R_TAC and SEP_W_TAC
     do to the assumption, here as a lemma over the space *)
  let word_list_exists_write = prove
   (`!(a:'a word) k n p m dm w.
       (word_list_exists a k * p) (fun2set (m,dm)) /\ n < k ==>
       (a + bytes_in_word * n2w n) IN dm /\
       (word_list_exists a k * p)
         (fun2set (((a + bytes_in_word * n2w n) =+ w) m,dm))`,
    REPEAT GEN_TAC THEN
    REWRITE_TAC[word_list_exists_def; SEP_EXISTS_STAR;
                SEP_EXISTS_THM] THEN
    DISCH_THEN (CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
    REWRITE_TAC[cfront; cond_STAR] THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_ASSUM (fun le ->
      if (try is_eq (concl le) && hd_is "LENGTH" (lhs (concl le))
          with Failure _ -> false)
      then FIRST_ASSUM (fun lt ->
             if (try hd_is "<" (concl lt) with Failure _ -> false)
             then STRIP_ASSUME_TAC (MATCH_MP LESS_LENGTH
                    (ONCE_REWRITE_RULE[GSYM le] lt))
             else fail())
      else fail()) THEN
    FIRST_X_ASSUM (fun eq ->
      if is_heapeq eq then SUBST_ALL_TAC eq else fail()) THEN
    FIRST_X_ASSUM (fun lne ->
      if (try is_eq (concl lne) &&
              hd_is "LENGTH" (lhs (concl lne)) &&
              is_var (rand (concl lne))
          with Failure _ -> false)
      then SUBST_ALL_TAC (SYM lne) else fail()) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[word_list_APPEND; word_list_def;
                                 STAR_ASSOC; mswap]) THEN
    FIRST_ASSUM (fun sep ->
      if not (is_sep sep) then fail() else
      let sep' = sfront "set_sep_one" sep in
      STRIP_ASSUME_TAC (MATCH_MP read_fun2set sep') THEN
      STRIP_ASSUME_TAC (MATCH_MP write_fun2set sep')) THEN
    CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    W(fun (asl,gl) ->
      let bod = snd (dest_exists gl) in
      let pr = rand (rand (rand bod)) in
      let wv = rand (rator (fst (dest_pair pr))) in
      let sep = find (fun th ->
        (try is_sep th &&
             exists (hd_is "set_sep_one") (facs (rator (concl th)))
         with Failure _ -> false)) (map snd asl) in
      let fs = facs (rator (concl sep)) in
      let wls = filter (hd_is "misc_word_list") fs in
      EXISTS_TAC (list_mk_icomb "APPEND"
        [rand (el 0 wls);
         list_mk_icomb "CONS" [wv; rand (el 1 wls)]])) THEN
    CONJ_TAC THENL
     [RULE_ASSUM_TRY (REWRITE_RULE[LENGTH_APPEND; LENGTH]) THEN
      REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN ASM_ARITH_TAC;
      REWRITE_TAC[word_list_APPEND; word_list_def; STAR_ASSOC;
                  mswap] THEN
      W(fun (asl,gl) ->
        let pred = rator gl in
        let wv = rand (rator (fst (dest_pair (rand (rand gl))))) in
        FIRST_ASSUM (fun wth ->
          let th = sepof wv wth in
          let eq = prove (mk_eq (pred,rator (concl th)),
                          REWRITE_TAC[STAR_AC]) in
          ACCEPT_TAC (REWRITE_RULE[GSYM eq] th)))]) in
  (* the next free address is the one the store says, and the space
     from it is the Unused element that unused_space_inv puts at the
     end of the data of the heap (heap_lookup_SPLIT splits the heap
     at it).  A write below the space keeps the invariant: nothing
     of it but the memory of heap_in_memory_store has the memory in
     it, and that is the lemma above *)
  STRIP_TAC THEN
  FIRST_ASSUM (fun mr ->
    if hd_is "memory_rel" (concl mr)
    then STRIP_ASSUME_TAC (REWRITE_RULE[memory_rel_def] mr)
    else fail()) THEN
  FIRST_ASSUM (fun h ->
    if hd_is "heap_in_memory_store" (concl h)
    then STRIP_ASSUME_TAC
           (REWRITE_RULE[heap_in_memory_store_def] h)
    else fail()) THEN
  ASM_EXISTS_TAC THEN CONJ_TAC THEN
  TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  FIRST_ASSUM (fun wi ->
    if hd_is "word_ml_inv" (concl wi)
    then STRIP_ASSUME_TAC (REWRITE_RULE[word_ml_inv_def;
           abs_ml_inv_def; unused_space_inv_def] wi)
    else fail()) THEN
  FIRST_ASSUM (fun imp ->
    let c = concl imp in
    if is_imp c &&
       (try hd_is "heap_lookup" (lhs (rand c))
        with Failure _ -> false)
    then SUBGOAL_THEN (lhand c)
           (fun th -> STRIP_ASSUME_TAC (MP imp th)) THENL
          [ASM_ARITH_TAC; ALL_TAC]
    else fail()) THEN
  FIRST_ASSUM (fun hl ->
    if (try hd_is "heap_lookup" (lhs (concl hl))
        with Failure _ -> false)
    then STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl)
    else fail()) THEN
  FIRST_ASSUM (fun heq ->
    if not (is_heapeq heq) then fail() else
    FIRST_ASSUM (fun aeq ->
      if not (is_aeq aeq) then fail() else
      FIRST_ASSUM (fun sep ->
        if not (is_sep sep) then fail() else
        ASSUME_TAC (REWRITE_RULE[heq; word_heap_APPEND;
          word_heap_def; word_el_def; el_length_def;
          STAR_ASSOC; GSYM aeq] sep)))) THEN
  FIRST_ASSUM (fun sep ->
    if not (is_sep sep) ||
       not (exists (hd_is "word_list_exists")
              (facs (rator (concl sep)))) then fail() else
    let sep' = sfront "word_list_exists" sep in
    let cell = find (hd_is "word_list_exists")
                 (facs (rator (concl sep'))) in
    let k = el 1 (snd (strip_comb cell)) in
    SUBGOAL_THEN (mk_binop `(<):num->num->bool` `n:num` k)
      (fun lt -> STRIP_ASSUME_TAC
         (MATCH_MP word_list_exists_write (CONJ sep' lt))) THENL
     [ASM_ARITH_TAC; ALL_TAC]) THEN
  CONJ_TAC THENL
   [FIRST_ASSUM (fun th -> ACCEPT_TAC (CONJUNCT1 (SPEC_ALL th)));
    ALL_TAC] THEN
  REWRITE_TAC[memory_rel_def] THEN
  FIRST_ASSUM (fun h ->
    if hd_is "heap_in_memory_store" (concl h)
    then let args = snd (strip_comb (concl h)) in
         MAP_EVERY EXISTS_TAC [el 0 args; el 9 args; el 1 args;
                               el 2 args; el 3 args; el 4 args]
    else fail()) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  REWRITE_TAC[heap_in_memory_store_def] THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST_ASSUM (fun sep ->
    if not (is_sep sep) then fail() else
    let fs = facs (rator (concl sep)) in
    let whs = filter (hd_is "word_heap") fs in
    if not (length whs = 2) then fail() else
    MAP_EVERY EXISTS_TAC
      [el 0 (snd (strip_comb (el 0 whs)));
       el 0 (snd (strip_comb (el 1 whs)))]) THEN
  REPEAT CONJ_TAC THEN
  TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  FIRST_ASSUM (fun heq ->
    if not (is_heapeq heq) then fail() else
    FIRST_ASSUM (fun aeq ->
      if not (is_aeq aeq) then fail() else
      REWRITE_TAC[heq; word_heap_APPEND; word_heap_def;
        word_el_def; el_length_def; STAR_ASSOC; GSYM aeq])) THEN
  W(fun (asl,gl) ->
    let pred = rator gl in
    let wv = rand (rator (fst (dest_pair (rand (rand gl))))) in
    FIRST_ASSUM (fun wth ->
      let th = sepof wv wth in
      let eq = prove (mk_eq (pred,rator (concl th)),
                      REWRITE_TAC[STAR_AC]) in
      ACCEPT_TAC (REWRITE_RULE[GSYM eq] th)))));;

let word_list_AND_word_list_exists_IMP = prove
 (`!ws aa frame n.
      (misc_word_list aa ws * SEP_T) (fun2set (m,dm)) /\
      (word_list_exists aa n * frame) (fun2set (m,dm)) /\
      LENGTH ws <= n ==>
      (misc_word_list aa ws *
       word_list_exists (aa + bytes_in_word * n2w (LENGTH ws)) (n -
         LENGTH ws) *
       frame) (fun2set (m,dm))`,
  (* a word_list that lies inside free space takes the front of it:
     the cell of the head is the first cell of the space (both are
     the memory at the address, which read_fun2set reads off), and
     the induction hypothesis takes the tail with that cell in the
     frame *)
  (let has nm th =
     can (find_term (fun t ->
       (try fst(dest_const(fst(strip_comb t))) = nm
        with Failure _ -> false))) (concl th) in
   let aux = prove
    (`!(ws:(M)list) (aa:(N)word) frame n m dm.
        (misc_word_list aa ws * SEP_T) (fun2set (m,dm)) /\
        (word_list_exists aa n * frame) (fun2set (m,dm)) /\
        LENGTH ws <= n
        ==> (misc_word_list aa ws *
             word_list_exists (aa + bytes_in_word * n2w (LENGTH ws))
               (n - LENGTH ws) * frame) (fun2set (m,dm))`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
      [REWRITE_TAC[word_list_def; LENGTH; emp_STAR;
                   SUB_0; WORD_ADD_MUL_0] THEN
       STRIP_TAC THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     STRIP_TAC THEN
     (SUBGOAL_THEN `?n':num. n = SUC n'` MP_TAC THENL
       [EXISTS_TAC `n - 1` THEN
        FIRST_X_ASSUM(fun th -> MP_TAC th) THEN
        REWRITE_TAC[LENGTH] THEN ARITH_TAC;
        ALL_TAC]) THEN
     DISCH_THEN(X_CHOOSE_THEN `n':num` SUBST_ALL_TAC) THEN
     RULE_ASSUM_TAC(REWRITE_RULE
       [word_list_def; LENGTH;
        word_list_exists_thm;
        SEP_EXISTS_STAR; SEP_EXISTS_THM]) THEN
     FIRST_X_ASSUM(fun ex ->
       if is_exists (concl ex) then
         X_CHOOSE_THEN `w:M` ASSUME_TAC ex else fail()) THEN
     REWRITE_TAC[word_list_def; LENGTH] THEN
     REWRITE_TAC[ARITH_RULE `SUC a - SUC b = a - b`;
                 WORD_ADD_MUL_SUC] THEN
     SUBGOAL_THEN `(w:M) = h` SUBST_ALL_TAC THENL
      [FIRST_ASSUM(fun a1 ->
         if has "SEP_T" a1
         then MP_TAC(MATCH_MP read_fun2set
                (REWRITE_RULE[GSYM STAR_ASSOC] a1))
         else fail()) THEN
       FIRST_ASSUM(fun a2 ->
         if has "word_list_exists" a2
         then MP_TAC(MATCH_MP read_fun2set
                (REWRITE_RULE[GSYM STAR_ASSOC] a2))
         else fail()) THEN
       MESON_TAC[];
       ALL_TAC] THEN
     FIRST_X_ASSUM(fun ih ->
       if is_forall (concl ih) then
         MP_TAC(SPECL [`aa + bytes_in_word:(N)word`;
                       `set_sep_one (aa:(N)word,h:M) *
                        frame`;
                       `n':num`; `m:(N)word->M`;
                       `dm:(N)word->bool`] ih)
       else fail()) THEN
     ANTS_TAC THENL
      [REPEAT CONJ_TAC THENL
        [FIRST_ASSUM(fun a1 ->
           if has "SEP_T" a1
           then MP_TAC(REWRITE_RULE[GSYM STAR_ASSOC; STAR_SEP_T] a1)
           else fail()) THEN
         REWRITE_TAC[STAR_SEP_T] THEN
         DISCH_THEN(X_CHOOSE_THEN `u:((N)word # M)->bool`
           (CONJUNCTS_THEN2 ASSUME_TAC
             (fun st -> MP_TAC(REWRITE_RULE[one_STAR] st)))) THEN
         DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ASSUME_TAC) THEN
         EXISTS_TAC
           `(u:((N)word # M)->bool) DELETE (aa,h)` THEN
         ASM_REWRITE_TAC[] THEN
         FIRST_X_ASSUM(fun th ->
           if has "SUBSET" th then MP_TAC th else fail()) THEN
         SET_TAC[];
         FIRST_ASSUM(fun a2 ->
           if has "word_list_exists" a2 then MP_TAC a2 else fail()) THEN
         REWRITE_TAC[STAR_AC];
         FIRST_X_ASSUM(fun th ->
           if has "LENGTH" th then MP_TAC th else fail()) THEN
         REWRITE_TAC[LENGTH] THEN ARITH_TAC];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> MP_TAC th) THEN
     REWRITE_TAC[STAR_AC]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Cons_alt = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm (ZIP vals ws ++ vars) /\
      LENGTH vals = LENGTH (ws:('a word_loc) list) /\ ~(vals = [])
        /\
      encode_header c (4 * tag) (LENGTH ws) = SOME hd /\
      LENGTH ws < sp /\ good_dimindex (:'a) ==>
      (?free' (curr:'a word) m1.
        FLOOKUP st NextFree = SOME (wordLang_Word free') /\
        FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
        ((misc_word_list free' (wordLang_Word hd :: ws) * SEP_T)
          (fun2set (m,dm)) ==>
         memory_rel c be (ts + 1) refs (sp - (LENGTH ws + 1))
           (st |+ (NextFree,wordLang_Word (free' + bytes_in_word *
             n2w (LENGTH ws + 1)))) m dm
           ((Block ts tag vals,make_cons_ptr c (free' - curr) tag
             (LENGTH ws)) :: vars)))`),
(* the same allocation as memory_rel_Cons1, of which this is the
   statement for a memory that holds the words of the element
   already: so the proof is that one with
   word_list_AND_word_list_exists_IMP in place of store_list_thm --
   the words of the space that the element takes are the words the
   hypothesis says are there, and what is left of the space is
   empty (word_list_exists at zero is emp) *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let front sp cell =
    let pred = rator (concl sp) in
    let fs = facs pred in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk x y = mk_comb(mk_comb(st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target),
              REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
    REWRITE_RULE[eq] sp in
  (* an ALL2 over two appends of matching lengths *)
  let all2app = prove
   (`!(P:A->B->bool) xs1 ys1 xs2 ys2.
       LENGTH xs1 = LENGTH ys1
       ==> (ALL2 P (xs1 ++ xs2) (ys1 ++ ys2) <=>
            ALL2 P xs1 ys1 /\ ALL2 P xs2 ys2)`,
    GEN_TAC THEN LIST_INDUCT_TAC THENL
     [X_GEN_TAC `ys1:(B)list` THEN
      STRUCT_CASES_TAC (ISPEC `ys1:(B)list` list_CASES) THEN
      REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC;
                  ARITH_RULE `~(0 = SUC n)`];
      X_GEN_TAC `ys1:(B)list` THEN
      STRUCT_CASES_TAC (ISPEC `ys1:(B)list` list_CASES) THEN
      REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC;
                  ARITH_RULE `~(SUC n = 0)`; SUC_INJ] THEN
      REPEAT GEN_TAC THEN DISCH_TAC THEN
      ASM_SIMP_TAC[] THEN CONV_TAC TAUT]) in
  (* two steps of an address in one *)
  let addsum = prove
   (`!(a:'a word) x y.
       a + bytes_in_word * n2w x + bytes_in_word * n2w y =
       a + bytes_in_word * n2w (x + y)`,
    REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE) in
  (* the shift of two that the tag of a block is encoded with *)
  let shl2 = prove
   (`!t. ((n2w t):(N)word) << 2 = n2w (4 * t)`,
    GEN_TAC THEN REWRITE_TAC[word_shl; VAL_WORD] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[WORD_EQ; CONG] THEN CONV_TAC MOD_DOWN_CONV THEN
    REWRITE_TAC[MULT_AC]) in
  let someif = prove
   (`!p (x:A) y. (if p then SOME x else NONE) = SOME y ==> x = y`,
    REPEAT GEN_TAC THEN COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"]) in
  (* the numeric facts that the assumptions give *)
  let numfacts asl =
    mapfilter (fun (_,th) ->
      let c = concl th in
      if (try hd_is "<=" c || hd_is "<" c ||
              (is_eq c && hd_is "LENGTH" (lhs c) &&
               hd_is "LENGTH" (rhs c))
          with Failure _ -> false) then th else fail()) asl in
  let addreq asl t1 t2 =
      let fs = numfacts asl in
      let extra = (try
        let lt = grab asl (fun th ->
          try hd_is "<" (concl th) &&
              hd_is "LENGTH" (lhand (concl th))
          with Failure _ -> false) in
        let spe = grab asl (fun th ->
          try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
              is_var (rand (concl th))
          with Failure _ -> false) in
        [MATCH_MP (ARITH_RULE
           `!a b c:num. a < b /\ b <= c ==> a + 1 <= c`)
           (CONJ lt spe)]
        with Failure _ -> []) in
      let cnd = end_itlist CONJ (fs @ extra) in
      MP (prove (mk_imp (concl cnd, mk_eq (t1,t2)),
            DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
              (fun th -> ASSUME_TAC
                 (REWRITE_RULE[LENGTH; ADD1] th))) THEN
            ASM_REWRITE_TAC[BlockRep_def; el_length_def;
                            LENGTH; ADD1] THEN
            REWRITE_TAC[WORD_SUB; WORD_ADD] THEN
            ASM_SIMP_TAC[ARITH_RULE
              `!l s h:num. l <= s ==> l <= h + s`;
              ARITH_RULE
              `!a b c:num. a <= b /\ b <= c ==> a <= c`] THEN
            CONV_TAC WORD_RULE)) cnd in
  let wordeq =
    W(fun (asl,gl) ->
      REWRITE_TAC[addreq asl (rand (rand (lhs gl)))
                    (rand (rand (rhs gl)))]) in
  (* a store that says the same of a key, with the numbers of the
     new element in place of the old ones *)
  let numeq =
    W(fun (asl,gl) ->
      let fl = grab asl (fun th ->
        try hd_is "FLOOKUP" (lhs (concl th)) &&
            rand (lhs (concl th)) = rand (lhs gl) &&
            not (concl th = gl)
        with Failure _ -> false) in
      let isn t = (try hd_is "word" t &&
                       type_of (rand t) = `:num` &&
                       not (is_numeral (rand t))
                   with Failure _ -> false) in
      let ge = find_term isn (rhs gl) in
      let fe = find_term isn (rhs (concl fl)) in
      let fs = numfacts asl in
      let cnd = end_itlist CONJ fs in
      let eq = MP (prove (mk_imp (concl cnd,
                    mk_eq (rand ge, rand fe)),
                  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
                    ASSUME_TAC) THEN
                  REWRITE_TAC[BlockRep_def; el_length_def;
                              LENGTH; ADD1] THEN
                  ASM_ARITH_TAC)) cnd in
      REWRITE_TAC[eq] THEN FIRST_ASSUM ACCEPT_TAC) in
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* what the invariant says of the stack *)
  FIRST_ASSUM (fun mr ->
    if hd_is "memory_rel" (concl mr)
    then MP_TAC (REWRITE_RULE[memory_rel_def; word_ml_inv_def] mr)
    else fail()) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the values and the words that the ZIP of the stack holds *)
  W(fun (asl,gl) ->
    let le = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    RULE_ASSUM_TRY (REWRITE_RULE[MAP_APPEND;
      MATCH_MP MAP_FST_ZIP le; MATCH_MP MAP_SND_ZIP le])) THEN
  (* the block that the cons makes of the values *)
  W(fun (asl,gl) ->
    let ai = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
    let ne = grab asl (fun th ->
      try hd_is "NIL" (rhs (dest_neg (concl th)))
      with Failure _ -> false) in
    let lt = grab asl (fun th ->
      try hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false) in
    let le = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    let spe = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          lhand (concl th) = rand (concl lt)
      with Failure _ -> false) in
    let bnd = MATCH_MP (ARITH_RULE
                `!a b c d:num. a = b /\ b < c /\ c <= d
                               ==> a < d`)
                (CONJ le (CONJ lt spe)) in
    let tg = el 2 (snd(strip_comb (find_term
               (hd_is "make_cons_ptr") gl))) in
    MP_TAC (SPEC tg (MATCH_MP (GEN_ALL cons_thm_alt)
      (CONJ ai (CONJ bnd ne))))) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the ends of the heap that the store holds *)
  FIRST_ASSUM (fun hs ->
    if hd_is "heap_in_memory_store" (concl hs)
    then STRIP_ASSUME_TAC
           (REWRITE_RULE[heap_in_memory_store_def] hs)
    else fail()) THEN
  (* the unused space of the heap, where the element goes *)
  FIRST_ASSUM (fun hu ->
    if not (try hd_is "heap_store_unused_alt" (lhs (concl hu))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_unused_alt_def] hu)) THEN
  COND_CASES_TAC THEN REWRITE_TAC[PAIR_EQ] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  FIRST_X_ASSUM (fun cnd ->
    if not (is_conj (concl cnd)) then fail() else
    if not (try hd_is "heap_lookup" (lhs (lhand (concl cnd)))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC cnd) THEN
  (* so the heap splits there *)
  FIRST_ASSUM (fun hl ->
    if not (try hd_is "heap_lookup" (lhs (concl hl))
            with Failure _ -> false) then fail() else
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT hl)) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                (hd_is "APPEND" (rhs (concl e)) ||
                 hd_is "heap_length" (rhs (concl e)))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  (* and the store writes the element at the end of the space *)
  FIRST_ASSUM (fun hs ->
    if not (try hd_is "heap_store" (lhs (concl hs))
            with Failure _ -> false) then fail() else
    MP_TAC (REWRITE_RULE[heap_store_lemma; PAIR_EQ] hs)) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the words of the unused space, and its end where the element
     goes *)
  W(fun (asl,gl) ->
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "el_length" (lhand (concl th))
      with Failure _ -> false) in
    let e1 = REWRITE_RULE[BlockRep_def; el_length_def] bnd in
    let eq1 = MATCH_MP (ARITH_RULE
                `!k s:num. k + 1 <= s ==> (s - 1) + 1 = s`) e1 in
    let eq3 = MATCH_MP (ARITH_RULE
                `!k s:num. k + 1 <= s
                           ==> (k + 1) + (s - (k + 1)) = s`) e1 in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th))
      with Failure _ -> false) in
    let sep1 = REWRITE_RULE[word_heap_APPEND; word_heap_def;
                 word_el_def; el_length_def; eq1] sep in
    let addr = el 0 (snd(strip_comb (find (fun t ->
                 hd_is "word_list_exists" t)
                 (facs (rator (concl sep1)))))) in
    let wle = REWRITE_RULE[eq3]
                (ISPECL [lhand (lhs (concl eq3));
                         rand (lhs (concl eq3)); addr]
                   word_list_exists_ADD) in
    let sep2 = REWRITE_RULE[wle; STAR_ASSOC] sep1 in
    ASSUME_TAC sep2) THEN
  (* the words of the element are as many as its roots, and its
     address is the end of the heap less them *)
  W(fun (asl,gl) ->
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          length (filter (hd_is "word_list_exists")
                   (facs (rator (concl th)))) = 2
      with Failure _ -> false) in
    let bnd = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "el_length" (lhand (concl th))
      with Failure _ -> false) in
    let e1 = REWRITE_RULE[BlockRep_def; el_length_def] bnd in
    let rsl = rand (lhand (lhand (concl e1))) in
    let l1 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) =
            mk_icomb (`LENGTH`,rsl)
      with Failure _ -> false) in
    let l2 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) = rhs (concl l1) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    let rw = TRANS l1 l2 in
    let xs = el 1 (snd(strip_comb (find_term
               (fun t -> hd_is "misc_word_list" t &&
                         hd_is "CONS"
                           (el 1 (snd(strip_comb t)))) gl))) in
    let lenq = prove (mk_eq (mk_binop `(+):num->num->num`
                  (rhs (concl rw)) `1`, mk_icomb (`LENGTH`,xs)),
                REWRITE_TAC[LENGTH] THEN ARITH_TAC) in
    let sep4 = REWRITE_RULE[lenq] (REWRITE_RULE[rw] sep) in
    let bnd2 = REWRITE_RULE[lenq] (REWRITE_RULE[rw] e1) in
    ASSUME_TAC sep4 THEN ASSUME_TAC bnd2 THEN
    REWRITE_TAC[lenq]) THEN
  (* the two ends of the heap that the store holds *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "NextFree"))));
       rand (rand (rhs (concl (flk "CurrHeap"))))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the words that the memory holds at that address already *)
  DISCH_THEN (fun hyp ->
    W(fun (asl,gl) ->
      let iscell t = hd_is "word_list_exists" t &&
                     hd_is "LENGTH" (el 1 (snd(strip_comb t))) in
      let sep = grab asl (fun th ->
        try hd_is "STAR" (rator (concl th)) &&
            exists iscell (facs (rator (concl th)))
        with Failure _ -> false) in
      let cell = find iscell (facs (rator (concl sep))) in
      let n = el 1 (snd(strip_comb cell)) in
      let le = ARITH_RULE (mk_binop `(<=):num->num->bool` n n) in
      ASSUME_TAC (REWRITE_RULE[SUB_REFL;
        CONJUNCT1 word_list_exists_thm; emp_STAR; STAR_emp]
        (MATCH_MP word_list_AND_word_list_exists_IMP
          (CONJ hyp (CONJ (front sep cell) le)))))) THEN
  (* the roots of the element and the roots of the stack *)
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                hd_is "APPEND" (rhs (concl e))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      hd_is "ALL2" (concl th) &&
      hd_is "APPEND" (el 1 (snd(strip_comb (concl th))))) in
    let rsl = lhand (el 1 (snd(strip_comb (concl a2)))) in
    let l1 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) =
            mk_icomb (`LENGTH`,rsl)
      with Failure _ -> false) in
    let l2 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) = rhs (concl l1) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    STRIP_ASSUME_TAC
      (REWRITE_RULE[MATCH_MP all2app (TRANS l1 l2)] a2)) THEN

  (* the invariant with the new element in the heap *)
  REWRITE_TAC[memory_rel_def] THEN
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "CONS" (el 1 (snd(strip_comb (concl th)))) &&
           hd_is "dataSem_Block"
             (lhand (el 1 (snd(strip_comb (concl th)))))
       with Failure _ -> false)) in
    let args = snd(strip_comb (concl ai)) in
    let ps = tparts (el 3 args) in
    MAP_EVERY EXISTS_TAC
      [el 1 ps; el 4 args; el 3 ps; el 4 ps; el 5 ps; el 6 ps]) THEN
  REPEAT CONJ_TAC THENL
   [ALL_TAC;
    (* the roots: the pointer of the new reference and the rest *)
    REWRITE_TAC[word_ml_inv_def] THEN
    W(fun (asl,gl) ->
      let ai = grab asl (fun th ->
        hd_is "abs_ml_inv" (concl th) &&
        (try hd_is "CONS" (el 1 (snd(strip_comb (concl th)))) &&
             hd_is "dataSem_Block"
               (lhand (el 1 (snd(strip_comb (concl th)))))
         with Failure _ -> false)) in
      EXISTS_TAC
        (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
    REWRITE_TAC[MAP; FST; SND; ALL2] THEN
    CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    (* the word of the pointer is the one make_ptr builds *)
    W(fun (asl,gl) ->
      let mp = rhs gl in
      let sub = el 1 (snd(strip_comb mp)) in
      let aterm = lhand sub in
      let bwterm = rand aterm in
      let pt = lhand (rand (lhs gl)) in
      let mulp = mk_comb (rator bwterm,
                   mk_comb (rator (rand bwterm), pt)) in
      SUBST1_TAC (addreq asl sub mulp)) THEN
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      REWRITE_TAC(word_addr_clauses ()) THEN
      REWRITE_TAC[make_cons_ptr_def; get_addr_def] THEN
      REWRITE_TAC[MATCH_MP bytes_in_word_mul_eq_shift gd;
                  WORD_SHL_COMPOSE] THEN
      ASM_SIMP_TAC[ARITH_RULE
        `!a b:num. a <= b ==> a + (b - a) = b`] THEN
      AP_TERM_TAC THEN
      GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV)
        [get_lowerbits_or_1] THEN
      WORD_BITWISE_TAC);
    FIRST_ASSUM ACCEPT_TAC;
    W(fun (asl,gl) ->
      let spe = grab asl (fun th ->
        try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
            is_var (rand (concl th))
        with Failure _ -> false) in
      let les = mapfilter (fun (_,th) ->
        if (try is_eq (concl th) &&
                hd_is "LENGTH" (lhs (concl th)) &&
                hd_is "LENGTH" (rhs (concl th))
            with Failure _ -> false) then th else fail()) asl in
      MP_TAC (end_itlist CONJ (spe :: les))) THEN
    REWRITE_TAC[BlockRep_def; el_length_def; LENGTH; ADD1] THEN
    ARITH_TAC] THEN
  (* the store of the new heap: its length is the old one *)
  REWRITE_TAC[heap_in_memory_store_def] THEN
  W(fun (asl,gl) ->
    let hu = grab asl (fun th ->
      try hd_is "heap_store_unused_alt" (lhs (concl th))
      with Failure _ -> false) in
    REWRITE_TAC[MATCH_MP heap_store_unused_alt_IMP_length hu]) THEN
  W(fun (asl,gl) ->
    let dis = CONJUNCTS (distinctness "store_name") in
    REWRITE_TAC([FLOOKUP_UPDATE; FDOM_FUPDATE; IN_INSERT] @
                dis @ map GSYM dis)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the two heaps of the store *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "CurrHeap"))));
       rand (rand (rhs (concl (flk "OtherHeap"))))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (wordeq THEN NO_TAC) THEN
  TRY (numeq THEN NO_TAC) THEN
  (* the heap with the new element, which the store wrote *)
  FIRST_ASSUM (fun h2 ->
    if not (try is_eq (concl h2) && hd_is "APPEND" (lhs (concl h2)) &&
                is_var (rhs (concl h2))
            with Failure _ -> false) then fail() else
    SUBST1_TAC (SYM h2)) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_heap_expand;
              word_heap_def; heap_length_APPEND;
              heap_length_heap_expand; BlockRep_def] THEN
  REWRITE_TAC[word_el_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; LENGTH_MAP; el_length_def;
              heap_length_NIL; STAR_ASSOC; emp_STAR; STAR_emp] THEN
  (* the words of the element are the roots of the values, and its
     header is the one that encode_header gave *)
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      try hd_is "ALL2" (concl th) &&
          not (hd_is "MAP" (el 2 (snd(strip_comb (concl th)))))
      with Failure _ -> false) in
    let a2args = snd(strip_comb (concl a2)) in
    let fterm = rator (lhs (snd(strip_abs (el 0 a2args)))) in
    let mapeq = EQ_MP (ISPECL [el 1 a2args; el 2 a2args; fterm]
                  EVERY2_f_EQ) a2 in
    let eh = grab asl (fun th ->
      try hd_is "encode_header" (lhs (concl th))
      with Failure _ -> false) in
    let mh = CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
               (REWRITE_RULE[encode_header_def] eh)) in
    let les = mapfilter (fun (_,th) ->
      if (try is_eq (concl th) &&
              hd_is "LENGTH" (lhs (concl th)) &&
              hd_is "LENGTH" (rhs (concl th))
          with Failure _ -> false) then th else fail()) asl in
    REWRITE_TAC(shl2 :: mapeq :: mh :: les)) THEN
  (* the condition of the payload, which the header's length says *)
  W(fun (asl,gl) ->
    let pred = rator gl in
    let fs = facs pred in
    let cell = find (hd_is "cond") fs in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk a b = mk_comb(mk_comb(st,a),b) in
    SUBGOAL_THEN (mk_eq (pred, mk cell (end_itlist mk rest)))
      SUBST1_TAC THENL
     [REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]; ALL_TAC]) THEN
  REWRITE_TAC[cond_STAR] THEN
  CONJ_TAC THENL
   [W(fun (asl,gl) ->
      let eh = grab asl (fun th ->
        try hd_is "encode_header" (lhs (concl th))
        with Failure _ -> false) in
      let ls7 = grab asl (fun th ->
        try hd_is "<" (concl th) &&
            hd_is "+" (lhand (concl th)) &&
            hd_is "data_to_word_config_len_size"
              (lhand (lhand (concl th)))
        with Failure _ -> false) in
      let ls = MATCH_MP (ARITH_RULE
                 `!a b:num. a + 7 < b ==> a + 5 < b`) ls7 in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      STRIP_ASSUME_TAC (MATCH_MP encode_header_IMP
        (CONJ eh (CONJ ls gd)))) THEN
    W(fun (asl,gl) ->
      let eh = grab asl (fun th ->
        try hd_is "encode_header" (lhs (concl th))
        with Failure _ -> false) in
      let mh = CONV_RULE NUM_REDUCE_CONV (MATCH_MP someif
                 (REWRITE_RULE[encode_header_def] eh)) in
      REWRITE_TAC[shl2; ARITH_RULE `!t:num. t * 4 = 4 * t`;
                  mh]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* and the words at the address the store wrote them to *)
  W(fun (asl,gl) ->
    let iscell t = hd_is "misc_word_list" t &&
                   hd_is "CONS" (el 1 (snd(strip_comb t))) in
    let sl = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let bnd = REWRITE_RULE[LENGTH; ADD1] (grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "LENGTH" (lhand (concl th))
      with Failure _ -> false)) in
    let arith = MATCH_MP (ARITH_RULE
                  `!l s:num. l <= s ==> l + (s - l) = s`) bnd in
    let sl2 = REWRITE_RULE[LENGTH; ADD1; word_list_def;
                word_heap_heap_expand; STAR_ASSOC; emp_STAR;
                STAR_emp; addsum] sl in
    REWRITE_TAC[heap_length_CONS; heap_length_NIL; el_length_def;
                ARITH_RULE `!n:num. n + 0 = n`; addsum;
                arith] THEN
    W(fun (asl2,gl2) ->
      let eq = prove (mk_eq (rator gl2, rator (concl sl2)),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      ACCEPT_TAC (REWRITE_RULE[GSYM eq] sl2))))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_REPLICATE = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((v,w) :: vars) ==>
      memory_rel c be ts refs sp st m dm (REPLICATE n (v,w) ++
        vars)`),
  (MATCH_MP_TAC memory_rel_rearrange THEN
   GEN_TAC THEN REWRITE_TAC[MEM_APPEND; MEM_REPLICATE; MEM] THEN
   CONV_TAC TAUT));;

(* HOL4 data_to_word_memoryProofScript.sml:10078-10084: a theorem
   that HOL4 states as the value of an ML expression:
   memory_rel_RefArray *)

let word_of_byte_def = cake_define
  `word_of_byte (w:'a word) =
     (let w = (w << 8 || w) in
     let w = (w << 16 || w) in
       if dimindex (:'a) = 32 then w else w << 32 || w)`;;

(* HOL4 data_to_word_memoryProofScript.sml:10093-10096: a theorem
   that HOL4 states as the value of an ML expression: ADD_DIV_EQ *)

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let set_byte_word_of_byte = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) ==>
       set_byte a w (word_of_byte ((w2w w):'a word)) be =
         word_of_byte (w2w w)`),
  (* every set_byte of the word that repeats a byte writes the byte
     it already has there: the byte index is a multiple of eight, so
     the position inside the byte is the position modulo eight, and
     that is the bit of the byte that word_of_byte put there *)
  (let bsb0 = prove
    (`!(a:(N)word) b (h:(N)word) bb j. j < dimindex (:N)
        ==> (bit j (set_byte a b h bb) <=>
             (if byte_index a bb <= j /\ j < byte_index a bb + 8
              then bit (j - byte_index a bb) b else bit j h))`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[set_byte_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_SIMP_TAC[BIT_WORD_OR; BIT_WORD_SLICE_ALT_LT; BIT_WORD_SHL;
                  BIT_WORD_ZX; DIMINDEX_8] THEN
     MP_TAC(REWRITE_RULE[DIMINDEX_8]
       (ISPECL [`b:(8)word`; `j - byte_index (a:(N)word) bb`]
          BIT_TRIVIAL)) THEN
     ASM_CASES_TAC `byte_index (a:(N)word) bb <= j` THEN
     ASM_CASES_TAC `j < byte_index (a:(N)word) bb + 8` THEN
     ASM_CASES_TAC `bit j (h:(N)word)` THEN
     ASM_CASES_TAC
       `bit (j - byte_index (a:(N)word) bb) (b:(8)word)` THEN
     ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC) in
   let modgen = prove
    (`!i k. 8 * k <= i /\ i < 8 * k + 8 ==> i MOD 8 = i - 8 * k`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     SUBGOAL_THEN `(8 * k + (i - 8 * k)) MOD 8 = i - 8 * k` MP_TAC THENL
      [ONCE_REWRITE_TAC[ARITH_RULE `8 * k + r = k * 8 + r`] THEN
       REWRITE_TAC[MOD_MULT_ADD] THEN
       MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
       ASM_SIMP_TAC[ARITH_RULE
         `8 * k <= i ==> 8 * k + (i - 8 * k) = i`]]) in
   let modfacts =
     map (fun k -> REWRITE_RULE[LE_0; SUB_0]
       (CONV_RULE NUM_REDUCE_CONV
         (SPECL [`i:num`; mk_small_numeral k] modgen)))
       [0; 1; 2; 3; 4; 5; 6; 7] in
   let bix8 = prove
    (`!(a:'a word) bb. ?k. byte_index a bb = 8 * k /\
                           (0 < dimindex (:'a) DIV 8
                            ==> k < dimindex (:'a) DIV 8)`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[byte_index_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     COND_CASES_TAC THENL
      [EXISTS_TAC `(dimindex (:'a) DIV 8 - 1) -
                   w2n (a:'a word) MOD (dimindex (:'a) DIV 8)`;
       EXISTS_TAC `w2n (a:'a word) MOD (dimindex (:'a) DIV 8)`] THEN
     REWRITE_TAC[] THEN DISCH_TAC THEN
     ASM_SIMP_TAC[DIVISION] THEN ASM_ARITH_TAC) in
   let rules =
     let num k = mk_small_numeral k in
     let le a b = mk_binop `(<=):num->num->bool` a b in
     let lt a b = mk_binop `(<):num->num->bool` a b in
     let iv = `i:num` in
     let ks = [8; 16; 24; 32; 40; 48; 56; 64] in
     itlist (fun k acc -> itlist (fun k2 acc ->
       (if k <= k2
        then [ARITH_RULE(mk_imp(le (num k2) iv, le (num k) iv));
              ARITH_RULE(mk_imp(lt iv (num k), lt iv (num k2)))]
        else []) @
       (if k2 <= k
        then [ARITH_RULE(mk_imp(lt iv (num k2), mk_neg(le (num k) iv)));
              ARITH_RULE(mk_imp(le (num k) iv, mk_neg(lt iv (num k2))))]
        else []) @ acc) ks acc) ks
       [ARITH_RULE `i < 64 ==> (i - m < 64 <=> T)`;
        ARITH_RULE `i < 32 ==> (i - m < 32 <=> T)`;
        ARITH_RULE `(8 <= i - 8 <=> 16 <= i) /\
                    (8 <= i - 16 <=> 24 <= i) /\
                    (8 <= i - 24 <=> 32 <= i) /\
                    (8 <= i - 32 <=> 40 <= i) /\
                    (8 <= i - 40 <=> 48 <= i) /\
                    (8 <= i - 48 <=> 56 <= i) /\
                    (16 <= i - 32 <=> 48 <= i)`] in
   let killbit tm =
     TRY(MP_TAC(REWRITE_RULE[DIMINDEX_8]
           (ISPECL [`w:(8)word`; tm] BIT_TRIVIAL)) THEN
         (ANTS_TAC THENL
           [ASM_ARITH_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])])) in
   let wobbit = prove
    (`!i. good_dimindex (:'a) /\ i < dimindex (:'a)
          ==> (bit i (word_of_byte ((w2w (w:(8)word)):'a word)) <=>
               bit (i MOD 8) w)`,
     GEN_TAC THEN STRIP_TAC THEN
     FIRST_ASSUM(DISJ_CASES_THEN ASSUME_TAC o
       REWRITE_RULE[good_dimindex_def]) THEN
     REWRITE_TAC[word_of_byte_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
     REWRITE_TAC[BIT_WORD_OR; BIT_WORD_SHL; BIT_WORD_ZX;
                 DIMINDEX_8] THEN
     REWRITE_TAC[ARITH_RULE
       `(((i - 32) - 16) - 8 = i - 56) /\ ((i - 32) - 16 = i - 48) /\
        ((i - 32) - 8 = i - 40) /\ ((i - 16) - 8 = i - 24)`] THEN
     (SUBGOAL_THEN
        `(i:num) < 8 \/ (8 <= i /\ i < 16) \/ (16 <= i /\ i < 24) \/
         (24 <= i /\ i < 32) \/ (32 <= i /\ i < 40) \/
         (40 <= i /\ i < 48) \/ (48 <= i /\ i < 56) \/
         (56 <= i /\ i < 64)`
        MP_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
     STRIP_TAC THEN
     killbit `i:num` THEN killbit `i - 8` THEN killbit `i - 16` THEN
     killbit `i - 24` THEN killbit `i - 32` THEN killbit `i - 40` THEN
     killbit `i - 48` THEN
     ASM_SIMP_TAC (modfacts @ rules) THEN
     TRY(SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC)) in
   let stripconj =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) in
   DISCH_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
   X_GEN_TAC `i:num` THEN DISCH_TAC THEN
   ASM_SIMP_TAC[bsb0; wobbit] THEN
   W(fun (asl,w) ->
     let bidx = find_term (fun t ->
       (try fst(dest_const(fst(strip_comb t))) = "byte_index"
        with Failure _ -> false)) w in
     MP_TAC(ISPECL (snd(strip_comb bidx)) bix8)) THEN
   DISCH_THEN(X_CHOOSE_THEN `k:num` STRIP_ASSUME_TAC) THEN
   ASM_REWRITE_TAC[] THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   stripconj THEN
   FIRST_ASSUM(fun th1 -> FIRST_ASSUM(fun th2 ->
     MP_TAC(MATCH_MP modgen (CONJ th1 th2)) THEN
     DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[]))));;

let w2w_word_of_byte_w2w = prove
 (`good_dimindex (:'a) ==>
   (w2w (word_of_byte (w2w w:'a word)):word8) = w`,
  (* the word of a byte repeats the byte, and the low eight bits of
     it are the byte itself: the shifts of the definition are by
     eight, sixteen and thirty-two, which no bit below eight is
     above *)
  (DISCH_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; DIMINDEX_8] THEN
   X_GEN_TAC `i:num` THEN DISCH_TAC THEN
   REWRITE_TAC[word_of_byte_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   FIRST_ASSUM(DISJ_CASES_THEN (fun th -> ASSUME_TAC th) o
     REWRITE_RULE[good_dimindex_def]) THEN
   ASM_REWRITE_TAC[ARITH_EQ] THEN
   ASM_REWRITE_TAC[BIT_WORD_ZX; BIT_WORD_OR; BIT_WORD_SHL;
                   DIMINDEX_8] THEN
   ASM_SIMP_TAC[ARITH_RULE `i < 8 ==> ~(8 <= i)`;
                ARITH_RULE `i < 8 ==> ~(16 <= i)`;
                ARITH_RULE `i < 8 ==> ~(32 <= i)`;
                ARITH_RULE `i < 8 ==> i < 32`;
                ARITH_RULE `i < 8 ==> i < 64`]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let write_bytes_REPLICATE = prove
 (cake_as_vars (fun () ->
    `!n m.
         good_dimindex (:'a) ==>
         write_bytes (REPLICATE m w) (REPLICATE n (word_of_byte
           (w2w w))) be =
         REPLICATE n (word_of_byte ((w2w w):'a word))`),
  (* the words are written one by one, and writing the bytes of a
     word of one byte over and over leaves it as it is, which
     set_byte_word_of_byte says of each byte.  The flag of the
     endianness is called b2 in the two lemmas, because be is the
     field of the configuration and not a variable *)
  (let drop0 = prove
    (`!l:A list. DROP 0 l = l`,
     LIST_INDUCT_TAC THEN REWRITE_TAC[DROP]) in
   let drop_rep = prove
    (`!k m (x:A). DROP k (REPLICATE m x) = REPLICATE (m - k) x`,
     INDUCT_TAC THENL
      [REWRITE_TAC[drop0; SUB_0];
       REPEAT GEN_TAC THEN
       STRUCT_CASES_TAC(ISPEC `m:num` num_CASES) THEN
       ASM_REWRITE_TAC[REPLICATE; DROP; NOT_SUC; SUC_SUB1; SUB_0;
                       SUB_SUC; ARITH_RULE `0 - SUC k = 0`]]) in
   let head = prove
    (`good_dimindex (:'a) ==>
      !k a m b2.
        bytes_to_word k (a:'a word) (REPLICATE m (w:(8)word))
          (word_of_byte ((w2w w):'a word)) b2 =
        word_of_byte ((w2w w):'a word)`,
     DISCH_TAC THEN INDUCT_TAC THENL
      [ONCE_REWRITE_TAC[bytes_to_word_def] THEN
       REWRITE_TAC[];
       REPEAT GEN_TAC THEN
       ONCE_REWRITE_TAC[bytes_to_word_def] THEN
       REWRITE_TAC[NOT_SUC; SUC_SUB1] THEN
       STRUCT_CASES_TAC(ISPEC `m:num` num_CASES) THEN
       REWRITE_TAC[REPLICATE] THEN MATCH_REDUCE_TAC THEN
       ASM_REWRITE_TAC[] THEN
       ASM_SIMP_TAC[set_byte_word_of_byte]]) in
   INDUCT_TAC THENL
    [REWRITE_TAC[REPLICATE; write_bytes_def];
     GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[REPLICATE] THEN
     ONCE_REWRITE_TAC[write_bytes_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_SIMP_TAC[head; drop_rep] THEN
     FIRST_ASSUM(fun th ->
       ASM_SIMP_TAC[SPEC `m - dimindex (:'a) DIV 8` th])]));;

let IMP_EXP_LESS = prove
 (`m <= l ==> 2 EXP m <= 2 EXP l`,
  (REWRITE_TAC[LE_EXP; ARITH_EQ] THEN ARITH_TAC));;

(* [local] *)
let shift_shift_lemma = prove
 (`l = k + backend_common_word_shift (:'a) /\ t < k /\ n DIV i < 2 EXP t
  /\ l = dimindex (:'a) /\
     i = 2 EXP backend_common_word_shift (:'a) /\ n < dimword (:'a)
       ==>
     n2w n << (k - t) >>> (l - t) = ((n2w (n DIV i)):'a word)`,
  (* the shift up and down of a word that keeps t of its bits:
     the bit that the two shifts leave at j is the one of n at
     j plus the word shift, and above t there is none, because
     n divided by the word shift is below two to the t *)
  (let ARITH_NO_DIV_TAC =
     POP_ASSUM_LIST(fun l ->
       MAP_EVERY MP_TAC
         (filter (fun th ->
            not (can (find_term (fun t ->
              (try fst(dest_const(fst(strip_comb t))) = "DIV"
               with Failure _ -> false))) (concl th))) l)) THEN
     ARITH_TAC in
   STRIP_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
   X_GEN_TAC `j:num` THEN DISCH_TAC THEN
   REWRITE_TAC[BIT_WORD_USHR; BIT_WORD_SHL; BIT_WORD] THEN
   SUBGOAL_THEN
     `(j + (l - t)) - (k - t) =
      j + backend_common_word_shift (:'a)`
     SUBST1_TAC THENL [ARITH_NO_DIV_TAC; ALL_TAC] THEN
   SUBGOAL_THEN `(n DIV i) DIV 2 EXP j =
                 n DIV 2 EXP (j + backend_common_word_shift (:'a))`
     SUBST1_TAC THENL
    [ASM_REWRITE_TAC[DIV_DIV; GSYM EXP_ADD] THEN
     AP_TERM_TAC THEN AP_TERM_TAC THEN ARITH_TAC;
     ALL_TAC] THEN
   ASM_CASES_TAC `(j:num) < t` THENL
    [SUBGOAL_THEN
       `(k - t <= j + (l - t)) /\ (j + (l - t) < dimindex (:'a)) /\
        (j + backend_common_word_shift (:'a) < dimindex (:'a)) /\
        j < dimindex (:'a)`
       (fun th -> REWRITE_TAC[th]) THENL
      [ARITH_NO_DIV_TAC];
     SUBGOAL_THEN
       `n DIV 2 EXP (j + backend_common_word_shift (:'a)) = 0`
       SUBST1_TAC THENL
      [SUBGOAL_THEN
         `n DIV 2 EXP (j + backend_common_word_shift (:'a)) =
          (n DIV i) DIV 2 EXP j` SUBST1_TAC THENL
        [ASM_REWRITE_TAC[DIV_DIV; GSYM EXP_ADD] THEN
         AP_TERM_TAC THEN AP_TERM_TAC THEN ARITH_TAC;
         MATCH_MP_TAC DIV_LT THEN
         TRANS_TAC LTE_TRANS `2 EXP t` THEN
         ASM_REWRITE_TAC[LE_EXP] THEN
         CONV_TAC NUM_REDUCE_CONV THEN ARITH_NO_DIV_TAC];
       REWRITE_TAC[ODD]]]));;

let write_bytes_APPEND = prove
 (`!xs ys vals be'.
      write_bytes vals (xs ++ (ys:('a word) list)) be' =
      write_bytes vals xs be' ++
      write_bytes (DROP ((dimindex (:'a) DIV 8) * LENGTH xs) vals)
        ys be'`,
  (* induction on the first list of words: each word takes the
     bytes of its own length off the front, so the words of the
     second list see the bytes that the first list leaves *)
  (LIST_INDUCT_TAC THEN
   REWRITE_TAC[APPEND; write_bytes_def; LENGTH; MULT_CLAUSES;
               DROP_0] THEN
   REPEAT GEN_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_REWRITE_TAC[APPEND; DROP_DROP] THEN
   REWRITE_TAC[ARITH_RULE `(d * SUC n) = d + d * n`] THEN
   REWRITE_TAC[DROP_DROP; ADD_AC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let set_byte_sort = prove
 (cake_as_vars (fun () ->
    `!n1 n2.
        set_byte (n2w n1) b1 (set_byte (n2w n2:'a word) b2 w be) be
          =
        (if n1 = n2 then set_byte (n2w n1) b1 w be else
        if n1 < dimindex (:'a) DIV 8 /\ n2 < dimindex (:'a) DIV 8
          /\
           good_dimindex (:'a) /\ ~(n2 = n1) then
          set_byte (n2w n2) b2 (set_byte (n2w n1) b1 w be) be else
          set_byte (n2w n1) b1 (set_byte (n2w n2) b2 w be) be)`),
  (* two set_bytes of a word commute when they write different
     bytes of it: the byte index of a number below the number of
     bytes is eight times it (or eight times its mirror), so two
     such indices are different, and no bit is in both ranges; when
     the two are the same byte the outer write covers the inner *)
  (let bsb0 = prove
  (`!(a:(N)word) b (h:(N)word) bb j. j < dimindex (:N)
      ==> (bit j (set_byte a b h bb) <=>
           (if byte_index a bb <= j /\ j < byte_index a bb + 8
            then bit (j - byte_index a bb) b else bit j h))`,
   REPEAT GEN_TAC THEN DISCH_TAC THEN
   REWRITE_TAC[set_byte_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_SIMP_TAC[BIT_WORD_OR; BIT_WORD_SLICE_ALT_LT; BIT_WORD_SHL;
                BIT_WORD_ZX; DIMINDEX_8] THEN
   MP_TAC(REWRITE_RULE[DIMINDEX_8]
     (ISPECL [`b:(8)word`; `j - byte_index (a:(N)word) bb`]
        BIT_TRIVIAL)) THEN
   ASM_CASES_TAC `byte_index (a:(N)word) bb <= j` THEN
   ASM_CASES_TAC `j < byte_index (a:(N)word) bb + 8` THEN
   ASM_CASES_TAC `bit j (h:(N)word)` THEN
   ASM_CASES_TAC `bit (j - byte_index (a:(N)word) bb) (b:(8)word)` THEN
   ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC) in
 let bixval = prove
  (`!n bb. good_dimindex (:'a) /\ n < dimindex (:'a) DIV 8
      ==> byte_index ((n2w n):'a word) bb =
          8 * (if bb then (dimindex (:'a) DIV 8 - 1) - n else n)`,
   REPEAT GEN_TAC THEN
   REWRITE_TAC[good_dimindex_def; byte_index_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[VAL_WORD; dimword] THEN
   STRIP_TAC THEN
   FIRST_ASSUM(fun dd ->
     if (try fst(dest_const(fst(strip_comb(lhs(concl dd))))) =
              "dimindex" with Failure _ -> false)
     then REWRITE_TAC[dd] THEN RULE_ASSUM_TAC(REWRITE_RULE[dd]) THEN
          ASSUME_TAC dd
     else fail()) THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   RULE_ASSUM_TAC(fun th ->
     try CONV_RULE NUM_REDUCE_CONV th with Failure _ -> th) THEN
   (FIRST
     [(SUBGOAL_THEN `n MOD 4294967296 MOD 4 = n` SUBST1_TAC THENL
        [MP_TAC(SPECL [`n:num`; `4`; `1073741824`] MOD_MOD) THEN
         CONV_TAC NUM_REDUCE_CONV THEN
         DISCH_THEN SUBST1_TAC THEN
         MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
         ALL_TAC]);
      (SUBGOAL_THEN `n MOD 18446744073709551616 MOD 8 = n`
         SUBST1_TAC THENL
        [MP_TAC(SPECL [`n:num`; `8`; `2305843009213693952`]
           MOD_MOD) THEN
         CONV_TAC NUM_REDUCE_CONV THEN
         DISCH_THEN SUBST1_TAC THEN
         MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC;
         ALL_TAC])]) THEN
   COND_CASES_TAC THEN REWRITE_TAC[]) in
   let usebe =
     TRY(FIRST_ASSUM(fun th ->
       let c = concl th in
       if is_var c || (is_neg c && is_var (rand c))
       then RULE_ASSUM_TAC(REWRITE_RULE[th]) THEN ASSUME_TAC th
       else fail())) in
   let numred =
     RULE_ASSUM_TAC(fun th ->
       try CONV_RULE NUM_REDUCE_CONV th with Failure _ -> th) in
   let stripconj =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) in
   REPEAT GEN_TAC THEN
   COND_CASES_TAC THENL
    [ASM_REWRITE_TAC[] THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_SIMP_TAC[bsb0] THEN
     COND_CASES_TAC THEN REWRITE_TAC[];
     COND_CASES_TAC THENL
      [stripconj THEN
       REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
       X_GEN_TAC `i:num` THEN DISCH_TAC THEN
       ASM_SIMP_TAC[bsb0; bixval] THEN
       REPEAT COND_CASES_TAC THEN usebe THEN numred THEN
       ASM_REWRITE_TAC[] THEN
       TRY(SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC);
       REWRITE_TAC[]]]));;

(* HOL4 data_to_word_memoryProofScript.sml:10203-10213: ML code, not
   ported *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let set_byte_eq_ARB = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) ==>
      (!x h h'.
        (set_byte (n2w 0) x h be = set_byte (n2w 0) x (h':'a word)
          be <=>
         set_byte (n2w 0) ARB h be = set_byte (n2w 0) ARB h' be) /\
        (set_byte (n2w 1) x h be = set_byte (n2w 1) x (h':'a word)
          be <=>
         set_byte (n2w 1) ARB h be = set_byte (n2w 1) ARB h' be) /\
        (set_byte (n2w 2) x h be = set_byte (n2w 2) x (h':'a word)
          be <=>
         set_byte (n2w 2) ARB h be = set_byte (n2w 2) ARB h' be) /\
        (set_byte (n2w 3) x h be = set_byte (n2w 3) x (h':'a word)
          be <=>
         set_byte (n2w 3) ARB h be = set_byte (n2w 3) ARB h' be) /\
        (set_byte (n2w 4) x h be = set_byte (n2w 4) x (h':'a word)
          be <=>
         set_byte (n2w 4) ARB h be = set_byte (n2w 4) ARB h' be) /\
        (set_byte (n2w 5) x h be = set_byte (n2w 5) x (h':'a word)
          be <=>
         set_byte (n2w 5) ARB h be = set_byte (n2w 5) ARB h' be) /\
        (set_byte (n2w 6) x h be = set_byte (n2w 6) x (h':'a word)
          be <=>
         set_byte (n2w 6) ARB h be = set_byte (n2w 6) ARB h' be) /\
        (set_byte (n2w 7) x h be = set_byte (n2w 7) x (h':'a word)
          be <=>
         set_byte (n2w 7) ARB h be = set_byte (n2w 7) ARB h' be))`),
  (* the bit of a set_byte is the byte's bit inside the byte and the
     word's outside it, so two set_bytes of the same byte agree
     exactly when the two words agree outside it -- which does not
     depend on what the byte is *)
  (let bsb = prove
    (`!a b (h:(N)word) bb j.
        byte_index a bb + 8 <= dimindex (:N) /\ j < dimindex (:N)
        ==> (bit j (set_byte a b h bb) <=>
             (if byte_index a bb <= j /\ j < byte_index a bb + 8
              then bit (j - byte_index a bb) b else bit j h))`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     REWRITE_TAC[set_byte_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_SIMP_TAC[BIT_WORD_OR; BIT_WORD_SLICE_ALT;
                  ARITH_RULE `0 <= (i:num)`;
                  BIT_WORD_SHL; BIT_WORD_ZX; DIMINDEX_8] THEN
     MP_TAC(REWRITE_RULE[DIMINDEX_8]
       (ISPECL [`b:(8)word`; `j - byte_index (a:(N)word) bb`]
          BIT_TRIVIAL)) THEN
     ASM_CASES_TAC `byte_index (a:(N)word) bb <= j` THEN
     ASM_CASES_TAC `j < byte_index (a:(N)word) bb + 8` THEN
     ASM_CASES_TAC `bit j (h:(N)word)` THEN
     ASM_CASES_TAC
       `bit (j - byte_index (a:(N)word) bb) (b:(8)word)` THEN
     ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC) in
   let bib = prove
    (`!(k:num) bb. good_dimindex (:'a)
        ==> byte_index ((n2w k):'a word) bb + 8 <= dimindex (:'a)`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[byte_index_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[good_dimindex_def] THEN
     DISCH_THEN(DISJ_CASES_THEN (fun th -> SUBST1_TAC th)) THEN
     CONV_TAC NUM_REDUCE_CONV THEN
     (MP_TAC(SPEC `w2n ((n2w k):'a word)`
        (MATCH_MP DIVISION (ARITH_RULE `~(4 = 0)`))) ORELSE
      MP_TAC(SPEC `w2n ((n2w k):'a word)`
        (MATCH_MP DIVISION (ARITH_RULE `~(8 = 0)`)))) THEN
     COND_CASES_TAC THEN ARITH_TAC) in
   DISCH_TAC THEN REPEAT GEN_TAC THEN REPEAT CONJ_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
   ASM_SIMP_TAC[bsb; bib; COND_SAME_IFF]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let bytes_to_word_eq_lemma = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) /\ LENGTH bs' = LENGTH bs /\
      bytes_to_word (dimindex (:'a) DIV 8) (n2w 0) bs (h:'a word)
        be =
      bytes_to_word (dimindex (:'a) DIV 8) (n2w 0) bs h' be ==>
      bytes_to_word (dimindex (:'a) DIV 8) (n2w 0) bs' h be =
      bytes_to_word (dimindex (:'a) DIV 8) (n2w 0) bs' h' be`),
(* the bytes of a list written into a word leave the bits of the
   word that no byte of the list covers, and cover the others with
   the bytes: so whether two words that the same list was written
   into are equal depends on the bits that no byte covers, which
   is where the two words have to agree, and not on the bytes
   themselves -- the key lemma says it of one bit at a time
   (WORD_EQ_BITS_ALT, and set_byte_eq_ARB's own step that the bit
   of a set_byte is the byte's inside the byte and the word's
   outside it), by the induction on the number of words that
   bytes_to_word takes, where a list of as many bytes splits the
   same way (LENGTH_EQ_NIL, LENGTH_EQ_CONS) *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  (* the bit of a set_byte is the byte's bit inside the byte and
     the word's outside it (set_byte_eq_ARB) *)
  let bsb = prove
   (`!a b (h:(N)word) bb j.
       byte_index a bb + 8 <= dimindex (:N) /\ j < dimindex (:N)
       ==> (bit j (set_byte a b h bb) <=>
            (if byte_index a bb <= j /\ j < byte_index a bb + 8
             then bit (j - byte_index a bb) b else bit j h))`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[set_byte_def] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    ASM_SIMP_TAC[BIT_WORD_OR; BIT_WORD_SLICE_ALT;
                 ARITH_RULE `0 <= (i:num)`;
                 BIT_WORD_SHL; BIT_WORD_ZX; DIMINDEX_8] THEN
    MP_TAC(REWRITE_RULE[DIMINDEX_8]
      (ISPECL [`b:(8)word`; `j - byte_index (a:(N)word) bb`]
         BIT_TRIVIAL)) THEN
    ASM_CASES_TAC `byte_index (a:(N)word) bb <= j` THEN
    ASM_CASES_TAC `j < byte_index (a:(N)word) bb + 8` THEN
    ASM_CASES_TAC `bit j (h:(N)word)` THEN
    ASM_CASES_TAC
      `bit (j - byte_index (a:(N)word) bb) (b:(8)word)` THEN
    ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC) in
  (* and a byte of a word of the machine is a byte of it *)
  let bib = prove
   (`!(a:'a word) bb. good_dimindex (:'a)
       ==> byte_index a bb + 8 <= dimindex (:'a)`,
    REPEAT GEN_TAC THEN
    REWRITE_TAC[byte_index_def] THEN
    CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[good_dimindex_def] THEN
    DISCH_THEN(DISJ_CASES_THEN (fun th -> SUBST1_TAC th)) THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    MP_TAC(SPEC `w2n (a:'a word)`
      (MATCH_MP DIVISION (ARITH_RULE `~(4 = 0)`))) THEN
    MP_TAC(SPEC `w2n (a:'a word)`
      (MATCH_MP DIVISION (ARITH_RULE `~(8 = 0)`))) THEN
    COND_CASES_TAC THEN ARITH_TAC) in
  (* so whether a bit of the words that two lists of bytes are
     written into is the same bit does not depend on the bytes,
     but only on how many there are: inside a byte that the list
     wrote the bit is the byte's and the two agree, and outside
     every byte the bit is the word's *)
  let key = prove
   (`good_dimindex (:'a)
     ==> !k bs bs' a (h:'a word) h' bb j.
           LENGTH bs = LENGTH bs' /\ j < dimindex (:'a)
           ==> ((bit j (bytes_to_word k a bs h bb) <=>
                 bit j (bytes_to_word k a bs h' bb)) <=>
                (bit j (bytes_to_word k a bs' h bb) <=>
                 bit j (bytes_to_word k a bs' h' bb)))`,
    DISCH_TAC THEN INDUCT_TAC THEN REPEAT GEN_TAC THEN
    STRIP_TAC THEN
    ONCE_REWRITE_TAC[bytes_to_word_def] THEN
    REWRITE_TAC[NOT_SUC; SUC_SUB1] THEN
    (* the words of no byte are the words themselves, which the
       rewrite closed; the step writes the first byte *)
    DISJ_CASES_THEN2 SUBST_ALL_TAC
      (X_CHOOSE_THEN `b0:word8`
         (X_CHOOSE_THEN `t0:word8 list` SUBST_ALL_TAC))
      (ISPEC `bs:word8 list` list_CASES) THEN
    (* the other list has as many bytes, so it splits the same way
       (LENGTH_EQ_NIL, LENGTH_EQ_CONS) *)
    FIRST_X_ASSUM (fun le ->
      if not (try hd_is "LENGTH" (lhs (concl le))
              with Failure _ -> false) then fail() else
      REPEAT_TCL CHOOSE_THEN
        (REPEAT_TCL CONJUNCTS_THEN
           (fun c ->
              if (try is_var (lhs (concl c))
                  with Failure _ -> false)
              then SUBST_ALL_TAC c else ASSUME_TAC c))
        (REWRITE_RULE[LENGTH; LENGTH_EQ_NIL; LENGTH_EQ_CONS]
           (SYM le))) THEN
    SAFE_MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let jlt = grab asl (fun th ->
        try hd_is "<" (concl th) &&
            hd_is "dimindex" (rand (concl th))
        with Failure _ -> false) in
      let sb = find_term (hd_is "set_byte") gl in
      let a = el 0 (snd (strip_comb sb)) in
      let bb = el 3 (snd (strip_comb sb)) in
      let bi = MP (SPECL [a; bb] bib) gd in
      ASM_SIMP_TAC[bsb; bi; jlt]) THEN
    COND_CASES_TAC THEN REWRITE_TAC[] THEN
    FIRST_X_ASSUM (fun ih ->
      if not (is_forall (concl ih)) then fail() else
      W(fun (asl,gl) ->
        let le = grab asl (fun th ->
          try is_eq (concl th) &&
              hd_is "LENGTH" (lhs (concl th))
          with Failure _ -> false) in
        let jlt = grab asl (fun th ->
          try hd_is "<" (concl th) &&
              hd_is "dimindex" (rand (concl th))
          with Failure _ -> false) in
        let p = lhand gl and q = rand gl in
        let args = snd (strip_comb (rand (lhand p))) in
        let args2 = snd (strip_comb (rand (lhand q))) in
        let inst = SPECL [el 2 args; el 2 args2; el 1 args;
                          el 3 args;
                          el 3 (snd (strip_comb (rand (rand p))));
                          el 4 args; lhand (concl jlt)] ih in
        let eqn = lhand (lhand (concl inst)) in
        let le2 = if concl le = eqn then le else SYM le in
        ACCEPT_TAC (MP inst (CONJ le2 jlt))))) in
  (* the theorem: the two sides of the hypothesis agree in a bit
     exactly when the two sides of the goal do *)
  REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN
  W(fun (asl,gl) ->
    let gd = grab asl (fun th ->
      hd_is "good_dimindex" (concl th)) in
    let le = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th))
      with Failure _ -> false) in
    let jlt = grab asl (fun th ->
      try hd_is "<" (concl th) &&
          hd_is "dimindex" (rand (concl th))
      with Failure _ -> false) in
    let hb = grab asl (fun th -> is_forall (concl th)) in
    let hj = MP (SPEC `j:num` hb) jlt in
    let args = snd (strip_comb (rand (lhand gl))) in
    let args' = snd (strip_comb (rand (rand gl))) in
    let args2 = snd (strip_comb (rand (lhand (concl hj)))) in
    let inst = SPECL [el 0 args; el 2 args2; el 2 args;
                      el 1 args; el 3 args; el 3 args';
                      el 4 args; `j:num`]
                 (MATCH_MP key gd) in
    let eqn = lhand (lhand (concl inst)) in
    let le2 = if concl le = eqn then le else SYM le in
    ACCEPT_TAC (EQ_MP (MP inst (CONJ le2 jlt)) hj)))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let write_bytes_inj_lemma = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) ==>
     (!w1 w2 bs bs'.
     write_bytes bs w1 be = write_bytes bs (w2:('a word) list) be
       /\
     LENGTH w1 = LENGTH w2 /\
     LENGTH bs' = LENGTH bs ==>
     // ∧
     // LENGTH bs ≤ LENGTH (w1:α word list) * (dimindex (:α) DIV 8)
     // ∧ LENGTH (w1:α word list) ≤ LENGTH bs DIV (dimindex(:α) DIV 8) +1
     write_bytes bs' w1 be = write_bytes bs' w2 be)`),
  (* the words are written one by one: the first word of the one
     list and of the other are the same word written over the same
     bytes, which bytes_to_word_eq_lemma takes to the other bytes,
     and the rest follows by the induction with the bytes dropped *)
  (let len_drop = prove
    (`!k (l:A list). LENGTH (DROP k l) = LENGTH l - k`,
     INDUCT_TAC THEN LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[DROP; LENGTH; SUB_0; NOT_SUC; SUC_SUB1;
                     ARITH_RULE `0 - SUC k = 0`; SUB_SUC]) in
   DISCH_TAC THEN LIST_INDUCT_TAC THEN GEN_TAC THEN
   CASES_ON_NAME "w2" THEN
   REWRITE_TAC[write_bytes_def; LENGTH; NOT_SUC;
               ARITH_RULE `~(0 = SUC n)`] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[CONS_11; SUC_INJ] THEN REPEAT GEN_TAC THEN
   STRIP_TAC THEN CONJ_TAC THENL
    [FIRST_ASSUM(fun gd -> FIRST_ASSUM(fun lb -> FIRST_ASSUM(fun bw ->
       ACCEPT_TAC(MATCH_MP bytes_to_word_eq_lemma
         (CONJ gd (CONJ lb bw))))));
     FIRST_X_ASSUM MATCH_MP_TAC THEN
     FIRST_ASSUM(fun th ->
       EXISTS_TAC(rand(rator(rator(lhand(concl th))))) THEN
       ASM_REWRITE_TAC[len_drop])]));;

