       ASM_REWRITE_TAC[] THEN
       MP_TAC(ISPECL [`len + 4`;
                      `data_to_word_config_len_size c + 2`;
                      `j:num`] hi) THEN
       SUBGOAL_THEN `data_to_word_config_len_size c + 2 <= j`
