                      `j:num`] hi) THEN
       SUBGOAL_THEN `data_to_word_config_len_size c + 3 <= j`
         (fun th -> REWRITE_TAC[th]) THENL
        [ASM_ARITH_TAC; ASM_REWRITE_TAC[]];
       ALL_TAC] THEN
