(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let IMP_memory_rel_Number = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) /\ small_int (:'a) i /\
      memory_rel c be ts refs sp st m dm vars ==>
      memory_rel c be ts refs sp st m dm
       ((Number i,(wordLang_Word (Smallnum i):'a word_loc)) ::
         vars)`),
  (* the root of a small Number is the Data of its Smallnum, which
     abs_ml_inv_Num adds to the roots, and Smallnum is four times
     the integer up to the sign, so word_addr leaves it alone *)
  (let nmul = prove
    (`!(i:int). &0 <= i
        ==> n2w (num_of_int (&4 * i)) =
            (n2w 4 * n2w (num_of_int i):(N)word)`,
     REPEAT STRIP_TAC THEN
     SUBGOAL_THEN `num_of_int (&4 * (i:int)) = 4 * num_of_int i`
       SUBST1_TAC THENL
      [FIRST_ASSUM(fun th ->
         GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
           [GSYM(MATCH_MP INT_OF_NUM_OF_INT th)]) THEN
       REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM];
       REWRITE_TAC[WORD_MUL]]) in
   let and_sym = WORD_BITWISE_RULE `(x:(N)word) && y = y && x` in
   let andnot1 = prove
    (`good_dimindex (:'a)
      ==> ((n2w 4 * v:'a word) && word_not (n2w 1) = n2w 4 * v) /\
          ((--(n2w 4) * v:'a word) && word_not (n2w 1) =
           --(n2w 4) * v)`,
     DISCH_TAC THEN
     SUBGOAL_THEN `word_not (n2w 1:'a word) = --(n2w 2)`
       SUBST1_TAC THENL
      [CONV_TAC WORD_RULE; ALL_TAC] THEN
     ONCE_REWRITE_TAC[and_sym] THEN
     ASM_SIMP_TAC[word_ml_inv_num_lemma;
                  word_ml_inv_neg_num_lemma]) in
   let neg_mul = WORD_RULE
     `word_neg (word 4 * (v:(N)word)) = word_neg (word 4) * v` in
   let waddr = hd (word_addr_clauses ()) in
   REWRITE_TAC[memory_rel_def; word_ml_inv_def] THEN
   REPEAT STRIP_TAC THEN ASM_EXISTS_TAC THEN
   ASM_REWRITE_TAC[] THEN
   EXISTS_TAC
     `CONS (gc_shared_Data (wordLang_Word (Smallnum i:'a word))) hs`
   THEN
   REWRITE_TAC[MAP; ALL2; waddr] THEN
   ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
    [MATCH_MP_TAC abs_ml_inv_Num THEN ASM_REWRITE_TAC[];
     REWRITE_TAC[smallnum_def] THEN COND_CASES_TAC THENL
      [SUBGOAL_THEN `&0 <= ((&0) - (i:int))` ASSUME_TAC THENL
        [ASM_INT_ARITH_TAC; ALL_TAC] THEN
       FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP nmul th]) THEN
       REWRITE_TAC[WORD_SUB_LZERO; neg_mul] THEN
       ASM_SIMP_TAC[andnot1];
       SUBGOAL_THEN `&0 <= (i:int)` ASSUME_TAC THENL
        [ASM_INT_ARITH_TAC; ALL_TAC] THEN
       FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP nmul th]) THEN
       ASM_SIMP_TAC[andnot1]]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_El_any = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Block ts' tag vals,(ptr:'a
  word_loc)) :: vars) /\
      good_dimindex (:'a) /\
      index < LENGTH vals ==>
      (?ptr_w x (y:'a word).
        ptr = wordLang_Word ptr_w /\
        get_real_addr c st ptr_w = SOME x /\
        (x + bytes_in_word + bytes_in_word * n2w index) IN dm /\
        memory_rel c be ts refs sp st m dm
          ((EL index vals,m (x + bytes_in_word + bytes_in_word *
            n2w index)) ::
           (Block ts' tag vals,ptr) :: vars))`),
  (* the same statement as memory_rel_El', up to an existential
     that neither of the two uses: the source proves it again from
     memory_rel_El, with a Number put into the list for the offset,
     and the port takes the primed one, which is already there *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
 let grab asl p =
   tryfind (fun (_,th) ->
     if (try p th with Failure _ -> false) then th else fail())
     asl in
   DISCH_TAC THEN
   FIRST_ASSUM(fun th ->
     MP_TAC(MATCH_MP memory_rel_El' th)) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   W(fun (asl,w) ->
     let pe = grab asl (fun th ->
       hd_is "wordLang_Word" (rhs (concl th))) in
     let ga = grab asl (fun th ->
       hd_is "get_real_addr" (lhs (concl th))) in
     let pw = rand (rhs (concl pe)) in
     let x = rand (rhs (concl ga)) in
     EXISTS_TAC pw THEN EXISTS_TAC x THEN EXISTS_TAC x) THEN
   ASM_REWRITE_TAC[]));;

let copy_list_def = cake_define
  `copy_list c' st k (a,x,(b:'a word),(m:'a word->'a word_loc),dm) =
     (let c = (b IN dm) in
     let m = (b =+ x) m in
     let b = b + bytes_in_word in
       if k = 0 then (if c then SOME (b,m) else NONE) else
         match a with Loc _53 _54 -> NONE | wordLang_Word a ->
         (match get_real_addr c' st a with NONE -> NONE | SOME a ->
           (let c = (c /\ a + (n2w 2) * bytes_in_word IN dm /\ a +
             bytes_in_word IN dm) in
           let x = m (a + bytes_in_word) in
           let a = m (a + (n2w 2) * bytes_in_word) in
             if c then copy_list c' st (k - 1) (a,x,b,m,dm) else
               NONE)))`;;

(* HOL4 data_to_word_memoryProofScript.sml:10872-10965: a theorem
   that HOL4 states as the value of an ML expression: copy_list_thm *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_FromList = prove
 (cake_as_vars (fun () ->
    `v_to_list v = SOME vs /\ ~(vs = []) /\
      memory_rel c be ts refs sp st m dm ((v,(a:'a word_loc)) ::
        vars) /\
      encode_header c (4 * tag) (LENGTH vs) = SOME hd /\ LENGTH vs
        < sp /\
      good_dimindex (:'a) ==>
      (?free' curr m1 f1 xs.
        FLOOKUP st NextFree = SOME (wordLang_Word free') /\
        FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
        copy_list c st (LENGTH vs) (a,wordLang_Word hd,free',m,dm)
          = SOME (f1,m1) /\
        memory_rel c be (ts + 1) refs (sp - (LENGTH vs + 1)) (st |+
          (NextFree,wordLang_Word f1)) m1 dm
          ((Block ts tag vs,
            make_cons_ptr c (free' - curr) tag (LENGTH vs)) ::
              vars))`),
  (* the attempt: the proof of the source names FLOOKUP,
     memory_rel_def, heap_in_memory_store_def,
     memory_rel_IMP_word_list_exists, memory_rel_Cons_alt.  What is
     here rewrites with them and closes by arithmetic, and the cheat
     is behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[FLOOKUP; memory_rel_def;
       heap_in_memory_store_def; memory_rel_IMP_word_list_exists;
       memory_rel_Cons_alt] THEN
     TRY ASM_ARITH_TAC)));;

(* [local] *)
let make_header_tag_mask = prove
 (`k < 2 EXP (dimindex (:'a) - (data_to_word_config_len_size c + 2)) ==>
     (tag_mask c && make_header c ((n2w k):'a word) n) = n2w (4 *
       k)`,
  (* the tag mask keeps the bits of a header between the second and
     the one the length size leaves, and those are the bits of four
     times the tag; above them the tag has none, because it is below
     two to the width of its field *)
  (let hi = prove
    (`!n r (i:num). n < 2 EXP r /\ r <= i
        ==> ~(bit i ((n2w n):'a word))`,
     MATCH_ACCEPT_TAC BIT_WORD_HI) in
   let b3 = prove
    (`!j. j < dimindex (:'a)
          ==> (bit j ((n2w 3):'a word) <=> j < 2)`,
     GEN_TAC THEN DISCH_TAC THEN
     ASM_CASES_TAC `(j:num) < 2` THEN ASM_REWRITE_TAC[] THENL
      [FIRST_ASSUM(DISJ_CASES_THEN SUBST_ALL_TAC o MATCH_MP
         (ARITH_RULE `(j:num) < 2 ==> j = 0 \/ j = 1`)) THEN
       ASM_REWRITE_TAC[BIT_WORD] THEN CONV_TAC NUM_REDUCE_CONV THEN
       ASM_ARITH_TAC;
       MP_TAC(ISPECL [`3`; `2`; `j:num`] hi) THEN
       ASM_SIMP_TAC[ARITH_RULE `~((j:num) < 2) ==> 2 <= j`] THEN
       CONV_TAC NUM_REDUCE_CONV]) in
   let btm = prove
    (`!c j. j < dimindex (:'a)
        ==> (bit j ((tag_mask c):'a word) <=>
             2 <= j /\
             j < dimindex (:'a) - data_to_word_config_len_size c)`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[tag_mask_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_SIMP_TAC[BIT_WORD_SLICE; BIT_WORD_NOT; BIT_WORD_0] THEN
     ASM_ARITH_TAC) in
   let bmh = prove
    (`!c (t:'a word) n j. j < dimindex (:'a)
        ==> (bit j (make_header c t n:'a word) <=>
             j < 2 \/ (2 <= j /\ bit (j - 2) t) \/
             (dimindex (:'a) - data_to_word_config_len_size c <= j /\
              bit (j - (dimindex (:'a) -
                        data_to_word_config_len_size c))
                  ((n2w n):'a word)))`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[make_header_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_SIMP_TAC[BIT_WORD_OR; BIT_WORD_SHL; b3] THEN
     CONV_TAC TAUT) in
   let n4 = prove
    (`!k. (n2w (4 * k):(N)word) = word_shl (n2w k) 2`,
     let shl4 = prove
      (`!(v:(N)word). word 4 * v = word_shl v 2`,
       REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
       CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
       REWRITE_TAC[MULT_AC]) in
     GEN_TAC THEN REWRITE_TAC[GSYM shl4; WORD_MUL]) in
   DISCH_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
   X_GEN_TAC `j:num` THEN DISCH_TAC THEN
   ASM_SIMP_TAC[BIT_WORD_AND; btm; bmh; n4; BIT_WORD_SHL] THEN
   MP_TAC(ISPECL
     [`k:num`;
      `dimindex (:'a) - (data_to_word_config_len_size c + 2)`;
      `j - 2`] hi) THEN
   ASM_CASES_TAC `2 <= (j:num)` THEN
   ASM_CASES_TAC
     `j < dimindex (:'a) - data_to_word_config_len_size c` THEN
   ASM_CASES_TAC `bit (j - 2) ((n2w k):'a word)` THEN
   ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC));;

(* [local] *)
let make_header_and_2 = prove
 (`((n2w 2) && make_header c w n) = (n2w 2)`,
  (* make_header ors a 3 in, whose second bit is the one that the 2
     masks out *)
  (let bw2 = prove
    (`!i. bit i (word 2:(N)word) <=> i = 1 /\ 1 < dimindex(:N)`,
     GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [ARITH_RULE `2 = 2 EXP 1`] THEN
     REWRITE_TAC[BIT_WORD_POW2]) in
   let bw3_1 = prove
    (`bit 1 (word 3:(N)word) <=> 1 < dimindex(:N)`,
     REWRITE_TAC[BIT_WORD] THEN CONV_TAC NUM_REDUCE_CONV) in
   REWRITE_TAC[make_header_def] THEN
   CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_OR; bw2] THEN
   GEN_TAC THEN DISCH_TAC THEN
   ASM_CASES_TAC `i = 1` THEN ASM_REWRITE_TAC[bw3_1] THEN
   CONV_TAC TAUT));;

let encode_header_tag_mask = prove
 (`encode_header c (4 * tag) n = SOME (w:'a word) /\ good_dimindex (:'a)
  ==>
    tag < dimword (:'a) DIV 16 /\
    (w && (tag_mask c || (n2w 2))) = n2w (16 * tag + 2)`,
  (* the header of encode_header is make_header of four times the
     tag, whose and with the tag mask make_header_tag_mask says is
     sixteen times the tag and whose and with the two
     make_header_and_2 says is the two; the or of those two is their
     sum, because sixteen times a number has no bit as low as the
     second *)
  (
   let bw2 = prove
    (`!i. bit i (word 2:(N)word) <=> i = 1 /\ 1 < dimindex(:N)`,
     GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [ARITH_RULE `2 = 2 EXP 1`] THEN
     REWRITE_TAC[BIT_WORD_POW2]) in
   let n16 = prove
    (`!k. (n2w (16 * k):(N)word) = word_shl (n2w k) 4`,
     let shl16 = prove
      (`!(v:(N)word). word 16 * v = word_shl v 4`,
       REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
       CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
       REWRITE_TAC[MULT_AC]) in
     GEN_TAC THEN REWRITE_TAC[GSYM shl16; WORD_MUL]) in
   let and2_0 = prove
    (`!k. (n2w (16 * k):(N)word) && n2w 2 = n2w 0`,
     GEN_TAC THEN REWRITE_TAC[n16] THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
                 BIT_WORD_SHL; bw2] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `(i:num) = 1` THEN ASM_REWRITE_TAC[] THEN
     CONV_TAC NUM_REDUCE_CONV) in
   let orsum = prove
    (`!k. (n2w (16 * k):(N)word) || n2w 2 = n2w (16 * k + 2)`,
     GEN_TAC THEN
     MP_TAC(SPEC_ALL (ISPECL [`n2w (16 * k):(N)word`; `n2w 2:(N)word`]
       WORD_ADD_OR)) THEN
     REWRITE_TAC[and2_0] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
     REWRITE_TAC[WORD_ADD]) in
   let distr = WORD_BITWISE_RULE
     `!(x:(N)word) a b. x && (a || b) = (x && a) || (x && b)` in
   STRIP_TAC THEN
   USE_CHANGED [encode_header_def] THEN
   COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
   REWRITE_TAC[injectivity "option"] THEN
   DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
   FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC) THEN
   CONJ_TAC THENL
    [ASM_ARITH_TAC;
     REWRITE_TAC[distr] THEN
     ONCE_REWRITE_TAC[WORD_AND_SYM] THEN
     REWRITE_TAC[make_header_and_2] THEN
     SUBGOAL_THEN
       `tag_mask c && make_header c ((n2w (4 * tag)):'a word) n =
        n2w (4 * (4 * tag))`
       SUBST1_TAC THENL
      [MATCH_MP_TAC make_header_tag_mask THEN
       REWRITE_TAC[ARITH_RULE `d - (k + 2) = d - k - 2`] THEN
       ASM_REWRITE_TAC[];
       ONCE_REWRITE_TAC[WORD_AND_SYM] THEN
       REWRITE_TAC[ARITH_RULE `4 * (4 * tag) = 16 * tag`; orsum]]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_tag_limit = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Block ts' tag l,(w:'a
  word_loc)) :: rest) /\
      good_dimindex (:'a) ==>
      tag < dimword (:'a) DIV 16`),
  (* the tag of an empty Block is below the bound by what
     memory_rel_Block_IMP says, and the tag of a Block with a
     payload by the header that encode_header gives it *)
  (STRIP_TAC THEN USE2 memory_rel_Block_IMP THEN STRIP_TAC THEN
   OPEN_COND THEN
   TRY(FIRST_ASSUM ACCEPT_TAC) THEN
   USE2 encode_header_tag_mask THEN STRIP_TAC THEN
   FIRST_ASSUM ACCEPT_TAC));;

(* [local] *)
let LESS_DIV_16_IMP = prove
 (`n < k DIV 16 ==> 16 * n + 2 < (k:num)`,
  (ARITH_TAC));;

(* [local] *)
let MULT_BIT0 = prove
 (`BIT 0 (m * n) <=> BIT 0 m /\ BIT 0 n`,
  (* HOL4's BIT0_ODD, which the port does not have of bitTheory *)
  (let bit0 = prove
    (`!n. BIT 0 n <=> ODD n`,
     REWRITE_TAC[BIT; BITS; MOD_2EXP; DIV_2EXP; SUB_0; EXP; DIV_1;
                 ARITH_RULE `SUC 0 = 1`; EXP_1] THEN
     GEN_TAC THEN
     MP_TAC(SPECL [`n:num`; `2`] DIVISION) THEN
     REWRITE_TAC[ARITH_EQ] THEN
     MP_TAC(SPEC `n:num` EVEN_OR_ODD) THEN
     REWRITE_TAC[EVEN_MOD; ODD_MOD] THEN ARITH_TAC) in
   REWRITE_TAC[bit0; ODD_MULT]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_test_nil_eq = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Block ts' tag l,(w:'a
  word_loc)) :: rest) /\
      n < dimword (:'a) DIV 16 /\ good_dimindex (:'a) ==>
      (?v. w = wordLang_Word v /\ (v = n2w (16 * n + 2) <=> tag =
        n /\ l = []))`),
  (* memory_rel_Block_IMP says what the word of the Block is: of an
     empty Block it is sixteen times the tag plus two, whose lowest
     bit is clear, and of a Block with values it is a pointer, whose
     lowest bit is set.  So of an empty Block the two words are
     equal exactly when the two numbers are, both of which are below
     dimword by LESS_DIV_16_IMP, and of a Block with values the test
     fails on the lowest bit *)
  (let ldi = LESS_DIV_16_IMP in
   let n2w_11 = prove
    (`!a b. a < dimword (:N) /\ b < dimword (:N)
        ==> ((n2w a:(N)word) = n2w b <=> a = b)`,
     REPEAT STRIP_TAC THEN
     REWRITE_TAC[GSYM VAL_EQ; VAL_WORD; GSYM dimword] THEN
     ASM_SIMP_TAC[MOD_LT]) in
   STRIP_TAC THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
     MP_TAC(MATCH_MP memory_rel_Block_IMP
       (CONJ mr gd)))) THEN
   DISCH_THEN(X_CHOOSE_THEN `u:'a word`
     (CONJUNCTS_THEN2 SUBST_ALL_TAC MP_TAC)) THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[] THENL
    [DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC STRIP_ASSUME_TAC) THEN
     EXISTS_TAC `n2w tag * n2w 16 + (n2w 2):'a word` THEN
     REWRITE_TAC[GSYM WORD_MUL; GSYM WORD_ADD] THEN
     MP_TAC(SPECL [`tag * 16 + 2`; `16 * n + 2`]
       (INST_TYPE [`:'a`,`:N`] n2w_11)) THEN
     ANTS_TAC THENL
      [CONJ_TAC THENL
        [MP_TAC(INST [`tag:num`,`n:num`;
                      `dimword (:'a)`,`k:num`] ldi);
         MP_TAC(INST [`dimword (:'a)`,`k:num`] ldi)] THEN
       ASM_ARITH_TAC;
       DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ARITH_TAC];
     STRIP_TAC THEN EXISTS_TAC `u:'a word` THEN REWRITE_TAC[] THEN
     DISCH_THEN SUBST_ALL_TAC THEN
     FIRST_ASSUM(fun b0 ->
       CONTR_TAC(REWRITE_RULE[word_index; BIT_WORD; EXP; DIV_1;
         ODD_ADD; ODD_MULT; ARITH] b0))]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_test_none_eq = prove
 (cake_as_vars (fun () ->
    `encode_header c (4 * n) len = (NONE:('a word) option) /\
      memory_rel c be ts refs sp st m dm ((Block ts' tag l,(w:'a
        word_loc)) :: rest) /\ ~(len = 0) /\ good_dimindex (:'a) ==>
      ~(tag = n /\ LENGTH l = len)`),
  (* the Block has values, because its length is not zero, so
     memory_rel_Block_IMP gives its header, and encode_header of the
     tag and that length is SOME of it, not NONE *)
  (REPEAT STRIP_TAC THEN
   SUBGOAL_THEN `~(l:(dataSem_v)list = [])` ASSUME_TAC THENL
    [REWRITE_TAC[GSYM LENGTH_EQ_NIL] THEN ASM_REWRITE_TAC[];
     ALL_TAC] THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
     MP_TAC(MATCH_MP memory_rel_Block_IMP
       (CONJ mr gd)))) THEN
   ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
   (* the equations of the chosen witnesses are used up, the tag and
      the length first *)
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_eq(concl th) && is_var(lhand(concl th))
     then SUBST_ALL_TAC th else fail())) THEN
   FIRST_X_ASSUM(fun th ->
     let c = concl th in
     if is_eq c && is_var(rand c) && not(is_var(lhand c))
     then SUBST_ALL_TAC(SYM th) else fail()) THEN
   FIRST_ASSUM(fun th1 -> FIRST_ASSUM(fun th2 ->
     CONTR_TAC(REWRITE_RULE[th1; option_DISTINCT] th2)))));;

(* [local] *)
let not_bit_lt_2exp = prove
 (`!p x n. n < 2 EXP (p + 1) ==> ~(BIT (p + (x + 1)) n)`,
  (* the number is below 2 EXP (p + 1), so every bit of it from
     there up is zero *)
  (REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[BIT; BITS; MOD_2EXP;
                                       DIV_2EXP]) THEN
   SUBGOAL_THEN `n DIV (2 EXP (p + (x + 1))) = 0` SUBST1_TAC THENL
    [MATCH_MP_TAC DIV_LT THEN
     MATCH_MP_TAC LTE_TRANS THEN
     EXISTS_TAC `2 EXP (p + 1)` THEN ASM_REWRITE_TAC[LE_EXP] THEN
     CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC;
     REWRITE_TAC[ARITH_RULE `SUC a - a = 1`] THEN
     CONV_TAC NUM_REDUCE_CONV]));;

(* HOL4 data_to_word_memoryProofScript.sml:11090: ML code, not ported *)

let encode_header_EQ = prove
 (`encode_header c t1 l1 = SOME (w1:'a word) /\
    encode_header c t2 l2 = SOME (w2:'a word) /\
      data_to_word_config_len_size
    c + 2 < dimindex (:'a) ==>
    (w1 = w2 <=> t1 = t2 /\ l1 = l2)`,
  (* two headers with the same bits have the same fields: the bit of
     the tag at j is the bit of the header at j plus two, the bit of
     the length at j is the one at j plus the shift, and above their
     fields both tags and both lengths have no bit at all *)
  (let hi = prove
    (`!n r (i:num). n < 2 EXP r /\ r <= i
        ==> ~(bit i ((n2w n):'a word))`,
     MATCH_ACCEPT_TAC BIT_WORD_HI) in
   let b3 = prove
    (`!j. j < dimindex (:'a)
          ==> (bit j ((n2w 3):'a word) <=> j < 2)`,
     GEN_TAC THEN DISCH_TAC THEN
     ASM_CASES_TAC `(j:num) < 2` THEN ASM_REWRITE_TAC[] THENL
      [FIRST_ASSUM(DISJ_CASES_THEN SUBST_ALL_TAC o MATCH_MP
         (ARITH_RULE `(j:num) < 2 ==> j = 0 \/ j = 1`)) THEN
       ASM_REWRITE_TAC[BIT_WORD] THEN CONV_TAC NUM_REDUCE_CONV THEN
       ASM_ARITH_TAC;
       MP_TAC(ISPECL [`3`; `2`; `j:num`] hi) THEN
       ASM_SIMP_TAC[ARITH_RULE `~((j:num) < 2) ==> 2 <= j`] THEN
       CONV_TAC NUM_REDUCE_CONV]) in
   let bmh = prove
    (`!c (t:'a word) n j. j < dimindex (:'a)
        ==> (bit j (make_header c t n:'a word) <=>
             j < 2 \/ (2 <= j /\ bit (j - 2) t) \/
             (dimindex (:'a) - data_to_word_config_len_size c <= j /\
              bit (j - (dimindex (:'a) -
                        data_to_word_config_len_size c))
                  ((n2w n):'a word)))`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[make_header_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_SIMP_TAC[BIT_WORD_OR; BIT_WORD_SHL; b3] THEN
     CONV_TAC TAUT) in
   let n2w_inj = prove
    (`!a b m. a < 2 EXP m /\ b < 2 EXP m /\ m <= dimindex (:'a) /\
              ((n2w a):'a word = n2w b)
        ==> a = b`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     FIRST_X_ASSUM(MP_TAC o AP_TERM `val:'a word->num`) THEN
     REWRITE_TAC[VAL_WORD] THEN
     SUBGOAL_THEN
       `a < 2 EXP dimindex (:'a) /\ b < 2 EXP dimindex (:'a)`
       STRIP_ASSUME_TAC THENL
      [CONJ_TAC THEN TRANS_TAC LTE_TRANS `2 EXP m` THEN
       ASM_SIMP_TAC[LE_EXP; ARITH];
       ASM_SIMP_TAC[MOD_LT]]) in
   REWRITE_TAC[encode_header_def] THEN
   COND_CASES_TAC THEN COND_CASES_TAC THEN
   REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_conj (concl th) then STRIP_ASSUME_TAC th else fail())) THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM)
     (CONJUNCTS_THEN2 (SUBST1_TAC o SYM) ASSUME_TAC)) THEN
   EQ_TAC THENL
    [DISCH_THEN(fun hdeq ->
       ASSUME_TAC(REWRITE_RULE[WORD_EQ_BITS_ALT] hdeq)) THEN
     SUBGOAL_THEN
       `((n2w t1):'a word = n2w t2) /\ ((n2w l1):'a word = n2w l2)`
       MP_TAC THENL
      [CONJ_TAC THEN REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
       X_GEN_TAC `j:num` THEN DISCH_TAC THENL
        [ASM_CASES_TAC `j < dimindex (:'a) -
                        data_to_word_config_len_size c - 2` THENL
          [SUBGOAL_THEN
             `~(j + 2 < 2) /\ 2 <= j + 2 /\
              ~(dimindex (:'a) - data_to_word_config_len_size c <=
                j + 2) /\
              (j + 2) - 2 = j /\ j + 2 < dimindex (:'a)`
             STRIP_ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
           FIRST_X_ASSUM(fun bits -> MP_TAC(SPEC `j + 2` bits)) THEN
           ASM_SIMP_TAC[bmh] THEN TRY(DISCH_THEN ACCEPT_TAC);
           MP_TAC(ISPECL
             [`t1:num`; `dimindex (:'a) -
               data_to_word_config_len_size c - 2`; `j:num`] hi) THEN
           MP_TAC(ISPECL
             [`t2:num`; `dimindex (:'a) -
               data_to_word_config_len_size c - 2`; `j:num`] hi) THEN
           ASM_SIMP_TAC[ARITH_RULE `~((j:num) < m) ==> m <= j`] THEN
           DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
           DISCH_THEN(fun th -> REWRITE_TAC[th])];
         ASM_CASES_TAC `j < data_to_word_config_len_size c` THENL
          [SUBGOAL_THEN
             `~(j + (dimindex (:'a) -
                     data_to_word_config_len_size c) < 2) /\
              2 <= j + (dimindex (:'a) -
                        data_to_word_config_len_size c) /\
              dimindex (:'a) - data_to_word_config_len_size c <=
              j + (dimindex (:'a) -
                   data_to_word_config_len_size c) /\
              (j + (dimindex (:'a) -
                    data_to_word_config_len_size c)) -
              (dimindex (:'a) - data_to_word_config_len_size c) = j /\
              j + (dimindex (:'a) -
                   data_to_word_config_len_size c) <
              dimindex (:'a) /\
              dimindex (:'a) - data_to_word_config_len_size c - 2 <=
              (j + (dimindex (:'a) -
                    data_to_word_config_len_size c)) - 2`
             STRIP_ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
           FIRST_X_ASSUM(fun bits -> MP_TAC(SPEC
             `j + (dimindex (:'a) -
                   data_to_word_config_len_size c)` bits)) THEN
           ASM_SIMP_TAC[bmh] THEN
           MP_TAC(ISPECL
             [`t1:num`; `dimindex (:'a) -
               data_to_word_config_len_size c - 2`;
              `(j + (dimindex (:'a) -
                     data_to_word_config_len_size c)) - 2`] hi) THEN
           MP_TAC(ISPECL
             [`t2:num`; `dimindex (:'a) -
               data_to_word_config_len_size c - 2`;
              `(j + (dimindex (:'a) -
                     data_to_word_config_len_size c)) - 2`] hi) THEN
           ASM_REWRITE_TAC[] THEN
           DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
           DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
           TRY(DISCH_THEN ACCEPT_TAC);
           MP_TAC(ISPECL
             [`l1:num`; `data_to_word_config_len_size c`;
              `j:num`] hi) THEN
           MP_TAC(ISPECL
             [`l2:num`; `data_to_word_config_len_size c`;
              `j:num`] hi) THEN
           ASM_SIMP_TAC[ARITH_RULE `~((j:num) < m) ==> m <= j`] THEN
           DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
           DISCH_THEN(fun th -> REWRITE_TAC[th])]];
       STRIP_TAC THEN CONJ_TAC THENL
        [MATCH_MP_TAC n2w_inj THEN
         EXISTS_TAC `dimindex (:'a) -
                     data_to_word_config_len_size c - 2` THEN
         ASM_REWRITE_TAC[] THEN ARITH_TAC;
         MATCH_MP_TAC n2w_inj THEN
         EXISTS_TAC `data_to_word_config_len_size c` THEN
         ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]];
     DISCH_THEN(CONJUNCTS_THEN SUBST1_TAC) THEN REFL_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_ValueArray_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,(v:'a word_loc))
  :: vars) /\
      lookup p refs = SOME (ValueArray vals) /\ good_dimindex (:'a)
        ==>
      (?w a x.
        v = wordLang_Word w /\ FAPPLY w 0 /\ word_bit 3 x /\
          ~(word_bit 2 x) /\ ~(word_bit 4 x) /\
        get_real_simple_addr c st w = SOME a /\
        get_real_addr c st w = SOME a /\
        m a = wordLang_Word x /\ a IN dm /\
        decode_length c x = n2w (LENGTH vals) /\
        LENGTH vals < 2 EXP (dimindex (:'a) - 4))`),
  (* the header of a reference's array, read out of the memory: as
     for a byte array, the v_inv of the RefPtr gives the pointer
     (whose lowest bit is set, which is get_addr_0), bc_ref_inv
     gives the RefBlock of the heap and get_real_addr_get_addr the
     address.  The cond of the word_el says what decode_length of
     the header is, and the three bits of the statement are read
     off make_header: the tag of a RefTag is two, which puts the
     bit at three, and the length sits above the len_size, which
     heap_in_memory_store keeps seven below the word size *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let rec facs t =
     if hd_is "STAR" t then
       let args = snd(strip_comb t) in
       facs (el 0 args) @ facs (el 1 args)
     else [t] in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail()) asl in
   let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
   let sepfront names =
     W(fun (asl,w) ->
       let pred = rator (lhand w) in
       let fs = facs pred in
       let picked = map (fun n -> find (hd_is n) fs) names in
       let rest = filter (fun t -> not (mem t picked)) fs in
       let st = fst(strip_comb pred) in
       let mk a b = mk_comb(mk_comb(st,a),b) in
       let target = itlist mk picked (end_itlist mk rest) in
       SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
        [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
   MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN
   TRY(FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 ->
     CONTR_TAC(REWRITE_RULE[injectivity "option";
                            distinctness "bvlSem_ref"]
                 (TRANS (SYM t1) t2))))) THEN
   FIRST_ASSUM(fun e ->
     let c = concl e in
     if is_eq c && is_var (rand c) && hd_is "wordLang_Word" (lhs c)
     then SUBST1_TAC (SYM e) else fail()) THEN
   REWRITE_TAC[injectivity "word_loc"] THEN
   CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
   REWRITE_TAC[get_addr_0] THEN
   FIRST_X_ASSUM(fun th ->
     if is_forall (concl th) &&
        hd_is "bc_ref_inv" (rand (snd(strip_forall(concl th))))
     then MP_TAC(SPEC `p:num` th) else fail()) THEN
   ANTS_TAC THENL
    [CONJ_TAC THENL
      [REWRITE_TAC[reachable_refs_def; MEM] THEN
       EXISTS_TAC `RefPtr bl p:dataSem_v` THEN
       EXISTS_TAC `p:num` THEN
       REWRITE_TAC[get_refs_def; MEM;
                   CONJUNCT1(SPEC_ALL RTC_RULES)];
       ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
   REWRITE_TAC[bc_ref_inv_def] THEN
   ASM_SIMP_TAC[FLOOKUP_DEF] THEN
   MATCH_REDUCE_TAC THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun th ->
     if hd_is "heap_in_memory_store" (concl th)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
     else fail()) THEN
   STRIP_TAC THEN
   W(fun (asl,w) ->
     MP_TAC(MATCH_MP heap_lookup_SPLIT
              (grab asl is_hl))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "fmap_apply" (lhs (concl th))
         with Failure _ -> false)
     then SUBST_ALL_TAC th else fail()) THEN
   W(fun (asl,w) ->
     let hl = grab asl is_hl in
     let hlen = grab asl (fun th ->
       hd_is "heap_length" (lhand (concl th))) in
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
     let gd = grab asl (fun th -> concl th = `good_dimindex (:'a)`) in
     let gat = tryfind (fun t ->
       find_term (fun u ->
         hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
       (w :: map (fun (_,th) -> concl th) asl) in
     let th = SPEC (last (snd(strip_comb gat)))
       (GEN `w:('a)word_loc`
         (MATCH_MP get_real_addr_get_addr
           (CONJ hlen (CONJ hl (CONJ cu gd))))) in
     let r = rhs (concl (CONJUNCT1 th)) in
     let a = rand r in
     let args = snd(strip_comb (rand a)) in
     let mul = fst(strip_comb (rand a)) in
     let swap = mk_comb(rator a,
                  mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
     let sw = WORD_RULE (mk_eq(a,swap)) in
     EXISTS_TAC swap THEN
     STRIP_ASSUME_TAC(REWRITE_RULE[sw] th)) THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def;
               RefBlock_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_list_def; LENGTH_MAP] THEN
   sepfront ["cond"] THEN
   REWRITE_TAC[cond_STAR] THEN
   DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC) THEN
   sepfront ["set_sep_one"] THEN
   DISCH_THEN(fun sep ->
     let rd = MATCH_MP read_fun2set sep in
     EXISTS_TAC (rand (rhs (concl (CONJUNCT1 rd)))) THEN
     STRIP_ASSUME_TAC rd) THEN
   FIRST_ASSUM(fun lr ->
     if hd_is "ALL2" (concl lr)
     then SUBST1_TAC(SYM(MATCH_MP LIST_REL_LENGTH lr)) else fail()) THEN
   ASM_REWRITE_TAC[] THEN
   REWRITE_TAC[make_header_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[BIT_WORD_OR; BIT_WORD_SHL; BIT_WORD] THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   UNDISCH_TAC `data_to_word_config_len_size c + 7 < dimindex (:'a)`
     THEN ARITH_TAC));;

let blocks_unique_Thunk = prove
 (`lookup p refs = SOME (Thunk ev x) /\
   blocks_unique ts (all_vs refs (RefPtr bl p :: MAP FST vars)) ==>
     blocks_unique ts (all_vs refs (x :: MAP FST vars))`,
  (* the value of the thunk is a value of the refs already *)
  (let vcons = prove
    (`!(v:dataSem_v) xs y. MEM y (v_all_vs (CONS v xs)) <=>
        MEM y (v_all_vs [v]) \/ MEM y (v_all_vs xs)`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [prove(`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
              REWRITE_TAC[APPEND])] THEN
     REWRITE_TAC[v_all_vs_append; MEM_APPEND]) in
   let inc = prove
    (`!refs p ev x bl vs t a q.
        sptree_lookup p refs = SOME (Thunk ev x) /\
        Block t a q IN all_vs refs (CONS x vs) ==>
        Block t a q IN all_vs refs (CONS (RefPtr bl p) vs)`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
     MESON_TAC[vcons]) in
   REWRITE_TAC[blocks_unique_def] THEN STRIP_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

let blocks_unique_Thunk2 = prove
 (`lookup p refs = SOME (Thunk ev v') /\
   blocks_unique ts (all_vs refs (RefPtr F p :: MAP FST vars)) ==>
     blocks_unique ts (all_vs refs (v' :: RefPtr F p :: MAP FST
       vars))`,
  (* the value of the Thunk at p is already among the values of the
     references, so the stack with it in front has the same values
     as the stack without it, and the uniqueness carries over.  The
     element of the goal picks the assumption about it (there are
     two), and the two sides of the transfer are split the same way
     so that the disjuncts match one by one *)
  (
   let cons_app = prove
    (`!(h:dataSem_v) t. CONS h t = APPEND [h] t`,
     REWRITE_TAC[APPEND]) in
   let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   REWRITE_TAC[blocks_unique_def] THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
   W(fun (asl,w) ->
     let gel = el 0 (snd(strip_comb w)) in
     FIRST_ASSUM(fun inm ->
       let c = concl inm in
       if not (hd_is "IN" c) || not (el 0 (snd(strip_comb c)) = gel)
       then fail() else
       FIRST_ASSUM(fun lk ->
         if not (hd_is "=" (concl lk)) then fail() else
         MP_TAC(REWRITE_RULE[all_vs_def; IN_UNION;
                             IN_ELIM_THM; v_all_vs_append;
                             MEM_APPEND]
                  (ONCE_REWRITE_RULE[cons_app] inm)) THEN
         MP_TAC lk THEN
         REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM;
                     v_all_vs_append; MEM_APPEND] THEN
         MESON_TAC[])))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Thunk_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,(v:'a word_loc))
  :: vars) /\
     lookup p refs = SOME (Thunk ev z) /\
     good_dimindex (:'a) ==>
       (~bl /\
        ev = Evaluated /\
        (!w. v = wordLang_Word w /\ FAPPLY w 0 ==>
           memory_rel c be ts refs sp st m dm ((z,v) :: vars) /\
           (?a x. get_real_addr c st w = SOME a /\
                 m a = wordLang_Word x /\ a IN dm /\ ~((x && (n2w
                   0b111100)) = n2w ((0 + 6) * 4)) /\ ~((x && (n2w
                   0b111100)) = n2w ((8 + 6) * 4))))) \/
       (?w a x.
         v = wordLang_Word w /\ FAPPLY w 0 /\ word_bit 3 x /\
           ~(word_bit 2 x) /\ word_bit 4 x /\
         get_real_simple_addr c st w = SOME a /\
         get_real_addr c st w = SOME a /\
         m a = wordLang_Word x /\ a IN dm /\
         (a + bytes_in_word) IN dm /\
         decode_length c x = (n2w 1) /\
         (word_bit 5 x <=> ev = Evaluated) /\
         memory_rel c be ts refs sp st m dm
           ((z,m (a + bytes_in_word)) :: (RefPtr bl p,v) ::
             vars))`),
  (* the attempt: the proof of the source names memory_rel_def,
     word_ml_inv_def, abs_ml_inv_def, bc_stack_ref_inv_def,
     v_inv_def, word_addr_def.  What is here rewrites with them and
     closes by arithmetic, and the cheat is behind it until the
     proof is written.  A MESON over them is what the next round
     adds; it costs a load ten minutes to have it in every attempt
     and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_def; word_ml_inv_def;
       abs_ml_inv_def; bc_stack_ref_inv_def; v_inv_def;
       word_addr_def] THEN
     TRY ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Thunk_inlined = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,(w:'a word_loc))
  :: vars) /\
     ((?l1 l2. w = Loc l1 l2) \/ (?w1. w = wordLang_Word w1 /\
       ~(FAPPLY w1 0))) /\
     lookup p refs = SOME (Thunk ev z) /\
     good_dimindex (:'a) ==>
       ev = Evaluated /\
       memory_rel c be ts refs sp st m dm ((z,w) :: vars)`),
(* the invariant of the source names memory_rel_Thunk_IMP for the
   first conjunct and the chain of the definitions of the invariant
   for the second.  Here the first is that lemma, whose other case
   has the value a word with its lowest bit set and the hypothesis
   says it has not; and the second is the invariant rebuilt on the
   same heap, the same roots and the same two maps, where the
   clause of v_inv that inlines the thunk gives the root of its
   value.  What the rebuilding leaves is that the timestamps and
   the blocks of the new stack are those of the old one and that a
   reference the value reaches was reached by the pointer *)
  ((* a RefPtr is not a Block, so it has no timestamps of its own *)
  let vats_refptr = prove
   (`!bl p. v_all_ts (RefPtr bl p:dataSem_v) = []`,
    REPEAT GEN_TAC THEN
    GEN_REWRITE_TAC LAND_CONV [v_all_ts_def] THEN
    MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
  let no_ts = prove
   (`!t bl p. ~MEM (t:num) (v_all_ts (RefPtr bl p:dataSem_v))`,
    REWRITE_TAC[vats_refptr; MEM]) in
  (* so a stack with a RefPtr in front has no more timestamps
     than the same stack with any other value in front *)
  let all_ts_sub = prove
   (`!refs bl p vs (y:dataSem_v).
       all_ts refs (CONS (RefPtr bl p) vs) SUBSET
       all_ts refs (CONS y vs)`,
    REPEAT GEN_TAC THEN REWRITE_TAC[all_ts_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[SUBSET; IN_ELIM_THM; MEM] THEN
    MESON_TAC[no_ts]) in
  (* a reference that the value of a thunk reaches is one that the
     pointer to the thunk reaches, in one step of ref_edge more *)
  let reach_thunk = prove
   (`!refs p ev z vs n bl.
       lookup p refs = SOME (Thunk ev z) /\
       reachable_refs (CONS z vs) refs n ==>
       reachable_refs (CONS (RefPtr bl p:dataSem_v) vs) refs n`,
    REPEAT GEN_TAC THEN REWRITE_TAC[reachable_refs_def] THEN
    DISCH_THEN (CONJUNCTS_THEN2 ASSUME_TAC
      (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC)) THEN
    FIRST_X_ASSUM (fun mm ->
      DISJ_CASES_THEN2 SUBST_ALL_TAC ASSUME_TAC
        (REWRITE_RULE[MEM] mm)) THENL
     [EXISTS_TAC `RefPtr bl p:dataSem_v` THEN
      EXISTS_TAC `p:num` THEN
      REWRITE_TAC[MEM; get_refs_def] THEN
      MATCH_MP_TAC (CONJUNCT2 (SPEC_ALL RTC_RULES)) THEN
      FIRST_ASSUM (fun rt ->
        if hd_is "RTC" (concl rt)
        then EXISTS_TAC (rand (rator (concl rt))) else fail()) THEN
      ASM_REWRITE_TAC[ref_edge_def] THEN MATCH_REDUCE_TAC THEN
      REWRITE_TAC[get_refs_def; MAP; FLAT; APPEND_NIL] THEN
      FIRST_ASSUM ACCEPT_TAC;
      ASM_REWRITE_TAC[MEM] THEN ASM_MESON_TAC[]]) in
  (* the thunk is evaluated: of the two cases of
     memory_rel_Thunk_IMP the one that does not say so has the
     value a word with its lowest bit set, and the hypothesis
     says it is a code pointer or has that bit clear *)
  let ev_tac =
    FIRST_ASSUM (fun mr -> FIRST_ASSUM (fun lk ->
      FIRST_ASSUM (fun gd ->
        DISJ_CASES_THEN STRIP_ASSUME_TAC
          (MATCH_MP memory_rel_Thunk_IMP
            (CONJ mr (CONJ lk gd)))))) THEN
    (FIRST_ASSUM ACCEPT_TAC ORELSE
     (REPEAT SUBST_LHS_TAC THEN
      RULE_ASSUM_TAC (REWRITE_RULE[distinctness "word_loc";
                                   injectivity "word_loc"]) THEN
      TRY (FIRST_X_ASSUM CONTR_TAC) THEN
      REPEAT SUBST_LHS_TAC THEN CONTRA_TAC)) in
  (* the conjuncts of the invariant that are what they were *)
  let close_tac =
    REPEAT CONJ_TAC THEN REWRITE_TAC[MAP] THEN
    TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    TRY (REWRITE_TAC[MAP; ALL2] THEN ASM_REWRITE_TAC[] THEN
         NO_TAC) in
  (* the two maps of the invariant are the two of the clause of
     v_inv that the value of the thunk is related by *)
  let exists_f_tf =
    FIRST_ASSUM (fun vi ->
      let c = concl vi in
      if hd_is "v_inv" c then
        let tup = el 3 (snd (strip_comb c)) in
        let _,r1 = dest_pair tup in
        let f,r2 = dest_pair r1 in
        let tf,_ = dest_pair r2 in
        MAP_EVERY EXISTS_TAC [f; tf]
      else fail()) in
  (* the invariant with the value of the thunk in place of the
     pointer to it: the same heap, the same roots and the same
     two maps.  Of the three clauses of v_inv for a RefPtr the
     first says the reference is not a thunk, which the lookup
     denies, and the second has a ThunkBlock in the heap and the
     pointer to it for a root, whose word is odd (get_addr_0) and
     the hypothesis says the value is not; so the third is the
     one, and it gives the root of the value of the thunk *)
  let rebuild_tac =
    FIRST_X_ASSUM (fun mr ->
      if hd_is "memory_rel" (concl mr)
      then STRIP_ASSUME_TAC (REWRITE_RULE[memory_rel_def;
             word_ml_inv_def; abs_ml_inv_def;
             bc_stack_ref_inv_def] mr)
      else fail()) THEN
    SPLIT_ROOTS_TAC THEN
    V_INV_TAC v_inv_def THEN
    TRY (FIRST_X_ASSUM (fun eq ->
      if (try is_eq (concl eq) && is_var (rand (concl eq)) &&
              hd_is "get_addr" (lhs (concl eq))
          with Failure _ -> false)
      then SUBST_ALL_TAC (SYM eq) else fail())) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[get_addr_0]) THEN
    TRY (FIRST_X_ASSUM CONTR_TAC) THEN
    TRY (FIRST_ASSUM (fun neg ->
      let nt = (try let _,bod = strip_forall (concl neg) in
                    is_neg bod && hd_is "sptree_lookup"
                      (lhs (dest_neg bod))
                with Failure _ -> false) in
      if nt then
        FIRST_ASSUM (fun lk ->
          if (try hd_is "sptree_lookup" (lhs (concl lk))
              with Failure _ -> false)
          then MP_TAC neg THEN
               REWRITE_TAC[lk; injectivity "option";
                           injectivity "bvlSem_ref"] THEN
               MESON_TAC[]
          else fail())
      else fail())) THEN
    TRY (FIRST_ASSUM (fun lk1 -> FIRST_ASSUM (fun lk2 ->
      if concl lk1 = concl lk2 then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[injectivity "option";
                          injectivity "bvlSem_ref"]
                          (TRANS (SYM lk1) lk2))))) THEN
    REPEAT SUBST_LHS_TAC THEN
    REWRITE_TAC[memory_rel_def; word_ml_inv_def; abs_ml_inv_def;
                bc_stack_ref_inv_def] THEN
    ASM_EXISTS_TAC THEN close_tac THEN
    TRY ASM_EXISTS_TAC THEN close_tac THEN
    TRY exists_f_tf THEN close_tac THEN
    FIRST
     [(* the timestamps of the new stack are the old ones *)
      FIRST_ASSUM (fun sb ->
        if hd_is "SUBSET" (concl sb) &&
           hd_is "all_ts" (rand (concl sb))
        then MATCH_MP_TAC SUBSET_TRANS THEN
             EXISTS_TAC (rand (concl sb)) THEN
             CONJ_TAC THENL
              [ACCEPT_TAC sb; MATCH_ACCEPT_TAC all_ts_sub]
        else fail());
      (* and so are its blocks *)
      FIRST_ASSUM (fun lk -> FIRST_ASSUM (fun bu ->
        ACCEPT_TAC (MATCH_MP (GEN_ALL blocks_unique_Thunk)
                      (CONJ lk bu))));
      (* and a reference it reaches was reached before *)
      GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
      CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
      MATCH_MP_TAC reach_thunk THEN ASM_EXISTS_TAC THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC] in
  STRIP_TAC THEN CONJ_TAC THENL
   [ev_tac; rebuild_tac; ev_tac; rebuild_tac]));;

(* HOL4 data_to_word_memoryProofScript.sml:11655-11657: the ML values
   that the definitions below antiquote *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let get_byte_set_byte_alt = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) /\ ~(w = v) /\ byte_align w = byte_align v /\
      get_byte w s be = x ==>
      get_byte w (set_byte v b (s:'a word) be) be = x`),
  (REPEAT STRIP_TAC THEN ASM_MESON_TAC[get_byte_set_byte_diff]));;

(* the port's own: the address of a byte of the first word of a
   memory is below the bytes in a word, and the facts that the
   proofs about such an address need of it -- that it is aligned to
   the word, and that two of them are different words *)

(* LOG2 of a numeral, by the equation that defines it *)
let LOG2_RED =
  REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                       NUM_REDUCE_CONV THENC REWRITE_CONV[]));;

(* the slice that takes the bits from p up is the word shifted down
   by p and up again *)
let slice_shl = prove
 (`!p (w:(N)word).
     word_slice (dimindex (:N) - 1) p w = word_shl (word_ushr w p) p`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
              BIT_WORD_SHL; BIT_WORD_SUBWORD; BIT_WORD_USHR] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  ASM_CASES_TAC `p:num <= i` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
    `i - p < MIN ((dimindex (:N) - 1 + 1) - p) (dimindex (:N))`
    (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
    COND_CASES_TAC THEN ASM_ARITH_TAC;
    REWRITE_TAC[ARITH_RULE `p + (i - p) = (i - p) + p`]]);;

(* a number below two to the p has nothing left when it is shifted
   down by p *)
let ushr_small = prove
 (`!x p. x < 2 EXP p /\ p <= dimindex (:'a)
         ==> word_ushr ((n2w x):'a word) p = n2w 0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[GSYM VAL_EQ_0; VAL_WORD_USHR; VAL_WORD] THEN
  MATCH_MP_TAC DIV_LT THEN
  MP_TAC (SPECL [`x:num`; `2 EXP dimindex (:'a)`] MOD_LE) THEN
  ASM_ARITH_TAC);;

(* so the address of a byte of the first word is aligned to it *)
let align_small = prove
 (`!x. good_dimindex (:'a) /\ x < dimindex (:'a) DIV 8
       ==> byte_align ((n2w x):'a word) = n2w 0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[byte_align_def; align_def; slice_shl] THEN
  SUBGOAL_THEN `word_ushr ((n2w x):'a word)
                  (LOG2 (dimindex (:'a) DIV 8)) = n2w 0`
    SUBST1_TAC THENL
   [MATCH_MP_TAC ushr_small THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN (fun eq ->
      RULE_ASSUM_TAC(REWRITE_RULE[eq]) THEN SUBST1_TAC eq) o
      REWRITE_RULE[good_dimindex_def]) THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC;
    REWRITE_TAC[word_shl; VAL_WORD_0; MULT_CLAUSES]]);;

(* and two numbers below the width of a word are different words *)
let n2w_ne = prove
 (`!a b. a < 2 EXP dimindex (:'a) /\ b < 2 EXP dimindex (:'a) /\
         ~(a = b) ==> ~(((n2w a):'a word) = n2w b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[GSYM VAL_EQ; VAL_WORD] THEN
  ASM_SIMP_TAC[MOD_LT]);;

let ne_small = prove
 (`!a b. good_dimindex (:'a) /\ a < dimindex (:'a) DIV 8 /\
         b < dimindex (:'a) DIV 8 /\ ~(a = b)
         ==> ~(((n2w a):'a word) = n2w b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC n2w_ne THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN (fun eq ->
    RULE_ASSUM_TAC(REWRITE_RULE[eq]) THEN SUBST1_TAC eq) o
    REWRITE_RULE[good_dimindex_def]) THEN
  CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let get_byte_bytes_to_word = prove
 (cake_as_vars (fun () ->
    `!zs (t:'a word).
        i < LENGTH zs /\ i < 2 EXP k /\
        2 EXP k = dimindex (:'a) DIV 8 /\ good_dimindex (:'a) ==>
        get_byte (n2w i) (bytes_to_word (2 EXP k) (n2w 0) zs t
          be) be = EL i zs`),
  (* the source takes the list of bytes apart into the four or the
     eight bytes of a word.  Here one lemma does it for every
     length, by the induction of bytes_to_word over the list: the
     byte at the address of the first set_byte is the head of the
     list (good_dimindex_get_byte_set_byte), and a byte further on
     is the byte of the word that the rest of the list makes
     (get_byte_set_byte_alt, whose two addresses align to the same
     word by align_small).  The lemma is about the word at an
     offset, because that is what the recursive call of
     bytes_to_word is about *)
  (let aux = prove
    (`!ls n m i (t:'a word) be'.
        i < n /\ i < LENGTH ls /\ m + n <= dimindex (:'a) DIV 8 /\
        good_dimindex (:'a)
        ==> get_byte (n2w (m + i))
              (bytes_to_word n (n2w m) ls t be') be' = EL i ls`,
     LIST_INDUCT_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[LENGTH; CONJUNCT1 LT];
       ALL_TAC] THEN
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC (SPEC `n:num` num_CASES) THENL
      [REWRITE_TAC[CONJUNCT1 LT]; ALL_TAC] THEN
     REWRITE_TAC[LENGTH] THEN
     STRUCT_CASES_TAC (SPEC `i:num` num_CASES) THENL
      [(* the byte that the first set_byte of the word sets *)
       REWRITE_TAC[ADD_CLAUSES; EL; HD] THEN
       STRIP_TAC THEN
       ONCE_REWRITE_TAC[bytes_to_word_def] THEN
       REWRITE_TAC[NOT_SUC; SUC_SUB1] THEN MATCH_REDUCE_TAC THEN
       FIRST_ASSUM (fun gd ->
         MATCH_ACCEPT_TAC (GEN_ALL
           (MATCH_MP good_dimindex_get_byte_set_byte gd)));
       (* or a byte further on, which the set_byte does not touch *)
       REWRITE_TAC[EL; TL] THEN
       STRIP_TAC THEN
       ONCE_REWRITE_TAC[bytes_to_word_def] THEN
       REWRITE_TAC[NOT_SUC; SUC_SUB1] THEN MATCH_REDUCE_TAC THEN
       (* both addresses are bytes of the same word *)
       W(fun (asl,w) ->
         let gb = find_term (hd_is "get_byte") w in
         let a1 = rand (el 0 (snd (strip_comb gb))) in
         let sb = find_term (hd_is "set_byte") w in
         let a2 = rand (el 0 (snd (strip_comb sb))) in
         let dd = find_term (hd_is "DIV")
                    (list_mk_conj (map (concl o snd) asl)) in
         MAP_EVERY (fun a ->
           SUBGOAL_THEN (mk_binop `(<):num->num->bool` a dd)
             ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) [a1; a2]) THEN
       MATCH_MP_TAC (GEN_ALL get_byte_set_byte_alt) THEN
       REPEAT CONJ_TAC THENL
        [FIRST_ASSUM ACCEPT_TAC;
         MATCH_MP_TAC ne_small THEN
         REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
         ASM_ARITH_TAC;
         ASM_SIMP_TAC[align_small];
         REWRITE_TAC[GSYM WORD_ADD] THEN
         ONCE_REWRITE_TAC[ARITH_RULE `m + SUC j = (m + 1) + j`] THEN
         FIRST_X_ASSUM MATCH_MP_TAC THEN
         REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
         ASM_ARITH_TAC]]) in
   REPEAT STRIP_TAC THEN
   W(fun (asl,w) ->
     let gargs = snd (strip_comb (lhs w)) in
     let i = rand (el 0 gargs) in
     let bargs = snd (strip_comb (el 1 gargs)) in
     MP_TAC (SPECL [el 2 bargs; el 0 bargs; `0`; i; el 3 bargs;
                    el 2 gargs] aux)) THEN
   REWRITE_TAC[ADD_CLAUSES] THEN
   DISCH_THEN MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   ASM_ARITH_TAC));;

(* [local] *)
let MOD_MULT_MOD_LEMMA = prove
 (`k MOD n = 0 /\ x MOD n = t /\ 0 < k /\ 0 < n /\ n <= k ==>
     x MOD k MOD n = t`,
  (* n divides k, so k is n times the quotient and MOD_MOD gives
     the modulus of the modulus *)
  (STRIP_TAC THEN
   SUBGOAL_THEN `?q. k:num = n * q` (CHOOSE_THEN SUBST_ALL_TAC) THENL
    [EXISTS_TAC `k DIV n` THEN
     MP_TAC(SPECL [`k:num`; `n:num`] DIVISION) THEN
     ASM_SIMP_TAC[ARITH_RULE `0 < n ==> ~(n = 0)`] THEN
     ASM_REWRITE_TAC[ADD_CLAUSES] THEN MESON_TAC[MULT_SYM];
     ASM_REWRITE_TAC[MOD_MOD]]));;

let w2n_add_byte_align_lemma = prove
 (`good_dimindex (:'a) ==>
    w2n (a' + byte_align (a:'a word)) MOD (dimindex (:'a) DIV 8) =
    w2n a' MOD (dimindex (:'a) DIV 8)`,
  (* the alignment of a word is the word shifted down and up again,
     so its lowest bits are clear and adding it does not change the
     value by the bytes in a word -- which is two to the shift, as
     the two good dimindexes give *)
  (let LOG2_RED =
     REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                          NUM_REDUCE_CONV THENC REWRITE_CONV[])) in
   let slice_shl = prove
    (`!p (w:(N)word).
        word_slice (dimindex (:N) - 1) p w =
        word_shl (word_ushr w p) p`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
                 BIT_WORD_SHL; BIT_WORD_SUBWORD; BIT_WORD_USHR] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THEN ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN
       `i - p < MIN ((dimindex (:N) - 1 + 1) - p) (dimindex (:N))`
       (fun th -> REWRITE_TAC[th]) THENL
      [REWRITE_TAC[ARITH_RULE
         `MIN a b = if a <= b then a else b`] THEN
       COND_CASES_TAC THEN ASM_ARITH_TAC;
       REWRITE_TAC[ARITH_RULE `p + (i - p) = (i - p) + p`]]) in
   let main = prove
    (`!p d (x:(N)word) y. d = 2 EXP p /\ p <= dimindex (:N)
        ==> w2n (x + word_shl y p) MOD d = w2n x MOD d`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC ASSUME_TAC) THEN
     REWRITE_TAC[VAL_WORD_ADD; VAL_WORD_SHL; MOD_MOD_EXP_MIN] THEN
     ASM_SIMP_TAC[ARITH_RULE `p <= d ==> MIN d p = p`] THEN
     ONCE_REWRITE_TAC[GSYM MOD_ADD_MOD] THEN
     REWRITE_TAC[MOD_MOD_EXP_MIN] THEN
     ASM_SIMP_TAC[ARITH_RULE `p <= d ==> MIN d p = p`] THEN
     REWRITE_TAC[MOD_MULT; ADD_CLAUSES; MOD_MOD_REFL]) in
   DISCH_TAC THEN
   REWRITE_TAC[byte_align_def; align_def;
               slice_shl] THEN
   MATCH_MP_TAC main THEN
   FIRST_ASSUM(DISJ_CASES_THEN SUBST1_TAC o
     REWRITE_RULE[good_dimindex_def]) THEN
   CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED THEN
   CONV_TAC NUM_REDUCE_CONV));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let get_byte_byte_align = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) ==>
      get_byte (a' + byte_align a) w be = get_byte a' (w:'a word)
        be`),
  (* which byte an address picks out is its remainder by the bytes
     in a word, which adding a byte aligned word does not change *)
  (DISCH_TAC THEN
   REWRITE_TAC[get_byte_def] THEN
   AP_TERM_TAC THEN AP_TERM_TAC THEN
   REWRITE_TAC[byte_index_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_SIMP_TAC[w2n_add_byte_align_lemma]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let get_byte_eq = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) /\ a = byte_align a + a' ==>
      get_byte a w be = get_byte a' (w:'a word) be`),
  (* the byte that an address selects does not change when the
     address is taken modulo the word it is in *)
  (STRIP_TAC THEN
   FIRST_X_ASSUM(fun th -> ONCE_REWRITE_TAC[th]) THEN
   ONCE_REWRITE_TAC[WORD_ADD_SYM] THEN
   FIRST_ASSUM(fun gd ->
     MATCH_ACCEPT_TAC(MATCH_MP get_byte_byte_align gd))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let write_bytes_same = prove
 (cake_as_vars (fun () ->
    `!ws b1 b2.
     (!n. n < LENGTH (ws:('a word) list) * (dimindex (:'a) DIV 8)
       ==> n < LENGTH b1 /\ n < LENGTH b2 /\ EL n b1 = EL n b2) ==>
       write_bytes b1 ws be = write_bytes b2 ws be`),
  (* the words come out the same because every byte that one of
     them reads is the same in the two lists: the head word reads
     the first bytes (the bytes_to_word of a list of bytes that
     agree up to the count), and the tail reads the rest, which the
     DROP shifts by the count *)
  (let btw = prove
    (`!k a b1 b2 (w:(N)word) be.
        (!n. n < k ==> n < LENGTH b1 /\ n < LENGTH b2 /\
             EL n b1 = EL n b2)
        ==> bytes_to_word k a b1 w be = bytes_to_word k a b2 w be`,
     INDUCT_TAC THEN REPEAT GEN_TAC THENL
      [REWRITE_TAC[bytes_to_word_def]; ALL_TAC] THEN
     DISCH_TAC THEN
     GEN_REWRITE_TAC BINOP_CONV [bytes_to_word_def] THEN
     REWRITE_TAC[NOT_SUC] THEN
     FIRST_ASSUM(MP_TAC o SPEC `0`) THEN
     REWRITE_TAC[LT_0] THEN STRIP_TAC THEN
     MP_TAC(ISPEC `b1:(word8)list` list_CASES) THEN
     DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
       (X_CHOOSE_THEN `h1:word8`
         (X_CHOOSE_THEN `t1:(word8)list` SUBST_ALL_TAC))) THENL
      [ASM_MESON_TAC[LENGTH; LT_REFL]; ALL_TAC] THEN
     MP_TAC(ISPEC `b2:(word8)list` list_CASES) THEN
     DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC
       (X_CHOOSE_THEN `h2:word8`
         (X_CHOOSE_THEN `t2:(word8)list` SUBST_ALL_TAC))) THENL
      [ASM_MESON_TAC[LENGTH; LT_REFL]; ALL_TAC] THEN
     RULE_ASSUM_TAC(REWRITE_RULE[EL; HD]) THEN
     ASM_REWRITE_TAC[] THEN AP_THM_TAC THEN AP_TERM_TAC THEN
     REWRITE_TAC[SUC_SUB1] THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN
     X_GEN_TAC `n:num` THEN DISCH_TAC THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `SUC n`) THEN
     ASM_REWRITE_TAC[LT_SUC; LENGTH; EL; TL] THEN
     ASM_ARITH_TAC) in
   let lt1 = ARITH_RULE `!n m b:num. n < b ==> n < m * b + b` in
   let lt2 = ARITH_RULE
     `!n m b:num. n < m * b ==> n + b < m * b + b` in
   let lt3 = ARITH_RULE `!n b l:num. n + b < l ==> n < l - b` in
   LIST_INDUCT_TAC THEN
   REWRITE_TAC[write_bytes_def] THEN
   REPEAT GEN_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[CONS_11] THEN
   DISCH_TAC THEN CONJ_TAC THENL
    [MATCH_MP_TAC btw THEN
     X_GEN_TAC `n:num` THEN DISCH_TAC THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN
     REWRITE_TAC[LENGTH; MULT] THEN
     MATCH_MP_TAC lt1 THEN ASM_REWRITE_TAC[];
     FIRST_X_ASSUM MATCH_MP_TAC THEN
     X_GEN_TAC `n:num` THEN DISCH_TAC THEN
     REWRITE_TAC[LENGTH_DROP] THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `n + dimindex (:'a) DIV 8`) THEN
     ANTS_TAC THENL
      [REWRITE_TAC[LENGTH; MULT] THEN
       MATCH_MP_TAC lt2 THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     STRIP_TAC THEN ASM_SIMP_TAC[EL_DROP] THEN
     REPEAT CONJ_TAC THEN TRY(MATCH_MP_TAC lt3) THEN
     ASM_REWRITE_TAC[]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let set_byte_bytes_to_word = prove
 (cake_as_vars (fun () ->
    `i < LENGTH ls /\ i < 2 EXP k /\ 2 EXP k = dimindex (:'a) DIV 8 /\
     good_dimindex (:'a) ==>
     set_byte (n2w i) b (bytes_to_word (2 EXP k) (n2w 0) ls t be)
       be =
     bytes_to_word (2 EXP k) ((n2w 0):'a word) (LUPDATE b i ls) t
       be`),
  (* the source takes the list of bytes apart into the four or the
     eight bytes of a word and sorts the set_bytes of each case.
     Here one lemma does it for every length, by the induction of
     bytes_to_word over the list: the byte that the first set_byte
     of the word sets is the head, and a byte further on commutes
     with it (set_byte_sort), where the induction hypothesis sets it
     in the rest.  The lemma is about the word at an offset, because
     that is what the recursive call of bytes_to_word is about, and
     it is stated with the type variable of the statement, because
     SPECL instantiates the term variables of a theorem and not its
     types *)
  (let aux = prove
    (`!ls n m i b (t:'a word) be'.
        i < n /\ i < LENGTH ls /\ m + n <= dimindex (:'a) DIV 8 /\
        good_dimindex (:'a)
        ==> set_byte (n2w (m + i)) b
              (bytes_to_word n (n2w m) ls t be') be' =
            bytes_to_word n (n2w m) (LUPDATE b i ls) t be'`,
     LIST_INDUCT_TAC THENL
      [REPEAT GEN_TAC THEN REWRITE_TAC[LENGTH; CONJUNCT1 LT];
       ALL_TAC] THEN
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC (SPEC `n:num` num_CASES) THENL
      [REWRITE_TAC[CONJUNCT1 LT]; ALL_TAC] THEN
     REWRITE_TAC[LENGTH] THEN
     STRUCT_CASES_TAC (SPEC `i:num` num_CASES) THENL
      [(* the byte that the first set_byte of the word sets *)
       REWRITE_TAC[ADD_CLAUSES; LUPDATE] THEN
       STRIP_TAC THEN
       ONCE_REWRITE_TAC[bytes_to_word_def] THEN
       REWRITE_TAC[NOT_SUC; SUC_SUB1] THEN MATCH_REDUCE_TAC THEN
       ONCE_REWRITE_TAC[GEN_ALL set_byte_sort] THEN
       REWRITE_TAC[];
       (* or a byte further on, where the two set_bytes commute *)
       REWRITE_TAC[LUPDATE; NOT_SUC; SUC_SUB1] THEN
       STRIP_TAC THEN
       ONCE_REWRITE_TAC[bytes_to_word_def] THEN
       REWRITE_TAC[NOT_SUC; SUC_SUB1] THEN MATCH_REDUCE_TAC THEN
       ONCE_REWRITE_TAC[GEN_ALL set_byte_sort] THEN
       COND_CASES_TAC THENL
        [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
       COND_CASES_TAC THENL
        [ALL_TAC;
         SUBGOAL_THEN `F` CONTR_TAC THEN
         FIRST_X_ASSUM MP_TAC THEN ASM_REWRITE_TAC[] THEN
         ASM_ARITH_TAC] THEN
       AP_THM_TAC THEN AP_TERM_TAC THEN
       REWRITE_TAC[GSYM WORD_ADD] THEN
       ONCE_REWRITE_TAC[ARITH_RULE `m + SUC j = (m + 1) + j`] THEN
       FIRST_X_ASSUM MATCH_MP_TAC THEN
       REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
       ASM_ARITH_TAC]) in
   REPEAT STRIP_TAC THEN
   W(fun (asl,w) ->
     let sargs = snd (strip_comb (lhs w)) in
     let i = rand (el 0 sargs) in
     let bb = el 1 sargs in
     let bargs = snd (strip_comb (el 2 sargs)) in
     MP_TAC (SPECL [el 2 bargs; el 0 bargs; `0`; i; bb; el 3 bargs;
                    el 3 sargs] aux)) THEN
   REWRITE_TAC[ADD_CLAUSES] THEN
   DISCH_THEN MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   ASM_ARITH_TAC));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let heap_in_memory_store_UpdateByte = prove
 (cake_as_vars (fun () ->
    `heap_in_memory_store heap a sp sp1 gens c s m dm limit /\
     heap = ha ++ [Bytes be fl bs ws] ++ hb /\ i < LENGTH bs /\
     ad = curr + bytes_in_word + n2w i + (bytes_in_word:'a word) *
       n2w (heap_length ha) /\
     FLOOKUP s CurrHeap = SOME (wordLang_Word curr) /\
     m (byte_align ad) = wordLang_Word w /\ good_dimindex (:'a) ==>
     heap_in_memory_store (ha ++ [Bytes be fl (LUPDATE b i bs) ws]
       ++ hb)
     a sp sp1 gens c s
     ((byte_align ad =+ wordLang_Word (set_byte ad b w be)) m) dm
       limit`),
  (* the attempt: the proof of the source names
     heap_in_memory_store_def, heap_length_APPEND, byte_aligned_def,
     byte_align_def, align_def, bytes_in_word_def.  What is here
     rewrites with them and closes by arithmetic, and the cheat is
     behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[heap_in_memory_store_def;
       heap_length_APPEND; byte_aligned_def; byte_align_def;
       align_def; bytes_in_word_def] THEN
     TRY ASM_ARITH_TAC)));;

let hide_memory_rel_def = cake_define
  `hide_memory_rel = memory_rel`;;

let hide_heap_in_memory_store_def = cake_define
  `hide_heap_in_memory_store = heap_in_memory_store`;;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_ByteArray_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,(v:'a word_loc))
  :: vars) /\
     lookup p refs = SOME (ByteArray fl vals) /\ good_dimindex
       (:'a) ==>
     (?w a x l.
       v = wordLang_Word w /\ FAPPLY w 0 /\
       make_byte_header c fl (LENGTH vals) = x /\
       ~(word_bit 3 x) /\ (word_bit 4 x <=> ~fl) /\ word_bit 2 x /\
       get_real_simple_addr c st w = SOME a /\
       get_real_addr c st w = SOME a /\
       m a = wordLang_Word x /\ a IN dm /\
       (!i. i < LENGTH vals ==>
            mem_load_byte_aux m dm be (a + bytes_in_word + n2w i) =
            SOME (EL i vals)) /\
       (!i w. i < LENGTH vals ==>
         (let addr' = a + bytes_in_word + n2w i in
         memory_rel c be ts (insert p (ByteArray fl (LUPDATE w i
           vals)) refs) sp st
           ((byte_align addr' =+
             wordLang_Word (set_byte addr' w (theWord (m
               (byte_align addr'))) be)) m) dm
             ((RefPtr bl p,v) :: vars))) /\
       (if dimindex (:'a) = 32 then
         LENGTH vals + 4 < 2 EXP (dimindex (:'a) - 3) /\
         (x >>> (dimindex (:'a) - data_to_word_config_len_size c -
           2) = n2w (LENGTH vals + 4)) else
         LENGTH vals + 8 < 2 EXP (dimindex (:'a) - 3) /\
         (x >>> (dimindex (:'a) - data_to_word_config_len_size c
           - 3) = n2w (LENGTH vals + 8))))`),
  (* the attempt: the proof of the source names hide_memory_rel_def,
     make_byte_header_def, memory_rel_def, word_ml_inv_def,
     bc_stack_ref_inv_def, v_inv_def.  What is here rewrites with
     them and closes by arithmetic, and the cheat is behind it until
     the proof is written.  A MESON over them is what the next round
     adds; it costs a load ten minutes to have it in every attempt
     and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[hide_memory_rel_def; make_byte_header_def;
       memory_rel_def; word_ml_inv_def; bc_stack_ref_inv_def;
       v_inv_def] THEN
     TRY ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_RefPtr_IMP_lemma = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,(v:'a word_loc))
  :: vars) ==>
      (?res. lookup p refs = SOME res)`),
  (* every rule of v_inv for a RefPtr says that the pointer is in
     the refs: the first through the domain of f, the other two
     with the lookup itself *)
  (MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN
   ASM_MESON_TAC[domain_lookup; SUBSET]));;

(* a compare-by-pointer RefPtr can never point at a MutBlock: v_inv's RefPtr
   case demands ~b when the ref is a MutBlock *)
(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_MutBlock_IMP_F = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr T p,(v:'a word_loc)) ::
  vars) /\
     lookup p refs = SOME (bvlSem_MutBlock tg fin ls cv rs) ==> F`),
  (* a RefPtr T is no MutBlock: every rule of v_inv that gives one
     a root says so *)
  (MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN ASM_MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_RefPtr_T_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr T p,v) :: vars) /\
     good_dimindex (:'a) ==>
       (?w a x.
         v = wordLang_Word w /\ FAPPLY w 0 /\
         (
          // (word_bit 4 x ⇒ word_bit 2 x) ∧
          word_bit 3 x <=> ~(word_bit 2 x)) /\
         get_real_addr c st w = SOME a /\
         get_real_simple_addr c st w = SOME a /\
         m a = wordLang_Word (x:'a word) /\ a IN dm)`),
  (* a RefPtr T is no thunk (the rule of v_inv for one asks for a
     RefPtr F) and no MutBlock, so the four cases of the value in
     the refs are the two arrays and two contradictions *)
  (STRIP_TAC THEN
   FIRST_ASSUM(fun mr ->
     MP_TAC(MATCH_MP memory_rel_RefPtr_IMP_lemma mr)) THEN
   STRIP_TAC THEN CASES_ON_NAME "res" THEN
   ALL_INST3 memory_rel_ValueArray_IMP THEN
   ALL_INST3 memory_rel_ByteArray_IMP THEN
   ALL_INST3 memory_rel_Thunk_IMP THEN
   ALL_INST2 memory_rel_MutBlock_IMP_F THEN
   RULE_ASSUM_TAC(REWRITE_RULE[]) THEN
   TRY(FIRST_X_ASSUM CONTR_TAC) THEN
   ASM_MESON_TAC[]));;

(* the MutBlock exclusion is needed: a MutBlock is laid out with a BlockTag
   header, whose bits 2 and 3 are both clear, so the conclusion below fails *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_RefPtr_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,v) :: vars) /\
     good_dimindex (:'a) /\
     (!t a. ~(lookup p refs = SOME (Thunk t a))) /\
     (!tg fin l cv rs. ~(lookup p refs = SOME (bvlSem_MutBlock tg
       fin l cv rs))) ==>
       (?w a x.
         v = wordLang_Word w /\ FAPPLY w 0 /\
         (
          // (word_bit 4 x ⇒ word_bit 2 x) ∧
          word_bit 3 x <=> ~(word_bit 2 x)) /\
         get_real_addr c st w = SOME a /\
         get_real_simple_addr c st w = SOME a /\
         m a = wordLang_Word (x:'a word) /\ a IN dm)`),
  (* the pointer has a value in the refs, which is a ValueArray or
     a ByteArray because the hypotheses exclude the other two *)
  (STRIP_TAC THEN
   FIRST_ASSUM(fun mr ->
     MP_TAC(MATCH_MP memory_rel_RefPtr_IMP_lemma mr)) THEN
   STRIP_TAC THEN CASES_ON_NAME "res" THEN
   TRY(FIRST_X_ASSUM(fun th -> FIRST_ASSUM(fun a ->
     CONTR_TAC(MP (NOT_ELIM(SPEC_ALL th)) a)))) THEN
   ALL_INST3 memory_rel_ValueArray_IMP THEN
   ALL_INST3 memory_rel_ByteArray_IMP THEN
   ASM_MESON_TAC[]));;

(* the port's own: the bit of the header that tells an evaluated
   thunk from the pattern the statement rules out.  HOL4 gives the
   fifth bit to CART_EQ and lets EVAL_TAC do the rest; here
   and60_ne24 says what that comes to, and dim5 is the word size
   being wide enough for the bit to be there at all *)

let and60_ne24 = prove
 (`!(x:'a word). 5 < dimindex (:'a) /\ word_bit 5 x
    ==> ~((x && (n2w 60)) = n2w 24)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM (MP_TAC o SPEC `5` o
    REWRITE_RULE[WORD_EQ_BITS_ALT]) THEN
  ASM_REWRITE_TAC[BIT_WORD_AND; BIT_WORD] THEN
  CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[]);;

let dim5 = prove
 (`good_dimindex (:'a) ==> 5 < dimindex (:'a)`,
  REWRITE_TAC[good_dimindex_def] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_RefPtr_gen_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,v) :: vars) /\
     good_dimindex (:'a) ==>
     (?r. lookup p refs = SOME r /\
     (match r with Thunk Evaluated x ->
       (!w. v = wordLang_Word w /\ FAPPLY w 0 ==>
          (?a x. get_real_addr c st w = SOME a /\
                m a = wordLang_Word x /\ a IN dm /\ ~((x && (n2w
                  0b111100)) = n2w ((0 + 6) * 4)))) |
       // a MutBlock carries a BlockTag header, for which the bit pattern below
       // does not hold; this theorem has no users, so the case is left trivial
       bvlSem_MutBlock _61 _62 _63 _64 _65 -> T | _66 ->
       (?w a x.
         v = wordLang_Word w /\ FAPPLY w 0 /\
         (
          // (word_bit 4 x ⇒ word_bit 2 x) ∧
          word_bit 3 x <=> ~(word_bit 2 x)) /\
         get_real_addr c st w = SOME a /\
         get_real_simple_addr c st w = SOME a /\
         m a = wordLang_Word (x:'a word) /\ a IN dm)))`),
(* the proof of the source takes the kind of the reference out of
   the lookup (memory_rel_RefPtr_IMP_lemma) and then has a case for
   each: an array of values has bit 3 of its header set and bit 2
   clear, an array of bytes the other way round, a MutBlock is the
   case the statement leaves trivial, and a thunk is the one real
   case.  For an evaluated one memory_rel_Thunk_IMP either says
   what the pattern wants or says that bit 5 of the header is set,
   which says it too (and60_ne24); for one that is not evaluated
   the first of its two cases says it is, so the second is the one *)
  ((* the lemma of a kind of reference, at this memory and this
     lookup *)
  let use_lemma th =
    FIRST_ASSUM (fun mr -> FIRST_ASSUM (fun lk ->
      FIRST_ASSUM (fun gd ->
        STRIP_ASSUME_TAC (MATCH_MP th (CONJ mr (CONJ lk gd)))))) in
  (* the word of the value, the address it points at and what the
     memory holds there, out of the assumptions *)
  let pick n =
    W(fun (asl,gw as gl) ->
      let vs = fst (strip_exists gw) in
      let wty = type_of (el 0 vs) in
      let mm = var_by_name "m" gl in
      let ad = rand (rand (concl (the_asm (fun c ->
                 try is_eq c && type_of (rand (rand c)) = wty &&
                     fst (dest_const (rator (rand c))) = "SOME"
                 with Failure _ -> false) gl))) in
      let xd = rand (rand (concl (the_asm (fun c ->
                 try is_eq c && rator (lhs c) = mm
                 with Failure _ -> false) gl))) in
      if n = 2 then MAP_EVERY EXISTS_TAC [ad; xd] else
      let vv = var_by_name "v" gl in
      let wd = rand (rand (concl (the_asm (fun c ->
                 try is_eq c && lhs c = vv
                 with Failure _ -> false) gl))) in
      MAP_EVERY EXISTS_TAC [wd; ad; xd]) in
  STRIP_TAC THEN
  FIRST_ASSUM (fun mr ->
    STRIP_ASSUME_TAC (MATCH_MP memory_rel_RefPtr_IMP_lemma mr)) THEN
  FIRST_ASSUM (fun lk ->
    EXISTS_TAC (rand (rand (concl lk)))) THEN
  ASM_REWRITE_TAC[] THEN
  W(fun gl -> CASES_ON_TAC (var_by_name "res" gl)) THEN
  TRY SAFE_MATCH_REDUCE_TAC THENL
   [(* an array of values: its header has bit 3 set and bit 2
        clear *)
    use_lemma memory_rel_ValueArray_IMP THEN pick 3 THEN
    ASM_REWRITE_TAC[];
    (* an array of bytes: the other way round *)
    use_lemma memory_rel_ByteArray_IMP THEN pick 3 THEN
    ASM_REWRITE_TAC[];
    (* a thunk, and the two modes of one *)
    W(fun gl -> CASES_ON_TAC (var_by_name "a0" gl)) THEN
    REWRITE_TAC[distinctness "thunk_mode"] THEN
    TRY SAFE_MATCH_REDUCE_TAC THENL
     [(* an evaluated thunk: the lemma either says what the
          pattern wants or says that bit 5 of the header is set,
          which says it too *)
      GEN_TAC THEN DISCH_TAC THEN
      use_lemma memory_rel_Thunk_IMP THENL
       [FIRST_ASSUM (fun h -> FIRST_ASSUM (fun th ->
          MP_TAC (MATCH_MP th h))) THEN
        STRIP_TAC THEN pick 2 THEN ASM_REWRITE_TAC[];
        FIRST_ASSUM (fun h ->
          let e0 = CONJUNCT1 h in
          FIRST_ASSUM (fun e1 ->
            if concl e1 = concl e0 then fail() else
            SUBST_ALL_TAC (REWRITE_RULE[injectivity "word_loc"]
              (TRANS (SYM e1) e0)))) THEN
        pick 2 THEN ASM_REWRITE_TAC[] THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        MATCH_MP_TAC and60_ne24 THEN CONJ_TAC THENL
         [MATCH_MP_TAC dim5 THEN FIRST_ASSUM ACCEPT_TAC;
          ASM_REWRITE_TAC[]]];
      (* a thunk that is not evaluated: the first of the lemma's
         two cases says it is, so the second one is the one *)
      use_lemma memory_rel_Thunk_IMP THENL
       [RULE_ASSUM_TAC (REWRITE_RULE[distinctness "thunk_mode";
          GSYM (distinctness "thunk_mode")]) THEN
        FIRST_X_ASSUM CONTR_TAC;
        pick 3 THEN ASM_REWRITE_TAC[]]]]));;

(* Smallnum_bits *)
let smallnum_bits = prove
 (`((n2w 1) && Smallnum i) = (n2w 0) /\ ((n2w 2) && Smallnum i) = (n2w
  0)`,
  (* Smallnum is four times the integer, up to the sign, so
     its two lowest bits are clear *)
  (let bw2 = prove
    (`!i. bit i (word 2:(N)word) <=> i = 1 /\ 1 < dimindex(:N)`,
     GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [ARITH_RULE `2 = 2 EXP 1`] THEN
     REWRITE_TAC[BIT_WORD_POW2]) in
   let shl4 = prove
    (`!(v:(N)word). word 4 * v = word_shl v 2`,
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
     REWRITE_TAC[MULT_AC]) in
   let bits01 = prove
    (`!(v:(N)word). (word 1 && word_shl v 2 = word 0) /\
                    (word 2 && word_shl v 2 = word 0)`,
     GEN_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
                 BIT_WORD_1; bw2; BIT_WORD_SHL] THEN
     CONJ_TAC THEN GEN_TAC THEN DISCH_TAC THEN ARITH_TAC) in
   let nmul = prove
    (`!(i:int). &0 <= i
        ==> n2w (num_of_int (&4 * i)) =
            (n2w 4 * n2w (num_of_int i):(N)word)`,
     REPEAT STRIP_TAC THEN
     SUBGOAL_THEN `num_of_int (&4 * (i:int)) = 4 * num_of_int i`
       SUBST1_TAC THENL
      [FIRST_ASSUM(fun th ->
         GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
           [GSYM(MATCH_MP INT_OF_NUM_OF_INT th)]) THEN
       REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM];
       REWRITE_TAC[WORD_MUL]]) in
   REWRITE_TAC[smallnum_def] THEN COND_CASES_TAC THENL
    [SUBGOAL_THEN `&0 <= ((&0) - (i:int))` ASSUME_TAC THENL
      [ASM_INT_ARITH_TAC; ALL_TAC] THEN
     FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP nmul th]) THEN
     REWRITE_TAC[WORD_SUB_LZERO; shl4] THEN
     GEN_REWRITE_TAC (ONCE_DEPTH_CONV)
       [WORD_RULE `word_neg (word_shl v 2) = word_shl (word_neg v) 2`]
     THEN REWRITE_TAC[bits01];
     SUBGOAL_THEN `&0 <= (i:int)` ASSUME_TAC THENL
      [ASM_INT_ARITH_TAC; ALL_TAC] THEN
     FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP nmul th]) THEN
     REWRITE_TAC[shl4; bits01]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_any_Number_IMP = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) /\
      memory_rel c be ts refs sp st m dm ((Number i,(v:'a
        word_loc)) :: vars) ==>
      (?w. v = wordLang_Word w /\ (FAPPLY w 0 <=> ~(small_int
        (:'a) i)))`),
  (* the root of a Number is the Data of its Smallnum, whose lowest
     bit the and with the complement of one clears, or a Pointer,
     whose address has that bit set (get_addr_0) *)
  (MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN
    FIRST_ASSUM(fun e ->
      let c = concl e in
      if is_eq c && is_var (rand c) then SUBST1_TAC (SYM e)
      else fail()) THEN
    REWRITE_TAC[injectivity "word_loc"] THEN
    CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
    REWRITE_TAC[word_index; get_addr_0; BIT_WORD_AND;
                BIT_WORD_NOT; BIT_WORD_1] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[ARITH_RULE `0 < d <=> 1 <= d`; DIMINDEX_GE_1]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_IMP = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) /\ small_int (:'a) i /\
      memory_rel c be ts refs sp st m dm ((Number i,(v:'a
        word_loc)) :: vars) ==>
      v = wordLang_Word (Smallnum i)`),
  (* the root of a small Number is the Data of its Smallnum,
     whose word_addr takes the tag bit off -- and Smallnum is
     four times the integer, which has that bit clear *)
  (let nmul = prove
    (`!(i:int). &0 <= i
        ==> n2w (num_of_int (&4 * i)) =
            (n2w 4 * n2w (num_of_int i):(N)word)`,
     REPEAT STRIP_TAC THEN
     SUBGOAL_THEN `num_of_int (&4 * (i:int)) = 4 * num_of_int i`
       SUBST1_TAC THENL
      [FIRST_ASSUM(fun th ->
         GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
           [GSYM(MATCH_MP INT_OF_NUM_OF_INT th)]) THEN
       REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM];
       REWRITE_TAC[WORD_MUL]]) in
   let neg2 = prove
    (`word_not (word 1):(N)word = word_neg (word 2)`,
     CONV_TAC WORD_RULE) in
   let sm_and = prove
    (`good_dimindex (:'a) ==>
        ((Smallnum i && word_not (n2w 1)) = (Smallnum i:'a word))`,
     DISCH_TAC THEN REWRITE_TAC[smallnum_def] THEN
     REWRITE_TAC[neg2] THEN ONCE_REWRITE_TAC[WORD_AND_SYM] THEN
     COND_CASES_TAC THENL
      [SUBGOAL_THEN `&0 <= ((&0) - (i:int))` ASSUME_TAC THENL
        [ASM_INT_ARITH_TAC; ALL_TAC] THEN
       FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP nmul th]) THEN
       REWRITE_TAC[WORD_SUB_LZERO] THEN
       SUBGOAL_THEN
         `word_neg (n2w 4 * n2w (num_of_int ((&0) - (i:int)))) =
          word_neg (n2w 4) * (n2w (num_of_int ((&0) - i)):'a word)`
         SUBST1_TAC THENL
        [CONV_TAC WORD_RULE; ALL_TAC] THEN
       MATCH_MP_TAC word_ml_inv_neg_num_lemma THEN
       FIRST_ASSUM ACCEPT_TAC;
       SUBGOAL_THEN `&0 <= (i:int)` ASSUME_TAC THENL
        [ASM_INT_ARITH_TAC; ALL_TAC] THEN
       FIRST_ASSUM(fun th -> REWRITE_TAC[MATCH_MP nmul th]) THEN
       MATCH_MP_TAC word_ml_inv_num_lemma THEN
       FIRST_ASSUM ACCEPT_TAC]) in
   MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN
   TRY CONTRA_TAC THEN
   FIRST_ASSUM(fun gd ->
     RULE_ASSUM_TAC(REWRITE_RULE[MATCH_MP sm_and gd])) THEN
   ASM_MESON_TAC[]));;

(* the port's own: what the payload and the header of a bignum
   need.  n2mw_cons is the first word of the payload (HOL4 gets it
   from n2mw_def and n2w_mod), abs_nonzero is why there is one at
   all -- a number the invariant keeps as a bignum is not nought --
   and1_bit0 and and_pow2_zero read a bit of a word off an AND with
   a power of two, which is the form the statement has *)

let n2mw_cons = prove
 (`!k. ~(k = 0) ==> (?ns. (n2mw k:('a word) list) = n2w k :: ns)`,
  REPEAT STRIP_TAC THEN
  EXISTS_TAC `n2mw (k DIV dimword (:'a)):('a word) list` THEN
  GEN_REWRITE_TAC LAND_CONV [n2mw_def] THEN
  ASM_REWRITE_TAC[dimword; WORD_MOD_SIZE]);;

let abs_nonzero = prove
 (`good_dimindex (:'a) /\ ~small_int (:'a) i
    ==> ~(num_of_int (abs i) = 0)`,
  REWRITE_TAC[small_int_def; good_dimindex_def; dimword] THEN
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM (fun dd ->
    if (try lhs (concl dd) = `dimindex (:'a)`
         with Failure _ -> false)
    then RULE_ASSUM_TAC (REWRITE_RULE[dd]) else fail()) THEN
  RULE_ASSUM_TAC (CONV_RULE NUM_REDUCE_CONV) THEN
  MP_TAC (SPEC `abs (i:int)` INT_OF_NUM_OF_INT) THEN
  REWRITE_TAC[INT_ABS_POS] THEN
  ASM_REWRITE_TAC[] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  ASM_INT_ARITH_TAC);;

let and1_bit0 = prove
 (`!(x:'a word). ~((x && (n2w 1)) = n2w 0) <=> word_bit 0 x`,
  GEN_TAC THEN
  REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
               BIT_WORD_1] THEN
  MESON_TAC[DIMINDEX_GE_1; ARITH_RULE `1 <= n ==> 0 < n`]);;

let and_pow2_zero = prove
 (`!(x:'a word) k. k < dimindex (:'a)
    ==> ((x && (n2w (2 EXP k)) = n2w 0) <=> ~(word_bit k x))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
               BIT_WORD_POW2] THEN
  ASM_MESON_TAC[]);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_bignum_IMP_ALT = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i,v) :: vars) /\
      ~(small_int (:'a) i) /\ good_dimindex (:'a) ==>
      (?ff w x a y.
        v = wordLang_Word w /\ ~((w && (n2w 1)) = ((n2w 0):'a
          word)) /\
        get_real_addr c st w = SOME a /\
        a IN dm /\ m a = wordLang_Word x /\ (~((x && (n2w 8)) =
          (n2w 0))) /\
        word_bit 2 x /\ word_bit 3 x /\
        (word_bit 4 x <=> i < (&0)) /\
        (misc_word_list (a + bytes_in_word)
          (MAP wordLang_Word (n2mw (num_of_int (abs i)))) * ff)
            (fun2set (m,dm)) /\
        a + bytes_in_word IN dm /\
        m (a + bytes_in_word) = wordLang_Word (n2w (num_of_int (abs
          i))) /\
        ((x && (n2w 16)) = (n2w 0) <=> (&0) <= i) /\
        LENGTH (n2mw (num_of_int (abs i)):('a word) list) < 2 EXP
          (dimindex (:'a) - 4) /\
        LENGTH (n2mw (num_of_int (abs i)):('a word) list) < dimword
          (:'a) /\
        decode_length c x = n2w
          (LENGTH (n2mw (num_of_int (abs i)):('a word) list)))`),
(* the proof of the source is the template of
   memory_rel_ValueArray_IMP at a Bignum, and the three things it
   needs beyond it are above the statement: the payload has a first
   word (n2mw_cons, abs_nonzero), the header's bits come off
   make_header as they do there, and what the statement writes as
   an AND with a power of two is a bit of the header
   (and_pow2_zero).  The frame of the separating conjunction that
   the statement leaves existential is what is left of the heap
   when the word_list of the payload is taken out of it *)
  (let hd_is n t =
    (try fst(dest_const(fst(strip_comb t))) = n
     with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail()) asl in
  let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
  let sepfront names =
    W(fun (asl,w) ->
      let pred = rator (lhand w) in
      let fs = facs pred in
      let picked = map (fun n -> find (hd_is n) fs) names in
      let rest = filter (fun t -> not (mem t picked)) fs in
      let st = fst(strip_comb pred) in
      let mk a b = mk_comb(mk_comb(st,a),b) in
      let target = itlist mk picked (end_itlist mk rest) in
      SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
       [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
  MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN
  FIRST_ASSUM(fun e ->
    let c = concl e in
    if is_eq c && is_var (rand c) && hd_is "wordLang_Word" (lhs c)
    then SUBST1_TAC (SYM e) else fail()) THEN
  REWRITE_TAC[injectivity "word_loc"] THEN
  CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
  FIRST_X_ASSUM(fun th ->
    if hd_is "heap_in_memory_store" (concl th)
    then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
    else fail()) THEN
  STRIP_TAC THEN
  W(fun (asl,w) ->
    MP_TAC(MATCH_MP heap_lookup_SPLIT (grab asl is_hl))) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  VAR_EQ_TAC THEN
   W(fun (asl,w) ->
     let hl = grab asl is_hl in
     let hlen = grab asl (fun th ->
       hd_is "heap_length" (lhand (concl th))) in
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
     let gd = grab asl (fun th -> concl th = `good_dimindex (:'a)`) in
     let gat = tryfind (fun t ->
       find_term (fun u ->
         hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
       (w :: map (fun (_,th) -> concl th) asl) in
     let th = SPEC (last (snd(strip_comb gat)))
       (GEN `w:('a)word_loc`
         (MATCH_MP get_real_addr_get_addr
           (CONJ hlen (CONJ hl (CONJ cu gd))))) in
     let r = rhs (concl (CONJUNCT1 th)) in
     let a = rand r in
     let args = snd(strip_comb (rand a)) in
     let mul = fst(strip_comb (rand a)) in
     let swap = mk_comb(rator a,
                  mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
     let sw = WORD_RULE (mk_eq(a,swap)) in
     STRIP_ASSUME_TAC(REWRITE_RULE[sw] th)) THEN
  (* the payload of the bignum has a first word *)
  W(fun gl ->
    let gd = the_asm (fun c -> c = `good_dimindex (:'a)`) gl in
    let si = the_asm (fun c ->
               try is_neg c && hd_is "small_int" (rand c)
               with Failure _ -> false) gl in
    STRIP_ASSUME_TAC (MATCH_MP n2mw_cons
      (MATCH_MP abs_nonzero (CONJ gd si)))) THEN
  (* the cells of the heap at the bignum *)
  FIRST_X_ASSUM(fun th ->
    if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
    then MP_TAC th else fail()) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_def; bignum_def;
              i2mw_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_el_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[LENGTH_MAP] THEN
  sepfront ["cond"] THEN
  REWRITE_TAC[cond_STAR] THEN
  DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC) THEN
  FIRST_X_ASSUM (fun cons ->
    if not (try is_eq (concl cons) &&
                hd_is "CONS" (rand (concl cons)) &&
                length (snd (strip_comb (lhs (concl cons)))) = 1
            with Failure _ -> false)
    then fail() else
    DISCH_THEN (fun sep ->
      let front th cell =
        let p = rator (concl th) in
        let fs = facs p in
        let st = fst (strip_comb p) in
        let mk a b = mk_comb (mk_comb (st, a), b) in
        let rest = filter (fun t -> not (t = cell)) fs in
        let target = mk cell (end_itlist mk rest) in
        let eq = prove (mk_eq (p, target), REWRITE_TAC[STAR_AC]) in
        MATCH_MP read_fun2set (REWRITE_RULE[eq] th) in
      let sep2 = REWRITE_RULE[cons; MAP; word_list_def] sep in
      let cells th =
        map (front th) (filter (hd_is "set_sep_one") (facs
          (rator (concl th)))) in
      let rds2 = cells sep2 in
      let sep1 = REWRITE_RULE[word_list_def] sep in
      let rds1 = cells sep1 in
      let hdr = hd rds1 in
      let x = rand (rhs (concl (CONJUNCT1 hdr))) in
      let a = rand (lhs (concl (CONJUNCT1 hdr))) in
      let p1 = rator (concl sep1) in
      let fs1 = facs p1 in
      let st1 = fst (strip_comb p1) in
      let mk1 u v = mk_comb (mk_comb (st1, u), v) in
      let wl = find (hd_is "misc_word_list") fs1 in
      let rest1 = filter (fun t -> not (t = wl)) fs1 in
      let eq1 = prove (mk_eq (p1, mk1 wl (end_itlist mk1 rest1)),
                  REWRITE_TAC[STAR_AC]) in
      let sep3 = REWRITE_RULE[eq1] sep1 in
      MAP_EVERY EXISTS_TAC [rand (rator (concl sep3)); x; a] THEN
      MAP_EVERY STRIP_ASSUME_TAC
        (sep3 :: (rds1 @ rds2)))) THEN
  (* the bits of the header, off make_header *)
  SUBGOAL_THEN `3 < dimindex (:'a) /\ 4 < dimindex (:'a)`
    STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
      `data_to_word_config_len_size c + 7 < dimindex (:'a)` THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `2 EXP (dimindex (:'a) - 4) <= dimword (:'a)`
    ASSUME_TAC THENL
   [REWRITE_TAC[dimword; LE_EXP] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[and1_bit0;
    REWRITE_RULE[word_index] get_addr_0] THEN
  ASM_SIMP_TAC[ARITH_RULE `8 = 2 EXP 3`;
               ARITH_RULE `16 = 2 EXP 4`; and_pow2_zero] THEN
  REPEAT CONJ_TAC THEN
  TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
  REWRITE_TAC[make_header_def; b2w_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  ASM_CASES_TAC `(i:int) < &0` THEN
  FIRST
   [SUBGOAL_THEN `((&0:int) <= i) <=> F`
      (fun e -> REWRITE_TAC[e]) THENL
     [ASM_INT_ARITH_TAC; ALL_TAC];
    SUBGOAL_THEN `((&0:int) <= i) <=> T`
      (fun e -> REWRITE_TAC[e]) THENL
     [ASM_INT_ARITH_TAC; ALL_TAC]] THEN
  ASM_REWRITE_TAC[b2n_def] THEN
  REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
              BIT_WORD_OR; BIT_WORD_SHL; BIT_WORD] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  TRY (W(fun gl ->
    UNDISCH_TAC (concl (the_asm (fun c ->
      try is_binop `(<):num->num->bool` c &&
          hd_is "LENGTH" (lhand c)
      with Failure _ -> false) gl)))) THEN
  TRY (UNDISCH_TAC
    `2 EXP (dimindex (:'a) - 4) <= dimword (:'a)`) THEN
  UNDISCH_TAC `4 < dimindex (:'a)` THEN
  UNDISCH_TAC `3 < dimindex (:'a)` THEN
  UNDISCH_TAC
    `data_to_word_config_len_size c + 7 < dimindex (:'a)` THEN
  ARITH_TAC));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_bignum_header = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i,(v:'a word_loc)) ::
  vars) /\
      ~(small_int (:'a) i) /\ good_dimindex (:'a) ==>
      (?ff w x a y.
        v = wordLang_Word w /\ get_real_addr c st w = SOME a /\
        IS_SOME ((encode_header c (w2n ((b2w (i < (&0)) << 2 ||
          (n2w 3)):'a word))
            (LENGTH (n2mw (num_of_int (abs i)):('a word)
              list))):('a word) option) /\
        m a = wordLang_Word (make_header c (b2w (i < (&0)) << 2 ||
          (n2w 3))
                (LENGTH (n2mw (num_of_int (abs i)):('a word)
                  list))))`),
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let sep_cond_front =
     W(fun (asl,w) ->
       let star t = hd_is "STAR" t in
       let rec facs t =
         if star t then
           let args = snd(strip_comb t) in
           facs (el 0 args) @ facs (el 1 args)
         else [t] in
       let pred = rator (lhand w) in
       let fs = facs pred in
       let isone t = hd_is "set_sep_one" t in
       let iscond t = hd_is "cond" t in
       let one = find isone fs and cnd = find iscond fs in
       let rest = filter (fun t -> not (isone t) && not (iscond t))
                    fs in
       let st = fst(strip_comb pred) in
       let mk a b = mk_comb(mk_comb(st,a),b) in
       let target = mk cnd (mk one (end_itlist mk rest)) in
       SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
        [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
   MEMORY_REL_TAC THEN
   FIRST_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi)
     then MP_TAC(REWRITE_RULE[v_inv_def] vi)
     else fail()) THEN
   ASM_REWRITE_TAC[] THEN
   DISCH_THEN(X_CHOOSE_THEN `ptr:num` STRIP_ASSUME_TAC) THEN
   VAR_EQ_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE(word_addr_clauses ())) THEN
   FIRST_ASSUM(fun hm ->
     if hd_is "heap_in_memory_store" (concl hm)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] hm)
     else fail()) THEN
   STRIP_TAC THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_exists (concl th) then
       (X_CHOOSE_THEN `curr:'a word`
         (X_CHOOSE_THEN `other:'a word` STRIP_ASSUME_TAC)) th
     else fail())) THEN
   REWRITE_TAC(word_addr_clauses ()) THEN
   EXISTS_TAC `get_addr c ptr (wordLang_Word ((n2w 0):'a word))` THEN
   EXISTS_TAC `curr + n2w ptr * bytes_in_word:'a word` THEN
   REWRITE_TAC[] THEN CONJ_TAC THENL
    [FIRST_ASSUM(fun hl ->
       if hd_is "=" (concl hl) && hd_is "heap_lookup" (lhs(concl hl))
       then FIRST_ASSUM(fun hlen ->
         FIRST_ASSUM(fun cu ->
           FIRST_ASSUM(fun gd ->
             MP_TAC(SPEC `wordLang_Word ((n2w 0):'a word)`
               (GEN `w:('a)word_loc`
                 (MATCH_MP get_real_addr_get_addr
                   (CONJ hlen (CONJ hl (CONJ cu gd)))))))))
       else fail()) THEN
     DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
     ALL_TAC] THEN
   FIRST_ASSUM(fun hl ->
     if hd_is "=" (concl hl) && hd_is "heap_lookup" (lhs(concl hl))
     then MP_TAC(MATCH_MP heap_lookup_SPLIT hl)
     else fail()) THEN
   DISCH_THEN(X_CHOOSE_THEN
     `ha:(('a word_loc,data_to_word_memoryProof_tag#('a word_loc)
           list)heap_element) list`
     (X_CHOOSE_THEN
       `hb:(('a word_loc,data_to_word_memoryProof_tag#('a word_loc)
             list)heap_element) list` STRIP_ASSUME_TAC)) THEN
   VAR_EQ_TAC THEN
   FIRST_X_ASSUM(fun hs ->
     if (try hd_is "STAR" (rator(concl hs)) with Failure _ -> false)
     then MP_TAC hs else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def;
               bignum_def; i2mw_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_list_def; LENGTH_MAP] THEN
   sep_cond_front THEN
   REWRITE_TAC[cond_STAR] THEN
   DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC
     (fun st -> MP_TAC(MATCH_MP read_fun2set st))) THEN
   ASM_REWRITE_TAC[] THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST1_TAC o SYM) (K ALL_TAC)) THEN
   AP_TERM_TAC THEN AP_TERM_TAC THEN CONV_TAC WORD_RULE));;

(* the port's own: what the proof of memory_rel_bignum_cmp needs.
   The invariant says of a bignum both that the element of the heap
   holds its header (memory_rel_Number_bignum_header) and what the
   header is made of (memory_rel_Number_bignum_IMP_ALT), of one
   address but with a root of its own each time, so the two are put
   together into one statement (bignum_header) first.  Of two
   bignums whose elements are not one, the signs then cannot be one
   when the lengths are (bignum_cmp_sign), because a header is the
   sign and the length *)

(* the element of the heap that holds a bignum is its header: what
   the invariant says of the number twice over, as the element and
   as the header, is of one address *)
let bignum_elt_eq = prove
 (cake_as_vars (fun () ->
    `(v:'a word_loc) = wordLang_Word w /\
     get_real_addr c st w = SOME a /\ m a = wordLang_Word x /\
     v = wordLang_Word w2 /\ get_real_addr c st w2 = SOME a2 /\
     m a2 = wordLang_Word y
     ==> (x:'a word) = y`),
  REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[injectivity "word_loc"; injectivity "option"]);;

(* of two bignums whose elements are not one: if the headers have
   one length then the signs are not one, because a header is the
   sign and the length *)
let bignum_cmp_sign = prove
 (cake_as_vars (fun () ->
    `(x1:'a word) = make_header c (b2w ((i1:int) < (&0)) << 2 ||
       (n2w 3)) l1 /\
     x2 = make_header c (b2w ((i2:int) < (&0)) << 2 || (n2w 3))
       l2 /\
     decode_length c x1 = n2w l1 /\ decode_length c x2 = n2w l2 /\
     l1 < dimword (:'a) /\ l2 < dimword (:'a) /\
     ((x1 && (n2w 16) = (n2w 0)) <=> (&0) <= i1) /\
     ((x2 && (n2w 16) = (n2w 0)) <=> (&0) <= i2)
     ==> (~(x1 = x2)
          ==> decode_length c x1 = decode_length c x2
          ==> ~(((n2w 16) && x1 = (n2w 0)) <=>
                ((n2w 16) && x2 = (n2w 0))))`),
  STRIP_TAC THEN SPLIT_ASM_TAC THEN
  DISCH_TAC THEN DISCH_TAC THEN
  (* the signs, which the two iffs of the assumptions give once the
     AND of each is in the order that the rewriter puts it *)
  W(fun (asl,_) ->
    let sgs = mapfilter (fun (_,th) ->
                let c = concl th in
                if is_eq c && type_of (lhand c) = bool_ty &&
                   can (find_term (hd_is "word_and")) (lhand c)
                then REWRITE_RULE[WORD_AND_SYM] th else fail()) asl in
    REWRITE_TAC (WORD_AND_SYM :: sgs)) THEN
  STRIP_TAC THEN
  (* the two lengths are one, because the headers' are *)
  SUBGOAL_THEN `(l1:num) = l2` ASSUME_TAC THENL
   [MATCH_MP_TAC n2w_eq_LENGTH THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* and so are the signs *)
  FIRST_ASSUM (fun th -> ASSUME_TAC (MATCH_MP int_sign_iff th)) THEN
  (* so the headers are one, which the elements are not *)
  FIRST_X_ASSUM (fun ne ->
    if not (is_neg (concl ne)) || not (is_eq (rand (concl ne)))
    then fail() else MP_TAC (NOT_ELIM ne)) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[]);;

(* what the invariant says of a bignum, with the element of the
   heap read as the header that it is *)
let bignum_header = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i,v) :: vars) /\
     ~(small_int (:'a) i) /\ good_dimindex (:'a)
     ==> (?w a x.
            v = wordLang_Word w /\
            get_real_addr c st w = SOME a /\
            m a = wordLang_Word (x:'a word) /\
            x = make_header c (b2w ((i:int) < (&0)) << 2 ||
                  (n2w 3))
                  (LENGTH (n2mw (num_of_int (abs i)):('a word)
                     list)) /\
            decode_length c x = n2w (LENGTH (n2mw (num_of_int
              (abs i)):('a word) list)) /\
            LENGTH (n2mw (num_of_int (abs i)):('a word) list)
              < dimword (:'a) /\
            ((x && (n2w 16) = (n2w 0)) <=> (&0) <= i))`),
  STRIP_TAC THEN
  (* the element of the heap, and the header that the invariant
     says of the same address *)
  W(fun gl ->
    let mr = the_asm (hd_is "memory_rel") gl in
    let ns = the_asm (fun c -> is_neg c &&
               hd_is "small_int" (rand c)) gl in
    let gd = the_asm (hd_is "good_dimindex") gl in
    STRIP_ASSUME_TAC (MATCH_MP memory_rel_Number_bignum_IMP_ALT
      (CONJ mr (CONJ ns gd))) THEN
    STRIP_ASSUME_TAC (MATCH_MP memory_rel_Number_bignum_header
      (CONJ mr (CONJ ns gd)))) THEN
  W(fun (asl,gw as gl) ->
    let mr = the_asm (hd_is "memory_rel") gl in
    let margs = snd (strip_comb (concl mr)) in
    let mem = el 6 margs in
    let vt = rand (lhand (el 8 margs)) in
    let elts = mapfilter (fun (_,th) ->
      let c = concl th in
      if is_eq c && is_comb (lhand c) &&
         rator (lhand c) = mem && hd_is "wordLang_Word" (rand c)
      then th else fail()) asl in
    let triple e =
      let a = rand (lhand (concl e)) in
      let ga = the_asm (fun c -> is_eq c &&
                 hd_is "get_real_addr" (lhand c) &&
                 rand (rand c) = a) gl in
      let wv = el 2 (snd (strip_comb (lhand (concl ga)))) in
      let vw = the_asm (fun c -> is_eq c && lhand c = vt &&
                 rand c = list_mk_icomb "wordLang_Word" [wv]) gl in
      (vw,ga,e) in
    let alt = find (fun e -> is_var (rand (rand (concl e)))) elts in
    let hdr = find (fun e ->
                not (is_var (rand (rand (concl e))))) elts in
    let (va,ga,ma) = triple alt in
    let (vh,gh,mh) = triple hdr in
    let xeq = MATCH_MP bignum_elt_eq
                (CONJ va (CONJ ga (CONJ ma
                  (CONJ vh (CONJ gh mh))))) in
    MAP_EVERY EXISTS_TAC
      [el 2 (snd (strip_comb (lhand (concl ga))));
       rand (lhand (concl ma)); rand (rand (concl ma))] THEN
    REPEAT CONJ_TAC THEN
    TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
    TRY (SOLVED (ACCEPT_TAC xeq))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_bignum_cmp = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
          ((Number i1,v1) :: (Number i2,(v2:'a word_loc)) :: vars)
            /\
      good_dimindex (:'a) /\ ~(small_int (:'a) i1) /\ ~(small_int
        (:'a) i2) ==>
      (?w1 w2 a1 a2 x1 x2.
         v1 = wordLang_Word w1 /\ v2 = wordLang_Word w2 /\
         get_real_addr c st w1 = SOME a1 /\
         get_real_addr c st w2 = SOME a2 /\
         m a1 = wordLang_Word x1 /\
         m a2 = wordLang_Word x2 /\
         (~(x1 = x2) ==>
          (decode_length c (x1) = decode_length c (x2)) ==>
            ~((((n2w 16) && x1) = (n2w 0)) = (((n2w 16) && x2) = (n2w
            0)))))`),
  (* the steps are above the statement (tools/overrides.py).  Of
     each of the two numbers the invariant gives the element of the
     heap as its header (bignum_header), and the header is the sign
     and the length of each: if the lengths are one and the signs
     are one then the headers are one, which the elements of the
     two are not (bignum_cmp_sign) *)
  (STRIP_TAC THEN SPLIT_ASM_TAC THEN
    (* what the invariant says of each of the two numbers *)
    W(fun gl ->
      let mr = the_asm (hd_is "memory_rel") gl in
      let gd = the_asm (hd_is "good_dimindex") gl in
      let lst = el 8 (snd (strip_comb (concl mr))) in
      let num t = rand (lhand (lhand t)) in
      let ns i = the_asm (fun c -> is_neg c &&
                   hd_is "small_int" (rand c) &&
                   el 1 (snd (strip_comb (rand c))) = i) gl in
      MAP_EVERY STRIP_ASSUME_TAC
        [MATCH_MP bignum_header (CONJ mr (CONJ (ns (num lst)) gd));
         MATCH_MP bignum_header
           (CONJ (MATCH_MP memory_rel_tail mr)
             (CONJ (ns (num (rand lst))) gd))]) THEN
    (* the witnesses: the root, the address and the element of each *)
    W(fun (asl,gw as gl) ->
      let mr = the_asm (hd_is "memory_rel") gl in
      let lst = el 8 (snd (strip_comb (concl mr))) in
      let pieces vt =
        let vw = the_asm (fun c -> is_eq c && lhand c = vt &&
                   hd_is "wordLang_Word" (rand c)) gl in
        let wv = rand (rand (concl vw)) in
        let ga = the_asm (fun c -> is_eq c &&
                   hd_is "get_real_addr" (lhand c) &&
                   el 2 (snd (strip_comb (lhand c))) = wv) gl in
        let a = rand (rand (concl ga)) in
        let ma = the_asm (fun c -> is_eq c && is_comb (lhand c) &&
                   rand (lhand c) = a &&
                   hd_is "wordLang_Word" (rand c)) gl in
        let x = rand (rand (concl ma)) in
        let he = the_asm (fun c -> is_eq c && lhand c = x &&
                   hd_is "make_header" (rand c)) gl in
        let dl = the_asm (fun c -> is_eq c &&
                   hd_is "decode_length" (lhand c) &&
                   rand (lhand c) = x) gl in
        let l = rand (rand (concl dl)) in
        let bd = the_asm (fun c -> hd_is "<" c && lhand c = l &&
                   hd_is "dimword" (rand c)) gl in
        let sg = the_asm (fun c -> is_eq c &&
                   type_of (lhand c) = bool_ty &&
                   is_eq (lhand c) &&
                   can (find_term (fun t -> t = x)) (lhand c)) gl in
        (wv,a,x,he,dl,bd,sg) in
      let (w1,a1,x1,he1,dl1,bd1,sg1) = pieces (rand (lhand lst)) in
      let (w2,a2,x2,he2,dl2,bd2,sg2) =
        pieces (rand (lhand (rand lst))) in
      MAP_EVERY EXISTS_TAC [w1; w2; a1; a2; x1; x2] THEN
      REPEAT CONJ_TAC THEN
      TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
      MATCH_ACCEPT_TAC (MATCH_MP bignum_cmp_sign
        (CONJ he1 (CONJ he2 (CONJ dl1 (CONJ dl2 (CONJ bd1 (CONJ bd2
          (CONJ sg1 sg2)))))))))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_bignum_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i,v) :: vars) /\
      ~(small_int (:'a) i) /\ good_dimindex (:'a) ==>
      (?w x a y.
        v = wordLang_Word w /\ ~((w && (n2w 1)) = ((n2w 0):'a
          word)) /\
        get_real_addr c st w = SOME a /\
        a IN dm /\ m a = wordLang_Word x /\ (~((x && (n2w 8)) =
          (n2w 0))) /\
        a + bytes_in_word IN dm /\
        m (a + bytes_in_word) = wordLang_Word (n2w (num_of_int (abs
          i))) /\
        ((x && (n2w 16)) = (n2w 0) <=> (&0) <= i))`),
  (* the ALT of it says more; this is what the source keeps *)
  (STRIP_TAC THEN
   FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 -> FIRST_ASSUM(fun t3 ->
     MP_TAC(MATCH_MP memory_rel_Number_bignum_IMP_ALT
       (CONJ t1 (CONJ t2 t3)))))) THEN
   STRIP_TAC THEN
   REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC)) THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_exists(concl th) then CHOOSE_TAC th else fail())) THEN
   ASM_MESON_TAC[]));;

(* the port's own: a shift by one is a doubling, which is what the
   second word of a 64-bit value on a 32-bit target is at *)

let shl1_add = prove
 (`!(w:'a word). w << 1 = w + w`,
  CONV_TAC WORD_RULE);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Word64_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Word64 w64,(v:'a word_loc)) ::
  vars) /\
     good_dimindex (:'a) ==>
     (?ptr x w.
       v = wordLang_Word (get_addr c ptr (wordLang_Word (n2w 0)))
         /\
       get_real_addr c st (get_addr c ptr (wordLang_Word (n2w 0)))
         = SOME x /\
       x IN dm /\ m x = wordLang_Word w /\ word_bit 3 w /\
         ~(word_bit 4 w) /\ word_bit 2 w /\
       (x + bytes_in_word) IN dm /\
       (if dimindex (:'a) < 64 then
         (m (x + bytes_in_word) = wordLang_Word ((63 >< 32) w64) /\
          (x + (bytes_in_word << 1)) IN dm /\ m (x + (bytes_in_word
            << 1)) = wordLang_Word ((31 >< 0) w64) /\
         decode_length c w = (n2w 2) /\
         w = make_header c (n2w 3) 2) else
         (m (x + bytes_in_word) = wordLang_Word ((63 >< 0) w64)) /\
         decode_length c w = (n2w 1) /\
         w = make_header c (n2w 3) 1))`),
(* the proof of the source is the one of memory_rel_ValueArray_IMP
   with Word64Rep in place of the RefBlock: v_inv gives the heap
   lookup at the pointer, heap_in_memory_store and
   get_real_addr_get_addr give the address, and the heap split
   there lets word_heap be unfolded down to the three cells (two on
   a 64-bit target) that the statement reads.  The two word sizes
   are one case split, because Word64Rep is a conditional on the
   same test the statement has, and the bits of the header come off
   make_header as they do there *)
  (let hd_is n t =
    (try fst(dest_const(fst(strip_comb t))) = n
     with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail()) asl in
  let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
  let sepfront names =
    W(fun (asl,w) ->
      let pred = rator (lhand w) in
      let fs = facs pred in
      let picked = map (fun n -> find (hd_is n) fs) names in
      let rest = filter (fun t -> not (mem t picked)) fs in
      let st = fst(strip_comb pred) in
      let mk a b = mk_comb(mk_comb(st,a),b) in
      let target = itlist mk picked (end_itlist mk rest) in
      SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
       [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
  MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN
  W(fun gl -> EXISTS_TAC (var_by_name "ptr" gl)) THEN
  FIRST_X_ASSUM(fun th ->
    if hd_is "heap_in_memory_store" (concl th)
    then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
    else fail()) THEN
  STRIP_TAC THEN
  W(fun (asl,w) ->
    MP_TAC(MATCH_MP heap_lookup_SPLIT (grab asl is_hl))) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  VAR_EQ_TAC THEN
  W(fun (asl,w) ->
    let hl = grab asl is_hl in
    let hlen = grab asl (fun th ->
      hd_is "heap_length" (lhand (concl th))) in
    let cu = grab asl (fun th ->
      hd_is "FLOOKUP" (lhs (concl th)) &&
      fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
    let gd = grab asl (fun th -> concl th = `good_dimindex (:'a)`) in
    let gat = tryfind (fun t ->
      find_term (fun u ->
        hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
      (w :: map (fun (_,th) -> concl th) asl) in
    let th = SPEC (last (snd(strip_comb gat)))
      (GEN `w:('a)word_loc`
        (MATCH_MP get_real_addr_get_addr
          (CONJ hlen (CONJ hl (CONJ cu gd))))) in
    let r = rhs (concl (CONJUNCT1 th)) in
    let a = rand r in
    let args = snd(strip_comb (rand a)) in
    let mul = fst(strip_comb (rand a)) in
    let swap = mk_comb(rator a,
                 mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
    let sw = WORD_RULE (mk_eq(a,swap)) in
    EXISTS_TAC swap THEN
    STRIP_ASSUME_TAC(REWRITE_RULE[sw] th)) THEN
  FIRST_X_ASSUM(fun th ->
    if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
    then MP_TAC th else fail()) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_def; Word64Rep_def] THEN
  COND_CASES_TAC THEN
  REWRITE_TAC[] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_el_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; LENGTH_MAP] THEN
  sepfront ["cond"] THEN
  REWRITE_TAC[cond_STAR] THEN
  DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC) THEN
  DISCH_THEN (fun sep ->
    let p = rator (concl sep) in
    let fs = facs p in
    let st = fst (strip_comb p) in
    let mk a b = mk_comb (mk_comb (st, a), b) in
    let front cell =
      let rest = filter (fun t -> not (t = cell)) fs in
      let target = mk cell (end_itlist mk rest) in
      let eq = prove (mk_eq (p, target), REWRITE_TAC[STAR_AC]) in
      MATCH_MP read_fun2set (REWRITE_RULE[eq] sep) in
    let rds = map front (filter (hd_is "set_sep_one") fs) in
    EXISTS_TAC (rand (rhs (concl (CONJUNCT1 (hd rds))))) THEN
    MAP_EVERY STRIP_ASSUME_TAC rds) THEN
  REWRITE_TAC[shl1_add; WORD_ADD_ASSOC] THEN
  ASM_REWRITE_TAC[LENGTH] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[make_header_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[BIT_WORD_OR; BIT_WORD_SHL; BIT_WORD] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  UNDISCH_TAC
    `data_to_word_config_len_size c + 7 < dimindex (:'a)` THEN
  ARITH_TAC));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let IMP_memory_rel_Number_num3 = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) /\ n < 2 EXP (dimindex (:'a) - 3) /\
      memory_rel c be ts refs sp st m dm vars ==>
      memory_rel c be ts refs sp st m dm
       ((Number (&n),wordLang_Word ((n2w n << 2):'a word)) ::
         vars)`),
  (* the Smallnum of a natural number is it shifted up by two, and
     a number below two to the dimindex less three is small *)
  (let shl2 = prove
    (`!(v:(N)word). word_shl v 2 = word 4 * v`,
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
     REWRITE_TAC[MULT_AC]) in
   let smallnum_shl = prove
    (`Smallnum (&n) = ((n2w n << 2):'a word)`,
     REWRITE_TAC[smallnum_def; INT_OF_NUM_LT;
                 ARITH_RULE `~(n < 0)`; INT_OF_NUM_MUL;
                 NUM_OF_INT_OF_NUM; shl2; WORD_MUL]) in
   STRIP_TAC THEN
   MP_TAC(INST [`&n:int`,`i:int`]
     IMP_memory_rel_Number) THEN
   REWRITE_TAC[smallnum_shl] THEN
   DISCH_THEN MATCH_MP_TAC THEN
   ASM_REWRITE_TAC[small_int_def; INT_OF_NUM_LT; dimword] THEN
   CONJ_TAC THENL
    [INT_ARITH_TAC;
     UNDISCH_TAC `good_dimindex (:'a)` THEN
     REWRITE_TAC[good_dimindex_def] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
     RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
     CONV_TAC NUM_REDUCE_CONV THEN ARITH_ASM_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let IMP_memory_rel_Number_num = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) /\ n < 2 EXP (dimindex (:'a) - 4) /\
      memory_rel c be ts refs sp st m dm vars ==>
      memory_rel c be ts refs sp st m dm
       ((Number (&n),wordLang_Word ((n2w n << 2):'a word)) ::
         vars)`),
  (* and so is one below two to the dimindex less four *)
  (let shl2 = prove
    (`!(v:(N)word). word_shl v 2 = word 4 * v`,
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
     REWRITE_TAC[MULT_AC]) in
   let smallnum_shl = prove
    (`Smallnum (&n) = ((n2w n << 2):'a word)`,
     REWRITE_TAC[smallnum_def; INT_OF_NUM_LT;
                 ARITH_RULE `~(n < 0)`; INT_OF_NUM_MUL;
                 NUM_OF_INT_OF_NUM; shl2; WORD_MUL]) in
   STRIP_TAC THEN
   MP_TAC(INST [`&n:int`,`i:int`]
     IMP_memory_rel_Number) THEN
   REWRITE_TAC[smallnum_shl] THEN
   DISCH_THEN MATCH_MP_TAC THEN
   ASM_REWRITE_TAC[small_int_def; INT_OF_NUM_LT; dimword] THEN
   CONJ_TAC THENL
    [INT_ARITH_TAC;
     UNDISCH_TAC `good_dimindex (:'a)` THEN
     REWRITE_TAC[good_dimindex_def] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
     RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
     CONV_TAC NUM_REDUCE_CONV THEN ARITH_ASM_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_EQ = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((Number i1,w1) :: (Number i2,w2) :: vars) /\
      (small_int (:'a) i1 \/ small_int (:'a) i2) /\
      good_dimindex (:'a) ==>
        (?v1 v2. w1 = wordLang_Word v1 /\ w2 = wordLang_Word
          (v2:'a word) /\ (v1 = v2 <=> i1 = i2))`),
  (* two Numbers of which at least one is small: if both are, both
     roots are Smallnums and num_eq_thm says that two Smallnums are
     equal only for equal integers; if one is not, the lowest bits
     of the two roots differ (that bit says whether the Number is
     small), so the words differ, and so do the integers *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
   let clash =
     FIRST_ASSUM(fun n ->
       if is_neg (concl n) then
         FIRST_ASSUM(fun p ->
           if concl p = rand (concl n)
           then CONTR_TAC(EQ_MP (EQF_INTRO n) p) else fail())
       else fail()) in
   let all2cons = prove
    (`!P h t (l:(A)list).
        ALL2 P l (CONS (h:B) t) <=>
        ?a b. l = CONS a b /\ P a h /\ ALL2 P b t`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(A)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   (* one of the two is small and the other is not: their lowest
      bits differ, so the words differ, and the integers differ
      because small_int holds of one and not of the other *)
   let bits =
     MATCH_MP_TAC(TAUT `~p /\ ~q ==> (p <=> q)`) THEN CONJ_TAC THENL
      [DISCH_THEN SUBST_ALL_TAC THEN
       W(fun (asl,w) ->
         MP_TAC(end_itlist CONJ
           (map snd (filter (fun (_,th) ->
              let c = concl th in
              is_eq c && type_of (lhs c) = bool_ty) asl)))) THEN
       ASM_REWRITE_TAC[];
       DISCH_THEN SUBST_ALL_TAC THEN clash] in
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
     MP_TAC(MATCH_MP memory_rel_any_Number_IMP
              (CONJ gd mr)))) THEN
   DISCH_THEN(X_CHOOSE_THEN `v1:'a word` STRIP_ASSUME_TAC) THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
     let tl = MATCH_MP memory_rel_tail mr in
     MP_TAC(MATCH_MP memory_rel_any_Number_IMP
              (CONJ gd tl)))) THEN
   DISCH_THEN(X_CHOOSE_THEN `v2:'a word` STRIP_ASSUME_TAC) THEN
   EXISTS_TAC `v1:'a word` THEN EXISTS_TAC `v2:'a word` THEN
   ASM_REWRITE_TAC[] THEN
   ASM_CASES_TAC `small_int (:'a) i1` THEN
   ASM_CASES_TAC `small_int (:'a) i2` THENL
    [(* both are small, so both roots are Smallnums, and num_eq_thm
        says that two Smallnums are equal only for equal integers *)
     FIRST_ASSUM(fun e1 ->
       FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
         FIRST_ASSUM(fun si ->
           let ni = MATCH_MP memory_rel_Number_IMP
                      (CONJ gd (CONJ si mr)) in
           SUBST_ALL_TAC(REWRITE_RULE[injectivity "word_loc"]
                           (TRANS (SYM e1) ni)))))) THEN
     FIRST_ASSUM(fun e2 ->
       FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
         FIRST_ASSUM(fun si ->
           let tl = MATCH_MP memory_rel_tail mr in
           let ni = MATCH_MP memory_rel_Number_IMP
                      (CONJ gd (CONJ si tl)) in
           SUBST_ALL_TAC(REWRITE_RULE[injectivity "word_loc"]
                           (TRANS (SYM e2) ni)))))) THEN
     FIRST_ASSUM(fun mr ->
       if hd_is "memory_rel" (concl mr)
       then MP_TAC(REWRITE_RULE[memory_rel_def;
                                word_ml_inv_def; MAP; FST] mr)
       else fail()) THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN
     FIRST_X_ASSUM(fun a2 ->
       if hd_is "ALL2" (concl a2)
       then MP_TAC(REWRITE_RULE[MAP; all2cons] a2) else fail()) THEN
     DISCH_THEN STRIP_ASSUME_TAC THEN
     VAR_EQ_TAC THEN
     FIRST_ASSUM(fun am -> FIRST_ASSUM(fun s1 -> FIRST_ASSUM(fun s2 ->
       MP_TAC(MATCH_MP num_eq_thm
                (CONJ am (CONJ s1 s2)))))) THEN
     DISCH_THEN(CONJUNCTS_THEN2 MP_TAC
       (CONJUNCTS_THEN SUBST_ALL_TAC)) THEN
     REWRITE_TAC[injectivity "word_loc";
                 injectivity "heap_address"] THEN
     DISCH_THEN(ACCEPT_TAC o GSYM);
     bits;
     bits;
     (* neither is small, which the statement's disjunction denies *)
     FIRST_ASSUM(fun d ->
       if is_disj (concl d) then DISJ_CASES_TAC d else fail()) THEN
     clash]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_LESS = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((Number i1,w1) :: (Number i2,w2) :: vars) /\
      small_int (:'a) i1 /\
      small_int (:'a) i2 /\
      good_dimindex (:'a) ==>
        (?v1 v2. w1 = wordLang_Word v1 /\ w2 = wordLang_Word v2
          /\ (v1 < (v2:'a word) <=> i1 < i2))`),
  (* both words are the Smallnum of their integer, and num_less_thm
     says that the order of the two is the order of the integers *)
  (STRIP_TAC THEN
   FIRST_ASSUM(fun mr -> ASSUME_TAC(MATCH_MP memory_rel_swap mr)) THEN
   ALL_INST3 memory_rel_Number_IMP THEN
   ASM_MESON_TAC[num_less_thm]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_LESS_EQ = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((Number i1,w1) :: (Number i2,w2) :: vars) /\
      small_int (:'a) i1 /\
      small_int (:'a) i2 /\
      good_dimindex (:'a) ==>
        (?v1 v2. w1 = wordLang_Word v1 /\ w2 = wordLang_Word v2
          /\ (v1 <= (v2:'a word) <=> i1 <= i2))`),
  (* the order or the equality, which the two theorems above give *)
  (let wle = prove
    (`!(x:(N)word) y. x <= y <=> x < y \/ x = y`,
     REWRITE_TAC[word_ile; word_ilt; irelational2] THEN
     CONV_TAC(DEPTH_CONV BETA_CONV) THEN
     REWRITE_TAC[GSYM IVAL_EQ] THEN INT_ARITH_TAC) in
   STRIP_TAC THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun s1 -> FIRST_ASSUM(fun s2 ->
     FIRST_ASSUM(fun gd ->
       MP_TAC(MATCH_MP memory_rel_Number_EQ
         (CONJ mr (CONJ (DISJ1 s1 (concl s2)) gd))) THEN
       MP_TAC(MATCH_MP memory_rel_Number_LESS
         (CONJ mr (CONJ s1 (CONJ s2 gd)))))))) THEN
   REPEAT STRIP_TAC THEN
   REPEAT(FIRST_X_ASSUM(fun th ->
     if is_eq(concl th) && is_var(lhs(concl th))
     then SUBST_ALL_TAC th else fail())) THEN
   RULE_ASSUM_TAC(REWRITE_RULE[injectivity "word_loc"]) THEN
   ASM_REWRITE_TAC[] THEN
   ASM_MESON_TAC[wle; INT_LE_LT]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_word_msb = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i1,wordLang_Word (w:'a
  word)) :: vars) /\
      good_dimindex (:'a) /\ small_int (:'a) i1 ==>
      (word_msb w <=> i1 < (&0))`),
  (* zero is a small integer, so the relation holds of it as
     well, and the order of the two Smallnums is the order of
     the integers: the sign bit of the word says which side of
     zero it is on *)
  (let si0 = prove
    (`good_dimindex (:'a) ==> small_int (:'a) (&0)`,
     REWRITE_TAC[good_dimindex_def; small_int_def;
                 dimword] THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC) in
   let sm0 = prove
    (`Smallnum (&0) = (word 0:(N)word)`,
     REWRITE_TAC[smallnum_def] THEN
     REWRITE_TAC[INT_ARITH `~((&0:int) < &0)`] THEN
     REWRITE_TAC[INT_ARITH `(&4:int) * &0 = &0`;
                 NUM_OF_INT_OF_NUM]) in
   STRIP_TAC THEN
   FIRST_ASSUM(fun gd -> ASSUME_TAC(MATCH_MP si0 gd)) THEN
   ALL_INST3 IMP_memory_rel_Number THEN
   RULE_ASSUM_TAC(REWRITE_RULE[sm0]) THEN
   ALL_INST4 memory_rel_Number_LESS_EQ THEN
   RULE_ASSUM_TAC(REWRITE_RULE[injectivity "word_loc"]) THEN
   REWRITE_TAC[word_msb; MSB_IVAL] THEN
   ASM_MESON_TAC[word_ile; irelational2; IVAL_WORD_0;
                 INT_ARITH `(i:int) < &0 <=> ~(&0 <= i)`]));;

(* [local] *)
let memory_rel_RefPtr_EQ_lemma = prove
 (`n * 2 EXP k < dimword (:'a) /\ m * 2 EXP k < dimword (:'a) /\ 0 < k
  /\
     (n2w n << k || (n2w 1)) = (n2w m << k || ((n2w 1):'a word))
       ==> n = m`,
  (* the one in the lowest bit is free of the shifted pointer, so
     the or is a sum, the sum cancels and the shift is a
     multiplication by two to the shift, which cancels as well
     because both products are below the dimword *)
  (
   let shl_n2w = prove
    (`!n k. word_shl (n2w n:(N)word) k = n2w (n * 2 EXP k)`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN REWRITE_TAC[MULT_AC]) in
   let and1 = prove
    (`!(v:(N)word) k. 0 < k ==> word_shl v k && n2w 1 = n2w 0`,
     REPEAT STRIP_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
                 BIT_WORD_SHL; BIT_WORD_1] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
     ASM_ARITH_TAC) in
   let n2w_11 = prove
    (`!a b. a < dimword (:N) /\ b < dimword (:N)
        ==> ((n2w a:(N)word) = n2w b <=> a = b)`,
     REPEAT STRIP_TAC THEN
     REWRITE_TAC[GSYM VAL_EQ; VAL_WORD; GSYM dimword] THEN
     ASM_SIMP_TAC[MOD_LT]) in
   STRIP_TAC THEN
   FIRST_ASSUM(fun pk ->
     let a1 = MATCH_MP (ISPEC `n2w n:'a word` and1) pk
     and a2 = MATCH_MP (ISPEC `n2w m:'a word` and1) pk in
     RULE_ASSUM_TAC(REWRITE_RULE
       [GSYM (MATCH_MP WORD_ADD_OR a1);
        GSYM (MATCH_MP WORD_ADD_OR a2)])) THEN
   RULE_ASSUM_TAC(REWRITE_RULE[shl_n2w;
     WORD_ARITH `!(x:(N)word) y a. (x + a = y + a) <=> (x = y)`]) THEN
   FIRST_ASSUM(fun eq ->
     FIRST_ASSUM(fun b1 -> FIRST_ASSUM(fun b2 ->
       MP_TAC(EQ_MP (MATCH_MP n2w_11 (CONJ b1 b2)) eq)))) THEN
   SUBGOAL_THEN `~(2 EXP k = 0)` MP_TAC THENL
    [REWRITE_TAC[EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
   MESON_TAC[EQ_MULT_RCANCEL]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_RefPtr_EQ = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((RefPtr T i1,w1) :: (RefPtr T i2,w2) :: vars) /\
          good_dimindex (:'a) ==>
        (?v1 v2. w1 = wordLang_Word v1 /\ w2 = wordLang_Word
          (v2:'a word) /\ (v1 = v2 <=> i1 = i2))`),
  (* the invariant gives the heap and the roots, and ref_eq_thm
     gives the two roots as pointers with a zero annotation and
     says that the two references are the same exactly when the two
     roots are.  So the words of the statement are the two
     addresses, and they determine the pointers
     (memory_rel_RefPtr_EQ_lemma): a pointer of the roots is an
     element of the heap (roots_ok, heap_lookup_LESS), and the heap
     is short enough for the shift not to wrap
     (heap_in_memory_store) *)
  (let rec ntimes k t =
     if k <= 0 then ALL_TAC else t THEN ntimes (k-1) t in
  let SPLIT_ROOT =
    W(fun (asl,w) ->
      let lr = snd (find (fun (_,th) -> hd_is "ALL2" (concl th)) asl) in
      let hs = el 1 (snd (strip_comb (concl lr))) in
      if is_var hs then CASES_ON_TAC hs else fail()) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[ALL2]) THEN
    TRY (FIRST_ASSUM CONTR_TAC) THEN
    RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) THEN
    SPLIT_ASM_TAC in
   STRIP_TAC THEN
   FIRST_X_ASSUM (fun mr ->
     if not (hd_is "memory_rel" (concl mr)) then fail() else
     STRIP_ASSUME_TAC (REWRITE_RULE[memory_rel_def; word_ml_inv_def;
                                    MAP] mr)) THEN
   ntimes 2 SPLIT_ROOT THEN
   (* the two roots are pointers, and the references are the same
      exactly when they are (ref_eq_thm) *)
   FIRST_ASSUM (fun ai ->
     if not (hd_is "abs_ml_inv" (concl ai)) then fail() else
     STRIP_ASSUME_TAC (MATCH_MP (GEN_ALL ref_eq_thm) ai)) THEN
   VAR_EQ_TAC THEN
   REWRITE_TAC[word_addr_def] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[injectivity "word_loc"] THEN
   W(fun (asl,w) ->
     let vs,bod = strip_exists w in
     let cs = conjuncts bod in
     MAP_EVERY EXISTS_TAC [lhs (el 0 cs); lhs (el 1 cs)]) THEN
   REWRITE_TAC[] THEN
   (* so the goal is that the two addresses are the same exactly
      when the two pointers are *)
   FIRST_ASSUM (fun eq ->
     if not (is_iff (concl eq)) then fail() else
     REWRITE_TAC[eq; injectivity "heap_address"]) THEN
   EQ_TAC THENL
    [ALL_TAC;
     DISCH_THEN SUBST1_TAC THEN REFL_TAC] THEN
   (* the addresses are the pointers shifted up with a one in the
      lowest bit, so they determine the pointers *)
   REWRITE_TAC[get_addr_def; get_lowerbits_def] THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[word_bits; WORD_SUBWORD_0; WORD_OR_0] THEN
   DISCH_TAC THEN
   MATCH_MP_TAC (GEN_ALL memory_rel_RefPtr_EQ_lemma) THEN
   EXISTS_TAC `shift_length c` THEN
   REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
   TRY (REWRITE_TAC[shift_length_def] THEN ARITH_TAC) THEN
   (* a pointer of the roots is an element of the heap, and the heap
      is short enough for the shift not to wrap *)
   W(fun (asl,w) ->
     let p = lhand (lhand w) in
     let tp = rand (lhand w) in
     let dw = rand w in
     FIRST_ASSUM (fun ai ->
       if not (hd_is "abs_ml_inv" (concl ai)) then fail() else
       let rk = REWRITE_RULE[roots_ok_def]
                  (CONJUNCT1 (REWRITE_RULE[abs_ml_inv_def] ai)) in
       MP_TAC (SPEC p rk)) THEN
     REWRITE_TAC[MEM; isSomeDataElement_def] THEN
     DISCH_THEN (fun th ->
       MP_TAC (REWRITE_RULE[] (SPEC `wordLang_Word ((n2w 0):'a word)`
                                th))) THEN
     REWRITE_TAC[] THEN
     DISCH_THEN (REPEAT_TCL CHOOSE_THEN (fun hl ->
       ASSUME_TAC (MATCH_MP (GEN_ALL heap_lookup_LESS) hl))) THEN
     FIRST_ASSUM (fun hm ->
       if not (hd_is "heap_in_memory_store" (concl hm)) then fail()
       else
       ASSUME_TAC (CONJUNCT1
         (REWRITE_RULE[heap_in_memory_store_def] hm))) THEN
     MP_TAC (SPECL [tp; dw; p] LDIV_LT_EQ) THEN
     REWRITE_TAC[EXP_EQ_0; ARITH_RULE `~(2 = 0)`] THEN
     DISCH_THEN (fun iff ->
       SUBGOAL_THEN (lhs (concl iff)) (fun lt ->
         MP_TAC (EQ_MP iff lt)) THENL
        [ASM_ARITH_TAC; ALL_TAC]) THEN
     REWRITE_TAC[LEFT_ADD_DISTRIB; MULT_CLAUSES; MULT_AC] THEN
     ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_RefPtr_EQ_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m (dm:'a word->bool)
       ((RefPtr b1 i1,wordLang_Word w1) :: (RefPtr b2
         i1,wordLang_Word w2) :: vars) /\ good_dimindex (:'a) /\
     lookup i1 refs = SOME (ByteArray ys_fl ys) ==>
     w1 = w2`),
  (* the value at the pointer is a ByteArray, so the two RefPtrs
     are no thunks and the rule of v_inv for a plain reference
     gives both of them the same address *)
  (let LOOKUP_SUBST =
     FIRST_ASSUM(fun th ->
       let c = concl th in
       if is_eq c &&
          (try fst(dest_const(fst(strip_comb(lhs c)))) =
               "sptree_lookup"
           with Failure _ -> false)
       then RULE_ASSUM_TRY(REWRITE_RULE[th]) else fail()) in
   MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN SPLIT_ROOTS_TAC THEN
   V_INV_TAC v_inv_def THEN
   LOOKUP_SUBST THEN
   RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                              distinctness "bvlSem_ref"]) THEN
   TRY(FIRST_ASSUM CONTR_TAC) THEN
   FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 ->
     MATCH_ACCEPT_TAC(TRANS (SYM t1) t2)))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Boolv_T = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm vars /\ good_dimindex (:'a)
  ==> memory_rel c be ts refs sp st m dm ((Boolv T,wordLang_Word ((n2w
  18):'a word)) :: vars)`),
  (* the true Boolv is the empty Block of the true tag, which is
     one, so its root is the Data of BlockNil 1, the word eighteen *)
  (let shl16 = prove
    (`word_shl (word 1:(N)word) 4 = word 16`,
     REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD] THEN
     CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV) in
   let blocknil1 = prove
    (`BlockNil 1 = (n2w 18:'a word)`,
     REWRITE_TAC[BlockNil_def; shl16] THEN
     CONV_TAC WORD_RULE) in
   let and18 = prove
    (`(n2w 18:(N)word) && word_not (n2w 1) = n2w 18`,
     WORD_NUM_BIT_TAC 5) in
   let dimword16 = prove
    (`good_dimindex (:'a) ==> 1 < dimword (:'a) DIV 16`,
     REWRITE_TAC[good_dimindex_def; dimword] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
     CONV_TAC NUM_REDUCE_CONV) in
   let waddr = hd (word_addr_clauses ()) in
   let cons1 = REWRITE_RULE[blocknil1]
     (INST [`1`,`tag:num`] cons_thm_EMPTY) in
   REWRITE_TAC[memory_rel_def; word_ml_inv_def] THEN
   REPEAT STRIP_TAC THEN ASM_EXISTS_TAC THEN
   ASM_REWRITE_TAC[] THEN
   EXISTS_TAC
     `CONS (gc_shared_Data (wordLang_Word (n2w 18:'a word))) hs` THEN
   REWRITE_TAC[MAP; ALL2; waddr; and18] THEN
   ASM_REWRITE_TAC[dataSem_Boolv_def;
                   bool_to_tag_def; true_tag_def] THEN
   MATCH_MP_TAC cons1 THEN
   ASM_SIMP_TAC[dimword16]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Boolv_F = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm vars /\ good_dimindex (:'a)
  ==> memory_rel c be ts refs sp st m dm ((Boolv F,wordLang_Word ((n2w
  2):'a word)) :: vars)`),
  (* the false Boolv is the empty Block of the false tag, which is
     zero, so it is the same root as the one of Unit *)
  (let blocknil0 = prove
    (`BlockNil 0 = (n2w 2:'a word)`,
     REWRITE_TAC[BlockNil_def] THEN CONV_TAC WORD_RULE) in
   let and2 = prove
    (`(n2w 2:(N)word) && word_not (n2w 1) = n2w 2`,
     WORD_NUM_BIT_TAC 2) in
   let dimword16 = prove
    (`good_dimindex (:'a) ==> 0 < dimword (:'a) DIV 16`,
     REWRITE_TAC[good_dimindex_def; dimword] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
     CONV_TAC NUM_REDUCE_CONV) in
   let waddr = hd (word_addr_clauses ()) in
   let cons0 = REWRITE_RULE[blocknil0]
     (INST [`0`,`tag:num`] cons_thm_EMPTY) in
   REWRITE_TAC[memory_rel_def; word_ml_inv_def] THEN
   REPEAT STRIP_TAC THEN ASM_EXISTS_TAC THEN
   ASM_REWRITE_TAC[] THEN
   EXISTS_TAC
     `CONS (gc_shared_Data (wordLang_Word (n2w 2:'a word))) hs` THEN
   REWRITE_TAC[MAP; ALL2; waddr; and2] THEN
   ASM_REWRITE_TAC[dataSem_Boolv_def;
                   bool_to_tag_def; false_tag_def] THEN
   MATCH_MP_TAC cons0 THEN
   ASM_SIMP_TAC[dimword16]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Boolv = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm vars /\ good_dimindex (:'a) /\
     (b ==> v = wordLang_Word (n2w 18)) /\ (~b ==> v =
       wordLang_Word ((n2w 2):'a word)) ==>
     memory_rel c be ts refs sp st m dm ((Boolv b,v) :: vars)`),
  (STRIP_TAC THEN ASM_CASES_TAC `b:bool` THEN ASM_SIMP_TAC[] THENL
    [MATCH_MP_TAC memory_rel_Boolv_T;
     MATCH_MP_TAC memory_rel_Boolv_F] THEN
   ASM_REWRITE_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_ml_inv_SP_LIMIT = prove
 (cake_as_vars (fun () ->
    `word_ml_inv (heap,be,a,sp,sp1,gens) limit ts c refs stack ==> sp
  <= limit`),
  (* the unused space of the invariant lies inside the heap and the
     heap is of the limit *)
  (REWRITE_TAC[word_ml_inv_def; abs_ml_inv_def;
               unused_space_inv_def; heap_ok_def] THEN
   REPEAT STRIP_TAC THEN ARITH_ASM_TAC));;

(* HOL4 data_to_word_memoryProofScript.sml:12767-12769: the ML values
   that the definitions below antiquote *)

(* Smallnum_test[local] *)
let smallnum_test = prove
 (`((Smallnum i && --(n2w 1) << (dimindex (:'a) - 2)) = ((n2w 0):'a
  word)) /\
     good_dimindex (:'a) /\ small_int (:'a) i ==>
     ~(i < (&0)) /\ i < &(2 EXP (dimindex (:'a) - 4))`,
(* the proof of the source splits the two word sizes and reads the
   bits of the number off BITS.  Here the and with the top two bits
   says that the value is below two to the dimindex less two (the
   first two lemmas: the mask of the source is the complement of
   the mask of the lower bits, and what the and with that leaves is
   what HOL Light's VAL_WORD_AND_NOT_MASK_WORD says).  Of a
   negative number the value is the word size less four times it,
   and small_int keeps that above half the word size, which is too
   big; so the number is not negative, four times it is the value,
   and a quarter of the bound is the bound of the statement *)
  (let mask_shl = prove
   (`!k. (--(word 1):'a word) << k = word_not (word (2 EXP k - 1))`,
    GEN_TAC THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_SHL; WORD_NEG_1;
                BIT_WORD_NOT; BIT_WORD_0; GSYM WORD_OF_BITS_MASK;
                BIT_WORD_OF_BITS; IN_ELIM_THM] THEN
    REPEAT STRIP_TAC THEN ASM_ARITH_TAC) in
  let top_bits = prove
   (`!(w:'a word) k. (w && --(word 1) << k) = word 0 ==>
       val w < 2 EXP k`,
    REPEAT GEN_TAC THEN REWRITE_TAC[mask_shl] THEN
    DISCH_THEN (MP_TAC o REWRITE_RULE[GSYM VAL_EQ]) THEN
    REWRITE_TAC[VAL_WORD_AND_NOT_MASK_WORD; VAL_WORD_0] THEN
    SIMP_TAC[MULT_EQ_0; EXP_EQ_0; ARITH_EQ; DIV_EQ_0]) in
  let e16 = prove
   (`!x. 2 EXP (x + 4) = 16 * 2 EXP x /\
         2 EXP (x + 4) DIV 8 = 2 * 2 EXP x /\
         2 EXP (x + 2) = 4 * 2 EXP x`,
    GEN_TAC THEN REWRITE_TAC[EXP_ADD] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    SIMP_TAC[ARITH_RULE `2 EXP x * 16 = 8 * (2 * 2 EXP x)`;
             DIV_MULT; ARITH_EQ] THEN ARITH_TAC) in
  let div16 = prove
   (`!y. (16 * y) DIV 8 = 2 * y`,
    GEN_TAC THEN ONCE_REWRITE_TAC[ARITH_RULE `16 * y = 8 * (2 * y)`]
    THEN SIMP_TAC[DIV_MULT; ARITH_EQ]) in
  STRIP_TAC THEN
  FIRST_ASSUM (fun c ->
    if (try hd_is "word_and" (lhs (concl c))
        with Failure _ -> false)
    then ASSUME_TAC (MATCH_MP top_bits c) else fail()) THEN
  SUBGOAL_THEN `?x. dimindex (:'a) = x + 4` MP_TAC THENL
   [EXISTS_TAC `dimindex (:'a) - 4` THEN
    FIRST_ASSUM (fun gd ->
      if hd_is "good_dimindex" (concl gd)
      then MP_TAC (REWRITE_RULE[good_dimindex_def] gd)
      else fail()) THEN ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN (CHOOSE_THEN (fun eq ->
    SUBST_ALL_TAC eq THEN ASSUME_TAC eq)) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[ARITH_RULE `(x + 4) - 2 = x + 2`;
                               ARITH_RULE `(x + 4) - 4 = x`]) THEN
  REWRITE_TAC[ARITH_RULE `(x + 4) - 4 = x`] THEN
  DISJ_CASES_THEN (X_CHOOSE_THEN `n:num` SUBST_ALL_TAC)
    (SPEC `i:int` INT_IMAGE) THENL
   [(* the number is not negative *)
    RULE_ASSUM_TRY (REWRITE_RULE[smallnum_def; small_int_def;
      INT_OF_NUM_LT; INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM;
      ARITH_RULE `~(m < 0)`; dimword; VAL_WORD; e16]) THEN
    REWRITE_TAC[INT_OF_NUM_LT; ARITH_RULE `~(m < 0)`] THEN
    FIRST_ASSUM (fun b ->
      if not (try hd_is "MOD" (lhand (concl b))
              with Failure _ -> false) then fail() else
      SUBGOAL_THEN (mk_binop `(<):num->num->bool`
                      (lhand (lhand (concl b)))
                      (rand (lhand (concl b))))
        (fun lt -> MP_TAC (REWRITE_RULE[MATCH_MP MOD_LT lt] b))
      THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
    ASM_ARITH_TAC;
    (* the number is negative, which the top bits deny *)
    ASM_CASES_TAC `0 < n` THENL
     [RULE_ASSUM_TRY (REWRITE_RULE[smallnum_def; small_int_def;
        INT_NEG_LT0; INT_OF_NUM_LT; INT_OF_NUM_LE; INT_LE_NEG2;
        INT_SUB_LZERO; INT_NEG_NEG; INT_OF_NUM_MUL;
        NUM_OF_INT_OF_NUM; WORD_SUB_LZERO; dimword]) THEN
      FIRST_ASSUM (fun pos ->
        if not (try concl pos = `0 < n`
                with Failure _ -> false) then fail() else
        RULE_ASSUM_TRY (REWRITE_RULE[pos]) THEN ASSUME_TAC pos) THEN
      FIRST_ASSUM (fun eq ->
        if (try hd_is "dimindex" (lhs (concl eq))
            with Failure _ -> false)
        then RULE_ASSUM_TRY (REWRITE_RULE[VAL_WORD_NEG_CASES;
               VAL_WORD; eq; e16; div16]) else fail())
      THEN
      SUBGOAL_THEN `4 * n < 16 * 2 EXP x` ASSUME_TAC THENL
       [ASM_ARITH_TAC; ALL_TAC] THEN
      FIRST_ASSUM (fun lt ->
        if not (try concl lt = `4 * n < 16 * 2 EXP x`
                with Failure _ -> false) then fail() else
        RULE_ASSUM_TRY (REWRITE_RULE[MATCH_MP MOD_LT lt])) THEN
      FIRST_ASSUM (fun pos ->
        if not (try concl pos = `0 < n`
                with Failure _ -> false) then fail() else
        RULE_ASSUM_TRY (REWRITE_RULE[EQF_INTRO (MATCH_MP
          (ARITH_RULE `0 < n ==> ~(4 * n = 0)`) pos)])) THEN
      ASM_ARITH_TAC;
      SUBGOAL_THEN `n = 0` SUBST_ALL_TAC THENL
       [ASM_ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[INT_NEG_0; INT_OF_NUM_LT; INT_LT_REFL] THEN
      SIMP_TAC[LT_NZ; EXP_EQ_0; ARITH_EQ]]]));;

(* [local] *)
let small_int_w2i_i2w = prove
 (`small_int (:'a) i /\ good_dimindex (:'a) ==>
   w2i ((i2w ((&4) * i)):'a word) = (&4) * i`,
  (* four times a small integer is between INT_MIN and INT_MAX, so
     the i2w of it has it for its w2i *)
  (let bnds = prove
    (`good_dimindex (:'a) /\ small_int (:'a) i ==>
       --(&2 pow (dimindex (:'a) - 1)) <= (&4) * i /\
       (&4) * i < &2 pow (dimindex (:'a) - 1)`,
     REWRITE_TAC[good_dimindex_def; small_int_def;
                 dimword] THEN
     STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
     RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
     CONV_TAC NUM_REDUCE_CONV THEN
     CONV_TAC(ONCE_DEPTH_CONV INT_POW_CONV) THEN
     ASM_INT_ARITH_TAC) in
   STRIP_TAC THEN MATCH_MP_TAC IVAL_IWORD THEN
   FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 ->
     ACCEPT_TAC(MATCH_MP bnds (CONJ t1 t2))))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Add = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((Number i,wordLang_Word wi) :: (Number j,wordLang_Word wj)
          :: vars) /\
      ~(word_bit 0 wi) /\ ~(word_bit 0 wj) /\
      good_dimindex (:'a) /\ (w2i (wi + wj) = w2i wi + w2i wj) ==>
      memory_rel c be ts refs sp st m dm
        ((Number (i + j),wordLang_Word (wi + (wj:'a word))) ::
          vars)`),
  (* the sum of two small integers: the bit zero of each root is
     clear, so memory_rel_any_Number_IMP says that both integers
     are small and memory_rel_Number_IMP that the roots are their
     Smallnums, whose sum is the Smallnum of the sum, because
     Smallnum is i2w of four times the integer.  The sum is small
     in its turn, because w2i of it is four times it by the
     premise, and w2i_i2w_IMP puts that between INT_MIN and
     INT_MAX *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* the sum of two Smallnums *)
    (* the sum and the difference of two Smallnums *)
    let addsm = prove
     (`!i j. word_add (Smallnum i) (Smallnum j) =
             (Smallnum (i + j):(N)word)`,
      REWRITE_TAC[smallnum_i2w; GSYM IWORD_INT_ADD;
                  GSYM INT_ADD_LDISTRIB]) in
    (* and an integer whose four times is between INT_MIN and INT_MAX
       is a small one: the converse of small_int_IMP_MIN_MAX *)
    (* and an integer whose four times is between INT_MIN and INT_MAX
       is a small one: the converse of small_int_IMP_MIN_MAX *)
    let minmax_small = prove
     (`!i. good_dimindex (:'a) /\
           INT_MIN (:'a) <= (&4) * i /\ (&4) * i <= INT_MAX (:'a)
           ==> small_int (:'a) i`,
      REWRITE_TAC[good_dimindex_def; small_int_def;
                  dimword; integer_word_INT_MIN; integer_word_INT_MAX;
                  INT_MIN] THEN
      GEN_TAC THEN STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
      RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
      CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC) in
    let mr0 asl = grab asl (fun th -> hd_is "memory_rel" (concl th)) in
    let mr1 asl = MATCH_MP memory_rel_tail (mr0 asl) in
    let mr2 asl = MATCH_MP memory_rel_tail (mr1 asl) in
    let smalls =
      W(fun (asl,w) ->
        let gd = grab asl (fun th ->
          hd_is "good_dimindex" (concl th)) in
        let nbs = map snd (filter (fun (_,th) ->
          is_neg (concl th) &&
          (try hd_is "bit" (rand (concl th)) with Failure _ -> false))
          asl) in
        let any = memory_rel_any_Number_IMP in
        let step m =
          MP_TAC(MATCH_MP any (CONJ gd m)) THEN
          REWRITE_TAC[injectivity "word_loc"; word_index] THEN
          DISCH_THEN(CHOOSE_THEN(fun th ->
            ASSUME_TAC(REWRITE_RULE (GSYM(CONJUNCT1 th) :: nbs)
                         (CONJUNCT2 th)))) in
        step (mr0 asl) THEN step (mr1 asl)) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    smalls THEN
    W(fun (asl,w) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let num = memory_rel_Number_IMP in
      let inj = REWRITE_RULE[injectivity "word_loc"] in
      let sis = filter (fun (_,th) -> hd_is "small_int" (concl th))
                  asl in
      let e1 = inj (MATCH_MP num
        (CONJ gd (CONJ (snd (el 1 sis)) (mr0 asl)))) in
      let e2 = inj (MATCH_MP num
        (CONJ gd (CONJ (snd (el 0 sis)) (mr1 asl)))) in
      RULE_ASSUM_TAC(REWRITE_RULE[e1; e2]) THEN
      REWRITE_TAC[e1; e2]) THEN
    REWRITE_TAC[addsm] THEN
    MATCH_MP_TAC IMP_memory_rel_Number THEN
    W(fun (asl,w) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let sis = filter (fun (_,th) -> hd_is "small_int" (concl th))
                  asl in
      let sw = small_int_w2i_i2w in
      let e1 = MATCH_MP sw (CONJ (snd (el 1 sis)) gd) in
      let e2 = MATCH_MP sw (CONJ (snd (el 0 sis)) gd) in
      let hy = grab asl (fun th -> hd_is "ival" (lhs (concl th))) in
      let th = REWRITE_RULE[smallnum_i2w; e1; e2;
                            GSYM IWORD_INT_ADD;
                            GSYM INT_ADD_LDISTRIB] hy in
      ASSUME_TAC(MATCH_MP minmax_small
        (CONJ gd (MATCH_MP w2i_i2w_IMP th))) THEN
      ASM_REWRITE_TAC[mr2 asl])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Sub = prove
