                  INT_MIN] THEN
      GEN_TAC THEN STRIP_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
      RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
      CONV_TAC NUM_REDUCE_CONV THEN ASM_INT_ARITH_TAC) in
    let mr0 asl = grab asl (fun th -> hd_is "memory_rel" (concl th)) in
    let mr1 asl = MATCH_MP memory_rel_tail (mr0 asl) in
    let mr2 asl = MATCH_MP memory_rel_tail (mr1 asl) in
    let smalls =
      W(fun (asl,w) ->
        let gd = grab asl (fun th ->
          hd_is "good_dimindex" (concl th)) in
        let nbs = map snd (filter (fun (_,th) ->
          is_neg (concl th) &&
          (try hd_is "bit" (rand (concl th)) with Failure _ -> false))
          asl) in
        let any = memory_rel_any_Number_IMP in
        let step m =
          MP_TAC(MATCH_MP any (CONJ gd m)) THEN
          REWRITE_TAC[injectivity "word_loc"; word_index] THEN
          DISCH_THEN(CHOOSE_THEN(fun th ->
            ASSUME_TAC(REWRITE_RULE (GSYM(CONJUNCT1 th) :: nbs)
                         (CONJUNCT2 th)))) in
        step (mr0 asl) THEN step (mr1 asl)) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    smalls THEN
    W(fun (asl,w) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let num = memory_rel_Number_IMP in
      let inj = REWRITE_RULE[injectivity "word_loc"] in
      let sis = filter (fun (_,th) -> hd_is "small_int" (concl th))
                  asl in
      let e1 = inj (MATCH_MP num
        (CONJ gd (CONJ (snd (el 1 sis)) (mr0 asl)))) in
      let e2 = inj (MATCH_MP num
        (CONJ gd (CONJ (snd (el 0 sis)) (mr1 asl)))) in
      RULE_ASSUM_TAC(REWRITE_RULE[e1; e2]) THEN
      REWRITE_TAC[e1; e2]) THEN
    REWRITE_TAC[subsm] THEN
    MATCH_MP_TAC IMP_memory_rel_Number THEN
    W(fun (asl,w) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let sis = filter (fun (_,th) -> hd_is "small_int" (concl th))
                  asl in
      let sw = small_int_w2i_i2w in
      let e1 = MATCH_MP sw (CONJ (snd (el 1 sis)) gd) in
      let e2 = MATCH_MP sw (CONJ (snd (el 0 sis)) gd) in
      let hy = grab asl (fun th -> hd_is "ival" (lhs (concl th))) in
      let th = REWRITE_RULE[smallnum_i2w; e1; e2;
                            GSYM IWORD_INT_SUB;
                            GSYM INT_SUB_LDISTRIB] hy in
      ASSUME_TAC(MATCH_MP minmax_small
        (CONJ gd (MATCH_MP w2i_i2w_IMP th))) THEN
      ASM_REWRITE_TAC[mr2 asl])));;

(* [local] *)
let exists_num = prove
 (`~(i < (&0:int)) <=> (?n. i = &n)`,
  (* an integer that is not below zero is the injection of a
     number, which is HOL Light's INT_OF_NUM_EXISTS *)
  (REWRITE_TAC[INT_OF_NUM_EXISTS; INT_NOT_LT]));;

(* [simp] *)
let small_int_w2n = prove
 (`good_dimindex (:'a) ==> small_int (:'a) (&(w2n (w:word8)))`,
  (* a byte is below 256 and the bound of a small integer is a
     quarter of the dimword, which good_dimindex makes 2 EXP 29 at
     the least *)
  (REWRITE_TAC[good_dimindex_def; small_int_def;
               dimword] THEN
   STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
   MATCH_MP_TAC(INT_ARITH
     `&0 <= (i:int) /\ i < n ==> --n <= i /\ i < n`) THEN
   REWRITE_TAC[INT_POS; INT_OF_NUM_LT] THEN
   MP_TAC(ISPEC `w:word8` VAL_BOUND) THEN
   REWRITE_TAC[DIMINDEX_8] THEN CONV_TAC NUM_REDUCE_CONV THEN
   ARITH_TAC));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_And = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((Number (&(w2n (i:word8))),wordLang_Word wi) :: (Number
          (&(w2n j)),wordLang_Word wj) :: vars) /\
      good_dimindex (:'a) ==>
      memory_rel c be ts refs sp st m dm
        ((Number (&(w2n (i && j))),wordLang_Word (wi && (wj:'a
          word))) :: vars)`),
  (* the and of two bytes as the and of their roots: both roots are
     the Smallnum of their byte, because a byte is a small integer,
     and the and of two Smallnums of bytes is the Smallnum of the
     and of the bytes, because the Smallnum of a byte has the bits
     of the byte two places up *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* the Smallnum of a natural number is four times it, and the and
       with the complement of one leaves such a word alone *)
    let smn = prove
     (`!n. Smallnum (&n) = (n2w (4 * n)):(N)word`,
      GEN_TAC THEN REWRITE_TAC[smallnum_def] THEN
      REWRITE_TAC[INT_ARITH `~((&n:int) < &0)`] THEN
      REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM]) in
    (* the bits of the Smallnum of a byte: two above the bits
       of the byte *)
    let bitsm = prove
     (`!(x:(M)word) i.
         bit i (n2w (4 * w2n x):(N)word) <=>
         i < dimindex (:N) /\ 2 <= i /\ bit (i - 2) x`,
      REPEAT GEN_TAC THEN REWRITE_TAC[BIT_WORD] THEN
      ASM_CASES_TAC `2 <= i` THENL
       [FIRST_ASSUM(X_CHOOSE_THEN `k:num` SUBST1_TAC o
          REWRITE_RULE[LE_EXISTS]) THEN
        REWRITE_TAC[ARITH_RULE `(2 + k) - 2 = k`; BIT_VAL] THEN
        REWRITE_TAC[EXP_ADD; ARITH_RULE `2 EXP 2 = 4`] THEN
        SIMP_TAC[DIV_MULT2; ARITH_EQ] THEN
        REWRITE_TAC[ARITH_RULE `(2 <= 2 + k) <=> T`] THEN
        CONV_TAC TAUT;
        ASM_REWRITE_TAC[] THEN
        FIRST_ASSUM(fun th ->
          DISJ_CASES_THEN SUBST1_TAC
            (MATCH_MP (ARITH_RULE
               `~(2 <= i) ==> i = 0 \/ i = 1`) th)) THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        REWRITE_TAC[DIV_1] THEN
        REWRITE_TAC[ARITH_RULE `4 * n = 2 * (2 * n)`] THEN
        SIMP_TAC[DIV_MULT; ARITH_EQ] THEN
        REWRITE_TAC[ODD_MULT] THEN CONV_TAC NUM_REDUCE_CONV THEN
        CONV_TAC TAUT]) in
    (* and the Smallnum of a bitwise operation on bytes is the
       operation on the Smallnums *)
    let andsm = prove
     (`!(x:word8) y.
         word_and (Smallnum (&(w2n x))) (Smallnum (&(w2n y))) =
         (Smallnum (&(w2n (word_and x y))):(N)word)`,
      REPEAT GEN_TAC THEN REWRITE_TAC[smn; WORD_EQ_BITS_ALT] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[BIT_WORD_AND_ALT; bitsm] THEN CONV_TAC TAUT) in

    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    W(fun (asl,w) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let mr = grab asl (fun th -> hd_is "memory_rel" (concl th)) in
      let tl = memory_rel_tail in
      let mr2 = MATCH_MP tl mr in
      let mr3 = MATCH_MP tl mr2 in
      let inj = REWRITE_RULE[injectivity "word_loc"] in
      let siw = MATCH_MP small_int_w2n gd in
      let byte th =
        rand (rand (rand (fst(dest_pair(lhand(last
          (snd(strip_comb (concl th)))))))) ) in
      let wv = find (fun v -> type_of v = type_of (byte mr))
                 (frees (concl siw)) in
      let num = memory_rel_Number_IMP in
      let e1 = inj (MATCH_MP num
                      (CONJ gd (CONJ (INST [byte mr,wv] siw) mr))) in
      let e2 = inj (MATCH_MP num
                      (CONJ gd (CONJ (INST [byte mr2,wv] siw) mr2))) in
      REWRITE_TAC[e1; e2; andsm] THEN
      MATCH_MP_TAC IMP_memory_rel_Number THEN
      ASM_REWRITE_TAC[siw; mr3])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Or = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((Number (&(w2n (i:word8))),wordLang_Word wi) :: (Number
          (&(w2n j)),wordLang_Word wj) :: vars) /\
      good_dimindex (:'a) ==>
      memory_rel c be ts refs sp st m dm
        ((Number (&(w2n (i || j))),wordLang_Word (wi || (wj:'a
          word))) :: vars)`),
  (* the or of two bytes as the or of their roots: both roots are
     the Smallnum of their byte, because a byte is a small integer,
     and the or of two Smallnums of bytes is the Smallnum of the
     or of the bytes, because the Smallnum of a byte has the bits
     of the byte two places up *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* the Smallnum of a natural number is four times it, and the and
       with the complement of one leaves such a word alone *)
    let smn = prove
     (`!n. Smallnum (&n) = (n2w (4 * n)):(N)word`,
      GEN_TAC THEN REWRITE_TAC[smallnum_def] THEN
      REWRITE_TAC[INT_ARITH `~((&n:int) < &0)`] THEN
      REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM]) in
    (* the bits of the Smallnum of a byte: two above the bits
       of the byte *)
    let bitsm = prove
     (`!(x:(M)word) i.
         bit i (n2w (4 * w2n x):(N)word) <=>
         i < dimindex (:N) /\ 2 <= i /\ bit (i - 2) x`,
      REPEAT GEN_TAC THEN REWRITE_TAC[BIT_WORD] THEN
      ASM_CASES_TAC `2 <= i` THENL
       [FIRST_ASSUM(X_CHOOSE_THEN `k:num` SUBST1_TAC o
          REWRITE_RULE[LE_EXISTS]) THEN
        REWRITE_TAC[ARITH_RULE `(2 + k) - 2 = k`; BIT_VAL] THEN
        REWRITE_TAC[EXP_ADD; ARITH_RULE `2 EXP 2 = 4`] THEN
        SIMP_TAC[DIV_MULT2; ARITH_EQ] THEN
        REWRITE_TAC[ARITH_RULE `(2 <= 2 + k) <=> T`] THEN
        CONV_TAC TAUT;
        ASM_REWRITE_TAC[] THEN
        FIRST_ASSUM(fun th ->
          DISJ_CASES_THEN SUBST1_TAC
            (MATCH_MP (ARITH_RULE
               `~(2 <= i) ==> i = 0 \/ i = 1`) th)) THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        REWRITE_TAC[DIV_1] THEN
        REWRITE_TAC[ARITH_RULE `4 * n = 2 * (2 * n)`] THEN
        SIMP_TAC[DIV_MULT; ARITH_EQ] THEN
        REWRITE_TAC[ODD_MULT] THEN CONV_TAC NUM_REDUCE_CONV THEN
        CONV_TAC TAUT]) in
    let orsm = prove
     (`!(x:word8) y.
         word_or (Smallnum (&(w2n x))) (Smallnum (&(w2n y))) =
         (Smallnum (&(w2n (word_or x y))):(N)word)`,
      REPEAT GEN_TAC THEN REWRITE_TAC[smn; WORD_EQ_BITS_ALT] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[BIT_WORD_OR_ALT; bitsm] THEN CONV_TAC TAUT) in

    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    W(fun (asl,w) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let mr = grab asl (fun th -> hd_is "memory_rel" (concl th)) in
      let tl = memory_rel_tail in
      let mr2 = MATCH_MP tl mr in
      let mr3 = MATCH_MP tl mr2 in
      let inj = REWRITE_RULE[injectivity "word_loc"] in
      let siw = MATCH_MP small_int_w2n gd in
      let byte th =
        rand (rand (rand (fst(dest_pair(lhand(last
          (snd(strip_comb (concl th)))))))) ) in
      let wv = find (fun v -> type_of v = type_of (byte mr))
                 (frees (concl siw)) in
      let num = memory_rel_Number_IMP in
      let e1 = inj (MATCH_MP num
                      (CONJ gd (CONJ (INST [byte mr,wv] siw) mr))) in
      let e2 = inj (MATCH_MP num
                      (CONJ gd (CONJ (INST [byte mr2,wv] siw) mr2))) in
      REWRITE_TAC[e1; e2; orsm] THEN
      MATCH_MP_TAC IMP_memory_rel_Number THEN
      ASM_REWRITE_TAC[siw; mr3])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Xor = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((Number (&(w2n (i:word8))),wordLang_Word wi) :: (Number
          (&(w2n j)),wordLang_Word wj) :: vars) /\
      good_dimindex (:'a) ==>
      memory_rel c be ts refs sp st m dm
        ((Number (&(w2n (word_xor i j))),wordLang_Word (word_xor
          wi wj:'a word)) :: vars)`),
  (* the xor of two bytes as the xor of their roots: both roots are
     the Smallnum of their byte, because a byte is a small integer,
     and the xor of two Smallnums of bytes is the Smallnum of the
     xor of the bytes, because the Smallnum of a byte has the bits
     of the byte two places up *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* the Smallnum of a natural number is four times it, and the and
       with the complement of one leaves such a word alone *)
    let smn = prove
     (`!n. Smallnum (&n) = (n2w (4 * n)):(N)word`,
      GEN_TAC THEN REWRITE_TAC[smallnum_def] THEN
      REWRITE_TAC[INT_ARITH `~((&n:int) < &0)`] THEN
      REWRITE_TAC[INT_OF_NUM_MUL; NUM_OF_INT_OF_NUM]) in
    (* the bits of the Smallnum of a byte: two above the bits
       of the byte *)
    let bitsm = prove
     (`!(x:(M)word) i.
         bit i (n2w (4 * w2n x):(N)word) <=>
         i < dimindex (:N) /\ 2 <= i /\ bit (i - 2) x`,
      REPEAT GEN_TAC THEN REWRITE_TAC[BIT_WORD] THEN
      ASM_CASES_TAC `2 <= i` THENL
       [FIRST_ASSUM(X_CHOOSE_THEN `k:num` SUBST1_TAC o
          REWRITE_RULE[LE_EXISTS]) THEN
        REWRITE_TAC[ARITH_RULE `(2 + k) - 2 = k`; BIT_VAL] THEN
        REWRITE_TAC[EXP_ADD; ARITH_RULE `2 EXP 2 = 4`] THEN
        SIMP_TAC[DIV_MULT2; ARITH_EQ] THEN
        REWRITE_TAC[ARITH_RULE `(2 <= 2 + k) <=> T`] THEN
        CONV_TAC TAUT;
        ASM_REWRITE_TAC[] THEN
        FIRST_ASSUM(fun th ->
          DISJ_CASES_THEN SUBST1_TAC
            (MATCH_MP (ARITH_RULE
               `~(2 <= i) ==> i = 0 \/ i = 1`) th)) THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        REWRITE_TAC[DIV_1] THEN
        REWRITE_TAC[ARITH_RULE `4 * n = 2 * (2 * n)`] THEN
        SIMP_TAC[DIV_MULT; ARITH_EQ] THEN
        REWRITE_TAC[ODD_MULT] THEN CONV_TAC NUM_REDUCE_CONV THEN
        CONV_TAC TAUT]) in
    let xorsm = prove
     (`!(x:word8) y.
         word_xor (Smallnum (&(w2n x))) (Smallnum (&(w2n y))) =
         (Smallnum (&(w2n (word_xor x y))):(N)word)`,
      REPEAT GEN_TAC THEN REWRITE_TAC[smn; WORD_EQ_BITS_ALT] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[BIT_WORD_XOR_ALT; bitsm] THEN CONV_TAC TAUT) in

    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    W(fun (asl,w) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let mr = grab asl (fun th -> hd_is "memory_rel" (concl th)) in
      let tl = memory_rel_tail in
      let mr2 = MATCH_MP tl mr in
      let mr3 = MATCH_MP tl mr2 in
      let inj = REWRITE_RULE[injectivity "word_loc"] in
      let siw = MATCH_MP small_int_w2n gd in
      let byte th =
        rand (rand (rand (fst(dest_pair(lhand(last
          (snd(strip_comb (concl th)))))))) ) in
      let wv = find (fun v -> type_of v = type_of (byte mr))
                 (frees (concl siw)) in
      let num = memory_rel_Number_IMP in
      let e1 = inj (MATCH_MP num
                      (CONJ gd (CONJ (INST [byte mr,wv] siw) mr))) in
      let e2 = inj (MATCH_MP num
                      (CONJ gd (CONJ (INST [byte mr2,wv] siw) mr2))) in
      REWRITE_TAC[e1; e2; xorsm] THEN
      MATCH_MP_TAC IMP_memory_rel_Number THEN
      ASM_REWRITE_TAC[siw; mr3])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_IMP_Word = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i,v) :: vars) ==>
  (?w. v = wordLang_Word w)`),
  (* a Number stands for a Data of its Smallnum or for a Pointer at
     its Bignum, and the word_addr of either is a Word *)
  (MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN ASM_MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_IMP_Word_2 = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i,v) :: (Number j,w) ::
  vars) ==>
      (?w1 w2. v = wordLang_Word w1 /\ w = wordLang_Word w2)`),
  (* the same of the two Numbers at the head of the list *)
  (MEMORY_REL_TAC THEN SPLIT_ROOTS_TAC THEN V_INV_TAC v_inv_def THEN
   ASM_MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_zero_space = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm vars ==>
      memory_rel c be ts refs 0 st m dm vars`),
  (REWRITE_TAC[memory_rel_def] THEN STRIP_TAC THEN
   ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[LE_0]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_less_space = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm vars /\ sp' <= sp ==>
     memory_rel c be ts refs sp' st m dm vars`),
  (REWRITE_TAC[memory_rel_def] THEN REPEAT STRIP_TAC THEN
   ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC));;

let all_ones_bit = prove
 (`i < dimindex (:'a) ==>
   (FAPPLY (all_ones e b:'a word) i <=> b <= i /\ i < e)`,
  (* all_ones is the slice of the word of all ones, so its bit is
     the one of the subword that the slice shifts up *)
  (DISCH_TAC THEN
   REWRITE_TAC[word_index; all_ones_def] THEN
   COND_CASES_TAC THENL
    [REWRITE_TAC[BIT_WORD_0] THEN
     FIRST_ASSUM(fun th -> MP_TAC th) THEN ARITH_TAC;
     ALL_TAC] THEN
   ASM_SIMP_TAC[word_slice; word_bits; BIT_WORD_SHL;
                BIT_WORD_SUBWORD; BIT_WORD_NOT; BIT_WORD_0] THEN
   REWRITE_TAC[ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
   REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   POP_ASSUM_LIST(fun ths -> MAP_EVERY MP_TAC ths) THEN ARITH_TAC));;

let maxout_bits_bit = prove
 (`FAPPLY
     (maxout_bits n l b:'a word) i /\ i < dimindex (:'a) ==>
     b <= i /\ i < b + l`,
  (* maxout_bits is the number shifted up by the base, and a number
     below two to the width of the field has no bit at the width or
     above, or it is all the ones of the field *)
  (let odd_div = prove
    (`!k m i. k < 2 EXP m /\ m <= i
              ==> (ODD (k DIV 2 EXP i) <=> F)`,
     REPEAT STRIP_TAC THEN
     SUBGOAL_THEN `k DIV 2 EXP i = 0` SUBST1_TAC THENL
      [MATCH_MP_TAC DIV_LT THEN
       TRANS_TAC LTE_TRANS `2 EXP m` THEN
       ASM_REWRITE_TAC[LE_EXP] THEN ARITH_TAC;
       REWRITE_TAC[ODD]]) in
   REWRITE_TAC[word_index; maxout_bits_def] THEN
   COND_CASES_TAC THENL
    [REWRITE_TAC[BIT_WORD_SHL; BIT_WORD] THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     MP_TAC(SPECL [`n:num`; `l:num`; `i - b`] odd_div) THEN
     ASM_REWRITE_TAC[] THEN
     ASM_SIMP_TAC[ARITH_RULE `n < m - 1 ==> n < m`] THEN
     ARITH_ASM_TAC;
     STRIP_TAC THEN
     ASM_MESON_TAC[REWRITE_RULE[word_index] all_ones_bit]]));;

let maxout_bits_IMP = prove
 (`i < dimindex (:'a) /\ FAPPLY (maxout_bits tag k n:'a word) i ==> i
  < n + k`,
  (REPEAT STRIP_TAC THEN
   FIRST_ASSUM(fun th1 -> FIRST_ASSUM(fun th2 ->
     MP_TAC(MATCH_MP maxout_bits_bit (CONJ th1 th2)))) THEN
   ARITH_TAC));;

let make_cons_ptr_thm = prove
 (`make_cons_ptr conf (f:'a word) tag len =
     wordLang_Word ((f << (shift_length conf -
       backend_common_word_shift (:'a)) || (n2w 1) ||
            ptr_bits conf tag len))`,
  (* the lower bits of ptr_bits are ptr_bits itself, which the
     source proves here as well (the theorem that states it on its
     own stands further down the file) *)
  (let mb = REWRITE_RULE[word_index] maxout_bits_IMP in
   let bits_lt = prove
    (`!i. i < dimindex (:'a) /\ bit i (ptr_bits c x y:'a word)
          ==> i < small_shift_length c`,
     REWRITE_TAC[ptr_bits_def; small_shift_length_def;
                 BIT_WORD_OR] THEN
     REPEAT STRIP_TAC THEN
     FIRST_X_ASSUM(fun th ->
       MP_TAC(MATCH_MP mb
         (CONJ (ASSUME `i < dimindex (:'a)`) th))) THEN
     ARITH_TAC) in
   let glp = prove
    (`get_lowerbits c (wordLang_Word (ptr_bits c x y)) =
      (ptr_bits c x y || (n2w 1))`,
     REWRITE_TAC[get_lowerbits_def] THEN MATCH_REDUCE_TAC THEN
     AP_THM_TAC THEN AP_TERM_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; word_bits; BIT_WORD_SUBWORD;
                 ADD_CLAUSES] THEN
     GEN_TAC THEN DISCH_TAC THEN EQ_TAC THENL
      [SIMP_TAC[];
       DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
       FIRST_ASSUM(fun th1 -> FIRST_ASSUM(fun th2 ->
         MP_TAC(MATCH_MP bits_lt (CONJ th2 th1)))) THEN
       ASM_ARITH_TAC]) in
   REWRITE_TAC[make_cons_ptr_def; glp] THEN
   AP_TERM_TAC THEN WORD_BITWISE_TAC));;

(* [local] *)
let Num_ABS_lemmas = prove
 (`num_of_int (abs (&n)) = n /\ num_of_int (abs (--(&n))) = n`,
  (REWRITE_TAC[INT_ABS_NUM; INT_ABS_NEG; NUM_OF_INT_OF_NUM]));;

let word_cmp_res_def = cake_define
  `word_cmp_res i (j:int) =
     (if i = j then (n2w 1) else if i < j then (n2w 0) else (n2w
       2))`;;

(* the termination relation is not in the HOL4 source *)
let word_cmp_loop_def = cake_define_try_tac (fun () ->
  `MEASURE (w2n o FST)`)
  TERM_TAC
  `word_cmp_loop (l:'a word) (a1:'a word) a2 dm (m:'a word->'a word_loc)
  =
     (if l = (n2w 0) then SOME (n2w 1) else
       if a1 IN dm /\ a2 IN dm then
         match (m a1,m a2) with (wordLang_Word w1,wordLang_Word w2)
           ->
             (if w1 = w2 then
               word_cmp_loop (l - (n2w 1)) (a1 - bytes_in_word)
                 (a2 - bytes_in_word) dm m else if w1 <+ w2 then
                   SOME (n2w 0) else SOME ((n2w 2):'a word)) | _67 ->
                   NONE else NONE)`;;

(* HOL4 data_to_word_memoryProofScript.sml:13106: ML code, not ported *)

(* the port's own: the word level of this file begins here, and
   what it needs of the separating conjunction.  HOL4's SEP_R_TAC
   is read_fun2set applied to an assumption, with the star
   rearranged so that the cell is at the front (star_front, over
   the STAR_AC of ml/lib/set_sep.ml); the last cell of a word_list
   is where a loop over it starts (word_list_SNOC); and the three
   word equations are the addresses and the counter of such a loop
   (addr_step, addr_prev, len_step) *)

let sep_read = prove
 (`!a x p (f:B->A) d. (set_sep_one (a,x) * p) (fun2set (f,d))
    ==> f a = x /\ a IN d`,
  MATCH_ACCEPT_TAC read_fun2set);;

let star_front = prove
 (`!p c f (s:(B#A->bool)). ((p * set_sep_one c) * f) s
    ==> (set_sep_one c * (p * f)) s`,
  REPEAT GEN_TAC THEN
   SUBGOAL_THEN
     `((p:(B#A->bool)->bool) * set_sep_one c) * f =
      set_sep_one c * (p * f)`
     (fun e -> REWRITE_TAC[e]) THENL
    [CONV_TAC (AC STAR_AC)]);;

let word_list_SNOC = prove
 (`!xs x a. misc_word_list a (xs ++ [x]) =
           misc_word_list a xs *
           set_sep_one (a + n2w (LENGTH xs) * bytes_in_word,x)`,
  REWRITE_TAC[word_list_APPEND; word_list_def; STAR_emp]);;

let addr_step = prove
 (`!(a:'a word) n. a + bytes_in_word * n2w (n + 1) =
                  (a + bytes_in_word) + n2w n * bytes_in_word`,
  REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE);;

let addr_prev = prove
 (`!(a:'a word) n.
    ((a + bytes_in_word) + n2w n * bytes_in_word) - bytes_in_word =
    a + bytes_in_word * n2w n`,
  REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE);;

let len_step = prove
 (`!n. (n2w (n + 1):'a word) - n2w 1 = n2w n`,
  REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE);;

(* [local] *)
let word_cmp_loop_thm = prove
 (`!xs1 (xs2:('a word) list) f1 f2 (a1:'a word) a2.
     LENGTH xs1 = LENGTH xs2 /\ LENGTH xs1 < dimword (:'a) /\
     (misc_word_list (a1 + bytes_in_word) (MAP wordLang_Word xs1) *
       f1) (fun2set (m,dm)) /\
     (misc_word_list (a2 + bytes_in_word) (MAP wordLang_Word xs2) *
       f2) (fun2set (m,dm)) ==>
     word_cmp_loop (n2w (LENGTH xs1))
       (a1 + bytes_in_word * n2w (LENGTH xs1))
       (a2 + bytes_in_word * n2w (LENGTH xs1)) dm m =
       SOME (match mw_cmp xs1 xs2 with NONE -> (n2w 1) | SOME T ->
         (n2w 0) | SOME F -> (n2w 2))`,
  (* the first proof of the word level, and the shape the thirty
     others of this file have.  The induction is the complete one
     on the length of the two lists, which is what mw_cmp recurses
     on (PORTING-GUIDE.md entry 44, since the port has no
     mw_cmp_ind); the loop starts at the last cell of each list, so
     each list is taken apart at its end (SNOC_CASES) and the cell
     of its last element comes out of the memory by the steps above
     the statement -- star_front and read_fun2set, which is what
     HOL4's SEP_R_TAC does; the addresses and the counter of the
     step back are the three word equations of the block; and the
     hypothesis at the two fronts is what the branch where the two
     last elements agree leaves *)
  ((* the complete induction on the length of the two lists, which
     is what mw_cmp recurses on *)
  SUBGOAL_THEN
   `!k xs1 (xs2:('a word) list) f1 f2 (a1:'a word) a2.
      LENGTH xs1 <= k /\ LENGTH xs1 = LENGTH xs2 /\
      LENGTH xs1 < dimword (:'a) /\
      (misc_word_list (a1 + bytes_in_word) (MAP wordLang_Word xs1) *
        f1) (fun2set (m,dm)) /\
      (misc_word_list (a2 + bytes_in_word) (MAP wordLang_Word xs2) *
        f2) (fun2set (m,dm))
      ==> word_cmp_loop (n2w (LENGTH xs1))
            (a1 + bytes_in_word * n2w (LENGTH xs1))
            (a2 + bytes_in_word * n2w (LENGTH xs1)) dm m =
          SOME (match mw_cmp xs1 xs2 with NONE -> (n2w 1)
                | SOME T -> (n2w 0) | SOME F -> (n2w 2))`
   (fun th ->
      REPEAT GEN_TAC THEN DISCH_TAC THEN
      MP_TAC (SPEC `LENGTH (xs1:('a word) list)` th) THEN
      ASM_MESON_TAC[LE_REFL]) THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN DISCH_TAC THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* of two empty lists the loop stops at once *)
  ASM_CASES_TAC `xs1:('a word) list = []` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    RULE_ASSUM_TRY (REWRITE_RULE[LENGTH]) THEN
    SUBGOAL_THEN `xs2:('a word) list = []` SUBST_ALL_TAC THENL
     [REWRITE_TAC[GSYM LENGTH_EQ_NIL] THEN
      FIRST_ASSUM (ACCEPT_TAC o SYM);
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[word_cmp_loop_def; mw_cmp_def] THEN
    REWRITE_TAC[LENGTH] THEN
    TRY SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  (* and of two lists that end in an element: the two elements *)
  W(fun gl ->
    let x1 = var_by_name "xs1" gl in
    STRIP_ASSUME_TAC (MATCH_MP SNOC_CASES
      (the_asm (fun c -> is_neg c && is_eq (rand c) &&
         lhand (rand c) = x1) gl))) THEN
  FIRST_X_ASSUM SUBST_ALL_TAC THEN
  (* and so does the other list, because they are of one length *)
  W(fun gl ->
    let x2 = var_by_name "xs2" gl in
    let ety = hd (snd (dest_type (type_of x2))) in
    SUBGOAL_THEN (mk_neg (mk_eq (x2,
        mk_const ("NIL", [ety,`:A`]))))
      (fun ne -> STRIP_ASSUME_TAC (MATCH_MP SNOC_CASES ne))) THENL
   [REWRITE_TAC[GSYM LENGTH_EQ_NIL] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[LENGTH_SNOC]) THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  FIRST_X_ASSUM SUBST_ALL_TAC THEN
  (* the cell of each last element, taken out of the memory *)
  RULE_ASSUM_TRY (REWRITE_RULE[SNOC_APPEND; MAP_APPEND; MAP;
                               word_list_SNOC; LENGTH_MAP]) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[LENGTH_SNOC; LENGTH_APPEND;
                               LENGTH]) THEN
  REWRITE_TAC[LENGTH_SNOC] THEN
  (* the two lists are of one length, and the counter is a sum *)
  W(fun (asl,w as gl) ->
    let y = var_by_name "y" gl and y' = var_by_name "y'" gl in
    SUBGOAL_THEN (mk_eq (list_mk_icomb "LENGTH" [y'],
                         list_mk_icomb "LENGTH" [y]))
      (fun e -> RULE_ASSUM_TRY (REWRITE_RULE[e]) THEN
                ASSUME_TAC e)) THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TRY (CONV_RULE NUM_REDUCE_CONV) THEN
  (* the two cells, out of the memory *)
  W(fun (asl,_) ->
    MAP_EVERY (fun th -> TRY (STRIP_ASSUME_TAC th))
      (mapfilter (fun (_,t) ->
         MATCH_MP sep_read (MATCH_MP star_front t)) asl)) THEN
  (* the address of the last cell is where the loop starts *)
  REWRITE_TAC[addr_step] THEN
  (* the loop and the comparison, one step each *)
  ONCE_REWRITE_TAC[word_cmp_loop_def] THEN
  ONCE_REWRITE_TAC[mw_cmp_def] THEN
  REWRITE_TAC[NOT_SNOC_NIL; LAST_SNOC; FRONT_SNOC] THEN
  (* the counter is not zero, because the lists are not empty *)
  W(fun (asl,w as gl) ->
    let lt = the_asm (fun c ->
               is_binop `(<):num->num->bool` c &&
               hd_is "dimword" (rand c)) gl in
    REWRITE_TAC[MATCH_MP WORD_EQ_0 (REWRITE_RULE[dimword] lt)]) THEN
  REWRITE_TAC[ADD_EQ_0; ARITH_EQ] THEN
  (* the two addresses are in the domain and hold the two last
     elements *)
  ASM_REWRITE_TAC[] THEN
  TRY SAFE_MATCH_REDUCE_TAC THEN
  (* the step back to the cell before the last, and the counter *)
  REWRITE_TAC[addr_prev; len_step] THEN
  (* the rest of the two lists, for the hypothesis *)
  RULE_ASSUM_TRY (REWRITE_RULE[GSYM STAR_ASSOC]) THEN
  (* where the two last elements differ the loop stops *)
  TRY (SOLVED (COND_CASES_TAC THEN REWRITE_TAC[])) THEN
  (* the front of the list is shorter than the whole of it *)
  W(fun (asl,w as gl) ->
    let y = var_by_name "y" gl in
    let lt = the_asm (fun c ->
               is_binop `(<):num->num->bool` c &&
               hd_is "dimword" (rand c)) gl in
    SUBGOAL_THEN (mk_binop `(<):num->num->bool`
        (list_mk_icomb "LENGTH" [y]) (rand (concl lt)))
       ASSUME_TAC) THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  (* and where they agree it goes on, which is the hypothesis at
     the two fronts *)
  W(fun (asl,w as gl) ->
    let y = var_by_name "y" gl in
    let ih = the_asm (fun c -> is_forall c &&
               (try hd_is "<" (lhand (snd (strip_forall c)))
                with Failure _ -> false)) gl in
    let kk = rand (lhand (snd (strip_forall (concl ih)))) in
    SUBGOAL_THEN (mk_binop `(<):num->num->bool`
        (list_mk_icomb "LENGTH" [y]) kk)
      (fun lt -> MP_TAC (MP (SPEC (list_mk_icomb "LENGTH" [y]) ih)
                            lt))) THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN (fun th ->
    W(fun (asl,w as gl) ->
      let y = var_by_name "y" gl and y' = var_by_name "y'" gl in
      let lst c = rand (el 1 (snd (strip_comb
                    (lhand (rator c))))) in
      let w1 = the_asm (fun c ->
                 (try lst c = y with Failure _ -> false)) gl in
      let w2 = the_asm (fun c ->
                 (try lst c = y' with Failure _ -> false)) gl in
      let f1 = rand (rator (concl w1)) in
      let f2 = rand (rator (concl w2)) in
      let adr c = lhand (el 0 (snd (strip_comb
                    (lhand (rator c))))) in
      let a1 = adr (concl w1) in
      let a2 = adr (concl w2) in
      MP_TAC (SPECL [y; y'; f1; f2; a1; a2] th))) THEN
  (* its hypotheses are the branch's own *)
  ASM_REWRITE_TAC[LE_REFL] THEN
  DISCH_THEN (fun th -> REWRITE_TAC[th]) THEN
  (* and the two last elements decide the one step *)
  COND_CASES_TAC THEN
  ASM_REWRITE_TAC[] THEN
  TRY SAFE_MATCH_REDUCE_TAC THEN
  TRY (SOLVED (REWRITE_TAC[])) THEN
  COND_CASES_TAC THEN
  ASM_REWRITE_TAC[] THEN
  TRY SAFE_MATCH_REDUCE_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_cmp = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i1,v1) :: (Number
  i2,v2) :: vars) /\
     good_dimindex (:'a) ==>
     (?w1 w2.
       v1 = wordLang_Word w1 /\ v2 = wordLang_Word (w2:'a word) /\
       (if ~(word_bit 0 w1) /\ ~(word_bit 0 w2) then
         (i1 < i2 <=> w1 < w2) /\ (i1 = i2 <=> w1 = w2) else if
           ~(word_bit 0 w1) /\ word_bit 0 w2 then ~(i1 = i2) /\
         (?a x2. get_real_addr c st w2 = SOME a /\
                m a = wordLang_Word x2 /\ a IN dm /\
                word_cmp_res i1 i2 = (if (x2 && (n2w 16)) = (n2w 0)
                  then (n2w 0) else (n2w 2):'a word)) else if word_bit 0
                  w1 /\ word_bit 0 w2 then
         ?a1 x1 a2 x2.
           get_real_addr c st w1 = SOME a1 /\ m a1 = wordLang_Word
             x1 /\ a1 IN dm /\
           get_real_addr c st w2 = SOME a2 /\ m a2 = wordLang_Word
             x2 /\ a2 IN dm /\
           (if x1 = x2 then
             let (a1,a2) = (if (x1 && (n2w 16)) = (n2w 0) then
               (a1,a2) else (a2,a1)) in
               word_cmp_loop (decode_length c x1)
                 (a1 + bytes_in_word * (decode_length c x1))
                 (a2 + bytes_in_word * (decode_length c x2))
                   dm m = SOME (word_cmp_res i1 i2) else
             word_cmp_res i1 i2 =
             (if (x1 && (n2w 16)) = (n2w 0) then
                // 0 <= i1
                if (x2 && (n2w 16)) = (n2w 0) then
                  // 0 <= i2
                  if decode_length c x1 <+ decode_length c x2 then
                    (n2w 0) else (n2w 2):'a word else
                  (n2w 2) else
                if (x2 && (n2w 16)) = (n2w 0) then
                  // 0 <= i2
                  (n2w 0) else
                  if decode_length c x1 <+ decode_length c x2
                    then (n2w 2) else (n2w 0))) else T))`),
  (* the attempt: the proof of the source names
     memory_rel_Number_IMP_Word_2, small_int_def,
     memory_rel_any_Number_IMP, memory_rel_tail,
     memory_rel_Number_EQ, memory_rel_Number_LESS.  What is here
     rewrites with them and closes by arithmetic, and the cheat is
     behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_Number_IMP_Word_2; small_int_def;
       memory_rel_any_Number_IMP; memory_rel_tail;
       memory_rel_Number_EQ; memory_rel_Number_LESS] THEN
     TRY ASM_ARITH_TAC)));;

