let v_same_type_def = cake_define_try_tac (fun () ->
  `MEASURE (dataSem_v_size o FST)`)
  CHEAT_TAC
  `v_same_type x1 x2 =
        match (x1,x2) with
          ((Number _70:dataSem_v),(Number _71:dataSem_v)) -> T
        | ((Word64 _72),(Word64 _73)) -> T
        | ((Block _74 t1 l1),(Block _75 t2 l2)) -> (t1 = t2 /\ LENGTH
          l1 = LENGTH l2 ==> LIST_REL v_same_type l1 l2)
        | ((CodePtr _76),(CodePtr _77)) -> T
        | ((RefPtr _78 _79),(RefPtr _80 _81)) -> T
        | (_82,_83) -> F`;;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Block_MEM = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Block ts' n ls,(v:'a
  word_loc)) :: vars) /\
     i < LENGTH ls /\
     good_dimindex (:'a) ==>
     (?w a y.
     get_real_offset (Smallnum (&i)) = SOME y /\
     v = wordLang_Word w /\ get_real_addr c st w = SOME a /\ (a +
       y) IN dm /\
     memory_rel c be ts refs sp st m dm ((EL i ls,m (a + y)) ::
       (Block ts' n ls,v) :: vars))`),
  (* an element of a block at an index, with the root of the index
     put in and taken out again: the length of the block that
     memory_rel_Block_IMP gives is below two to the dimindex less
     four, so the index below it is a small integer, which
     IMP_memory_rel_Number puts in front of the roots and
     memory_rel_swap moves past the block; then memory_rel_El reads
     the element out and memory_rel_rearrange drops the root of the
     index again *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* an index below a length that a header encodes is small *)
    let smallidx = prove
     (`!(i:num) n.
         good_dimindex (:'a) /\ i < n /\
         n < 2 EXP (dimindex (:'a) - 4)
         ==> small_int (:'a) (&i)`,
      REPEAT GEN_TAC THEN
      REWRITE_TAC[small_int_def; dimword;
                  good_dimindex_def] THEN
      DISCH_THEN(CONJUNCTS_THEN2 MP_TAC STRIP_ASSUME_TAC) THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
      RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
      CONV_TAC NUM_REDUCE_CONV THEN
      CONJ_TAC THEN
      TRY(MATCH_MP_TAC INT_LE_TRANS THEN EXISTS_TAC `&0:int` THEN
          REWRITE_TAC[INT_POS; INT_NEG_LE0; INT_POS] THEN NO_TAC) THEN
      REWRITE_TAC[INT_OF_NUM_LT] THEN ASM_ARITH_TAC) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    SUBGOAL_THEN `~(ls:(dataSem_v)list = [])` ASSUME_TAC THENL
     [DISCH_TAC THEN VAR_EQ_TAC THEN
      FIRST_X_ASSUM(fun th ->
        if (try hd_is "<" (concl th) with Failure _ -> false)
        then MP_TAC(REWRITE_RULE[LENGTH; LT] th) else fail()) THEN
      REWRITE_TAC[];
      ALL_TAC] THEN
    W(fun (asl,w) ->
      let mr = grab asl (fun th -> hd_is "memory_rel" (concl th)) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      MP_TAC(MATCH_MP memory_rel_Block_IMP
               (CONJ mr gd))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    W(fun (asl,w) ->
      let bd = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th)) &&
        hd_is "EXP" (rand (concl th))) in
      let lt = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      ASSUME_TAC(MATCH_MP smallidx (CONJ gd (CONJ lt bd)))) THEN
    W(fun (asl,w) ->
      let mr = grab asl (fun th -> hd_is "memory_rel" (concl th)) in
      let si = grab asl (fun th -> hd_is "small_int" (concl th)) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      ASSUME_TAC(MATCH_MP IMP_memory_rel_Number
                   (CONJ gd (CONJ si mr)))) THEN
    W(fun (asl,w) ->
      let num = grab asl (fun th ->
        hd_is "memory_rel" (concl th) &&
        hd_is "dataSem_Number"
          (fst(dest_pair(lhand(last(snd(strip_comb (concl th)))))))) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let lt = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "LENGTH" (rand (concl th))) in
      MP_TAC(MATCH_MP memory_rel_El
               (CONJ (MATCH_MP memory_rel_swap num)
                     (CONJ gd lt)))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && hd_is "wordLang_Word" (lhs (concl e)) &&
         hd_is "wordLang_Word" (rhs (concl e))
      then SUBST_ALL_TAC(SYM(REWRITE_RULE[injectivity "word_loc"] e))
      else fail()) THEN
    W(fun (asl,w) ->
      let ind = grab asl (fun th ->
        hd_is "IN" (concl th) &&
        hd_is "word_add" (lhand (concl th))) in
      let x = lhand (lhand (concl ind)) in
      let y = rand (lhand (concl ind)) in
      let ga = grab asl (fun th ->
        hd_is "get_real_addr" (lhs (concl th)) &&
        rand (rhs (concl th)) = x) in
      EXISTS_TAC (rand (lhs (concl ga))) THEN
      EXISTS_TAC x THEN EXISTS_TAC y) THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [ASM_MESON_TAC[injectivity "word_loc"];
      ALL_TAC] THEN
    W(fun (asl,w) ->
      let mr = grab asl (fun th ->
        hd_is "memory_rel" (concl th) &&
        hd_is "EL"
          (fst(dest_pair(lhand(last(snd(strip_comb (concl th)))))))) in
      MATCH_MP_TAC(MATCH_MP
        (ONCE_REWRITE_RULE[TAUT `(p ==> q ==> r) <=> (q ==> p ==> r)`]
           memory_rel_rearrange) mr)) THEN
    ASM_REWRITE_TAC[MEM] THEN
    MESON_TAC[]));;

(* Smallnum_0 *)
let smallnum_0 = prove
 (`~(FAPPLY (Smallnum i:'a word) 0)`,
  (* Smallnum_bits says that the one of its two lowest bits is
     clear; a bit is clear exactly when the and with the word of
     that bit is zero *)
  (let bit0_and = prove
    (`!x:(N)word. bit 0 x <=> ~((n2w 1 && x) = n2w 0)`,
     GEN_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
                 BIT_WORD_1] THEN
     MESON_TAC[DIMINDEX_GE_1; ARITH_RULE `1 <= d ==> 0 < d:num`]) in
   REWRITE_TAC[word_index; bit0_and;
               CONJUNCT1 smallnum_bits]));;

(* Smallnum_1 *)
let smallnum_1 = prove
 (`good_dimindex (:'a) ==> ~(FAPPLY (Smallnum i:'a word) 1)`,
  (* and the other one, where the word of the bit is two and the
     dimindex has to be above one, which good_dimindex gives *)
  (let bw2 = prove
    (`!i. bit i (n2w 2:(N)word) <=> i = 1 /\ 1 < dimindex(:N)`,
     GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o RAND_CONV o RAND_CONV)
       [ARITH_RULE `2 = 2 EXP 1`] THEN
     REWRITE_TAC[BIT_WORD_POW2]) in
   let bit1_and = prove
    (`!x:(N)word. 1 < dimindex(:N)
                  ==> (bit 1 x <=> ~((n2w 2 && x) = n2w 0))`,
     GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
                 bw2] THEN
     ASM_MESON_TAC[]) in
   DISCH_TAC THEN REWRITE_TAC[word_index] THEN
   FIRST_ASSUM(fun gd ->
     MP_TAC(REWRITE_RULE[good_dimindex_def] gd)) THEN
   STRIP_TAC THEN
   ASM_SIMP_TAC[bit1_and; CONJUNCT2 smallnum_bits;
                ARITH_RULE `d = 32 ==> 1 < d:num`;
                ARITH_RULE `d = 64 ==> 1 < d:num`]));;

(* [local] *)
let do_eq_list_F_IMP_MEM = prove
 (`!l l'.
     do_eq_list refs l l' = Eq_val F /\ LENGTH l' = LENGTH l ==>
     (?i. i < LENGTH l /\ do_eq refs (EL i l) (EL i l') = Eq_val F)`,
  (* a do_eq_list that says F has an element that does: the clause
     of a cons compares the heads and goes on with the tails, so
     either the head is the element (and the index is zero) or the
     induction hypothesis names one of the tail (and the index is
     its successor).  Only the clause of do_eq_list is unfolded:
     the two are one definition, and the other clause would unfold
     the do_eq of the conclusion as well *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
   LIST_INDUCT_TAC THEN GEN_TAC THEN CASES_ON_NAME "l'" THEN
   ONCE_REWRITE_TAC[CONJUNCT2 dataSem_do_eq_def] THEN
   SAFE_MATCH_REDUCE_TAC THEN
   REWRITE_TAC[LENGTH; NOT_SUC; GSYM NOT_SUC; SUC_INJ;
               injectivity "eq_result"] THEN
   EVERY_CASE_TAC THEN
   STRIP_TAC THEN
   (* the head is the element that fails, or the tail has one *)
   TRY(EXISTS_TAC `0` THEN
       ASM_REWRITE_TAC[EL; HD; LT_0] THEN NO_TAC) THEN
   FIRST_X_ASSUM(fun ih ->
     if is_forall (concl ih) then
       FIRST_ASSUM(fun dl ->
         if (try hd_is "dataSem_do_eq_list" (lhs (concl dl))
             with Failure _ -> false)
         then MP_TAC(SPEC (rand (lhs (concl dl))) ih) else fail())
     else fail()) THEN
   ASM_REWRITE_TAC[] THEN
   DISCH_THEN(X_CHOOSE_THEN `i:num` STRIP_ASSUME_TAC) THEN
   EXISTS_TAC `SUC i` THEN
   ASM_REWRITE_TAC[LT_SUC; EL; TL]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_rotate3 = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm (x1 :: x2 :: x3 :: vars) ==>
     memory_rel c be ts refs sp st m dm (x3 :: x1 :: x2 :: vars)`),
  (MATCH_MP_TAC memory_rel_rearrange THEN
   GEN_TAC THEN REWRITE_TAC[MEM] THEN CONV_TAC TAUT));;

