let v_depth_def = cake_define_wf
  `MEASURE dataSem_v_size`
  `v_depth x1 =
        match x1 with
          (Block _86 _87 ls:dataSem_v) -> (if NULL ls then 0 else 1)
            + MAX_LIST (MAP v_depth ls)
        | _88 -> 0`;;

(* HOL4 data_to_word_memoryProofScript.sml:13427: ML code, not ported *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let v_inv_Block_tag_limit = prove
 (cake_as_vars (fun () ->
    `v_inv c (Block ts n l) refs (v,f,tf,(heap:(('a
  word_loc,data_to_word_memoryProof_tag#('a word_loc) list)heap_element)
  list)) /\
     heap_in_memory_store heap a sp sp1 gens c s m (dm:'a
       word->bool) limit ==> n < dimword (:'a) DIV 16`),
  (* the header of the BlockRep that the Block points at is an
     encode_header of four times the tag, and encode_header is only
     a SOME when that is below a sixteenth of the word size *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let rec facs t =
     if hd_is "STAR" t then
       let args = snd(strip_comb t) in
       facs (el 0 args) @ facs (el 1 args)
     else [t] in
   let sepfront names =
     W(fun (asl,w) ->
       let pred = rator (lhand w) in
       let fs = facs pred in
       let picked = map (fun n -> find (hd_is n) fs) names in
       let rest = filter (fun t -> not (mem t picked)) fs in
       let st = fst(strip_comb pred) in
       let mk a b = mk_comb(mk_comb(st,a),b) in
       let target = itlist mk picked (end_itlist mk rest) in
       SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
        [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
   DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
   REWRITE_TAC[v_inv_def] THEN
   COND_CASES_TAC THENL
    [STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun th ->
     if hd_is "heap_in_memory_store" (concl th)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
     else fail()) THEN
   STRIP_TAC THEN
   FIRST_ASSUM(fun th ->
     if hd_is "heap_lookup" (lhs (concl th))
     then MP_TAC(MATCH_MP heap_lookup_SPLIT th)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def;
               word_el_def; BlockRep_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   sepfront ["cond"] THEN
   REWRITE_TAC[cond_STAR] THEN
   DISCH_THEN(MP_TAC o CONJUNCT1) THEN
   REWRITE_TAC[encode_header_def] THEN
   COND_CASES_TAC THEN
   REWRITE_TAC[distinctness "option"] THEN
   POP_ASSUM MP_TAC THEN ARITH_TAC));;

let elements_list_def = cake_define_list
  [`elements_list [] = T`;
   `elements_list [v] = T`;
   `elements_list (v :: w :: vs) =
       (?ts t ls1 ls2.
         w = Block ts t (ls1 ++ [v] ++ ls2) /\
         // EVERY (λe. ∀p. e ≠ RefPtr F p) ls1 ∧
         elements_list (w :: vs))`];;

(* HOL4 data_to_word_memoryProofScript.sml:13453: ML code, not ported *)

let memory_rel_depth_limit = prove
 (`!v w vars'.
    memory_rel c b ts refs sp st m dm ((v,(w:'a word_loc)) :: vars')
      /\
    elements_list (v :: (MAP FST vars')) /\ good_dimindex (:'a) ==>
    (?ls.
       memory_rel c b ts refs sp st m dm (ls ++ ((v,w) :: vars')) /\
       v_depth v = LENGTH ls /\
       elements_list (MAP FST ls ++ (v :: (MAP FST vars'))))`,
(* the proof of the source is the induction of the values, with
   NULL_EQ, MAX_LIST, memory_rel_Block_MEM and LESS_LENGTH.  Here
   the induction is HOL Light's for the type, with the hypothesis
   of a Block over its list (the first lemma below), and a value
   that is not a Block has depth nought and wants no stack.  For a
   Block the deepest of its elements is one of them (the second
   lemma), and that element with its root is what the stack gains:
   memory_rel_Block_MEM puts the element in front of the Block, the
   element of the induction hypothesis gives the stack of it, and
   elements_list of the two says that the element is one of the
   Block's *)
  (let v_ind = prove
   (`!P. (!i. P (Number i)) /\ (!w. P (Word64 w)) /\
         (!ts t l. ALL P l ==> P (Block ts t l)) /\
         (!n. P (CodePtr n)) /\ (!b n. P (RefPtr b n)) ==>
         (!v. P (v:dataSem_v))`,
    GEN_TAC THEN DISCH_TAC THEN
    MP_TAC (ISPECL [`P:dataSem_v->bool`; `ALL (P:dataSem_v->bool)`]
              dataSem_v_INDUCT) THEN
    ASM_REWRITE_TAC[ALL] THEN
    DISCH_THEN (ACCEPT_TAC o CONJUNCT1)) in
  let MAX_LIST_MEM = prove
   (`!l. ~(l = []) ==> MEM (MAX_LIST l) l`,
    LIST_INDUCT_TAC THEN
    REWRITE_TAC[NOT_CONS_NIL; MEM; MAX_LIST] THEN
    ASM_CASES_TAC `t:num list = []` THENL
     [ASM_REWRITE_TAC[MAX_LIST; ARITH_RULE `MAX h 0 = h`];
      DISJ_CASES_TAC (ARITH_RULE
        `MAX h (MAX_LIST t) = h \/ MAX h (MAX_LIST t) = MAX_LIST t`)
      THEN ASM_REWRITE_TAC[] THEN ASM_SIMP_TAC[]]) in
  let depth_conv =
    GEN_REWRITE_TAC LAND_CONV [v_depth_def] THEN
    MATCH_REDUCE_TAC in
  let nb =
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    EXISTS_TAC `[]:(dataSem_v # ('a word_loc)) list` THEN
    REWRITE_TAC[APPEND; MAP; LENGTH] THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    depth_conv THEN REWRITE_TAC[] in
  W(fun (asl,gl) ->
    let v,bod = dest_forall gl in
    MATCH_MP_TAC (CONV_RULE (TOP_DEPTH_CONV BETA_CONV)
                    (ISPEC (mk_abs (v,bod)) v_ind))) THEN
  REPEAT CONJ_TAC THENL
   [nb; nb;
    REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
    STRIP_TAC THEN
    ASM_CASES_TAC `l:(dataSem_v) list = []` THENL
     [EXISTS_TAC `[]:(dataSem_v # ('a word_loc)) list` THEN
      REWRITE_TAC[APPEND; MAP; LENGTH] THEN
      REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
      depth_conv THEN
      ASM_REWRITE_TAC[NULL; MAP; MAX_LIST] THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `~(MAP v_depth (l:(dataSem_v)list) = [])`
      (fun th -> MP_TAC (MATCH_MP MAX_LIST_MEM th)) THENL
     [ASM_REWRITE_TAC[MAP_EQ_NIL]; ALL_TAC] THEN
    REWRITE_TAC[MEM_MAP] THEN
    DISCH_THEN (X_CHOOSE_THEN `e:dataSem_v`
                 STRIP_ASSUME_TAC) THEN
    FIRST_ASSUM (fun mm ->
      if hd_is "MEM" (concl mm)
      then STRIP_ASSUME_TAC
             (REWRITE_RULE[MEM_APPEND_DECOMPOSE] mm)
      else fail()) THEN
    SUBGOAL_THEN
      `LENGTH (l1:(dataSem_v)list) < LENGTH (l:(dataSem_v)list)`
      ASSUME_TAC THENL
     [ASM_REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
      `EL (LENGTH (l1:(dataSem_v)list)) l = (e:dataSem_v)`
      ASSUME_TAC THENL
     [ASM_REWRITE_TAC[EL_APPEND; LT_REFL; SUB_REFL; EL; HD];
      ALL_TAC] THEN
    FIRST_ASSUM (fun mr ->
      if hd_is "memory_rel" (concl mr)
      then FIRST_ASSUM (fun lt ->
             if (try hd_is "<" (concl lt) with Failure _ -> false)
             then FIRST_ASSUM (fun gd ->
                    if hd_is "good_dimindex" (concl gd)
                    then STRIP_ASSUME_TAC
                           (MATCH_MP (GEN_ALL memory_rel_Block_MEM)
                             (CONJ mr (CONJ lt gd)))
                    else fail())
             else fail())
      else fail()) THEN
    FIRST_ASSUM (fun elq ->
      if (try is_eq (concl elq) && hd_is "EL" (lhs (concl elq))
          with Failure _ -> false)
      then RULE_ASSUM_TRY (REWRITE_RULE[elq]) else fail()) THEN
    SUBGOAL_THEN `elements_list ((e:dataSem_v) ::
                    MAP FST ((Block ts' t l,(w:'a word_loc)) ::
                      (vars':(dataSem_v # ('a word_loc))list)))`
      ASSUME_TAC THENL
     [REWRITE_TAC[MAP; FST; elements_list_def] THEN
      MAP_EVERY EXISTS_TAC
        [`ts':num`; `t:num`; `l1:(dataSem_v)list`;
         `l2:(dataSem_v)list`] THEN
      ASM_REWRITE_TAC[APPEND];
      ALL_TAC] THEN
    FIRST_ASSUM (fun ih ->
      if not (hd_is "ALL" (concl ih)) then fail() else
      FIRST_ASSUM (fun mm ->
        if not (try hd_is "MEM" (concl mm)
                with Failure _ -> false) then fail() else
        let ihe = MATCH_MP (REWRITE_RULE[GSYM ALL_MEM] ih) mm in
        FIRST_ASSUM (fun mr ->
          if not (hd_is "memory_rel" (concl mr)) then fail() else
          FIRST_ASSUM (fun elm ->
            if not (hd_is "elements_list" (concl elm)) then fail()
            else FIRST_ASSUM (fun gd ->
              if not (hd_is "good_dimindex" (concl gd)) then fail()
              else STRIP_ASSUME_TAC (MATCH_MP ihe
                     (CONJ mr (CONJ elm gd)))))))) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[MAP; FST]) THEN
    FIRST_ASSUM (fun mr ->
      if not (hd_is "memory_rel" (concl mr)) then fail() else
      let stack = last (snd (strip_comb (concl mr))) in
      if not (hd_is "APPEND" stack) then fail() else
      let args = snd (strip_comb stack) in
      let pair = hd (snd (strip_comb (el 1 args))) in
      EXISTS_TAC (list_mk_icomb "APPEND"
        [el 0 args; mk_list ([pair], type_of pair)])) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[GSYM APPEND_ASSOC; APPEND] THEN
      FIRST_ASSUM ACCEPT_TAC;
      depth_conv THEN
      ASM_REWRITE_TAC[NULL_EQ; LENGTH_APPEND; LENGTH] THEN
      ARITH_TAC;
      REWRITE_TAC[MAP_APPEND; MAP; FST; GSYM APPEND_ASSOC;
                  APPEND] THEN
      FIRST_ASSUM ACCEPT_TAC];
    nb; nb]));;

(* [local] *)
let not_all_distinct_map_snd = prove
 (`~(ALL_DISTINCT (MAP SND xs)) ==>
   (?xs1 xs2 xs3 x y1 y2. xs = xs1 ++ [(y1,x)] ++ xs2 ++ [(y2,x)]
     ++ xs3)`,
  (* a list whose seconds repeat: the induction finds the first
     repetition, either the head's second in the tail -- and then
     the head is the first of the two -- or inside the tail, which
     the hypothesis splits.  The lemma states the split with the
     types of the pairs named, so the two pairs can be taken apart
     and the witnesses written down *)
  (let lem = prove
    (`!l:(A#B)list. ~(ALL_DISTINCT (MAP SND l))
        ==> ?l1 l2 l3 x y1 y2.
              l = l1 ++ [(y1,x)] ++ l2 ++ [(y2,x)] ++ l3`,
     LIST_INDUCT_TAC THEN
     REWRITE_TAC[MAP; ALL_DISTINCT_CLAUSES; DE_MORGAN_THM] THEN
     MP_TAC(ISPEC `h:A#B` PAIR_SURJECTIVE) THEN
     DISCH_THEN(X_CHOOSE_THEN `a:A`
       (X_CHOOSE_THEN `b:B` SUBST_ALL_TAC)) THEN
     REWRITE_TAC[SND; MEM_MAP; MEM_APPEND_DECOMPOSE] THEN
     DISCH_THEN(DISJ_CASES_THEN2
       (X_CHOOSE_THEN `p:A#B` (CONJUNCTS_THEN2
          (X_CHOOSE_THEN `m1:(A#B)list`
            (X_CHOOSE_THEN `m2:(A#B)list` SUBST_ALL_TAC))
          ASSUME_TAC))
       ASSUME_TAC) THENL
      [MP_TAC(ISPEC `p:A#B` PAIR_SURJECTIVE) THEN
       DISCH_THEN(X_CHOOSE_THEN `c:A`
         (X_CHOOSE_THEN `d:B` SUBST_ALL_TAC)) THEN
       RULE_ASSUM_TAC(REWRITE_RULE[SND]) THEN
       FIRST_X_ASSUM SUBST_ALL_TAC THEN
       MAP_EVERY EXISTS_TAC
         [`[]:(A#B)list`; `m1:(A#B)list`; `m2:(A#B)list`;
          `d:B`; `a:A`; `c:A`] THEN
       REWRITE_TAC[APPEND];
       FIRST_X_ASSUM(fun ih -> FIRST_X_ASSUM(fun nd ->
         MP_TAC(MATCH_MP ih nd))) THEN
       DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST_ALL_TAC) THEN
       MAP_EVERY EXISTS_TAC
         [`CONS (a:A,b:B) (l1:(A#B)list)`; `l2:(A#B)list`;
          `l3:(A#B)list`; `x:B`; `y1:A`; `y2:A`] THEN
       REWRITE_TAC[APPEND]]) in
   MATCH_ACCEPT_TAC lem));;

let IN_all_vs_HD = prove
 (`x IN all_vs refs (x :: xs)`,
  (REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   REPEAT DISJ2_TAC THEN MATCH_MP_TAC MEM_v_all_vs THEN
   REWRITE_TAC[MEM]));;

let IN_all_vs_TL = prove
 (`x IN all_vs refs xs ==>
   x IN all_vs refs (y :: xs)`,
  (* the three parts of all_vs that read the refs are the same, and
     what the stack reaches is still reached when a value is put in
     front of it: the values of that one come first, whatever it is *)
  (let tl_mem = prove
    (`!y xs x. MEM x (v_all_vs xs) ==> MEM x (v_all_vs (CONS y xs))`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     STRUCT_CASES_TAC(ISPEC `y:dataSem_v` (cases_of `:dataSem_v`)) THEN
     GEN_REWRITE_TAC ONCE_DEPTH_CONV [v_all_vs_def] THEN
     MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[MEM; MEM_APPEND]) in
   REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
   STRIP_TAC THEN ASM_MESON_TAC[tl_mem]));;

(* [local] *)
let get_lowerbits_shift_length = prove
 (`(w2 >>> n) = (n2w 0) ==>
     ((w1 || w2) >>> n) = (w1 >>> n)`,
  (* the bits of the shifted or are the shifted bits of each, and
     the second word has none left; BIT_GUARD is what says that a
     bit that is set is one of the word's own *)
  (DISCH_TAC THEN
   FIRST_X_ASSUM(MP_TAC o
     REWRITE_RULE[WORD_EQ_BITS_ALT; BIT_WORD_0;
                  BIT_WORD_USHR]) THEN
   DISCH_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_OR; BIT_WORD_USHR] THEN
   REPEAT STRIP_TAC THEN ASM_SIMP_TAC[] THEN
   GEN_REWRITE_TAC RAND_CONV [BIT_GUARD] THEN REWRITE_TAC[]));;

(* [local] *)
let shift_shift = prove
 (`n1 * (2 EXP l) < dimword (:'a) ==>
     n2w n1 << l >>> l = (n2w n1:'a word)`,
  (* the shift up multiplies by two to the shift, which stays below
     the dimword, so the shift down divides it out again *)
  (let e2 = prove
    (`!l. 1 <= 2 EXP l`,
     REWRITE_TAC[ARITH_RULE `1 <= n <=> ~(n = 0)`; EXP_EQ_0;
                 ARITH_EQ]) in
   DISCH_TAC THEN
   SUBGOAL_THEN `n1 < dimword (:'a) /\ 2 EXP l * n1 < dimword (:'a)`
     STRIP_ASSUME_TAC THENL
    [CONJ_TAC THENL
      [TRANS_TAC LET_TRANS `n1 * 2 EXP l` THEN ASM_REWRITE_TAC[] THEN
       SUBGOAL_THEN `n1 * 1 <= n1 * 2 EXP l` MP_TAC THENL
        [REWRITE_TAC[LE_MULT_LCANCEL] THEN
         DISJ2_TAC THEN MATCH_ACCEPT_TAC e2;
         ARITH_TAC];
       ONCE_REWRITE_TAC[MULT_SYM] THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
   REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_USHR; VAL_WORD_SHL; VAL_WORD;
               GSYM dimword] THEN
   CONV_TAC MOD_DOWN_CONV THEN
   ASM_SIMP_TAC[MOD_LT; DIV_MULT; EXP_EQ_0; ARITH_EQ]));;

(* [local] *)
let word_addr_Data_NE_get_addr = prove
 (`good_dimindex (:'a) ==> ~(word_addr c (gc_shared_Data a1) =
  wordLang_Word (get_addr c n a2:'a word))`,
  (* the address of a Data of a Loc is a Loc, and the one of a Data
     of a word has its lowest bit taken off, where get_addr_0 says
     that the lowest bit of an address is set *)
  (DISCH_TAC THEN CASES_ON_NAME "a1" THEN
   REWRITE_TAC(word_addr_clauses () @
               [distinctness "word_loc"; injectivity "word_loc"]) THEN
   DISCH_TAC THEN
   FIRST_ASSUM(fun eq ->
     let ga = PART_MATCH (rand o rator)
                (GEN_ALL get_addr_0) (rand (concl eq)) in
     CONTR_TAC(REWRITE_RULE[GSYM eq; word_index; BIT_WORD_AND;
                            BIT_WORD_NOT; BIT_WORD_1] ga))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Block_ptr_eq = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m (dm:'a word->bool)
       ((Block t1 a1 b1,x) :: (Block t2 a2 b2,x) :: rest) /\
     good_dimindex (:'a) ==>
     Block t1 a1 b1 = Block t2 a2 b2`),
(* the proof of the source takes the roots of the two Blocks apart.
   An empty Block has the Data of the BlockNil of its tag for a
   root, and the and with the complement of one leaves that alone
   (the lemmas below are the ones of memory_rel_Block_IMP), so the
   tags are equal -- sixteen times a tag and two is below the word
   size, which is what makes the BlockNil of a tag tell the tag.  A
   non-empty one has a pointer, whose word is odd, so the two cases
   do not meet (word_addr_Data_NE_get_addr).  Two pointers that
   make the same word have the same address: the lower bits go in
   the shift (get_lowerbits_shift_length) and what is left is the
   address shifted up and down again (shift_shift), which is itself
   because an address of the heap is below the word size divided by
   the shift.  Then the timestamps are equal, because tf takes them
   to the one address and is injective, and blocks_unique says that
   two Blocks of one timestamp among the values are equal *)
  (let shl16 = prove
   (`!(v:(N)word). word 16 * v = word_shl v 4`,
    REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
    CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[MULT_AC]) in
  let shl1 = prove
   (`!(v:(N)word). word_shl v 1 = word 2 * v`,
    REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
    CONV_TAC MOD_DOWN_CONV THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[MULT_AC]) in
  let andid = prove
   (`!(x:(N)word).
       word_and (word_shl x 4 + word 2) (word_not (word 1)) =
       x * word 16 + word 2`,
    GEN_TAC THEN
    SUBGOAL_THEN
      `word_shl (x:(N)word) 4 + word 2 = x * word 16 + word 2`
      SUBST1_TAC THENL
     [REWRITE_TAC[shl16] THEN CONV_TAC WORD_RULE; ALL_TAC] THEN
    SUBGOAL_THEN `~(bit 0 ((x:(N)word) * word 16 + word 2))`
      MP_TAC THENL
     [SUBGOAL_THEN `(x:(N)word) * word 16 + word 2 =
                    word_shl (word 8 * x + word 1) 1` SUBST1_TAC THENL
       [REWRITE_TAC[shl1] THEN CONV_TAC WORD_RULE; ALL_TAC] THEN
      REWRITE_TAC[BIT_WORD_SHL] THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    DISCH_TAC THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_NOT;
                BIT_WORD_1] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC TAUT) in
  (* the tag of an empty Block is what its root says *)
  let bnil_inj = prove
   (`!a1 a2. (n2w a1 * word 16 + word 2:'a word) =
             n2w a2 * word 16 + word 2 /\
             a1 < dimword (:'a) DIV 16 /\
             a2 < dimword (:'a) DIV 16 ==> a1 = a2`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `a1 * 16 + 2 < dimword (:'a) /\ a2 * 16 + 2 < dimword (:'a)`
      STRIP_ASSUME_TAC THENL
     [MP_TAC (SPECL [`dimword (:'a)`; `16`] DIVISION) THEN
      CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM (fun eq ->
      if not (try hd_is "word_add" (lhs (concl eq))
              with Failure _ -> false) then fail() else
      MP_TAC (REWRITE_RULE[GSYM VAL_EQ; VAL_WORD_ADD; VAL_WORD_MUL;
                           VAL_WORD; GSYM dimword] eq)) THEN
    CONV_TAC MOD_DOWN_CONV THEN
    ASM_SIMP_TAC[MOD_LT] THEN ARITH_TAC) in
  (* a pointer below the heap is below the words *)
  let mul_lt = prove
   (`!p h d k. p < h /\ h <= d DIV k /\ ~(k = 0) ==> p * k < d`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC LTE_TRANS THEN
    EXISTS_TAC `(d DIV k) * k` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[LT_MULT_RCANCEL] THEN ASM_ARITH_TAC;
      MP_TAC (SPECL [`d:num`; `k:num`] DIVISION) THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC]) in
  let n2w_inj = prove
   (`!a b. (n2w a:'a word) = n2w b /\ a < dimword (:'a) /\
           b < dimword (:'a) ==> a = b`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_X_ASSUM (fun eq ->
      if not (try is_eq (concl eq) && hd_is "word" (lhs (concl eq))
              with Failure _ -> false) then fail() else
      MP_TAC (REWRITE_RULE[GSYM VAL_EQ; VAL_WORD; GSYM dimword]
                eq)) THEN
    ASM_SIMP_TAC[MOD_LT]) in
  let exp2_nz = prove
   (`!n. ~(2 EXP n = 0)`,
    REWRITE_TAC[EXP_EQ_0; ARITH_EQ]) in
  let lt_mul = prove
   (`!p k d. p * k < d /\ ~(k = 0) ==> p < d`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC LET_TRANS THEN EXISTS_TAC `(p:num) * k` THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(p:num) * 1 <= p * k` MP_TAC THENL
     [REWRITE_TAC[LE_MULT_LCANCEL] THEN ASM_ARITH_TAC;
      ARITH_TAC]) in
  (* two timestamps that the map takes to one address are one *)
  let flookup_inj = prove
   (`!(f:(num,num)fmap) s x y p.
       INJ (FAPPLY f) (FDOM f) s /\ FLOOKUP f x = SOME p /\
       FLOOKUP f y = SOME p ==> x = y`,
    REWRITE_TAC[INJ; FLOOKUP_DEF] THEN REPEAT GEN_TAC THEN
    REPEAT COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
    ASM_MESON_TAC[]) in
  let tl_hd = MATCH_MP (GEN_ALL IN_all_vs_TL) IN_all_vs_HD in
  MEMORY_REL_TAC THEN SPLIT_ROOTS_TAC THEN
  RULE_ASSUM_TRY (REWRITE_RULE[v_inv_def]) THEN
  ASM_CASES_TAC `b1:(dataSem_v)list = []` THEN
  FIRST_ASSUM (fun e ->
    RULE_ASSUM_TRY (REWRITE_RULE[e]) THEN ASSUME_TAC e) THEN
  ASM_CASES_TAC `b2:(dataSem_v)list = []` THEN
  FIRST_ASSUM (fun e ->
    RULE_ASSUM_TRY (REWRITE_RULE[e]) THEN ASSUME_TAC e) THEN
  REPEAT (FIRST_X_ASSUM (CONJUNCTS_THEN ASSUME_TAC)) THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_exists (concl th) then CHOOSE_TAC th else fail())) THEN
  REPEAT (FIRST_X_ASSUM (CONJUNCTS_THEN ASSUME_TAC)) THEN
  REPEAT SUBST_LHS_TAC THEN
  RULE_ASSUM_TRY (REWRITE_RULE (word_addr_clauses () @
    [distinctness "word_loc"; injectivity "word_loc"])) THEN
  TRY (FIRST_ASSUM (fun eq ->
    if (try is_eq (concl eq) && is_var (rand (concl eq)) &&
            not (is_var (lhs (concl eq)))
        with Failure _ -> false)
    then SUBST_ALL_TAC (SYM eq) else fail())) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[injectivity "word_loc";
                               distinctness "word_loc"]) THENL
   [(* both Blocks are empty: their roots are the BlockNils of the
       tags, whose and with the complement of one is themselves *)
    FIRST_ASSUM (fun eq ->
      if not (try hd_is "word_and" (lhs (concl eq))
              with Failure _ -> false) then fail() else
      let eq' = REWRITE_RULE[BlockNil_def; andid] eq in
      FIRST_ASSUM (fun lt1 ->
        FIRST_ASSUM (fun lt2 ->
          if concl lt1 = concl lt2 then fail() else
          STRIP_ASSUME_TAC (MATCH_MP bnil_inj
            (CONJ eq' (CONJ lt1 lt2)))))) THEN
    ASM_REWRITE_TAC[];
    (* one is empty and the other is not: a Data is not the word
       of an address, whose lowest bit is set *)
    FIRST_ASSUM (fun eq ->
      let mk side rl =
        let ga = PART_MATCH (rand o rator) (GEN_ALL get_addr_0)
                   (side (concl eq)) in
        REWRITE_RULE[rl eq; word_index; BIT_WORD_AND; BIT_WORD_NOT;
                     BIT_WORD_1] ga in
      let th = (try mk rand GSYM
                with Failure _ -> mk lhs (fun t -> t)) in
      if concl th = `F` then CONTR_TAC th else fail());
    FIRST_ASSUM (fun eq ->
      let mk side rl =
        let ga = PART_MATCH (rand o rator) (GEN_ALL get_addr_0)
                   (side (concl eq)) in
        REWRITE_RULE[rl eq; word_index; BIT_WORD_AND; BIT_WORD_NOT;
                     BIT_WORD_1] ga in
      let th = (try mk rand GSYM
                with Failure _ -> mk lhs (fun t -> t)) in
      if concl th = `F` then CONTR_TAC th else fail());
    (* both are pointers, and the addresses they shift up are the
       same, so the timestamps that the map takes to them are the
       same, and then blocks_unique says the Blocks are *)
    FIRST_ASSUM (fun h ->
      if hd_is "heap_in_memory_store" (concl h)
      then STRIP_ASSUME_TAC
             (REWRITE_RULE[heap_in_memory_store_def] h)
      else fail()) THEN
    ASSUM_LIST (fun asl ->
      let mkbound hl =
        FIRST_ASSUM (fun hb ->
          if not (try hd_is "heap_length" (lhand (concl hb)) &&
                      hd_is "DIV" (rand (concl hb))
                  with Failure _ -> false) then fail() else
          let k = rand (rand (concl hb)) in
          let th = MATCH_MP mul_lt
            (CONJ (MATCH_MP (GEN_ALL heap_lookup_LESS) hl)
                  (CONJ hb (SPEC (rand k) exp2_nz))) in
          STRIP_ASSUME_TAC th THEN
          STRIP_ASSUME_TAC (MATCH_MP lt_mul
            (CONJ th (SPEC (rand k) exp2_nz)))) in
      MAP_EVERY mkbound (filter (fun th ->
        try hd_is "heap_lookup" (lhs (concl th))
        with Failure _ -> false) asl)) THEN
    FIRST_ASSUM (fun eq ->
      if not (try hd_is "get_addr" (lhs (concl eq)) &&
                  hd_is "get_addr" (rand (concl eq))
              with Failure _ -> false) then fail() else
      let slt = cake_as_vars (fun () -> `shift_length c`) in
      let v = mk_var ("w", type_of (lhs (concl eq))) in
      let f = mk_abs (v, list_mk_icomb "word_ushr" [v; slt]) in
      MP_TAC (CONV_RULE (TOP_DEPTH_CONV BETA_CONV)
                (AP_TERM f (REWRITE_RULE[get_addr_def] eq)))) THEN
    REWRITE_TAC[MATCH_MP (GEN_ALL get_lowerbits_shift_length)
                  get_lowerbits_LSL_shift_length] THEN
    ASM_SIMP_TAC[shift_shift] THEN
    DISCH_THEN (fun eq ->
      FIRST_ASSUM (fun lt1 ->
        FIRST_ASSUM (fun lt2 ->
          if concl lt1 = concl lt2 then fail() else
          SUBST_ALL_TAC (MATCH_MP n2w_inj
            (CONJ eq (CONJ lt1 lt2)))))) THEN
    FIRST_ASSUM (fun inj ->
      if not (try hd_is "INJ" (concl inj) with Failure _ -> false)
      then fail() else
      FIRST_ASSUM (fun f1 ->
        if not (try hd_is "FLOOKUP" (lhs (concl f1))
                with Failure _ -> false) then fail() else
        FIRST_ASSUM (fun f2 ->
          if concl f1 = concl f2 then fail() else
          SUBST_ALL_TAC (MATCH_MP flookup_inj
            (CONJ inj (CONJ f1 f2)))))) THEN
    W(fun (asl,gl) ->
      let bl1 = lhs gl and bl2 = rand gl in
      let a1 = snd (strip_comb bl1) and a2 = snd (strip_comb bl2) in
      FIRST_ASSUM (fun bu ->
        if not (hd_is "blocks_unique" (concl bu)) then fail() else
        MP_TAC (SPECL [el 0 a1; el 1 a1; el 2 a1; el 1 a2; el 2 a2]
                  (REWRITE_RULE[blocks_unique_def] bu)))) THEN
    ASM_REWRITE_TAC[IN_all_vs_HD; tl_hd] THEN
    DISCH_THEN (fun th -> ASM_REWRITE_TAC[th])]));;

let elements_list_all_blocks = prove
 (`elements_list xs /\ ~(xs = []) /\ (?t a b. HD xs = Block t a b) ==>
   EVERY (\x. ?t a b. x = Block t a b) xs /\
   SORTED (\x y. vb_size x < vb_size y) xs`,
  (* the elements of an elements_list are the payload of the next
     one, so each of them is a Block when the first is, and each is
     smaller than the next: the size of a Block counts the sizes of
     its payload, and the element is one of that payload *)
  (let sumc = prove
    (`SUM [] = 0 /\ (!h t. SUM (CONS h t) = h + SUM t)`,
     REWRITE_TAC[SUM_DEF; ITLIST]) in
   let sum_append = prove
    (`!l1 l2. SUM (l1 ++ l2) = SUM l1 + SUM l2`,
     LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[APPEND; sumc; ADD_CLAUSES; ADD_ASSOC]) in
   let vbs = prove
    (`!ts t ls. vb_size (Block ts t ls) =
                1 + t + SUM (MAP vb_size ls) + LENGTH ls`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [vb_size_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   SUBGOAL_THEN
     `!xs. elements_list xs /\ ~(xs = []) /\
           (?t a b. HD xs = Block t a b)
           ==> EVERY (\x. ?t a b. x = Block t a b) xs /\
               SORTED (\x y. vb_size x < vb_size y) xs`
     (fun th -> MATCH_ACCEPT_TAC th) THEN
   LIST_INDUCT_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
   POP_ASSUM MP_TAC THEN
   STRUCT_CASES_TAC(ISPEC `t:(dataSem_v)list` list_CASES_v) THEN
   DISCH_TAC THENL
    [REWRITE_TAC[ALL; SORTED_DEF; HD] THEN MESON_TAC[];
     REWRITE_TAC[elements_list_def; HD; ALL; SORTED_DEF] THEN
     STRIP_TAC THEN
     SUBGOAL_THEN
       `EVERY (\x. ?t a b. x = Block t a b) (CONS v vs) /\
        SORTED (\x y. vb_size x < vb_size y) (CONS v vs)`
       (fun th -> STRIP_ASSUME_TAC(REWRITE_RULE[ALL] th)) THENL
      [FIRST_X_ASSUM MATCH_MP_TAC THEN
       ASM_REWRITE_TAC[NOT_CONS_NIL; HD] THEN ASM_MESON_TAC[];
       ALL_TAC] THEN
     ASM_REWRITE_TAC[] THEN
     ASM_REWRITE_TAC[vbs; MAP_APPEND; sum_append; LENGTH_APPEND;
                     MAP; LENGTH; sumc] THEN
     REPEAT CONJ_TAC THEN TRY ARITH_TAC THEN MESON_TAC[]]));;

(* the port's own: the four things HOL4 gets from SORTED_APPEND.
   sorted_tl and sorted_drop say that what follows a sorted list is
   sorted, sorted_head that the head of a sorted list relates to
   every member of the tail, and sorted_pair puts the two together:
   of two elements of a sorted list the earlier one relates to the
   later *)

let sorted_tl = prove
 (`!R x l. SORTED R (CONS x l) ==> SORTED R l`,
  GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
  REWRITE_TAC[SORTED_DEF] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]);;

let sorted_drop = prove
 (`!R l1 l2. SORTED R (l1 ++ l2) ==> SORTED R l2`,
  GEN_TAC THEN LIST_INDUCT_TAC THEN GEN_TAC THEN
  REWRITE_TAC[APPEND] THEN
  TRY (DISCH_THEN ACCEPT_TAC) THEN
  DISCH_THEN (fun th ->
    FIRST_ASSUM (fun ih ->
       ACCEPT_TAC (MATCH_MP ih (MATCH_MP sorted_tl th)))));;

let sorted_head = prove
 (`!R l x y. (!a b c. R a b /\ R b c ==> R a c) /\
            SORTED R (CONS x l) /\ MEM y l ==> R x y`,
  GEN_TAC THEN LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[MEM; SORTED_DEF] THEN REPEAT STRIP_TAC THENL
    [ASM_REWRITE_TAC[];
    FIRST_ASSUM (fun tr ->
       if length (fst (strip_forall (concl tr))) = 3
       then MATCH_MP_TAC tr else fail()) THEN
    W(fun gl -> EXISTS_TAC (var_by_name "h" gl)) THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM (fun ih ->
       if length (fst (strip_forall (concl ih))) = 2
       then MATCH_MP_TAC ih else fail()) THEN
    ASM_REWRITE_TAC[]]);;

let sorted_pair = prove
 (`!R l1 l2 l3 u v.
    (!a b c. R a b /\ R b c ==> R a c) /\
    SORTED R (l1 ++ [u] ++ l2 ++ [v] ++ l3) ==> R u v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC sorted_head THEN
  FIRST_ASSUM (fun s ->
    if (try fst (dest_const (fst (strip_comb (concl s)))) =
             "SORTED"
         with Failure _ -> false)
    then EXISTS_TAC (rand (rand (rand (concl s)))) else fail()) THEN
  REPEAT CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM (fun s -> MP_TAC (MATCH_MP sorted_drop s)) THEN
    REWRITE_TAC[APPEND] THEN DISCH_THEN ACCEPT_TAC;
    REWRITE_TAC[MEM_APPEND; MEM]]);;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_elements_list_distinct_lemma = prove
 (cake_as_vars (fun () ->
    `!vs vars' tag a b.
       memory_rel c be ts refs sp st m (dm:'a word->bool) vars' /\
       elements_list vs /\ vs = MAP FST vars' /\
       good_dimindex (:'a) /\ ~(vs = []) /\
       HD vs = Block tag a b ==>
       ALL_DISTINCT (MAP SND vars')`),
(* the proof of the source is by contradiction:
   not_all_distinct_map_snd gives two pairs of the stack with the
   same word, elements_list_all_blocks says the values are blocks
   and sorted by their size, so the earlier of the two is the
   smaller (sorted_pair above), and memory_rel_Block_ptr_eq says
   that two blocks the memory holds the same word for are the same
   block -- which the two sizes say they are not *)
  (let hd_of n t =
    (try fst (dest_const (fst (strip_comb t))) = n
     with Failure _ -> false) in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* by contradiction: two pairs of the stack with the same word *)
  MATCH_MP_TAC (TAUT `(~p ==> F) ==> p`) THEN DISCH_TAC THEN
  FIRST_ASSUM (fun nd ->
    STRIP_ASSUME_TAC (MATCH_MP not_all_distinct_map_snd nd)) THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if (try is_eq (concl th) && is_var (lhs (concl th)) &&
            not (is_var (rand (concl th)))
        with Failure _ -> false)
    then SUBST_ALL_TAC th else fail())) THEN
  (* the values of the stack are blocks, and sorted by their
     size *)
  W(fun gl ->
    let e1 = the_asm (hd_of "elements_list") gl in
    let e2 = the_asm (fun c ->
               try is_neg c && is_eq (rand c) &&
                   hd_of "MAP" (lhand (rand c))
               with Failure _ -> false) gl in
    let hh = the_asm (fun c ->
               try is_eq c && hd_of "HD" (lhs c)
               with Failure _ -> false) gl in
    let ps = snd (strip_comb (rand (concl hh))) in
    let vs = map (fun t -> genvar (type_of t)) ps in
    let ex = list_mk_exists (vs,
               mk_eq (lhs (concl hh),
                 list_mk_comb (fst (strip_comb (rand (concl hh))),
                   vs))) in
    SUBGOAL_THEN ex (fun e ->
      STRIP_ASSUME_TAC (MATCH_MP elements_list_all_blocks
        (CONJ e1 (CONJ e2 e)))) THENL
     [MAP_EVERY EXISTS_TAC ps THEN ACCEPT_TAC hh; ALL_TAC]) THEN
  (* the two words of the two pairs, and the size of the first is
     below the size of the second *)
  RULE_ASSUM_TRY (REWRITE_RULE[MAP_APPEND; MAP; FST;
                               ALL_APPEND; ALL]) THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    if is_conj (concl th) || is_exists (concl th)
    then STRIP_ASSUME_TAC th else fail())) THEN
  W(fun gl ->
    let so = the_asm (hd_of "SORTED") gl in
    let r = el 0 (snd (strip_comb (concl so))) in
    let ty = hd (snd (dest_type (type_of r))) in
    let a = mk_var ("a",ty) and b = mk_var ("b",ty)
    and c = mk_var ("c",ty) in
    let ap x y = mk_comb (mk_comb (r,x), y) in
    let tr = prove (list_mk_forall ([a;b;c],
               mk_imp (mk_conj (ap a b, ap b c), ap a c)),
               REWRITE_TAC[] THEN ARITH_TAC) in
    ASSUME_TAC (REWRITE_RULE[]
      (MATCH_MP sorted_pair (CONJ tr so)))) THEN
  (* both of them are blocks *)
  REPEAT (FIRST_X_ASSUM (fun th ->
    if (try is_eq (concl th) && is_var (lhs (concl th)) &&
            hd_of "dataSem_Block" (rand (concl th))
        with Failure _ -> false)
    then SUBST_ALL_TAC th else fail())) THEN
  (* so the memory holds the same word for two blocks, and
     memory_rel_Block_ptr_eq says they are the same block *)
  W(fun gl ->
    let mr = the_asm (fun c ->
               try length (snd (strip_comb c)) = 9 && not (is_eq c)
               with Failure _ -> false) gl in
    let lst = last (snd (strip_comb (concl mr))) in
    let p1 = hd (dest_list (lhand (rand lst))) in
    let p2 = hd (dest_list (lhand (rand (rand (rand lst))))) in
    SUBGOAL_THEN (mk_comb (rator (concl mr),
                    mk_list ([p1; p2], type_of p1))) ASSUME_TAC THENL
     [MP_TAC mr THEN MATCH_MP_TAC memory_rel_rearrange THEN
      REWRITE_TAC[MEM; MEM_APPEND] THEN MESON_TAC[];
      ALL_TAC]) THEN
  W(fun gl ->
    let mr2 = the_asm (fun c ->
                try length (dest_list (last (snd (strip_comb c))))
                    = 2
                with Failure _ -> false) gl in
    let gd = the_asm (fun c -> c = `good_dimindex (:'a)`) gl in
    MP_TAC (MATCH_MP memory_rel_Block_ptr_eq (CONJ mr2 gd))) THEN
  DISCH_THEN (fun e -> RULE_ASSUM_TRY (REWRITE_RULE[e])) THEN
  W(fun gl ->
    MP_TAC (the_asm (fun c ->
      try is_binop `(<):num->num->bool` c with Failure _ -> false)
      gl)) THEN
  ARITH_TAC));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_elements_list_distinct = prove
 (cake_as_vars (fun () ->
    `!vs vars'.
       memory_rel c be ts refs sp st m (dm:'a word->bool) vars' /\
       elements_list vs /\ vs = MAP FST vars' /\
       good_dimindex (:'a) ==>
       ALL_DISTINCT (MAP SND (TL vars'))`),
  (* the roots of the tail of an elements_list are distinct: the
     tail is what the lemma says it of, whose Block the second
     clause of elements_list names (the head of the list is an
     element of it).  The tail of the empty list is empty, which is
     HOL4's clause for it (ml/lib/hol4.ml) *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
 let grab asl p =
   tryfind (fun (_,th) ->
     if (try p th with Failure _ -> false) then th else fail())
     asl in
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   VAR_EQ_TAC THEN
   CASES_ON_NAME "vars'" THEN
   REWRITE_TAC[hol4_TL] THEN
   TRY(REWRITE_TAC[MAP; ALL_DISTINCT; PAIRWISE] THEN NO_TAC) THEN
   FIRST_ASSUM(fun mr ->
     if hd_is "memory_rel" (concl mr)
     then ASSUME_TAC(MATCH_MP memory_rel_tl mr)
     else fail()) THEN
   CASES_ON_NAME "a1" THEN
   REWRITE_TAC[hol4_TL] THEN
   TRY(REWRITE_TAC[MAP; ALL_DISTINCT; PAIRWISE] THEN NO_TAC) THEN
   FIRST_X_ASSUM(fun el ->
     if hd_is "elements_list" (concl el)
     then MP_TAC(REWRITE_RULE[MAP; elements_list_def] el)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   MATCH_MP_TAC
     memory_rel_elements_list_distinct_lemma THEN
   W(fun (asl,w) ->
     let be = grab asl (fun th ->
       is_eq (concl th) && hd_is "dataSem_Block" (rhs (concl th))) in
     let args = snd(strip_comb (rhs (concl be))) in
     let cs = conjuncts (snd(strip_exists w)) in
     EXISTS_TAC (rhs (el 2 cs)) THEN
     EXISTS_TAC (el 0 args) THEN EXISTS_TAC (el 1 args) THEN
     EXISTS_TAC (el 2 args)) THEN
   FIRST_ASSUM(fun e ->
     if is_eq (concl e) && hd_is "dataSem_Block" (rhs (concl e))
     then RULE_ASSUM_TAC(REWRITE_RULE[e]) THEN
          ASM_REWRITE_TAC[e; MAP; HD; NOT_CONS_NIL; PAIRWISE;
                          hol4_TL]
     else fail())));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_elements_list_words = prove
 (cake_as_vars (fun () ->
    `!vs vars'.
       memory_rel c be ts refs sp st m (dm:'a word->bool) vars' /\
       elements_list vs /\ vs = MAP FST vars' /\
       good_dimindex (:'a) ==> ~(vars' = []) ==> EVERY isWord (TL
         (MAP SND vars'))`),
  (* every root of the tail of an elements_list is a Word: the
     second element of the list is a Block by the third clause of
     elements_list, so the root of the tail that memory_rel_tl
     keeps is the Word that memory_rel_Block_IMP gives it, and the
     induction says it of the rest.  The hypothesis of the
     induction is moved into the goal, so that the split of the
     tail reaches it *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
  SUBGOAL_THEN
      `!vars0 (c:data_to_word_config) be ts refs sp st m dm.
         memory_rel c be ts refs sp st m (dm:'a word->bool) vars0 /\
         elements_list (MAP FST vars0) /\ good_dimindex (:'a)
         ==> ALL isWord (TL (MAP SND vars0))`
      (fun th ->
        REPEAT GEN_TAC THEN
        DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
        VAR_EQ_TAC THEN DISCH_THEN(K ALL_TAC) THEN
        W(fun (asl,w) ->
          let mr = grab asl (fun t -> hd_is "memory_rel" (concl t)) in
          let args = snd(strip_comb (concl mr)) in
          let el = grab asl (fun t ->
            hd_is "elements_list" (concl t)) in
          let gd = grab asl (fun t ->
            hd_is "good_dimindex" (concl t)) in
          ACCEPT_TAC(MP (SPECL (last args :: butlast args) th)
                        (CONJ mr (CONJ el gd))))) THEN
    LIST_INDUCT_TAC THENL
     [REWRITE_TAC[MAP; hol4_TL; ALL];
      ALL_TAC] THEN
    POP_ASSUM MP_TAC THEN
    W(fun (asl,w) ->
      STRUCT_CASES_TAC(ISPEC (var_by_name "t" (asl,w)) list_CASES))
    THENL
     [REWRITE_TAC[MAP; hol4_TL; ALL];
      ALL_TAC] THEN
    W(fun (asl,w) ->
      let l = last (snd(strip_comb (find_term (hd_is "memory_rel") w)))
        in
      let ty = hd (snd (dest_type (type_of l))) in
      STRUCT_CASES_TAC(ISPEC
        (find_term (fun u -> is_var u && type_of u = ty) w)
        PAIR_SURJECTIVE)) THEN
    REWRITE_TAC[MAP; FST; SND; hol4_TL; ALL] THEN
    DISCH_TAC THEN
    REPEAT GEN_TAC THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    FIRST_X_ASSUM(fun el ->
      if hd_is "elements_list" (concl el)
      then MP_TAC(REWRITE_RULE[elements_list_def] el)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_ASSUM(fun mr ->
      if hd_is "memory_rel" (concl mr)
      then ASSUME_TAC(MATCH_MP memory_rel_tl mr)
      else fail()) THEN
    CONJ_TAC THENL
     [W(fun (asl,w) ->
        let be = grab asl (fun th ->
          is_eq (concl th) && is_var (lhs (concl th)) &&
          hd_is "dataSem_Block" (rhs (concl th))) in
        let mr = grab asl (fun th ->
          hd_is "memory_rel" (concl th) &&
          fst(dest_pair(lhand(last(snd(strip_comb (concl th)))))) =
            lhs (concl be)) in
        let gd = grab asl (fun th ->
          hd_is "good_dimindex" (concl th)) in
        MP_TAC(MATCH_MP memory_rel_Block_IMP
                 (CONJ (REWRITE_RULE[be] mr) gd))) THEN
      DISCH_THEN STRIP_ASSUME_TAC THEN
      FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) && is_var (lhs (concl e)) &&
           hd_is "wordLang_Word" (rhs (concl e))
        then SUBST1_TAC e else fail()) THEN
      REWRITE_TAC[isWord_def] THEN MATCH_REDUCE_TAC THEN
      REWRITE_TAC[];
      W(fun (asl,w) ->
        let ih = grab asl (fun t ->
          is_forall (concl t) &&
          can (find_term (hd_is "memory_rel")) (concl t)) in
        let mr = grab asl (fun t ->
          hd_is "memory_rel" (concl t) &&
          not (hd_is "CONS"
                 (rand (last (snd(strip_comb (concl t))))))) in
        let args = butlast (snd(strip_comb (concl mr))) in
        let el = grab asl (fun t ->
          hd_is "elements_list" (concl t) &&
          hd_is "CONS" (rand (concl t))) in
        let gd = grab asl (fun t ->
          hd_is "good_dimindex" (concl t)) in
        ACCEPT_TAC(REWRITE_RULE[MAP; SND; hol4_TL]
          (MP (SPECL args ih) (CONJ mr (CONJ el gd)))))]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_depth_size_limit = prove
 (cake_as_vars (fun () ->
    `!v w vars'.
     memory_rel c be ts refs sp st m dm ((v,(w:'a word_loc)) ::
       vars') /\
     good_dimindex (:'a) ==>
     vb_size v <= dimword (:'a) EXP (v_depth v + 1)`),
(* the size of a value is below the word size to its depth and
   one, by the induction of the values.  A value that is no Block
   has size one and depth nought, an empty Block is its tag, which
   a sixteenth of the word holds (memory_rel_Block_IMP), and a
   Block with elements has its tag, its length and the sizes of
   its elements: each element is one that the memory holds in
   front of the Block (memory_rel_Block_MEM), so the induction
   hypothesis bounds its size by the word size to its own depth,
   and the greatest of those bounds is the word size to the
   greatest depth (MAX_LIST_MAP of the power, which grows with the
   depth).  The sum of the sizes is then below the length times
   that bound (MAX_LIST_sum_bound), and the tag and the length are
   each below a sixteenth of the word (v_inv_Block_tag_limit and
   the header's length), which is what the arithmetic of the step
   asks for *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  (* the induction of the values, with the hypothesis of a Block
     over its list *)
  let v_ind = prove
   (`!P. (!i. P (Number i)) /\ (!w. P (Word64 w)) /\
         (!ts t l. ALL P l ==> P (Block ts t l)) /\
         (!n. P (CodePtr n)) /\ (!b n. P (RefPtr b n)) ==>
         (!v. P (v:dataSem_v))`,
    GEN_TAC THEN DISCH_TAC THEN
    MP_TAC (ISPECL [`P:dataSem_v->bool`;
                    `ALL (P:dataSem_v->bool)`] dataSem_v_INDUCT) THEN
    ASM_REWRITE_TAC[ALL] THEN
    DISCH_THEN (ACCEPT_TAC o CONJUNCT1)) in
  (* HOL4's SUM is ITLIST (+) l 0 in the port (ml/lib/hol4.ml), so
     its clauses come first *)
  let sum_cl = prove
   (`SUM [] = 0 /\ (!h t. SUM (CONS h t) = h + SUM t)`,
    REWRITE_TAC[SUM_DEF; ITLIST]) in
  (* a word of the machine has room for sixteen, and for one to
     any power of itself *)
  let dwpos = prove
   (`good_dimindex (:'a) ==> 16 <= dimword (:'a)`,
    REWRITE_TAC[good_dimindex_def; dimword] THEN
    DISCH_THEN (DISJ_CASES_THEN SUBST1_TAC) THEN
    CONV_TAC NUM_REDUCE_CONV) in
  let one_le = prove
   (`!n. 1 <= dimword (:'a) EXP n`,
    INDUCT_TAC THEN REWRITE_TAC[EXP; LE_REFL] THEN
    MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `1 * 1` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[MULT_CLAUSES; LE_REFL];
      MATCH_MP_TAC LE_MULT2 THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[dimword; ARITH_RULE `1 <= n <=> ~(n = 0)`;
                  EXP_EQ_0] THEN ARITH_TAC]) in
  (* the power of the word size grows with the depth *)
  let mono_exp = prove
   (`good_dimindex (:'a)
     ==> !x y. x < y ==> dimword (:'a) EXP (x + 1) <
                         dimword (:'a) EXP (y + 1)`,
    DISCH_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
    REWRITE_TAC[LT_EXP] THEN
    FIRST_ASSUM (fun gd -> MP_TAC (MATCH_MP dwpos gd)) THEN
    ASM_ARITH_TAC) in
  (* and a sixteenth of it is what the header of a Block leaves *)
  let dwdiv = prove
   (`good_dimindex (:'a)
     ==> dimword (:'a) DIV 16 = 2 EXP (dimindex (:'a) - 4)`,
    REWRITE_TAC[good_dimindex_def; dimword] THEN
    DISCH_THEN (DISJ_CASES_THEN SUBST1_TAC) THEN
    CONV_TAC NUM_REDUCE_CONV) in
  let exp_split = prove
   (`!m. dimword (:'a) EXP ((1 + m) + 1) =
         dimword (:'a) * dimword (:'a) EXP (m + 1)`,
    GEN_TAC THEN REWRITE_TAC[EXP_ADD; EXP_1] THEN
    REWRITE_TAC[MULT_AC]) in
  (* two lists that a map of each element gives are related when
     the elements are, and the head of a related list is *)
  let all2_map = prove
   (`!(f:A->num) g l. (!x. MEM x l ==> f x <= g x)
        ==> ALL2 (<=) (MAP f l) (MAP g l)`,
    REPEAT GEN_TAC THEN SPEC_TAC (`l:(A)list`,`l:(A)list`) THEN
    LIST_INDUCT_TAC THEN REWRITE_TAC[MAP; ALL2; MEM] THEN
    ASM_MESON_TAC[]) in
  let all2_hd = prove
   (`!P x xs ys. ALL2 (P:A->B->bool) (CONS x xs) ys ==> ?y. P x y`,
    REPEAT GEN_TAC THEN
    STRUCT_CASES_TAC (ISPEC `ys:(B)list` list_CASES) THEN
    REWRITE_TAC[ALL2] THEN MESON_TAC[]) in
  let map_dep = prove
   (`!l. MAP (\x. dimword (:'a) EXP (v_depth x + 1)) l =
         MAP (\y. dimword (:'a) EXP (y + 1)) (MAP v_depth l)`,
    LIST_INDUCT_TAC THEN ASM_REWRITE_TAC[MAP]) in
  (* so the greatest size of an element is below the word size to
     the greatest depth of one (MAX_LIST_MAP of the power, which
     grows) *)
  let max_bound = prove
   (cake_as_vars (fun () ->
      `good_dimindex (:'a) /\ ~(l = []) /\
       (!e. MEM e l
            ==> vb_size e <= dimword (:'a) EXP (v_depth e + 1))
       ==> MAX_LIST (MAP vb_size l) <=
           dimword (:'a) EXP (MAX_LIST (MAP v_depth l) + 1)`),
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "gd")
      (CONJUNCTS_THEN2 (LABEL_TAC "nn") (LABEL_TAC "eb"))) THEN
    MATCH_MP_TAC LE_TRANS THEN
    EXISTS_TAC `MAX_LIST (MAP (\x. dimword (:'a) EXP
                  (v_depth x + 1)) l)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC MAX_LIST_bounded_elements THEN
      MATCH_MP_TAC all2_map THEN
      CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
      USE_THEN "eb" MATCH_ACCEPT_TAC;
      REWRITE_TAC[map_dep] THEN
      USE_THEN "gd" (fun gd ->
        let mono = MATCH_MP mono_exp gd in
        MP_TAC (BETA_RULE (MP (BETA_RULE (SPECL
          [`\y. dimword (:'a) EXP (y + 1)`;
           `MAP v_depth (l:(dataSem_v)list)`] MAX_LIST_MAP))
          mono))) THEN
      USE_THEN "nn" (fun nn ->
        ASM_REWRITE_TAC[NULL_EQ; MAP_EQ_NIL]) THEN
      DISCH_THEN (fun th -> REWRITE_TAC[th; LE_REFL])]) in
  (* and each element of a Block is one that the memory holds in
     front of it (memory_rel_Block_MEM), so the induction
     hypothesis bounds its size *)
  let elem_bound = prove
   (cake_as_vars (fun () ->
      `ALL (\e. !w vars'.
              memory_rel c be ts refs sp st m dm ((e,(w:'a
                word_loc)) :: vars') /\ good_dimindex (:'a)
              ==> vb_size e <= dimword (:'a) EXP (v_depth e + 1))
         l /\
       memory_rel c be ts refs sp st m dm ((Block ts' t l,(w:'a
         word_loc)) :: vars') /\
       good_dimindex (:'a)
       ==> !e. MEM e l
               ==> vb_size e <= dimword (:'a) EXP (v_depth e + 1)`),
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "ih")
      (CONJUNCTS_THEN2 (LABEL_TAC "mr") (LABEL_TAC "gd"))) THEN
    X_GEN_TAC `e:dataSem_v` THEN DISCH_TAC THEN
    FIRST_ASSUM (fun mm ->
      if not (try hd_is "MEM" (concl mm) with Failure _ -> false)
      then fail() else
      MP_TAC (REWRITE_RULE[MEM_EXISTS_EL] mm)) THEN
    DISCH_THEN (X_CHOOSE_THEN `i:num` STRIP_ASSUME_TAC) THEN
    USE_THEN "mr" (fun mr -> USE_THEN "gd" (fun gd ->
      FIRST_ASSUM (fun lt ->
        if not (try hd_is "<" (concl lt) &&
                    hd_is "LENGTH" (rand (concl lt))
                with Failure _ -> false) then fail() else
        STRIP_ASSUME_TAC (MATCH_MP (GEN_ALL memory_rel_Block_MEM)
          (CONJ mr (CONJ lt gd)))))) THEN
    FIRST_ASSUM (fun eq ->
      if not (try is_eq (concl eq) && hd_is "EL" (rhs (concl eq))
              with Failure _ -> false) then fail() else
      RULE_ASSUM_TRY (REWRITE_RULE[GSYM eq])) THEN
    USE_THEN "ih" (fun ih ->
      FIRST_ASSUM (fun mm ->
        if not (try hd_is "MEM" (concl mm)
                with Failure _ -> false) then fail() else
        USE_THEN "gd" (fun gd ->
          FIRST_ASSUM (fun mr2 ->
            if not (hd_is "memory_rel" (concl mr2)) then fail() else
            MATCH_ACCEPT_TAC (MATCH_MP (BETA_RULE (MATCH_MP
              (REWRITE_RULE[GSYM ALL_MEM] ih) mm))
              (CONJ mr2 gd))))))) in
  (* the arithmetic of the step: the sizes of the elements and the
     tag and the length of the Block all fit *)
  let arith_core = prove
   (`!d t l s sz.
       1 <= sz /\ 16 <= d /\ t < d DIV 16 /\ l < d DIV 16 /\
       s <= l * sz ==> 1 + t + s + l <= d * sz`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `1 + t + s + l = (1 + t + l) + s` SUBST1_TAC THENL
     [ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC LE_TRANS THEN
    EXISTS_TAC `(d DIV 8) * sz + l * sz` THEN CONJ_TAC THENL
     [MATCH_MP_TAC LE_ADD2 THEN CONJ_TAC THENL
       [MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `(d DIV 8) * 1` THEN
        CONJ_TAC THENL
         [REWRITE_TAC[MULT_CLAUSES] THEN ASM_ARITH_TAC;
          MATCH_MP_TAC LE_MULT2 THEN ASM_REWRITE_TAC[LE_REFL]];
        FIRST_ASSUM ACCEPT_TAC];
      REWRITE_TAC[GSYM RIGHT_ADD_DISTRIB] THEN
      MATCH_MP_TAC LE_MULT2 THEN REWRITE_TAC[LE_REFL] THEN
      ASM_ARITH_TAC]) in
  let unfold =
    ONCE_REWRITE_TAC[vb_size_def; v_depth_def] THEN
    MATCH_REDUCE_TAC in
  (* a value that is no Block has size one and depth nought *)
  let nb =
    REPEAT GEN_TAC THEN STRIP_TAC THEN unfold THEN
    REWRITE_TAC[ADD_CLAUSES] THEN MATCH_ACCEPT_TAC one_le in
  W(fun (asl,gl) ->
    let v,bod = dest_forall gl in
    MATCH_MP_TAC (CONV_RULE (TOP_DEPTH_CONV BETA_CONV)
                    (ISPEC (mk_abs (v,bod)) v_ind))) THEN
  REPEAT CONJ_TAC THENL
   [nb; nb;
    REPEAT GEN_TAC THEN DISCH_THEN (LABEL_TAC "ih") THEN
    REPEAT GEN_TAC THEN
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "mr")
      (LABEL_TAC "gd")) THEN
    unfold THEN
    ASM_CASES_TAC `l:(dataSem_v) list = []` THENL
     [(* the empty Block is its tag and the two words of its
         header *)
      ASM_REWRITE_TAC[MAP; sum_cl; LENGTH; NULL; MAX_LIST;
                      ADD_CLAUSES; EXP_1] THEN
      USE_THEN "mr" (fun mr -> USE_THEN "gd" (fun gd ->
        FIRST_ASSUM (fun nl ->
          if not (is_eq (concl nl)) then fail() else
          STRIP_ASSUME_TAC (REWRITE_RULE[nl]
            (MATCH_MP memory_rel_Block_IMP (CONJ mr gd)))))) THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    (* the length of a Block and its tag fit in a sixteenth of the
       word *)
    USE_THEN "mr" (fun mr -> USE_THEN "gd" (fun gd ->
      FIRST_ASSUM (fun nl ->
        if not (is_neg (concl nl)) then fail() else
        STRIP_ASSUME_TAC (REWRITE_RULE[nl]
          (MATCH_MP memory_rel_Block_IMP (CONJ mr gd)))))) THEN
    USE_THEN "mr" (fun mr ->
      STRIP_ASSUME_TAC (REWRITE_RULE[memory_rel_def;
        word_ml_inv_def; abs_ml_inv_def; bc_stack_ref_inv_def;
        MAP; FST] mr)) THEN
    FIRST_ASSUM (fun a2 ->
      if not (hd_is "ALL2" (concl a2)) then fail() else
      MP_TAC (BETA_RULE (MATCH_MP all2_hd a2))) THEN
    DISCH_THEN (CHOOSE_THEN ASSUME_TAC) THEN
    FIRST_ASSUM (fun vi ->
      if not (hd_is "v_inv" (concl vi)) then fail() else
      FIRST_ASSUM (fun hm ->
        if not (hd_is "heap_in_memory_store" (concl hm))
        then fail() else
        ASSUME_TAC (MATCH_MP v_inv_Block_tag_limit
          (CONJ vi hm)))) THEN
    (* the greatest size of an element *)
    USE_THEN "ih" (fun ih ->
      USE_THEN "mr" (fun mr ->
        USE_THEN "gd" (fun gd ->
          FIRST_ASSUM (fun nn ->
            if not (is_neg (concl nn)) then fail() else
            let eb = MATCH_MP elem_bound (CONJ ih (CONJ mr gd)) in
            ASSUME_TAC (MATCH_MP max_bound
              (CONJ gd (CONJ nn eb))))))) THEN
    (* so the sum of the sizes is below the length times it *)
    SUBGOAL_THEN
      `SUM (MAP vb_size (l:(dataSem_v)list)) <= LENGTH l *
         dimword (:'a) EXP (MAX_LIST (MAP v_depth l) + 1)`
      ASSUME_TAC THENL
     [MATCH_MP_TAC LE_TRANS THEN
      EXISTS_TAC `MAX_LIST (MAP vb_size (l:(dataSem_v)list)) *
                  LENGTH (l:(dataSem_v)list)` THEN
      CONJ_TAC THENL
       [MP_TAC (INST [`MAP vb_size (l:(dataSem_v)list)`,
                      mk_var("ls",`:(num)list`)]
                  MAX_LIST_sum_bound) THEN
        REWRITE_TAC[LENGTH_MAP];
        ONCE_REWRITE_TAC[SPECL
          [`MAX_LIST (MAP vb_size (l:(dataSem_v)list))`;
           `LENGTH (l:(dataSem_v)list)`] MULT_SYM] THEN
        MATCH_MP_TAC LE_MULT2 THEN
        ASM_REWRITE_TAC[LE_REFL]];
      ALL_TAC] THEN
    (* and what is left is the arithmetic *)
    ASM_REWRITE_TAC[NULL_EQ] THEN
    REWRITE_TAC[exp_split] THEN
    MATCH_MP_TAC arith_core THEN REPEAT CONJ_TAC THENL
     [MATCH_ACCEPT_TAC one_le;
      USE_THEN "gd" (fun gd ->
        MATCH_ACCEPT_TAC (MATCH_MP dwpos gd));
      FIRST_ASSUM MATCH_ACCEPT_TAC;
      USE_THEN "gd" (fun gd -> REWRITE_TAC[MATCH_MP dwdiv gd]) THEN
      FIRST_ASSUM MATCH_ACCEPT_TAC;
      FIRST_ASSUM MATCH_ACCEPT_TAC];
    nb; nb])));;

(* the first pass assumes the termination:
   replacing the CHEAT_TAC is all that is left *)
(* the clauses of the source overlap -- the last one says NONE of a
   pair that an earlier one has already given a value -- and HOL4
   takes the first that matches, so the port writes them as a
   match, which takes the first arm (see ml/lib/define.ml, "A
   definition whose clauses overlap").  As a list of clauses they
   would be inconsistent. *)
let vb_eq_size_def = cake_define_list_cheat CHEAT_TAC
  [`vb_eq_size refs x2 x3 =
         match (x2,x3) with
           ((Block _91 t1 l1:dataSem_v),(Block _92 t2 l2:dataSem_v))
             ->
         (if isClos t1 l1 \/ isClos t2 l2 then if isClos t1 l1 /\
           isClos t2 l2 then SOME ((1:num),T) else NONE else if (t1 =
           t2) /\ (LENGTH l1 = LENGTH l2) then OPTION_MAP (\(n,b). (n +
           1,b)) (vb_eq_size_list refs l1 l2) else SOME (1,F))
         | ((RefPtr b1 n1),(RefPtr b2 n2)) ->
         (if b1 /\ b2 then
           (match (sptree_lookup n1 refs,sptree_lookup n2 refs) with
              (SOME (ByteArray T bs1),SOME (ByteArray T bs2)) ->
                SOME (1,(bs1 = bs2)) | (SOME (ByteArray T bs1),_93) ->
                NONE | (_94,SOME (ByteArray T bs2)) -> NONE | _95 ->
                SOME (1,(n1 = n2))) else NONE)
         | ((Number n1),(Number n2)) -> SOME (1,(n1 = n2))
         | ((Word64 w1),(Word64 w2)) -> SOME (1,(w1 = w2))
         | (_96,_97) -> NONE`;
   `vb_eq_size_list refs x2 x3 =
         match (x2,x3) with
           ([],[]) -> SOME (0,T)
         | ([],_98) -> SOME (0,F)
         | (_99,[]) -> SOME (0,F)
         | ((v1 :: vs1),(v2 :: vs2)) ->
         (match vb_eq_size refs v1 v2 with NONE -> NONE | SOME (n,F)
           -> SOME (n + 1,F) | SOME (n,T) -> (
           match vb_eq_size_list refs vs1 vs2 with NONE -> NONE
             | SOME (m,b) -> SOME (m + n + 1,b)))`];;

(* the port's own: what the two theorems about vb_eq_size go by.
   The definition is the one match that HOL4 means (its clauses
   overlap), so a proof that takes two values apart would reduce
   that match again in each of the twenty-five cases
   (PORTING-GUIDE.md entry 43).  The two lemmas below pay that
   reduction once and say what a SOME of each of the two functions
   can be, and the proofs after them are a complete induction on
   the size of the value with those two, the size of a Block and
   arithmetic *)

(* the clauses of SUM, which the port defines as an ITLIST *)
let vb_sum_clauses = prove
 (`SUM [] = 0 /\ (!h t. SUM (CONS h t) = h + SUM t)`,
  REWRITE_TAC[SUM_DEF; ITLIST]);;

(* what a value of the map of the successor of a pair is *)
let option_map_pair_eq = prove
 (`OPTION_MAP (\(k,c). (k + 1,c)) (x:(num#bool)option) = SOME (n,b)
   <=> (?m. x = SOME (m,b) /\ n = m + 1)`,
  CASES_ON_TAC `x:(num#bool)option` THEN
  REWRITE_TAC[OPTION_MAP; distinctness "option"] THEN
  TRY (SOLVED (REWRITE_TAC[])) THEN
  W(fun (asl,w) -> CASES_ON_TAC (rand (rand (lhand (lhand w))))) THEN
  REWRITE_TAC[OPTION_MAP] THEN
  CONV_TAC(TOP_DEPTH_CONV GEN_BETA_CONV) THEN
  REWRITE_TAC[injectivity "option"; PAIR_EQ] THEN
  MESON_TAC[]);;

(* and the same under the existential that the two theorems put
   it under *)
let exists_option_map_pair = prove
 (`(?n. OPTION_MAP (\(k,c). (k + 1,c)) (x:(num#bool)option)
          = SOME (n,b)) <=> (?m. x = SOME (m,b))`,
  REWRITE_TAC[option_map_pair_eq] THEN MESON_TAC[]);;

(* a value is at least one word big, and a Block is as big as its
   payload *)
let vb_size_ge_1 = prove
 (`!v. 1 <= vb_size (v:dataSem_v)`,
  GEN_TAC THEN CASES_ON_TAC `v:dataSem_v` THEN
  ONCE_REWRITE_TAC[vb_size_def] THEN SAFE_MATCH_REDUCE_TAC THEN
  ARITH_TAC);;

let vb_size_Block = prove
 (`vb_size (Block ts t ls:dataSem_v) =
   1 + t + SUM (MAP vb_size ls) + LENGTH ls`,
  ONCE_REWRITE_TAC[vb_size_def] THEN SAFE_MATCH_REDUCE_TAC THEN
  REWRITE_TAC[]);;

(* what a SOME of vb_eq_size can be: one word, or one more than
   what the payloads of two Blocks took.  The definition is
   unfolded in the antecedent only -- the function stands in the
   conclusion as well, and a rewrite that reaches it there unfolds
   the match the lemma is there to avoid *)
let vb_eq_size_cases = prove
 (`!(refs:('a bvlSem_ref) spt) v1 v2 n b.
     vb_eq_size refs v1 v2 = SOME (n,b)
     ==> n = 1 \/
         (?ts1 t1 l1 ts2 t2 l2 m.
            v1 = Block ts1 t1 l1 /\ v2 = Block ts2 t2 l2 /\
            vb_eq_size_list refs l1 l2 = SOME (m,b) /\ n = m + 1)`,
  REPEAT GEN_TAC THEN
  CASES_ON_TAC `v1:dataSem_v` THEN CASES_ON_TAC `v2:dataSem_v` THEN
  GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [vb_eq_size_def] THEN
  CONV_TAC (LAND_CONV (REDEPTH_CONV safe_match_conv)) THEN
  REPEAT COND_CASES_TAC THEN
  REWRITE_TAC[option_map_pair_eq; distinctness "option";
              injectivity "option"; PAIR_EQ] THEN
  (* of two values that are no Block, and of two Blocks that the
     function decided by their tags: one word *)
  TRY (SOLVED (STRIP_TAC THEN ASM_REWRITE_TAC[])) THEN
  (* of two Blocks whose payloads it went into: one more than
     what the payloads took *)
  TRY (SOLVED
    (STRIP_TAC THEN DISJ2_TAC THEN
     W(fun (asl,w as gl) ->
       let cs = conjuncts (snd (strip_exists w)) in
       let lk = the_asm (fun c -> is_eq c &&
                  hd_is "vb_eq_size_list" (lhand c)) gl in
       MAP_EVERY EXISTS_TAC
         (snd (strip_comb (lhand (el 0 cs))) @
          snd (strip_comb (lhand (el 1 cs))) @
          [lhand (rand (rand (concl lk)))])) THEN
     ASM_REWRITE_TAC[])) THEN
  (* of two pointers: whatever the two lookups are, it is one *)
  DISCH_TAC THEN EVERY_CASE_TAC THEN
  RULE_ASSUM_TRY (REWRITE_RULE[distinctness "option";
                              injectivity "option"; PAIR_EQ]) THEN
  TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
  ASM_REWRITE_TAC[]);;

(* and what a SOME of the list function can be: nothing, or the
   value of the two elements and then that of the two rests *)
let vb_eq_size_list_cases = prove
 (`!(refs:('a bvlSem_ref) spt) l1 l2 n b.
     vb_eq_size_list refs l1 l2 = SOME (n,b)
     ==> n = 0 \/
         (?x1 t1 x2 t2 k.
            l1 = CONS x1 t1 /\ l2 = CONS x2 t2 /\
            ((vb_eq_size refs x1 x2 = SOME (k,F) /\ n = k + 1) \/
             (?m. vb_eq_size refs x1 x2 = SOME (k,T) /\
                  vb_eq_size_list refs t1 t2 = SOME (m,b) /\
                  n = m + k + 1)))`,
  REPEAT GEN_TAC THEN
  CASES_ON_TAC `l1:dataSem_v list` THEN
  CASES_ON_TAC `l2:dataSem_v list` THEN
  GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV) [vb_eq_size_def] THEN
  CONV_TAC (LAND_CONV (REDEPTH_CONV safe_match_conv)) THEN
  REWRITE_TAC[distinctness "option"; injectivity "option";
              PAIR_EQ] THEN
  (* of two lists of which one is empty: nothing *)
  TRY (SOLVED (STRIP_TAC THEN ASM_REWRITE_TAC[])) THEN
  (* and of two lists with an element each: the elements, and then
     the rests where the elements were equal.  A branch that the
     split of the two values settled on its own is past the
     witnesses, which is what the TRYs are for *)
  DISCH_TAC THEN EVERY_CASE_TAC THEN
  TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
  TRY DISJ2_TAC THEN
  TRY (W(fun (asl,w as gl) ->
    let cs = conjuncts (snd (strip_exists w)) in
    let eq = the_asm (fun c -> is_eq c &&
               hd_is "vb_eq_size" (lhand c)) gl in
    MAP_EVERY EXISTS_TAC
      (snd (strip_comb (lhand (el 0 cs))) @
       snd (strip_comb (lhand (el 1 cs))) @
       [lhand (rand (rand (concl eq)))]))) THEN
  TRY (ASM_REWRITE_TAC[injectivity "option"; PAIR_EQ]) THEN
  TRY (SOLVED (ARITH_ASM_TAC)) THEN
  W(fun gl ->
    let lk = the_asm (fun c -> is_eq c &&
               hd_is "vb_eq_size_list" (lhand c) &&
               hd_is "SOME" (rand c) &&
               (try is_var (el 1 (snd (strip_comb (lhand c))))
                with Failure _ -> false)) gl in
    EXISTS_TAC (lhand (rand (rand (concl lk))))) THEN
  ASM_REWRITE_TAC[injectivity "option"; PAIR_EQ] THEN
  TRY (SOLVED (ARITH_ASM_TAC)));;

let vb_eq_size_IMP_vb_size = prove
 (`(!(refs:('a bvlSem_ref) spt) v1 v2 n b.
     vb_eq_size refs v1 v2 = SOME (n,b) ==> n <= vb_size v1) /\
   (!(refs:('a bvlSem_ref) spt) v1 v2 n b.
     vb_eq_size_list refs v1 v2 = SOME (n,b) ==> n <= SUM (MAP
       vb_size v1) + LENGTH v1)`,
  (* the complete induction on the size of the value that the
     definition recurses on (PORTING-GUIDE.md entry 44), with
     the measure bounded so that the hypothesis is about the
     measure of a sub-term.  What a value of the two functions
     can be is above the statement (tools/overrides.py): of a
     value one word or one more than what the payloads of two
     Blocks took, of a list nothing or the element and then the
     rest.  The payload of a Block is smaller than the Block
     (vb_size_Block) and so are an element of a list and the
     rest of it, which is what the bound of each use of the
     hypothesis comes to; the leaves are arithmetic *)
  ((* the measure of a list of values: what the statement about the
     list function bounds its value by *)
  let meas l = mk_binop `(+):num->num->num`
      (list_mk_icomb "SUM" [list_mk_icomb "MAP" [`vb_size`; l]])
      (list_mk_icomb "LENGTH" [l]) in
  (* the hypothesis of the complete induction at a measure, used
     on an equation of the assumptions: the bound is the first
     goal, and the value of the sub-term is bounded in the second *)
  let use_ih which t eq (asl,w as gl) =
    let ih = the_asm (fun c -> is_forall c &&
               (try hd_is "<" (lhand (snd (strip_forall c)))
                with Failure _ -> false)) gl in
    let kk = rand (lhand (snd (strip_forall (concl ih)))) in
    (SUBGOAL_THEN (mk_binop `(<):num->num->bool` t kk)
       (fun lt -> MP_TAC (MATCH_MP (which (MP (SPEC t ih) lt))
                            (CONJ (SPEC t LE_REFL) eq)))) gl in
  (* the equation of the assumptions that a function left, with
     the sub-term it is about *)
  let the_eq nm vr gl =
    let eq = the_asm (fun c -> is_eq c && hd_is nm (lhand c) &&
               (not vr ||
                (try is_var (el 1 (snd (strip_comb (lhand c))))
                 with Failure _ -> false))) gl in
    eq,el 1 (snd (strip_comb (lhand (concl eq)))) in
  (* the statement of the induction, with the measure bounded, so
     that the hypothesis is about the measure of a sub-term and not
     about the bound (PORTING-GUIDE.md entry 5) *)
  SUBGOAL_THEN
   `!k. (!(refs:('a bvlSem_ref) spt) v1 v2 n b.
           vb_size v1 <= k /\ vb_eq_size refs v1 v2 = SOME (n,b)
           ==> n <= vb_size v1) /\
        (!(refs:('a bvlSem_ref) spt) v1 v2 n b.
           SUM (MAP vb_size v1) + LENGTH v1 <= k /\
           vb_eq_size_list refs v1 v2 = SOME (n,b)
           ==> n <= SUM (MAP vb_size v1) + LENGTH v1)`
   (fun th ->
      CONJ_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THENL
       [MP_TAC (CONJUNCT1 (SPEC `vb_size (v1:dataSem_v)` th));
        MP_TAC (CONJUNCT2 (SPEC
          `SUM (MAP vb_size (v1:dataSem_v list)) +
           LENGTH (v1:dataSem_v list)` th))] THEN
      ASM_MESON_TAC[LE_REFL]) THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN DISCH_TAC THEN
  CONJ_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THENL
   [(* a value: its size is one word, or one more than what the
       payloads of two Blocks took *)
    FIRST_ASSUM (fun eq ->
      if not (is_eq (concl eq) &&
              hd_is "vb_eq_size" (lhand (concl eq))) then fail()
      else STRIP_ASSUME_TAC (MATCH_MP vb_eq_size_cases eq)) THEN
    TRY (SOLVED (ASM_REWRITE_TAC[vb_size_ge_1])) THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      let c = concl th in
      if is_eq c && is_var (lhand c) &&
         not (vfree_in (lhand c) (rand c))
      then SUBST_ALL_TAC th else fail())) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[vb_size_Block]) THEN
    REWRITE_TAC[vb_size_Block] THEN
    (* the payload is smaller than the Block it is in *)
    W(fun gl ->
      let lk,l1 = the_eq "vb_eq_size_list" false gl in
      use_ih CONJUNCT2 (meas l1) lk) THEN
    TRY (SOLVED ARITH_ASM_TAC) THEN
    ARITH_TAC;
    (* a list of values: nothing, or its first element and the
       rest of the list *)
    FIRST_ASSUM (fun eq ->
      if not (is_eq (concl eq) &&
              hd_is "vb_eq_size_list" (lhand (concl eq)))
      then fail()
      else STRIP_ASSUME_TAC (MATCH_MP vb_eq_size_list_cases eq)) THEN
    TRY (SOLVED (ASM_REWRITE_TAC[LE_0])) THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      let c = concl th in
      if is_eq c && is_var (lhand c) &&
         not (vfree_in (lhand c) (rand c))
      then SUBST_ALL_TAC th else fail())) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[MAP; LENGTH; vb_sum_clauses]) THEN
    REWRITE_TAC[MAP; LENGTH; vb_sum_clauses] THEN
    (* the element is smaller than the list it is in *)
    W(fun gl ->
      let eq,x1 = the_eq "vb_eq_size" false gl in
      use_ih CONJUNCT1 (list_mk_icomb "vb_size" [x1]) eq) THEN
    TRY (SOLVED ARITH_ASM_TAC) THEN
    (* and so is the rest of it, where the value of the element
       left one *)
    TRY (W(fun gl ->
           let lk,t1 = the_eq "vb_eq_size_list" true gl in
           use_ih CONJUNCT2 (meas t1) lk)) THEN
    TRY (SOLVED ARITH_ASM_TAC) THEN
    ARITH_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_limit = prove
 (cake_as_vars (fun () ->
    `!v w.
       memory_rel c be ts refs sp st m dm
         ((v1,(w1:'a word_loc)) :: (v2,(w2:'a word_loc)) :: vars)
           /\
       vb_eq_size refs v1 v2 = SOME (n,b) /\
       good_dimindex (:'a) ==>
       n * dimword (:'a) < MustTerminate_limit (:'a) - dimword
         (:'a)`),
(* the proof of the source bounds the size by
   memory_rel_depth_size_limit and vb_eq_size_IMP_vb_size, and the
   depth by the stack that memory_rel_depth_limit gives: its roots
   are distinct (memory_rel_elements_list_distinct) words
   (memory_rel_elements_list_words), so there are no more of them
   than there are words (word_list_limit).  What is left is the
   arithmetic, which is the lemma below: the size is at most the
   word size to the depth and one more, the depth at most the word
   size, and the limit of the source has the word size to the word
   size to the word size in it *)
  (let mtl = prove
   (`!n d l. 2 <= d /\ n <= d EXP (l + 1) /\ l <= d ==>
       n * d < (2 * d + d * d + d EXP d + d EXP d EXP d) - d`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `~(d = 0) /\ ~(d = 1)` STRIP_ASSUME_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC (ARITH_RULE
      `!p q r s t. 1 <= q /\ p <= t
                   ==> p < (2 * q + r + s + t) - q`) THEN
    CONJ_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `d EXP (l + 2)` THEN
    CONJ_TAC THENL
     [RULE_ASSUM_TRY (REWRITE_RULE[EXP_ADD; EXP_1]) THEN
      ONCE_REWRITE_TAC[ARITH_RULE `l + 2 = (l + 1) + 1`] THEN
      REWRITE_TAC[EXP_ADD; EXP_1] THEN
      MATCH_MP_TAC LE_MULT2 THEN ASM_REWRITE_TAC[LE_REFL];
      MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `d EXP (d + 2)` THEN
      CONJ_TAC THENL
       [ASM_REWRITE_TAC[LE_EXP] THEN ASM_ARITH_TAC;
        REWRITE_TAC[GSYM EXP_MULT] THEN
        ASM_REWRITE_TAC[LE_EXP] THEN
        MATCH_MP_TAC LE_TRANS THEN EXISTS_TAC `(d:num) * 2` THEN
        CONJ_TAC THENL
         [ASM_ARITH_TAC; ASM_REWRITE_TAC[LE_MULT_LCANCEL]]]]) in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `2 <= dimword (:'a)` ASSUME_TAC THENL
   [FIRST_ASSUM (fun gd ->
      if hd_is "good_dimindex" (concl gd)
      then MP_TAC (REWRITE_RULE[good_dimindex_def] gd)
      else fail()) THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[dimword] THEN
    CONV_TAC NUM_REDUCE_CONV;
    ALL_TAC] THEN
  FIRST_ASSUM (fun vb ->
    if (try hd_is "vb_eq_size" (lhs (concl vb))
        with Failure _ -> false)
    then STRIP_ASSUME_TAC
           (MATCH_MP (CONJUNCT1 vb_eq_size_IMP_vb_size) vb)
    else fail()) THEN
  FIRST_ASSUM (fun mr ->
    if not (hd_is "memory_rel" (concl mr)) then fail() else
    FIRST_ASSUM (fun gd ->
      if not (hd_is "good_dimindex" (concl gd)) then fail() else
      STRIP_ASSUME_TAC (MATCH_MP (GEN_ALL
        memory_rel_depth_size_limit) (CONJ mr gd)))) THEN
  SUBGOAL_THEN (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       [(v1,(w1:'a word_loc))]`)) ASSUME_TAC THENL
   [FIRST_ASSUM (fun mr ->
      if not (hd_is "memory_rel" (concl mr)) then fail() else
      MP_TAC mr THEN MATCH_MP_TAC memory_rel_rearrange THEN
      REWRITE_TAC[MEM] THEN MESON_TAC[]);
    ALL_TAC] THEN
  FIRST_ASSUM (fun mr1 ->
    if not (hd_is "memory_rel" (concl mr1)) then fail() else
    let stack = last (snd (strip_comb (concl mr1))) in
    if not (length (dest_list stack) = 1) then fail() else
    FIRST_ASSUM (fun gd ->
      if not (hd_is "good_dimindex" (concl gd)) then fail() else
      let el1 = prove
        (`elements_list (CONS (v1:dataSem_v)
            (MAP FST ([]:(dataSem_v # ('a word_loc))list)))`,
         REWRITE_TAC[MAP; elements_list_def]) in
      STRIP_ASSUME_TAC (MATCH_MP (GEN_ALL memory_rel_depth_limit)
        (CONJ mr1 (CONJ el1 gd))))) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[MAP]) THEN
  MP_TAC (ISPECL
    [`MAP FST (ls:(dataSem_v # ('a word_loc))list) ++ [v1]`;
     `(ls:(dataSem_v # ('a word_loc))list) ++ [v1,(w1:'a word_loc)]`]
    memory_rel_elements_list_distinct) THEN
  ASM_REWRITE_TAC[MAP_APPEND; MAP; FST] THEN DISCH_TAC THEN
  MP_TAC (ISPECL
    [`MAP FST (ls:(dataSem_v # ('a word_loc))list) ++ [v1]`;
     `(ls:(dataSem_v # ('a word_loc))list) ++ [v1,(w1:'a word_loc)]`]
    memory_rel_elements_list_words) THEN
  ASM_REWRITE_TAC[MAP_APPEND; MAP; FST; APPEND_EQ_NIL;
                  NOT_CONS_NIL] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `LENGTH (ls:(dataSem_v # ('a word_loc))list)
                  <= dimword (:'a)` ASSUME_TAC THENL
   [ASM_CASES_TAC `ls:(dataSem_v # ('a word_loc))list = []` THENL
     [ASM_REWRITE_TAC[LENGTH] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    MP_TAC (ISPEC `ls:(dataSem_v # ('a word_loc))list`
              list_CASES) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN SUBST_ALL_TAC) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[APPEND; MAP; MAP_APPEND; FST;
                                 SND; hol4_TL]) THEN
    FIRST_ASSUM (fun ev ->
      if not (hd_is "ALL" (concl ev)) then fail() else
      FIRST_ASSUM (fun ad ->
        if not (hd_is "ALL_DISTINCT" (concl ad)) then fail() else
        MP_TAC (MATCH_MP (GEN_ALL word_list_limit)
                  (CONJ ev ad)))) THEN
    REWRITE_TAC[LENGTH_MAP; LENGTH_APPEND; LENGTH] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[MustTerminate_limit_def] THEN
  MATCH_MP_TAC mtl THEN
  EXISTS_TAC `v_depth (v1:dataSem_v)` THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THENL
   [MATCH_MP_TAC LE_TRANS THEN
    EXISTS_TAC `vb_size (v1:dataSem_v)` THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ASM_REWRITE_TAC[] THEN FIRST_ASSUM ACCEPT_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_ptr_eq = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((v1,x1) :: (v2,(x1:'a
  word_loc)) :: vars) /\
     do_eq refs v1 v2 = Eq_val b /\
     good_dimindex (:'a) ==> b`),
  (* the attempt: of what the proof of the source names,
     the port has nothing in this file's closure, so this
     is the plain attempt, with the cheat behind it until
     the proof is written *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[] THEN TRY ASM_ARITH_TAC)));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Block_Block_small_eq = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((Block ts1 t1 v1,wordLang_Word (w1:'a word)) :: (Block ts2
         t2 v2,wordLang_Word w2) :: vars) /\
     good_dimindex (:'a) /\ ~(w1 = w2) /\ ~(word_bit 0 w1) ==>
       ~(LENGTH v1 = LENGTH v2) \/ ~(t1 = t2)`),
  (* the first Block has its lowest bit clear, so it is the empty
     one, whose word is sixteen times its tag plus two.  If the two
     had the same length and the same tag the second would be the
     empty one of the same tag, whose word is the same word, which
     the assumption says it is not *)
  (let subst_vars =
     REPEAT(FIRST_X_ASSUM(fun th ->
       if is_eq(concl th) && is_var(lhand(concl th))
       then SUBST_ALL_TAC th else fail())) in
   STRIP_TAC THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
     MP_TAC(MATCH_MP memory_rel_Block_IMP
       (CONJ mr gd)))) THEN
   REWRITE_TAC[injectivity "word_loc"; word_index] THEN
   DISCH_THEN(X_CHOOSE_THEN `u:'a word`
     (CONJUNCTS_THEN2 SUBST_ALL_TAC MP_TAC)) THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   ONCE_REWRITE_TAC[GSYM DE_MORGAN_THM] THEN
   UNDISCH_TAC `(v1:(dataSem_v)list) = []` THEN
   DISCH_THEN SUBST_ALL_TAC THEN STRIP_TAC THEN STRIP_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[LENGTH]) THEN
   SUBGOAL_THEN `(v2:(dataSem_v)list) = []` SUBST_ALL_TAC THENL
    [REWRITE_TAC[GSYM LENGTH_EQ_NIL] THEN ASM_REWRITE_TAC[];
     ALL_TAC] THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
     MP_TAC(MATCH_MP memory_rel_Block_IMP
       (CONJ (MATCH_MP memory_rel_tail mr) gd)))) THEN
   REWRITE_TAC[injectivity "word_loc"; word_index] THEN
   DISCH_THEN(X_CHOOSE_THEN `u2:'a word`
     (CONJUNCTS_THEN2 SUBST_ALL_TAC MP_TAC)) THEN
   REWRITE_TAC[] THEN STRIP_TAC THEN subst_vars THEN
   FIRST_ASSUM(fun th -> CONTR_TAC(REWRITE_RULE[] th))));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_simple_eq = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((v1,x1) :: (v2,x2) :: vars) /\
     do_eq refs v1 v2 = Eq_val b /\
     good_dimindex (:'a) ==>
     (?w1 (w2:'a word).
       x1 = wordLang_Word w1 /\ x2 = wordLang_Word w2 /\
       (~(word_bit 0 w1) \/ ~(word_bit 0 w2) ==>
       (w1 = w2) = b))`),
(* the cases of the source: the five shapes of the one value
   against the five of the other, of which the clause of do_eq
   settles twenty-one at once, because they give a type error and
   not a value.  What is left are two values of the same shape.
     Two numbers: the comparison of the source
   (memory_rel_Number_cmp, used on the invariant and on the
   swapped one, so that the word of each of the two is in hand)
   says of each word whether it is the number itself, and then
   the words are the same exactly when the numbers are.
     Two words of sixty-four bits and two references: both roots
   are pointers (memory_rel_Word64_IMP and
   memory_rel_RefPtr_T_IMP after the invariant is shortened with
   memory_rel_tail), so the lowest bit of each of them is set and
   the step of the statement holds of itself; of the clause for
   two references only the arm of two that are not byte arrays is
   left, and there the two are equal exactly when the numbers of
   the references are.
     Two Blocks: the words of them are the roots
   (memory_rel_Block_IMP), and the clause of do_eq splits into
   three.  Two closures have elements, so both roots are pointers
   and the step of the statement is denied.  Otherwise the two
   roots are the same or they are not: the same root is the same
   value (memory_rel_ptr_eq), and two roots that differ have a
   different tag or a different length
   (memory_rel_Block_Block_small_eq, used on the invariant or on
   the swapped one, after which the root whose lowest bit is
   clear goes first), which the arm of the clause denies *)
  ((let grab_asm p asl =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let the_mr asl =
    grab_asm (fun th -> hd_is "memory_rel" (concl th)) asl in
  let the_gd asl =
    grab_asm (fun th -> hd_is "good_dimindex" (concl th)) asl in
  let the_deq asl =
    grab_asm (fun th ->
      is_eq (concl th) &&
      hd_is "dataSem_do_eq" (lhand (concl th))) asl in
  let the_cjeq asl =
    grab_asm (fun th ->
      is_conj (concl th) && is_eq (lhand (concl th)) &&
      is_eq (rand (concl th))) asl in
  let the_bitdisj asl =
    grab_asm (fun th ->
      is_disj (concl th) &&
      hd_is "bit" (rand (lhand (concl th)))) asl in
  (* the two roots both have their lowest bit set, which the step
     of the statement denies; the disjunction has to be refuted by
     hand, because as an assumption it is a rewrite to truth *)
  let kill_disj =
    W(fun (asl,gl) ->
      let dj = the_bitdisj asl in
      let b1 = rand (lhand (concl dj))
      and b2 = rand (rand (concl dj)) in
      let t1 = grab_asm (fun th -> concl th = b1) asl
      and t2 = grab_asm (fun th -> concl th = b2) asl in
      CONTR_TAC (EQ_MP (REWRITE_CONV[EQT_INTRO t1; EQT_INTRO t2]
        (concl dj)) dj)) in
  (* two assumptions that deny each other close any goal *)
  let contra2 =
    W(fun (asl,gl) ->
      tryfind (fun (_,th) ->
        let nth = snd (find (fun (_,t) ->
          concl t = mk_neg (concl th)) asl) in
        CONTR_TAC (EQ_MP (EQF_INTRO nth) th)) asl) in
  (* the tag and the length of the two Blocks are the same, which
     is what the small lemma denies *)
  let sm_contr =
    W(fun (asl,gl) ->
      let c1,c2 = CONJ_PAIR (the_cjeq asl) in
      let sm = snd (find (fun (s,_) -> s = "sm") asl) in
      CONTR_TAC (EQ_MP (REWRITE_CONV[c1; c2] (concl sm)) sm)) in
  (* the two roots, from a lemma that gives each of them: the
     second one after the invariant is shortened *)
  let two_roots lem =
    W(fun (asl,gl) ->
      let mr = the_mr asl in
      let gd = the_gd asl in
      let mr2 = MATCH_MP memory_rel_tail mr in
      MP_TAC (MATCH_MP lem (CONJ mr gd)) THEN
      MP_TAC (MATCH_MP lem (CONJ mr2 gd))) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) in
  (* and then the lowest bit of each of them is set, so the
     implication of the statement holds of itself *)
  let bits_set =
    W(fun (asl,gl) ->
      let cs = conjuncts (snd (strip_exists gl)) in
      let e t = grab_asm (fun th ->
        is_eq (concl th) && lhs (concl th) = t &&
        hd_is "wordLang_Word" (rhs (concl th))) asl in
      MAP_EVERY EXISTS_TAC
        [rand (rhs (concl (e (lhs (el 0 cs)))));
         rand (rhs (concl (e (lhs (el 1 cs)))))]) THEN
    ASM_REWRITE_TAC[] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[word_index]) THEN
    ASM_REWRITE_TAC[REWRITE_RULE[word_index] get_addr_0] in
  (* the five shapes of a value against the five of the other:
     of the twenty-five pairs the clause of do_eq settles all
     but the four of two values of the same shape *)
  let setup =
    STRIP_TAC THEN
    CASES_ON_NAME "v1" THEN CASES_ON_NAME "v2" THEN
    FIRST_ASSUM (fun de ->
      if not (is_eq (concl de)) ||
         not (hd_is "dataSem_do_eq" (lhs (concl de)))
      then fail() else
      ASSUME_TAC (CONV_RULE (TOP_DEPTH_CONV MATCH_CONV)
        (ONCE_REWRITE_RULE[CONJUNCT1 dataSem_do_eq_def] de))) THEN
    TRY (SOLVED (FIRST_ASSUM (fun th ->
      MP_TAC (REWRITE_RULE[distinctness "eq_result"] th)) THEN
      REWRITE_TAC[])) in
  (* two numbers: the comparison of the source gives the words of
     both of them, in both orders *)
  let number_branch_pre =
    FIRST_ASSUM (fun de ->
      if not (is_eq (concl de)) ||
         not (hd_is "Eq_val" (lhs (concl de))) then fail() else
      SUBST_ALL_TAC
        (SYM (REWRITE_RULE[injectivity "eq_result"] de))) THEN
    W(fun (asl,gl) ->
      let mr = the_mr asl in
      let gd = the_gd asl in
      MP_TAC (MATCH_MP memory_rel_Number_cmp
                (CONJ (MATCH_MP memory_rel_swap mr) gd)) THEN
      MP_TAC (MATCH_MP memory_rel_Number_cmp (CONJ mr gd))) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) in
  (* the two instances of the comparison speak of the same two
     words *)
  let unify_words =
    REPEAT (W(fun (asl,gl) ->
      let cs = conjuncts (snd (strip_exists gl)) in
      let xs = [lhs (el 0 cs); lhs (el 1 cs)] in
      tryfind (fun x ->
        let es = filter (fun (_,th) ->
          (try is_eq (concl th) && lhs (concl th) = x &&
               hd_is "wordLang_Word" (rhs (concl th))
           with Failure _ -> false)) asl in
        if length es < 2 then fail() else
        let eq = REWRITE_RULE[injectivity "word_loc"]
                   (TRANS (SYM (snd (el 0 es))) (snd (el 1 es))) in
        if lhs (concl eq) = rhs (concl eq) then fail() else
        SUBST_ALL_TAC eq) xs)) in
  let number_branch =
    number_branch_pre THEN unify_words THEN
    W(fun (asl,gl) ->
      let cs = conjuncts (snd (strip_exists gl)) in
      let e t = grab_asm (fun th ->
        is_eq (concl th) && lhs (concl th) = t &&
        hd_is "wordLang_Word" (rhs (concl th))) asl in
      MAP_EVERY EXISTS_TAC
        [rand (rhs (concl (e (lhs (el 0 cs)))));
         rand (rhs (concl (e (lhs (el 1 cs)))))]) THEN
    ASM_REWRITE_TAC[] THEN
    W(fun (asl,gl) ->
      let ant = lhand gl in
      MAP_EVERY ASM_CASES_TAC
        [rand (lhand ant); rand (rand ant)]) THEN
    ASM_FS_TAC THEN TRY (SOLVED (ASM_MESON_TAC[])) in
  (* two references: of the clause of do_eq only the arm of two
     that are not byte arrays is left, and there both roots are
     pointers *)
  let refptr_branch =
    FIRST_ASSUM (fun de ->
      if not (is_eq (concl de)) ||
         not (hd_is "COND" (lhs (concl de))) then fail() else
      MP_TAC de) THEN
    COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "eq_result"] THEN DISCH_TAC THEN
    FIRST_ASSUM (fun cj ->
      if not (is_conj (concl cj)) then fail() else
      CONJUNCTS_THEN (fun th -> SUBST_ALL_TAC (EQT_INTRO th)) cj) THEN
    two_roots memory_rel_RefPtr_T_IMP THEN bits_set in
  (* two Blocks: the words of both of them are the roots, and the
     clause of do_eq splits into the arm of two closures, the arm
     of a tag and a length that agree, and the arm that gives
     falsity *)
  let blk_pre =
    two_roots memory_rel_Block_IMP THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      let c = concl th in
      if is_eq c && is_var (lhs c) && hd_is "wordLang_Word" (rhs c)
      then SUBST_ALL_TAC th else fail())) THEN
    W(fun (asl,gl) ->
      let cs = conjuncts (snd (strip_exists gl)) in
      MAP_EVERY EXISTS_TAC
        [rand (lhs (el 0 cs)); rand (lhs (el 1 cs))]) THEN
    REWRITE_TAC[] THEN DISCH_TAC THEN
    FIRST_ASSUM (fun de ->
      if not (is_eq (concl de)) ||
         not (hd_is "COND" (lhs (concl de))) then fail() else
      MP_TAC de) THEN
    REPEAT COND_CASES_TAC THEN
    REWRITE_TAC[distinctness "eq_result";
                injectivity "eq_result"] THEN
    TRY (SOLVED ASM_FS_TAC) in
  (* a closure has elements, so its root is a pointer and the
     lowest bit of it is set, which the step of the statement
     denies *)
  let clos_case =
    DISCH_TAC THEN
    FIRST_ASSUM (fun cj ->
      if not (is_conj (concl cj)) then fail() else
      MP_TAC (REWRITE_RULE[dataSem_isClos_def] cj)) THEN
    STRIP_TAC THEN
    W(fun (asl,gl) ->
      let nils = filter (fun (_,th) ->
        (try is_neg (concl th) && is_eq (rand (concl th)) &&
             fst (dest_const (rand (rand (concl th)))) = "NIL"
         with Failure _ -> false)) asl in
      RULE_ASSUM_TRY (REWRITE_RULE (map snd nils))) THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      if is_exists (concl th) then STRIP_ASSUME_TAC th
      else fail())) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[word_index]) THEN
    kill_disj in
  (* two Blocks whose roots differ have a different tag or a
     different length, by the small lemma; the root whose lowest
     bit is clear goes first, so the lemma is used on the
     invariant of the source or on the swapped one *)
  let small_eq_use =
    W(fun (asl,gl) ->
      let mr = the_mr asl in
      let gd = the_gd asl in
      let ne = grab_asm (fun th ->
        is_neg (concl th) && is_eq (rand (concl th)) &&
        hd_is "bit" (concl th) = false &&
        type_of (lhs (rand (concl th))) =
        type_of (rand (rand (concl th)))) asl in
      let dj = grab_asm (fun th -> is_disj (concl th)) asl in
      DISJ_CASES_THEN (fun nb ->
        let same = rand (rand (concl nb)) = lhs (rand (concl ne)) in
        let mr' = if same then mr else MATCH_MP memory_rel_swap mr in
        let ne' = if same then ne else GSYM ne in
        LABEL_TAC "sm" (MATCH_MP memory_rel_Block_Block_small_eq
          (CONJ mr' (CONJ gd (CONJ ne' nb))))) dj) in
  (* and two Blocks whose roots are the same are the same value,
     by the pointer lemma *)
  let blocks_case =
    DISCH_TAC THEN
    W(fun (asl,gl) ->
      let weq = lhs gl in
      ASM_CASES_TAC weq THENL
       [W(fun (asl2,gl2) ->
          ASSUME_TAC (MATCH_MP memory_rel_ptr_eq
            (CONJ (REWRITE_RULE[ASSUME weq] (the_mr asl2))
              (CONJ (the_deq asl2) (the_gd asl2))))) THEN
        ASM_REWRITE_TAC[] THEN TRY (SOLVED contra2);
        ASM_REWRITE_TAC[] THEN
        TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
        small_eq_use THEN sm_contr]) in
  setup THENL
   [number_branch;
    two_roots memory_rel_Word64_IMP THEN bits_set;
    blk_pre THENL [clos_case; blocks_case; blocks_case];
    refptr_branch])));;

let word_header_def = cake_define
  `word_header c st a dm m =
     (match get_real_addr c st a with NONE -> NONE | SOME a1 ->
         (if ~(a1 IN dm) then NONE else
           match m a1 with wordLang_Word x1 -> SOME (a1,x1) | _100
             -> NONE))`;;

let data_to_word_memoryProof_fix_clock_def = cake_define_list
  [`data_to_word_memoryProof_fix_clock ck (l:num) NONE = NONE`;
   `data_to_word_memoryProof_fix_clock ck (l:num) (SOME
  (y,(l1:num),(ck1:num))) =
    (let new_ck = (if ck < ck1 then ck else ck1) in let
        new_l = (if l < l1 then l else l1) in SOME
          (y,new_l,new_ck))`];;
hol4_overload "fix_clock" "data_to_word_memoryProof_fix_clock";;

(* fix_clock_IMP[local] *)
let data_to_word_memoryProof_fix_clock_IMP = prove
 (`!ck l x. fix_clock ck l x = SOME (w,l1,ck1) ==> ck1 <= ck /\ l1 <=
  l`,
  (REPEAT GEN_TAC THEN CASES_ON_NAME "x" THEN
   REWRITE_TAC[data_to_word_memoryProof_fix_clock_def;
               distinctness "option"] THEN
   TRY(CASES_ON_NAME "a" THEN CASES_ON_NAME "y" THEN
       REWRITE_TAC[data_to_word_memoryProof_fix_clock_def]) THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[injectivity "option"; PAIR_EQ] THEN
   REPEAT COND_CASES_TAC THEN REPEAT STRIP_TAC THEN
   ASM_ARITH_TAC));;

let word_is_clos_def = cake_define
  `word_is_clos c h <=>
     (h && (tag_mask c || (n2w 2))) = n2w (16 * closure_tag + 2) \/
     (h && (tag_mask c || (n2w 2))) = n2w (16 * partial_app_tag +
       2)`;;

(* l  corresponds to the functional big-step semantics clock.
      Used to show that equality comparisons respect the
      MustTerminate limit.
   ck is an upper bound on the number of stack frames
      allocated by an equality comparison.
  *)
(* HOL4 data_to_word_memoryProofScript.sml:14020-14025: the tactic
   that proves the termination *)
(* the first pass assumes the termination:
   replacing the CHEAT_TAC is all that is left *)
let word_eq_def = cake_define_try_tac (fun () ->
  `MEASURE (\x. match x with INL (c,st,dm,m,l1,ck1,w1,w2) -> l1 | INR
  (c,st,dm,m,l1,ck1,w,a1,a2) -> l1)`)
  CHEAT_TAC
  `(word_eq c st dm m l ck w1 (w2:'a word) =
      (if w1 = w2 then SOME (((n2w 1):'a word),l,ck) else
      if ~(word_bit 0 w1 /\ word_bit 0 w2) then SOME ((n2w 0),l,ck)
        else
        match (word_header c st w1 dm m,word_header c st w2 dm m)
          with (SOME (a1,h1),SOME (a2,h2)) ->
            (if (h1 && (n2w 0b1100)) = (n2w 0) then
              // is Block
              if word_is_clos c h1 then
                    // isClos
                    SOME ((n2w 1),l,ck) else
              if ~(h1 = h2) then SOME ((n2w 0),l,ck) else
              if l = 0 then
                   // \/ ck = 0
                   NONE else
                word_eq_list c st dm m (l - 1) ck (decode_length c
                  h1)
                  (a1 + bytes_in_word) (a2 + bytes_in_word) else
            if ~(h1 = h2) then SOME ((n2w 0),l,ck) else
            if ~(word_bit 2 h1) then
                     // is array
                     SOME ((n2w 0),l,ck) else
            if ~(word_bit 3 h1) /\ word_bit 4 h1 then
              // is cmp-by-pointer byte array
              SOME ((n2w 0),l,ck) else
             (
              // must be a bignum or word64 or cmp-by-contents byte array
              if l <= w2n (decode_length c h1) then NONE else
              match word_cmp_loop (decode_length c h1)
                (a1 + bytes_in_word * (decode_length c h1))
                (a2 + bytes_in_word * (decode_length c h1)) dm m with
                  NONE -> NONE | SOME res -> SOME (res,l - 1 - w2n
                  (decode_length c h1),ck))) | _101 -> NONE)) /\
   (word_eq_list c st dm m l ck w a1 a2 =
      (if w = ((n2w 0):'a word) then SOME ((n2w 1),l,ck) else
      if ~(a1 IN dm) \/ ~(a2 IN dm) \/ (l = 0) \/ (ck = 0) then NONE
        else
        match (m a1,m a2) with (wordLang_Word w1,wordLang_Word w2) ->
         (match fix_clock (ck - 1) (l - 1) (word_eq c st dm m (l - 1)
           (ck - 1) w1 w2) with NONE -> NONE | SOME (x,l,ck') -> (if ~(x
           = (n2w 1)) then SOME (x,l,ck) else
                             if l = 0 then NONE else
                              word_eq_list c st dm m (l - 1) ck (w -
                                (n2w 1))
                              (a1 + bytes_in_word) (a2 +
                                bytes_in_word))) | _102 -> NONE))`;;

(* HOL4 data_to_word_memoryProofScript.sml:14027: ML code, not ported *)

(* the port's own: the case tree of word_eq, which its two
   theorems about the budget and the clock open in the same way,
   split in the order the definition has it.
   EVERY_CASE_COND_TAC on the whole tree does not come back: the
   conditions of an arm are under a match that is not reduced yet,
   so the splits it makes there are vacuous and it makes them again
   in every branch (PORTING-GUIDE.md entry 74) *)
let a_loc w = find_term (fun t ->
  (try fst (dest_type (type_of t)) = "word_loc"
   with Failure _ -> false) &&
  not (is_var t) && not (is_con_app t)) w;;
let we_rws =
  [distinctness "option"; injectivity "option"; PAIR_EQ;
   distinctness "word_loc"; injectivity "word_loc"];;
let we_tidy =
  REWRITE_TAC we_rws THEN
  RULE_ASSUM_TRY (REWRITE_RULE we_rws) THEN
  TRY (FIRST_ASSUM CONTR_TAC);;
let we_reduce =
  TRY SAFE_MATCH_REDUCE_TAC THEN TRY SAFE_MATCH_REDUCE_ASM_TAC;;
let we_split p =
  TRY (CHANGED_TAC
    (W(fun (asl,w) -> CASES_ON_TAC (p w)) THEN
     we_reduce THEN we_tidy));;
let we_close = TRY (SOLVED (STRIP_TAC THEN ASM_REWRITE_TAC[LE_REFL]));;
let we_step we_close =
  CHANGED_TAC (CASE_SPLIT_TAC THEN we_reduce THEN
               we_tidy THEN we_close);;
let we_tree we_close =
  let we_step = we_step we_close in
  (* the two conditions the comparison starts with *)
  REPEAT COND_CASES_TAC THEN we_tidy THEN we_close THEN
  (* the scrutinees that the patterns of the match look into: the
     headers of the two words and the pair each gives, and the
     inner comparison of two words with its budget and clock.
     CASES_ON_TAC of every variable of a product type instead
     splits the two records of the arguments into their fields,
     which was 88368 steps and no progress *)
  REPEAT we_step THEN
  (* the memory at the two addresses, which is an application of a
     variable and so no scrutinee that scruts_of_goal picks *)
  we_split a_loc THEN we_split a_loc THEN
  we_reduce THEN we_tidy THEN we_close THEN
  REPEAT we_step THEN
  (* the conditions of the arm the two headers left *)
  REPEAT COND_CASES_TAC THEN we_tidy THEN we_close THEN
  REPEAT we_step;;

let word_eq_LESS_EQ = prove
 (`(!c st dm m l ck w1 (w2:'a word) x0 l1 ck1.
        word_eq c st dm m l ck w1 w2 = SOME (x0,l1,ck1) ==> l1 <= l
          /\ ck1 <= ck) /\
     (!c st dm m l ck w a1 (a2:'a word) x0 l1 ck1.
        word_eq_list c st dm m l ck w a1 a2 = SOME (x0,l1,ck1) ==>
          l1 <= l /\ ck1 <= ck)`,
  (* the complete induction on the budget l that the definition
     recurses on (PORTING-GUIDE.md entry 44).  The case tree of the
     definition is opened by the steps above the statement
     (tools/overrides.py), which close a leaf as soon as a split
     settles it: most of them give back the budget and the clock
     they were given, so ASM_REWRITE_TAC[LE_REFL] does it where the
     equations of PAIR_EQ are among the assumptions (entry 43: the
     old round paid ASM_ARITH_TAC per leaf and cost the file tens
     of minutes).  What is left is the leaf that counts down by the
     length it read, the inner comparison of a list -- whose budget
     and clock fix_clock_IMP bounds -- and the recursive call, by
     the hypothesis *)
  ((* the hypothesis of the complete induction on the budget that
     the definition recurses on, at the budget of a recursive
     call: the bound is the first goal *)
  let ih_at which t use (asl,w as gl) =
    let ih = the_asm (fun c -> is_forall c &&
               (try hd_is "<" (lhand (snd (strip_forall c)))
                with Failure _ -> false)) gl in
    let kk = rand (lhand (snd (strip_forall (concl ih)))) in
    (SUBGOAL_THEN (mk_binop `(<):num->num->bool` t kk)
       (fun lt -> use (which (MP (SPEC t ih) lt)))) gl in
  let the_call nm gl =
    the_asm (fun c -> is_eq c && hd_is nm (lhand c) &&
               hd_is "SOME" (rand c)) gl in
  SUBGOAL_THEN
   `!k. (!c st dm m l ck w1 (w2:'a word) x0 l1 ck1.
           l <= k /\ word_eq c st dm m l ck w1 w2 = SOME (x0,l1,ck1)
           ==> l1 <= l /\ ck1 <= ck) /\
        (!c st dm m l ck w a1 (a2:'a word) x0 l1 ck1.
           l <= k /\
           word_eq_list c st dm m l ck w a1 a2 = SOME (x0,l1,ck1)
           ==> l1 <= l /\ ck1 <= ck)`
   (fun th ->
      CONJ_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THENL
       [MP_TAC (CONJUNCT1 (SPEC `l:num` th));
        MP_TAC (CONJUNCT2 (SPEC `l:num` th))] THEN
      ASM_MESON_TAC[LE_REFL]) THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN DISCH_TAC THEN
  CONJ_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* the definition at the arguments, and its case tree *)
  FIRST_X_ASSUM (fun eq ->
    if not (is_eq (concl eq) &&
            (hd_is "word_eq" (lhand (concl eq)) ||
             hd_is "word_eq_list" (lhand (concl eq)))) then fail()
    else MP_TAC (ONCE_REWRITE_RULE[word_eq_def] eq)) THEN
  we_tree we_close THEN
  (* the leaf that counts down by the length it read *)
  TRY (SOLVED (STRIP_TAC THEN ARITH_ASM_TAC)) THEN
  (* the inner comparison of a list, whose budget and clock the
     fix_clock bounds *)
  TRY (FIRST_ASSUM (fun fc ->
    if not (is_eq (concl fc) &&
            hd_is "data_to_word_memoryProof_fix_clock"
              (lhand (concl fc))) then fail()
    else ASSUME_TAC (MATCH_MP
      (GEN_ALL data_to_word_memoryProof_fix_clock_IMP) fc))) THEN
  SPLIT_ASM_TAC THEN
  TRY (SOLVED (STRIP_TAC THEN ARITH_ASM_TAC)) THEN
  TRY (SOLVED ARITH_ASM_TAC) THEN
  (* and the recursive call, by the hypothesis *)
  TRY STRIP_TAC THEN
  W(fun gl ->
    let eq = the_call "word_eq_list" gl in
    let t = el 4 (snd (strip_comb (lhand (concl eq)))) in
    ih_at CONJUNCT2 t
      (fun c2 -> MP_TAC (MATCH_MP c2 (CONJ (SPEC t LE_REFL) eq)))) THEN
  TRY (SOLVED ARITH_ASM_TAC) THEN
  ARITH_ASM_TAC));;

(* [local] *)
let fix_clock_word_eq = prove
 (`fix_clock ck l (word_eq c st dm m l ck w1 w2) = word_eq c st dm m l
  ck w1 w2`,
  (* word_eq gives a clock and a budget that are no larger than the
     ones it was given, so fix_clock leaves its result alone *)
  (let wle = CONJUNCT1 word_eq_LESS_EQ in
   (fun (asl,w as gl) -> CASES_ON_TAC (rand w) gl) THEN
   REWRITE_TAC[data_to_word_memoryProof_fix_clock_def] THEN
   TRY(CASES_ON_NAME "a" THEN CASES_ON_NAME "y" THEN
       REWRITE_TAC[data_to_word_memoryProof_fix_clock_def]) THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[injectivity "option"; PAIR_EQ] THEN
   FIRST_ASSUM(fun th -> MP_TAC(MATCH_MP wle th)) THEN
   ARITH_TAC));;

(* HOL4 data_to_word_memoryProofScript.sml:14055-14056: a theorem
   that HOL4 states as the value of an ML expression: word_eq_def *)

(* HOL4 data_to_word_memoryProofScript.sml:14058-14059: a theorem
   that HOL4 states as the value of an ML expression: word_eq_ind *)

(* [simp] *)
let bit_pattern_1100 = prove
 (`good_dimindex (:'a) ==>
    (((n2w 0b1100) && x1) = (n2w 0) <=> ~(word_bit 2 x1) /\
      ~(word_bit 3 (x1:'a word)))`,
  (* 12 is the two bits 2 and 3, which good_dimindex puts inside
     the word *)
  (let bw12 = prove
    (`!i. bit i (word 12:(N)word) <=>
          (i = 2 \/ i = 3) /\ i < dimindex(:N)`,
     GEN_TAC THEN REWRITE_TAC[BIT_WORD] THEN
     ASM_CASES_TAC `i < 4` THENL
      [FIRST_X_ASSUM(MP_TAC o REWRITE_RULE
         [ARITH_RULE
            `i < 4 <=> i = 0 \/ i = 1 \/ i = 2 \/ i = 3`]) THEN
       DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC) THEN
       CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC TAUT;
       SUBGOAL_THEN `12 DIV 2 EXP i = 0` SUBST1_TAC THENL
        [MATCH_MP_TAC DIV_LT THEN
         MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `2 EXP 4` THEN
         ASM_REWRITE_TAC[LE_EXP] THEN CONV_TAC NUM_REDUCE_CONV THEN
         ASM_ARITH_TAC;
         CONV_TAC NUM_REDUCE_CONV THEN ASM_ARITH_TAC]]) in
   DISCH_TAC THEN
   SUBGOAL_THEN `2 < dimindex (:'a) /\ 3 < dimindex (:'a)`
     STRIP_ASSUME_TAC THENL
    [FIRST_X_ASSUM(MP_TAC o
       REWRITE_RULE[good_dimindex_def]) THEN
     ARITH_TAC; ALL_TAC] THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
               bw12] THEN
   ASM_MESON_TAC[]));;

let word_eq_add_clock = prove
 (`(!c st dm m l ck (a1:'a word) a2 res l' ck1 n.
   word_eq c st dm m l ck a1 a2 = SOME (res,l',ck1) ==>
   (word_eq c st dm m l (ck + n) a1 a2 = SOME (res,l',ck1 + n))) /\
   (!c st dm m l ck w (a1:'a word) a2 res l' ck1 n.
   word_eq_list c st dm m l ck w a1 a2 = SOME (res,l',ck1) ==>
   word_eq_list c st dm m l (ck + n) w a1 a2 = SOME (res,l',ck1 +
     n))`,
  (* the same induction on the budget, but with **one** tree: the
     definition is unfolded in the assumption only, and the goal is
     left folded, so the splits above the statement are the ones of
     the assumption and every condition of the goal's own tree is
     decided by the branch they leave.  Unfolding both sides
     instead splits the two inner comparisons against each other,
     and the branches where the two trees take different arms are
     settled by nothing the goal has.

     In a branch, then: the negated disjunction of the guard taken
     apart (that half of De Morgan only -- a negated conjunction is
     what the goal's tree asks for), the equations between a
     variable and a value used up (VAR_EQ_TAC), the rest oriented
     so that what is rewritten away is the variables of the claim
     and not the zeros and the headers of the goal's tree, the
     budget of the inner comparison bounded by the theorem above,
     and the hypothesis at the inner comparison and at the rest of
     the list.  The goal is then the definition once, with
     fix_clock_word_eq, ADD_EQ_0, the clock of a recursive call as
     this clock minus one plus n, and the values of the branch *)
  ((* the hypothesis of the complete induction on the budget, at the
     budget of a recursive call *)
  let ih_at which t use (asl,w as gl) =
    let ih = the_asm (fun c -> is_forall c &&
               (try hd_is "<" (lhand (snd (strip_forall c)))
                with Failure _ -> false)) gl in
    let kk = rand (lhand (snd (strip_forall (concl ih)))) in
    (SUBGOAL_THEN (mk_binop `(<):num->num->bool` t kk)
       (fun lt -> use (which (MP (SPEC t ih) lt)))) gl in
  let the_call nm gl =
    the_asm (fun c -> is_eq c && hd_is nm (lhand c) &&
               hd_is "SOME" (rand c)) gl in
  (* the clock of a recursive call, as the clock of this one minus
     one plus n *)
  let ckn = prove
   (`~(ck = 0) ==> (ck + n) - 1 = (ck - 1) + n`,
    ARITH_TAC) in
  let use_ckn (asl,w as gl) =
    let nz = the_asm (fun c -> is_neg c && is_eq (rand c) &&
               rand (rand c) = `0`) gl in
    let th = MATCH_MP ckn nz in
    (REWRITE_TAC[th] THEN RULE_ASSUM_TRY (REWRITE_RULE[th])) gl in
  (* the half of De Morgan that takes a negated disjunction apart;
     a negated conjunction is what the goal's own tree asks for
     and stays as it is *)
  let de_morgan_or = GEN_ALL (CONJUNCT2 (SPEC_ALL DE_MORGAN_THM)) in
  SUBGOAL_THEN
   `!k. (!c st dm m l ck (a1:'a word) a2 res l' ck1 n.
           l <= k /\ word_eq c st dm m l ck a1 a2 = SOME (res,l',ck1)
           ==> word_eq c st dm m l (ck + n) a1 a2
                 = SOME (res,l',ck1 + n)) /\
        (!c st dm m l ck w (a1:'a word) a2 res l' ck1 n.
           l <= k /\
           word_eq_list c st dm m l ck w a1 a2 = SOME (res,l',ck1)
           ==> word_eq_list c st dm m l (ck + n) w a1 a2
                 = SOME (res,l',ck1 + n))`
   (fun th ->
      CONJ_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THENL
       [MP_TAC (CONJUNCT1 (SPEC `l:num` th));
        MP_TAC (CONJUNCT2 (SPEC `l:num` th))] THEN
      ASM_MESON_TAC[LE_REFL]) THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN DISCH_TAC THEN
  CONJ_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* the definition at the arguments of the assumption, and its
     case tree.  The goal is left folded, so the splits are the
     ones of the assumption and every condition of the goal's own
     tree is decided by the branch they leave *)
  FIRST_X_ASSUM (fun eq ->
    if not (is_eq (concl eq) &&
            (hd_is "word_eq" (lhand (concl eq)) ||
             hd_is "word_eq_list" (lhand (concl eq)))) then fail()
    else MP_TAC (REWRITE_RULE[fix_clock_word_eq]
                   (ONCE_REWRITE_RULE[word_eq_def] eq))) THEN
  we_tree ALL_TAC THEN
  (* the conditions of the branch, and the leaf of the assumption *)
  (* a negated disjunction taken apart, so that the arithmetic of
     a bound has the conditions it needs; only that half of De
     Morgan, because a negated conjunction is what the goal's own
     tree asks for *)
  RULE_ASSUM_TRY (REWRITE_RULE[de_morgan_or]) THEN
  SPLIT_ASM_TAC THEN
  STRIP_TAC THEN
  SPLIT_ASM_TAC THEN
  (* the equations between a variable and a value, used up *)
  VAR_EQ_TAC THEN
  (* and the rest oriented so that it is the
     variables of the claim that are rewritten away: a leaf that
     says `n2w 0 = res` would otherwise rewrite every zero of the
     goal's own tree into res, and one that says
     `SOME (a,h) = word_header ...` would not reduce the header of
     the goal's own tree at all *)
  RULE_ASSUM_TRY (fun th ->
    let c = concl th in
    if is_eq c &&
       ((not (is_var (lhand c)) && is_var (rand c)) ||
        (is_con_app (lhand c) && not (is_con_app (rand c))))
    then SYM th else fail()) THEN
  (* what the inner comparison left is no larger than what it was
     given (the theorem above), which is what the bound of the
     hypothesis for the rest of the list needs *)
  TRY (FIRST_ASSUM (fun eq ->
    if not (is_eq (concl eq) &&
            hd_is "word_eq" (lhand (concl eq)) &&
            hd_is "SOME" (rand (concl eq))) then fail()
    else ASSUME_TAC (MATCH_MP (CONJUNCT1 word_eq_LESS_EQ) eq))) THEN
  SPLIT_ASM_TAC THEN
  (* what the hypothesis gives of the inner comparison of two
     words, and of the rest of a list *)
  TRY (W(fun gl ->
           let eq = the_call "word_eq" gl in
           let t = el 4 (snd (strip_comb (lhand (concl eq)))) in
           ih_at CONJUNCT1 t
             (fun c1 -> ASSUME_TAC (SPEC_ALL
                (MATCH_MP c1 (CONJ (SPEC t LE_REFL) eq))))) THENL
       [ARITH_ASM_TAC; ALL_TAC]) THEN
  TRY (W(fun gl ->
           let eq = the_call "word_eq_list" gl in
           let t = el 4 (snd (strip_comb (lhand (concl eq)))) in
           ih_at CONJUNCT2 t
             (fun c2 -> ASSUME_TAC (SPEC_ALL
                (MATCH_MP c2 (CONJ (SPEC t LE_REFL) eq))))) THENL
       [ARITH_ASM_TAC; ALL_TAC]) THEN
  (* and the goal, with the branch known: the definition once, the
     clock of the inner call as this clock minus one plus n, and
     the conditions and the values of the branch *)
  GEN_REWRITE_TAC ONCE_DEPTH_CONV [word_eq_def] THEN
  REWRITE_TAC[fix_clock_word_eq; ADD_EQ_0] THEN
  TRY use_ckn THEN
  ASM_REWRITE_TAC[] THEN
  we_reduce THEN
  ASM_REWRITE_TAC[] THEN
  we_tidy THEN
  TRY (SOLVED (ASM_REWRITE_TAC[])) THEN
  TRY (SOLVED ARITH_ASM_TAC)));;

let word_eq_max_clock = prove
 (`(!c st dm m l ck (a1:'a word) a2 res l' ck1 n.
   word_eq c st dm m l ck a1 a2 = SOME (res,l',ck1) ==>
   (word_eq c st dm m l (MAX ck n) a1 a2 = SOME (res,l',ck1 + (n -
     ck)))) /\
   (!c st dm m l ck w (a1:'a word) a2 res l' ck1 n.
   word_eq_list c st dm m l ck w a1 a2 = SOME (res,l',ck1) ==>
   word_eq_list c st dm m l (MAX ck n) w a1 a2 = SOME (res,l',ck1 +
     (n - ck)))`,
  (* the MAX is the clock itself or the clock plus the difference,
     and word_eq_add_clock gives the second *)
  (let step th1 =
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     ASM_CASES_TAC `ck < n:num` THENL
      [SUBGOAL_THEN `MAX ck n = ck + (n - ck)` SUBST1_TAC THENL
        [ASM_ARITH_TAC; ALL_TAC] THEN
       FIRST_ASSUM(fun th -> MATCH_ACCEPT_TAC(MATCH_MP th1 th));
       SUBGOAL_THEN `MAX ck n = ck /\ n - ck = 0`
         (CONJUNCTS_THEN SUBST1_TAC) THENL
        [ASM_ARITH_TAC; ALL_TAC] THEN
       ASM_REWRITE_TAC[ADD_CLAUSES]] in
   CONJ_TAC THENL [step (CONJUNCT1 word_eq_add_clock);
                   step (CONJUNCT2 word_eq_add_clock)]));;

let word_eq_min_max_clock = prove
 (`(!x y. word_eq c st dm m l (MIN a b) a1 a2 = SOME (res,l',ck1) ==>
   (?ck1'. word_eq c st dm m l (MIN (MAX a x) (MAX b y)) a1 a2 = SOME
     (res,l',ck1'))) /\
   (!x y. word_eq_list c st dm m l (MIN a b) w a1 a2 = SOME
     (res,l',ck1) ==>
   (?ck1'. word_eq_list c st dm m l (MIN (MAX a x) (MAX b y)) w a1
     a2 = SOME (res,l',ck1')))`,
  (* the clock of the goal is above the clock of the assumption,
     because each MAX is above its first argument, so the difference
     is what word_eq_add_clock adds *)
  (let step cj =
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     SUBGOAL_THEN `?n. MIN (MAX a x) (MAX b y) = MIN a b + n`
       (CHOOSE_THEN SUBST1_TAC) THENL
      [EXISTS_TAC `MIN (MAX a x) (MAX b y) - MIN a b` THEN
       ARITH_TAC;
       ALL_TAC] THEN
     EXISTS_TAC `ck1 + n` THEN
     FIRST_ASSUM(fun th -> MATCH_ACCEPT_TAC(MATCH_MP cj th)) in
   CONJ_TAC THENL
    [step (CONJUNCT1 word_eq_add_clock);
     step (CONJUNCT2 word_eq_add_clock)]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_isClos = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Block ts1 t1 v1,wordLang_Word
  (w1:'a word)) :: vars) /\
     word_bit 0 w1 /\
     get_real_addr c st w1 = SOME a' /\ m a' = wordLang_Word x' /\
       good_dimindex (:'a) ==>
     (isClos t1 v1 <=> word_is_clos c x')`),
  (* the Block has values, because the lowest bit of its word is
     set, so memory_rel_Block_IMP gives its header and the address
     and the header word are the ones of the goal;
     encode_header_tag_mask reads the tag off the header as sixteen
     times the tag plus two, and both that and the two closure tags
     are below the dimword, where the two numbers are equal exactly
     when the tags are *)
  (
   let n2w_11 = prove
    (`!a b. a < dimword (:N) /\ b < dimword (:N)
        ==> ((n2w a:(N)word) = n2w b <=> a = b)`,
     REPEAT STRIP_TAC THEN
     REWRITE_TAC[GSYM VAL_EQ; VAL_WORD; GSYM dimword] THEN
     ASM_SIMP_TAC[MOD_LT]) in
   let ldi = LESS_DIV_16_IMP in
   STRIP_TAC THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun gd ->
     MP_TAC(MATCH_MP memory_rel_Block_IMP
       (CONJ mr gd)))) THEN
   REWRITE_TAC[injectivity "word_loc"; word_index] THEN
   DISCH_THEN(X_CHOOSE_THEN `u:'a word`
     (CONJUNCTS_THEN2 SUBST_ALL_TAC MP_TAC)) THEN
   COND_CASES_TAC THEN STRIP_TAC THENL
    [FIRST_ASSUM(fun pos -> FIRST_ASSUM(fun neg ->
       CONTR_TAC(MP (NOT_ELIM neg) pos)));
     ALL_TAC] THEN
   (* the address and the header word are the ones of the goal *)
   REPEAT(FIRST_X_ASSUM(fun g2 ->
     FIRST_ASSUM(fun g1 ->
       let th = REWRITE_RULE[g1; injectivity "option";
                             injectivity "word_loc"] g2 in
       if concl th = concl g2 then fail() else SUBST_ALL_TAC th))) THEN
   REWRITE_TAC[word_is_clos_def; dataSem_isClos_def;
               closure_tag_def; partial_app_tag_def] THEN
   FIRST_ASSUM(fun eh -> FIRST_ASSUM(fun gd ->
     MP_TAC(MATCH_MP encode_header_tag_mask
       (CONJ eh gd)))) THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC) THEN
   ASM_REWRITE_TAC[] THEN
   SUBGOAL_THEN `16 * t1 + 2 < dimword (:'a)` ASSUME_TAC THENL
    [FIRST_ASSUM(fun th ->
       MP_TAC(INST [`t1:num`,`n:num`;
                    `dimword (:'a)`,`k:num`] ldi)) THEN
     ASM_ARITH_TAC;
     ALL_TAC] THEN
   SUBGOAL_THEN `16 * 30 + 2 < dimword (:'a) /\
                 16 * 31 + 2 < dimword (:'a)`
     STRIP_ASSUME_TAC THENL
    [REWRITE_TAC[dimword] THEN
     FIRST_ASSUM(DISJ_CASES_THEN SUBST1_TAC o
       REWRITE_RULE[good_dimindex_def]) THEN
     CONV_TAC NUM_REDUCE_CONV;
     ALL_TAC] THEN
   ASM_SIMP_TAC[n2w_11] THEN ARITH_TAC));;

let eq_assum_def = cake_define_list
  [`eq_assum a m dm [] = T`;
   `eq_assum a m dm (v :: vs) <=>
         a IN dm /\ eq_assum (a + bytes_in_word) m dm vs`];;

let eq_explode_def = cake_define_list
  [`eq_explode a m dm [] = []`;
   `eq_explode a m dm (v :: vs) = (v,m a) :: eq_explode (a +
  bytes_in_word) m dm vs`];;

(* [local] *)
let eq_explode_APPEND = prove
 (`!xs ys a.
     eq_explode a m dm (xs ++ ys) =
     eq_explode a m dm xs ++
     eq_explode (a + n2w (LENGTH xs) * bytes_in_word) m dm ys`,
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   ASM_REWRITE_TAC[APPEND; eq_explode_def; LENGTH;
                   WORD_ADD_0_MUL; WORD_ADD_SUC_MUL]));;

(* [local] *)
let eq_assum_APPEND = prove
 (`!xs ys a.
     eq_assum a m dm (xs ++ ys) <=>
     eq_assum a m dm xs /\
     eq_assum (a + n2w (LENGTH xs) * bytes_in_word) m dm ys`,
  (LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   ASM_REWRITE_TAC[APPEND; eq_assum_def; LENGTH;
                   WORD_ADD_0_MUL; WORD_ADD_SUC_MUL; CONJ_ASSOC]));;

(* the port's own: what the explosion of a block needs of TAKE and
   of the offset of an element.  take_nil, take_suc and
   take_too_long are the three clauses of TAKE that the induction
   uses (HOL4 has them as TAKE_def, SNOC_EL_TAKE and
   TAKE_LENGTH_TOO_LONG), and offset_cell is get_real_offset of the
   index as a number: a cell further on is one bytes_in_word
   further on, whichever the word size is *)

let take_nil = prove
 (`!(l:A list). TAKE 0 l = []`,
  LIST_INDUCT_TAC THEN REWRITE_TAC[TAKE]);;

let take_suc = prove
 (`!n (l:A list). n < LENGTH l
    ==> TAKE (SUC n) l = TAKE n l ++ [EL n l]`,
  INDUCT_TAC THEN LIST_INDUCT_TAC THEN
  REWRITE_TAC[LENGTH; ARITH_RULE `~(n < 0)`; LT_SUC; LT_0; TAKE;
              NOT_SUC; SUC_SUB1; EL; HD; TL; APPEND; take_nil] THEN
  ASM_SIMP_TAC[]);;

let take_too_long = prove
 (`!n (l:A list). LENGTH l <= n ==> TAKE n l = l`,
  INDUCT_TAC THEN LIST_INDUCT_TAC THEN
  REWRITE_TAC[TAKE; LENGTH; LE_SUC; NOT_SUC; SUC_SUB1;
              ARITH_RULE `~(SUC n <= 0)`] THEN
  ASM_SIMP_TAC[]);;

let offset_cell = prove
 (`!n. good_dimindex (:'a) ==>
    get_real_offset (Smallnum (&n)) =
    SOME ((bytes_in_word + n2w n * bytes_in_word):'a word)`,
  REWRITE_TAC[get_real_offset_def; smallnum_def; INT_OF_NUM_LT;
              ARITH_RULE `~(n < 0)`; INT_OF_NUM_MUL;
              NUM_OF_INT_OF_NUM; good_dimindex_def] THEN
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM (fun dd ->
    REWRITE_TAC[dd; bytes_in_word_def; shl1_add]) THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[GSYM WORD_MUL; GSYM WORD_ADD] THEN
  REWRITE_TAC[injectivity "option"] THEN AP_TERM_TAC THEN
  ARITH_TAC);;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Block_explode_lemma = prove
 (cake_as_vars (fun () ->
    `!n.
       memory_rel c be ts refs sp st m dm ((Block ts1 t1
         v1,wordLang_Word w1) :: vars) /\
       word_bit 0 w1 /\ get_real_addr c st w1 = SOME a /\
         good_dimindex (:'a) ==>
       memory_rel c be ts refs sp st m dm
         (eq_explode (a + bytes_in_word) m dm (TAKE n v1) ++ (
          (Block ts1 t1 v1,wordLang_Word (w1:'a word)) :: vars)) /\
       eq_assum (a + bytes_in_word) m dm (TAKE n v1)`),
(* the proof of the source is an induction on how much of the block
   is exploded.  At nought nothing is, and the memory_rel is the
   one of the assumptions; one element more is the element of the
   block at that index (memory_rel_Block_MEM, at the memory_rel
   with the block in front of what is exploded so far), whose
   offset is the one of offset_cell and whose word and address are
   the ones of the assumptions.  Both times what is left is the
   same list of pairs in another order, which memory_rel_rearrange
   does *)
  ((* the memory_rel of the assumptions, with the block in front and
     what is exploded so far behind it *)
  let block_first =
    W(fun (asl,w as gl) ->
      let mr = the_asm (fun c ->
                 try hd_is "memory_rel" c &&
                     can lhand (last (snd (strip_comb c)))
                 with Failure _ -> false) gl in
      let lst = last (snd (strip_comb (concl mr))) in
      let ex = lhand lst and rest = rand lst in
      let vs = rand rest in
      let nl = mk_comb (rator rest,
                 mk_comb (mk_comb (rator (rator lst), ex), vs)) in
      SUBGOAL_THEN (mk_comb (rator (concl mr), nl)) ASSUME_TAC THENL
       [MP_TAC mr THEN MATCH_MP_TAC memory_rel_rearrange THEN
        REWRITE_TAC[MEM; MEM_APPEND] THEN MESON_TAC[];
        ALL_TAC]) in
  INDUCT_TAC THEN STRIP_TAC THENL
   [(* nothing of the block is taken *)
    ASM_REWRITE_TAC[take_nil; eq_explode_def; eq_assum_def; APPEND];
    (* one element more, if the block has one *)
    ASM_CASES_TAC `n < LENGTH (v1:dataSem_v list)` THENL
     [FIRST_ASSUM (fun ih ->
        if is_imp (concl ih) then MP_TAC ih else fail()) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      STRIP_TAC THEN
      block_first THEN
      (* the element of the block at that index, and that its
         offset, its word and its address are the ones of the
         assumptions *)
      FIRST_ASSUM (fun mr -> FIRST_ASSUM (fun lt ->
        FIRST_ASSUM (fun gd ->
          STRIP_ASSUME_TAC (MATCH_MP memory_rel_Block_MEM
            (CONJ mr (CONJ lt gd)))))) THEN
      FIRST_ASSUM (fun gd ->
        let oc = MATCH_MP (SPEC_ALL offset_cell) gd in
        FIRST_X_ASSUM (fun go ->
          SUBST_ALL_TAC (REWRITE_RULE[injectivity "option"]
            (TRANS (SYM go) oc)))) THEN
      FIRST_X_ASSUM (fun e ->
        if (try hd_is "wordLang_Word" (lhs (concl e)) &&
                is_var (rand (rand (concl e)))
            with Failure _ -> false)
        then SUBST_ALL_TAC (SYM (REWRITE_RULE[injectivity
               "word_loc"] e))
        else fail()) THEN
      FIRST_ASSUM (fun g1 -> FIRST_X_ASSUM (fun g2 ->
        if concl g1 = concl g2 then fail() else
        SUBST_ALL_TAC (REWRITE_RULE[injectivity "option"]
          (TRANS (SYM g2) g1)))) THEN
      (* and then the two lists are the same one *)
      FIRST_ASSUM (fun lt ->
        ASM_REWRITE_TAC[MATCH_MP take_suc lt; eq_explode_APPEND;
          eq_assum_APPEND; eq_explode_def; eq_assum_def;
          MATCH_MP LENGTH_TAKE (MATCH_MP LT_IMP_LE lt);
          GSYM WORD_ADD_ASSOC; APPEND]) THEN
      FIRST_ASSUM (fun mr ->
        MATCH_MP_TAC (MATCH_MP (ONCE_REWRITE_RULE
          [TAUT `(p ==> q ==> r) <=> (q ==> p ==> r)`]
          memory_rel_rearrange) mr)) THEN
      REWRITE_TAC[MEM; MEM_APPEND] THEN MESON_TAC[];
      (* the block has not: the two takes are the same *)
      SUBGOAL_THEN `TAKE (SUC n) (v1:dataSem_v list) = TAKE n v1`
        (fun e -> REWRITE_TAC[e]) THENL
       [FIRST_ASSUM (fun nl ->
          ASM_SIMP_TAC[take_too_long; MATCH_MP (ARITH_RULE
            `~(n < m) ==> m <= n /\ m <= SUC n`) nl]);
        ALL_TAC] THEN
      FIRST_ASSUM (fun ih ->
        if is_imp (concl ih) then MP_TAC ih else fail()) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Block_explode = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Block ts1 t1 v1,wordLang_Word
  w1) :: vars) /\
      word_bit 0 w1 /\ get_real_addr c st w1 = SOME a /\
        good_dimindex (:'a) ==>
      memory_rel c be ts refs sp st m dm
        (eq_explode (a + (bytes_in_word:'a word)) m dm v1 ++ vars)
          /\
      eq_assum (a + bytes_in_word) m dm v1`),
  (* memory_rel_Block_explode_lemma says it of the first n values of
     the Block, so at the length of the Block it says it of all of
     them; what it gives has the Block itself still in front of the
     rest, which memory_rel_rearrange drops *)
  (let take_all = prove
    (`!l:A list. TAKE (LENGTH l) l = l`,
     LIST_INDUCT_TAC THEN
     REWRITE_TAC[TAKE; LENGTH; NOT_SUC; SUC_SUB1] THEN
     ASM_REWRITE_TAC[]) in
   let rearrange =
     ONCE_REWRITE_RULE [TAUT `(p ==> q ==> r) <=> (q ==> p ==> r)`]
       memory_rel_rearrange in
   STRIP_TAC THEN
   MP_TAC(SPEC `LENGTH (v1:(dataSem_v)list)`
     memory_rel_Block_explode_lemma) THEN
   ASM_REWRITE_TAC[take_all] THEN STRIP_TAC THEN CONJ_TAC THENL
    [FIRST_ASSUM(fun th ->
       MATCH_MP_TAC(MATCH_MP rearrange th) THEN
       REWRITE_TAC[MEM_APPEND; MEM] THEN MESON_TAC[]);
     FIRST_ASSUM ACCEPT_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Loc = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((v1,Loc n k) :: vars) /\
     (!ptr. ~(v1 = RefPtr F ptr)) ==>
     v1 = CodePtr n`),
  (* the word_addr of a root is a Loc only for a Data of a Loc,
     which only a CodePtr stands for: the RefPtr that could is a
     RefPtr F, which the hypothesis excludes *)
  (let noforall = MESON[] `(!p. ~(q /\ (x:num) = p)) <=> ~q` in
   MEMORY_REL_TAC THEN CASES_ON_NAME "v1" THEN
   RULE_ASSUM_TAC(REWRITE_RULE[injectivity "dataSem_v";
                               noforall]) THEN
   V_INV_TAC v_inv_def THEN ASM_REWRITE_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_ByteArray_words_IMP = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,wordLang_Word
  (w:'a word)) :: vars) /\
     lookup p refs = SOME (ByteArray fl vals) /\
     good_dimindex (:'a) /\
     get_real_addr c st w = SOME a ==>
     (?x frame.
       m a = wordLang_Word x /\
       (
        misc_word_list (a + bytes_in_word)
          (MAP wordLang_Word (write_bytes vals (REPLICATE (w2n
            (decode_length c x)) (n2w 0)) be)) * frame) (fun2set (m,dm))
            /\
     w2n (decode_length c x) < dimword (:'a) /\
     w2n (decode_length c x) = LENGTH vals DIV (dimindex (:'a)
       DIV 8) + 1)`),
  (* the words of a byte array, read out of the memory: the
     reference's v_inv gives the pointer, bc_ref_inv (at the
     reference itself, which reaches itself) gives the Bytes
     element of the heap, get_real_addr_get_addr turns the pointer
     into the address, and the word_el of the element is the header
     cell beside the word_list of the bytes.  The length comes off
     the cond of the word_el, where decode_length of the header is
     the length of the list, and the w2n of that is the length
     itself because the cond also bounds it *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let rec facs t =
     if hd_is "STAR" t then
       let args = snd(strip_comb t) in
       facs (el 0 args) @ facs (el 1 args)
     else [t] in
   let rec remove1 t = function
       [] -> []
     | h :: rest -> if h = t then rest else h :: remove1 t rest in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail()) asl in
   let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
   let sepfront names =
     W(fun (asl,w) ->
       let pred = rator (lhand w) in
       let fs = facs pred in
       let picked = map (fun n -> find (hd_is n) fs) names in
       let rest = filter (fun t -> not (mem t picked)) fs in
       let st = fst(strip_comb pred) in
       let mk a b = mk_comb(mk_comb(st,a),b) in
       let target = itlist mk picked (end_itlist mk rest) in
       SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
        [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
   let usesep =
     FIRST_ASSUM(fun th ->
       if (try hd_is "STAR" (rator (concl th))
           with Failure _ -> false)
       then MP_TAC th else fail()) in
   MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN
   TRY(FIRST_ASSUM(fun t1 -> FIRST_ASSUM(fun t2 ->
     CONTR_TAC(REWRITE_RULE[injectivity "option";
                            distinctness "bvlSem_ref"]
                 (TRANS (SYM t1) t2))))) THEN
   FIRST_X_ASSUM(fun th ->
     if is_forall (concl th) &&
        hd_is "bc_ref_inv" (rand (snd(strip_forall(concl th))))
     then MP_TAC(SPEC `p:num` th) else fail()) THEN
   ANTS_TAC THENL
    [CONJ_TAC THENL
      [REWRITE_TAC[reachable_refs_def; MEM] THEN
       EXISTS_TAC `RefPtr bl p:dataSem_v` THEN
       EXISTS_TAC `p:num` THEN
       REWRITE_TAC[get_refs_def; MEM;
                   CONJUNCT1(SPEC_ALL RTC_RULES)];
       ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
   REWRITE_TAC[bc_ref_inv_def] THEN
   ASM_SIMP_TAC[FLOOKUP_DEF] THEN
   MATCH_REDUCE_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   DISCH_TAC THEN
   FIRST_X_ASSUM(fun th ->
     if hd_is "heap_in_memory_store" (concl th)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
     else fail()) THEN
   STRIP_TAC THEN
   W(fun (asl,w) ->
     let hl = grab asl is_hl in
     let hlen = grab asl (fun th ->
       hd_is "heap_length" (lhand (concl th))) in
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
     let gd = grab asl (fun th -> concl th = `good_dimindex (:'a)`) in
     let ga = grab asl (fun th -> hd_is "get_addr" (lhs (concl th))) in
     let gr = grab asl (fun th ->
       hd_is "get_real_addr" (lhs (concl th))) in
     let th = CONJUNCT2(SPEC (rand (lhs (concl ga)))
       (GEN `w:('a)word_loc`
         (MATCH_MP get_real_addr_get_addr
           (CONJ hlen (CONJ hl (CONJ cu gd)))))) in
     let eq = REWRITE_RULE[injectivity "option"]
                (TRANS (SYM gr) (REWRITE_RULE[ga] th)) in
     let r = rhs (concl eq) in
     let args = snd(strip_comb (rand r)) in
     let mul = fst(strip_comb (rand r)) in
     let swap = mk_comb(rator r,
                  mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
     SUBST_ALL_TAC(TRANS eq (WORD_RULE (mk_eq(r,swap))))) THEN
   W(fun (asl,w) ->
     MP_TAC(MATCH_MP heap_lookup_SPLIT
              (grab asl is_hl))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   VAR_EQ_TAC THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "fmap_apply" (lhs (concl th))
         with Failure _ -> false)
     then SUBST_ALL_TAC th else fail()) THEN
   FIRST_X_ASSUM(fun th ->
     if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
     then MP_TAC th else fail()) THEN
   REWRITE_TAC[word_heap_APPEND; word_heap_def;
               bytes_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_el_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_payload_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[word_list_def; LENGTH_MAP;
               LENGTH_write_bytes; LENGTH_REPLICATE] THEN
   sepfront ["cond"] THEN
   REWRITE_TAC[cond_STAR] THEN
   DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC) THEN
   sepfront ["set_sep_one"] THEN
   DISCH_THEN(fun sep ->
     let rd = MATCH_MP read_fun2set sep in
     EXISTS_TAC (rand (rhs (concl (CONJUNCT1 rd)))) THEN
     ASSUME_TAC sep THEN STRIP_ASSUME_TAC rd) THEN
   W(fun (asl,w) ->
     let sep = grab asl (fun th -> hd_is "STAR" (rator (concl th))) in
     let fs = facs (rator (concl sep)) in
     let wl = find (hd_is "misc_word_list") fs in
     let rest = remove1 wl fs in
     let st = fst(strip_comb (rator (concl sep))) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     EXISTS_TAC (end_itlist mk rest)) THEN
   FIRST_ASSUM(fun dl ->
     if (try hd_is "decode_length" (lhs (concl dl))
         with Failure _ -> false)
     then REWRITE_TAC[dl] else fail()) THEN
   REWRITE_TAC[VAL_WORD; GSYM dimword] THEN
   SUBGOAL_THEN
     `(LENGTH (vals:(word8)list) DIV (dimindex (:'a) DIV 8) + 1)
        MOD dimword (:'a) =
      LENGTH vals DIV (dimindex (:'a) DIV 8) + 1`
     SUBST1_TAC THENL
    [MATCH_MP_TAC MOD_LT THEN
     TRANS_TAC LTE_TRANS `2 EXP (dimindex (:'a) - 4)` THEN
     ASM_REWRITE_TAC[dimword] THEN
     SIMP_TAC[LE_EXP; ARITH] THEN ARITH_TAC;
     ALL_TAC] THEN
   ASM_REWRITE_TAC[] THEN
   REPEAT CONJ_TAC THENL
    [usesep THEN REWRITE_TAC[STAR_AC];
     TRANS_TAC LTE_TRANS `2 EXP (dimindex (:'a) - 4)` THEN
     ASM_REWRITE_TAC[dimword] THEN
     SIMP_TAC[LE_EXP; ARITH] THEN ARITH_TAC]));;

let poly_inj_lemma = prove
 (`(a:num) < b /\ a' < b /\ a + b * c = a' + b * c' ==> a = a' /\ c =
  c'`,
  (* the remainder of the division by b gives a and a', and what is
     left of the equation then cancels b *)
  (STRIP_TAC THEN
   SUBGOAL_THEN `(a:num) = a'` ASSUME_TAC THENL
    [SUBGOAL_THEN
       `((a:num) + b * c) MOD b = (a' + b * c') MOD b` MP_TAC THENL
      [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     ONCE_REWRITE_TAC[ADD_SYM] THEN ONCE_REWRITE_TAC[MULT_SYM] THEN
     REWRITE_TAC[MOD_MULT_ADD] THEN ASM_SIMP_TAC[MOD_LT];
     ALL_TAC] THEN
   ASM_REWRITE_TAC[] THEN
   UNDISCH_TAC `(a:num) + b * c = a' + b * c'` THEN
   ASM_REWRITE_TAC[EQ_ADD_LCANCEL; EQ_MULT_LCANCEL] THEN
   ARITH_ASM_TAC));;

let mw2n_inj = prove
 (`!x y. LENGTH x = LENGTH y ==> (mw2n (x:('a word) list) = mw2n y <=>
  x = y)`,
  (* the value of a multiword is its first word plus the dimword
     times the value of the rest, and a word is below the dimword,
     so poly_inj_lemma takes the sum apart *)
  (let pil = GEN_ALL poly_inj_lemma in
   let wlt = prove
    (`!(x:(N)word). w2n x < dimword (:N)`,
     REWRITE_TAC[dimword; VAL_BOUND]) in
   LIST_INDUCT_TAC THEN GEN_TAC THEN
   STRUCT_CASES_TAC(ISPEC `y:('a word)list` list_CASES_v) THEN
   REWRITE_TAC[LENGTH; mw2n_def; CONS_11; NOT_CONS_NIL;
               ARITH_RULE `(0 = SUC n) <=> F`;
               ARITH_RULE `(SUC n = 0) <=> F`; SUC_INJ] THEN
   DISCH_TAC THEN EQ_TAC THENL
    [DISCH_TAC THEN
     FIRST_ASSUM(fun eq ->
       MP_TAC(MATCH_MP pil (CONJ (ISPEC `h:'a word` wlt)
         (CONJ (ISPEC `v:'a word` wlt) eq)))) THEN
     DISCH_THEN(CONJUNCTS_THEN ASSUME_TAC) THEN
     CONJ_TAC THENL
      [ASM_MESON_TAC[VAL_EQ];
       FIRST_X_ASSUM(fun ih ->
         MP_TAC(SPEC `vs:('a word)list` ih)) THEN
       ASM_REWRITE_TAC[]];
     DISCH_THEN(CONJUNCTS_THEN SUBST1_TAC) THEN REWRITE_TAC[]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let write_bytes_inj = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) ==>
     (!ws bs1 bs2.
       LENGTH bs1 = LENGTH bs2 /\
       LENGTH bs1 <= LENGTH ws * (dimindex (:'a) DIV 8) /\
       LENGTH ws <= LENGTH bs1 DIV (dimindex (:'a) DIV 8) + 1 ==>
       (write_bytes bs1 (ws:('a word) list) be = write_bytes bs2
         ws be <=> bs1 = bs2))`),
  (* the induction of the source over the list of words.  The source
     takes the bytes of a word off the list one at a time and reads
     each of them with get_byte; here get_byte_bytes_to_word says it
     of every byte of the first word at once (gbd), so the bytes
     before the first word's worth are the same, the induction
     hypothesis says it of the bytes after them, and LIST_EQ puts
     the two halves together *)
  (let gbd = prove
    (`!zs i (t:'a word) be'.
        good_dimindex (:'a) /\ i < LENGTH zs /\
        i < dimindex (:'a) DIV 8
        ==> get_byte (n2w i)
              (bytes_to_word (dimindex (:'a) DIV 8) (n2w 0) zs t be')
              be' = EL i zs`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     FIRST_ASSUM (fun gd ->
       DISJ_CASES_THEN (fun eq ->
         let n = if dest_small_numeral (rand (concl eq)) = 32
                 then 2 else 3 in
         let th = CONV_RULE NUM_REDUCE_CONV
                    (GEN_ALL (INST [mk_small_numeral n,`k:num`]
                       get_byte_bytes_to_word)) in
         RULE_ASSUM_TAC(REWRITE_RULE[eq]) THEN
         RULE_ASSUM_TAC(CONV_RULE NUM_REDUCE_CONV) THEN
         REWRITE_TAC[eq] THEN CONV_TAC NUM_REDUCE_CONV THEN
         MATCH_MP_TAC th THEN
         REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
         REWRITE_TAC[eq] THEN CONV_TAC NUM_REDUCE_CONV)
         (REWRITE_RULE[good_dimindex_def] gd))) in
   (* the bytes in a word, as the goal and the assumptions have it *)
   let kof (asl,w) =
     find_term (fun t -> hd_is "DIV" t && hd_is "dimindex" (lhand t))
       (list_mk_conj (w :: map (concl o snd) asl)) in
   let nil_of t = mk_list([], hd (snd (dest_type (type_of t)))) in
   DISCH_TAC THEN
   (* a word holds at least one byte *)
   W(fun (asl,w) ->
     SUBGOAL_THEN (mk_binop `(<):num->num->bool` `0` (kof (asl,w)))
       ASSUME_TAC THENL
      [FIRST_ASSUM MP_TAC THEN REWRITE_TAC[good_dimindex_def] THEN
       DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
       CONV_TAC NUM_REDUCE_CONV;
       ALL_TAC]) THEN
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[write_bytes_def; LENGTH; MULT_CLAUSES] THENL
    [(* no word at all, so there is no byte either *)
     STRIP_TAC THEN REWRITE_TAC[] THEN
     W(fun (asl,w) ->
       MAP_EVERY (fun b ->
         SUBGOAL_THEN (mk_eq (b, nil_of b)) SUBST_ALL_TAC THENL
          [REWRITE_TAC[GSYM LENGTH_EQ_NIL] THEN ASM_ARITH_TAC;
           ALL_TAC])
         [lhs w; rhs w]) THEN
     REWRITE_TAC[];
     ALL_TAC] THEN
   CONV_TAC(DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[CONS_11] THEN
   STRIP_TAC THEN
   EQ_TAC THENL
    [ALL_TAC;
     DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[]] THEN
   STRIP_TAC THEN
   (* the bytes after the first word are the same *)
   W(fun (asl,w) ->
     let k = kof (asl,w) in
     let b1 = lhs w and b2 = rhs w in
     SUBGOAL_THEN (mk_eq (list_mk_icomb "DROP" [k; b1],
                          list_mk_icomb "DROP" [k; b2]))
       ASSUME_TAC THENL
      [ASM_CASES_TAC (mk_binop `(<=):num->num->bool` k
                        (list_mk_icomb "LENGTH" [b1])) THENL
        [(* by the induction hypothesis, for the rest of the words *)
         FIRST_X_ASSUM (fun ih ->
           MP_TAC (SPECL [list_mk_icomb "DROP" [k; b1];
                          list_mk_icomb "DROP" [k; b2]] ih)) THEN
         REWRITE_TAC[LENGTH_DROP] THEN
         ANTS_TAC THENL
          [REPEAT CONJ_TAC THEN
           TRY (W(fun (asl,w) ->
             let dv = find_term (fun t -> hd_is "DIV" t &&
                        not (hd_is "dimindex" (lhand t))) w in
             MP_TAC (SPECL [lhand (lhand dv); rand dv]
                       DIV_SUB_STEP)) THEN
             ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
             DISCH_THEN SUBST1_TAC) THEN
           ASM_ARITH_TAC;
           ALL_TAC] THEN
         DISCH_THEN (fun iff -> REWRITE_TAC[GSYM iff]) THEN
         FIRST_ASSUM ACCEPT_TAC;
         (* or there is no byte after the first word *)
         W(fun (asl,w) ->
           MAP_EVERY (fun d ->
             SUBGOAL_THEN (mk_eq (d, nil_of d)) SUBST1_TAC THENL
              [REWRITE_TAC[DROP_NIL] THEN ASM_ARITH_TAC; ALL_TAC])
             [lhs w; rhs w]) THEN
         REWRITE_TAC[]];
       ALL_TAC]) THEN
   (* and then every byte of the two is the same *)
   ONCE_REWRITE_TAC[LIST_EQ] THEN
   CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
   X_GEN_TAC `i:num` THEN DISCH_TAC THEN
   W(fun (asl,w) ->
     ASM_CASES_TAC (mk_binop `(<):num->num->bool` `i:num`
                      (kof (asl,w)))) THENL
    [(* a byte of the first word, which the two words agree on *)
     FIRST_ASSUM (fun he ->
       if not (is_eq (concl he) &&
               hd_is "bytes_to_word" (lhs (concl he))) then fail()
       else
       let a1 = snd (strip_comb (lhs (concl he))) in
       let a2 = snd (strip_comb (rhs (concl he))) in
       MP_TAC (SPECL [el 2 a1; `i:num`; el 3 a1; el 4 a1] gbd) THEN
       MP_TAC (SPECL [el 2 a2; `i:num`; el 3 a2; el 4 a2] gbd)) THEN
     ASM_REWRITE_TAC[] THEN
     DISCH_THEN (SUBST1_TAC o SYM) THEN
     DISCH_THEN (SUBST1_TAC o SYM) THEN
     ASM_REWRITE_TAC[];
     (* or a byte after it, where the two rests agree *)
     W(fun (asl,w) ->
       let k = kof (asl,w) in
       let b1 = rand (lhs w) and b2 = rand (rhs w) in
       let d = mk_binop `(-):num->num->num` `i:num` k in
       MP_TAC (ISPECL [b1; d; k] EL_DROP) THEN
       MP_TAC (ISPECL [b2; d; k] EL_DROP)) THEN
     ASM_SIMP_TAC[ARITH_RULE
       `~(i < k) /\ i < n ==> (i - k) + k < n`] THEN
     ASM_SIMP_TAC[ARITH_RULE `~(i < k) ==> (i - k) + k = i`] THEN
     DISCH_THEN (SUBST1_TAC o SYM) THEN
     DISCH_THEN (SUBST1_TAC o SYM) THEN
     ASM_REWRITE_TAC[]]));;

(* [local] *)
let MIN_ADD = prove
 (`MIN a b + c = MIN (a + c) (b + c)`,
  (ARITH_TAC));;

(* [local] *)
let MIN_SUB = prove
 (`MIN a b - c = MIN (a - c) (b - c)`,
  (ARITH_TAC));;

(* [local] *)
let MAX_ADD = prove
 (`MAX a b + c = MAX (a + c) (b + c)`,
  (ARITH_TAC));;

(* [local] *)
let MAX_SUB = prove
 (`MAX a b - c = MAX (a - c) (b - c)`,
  (ARITH_TAC));;

let do_eq_IFF_vb_eq_size = prove
 (`(!(refs:('a bvlSem_ref) spt) v1 v2 b.
      do_eq refs v1 v2 = Eq_val b <=>
        (?n. vb_eq_size refs v1 v2 = SOME (n,b))) /\
   (!(refs:('a bvlSem_ref) spt) v1 v2 b.
      do_eq_list refs v1 v2 = Eq_val b <=>
        (?n. vb_eq_size_list refs v1 v2 = SOME (n,b)))`,
  (* the complete induction on the size of the value again
     (PORTING-GUIDE.md entry 44), with what a value of the two
     functions can be above the statement.  Of two values the
     two definitions are reduced together: their conditions are
     the same conditions, so one split decides both, and of two
     Blocks with the same tag what is left is the hypothesis at
     their payloads.  Of two lists the hypothesis at the two
     elements, at each flag, decides both matches -- a
     combination it rules out closes its branch -- and the
     hypothesis at the two rests is the goal they leave *)
  (let meas l = mk_binop `(+):num->num->num`
      (list_mk_icomb "SUM" [list_mk_icomb "MAP" [`vb_size`; l]])
      (list_mk_icomb "LENGTH" [l]) in
  (* the hypothesis of the complete induction, at a measure: what
     it says of the sub-term is used as the step of the goal or
     put among the assumptions, and the bound is the first goal *)
  let ih_tac which t use (asl,w as gl) =
    let ih = the_asm (fun c -> is_forall c &&
               (try hd_is "<" (lhand (snd (strip_forall c)))
                with Failure _ -> false)) gl in
    let kk = rand (lhand (snd (strip_forall (concl ih)))) in
    (SUBGOAL_THEN (mk_binop `(<):num->num->bool` t kk)
       (fun lt -> use (which (MP (SPEC t ih) lt)))) gl in
  let tidy = [distinctness "eq_result"; injectivity "eq_result";
              distinctness "option"; injectivity "option";
              PAIR_EQ; UNWIND_THM1; UNWIND_THM2] in
  SUBGOAL_THEN
   `!k. (!(refs:('a bvlSem_ref) spt) v1 v2 b.
           vb_size v1 <= k
           ==> (do_eq refs v1 v2 = Eq_val b <=>
                (?n. vb_eq_size refs v1 v2 = SOME (n,b)))) /\
        (!(refs:('a bvlSem_ref) spt) v1 v2 b.
           SUM (MAP vb_size v1) + LENGTH v1 <= k
           ==> (do_eq_list refs v1 v2 = Eq_val b <=>
                (?n. vb_eq_size_list refs v1 v2 = SOME (n,b))))`
   (fun th ->
      CONJ_TAC THEN REPEAT GEN_TAC THENL
       [MATCH_MP_TAC (CONJUNCT1 (SPEC `vb_size (v1:dataSem_v)` th));
        MATCH_MP_TAC (CONJUNCT2 (SPEC
          `SUM (MAP vb_size (v1:dataSem_v list)) +
           LENGTH (v1:dataSem_v list)` th))] THEN
      REWRITE_TAC[LE_REFL]) THEN
  MATCH_MP_TAC num_WF THEN GEN_TAC THEN DISCH_TAC THEN
  CONJ_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THENL
   [(* two values, by their constructors *)
    CASES_ON_TAC `v1:dataSem_v` THEN CASES_ON_TAC `v2:dataSem_v` THEN
    ONCE_REWRITE_TAC[dataSem_do_eq_def; vb_eq_size_def] THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REPEAT COND_CASES_TAC THEN
    RULE_ASSUM_TRY (REWRITE_RULE tidy) THEN
    TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
    REWRITE_TAC tidy THEN
    (* where neither is a Block, and where the two tags decided *)
    TRY (SOLVED (ASM_REWRITE_TAC tidy)) THEN
    (* of two Blocks with the same tag: their payloads, by the
       hypothesis *)
    TRY (SOLVED
      (RULE_ASSUM_TRY (REWRITE_RULE[vb_size_Block]) THEN
       REWRITE_TAC[exists_option_map_pair] THEN
       W(fun (asl,w) ->
         let l1 = el 1 (snd (strip_comb (lhand (lhand w)))) in
         ih_tac CONJUNCT2 (meas l1) MATCH_MP_TAC) THENL
        [ARITH_ASM_TAC; REWRITE_TAC[LE_REFL]])) THEN
    (* of two pointers: whatever the two lookups are *)
    EVERY_CASE_TAC THEN
    RULE_ASSUM_TRY (REWRITE_RULE tidy) THEN
    TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
    ASM_REWRITE_TAC tidy;
    (* two lists, by their shape *)
    CASES_ON_TAC `v1:dataSem_v list` THEN
    CASES_ON_TAC `v2:dataSem_v list` THEN
    ONCE_REWRITE_TAC[dataSem_do_eq_def; vb_eq_size_def] THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC tidy THEN
    (* where one of the two is empty *)
    TRY (SOLVED (ASM_REWRITE_TAC tidy)) THEN
    (* and of two lists with an element each: what the hypothesis
       says of the two elements decides both matches, and what it
       says of the two rests is the goal they leave *)
    RULE_ASSUM_TRY (REWRITE_RULE[MAP; LENGTH; vb_sum_clauses]) THEN
    W(fun (asl,w) ->
      let args = snd (strip_comb
                   (find_term (hd_is "vb_eq_size") w)) in
      ih_tac CONJUNCT1 (list_mk_icomb "vb_size" [el 1 args])
        (fun c1 ->
           let i = REWRITE_RULE[LE_REFL] (SPECL args c1) in
           MAP_EVERY ASSUME_TAC [SPEC `T` i; SPEC `F` i])) THENL
     [ARITH_ASM_TAC; ALL_TAC] THEN
    W(fun (asl,w) ->
      let args = snd (strip_comb
                   (find_term (hd_is "vb_eq_size_list") w)) in
      ih_tac CONJUNCT2 (meas (el 1 args))
        (fun c2 -> ASSUME_TAC
           (REWRITE_RULE[LE_REFL] (SPECL args c2)))) THENL
     [ARITH_ASM_TAC; ALL_TAC] THEN
    EVERY_CASE_TAC THEN
    RULE_ASSUM_TRY (REWRITE_RULE tidy) THEN
    TRY (SOLVED (FIRST_ASSUM CONTR_TAC)) THEN
    TRY (SOLVED (ASM_REWRITE_TAC tidy)) THEN
    (* and where the element has no value at all: of neither
       flag is its comparison a value *)
    W(fun gl -> BOOL_CASES_TAC (var_by_name "b" gl)) THEN
    ASM_REWRITE_TAC tidy]));;

let do_eq_IMP_vb_eq_size = prove
 (`do_eq refs v1 v2 = Eq_val b ==>
     (?n. vb_eq_size refs v1 v2 = SOME (n,b))`,
  (REWRITE_TAC[CONJUNCT1 do_eq_IFF_vb_eq_size]));;

let vb_eq_size_IMP_do_eq = prove
 (`vb_eq_size refs v1 v2 = SOME (n,b) ==>
   do_eq refs v1 v2 = Eq_val b`,
  (REWRITE_TAC[CONJUNCT1 do_eq_IFF_vb_eq_size] THEN MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_ptr_vb_eq = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((v1,x1) :: (v2,(x1:'a
  word_loc)) :: vars) /\
     vb_eq_size refs v1 v2 = SOME (n,b) /\
     good_dimindex (:'a) ==> b`),
  (* a vb_eq_size that gives b is a do_eq that gives Eq_val b *)
  (STRIP_TAC THEN
   FIRST_ASSUM(fun th ->
     MP_TAC(MATCH_MP vb_eq_size_IMP_do_eq th)) THEN
   DISCH_TAC THEN
   MATCH_MP_TAC memory_rel_ptr_eq THEN
   ASM_MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_eq_thm0 = prove
 (cake_as_vars (fun () ->
    `(!refs v1 v2 l ck b w1 w2 n.
          memory_rel c be ts refs sp st m dm
             ((v1,wordLang_Word w1) :: (v2,(wordLang_Word w2:'a
               word_loc)) :: vars) /\
          vb_eq_size refs v1 v2 = SOME (n,b) /\
          ck = MIN (vs_depth v1) (vs_depth v2) /\
          n * dimword (:'a) < l /\
          good_dimindex (:'a) ==>
          (?res l1 ck1. word_eq c st dm m l ck w1 w2 = SOME
            (res,l1,ck1) /\
                   (b <=> (res = (n2w 1))) /\
                   l <= l1 + n * dimword (:'a))) /\
       (!refs v1 v2 l ck b w1 w2 t1 t2 n.
          memory_rel c be ts refs sp st m dm
             (eq_explode w1 m dm v1 ++ eq_explode w2 m dm v2 ++
               vars) /\
          LENGTH v2 = LENGTH v1 /\ LENGTH v1 < dimword (:'a) /\
          eq_assum w1 m dm v1 /\ eq_assum w2 m dm v2 /\
          vb_eq_size_list refs v1 v2 = SOME (n,b) /\
          ck = MIN (vs_depth_list v1) (vs_depth_list v2) /\
          n * dimword (:'a) < l /\
          good_dimindex (:'a) ==>
          (?res l1 ck1. word_eq_list c st dm m l ck (n2w (LENGTH
            v1)) w1 w2 = SOME (res,l1,ck1) /\
                   (b <=> (res = (n2w 1))) /\
                   l <= l1 + n * dimword (:'a)))`),
  (* the attempt: the proof of the source names
     memory_rel_Number_cmp, memory_rel_swap, word_header_def,
     small_int_def, memory_rel_any_Number_IMP,
     memory_rel_Number_bignum_IMP_ALT.  What is here rewrites with
     them and closes by arithmetic, and the cheat is behind it until
     the proof is written.  A MESON over them is what the next round
     adds; it costs a load ten minutes to have it in every attempt
     and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_Number_cmp; memory_rel_swap;
       word_header_def; small_int_def; memory_rel_any_Number_IMP;
       memory_rel_Number_bignum_IMP_ALT] THEN
     TRY ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_eq_thm = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((v1,wordLang_Word w1) :: (v2,(wordLang_Word w2:'a
          word_loc)) :: vars) /\
      do_eq refs v1 v2 = Eq_val b /\ good_dimindex (:'a) ==>
      (?res l1 ck1.
         word_eq c st dm m (MustTerminate_limit (:'a) - 1)
           (MIN (vs_depth v1) (vs_depth v2)) w1 w2 = SOME
             (res,l1,ck1) /\
         (b <=> (res = (n2w 1))))`),
  (* do_eq gives the size of the comparison, memory_rel_limit bounds
     it by the clock of MustTerminate (and the dimword is at least
     one, so the bound by the limit less one holds as well), and
     word_eq_thm0 is the comparison itself *)
  (STRIP_TAC THEN
   FIRST_ASSUM(fun de ->
     MP_TAC(MATCH_MP do_eq_IMP_vb_eq_size de)) THEN
   DISCH_THEN(X_CHOOSE_THEN `nn:num` ASSUME_TAC) THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun vb -> FIRST_ASSUM(fun gd ->
     ASSUME_TAC(MATCH_MP (SPEC_ALL memory_rel_limit)
       (CONJ mr (CONJ vb gd)))))) THEN
   SUBGOAL_THEN `1 <= dimword (:'a)` ASSUME_TAC THENL
    [REWRITE_TAC[dimword; ARITH_RULE `1 <= n <=> ~(n = 0)`;
                 EXP_EQ_0; ARITH_EQ];
     ALL_TAC] THEN
   SUBGOAL_THEN
     `nn * dimword (:'a) < MustTerminate_limit (:'a) - 1`
     ASSUME_TAC THENL
    [ASM_ARITH_TAC; ALL_TAC] THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun vb -> FIRST_ASSUM(fun lt ->
     FIRST_ASSUM(fun gd ->
       let ck = REFL `MIN (vs_depth v1) (vs_depth v2)` in
       let th = MATCH_MP (CONJUNCT1 word_eq_thm0)
                  (CONJ mr (CONJ vb (CONJ ck (CONJ lt gd)))) in
       MP_TAC th)))) THEN
   STRIP_TAC THEN ASM_EXISTS_TAC THEN ASM_REWRITE_TAC[]));;

let word_mem_eq_def = cake_define_list
  [`word_mem_eq a [] dm m = SOME T`;
   `word_mem_eq a (x :: xs) dm m =
         (if ~(a IN dm) then NONE else
         if ~(isWord (m a)) then NONE else
         if ~(m a = wordLang_Word x) then SOME F else
           word_mem_eq (a + bytes_in_word) xs dm m)`];;

(* [local] *)
let word_mem_eq_thm = prove
 (`!xs ys a ff.
    (misc_word_list a (MAP wordLang_Word xs) * ff) (fun2set (m,dm))
      /\
    LENGTH xs = LENGTH ys ==>
    word_mem_eq a ys dm m = SOME (xs = ys)`,
  (* the memory holds the words of the list, so the loop reads them
     one at a time: the cell at the address is the head, which
     read_fun2set takes out of the separating product, and the
     induction hypothesis takes the cell into the frame *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let rec facs t =
     if hd_is "STAR" t then
       let args = snd(strip_comb t) in
       facs (el 0 args) @ facs (el 1 args)
     else [t] in
   let sepasm (asl,w) =
     tryfind (fun (_,th) ->
       let c = concl th in
       if hd_is "STAR" (rator c) then rator c else fail()) asl in
   let witness = W(fun gl ->
     let ante = sepasm gl in
     let fs = facs ante in
     let one = find (hd_is "set_sep_one") fs in
     let rest = filter (fun t -> not (hd_is "set_sep_one" t) &&
                                 not (hd_is "misc_word_list" t)) fs in
     let st = fst(strip_comb ante) in
     let mk a b = mk_comb(mk_comb(st,a),b) in
     EXISTS_TAC (mk one (end_itlist mk rest))) in
   let usesep =
     FIRST_ASSUM(fun th ->
       if hd_is "STAR" (rator (concl th)) then MP_TAC th else fail()) in
   LIST_INDUCT_TAC THEN GEN_TAC THEN CASES_BY_NAME "ys" THEN
   REWRITE_TAC[word_mem_eq_def; LENGTH; MAP; NOT_CONS_NIL;
               NOT_SUC; GSYM NOT_SUC; SUC_INJ; CONS_11] THEN
   REPEAT GEN_TAC THEN
   REWRITE_TAC[word_list_def; GSYM STAR_ASSOC] THEN
   STRIP_TAC THEN
   FIRST_ASSUM(fun th -> MP_TAC(MATCH_MP read_fun2set th)) THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
   ASM_REWRITE_TAC[isWord_def; injectivity "word_loc"] THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   RULE_ASSUM_TAC(REWRITE_RULE[]) THEN VAR_EQ_TAC THEN
   REWRITE_TAC[] THEN
   FIRST_X_ASSUM MATCH_MP_TAC THEN witness THEN
   ASM_REWRITE_TAC[] THEN usesep THEN REWRITE_TAC[STAR_AC]));;

let bignum_words_def = cake_define
  `bignum_words c i =
     (let (sign,payload) = i2mw i in
       match encode_header c (if sign then 7 else 3) (LENGTH
         payload) with NONE -> NONE | SOME h -> SOME (h :: payload))`;;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_const_test = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i,wordLang_Word (w:'a
  word)) :: vars) /\
      good_dimindex (:'a) ==>
      (if small_int (:'a) j then
        (Smallnum j = w <=> i = j) else
        match bignum_words c j with NONE -> ~(i = j) | SOME words
          ->
          (if ~(word_bit 0 w) then ~(i = j) else
            ?a. get_real_addr c st w = SOME a /\
                word_mem_eq a words dm m = SOME (i = j)))`),
  (* the attempt: the proof of the source names
     memory_rel_any_Number_IMP, IMP_memory_rel_Number,
     memory_rel_Number_EQ, small_int_def, bignum_words_def,
     i2mw_def.  What is here rewrites with them and closes by
     arithmetic, and the cheat is behind it until the proof is
     written.  A MESON over them is what the next round adds; it
     costs a load ten minutes to have it in every attempt and it
     closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_any_Number_IMP;
       IMP_memory_rel_Number; memory_rel_Number_EQ;
       small_int_def; bignum_words_def; i2mw_def] THEN
     TRY ASM_ARITH_TAC)));;

(* the port's own: that the two halves of a 64-bit value, or the
   whole of it, decide the value.  HOL4 gets this from BITS_THM and
   DIVISION; here it is the bits of the two words, with the index
   of the upper half shifted by thirty-two *)

let extract64_eq = prove
 (`!(i:word64) j. dimindex (:'a) = 32 ==>
    ((((63 >< 32) i):'a word = (63 >< 32) j) /\
     (((31 >< 0) i):'a word = (31 >< 0) j) <=> i = j)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[word_extract; WORD_EQ_BITS_ALT; BIT_WORD_SUBWORD;
               DIMINDEX_64] THEN
  ASM_REWRITE_TAC[MIN; ADD_CLAUSES] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[TAUT
     `(p ==> (p /\ a <=> p /\ b)) <=> (p ==> (a <=> b))`] THEN
  EQ_TAC THENL
    [DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "hi")
       (LABEL_TAC "lo")) THEN
     X_GEN_TAC `k:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `k < 32` THENL
      [USE_THEN "lo" (fun lo -> ASM_SIMP_TAC[lo]);
       SUBGOAL_THEN `32 + (k - 32) = k /\ k - 32 < 32`
         STRIP_ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
       USE_THEN "hi" (fun hi ->
         FIRST_ASSUM (fun e ->
           MP_TAC (ONCE_REWRITE_RULE[e] (SPEC `k - 32` hi)))) THEN
       ASM_REWRITE_TAC[]];
     DISCH_THEN (LABEL_TAC "all") THEN CONJ_TAC THEN
     X_GEN_TAC `k:num` THEN DISCH_TAC THENL
      [USE_THEN "all" (fun a -> MP_TAC (SPEC `32 + k` a)) THEN
       ASM_SIMP_TAC[ARITH_RULE `k < 32 ==> 32 + k < 64`];
       USE_THEN "all" (fun a -> MP_TAC (SPEC `k:num` a)) THEN
       ASM_SIMP_TAC[ARITH_RULE `k < 32 ==> k < 64`]]]);;

let extract64_full = prove
 (`!(i:word64) j. dimindex (:'a) = 64 ==>
    ((((63 >< 0) i):'a word = (63 >< 0) j) <=> i = j)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[word_extract; WORD_EQ_BITS_ALT; BIT_WORD_SUBWORD;
               DIMINDEX_64] THEN
  ASM_REWRITE_TAC[MIN; ADD_CLAUSES] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[TAUT
     `(p ==> (p /\ a <=> p /\ b)) <=> (p ==> (a <=> b))`]);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Word64_const_test = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Word64 i,v) :: vars) /\
     good_dimindex (:'a) ==>
       (?(w:'a word) a words h.
         v = wordLang_Word w /\ get_real_addr c st w = SOME a /\
         word_mem_eq (a + bytes_in_word) words dm m = SOME (i = j)
           /\
         encode_header c 3 (LENGTH words) = SOME (h:'a word) /\
         (if dimindex (:'a) < 64 then
           words = [(63 >< 32) j; (31 >< 0) j] else
           words = [(63 >< 0) j]))`),
(* the proof of the source is the template of
   memory_rel_ValueArray_IMP at a Word64Rep, as memory_rel_Word64_IMP
   is, and what it adds is the comparison: word_mem_eq reads the one
   or two cells of the value and compares them with the halves of
   the constant, and extract64_eq and extract64_full above say that
   those decide the value.  The header the statement asks for is the
   one the cond of the payload says encode_header gives *)
  (let hd_is n t =
    (try fst(dest_const(fst(strip_comb t))) = n
     with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail()) asl in
  let is_hl th = hd_is "heap_lookup" (lhs (concl th)) in
  let sepfront names =
    W(fun (asl,w) ->
      let pred = rator (lhand w) in
      let fs = facs pred in
      let picked = map (fun n -> find (hd_is n) fs) names in
      let rest = filter (fun t -> not (mem t picked)) fs in
      let st = fst(strip_comb pred) in
      let mk a b = mk_comb(mk_comb(st,a),b) in
      let target = itlist mk picked (end_itlist mk rest) in
      SUBGOAL_THEN (mk_eq(pred,target)) SUBST1_TAC THENL
       [REWRITE_TAC[STAR_AC]; ALL_TAC]) in
  MEMORY_REL_TAC THEN V_INV_TAC v_inv_def THEN
  FIRST_ASSUM(fun e ->
    let c = concl e in
    if is_eq c && is_var (rand c) && hd_is "wordLang_Word" (lhs c)
    then SUBST1_TAC (SYM e) else fail()) THEN
  REWRITE_TAC[injectivity "word_loc"] THEN
  CONV_TAC(REDEPTH_CONV UNWIND_CONV) THEN
  FIRST_X_ASSUM(fun th ->
    if hd_is "heap_in_memory_store" (concl th)
    then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] th)
    else fail()) THEN
  STRIP_TAC THEN
  W(fun (asl,w) ->
    MP_TAC(MATCH_MP heap_lookup_SPLIT (grab asl is_hl))) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  VAR_EQ_TAC THEN
   W(fun (asl,w) ->
     let hl = grab asl is_hl in
     let hlen = grab asl (fun th ->
       hd_is "heap_length" (lhand (concl th))) in
     let cu = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const(rand(lhs(concl th)))) = "CurrHeap") in
     let gd = grab asl (fun th -> concl th = `good_dimindex (:'a)`) in
     let gat = tryfind (fun t ->
       find_term (fun u ->
         hd_is "get_addr" u && length (snd(strip_comb u)) = 3) t)
       (w :: map (fun (_,th) -> concl th) asl) in
     let th = SPEC (last (snd(strip_comb gat)))
       (GEN `w:('a)word_loc`
         (MATCH_MP get_real_addr_get_addr
           (CONJ hlen (CONJ hl (CONJ cu gd))))) in
     let r = rhs (concl (CONJUNCT1 th)) in
     let a = rand r in
     let args = snd(strip_comb (rand a)) in
     let mul = fst(strip_comb (rand a)) in
     let swap = mk_comb(rator a,
                  mk_comb(mk_comb(mul,el 1 args),el 0 args)) in
     let sw = WORD_RULE (mk_eq(a,swap)) in
     EXISTS_TAC swap THEN
     STRIP_ASSUME_TAC(REWRITE_RULE[sw] th)) THEN
  ASM_CASES_TAC `dimindex (:'a) < 64` THEN
  ASM_REWRITE_TAC[] THEN
  W(fun (asl,gw) ->
    EXISTS_TAC (rand (last (conjuncts (snd (strip_exists gw)))))) THEN
  FIRST_X_ASSUM(fun th ->
    if (try hd_is "STAR" (rator (concl th)) with Failure _ -> false)
    then MP_TAC th else fail()) THEN
  REWRITE_TAC[word_heap_APPEND; word_heap_def; Word64Rep_def] THEN
  ASM_REWRITE_TAC[] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_el_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_payload_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[word_list_def; LENGTH_MAP] THEN
  sepfront ["cond"] THEN
  REWRITE_TAC[cond_STAR] THEN
  DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC MP_TAC) THEN
  DISCH_THEN (fun sep ->
    let p = rator (concl sep) in
    let fs = facs p in
    let st = fst (strip_comb p) in
    let mk a b = mk_comb (mk_comb (st, a), b) in
    let front cell =
      let rest = filter (fun t -> not (t = cell)) fs in
      let target = mk cell (end_itlist mk rest) in
      let eq = prove (mk_eq (p, target), REWRITE_TAC[STAR_AC]) in
      MATCH_MP read_fun2set (REWRITE_RULE[eq] sep) in
    let rds = map front (filter (hd_is "set_sep_one") fs) in
    EXISTS_TAC (rand (rhs (concl (CONJUNCT1 (hd rds))))) THEN
    MAP_EVERY STRIP_ASSUME_TAC rds) THEN
  (* what the header encodes, out of the cond of the payload *)
  W(fun gl ->
    let is = the_asm (hd_is "IS_SOME") gl in
    let eh = rand (concl is) in
    let mh = rand (rhs (concl (the_asm (fun c ->
               try is_eq c && hd_is "wordLang_Word" (rand c) &&
                   hd_is "make_header" (rand (rand c))
               with Failure _ -> false) gl))) in
    SUBGOAL_THEN (mk_eq (eh, mk_icomb (`SOME`, mh)))
      (fun e -> REWRITE_TAC[LENGTH] THEN
                CONV_TAC NUM_REDUCE_CONV THEN
                ASM_REWRITE_TAC[e]) THENL
     [MP_TAC is THEN REWRITE_TAC[encode_header_def] THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[IS_SOME];
      ALL_TAC]) THEN
  (* and the comparison of the cells, byte by byte *)
  REWRITE_TAC[word_mem_eq_def] THEN
  ASM_REWRITE_TAC[isWord_def; shl1_add; WORD_ADD_ASSOC] THEN
  TRY SAFE_MATCH_REDUCE_TAC THEN
  REWRITE_TAC[injectivity "word_loc"] THEN
  FIRST
   [(SUBGOAL_THEN `dimindex (:'a) = 32` ASSUME_TAC THENL
      [W(fun gl ->
         let gd = the_asm (fun c ->
                    c = `good_dimindex (:'a)`) gl in
         let lt = the_asm (fun c ->
                    try is_binop `(<):num->num->bool` c &&
                        rand c = `64`
                    with Failure _ -> false) gl in
         MP_TAC (REWRITE_RULE[good_dimindex_def] gd) THEN
         MP_TAC lt) THEN
       ARITH_TAC;
       ALL_TAC] THEN
     W(fun (asl,gw as gl) ->
       let ij = rand (rand gw) in
       let d = the_asm (fun c -> c = `dimindex (:'a) = 32`) gl in
       MP_TAC (MATCH_MP
         (ISPECL [lhand ij; rand ij] extract64_eq) d)) THEN
     DISCH_THEN (fun ee ->
       REPEAT COND_CASES_TAC THEN
       ASM_REWRITE_TAC[injectivity "option"; GSYM ee]));
    (SUBGOAL_THEN `dimindex (:'a) = 64` ASSUME_TAC THENL
      [W(fun gl ->
         let gd = the_asm (fun c ->
                    c = `good_dimindex (:'a)`) gl in
         let lt = the_asm (fun c ->
                    try is_neg c &&
                        is_binop `(<):num->num->bool` (rand c) &&
                        rand (rand c) = `64`
                    with Failure _ -> false) gl in
         MP_TAC (REWRITE_RULE[good_dimindex_def] gd) THEN
         MP_TAC lt) THEN
       ARITH_TAC;
       ALL_TAC] THEN
     W(fun (asl,gw as gl) ->
       let ij = rand (rand gw) in
       let d = the_asm (fun c -> c = `dimindex (:'a) = 64`) gl in
       MP_TAC (MATCH_MP
         (ISPECL [lhand ij; rand ij] extract64_full) d)) THEN
     DISCH_THEN (fun ee ->
       REPEAT COND_CASES_TAC THEN
       ASM_REWRITE_TAC[injectivity "option"; GSYM ee]))]));;

(* [local] *)
let or_seven_eq = prove
 (`~((w << k) = (v << k)) /\ 2 < k ==> ~(((w << k) || (n2w 7)) = ((v
  << k) || (n2w 7)))`,
  (* seven has no bit above the second, and the shift by more than
     two has none below the third, so the bit where the shifts
     differ is a bit where the ors differ *)
  (let odd_div = prove
    (`!k m i. k < 2 EXP m /\ m <= i
              ==> (ODD (k DIV 2 EXP i) <=> F)`,
     REPEAT STRIP_TAC THEN
     SUBGOAL_THEN `k DIV 2 EXP i = 0` SUBST1_TAC THENL
      [MATCH_MP_TAC DIV_LT THEN
       TRANS_TAC LTE_TRANS `2 EXP m` THEN
       ASM_REWRITE_TAC[LE_EXP] THEN ARITH_TAC;
       REWRITE_TAC[ODD]]) in
   let bit7 = prove
    (`!i. 3 <= i ==> (word_bit i (n2w 7:(N)word) <=> F)`,
     REPEAT STRIP_TAC THEN REWRITE_TAC[BIT_WORD] THEN
     MP_TAC(SPECL [`7`; `3`; `i:num`] odd_div) THEN
     ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th])) in
   MATCH_MP_TAC(TAUT `(q ==> b ==> a) ==> (~a /\ q ==> ~b)`) THEN
   DISCH_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_OR; BIT_WORD_SHL] THEN
   REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM(MP_TAC o SPEC `i:num`) THEN
   ASM_REWRITE_TAC[] THEN
   ASM_CASES_TAC `3 <= i` THENL
    [ASM_SIMP_TAC[bit7];
     ASM_SIMP_TAC[ARITH_RULE `~(3 <= i) /\ 2 < k ==> ~(k <= i)`]]));;

let make_byte_header_eq = prove
 (`byte_len (:'a) m < 2 EXP data_to_word_config_len_size c /\
   byte_len (:'a) m < 2 EXP (dimindex (:'a) - 4) /\
   byte_len (:'a) n < 2 EXP data_to_word_config_len_size c /\
   byte_len (:'a) n < 2 EXP (dimindex (:'a) - 4) /\
   good_dimindex (:'a) /\
   2 < dimindex (:'a) - (if dimindex (:'a) = 32 then 2 else 3) -
     data_to_word_config_len_size c ==>
   (make_byte_header c T m = (make_byte_header c T n:'a word) <=> m
     = n)`,
  (* the header of a byte array keeps the length in the field above
     the shift, so two of them agree only when their lengths do: the
     tag is below the shift and the length plus the word size is
     below two to the width of the field, because the byte length is
     below two to the length size *)
  (let hi = prove
    (`!n r (i:num). n < 2 EXP r /\ r <= i
        ==> ~(bit i ((n2w n):'a word))`,
     MATCH_ACCEPT_TAC BIT_WORD_HI) in
   let b7 = prove
    (`!j. j < dimindex (:'a)
          ==> (bit j ((n2w 7):'a word) <=> j < 3)`,
     GEN_TAC THEN DISCH_TAC THEN
     ASM_CASES_TAC `(j:num) < 3` THEN ASM_REWRITE_TAC[] THENL
      [FIRST_ASSUM(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC o MATCH_MP
         (ARITH_RULE `(j:num) < 3 ==> j = 0 \/ j = 1 \/ j = 2`)) THEN
       ASM_REWRITE_TAC[BIT_WORD] THEN CONV_TAC NUM_REDUCE_CONV THEN
       ASM_ARITH_TAC;
       MP_TAC(ISPECL [`7`; `3`; `j:num`] hi) THEN
       ASM_SIMP_TAC[ARITH_RULE `~((j:num) < 3) ==> 3 <= j`] THEN
       CONV_TAC NUM_REDUCE_CONV]) in
   let n2w_inj = prove
    (`!a b m. a < 2 EXP m /\ b < 2 EXP m /\ m <= dimindex (:'a) /\
              ((n2w a):'a word = n2w b)
        ==> a = b`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     FIRST_X_ASSUM(MP_TAC o AP_TERM `val:'a word->num`) THEN
     REWRITE_TAC[VAL_WORD] THEN
     SUBGOAL_THEN
       `a < 2 EXP dimindex (:'a) /\ b < 2 EXP dimindex (:'a)`
       STRIP_ASSUME_TAC THENL
      [CONJ_TAC THEN TRANS_TAC LTE_TRANS `2 EXP m` THEN
       ASM_SIMP_TAC[LE_EXP; ARITH];
       ASM_SIMP_TAC[MOD_LT]]) in
   let gen = prove
    (`!(s:num) a m n.
        3 <= s /\ s < dimindex (:'a) /\
        m + a < 2 EXP (dimindex (:'a) - s) /\
        n + a < 2 EXP (dimindex (:'a) - s) /\
        ((((n2w (m + a)):'a word) << s || n2w 7) =
         (((n2w (n + a)):'a word) << s || n2w 7))
        ==> m = n`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     SUBGOAL_THEN `!j. bit j ((n2w 7):'a word) ==> j < s`
       ASSUME_TAC THENL
      [X_GEN_TAC `j:num` THEN
       ASM_CASES_TAC `j < dimindex (:'a)` THENL
        [ASM_SIMP_TAC[b7] THEN ASM_ARITH_TAC;
         ASM_SIMP_TAC[BIT_TRIVIAL;
                      ARITH_RULE `~((a:num) < b) ==> b <= a`]];
       ALL_TAC] THEN
     SUBGOAL_THEN
       `(!j. bit j ((n2w (m + a)):'a word) ==> j + s < dimindex (:'a))
        /\
        (!j. bit j ((n2w (n + a)):'a word) ==> j + s < dimindex (:'a))`
       STRIP_ASSUME_TAC THENL
      [CONJ_TAC THEN X_GEN_TAC `j:num` THEN
       ASM_CASES_TAC `j + s < dimindex (:'a)` THEN
       ASM_REWRITE_TAC[] THENL
        [MP_TAC(ISPECL [`m + a:num`; `dimindex (:'a) - s`; `j:num`] hi);
         MP_TAC(ISPECL [`n + a:num`; `dimindex (:'a) - s`;
                        `j:num`] hi)] THEN
       ASM_SIMP_TAC[ARITH_RULE
         `~(j + s < d) /\ s < d ==> d - s <= j`] THEN
       REWRITE_TAC[];
       ALL_TAC] THEN
     SUBGOAL_THEN `m + a = n + a` MP_TAC THENL
      [MATCH_MP_TAC n2w_inj THEN
       EXISTS_TAC `dimindex (:'a) - s` THEN
       ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
        [ARITH_TAC; ALL_TAC] THEN
       FIRST_X_ASSUM(fun th -> MP_TAC(AP_TERM
         `\w:'a word. word_ushr w s` th)) THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       ASM_SIMP_TAC[USHR_OR_LOW; USHR_SHL_CANCEL];
       ARITH_TAC]) in
   let usedim =
     FIRST_X_ASSUM(fun dd ->
       let c = concl dd in
       if is_eq c &&
          (try fst(dest_const(fst(strip_comb(lhs c)))) = "dimindex"
           with Failure _ -> false)
       then RULE_ASSUM_TAC(REWRITE_RULE[dd; byte_len_def]) THEN
            ASSUME_TAC dd
       else fail()) in
   STRIP_TAC THEN EQ_TAC THENL
    [ALL_TAC; DISCH_THEN SUBST1_TAC THEN REFL_TAC] THEN
   FIRST_ASSUM(DISJ_CASES_THEN ASSUME_TAC o
     REWRITE_RULE[good_dimindex_def]) THEN
   usedim THEN
   REWRITE_TAC[make_byte_header_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
   DISCH_TAC THEN MATCH_MP_TAC gen THENL
    [MAP_EVERY EXISTS_TAC
       [`30 - data_to_word_config_len_size c`; `4`] THEN
     SUBGOAL_THEN
       `dimindex (:'a) - (30 - data_to_word_config_len_size c) =
        data_to_word_config_len_size c + 2`
       SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[EXP_ADD] THEN CONV_TAC NUM_REDUCE_CONV THEN
     REPEAT CONJ_TAC THEN TRY ASM_ARITH_TAC THEN
     MP_TAC(SPEC `m:num` (MATCH_MP DIVISION (ARITH_RULE `~(4 = 0)`)))
     THEN
     MP_TAC(SPEC `n:num` (MATCH_MP DIVISION (ARITH_RULE `~(4 = 0)`)))
     THEN ASM_ARITH_TAC;
     MAP_EVERY EXISTS_TAC
       [`61 - data_to_word_config_len_size c`; `8`] THEN
     SUBGOAL_THEN
       `dimindex (:'a) - (61 - data_to_word_config_len_size c) =
        data_to_word_config_len_size c + 3`
       SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[EXP_ADD] THEN CONV_TAC NUM_REDUCE_CONV THEN
     REPEAT CONJ_TAC THEN TRY ASM_ARITH_TAC THEN
     MP_TAC(SPEC `m:num` (MATCH_MP DIVISION (ARITH_RULE `~(8 = 0)`)))
     THEN
     MP_TAC(SPEC `n:num` (MATCH_MP DIVISION (ARITH_RULE `~(8 = 0)`)))
     THEN ASM_ARITH_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_String_const_test = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl i,v) :: vars) /\
     lookup i refs = SOME (ByteArray T other) /\
     good_dimindex (:'a) ==>
     (let t = implode (MAP (CHR o w2n) other) in
       (part_to_words c LN (closLang_Str s) ((n2w 0):'a word) =
         NONE ==> ~(s = t)) /\
       (!x res.
         part_to_words c LN (closLang_Str s) (n2w 0) = SOME (x,res)
           ==>
         (?(w:'a word) a.
           v = wordLang_Word w /\ get_real_addr c st w = SOME a /\
           word_mem_eq a (MAP (get_Word o SND) res) dm m = SOME
             (s = t))))`),
  (* the attempt: the proof of the source names
     memory_rel_ByteArray_IMP, part_to_words_def, good_dimindex_def,
     byte_len_def, make_byte_header_def, memory_rel_def.  What is
     here rewrites with them and closes by arithmetic, and the cheat
     is behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_ByteArray_IMP; part_to_words_def;
       good_dimindex_def; byte_len_def; make_byte_header_def;
       memory_rel_def] THEN
     TRY ASM_ARITH_TAC)));;

(* [local] *)
let word_1_and_eq_0 = prove
 (`(((n2w 1) && w) = (n2w 0)) <=> ~(word_bit 0 w)`,
  (REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
               BIT_WORD_1] THEN
   MESON_TAC[DIMINDEX_GE_1; ARITH_RULE `1 <= n ==> 0 < n`]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_Number_single_mul = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
        ((Number i1,wordLang_Word (w1:'a word)) :: (Number
          i2,wordLang_Word w2) :: vars) /\
      good_dimindex (:'a) ==>
        (let (lw,hw) = single_mul w1 (w2 >>> 1) (n2w 0) in
          (hw || ((w1 || w2) && (n2w 1))) = (n2w 0) ==>
          memory_rel c be ts refs sp st m dm ((Number (i1 *
            i2),wordLang_Word (lw >>> 1)) :: vars))`),
  (* the attempt: the proof of the source names word_or_eq_0,
     memory_rel_swap, memory_rel_Number_const_test, small_int_def,
     good_dimindex_def, single_mul_def.  What is here rewrites with
     them and closes by arithmetic, and the cheat is behind it until
     the proof is written.  A MESON over them is what the next round
     adds; it costs a load ten minutes to have it in every attempt
     and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[word_or_eq_0; memory_rel_swap;
       memory_rel_Number_const_test; small_int_def;
       good_dimindex_def; single_mul_def] THEN
     TRY ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_bounds_check = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((Number i1,wordLang_Word (w1:'a
  word)) :: vars) /\
      small_int (:'a) (&n) /\ good_dimindex (:'a) ==>
      (word_ror w1 2 <+ n2w n <=> (&0) <= i1 /\ i1 < &n) /\
      (word_ror w1 2 <=+ n2w n <=> (&0) <= i1 /\ i1 <= &n)`),
  (* the attempt: the proof of the source names
     memory_rel_any_Number_IMP, dimword, small_int_def,
     good_dimindex_def, word_index, memory_rel_Number_IMP.  What is
     here rewrites with them and closes by arithmetic, and the cheat
     is behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_any_Number_IMP; dimword;
       small_int_def; good_dimindex_def; word_index;
       memory_rel_Number_IMP] THEN
     TRY ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_ByteArray_IMP_store = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p,wordLang_Word
  (w:'a word)) :: vars) /\
      lookup p refs = SOME (ByteArray fl vals) /\ good_dimindex
        (:'a) /\
      get_real_addr c st w = SOME a /\ i < LENGTH vals ==>
      (?m1. mem_store_byte_aux m dm be (a + bytes_in_word + n2w i)
        b = SOME m1 /\
           memory_rel c be ts (insert p (ByteArray fl (LUPDATE b i
             vals)) refs) sp st m1 dm
             ((RefPtr bl p,wordLang_Word (w:'a word)) :: vars))`),
  (* a byte of a byte array can be stored: memory_rel_ByteArray_IMP
     says that the load of that byte works, which tells that the
     cell the store writes holds a word and is in the domain, and
     it says that the memory relation survives the write.  Those
     two are about the address of the lemma's own existential, and
     the statement's is the same because get_real_addr is a
     function *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
   (* what a load of a byte says about the cell it reads: it holds a
      word and its address is in the domain *)
   let loadword = prove
    (`!(m:('a)word->('a)word_loc) dm be' w x.
        mem_load_byte_aux m dm be' w = SOME x
        ==> (?v. m (byte_align w) = wordLang_Word v) /\
            byte_align w IN dm`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[mem_load_byte_aux_def] THEN
     STRUCT_CASES_TAC(ISPEC `(m:('a)word->('a)word_loc) (byte_align w)`
                        (cases_of `:('a)word_loc`)) THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[distinctness "option"] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[distinctness "option"] THEN
     MESON_TAC[]) in
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   FIRST_ASSUM(fun mr -> FIRST_ASSUM(fun lk -> FIRST_ASSUM(fun gd ->
     MP_TAC(MATCH_MP memory_rel_ByteArray_IMP
              (CONJ mr (CONJ lk gd)))))) THEN
   DISCH_THEN(STRIP_ASSUME_TAC o
              REWRITE_RULE[injectivity "word_loc"]) THEN
   VAR_EQ_TAC THEN
   FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
     let e = REWRITE_RULE[injectivity "option"] (TRANS (SYM e1) e2) in
     if is_var (lhs (concl e)) && lhs (concl e) <> rhs (concl e)
     then SUBST_ALL_TAC e else fail())) THEN
   FIRST_X_ASSUM(fun ld ->
     if is_forall (concl ld) &&
        (try hd_is "mem_load_byte_aux"
               (lhs (rand (snd(strip_forall (concl ld)))))
         with Failure _ -> false)
     then MP_TAC(SPEC `i:num` ld) else fail()) THEN
   ASM_REWRITE_TAC[] THEN
   DISCH_THEN(fun le -> STRIP_ASSUME_TAC(MATCH_MP loadword le)) THEN
   FIRST_X_ASSUM(fun st ->
     if is_forall (concl st) &&
        (try hd_is "memory_rel"
               (snd(dest_let(rand(snd(strip_forall (concl st))))))
         with Failure _ -> false)
     then MP_TAC(SPECL [`i:num`; `b:(word8)`] st) else fail()) THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_REWRITE_TAC[theWord_def] THEN
   DISCH_TAC THEN
   ASM_REWRITE_TAC[mem_store_byte_aux_def] THEN
   MATCH_REDUCE_TAC THEN
   ASM_REWRITE_TAC[injectivity "option"; UNWIND_THM1; UNWIND_THM2]));;

(* copy forward *)

(* HOL4 data_to_word_memoryProofScript.sml:15324-15329: the tactic
   that proves the termination *)
let word_copy_fwd_def = cake_define_try_tac (fun () ->
  `MEASURE (w2n o FST o SND)`)
  TERM_TAC
  `word_copy_fwd be' (n:'a word) a b (m:'a word->'a word_loc) dm =
     (if dimword (:'a) <= 4 then NONE else
     if n <+ (n2w 4) then
       if n <+ (n2w 2) then
         if n = (n2w 0) then SOME m else
           OPTION_BIND (mem_load_byte_aux m dm be' a)
                       (\w. mem_store_byte_aux m dm be' b w) else
         OPTION_BIND (mem_load_byte_aux m dm be' a) (\w1.
         OPTION_BIND (mem_load_byte_aux m dm be' (a + (n2w 1))) (\w2.
           if n = (n2w 2) then
             OPTION_BIND (mem_store_byte_aux m dm be' b w1) (\m.
             OPTION_BIND (mem_store_byte_aux m dm be' (b + (n2w 1))
               w2) (\m. SOME m)) else
             OPTION_BIND (mem_load_byte_aux m dm be' (a + (n2w 2)))
               (\w3.
             OPTION_BIND (mem_store_byte_aux m dm be' b w1) (\m.
             OPTION_BIND (mem_store_byte_aux m dm be' (b + (n2w 1))
               w2) (\m.
             OPTION_BIND (mem_store_byte_aux m dm be' (b + (n2w 2))
               w3) (\m. SOME m)))))) else
       OPTION_BIND (mem_load_byte_aux m dm be' a) (\w1.
       OPTION_BIND (mem_load_byte_aux m dm be' (a + (n2w 1))) (\w2.
       OPTION_BIND (mem_load_byte_aux m dm be' (a + (n2w 2))) (\w3.
       OPTION_BIND (mem_load_byte_aux m dm be' (a + (n2w 3))) (\w4.
       OPTION_BIND (mem_store_byte_aux m dm be' b w1) (\m.
       OPTION_BIND (mem_store_byte_aux m dm be' (b + (n2w 1)) w2)
         (\m.
       OPTION_BIND (mem_store_byte_aux m dm be' (b + (n2w 2)) w3)
         (\m.
       OPTION_BIND (mem_store_byte_aux m dm be' (b + (n2w 3)) w4)
         (\m.
         word_copy_fwd be' (n - (n2w 4)) (a + (n2w 4)) (b + (n2w
           4)) m dm)))))))))`;;

let list_copy_fwd_def = cake_define
  `list_copy_fwd n xp xs yp ys =
     (if xp + n <= LENGTH xs /\ yp + n <= LENGTH ys then
       if n = 0 then SOME ys else
       if n = 1 then SOME (LUPDATE (EL xp xs) yp ys) else
       if n = 2 then SOME ((LUPDATE (EL (xp + 1) xs) (yp + 1) o
                            LUPDATE (EL (xp + 0) xs) (yp + 0)) ys)
                              else
       if n = 3 then SOME ((LUPDATE (EL (xp + 2) xs) (yp + 2) o
                            LUPDATE (EL (xp + 1) xs) (yp + 1) o
                            LUPDATE (EL (xp + 0) xs) (yp + 0)) ys)
                              else
         list_copy_fwd (n - 4) (xp + 4) xs (yp + 4)
                          ((LUPDATE (EL (xp + 3) xs) (yp + 3) o
                            LUPDATE (EL (xp + 2) xs) (yp + 2) o
                            LUPDATE (EL (xp + 1) xs) (yp + 1) o
                            LUPDATE (EL (xp + 0) xs) (yp + 0)) ys)
                              else NONE)`;;

let list_copy_fwd_alias_def = cake_define
  `list_copy_fwd_alias n xp yp ys =
     (if xp + n <= LENGTH ys /\ yp + n <= LENGTH ys then
       if n = 0 then SOME ys else
       if n = 1 then SOME (LUPDATE (EL xp ys) yp ys) else
       if n = 2 then SOME ((LUPDATE (EL (xp + 1) ys) (yp + 1) o
                            LUPDATE (EL (xp + 0) ys) (yp + 0)) ys)
                              else
       if n = 3 then SOME ((LUPDATE (EL (xp + 2) ys) (yp + 2) o
                            LUPDATE (EL (xp + 1) ys) (yp + 1) o
                            LUPDATE (EL (xp + 0) ys) (yp + 0)) ys)
                              else
         list_copy_fwd_alias (n - 4) (xp + 4) (yp + 4)
                          ((LUPDATE (EL (xp + 3) ys) (yp + 3) o
                            LUPDATE (EL (xp + 2) ys) (yp + 2) o
                            LUPDATE (EL (xp + 1) ys) (yp + 1) o
                            LUPDATE (EL (xp + 0) ys) (yp + 0)) ys)
                              else NONE)`;;

(* the port's own: what the four lemmas about the copy of a part of
   a byte array share.  The lemmas are three facts about the word
   size and about the arithmetic of the addresses, and the second
   insert at a key that the stores leave behind; the rest are the
   steps that the four proofs take, which are the same in all four
   because the four definitions of the loop are the same up to the
   direction of the step *)

let dimword_facts = prove
 (`good_dimindex (:'a)
     ==> (~(dimword (:'a) <= 4) /\ 0 < dimword (:'a) /\
          2 < dimword (:'a) /\ 4 < dimword (:'a))`,
  (REWRITE_TAC[good_dimindex_def; dimword; NOT_LE] THEN
   DISCH_THEN (DISJ_CASES_THEN SUBST1_TAC) THEN
   CONV_TAC NUM_REDUCE_CONV));;
(* the four guards of the loop, as guards about the counter *)
let word_copy_guards = prove
 (`!n. good_dimindex (:'a) /\ n < dimword (:'a)
     ==> ((((n2w n):'a word) <+ n2w 4 <=> n < 4) /\
          (((n2w n):'a word) <+ n2w 2 <=> n < 2) /\
          (((n2w n):'a word) = n2w 0 <=> n = 0) /\
          (((n2w n):'a word) = n2w 2 <=> n = 2))`,
  (GEN_TAC THEN STRIP_TAC THEN
   FIRST_ASSUM (fun gd ->
     if not (hd_is "good_dimindex" (concl gd)) then fail() else
     MP_TAC (REWRITE_RULE[good_dimindex_def] gd)) THEN
   STRIP_TAC THEN
   (SUBGOAL_THEN `0 < dimword (:'a) /\ 2 < dimword (:'a) /\
                  4 < dimword (:'a)` STRIP_ASSUME_TAC THENL
     [ASM_REWRITE_TAC[dimword] THEN CONV_TAC NUM_REDUCE_CONV;
      ASM_SIMP_TAC[n2w_lo_lt; n2w_11_lt]])));;
(* a step of the backward loop takes the address down, and the
   index of the array goes down with it *)
let sub_n2w_step = prove
 (`!(a:'a word) k j. j <= k
     ==> (a + n2w k) - n2w j = a + n2w (k - j)`,
  (REPEAT STRIP_TAC THEN ASM_SIMP_TAC[WORD_SUB] THEN
   CONV_TAC WORD_RULE));;
(* and a second insert at the same key, which the stores of the
   bytes of an array one at a time leave behind.  HOL4 has the
   general insert_insert (sptreeScript.sml:1612), of which the
   proofs of the port only need this case *)
let insert_insert_same = prove
 (`!k v1 v2 (t:(A)spt).
    sptree_insert k v1 (sptree_insert k v2 t) = sptree_insert k v1 t`,
  (MATCH_MP_TAC num_WF THEN X_GEN_TAC `k:num` THEN DISCH_TAC THEN
  MAP_EVERY X_GEN_TAC [`v1:A`; `v2:A`; `t:(A)spt`] THEN
  STRUCT_CASES_TAC (ISPEC `t:(A)spt` (cases_of `:(A)spt`)) THEN
  ONCE_REWRITE_TAC[insert_def] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  TRY (COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN
  GEN_REWRITE_TAC LAND_CONV [insert_def] THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM (fun ih ->
    if not (is_forall (concl ih)) then fail() else
    FIRST_ASSUM (fun nz ->
      if not (is_neg (concl nz)) || not (is_eq (rand (concl nz)))
      then fail() else
      REWRITE_TAC[MP (SPEC `(k - 1) DIV 2` ih)
                    (MATCH_MP DIV2_SUB1_LESS nz)])) THEN
  TRY (REWRITE_TAC[])));;
(* the assumptions that the steps below are built from *)
let the_mr asl =
  grab_asm (fun th -> hd_is "memory_rel" (concl th)) asl;;
let the_gd asl =
  grab_asm (fun th -> hd_is "good_dimindex" (concl th)) asl;;
let the_lk asl =
  grab_asm (fun th ->
    is_eq (concl th) && hd_is "sptree_lookup" (lhs (concl th)) &&
    hd_is "SOME" (rhs (concl th))) asl;;
let the_ne asl =
  grab_asm (fun th ->
    is_neg (concl th) && is_eq (rand (concl th)) &&
    is_var (lhs (rand (concl th))) &&
    is_var (rand (rand (concl th))) &&
    type_of (lhs (rand (concl th))) = `:num`) asl;;
let the_weq v asl =
  grab_asm (fun th ->
    is_eq (concl th) && lhs (concl th) = v &&
    hd_is "wordLang_Word" (rhs (concl th))) asl;;
let the_gra w asl =
  grab_asm (fun th ->
    is_eq (concl th) && hd_is "get_real_addr" (lhs (concl th)) &&
    rand (lhs (concl th)) = w) asl;;
let refs_of mr = el 3 (snd (strip_comb (concl mr)));;
let mem_of mr = el 6 (snd (strip_comb (concl mr)));;
let vars_of mr = el 8 (snd (strip_comb (concl mr)));;
let ins_of mr = snd (strip_comb (refs_of mr));;
let hd_of mr = rand (rator (vars_of mr));;
(* the array that the insert of the refs of the invariant put
   there, and the invariant turned so that the pointer of it comes
   first; where a store has been done already the root of that
   pointer is a word there, and otherwise it is the one that the
   lemma about the array gave *)
let ins_lk mr =
  let ins = ins_of mr in
  REWRITE_RULE[] (ISPECL [el 0 ins; el 0 ins; el 1 ins; el 2 ins]
    lookup_insert);;
let turn mr =
  if rand (lhand (hd_of mr)) = el 0 (ins_of mr) then mr
  else MATCH_MP memory_rel_swap mr;;
let turn_mr asl =
  let mr0 = turn (the_mr asl) in
  let v = rand (hd_of mr0) in
  if is_var v then
    let weq = the_weq v asl in
    REWRITE_RULE[weq] mr0, rand (rhs (concl weq))
  else mr0, rand v;;
let get_ins =
  W(fun (asl,gl) ->
    let mr = turn (the_mr asl) in
    MP_TAC (MATCH_MP memory_rel_ByteArray_IMP
      (CONJ mr (CONJ (ins_lk mr) (the_gd asl))))) THEN
  DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC);;
(* and the array of the other pointer, which is in the refs that
   the insert was done to, because the two keys are not the same *)
let get_other =
  W(fun (asl,gl) ->
    let mr = the_mr asl in
    let ins = ins_of mr in
    let lk = the_lk asl in
    let lk' = TRANS (REWRITE_RULE[EQF_INTRO (the_ne asl)]
      (ISPECL [el 0 ins; lhand (lhs (concl lk)); el 1 ins;
        el 2 ins] lookup_insert)) lk in
    MP_TAC (MATCH_MP memory_rel_ByteArray_IMP
      (CONJ mr (CONJ lk' (the_gd asl))))) THEN
  DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC);;
(* the load of the byte at an index of an array, from what the
   lemma about that array says of every index of it *)
let load_at xs i =
  W(fun (asl,gl) ->
    let lds = grab_asm (fun th ->
      is_forall (concl th) &&
      can (find_term (hd_is "mem_load_byte_aux")) (concl th) &&
      can (find_term (fun t -> hd_is "EL" t && rand t = xs))
        (concl th)) asl in
    let sp = SPEC i lds in
    let lt = grab_asm (fun th -> concl th = lhand (concl sp)) asl in
    ASSUME_TAC (MP sp lt));;
(* and the store of a byte at an index of the array of the insert,
   which gives a memory and an invariant of that memory; the
   second insert that it leaves at the key is the first one *)
let store_at i b =
  W(fun (asl,gl) ->
    let vals = rand (el 1 (ins_of (the_mr asl))) in
    let mr,w = turn_mr asl in
    let lt0 = grab_asm (fun th ->
      hd_is "<" (concl th) && lhand (concl th) = i) asl in
    let lt = ONCE_REWRITE_RULE
      [SYM (REWRITE_CONV[LENGTH_LUPDATE] (mk_comb (rator (rand
         (concl lt0)), vals)))] lt0 in
    MP_TAC (MATCH_MP (INST [i,`i:num`; b,`b:word8`]
      memory_rel_ByteArray_IMP_store)
      (CONJ mr (CONJ (ins_lk mr) (CONJ (the_gd asl)
        (CONJ (the_gra w asl) lt)))))) THEN
  DISCH_THEN (CHOOSE_THEN STRIP_ASSUME_TAC) THEN
  FIRST_X_ASSUM (fun mr ->
    if not (hd_is "memory_rel" (concl mr)) then fail() else
    let mr' = REWRITE_RULE[insert_insert_same] mr in
    (if can (MATCH_MP memory_rel_swap) mr'
     then ASSUME_TAC (MATCH_MP memory_rel_swap mr')
     else ALL_TAC) THEN
    ASSUME_TAC mr');;
(* what the loads and the stores of a case need of the bounds, from
   the bound that the definition of the copy gave.  The assumptions
   about the word size are left out of the arithmetic, which cannot
   take dimword for an atom *)
let bounds tm =
  SUBGOAL_THEN tm STRIP_ASSUME_TAC THENL
   [EVERY_ASSUM (fun th ->
      let c = concl th in
      if not (can (find_term (hd_is "dimword")) c) &&
         (is_conj c || hd_is "<" c || hd_is "<=" c ||
          (is_neg c &&
           ((is_eq (rand c) && is_numeral (rand (rand c))) ||
            is_conj (rand c))))
      then MP_TAC th else ALL_TAC) THEN
    ARITH_TAC;
    ALL_TAC];;
(* the roots and the memory that the lemmas gave are the witnesses
   of the statement; where a root is in the goal already it is the
   word of it *)
let wof asl t =
  if hd_is "wordLang_Word" t then rand t
  else rand (rhs (concl (the_weq t asl)));;
let wit1 =
  W(fun (asl,gl) ->
    let cs = conjuncts (snd (strip_exists gl)) in
    let w = wof asl (lhs (el 0 cs)) in
    MAP_EVERY EXISTS_TAC [w; rand (rhs (concl (the_gra w asl)))]);;
let wit2 =
  W(fun (asl,gl) ->
    let cs = conjuncts (snd (strip_exists gl)) in
    let w1 = wof asl (lhs (el 0 cs))
    and w2 = wof asl (lhs (el 1 cs)) in
    MAP_EVERY EXISTS_TAC
      [w1; w2; rand (rhs (concl (the_gra w1 asl)));
       rand (rhs (concl (the_gra w2 asl)))]);;
let is_wc t = hd_is "word_copy_fwd" t || hd_is "word_copy_bwd" t;;
let wit_m =
  W(fun (asl,gl) ->
    let eqn = find (fun t -> is_eq t && is_wc (lhs t))
      (conjuncts (snd (strip_exists gl))) in
    EXISTS_TAC (el 4 (snd (strip_comb (lhs eqn)))));;
let wit_store =
  W(fun (asl,gl) ->
    EXISTS_TAC (rand (rhs (concl (grab_asm (fun th ->
      is_eq (concl th) &&
      hd_is "mem_store_byte_aux" (lhs (concl th))) asl)))));;
let wit_wcf =
  W(fun (asl,gl) ->
    EXISTS_TAC (rand (rhs (concl (grab_asm (fun th ->
      is_eq (concl th) && is_wc (lhs (concl th))) asl)))));;
let subst_vs =
  REPEAT (FIRST_X_ASSUM (fun th ->
    let c = concl th in
    if is_eq c && is_var (lhs c) && hd_is "wordLang_Word" (rhs c)
    then SUBST_ALL_TAC th else fail()));;
(* the roots of the hypothesis of the induction are the roots of
   the goal, and so are the real addresses of them *)
let unify_wds =
  RULE_ASSUM_TRY (REWRITE_RULE[injectivity "word_loc"]) THEN
  REPEAT (FIRST_X_ASSUM (fun th ->
    let c = concl th in
    if is_eq c && is_var (lhs c) && is_var (rand c) &&
       not (lhs c = rand c) &&
       (try fst (dest_type (type_of (lhs c))) = "word"
        with Failure _ -> false)
    then SUBST_ALL_TAC (SYM th) else fail()));;
let unify_addrs =
  REPEAT (W(fun (asl,gl) ->
    let gr th =
      is_eq (concl th) && hd_is "get_real_addr" (lhs (concl th)) in
    tryfind (fun (_,th1) ->
      if not (gr th1) then fail() else
      tryfind (fun (_,th2) ->
        if not (gr th2) || not (lhs (concl th1) = lhs (concl th2))
           || rand (rhs (concl th1)) = rand (rhs (concl th2))
        then fail() else
        SUBST_ALL_TAC (REWRITE_RULE[injectivity "option"]
          (TRANS (SYM th1) th2))) asl) asl));;
(* the hypothesis of the induction, at the counter less four and at
   the arrays and the memory that the four stores left *)
let use_ih xt yt =
  W(fun (asl,gl) ->
    let ih = grab_asm (fun th ->
      is_forall (concl th) &&
      can (find_term is_wc) (concl th)) asl in
    let mr = the_mr asl in
    let lt = grab_asm (fun th -> concl th = `n - 4 < n`) asl in
    MP_TAC (SPECL [xt; yt; rand (el 1 (ins_of mr));
      `ys1:word8 list`; mem_of mr] (MP (SPEC `n - 4` ih) lt))) THEN
  (ANTS_TAC THENL
    [REPEAT CONJ_TAC THEN
     TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
     EVERY_ASSUM (fun th ->
       if hd_is "<" (concl th) then MP_TAC th else ALL_TAC) THEN
     ARITH_TAC;
     ALL_TAC]) THEN
  DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
  unify_wds THEN unify_addrs;;
(* the counter of the loop goes down by four, and the word of that
   is the word of the counter less four *)
let sub4 =
  W(fun (asl,gl) ->
    let le = grab_asm (fun th -> concl th = `4 <= n`) asl in
    REWRITE_TAC[GSYM (REWRITE_RULE[EQT_INTRO le]
      (ISPECL [`n:num`; `4`] WORD_SUB))]);;
(* the loop at the counter of a case, with the guards settled and
   the addresses of the loads and of the stores brought to the
   shape that the lemmas about the arrays give them in *)
let open_wc def =
  ONCE_REWRITE_TAC[def] THEN
  ASM_SIMP_TAC[dimword_facts; word_copy_guards] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  RULE_ASSUM_TRY (REWRITE_RULE[WORD_ADD; WORD_ADD_ASSOC]) THEN
  ASM_SIMP_TAC[OPTION_BIND; WORD_ADD; WORD_ADD_ASSOC;
               sub_n2w_step];;
(* and the five cases of the counter, from the definition of the
   copy: the counter is zero, or one, or two, or three, or it is
   four or more and the loop takes a step *)
let setup_cp def rws =
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  REPEAT GEN_TAC THEN
  ONCE_REWRITE_TAC[def] THEN
  STRIP_TAC THEN
  FIRST_X_ASSUM (fun th ->
    if is_eq (concl th) && hd_is "COND" (lhs (concl th))
    then MP_TAC th else fail()) THEN
  REPEAT COND_CASES_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  DISCH_THEN (fun th ->
    if is_eq (concl th) && is_var (rand (concl th))
    then SUBST_ALL_TAC (SYM th) else ASSUME_TAC th) THEN
  TRY (FIRST_X_ASSUM (fun th ->
    if is_eq (concl th) && is_var (lhs (concl th)) &&
       is_numeral (rand (concl th)) then SUBST_ALL_TAC th
    else fail())) THEN
  REWRITE_TAC rws THEN RULE_ASSUM_TRY (REWRITE_RULE rws);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_copy_fwd_thm = prove
 (cake_as_vars (fun () ->
    `!n xp yp ys ys1 m.
        memory_rel c be ts (insert p2 (ByteArray fl_ys ys) refs)
          sp st m dm ((RefPtr bl1 p1,v1) :: (RefPtr bl2 p2,v2) ::
            vars) /\
        lookup p1 refs = SOME (ByteArray fl_xs xs) /\
        list_copy_fwd n xp xs yp ys = SOME ys1 /\
        good_dimindex (:'a) /\ n < dimword (:'a) /\ ~(p1 = p2) ==>
        (?w1 (w2:'a word) a1 a2 m1.
          v1 = wordLang_Word w1 /\ v2 = wordLang_Word w2 /\
          get_real_addr c st w1 = SOME a1 /\
          get_real_addr c st w2 = SOME a2 /\
          word_copy_fwd be (n2w n) (a1 + bytes_in_word + n2w xp)
            (a2 + bytes_in_word + n2w yp) m dm = SOME m1 /\
          memory_rel c be ts (insert p2 (ByteArray fl_ys ys1) refs)
            sp st m1 dm ((RefPtr bl1 p1,v1) :: (RefPtr bl2 p2,v2)
              :: vars))`),
(* the complete induction of the source on the counter, and then
   the five cases that the definition of the copy of a list has:
   the counter is zero, or one, or two, or three, or it is four or
   more and four bytes are copied before the loop goes on.
     In each case the two arrays are the ones that the invariant
   speaks of (memory_rel_ByteArray_IMP of the pointer that the
   insert of the refs is at, and of the other pointer after its
   lookup is taken through that insert), the bytes are loaded from
   the first array (the load of every index of it that the lemma
   gives) and stored into the second one
   (memory_rel_ByteArray_IMP_store, which gives the memory of the
   store and the invariant of that memory), and the guards of the
   loop are decided by the counter (word_copy_guards).  In the
   last case the hypothesis of the induction copies what is left,
   at the counter less four *)
  ((let pre = bounds `xp < LENGTH (xs:word8 list) /\
                    yp < LENGTH (ys:word8 list)` in
  let bnd k = bounds (subst [mk_small_numeral k,`k:num`]
    `xp + k < LENGTH (xs:word8 list) /\
     yp + k < LENGTH (ys:word8 list)`) in
  let load k = load_at `xs:word8 list`
    (if k = 0 then `xp:num` else
     subst [mk_small_numeral k,`k:num`] `xp + k`) in
  let store k =
    if k = 0 then store_at `yp:num` `EL xp (xs:word8 list)`
    else store_at (subst [mk_small_numeral k,`k:num`] `yp + k`)
      (subst [mk_small_numeral k,`k:num`]
        `EL (xp + k) (xs:word8 list)`) in
  let zero =
    get_other THEN get_ins THEN wit2 THEN wit_m THEN subst_vs THEN
    open_wc word_copy_fwd_def in
  let small j =
    get_other THEN get_ins THEN pre THEN
    EVERY (map bnd (1--j)) THEN
    EVERY (map load (0--j)) THEN
    EVERY (map store (0--j)) THEN
    wit2 THEN wit_store THEN subst_vs THEN
    open_wc word_copy_fwd_def in
  let step =
    bounds `~(n < 4) /\ 4 <= n /\ n - 4 < n` THEN
    get_other THEN get_ins THEN pre THEN
    EVERY (map bnd [1; 2; 3]) THEN
    EVERY (map load [0; 1; 2; 3]) THEN
    EVERY (map store [0; 1; 2; 3]) THEN
    subst_vs THEN use_ih `xp + 4` `yp + 4` THEN
    wit2 THEN wit_wcf THEN open_wc word_copy_fwd_def THEN
    sub4 THEN ASM_REWRITE_TAC[WORD_ADD; WORD_ADD_ASSOC] in
  setup_cp list_copy_fwd_def [o_THM; ADD_CLAUSES] THENL
   [zero; small 0; small 1; small 2; step])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_copy_fwd_alias_thm = prove
 (cake_as_vars (fun () ->
    `!n xp yp ys ys1 m.
        memory_rel c be ts (insert p2 (ByteArray fl_ys ys) refs)
          sp st m dm ((RefPtr bl p2,v2) :: vars) /\
        list_copy_fwd_alias n xp yp ys = SOME ys1 /\
        good_dimindex (:'a) /\ n < dimword (:'a) ==>
        (?(w2:'a word) a2 m1.
          v2 = wordLang_Word w2 /\
          get_real_addr c st w2 = SOME a2 /\
          word_copy_fwd be (n2w n) (a2 + bytes_in_word + n2w xp)
            (a2 + bytes_in_word + n2w yp) m dm = SOME m1 /\
          memory_rel c be ts (insert p2 (ByteArray fl_ys ys1) refs)
            sp st m1 dm ((RefPtr bl p2,v2) :: vars))`),
(* the same five cases as word_copy_fwd_thm, of one array that is
   copied into itself: the four bytes are loaded before any of
   them is stored, so the loads are the loads of the array as the
   invariant of the source has it, and only the stores go through
   memory_rel_ByteArray_IMP_store one after the other *)
  ((let pre = bounds `xp < LENGTH (ys:word8 list) /\
                    yp < LENGTH (ys:word8 list)` in
  let bnd k = bounds (subst [mk_small_numeral k,`k:num`]
    `xp + k < LENGTH (ys:word8 list) /\
     yp + k < LENGTH (ys:word8 list)`) in
  let load k = load_at `ys:word8 list`
    (if k = 0 then `xp:num` else
     subst [mk_small_numeral k,`k:num`] `xp + k`) in
  let store k =
    if k = 0 then store_at `yp:num` `EL xp (ys:word8 list)`
    else store_at (subst [mk_small_numeral k,`k:num`] `yp + k`)
      (subst [mk_small_numeral k,`k:num`]
        `EL (xp + k) (ys:word8 list)`) in
  let zero =
    get_ins THEN wit1 THEN wit_m THEN subst_vs THEN
    open_wc word_copy_fwd_def in
  let small j =
    get_ins THEN pre THEN
    EVERY (map bnd (1--j)) THEN
    EVERY (map load (0--j)) THEN
    EVERY (map store (0--j)) THEN
    wit1 THEN wit_store THEN subst_vs THEN
    open_wc word_copy_fwd_def in
  let step =
    bounds `~(n < 4) /\ 4 <= n /\ n - 4 < n` THEN
    get_ins THEN pre THEN
    EVERY (map bnd [1; 2; 3]) THEN
    EVERY (map load [0; 1; 2; 3]) THEN
    EVERY (map store [0; 1; 2; 3]) THEN
    subst_vs THEN use_ih `xp + 4` `yp + 4` THEN
    wit1 THEN wit_wcf THEN open_wc word_copy_fwd_def THEN
    sub4 THEN ASM_REWRITE_TAC[WORD_ADD; WORD_ADD_ASSOC] in
  setup_cp list_copy_fwd_alias_def [o_THM; ADD_CLAUSES] THENL
   [zero; small 0; small 1; small 2; step])));;

(* copy backward *)

(* HOL4 data_to_word_memoryProofScript.sml:15569-15574: the tactic
   that proves the termination *)
let word_copy_bwd_def = cake_define_try_tac (fun () ->
  `MEASURE (w2n o FST o SND)`)
  TERM_TAC
  `word_copy_bwd be' (n:'a word) a b (m:'a word->'a word_loc) dm =
     (if dimword (:'a) <= 4 then NONE else
     if n <+ (n2w 4) then
       if n <+ (n2w 2) then
         if n = (n2w 0) then SOME m else
           OPTION_BIND (mem_load_byte_aux m dm be' a)
                       (\w. mem_store_byte_aux m dm be' b w) else
         OPTION_BIND (mem_load_byte_aux m dm be' a) (\w1.
         OPTION_BIND (mem_load_byte_aux m dm be' (a - (n2w 1))) (\w2.
           if n = (n2w 2) then
             OPTION_BIND (mem_store_byte_aux m dm be' b w1) (\m.
             OPTION_BIND (mem_store_byte_aux m dm be' (b - (n2w 1))
               w2) (\m. SOME m)) else
             OPTION_BIND (mem_load_byte_aux m dm be' (a - (n2w 2)))
               (\w3.
             OPTION_BIND (mem_store_byte_aux m dm be' b w1) (\m.
             OPTION_BIND (mem_store_byte_aux m dm be' (b - (n2w 1))
               w2) (\m.
             OPTION_BIND (mem_store_byte_aux m dm be' (b - (n2w 2))
               w3) (\m. SOME m)))))) else
       OPTION_BIND (mem_load_byte_aux m dm be' a) (\w1.
       OPTION_BIND (mem_load_byte_aux m dm be' (a - (n2w 1))) (\w2.
       OPTION_BIND (mem_load_byte_aux m dm be' (a - (n2w 2))) (\w3.
       OPTION_BIND (mem_load_byte_aux m dm be' (a - (n2w 3))) (\w4.
       OPTION_BIND (mem_store_byte_aux m dm be' b w1) (\m.
       OPTION_BIND (mem_store_byte_aux m dm be' (b - (n2w 1)) w2)
         (\m.
       OPTION_BIND (mem_store_byte_aux m dm be' (b - (n2w 2)) w3)
         (\m.
       OPTION_BIND (mem_store_byte_aux m dm be' (b - (n2w 3)) w4)
         (\m.
         word_copy_bwd be' (n - (n2w 4)) (a - (n2w 4)) (b - (n2w
           4)) m dm)))))))))`;;

let minus_def = cake_define
  `minus m n = m - (n:num)`;;

let list_copy_bwd_def = cake_define
  `list_copy_bwd (n:num) xp xs yp ys =
     (if n <= xp + 1 /\ xp < LENGTH xs /\ n <= yp + 1 /\ yp < LENGTH
       ys then
       if n = 0 then SOME ys else
       if n = 1 then SOME (LUPDATE (EL xp xs) yp ys) else
       if n = 2 then SOME ((LUPDATE (EL (minus xp 1) xs) (minus yp 1)
         o
                            LUPDATE (EL (minus xp 0) xs) (minus yp
                              0)) ys) else
       if n = 3 then SOME ((LUPDATE (EL (minus xp 2) xs) (minus yp 2)
         o
                            LUPDATE (EL (minus xp 1) xs) (minus yp 1)
                              o
                            LUPDATE (EL (minus xp 0) xs) (minus yp
                              0)) ys) else
         list_copy_bwd (n - 4) (minus xp 4) xs (minus yp 4)
                          ((LUPDATE (EL (minus xp 3) xs) (minus yp 3)
                            o
                            LUPDATE (EL (minus xp 2) xs) (minus yp 2)
                              o
                            LUPDATE (EL (minus xp 1) xs) (minus yp 1)
                              o
                            LUPDATE (EL (minus xp 0) xs) (minus yp
                              0)) ys) else NONE)`;;

(* HOL4 data_to_word_memoryProofScript.sml:15598: ML code, not ported *)

let list_copy_bwd_alias_def = cake_define
  `list_copy_bwd_alias n xp yp ys =
     (if n <= xp + 1 /\ xp < LENGTH ys /\ n <= yp + 1 /\ yp < LENGTH
       ys then
       if n = 0 then SOME ys else
       if n = 1 then SOME (LUPDATE (EL xp ys) yp ys) else
       if n = 2 then SOME ((LUPDATE (EL (minus xp 1) ys) (minus yp 1)
         o
                            LUPDATE (EL (minus xp 0) ys) (minus yp
                              0)) ys) else
       if n = 3 then SOME ((LUPDATE (EL (minus xp 2) ys) (minus yp 2)
         o
                            LUPDATE (EL (minus xp 1) ys) (minus yp 1)
                              o
                            LUPDATE (EL (minus xp 0) ys) (minus yp
                              0)) ys) else
         list_copy_bwd_alias (n - 4) (minus xp 4) (minus yp 4)
                          ((LUPDATE (EL (minus xp 3) ys) (minus yp 3)
                            o
                            LUPDATE (EL (minus xp 2) ys) (minus yp 2)
                              o
                            LUPDATE (EL (minus xp 1) ys) (minus yp 1)
                              o
                            LUPDATE (EL (minus xp 0) ys) (minus yp
                              0)) ys) else NONE)`;;
(* HOL4 data_to_word_memoryProofScript.sml:15617-15618: ML code, not
   ported *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_copy_bwd_thm = prove
 (cake_as_vars (fun () ->
    `!n xp yp ys ys1 m.
        memory_rel c be ts (insert p2 (ByteArray fl_ys ys) refs)
          sp st m dm ((RefPtr bl1 p1,v1) :: (RefPtr bl2 p2,v2) ::
            vars) /\
        lookup p1 refs = SOME (ByteArray fl_xs xs) /\
        list_copy_bwd n xp xs yp ys = SOME ys1 /\
        good_dimindex (:'a) /\ n < dimword (:'a) /\ ~(p1 = p2) ==>
        (?w1 (w2:'a word) a1 a2 m1.
          v1 = wordLang_Word w1 /\ v2 = wordLang_Word w2 /\
          get_real_addr c st w1 = SOME a1 /\
          get_real_addr c st w2 = SOME a2 /\
          word_copy_bwd be (n2w n) (a1 + bytes_in_word + n2w xp)
            (a2 + bytes_in_word + n2w yp) m dm = SOME m1 /\
          memory_rel c be ts (insert p2 (ByteArray fl_ys ys1) refs)
            sp st m1 dm ((RefPtr bl1 p1,v1) :: (RefPtr bl2 p2,v2)
              :: vars))`),
(* the same five cases as word_copy_fwd_thm, with the addresses
   and the indices going down instead of up (sub_n2w_step, whose
   condition is that the index is at least as big as the step --
   which the bound of the definition of the copy gives).
     Where an index is below four the step is the last one: the
   bound says that the counter is at most the index plus one, so
   the counter is four, and then the loop and the copy both do
   nothing more, whatever the addresses of that step are *)
  ((let pre = bounds `xp < LENGTH (xs:word8 list) /\
                    yp < LENGTH (ys:word8 list)` in
  let bnd k = bounds (subst [mk_small_numeral k,`k:num`]
    `k <= xp /\ k <= yp /\ xp - k < LENGTH (xs:word8 list) /\
     yp - k < LENGTH (ys:word8 list)`) in
  let load k = load_at `xs:word8 list`
    (if k = 0 then `xp:num` else
     subst [mk_small_numeral k,`k:num`] `xp - k`) in
  let store k =
    if k = 0 then store_at `yp:num` `EL xp (xs:word8 list)`
    else store_at (subst [mk_small_numeral k,`k:num`] `yp - k`)
      (subst [mk_small_numeral k,`k:num`]
        `EL (xp - k) (xs:word8 list)`) in
  let zero =
    get_other THEN get_ins THEN wit2 THEN wit_m THEN subst_vs THEN
    open_wc word_copy_bwd_def in
  let small j =
    get_other THEN get_ins THEN pre THEN
    EVERY (map bnd (1--j)) THEN
    EVERY (map load (0--j)) THEN
    EVERY (map store (0--j)) THEN
    wit2 THEN wit_store THEN subst_vs THEN
    open_wc word_copy_bwd_def in
  (* where an index is below four this step is the last one, the
     counter being four, and then the loop and the copy do
     nothing more *)
  let tail =
    bounds `n = 4` THEN
    FIRST_X_ASSUM (fun th ->
      if concl th = `n = 4` then SUBST_ALL_TAC th else fail()) THEN
    bounds `xp - 4 < LENGTH (xs:word8 list) /\
            yp - 4 < LENGTH (ys:word8 list)` THEN
    FIRST_X_ASSUM (fun lc ->
      if not (is_eq (concl lc)) ||
         not (hd_is "list_copy_bwd" (lhs (concl lc)))
      then fail() else
      MP_TAC (CONV_RULE NUM_REDUCE_CONV
        (ONCE_REWRITE_RULE[list_copy_bwd_def] lc))) THEN
    ASM_REWRITE_TAC[LE_0; LENGTH_LUPDATE;
                    injectivity "option"] THEN
    DISCH_THEN (fun th ->
      if is_var (lhs (concl th)) then SUBST_ALL_TAC th
      else SUBST_ALL_TAC (SYM th)) THEN
    wit2 THEN wit_store THEN open_wc word_copy_bwd_def THEN
    REWRITE_TAC[WORD_SUB_REFL] THEN
    ONCE_REWRITE_TAC[word_copy_bwd_def] THEN
    ASM_SIMP_TAC[dimword_facts; word_copy_guards] THEN
    CONV_TAC NUM_REDUCE_CONV THEN ASM_REWRITE_TAC[] in
  let step =
    bounds `~(n < 4) /\ 4 <= n /\ n - 4 < n` THEN
    get_other THEN get_ins THEN pre THEN
    EVERY (map bnd [1; 2; 3]) THEN
    EVERY (map load [0; 1; 2; 3]) THEN
    EVERY (map store [0; 1; 2; 3]) THEN
    subst_vs THEN
    (ASM_CASES_TAC `4 <= xp /\ 4 <= yp` THENL
      [FIRST_X_ASSUM (CONJUNCTS_THEN ASSUME_TAC) THEN
       use_ih `xp - 4` `yp - 4` THEN
       wit2 THEN wit_wcf THEN open_wc word_copy_bwd_def THEN
       sub4 THEN ASM_REWRITE_TAC[WORD_ADD; WORD_ADD_ASSOC];
       tail]) in
  setup_cp list_copy_bwd_def
    [o_THM; minus_def; ADD_CLAUSES; SUB_0] THENL
   [zero; small 0; small 1; small 2; step])));;

(* the names of record fields that this statement uses for
