     [POP_ASSUM SUBST_ALL_TAC THEN
      REWRITE_TAC[SUB_0; TAKE_0; APPEND; TAKE_DROP];
      ALL_TAC]) THEN
   ASM_REWRITE_TAC[] THEN
   (ASM_CASES_TAC `n = 1` THENL
     [POP_ASSUM SUBST_ALL_TAC THEN ASM_SIMP_TAC[copy_base_bwd];
      ALL_TAC]) THEN
   ASM_REWRITE_TAC[] THEN
   (ASM_CASES_TAC `n = 2` THENL
     [POP_ASSUM SUBST_ALL_TAC THEN COPY_BNDS_B_TAC THEN
      ASM_SIMP_TAC[o_THM; SUB_0; copy_base_bwd; copy_step_bwd;
                   ARITH];
      ALL_TAC]) THEN
   ASM_REWRITE_TAC[] THEN
   (ASM_CASES_TAC `n = 3` THENL
     [POP_ASSUM SUBST_ALL_TAC THEN COPY_BNDS_B_TAC THEN
      ASM_SIMP_TAC[o_THM; SUB_0; copy_base_bwd; copy_step_bwd;
                   ARITH];
      ALL_TAC]) THEN
   ASM_REWRITE_TAC[] THEN
   COPY_BNDS_B_TAC THEN
   ASM_SIMP_TAC[o_THM; SUB_0; copy_base_bwd; copy_step_bwd;
                ARITH] THEN
   W(fun (asl,w) ->
     let args = snd(strip_comb(lhs w)) in
     FIRST_ASSUM(fun ih ->
       if not (is_forall(concl ih)) then fail() else
       MP_TAC(SPEC (hd args) ih))) THEN
   (ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
   DISCH_THEN(fun ih2 ->
     W(fun (asl,w) ->
       let args = snd(strip_comb(lhs w)) in
       MP_TAC(SPECL (tl args) ih2))) THEN
   (ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN COPY_LEN_TAC THEN
      ASM_REWRITE_TAC[LENGTH_APPEND; LENGTH_DROP] THEN
      ASM_ARITH_TAC;
      ALL_TAC]) THEN
   DISCH_THEN SUBST1_TAC THEN AP_TERM_TAC THEN
   MATCH_MP_TAC copy_glue_bwd_alias THEN ASM_ARITH_TAC));;

let list_copy_alias_thm = prove
 (`!ys xp yp n ys1.
      copy_array (ys,&xp) (&n) (SOME (ys,&yp)) = SOME ys1 ==>
      list_copy_alias n xp yp ys = SOME ys1`,
  (* the same of an alias.  Of a copy of none the forward
     equation says nothing, because the destination may be above
     the source there, and the definition gives it of itself *)
  (REPEAT GEN_TAC THEN
   REWRITE_TAC[copy_array_def; I_THM; INT_OF_NUM_ADD; INT_ABS_NUM;
               NUM_OF_INT_OF_NUM; INT_OF_NUM_LT; LT] THEN
   COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN MATCH_REDUCE_TAC THEN
   COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
   REWRITE_TAC[injectivity "option"] THEN
   DISCH_THEN(SUBST1_TAC o SYM) THEN
   REWRITE_TAC[list_copy_alias_def] THEN
   (COND_CASES_TAC THENL
     [(ASM_CASES_TAC `(yp:num) <= xp` THENL
        [W(fun (_,w) -> MP_TAC(PART_MATCH (lhs o rand)
             list_copy_fwd_alias_eq (lhand w))) THEN
         (ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
         DISCH_THEN SUBST1_TAC THEN
         (SUBGOAL_THEN `n + yp = yp + n` SUBST1_TAC THENL
           [ARITH_TAC; ALL_TAC]) THEN
         REFL_TAC;
         (SUBGOAL_THEN `n = 0 /\ xp = 0` STRIP_ASSUME_TAC THENL
           [ASM_ARITH_TAC; ALL_TAC]) THEN
         ASM_REWRITE_TAC[] THEN
         ONCE_REWRITE_TAC[list_copy_fwd_alias_def] THEN
         (COND_CASES_TAC THENL
           [ALL_TAC;
            SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC]) THEN
         REWRITE_TAC[ARITH_EQ; TAKE_0; APPEND; ADD_CLAUSES;
                     TAKE_DROP]]);
      W(fun (_,w) -> MP_TAC(PART_MATCH (lhs o rand)
          list_copy_bwd_alias_eq (lhand w))) THEN
      (ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
      DISCH_THEN SUBST1_TAC THEN
      (SUBGOAL_THEN `(((yp + n) - 1) + 1) - n = yp` SUBST1_TAC THENL
        [ASM_ARITH_TAC; ALL_TAC]) THEN
      (SUBGOAL_THEN `(((xp + n) - 1) + 1) - n = xp` SUBST1_TAC THENL
        [ASM_ARITH_TAC; ALL_TAC]) THEN
      (SUBGOAL_THEN `((yp + n) - 1) + 1 = yp + n` SUBST1_TAC THENL
        [ASM_ARITH_TAC; ALL_TAC]) THEN
      REFL_TAC])));;

let copy_array_NONE_IMP = prove
 (`!xs ys xp n.
      copy_array (xs,&xp) (&n) NONE = SOME ys ==>
      list_copy_fwd n xp xs 0 (REPLICATE n (n2w 0)) = SOME ys`,
  (* the offsets are of naturals, so copy_array is NONE exactly when
     the source is too short and otherwise takes the n elements from
     the offset on, and list_copy_fwd_eq copies them into a list of
     n zeroes: the whole of it, so nothing of the zeroes is left *)
  (let take0 = prove
    (`!l:A list. TAKE 0 l = []`,
     LIST_INDUCT_TAC THEN REWRITE_TAC[TAKE]) in
   let dropall = prove
    (`!n (x:A). DROP n (REPLICATE n x) = []`,
     INDUCT_TAC THEN
     ASM_REWRITE_TAC[DROP; REPLICATE; NOT_SUC; SUC_SUB1]) in
   REPEAT GEN_TAC THEN
   REWRITE_TAC[copy_array_def; I_THM; INT_OF_NUM_ADD;
               INT_ABS_NUM; NUM_OF_INT_OF_NUM; INT_OF_NUM_LT;
               LT] THEN
   COND_CASES_TAC THEN
   REWRITE_TAC[distinctness "option"] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[injectivity "option"] THEN
   DISCH_THEN(SUBST1_TAC o SYM) THEN
   W(fun (_,w) -> MP_TAC(PART_MATCH (lhs o rand)
       list_copy_fwd_eq (lhand w))) THEN
   REWRITE_TAC[LENGTH_REPLICATE; ADD_CLAUSES; LE_REFL] THEN
   ANTS_TAC THENL
    [ASM_ARITH_TAC;
     REWRITE_TAC[take0; dropall; APPEND; APPEND_NIL] THEN
     DISCH_THEN ACCEPT_TAC]));;

(*

val xs = EVAL ``GENLIST I 20`` |> concl |> rand

fun cross [] xs = []
  | cross (y::ys) xs = map (fn x => (y,x)) xs @ cross ys xs

val nums = xs |> listSyntax.dest_list |> fst

val inputs = cross nums (cross nums nums)

fun test (n1,(n2,n3)) =
  (ISPEC xs list_copy_alias_thm
   |> Q.SPECL [`1`,`4`,`18`] |> SPEC_ALL
   |> CONV_RULE (RATOR_CONV EVAL THENC RAND_CONV EVAL)
   |> GEN_ALL |> SIMP_RULE std_ss [] |> concl) = T

val (n1,(n2,n3)) = first (not o test) inputs

*)

let word_copy_array_def = cake_define
  `word_copy_array be' n a a1 b b1 (m:'a word->'a word_loc) dm =
     (if b1 <=+ a1 then
       word_copy_fwd be' n (a + a1) (b + b1) m dm else
       word_copy_bwd be' n ((a + a1 + n) - (n2w 1)) ((b + b1 + n)
         - (n2w 1)) m dm)`;;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_copy_bwd_0 = prove
 (cake_as_vars (fun () ->
    `good_dimindex (:'a) ==>
     word_copy_bwd be ((n2w 0):'a word) a1 a2 m dm = SOME m`),
  (* a copy of no bytes is the memory itself, and good_dimindex puts
     the dimword above the four that the clause asks for *)
  (REWRITE_TAC[good_dimindex_def] THEN STRIP_TAC THEN
   GEN_REWRITE_TAC LAND_CONV [word_copy_bwd_def] THEN
   ASM_REWRITE_TAC[dimword; WORD_ULT; VAL_WORD; VAL_WORD_0] THEN
   CONV_TAC NUM_REDUCE_CONV));;

(* the port's own: what the two lemmas about a copy of a part of a
   byte array into another share.  HOL4 takes insert_unchanged
   from sptreeTheory (sptreeScript.sml:2255, with splem1 for the
   key of a subtree) and gets the other two with fs from the
   definitions; the steps below are the ones that both proofs
   take, and they stand here for the same reason as the arms of
   bc_ref_inv above *)

let insert_unchanged = prove
 (`!k (t:(A)spt) y. sptree_lookup k t = SOME y
    ==> sptree_insert k y t = t`,
  (MATCH_MP_TAC num_WF THEN X_GEN_TAC `k:num` THEN DISCH_TAC THEN
  MAP_EVERY X_GEN_TAC [`t:(A)spt`; `y:A`] THEN
  STRUCT_CASES_TAC (ISPEC `t:(A)spt` (cases_of `:(A)spt`)) THEN
  ONCE_REWRITE_TAC[insert_def] THEN REWRITE_TAC[lookup_def] THEN
  REWRITE_TAC[distinctness "option"] THEN
  COND_CASES_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  TRY (SOLVED (DISCH_THEN (fun th -> REWRITE_TAC[th]))) THEN
  DISCH_TAC THEN
  FIRST_ASSUM (fun ih ->
    if not (is_forall (concl ih)) then fail() else
    MP_TAC (SPEC `(k - 1) DIV 2` ih)) THEN
  FIRST_ASSUM (fun nz ->
    if not (is_neg (concl nz)) then fail() else
    REWRITE_TAC[MATCH_MP DIV2_SUB1_LESS nz]) THEN
  DISCH_THEN (fun ih ->
    FIRST_ASSUM (fun lk ->
      if not (hd_is "sptree_lookup" (lhs (concl lk))) then fail()
      else MP_TAC (MATCH_MP ih lk))) THEN
  COND_CASES_TAC THEN
  DISCH_THEN (fun th -> REWRITE_TAC[th])));;
(* the offsets and the count of a copy that goes through are
   within the two lists: copy_array is NONE otherwise *)
let copy_array_bounds = prove
 ((cake_as_vars (fun () ->
   `copy_array (xs,&xp) (&n) (SOME (ys,&yp)) = SOME ys1
    ==> xp + n <= LENGTH xs /\ yp + n <= LENGTH ys`)),
  (REWRITE_TAC[copy_array_def; I_THM; INT_OF_NUM_ADD; INT_ABS_NUM;
              NUM_OF_INT_OF_NUM; INT_OF_NUM_LT; LT] THEN
  COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN MATCH_REDUCE_TAC THEN
  COND_CASES_TAC THEN REWRITE_TAC[distinctness "option"] THEN
  POP_ASSUM MP_TAC THEN POP_ASSUM MP_TAC THEN ARITH_TAC));;
(* a byte array of the memory is shorter than the word size,
   which the header of it says (memory_rel_ByteArray_IMP) *)
let byte_array_LENGTH_LESS = prove
 ((cake_as_vars (fun () ->
   `memory_rel c be ts refs sp st m dm
      ((RefPtr bl p,(v:'a word_loc)) :: vars) /\
    lookup p refs = SOME (ByteArray fl vals) /\
    good_dimindex (:'a)
    ==> LENGTH vals < dimword (:'a)`)),
  (REWRITE_TAC[dimword] THEN
  DISCH_THEN (fun th ->
    MP_TAC (MATCH_MP memory_rel_ByteArray_IMP th) THEN
    MP_TAC (REWRITE_RULE[good_dimindex_def]
              (CONJUNCT2 (CONJUNCT2 th)))) THEN
  DISCH_THEN (DISJ_CASES_THEN SUBST1_TAC) THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  STRIP_TAC THEN ASM_ARITH_TAC));;
(* a comparison of two offsets as words is the one of the
   numbers, because both are below the word size *)
let n2w_LE_n2w = prove
 (`!a b. a < dimword (:'a) /\ b < dimword (:'a)
    ==> (((n2w a):'a word) <=+ n2w b <=> a <= b)`,
  (REWRITE_TAC[dimword] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_SIMP_TAC[WORD_ULE; VAL_WORD; MOD_LT]));;
(* and a copy of no bytes forward leaves the memory alone, as
   word_copy_bwd_0 above says of one backward *)
let word_copy_fwd_0 = prove
 ((cake_as_vars (fun () ->
   `good_dimindex (:'a) ==>
    word_copy_fwd be ((n2w 0):'a word) a1 a2 m dm = SOME m`)),
  (REWRITE_TAC[good_dimindex_def] THEN STRIP_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [word_copy_fwd_def] THEN
  ASM_REWRITE_TAC[dimword; WORD_ULT; VAL_WORD; VAL_WORD_0] THEN
  CONV_TAC NUM_REDUCE_CONV));;
(* the assumptions of the step that the lemmas are applied to *)
let the_mr asl =
    grab_asm (fun th -> hd_is "memory_rel" (concl th)) asl;;
let the_gd asl =
    grab_asm (fun th -> hd_is "good_dimindex" (concl th)) asl;;
let the_lkp p asl =
    grab_asm (fun th ->
      hd_is "sptree_lookup" (lhs (concl th)) &&
      lhand (lhs (concl th)) = p) asl;;
let the_eq h asl =
    grab_asm (fun th -> hd_is h (lhs (concl th))) asl;;
(* the count of the copy and an offset of it are below the word
   size, because the list they are of is *)
let ndw_of asl =
    let a1 = grab_asm (fun th ->
      hd_is "<=" (concl th) && hd_is "+" (lhand (concl th)) &&
      hd_is "LENGTH" (rand (concl th))) asl in
    let a2 = grab_asm (fun th ->
      hd_is "<" (concl th) && hd_is "LENGTH" (lhand (concl th))) asl in
    MATCH_MP (ARITH_RULE
      `!a b c d:num. a + b <= c /\ c < d ==> b < d`) (CONJ a1 a2);;
let off_lt t asl =
    let le = grab_asm (fun th ->
      hd_is "<=" (concl th) && hd_is "+" (lhand (concl th)) &&
      lhand (lhand (concl th)) = t &&
      hd_is "LENGTH" (rand (concl th))) asl in
    let l = rand (concl le) in
    let lt = grab_asm (fun th ->
      hd_is "<" (concl th) && lhand (concl th) = l) asl in
    MATCH_MP (ARITH_RULE `!a b c d:num. a + b <= c /\ c < d ==> a < d`)
      (CONJ le lt);;
(* the condition of word_copy_array is the one of list_copy *)
let COPY_COND =
    W(fun (asl,gl) ->
      let cnd = fst (dest_cond (lhs gl)) in
      let yp = rand (lhand cnd) in
      let xp = rand (rand cnd) in
      REWRITE_TAC[MP (ISPECL [yp; xp] n2w_LE_n2w)
                    (CONJ (off_lt yp asl) (off_lt xp asl))]);;
(* where there is nothing to copy no byte moves either way *)
let COPY_NOTHING =
    FIRST_ASSUM (fun d ->
      if not (is_disj (concl d)) then fail() else
      DISJ_CASES_THEN2
        (fun le -> W(fun (asl,gl) ->
           let ne = grab_asm (fun th ->
             is_neg (concl th) && hd_is "<=" (rand (concl th))) asl in
           ACCEPT_TAC (CONTR gl (MP (NOT_ELIM ne) le))))
        (fun z -> SUBST_ALL_TAC (MATCH_MP
           (ARITH_RULE `!a b:num. a + b = 0 ==> a = 0`) z))
        d) THEN
    W(fun (asl,gl) ->
      let gd = the_gd asl in
      let wcf = the_eq "word_copy_fwd" asl in
      let z = PART_MATCH lhs (MATCH_MP word_copy_fwd_0 gd)
                (lhs (concl wcf)) in
      let eq = REWRITE_RULE[injectivity "option"]
                 (TRANS (SYM wcf) z) in
      REWRITE_TAC[MATCH_MP word_copy_bwd_0 gd; eq]);;
(* the destination is above the source, so the copy of the step
   is the backward one *)
let COPY_NOT_FWD =
    W(fun (asl,gl) ->
      let nd = grab_asm (fun th ->
        is_neg (concl th) && is_disj (rand (concl th))) asl in
      let le = grab_asm (fun th ->
        hd_is "<=" (concl th) &&
        lhand (concl th) = lhand (lhand (rand (concl nd)))) asl in
      ACCEPT_TAC (CONTR gl (MP (NOT_ELIM nd)
        (DISJ1 le (rand (rand (concl nd)))))));;
(* and it starts at the last byte of the two parts *)
let COPY_BWD_ADDR =
    W(fun (asl,gl) ->
      let nd = grab_asm (fun th ->
        is_neg (concl th) && is_disj (rand (concl th))) asl in
      let ps = CONJUNCTS (REWRITE_RULE[DE_MORGAN_THM] nd) in
      let le1 = MATCH_MP (ARITH_RULE
        `!a b:num. ~(a + b = 0) ==> 1 <= b + a`) (el 1 ps) in
      let le2 = MATCH_MP (ARITH_RULE
        `!a b c:num. ~(a <= b) ==> 1 <= a + c`) (el 0 ps) in
      let wcb = the_eq "word_copy_bwd" asl in
      let ga = snd (strip_comb (lhs gl)) in
      let aa = snd (strip_comb (lhs (concl wcb))) in
      let hyps = mk_conj (concl le1, concl le2) in
      let adeq i =
        MP (prove (mk_imp (hyps, mk_eq (el i ga, el i aa)),
              DISCH_THEN (CONJUNCTS_THEN ASSUME_TAC) THEN
              ASM_SIMP_TAC[WORD_SUB; GSYM WORD_ADD] THEN
              CONV_TAC WORD_RULE))
           (CONJ le1 le2) in
      REWRITE_TAC[adeq 2; adeq 3]) THEN
    ASM_REWRITE_TAC[];;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_copy_array_thm = prove
 (cake_as_vars (fun () ->
    `!n xp yp xs ys ys1 m.
        memory_rel c be ts refs sp st m dm ((RefPtr bl1 p1,v1) ::
          (RefPtr bl2 p2,v2) :: vars) /\
        lookup p1 refs = SOME (ByteArray fl_xs xs) /\
        lookup p2 refs = SOME (ByteArray fl_ys ys) /\
        copy_array (xs,&xp) (&n) (SOME (ys,&yp)) = SOME ys1 /\
        good_dimindex (:'a) /\ ~(p1 = p2) ==>
        (?w1 (w2:'a word) a1 a2 m1.
          v1 = wordLang_Word w1 /\ v2 = wordLang_Word w2 /\
          get_real_addr c st w1 = SOME a1 /\
          get_real_addr c st w2 = SOME a2 /\
          word_copy_array be (n2w n) (a1 + bytes_in_word) (n2w xp)
            (a2 + bytes_in_word) (n2w yp) m dm = SOME m1 /\
          memory_rel c be ts (insert p2 (ByteArray fl_ys ys1) refs)
            sp st m1 dm ((RefPtr bl1 p1,v1) :: (RefPtr bl2 p2,v2)
              :: vars))`),
(* the copy of the two lists that the source and the destination
   hold (list_copy_thm), which goes forward when the destination is
   not above the source and backward from the end of it when it is.
   The condition of word_copy_array is that same one, because both
   offsets are below the word size (n2w_LE_n2w, with the bounds
   that copy_array_bounds and byte_array_LENGTH_LESS give).
     Where it goes forward word_copy_fwd_thm gives the memory and
   the invariant; where there is nothing to copy at all (the count
   and the offset of the source are both nought) the condition of
   the words may still be false, and then no byte moves either way
   (word_copy_fwd_0 and word_copy_bwd_0).  Where it goes backward
   word_copy_bwd_thm gives them, and the addresses of the loop are
   the last byte of each part: the count and the offset of the step
   add up to the one that the lemma takes (WORD_RULE, with the
   count and the offset of the source not both nought).
     The two lemmas of the loops are about the invariant with the
   destination written back as it stands, which is the invariant
   itself (insert_unchanged) *)
  ((let grab_asm p asl =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
  let keys asl =
    let mr = the_mr asl in
    let l = el 8 (snd (strip_comb (concl mr))) in
    (rand (lhand (lhand l)), rand (lhand (lhand (rand l)))) in
  let pre_w =
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM (fun ca ->
      if not (hd_is "copy_array" (lhs (concl ca))) then fail() else
      ASSUME_TAC (MATCH_MP list_copy_thm ca) THEN
      STRIP_ASSUME_TAC (MATCH_MP copy_array_bounds ca)) THEN
    W(fun (asl,gl) ->
      let mr = the_mr asl in
      let gd = the_gd asl in
      let p1,p2 = keys asl in
      let lk1 = the_lkp p1 asl in
      let lk2 = the_lkp p2 asl in
      let mr2 = MATCH_MP memory_rel_swap mr in
      MAP_EVERY ASSUME_TAC
        [MATCH_MP byte_array_LENGTH_LESS (CONJ mr (CONJ lk1 gd));
         MATCH_MP byte_array_LENGTH_LESS (CONJ mr2 (CONJ lk2 gd))]) in
  let mr_ins asl =
    let mr = the_mr asl in
    let p1,p2 = keys asl in
    let lk2 = the_lkp p2 asl in
    let iu = MATCH_MP insert_unchanged lk2 in
    let tm = subst [lhs (concl iu),
                    el 3 (snd (strip_comb (concl mr)))] (concl mr) in
    let _ = p1 in
    EQ_MP (SYM (REWRITE_CONV[iu] tm)) mr in
  let split_lc =
    FIRST_X_ASSUM (fun lc ->
      if not (hd_is "list_copy" (lhs (concl lc))) then fail() else
      MP_TAC (REWRITE_RULE[list_copy_def] lc)) THEN
    COND_CASES_TAC THEN DISCH_TAC in
  let wits =
    W(fun (asl,gl) ->
      let cs = conjuncts (snd (strip_exists gl)) in
      let v1t = lhs (el 0 cs) and v2t = lhs (el 1 cs) in
      let e1 = grab_asm (fun th ->
        is_eq (concl th) && lhs (concl th) = v1t) asl in
      let e2 = grab_asm (fun th ->
        is_eq (concl th) && lhs (concl th) = v2t) asl in
      let w1 = rand (rhs (concl e1)) in
      let w2 = rand (rhs (concl e2)) in
      let ga t = grab_asm (fun th ->
        hd_is "get_real_addr" (lhs (concl th)) &&
        rand (lhs (concl th)) = t) asl in
      let wc = grab_asm (fun th ->
        (hd_is "word_copy_fwd" (lhs (concl th)) ||
         hd_is "word_copy_bwd" (lhs (concl th)))) asl in
      MAP_EVERY EXISTS_TAC
        [w1; w2; rand (rhs (concl (ga w1)));
         rand (rhs (concl (ga w2))); rand (rhs (concl wc))]) in
  let use_fwd =
    W(fun (asl,gl) ->
      let p1,p2 = keys asl in
      let lk1 = the_lkp p1 asl in
      let gd = the_gd asl in
      let mri = mr_ins asl in
      let lcf = the_eq "list_copy_fwd" asl in
      let ndw = ndw_of asl in
      let ne = grab_asm (fun th ->
        is_neg (concl th) && is_eq (rand (concl th)) &&
        lhs (rand (concl th)) = p1) asl in
      MP_TAC (MATCH_MP word_copy_fwd_thm
        (CONJ mri (CONJ lk1 (CONJ lcf (CONJ gd (CONJ ndw ne))))))) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) in
  let use_bwd =
    W(fun (asl,gl) ->
      let p1,p2 = keys asl in
      let lk1 = the_lkp p1 asl in
      let gd = the_gd asl in
      let mri = mr_ins asl in
      let lcb = the_eq "list_copy_bwd" asl in
      let ndw = ndw_of asl in
      let ne = grab_asm (fun th ->
        is_neg (concl th) && is_eq (rand (concl th)) &&
        lhs (rand (concl th)) = p1) asl in
      MP_TAC (MATCH_MP word_copy_bwd_thm
        (CONJ mri (CONJ lk1 (CONJ lcb (CONJ gd (CONJ ndw ne))))))) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) in
  let fwd_branch2 =
    use_fwd THEN wits THEN
    ASM_REWRITE_TAC[word_copy_array_def] THEN
    COPY_COND THEN COND_CASES_TAC THENL
     [RULE_ASSUM_TRY (REWRITE_RULE[WORD_ADD_ASSOC]) THEN
      ASM_REWRITE_TAC[];
      COPY_NOTHING] in
  let bwd_branch =
    use_bwd THEN wits THEN
    ASM_REWRITE_TAC[word_copy_array_def] THEN
    COPY_COND THEN COND_CASES_TAC THENL
     [COPY_NOT_FWD; COPY_BWD_ADDR] in
  pre_w THEN split_lc THENL [fwd_branch2; bwd_branch])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_copy_array_alias_thm = prove
 (cake_as_vars (fun () ->
    `!n xp yp ys ys1 m.
        memory_rel c be ts refs sp st m dm ((RefPtr bl p2,v2) ::
          vars) /\
        lookup p2 refs = SOME (ByteArray fl_ys ys) /\
        copy_array (ys,&xp) (&n) (SOME (ys,&yp)) = SOME ys1 /\
        good_dimindex (:'a) ==>
        (?(w2:'a word) a2 m1.
          v2 = wordLang_Word w2 /\
          get_real_addr c st w2 = SOME a2 /\
          word_copy_array be (n2w n) (a2 + bytes_in_word) (n2w xp)
            (a2 + bytes_in_word) (n2w yp) m dm = SOME m1 /\
          memory_rel c be ts (insert p2 (ByteArray fl_ys ys1) refs)
            sp st m1 dm ((RefPtr bl p2,v2) :: vars))`),
(* as word_copy_array_thm above, with the source and the
   destination the same byte array: the copy is list_copy_alias
   (list_copy_alias_thm), the loops are word_copy_fwd_alias_thm and
   word_copy_bwd_alias_thm, and the steps are the ones that both
   proofs share *)
  ((let key1 asl =
    let mr = the_mr asl in
    rand (lhand (lhand (el 8 (snd (strip_comb (concl mr)))))) in
  let pre_a =
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM (fun ca ->
      if not (hd_is "copy_array" (lhs (concl ca))) then fail() else
      ASSUME_TAC (MATCH_MP list_copy_alias_thm ca) THEN
      STRIP_ASSUME_TAC (MATCH_MP copy_array_bounds ca)) THEN
    W(fun (asl,gl) ->
      let mr = the_mr asl in
      let gd = the_gd asl in
      let p = key1 asl in
      let lk = the_lkp p asl in
      ASSUME_TAC (MATCH_MP byte_array_LENGTH_LESS
        (CONJ mr (CONJ lk gd)))) in
  let mr_ins_a asl =
    let mr = the_mr asl in
    let lk = the_lkp (key1 asl) asl in
    let iu = MATCH_MP insert_unchanged lk in
    let tm = subst [lhs (concl iu),
                    el 3 (snd (strip_comb (concl mr)))] (concl mr) in
    EQ_MP (SYM (REWRITE_CONV[iu] tm)) mr in
  let split_la =
    FIRST_X_ASSUM (fun lc ->
      if not (hd_is "list_copy_alias" (lhs (concl lc))) then fail()
      else MP_TAC (REWRITE_RULE[list_copy_alias_def] lc)) THEN
    COND_CASES_TAC THEN DISCH_TAC in
  let wits1 =
    W(fun (asl,gl) ->
      let cs = conjuncts (snd (strip_exists gl)) in
      let v2t = lhs (el 0 cs) in
      let e2 = grab_asm (fun th ->
        is_eq (concl th) && lhs (concl th) = v2t) asl in
      let w2 = rand (rhs (concl e2)) in
      let ga = grab_asm (fun th ->
        hd_is "get_real_addr" (lhs (concl th)) &&
        rand (lhs (concl th)) = w2) asl in
      let wc = grab_asm (fun th ->
        (hd_is "word_copy_fwd" (lhs (concl th)) ||
         hd_is "word_copy_bwd" (lhs (concl th)))) asl in
      MAP_EVERY EXISTS_TAC
        [w2; rand (rhs (concl ga)); rand (rhs (concl wc))]) in
  let use_fwd_a =
    W(fun (asl,gl) ->
      let gd = the_gd asl in
      let mri = mr_ins_a asl in
      let lcf = the_eq "list_copy_fwd_alias" asl in
      let ndw = ndw_of asl in
      MP_TAC (MATCH_MP word_copy_fwd_alias_thm
        (CONJ mri (CONJ lcf (CONJ gd ndw))))) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) in
  let use_bwd_a =
    W(fun (asl,gl) ->
      let gd = the_gd asl in
      let mri = mr_ins_a asl in
      let lcb = the_eq "list_copy_bwd_alias" asl in
      let ndw = ndw_of asl in
      MP_TAC (MATCH_MP word_copy_bwd_alias_thm
        (CONJ mri (CONJ lcb (CONJ gd ndw))))) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) in
  let fwd_a =
    use_fwd_a THEN wits1 THEN
    ASM_REWRITE_TAC[word_copy_array_def] THEN
    COPY_COND THEN COND_CASES_TAC THENL
     [RULE_ASSUM_TRY (REWRITE_RULE[WORD_ADD_ASSOC]) THEN
      ASM_REWRITE_TAC[];
      COPY_NOTHING] in
  let bwd_a =
    use_bwd_a THEN wits1 THEN
    ASM_REWRITE_TAC[word_copy_array_def] THEN
    COPY_COND THEN COND_CASES_TAC THENL
     [COPY_NOT_FWD; COPY_BWD_ADDR] in
  pre_a THEN split_la THENL [fwd_a; bwd_a])));;

let word_of_byte_0 = prove
 (`word_of_byte (n2w 0) = (n2w 0)`,
  (REWRITE_TAC[word_of_byte_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   COND_CASES_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_OR; BIT_WORD_SHL;
               BIT_WORD_0]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let last_bytes_0 = prove
 (cake_as_vars (fun () ->
    `!nb a. last_bytes nb (n2w 0) a (n2w 0) be = (n2w 0)`),
  (* the bytes of zero written into zero leave zero: a byte set to
     zero in a word of zeroes is an or of words with no bit *)
  (let sb0 = prove
    (`!a be. set_byte a (n2w 0) (n2w 0:(N)word) be = n2w 0`,
     REPEAT GEN_TAC THEN REWRITE_TAC[set_byte_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     REWRITE_TAC[word_slice_alt; WORD_EQ_BITS_ALT; BIT_WORD_OR;
                 BIT_WORD_SHL; BIT_WORD_0; BIT_WORD_SUBWORD;
                 BIT_WORD_ZX] THEN
     REWRITE_TAC[BIT_WORD_0]) in
   INDUCT_TAC THEN GEN_TAC THEN
   ONCE_REWRITE_TAC[last_bytes_def] THEN
   REWRITE_TAC[ARITH_RULE `~(SUC n = 0)`] THEN
   ASM_REWRITE_TAC[ARITH_RULE `SUC n - 1 = n`; sb0]));;

(* [simp] *)
let LUPDATE_REPLICATE = prove
 (`!n a. LUPDATE x a (REPLICATE n x) = REPLICATE n x`,
  (INDUCT_TAC THEN GEN_TAC THEN REWRITE_TAC[REPLICATE; LUPDATE] THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[]));;

(* HOL4 data_to_word_memoryProofScript.sml:16179-16183: ML code, not
   ported *)

(* the port's own: that the address of a value does not change
   when the store's NextFree does (get_real_addr reads CurrHeap
   only), and that a byte array that fits in the heap is shorter
   than the word size, which is the one arithmetic step of HOL4's
   impl_tac here *)

let get_real_addr_update = prove
 (`!w. get_real_addr conf (st |+ (NextFree,x)) (w:'a word) =
      get_real_addr conf st w`,
  REWRITE_TAC[get_real_addr_def; FLOOKUP_UPDATE;
              distinctness "store_name";
              GSYM (distinctness "store_name")]);;

let byte_len_bound = prove
 (`good_dimindex (:'a) /\
  byte_len (:'a) n < 2 EXP (dimindex (:'a) - 4)
  ==> n < dimword (:'a)`,
  REWRITE_TAC[good_dimindex_def; byte_len_def; dimword] THEN
  STRIP_TAC THEN
  FIRST_X_ASSUM (fun dd ->
    if is_eq (concl dd) then SUBST_ALL_TAC dd else fail()) THEN
  RULE_ASSUM_TAC (CONV_RULE NUM_REDUCE_CONV o REWRITE_RULE[]) THEN
  REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
  MP_TAC (SPECL [`n:num`; `4`] DIVISION) THEN
  MP_TAC (SPECL [`n:num`; `8`] DIVISION) THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  ASM_ARITH_TAC);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_copy_array_NONE = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm ((RefPtr bl p1,(v1:'a word_loc))
  :: vars) /\ ~(new IN (domain refs)) /\
      lookup p1 refs = SOME (ByteArray fl_xs xs) /\
      copy_array (xs,&xp) (&n) NONE = SOME ys /\
      byte_len (:'a) n < sp /\ byte_len (:'a) n < 2 EXP (dimindex
        (:'a) - 4) /\
      byte_len (:'a) n < 2 EXP data_to_word_config_len_size c /\
        good_dimindex (:'a) ==>
      (?free' curr a1 a2 m1 m2 w1 w2.
        v1 = wordLang_Word w1 /\
        get_real_addr c st w1 = SOME a1 /\
        make_ptr c (free' - curr) (n2w 0) (byte_len (:'a) n) =
          wordLang_Word w2 /\
        get_real_addr c st w2 = SOME a2 /\
        FLOOKUP st NextFree = SOME (wordLang_Word free') /\
        FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
        data_to_word_memoryProof_store_list free'
          (wordLang_Word (make_byte_header c fl n) ::
               REPLICATE (byte_len (:'a) n) (wordLang_Word (n2w
                 0))) m dm = SOME m1 /\
        word_copy_fwd be (n2w n) (a1 + bytes_in_word + n2w xp)
          (a2 + bytes_in_word) m1 dm = SOME m2 /\
        memory_rel c be ts (insert new (ByteArray fl ys) refs)
         (sp - (byte_len (:'a) n + 1))
         (st |+ (NextFree,
                 wordLang_Word (free' + bytes_in_word * n2w
                   (byte_len (:'a) n + 1)))) m2 dm
         ((RefPtr T new,wordLang_Word w2) :: vars))`),
(* the lemma of the source is memory_rel_RefByte_alt at a zero
   byte, where the bytes the new array is made of are all zero
   (word_of_byte_0, last_bytes_0, LUPDATE_REPLICATE), and the one
   thing to watch is that the type of the pointer's lower bits is a
   type variable of the statement, so the lemma has to be
   instantiated at it before its conclusion will match.  After it
   the new array goes in front of the old one (memory_rel_swap),
   copy_array_NONE_IMP turns the copy into the one of the word
   level, word_copy_fwd_thm does it, and what is left is the same
   list of pairs in another order *)
  ((* the lemma of the source is memory_rel_RefByte_alt at a zero
     byte, where the bytes it writes are all zero *)
  let refbyte_zero =
    REWRITE_RULE[WORD_ZX_0; word_of_byte_0; last_bytes_0;
                 LUPDATE_REPLICATE]
      (CONV_RULE (TOP_DEPTH_CONV let_CONV)
         (INST [`n2w 0:word8`, `w:word8`]
            memory_rel_RefByte_alt)) in
  let hd_of n t =
    (try fst (dest_const (fst (strip_comb t))) = n
     with Failure _ -> false) in
  STRIP_TAC THEN
  W(fun (asl,gw as gl) ->
    let mr = the_asm (fun c ->
               try length (snd (strip_comb c)) = 9 && not (is_eq c)
               with Failure _ -> false) gl in
    let lst = last (snd (strip_comb (concl mr))) in
    let tyof t = hd (snd (dest_type (type_of (el 2 (snd (strip_comb
                   (find_term (hd_of "make_ptr") t))))))) in
    let th = INST_TYPE [tyof gw, tyof (concl refbyte_zero)]
               refbyte_zero in
    let ant = lhand (concl th) in
    let vv = last (snd (strip_comb (hd (conjuncts ant)))) in
    MP_TAC (INST [lst, vv] th)) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the new array in front of the old one, the copy of the source
     into the zeroes it holds, and the two things the word level
     asks of the lengths *)
  FIRST_ASSUM (fun mr ->
    if (try let args = snd (strip_comb (concl mr)) in
            length args = 9 && not (is_var (el 3 args))
        with Failure _ -> false)
    then ASSUME_TAC (MATCH_MP memory_rel_swap mr) else fail()) THEN
  FIRST_ASSUM (fun ca ->
    ASSUME_TAC (MATCH_MP copy_array_NONE_IMP ca)) THEN
  SUBGOAL_THEN `~((p1:num) = new)` ASSUME_TAC THENL
   [W(fun gl ->
      let nd = the_asm (fun c ->
                 try is_neg c &&
                     fst (dest_const (rator (rator (rand c)))) =
                     "IN"
                 with Failure _ -> false) gl in
      let lk = the_asm (fun c ->
                 try is_eq c &&
                     fst (dest_const (fst (strip_comb (rand (rand
                       c))))) = "bvlSem_ByteArray"
                 with Failure _ -> false) gl in
      MESON_TAC[nd; lk; domain_lookup]);
    ALL_TAC] THEN
  SUBGOAL_THEN `n < dimword (:'a)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[byte_len_bound]; ALL_TAC] THEN
  (* the copy of the source into the zeroes of the new array *)
  W(fun (asl,gw as gl) ->
    let mr = the_asm (fun c ->
               try let a = snd (strip_comb c) in
                   length a = 9 && not (is_var (el 3 a))
               with Failure _ -> false) gl in
    let lk = the_asm (fun c ->
               try is_eq c &&
                   fst (dest_const (fst (strip_comb (rand (rand
                     c))))) = "bvlSem_ByteArray"
               with Failure _ -> false) gl in
    let lc = the_asm (fun c ->
               try is_eq c &&
                   length (snd (strip_comb (lhs c))) = 5
               with Failure _ -> false) gl in
    let gd = the_asm (fun c -> c = `good_dimindex (:'a)`) gl in
    let nd = the_asm (fun c ->
               try rand c = `dimword (:'a)` && not (is_eq c)
               with Failure _ -> false) gl in
    let pn = the_asm (fun c ->
               try is_neg c && is_eq (rand c)
               with Failure _ -> false) gl in
    STRIP_ASSUME_TAC (MATCH_MP word_copy_fwd_thm
      (CONJ mr (CONJ lk (CONJ lc (CONJ gd (CONJ nd pn))))))) THEN
  (* and then every piece of the statement is an assumption *)
  W(fun (asl,gw as gl) ->
    let wof v = rand (rand (concl (the_asm (fun c ->
                  try is_eq c && lhs c = v with Failure _ -> false)
                  gl))) in
    let som p = rand (rand (concl (the_asm (fun c ->
                  try is_eq c && p (lhs c) with Failure _ -> false)
                  gl))) in
    let w1 = wof (var_by_name "v1" gl) in
    let w2 = wof (the_asm (fun c ->
               try is_eq c && hd_of "make_ptr" (lhs c)
               with Failure _ -> false) gl |> concl |> lhs) in
    MAP_EVERY EXISTS_TAC
      [rand (som (fun t -> hd_of "FLOOKUP" t &&
               fst (dest_const (rand t)) = "NextFree"));
       rand (som (fun t -> hd_of "FLOOKUP" t &&
               fst (dest_const (rand t)) = "CurrHeap"));
       som (fun t -> hd_of "get_real_addr" t &&
              last (snd (strip_comb t)) = w1);
       som (fun t -> hd_of "get_real_addr" t &&
              last (snd (strip_comb t)) = w2);
       som (fun t -> hd_of "data_to_word_memoryProof_store_list" t);
       som (fun t -> hd_of "word_copy_fwd" t);
       w1; w2]) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[get_real_addr_update;
                               WORD_ADD_0]) THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM (fun mr ->
    if (try length (snd (strip_comb (concl mr))) = 9 &&
            not (is_eq (concl mr))
        with Failure _ -> false)
    then MP_TAC mr else fail()) THEN
  MATCH_MP_TAC memory_rel_rearrange THEN
  ASM_REWRITE_TAC[MEM] THEN MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let write_bytearray_isWord = prove
 (cake_as_vars (fun () ->
    `!ls a m x.
     isWord (m x) ==>
     isWord (write_bytearray a ls m dm be x)`),
  (* writing bytes leaves a word a word: the write either updates
     the address with a word or leaves the memory alone *)
  (let isw = prove
    (`!w. isWord (wordLang_Word w)`,
     GEN_TAC THEN REWRITE_TAC[isWord_def] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[]) in
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THENL
    [REWRITE_TAC[write_bytearray_def] THEN
     FIRST_ASSUM ACCEPT_TAC;
     REWRITE_TAC[write_bytearray_def;
                 mem_store_byte_aux_def] THEN
     EVERY_CASE_TAC THEN
     POP_ASSUM MP_TAC THEN COND_CASES_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
     DISCH_THEN(SUBST1_TAC o SYM) THEN
     REWRITE_TAC[UPDATE] THEN
     COND_CASES_TAC THEN REWRITE_TAC[isw] THEN
     FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]));;

let write_bytearray_append = prove
 (`!xs ys a m dm be'.
     (!i. i < LENGTH xs + LENGTH ys ==>
          (?b. mem_load_byte_aux m dm be' (a + n2w i) = SOME b)) ==>
     write_bytearray a (xs ++ ys) m dm be' =
     write_bytearray a xs (write_bytearray (a + n2w (LENGTH xs)) ys
       m dm be') dm be'`,
  (* the induction of the source: the load of the first byte, which
     the hypothesis of the statement gives, makes the store of that
     byte go through, and the induction hypothesis rewrites the
     writes of the rest *)
  (let addr_shift = prove
    (`!(a:'a word) n. (a + n2w 1) + n2w n = a + n2w (n + 1)`,
     REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE) in
   let store_ok = prove
    (`!m dm be' a b.
        mem_load_byte_aux m dm be' a = SOME b ==>
        (!a2 ls x. ?mm.
           mem_store_byte_aux (write_bytearray a2 ls m dm be')
             dm be' a x = SOME mm)`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
     RULE_ASSUM_TAC(REWRITE_RULE[mem_load_byte_aux_def]) THEN
     (* the byte is in a word of the memory, inside the domain *)
     W(fun g ->
       let sc = in_goal g (fun t ->
         is_comb t && hd_is "byte_align" (rand t) &&
         is_var (rator t)) in
       CASES_ON_TAC sc) THEN
     RULE_ASSUM_TRY (CONV_RULE(REDEPTH_CONV MATCH_CONV)) THEN
     RULE_ASSUM_TRY (REWRITE_RULE[distinctness "option"]) THEN
     TRY(FIRST_ASSUM CONTR_TAC) THEN
     (* so the writes leave a word there, and the store of the
        byte goes through *)
     W(fun g ->
       let wb = in_goal g (hd_is "write_bytearray") in
       let ba = in_goal g (hd_is "byte_align") in
       SUBGOAL_THEN (list_mk_icomb "isWord" [mk_comb(wb,ba)])
         MP_TAC THENL
        [MATCH_MP_TAC (GEN_ALL write_bytearray_isWord) THEN
         ASM_REWRITE_TAC[isWord_def] THEN
         TRY MATCH_REDUCE_TAC THEN REWRITE_TAC[];
         ALL_TAC]) THEN
     REWRITE_TAC[isWord_def; mem_store_byte_aux_def] THEN
     W(fun g ->
       let sc = in_goal g (fun t ->
         is_comb t && hd_is "byte_align" (rand t) &&
         hd_is "write_bytearray" (rator t)) in
       CASES_ON_TAC sc) THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[] THEN
     ASM_REWRITE_TAC[] THEN
     COND_CASES_TAC THEN
     TRY(FIRST_ASSUM(fun neg ->
       if not (is_neg (concl neg)) then fail() else
       RULE_ASSUM_TAC(REWRITE_RULE[neg;
         distinctness "option"]))) THEN
     TRY(FIRST_ASSUM CONTR_TAC) THEN
     REWRITE_TAC[injectivity "option"] THEN
     MESON_TAC[]) in
   (* the induction hypothesis is the assumption that concludes an
      equation, the hypothesis of the statement the one that
      concludes a load *)
   let find_ih asl =
     snd (find (fun (_,th) ->
       let b = snd(strip_forall(concl th)) in
       is_imp b && is_eq (rand b)) asl) in
   let find_hyp asl =
     snd (find (fun (_,th) ->
       let b = snd(strip_forall(concl th)) in
       is_imp b && is_exists (rand b)) asl) in
   LIST_INDUCT_TAC THEN
   REWRITE_TAC[APPEND; write_bytearray_def; LENGTH; WORD_ADD_0;
               ADD1] THEN
   REPEAT GEN_TAC THEN DISCH_TAC THEN
   (* the load at the first byte, which is the hypothesis at 0 *)
   W(fun (asl,w) ->
     let hyp = find_hyp asl in
     let sp = SPEC `0` hyp in
     SUBGOAL_THEN (lhand (concl sp)) (fun th ->
       MP_TAC (MP sp th)) THENL
      [ARITH_TAC; ALL_TAC]) THEN
   DISCH_THEN CHOOSE_TAC THEN
   RULE_ASSUM_TRY (REWRITE_RULE[WORD_ADD_0]) THEN
   (* so the store of that byte, over the writes of both sides,
      goes through *)
   W(fun (asl,w) ->
     let lo = snd (find (fun (_,th) ->
       is_eq (concl th) &&
       hd_is "mem_load_byte_aux" (lhs (concl th))) asl) in
     let s = find_term (hd_is "mem_store_byte_aux") w in
     let args = snd (strip_comb s) in
     let wargs = snd (strip_comb (hd args)) in
     STRIP_ASSUME_TAC (SPECL [el 0 wargs; el 1 wargs; el 4 args]
                         (MATCH_MP store_ok lo))) THEN
   (* and the induction hypothesis rewrites the writes of the
      rest, with the hypothesis shifted by one byte *)
   W(fun (asl,w) ->
     let ih = find_ih asl in
     let inst = find_term (fun tm ->
       hd_is "write_bytearray" tm &&
       (let args = snd(strip_comb tm) in
        length args = 5 && hd_is "APPEND" (el 1 args))) w in
     let ih' = PART_MATCH (lhs o rand) ih inst in
     SUBGOAL_THEN (lhand (concl ih')) (fun p ->
       SUBST_ALL_TAC (MATCH_MP ih' p)) THENL
      [GEN_TAC THEN DISCH_TAC THEN
       W(fun (asl,w) ->
         let hyp = find_hyp asl in
         (* n2w is the port's name of HOL Light's word *)
         let iv = rand (find_term (fun tm ->
           hd_is "word" tm && is_var (rand tm)) w) in
         let sp = SPEC (mk_binop `(+):num->num->num` iv `1`) hyp in
         SUBGOAL_THEN (lhand (concl sp)) (fun th ->
           MP_TAC (MP sp th)) THENL
          [ASM_ARITH_TAC; ALL_TAC]) THEN
       REWRITE_TAC[addr_shift];
       ALL_TAC]) THEN
   RULE_ASSUM_TRY (REWRITE_RULE[addr_shift]) THEN
   ASM_REWRITE_TAC[addr_shift] THEN
   MATCH_REDUCE_TAC THEN REWRITE_TAC[]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_write_bytearray_lemma = prove
 (cake_as_vars (fun () ->
    `!rest bytes bytes0 m refs.
       memory_rel c be stm refs sp st m dm ((RefPtr b
         n,wordLang_Word (w:'a word)) :: vs) /\
       lookup n refs = SOME (ByteArray F (bytes0 ++ rest)) /\
         LENGTH bytes = LENGTH bytes0 /\
       get_real_simple_addr c st w = SOME a /\ good_dimindex (:'a)
         ==>
       memory_rel c be stm (insert n (ByteArray F (bytes ++ rest))
         refs) sp st
         (write_bytearray (a + bytes_in_word) bytes m dm be)
         dm ((RefPtr b n,wordLang_Word w) :: vs)`),
(* the induction of the source, from the right on the bytes that
   are written (SNOC_INDUCT): where there are none the memory and
   the references stand as they are (insert_unchanged), and the
   step writes the last byte first and the rest after
   (write_bytearray_append, whose condition is that every byte of
   the part can be read, which memory_rel_ByteArray_IMP gives).
     The write of that one byte is a store of it
   (memory_rel_ByteArray_IMP_store at the index of the last byte,
   which is the length of the part that is left), and it leaves
   the byte array with that byte in place (LUPDATE_LENGTH).  The
   hypothesis of the induction then writes the rest into it, with
   the byte that was just written as the front of what stays, and
   the two stores into the references are one (insert_insert_same) *)
  ((let the_loads asl =
    grab_asm (fun th ->
      is_forall (concl th) &&
      can (find_term (fun t ->
        hd_is "mem_load_byte_aux" t)) (concl th)) asl in
  let the_leq asl =
    MATCH_MP (ARITH_RULE `!a b:num. a + 1 = b + SUC 0 ==> a = b`)
      (grab_asm (fun th ->
         is_eq (concl th) && hd_is "+" (lhs (concl th)) &&
         rand (lhs (concl th)) = `1`) asl) in
  let setupb =
    GEN_REWRITE_TAC I [SWAP_FORALL_THM] THEN
    MATCH_MP_TAC SNOC_INDUCT THEN CONJ_TAC in
  let baseb =
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM (fun le ->
      if not (is_eq (concl le)) ||
         not (hd_is "LENGTH" (lhs (concl le))) then fail() else
       SUBST_ALL_TAC
         (REWRITE_RULE[LENGTH; LENGTH_EQ_NIL] (SYM le))) THEN
    REWRITE_TAC[write_bytearray_def; APPEND] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[APPEND]) THEN
    FIRST_ASSUM (fun lk ->
      if not (hd_is "sptree_lookup" (lhs (concl lk))) then fail() else
      REWRITE_TAC[MATCH_MP insert_unchanged lk]) THEN
    FIRST_ASSUM ACCEPT_TAC in
  let stepb1 =
    REPEAT GEN_TAC THEN DISCH_THEN (LABEL_TAC "bih") THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    (* the list that is written over is as long, so it has a last
       byte too *)
    FIRST_ASSUM (fun le ->
      if not (is_eq (concl le)) ||
         not (hd_is "LENGTH" (lhs (concl le))) then fail() else
      MP_TAC (REWRITE_RULE[LENGTH_SNOC] le)) THEN
    DISCH_TAC THEN
    W(fun (asl,gl) ->
      let le = grab_asm (fun th ->
        is_eq (concl th) && hd_is "+" (lhs (concl th))) asl in
      MP_TAC (MATCH_MP SNOC_CASES
        (REWRITE_RULE[LENGTH_EQ_NIL]
          (MATCH_MP (ARITH_RULE
            `!a b:num. a + 1 = b ==> ~(b = 0)`) le)))) THEN
    DISCH_THEN (X_CHOOSE_THEN `lb:word8`
      (X_CHOOSE_THEN `l0:word8 list` SUBST_ALL_TAC)) THEN
    RULE_ASSUM_TRY (REWRITE_RULE[SNOC_APPEND; LENGTH_APPEND;
                                  LENGTH; GSYM APPEND_ASSOC;
                                  APPEND]) THEN
    REWRITE_TAC[SNOC_APPEND; GSYM APPEND_ASSOC; APPEND] in
  let loadsb =
    W(fun (asl,gl) ->
      let mr = grab_asm (fun th ->
        hd_is "memory_rel" (concl th)) asl in
      let lk = grab_asm (fun th ->
        hd_is "sptree_lookup" (lhs (concl th))) asl in
      let gd = grab_asm (fun th ->
        hd_is "good_dimindex" (concl th)) asl in
      MP_TAC (MATCH_MP memory_rel_ByteArray_IMP
                (CONJ mr (CONJ lk gd)))) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
    (* the root of the reference and the address of the lemma are
       the ones of the statement *)
    FIRST_ASSUM (fun we ->
      if not (is_eq (concl we)) ||
         not (hd_is "wordLang_Word" (lhs (concl we))) then fail() else
       SUBST_ALL_TAC
         (SYM (REWRITE_RULE[injectivity "word_loc"] we))) THEN
    W(fun (asl,gl) ->
      let gs = filter (fun (_,th) ->
        (try hd_is "get_real_simple_addr" (lhs (concl th))
         with Failure _ -> false)) asl in
      SUBST_ALL_TAC (REWRITE_RULE[injectivity "option"]
        (TRANS (SYM (snd (el 0 gs))) (snd (el 1 gs))))) in
  let writeb =
    W(fun (asl,gl) ->
      let wb = find_term (fun t ->
        hd_is "write_bytearray" t &&
        hd_is "APPEND" (el 1 (snd (strip_comb t)))) gl in
      let args = snd (strip_comb wb) in
      let ap = el 1 args in
      let inst = ISPECL [lhand ap; rand ap; el 0 args; el 2 args;
                          el 3 args; el 4 args]
                       write_bytearray_append in
      SUBGOAL_THEN (lhand (concl inst)) (fun h ->
        REWRITE_TAC[MP inst h]) THENL
       [GEN_TAC THEN DISCH_TAC THEN
        REWRITE_TAC[GSYM WORD_ADD_ASSOC] THEN
        W(fun (asl,gl) ->
          let lt = grab_asm (fun th -> hd_is "<" (concl th)) asl in
          MP_TAC (SPEC (lhand (concl lt)) (the_loads asl))) THEN
        ANTS_TAC THENL
         [W(fun (asl,gl) ->
            let lt = grab_asm (fun th -> hd_is "<" (concl th)) asl in
            let le = grab_asm (fun th ->
              is_eq (concl th) && hd_is "+" (lhs (concl th))) asl in
            MP_TAC (REWRITE_RULE[LENGTH] lt) THEN MP_TAC le) THEN
          REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN ARITH_TAC;
          DISCH_THEN (fun th ->
            EXISTS_TAC (rand (rhs (concl th))) THEN ACCEPT_TAC th)];
        ALL_TAC]) in
  let storeb =
    (* the write of the last byte is the store of it, which goes
       through because the load of it does *)
    REWRITE_TAC[write_bytearray_def] THEN
     W(fun (asl,gl) ->
       REWRITE_TAC[the_leq asl; GSYM WORD_ADD_ASSOC]) THEN
    W(fun (asl,gl) ->
      let mr = grab_asm (fun th ->
        hd_is "memory_rel" (concl th)) asl in
      let lk = grab_asm (fun th ->
        hd_is "sptree_lookup" (lhs (concl th))) asl in
      let gd = grab_asm (fun th ->
        hd_is "good_dimindex" (concl th)) asl in
      let gra = grab_asm (fun th ->
        hd_is "get_real_addr" (lhs (concl th))) asl in
      let vals = rand (rand (rhs (concl lk))) in
      let lt = prove (mk_binop `(<):num->num->bool`
                        (mk_icomb (`LENGTH`, lhand vals))
                        (mk_icomb (`LENGTH`, vals)),
                      REWRITE_TAC[LENGTH_APPEND; LENGTH] THEN
                      ARITH_TAC) in
      let inst = MATCH_MP memory_rel_ByteArray_IMP_store
                   (CONJ mr (CONJ lk (CONJ gd (CONJ gra lt)))) in
      let ins = find_term (fun t -> hd_is "sptree_insert" t) gl in
      let arr = rand (el 1 (snd (strip_comb ins))) in
      let xb = lhand (rand arr) in
      MP_TAC (INST [xb, mk_var("b", type_of xb)] inst)) THEN
    DISCH_THEN (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
    W(fun (asl,gl) ->
      let se = grab_asm (fun th ->
        hd_is "mem_store_byte_aux" (lhs (concl th))) asl in
      REWRITE_TAC[se]) THEN
    MATCH_REDUCE_TAC THEN
    RULE_ASSUM_TRY (REWRITE_RULE[LUPDATE_LENGTH]) in
  let finishb =
    W(fun (asl,gl) ->
      let mr1 = grab_asm (fun th ->
        hd_is "memory_rel" (concl th) &&
        hd_is "sptree_insert" (el 3 (snd (strip_comb (concl th))))) asl
        in
      let ins = el 3 (snd (strip_comb (concl mr1))) in
      let args = snd (strip_comb ins) in
      let lk1 = REWRITE_RULE[]
        (ISPECL [el 0 args; el 0 args; el 1 args; el 2 args]
           lookup_insert) in
      let gsa = grab_asm (fun th ->
        hd_is "get_real_simple_addr" (lhs (concl th))) asl in
      let gd = grab_asm (fun th ->
        hd_is "good_dimindex" (concl th)) asl in
      USE_THEN "bih" (fun ih ->
        MATCH_ACCEPT_TAC (REWRITE_RULE[insert_insert_same]
          (MATCH_MP ih (CONJ mr1 (CONJ lk1
            (CONJ (the_leq asl) (CONJ gsa gd)))))))) in
  setupb THENL
   [baseb;
    stepb1 THEN loadsb THEN writeb THEN storeb THEN
    finishb])));;

(* HOL4 data_to_word_memoryProofScript.sml:16298-16299: a theorem
   that HOL4 states as the value of an ML expression:
   memory_rel_write_bytearray *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_space_max = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs old_sp st m dm vars ==>
      (?next_free trig_gc sp.
        FLOOKUP st NextFree = SOME (wordLang_Word next_free) /\
        FLOOKUP st TriggerGC = SOME (wordLang_Word trig_gc) /\
        trig_gc - next_free = bytes_in_word * (n2w sp:'a word) /\
          old_sp <= sp /\
        memory_rel c be ts refs sp st m dm vars /\
        (good_dimindex (:'a) ==> (dimindex (:'a) DIV 8) * sp <
          dimword (:'a)))`),
  (* the space of the statement is the sp of the invariant itself:
     the store's NextFree and TriggerGC are the two ends of it, so
     their difference is the bytes in a word times it, and what is
     left to see is that it fits in a word, which the heap's own
     bound gives because the unused space is part of the heap *)
  (let hd_is n t =
   (try fst(dest_const(fst(strip_comb t))) = n
    with Failure _ -> false) in
 let grab asl p =
   tryfind (fun (_,th) ->
     if (try p th with Failure _ -> false) then th else fail())
     asl in
   DISCH_TAC THEN
   FIRST_ASSUM(fun mr ->
     if hd_is "memory_rel" (concl mr)
     then MP_TAC(REWRITE_RULE[memory_rel_def] mr)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_ASSUM(fun hm ->
     if hd_is "heap_in_memory_store" (concl hm)
     then MP_TAC(REWRITE_RULE[heap_in_memory_store_def] hm)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   W(fun (asl,w) ->
     let look n = grab asl (fun th ->
       hd_is "FLOOKUP" (lhs (concl th)) &&
       fst(dest_const(rand(lhs(concl th)))) = n) in
     let hm = grab asl (fun th ->
       hd_is "heap_in_memory_store" (concl th)) in
     let args = snd(strip_comb (concl hm)) in
     EXISTS_TAC (rand (rand (rhs (concl (look "NextFree"))))) THEN
     EXISTS_TAC (rand (rand (rhs (concl (look "TriggerGC"))))) THEN
     EXISTS_TAC (el 2 args) THEN
     ASM_REWRITE_TAC[] THEN
     REPEAT CONJ_TAC THENL
      [REWRITE_TAC[GSYM WORD_ADD] THEN CONV_TAC WORD_RULE;
       REWRITE_TAC[memory_rel_def] THEN
       EXISTS_TAC (el 0 args) THEN EXISTS_TAC (el 9 args) THEN
       EXISTS_TAC (el 1 args) THEN EXISTS_TAC (el 2 args) THEN
       EXISTS_TAC (el 3 args) THEN EXISTS_TAC (el 4 args) THEN
       ASM_REWRITE_TAC[LE_REFL];
       DISCH_TAC THEN
       FIRST_ASSUM(fun wm ->
         if hd_is "word_ml_inv" (concl wm)
         then MP_TAC(REWRITE_RULE[word_ml_inv_def;
                                  abs_ml_inv_def;
                                  unused_space_inv_def] wm)
         else fail()) THEN
       DISCH_THEN STRIP_ASSUME_TAC THEN
       W(fun (asl,w) ->
         let hb = grab asl (fun th ->
           hd_is "<" (concl th) && hd_is "*" (lhand (concl th)) &&
           hd_is "+" (lhand (lhand (concl th)))) in
         TRANS_TAC LET_TRANS (lhand (concl hb))) THEN
       ASM_REWRITE_TAC[] THEN
       GEN_REWRITE_TAC LAND_CONV [MULT_SYM] THEN
       REWRITE_TAC[LE_MULT_RCANCEL] THEN DISJ1_TAC THEN
       W(fun (asl,w) ->
         let us = grab asl (fun th ->
           hd_is "<=" (concl th) && hd_is "+" (lhand (concl th))) in
         UNDISCH_TAC (concl us)) THEN
       ARITH_TAC])));;

let get_lowerbits_ptrbits = prove
 (`get_lowerbits c (wordLang_Word (ptr_bits c x y)) = (ptr_bits c x y
  || (n2w 1))`,
  (* the bits of ptr_bits are below small_shift_length (that is what
     maxout_bits_IMP says of each of the two), so the word_bits of
     it is itself *)
  (let mb = REWRITE_RULE[word_index] maxout_bits_IMP in
   let bits_lt = prove
    (`!i. i < dimindex (:'a) /\ bit i (ptr_bits c x y:'a word)
          ==> i < small_shift_length c`,
     REWRITE_TAC[ptr_bits_def; small_shift_length_def;
                 BIT_WORD_OR] THEN
     REPEAT STRIP_TAC THEN
     FIRST_X_ASSUM(fun th ->
       MP_TAC(MATCH_MP mb
         (CONJ (ASSUME `i < dimindex (:'a)`) th))) THEN
     ARITH_TAC) in
   REWRITE_TAC[get_lowerbits_def] THEN MATCH_REDUCE_TAC THEN
   AP_THM_TAC THEN AP_TERM_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; word_bits; BIT_WORD_SUBWORD;
               ADD_CLAUSES] THEN
   GEN_TAC THEN DISCH_TAC THEN EQ_TAC THENL
    [SIMP_TAC[];
     DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
     FIRST_ASSUM(fun th1 -> FIRST_ASSUM(fun th2 ->
       MP_TAC(MATCH_MP bits_lt (CONJ th2 th1)))) THEN
     ASM_ARITH_TAC]));;

let append_writes_def = cake_define_list
  [`append_writes c ptr (hdr:'a word) [] l = ARB`;
   `append_writes c ptr (hdr:'a word) (x :: xs) l =
      wordLang_Word hdr :: x ::
        (if xs = [] then [l] else
          let ptr = ptr + ((n2w 3) << shift_length c) in
            wordLang_Word ptr ::
            append_writes c ptr hdr xs l)`];;

let append_writes_LENGTH = prove
 (`!xs ptr. ~(xs = []) ==> LENGTH (append_writes c ptr hdr xs l) = 3 *
  LENGTH xs`,
  (LIST_INDUCT_TAC THEN REWRITE_TAC[NOT_CONS_NIL] THEN GEN_TAC THEN
   ONCE_REWRITE_TAC[append_writes_def] THEN
   CASES_ON_NAME "t" THEN MATCH_REDUCE_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_SIMP_TAC[LENGTH; NOT_CONS_NIL] THEN ARITH_TAC));;

let ptr_bits_or_1_add_1 = prove
 (`ptr_bits c tag len || (n2w 1) = ptr_bits c tag len + (n2w 1)`,
  (* the lowest bit of ptr_bits is clear, because both of the
     maxouts it ors are shifted up by at least one, so the or with
     one is the sum with one *)
  (CONV_TAC SYM_CONV THEN MATCH_MP_TAC WORD_ADD_OR THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_0;
               BIT_WORD_1] THEN
   X_GEN_TAC `i:num` THEN DISCH_TAC THEN
   ASM_CASES_TAC `i = 0` THEN ASM_REWRITE_TAC[] THEN
   REWRITE_TAC[ptr_bits_def; BIT_WORD_OR;
               maxout_bits_def] THEN
   REPEAT COND_CASES_TAC THEN
   REWRITE_TAC[BIT_WORD_SHL; GSYM word_index] THEN
   ASM_SIMP_TAC[all_ones_bit;
                ARITH_RULE `0 < d <=> 1 <= d:num`; DIMINDEX_GE_1] THEN
   REWRITE_TAC[ARITH_RULE `~(1 + n <= 0)`;
               ARITH_RULE `~(1 <= 0)`] THEN
   CONV_TAC TAUT));;

let all_ones_n2w = prove
 (`all_ones (l + b) b = n2w (2 EXP l - 1) << b`,
  (* and the same word is the mask of l ones shifted up by b, whose
     bits HOL Light's BIT_MASK_WORD gives *)
  (REWRITE_TAC[all_ones_def] THEN COND_CASES_TAC THENL
    [SUBGOAL_THEN `l = 0` SUBST1_TAC THENL
      [POP_ASSUM MP_TAC THEN ARITH_TAC; ALL_TAC] THEN
     CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC WORD_RULE;
     ALL_TAC] THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; word_slice; word_bits;
               BIT_WORD_SHL; BIT_WORD_SUBWORD; BIT_WORD_NOT;
               BIT_WORD_0; BIT_MASK_WORD] THEN
   X_GEN_TAC `i:num` THEN DISCH_TAC THEN
   REWRITE_TAC[ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
   REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   POP_ASSUM_LIST(fun ths -> MAP_EVERY MP_TAC ths) THEN ARITH_TAC));;

let ptr_bits_lemma = prove
 (`(w << shift_length conf || ptr_bits conf 0 2 || (n2w 1)) =
   w << shift_length conf + ptr_bits conf 0 2 + (n2w 1)`,
  (* the three parts of a pointer do not share a bit, so the or
     of them is their sum: the bits of a maxout_bits lie between
     its shift and its shift plus its width, so the ones of
     ptr_bits lie below the shift_length and above the zeroth *)
  (let bit_hi = prove
    (`!n r (i:num). n < 2 EXP r /\ r <= i
        ==> ~(bit i ((n2w n):(N)word))`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[BIT_WORD] THEN
     SUBGOAL_THEN `n DIV 2 EXP i = 0` SUBST1_TAC THENL
      [MATCH_MP_TAC DIV_LT THEN
       TRANS_TAC LTE_TRANS `2 EXP r` THEN
       ASM_SIMP_TAC[LE_EXP; ARITH];
       REWRITE_TAC[ODD]]) in
   let bit_maxout = prove
    (`!n rep k j. bit j ((maxout_bits n rep k):(N)word)
        ==> k <= j /\ j < k + rep`,
     REPEAT GEN_TAC THEN REWRITE_TAC[maxout_bits_def] THEN
     COND_CASES_TAC THEN REWRITE_TAC[all_ones_def] THENL
      [REWRITE_TAC[BIT_WORD_SHL] THEN STRIP_TAC THEN
       CONJ_TAC THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC(ARITH_RULE
         `k <= j /\ ~(rep <= j - k) ==> j < k + rep`) THEN
       ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
       MP_TAC(ISPECL [`n:num`; `rep:num`; `j - k`] bit_hi) THEN
       ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC;
       COND_CASES_TAC THEN
       REWRITE_TAC[BIT_WORD_0; word_slice; word_bits; BIT_WORD_SHL;
                   BIT_WORD_SUBWORD] THEN
       STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC]) in
   let bit_pb = prove
    (`!conf j. bit j ((ptr_bits conf 0 2):(N)word)
        ==> 1 <= j /\ j < small_shift_length conf`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[ptr_bits_def; small_shift_length_def;
                 BIT_WORD_OR] THEN
     DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (DISJ_CASES_THEN
       (fun th -> MP_TAC(MATCH_MP bit_maxout th)))) THEN
     ARITH_TAC) in
   let sl = prove
    (`!conf. small_shift_length conf <= shift_length conf /\
             2 <= shift_length conf`,
     REWRITE_TAC[small_shift_length_def;
                 shift_length_def] THEN ARITH_TAC) in
   let pb1 = prove
    (`!conf. ((ptr_bits conf 0 2) && (n2w 1):(N)word) = n2w 0`,
     GEN_TAC THEN REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
     X_GEN_TAC `j:num` THEN DISCH_TAC THEN
     REWRITE_TAC[BIT_WORD_AND; BIT_WORD_0; BIT_WORD_1] THEN
     REWRITE_TAC[TAUT `(p <=> F) <=> ~p`] THEN STRIP_TAC THEN
     FIRST_ASSUM(MP_TAC o MATCH_MP bit_pb) THEN
     ASM_REWRITE_TAC[] THEN ARITH_TAC) in
   let aw = prove
    (`!(w:(N)word) conf.
        (w << shift_length conf) &&
        (ptr_bits conf 0 2 || n2w 1) = n2w 0`,
     REPEAT GEN_TAC THEN REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
     X_GEN_TAC `j:num` THEN DISCH_TAC THEN
     REWRITE_TAC[BIT_WORD_AND; BIT_WORD_OR; BIT_WORD_0; BIT_WORD_1;
                 BIT_WORD_SHL] THEN
     REWRITE_TAC[TAUT `(p <=> F) <=> ~p`] THEN STRIP_TAC THEN
     TRY(FIRST_ASSUM(MP_TAC o MATCH_MP bit_pb)) THEN
     MP_TAC(SPEC_ALL sl) THEN ARITH_NO_BIT_TAC) in
   let gen = prove
    (`!(w:(N)word) conf.
        (w << shift_length conf || ptr_bits conf 0 2 || n2w 1) =
        w << shift_length conf + ptr_bits conf 0 2 + n2w 1`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[GEN_ALL(MATCH_MP WORD_ADD_OR (SPEC_ALL pb1));
                 GEN_ALL(MATCH_MP WORD_ADD_OR (SPEC_ALL aw))]) in
   MATCH_ACCEPT_TAC gen));;

let encode_header_lemma = prove
 (`1 < data_to_word_config_len_size c /\ data_to_word_config_len_size c
  + 5 < dimindex (:'a) /\
   good_dimindex (:'a) ==>
   decode_length c (make_header c (n2w 0) 2) = ((n2w 2):'a word) /\
   encode_header c 0 2 = SOME (make_header c ((n2w 0):'a word) 2)`,
  (* the four conditions of encode_header hold of the tag 0 and the
     length 2 (the length size is above one, so two is below two to
     that power), so the header is SOME of what make_header gives,
     and encode_header_IMP reads the length back off it *)
  (let gdcases =
     FIRST_ASSUM(DISJ_CASES_THEN SUBST1_TAC o
       REWRITE_RULE[good_dimindex_def]) in
   STRIP_TAC THEN
   SUBGOAL_THEN
     `0 < 2 EXP (dimindex (:'a) -
                 data_to_word_config_len_size c - 2) /\
      0 < dimword (:'a) DIV 16 /\
      2 < 2 EXP (dimindex (:'a) - 4) /\
      2 < 2 EXP (data_to_word_config_len_size c)`
     STRIP_ASSUME_TAC THENL
    [REPEAT CONJ_TAC THENL
      [REWRITE_TAC[LT_NZ; EXP_EQ_0; ARITH_EQ];
       REWRITE_TAC[dimword] THEN gdcases THEN
       CONV_TAC NUM_REDUCE_CONV;
       gdcases THEN CONV_TAC NUM_REDUCE_CONV;
       MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `2 EXP 2` THEN
       CONJ_TAC THENL
        [CONV_TAC NUM_REDUCE_CONV;
         REWRITE_TAC[LE_EXP] THEN CONV_TAC NUM_REDUCE_CONV THEN
         ASM_ARITH_TAC]];
     ALL_TAC] THEN
   SUBGOAL_THEN
     `encode_header c 0 2 = SOME (make_header c ((n2w 0):'a word) 2)`
     ASSUME_TAC THENL
    [ASM_REWRITE_TAC[encode_header_def]; ALL_TAC] THEN
   ASM_REWRITE_TAC[] THEN
   FIRST_ASSUM(fun eh -> FIRST_ASSUM(fun ls -> FIRST_ASSUM(fun gd ->
     ACCEPT_TAC(CONJUNCT2(MATCH_MP encode_header_IMP
       (CONJ eh (CONJ ls gd)))))))));;

let append_writes_list_to_BlockReps = prove
 (`!xs ws x w offset init_ptr.
     LENGTH xs = LENGTH ws /\
     good_dimindex (:'a) /\
     1 < data_to_word_config_len_size c /\
       data_to_word_config_len_size c + 5 < dimindex (:'a) /\
     backend_common_word_shift (:'a) <= shift_length c /\
     LIST_REL (\v w. word_addr c v = w) (x :: xs) (w :: ws) /\
     wordLang_Word init_ptr = make_cons_ptr c (bytes_in_word * (n2w
       offset:'a word)) 0 2 ==>
     misc_word_list (curr + bytes_in_word * (n2w offset:'a word))
       (append_writes c init_ptr
          (make_header c (n2w 0) 2) (w :: ws) (word_addr c v)) =
     word_heap (curr + bytes_in_word * (n2w offset:'a word))
       (list_to_BlockReps c v offset (x :: xs)) c`,
(* the proof of the source is the induction of the list, with both
   sides unfolded one cons at a time.  Of one element the writes are
   the header, the root of the element and the value, and the heap
   is the BlockRep of the two, whose payload has the same three
   cells and a cond that encode_header_lemma discharges.  Of a
   longer list the third cell is the pointer of the next cons, which
   is the lemma below: the pointer of the source is the offset
   shifted into place with the bits of a cons under it
   (make_cons_ptr_thm, bytes_in_word_mul_eq_shift), and three words
   on is the pointer of the next, both as the sum that
   ptr_bits_lemma makes of the parts.  The rest is the induction
   hypothesis three words along *)
  (let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in

  let cond_T = prove
   (`cond T = (emp:(A->bool)->bool)`,
    REWRITE_TAC[FUN_EQ_THM; cond_def; emp_def]) in

  let shl_shl = prove
   (`!(w:'a word) a b. (w << a) << b = w << (a + b)`,
    REPEAT GEN_TAC THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_SHL] THEN
    REPEAT STRIP_TAC THEN
    REWRITE_TAC[ARITH_RULE `(i:num) - b - a = i - (a + b)`] THEN
    EQ_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THEN
    TRY (FIRST_ASSUM ACCEPT_TAC) THEN ASM_ARITH_TAC) in

  let shl_mul = prove
   (`!(x:'a word) k. x << k = x * word (2 EXP k)`,
    REWRITE_TAC[word_shl; GSYM VAL_EQ; VAL_WORD_MUL; VAL_WORD] THEN
    CONV_TAC MOD_DOWN_CONV THEN REWRITE_TAC[MULT_AC]) in

  let ptr_step = prove
   (cake_as_vars (fun () ->
     `!c init_ptr offset.
        good_dimindex (:'a) /\
        backend_common_word_shift (:'a) <= shift_length c /\
        wordLang_Word (init_ptr:'a word) =
          make_cons_ptr c (bytes_in_word * n2w offset) 0 2 ==>
        (init_ptr + (n2w 3 << shift_length c) =
           get_addr c (offset + 3) (wordLang_Word (ptr_bits c 0 2)) /\
         wordLang_Word (init_ptr + (n2w 3 << shift_length c)) =
           make_cons_ptr c (bytes_in_word * n2w (offset + 3)) 0 2)`),
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM (fun gd ->
      if not (hd_is "good_dimindex" (concl gd)) then fail() else
      RULE_ASSUM_TRY (REWRITE_RULE[make_cons_ptr_thm;
        injectivity "word_loc";
        MATCH_MP bytes_in_word_mul_eq_shift gd; shl_shl])) THEN
    FIRST_ASSUM (fun le ->
      if not (try hd_is "<=" (concl le) with Failure _ -> false)
      then fail() else
      RULE_ASSUM_TRY (REWRITE_RULE[MATCH_MP
        (ARITH_RULE `w <= s ==> w + (s - w) = s`) le])) THEN
    REWRITE_TAC[make_cons_ptr_thm; get_addr_def;
                get_lowerbits_ptrbits; injectivity "word_loc"] THEN
    FIRST_ASSUM (fun gd ->
      if not (hd_is "good_dimindex" (concl gd)) then fail() else
      REWRITE_TAC[MATCH_MP bytes_in_word_mul_eq_shift gd;
                  shl_shl]) THEN
    FIRST_ASSUM (fun le ->
      if not (try hd_is "<=" (concl le) with Failure _ -> false)
      then fail() else
      REWRITE_TAC[MATCH_MP
        (ARITH_RULE `w <= s ==> w + (s - w) = s`) le]) THEN
    FIRST_ASSUM (fun ip ->
      if not (try is_eq (concl ip) && is_var (lhs (concl ip))
              with Failure _ -> false) then fail() else
      ASM_REWRITE_TAC[]) THEN
    W(fun (asl,gl) ->
      let ok t = (try hd_is "word_or" t &&
                      hd_is "word_or" (rand t) &&
                      hd_is "word" (lhand (rand t))
                  with Failure _ -> false) in
      MAP_EVERY (fun t ->
        let a = lhand t and bc = rand t in
        let b = lhand bc and c2 = rand bc in
        let sw = mk_comb (mk_comb (fst (strip_comb t), a),
                   mk_comb (mk_comb (fst (strip_comb bc), c2), b)) in
        SUBST1_TAC (WORD_BITWISE_RULE (mk_eq (t, sw))))
        (find_terms ok gl)) THEN
    REWRITE_TAC[ptr_bits_lemma] THEN
    REWRITE_TAC[GSYM WORD_ADD; shl_mul] THEN
    CONV_TAC WORD_RULE) in
  LIST_INDUCT_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_ASSUM (fun le ->
      if not (try is_eq (concl le) &&
                  hd_is "LENGTH" (lhs (concl le))
              with Failure _ -> false) then fail() else
      MP_TAC le) THEN
    REWRITE_TAC[LENGTH] THEN CONV_TAC (LAND_CONV SYM_CONV) THEN
    REWRITE_TAC[LENGTH_EQ_NIL] THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    ONCE_REWRITE_TAC[append_writes_def] THEN
    ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[word_heap_def; word_el_def; BlockRep_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_payload_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_list_def; LENGTH; MAP] THEN
    REWRITE_TAC[cons_tag_def] THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[WORD_RULE `(n2w 0:'a word) << 2 = n2w 0`] THEN
    (* the root of the head is the word of the writes *)
    FIRST_ASSUM (fun lr ->
      if not (hd_is "ALL2" (concl lr)) then fail() else
      STRIP_ASSUME_TAC (REWRITE_RULE[ALL2; MAP] lr)) THEN
    ASM_REWRITE_TAC[] THEN
    (* and the cond of the payload holds *)
    W(fun (asl,gl) ->
      let cnd = rand (find_term (hd_is "cond") gl) in
      SUBGOAL_THEN cnd (fun th ->
        REWRITE_TAC[EQT_INTRO th; cond_T; emp_STAR; STAR_emp;
                    STAR_AC]) THENL
       [REPEAT CONJ_TAC THEN
        TRY (FIRST_ASSUM (fun gd ->
          if not (hd_is "good_dimindex" (concl gd)) then fail() else
          MP_TAC (REWRITE_RULE[good_dimindex_def] gd) THEN
          STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
          CONV_TAC NUM_REDUCE_CONV)) THEN
        FIRST_ASSUM (fun gd ->
          if not (hd_is "good_dimindex" (concl gd)) then fail() else
          FIRST_ASSUM (fun l1 ->
            FIRST_ASSUM (fun l2 ->
              STRIP_ASSUME_TAC (MATCH_MP encode_header_lemma
                (CONJ l1 (CONJ l2 gd)))))) THEN
        ASM_REWRITE_TAC[]]) THEN
    ALL_TAC;
    (* a longer list: the writes and the heap of the head, and the
       induction hypothesis of the tail *)
    REPEAT GEN_TAC THEN
    W(fun (asl,gl) ->
      STRUCT_CASES_TAC (ISPEC
        (rand (rhs (hd (conjuncts (lhand gl))))) list_CASES)) THEN
    REWRITE_TAC[LENGTH; NOT_SUC; SUC_INJ] THEN
    STRIP_TAC THEN
    ONCE_REWRITE_TAC[append_writes_def] THEN
    ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[NOT_CONS_NIL] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_heap_def; word_el_def; BlockRep_def;
                el_length_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_payload_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    REWRITE_TAC[word_list_def; LENGTH; MAP] THEN
    REWRITE_TAC[cons_tag_def] THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[WORD_RULE `(n2w 0:'a word) << 2 = n2w 0`] THEN
    (* the root of the head is the word of the writes *)
    FIRST_ASSUM (fun lr ->
      if not (hd_is "ALL2" (concl lr)) then fail() else
      ASSUME_TAC (CONJUNCT1 (REWRITE_RULE[ALL2; MAP] lr))) THEN
    ASM_REWRITE_TAC[] THEN
    (* the cond of the payload holds *)
    W(fun (asl,gl) ->
      let cnd = rand (find_term (hd_is "cond") gl) in
      SUBGOAL_THEN cnd (fun th ->
        REWRITE_TAC[EQT_INTRO th; cond_T; emp_STAR; STAR_emp])
      THENL
       [REPEAT CONJ_TAC THEN
        TRY (FIRST_ASSUM (fun gd ->
          if not (hd_is "good_dimindex" (concl gd)) then fail() else
          MP_TAC (REWRITE_RULE[good_dimindex_def] gd) THEN
          STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
          CONV_TAC NUM_REDUCE_CONV)) THEN
        FIRST_ASSUM (fun gd ->
          if not (hd_is "good_dimindex" (concl gd)) then fail() else
          FIRST_ASSUM (fun l1 ->
            FIRST_ASSUM (fun l2 ->
              STRIP_ASSUME_TAC (MATCH_MP encode_header_lemma
                (CONJ l1 (CONJ l2 gd)))))) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC]) THEN
    (* the pointer of the next cons *)
    FIRST_ASSUM (fun gd ->
      if not (hd_is "good_dimindex" (concl gd)) then fail() else
      FIRST_ASSUM (fun le ->
        if not (try hd_is "<=" (concl le) with Failure _ -> false)
        then fail() else
        FIRST_ASSUM (fun ip ->
          if not (try is_eq (concl ip) &&
                      hd_is "make_cons_ptr" (rhs (concl ip))
                  with Failure _ -> false) then fail() else
          STRIP_ASSUME_TAC (MATCH_MP ptr_step
            (CONJ gd (CONJ le ip)))))) THEN
    REWRITE_TAC(word_addr_clauses ()) THEN
    FIRST_ASSUM (fun pe ->
      if not (try is_eq (concl pe) &&
                  hd_is "get_addr" (rhs (concl pe))
              with Failure _ -> false) then fail() else
      REWRITE_TAC[SYM pe]) THEN
    (* and the induction hypothesis of the tail *)
    W(fun (asl,gl) ->
      let ih = grab asl (fun th -> is_forall (concl th)) in
      let lr = grab asl (fun th -> hd_is "ALL2" (concl th)) in
      let a2 = CONJUNCT2 (ONCE_REWRITE_RULE[ALL2] lr) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let len = grab asl (fun th ->
        is_eq (concl th) && hd_is "LENGTH" (lhs (concl th))) in
      let c1 = grab asl (fun th ->
        hd_is "<" (concl th) && lhand (concl th) = `1`) in
      let c2 = grab asl (fun th ->
        hd_is "<" (concl th) && hd_is "+" (lhand (concl th))) in
      let ws = grab asl (fun th -> hd_is "<=" (concl th)) in
      let ip2 = grab asl (fun th ->
        is_eq (concl th) &&
        hd_is "make_cons_ptr" (rhs (concl th)) &&
        not (is_var (rand (lhs (concl th))))) in
      let ihi = REWRITE_RULE[GSYM WORD_ADD] (MATCH_MP ih
        (CONJ len (CONJ gd (CONJ c1 (CONJ c2
           (CONJ ws (CONJ a2 ip2))))))) in
      let addr = lhand (lhs (concl ihi)) in
      let wl = find_term (hd_is "misc_word_list") gl in
      let wh = find_term (hd_is "word_heap") gl in
      SUBST1_TAC (WORD_RULE (mk_eq (lhand wl, addr))) THEN
      SUBST1_TAC (WORD_RULE (mk_eq
        (el 0 (snd (strip_comb wh)), addr))) THEN
      REWRITE_TAC[ihi] THEN
      REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp])]));;

let bind_each_eq_tf = prove
 (`!k tf ts n i x.
     (!t. t IN FDOM tf ==> t < ts) /\ x < ts ==> FAPPLY (bind_each
       tf ts n i k) x = FAPPLY tf x`,
  (* the bindings that bind_each adds are above ts, so a timestamp
     below it keeps the value that tf gives it *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   REWRITE_TAC[bind_each_def] THEN
   REWRITE_TAC[FAPPLY_FUPDATE_THM] THEN
   COND_CASES_TAC THENL
    [SUBGOAL_THEN `F` CONTR_TAC THEN ASM_ARITH_TAC;
     FIRST_X_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
      [GEN_TAC THEN DISCH_TAC THEN
       FIRST_X_ASSUM(MP_TAC o SPEC `t:num`) THEN
       ASM_REWRITE_TAC[] THEN ARITH_TAC;
       ASM_ARITH_TAC]]));;

let bind_each_FDOM = prove
 (`!n tf ts k i.
    FDOM (bind_each tf ts k i n) = FDOM tf UNION {x | ts <= x /\ x
      < ts + n}`,
  (* bind_each ts ... n binds the n timestamps from ts up *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   ASM_REWRITE_TAC[bind_each_def; FDOM_FUPDATE] THEN
   REWRITE_TAC[EXTENSION; IN_UNION; IN_INSERT; IN_ELIM_THM] THEN
   GEN_TAC THEN EQ_TAC THEN STRIP_TAC THEN
   ASM_REWRITE_TAC[] THEN
   TRY(DISJ2_TAC THEN ASM_ARITH_TAC) THEN
   TRY(DISJ1_TAC THEN ASM_ARITH_TAC) THEN
   ASM_ARITH_TAC));;

let bind_each_eq_tf_FDOM = prove
 (`!k tf ts n i x.
     (!t. t IN FDOM tf ==> t < ts) /\ x < ts /\ x IN FDOM
       (bind_each tf ts n i k) ==> x IN FDOM tf`,
  (REWRITE_TAC[bind_each_FDOM; IN_UNION; IN_ELIM_THM] THEN
   REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC));;

let bind_each_eq_lt_FAPPLY = prove
 (`!n tf ts k i x.
    FAPPLY
    (bind_each tf ts k i n) x < k ==> FAPPLY (bind_each tf ts k i
      n) x = FAPPLY tf x`,
  (* a value below the first key that bind_each gives out is one of
     tf: the keys it gives are k, k + i, k + 2 * i, ... *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM] THEN
   COND_CASES_TAC THEN REWRITE_TAC[LT_REFL] THEN
   DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC));;

let bind_each_eq_lt_FDOM = prove
 (`!n tf ts k i x.
    x IN FDOM (bind_each tf ts k i n) /\ FAPPLY (bind_each tf ts k
      i n) x < k ==> x IN FDOM tf`,
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM;
               FDOM_FUPDATE; IN_INSERT] THENL
    [CONV_TAC TAUT;
     COND_CASES_TAC THEN REWRITE_TAC[LT_REFL] THEN
     STRIP_TAC THEN
     FIRST_X_ASSUM(fun ih -> MP_TAC(SPECL
       [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`; `x:num`]
       ih)) THEN
     ANTS_TAC THENL
      [CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_ARITH_TAC;
       DISCH_THEN ACCEPT_TAC]]));;

let bind_each_eq_gt_FAPPLY = prove
 (`!n tf ts k i x.
    i * n + k < FAPPLY (bind_each tf ts k i n) x ==> FAPPLY
      (bind_each tf ts k i n) x = FAPPLY tf x`,
  (* and a value above the last one is one of tf as well *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM;
               MULT_SUC] THEN
   COND_CASES_TAC THEN
   TRY(DISCH_THEN(fun th -> MP_TAC th THEN ARITH_TAC)) THEN
   DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC));;

let bind_each_eq_gt_FDOM = prove
 (`!n tf ts k i x.
    x IN FDOM (bind_each tf ts k i n) /\ i * n + k < FAPPLY
      (bind_each tf ts k i n) x ==> x IN FDOM tf`,
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM;
               FDOM_FUPDATE; IN_INSERT; MULT_SUC] THENL
    [CONV_TAC TAUT;
     COND_CASES_TAC THENL
      [STRIP_TAC THEN ASM_ARITH_TAC;
       STRIP_TAC THEN
       FIRST_X_ASSUM(fun ih -> MP_TAC(SPECL
         [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`; `x:num`]
         ih)) THEN
       ANTS_TAC THENL
        [CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
         ASM_ARITH_TAC;
         DISCH_THEN ACCEPT_TAC]]]));;

let bind_each_eq_ge_FDOM = prove
 (`!n tf ts k i x.
    x IN FDOM (bind_each tf ts k i n) /\
    i * n + k <= FAPPLY (bind_each tf ts k i n) x /\ ~(i = 0) ==> x
      IN FDOM tf`,
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM;
               FDOM_FUPDATE; IN_INSERT; MULT_SUC] THENL
    [CONV_TAC TAUT;
     COND_CASES_TAC THENL
      [STRIP_TAC THEN ASM_ARITH_TAC;
       STRIP_TAC THEN
       FIRST_X_ASSUM(fun ih -> MP_TAC(SPECL
         [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`; `x:num`]
         ih)) THEN
       ANTS_TAC THENL
        [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
         ASM_ARITH_TAC;
         DISCH_THEN ACCEPT_TAC]]]));;

let bind_each_fdom_limit = prove
 (`!k tf ts n i x.
     (!t. t IN FDOM tf ==> t < ts) /\ ts + k < x ==> ~(x IN FDOM
       (bind_each tf ts n i k))`,
  (* bind_each binds the k timestamps from ts up, so a timestamp
     above ts + k is in neither it nor tf *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def; FDOM_FUPDATE; IN_INSERT;
               DE_MORGAN_THM] THEN
   STRIP_TAC THENL
    [DISCH_TAC THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `x:num`) THEN
     ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
     CONJ_TAC THENL
      [ASM_ARITH_TAC;
       FIRST_X_ASSUM MATCH_MP_TAC THEN CONJ_TAC THENL
        [GEN_TAC THEN DISCH_TAC THEN
         FIRST_X_ASSUM(MP_TAC o SPEC `t:num`) THEN
         ASM_REWRITE_TAC[] THEN ARITH_TAC;
         ASM_ARITH_TAC]]]));;

let bind_each_FUPDATE = prove
 (`!n i tf ts1 ts2 k1 k2.
    ts1 < ts2 /\ k1 < k2 ==> bind_each (tf |+ (ts1,k1)) ts2 k2 i n
      = bind_each tf ts2 k2 i n |+ (ts1,k1)`,
  (* the binding of the timestamps of a block does not touch a
     timestamp below the ones it binds, so an update of that one
     commutes with it (ml/lib/lemmas.ml has FUPDATE_COMMUTES) *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[bind_each_def] THEN
   DISCH_TAC THEN
   FIRST_X_ASSUM(fun ih ->
     MP_TAC(SPECL [`i:num`; `tf:(num,num)fmap`; `ts1:num`;
                   `ts2 + 1`; `k1:num`; `k2 + i`] ih)) THEN
   ASM_REWRITE_TAC[ARITH_RULE `(ts1 < ts2 + 1) <=> ts1 <= ts2`] THEN
   ANTS_TAC THENL
    [ASM_ARITH_TAC;
     DISCH_THEN SUBST1_TAC THEN
     MATCH_MP_TAC FUPDATE_COMMUTES THEN ASM_ARITH_TAC]));;

let bind_each_MINUS = prove
 (`!n tf ts x k1 k2 i.
    (!t. t IN FDOM tf ==> t < ts) /\
    x IN {x | ts <= x /\ x < ts + n} /\ k2 <= k1 ==> FAPPLY
      (bind_each tf ts k1 i n) x - k2 = FAPPLY (bind_each tf ts (k1 -
      k2) i n) x`,
  (* the binding of each timestamp of a block gives the one at ts
     the clock k and the ones above it k + i, k + 2i, ...: taking k2
     off every one of them is the binding that starts k2 lower *)
  (INDUCT_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bind_each_def; IN_ELIM_THM] THEN
    STRIP_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_CASES_TAC `(x:num) = ts` THENL
     [ASM_REWRITE_TAC[FAPPLY_FUPDATE_THM];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[FAPPLY_FUPDATE_THM] THEN
    SUBGOAL_THEN `(k1 - k2) + i = (k1 + i) - k2` SUBST1_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[IN_ELIM_THM] THEN
    REPEAT CONJ_TAC THEN TRY ASM_ARITH_TAC THEN
    GEN_TAC THEN DISCH_TAC THEN
    FIRST_ASSUM(fun fd -> FIRST_ASSUM(fun h ->
      MP_TAC(MATCH_MP fd h))) THEN
    ARITH_TAC));;

(* isSomeDataElement_heap_lookup[allow_rebind] *)
let data_to_word_memoryProof_isSomeDataElement_heap_lookup = prove
 (`!n a sp b.
    isSomeDataElement (heap_lookup n (a ++ [Unused sp] ++ b)) ==> n
      < heap_length a \/ el_length (Unused sp) + heap_length a <= n`,
  (* the lookup falls in the first heap, or past the Unused in the
     second: the Unused itself holds no data element *)
  (let hlen_cl = prove
    (`heap_length [] = 0 /\
      (!x xs. heap_length (CONS x xs) =
              el_length x + heap_length xs)`,
     REWRITE_TAC[heap_length_def; MAP; SUM_DEF; ITLIST]) in
   let isde_rws = [isSomeDataElement_def;
                   distinctness "option"; injectivity "option";
                   distinctness "heap_element"] in
   let un_none = prove
    (`!sp m. ~(isSomeDataElement
                 (heap_lookup m [Unused sp:((A,B)heap_element)]))`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC(heap_lookup_def :: el_length_def ::
                 isde_rws) THEN
     REPEAT COND_CASES_TAC THEN
     REWRITE_TAC(heap_lookup_def :: isde_rws)) in
   REPEAT GEN_TAC THEN
   REWRITE_TAC[GSYM APPEND_ASSOC;
               data_to_word_memoryProof_heap_lookup_APPEND] THEN
   COND_CASES_TAC THEN REWRITE_TAC[] THEN
   REWRITE_TAC[hlen_cl; ADD_CLAUSES] THEN
   COND_CASES_TAC THEN REWRITE_TAC[un_none] THEN
   DISCH_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[el_length_def]) THEN
   REWRITE_TAC[el_length_def] THEN ARITH_ASM_TAC));;

let isSomeDataElement_heap_lookup_eq = prove
 (`!ls n p k1 k2 conf.
    isSomeDataElement (heap_lookup n
      ((list_to_BlockReps conf p k2 ls):(('a
        word_loc,data_to_word_memoryProof_tag#'b list)heap_element)
        list)) ==> isSomeDataElement (heap_lookup n
      ((list_to_BlockReps conf p k1 ls):(('a
        word_loc,data_to_word_memoryProof_tag#'b list)heap_element)
        list))`,
  (* the heap that the list builds has the same elements whatever
     the address it starts at: the first block is a data element
     either way, and the lookup past it is the induction *)
  (let isde = prove
    (`!ys l d. isSomeDataElement (SOME (DataElement ys l d))`,
     REWRITE_TAC[isSomeDataElement_def] THEN MESON_TAC[]) in
   let isdeN = prove
    (`~isSomeDataElement NONE`,
     REWRITE_TAC[isSomeDataElement_def;
                 distinctness "option"]) in
   LIST_INDUCT_TAC THENL
    [REWRITE_TAC[list_to_BlockReps_def]; ALL_TAC] THEN
   REPEAT GEN_TAC THEN POP_ASSUM MP_TAC THEN
   REWRITE_TAC[list_to_BlockReps_def] THEN
   (fun (asl,w as gl) ->
      let scr = hd (filter is_var (match_scruts w)) in
      STRUCT_CASES_TAC(ISPEC scr list_CASES_v) gl) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[] THEN
   DISCH_TAC THEN
   ONCE_REWRITE_TAC[heap_lookup_def] THEN
   REWRITE_TAC[BlockRep_def; el_length_def; LENGTH] THEN
   CONV_TAC NUM_REDUCE_CONV THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[isde] THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[isdeN] THEN
   DISCH_TAC THEN
   FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_EXISTS_TAC THEN
   ASM_REWRITE_TAC[]));;

let bind_each_isSomeDataElement = prove
 (`!l tf ts x p k conf.
    ~(l = []) /\
    x IN {x | ts <= x /\ x < ts + (LENGTH l)} /\ (!t. t IN FDOM tf
      ==> t < ts) ==> isSomeDataElement (heap_lookup ((FAPPLY (bind_each
      tf ts 0 3 (LENGTH l)) x))
                        (list_to_BlockReps conf p k l))`,
(* the proof of the source is the induction of the list.  Of one
   element the one timestamp goes to nought, which is the head of
   the BlockReps; of a longer one the first timestamp goes there as
   well and the others into the tail, where the induction hypothesis
   has them -- three words along, because an element of the list
   takes three.  That the clock of a timestamp of the tail is three
   above the clock the hypothesis gives it is the lemma below, off
   bind_each_MINUS, with bind_each_eq_lt_FDOM to say that a
   timestamp that is not tf's is not below the clock *)
  (let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let step_lemma = prove
   (`!n tf ts x.
   (!t. t IN FDOM tf ==> t < ts) /\ ts + 1 <= x /\
   x < (ts + 1) + n ==>
   FAPPLY (bind_each tf (ts + 1) 3 3 n) x =
     3 + FAPPLY (bind_each tf (ts + 1) 0 3 n) x`,

    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `~((x:num) IN FDOM (tf:(num,num)fmap))`
      ASSUME_TAC THENL
     [DISCH_TAC THEN
      FIRST_ASSUM (fun fd ->
        if not (is_forall (concl fd)) then fail() else
        FIRST_ASSUM (fun mem ->
          if not (try hd_is "IN" (concl mem) with Failure _ -> false)
          then fail() else
          MP_TAC (MP (SPEC `x:num` fd) mem))) THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `!t. t IN FDOM (tf:(num,num)fmap) ==> t < ts + 1`
      ASSUME_TAC THENL
     [GEN_TAC THEN DISCH_TAC THEN
      FIRST_ASSUM (fun fd ->
        if not (is_forall (concl fd)) then fail() else
        FIRST_ASSUM (fun mem ->
          if not (try hd_is "IN" (concl mem) with Failure _ -> false)
          then fail() else
          MP_TAC (MP (SPEC_ALL fd) mem))) THEN
      ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
      `(x:num) IN {x | ts + 1 <= x /\ x < (ts + 1) + n}` ASSUME_TAC
    THENL
     [REWRITE_TAC[IN_ELIM_THM] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(x:num) IN FDOM (bind_each tf (ts + 1) 3 3 n)`
      ASSUME_TAC THENL
     [REWRITE_TAC[bind_each_FDOM; IN_UNION; IN_ELIM_THM] THEN
      DISJ2_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN
      `~(FAPPLY (bind_each (tf:(num,num)fmap) (ts + 1) 3 3 n) x < 3)`
      ASSUME_TAC THENL
     [DISCH_TAC THEN
      FIRST_ASSUM (fun lt ->
        FIRST_ASSUM (fun fdm ->
          if not (try hd_is "IN" (concl fdm) &&
                      hd_is "FDOM" (rand (concl fdm)) &&
                      hd_is "bind_each" (rand (rand (concl fdm)))
                  with Failure _ -> false) then fail() else
          MP_TAC (MATCH_MP (GEN_ALL bind_each_eq_lt_FDOM)
                    (CONJ fdm lt)))) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC (SPECL [`n:num`; `tf:(num,num)fmap`; `ts + 1`; `x:num`;
                   `3`; `3`; `3`] bind_each_MINUS) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    ASM_ARITH_TAC) in
  LIST_INDUCT_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_ELIM_THM; LENGTH] THEN STRIP_TAC THEN
  CASES_ON_NAME "t" THENL
   [(* the list of one: the one timestamp goes to the head *)
    RULE_ASSUM_TRY (REWRITE_RULE[LENGTH]) THEN
    ONCE_REWRITE_TAC[bind_each_def] THEN
    REWRITE_TAC[bind_each_def; FAPPLY_FUPDATE_THM] THEN
    SUBGOAL_THEN `x:num = ts` SUBST1_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[heap_lookup_def; isSomeDataElement_def;
                BlockRep_def] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  (* the general case: the first timestamp goes to the head of the
     BlockReps and the others into the tail *)
  ONCE_REWRITE_TAC[bind_each_def] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[FAPPLY_FUPDATE_THM] THEN
  ASM_CASES_TAC `x:num = ts` THEN ASM_REWRITE_TAC[] THENL
   [ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[heap_lookup_def; isSomeDataElement_def;
                BlockRep_def] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  (* the timestamps of tf are below the ones of the tail *)
  SUBGOAL_THEN `!t. t IN FDOM (tf:(num,num)fmap) ==> t < ts + 1`
    ASSUME_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN
    W(fun (asl,gl) ->
      let tv = lhand gl in
      FIRST_ASSUM (fun fd ->
        if not (try is_forall (concl fd) &&
                    hd_is "IN"
                      (lhand (snd (strip_forall (concl fd))))
                with Failure _ -> false) then fail() else
        FIRST_ASSUM (fun mem ->
          if not (try hd_is "IN" (concl mem)
                  with Failure _ -> false) then fail() else
          MP_TAC (MP (SPEC tv fd) mem)))) THEN
    ARITH_TAC;
    ALL_TAC] THEN
  (* and x is one of them *)
  W(fun (asl,gl) ->
    let be = find_term (hd_is "bind_each") gl in
    let nn = el 4 (snd (strip_comb be)) in
    let plus a b = mk_binop `(+):num->num->num` a b in
    let ar = mk_conj
      (mk_binop `(<=):num->num->bool` (plus `ts:num` `1`) `x:num`,
       mk_binop `(<):num->num->bool` `x:num`
         (plus (plus `ts:num` `1`) nn)) in
    SUBGOAL_THEN ar ASSUME_TAC THENL
     [RULE_ASSUM_TRY (REWRITE_RULE[LENGTH]) THEN
      REWRITE_TAC[LENGTH] THEN ASM_ARITH_TAC;
      ALL_TAC]) THEN
  (* so the index is three more than the index in the tail *)
  FIRST_ASSUM (fun ar ->
    if not (is_conj (concl ar)) then fail() else
    FIRST_ASSUM (fun fd ->
      if not (try is_forall (concl fd) &&
                  hd_is "IN"
                    (lhand (snd (strip_forall (concl fd)))) &&
                  rand (rand (snd (strip_forall (concl fd)))) =
                    `ts:num`
              with Failure _ -> false) then fail() else
      SUBST1_TAC (MATCH_MP step_lemma (CONJ fd ar)))) THEN
  (* the lookup goes past the first BlockRep *)
  ONCE_REWRITE_TAC[list_to_BlockReps_def] THEN
  MATCH_REDUCE_TAC THEN
  REWRITE_TAC[heap_lookup_def; BlockRep_def; el_length_def;
              LENGTH] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[ARITH_RULE `~(3 + v = 0)`;
              ARITH_RULE `~(3 + v < 3)`;
              ARITH_RULE `(3 + v) - 3 = v`] THEN
  (* and the induction hypothesis of the tail *)
  REWRITE_TAC[LENGTH] THEN
  W(fun (asl,gl) ->
    let ih = REWRITE_RULE[IN_ELIM_THM; LENGTH]
      (grab asl (fun th ->
         is_forall (concl th) &&
         (try hd_is "isSomeDataElement"
                (rand (snd (strip_forall (concl th))))
          with Failure _ -> false))) in
    let lbr = find_term (hd_is "list_to_BlockReps") gl in
    let lst = el 3 (snd (strip_comb lbr)) in
    let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
    let ar = REWRITE_RULE[LENGTH]
      (grab asl (fun th -> is_conj (concl th))) in
    let fd1 = grab asl (fun th ->
      try is_forall (concl th) &&
          hd_is "IN" (lhand (snd (strip_forall (concl th)))) &&
          hd_is "+" (rand (rand (snd (strip_forall (concl th)))))
      with Failure _ -> false) in
    MATCH_ACCEPT_TAC (MATCH_MP ih (CONJ ne (CONJ ar fd1))))));;

let bind_each_eq_INJ = prove
 (`!n x y tf ts k i.
   FAPPLY
   (bind_each tf ts k i n) x = FAPPLY (bind_each tf ts k i n) y /\
   ~(i = 0) /\ x IN {x | ts <= x /\ x < ts + n} /\
   ~(x IN FDOM tf) /\ y IN {x | ts <= x /\ x < ts + n} /\ ~(y IN
     FDOM tf) ==> x = y`,
  (* the binding gives each timestamp its own clock: the one at ts
     gets k and the ones above it more than k, which
     bind_each_eq_lt_FDOM says, so two of them with one clock are
     one timestamp *)
  (let eqlt = bind_each_eq_lt_FDOM in
    let bfd = bind_each_FDOM in
    let use_eqlt v =
      MP_TAC(SPECL [`n:num`; `tf:(num,num)fmap`; `ts + 1`; `k + i`;
                    `i:num`; v] eqlt) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [REWRITE_TAC[bfd; IN_UNION; IN_ELIM_THM] THEN ASM_ARITH_TAC;
          FIRST_ASSUM(fun e -> REWRITE_TAC[GSYM e]) THEN ASM_ARITH_TAC];
        ASM_REWRITE_TAC[]] in
    INDUCT_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bind_each_def; IN_ELIM_THM] THENL
     [STRIP_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[FAPPLY_FUPDATE_THM] THEN
    ASM_CASES_TAC `(x:num) = ts` THEN ASM_CASES_TAC `(y:num) = ts` THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [use_eqlt `y:num`;
      use_eqlt `x:num`;
      FIRST_X_ASSUM MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC
        [`tf:(num,num)fmap`; `ts + 1`; `k + i`; `i:num`] THEN
      ASM_REWRITE_TAC[IN_ELIM_THM] THEN
      REPEAT CONJ_TAC THEN ASM_ARITH_TAC]));;

let all_ts_list_to_v_SUBSET = prove
 (`!xs ts (refs:(dataSem_v bvlSem_ref) spt) t.
    {x | ts <= x /\ x < ts + LENGTH xs} SUBSET all_ts refs
      [list_to_v ts t xs]`,
  (* the list that list_to_v builds is a Block of each timestamp
     from ts up, one for each element, and the timestamps of a
     Block on the stack are its own and the ones of its payload *)
  (SUBGOAL_THEN
     `!xs ts refs (tv:dataSem_v).
        {x | ts <= x /\ x < ts + LENGTH xs} SUBSET
        all_ts refs [list_to_v ts tv xs]`
     (fun th -> MATCH_ACCEPT_TAC th) THEN
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[SUBSET; IN_ELIM_THM; LENGTH; ADD_CLAUSES] THEN
     GEN_TAC THEN MATCH_MP_TAC(TAUT `~p ==> (p ==> q)`) THEN
     ARITH_TAC;
     REWRITE_TAC[dataSem_list_to_v_def] THEN
     ONCE_REWRITE_TAC[all_ts_cons] THEN
     REWRITE_TAC[APPEND; APPEND_NIL] THEN
     ONCE_REWRITE_TAC[all_ts_head] THEN
     FIRST_X_ASSUM(MP_TAC o SPECL
       [`(ts:num) + 1`; `refs:(dataSem_v bvlSem_ref) spt`;
        `tv:dataSem_v`]) THEN
     REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INSERT; IN_UNION;
                 LENGTH] THEN
     DISCH_TAC THEN X_GEN_TAC `u:num` THEN STRIP_TAC THEN
     ASM_CASES_TAC `(u:num) = ts` THENL
      [DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
       DISJ2_TAC THEN DISJ2_TAC THEN
       FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC]]));;

let all_ts_SUBSET_list_to_v = prove
 (`!refs t xs stack' ts.
     all_ts refs (t :: (xs ++ stack')) SUBSET
     all_ts refs (list_to_v ts t xs :: stack')`,
  (* and so are the timestamps of the elements and of the tail of
     the list, which are the same values in another order *)
  (let all_ts_perm = prove
    (`!refs (xs:dataSem_v list) ys.
        (!x. MEM x xs <=> MEM x ys)
        ==> all_ts refs xs = all_ts refs ys`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[all_ts_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_REWRITE_TAC[]) in
   SUBGOAL_THEN
     `!xs refs (tv:dataSem_v) stk ts.
        all_ts refs (CONS tv (xs ++ stk)) SUBSET
        all_ts refs (CONS (list_to_v ts tv xs) stk)`
     (fun th -> REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC th) THEN
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[dataSem_list_to_v_def; APPEND; SUBSET_REFL];
     REWRITE_TAC[dataSem_list_to_v_def] THEN
     ONCE_REWRITE_TAC[all_ts_cons] THEN
     REWRITE_TAC[APPEND] THEN
     SUBGOAL_THEN
       `all_ts refs (CONS (tv:dataSem_v) (CONS h (t ++ stk))) =
        all_ts refs (CONS tv (t ++ CONS h stk))`
       SUBST1_TAC THENL
      [MATCH_MP_TAC all_ts_perm THEN
       REWRITE_TAC[MEM; MEM_APPEND] THEN CONV_TAC TAUT;
       ALL_TAC] THEN
     SUBGOAL_THEN
       `all_ts refs (CONS (h:dataSem_v)
          (CONS (list_to_v ((ts:num) + 1) tv t) stk)) =
        all_ts refs (CONS (list_to_v (ts + 1) tv t) (CONS h stk))`
       SUBST1_TAC THENL
      [MATCH_MP_TAC all_ts_perm THEN REWRITE_TAC[MEM] THEN
       CONV_TAC TAUT;
       ALL_TAC] THEN
     FIRST_X_ASSUM(MP_TAC o SPECL
       [`refs:(dataSem_v bvlSem_ref) spt`; `tv:dataSem_v`;
        `CONS (h:dataSem_v) stk`; `(ts:num) + 1`]) THEN
     SET_TAC[]]));;

let new_all_ts_SUBSET_list_to_v = prove
 (`!refs t xs stack' ts.
     {x | ts <= x /\ x < ts + LENGTH xs} SUBSET
     all_ts refs (list_to_v ts t xs :: stack')`,
  (* and those timestamps are timestamps of the stack that the
     list is on, whatever else that stack holds *)
  (let all_ts_perm = prove
    (`!refs (xs:dataSem_v list) ys.
        (!x. MEM x xs <=> MEM x ys)
        ==> all_ts refs xs = all_ts refs ys`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[all_ts_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_REWRITE_TAC[]) in
   SUBGOAL_THEN
     `!xs refs (tv:dataSem_v) stk ts.
        {x | ts <= x /\ x < ts + LENGTH xs} SUBSET
        all_ts refs (CONS (list_to_v ts tv xs) stk)`
     (fun th -> REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC th) THEN
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THENL
    [REWRITE_TAC[SUBSET; IN_ELIM_THM; LENGTH; ADD_CLAUSES] THEN
     GEN_TAC THEN MATCH_MP_TAC(TAUT `~p ==> (p ==> q)`) THEN
     ARITH_TAC;
     REWRITE_TAC[dataSem_list_to_v_def] THEN
     ONCE_REWRITE_TAC[all_ts_cons] THEN
     REWRITE_TAC[APPEND] THEN
     SUBGOAL_THEN
       `all_ts refs (CONS (h:dataSem_v)
          (CONS (list_to_v ((ts:num) + 1) tv t) stk)) =
        all_ts refs (CONS (list_to_v (ts + 1) tv t) (CONS h stk))`
       SUBST1_TAC THENL
      [MATCH_MP_TAC all_ts_perm THEN REWRITE_TAC[MEM] THEN
       CONV_TAC TAUT;
       ALL_TAC] THEN
     FIRST_X_ASSUM(MP_TAC o SPECL
       [`refs:(dataSem_v bvlSem_ref) spt`; `tv:dataSem_v`;
        `CONS (h:dataSem_v) stk`; `(ts:num) + 1`]) THEN
     REWRITE_TAC[SUBSET; IN_ELIM_THM; IN_INSERT; LENGTH] THEN
     DISCH_TAC THEN X_GEN_TAC `u:num` THEN STRIP_TAC THEN
     ASM_CASES_TAC `(u:num) = ts` THENL
      [DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
       DISJ2_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
       ASM_ARITH_TAC]]));;

let FDOM_bind_each_lemma = prove
 (`!tf k ts h.
     FDOM tf SUBSET {n | n < ts} ==>
     FDOM (bind_each tf ts h n k) SUBSET {n | n < ts + k}`,
  (* induction on the number of bindings: each one is a timestamp
     one higher than the last, and the domain grows by that one *)
  (let aux = prove
    (`!k tf ts h i. FDOM tf SUBSET {m | m < ts}
        ==> FDOM (bind_each tf ts h i k) SUBSET {m | m < ts + k}`,
     INDUCT_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THENL
      [ASM_REWRITE_TAC[bind_each_def; ADD_CLAUSES];
       REWRITE_TAC[bind_each_def; FDOM_FUPDATE;
                   INSERT_SUBSET; IN_ELIM_THM] THEN
       CONJ_TAC THENL
        [ARITH_TAC;
         FIRST_ASSUM(fun ih ->
           MP_TAC(SPECL [`tf:(num,num)fmap`; `ts + 1`; `h + i:num`;
                         `i:num`] ih)) THEN
         REWRITE_TAC[ARITH_RULE `(ts + 1) + k = ts + SUC k`] THEN
         DISCH_THEN MATCH_MP_TAC THEN
         FIRST_ASSUM(fun sub -> MP_TAC sub) THEN
         REWRITE_TAC[SUBSET; IN_ELIM_THM] THEN
         MESON_TAC[ARITH_RULE `!a b:num. a < b ==> a < b + 1`]]]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC(SPEC_ALL aux)));;

let v_all_vs_list_to_v1 = prove
 (`!xs stack' ts t t1 a1 xs1.
     t1 < ts /\
     MEM (Block t1 a1 xs1) (v_all_vs (list_to_v ts t xs :: stack'))
       ==>
       MEM (Block t1 a1 xs1) (v_all_vs (t :: (xs ++ stack')))`,
  (* the list that list_to_v builds is a chain of conses, and the
     Blocks of the chain itself have the timestamps from ts on,
     which the Block of the goal is below; so a Block among the
     values of the chain is one of the values of the list or of the
     stack, which the induction follows cons by cons *)
  (
   let (vnil,vsing,vats,vcons) = v_all_vs_clauses () in
   let split = MEM_v_all_vs_split
   and ext_hd = MEM_v_all_vs_extend_hd
   and ext_tl = MEM_v_all_vs_extend_tl in
   let mem_app = prove
    (`!(x:dataSem_v) l1 l2.
        MEM x (v_all_vs (l1 ++ l2)) <=>
        MEM x (v_all_vs l1) \/ MEM x (v_all_vs l2)`,
     REWRITE_TAC[v_all_vs_append; MEM_APPEND]) in
   LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
   REWRITE_TAC[dataSem_list_to_v_def; APPEND] THENL
    [DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
     STRIP_TAC THEN
     SUBGOAL_THEN `t1 < ts + 1` ASSUME_TAC THENL
      [ASM_ARITH_TAC; ALL_TAC] THEN
     FIRST_ASSUM(fun m ->
       let th = MATCH_MP split m in
       MP_TAC(REWRITE_RULE[vsing; MEM] th)) THEN
     STRIP_TAC THEN
     ASM_MESON_TAC[split; ext_hd; ext_tl; mem_app;
                   injectivity "dataSem_v"; LT_REFL]]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_GT_ts = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (t :: (xs ++ stack))) /\
     t' >= ts /\ ~(xs1 = []) ==> ~(Block t' a1 xs1 IN all_vs refs
       (t :: (xs ++ stack)))`),
  (* blocks_unique gives the timestamp of a Block of the set as one
     below ts, and this one is not *)
  (REWRITE_TAC[blocks_unique_def] THEN REPEAT STRIP_TAC THEN
   ASM_MESON_TAC[ARITH_RULE `!a b:num. a >= b /\ a < b ==> F`]));;

(* the port's own: what the three lemmas about the chain of conses
   that list_to_v builds share.  Each of them is an induction on the
   list the chain is of, and what the steps need is the three ways
   in which a value is one of the values of the refs and the stack,
   and the two ways in which a value of the chain and the stack is
   one of the chain's own. *)

(* a value of the head of the stack, a value of the rest of it, and
   a value of a shorter stack, are values of the refs and the
   stack *)

let av_in_stack = prove
 (`!x refs stack'.
     MEM x (v_all_vs stack') ==> x IN all_vs refs stack'`,
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[]);;

let av_in_cons = prove
 (`!x refs v l.
     MEM x (v_all_vs [v]) ==> x IN all_vs refs (v :: l)`,
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[MEM_v_all_vs_extend_tl]);;

let av_in_tl = prove
 (`!x refs v l. x IN all_vs refs l ==> x IN all_vs refs (v :: l)`,
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[MEM_v_all_vs_extend_hd]);;

(* and a value of the refs and a stack is one of the stack or one
   of the refs and any other stack *)

let av_in_refs = prove
 (`!x refs l1 l2.
     x IN all_vs refs l1
     ==> MEM x (v_all_vs l1) \/ x IN all_vs refs l2`,
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[]);;

(* the set of a stack without one of its values is a part of the
   set with it, and the other way about *)

let av_shrink2 = prove
 (`!x refs t h h' l.
     ~(x IN all_vs refs (t :: h :: h' :: l))
     ==> ~(x IN all_vs refs (t :: h' :: l))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; DE_MORGAN_THM] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[MEM_v_all_vs_split; MEM_v_all_vs_extend_hd;
                MEM_v_all_vs_extend_tl]);;

let av_shrink = prove
 (`!x refs t h l.
     ~(x IN all_vs refs (t :: h :: l))
     ==> ~(x IN all_vs refs (t :: l))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; DE_MORGAN_THM] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[MEM_v_all_vs_split; MEM_v_all_vs_extend_hd;
                MEM_v_all_vs_extend_tl]);;

let av_grow = prove
 (`!x refs t h l.
     x IN all_vs refs (t :: l) ==> x IN all_vs refs (t :: h :: l)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  MESON_TAC[MEM_v_all_vs_split; MEM_v_all_vs_extend_hd;
            MEM_v_all_vs_extend_tl]);;

(* a value of the values of a chain of conses and a stack is the
   first Block of the chain, a value of the element it holds, or a
   value of the rest of the chain and the stack *)

let av_decomp = prove
 (`!x ts t h xs stack'.
     MEM x (v_all_vs (list_to_v ts t (h :: xs) :: stack')) ==>
     x = Block ts cons_tag [h; list_to_v (ts + 1) t xs] \/
     MEM x (v_all_vs [h]) \/
     MEM x (v_all_vs (list_to_v (ts + 1) t xs :: stack'))`,
  (let (_,vsing,_,_) = v_all_vs_clauses () in
   REPEAT GEN_TAC THEN REWRITE_TAC[dataSem_list_to_v_def] THEN
   DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC o
               MATCH_MP MEM_v_all_vs_split) THENL
    [FIRST_ASSUM(fun m ->
       if not (hd_is "MEM" (concl m)) then fail() else
       MP_TAC(REWRITE_RULE[vsing; MEM] m)) THEN
     DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
      [ASM_REWRITE_TAC[];
       FIRST_ASSUM(fun m ->
         if not (hd_is "MEM" (concl m)) then fail() else
         DISJ_CASES_THEN ASSUME_TAC
           (MATCH_MP MEM_v_all_vs_split m)) THEN
       ASM_MESON_TAC[MEM_v_all_vs_extend_tl;
                     MEM_v_all_vs_extend_hd]];
     ASM_MESON_TAC[MEM_v_all_vs_extend_hd]]));;

(* and of the two ways that are left when the value is none of the
   list and the stack, the one through the element the chain holds
   is out, because that element is on the stack *)

let av_decomp2 = prove
 (`!x refs ts t h xs stack'.
     MEM x (v_all_vs (list_to_v ts t (h :: xs) :: stack')) /\
     ~(x IN all_vs refs (t :: ((h :: xs) ++ stack'))) ==>
     x = Block ts cons_tag [h; list_to_v (ts + 1) t xs] \/
     MEM x (v_all_vs (list_to_v (ts + 1) t xs :: stack'))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[APPEND] THEN STRIP_TAC THEN
  FIRST_ASSUM(fun m ->
    if not (hd_is "MEM" (concl m)) then fail() else
    STRIP_ASSUME_TAC(MATCH_MP av_decomp m)) THEN
  ASM_MESON_TAC[av_in_cons; av_in_tl]);;

(* a Block of the chain's own timestamp that is a value of the rest
   of the chain is a value of the list and the stack *)

let av_no_mix = prove
 (`!refs ts t h xs stack' a2 xs2.
     MEM (Block ts a2 xs2)
       (v_all_vs (list_to_v (ts + 1) t xs :: stack'))
     ==> Block ts a2 xs2 IN
           all_vs refs (t :: ((h :: xs) ++ stack'))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  FIRST_ASSUM(fun m ->
    MP_TAC(MATCH_MP v_all_vs_list_to_v1
      (CONJ (ARITH_RULE `ts < ts + 1`) m))) THEN
  REWRITE_TAC[APPEND] THEN
  ASM_MESON_TAC[av_in_stack; av_grow]);;

(* and one below the chain's timestamps that is a value of the refs
   and the chain is a value of the refs and the list *)

let av_in_shift = prove
 (`!refs ts t xs stack' t1 a1 xs1.
     t1 < ts /\
     Block t1 a1 xs1 IN all_vs refs (list_to_v ts t xs :: stack')
     ==> Block t1 a1 xs1 IN all_vs refs (t :: (xs ++ stack'))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM] THEN
  STRIP_TAC THEN ASM_MESON_TAC[v_all_vs_list_to_v1]);;

(* while one of the chain's timestamps that is a value of the refs
   and the chain is a value of the chain itself: a value of the
   refs would be one of the list and the stack, which
   blocks_unique_GT_ts says it is not *)

let av_in_mem = prove
 (`!refs ts t xs stack' t1 a1 xs1.
     blocks_unique ts (all_vs refs (t :: (xs ++ stack'))) /\
     ts <= t1 /\ ~(xs1 = []) /\
     Block t1 a1 xs1 IN all_vs refs (list_to_v ts t xs :: stack')
     ==> MEM (Block t1 a1 xs1)
           (v_all_vs (list_to_v ts t xs :: stack'))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(fun inn ->
    if not (is_binary "IN" (concl inn)) then fail() else
    DISJ_CASES_THEN2 ACCEPT_TAC
      (fun inn2 ->
         ASSUME_TAC inn2 THEN
         ASM_MESON_TAC[GEN_ALL blocks_unique_GT_ts;
                       ARITH_RULE `!a b:num. b <= a ==> a >= b`])
      (SPEC `(t:dataSem_v) :: (xs ++ stack')`
         (MATCH_MP av_in_refs inn))));;

(* the Block of an assumption that says a value is one of the refs
   and a stack, the list it holds, and the assumption that says
   that list is not empty *)

let av_blocks (asl,w) =
  map snd (filter (fun (_,th) ->
    is_binary "IN" (concl th) &&
    hd_is "all_vs" (rand(concl th))) asl);;

let av_xs_of th = last(snd(strip_comb(lhand(concl th))));;

let av_a_of th = el 1 (snd(strip_comb(lhand(concl th))));;

let av_find p (asl,w) =
  snd(find (fun (_,th) -> p (concl th)) asl);;

let av_nn g x =
  av_find (fun t -> is_neg t && is_eq (dest_neg t) &&
                    lhand(dest_neg t) = x) g;;

let Block_NOT_IN_all_vs = prove
 (`!xs t t' a2 xs2 h stack' refs. ~(Block t' a2 xs2 IN all_vs refs (t ::
  h :: (xs ++ stack'))) ==>
     (!m. m > 0 ==> ~(MEM (Block t' a2 xs2) (v_all_vs [list_to_v
       (t' + m) t xs])))`,
  (* the chain of no elements is the value it ends with, which is
     on the stack, and of one more it is a Block of a later
     timestamp, whose values are the element's -- also on the stack
     -- and the rest of the chain's, which the induction
     hypothesis is about at one timestamp more *)
  ((let (_,vsing,_,_) = v_all_vs_clauses () in
    LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
    RULE_ASSUM_TAC(REWRITE_RULE[APPEND]) THEN
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    REWRITE_TAC[dataSem_list_to_v_def] THENL
     [DISCH_TAC THEN ASM_MESON_TAC[av_in_cons];
      REWRITE_TAC[vsing; MEM; DE_MORGAN_THM] THEN CONJ_TAC THENL
       [DISCH_THEN(fun eq ->
          MP_TAC(REWRITE_RULE[injectivity "dataSem_v"] eq)) THEN
        ASM_ARITH_TAC;
        DISCH_TAC THEN
        FIRST_ASSUM(fun m ->
          if not (hd_is "MEM" (concl m)) then fail() else
          DISJ_CASES_THEN ASSUME_TAC
            (MATCH_MP MEM_v_all_vs_split m)) THEN
        FIRST_ASSUM(fun nin ->
          if not (is_neg (concl nin)) then fail() else
          FIRST_ASSUM(fun ih ->
            if not (is_forall (concl ih)) then fail() else
            let sh = MATCH_MP av_shrink2 nin in
            let th = MATCH_MP (MATCH_MP ih sh)
                       (ARITH_RULE `m + 1 > 0`) in
            MP_TAC(REWRITE_RULE
              [ARITH_RULE `t' + (m + 1) = (t' + m) + 1`] th))) THEN
        ASM_MESON_TAC[av_in_cons; av_in_tl]]])));;

let v_all_vs_list_to_v2 = prove
 (`!xs t' a1 a2 xs1 xs2 ts t stack' refs.
   MEM (Block t' a1 xs1) (v_all_vs (list_to_v ts t xs :: stack')) /\
     ~(xs1 = []) /\
   MEM (Block t' a2 xs2) (v_all_vs (list_to_v ts t xs :: stack')) /\
     ~(xs2 = []) /\ ~(Block t' a1 xs1 IN all_vs refs (t :: (xs ++
     stack'))) /\ ~(Block t' a2 xs2 IN all_vs refs (t :: (xs ++
     stack'))) ==>
     a1 = a2 /\ xs1 = xs2 /\ t' < ts + LENGTH xs`,
  (* each of the two Blocks is the chain's first Block or a value
     of the rest of the chain, because the hypothesis says neither
     is a value of the list and the stack.  Two first Blocks are
     the same Block; a first Block and one of the rest cannot have
     the same timestamp (av_no_mix); and two of the rest are what
     the induction hypothesis is about *)
  ((let inj = injectivity "dataSem_v" in
    let blk th = hd(snd(strip_comb(concl th))) in
    let not_in x t =
      is_neg t && is_binary "IN" (dest_neg t) &&
      lhand(dest_neg t) = x in
    LIST_INDUCT_TAC THENL
     [REPEAT GEN_TAC THEN DISCH_THEN STRIP_ASSUME_TAC THEN
      RULE_ASSUM_TAC(REWRITE_RULE[dataSem_list_to_v_def; APPEND]) THEN
      ASM_MESON_TAC[av_in_stack];
      REPEAT GEN_TAC THEN DISCH_THEN STRIP_ASSUME_TAC THEN
      W(fun g ->
        let (asl,w) = g in
        let mems = map snd (filter (fun (_,th) ->
          hd_is "MEM" (concl th)) asl) in
        let d th =
          MATCH_MP av_decomp2
            (CONJ th (av_find (not_in (blk th)) g)) in
        let d1 = d (hd mems) and d2 = d (hd(tl mems)) in
        DISJ_CASES_THEN2
          (fun e1 ->
            DISJ_CASES_THEN2
              (fun e2 ->
                STRIP_ASSUME_TAC(REWRITE_RULE[inj] e1) THEN
                STRIP_ASSUME_TAC(REWRITE_RULE[inj] e2) THEN
                ASM_REWRITE_TAC[LENGTH] THEN ASM_ARITH_TAC)
              (fun c2 ->
                ASSUME_TAC c2 THEN
                SUBST_ALL_TAC(CONJUNCT1(REWRITE_RULE[inj] e1)) THEN
                ASM_MESON_TAC[av_no_mix])
              d2)
          (fun c1 ->
            DISJ_CASES_THEN2
              (fun e2 ->
                ASSUME_TAC c1 THEN
                SUBST_ALL_TAC(CONJUNCT1(REWRITE_RULE[inj] e2)) THEN
                ASM_MESON_TAC[av_no_mix])
              (fun c2 ->
                W(fun g2 ->
                  let nin th =
                    MATCH_MP av_shrink (REWRITE_RULE[APPEND]
                      (av_find (not_in (blk th)) g2)) in
                  FIRST_ASSUM(fun ih ->
                    if not (is_forall (concl ih)) then fail() else
                    MP_TAC(MATCH_MP ih
                      (CONJ c1 (CONJ (av_nn g2 (last(snd(strip_comb
                         (blk c1))))) (CONJ c2 (CONJ (av_nn g2
                         (last(snd(strip_comb (blk c2)))))
                           (CONJ (nin c1) (nin c2))))))))) THEN
                REWRITE_TAC[LENGTH] THEN STRIP_TAC THEN
                ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC)
              d2)
          d1)])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let blocks_unique_cons_multi = prove
 (cake_as_vars (fun () ->
    `blocks_unique ts (all_vs refs (t :: (xs ++ stack))) ==>
       blocks_unique (ts + LENGTH xs) (all_vs refs (list_to_v ts
         t xs :: stack))`),
  (* a Block of the chain and the stack is below the chain's
     timestamps, and then it is a value of the list and the stack,
     of which the hypothesis speaks; or it is one of the chain's
     own, and then it is a value of the chain (av_in_mem) that the
     theorem before this one is about *)
  (DISCH_TAC THEN REWRITE_TAC[blocks_unique_def] THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN
   W(fun (asl,w) ->
     let third = rand(rand w) in
     ASM_CASES_TAC
       (mk_binary "<" (lhand third, lhand(rand third)))) THENL
    [W(fun g ->
       let lt = av_find (fun t -> is_binary "<" t) g in
       let ins = av_blocks g in
       let bu = REWRITE_RULE[blocks_unique_def]
                  (av_find (hd_is "blocks_unique") g) in
       let i1 = MATCH_MP av_in_shift (CONJ lt (el 0 ins))
       and i2 = MATCH_MP av_in_shift (CONJ lt (el 1 ins)) in
       STRIP_ASSUME_TAC(MATCH_MP bu
         (CONJ i1 (CONJ (av_nn g (av_xs_of (el 0 ins)))
           (CONJ i2 (av_nn g (av_xs_of (el 1 ins)))))))) THEN
     ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
     W(fun g ->
       let notlt = av_find (fun t ->
         is_neg t && is_binary "<" (dest_neg t)) g in
       let ins = av_blocks g in
       let bu = av_find (hd_is "blocks_unique") g in
       let t1 = lhand(dest_neg(concl notlt))
       and ts = rand(dest_neg(concl notlt)) in
       let le = MP (ARITH_RULE (mk_imp(concl notlt,
                  mk_binary "<=" (ts,t1)))) notlt in
       let ge = MP (ARITH_RULE (mk_imp(concl notlt,
                  mk_binary ">=" (t1,ts)))) notlt in
       let mem inn = MATCH_MP av_in_mem
         (CONJ bu (CONJ le (CONJ (av_nn g (av_xs_of inn)) inn))) in
       let notin inn = SPEC (av_a_of inn)
         (MATCH_MP (GEN_ALL blocks_unique_GT_ts)
            (CONJ bu (CONJ ge (av_nn g (av_xs_of inn))))) in
       STRIP_ASSUME_TAC(MATCH_MP (GEN_ALL v_all_vs_list_to_v2)
         (CONJ (mem (el 0 ins)) (CONJ (av_nn g (av_xs_of (el 0 ins)))
           (CONJ (mem (el 1 ins)) (CONJ (av_nn g
             (av_xs_of (el 1 ins)))
             (CONJ (notin (el 0 ins)) (notin (el 1 ins))))))))) THEN
     ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let cons_multi_thm = prove
 (cake_as_vars (fun () ->
    `abs_ml_inv conf ((t :: xs) ++ stack) refs
  (roots,heap,be,a,sp,sp1,gens) limit ts /\
     3 * LENGTH xs <= sp /\ ~(xs = []) ==>
        (?rt rs roots2 heap1 heap2.
          let Allocd = list_to_BlockReps conf rt a rs in
            (roots = (rt :: rs) ++ roots2) /\ (LENGTH rs = LENGTH
              xs) /\
            heap = heap1 ++ heap_expand (sp + sp1) ++ heap2 /\
            a = heap_length heap1 /\
            abs_ml_inv conf
              (list_to_v ts t xs :: stack) refs
              (gc_shared_Pointer a (wordLang_Word (ptr_bits conf
                cons_tag 2)) :: roots2,
               heap1 ++ Allocd ++ heap_expand ((sp + sp1) -
                 heap_length Allocd) ++ heap2,be,
               a + heap_length Allocd,sp - heap_length
                 Allocd,sp1,gens) limit (ts + LENGTH xs))`),
  (* the attempt: the proof of the source names abs_ml_inv_def,
     bc_stack_ref_inv_def, LIST_REL_SPLIT1, LIST_REL_LENGTH,
     unused_space_inv_def, heap_lookup_SPLIT.  What is here rewrites
     with them and closes by arithmetic, and the cheat is behind it
     until the proof is written.  A MESON over them is what the next
     round adds; it costs a load ten minutes to have it in every
     attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[abs_ml_inv_def; bc_stack_ref_inv_def;
       LIST_REL_SPLIT1; LIST_REL_LENGTH; unused_space_inv_def;
       heap_lookup_SPLIT] THEN
     TRY ASM_ARITH_TAC)));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_append = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m1 dm
        (((v,h) :: ZIP in1 ws) ++ vars) /\
      (misc_word_list next_free
        (append_writes c init_ptr (make_header c (n2w 0) 2) ws h) *
          SEP_T)
        (fun2set (m1,dm)) /\
      1 < data_to_word_config_len_size c /\
      LENGTH in1 = LENGTH ws /\ ~(in1 = []) /\
      3 * LENGTH in1 <= sp /\ good_dimindex (:'a) /\
      wordLang_Word init_ptr = make_cons_ptr c (next_free - curr) 0
        2 /\
      FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
      FLOOKUP st NextFree = SOME (wordLang_Word (next_free:'a
        word)) ==>
      memory_rel c be (ts + LENGTH in1) refs (sp - 3 * LENGTH in1)
         (st |+ (NextFree,
                 wordLang_Word (next_free + bytes_in_word * n2w (3
                   * LENGTH in1)))) m1 dm
         ((list_to_v ts v in1,wordLang_Word init_ptr) :: vars)`),
(* the invariant of a list that the append built: cons_multi_thm
   gives the blocks of the values in the unused space and the
   invariant of the list that points at them, and what is left to
   see is that the words of the statement are the heap of those
   blocks.  The writes of the append are in the memory already (the
   hypothesis of the statement), so
   word_list_AND_word_list_exists_IMP takes them out of the space
   that word_list_exists holds, and
   append_writes_list_to_BlockReps says that those words are the
   word_heap of list_to_BlockReps -- the lemma wants the lists as
   conses, which the lengths of the statement make them.  The
   pointer of the list is make_cons_ptr of the offset, which the
   statement gives, and the space the blocks take is three words to
   a value (list_to_BlockReps_heap_length and
   append_writes_LENGTH) *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  let front sp cell =
    let pred = rator (concl sp) in
    let fs = facs pred in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk x y = mk_comb(mk_comb(st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target),
              REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
    REWRITE_RULE[eq] sp in
  (* an ALL2 over two appends of matching lengths *)
  let all2app = prove
   (`!(P:A->B->bool) xs1 ys1 xs2 ys2.
       LENGTH xs1 = LENGTH ys1
       ==> (ALL2 P (xs1 ++ xs2) (ys1 ++ ys2) <=>
            ALL2 P xs1 ys1 /\ ALL2 P xs2 ys2)`,
    GEN_TAC THEN LIST_INDUCT_TAC THENL
     [X_GEN_TAC `ys1:(B)list` THEN
      STRUCT_CASES_TAC (ISPEC `ys1:(B)list` list_CASES) THEN
      REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC;
                  ARITH_RULE `~(0 = SUC n)`];
      X_GEN_TAC `ys1:(B)list` THEN
      STRUCT_CASES_TAC (ISPEC `ys1:(B)list` list_CASES) THEN
      REWRITE_TAC[LENGTH; APPEND; ALL2; NOT_SUC;
                  ARITH_RULE `~(SUC n = 0)`; SUC_INJ] THEN
      REPEAT GEN_TAC THEN DISCH_TAC THEN
      ASM_SIMP_TAC[] THEN CONV_TAC TAUT]) in
  (* two steps of an address in one *)
  let addsum = prove
   (`!(a:'a word) x y.
       a + bytes_in_word * n2w x + bytes_in_word * n2w y =
       a + bytes_in_word * n2w (x + y)`,
    REWRITE_TAC[WORD_ADD] THEN CONV_TAC WORD_RULE) in
  (* the numeric facts that the assumptions give *)
  let numfacts asl =
    mapfilter (fun (_,th) ->
      let c = concl th in
      if (try hd_is "<=" c || hd_is "<" c ||
              (is_eq c && hd_is "LENGTH" (lhs c) &&
               hd_is "LENGTH" (rhs c))
          with Failure _ -> false) then th else fail()) asl in
  let addreq asl t1 t2 =
      let fs = numfacts asl in
      let extra = (try
        let lt = grab asl (fun th ->
          try hd_is "<" (concl th) &&
              hd_is "LENGTH" (lhand (concl th))
          with Failure _ -> false) in
        let spe = grab asl (fun th ->
          try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
              is_var (rand (concl th))
          with Failure _ -> false) in
        [MATCH_MP (ARITH_RULE
           `!a b c:num. a < b /\ b <= c ==> a + 1 <= c`)
           (CONJ lt spe)]
        with Failure _ -> []) in
      let cnd = end_itlist CONJ (fs @ extra) in
      MP (prove (mk_imp (concl cnd, mk_eq (t1,t2)),
            DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
              (fun th -> ASSUME_TAC
                 (REWRITE_RULE[LENGTH; ADD1] th))) THEN
            ASM_REWRITE_TAC[BlockRep_def; el_length_def;
                            LENGTH; ADD1] THEN
            REWRITE_TAC[WORD_SUB; WORD_ADD] THEN
            ASM_SIMP_TAC[ARITH_RULE
              `!l s h:num. l <= s ==> l <= h + s`;
              ARITH_RULE
              `!a b c:num. a <= b /\ b <= c ==> a <= c`] THEN
            CONV_TAC WORD_RULE)) cnd in
  let wordeq =
    W(fun (asl,gl) ->
      REWRITE_TAC[addreq asl (rand (rand (lhs gl)))
                    (rand (rand (rhs gl)))]) in
  (* a store that says the same of a key, with the numbers of the
     new element in place of the old ones *)
  let numeq =
    W(fun (asl,gl) ->
      let fl = grab asl (fun th ->
        try hd_is "FLOOKUP" (lhs (concl th)) &&
            rand (lhs (concl th)) = rand (lhs gl) &&
            not (concl th = gl)
        with Failure _ -> false) in
      let isn t = (try hd_is "word" t &&
                       type_of (rand t) = `:num` &&
                       not (is_numeral (rand t))
                   with Failure _ -> false) in
      let ge = find_term isn (rhs gl) in
      let fe = find_term isn (rhs (concl fl)) in
      let fs = numfacts asl in
      let cnd = end_itlist CONJ fs in
      let eq = MP (prove (mk_imp (concl cnd,
                    mk_eq (rand ge, rand fe)),
                  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
                    ASSUME_TAC) THEN
                  REWRITE_TAC[BlockRep_def; el_length_def;
                              LENGTH; ADD1] THEN
                  ASM_ARITH_TAC)) cnd in
      REWRITE_TAC[eq] THEN FIRST_ASSUM ACCEPT_TAC) in
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* what the invariant says of the stack *)
  FIRST_ASSUM (fun mr ->
    if hd_is "memory_rel" (concl mr)
    then MP_TAC (REWRITE_RULE[memory_rel_def; word_ml_inv_def;
                              MAP; FST; SND; MAP_APPEND] mr)
    else fail()
  ) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the values and the words that the ZIP of the stack holds *)
  W(fun (asl,gl) ->
    let le = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    RULE_ASSUM_TRY (REWRITE_RULE[MATCH_MP MAP_FST_ZIP le;
                                 MATCH_MP MAP_SND_ZIP le])) THEN
  (* the blocks that the append makes of the values *)
  W(fun (asl,gl) ->
    let ai = grab asl (fun th -> hd_is "abs_ml_inv" (concl th)) in
    let lt = grab asl (fun th ->
      try hd_is "<=" (concl th) && hd_is "*" (lhand (concl th))
      with Failure _ -> false) in
    let spe = grab asl (fun th ->
      try hd_is "<=" (concl th) && is_var (lhand (concl th)) &&
          is_var (rand (concl th))
      with Failure _ -> false) in
    let bnd = MATCH_MP (ARITH_RULE
                `!a b c:num. a <= b /\ b <= c ==> a <= c`)
                (CONJ lt spe) in
    let ne = grab asl (fun th ->
      try hd_is "NIL" (rhs (dest_neg (concl th)))
      with Failure _ -> false) in
    MP_TAC (MATCH_MP (GEN_ALL cons_multi_thm)
      (CONJ ai (CONJ bnd ne)))) THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* the roots of the blocks and the roots of the stack *)
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                (hd_is "APPEND" (rhs (concl e)) ||
                 hd_is "heap_length" (rhs (concl e)))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      try hd_is "ALL2" (concl th) &&
          hd_is "APPEND" (el 1 (snd(strip_comb (concl th))))
      with Failure _ -> false) in
    let a2b = REWRITE_RULE[GSYM APPEND] a2 in
    let args = snd(strip_comb (concl a2b)) in
    let l1 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) =
            mk_icomb (`LENGTH`,rand (lhand (el 1 args)))
      with Failure _ -> false) in
    let l2 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) = rhs (concl l1) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    let rw = TRANS l1 l2 in
    let le = MP (prove (mk_imp (concl rw,
                  mk_eq (mk_icomb (`LENGTH`,lhand (el 1 args)),
                         mk_icomb (`LENGTH`,
                           lhand (el 2 args)))),
                DISCH_TAC THEN ASM_REWRITE_TAC[LENGTH])) rw in
    STRIP_ASSUME_TAC (REWRITE_RULE[MATCH_MP all2app le; ALL2]
      a2b)) THEN
  (* the ends of the heap that the store holds *)
  FIRST_ASSUM (fun hs ->
    if hd_is "heap_in_memory_store" (concl hs)
    then STRIP_ASSUME_TAC
           (REWRITE_RULE[heap_in_memory_store_def] hs)
    else fail()) THEN
  (* the store says the same of its keys as the statement *)
  MAP_EVERY (fun n ->
    W(fun (asl,gl) ->
      let fs = mapfilter (fun (_,th) ->
        if (try hd_is "FLOOKUP" (lhs (concl th)) &&
                fst (dest_const (rand (lhs (concl th)))) = n
            with Failure _ -> false) then th else fail()) asl in
      if length fs < 2 then ALL_TAC else
      let eq = REWRITE_RULE[injectivity "option";
                 injectivity "word_loc"]
                 (TRANS (SYM (el 0 fs)) (el 1 fs)) in
      SUBST_ALL_TAC (if is_var (lhs (concl eq)) then eq
                     else SYM eq)))
    ["CurrHeap"; "NextFree"] THEN
  (* the words of the unused space, where the blocks go *)
  W(fun (asl,gl) ->
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          length (filter (hd_is "word_heap")
                    (facs (rator (concl th)))) = 2
      with Failure _ -> false) in
    ASSUME_TAC (REWRITE_RULE[word_heap_APPEND;
      word_heap_heap_expand; heap_length_APPEND;
      heap_length_heap_expand; STAR_ASSOC] sep)) THEN
  (* which the writes of the statement have filled *)
  W(fun (asl,gl) ->
    let hyp = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists (hd_is "SEP_T") (facs (rator (concl th)))
      with Failure _ -> false) in
    let iscell t = hd_is "word_list_exists" t &&
                   not (is_var (el 1 (snd(strip_comb t)))) in
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists iscell (facs (rator (concl th)))
      with Failure _ -> false) in
    let cell = find iscell (facs (rator (concl sep))) in
    let aw = el 1 (snd(strip_comb (find (hd_is "misc_word_list")
               (facs (rator (concl hyp)))))) in
    let ne = grab asl (fun th ->
      try hd_is "NIL" (rhs (dest_neg (concl th)))
      with Failure _ -> false) in
    let wsl = el 3 (snd(strip_comb aw)) in
    let inst = PART_MATCH (lhs o snd o dest_imp)
                 append_writes_LENGTH
                 (mk_icomb (`LENGTH`,aw)) in
    let nel = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          rhs (concl th) = mk_icomb (`LENGTH`,wsl)
      with Failure _ -> false) in
    let nw = MP (prove (mk_imp (mk_conj (concl ne, concl nel),
                  lhand (concl inst)),
                DISCH_THEN (CONJUNCTS_THEN ASSUME_TAC) THEN
                REWRITE_TAC[GSYM LENGTH_EQ_NIL] THEN
                FIRST_ASSUM (fun le ->
                  if not (try is_eq (concl le) &&
                              hd_is "LENGTH" (lhs (concl le))
                          with Failure _ -> false) then fail()
                  else REWRITE_TAC[GSYM le]) THEN
                ASM_REWRITE_TAC[LENGTH_EQ_NIL]))
                (CONJ ne nel) in
    let awl = MP inst nw in
    let fs = numfacts asl in
    let cnd = end_itlist CONJ fs in
    let b0 = MP (prove (mk_imp (concl cnd,
                  mk_binop `(<=):num->num->bool` (rhs (concl awl))
                    (el 1 (snd(strip_comb cell)))),
                DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
                  ASSUME_TAC) THEN
                ASM_ARITH_TAC)) cnd in
    let bnd = REWRITE_RULE[GSYM awl] b0 in
    ASSUME_TAC (MATCH_MP word_list_AND_word_list_exists_IMP
      (CONJ hyp (CONJ (front sep cell) bnd)))) THEN
  (* the invariant with the blocks in the heap *)
  REWRITE_TAC[memory_rel_def] THEN
  W(fun (asl,gl) ->
    let ai = grab asl (fun th ->
      hd_is "abs_ml_inv" (concl th) &&
      (try hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
       with Failure _ -> false)) in
    let args = snd(strip_comb (concl ai)) in
    let ps = tparts (el 3 args) in
    MAP_EVERY EXISTS_TAC
      [el 1 ps; el 4 args; el 3 ps; el 4 ps; el 5 ps; el 6 ps]) THEN
  REPEAT CONJ_TAC THENL
   [ALL_TAC;
    (* the roots: the pointer of the blocks and the rest *)
    REWRITE_TAC[word_ml_inv_def] THEN
    W(fun (asl,gl) ->
      let ai = grab asl (fun th ->
        hd_is "abs_ml_inv" (concl th) &&
        (try hd_is "CONS" (el 1 (snd(strip_comb (concl th))))
         with Failure _ -> false)) in
      EXISTS_TAC
        (el 0 (tparts (el 3 (snd(strip_comb (concl ai))))))) THEN
    REWRITE_TAC[MAP; FST; SND; ALL2] THEN
    CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
    REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
    (* the word of the pointer is the one the statement gives *)
    W(fun (asl,gl) ->
      let mkp = grab asl (fun th ->
        try is_eq (concl th) &&
            hd_is "make_cons_ptr" (rhs (concl th))
        with Failure _ -> false) in
      let sub = el 1 (snd(strip_comb (rhs (concl mkp)))) in
      let pt = lhand (rand (lhs gl)) in
      let bwterm = rand (lhand sub) in
      let mulp = mk_comb (rator bwterm,
                   mk_comb (rator (rand bwterm), pt)) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      REWRITE_TAC[mkp] THEN
      SUBST1_TAC (addreq asl sub mulp) THEN
      REWRITE_TAC(word_addr_clauses ()) THEN
      REWRITE_TAC[make_cons_ptr_thm; get_addr_def;
                  get_lowerbits_ptrbits; cons_tag_def] THEN
      REWRITE_TAC[MATCH_MP bytes_in_word_mul_eq_shift gd;
                  WORD_SHL_COMPOSE] THEN
      ASM_SIMP_TAC[ARITH_RULE
        `!a b:num. a <= b ==> a + (b - a) = b`] THEN
      AP_TERM_TAC THEN WORD_BITWISE_TAC);
    FIRST_ASSUM ACCEPT_TAC;
    W(fun (asl,gl) ->
    let ne = grab asl (fun th ->
      try hd_is "NIL" (rhs (dest_neg (concl th)))
      with Failure _ -> false) in
    let lrs = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          rhs (concl th) = mk_icomb (`LENGTH`,
            lhand (dest_neg (concl ne)))
      with Failure _ -> false) in
    let bl = MATCH_MP list_to_BlockReps_heap_length
               (REWRITE_RULE[LENGTH_EQ_NIL]
                 (REWRITE_RULE[GSYM lrs]
                   (REWRITE_RULE[GSYM LENGTH_EQ_NIL] ne))) in
      let fs = numfacts asl in
      REWRITE_TAC[bl] THEN MP_TAC (end_itlist CONJ fs)) THEN
    REWRITE_TAC[LENGTH; ADD1] THEN ARITH_TAC] THEN
  (* the store of the new heap *)
  REWRITE_TAC[heap_in_memory_store_def] THEN
  W(fun (asl,gl) ->
    let ne = grab asl (fun th ->
      try hd_is "NIL" (rhs (dest_neg (concl th)))
      with Failure _ -> false) in
    let lrs = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          rhs (concl th) = mk_icomb (`LENGTH`,
            lhand (dest_neg (concl ne)))
      with Failure _ -> false) in
    let bl = MATCH_MP list_to_BlockReps_heap_length
               (REWRITE_RULE[LENGTH_EQ_NIL]
                 (REWRITE_RULE[GSYM lrs]
                   (REWRITE_RULE[GSYM LENGTH_EQ_NIL] ne))) in
    REWRITE_TAC[heap_length_APPEND; heap_length_heap_expand] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[heap_length_APPEND;
                                 heap_length_heap_expand]) THEN
    REWRITE_TAC[bl] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[bl])) THEN
  (* the length of the heap is the one it was *)
  W(fun (asl,gl) ->
    let nw = lhand (hd (conjuncts gl)) in
    let ol = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          rand (concl th) = rand (hd (conjuncts gl))
      with Failure _ -> false) in
    let fs = numfacts asl in
    let cnd = end_itlist CONJ fs in
    let eq = MP (prove (mk_imp (concl cnd,
                  mk_eq (nw, lhand (concl ol))),
                DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
                  ASSUME_TAC) THEN
                ASM_ARITH_TAC)) cnd in
    REWRITE_TAC[eq]) THEN
  W(fun (asl,gl) ->
    let dis = CONJUNCTS (distinctness "store_name") in
    REWRITE_TAC([FLOOKUP_UPDATE; FDOM_FUPDATE; IN_INSERT] @
                dis @ map GSYM dis)) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  (* the two heaps of the store *)
  W(fun (asl,gl) ->
    let flk n = grab asl (fun th ->
      try hd_is "FLOOKUP" (lhs (concl th)) &&
          fst (dest_const (rand (lhs (concl th)))) = n
      with Failure _ -> false) in
    MAP_EVERY EXISTS_TAC
      [rand (rand (rhs (concl (flk "CurrHeap"))));
       rand (rand (rhs (concl (flk "OtherHeap"))))]) THEN
  REPEAT CONJ_TAC THEN TRY (FIRST_ASSUM ACCEPT_TAC) THEN
  TRY (wordeq THEN NO_TAC) THEN
  TRY (numeq THEN NO_TAC) THEN
  (* the writes of the append are the heap of the blocks *)
  W(fun (asl,gl) ->
    let wa = grab asl (fun th ->
      try is_eq (concl th) && hd_is "word_addr" (lhs (concl th))
      with Failure _ -> false) in
    RULE_ASSUM_TRY (REWRITE_RULE[GSYM wa])) THEN
  W(fun (asl,gl) ->
    let ne = grab asl (fun th ->
      try hd_is "NIL" (rhs (dest_neg (concl th)))
      with Failure _ -> false) in
    let lrs = grab asl (fun th ->
      try is_eq (concl th) && hd_is "LENGTH" (lhs (concl th)) &&
          rhs (concl th) = mk_icomb (`LENGTH`,
            lhand (dest_neg (concl ne)))
      with Failure _ -> false) in
    let lws = grab asl (fun th ->
      try is_eq (concl th) &&
          lhs (concl th) = mk_icomb (`LENGTH`,
            lhand (dest_neg (concl ne))) &&
          hd_is "LENGTH" (rhs (concl th))
      with Failure _ -> false) in
    let ne0 = REWRITE_RULE[GSYM LENGTH_EQ_NIL] ne in
    let rsne = REWRITE_RULE[LENGTH_EQ_NIL]
                 (REWRITE_RULE[GSYM lrs] ne0) in
    let wsne = REWRITE_RULE[LENGTH_EQ_NIL]
                 (REWRITE_RULE[lws] ne0) in
    ASSUME_TAC rsne THEN ASSUME_TAC wsne THEN
    CASES_ON_TAC (rand (lhs (concl lrs))) THEN
    CASES_ON_TAC (rand (rhs (concl lws)))) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[]) THEN
  TRY (FIRST_ASSUM CONTR_TAC) THEN
  (* which is what append_writes_list_to_BlockReps says *)
  REWRITE_TAC[word_heap_APPEND; word_heap_heap_expand;
              heap_length_APPEND; heap_length_heap_expand;
              STAR_ASSOC] THEN
  W(fun (asl,gl) ->
    let a2 = grab asl (fun th ->
      try hd_is "ALL2" (concl th) &&
          hd_is "CONS" (el 1 (snd(strip_comb (concl th)))) &&
          hd_is "CONS" (el 2 (snd(strip_comb (concl th))))
      with Failure _ -> false) in
    let args = snd(strip_comb (concl a2)) in
    let l1 = grab asl (fun th ->
      try is_eq (concl th) &&
          lhs (concl th) = mk_icomb (`LENGTH`,el 1 args)
      with Failure _ -> false) in
    let l2 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) = rhs (concl l1) &&
          rhs (concl th) = mk_icomb (`LENGTH`,el 2 args)
      with Failure _ -> false) in
    let le = REWRITE_RULE[LENGTH; SUC_INJ] (TRANS l1 l2) in
    let gd = grab asl (fun th ->
      hd_is "good_dimindex" (concl th)) in
    let ls = grab asl (fun th ->
      try hd_is "<" (concl th) && is_numeral (lhand (concl th)) &&
          hd_is "data_to_word_config_len_size" (rand (concl th))
      with Failure _ -> false) in
    let ls7 = grab asl (fun th ->
      try hd_is "<" (concl th) && hd_is "+" (lhand (concl th)) &&
          hd_is "data_to_word_config_len_size"
            (lhand (lhand (concl th)))
      with Failure _ -> false) in
    let ls5 = MATCH_MP (ARITH_RULE
                `!a b:num. a + 7 < b ==> a + 5 < b`) ls7 in
    let wsh = grab asl (fun th ->
      try hd_is "<=" (concl th) &&
          hd_is "shift_length" (rand (concl th))
      with Failure _ -> false) in
    let mkp0 = grab asl (fun th ->
      try is_eq (concl th) &&
          hd_is "make_cons_ptr" (rhs (concl th))
      with Failure _ -> false) in
    let sub = el 1 (snd(strip_comb (rhs (concl mkp0)))) in
    let bwterm = rand (lhand sub) in
    let offs = el 2 (snd(strip_comb (find_term
                 (hd_is "list_to_BlockReps") gl))) in
    let mulp = mk_comb (rator bwterm,
                 mk_comb (rator (rand bwterm), offs)) in
    let mkp = REWRITE_RULE[addreq asl sub mulp] mkp0 in
    let lem = MATCH_MP (GEN_ALL append_writes_list_to_BlockReps)
                (CONJ le (CONJ gd (CONJ ls (CONJ ls5
                   (CONJ wsh (CONJ a2 mkp)))))) in
    REWRITE_TAC[GSYM lem]) THEN
  W(fun (asl,gl) ->
    let sep = grab asl (fun th ->
      try hd_is "STAR" (rator (concl th)) &&
          exists (hd_is "misc_word_list") (facs (rator (concl th)))
      with Failure _ -> false) in
    let aw = find_term (hd_is "append_writes") (concl sep) in
    let ne = grab asl (fun th ->
      try hd_is "NIL" (rhs (dest_neg (concl th))) &&
          lhand (dest_neg (concl th)) =
            el 3 (snd(strip_comb aw))
      with Failure _ -> false) in
    let awl = MP (PART_MATCH (lhs o snd o dest_imp)
                append_writes_LENGTH (mk_icomb (`LENGTH`,aw))) ne in
    let bls = find_term (hd_is "list_to_BlockReps") gl in
    let ne2 = grab asl (fun th ->
      try hd_is "NIL" (rhs (dest_neg (concl th))) &&
          lhand (dest_neg (concl th)) =
            el 3 (snd(strip_comb bls))
      with Failure _ -> false) in
    let bl = MATCH_MP list_to_BlockReps_heap_length ne2 in
    let sep2 = REWRITE_RULE[awl; word_heap_heap_expand;
                 STAR_ASSOC; emp_STAR; STAR_emp; addsum] sep in
    let l1 = grab asl (fun th ->
      try is_eq (concl th) &&
          lhs (concl th) = mk_icomb (`LENGTH`,
            el 3 (snd(strip_comb bls)))
      with Failure _ -> false) in
    let l2 = grab asl (fun th ->
      try is_eq (concl th) && lhs (concl th) = rhs (concl l1) &&
          rhs (concl th) = mk_icomb (`LENGTH`,
            el 3 (snd(strip_comb aw)))
      with Failure _ -> false) in
    let leq = TRANS l1 l2 in
    let cnt = el 1 (snd(strip_comb (find
                (hd_is "word_list_exists")
                (facs (rator (concl sep2)))))) in
    let fs = numfacts asl in
    let cnd = end_itlist CONJ fs in
    let ar = MP (prove (mk_imp (concl cnd,
                  mk_eq (mk_binop `(+):num->num->num`
                           (rand cnt) cnt, lhand cnt)),
                DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN
                  (fun th -> ASSUME_TAC
                     (REWRITE_RULE[LENGTH] th))) THEN
                REWRITE_TAC[LENGTH] THEN ASM_ARITH_TAC)) cnd in
    REWRITE_TAC[bl; leq] THEN
    W(fun (asl2,gl2) ->
      let gwh = filter (hd_is "word_heap") (facs (rator gl2)) in
      let swh = filter (hd_is "word_heap")
                  (facs (rator (concl sep2))) in
      let a1t,a2t = tryfind (fun g -> tryfind (fun h ->
          if el 1 (snd(strip_comb g)) = el 1 (snd(strip_comb h)) &&
             not (el 0 (snd(strip_comb g)) =
                  el 0 (snd(strip_comb h)))
          then (el 0 (snd(strip_comb g)),
                el 0 (snd(strip_comb h)))
          else fail()) swh) gwh in
      let xt = lhand (lhand a1t) in
      let bwp = rand (lhand a1t) in
      let bwq = rand a1t in
      let sum = mk_comb (rator (rand bwp),
                  mk_binop `(+):num->num->num`
                    (rand (rand bwp)) (rand (rand bwq))) in
      let mid = mk_comb (mk_comb (rator (rator a1t), xt),
                  mk_comb (rator bwp, sum)) in
      let step1 = prove (mk_eq (a1t,mid),
                    REWRITE_TAC[WORD_ADD] THEN
                    CONV_TAC WORD_RULE) in
      let aeq = TRANS step1 (REWRITE_CONV[ar] mid) in
      REWRITE_TAC[aeq] THEN
      W(fun (asl3,gl3) ->
        let eq = prove (mk_eq (rator gl3, rator (concl sep2)),
                  REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
        ACCEPT_TAC (REWRITE_RULE[GSYM eq] sep2)))))));;

(* --- ML lists cannot exceed heap size: --- *)

let data_to_word_memoryProof_walk_def = cake_define
  `data_to_word_memoryProof_walk conf heap ptr n =
     (if n = 0 then [] else if n = 1 then [ptr] else
       match some (\p.
         ?x y.
         heap_lookup ptr heap = SOME (BlockRep cons_tag [x; y]) /\
         y = gc_shared_Pointer p (wordLang_Word (ptr_bits conf
           cons_tag 2))) with
         NONE -> [] | SOME p ->
           ptr :: data_to_word_memoryProof_walk conf heap p (n -
             1))`;;
hol4_overload "walk" "data_to_word_memoryProof_walk";;

let v_inv_v_to_list_lemma = prove
 (`v_inv c v refs (y,f,tf,heap) /\
   v_to_list v = SOME vs /\ ~(vs = []) ==>
    (?p ys. y = gc_shared_Pointer p (wordLang_Word (ptr_bits c
      cons_tag 2)) /\
               heap_lookup p heap = SOME (BlockRep cons_tag ys))`,
  (* a list of at least one element is a Block of the cons tag with
     two elements, and the invariant of a Block that is not empty
     is a pointer at a BlockRep of as many elements *)
  (STRIP_TAC THEN
   CASES_ON_NAME "vs" THENL
    [RULE_ASSUM_TAC(REWRITE_RULE[]) THEN FIRST_ASSUM CONTR_TAC;
     ALL_TAC] THEN
   FIRST_ASSUM(fun th ->
     MP_TAC(SPEC_ALL(MATCH_MP v_to_list_SOME_CONS_IMP th))) THEN
   DISCH_THEN(X_CHOOSE_THEN `ts2:num`
     (X_CHOOSE_THEN `ys2:dataSem_v` STRIP_ASSUME_TAC)) THEN
   REPEAT SUBST_LHS_TAC THEN
   USE_CHANGED [v_inv_def] THEN
   REWRITE_TAC[NOT_CONS_NIL] THEN STRIP_TAC THEN
   FIRST_ASSUM(fun a2 ->
     let len = CONV_RULE NUM_REDUCE_CONV
       (REWRITE_RULE[LENGTH] (MATCH_MP LIST_REL_LENGTH a2)) in
     RULE_ASSUM_TAC(REWRITE_RULE[SYM len])) THEN
   FIRST_ASSUM(fun eq -> FIRST_ASSUM(fun hl ->
     MAP_EVERY EXISTS_TAC
       [rand(rator(rhs(concl eq))); rand(rand(rhs(concl hl)))] THEN
     ASM_REWRITE_TAC[]))));;

let walk_LENGTH = prove
 (`!vs ptr ps v ts.
     v_inv c v refs (gc_shared_Pointer ptr (wordLang_Word (ptr_bits c
       cons_tag 2)),f,tf,heap) /\
     v_to_list v = SOME vs /\ ~(vs = []) /\
     data_to_word_memoryProof_walk c heap ptr (LENGTH vs) = ps ==>
     LENGTH ps = LENGTH vs`,
  (* the walk of the heap from the pointer of a list gives as many
     pointers as the list has elements: the induction is on the
     list, the cons of the value is what v_to_list_SOME_CONS_IMP
     gives, and v_inv of that cons names the BlockRep of two that
     the heap holds at the pointer.  Of a list of one the walk is
     the pointer alone; of a longer one it goes on at the pointer
     of the tail, which v_inv_v_to_list_lemma names, and the walk's
     choice of that pointer has only the one witness *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* an ALL2 whose first list is a cons *)
    let all2cons1 = prove
     (`!P h t (l:(B)list).
         ALL2 P (CONS (h:A) t) l <=>
         ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
      REPEAT GEN_TAC THEN
      STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
      REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
    (* what HOL4's some binder is of a predicate with one witness *)
    let some_SOME = prove
     (`!(P:A->bool) x. P x /\ (!y. P y ==> y = x) ==> some P = SOME x`,
      REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[some_DEF] THEN
      COND_CASES_TAC THENL
       [AP_TERM_TAC THEN MATCH_MP_TAC SELECT_UNIQUE THEN
        GEN_TAC THEN ASM_MESON_TAC[];
        ASM_MESON_TAC[]]) in
  LIST_INDUCT_TAC THENL
     [REPEAT GEN_TAC THEN REWRITE_TAC[]; ALL_TAC] THEN
    REPEAT GEN_TAC THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    FIRST_ASSUM(fun th ->
      if hd_is "dataSem_v_to_list" (lhs (concl th))
      then MP_TAC(SPEC_ALL(MATCH_MP
             v_to_list_SOME_CONS_IMP th))
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "dataSem_Block" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun vi ->
      if hd_is "v_inv" (concl vi)
      then MP_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL] vi)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun a2 ->
      if hd_is "ALL2" (concl a2)
      then MP_TAC(REWRITE_RULE[all2cons1; CONJUNCT1 ALL2_DEF] a2)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    REPEAT(FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
      then SUBST_ALL_TAC e else fail())) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) &&
         hd_is "gc_shared_Pointer" (lhs (concl e)) &&
         hd_is "gc_shared_Pointer" (rhs (concl e))
      then MP_TAC(REWRITE_RULE[injectivity "heap_address"] e)
      else fail()) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
    CASES_ON_NAME "t" THENL
     [FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) &&
           hd_is "data_to_word_memoryProof_walk" (lhs (concl e))
        then SUBST1_TAC(SYM e) else fail()) THEN
      REWRITE_TAC[LENGTH] THEN
      ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
      REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
      REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC] THEN
    W(fun (asl,w) ->
      let vi,vl = tryfind (fun (_,th) ->
        if not (hd_is "v_inv" (concl th)) then fail() else
        (th, grab asl (fun u ->
           hd_is "dataSem_v_to_list" (lhs (concl u)) &&
           rand (lhs (concl u)) = el 1 (snd(strip_comb (concl th))) &&
           hd_is "CONS" (rand (rhs (concl u)))))) asl in
      let lst = rand (rhs (concl vl)) in
      let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
      MP_TAC(MATCH_MP v_inv_v_to_list_lemma
               (CONJ vi (CONJ vl ne)))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "gc_shared_Pointer" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) &&
         hd_is "data_to_word_memoryProof_walk" (lhs (concl e))
      then SUBST1_TAC(SYM e) else fail()) THEN
    REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
    REWRITE_TAC[ARITH_RULE `(SUC (SUC n) = 0) <=> F`;
                ARITH_RULE `(SUC (SUC n) = 1) <=> F`;
                ARITH_RULE `SUC (SUC n) - 1 = SUC n`] THEN
    W(fun (asl,w) ->
      let sm = find_term (hd_is "some") w in
      let ptr = lhand (find_term (hd_is "heap_lookup") sm) in
      let hl = grab asl (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        lhand (lhs (concl th)) = ptr) in
      let xs = rand (rand (rhs (concl hl))) in
      let x1 = lhand xs in
      let y1 = lhand (rand xs) in
      let p2 = lhand y1 in
      SUBGOAL_THEN (mk_eq(sm, mk_icomb(`SOME`,p2))) SUBST1_TAC THENL
       [MATCH_MP_TAC some_SOME THEN
        CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
        CONJ_TAC THENL
         [MAP_EVERY EXISTS_TAC [x1; y1] THEN ASM_REWRITE_TAC[];
          X_GEN_TAC `q:num` THEN
          REWRITE_TAC[REWRITE_RULE[BlockRep_def] hl;
                      BlockRep_def] THEN
          REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
          REWRITE_TAC[injectivity "option";
                      injectivity "heap_element"; CONS_11; PAIR_EQ] THEN
          STRIP_TAC THEN
          FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
            let th = TRANS e1 e2 in
            if hd_is "gc_shared_Pointer" (lhs (concl th)) &&
               hd_is "gc_shared_Pointer" (rhs (concl th))
            then MP_TAC(REWRITE_RULE[injectivity "heap_address"] th)
            else fail())) THEN
          STRIP_TAC THEN ASM_REWRITE_TAC[]];
        ALL_TAC]) THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[LENGTH] THEN
    W(fun (asl,w) ->
      let ih = grab asl (fun th -> is_forall (concl th)) in
      let wt = find_term (hd_is "data_to_word_memoryProof_walk") w in
      let lst = rand (rhs (el 1 (conjuncts
        (lhand (snd(strip_forall (concl ih))))))) in
      let vl = grab asl (fun th ->
        hd_is "dataSem_v_to_list" (lhs (concl th)) &&
        rand (rhs (concl th)) = lst) in
      MP_TAC(SPECL [el 2 (snd(strip_comb wt)); wt;
                    rand (lhs (concl vl));
                    el 3 (fst(strip_forall (concl ih)))] ih)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[LENGTH; NOT_CONS_NIL]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[LENGTH]));;

(* [simp] *)
let BlockRep_heap_length = prove
 (`heap_length [BlockRep tag [x; y]] = 3`,
  (REWRITE_TAC[BlockRep_def; heap_length_CONS; heap_length_NIL;
               el_length_def; LENGTH] THEN ARITH_TAC));;

let ALL_DISTINCT_FILTER_LENGTH = prove
 (`ALL_DISTINCT xs ==>
   LENGTH (FILTER ((~) o P) xs) + LENGTH (FILTER P xs) = LENGTH xs`,
  (* the two filters take each element once, whether the list has
     repetitions or not *)
  (let lem = prove
    (`!xs:A list. LENGTH (FILTER ((~) o P) xs) + LENGTH (FILTER P xs)
                  = LENGTH xs`,
     LIST_INDUCT_TAC THEN REWRITE_TAC[FILTER; LENGTH; o_THM] THEN
     ASM_CASES_TAC `(P:A->bool) h` THEN ASM_REWRITE_TAC[LENGTH] THEN
     ASM_ARITH_TAC) in
   DISCH_TAC THEN MATCH_ACCEPT_TAC lem));;

let heap_length_Blocks = prove
 (`!ps (heap:(('a word_loc,data_to_word_memoryProof_tag#('a word_loc)
  list)heap_element) list).
     ALL_DISTINCT ps /\
     EVERY (\p. ?x y. heap_lookup p heap = SOME (BlockRep cons_tag
       [x; y])) ps ==>
     3 * LENGTH ps <= heap_length heap`,
(* the pointers of a list of conses take three words each: the
   induction on the number of the pointers, where the heap splits
   at the first of them (heap_lookup_SPLIT) into the part before
   the cons, the cons itself and the rest.  A pointer of the rest
   of the list is either before the cons or three words past it,
   because it is not the cons itself (the list has no repetition)
   and the two words inside the cons hold no element
   (heap_lookup_def).  So the pointers of the rest split into the
   ones before the cons and the ones after it, which moved down by
   three words are the pointers of the heap without the cons: they
   are as many as the pointers of the rest
   (ALL_DISTINCT_FILTER_LENGTH), they have no repetition
   (FILTER_ALL_DISTINCT and the map that takes three off, which is
   one to one past the cons) and each has its element there
   (heap_lookup_APPEND).  The induction hypothesis counts them in
   that heap, which is three words shorter *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  (* the induction on the number of the pointers *)
  let strong = prove
   (`!P. (!l. (!m. LENGTH m < LENGTH l ==> P m) ==> P l)
         ==> !l:(num)list. P l`,
    GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `!n l:(num)list. LENGTH l = n ==> P l`
      (fun th -> MESON_TAC[th]) THEN
    MATCH_MP_TAC num_WF THEN ASM_MESON_TAC[]) in
  (* the pointers that a filter keeps have no repetition either,
     and the image of a map that is one to one on them has none,
     and neither has the append of two lists with nothing in
     common *)
  let filt_ad = prove
   (`!P (l:(A)list). ALL_DISTINCT l ==> ALL_DISTINCT (FILTER P l)`,
    GEN_TAC THEN LIST_INDUCT_TAC THEN
    REWRITE_TAC[FILTER; ALL_DISTINCT_CLAUSES] THEN
    STRIP_TAC THEN COND_CASES_TAC THEN
    ASM_SIMP_TAC[ALL_DISTINCT_CLAUSES; MEM_FILTER]) in
  let map_ad = prove
   (`!(f:A->B) l. ALL_DISTINCT l /\
        (!x y. MEM x l /\ MEM y l /\ f x = f y ==> x = y)
        ==> ALL_DISTINCT (MAP f l)`,
    GEN_TAC THEN LIST_INDUCT_TAC THEN
    REWRITE_TAC[MAP; ALL_DISTINCT_CLAUSES; MEM] THEN
    STRIP_TAC THEN CONJ_TAC THENL
     [REWRITE_TAC[MEM_MAP] THEN ASM_MESON_TAC[];
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]]) in
  let app_ad = prove
   (`!(l1:(A)list) l2.
       ALL_DISTINCT l1 /\ ALL_DISTINCT l2 /\
       (!x. MEM x l1 ==> ~(MEM x l2))
       ==> ALL_DISTINCT (l1 ++ l2)`,
    REWRITE_TAC[ALL_DISTINCT; PAIRWISE_APPEND] THEN MESON_TAC[]) in
  (* and the two filters take each pointer once *)
  let adfl = prove
   (`ALL_DISTINCT (xs:(A)list)
     ==> LENGTH (FILTER P xs) + LENGTH (FILTER ((~) o P) xs) =
         LENGTH xs`,
    DISCH_TAC THEN
    FIRST_ASSUM (fun ad ->
      MP_TAC (MATCH_MP ALL_DISTINCT_FILTER_LENGTH ad)) THEN
    ARITH_TAC) in
  (* the three words of a cons *)
  let el3 = prove
   (`!x y. el_length (BlockRep cons_tag [x; y]) = 3`,
    REWRITE_TAC[BlockRep_def; el_length_def; LENGTH] THEN
    ARITH_TAC) in
  (* a lookup at the element that a heap holds after its first
     part, and inside it: there the lookup has nothing *)
  let lk_in = prove
   (`!ha el hb k.
       heap_lookup (heap_length ha + k) (ha ++ (el :: hb)) =
       (if k = 0 then SOME el else
        if k < el_length el then NONE
        else heap_lookup (k - el_length el) hb)`,
    REPEAT GEN_TAC THEN
    REWRITE_TAC[heap_lookup_APPEND] THEN
    REWRITE_TAC[ARITH_RULE `~(h + k < h)`;
                ARITH_RULE `(h + k) - h = k`] THEN
    REWRITE_TAC[heap_lookup_def]) in
  let mid_none = prove
   (`!ha el hb k. 0 < k /\ k < el_length el
       ==> heap_lookup (heap_length ha + k) (ha ++ (el :: hb)) =
           NONE`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[lk_in] THEN
    ASM_SIMP_TAC[ARITH_RULE `!k:num. 0 < k ==> ~(k = 0)`]) in
  let in_none = prove
   (`!ha x y hb k. 0 < k /\ k < 3
       ==> heap_lookup (heap_length ha + k)
             (ha ++ (BlockRep cons_tag [x; y] :: hb)) = NONE`,
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC mid_none THEN ASM_REWRITE_TAC[el3]) in
  let none1 = prove
   (`!ha x y hb. heap_lookup (heap_length ha + 1)
       (ha ++ (BlockRep cons_tag [x; y] :: hb)) = NONE`,
    REPEAT GEN_TAC THEN MATCH_MP_TAC in_none THEN ARITH_TAC) in
  let none2 = prove
   (`!ha x y hb. heap_lookup (heap_length ha + 2)
       (ha ++ (BlockRep cons_tag [x; y] :: hb)) = NONE`,
    REPEAT GEN_TAC THEN MATCH_MP_TAC in_none THEN ARITH_TAC) in
  (* and a lookup before the element, or after it, is the one of
     the heap without it *)
  let lk_bef = prove
   (`!ha el hb k. k < heap_length ha
       ==> heap_lookup k (ha ++ (el :: hb)) =
           heap_lookup k (ha ++ hb)`,
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    ASM_REWRITE_TAC[heap_lookup_APPEND]) in
  let lk_bef3 = prove
   (`!ha x y hb k. k < heap_length ha
       ==> heap_lookup k (ha ++ (BlockRep cons_tag [x; y] :: hb)) =
           heap_lookup k (ha ++ hb)`,
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    FIRST_ASSUM (fun lt -> MATCH_ACCEPT_TAC (MATCH_MP lk_bef lt)))
    in
  let lk_aft3 = prove
   (`!ha x y hb k. heap_length ha + 3 <= k
       ==> heap_lookup k (ha ++ (BlockRep cons_tag [x; y] :: hb)) =
           heap_lookup (k - 3) (ha ++ hb)`,
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    REWRITE_TAC[heap_lookup_APPEND] THEN
    FIRST_ASSUM (fun le ->
      let f1 = MATCH_MP (ARITH_RULE
                 `!a c:num. a + 3 <= c ==> ~(c < a)`) le in
      let f2 = MATCH_MP (ARITH_RULE
                 `!a c:num. a + 3 <= c ==> ~((c - 3) < a)`) le in
      let f3 = MATCH_MP (ARITH_RULE
                 `!a c:num. a + 3 <= c ==> ~(c - a = 0)`) le in
      let f4 = MATCH_MP (ARITH_RULE
                 `!a c:num. a + 3 <= c ==> ~(c - a < 3)`) le in
      REWRITE_TAC[f1; f2] THEN
      REWRITE_TAC[heap_lookup_def; el3; f3; f4] THEN
      REWRITE_TAC[ARITH_RULE
        `!a c:num. (c - a) - 3 = (c - 3) - a`])) in
  (* a pointer of the list that is not before the cons is three
     words past it: it is not the cons itself (the list has no
     repetition) and the two words inside the cons hold no
     element *)
  let aft_lem = prove
   (`!(ha:(('a word_loc,data_to_word_memoryProof_tag#('a word_loc)
      list)heap_element) list) x y hb t.
      ~(MEM (heap_length ha) t) /\
      (!z. MEM z t
           ==> ?u w. heap_lookup z
                       (ha ++ (BlockRep cons_tag [x; y] :: hb)) =
                     SOME (BlockRep cons_tag [u; w]))
      ==> !z. MEM z t /\ ~(z < heap_length ha)
              ==> heap_length ha + 3 <= z`,
    REPEAT GEN_TAC THEN
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "nm")
      (LABEL_TAC "ev")) THEN
    X_GEN_TAC `z:num` THEN STRIP_TAC THEN
    FIRST_ASSUM (fun nlt ->
      if not (is_neg (concl nlt)) then fail() else
      MP_TAC (MATCH_MP (ARITH_RULE
        `!z h:num. ~(z < h)
                   ==> z = h \/ z = h + 1 \/ z = h + 2 \/
                       h + 3 <= z`) nlt)) THEN
    DISCH_THEN (REPEAT_TCL DISJ_CASES_THEN (fun th ->
      if is_eq (concl th) then SUBST_ALL_TAC th
      else ACCEPT_TAC th)) THENL
     [FIRST_ASSUM (fun m ->
        USE_THEN "nm" (fun nm ->
          W(fun (asl,gl) ->
            ACCEPT_TAC (CONTR gl (MP (NOT_ELIM nm) m)))));
      USE_THEN "ev" (fun ev -> FIRST_ASSUM (fun m ->
        MP_TAC (MATCH_MP ev m))) THEN
      REWRITE_TAC[none1; distinctness "option"];
      USE_THEN "ev" (fun ev -> FIRST_ASSUM (fun m ->
        MP_TAC (MATCH_MP ev m))) THEN
      REWRITE_TAC[none2; distinctness "option"]]) in
  (* so the pointers before the cons and the ones after it moved
     down by its three words have no repetition *)
  let ad2_lem = prove
   (`!(ha:(('a word_loc,data_to_word_memoryProof_tag#('a word_loc)
      list)heap_element) list) t.
      ALL_DISTINCT t /\
      (!z. MEM z t /\ ~(z < heap_length ha)
           ==> heap_length ha + 3 <= z)
      ==> ALL_DISTINCT
            (FILTER (\z. z < heap_length ha) t ++
             MAP (\z. z - 3)
               (FILTER ((~) o (\z. z < heap_length ha)) t))`,
    REPEAT GEN_TAC THEN
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "ad")
      (LABEL_TAC "aft")) THEN
    MATCH_MP_TAC app_ad THEN REPEAT CONJ_TAC THENL
     [USE_THEN "ad" (fun ad ->
        MATCH_ACCEPT_TAC (MATCH_MP filt_ad ad));
      MATCH_MP_TAC map_ad THEN CONJ_TAC THENL
       [USE_THEN "ad" (fun ad ->
          MATCH_ACCEPT_TAC (MATCH_MP filt_ad ad));
        X_GEN_TAC `z1:num` THEN X_GEN_TAC `z2:num` THEN
        REWRITE_TAC[MEM_FILTER; o_THM] THEN
        CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
        STRIP_TAC THEN
        SUBGOAL_THEN `heap_length (ha:(('a word_loc,
          data_to_word_memoryProof_tag#('a word_loc)
          list)heap_element) list) + 3 <= z1` ASSUME_TAC THENL
         [USE_THEN "aft" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN `heap_length (ha:(('a word_loc,
          data_to_word_memoryProof_tag#('a word_loc)
          list)heap_element) list) + 3 <= z2` ASSUME_TAC THENL
         [USE_THEN "aft" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        ASM_ARITH_TAC];
      X_GEN_TAC `z1:num` THEN
      REWRITE_TAC[MEM_FILTER; MEM_MAP; o_THM] THEN
      CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
      STRIP_TAC THEN
      DISCH_THEN (X_CHOOSE_THEN `z2:num` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `heap_length (ha:(('a word_loc,
        data_to_word_memoryProof_tag#('a word_loc)
        list)heap_element) list) + 3 <= z2` ASSUME_TAC THENL
       [USE_THEN "aft" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_ARITH_TAC]) in
  (* and each of them has its element in the heap without the
     cons *)
  let ev2_lem = prove
   (`!(ha:(('a word_loc,data_to_word_memoryProof_tag#('a word_loc)
      list)heap_element) list) x y hb t.
      (!z. MEM z t
           ==> ?u w. heap_lookup z
                       (ha ++ (BlockRep cons_tag [x; y] :: hb)) =
                     SOME (BlockRep cons_tag [u; w])) /\
      (!z. MEM z t /\ ~(z < heap_length ha)
           ==> heap_length ha + 3 <= z)
      ==> EVERY (\p. ?u w. heap_lookup p (ha ++ hb) =
            SOME (BlockRep cons_tag [u; w]))
            (FILTER (\z. z < heap_length ha) t ++
             MAP (\z. z - 3)
               (FILTER ((~) o (\z. z < heap_length ha)) t))`,
    REPEAT GEN_TAC THEN
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "ev")
      (LABEL_TAC "aft")) THEN
    REWRITE_TAC[ALL_APPEND; GSYM ALL_MEM; MEM_FILTER; MEM_MAP;
                o_THM] THEN
    CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
    CONJ_TAC THENL
     [X_GEN_TAC `z1:num` THEN STRIP_TAC THEN
      USE_THEN "ev" (fun ev ->
        FIRST_ASSUM (fun m ->
          if not (try hd_is "MEM" (concl m) with Failure _ -> false)
          then fail() else
          FIRST_ASSUM (fun lt ->
            if not (try hd_is "<" (concl lt)
                    with Failure _ -> false) then fail() else
            ACCEPT_TAC (REWRITE_RULE[MATCH_MP lk_bef3 lt]
              (MP (SPEC `z1:num` ev) m)))));
      X_GEN_TAC `z1:num` THEN
      DISCH_THEN (X_CHOOSE_THEN `z2:num` STRIP_ASSUME_TAC) THEN
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN `heap_length (ha:(('a word_loc,
        data_to_word_memoryProof_tag#('a word_loc)
        list)heap_element) list) + 3 <= z2` ASSUME_TAC THENL
       [USE_THEN "aft" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "ev" (fun ev ->
        FIRST_ASSUM (fun m ->
          if not (try hd_is "MEM" (concl m) with Failure _ -> false)
          then fail() else
          FIRST_ASSUM (fun le ->
            if not (try hd_is "<=" (concl le)
                    with Failure _ -> false) then fail() else
            ACCEPT_TAC (REWRITE_RULE[MATCH_MP lk_aft3 le]
              (MP (SPEC `z2:num` ev) m)))))]) in
  (* the step of the induction: the heap splits at the first
     pointer, and the induction hypothesis counts the others in
     the heap without the cons that it holds there *)
  let core = prove
   (`!(ha:(('a word_loc,data_to_word_memoryProof_tag#('a word_loc)
      list)heap_element) list) x y hb t.
      ALL_DISTINCT t /\ ~(MEM (heap_length ha) t) /\
      (!z. MEM z t
           ==> ?u w. heap_lookup z
                       (ha ++ (BlockRep cons_tag [x; y] :: hb)) =
                     SOME (BlockRep cons_tag [u; w])) /\
      (!ps2. LENGTH ps2 < LENGTH t + 1
             ==> !hp:(('a word_loc,
                   data_to_word_memoryProof_tag#('a word_loc)
                   list)heap_element) list.
                      ALL_DISTINCT ps2 /\
                      EVERY (\p. ?u w. heap_lookup p hp =
                        SOME (BlockRep cons_tag [u; w])) ps2
                      ==> 3 * LENGTH ps2 <= heap_length hp)
      ==> 3 * (LENGTH t + 1) <=
          heap_length (ha ++ (BlockRep cons_tag [x; y] :: hb))`,
    REPEAT GEN_TAC THEN
    DISCH_THEN (CONJUNCTS_THEN2 (LABEL_TAC "ad")
      (CONJUNCTS_THEN2 (LABEL_TAC "nm")
        (CONJUNCTS_THEN2 (LABEL_TAC "ev") (LABEL_TAC "ih")))) THEN
    USE_THEN "nm" (fun nm -> USE_THEN "ev" (fun ev ->
      LABEL_TAC "aft" (MATCH_MP aft_lem (CONJ nm ev)))) THEN
    SUBGOAL_THEN
      `LENGTH (FILTER (\z. z < heap_length (ha:(('a word_loc,
                 data_to_word_memoryProof_tag#('a word_loc)
                 list)heap_element) list)) t ++
               MAP (\z. z - 3)
                 (FILTER ((~) o (\z. z < heap_length ha)) t)) =
       LENGTH t` (LABEL_TAC "len") THENL
     [REWRITE_TAC[LENGTH_APPEND; LENGTH_MAP] THEN
      USE_THEN "ad" (fun ad ->
        MATCH_ACCEPT_TAC (MATCH_MP adfl ad));
      ALL_TAC] THEN
    W(fun (asl,gl) ->
      let app = rand (rand gl) in
      let hp = list_mk_comb (rator (rator app),
                 [lhand app; rand (rand app)]) in
      SUBGOAL_THEN (mk_binop `(<=):num->num->bool`
                      `3 * LENGTH (t:(num)list)`
                      (mk_icomb (`heap_length`, hp))) MP_TAC) THENL
     [USE_THEN "ih" (fun ih -> USE_THEN "len" (fun len ->
        MP_TAC (REWRITE_RULE[len]
          (SPEC (rand (lhand (concl len))) ih)))) THEN
      REWRITE_TAC[ARITH_RULE `!n:num. n < n + 1`] THEN
      DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
       [USE_THEN "ad" (fun ad -> USE_THEN "aft" (fun aft ->
          MATCH_ACCEPT_TAC (MATCH_MP ad2_lem (CONJ ad aft))));
        USE_THEN "ev" (fun ev -> USE_THEN "aft" (fun aft ->
          MATCH_ACCEPT_TAC (MATCH_MP ev2_lem (CONJ ev aft))))];
      ALL_TAC] THEN
    REWRITE_TAC[heap_length_APPEND; heap_length_CONS; el3] THEN
    ARITH_TAC) in
  MATCH_MP_TAC strong THEN X_GEN_TAC `ps:(num)list` THEN
  DISCH_THEN (LABEL_TAC "ih") THEN
  DISJ_CASES_THEN2 SUBST_ALL_TAC
    (X_CHOOSE_THEN `p:num`
       (X_CHOOSE_THEN `t:(num)list` SUBST_ALL_TAC))
    (ISPEC `ps:(num)list` list_CASES) THENL
   [REWRITE_TAC[LENGTH; MULT_CLAUSES; LE_0];
    ALL_TAC] THEN
  GEN_TAC THEN
  REWRITE_TAC[ALL_DISTINCT_CLAUSES; ALL; LENGTH; ADD1] THEN
  CONV_TAC (TOP_DEPTH_CONV BETA_CONV) THEN
  DISCH_THEN (CONJUNCTS_THEN2
    (CONJUNCTS_THEN2 (LABEL_TAC "nm") (LABEL_TAC "ad"))
    (CONJUNCTS_THEN2 (LABEL_TAC "ex") (LABEL_TAC "evt"))) THEN
  (* the heap splits at the first pointer *)
  USE_THEN "ex" (REPEAT_TCL CHOOSE_THEN (fun lk ->
    STRIP_ASSUME_TAC (MATCH_MP heap_lookup_SPLIT lk))) THEN
  REPEAT (FIRST_X_ASSUM (fun e ->
    if not (try is_eq (concl e) && is_var (lhs (concl e)) &&
                (hd_is "APPEND" (rhs (concl e)) ||
                 hd_is "heap_length" (rhs (concl e)))
            with Failure _ -> false) then fail() else
    SUBST_ALL_TAC e)) THEN
  USE_THEN "ad" (fun ad -> USE_THEN "nm" (fun nm ->
    USE_THEN "evt" (fun evt -> USE_THEN "ih" (fun ih ->
      let evf = REWRITE_RULE[GSYM ALL_MEM] evt in
      let ihf = REWRITE_RULE[LENGTH; ADD1] ih in
      MATCH_ACCEPT_TAC
        (MATCH_MP core (CONJ ad (CONJ nm (CONJ evf ihf)))))))))));;

let walk_heap_lookup = prove
 (`!vs p ps v ts.
     v_inv c v refs
       (gc_shared_Pointer p (wordLang_Word (ptr_bits c cons_tag
         2)),f,tf,heap) /\
     v_to_list v = SOME vs /\ ~(vs = []) /\
     data_to_word_memoryProof_walk c heap p (LENGTH vs) = ps ==>
     EVERY (\p. ?x y. heap_lookup p heap = SOME (BlockRep cons_tag
       [x; y])) ps`,
  (* every pointer of the walk has a BlockRep of two at it: the
     same induction as walk_LENGTH, where each step reads the
     element of the heap off the v_inv of the cons *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* an ALL2 whose first list is a cons *)
    let all2cons1 = prove
     (`!P h t (l:(B)list).
         ALL2 P (CONS (h:A) t) l <=>
         ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
      REPEAT GEN_TAC THEN
      STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
      REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
    (* what HOL4's some binder is of a predicate with one witness *)
    let some_SOME = prove
     (`!(P:A->bool) x. P x /\ (!y. P y ==> y = x) ==> some P = SOME x`,
      REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[some_DEF] THEN
      COND_CASES_TAC THENL
       [AP_TERM_TAC THEN MATCH_MP_TAC SELECT_UNIQUE THEN
        GEN_TAC THEN ASM_MESON_TAC[];
        ASM_MESON_TAC[]]) in
    (* the heap_lookup of a pointer that the invariant gives *)
    let pwit =
      W(fun (asl,w) ->
        let p = lhand (find_term (hd_is "heap_lookup") w) in
        let hl = grab asl (fun th ->
          hd_is "heap_lookup" (lhs (concl th)) &&
          lhand (lhs (concl th)) = p) in
        let xs = rand (rand (rhs (concl hl))) in
        MAP_EVERY EXISTS_TAC [lhand xs; lhand (rand xs)] THEN
        ASM_REWRITE_TAC[]) in
  LIST_INDUCT_TAC THENL
     [REPEAT GEN_TAC THEN REWRITE_TAC[]; ALL_TAC] THEN
    REPEAT GEN_TAC THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    FIRST_ASSUM(fun th ->
      if hd_is "dataSem_v_to_list" (lhs (concl th))
      then MP_TAC(SPEC_ALL(MATCH_MP
             v_to_list_SOME_CONS_IMP th))
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "dataSem_Block" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun vi ->
      if hd_is "v_inv" (concl vi)
      then MP_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL] vi)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun a2 ->
      if hd_is "ALL2" (concl a2)
      then MP_TAC(REWRITE_RULE[all2cons1; CONJUNCT1 ALL2_DEF] a2)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    REPEAT(FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
      then SUBST_ALL_TAC e else fail())) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) &&
         hd_is "gc_shared_Pointer" (lhs (concl e)) &&
         hd_is "gc_shared_Pointer" (rhs (concl e))
      then MP_TAC(REWRITE_RULE[injectivity "heap_address"] e)
      else fail()) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
    CASES_ON_NAME "t" THENL
     [FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) &&
           hd_is "data_to_word_memoryProof_walk" (lhs (concl e))
        then SUBST1_TAC(SYM e) else fail()) THEN
      REWRITE_TAC[LENGTH] THEN
      ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
      REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
      REWRITE_TAC[ALL] THEN pwit;
      ALL_TAC] THEN
    W(fun (asl,w) ->
      let vi,vl = tryfind (fun (_,th) ->
        if not (hd_is "v_inv" (concl th)) then fail() else
        (th, grab asl (fun u ->
           hd_is "dataSem_v_to_list" (lhs (concl u)) &&
           rand (lhs (concl u)) = el 1 (snd(strip_comb (concl th))) &&
           hd_is "CONS" (rand (rhs (concl u)))))) asl in
      let lst = rand (rhs (concl vl)) in
      let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
      MP_TAC(MATCH_MP v_inv_v_to_list_lemma
               (CONJ vi (CONJ vl ne)))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "gc_shared_Pointer" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) &&
         hd_is "data_to_word_memoryProof_walk" (lhs (concl e))
      then SUBST1_TAC(SYM e) else fail()) THEN
    REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
    REWRITE_TAC[ARITH_RULE `(SUC (SUC n) = 0) <=> F`;
                ARITH_RULE `(SUC (SUC n) = 1) <=> F`;
                ARITH_RULE `SUC (SUC n) - 1 = SUC n`] THEN
    W(fun (asl,w) ->
      let sm = find_term (hd_is "some") w in
      let ptr = lhand (find_term (hd_is "heap_lookup") sm) in
      let hl = grab asl (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        lhand (lhs (concl th)) = ptr) in
      let xs = rand (rand (rhs (concl hl))) in
      let x1 = lhand xs in
      let y1 = lhand (rand xs) in
      let p2 = lhand y1 in
      SUBGOAL_THEN (mk_eq(sm, mk_icomb(`SOME`,p2))) SUBST1_TAC THENL
       [MATCH_MP_TAC some_SOME THEN
        CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
        CONJ_TAC THENL
         [MAP_EVERY EXISTS_TAC [x1; y1] THEN ASM_REWRITE_TAC[];
          X_GEN_TAC `q:num` THEN
          REWRITE_TAC[REWRITE_RULE[BlockRep_def] hl;
                      BlockRep_def] THEN
          REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
          REWRITE_TAC[injectivity "option";
                      injectivity "heap_element"; CONS_11; PAIR_EQ] THEN
          STRIP_TAC THEN
          FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
            let th = TRANS e1 e2 in
            if hd_is "gc_shared_Pointer" (lhs (concl th)) &&
               hd_is "gc_shared_Pointer" (rhs (concl th))
            then MP_TAC(REWRITE_RULE[injectivity "heap_address"] th)
            else fail())) THEN
          STRIP_TAC THEN ASM_REWRITE_TAC[]];
        ALL_TAC]) THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[ALL] THEN
    CONJ_TAC THENL [pwit; ALL_TAC] THEN
    W(fun (asl,w) ->
      let ih = grab asl (fun th -> is_forall (concl th)) in
      let wt = find_term (hd_is "data_to_word_memoryProof_walk") w in
      let lst = rand (rhs (el 1 (conjuncts
        (lhand (snd(strip_forall (concl ih))))))) in
      let vl = grab asl (fun th ->
        hd_is "dataSem_v_to_list" (lhs (concl th)) &&
        rand (rhs (concl th)) = lst) in
      MP_TAC(SPECL [el 2 (snd(strip_comb wt)); wt;
                    rand (lhs (concl vl));
                    el 3 (fst(strip_forall (concl ih)))] ih)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[LENGTH; NOT_CONS_NIL]; ALL_TAC] THEN
    REWRITE_TAC[]));;

let walk_MEM = prove
 (`v_inv c v refs (gc_shared_Pointer ptr (wordLang_Word (ptr_bits c
  cons_tag 2)),f,tf,heap) /\
   v_to_list v = SOME vs /\ ~(vs = []) ==>
   MEM ptr (data_to_word_memoryProof_walk c heap ptr (LENGTH vs))`,
  (* the pointer of a non-empty list is in its walk: the walk of a
     list of one is the pointer alone, and of a longer one the
     pointer is its head *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* an ALL2 whose first list is a cons *)
    let all2cons1 = prove
     (`!P h t (l:(B)list).
         ALL2 P (CONS (h:A) t) l <=>
         ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
      REPEAT GEN_TAC THEN
      STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
      REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
    (* what HOL4's some binder is of a predicate with one witness *)
    let some_SOME = prove
     (`!(P:A->bool) x. P x /\ (!y. P y ==> y = x) ==> some P = SOME x`,
      REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[some_DEF] THEN
      COND_CASES_TAC THENL
       [AP_TERM_TAC THEN MATCH_MP_TAC SELECT_UNIQUE THEN
        GEN_TAC THEN ASM_MESON_TAC[];
        ASM_MESON_TAC[]]) in
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    CASES_ON_NAME "vs" THENL
     [FIRST_X_ASSUM(fun th -> CONTR_TAC(REWRITE_RULE[] th));
      ALL_TAC] THEN
    FIRST_ASSUM(fun th ->
      if hd_is "dataSem_v_to_list" (lhs (concl th))
      then MP_TAC(SPEC_ALL(MATCH_MP
             v_to_list_SOME_CONS_IMP th))
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "dataSem_Block" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    FIRST_X_ASSUM(fun vi ->
      if hd_is "v_inv" (concl vi)
      then MP_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL] vi)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun a2 ->
      if hd_is "ALL2" (concl a2)
      then MP_TAC(REWRITE_RULE[all2cons1; CONJUNCT1 ALL2_DEF] a2)
      else fail()) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    REPEAT(FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
      then SUBST_ALL_TAC e else fail())) THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) &&
         hd_is "gc_shared_Pointer" (lhs (concl e)) &&
         hd_is "gc_shared_Pointer" (rhs (concl e))
      then MP_TAC(REWRITE_RULE[injectivity "heap_address"] e)
      else fail()) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
    CASES_ON_NAME "a1" THENL
     [REWRITE_TAC[LENGTH] THEN
      ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
      REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
      REWRITE_TAC[MEM];
      ALL_TAC] THEN
    W(fun (asl,w) ->
      let vi,vl = tryfind (fun (_,th) ->
        if not (hd_is "v_inv" (concl th)) then fail() else
        (th, grab asl (fun u ->
           hd_is "dataSem_v_to_list" (lhs (concl u)) &&
           rand (lhs (concl u)) = el 1 (snd(strip_comb (concl th))) &&
           hd_is "CONS" (rand (rhs (concl u)))))) asl in
      let lst = rand (rhs (concl vl)) in
      let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
      MP_TAC(MATCH_MP v_inv_v_to_list_lemma
               (CONJ vi (CONJ vl ne)))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         hd_is "gc_shared_Pointer" (rhs (concl e))
      then SUBST_ALL_TAC e else fail()) THEN
    REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
    REWRITE_TAC[ARITH_RULE `(SUC (SUC n) = 0) <=> F`;
                ARITH_RULE `(SUC (SUC n) = 1) <=> F`;
                ARITH_RULE `SUC (SUC n) - 1 = SUC n`] THEN
    W(fun (asl,w) ->
      let sm = find_term (hd_is "some") w in
      let ptr = lhand (find_term (hd_is "heap_lookup") sm) in
      let hl = grab asl (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        lhand (lhs (concl th)) = ptr) in
      let xs = rand (rand (rhs (concl hl))) in
      let x1 = lhand xs in
      let y1 = lhand (rand xs) in
      let p2 = lhand y1 in
      SUBGOAL_THEN (mk_eq(sm, mk_icomb(`SOME`,p2))) SUBST1_TAC THENL
       [MATCH_MP_TAC some_SOME THEN
        CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
        CONJ_TAC THENL
         [MAP_EVERY EXISTS_TAC [x1; y1] THEN ASM_REWRITE_TAC[];
          X_GEN_TAC `q:num` THEN
          REWRITE_TAC[REWRITE_RULE[BlockRep_def] hl;
                      BlockRep_def] THEN
          REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
          REWRITE_TAC[injectivity "option";
                      injectivity "heap_element"; CONS_11; PAIR_EQ] THEN
          STRIP_TAC THEN
          FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
            let th = TRANS e1 e2 in
            if hd_is "gc_shared_Pointer" (lhs (concl th)) &&
               hd_is "gc_shared_Pointer" (rhs (concl th))
            then MP_TAC(REWRITE_RULE[injectivity "heap_address"] th)
            else fail())) THEN
          STRIP_TAC THEN ASM_REWRITE_TAC[]];
        ALL_TAC]) THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[MEM]));;

(* the port's own: the walk from the pointer of a non-empty list
   starts at that pointer.  Of a list of one the walk is the
   pointer alone, and of a longer one the choice of the next
   pointer has the pointer of the tail for a witness, so the walk
   is the pointer and the walk from there.  walk_EL asks for it to
   say what the head of the walk of the tail is, which is the
   pointer that the cons at the head of the walk points at *)
let walk_CONS = prove
 (cake_as_vars (fun () ->
    `!vs ptr v.
       v_inv c v refs (gc_shared_Pointer ptr (wordLang_Word
         (ptr_bits c cons_tag 2)),f,tf,heap) /\
       v_to_list v = SOME vs /\ ~(vs = []) ==>
       (?ws. data_to_word_memoryProof_walk c heap ptr (LENGTH vs) =
          CONS ptr ws)`),
  let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* an ALL2 whose first list is a cons *)
   let all2cons1 = prove
    (`!P h t (l:(B)list).
        ALL2 P (CONS (h:A) t) l <=>
        ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   (* what HOL4's some binder is of a predicate with one witness *)
   let some_SOME = prove
    (`!(P:A->bool) x. P x /\ (!y. P y ==> y = x) ==> some P = SOME x`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[some_DEF] THEN
     COND_CASES_TAC THENL
      [AP_TERM_TAC THEN MATCH_MP_TAC SELECT_UNIQUE THEN
       GEN_TAC THEN ASM_MESON_TAC[];
       ASM_MESON_TAC[]]) in

  REPEAT GEN_TAC THEN
  STRUCT_CASES_TAC (ISPEC `vs:(dataSem_v)list` list_CASES) THENL
   [REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   FIRST_ASSUM(fun th ->
     if hd_is "dataSem_v_to_list" (lhs (concl th))
     then MP_TAC(SPEC_ALL(MATCH_MP
            v_to_list_SOME_CONS_IMP th))
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "dataSem_Block" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi)
     then MP_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL] vi)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[all2cons1; CONJUNCT1 ALL2_DEF] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   REPEAT(FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
     then SUBST_ALL_TAC e else fail())) THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) &&
        hd_is "gc_shared_Pointer" (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then MP_TAC(REWRITE_RULE[injectivity "heap_address"] e)
     else fail()) THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
  CASES_ON_NAME "t" THENL
   [REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
    REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
    EXISTS_TAC `[]:num list` THEN REWRITE_TAC[];
    ALL_TAC] THEN
   W(fun (asl,w) ->
     let vi,vl = tryfind (fun (_,th) ->
       if not (hd_is "v_inv" (concl th)) then fail() else
       (th, grab asl (fun u ->
          hd_is "dataSem_v_to_list" (lhs (concl u)) &&
          rand (lhs (concl u)) = el 1 (snd(strip_comb (concl th))) &&
          hd_is "CONS" (rand (rhs (concl u)))))) asl in
     let lst = rand (rhs (concl vl)) in
     let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
     MP_TAC(MATCH_MP v_inv_v_to_list_lemma
              (CONJ vi (CONJ vl ne)))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   REWRITE_TAC[LENGTH] THEN
   ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
   REWRITE_TAC[ARITH_RULE `(SUC (SUC n) = 0) <=> F`;
               ARITH_RULE `(SUC (SUC n) = 1) <=> F`;
               ARITH_RULE `SUC (SUC n) - 1 = SUC n`] THEN
   W(fun (asl,w) ->
     let sm = find_term (hd_is "some") w in
     let ptr = lhand (find_term (hd_is "heap_lookup") sm) in
     let hl = grab asl (fun th ->
       hd_is "heap_lookup" (lhs (concl th)) &&
       lhand (lhs (concl th)) = ptr) in
     let xs = rand (rand (rhs (concl hl))) in
     let x1 = lhand xs in
     let y1 = lhand (rand xs) in
     let p2 = lhand y1 in
     SUBGOAL_THEN (mk_eq(sm, mk_icomb(`SOME`,p2))) SUBST1_TAC THENL
      [MATCH_MP_TAC some_SOME THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       CONJ_TAC THENL
        [MAP_EVERY EXISTS_TAC [x1; y1] THEN ASM_REWRITE_TAC[];
         X_GEN_TAC `q:num` THEN
         REWRITE_TAC[REWRITE_RULE[BlockRep_def] hl;
                     BlockRep_def] THEN
         REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
         REWRITE_TAC[injectivity "option";
                     injectivity "heap_element"; CONS_11; PAIR_EQ] THEN
         STRIP_TAC THEN
         FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
           let th = TRANS e1 e2 in
           if hd_is "gc_shared_Pointer" (lhs (concl th)) &&
              hd_is "gc_shared_Pointer" (rhs (concl th))
           then MP_TAC(REWRITE_RULE[injectivity "heap_address"] th)
           else fail())) THEN
         STRIP_TAC THEN ASM_REWRITE_TAC[]];
       ALL_TAC]) THEN
  MATCH_REDUCE_TAC THEN
  W(fun (asl,gl) ->
    EXISTS_TAC (rand (lhs (snd (dest_exists gl))))) THEN
  REWRITE_TAC[]);;

let walk_EL = prove
 (`!vs ptr ps v ts.
     v_inv c v refs (gc_shared_Pointer ptr (wordLang_Word (ptr_bits c
       cons_tag 2)),f,tf,heap) /\
     v_to_list v = SOME vs /\ ~(vs = []) /\
     data_to_word_memoryProof_walk c heap ptr (LENGTH vs) = ps ==>
     (!n. SUC n < LENGTH vs ==>
       (?x.
         heap_lookup (EL n ps) heap =
           SOME (BlockRep cons_tag [x;
             gc_shared_Pointer (EL (SUC n) ps) (wordLang_Word
               (ptr_bits c cons_tag 2))])))`,
(* the proof of the source is the induction of walk_heap_lookup,
   and the same steps take the cons of the list and the BlockRep of
   the heap apart: the walk of a list of one is the pointer alone,
   so the statement is vacuous there, and of a longer one the walk
   is the pointer and the walk from the pointer of the tail, which
   the choice of the definition has for its only witness.  The
   index is then taken apart: at nought the goal is about the cons
   at the pointer and the head of the walk of the tail, which
   walk_CONS above says is the pointer of the tail, and at a
   successor it is the induction hypothesis one element on *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* an ALL2 whose first list is a cons *)
   let all2cons1 = prove
    (`!P h t (l:(B)list).
        ALL2 P (CONS (h:A) t) l <=>
        ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   (* what HOL4's some binder is of a predicate with one witness *)
   let some_SOME = prove
    (`!(P:A->bool) x. P x /\ (!y. P y ==> y = x) ==> some P = SOME x`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[some_DEF] THEN
     COND_CASES_TAC THENL
      [AP_TERM_TAC THEN MATCH_MP_TAC SELECT_UNIQUE THEN
       GEN_TAC THEN ASM_MESON_TAC[];
       ASM_MESON_TAC[]]) in
  let el_cons = prove
   (`!a l k. EL (SUC k) (CONS a l) = EL k l`,
    REWRITE_TAC[EL; TL; hol4_TL]) in
  LIST_INDUCT_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[LENGTH;
      ARITH_RULE `~(SUC n < 0)`];
    ALL_TAC] THEN
   REPEAT GEN_TAC THEN
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   FIRST_ASSUM(fun th ->
     if hd_is "dataSem_v_to_list" (lhs (concl th))
     then MP_TAC(SPEC_ALL(MATCH_MP
            v_to_list_SOME_CONS_IMP th))
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "dataSem_Block" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi)
     then MP_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL] vi)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[all2cons1; CONJUNCT1 ALL2_DEF] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   REPEAT(FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
     then SUBST_ALL_TAC e else fail())) THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) &&
        hd_is "gc_shared_Pointer" (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then MP_TAC(REWRITE_RULE[injectivity "heap_address"] e)
     else fail()) THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
  CASES_ON_NAME "t" THENL
   [REWRITE_TAC[LENGTH] THEN
    REWRITE_TAC[ARITH_RULE `~(SUC n < SUC 0)`];
    ALL_TAC] THEN
   W(fun (asl,w) ->
     let vi,vl = tryfind (fun (_,th) ->
       if not (hd_is "v_inv" (concl th)) then fail() else
       (th, grab asl (fun u ->
          hd_is "dataSem_v_to_list" (lhs (concl u)) &&
          rand (lhs (concl u)) = el 1 (snd(strip_comb (concl th))) &&
          hd_is "CONS" (rand (rhs (concl u)))))) asl in
     let lst = rand (rhs (concl vl)) in
     let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
     MP_TAC(MATCH_MP v_inv_v_to_list_lemma
              (CONJ vi (CONJ vl ne)))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) &&
        hd_is "data_to_word_memoryProof_walk" (lhs (concl e))
     then SUBST1_TAC(SYM e) else fail()) THEN
   REWRITE_TAC[LENGTH] THEN
   ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
   REWRITE_TAC[ARITH_RULE `(SUC (SUC n) = 0) <=> F`;
               ARITH_RULE `(SUC (SUC n) = 1) <=> F`;
               ARITH_RULE `SUC (SUC n) - 1 = SUC n`] THEN
   W(fun (asl,w) ->
     let sm = find_term (hd_is "some") w in
     let ptr = lhand (find_term (hd_is "heap_lookup") sm) in
     let hl = grab asl (fun th ->
       hd_is "heap_lookup" (lhs (concl th)) &&
       lhand (lhs (concl th)) = ptr) in
     let xs = rand (rand (rhs (concl hl))) in
     let x1 = lhand xs in
     let y1 = lhand (rand xs) in
     let p2 = lhand y1 in
     SUBGOAL_THEN (mk_eq(sm, mk_icomb(`SOME`,p2))) SUBST1_TAC THENL
      [MATCH_MP_TAC some_SOME THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       CONJ_TAC THENL
        [MAP_EVERY EXISTS_TAC [x1; y1] THEN ASM_REWRITE_TAC[];
         X_GEN_TAC `q:num` THEN
         REWRITE_TAC[REWRITE_RULE[BlockRep_def] hl;
                     BlockRep_def] THEN
         REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
         REWRITE_TAC[injectivity "option";
                     injectivity "heap_element"; CONS_11; PAIR_EQ] THEN
         STRIP_TAC THEN
         FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
           let th = TRANS e1 e2 in
           if hd_is "gc_shared_Pointer" (lhs (concl th)) &&
              hd_is "gc_shared_Pointer" (rhs (concl th))
           then MP_TAC(REWRITE_RULE[injectivity "heap_address"] th)
           else fail())) THEN
         STRIP_TAC THEN ASM_REWRITE_TAC[]];
       ALL_TAC]) THEN
  MATCH_REDUCE_TAC THEN
  X_GEN_TAC `n:num` THEN
  STRUCT_CASES_TAC (SPEC `n:num` num_CASES) THENL
   [DISCH_TAC THEN
    REWRITE_TAC[EL; HD; TL; hol4_TL] THEN
    FIRST_ASSUM (fun vi ->
      if not (hd_is "v_inv" (concl vi)) then fail() else
      FIRST_ASSUM (fun vl ->
        if not (try hd_is "dataSem_v_to_list" (lhs (concl vl)) &&
                    rand (lhs (concl vl)) =
                      el 1 (snd (strip_comb (concl vi))) &&
                    hd_is "CONS" (rand (rhs (concl vl)))
                with Failure _ -> false) then fail() else
        let lst = rand (rhs (concl vl)) in
        let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
        MP_TAC (MATCH_MP walk_CONS (CONJ vi (CONJ vl ne))))) THEN
    REWRITE_TAC[LENGTH] THEN
    DISCH_THEN (CHOOSE_THEN SUBST1_TAC) THEN
    REWRITE_TAC[HD; TL; hol4_TL] THEN
    W(fun (asl,gl) ->
      let q = lhand (find_term (hd_is "heap_lookup") gl) in
      let hl = grab asl (fun th ->
        hd_is "heap_lookup" (lhs (concl th)) &&
        lhand (lhs (concl th)) = q) in
      let xs = rand (rand (rhs (concl hl))) in
      EXISTS_TAC (lhand xs) THEN ASM_REWRITE_TAC[]);
    DISCH_TAC THEN
    REWRITE_TAC[el_cons] THEN
    W(fun (asl,w) ->
      let ih = grab asl (fun th -> is_forall (concl th)) in
      let wt = find_term (hd_is "data_to_word_memoryProof_walk") w in
      let lst = rand (rhs (el 1 (conjuncts
        (lhand (snd(strip_forall (concl ih))))))) in
      let vl = grab asl (fun th ->
        hd_is "dataSem_v_to_list" (lhs (concl th)) &&
        rand (rhs (concl th)) = lst) in
      MP_TAC(SPECL [el 2 (snd(strip_comb wt)); wt;
                    rand (lhs (concl vl));
                    el 3 (fst(strip_forall (concl ih)))] ih)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[LENGTH; NOT_CONS_NIL]; ALL_TAC] THEN
    DISCH_THEN (fun th -> MATCH_MP_TAC th) THEN
    POP_ASSUM MP_TAC THEN REWRITE_TAC[LENGTH] THEN ARITH_TAC]));;

let v_to_list_same_LENGTH = prove
 (`!xs x ys v1 v2 ts1 ts2.
     v_inv c v1 refs (x,f,tf,heap) /\
     v_inv c v2 refs (x,f,tf,heap) /\
     v_to_list v1 = SOME xs /\
     v_to_list v2 = SOME ys ==>
     LENGTH xs = LENGTH ys`,
  (* two values with the same root have lists of the same length:
     the induction is on the first list.  Of an empty one the value
     is the Block of nil_tag, whose root is a Data, and of a cons
     it is the Block of cons_tag, whose root is a Pointer, so the
     two lists are empty together; and when both are a cons the
     roots are the same pointer, so the heap gives them the same
     BlockRep, whose second element is the root of both tails *)
  (let hd_is n t =
      (try fst(dest_const(fst(strip_comb t))) = n
       with Failure _ -> false) in
    let safep p th = (try p th with Failure _ -> false) in
    let grab asl p =
      tryfind (fun (_,th) ->
        if (try p th with Failure _ -> false) then th else fail())
        asl in
    (* an ALL2 whose first list is a cons *)
    let all2cons1 = prove
     (`!P h t (l:(B)list).
         ALL2 P (CONS (h:A) t) l <=>
         ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
      REPEAT GEN_TAC THEN
      STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
      REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
    (* a value whose list is empty is the Block of nil_tag, and one
       whose list is a cons is the Block of cons_tag of two *)
    let vnil =
      FIRST_X_ASSUM(fun th ->
        if hd_is "dataSem_v_to_list" (lhs (concl th)) &&
           hd_is "NIL" (rand (rhs (concl th)))
        then MP_TAC(REWRITE_RULE[v_to_list_SOME_NIL_IFF] th)
        else fail()) THEN
      DISCH_THEN(CHOOSE_THEN SUBST_ALL_TAC) in
    let vcons =
      FIRST_X_ASSUM(fun th ->
        if hd_is "dataSem_v_to_list" (lhs (concl th)) &&
           hd_is "CONS" (rand (rhs (concl th)))
        then MP_TAC(SPEC_ALL(MATCH_MP
               v_to_list_SOME_CONS_IMP th))
        else fail()) THEN
      DISCH_THEN STRIP_ASSUME_TAC THEN
      FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) && is_var (lhs (concl e)) &&
           hd_is "dataSem_Block" (rhs (concl e))
        then SUBST_ALL_TAC e else fail()) in
    (* the invariants of the values, taken apart *)
    let splitinv =
      RULE_ASSUM_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL;
                                  all2cons1; CONJUNCT1 ALL2_DEF]) THEN
      REPEAT(FIRST_X_ASSUM(fun th ->
        if is_conj (concl th) || is_exists (concl th)
        then STRIP_ASSUME_TAC th else fail())) THEN
      REPEAT(FIRST_X_ASSUM(fun e ->
        if is_eq (concl e) && is_var (lhs (concl e)) &&
           (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
        then SUBST_ALL_TAC e else fail())) in
    (* a Data and a Pointer of the same root is a contradiction *)
    let clash =
      FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
        CONTR_TAC(REWRITE_RULE[distinctness "heap_address"]
                    (TRANS (SYM e1) e2)))) in
  LIST_INDUCT_TAC THEN
    REPEAT GEN_TAC THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    CASES_ON_NAME "ys" THEN
    REWRITE_TAC[LENGTH] THEN
    TRY(vnil THEN vcons THEN splitinv THEN clash THEN NO_TAC) THEN
    TRY(vcons THEN vnil THEN splitinv THEN clash THEN NO_TAC) THEN
    vcons THEN
    vcons THEN
    splitinv THEN
    W(fun (asl,w) ->
      let pes = filter (fun (_,th) -> safep (fun t ->
        is_eq (concl t) && is_var (lhs (concl t)) &&
        hd_is "gc_shared_Pointer" (rhs (concl t))) th) asl in
      MP_TAC(REWRITE_RULE[injectivity "heap_address"]
               (TRANS (SYM (snd (el 0 pes))) (snd (el 1 pes))))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC (K ALL_TAC)) THEN
    W(fun (asl,w) ->
      let hls = filter (fun (_,th) -> safep (fun t ->
        hd_is "heap_lookup" (lhs (concl t))) th) asl in
      MP_TAC(REWRITE_RULE[BlockRep_def; injectivity "option";
                          injectivity "heap_element"; CONS_11;
                          PAIR_EQ; LENGTH]
               (TRANS (SYM (snd (el 0 hls))) (snd (el 1 hls))))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    REPEAT(FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) && is_var (lhs (concl e)) &&
         is_var (rhs (concl e))
      then SUBST_ALL_TAC e else fail())) THEN
    REWRITE_TAC[SUC_INJ] THEN
    W(fun (asl,w) ->
      MATCH_MP_TAC (grab asl (fun th -> is_forall (concl th)))) THEN
    W(fun (asl,w) ->
      let cs = conjuncts (snd(strip_exists w)) in
      let pick lst = grab asl (fun th -> safep (fun u ->
        hd_is "dataSem_v_to_list" (lhs (concl u)) &&
        rand (rhs (concl u)) = lst) th) in
      let vl1 = pick (rand (rhs (el 2 cs))) in
      let vl2 = pick (rand (rhs (el 3 cs))) in
      let w1 = rand (lhs (concl vl1)) in
      let w2 = rand (lhs (concl vl2)) in
      let vi1 = grab asl (fun th ->
        hd_is "v_inv" (concl th) &&
        el 1 (snd(strip_comb (concl th))) = w1) in
      let addr = fst(dest_pair
        (el 3 (snd(strip_comb (concl vi1))))) in
      MAP_EVERY EXISTS_TAC [addr; w1; w2]) THEN
    ASM_REWRITE_TAC[]));;

let block_drop_def = cake_define
  `block_drop x1 v =
      match (x1,v) with
        (0,v) -> SOME v
      | (SUC n,(Block ts tag [h; vl]:dataSem_v)) -> block_drop n vl
      | (_103,_104) -> NONE`;;

let v_to_list_DROP = prove
 (`!vs ptr ps k v ts.
   v_inv c v refs (gc_shared_Pointer ptr (wordLang_Word (ptr_bits c
     cons_tag 2)),f,tf,heap) /\
   v_to_list v = SOME vs /\ ~(vs = []) /\
   data_to_word_memoryProof_walk c heap ptr (LENGTH vs) = ps /\
   ALL_DISTINCT ps /\
   k < LENGTH vs ==>
   v_inv c (THE (block_drop k v)) refs
     (gc_shared_Pointer (EL k ps) (wordLang_Word (ptr_bits c
       cons_tag 2)),f,tf,heap)`,
(* the proof of the source is the induction of walk_heap_lookup
   once more, with the index taken apart rather than inducted on.
   Of none the drop is the value itself and the walk starts at the
   pointer (walk_CONS), so the statement is what the invariant
   already says.  Of a successor the walk unfolds at the pointer
   (the same choice of the next pointer, with the cons at the
   pointer for its only witness), which is the equation that the
   proof states: the goal and the distinctness are then about the
   walk of the tail, where the induction hypothesis gives the drop
   one index down *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* an ALL2 whose first list is a cons *)
   let all2cons1 = prove
    (`!P h t (l:(B)list).
        ALL2 P (CONS (h:A) t) l <=>
        ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   (* what HOL4's some binder is of a predicate with one witness *)
   let some_SOME = prove
    (`!(P:A->bool) x. P x /\ (!y. P y ==> y = x) ==> some P = SOME x`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[some_DEF] THEN
     COND_CASES_TAC THENL
      [AP_TERM_TAC THEN MATCH_MP_TAC SELECT_UNIQUE THEN
       GEN_TAC THEN ASM_MESON_TAC[];
       ASM_MESON_TAC[]]) in
   (* the heap_lookup of a pointer that the invariant gives *)
  let el_cons = prove
   (`!a l k. EL (SUC k) (CONS a l) = EL k l`,
    REWRITE_TAC[EL; TL; hol4_TL]) in
  LIST_INDUCT_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT GEN_TAC THEN
  STRUCT_CASES_TAC (SPEC `k:num` num_CASES) THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THENL
   [(* the drop of none is the value, and the walk starts at the
        pointer of it *)
    ONCE_REWRITE_TAC[block_drop_def] THEN MATCH_REDUCE_TAC THEN
    REWRITE_TAC[THE] THEN
    FIRST_ASSUM (fun vi ->
      if not (hd_is "v_inv" (concl vi)) then fail() else
      FIRST_ASSUM (fun vl ->
        if not (try hd_is "dataSem_v_to_list" (lhs (concl vl)) &&
                    rand (lhs (concl vl)) =
                      el 1 (snd (strip_comb (concl vi)))
                with Failure _ -> false) then fail() else
        let lst = rand (rhs (concl vl)) in
        let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
        MP_TAC (MATCH_MP walk_CONS (CONJ vi (CONJ vl ne))))) THEN
    FIRST_ASSUM (fun we ->
      if not (try hd_is "data_to_word_memoryProof_walk"
                    (lhs (concl we)) with Failure _ -> false)
      then fail() else REWRITE_TAC[we]) THEN
    DISCH_THEN (CHOOSE_THEN SUBST1_TAC) THEN
    REWRITE_TAC[EL; HD] THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
   FIRST_ASSUM(fun th ->
     if hd_is "dataSem_v_to_list" (lhs (concl th))
     then MP_TAC(SPEC_ALL(MATCH_MP
            v_to_list_SOME_CONS_IMP th))
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "dataSem_Block" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi)
     then MP_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL] vi)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[all2cons1; CONJUNCT1 ALL2_DEF] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   REPEAT(FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
     then SUBST_ALL_TAC e else fail())) THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) &&
        hd_is "gc_shared_Pointer" (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then MP_TAC(REWRITE_RULE[injectivity "heap_address"] e)
     else fail()) THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
  CASES_ON_NAME "t" THENL
   [FIRST_ASSUM (fun lt ->
      if not (try hd_is "<" (concl lt) with Failure _ -> false)
      then fail() else MP_TAC lt) THEN
    REWRITE_TAC[LENGTH] THEN ARITH_TAC;
    ALL_TAC] THEN
   W(fun (asl,w) ->
     let vi,vl = tryfind (fun (_,th) ->
       if not (hd_is "v_inv" (concl th)) then fail() else
       (th, grab asl (fun u ->
          hd_is "dataSem_v_to_list" (lhs (concl u)) &&
          rand (lhs (concl u)) = el 1 (snd(strip_comb (concl th))) &&
          hd_is "CONS" (rand (rhs (concl u)))))) asl in
     let lst = rand (rhs (concl vl)) in
     let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
     MP_TAC(MATCH_MP v_inv_v_to_list_lemma
              (CONJ vi (CONJ vl ne)))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
  (* the walk unfolds at the pointer *)
  W(fun (asl,gl) ->
    let we = grab asl (fun th ->
      is_eq (concl th) &&
      hd_is "data_to_word_memoryProof_walk" (lhs (concl th))) in
    let wfull = lhs (concl we) in
    let args = snd (strip_comb wfull) in
    let vi2 = grab asl (fun th ->
      hd_is "v_inv" (concl th) &&
      (try let tup = el 3 (snd (strip_comb (concl th))) in
           let rt = fst (dest_pair tup) in
           hd_is "gc_shared_Pointer" rt &&
           not (lhand rt = el 2 args)
       with Failure _ -> false)) in
    let pp = lhand (fst (dest_pair
      (el 3 (snd (strip_comb (concl vi2)))))) in
    let yv = el 1 (snd (strip_comb (concl vi2))) in
    let vl2 = grab asl (fun th ->
      hd_is "dataSem_v_to_list" (lhs (concl th)) &&
      rand (lhs (concl th)) = yv) in
    let lst = rand (rhs (concl vl2)) in
    let wtail = list_mk_comb (fst (strip_comb wfull),
      [el 0 args; el 1 args; pp; mk_icomb (`LENGTH`, lst)]) in
    SUBGOAL_THEN (mk_eq (wfull,
      list_mk_icomb "CONS" [el 2 args; wtail])) ASSUME_TAC THENL
     [
      REWRITE_TAC[LENGTH] THEN
      GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV)
        [data_to_word_memoryProof_walk_def] THEN
      REWRITE_TAC[ARITH_RULE `(SUC (SUC n) = 0) <=> F`;
                  ARITH_RULE `(SUC (SUC n) = 1) <=> F`;
                  ARITH_RULE `SUC (SUC n) - 1 = SUC n`] THEN
      W(fun (asl,w) ->
        let sm = find_term (hd_is "some") w in
        let ptr = lhand (find_term (hd_is "heap_lookup") sm) in
        let hl = grab asl (fun th ->
          hd_is "heap_lookup" (lhs (concl th)) &&
          lhand (lhs (concl th)) = ptr) in
        let xs = rand (rand (rhs (concl hl))) in
        let x1 = lhand xs in
        let y1 = lhand (rand xs) in
        let p2 = lhand y1 in
        SUBGOAL_THEN (mk_eq(sm, mk_icomb(`SOME`,p2))) SUBST1_TAC THENL
         [MATCH_MP_TAC some_SOME THEN
          CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
          CONJ_TAC THENL
           [MAP_EVERY EXISTS_TAC [x1; y1] THEN ASM_REWRITE_TAC[];
            X_GEN_TAC `q:num` THEN
            REWRITE_TAC[REWRITE_RULE[BlockRep_def] hl;
                        BlockRep_def] THEN
            REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
            REWRITE_TAC[injectivity "option";
                        injectivity "heap_element"; CONS_11;
                     PAIR_EQ] THEN
            STRIP_TAC THEN
            FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
              let th = TRANS e1 e2 in
              if hd_is "gc_shared_Pointer" (lhs (concl th)) &&
                 hd_is "gc_shared_Pointer" (rhs (concl th))
              then MP_TAC(REWRITE_RULE[injectivity "heap_address"] th)
              else fail())) THEN
            STRIP_TAC THEN ASM_REWRITE_TAC[]];
          ALL_TAC]) THEN
      MATCH_REDUCE_TAC THEN REWRITE_TAC[LENGTH];
      ALL_TAC]) THEN
  (* so the goal and the distinctness are about the walk of the
     tail, and the induction hypothesis gives it *)
  FIRST_ASSUM (fun ue ->
    if not (try is_eq (concl ue) &&
                hd_is "data_to_word_memoryProof_walk"
                  (lhs (concl ue)) &&
                hd_is "CONS" (rhs (concl ue))
            with Failure _ -> false) then fail() else
    FIRST_ASSUM (fun we ->
      if not (try is_eq (concl we) &&
                  hd_is "data_to_word_memoryProof_walk"
                    (lhs (concl we)) &&
                  is_var (rhs (concl we))
              with Failure _ -> false) then fail() else
      RULE_ASSUM_TRY (REWRITE_RULE[SYM we; ue;
                                   ALL_DISTINCT_CLAUSES]) THEN
      REWRITE_TAC[SYM we; ue])) THEN
  REWRITE_TAC[el_cons] THEN
  ONCE_REWRITE_TAC[block_drop_def] THEN MATCH_REDUCE_TAC THEN
  W(fun (asl,gl) ->
    let ih = grab asl (fun th -> is_forall (concl th)) in
    let wg = find_term (hd_is "data_to_word_memoryProof_walk") gl in
    let args = snd (strip_comb wg) in
    let pp = el 2 args in
    let vi = grab asl (fun th ->
      hd_is "v_inv" (concl th) &&
      (try let tup = el 3 (snd (strip_comb (concl th))) in
           let rt = fst (dest_pair tup) in
           hd_is "gc_shared_Pointer" rt && lhand rt = pp
       with Failure _ -> false)) in
    let yv = el 1 (snd (strip_comb (concl vi))) in
    let vl = grab asl (fun th ->
      hd_is "dataSem_v_to_list" (lhs (concl th)) &&
      rand (lhs (concl th)) = yv) in
    let lst = rand (rhs (concl vl)) in
    let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
    let wlen = list_mk_comb (fst (strip_comb wg),
      [el 0 args; el 1 args; pp; mk_icomb (`LENGTH`, lst)]) in
    let weq = REFL wlen in
    let ad = (try CONJUNCT2 (grab asl (fun th ->
                is_conj (concl th) &&
                hd_is "ALL_DISTINCT" (rand (concl th))))
              with Failure _ -> grab asl (fun th ->
                hd_is "ALL_DISTINCT" (concl th))) in
    let kv = lhand (find_term (hd_is "EL") gl) in
    SUBGOAL_THEN (mk_binop `(<):num->num->bool` kv
                    (mk_icomb (`LENGTH`, lst)))
      (fun lt -> MATCH_ACCEPT_TAC (MATCH_MP ih
         (CONJ vi (CONJ vl (CONJ ne (CONJ weq (CONJ ad lt)))))))
    THENL
     [REWRITE_TAC[LENGTH] THEN
      FIRST_ASSUM (fun lt ->
        if not (try hd_is "<" (concl lt) with Failure _ -> false)
        then fail() else MP_TAC lt) THEN
      REWRITE_TAC[LENGTH] THEN ARITH_TAC])));;

let block_drop_DROP = prove
 (`!n v vs.
   v_to_list v = SOME vs /\ n < LENGTH vs ==> v_to_list (THE
     (block_drop n v)) = SOME (DROP n vs)`,
  (* induction on the number: a drop of none is the value itself,
     and one more goes down the tail of the cons that the list of
     the value is, which v_to_list_SOME_CONS_IMP names *)
  (let suc1 = ARITH_RULE `SUC n - 1 = n` in
   INDUCT_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THENL
    [REWRITE_TAC[block_drop_def] THEN MATCH_REDUCE_TAC THEN
     ASM_REWRITE_TAC[THE; DROP_0];
     CASES_ON_NAME "vs" THENL
      [FIRST_ASSUM(fun th -> CONTR_TAC(REWRITE_RULE[LENGTH; LT] th));
       ALL_TAC] THEN
     FIRST_ASSUM(fun th ->
       MP_TAC(SPEC_ALL(MATCH_MP v_to_list_SOME_CONS_IMP th))) THEN
     DISCH_THEN(X_CHOOSE_THEN `ts':num`
       (X_CHOOSE_THEN `ys:dataSem_v` STRIP_ASSUME_TAC)) THEN
     REPEAT SUBST_LHS_TAC THEN
     ONCE_REWRITE_TAC[block_drop_def] THEN
     MATCH_REDUCE_TAC THEN
     REWRITE_TAC[DROP; NOT_SUC; suc1] THEN
     FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
     RULE_ASSUM_TAC(REWRITE_RULE[LENGTH]) THEN ARITH_ASM_TAC]));;

let walk_ALL_DISTINCT = prove
 (`!vs ptr ps v ts.
     v_inv c v refs (gc_shared_Pointer ptr (wordLang_Word (ptr_bits c
       cons_tag 2)),f,tf,heap) /\
     v_to_list v = SOME vs /\ ~(vs = []) /\
     data_to_word_memoryProof_walk c heap ptr (LENGTH vs) = ps ==>
     ALL_DISTINCT ps`,
(* the proof of the source is the induction of walk_heap_lookup
   again: the walk of a list of one is the pointer alone, and of a
   longer one it is the pointer and the walk from the pointer of the
   tail, which the induction hypothesis says is without a repeat.
   What is left is that the pointer is not in that walk, and the
   source has it of the length of the list: a pointer of the walk
   carries the drop of the list at it (v_to_list_DROP,
   block_drop_DROP), so if the pointer were there the whole list
   and a drop of its tail would be lists of one value, and
   v_to_list_same_LENGTH makes them as long as each other, which
   the lengths deny *)
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   let grab asl p =
     tryfind (fun (_,th) ->
       if (try p th with Failure _ -> false) then th else fail())
       asl in
   (* an ALL2 whose first list is a cons *)
   let all2cons1 = prove
    (`!P h t (l:(B)list).
        ALL2 P (CONS (h:A) t) l <=>
        ?a b. l = CONS a b /\ P h a /\ ALL2 P t b`,
     REPEAT GEN_TAC THEN
     STRUCT_CASES_TAC(ISPEC `l:(B)list` list_CASES) THEN
     REWRITE_TAC[ALL2; NOT_CONS_NIL; CONS_11] THEN MESON_TAC[]) in
   (* what HOL4's some binder is of a predicate with one witness *)
   let some_SOME = prove
    (`!(P:A->bool) x. P x /\ (!y. P y ==> y = x) ==> some P = SOME x`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[some_DEF] THEN
     COND_CASES_TAC THENL
      [AP_TERM_TAC THEN MATCH_MP_TAC SELECT_UNIQUE THEN
       GEN_TAC THEN ASM_MESON_TAC[];
       ASM_MESON_TAC[]]) in
   (* the heap_lookup of a pointer that the invariant gives *)
  LIST_INDUCT_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[]; ALL_TAC] THEN
   REPEAT GEN_TAC THEN
   DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
   FIRST_ASSUM(fun th ->
     if hd_is "dataSem_v_to_list" (lhs (concl th))
     then MP_TAC(SPEC_ALL(MATCH_MP
            v_to_list_SOME_CONS_IMP th))
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "dataSem_Block" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   FIRST_X_ASSUM(fun vi ->
     if hd_is "v_inv" (concl vi)
     then MP_TAC(REWRITE_RULE[v_inv_def; NOT_CONS_NIL] vi)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun a2 ->
     if hd_is "ALL2" (concl a2)
     then MP_TAC(REWRITE_RULE[all2cons1; CONJUNCT1 ALL2_DEF] a2)
     else fail()) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   REPEAT(FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        (hd_is "CONS" (rhs (concl e)) || hd_is "NIL" (rhs (concl e)))
     then SUBST_ALL_TAC e else fail())) THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) &&
        hd_is "gc_shared_Pointer" (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then MP_TAC(REWRITE_RULE[injectivity "heap_address"] e)
     else fail()) THEN
   DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
  CASES_ON_NAME "t" THENL
   [FIRST_X_ASSUM(fun e ->
      if is_eq (concl e) &&
         hd_is "data_to_word_memoryProof_walk" (lhs (concl e))
      then SUBST1_TAC(SYM e) else fail()) THEN
    REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
    REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[ALL_DISTINCT_CLAUSES; MEM];
    ALL_TAC] THEN
   W(fun (asl,w) ->
     let vi,vl = tryfind (fun (_,th) ->
       if not (hd_is "v_inv" (concl th)) then fail() else
       (th, grab asl (fun u ->
          hd_is "dataSem_v_to_list" (lhs (concl u)) &&
          rand (lhs (concl u)) = el 1 (snd(strip_comb (concl th))) &&
          hd_is "CONS" (rand (rhs (concl u)))))) asl in
     let lst = rand (rhs (concl vl)) in
     let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
     MP_TAC(MATCH_MP v_inv_v_to_list_lemma
              (CONJ vi (CONJ vl ne)))) THEN
   DISCH_THEN STRIP_ASSUME_TAC THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) && is_var (lhs (concl e)) &&
        hd_is "gc_shared_Pointer" (rhs (concl e))
     then SUBST_ALL_TAC e else fail()) THEN
   FIRST_X_ASSUM(fun e ->
     if is_eq (concl e) &&
        hd_is "data_to_word_memoryProof_walk" (lhs (concl e))
     then SUBST1_TAC(SYM e) else fail()) THEN
   REWRITE_TAC[LENGTH] THEN
   ONCE_REWRITE_TAC[data_to_word_memoryProof_walk_def] THEN
   REWRITE_TAC[ARITH_RULE `(SUC (SUC n) = 0) <=> F`;
               ARITH_RULE `(SUC (SUC n) = 1) <=> F`;
               ARITH_RULE `SUC (SUC n) - 1 = SUC n`] THEN
   W(fun (asl,w) ->
     let sm = find_term (hd_is "some") w in
     let ptr = lhand (find_term (hd_is "heap_lookup") sm) in
     let hl = grab asl (fun th ->
       hd_is "heap_lookup" (lhs (concl th)) &&
       lhand (lhs (concl th)) = ptr) in
     let xs = rand (rand (rhs (concl hl))) in
     let x1 = lhand xs in
     let y1 = lhand (rand xs) in
     let p2 = lhand y1 in
     SUBGOAL_THEN (mk_eq(sm, mk_icomb(`SOME`,p2))) SUBST1_TAC THENL
      [MATCH_MP_TAC some_SOME THEN
       CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
       CONJ_TAC THENL
        [MAP_EVERY EXISTS_TAC [x1; y1] THEN ASM_REWRITE_TAC[];
         X_GEN_TAC `q:num` THEN
         REWRITE_TAC[REWRITE_RULE[BlockRep_def] hl;
                     BlockRep_def] THEN
         REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
         REWRITE_TAC[injectivity "option";
                     injectivity "heap_element"; CONS_11; PAIR_EQ] THEN
         STRIP_TAC THEN
         FIRST_ASSUM(fun e1 -> FIRST_ASSUM(fun e2 ->
           let th = TRANS e1 e2 in
           if hd_is "gc_shared_Pointer" (lhs (concl th)) &&
              hd_is "gc_shared_Pointer" (rhs (concl th))
           then MP_TAC(REWRITE_RULE[injectivity "heap_address"] th)
           else fail())) THEN
         STRIP_TAC THEN ASM_REWRITE_TAC[]];
       ALL_TAC]) THEN
  MATCH_REDUCE_TAC THEN
   W(fun (asl,w) ->
     let ih = grab asl (fun th -> is_forall (concl th)) in
     let wt = find_term (hd_is "data_to_word_memoryProof_walk") w in
     let lst = rand (rhs (el 1 (conjuncts
       (lhand (snd(strip_forall (concl ih))))))) in
     let vl = grab asl (fun th ->
       hd_is "dataSem_v_to_list" (lhs (concl th)) &&
       rand (rhs (concl th)) = lst) in
     MP_TAC(SPECL [el 2 (snd(strip_comb wt)); wt;
                   rand (lhs (concl vl));
                   el 3 (fst(strip_forall (concl ih)))] ih)) THEN
   ANTS_TAC THENL
    [ASM_REWRITE_TAC[LENGTH; NOT_CONS_NIL]; ALL_TAC] THEN
   DISCH_TAC THEN
  REWRITE_TAC[ALL_DISTINCT_CLAUSES] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[MEM_EXISTS_EL] THEN STRIP_TAC THEN
  (* the pointer that the walk repeats, the tail it belongs to and
     the walk of that tail *)
  W(fun (asl,gl) ->
    let ad = grab asl (fun th -> hd_is "ALL_DISTINCT" (concl th)) in
    let wg = rand (concl ad) in
    let args = snd (strip_comb wg) in
    let pp = el 2 args in
    let vi = grab asl (fun th ->
      hd_is "v_inv" (concl th) &&
      (let tup = el 3 (snd (strip_comb (concl th))) in
       let rt = fst (dest_pair tup) in
       hd_is "gc_shared_Pointer" rt && lhand rt = pp)) in
    let yv = el 1 (snd (strip_comb (concl vi))) in
    let vl = grab asl (fun th ->
      hd_is "dataSem_v_to_list" (lhs (concl th)) &&
      rand (lhs (concl th)) = yv) in
    let lst = rand (rhs (concl vl)) in
    let ne = ISPECL [lhand lst; rand lst] NOT_CONS_NIL in
    let wlen = list_mk_comb (fst (strip_comb wg),
      [el 0 args; el 1 args; pp; mk_icomb (`LENGTH`, lst)]) in
    let weq = REWRITE_CONV[LENGTH] wlen in
    let iv = lhand (rhs (concl (grab asl (fun th ->
      is_eq (concl th) && hd_is "EL" (rhs (concl th)))))) in
    (* the walk of the tail is as long as the tail *)
    MP_TAC (MATCH_MP (GEN_ALL walk_LENGTH)
      (CONJ vi (CONJ vl (CONJ ne weq)))) THEN
    REWRITE_TAC[LENGTH] THEN DISCH_TAC THEN
    (* so the index is one of the tail's *)
    SUBGOAL_THEN (mk_binop `(<):num->num->bool` iv
                    (mk_icomb (`LENGTH`, lst))) ASSUME_TAC THENL
     [REWRITE_TAC[LENGTH] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    (* the value at that pointer is the drop of the tail, whose
       list is the drop of the list *)
    FIRST_ASSUM (fun lt ->
      if not (try concl lt = mk_binop `(<):num->num->bool` iv
                    (mk_icomb (`LENGTH`, lst))
              with Failure _ -> false) then fail() else
      MP_TAC (MATCH_MP (GEN_ALL v_to_list_DROP)
        (CONJ vi (CONJ vl (CONJ ne (CONJ weq (CONJ ad lt)))))) THEN
      MP_TAC (MATCH_MP (GEN_ALL block_drop_DROP)
        (CONJ vl lt)))) THEN
  DISCH_THEN (ASSUME_TAC o SPEC_ALL) THEN
  DISCH_THEN (ASSUME_TAC o SPEC_ALL) THEN
  FIRST_ASSUM (fun eq ->
    if (try is_eq (concl eq) && hd_is "EL" (rhs (concl eq))
        with Failure _ -> false)
    then RULE_ASSUM_TRY (REWRITE_RULE[GSYM eq]) else fail()) THEN
  (* and the Block at the pointer has the whole list *)
  W(fun (asl,gl) ->
    let vd = grab asl (fun th ->
      hd_is "v_inv" (concl th) &&
      hd_is "THE" (el 1 (snd (strip_comb (concl th))))) in
    let bd = grab asl (fun th ->
      hd_is "dataSem_v_to_list" (lhs (concl th)) &&
      hd_is "THE" (rand (lhs (concl th)))) in
    let tup = el 3 (snd (strip_comb (concl vd))) in
    let rt' = fst (dest_pair tup) in
    let vlb = grab asl (fun th ->
      hd_is "dataSem_v_to_list" (lhs (concl th)) &&
      hd_is "dataSem_Block" (rand (lhs (concl th)))) in
    let blk = rand (lhs (concl vlb)) in
    let newv = list_mk_comb (fst (strip_comb (concl vd)),
      [el 0 (snd (strip_comb (concl vd))); blk;
       el 2 (snd (strip_comb (concl vd))); tup]) in
    SUBGOAL_THEN newv (fun vib ->
      (* two values with one root have lists of one length *)
      MP_TAC (MATCH_MP (GEN_ALL v_to_list_same_LENGTH)
        (CONJ vib (CONJ vd (CONJ vlb bd))))) THENL
     [REWRITE_TAC[v_inv_def; NOT_CONS_NIL] THEN
      W(fun (asl2,gl2) ->
        let pt = lhand rt' in
        let hl = grab asl2 (fun th ->
          hd_is "heap_lookup" (lhs (concl th)) &&
          lhand (lhs (concl th)) = pt) in
        MAP_EVERY EXISTS_TAC
          [pt; rand (rand (rhs (concl hl)))]) THEN
      ASM_REWRITE_TAC[ALL2; LENGTH] THEN
      CONV_TAC NUM_REDUCE_CONV;
      ALL_TAC]) THEN
  REWRITE_TAC[LENGTH; LENGTH_DROP] THEN ASM_ARITH_TAC));;

let v_to_list_heap_length = prove
 (`v_inv c v refs (x,f,tf,heap) /\
   v_to_list v = SOME vs /\ ~(vs = []) ==>
   3 * LENGTH vs <= heap_length heap`,
  (* the walk of the heap from the pointer of the value gives one
     pointer per element of the list, they are distinct, and each
     holds a BlockRep of two: three words of the heap each.  The
     list of pointers is the walk itself, which the first premise
     of walk_LENGTH names, so the theorem is matched against the
     invariant and the walk is read off that instance *)
  (let wl = walk_LENGTH
   and wad = walk_ALL_DISTINCT
   and whl = walk_heap_lookup
   and hlb = heap_length_Blocks in
   STRIP_TAC THEN
   FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun vl -> FIRST_ASSUM(fun ne ->
     MP_TAC(MATCH_MP v_inv_v_to_list_lemma
              (CONJ vi (CONJ vl ne)))))) THEN
   STRIP_TAC THEN REPEAT SUBST_LHS_TAC THEN
   FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun vl -> FIRST_ASSUM(fun ne ->
     let w1 = PART_MATCH (hd o conjuncts o lhand) wl (concl vi) in
     let wt = lhs (last (conjuncts (lhand (concl w1)))) in
     let prem = CONJ vi (CONJ vl (CONJ ne (REFL wt))) in
     let len = SPEC_ALL(MATCH_MP wl prem)
     and ad = SPEC_ALL(MATCH_MP wad prem)
     and ev = SPEC_ALL(MATCH_MP whl prem) in
     MP_TAC(REWRITE_RULE[len] (MATCH_MP hlb (CONJ ad ev)))))) THEN
   REWRITE_TAC[]));;

(* ------------------------------------------------------------------------- *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_list_limit = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp0 st m dm ((v,(w:'a word_loc)) :: vars)
  /\
     v_to_list v = SOME xs /\
     good_dimindex (:'a) ==>
     3 * (LENGTH xs + 1) * (dimindex (:'a) DIV 8) < dimword (:'a)`),
  (* the heap holds three words per element of the list, and the
     heap in memory leaves room for the limit and three more *)
  (let mul_le = prove
    (`!a b d x. 3 * a <= b /\ (b + 3) * d + 1 < x
                ==> 3 * (a + 1) * d < x`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     MATCH_MP_TAC LET_TRANS THEN EXISTS_TAC `(b + 3) * d` THEN
     CONJ_TAC THENL
      [REWRITE_TAC[MULT_ASSOC;
                   ARITH_RULE `3 * (a + 1) = 3 * a + 3`;
                   LE_MULT_RCANCEL] THEN
       DISJ1_TAC THEN ASM_ARITH_TAC;
       ASM_ARITH_TAC]) in
   MEMORY_REL_TAC THEN USE_CHANGED [heap_ok_def] THEN
   STRIP_TAC THEN
   SUBGOAL_THEN `3 * LENGTH (xs:(dataSem_v)list) <= limit'`
     MP_TAC THENL
    [ASM_CASES_TAC `xs:(dataSem_v)list = []` THENL
      [ASM_REWRITE_TAC[LENGTH] THEN ARITH_TAC;
       FIRST_ASSUM(fun vi -> FIRST_ASSUM(fun vl ->
         FIRST_ASSUM(fun ne ->
           MP_TAC(MATCH_MP v_to_list_heap_length
                    (CONJ vi (CONJ vl ne)))))) THEN
       ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
   DISCH_TAC THEN
   FIRST_ASSUM(fun le -> FIRST_ASSUM(fun dw ->
     MATCH_ACCEPT_TAC(MATCH_MP mul_le (CONJ le dw))))));;

let build_part_words_def = cake_define_list
  [`build_part_words c m (Int i:const_part) (offset:'a word) =
      (if small_int (:'a) i then SOME (wordLang_Word (Smallnum
        i),[]) else let (sign,ws) = i2mw i in
              match encode_header c (w2n (b2w sign << 2 || ((n2w
                3):'a word))) (LENGTH ws) with NONE -> NONE | SOME hd ->
                SOME (make_ptr c offset ((n2w 0):'a word) (LENGTH ws),
                              MAP wordLang_Word (hd :: ws)))`;
   `build_part_words c m (Con t ns:const_part) (offset:'a word) =
      (if NULL ns then
         if t < dimword (:'a) DIV 16 then SOME (wordLang_Word (n2w
           (16 * t + 2)),[]) else NONE else
         match encode_header c (4 * t) (LENGTH ns) with NONE -> NONE
           | SOME hd -> SOME (make_cons_ptr c offset t (LENGTH ns),
                            wordLang_Word hd :: (MAP m ns)))`;
   `build_part_words c m (W64 w:const_part) (offset:'a word) =
      (let ws = (if dimindex (:'a) < 64 then [((63 >< 32) w); ((31
        >< 0) w)] else [((63 >< 0) w):'a word]) in
         match encode_header c 3 (LENGTH ws) with NONE -> NONE |
           SOME hd -> SOME (make_ptr c offset ((n2w 0):'a word) (LENGTH
           ws),
                            MAP wordLang_Word (hd :: ws)))`;
   `build_part_words c m (closLang_Str s:const_part) (offset:'a word) =
      (let bytes = MAP (n2w o ORD) (explode s) in
       let n = LENGTH bytes in
       let hd = make_byte_header c T n in
       let ws = write_bytes bytes (REPLICATE (byte_len (:'a) n) (n2w
         0)) (be c) in
         if byte_len (:'a) n < 2 EXP (dimindex (:'a) - 4) /\
            byte_len (:'a) n < 2 EXP
              data_to_word_config_len_size c then SOME (make_ptr c
              offset ((n2w 0):'a word) (byte_len (:'a) n),MAP
              wordLang_Word (hd :: ws)) else NONE)`];;

let build_words_def = cake_define_list
  [`build_words c m i [] (off:'a word) = SOME (m (i - (1:num)),[])`;
   `build_words c m i (x :: parts') (off:'a word) =
      (match build_part_words c m x off with NONE -> NONE | SOME
        (w,xs) ->
        (match build_words c ((i =+ w) m) (i + 1) parts' (off +
          bytes_in_word * n2w (LENGTH xs)) with NONE -> NONE | SOME
          (r,ys) -> SOME (r,xs ++ ys)))`];;

let do_part_SOME_IMP_SOME = prove
 (`do_part map0 h refs (SOME ts) = (x,s1,ts1) ==> (?ts'. ts1 = SOME
  ts')`,
  (* every clause of do_part gives the timestamp back as a SOME,
     and the one of a Str gives it under a let *)
  (CASES_ON_NAME "h" THEN
   REWRITE_TAC[dataSem_do_part_def] THEN
   REPEAT(CHANGED_TAC
     (REWRITE_TAC[PAIR_EQ] THEN
      CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
      REPEAT COND_CASES_TAC THEN REPEAT STRIP_TAC)) THEN
   RULE_ASSUM_TAC(CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
   RULE_ASSUM_TAC(REWRITE_RULE[PAIR_EQ]) THEN
   REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC)) THEN
   ASM_MESON_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_IMP_MAP_UPDATE = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
             (((b,w) :: MAP (\k. (map0 k,map0' k)) ks) ++ vars) ==>
     memory_rel c be ts refs sp st m dm
             (MAP (\k. ((i =+ b) map0 k,((i =+ w) map0' k))) ks
               ++ vars)`),
  (MATCH_MP_TAC memory_rel_rearrange THEN
   GEN_TAC THEN REWRITE_TAC[MEM_APPEND; MEM_MAP; MEM] THEN
   STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
   REWRITE_TAC[UPDATE] THEN
   CONV_TAC(DEPTH_CONV BETA_CONV) THEN
   COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
   ASM_MESON_TAC[]));;

(* ZIP_MAP_MAP[local] *)
let data_to_word_memoryProof_ZIP_MAP_MAP = prove
 (`!xs. ZIP (MAP f xs) (MAP g xs) = MAP (\k. (f k,g k)) xs`,
  (let aux = prove
    (`!(f:A->B) (g:A->C) xs.
        ZIP (MAP f xs) (MAP g xs) = MAP (\k. (f k,g k)) xs`,
     GEN_TAC THEN GEN_TAC THEN LIST_INDUCT_TAC THEN
     ASM_REWRITE_TAC[MAP; ZIP]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC aux));;

(* [local] *)
let LENGTH_n2mw_LE_num_size = prove
 (`!n m. good_dimindex (:'a) /\ n <= m ==> SUC (LENGTH (n2mw n:('a
  word) list)) <= num_size m`,
  (* the words of a number are at most its num_size: both
     recursions divide, n2mw by the size of a word and num_size by
     two to the thirty-two, and a word of a good size is at least
     that wide -- so a complete induction on the number does it,
     with the clause of num_size at a number below two to the
     thirty-two (which is two, and a number that small is one word)
     for the base.  The source has the induction theorem of the
     definition, which the port's cake_define does not make *)
  ((* the quotient of a number by two or more is smaller *)
   let divlt = prove
    (`!n d. ~(n = 0) /\ 2 <= d ==> n DIV d < n`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     MP_TAC(SPECL [`n:num`; `d:num`] DIVISION) THEN
     ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
     ABBREV_TAC `q = n DIV d` THEN ABBREV_TAC `r = n MOD d` THEN
     STRIP_TAC THEN
     SUBGOAL_THEN `2 * q <= d * q` MP_TAC THENL
      [ASM_SIMP_TAC[LE_MULT_RCANCEL]; ALL_TAC] THEN
     ASM_ARITH_TAC) in
   (* a word of a good size holds a number of thirty-two bits *)
   let dw32 = prove
    (`good_dimindex (:'a) ==> 2 EXP 32 <= dimword (:'a)`,
     REWRITE_TAC[good_dimindex_def; dimword] THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
     CONV_TAC NUM_REDUCE_CONV) in
   let usedw32 =
     FIRST_ASSUM(fun gd -> MATCH_ACCEPT_TAC(MATCH_MP dw32 gd)) in
   MATCH_MP_TAC num_WF THEN
   X_GEN_TAC `n:num` THEN DISCH_TAC THEN
   X_GEN_TAC `m:num` THEN STRIP_TAC THEN
   ONCE_REWRITE_TAC[n2mw_def] THEN
   ONCE_REWRITE_TAC[num_size_def] THEN
   ASM_CASES_TAC `n = 0` THEN
   ASM_REWRITE_TAC[LENGTH] THEN
   TRY(COND_CASES_TAC THEN ARITH_TAC THEN NO_TAC) THEN
   REWRITE_TAC[LENGTH] THEN
   COND_CASES_TAC THEN
   (* m is below two to the thirty-two, and then so is n *)
   TRY(SUBGOAL_THEN `n DIV dimword (:'a) = 0` SUBST1_TAC THENL
        [MATCH_MP_TAC DIV_LT THEN
         TRANS_TAC LTE_TRANS `2 EXP 32` THEN
         CONJ_TAC THENL [ASM_ARITH_TAC; usedw32];
         ALL_TAC] THEN
       REWRITE_TAC[n2mw_def; LENGTH] THEN ARITH_TAC THEN
       NO_TAC) THEN
   (* and otherwise the induction hypothesis, at the quotients *)
   MATCH_MP_TAC(ARITH_RULE `k <= l ==> SUC k <= 1 + l`) THEN
   FIRST_X_ASSUM(fun ih ->
     MP_TAC(SPEC `n DIV dimword (:'a)` ih)) THEN
   ANTS_TAC THENL
    [MATCH_MP_TAC divlt THEN ASM_REWRITE_TAC[] THEN
     TRANS_TAC LE_TRANS `2 EXP 32` THEN
     CONJ_TAC THENL [CONV_TAC NUM_REDUCE_CONV; usedw32];
     ALL_TAC] THEN
   DISCH_THEN(fun th -> MP_TAC(SPEC `m DIV 2 EXP 32` th)) THEN
   ASM_REWRITE_TAC[] THEN
   ANTS_TAC THENL
    [TRANS_TAC LE_TRANS `m DIV dimword (:'a)` THEN CONJ_TAC THENL
      [MATCH_MP_TAC DIV_MONO THEN ASM_REWRITE_TAC[] THEN
       REWRITE_TAC[dimword; EXP_EQ_0; ARITH];
       MATCH_MP_TAC DIV_MONO2 THEN CONJ_TAC THEN
       TRY(REWRITE_TAC[EXP_EQ_0; ARITH] THEN NO_TAC) THEN
       usedw32];
     DISCH_THEN ACCEPT_TAC]));;

let least_notin_domain = prove
 (`~((LEAST (\ptr. ~(ptr IN domain refs))) IN domain (refs:'a spt))`,
  (* the domain of a tree is finite, so some number is not in it,
     and the least number that is not in it is one of those *)
  (let fin = prove
    (`!t:A spt. FINITE (domain t)`,
     MATCH_MP_TAC spt_INDUCT THEN
     SIMP_TAC[domain_def; FINITE_EMPTY; FINITE_INSERT;
              FINITE_UNION; FINITE_IMAGE]) in
   let notin = prove
    (`!s:num->bool. FINITE s ==> ?n. ~(n IN s)`,
     GEN_TAC THEN REWRITE_TAC[num_FINITE] THEN
     DISCH_THEN(X_CHOOSE_TAC `a:num`) THEN
     EXISTS_TAC `a + 1` THEN DISCH_TAC THEN
     FIRST_X_ASSUM(MP_TAC o SPEC `a + 1`) THEN
     ASM_REWRITE_TAC[] THEN ARITH_TAC) in
   let least_lemma = prove
    (`!s:num->bool. FINITE s ==> ~((LEAST (\n. ~(n IN s))) IN s)`,
     GEN_TAC THEN DISCH_TAC THEN
     MP_TAC(ISPEC `\n:num. ~(n IN s)` MINIMAL) THEN
     REWRITE_TAC[LEAST] THEN
     ASM_SIMP_TAC[notin] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT1 th])) in
   MATCH_ACCEPT_TAC (MATCH_MP least_lemma (SPEC_ALL fin))));;

let _ = do_list hide_constant ["free"];;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_do_build = prove
 (cake_as_vars (fun () ->
    `!parts' i st free' curr sp map0 map0' refs ts refs1 v m v ws.
       do_build map0 i parts' refs (SOME ts) = (v,refs1,SOME ts1)
         /\
       build_words c map0' i parts' (free' - (curr:'a word)) = SOME
         (w,ws) /\
       SUM (MAP part_space_req parts') <= sp /\
       FLOOKUP st NextFree = SOME (wordLang_Word free') /\
       FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
       (!ks. memory_rel c be ts refs sp st m dm (MAP (\k. (map0
         k,(map0' k))) ks ++ vars)) /\
       good_dimindex (:'a) ==>
       (?m1.
         let nf = free' + bytes_in_word * n2w (LENGTH ws) in
           memory_rel c be ts1 refs1 (sp - LENGTH ws)
             (st |+ (NextFree,wordLang_Word nf)) m1 dm ((v,w) ::
               vars) /\
           data_to_word_memoryProof_store_list free' ws m dm =
             SOME m1)`),
  (* the attempt: the proof of the source names do_build_def,
     build_words_def, memory_rel_def, heap_in_memory_store_def,
     FLOOKUP_UPDATE, data_to_word_memoryProof_store_list_def.  What
     is here rewrites with them and closes by arithmetic, and the
     cheat is behind it until the proof is written.  A MESON over
     them is what the next round adds; it costs a load ten minutes
     to have it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[do_build_def; build_words_def;
       memory_rel_def; heap_in_memory_store_def; FLOOKUP_UPDATE;
       data_to_word_memoryProof_store_list_def] THEN
     TRY ASM_ARITH_TAC)));;

let word_and_lsr_0 = prove
 (`(!i. k <= i /\ i < dimindex (:'a) ==> ~(FAPPLY w i)) ==> w && n <<
  k = ((n2w 0):'a word)`,
  (REWRITE_TAC[word_index] THEN DISCH_TAC THEN
   REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_0; BIT_WORD_AND;
               BIT_WORD_SHL] THEN
   REPEAT STRIP_TAC THEN
   FIRST_X_ASSUM(MP_TAC o SPEC `i:num`) THEN ASM_REWRITE_TAC[]));;

let byte_aligned_IMP_shift = prove
 (`byte_aligned (w:'a word) /\ good_dimindex (:'a) ==>
   (?v. w = v << backend_common_word_shift (:'a))`,
  (* a byte aligned word is its own slice above the shift of the
     dimindex, and such a slice is the word shifted down and up
     again *)
  (let LOG2_RED =
     REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                          NUM_REDUCE_CONV THENC REWRITE_CONV[])) in
   let key = prove
    (`!p (w:(N)word). word_slice (dimindex (:N) - 1) p w = w
        ==> w = word_shl (word_ushr w p) p`,
     REPEAT GEN_TAC THEN
     DISCH_THEN(fun th -> GEN_REWRITE_TAC LAND_CONV [GSYM th]) THEN
     REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
                 BIT_WORD_SHL; BIT_WORD_SUBWORD; BIT_WORD_USHR] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THEN ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN
       `i - p < MIN ((dimindex (:N) - 1 + 1) - p) (dimindex (:N))`
       (fun th -> REWRITE_TAC[th]) THENL
      [REWRITE_TAC[ARITH_RULE
         `MIN a b = if a <= b then a else b`] THEN
       COND_CASES_TAC THEN ASM_ARITH_TAC;
       REWRITE_TAC[ARITH_RULE `p + (i - p) = (i - p) + p`]]) in
   REWRITE_TAC[byte_aligned_def; aligned_def;
               align_def] THEN
   STRIP_TAC THEN
   SUBGOAL_THEN `LOG2 (dimindex (:'a) DIV 8) =
                 backend_common_word_shift (:'a)`
     (fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THENL
    [FIRST_ASSUM(fun g -> MP_TAC g) THEN
     REWRITE_TAC[good_dimindex_def;
                 word_shift_def] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
     CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED;
     EXISTS_TAC
       `word_ushr (w:'a word) (backend_common_word_shift (:'a))` THEN
     MATCH_MP_TAC key THEN FIRST_ASSUM ACCEPT_TAC]));;

let make_cons_ptr_add = prove
 (`byte_aligned n /\ good_dimindex (:'a) /\ backend_common_word_shift
  (:'a) <= shift_length c ==>
   make_cons_ptr c n tag len =
   wordLang_Word (n << (shift_length c - backend_common_word_shift
     (:'a)) +
         (get_lowerbits c (wordLang_Word (ptr_bits c tag len)):'a
           word))`,
  (* and the same for the pointer of a cons, where the one that
     the lower bits already hold is absorbed first *)
  (let lb1 = prove
     (`!c (x:(N)word).
         word 1 || get_lowerbits c (wordLang_Word x) =
         get_lowerbits c (wordLang_Word x)`,
      REPEAT GEN_TAC THEN REWRITE_TAC[get_lowerbits_def] THEN
      MATCH_REDUCE_TAC THEN CONV_TAC WORD_BITWISE_RULE) in
    STRIP_TAC THEN
    REWRITE_TAC[make_cons_ptr_def] THEN
    AP_TERM_TAC THEN
    REWRITE_TAC[lb1] THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC WORD_ADD_OR THEN
    FIRST_ASSUM(fun ba -> FIRST_ASSUM(fun gd ->
      MP_TAC(MATCH_MP byte_aligned_IMP_shift
        (CONJ ba gd)))) THEN
    DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST_ALL_TAC) THEN
    REWRITE_TAC[get_lowerbits_def] THEN
    MATCH_REDUCE_TAC THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_OR;
                BIT_WORD_1; BIT_WORD_0; BIT_WORD_SHL; word_bits;
                BIT_WORD_SUBWORD;
                ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    REWRITE_TAC[shift_length_def;
                small_shift_length_def] THEN
    REPEAT COND_CASES_TAC THEN REWRITE_TAC[] THEN
    POP_ASSUM_LIST(fun ths -> MAP_EVERY MP_TAC ths) THEN
    REWRITE_TAC[shift_length_def;
                small_shift_length_def] THEN
    ARITH_TAC));;

let make_ptr_add = prove
 (`byte_aligned n /\ good_dimindex (:'a) /\ backend_common_word_shift
  (:'a) <= shift_length c ==>
   make_ptr c n tag len =
   wordLang_Word (n << (shift_length c - backend_common_word_shift
     (:'a)) + ((n2w 1):'a word))`,
  (* a byte aligned word is a word shifted up by the shift, so the
     pointer it makes has its lowest bit clear and the or with one
     is an add *)
  (STRIP_TAC THEN
    REWRITE_TAC[make_ptr_def] THEN
    AP_TERM_TAC THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC WORD_ADD_OR THEN
    FIRST_ASSUM(fun ba -> FIRST_ASSUM(fun gd ->
      MP_TAC(MATCH_MP byte_aligned_IMP_shift
        (CONJ ba gd)))) THEN
    DISCH_THEN(REPEAT_TCL CHOOSE_THEN SUBST_ALL_TAC) THEN
    REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_AND; BIT_WORD_1;
                BIT_WORD_0; BIT_WORD_SHL] THEN
    X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(i:num) = 0` THEN ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(fun gd ->
      if can (find_term (fun t ->
        try fst(dest_const t) = "good_dimindex"
        with Failure _ -> false))
        (concl gd)
      then MP_TAC gd else failwith "no") THEN
    REWRITE_TAC[good_dimindex_def;
                word_shift_def] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    POP_ASSUM_LIST(fun ths -> MAP_EVERY MP_TAC ths) THEN ARITH_TAC));;

let word_cond_add_def = cake_define
  `word_cond_add c a x3 =
      match x3 with
        (F,x) -> (x:'a word_loc)
      | (T,wordLang_Word w) -> wordLang_Word (w + a << (shift_length
        c - backend_common_word_shift (:'a)))
      | (T,other) -> other`;;

(* the port's own: what the four lemmas about the words of a
   constant part share.  HOL4 gets the sum of two aligned words
   from alignmentTheory; here a shifted word is aligned by the
   definition of align, and each aligned word is a shifted one
   (byte_aligned_IMP_shift). *)

let LOG2_RED =
  REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                       NUM_REDUCE_CONV THENC REWRITE_CONV[]));;

let shl_add = prove
 (`!(a:N word) b n.
     word_shl (word_add a b) n =
     word_add (word_shl a n) (word_shl b n)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[GSYM VAL_EQ; VAL_WORD_SHL; VAL_WORD_ADD] THEN
  CONV_TAC MOD_DOWN_CONV THEN
  REWRITE_TAC[LEFT_ADD_DISTRIB] THEN CONV_TAC MOD_DOWN_CONV THEN
  REWRITE_TAC[]);;

let byte_aligned_shl = prove
 (`good_dimindex (:'a) ==>
   byte_aligned (word_shl (u:'a word)
                   (backend_common_word_shift (:'a)))`,
  REWRITE_TAC[byte_aligned_def; aligned_def; align_def] THEN
  STRIP_TAC THEN
  (SUBGOAL_THEN `LOG2 (dimindex (:'a) DIV 8) =
                 backend_common_word_shift (:'a)` SUBST1_TAC THENL
    [FIRST_ASSUM MP_TAC THEN
     REWRITE_TAC[good_dimindex_def; word_shift_def] THEN
     DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
     CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED;
     ALL_TAC]) THEN
  REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
              BIT_WORD_SHL; BIT_WORD_SUBWORD;
              ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
  X_GEN_TAC `i:num` THEN DISCH_TAC THEN
  REPEAT COND_CASES_TAC THEN
  ASM_CASES_TAC `word_shift (:'a) <= i` THEN ASM_REWRITE_TAC[] THEN
  (SUBGOAL_THEN
     `(word_shift (:'a) + i - word_shift (:'a)) -
      word_shift (:'a) = i - word_shift (:'a)` SUBST1_TAC THENL
    [ASM_ARITH_TAC; ALL_TAC]) THEN
  (SUBGOAL_THEN
     `i - word_shift (:'a) <
        (dimindex (:'a) - 1 + 1) - word_shift (:'a) /\
      word_shift (:'a) <= word_shift (:'a) + i - word_shift (:'a) /\
      word_shift (:'a) + i - word_shift (:'a) < dimindex (:'a)`
     STRIP_ASSUME_TAC THENL
    [FIRST_ASSUM MP_TAC THEN
     REWRITE_TAC[good_dimindex_def; word_shift_def] THEN
     ASM_ARITH_TAC;
     ALL_TAC]) THEN
  ASM_REWRITE_TAC[] THEN
  (SUBGOAL_THEN `i - word_shift (:'a) < dimindex (:'a)`
     ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC]) THEN
  ASM_REWRITE_TAC[]);;

let byte_aligned_add = prove
 (`good_dimindex (:'a) /\ byte_aligned (a:'a word) /\ byte_aligned b
   ==> byte_aligned (a + b)`,
  STRIP_TAC THEN
  FIRST_ASSUM(fun gd ->
    if not (hd_is "good_dimindex" (concl gd)) then fail() else
    REPEAT(FIRST_X_ASSUM(fun ba ->
      if not (hd_is "byte_aligned" (concl ba)) then fail() else
      CHOOSE_THEN SUBST_ALL_TAC
        (MATCH_MP byte_aligned_IMP_shift (CONJ ba gd)))) THEN
    REWRITE_TAC[GSYM shl_add] THEN
    MATCH_ACCEPT_TAC(GEN_ALL(MATCH_MP byte_aligned_shl gd))));;

(* the header of a bignum, which the two definitions write
   differently: the deep embedding takes the sign bit of a word and
   the shallow one the number 7 or 3 *)

let or43 = prove
 (`((n2w 4):'a word) || n2w 3 = n2w 7`, WORD_NUM_BIT_TAC 3);;

let or03 = prove
 (`((n2w 0):'a word) || n2w 3 = n2w 3`, WORD_NUM_BIT_TAC 2);;

let hdr_bits = prove
 (`good_dimindex (:'a) ==>
   w2n ((b2w sign << 2 || (n2w 3)):'a word) =
   (if sign then 7 else 3)`,
  REWRITE_TAC[b2w_def] THEN DISCH_TAC THEN
  STRUCT_CASES_TAC(SPEC `sign:bool` BOOL_CASES_AX) THEN
  REWRITE_TAC[b2n_def; WORD_SHL_WORD] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[or43; or03; VAL_WORD] THEN
  FIRST_ASSUM(fun gd ->
    STRIP_ASSUME_TAC(REWRITE_RULE[good_dimindex_def] gd)) THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV);;

(* what word_cond_add does to a word that is a pointer and to one
   that is not *)

let cond_add_F = prove
 (`!c a x. word_cond_add c a (F,x) = x`,
  REPEAT GEN_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [word_cond_add_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

let cond_add_T = prove
 (`!c a (w:'a word). word_cond_add c a (T,wordLang_Word w) =
     wordLang_Word (w + a << (shift_length c -
       backend_common_word_shift (:'a)))`,
  REPEAT GEN_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [word_cond_add_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

(* the map of the deep embedding with a word put in: what it looks
   up, read as the function of the shallow side with that word put
   in, and the condition of the two maps carried over it *)

let lookup_mem_insert = prove
 (`!m i v j. lookup_mem (insert i v m) j =
             (if j = i then v else lookup_mem m j)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[lookup_mem_def; lookup_insert] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

let upd_lookup = prove
 (`!m i (v:bool#('a word_loc)).
     (\j. SND (lookup_mem (insert i v m) j)) =
     ((i =+ SND v) (\j. SND (lookup_mem m j)))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
  X_GEN_TAC `j:num` THEN REWRITE_TAC[UPDATE] THEN BETA_TAC THEN
  REWRITE_TAC[lookup_mem_insert] THEN
  (ASM_CASES_TAC `(i:num) = j` THENL
    [FIRST_ASSUM SUBST_ALL_TAC THEN REWRITE_TAC[];
     ASM_REWRITE_TAC[] THEN
     (SUBGOAL_THEN `~((j:num) = i)` (fun th -> REWRITE_TAC[th])
        THENL [ASM_MESON_TAC[]; ALL_TAC]) THEN
     REWRITE_TAC[]]));;

let ins_cond = prove
 (`(!j. SND (lookup_mem m1 j) =
        word_cond_add c a (lookup_mem m j)) /\
   SND v = word_cond_add c a w
   ==> (!j. SND (lookup_mem (insert i v m1) j) =
            word_cond_add c a (lookup_mem (insert i w m) j))`,
  STRIP_TAC THEN X_GEN_TAC `j:num` THEN
  REWRITE_TAC[lookup_mem_insert] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[]);;

(* two lists that a map takes to the same list are of one length *)

let len_of_map = prove
 (`!(l1:A list) (l2:B list) f g.
     MAP (f:A->C) l1 = MAP (g:B->C) l2 ==> LENGTH l1 = LENGTH l2`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(MP_TAC o AP_TERM `LENGTH:C list->num`) THEN
  REWRITE_TAC[LENGTH_MAP]);;

(* the witnesses of an existential whose body says what each of
   them is, the assumption that is an induction hypothesis and the
   one that is the condition of the two maps *)

let EXISTS_EQ_TAC =
  W(fun (asl,w) ->
    if not (is_exists w) then fail() else
    let vs,body = strip_exists w in
    let eqs = conjuncts body in
    let wit = map (fun v ->
      lhs(find (fun t -> is_eq t && rhs t = v) eqs)) vs in
    MAP_EVERY EXISTS_TAC wit);;

let is_ih t = is_forall t && is_imp(snd(strip_forall t));;

let is_cond t = is_forall t && is_eq(snd(strip_forall t));;

(* and the call of a recursion in an assumption, split into its
   result and that result into a pair *)

let pw_is_lhs n t = (try hd_is n (lhs t) with Failure _ -> false);;

let pw_has_call n t =
  (try hd_is n (find_term (hd_is n) t) with Failure _ -> false);;

let PW_SPLIT_CALL_TAC n =
  W(fun g ->
    let th = av_find (pw_has_call n) g in
    CASES_ON_TAC (find_term (hd_is n) (concl th))) THEN
  TRY SAFE_MATCH_REDUCE_ASM_TAC THEN
  RULE_ASSUM_TRY (REWRITE_RULE[distinctness "option"]) THEN
  TRY(FIRST_ASSUM CONTR_TAC) THEN
  TRY(W(fun g ->
    let th = av_find (fun t -> pw_is_lhs n t &&
                               hd_is "SOME" (rhs t)) g in
    CASES_ON_TAC (rand(rhs(concl th))))) THEN
  TRY SAFE_MATCH_REDUCE_ASM_TAC THEN
  RULE_ASSUM_TRY (REWRITE_RULE[distinctness "option";
                               injectivity "option"; PAIR_EQ]) THEN
  TRY(FIRST_ASSUM CONTR_TAC) THEN
  TRY SAFE_MATCH_REDUCE_ASM_TAC;;

let part_to_words_add = prove
 (`!part m off a w ws m1.
     byte_aligned off /\ byte_aligned a /\
     good_dimindex (:'a) /\ backend_common_word_shift (:'a) <=
       shift_length c ==>
     part_to_words c m part (off:'a word) = SOME (w,ws) /\
     (!i. SND (lookup_mem m1 i) = word_cond_add c a (lookup_mem m i))
       ==>
     (?v vs. part_to_words c m1 part (off + (a:'a word)) = SOME
       (v,vs) /\
            MAP SND vs = MAP (word_cond_add c a) ws /\
            SND v = word_cond_add c a w)`,
  (* the four kinds of part, each written at the offset and at the
     offset plus a: what is not a pointer is written the same, and
     a pointer has the shifted a added to it, which is what
     word_cond_add does *)
  (REPEAT GEN_TAC THEN STRIP_TAC THEN CASES_ON_NAME "part" THEN
   REWRITE_TAC[part_to_words_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN STRIP_TAC THEN
   TRY PAIRARG_TAC THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
   EVERY_CASE_COND_TAC THEN VAR_EQ_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_REWRITE_TAC[] THEN
   REPEAT(CHANGED_TAC(TRY MATCH_REDUCE_TAC THEN
     REWRITE_TAC[distinctness "option"])) THEN
   REWRITE_TAC[injectivity "option"; PAIR_EQ; GSYM CONJ_ASSOC] THEN
   TRY EXISTS_EQ_TAC THEN
   REWRITE_TAC[cond_add_F; cond_add_T; MAP; GSYM MAP_o; o_DEF] THEN
   ASM_REWRITE_TAC[] THEN
   TRY(ASM_SIMP_TAC[make_ptr_add; make_cons_ptr_add;
                    byte_aligned_add; get_lowerbits_ptrbits]) THEN
   REWRITE_TAC[cond_add_F; cond_add_T] THEN
   TRY(AP_TERM_TAC THEN REWRITE_TAC[shl_add] THEN
       CONV_TAC WORD_RULE)));;

let byte_aligned_bytes_in_word = prove
 (`good_dimindex (:'a) ==>
   byte_aligned (bytes_in_word:'a word)`,
  (* the alignment of a word is the slice that drops its lowest
     bits, and the bytes in a word of a good dimindex are four or
     eight, which have no bit as low as that *)
  (let LOG2_RED =
     REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                          NUM_REDUCE_CONV THENC REWRITE_CONV[])) in
   let slice_lemma = prove
    (`!h p (w:(N)word).
        dimindex (:N) <= h + 1 /\ (!i. i < p ==> ~word_bit i w)
        ==> word_slice h p w = w`,
     REPEAT GEN_TAC THEN STRIP_TAC THEN
     REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
                 BIT_WORD_SHL; BIT_WORD_SUBWORD] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THENL
      [SUBGOAL_THEN `(p + (i - p) = i) /\
                     i - p < MIN ((h + 1) - p) (dimindex (:N))`
         STRIP_ASSUME_TAC THENL
        [CONJ_TAC THENL
          [ASM_ARITH_TAC;
           REWRITE_TAC[ARITH_RULE
             `MIN a b = if a <= b then a else b`] THEN
           COND_CASES_TAC THEN ASM_ARITH_TAC];
         ASM_REWRITE_TAC[]];
       ASM_REWRITE_TAC[] THEN
       FIRST_X_ASSUM(MP_TAC o SPEC `i:num`) THEN
       ASM_SIMP_TAC[ARITH_RULE `~(p <= i) ==> (i:num) < p`]]) in
   REWRITE_TAC[good_dimindex_def; byte_aligned_def;
               aligned_def; align_def;
               bytes_in_word_def] THEN
   DISCH_THEN(DISJ_CASES_THEN
     (fun th -> SUBST1_TAC th THEN ASSUME_TAC th)) THEN
   CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED THEN
   MATCH_MP_TAC slice_lemma THEN
   (CONJ_TAC THENL
     [ASM_REWRITE_TAC[] THEN ARITH_TAC;
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `i = 0 \/ i = 1 \/ i = 2` MP_TAC THENL
       [ASM_ARITH_TAC;
        DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST_ALL_TAC) THEN
        REWRITE_TAC[BIT_WORD] THEN CONV_TAC NUM_REDUCE_CONV THEN
        TRY(REWRITE_TAC[]) THEN TRY(ASM_ARITH_TAC)]])));;

let byte_align_mult_bytes_in_word = prove
 (`good_dimindex (:'a) ==>
   byte_aligned (w * (bytes_in_word:'a word)) /\
   byte_aligned (bytes_in_word * (w:'a word))`,
  (* the bytes in a word are two to the shift, so a multiple of them
     is the word shifted up, and the alignment of a word shifted up
     is the word shifted down and up again, which is the word
     itself *)
  (
   let LOG2_RED =
     REPEATC(CHANGED_CONV(ONCE_DEPTH_CONV(REWR_CONV LOG2) THENC
                          NUM_REDUCE_CONV THENC REWRITE_CONV[])) in
   let slice_shl = prove
    (`!p (w:(N)word).
        word_slice (dimindex (:N) - 1) p w =
        word_shl (word_ushr w p) p`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[word_slice; word_bits; WORD_EQ_BITS_ALT;
                 BIT_WORD_SHL; BIT_WORD_SUBWORD; BIT_WORD_USHR] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THEN ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN
       `i - p < MIN ((dimindex (:N) - 1 + 1) - p) (dimindex (:N))`
       (fun th -> REWRITE_TAC[th]) THENL
      [REWRITE_TAC[ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
       COND_CASES_TAC THEN ASM_ARITH_TAC;
       REWRITE_TAC[ARITH_RULE `p + (i - p) = (i - p) + p`]]) in
   let shl_slice = prove
    (`!p (w:(N)word).
        word_slice (dimindex (:N) - 1) p (word_shl w p) =
        word_shl w p`,
     REPEAT GEN_TAC THEN REWRITE_TAC[slice_shl] THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT; BIT_WORD_SHL; BIT_WORD_USHR] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_CASES_TAC `p:num <= i` THEN
     ASM_SIMP_TAC[ARITH_RULE `p <= i ==> (i - p) + p = i`] THEN
     ASM_REWRITE_TAC[BIT_WORD_SHL]) in
   let mul_shl = prove
    (`!p d (w:(N)word). d = 2 EXP p ==> w * n2w d = word_shl w p`,
     REPEAT GEN_TAC THEN DISCH_THEN SUBST1_TAC THEN
     REWRITE_TAC[word_shl] THEN
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM WORD_VAL] THEN
     REWRITE_TAC[GSYM WORD_MUL]) in
   DISCH_TAC THEN
   SUBGOAL_THEN
     `dimindex (:'a) DIV 8 = 2 EXP (LOG2 (dimindex (:'a) DIV 8))`
     ASSUME_TAC THENL
    [FIRST_ASSUM(DISJ_CASES_THEN SUBST1_TAC o
       REWRITE_RULE[good_dimindex_def]) THEN
     CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC LOG2_RED THEN
     CONV_TAC NUM_REDUCE_CONV;
     ALL_TAC] THEN
   REWRITE_TAC[byte_aligned_def;
               aligned_def; align_def;
               bytes_in_word_def] THEN
   CONJ_TAC THENL
    [ALL_TAC;
     SUBST1_TAC(WORD_RULE
       `n2w (dimindex (:'a) DIV 8) * (w:'a word) =
        w * n2w (dimindex (:'a) DIV 8)`)] THEN
   FIRST_ASSUM(fun f1 -> REWRITE_TAC[MATCH_MP mul_shl f1]) THEN
   MATCH_ACCEPT_TAC shl_slice));;

let parts_to_words_add = prove
 (`!parts' m i off a w ws m1.
     parts_to_words c m i parts' (off:'a word) = SOME (w,ws) /\
     byte_aligned off /\ byte_aligned a /\
     good_dimindex (:'a) /\ backend_common_word_shift (:'a) <=
       shift_length c /\
     (!i. SND (lookup_mem m1 i) = word_cond_add c a (lookup_mem m i))
       ==>
     (?v vs. parts_to_words c m1 i parts' (off + (a:'a word)) = SOME
       (v,vs) /\
            MAP SND vs = MAP (word_cond_add c a) ws /\
            SND v = word_cond_add c a w)`,
  (* the parts one after the other: this part's words by the
     theorem before this one, and the rest by the induction
     hypothesis of the two maps with this part's word put in
     (ins_cond), at the offset that the words of this part move on
     by -- which is aligned (byte_aligned_add) and the same whether
     a is added before or after it *)
  (let gen = prove
    (`!parts' m i (off:'a word) a w ws m1.
        parts_to_words c m i parts' off = SOME (w,ws) /\
        byte_aligned off /\ byte_aligned a /\ good_dimindex (:'a) /\
        backend_common_word_shift (:'a) <= shift_length c /\
        (!j. SND (lookup_mem m1 j) =
             word_cond_add c a (lookup_mem m j))
        ==> (?v vs. parts_to_words c m1 i parts' (off + a) =
                      SOME (v,vs) /\
                    MAP SND vs = MAP (word_cond_add c a) ws /\
                    SND v = word_cond_add c a w)`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[parts_to_words_def] THENL
      [STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       REWRITE_TAC[injectivity "option"; PAIR_EQ;
                   GSYM CONJ_ASSOC] THEN
       EXISTS_EQ_TAC THEN ASM_REWRITE_TAC[MAP];
       STRIP_TAC THEN
       PW_SPLIT_CALL_TAC "part_to_words" THEN
       PW_SPLIT_CALL_TAC "parts_to_words" THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       W(fun g ->
         let pt = av_find (pw_is_lhs "part_to_words") g
         and gd = av_find (hd_is "good_dimindex") g
         and sh = av_find (is_binary "<=") g
         and cond = av_find is_cond g in
         let off = last(snd(strip_comb(lhs(concl pt)))) in
         let a = el 1 (snd(strip_comb(rhs(snd(strip_forall(concl
                   cond)))))) in
         let ba_off = av_find (fun t -> hd_is "byte_aligned" t &&
                                        rand t = off) g
         and ba_a = av_find (fun t -> hd_is "byte_aligned" t &&
                                      rand t = a) g in
         MP_TAC(MATCH_MP (MATCH_MP (SPEC_ALL part_to_words_add)
           (CONJ ba_off (CONJ ba_a (CONJ gd sh))))
           (CONJ pt cond))) THEN
       DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
       W(fun g ->
         let gd = av_find (hd_is "good_dimindex") g
         and sh = av_find (is_binary "<=") g
         and cond = av_find is_cond g
         and ih = av_find is_ih g
         and pw = av_find (pw_is_lhs "parts_to_words") g in
         let body = snd(strip_forall(concl cond)) in
         let m1t = el 0 (snd(strip_comb(rand(lhs body))))
         and mt = el 0 (snd(strip_comb(rand(rhs body)))) in
         let pt = av_find (fun t -> pw_is_lhs "part_to_words" t &&
                    el 1 (snd(strip_comb(lhs t))) = mt) g
         and pt1 = av_find (fun t -> pw_is_lhs "part_to_words" t &&
                     el 1 (snd(strip_comb(lhs t))) = m1t) g in
         let off = last(snd(strip_comb(lhs(concl pt)))) in
         let a = el 1 (snd(strip_comb(rhs body))) in
         let ba_a = av_find (fun t -> hd_is "byte_aligned" t &&
                                      rand t = a) g in
         let map_eq = av_find (fun t -> is_eq t &&
                                 hd_is "MAP" (lhs t)) g in
         let len_eq = MATCH_MP len_of_map map_eq in
         let snd_eq = av_find (fun t -> is_eq t &&
                                 hd_is "SND" (lhs t)) g in
         let off2 = last(snd(strip_comb(lhs(concl pw)))) in
         let ba2 = MATCH_MP byte_aligned_add
           (CONJ gd (CONJ (av_find (fun t ->
                             hd_is "byte_aligned" t &&
                             rand t = off) g)
              (SPEC (rand(rand off2)) (GEN_ALL(CONJUNCT2(MATCH_MP
                 byte_align_mult_bytes_in_word gd)))))) in
         let cond2 = MATCH_MP ins_cond (CONJ cond snd_eq) in
         let ith = MATCH_MP (SPEC_ALL ih)
           (CONJ pw (CONJ ba2 (CONJ ba_a (CONJ gd
              (CONJ sh cond2))))) in
         REWRITE_TAC[pt1] THEN
         CONV_TAC(ONCE_DEPTH_CONV MATCH_CONV) THEN
         REWRITE_TAC[len_eq] THEN
         SUBGOAL_THEN (mk_eq(mk_binop `(+):'a word->'a word->'a word`
                               (mk_binop
                                  `(+):'a word->'a word->'a word`
                                  off a) (rand off2),
                             mk_binop `(+):'a word->'a word->'a word`
                               off2 a)) SUBST1_TAC THENL
          [CONV_TAC WORD_RULE; ALL_TAC] THEN
         MP_TAC ith THEN
         DISCH_THEN(REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
         W(fun g2 ->
           let pw2 = av_find (fun t ->
             pw_is_lhs "parts_to_words" t &&
             (try rand(last(snd(strip_comb(lhs t)))) = a
              with Failure _ -> false)) g2 in
           REWRITE_TAC[pw2] THEN MATCH_REDUCE_TAC THEN
           REWRITE_TAC[distinctness "option"; injectivity "option";
                       PAIR_EQ; GSYM CONJ_ASSOC] THEN
           EXISTS_EQ_TAC THEN
           ASM_REWRITE_TAC[MAP_APPEND]))]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC(SPEC_ALL gen)));;

let part_to_words_IMP_build_words = prove
 (`part_to_words c m p (off:'a word) = SOME (w,ws) /\ good_dimindex
  (:'a) /\
   byte_aligned off /\ backend_common_word_shift (:'a) <=
     shift_length c ==>
   build_part_words c (\i. SND (lookup_mem m i)) p off = SOME (SND
     w,MAP SND ws)`,
  (* the four kinds of part again, where the deep embedding writes
     what the shallow one writes: the header of a bignum differs
     (hdr_bits), the pointer of a cons is the same one written out
     (make_cons_ptr_add), and the words themselves are the deep
     ones without their flags *)
  (REPEAT GEN_TAC THEN CASES_ON_NAME "p" THEN
   REWRITE_TAC[part_to_words_def; build_part_words_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN STRIP_TAC THEN
   TRY PAIRARG_TAC THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
   EVERY_CASE_COND_TAC THEN VAR_EQ_TAC THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
   ASM_SIMP_TAC[GEN_ALL hdr_bits] THEN
   EVERY_CASE_COND_TAC THEN VAR_EQ_TAC THEN
   ASM_SIMP_TAC[MAP; GSYM MAP_o; o_DEF; SND; ETA_AX;
                make_cons_ptr_add; get_lowerbits_ptrbits]));;

let parts_to_words_IMP_build_words = prove
 (`!c m i parts' (off:'a word) w ws.
     parts_to_words c m i parts' off = SOME (w,ws) /\ good_dimindex
       (:'a) /\
     byte_aligned off /\ backend_common_word_shift (:'a) <=
       shift_length c ==>
     build_words c (\i. SND (lookup_mem m i)) i parts' off = SOME
       (SND w,MAP SND ws)`,
  (* the parts one after the other, with the map, the index and the
     offset that the recursion changes generalised.  The offset of
     the next part is the one of this part and the words it wrote,
     which is aligned as well (byte_aligned_add), and the map with
     this part's word put in is the function of the shallow side
     with it put in (upd_lookup) *)
  (let gen = prove
    (`!parts' c m i (off:'a word) w ws.
        parts_to_words c m i parts' off = SOME (w,ws) /\
        good_dimindex (:'a) /\ byte_aligned off /\
        backend_common_word_shift (:'a) <= shift_length c
        ==> build_words c (\j. SND (lookup_mem m j)) i parts' off =
            SOME (SND w,MAP SND ws)`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[parts_to_words_def; build_words_def] THENL
      [STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       REWRITE_TAC[MAP] THEN BETA_TAC THEN REWRITE_TAC[];
       STRIP_TAC THEN
       PW_SPLIT_CALL_TAC "part_to_words" THEN
       PW_SPLIT_CALL_TAC "parts_to_words" THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       W(fun g ->
         let pt = av_find (pw_is_lhs "part_to_words") g
         and pw = av_find (pw_is_lhs "parts_to_words") g
         and gd = av_find (hd_is "good_dimindex") g
         and ba = av_find (hd_is "byte_aligned") g
         and sh = av_find (is_binary "<=") g
         and ih = av_find is_forall g in
         let pth = MATCH_MP part_to_words_IMP_build_words
                     (CONJ pt (CONJ gd (CONJ ba sh))) in
         let off2 = last(snd(strip_comb(lhs(concl pw)))) in
         let bal = MATCH_MP byte_aligned_add
           (CONJ gd (CONJ ba (SPEC (rand(rand off2))
              (GEN_ALL(CONJUNCT2(MATCH_MP
                 byte_align_mult_bytes_in_word gd)))))) in
         let ith = MATCH_MP (SPEC_ALL ih)
                     (CONJ pw (CONJ gd (CONJ bal sh))) in
         REWRITE_TAC[pth; LENGTH_MAP; GSYM upd_lookup; ith] THEN
         MATCH_REDUCE_TAC THEN REWRITE_TAC[MAP_APPEND])]) in
   REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC(SPEC_ALL gen)));;

let LESS_EQ_num_size = prove
 (`good_dimindex (:'a) ==>
   (!m n. n <= m ==> SUC (LENGTH (n2mw n:('a word) list)) <=
     num_size m)`,
  (* the same as LENGTH_n2mw_LE_num_size, with the good_dimindex
     pulled out in front, as the source states it twice *)
  (DISCH_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
   FIRST_ASSUM(fun le -> FIRST_ASSUM(fun gd ->
     MATCH_ACCEPT_TAC(MATCH_MP LENGTH_n2mw_LE_num_size
                        (CONJ gd le))))));;

(* the port's own: a number that is below 2 EXP 29 is a small int,
   whichever of the two word sizes it is -- which is what says that
   the words of a constant part are counted by part_space_req *)

let small_29 = prove
 (`good_dimindex (:'a) /\ num_of_int (abs i) < 2 EXP 29
   ==> small_int (:'a) i`,
  REWRITE_TAC[good_dimindex_def; small_int_def; dimword] THEN
  STRIP_TAC THEN
  (SUBGOAL_THEN `abs (i:int) < &(2 EXP 29)` MP_TAC THENL
    [FIRST_ASSUM(fun lt ->
       if not (is_binary "<" (concl lt)) then fail() else
       ACCEPT_TAC(ONCE_REWRITE_RULE
         [MATCH_MP INT_OF_NUM_OF_INT (SPEC `i:int` INT_ABS_POS)]
         (REWRITE_RULE[GSYM INT_OF_NUM_LT] lt)));
     ALL_TAC]) THEN
  ASM_REWRITE_TAC[ARITH_RULE `2 EXP 32 DIV 8 = 2 EXP 29`;
                  ARITH_RULE `2 EXP 64 DIV 8 = 2 EXP 61`] THEN
  CONV_TAC NUM_REDUCE_CONV THEN INT_ARITH_TAC);;

let part_to_words_LENGTH = prove
 (`part_to_words c m h a = SOME ((w:bool#'a word_loc),ws) /\
   good_dimindex (:'a) ==>
   LENGTH ws <= part_space_req h`,
  (* the four kinds of constant part, each written as a header and
     the words of its content: a small int writes nothing, a Con
     writes its elements, a W64 at most three words, and a string
     as many as its bytes fill *)
  (REPEAT GEN_TAC THEN CASES_ON_NAME "h" THEN
   REWRITE_TAC[part_to_words_def; part_space_req_def] THEN
   CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN STRIP_TAC THEN
   TRY PAIRARG_TAC THEN
   RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
   EVERY_CASE_COND_TAC THEN
   RULE_ASSUM_TAC(REWRITE_RULE[NULL_EQ]) THEN VAR_EQ_TAC THEN
   ASM_REWRITE_TAC[LENGTH; LENGTH_MAP; LENGTH_write_bytes;
                   LENGTH_REPLICATE] THEN
   TRY ASM_ARITH_TAC THEN
   FIRST
    [(* a list of no elements that is not empty *)
     SOLVED(SUBGOAL_THEN `F` CONTR_TAC THEN
            ASM_MESON_TAC[LENGTH_EQ_NIL]);
     (* a number below 2 EXP 29 that is not a small int *)
     SOLVED(SUBGOAL_THEN `F` CONTR_TAC THEN
            ASM_MESON_TAC[GEN_ALL small_29]);
     (* and otherwise the words of the number, which num_size
        bounds *)
     SOLVED
      (RULE_ASSUM_TAC(REWRITE_RULE[i2mw_def; PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       FIRST_ASSUM(fun gd ->
         if not (hd_is "good_dimindex" (concl gd)) then fail() else
         MATCH_MP_TAC(MATCH_MP LESS_EQ_num_size gd)) THEN
       REWRITE_TAC[LE_REFL]);
     (* the bytes of a string, of which a word holds four or
        eight *)
     SOLVED
      (REWRITE_TAC[byte_len_def; LENGTH_explode] THEN
       FIRST_ASSUM(fun gd ->
         if not (hd_is "good_dimindex" (concl gd)) then fail() else
         STRIP_ASSUME_TAC(REWRITE_RULE[good_dimindex_def] gd)) THEN
       ASM_REWRITE_TAC[ARITH_EQ] THEN
       MP_TAC(SPECL [`8`; `strlen a'`; `4`] DIV_MONO2) THEN
       REWRITE_TAC[ARITH] THEN ARITH_TAC)]));;

let const_parts_to_words_LENGTH = prove
 (`const_parts_to_words c parts = SOME ((w:bool#'a word_loc),ws) /\
   good_dimindex (:'a) ==>
   LENGTH ws <= SUM (MAP part_space_req parts)`,
  (* the parts one after the other, each counted by
     part_to_words_LENGTH, with the map, the index and the offset
     that the recursion changes generalised *)
  (let sum_cons = prove
    (`!f h t. SUM (MAP f (CONS h t)) = f h + SUM (MAP f t)`,
     REWRITE_TAC[MAP; SUM_DEF; ITLIST]) in
   let gen = prove
    (`!parts' c m i (off:'a word) w ws.
        parts_to_words c m i parts' off = SOME (w,ws) /\
        good_dimindex (:'a)
        ==> LENGTH ws <= SUM (MAP part_space_req parts')`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[parts_to_words_def; sum_cons] THENL
      [STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       REWRITE_TAC[LENGTH; LE_0];
       STRIP_TAC THEN EVERY_CASE_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       REWRITE_TAC[LENGTH_APPEND] THEN
       MATCH_MP_TAC LE_ADD2 THEN CONJ_TAC THENL
        [FIRST_ASSUM(fun pt ->
           if not (hd_is "part_to_words" (lhs(concl pt)))
           then fail() else
           FIRST_ASSUM(fun gd ->
             if not (hd_is "good_dimindex" (concl gd)) then fail()
             else
             MATCH_ACCEPT_TAC(MATCH_MP part_to_words_LENGTH
               (CONJ pt gd))));
         FIRST_ASSUM(fun ih ->
           if not (is_forall (concl ih)) then fail() else
           FIRST_ASSUM(fun pw ->
             if not (hd_is "parts_to_words" (lhs(concl pw))) then
               fail() else
             FIRST_ASSUM(fun gd ->
               if not (hd_is "good_dimindex" (concl gd)) then
                 fail() else
               MATCH_ACCEPT_TAC(MATCH_MP (SPEC_ALL ih)
                 (CONJ pw gd)))))]]) in
   REWRITE_TAC[const_parts_to_words_def] THEN
   MATCH_ACCEPT_TAC(SPEC_ALL gen)));;

let good_loc_def = cake_define
  `good_loc code x2 =
      match x2 with
        wordLang_Loc n m -> (m = 0 /\ n IN code)
      | _105 -> T`;;

(* the port's own: what says that the words of a constant part are
   good_loc.  Nothing a part writes is a Loc: it writes words, and
   the entries of the map, which the invariant of the induction
   keeps good. *)

let good_loc_Word = prove
 (`!s w. good_loc s (wordLang_Word w) = T`,
  REPEAT GEN_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [good_loc_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[]);;

let good_loc_LN = prove
 (`!s k. good_loc s
           (SND (lookup_mem (LN:(bool#('a word_loc))spt) k))`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[lookup_mem_def; lookup_def] THEN
  MATCH_REDUCE_TAC THEN REWRITE_TAC[SND; good_loc_Word]);;

let part_gl = prove
 (`(!k. good_loc s (SND (lookup_mem m k))) /\
   part_to_words c m h (off:'a word) = SOME ((y0,y1),y2)
   ==> good_loc s y1 /\ EVERY (good_loc s o SND) y2`,
  STRIP_TAC THEN
  RULE_ASSUM_TRY (CONV_RULE(REWRITE_CONV[part_to_words_def])) THEN
  POP_ASSUM MP_TAC THEN
  CASES_ON_NAME "h" THEN
  REWRITE_TAC[part_to_words_def] THEN
  CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
  TRY PAIRARG_TAC THEN
  RULE_ASSUM_TRY (CONV_RULE(TOP_DEPTH_CONV let_CONV)) THEN
  TRY(CONV_TAC(TOP_DEPTH_CONV let_CONV)) THEN
  EVERY_CASE_COND_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option";
              PAIR_EQ] THEN
  STRIP_TAC THEN VAR_EQ_TAC THEN
  ASM_REWRITE_TAC[ALL; ALL_MAP; good_loc_Word; o_DEF; SND;
                  make_ptr_def; make_cons_ptr_def] THEN
  ASM_REWRITE_TAC[good_loc_Word; ALL_T]);;

let ins_loc = prove
 (`(!k. good_loc s (SND (lookup_mem m k))) /\ good_loc s y1
   ==> (!k. good_loc s
              (SND (lookup_mem (insert i ((y0:bool),y1) m) k)))`,
  STRIP_TAC THEN GEN_TAC THEN REWRITE_TAC[lookup_mem_insert] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[SND]);;

let const_parts_to_words_good_loc = prove
 (`const_parts_to_words c parts = SOME ((y0,y1),y2) ==>
   good_loc s y1 /\ EVERY (good_loc s o SND) y2`,
  (* the parts one after the other, with the map generalised: the
     map starts empty, where every lookup is a word (good_loc_LN),
     and what each part puts in is good as well (part_gl), so the
     invariant holds all the way along (ins_loc) *)
  (let gen = prove
    (`!parts' m i (off:'a word) y0 y1 y2.
        (!k. good_loc s (SND (lookup_mem m k))) /\
        parts_to_words c m i parts' off = SOME ((y0,y1),y2)
        ==> good_loc s y1 /\ EVERY (good_loc s o SND) y2`,
     LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
     REWRITE_TAC[parts_to_words_def] THENL
      [STRIP_TAC THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       W(fun g ->
         let inv = av_find is_forall g in
         let eq = av_find (fun t -> is_eq t &&
                             hd_is "lookup_mem" (lhs t)) g in
         let k = last(snd(strip_comb(lhs(concl eq)))) in
         REWRITE_TAC[ALL; o_DEF] THEN
         ACCEPT_TAC(REWRITE_RULE[eq; SND] (SPEC k inv)));
       STRIP_TAC THEN
       PW_SPLIT_CALL_TAC "part_to_words" THEN
       TRY(W(fun g ->
         let pt = av_find (pw_is_lhs "part_to_words") g in
         CASES_ON_TAC (fst(dest_pair(rand(rhs(concl pt))))))) THEN
       PW_SPLIT_CALL_TAC "parts_to_words" THEN
       RULE_ASSUM_TAC(REWRITE_RULE[injectivity "option";
                                   PAIR_EQ]) THEN
       SPLIT_ASM_TAC THEN VAR_EQ_TAC THEN
       W(fun g ->
         let inv = av_find is_forall g
         and pt = av_find (pw_is_lhs "part_to_words") g
         and pw = av_find (pw_is_lhs "parts_to_words") g in
         let gl = MATCH_MP (GEN_ALL part_gl) (CONJ inv pt) in
         let body = snd(strip_forall(concl inv)) in
         let st = el 0 (snd(strip_comb body))
         and sndf = rator(rand body) in
         let mp = el 1 (snd(strip_comb(lhs(concl pw)))) in
         let tm = mk_forall(`k:num`,
                    list_mk_icomb "good_loc"
                      [st; mk_comb(sndf,
                             list_mk_icomb "lookup_mem"
                               [mp; `k:num`])]) in
         (SUBGOAL_THEN tm ASSUME_TAC THENL
           [GEN_TAC THEN REWRITE_TAC[lookup_mem_insert] THEN
            COND_CASES_TAC THEN
            ASM_REWRITE_TAC[SND; CONJUNCT1 gl];
            ALL_TAC]) THEN
         W(fun g2 ->
           let inv2 = av_find (fun t -> t = tm) g2
           and ih = av_find is_ih g2 in
           MP_TAC(MATCH_MP ih (CONJ inv2 pw)) THEN MP_TAC gl)) THEN
       REWRITE_TAC[ALL_APPEND] THEN
       REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]]) in
   REWRITE_TAC[const_parts_to_words_def] THEN
   ASM_MESON_TAC[gen; good_loc_LN]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_do_build_const = prove
 (cake_as_vars (fun () ->
    `do_build_const parts refs (SOME ts) = (v,refs1,SOME ts1) /\
     const_parts_to_words c parts = SOME (w,ws) /\
     memory_rel c be ts refs sp st m dm vars /\
     SUM (MAP part_space_req parts) <= sp /\
     FLOOKUP st NextFree = SOME (wordLang_Word free) /\
     FLOOKUP st CurrHeap = SOME (wordLang_Word curr) /\
     good_dimindex (:'a) ==>
     (?m1.
       let nf = free + bytes_in_word * n2w (LENGTH ws) in
       let adjust = word_cond_add c (free - (curr:'a word)) in
         memory_rel c be ts1 refs1 (sp - LENGTH ws)
           (st |+ (NextFree,wordLang_Word nf)) m1 dm ((v,adjust w)
             :: vars) /\
         data_to_word_memoryProof_store_list free (MAP adjust ws)
           m dm = SOME m1)`),
  (* the attempt: the proof of the source names memory_rel_do_build,
     word_cond_add_def, do_build_const_def, IMP_memory_rel_Number,
     good_dimindex_def, const_parts_to_words_def.  What is here
     rewrites with them and closes by arithmetic, and the cheat is
     behind it until the proof is written.  A MESON over them is
     what the next round adds; it costs a load ten minutes to have
     it in every attempt and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[memory_rel_do_build; word_cond_add_def;
       do_build_const_def; IMP_memory_rel_Number;
       good_dimindex_def; const_parts_to_words_def] THEN
     TRY ASM_ARITH_TAC)));;

let read_word_def = cake_define
  `read_word dm m a = (theWord (m a),(a IN dm /\ isWord (m a)))`;;

(* the port's own: the step of the loop over the words of two byte
   arrays takes the counter down by two, and the guard of the step
   says that the counter is not below two and that the word of the
   machine is of thirty-two bits or of sixty-four, so two is below
   the word size and the value of the counter goes down.  It stands
   here, and not with VAL_WORD_SUB_1_LT and VAL_WORD_SUB_4_LT in
   ml/lib/lemmas.ml, because good_dimindex is of the port's own
   sources; cake_term_lemmas is what the termination proof of the
   definition below reads it from *)
let VAL_WORD_SUB_2_LT = prove
 (`!(n:(N)word). ~(n <+ word 2 \/ ~good_dimindex (:N))
     ==> val (word_sub n (word 2)) < val n`,
  (let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
   GEN_TAC THEN REWRITE_TAC[DE_MORGAN_THM] THEN STRIP_TAC THEN
   MATCH_MP_TAC VAL_WORD_SUB_LT THEN
   ASM_REWRITE_TAC[] THEN
   FIRST_ASSUM (fun gd ->
     if not (hd_is "good_dimindex" (concl gd)) then NO_TAC else
     MP_TAC (REWRITE_RULE[good_dimindex_def] gd)) THEN
   REWRITE_TAC[dimword] THEN
   DISCH_THEN (DISJ_CASES_THEN SUBST1_TAC) THEN
   CONV_TAC NUM_REDUCE_CONV));;

let _ = cake_term_lemmas :=
  VAL_WORD_SUB_2_LT :: (!cake_term_lemmas);;

(* HOL4 data_to_word_memoryProofScript.sml:18378-18384: the tactic
   that proves the termination *)
let word_xor_bytes_def = cake_define_try_tac (fun () ->
  `MEASURE (\(a1,a2,len,dm,m). w2n len)`)
  TERM_TAC
  `word_xor_bytes (a1:'a word) (a2:'a word) (len:'a word) dm m =
     (if len <+ (n2w 2) \/ ~(good_dimindex (:'a)) then
       if len = (n2w 0) then SOME m else
         let (w1a,c1) = read_word dm m a1 in
         let (w2a,c2) = read_word dm m a2 in
         let a = word_xor w1a w2a in
         let m = (a2 =+ wordLang_Word (a:'a word)) m in
           if c1 /\ c2 then SOME m else NONE else
       let (w1a,c1) = read_word dm m a1 in
       let (w2a,c2) = read_word dm m a2 in
       let (w1b,c3) = read_word dm m (a1 + bytes_in_word) in
       let (w2b,c4) = read_word dm m (a2 + bytes_in_word) in
       let a = word_xor w1a w2a in
       let b = word_xor w1b w2b in
       let m = ((a2 + bytes_in_word) =+ wordLang_Word b) ((a2 =+
         wordLang_Word a) m) in
         if c1 /\ c2 /\ c3 /\ c4 then
           word_xor_bytes (a1 + (n2w 2) * bytes_in_word) (a2 + (n2w
             2) * bytes_in_word)
             (len - (n2w 2)) dm m else NONE)`;;

let make_zeros_def = cake_define
  `make_zeros (vals:word8 list) =
     REPLICATE (LENGTH vals DIV (dimindex (:'a) DIV 8) + 1) ((n2w
       0):'a word)`;;

let xor_words_def = cake_define
  `xor_words xs ys =
      match (xs,ys) with
        ([],ys) -> SOME ys
      | (xs,[]) -> NONE
      | ((x :: xs),(y :: ys)) ->
     (match xor_words xs ys with NONE -> NONE | SOME rest -> SOME
       (word_xor (x:'a word) y :: rest))`;;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let word_xor_set_byte = prove
 (cake_as_vars (fun () ->
    `word_xor (set_byte a h1 w1 be) (set_byte a h2 w2 be) =
     set_byte a (word_xor h1 h2) (word_xor w1 w2) be`),
  (let bsa = prove
    (`!h l (w:(N)word) j. j < dimindex (:N)
        ==> (bit j (word_slice_alt h l w) <=>
             l <= j /\ j < h /\ bit j w)`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[word_slice_alt; BIT_WORD_SHL; BIT_WORD_SUBWORD] THEN
     REWRITE_TAC[ARITH_RULE `MIN a b = if a <= b then a else b`] THEN
     ASM_CASES_TAC `l:num <= j` THEN ASM_REWRITE_TAC[] THEN
     ASM_SIMP_TAC[ARITH_RULE `l <= j ==> l + j - l = j`] THEN
     COND_CASES_TAC THEN
     ASM_CASES_TAC `bit j (w:(N)word)` THEN ASM_REWRITE_TAC[] THEN
     ARITH_NO_BIT_TAC) in
   let bsb0 = prove
    (`!(a:(N)word) b (h:(N)word) bb j. j < dimindex (:N)
        ==> (bit j (set_byte a b h bb) <=>
             (if byte_index a bb <= j /\ j < byte_index a bb + 8
              then bit (j - byte_index a bb) b else bit j h))`,
     REPEAT GEN_TAC THEN DISCH_TAC THEN
     REWRITE_TAC[set_byte_def] THEN
     CONV_TAC(TOP_DEPTH_CONV let_CONV) THEN
     ASM_SIMP_TAC[BIT_WORD_OR; bsa; BIT_WORD_SHL; BIT_WORD_ZX;
                  DIMINDEX_8] THEN
     MP_TAC(REWRITE_RULE[DIMINDEX_8]
       (ISPECL [`b:(8)word`; `j - byte_index (a:(N)word) bb`]
          BIT_TRIVIAL)) THEN
     ASM_CASES_TAC `byte_index (a:(N)word) bb <= j` THEN
     ASM_CASES_TAC `j < byte_index (a:(N)word) bb + 8` THEN
     ASM_CASES_TAC `bit j (h:(N)word)` THEN
     ASM_CASES_TAC
       `bit (j - byte_index (a:(N)word) bb) (b:(8)word)` THEN
     ASM_REWRITE_TAC[] THEN ARITH_NO_BIT_TAC) in
   let gen = prove
    (`!(a:(N)word) h1 h2 w1 w2 bb.
        word_xor (set_byte a h1 w1 bb) (set_byte a h2 w2 bb) =
        set_byte a (word_xor h1 h2) (word_xor w1 w2) bb`,
     REPEAT GEN_TAC THEN
     REWRITE_TAC[WORD_EQ_BITS_ALT] THEN
     X_GEN_TAC `i:num` THEN DISCH_TAC THEN
     ASM_SIMP_TAC[BIT_WORD_XOR; bsb0] THEN
     COND_CASES_TAC THEN
     TRY(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC)) THEN
     ASM_SIMP_TAC[BIT_WORD_XOR; DIMINDEX_8;
                  ARITH_RULE `b <= i /\ i < b + 8 ==> i - b < 8`]) in
   MATCH_ACCEPT_TAC gen));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let xor_bytes_bytes_to_word = prove
 (cake_as_vars (fun () ->
    `!k vals1 vals2 res_vals a.
       xor_bytes vals1 vals2 = SOME res_vals ==>
       bytes_to_word k a vals1 (n2w 0) be ??
       bytes_to_word k a vals2 (n2w 0) be =
       bytes_to_word k a res_vals (n2w 0) be`),
  (* the induction of the source on the number of bytes: the xor of
     the two bytes that the two words take is the byte that the word
     of the xor takes (word_xor_set_byte), and the induction
     hypothesis says it of the rest.  MATCH_CONV leaves the match on
     the result of the recursive call as an epsilon term, which
     UNWIND_CONV and the two theorems about one take apart *)
  (INDUCT_TAC THENL
    [ONCE_REWRITE_TAC[bytes_to_word_def] THEN
     REWRITE_TAC[WORD_XOR_0];
     ALL_TAC] THEN
   REPEAT GEN_TAC THEN
   LIST_CASES_TAC ["vals1"; "vals2"] THEN
   ONCE_REWRITE_TAC[xor_bytes_def] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[distinctness "option"] THEN
   TRY (W(fun (asl,w) ->
     CASES_ON_TAC (find_term (hd_is "xor_bytes") w))) THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
   TRY (CONV_TAC(REDEPTH_CONV UNWIND_CONV)) THEN
   REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL;
               distinctness "option"; injectivity "option"] THEN
   DISCH_THEN (SUBST1_TAC o SYM) THEN
   ONCE_REWRITE_TAC[bytes_to_word_def] THEN
   REWRITE_TAC[NOT_SUC; SUC_SUB1] THEN MATCH_REDUCE_TAC THEN
   REWRITE_TAC[WORD_XOR_0; word_xor_set_byte] THEN
   FIRST_X_ASSUM (fun ih -> FIRST_ASSUM (fun h ->
     REWRITE_TAC[GEN_ALL (MATCH_MP ih h)]))));;

let xor_bytes_length = prove
 (`!xs ys zs.
     xor_bytes xs ys = SOME zs ==>
     LENGTH xs <= LENGTH zs /\ LENGTH zs = LENGTH ys`,
  (* the xor of two lists of bytes is as long as the second and at
     least as long as the first, by the induction of the
     definition; the case of the xor of the tails is what
     EVERY_CASE_TAC splits *)
  (let xb = xor_bytes_def in
   LIST_INDUCT_TAC THENL
    [REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [xb] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[injectivity "option"] THEN
     DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[LENGTH; LE_0];
     (fun (asl,w as gl) ->
        let ysv = fst(dest_forall w) in
        (X_GEN_TAC ysv THEN
         STRUCT_CASES_TAC(ISPEC ysv list_CASES_v)) gl) THEN
     GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [xb] THEN
     EVERY_CASE_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
     TRY(DISCH_THEN(SUBST1_TAC o SYM)) THEN
     REWRITE_TAC[LENGTH; LE_SUC; SUC_INJ] THEN
     FIRST_ASSUM(fun st -> FIRST_ASSUM(fun ih ->
       ACCEPT_TAC(MATCH_MP ih st)))]));;

(* [local] *)
let xor_bytes_drop = prove
 (`!n xs ys zs.
     xor_bytes xs ys = SOME zs ==>
     xor_bytes (DROP n xs) (DROP n ys) = SOME (DROP n zs)`,
  (* dropping from both lists drops from the xor as well, by the
     induction of the definition *)
  (let xb = xor_bytes_def in
   SUBGOAL_THEN
     `!xs n ys zs. xor_bytes xs ys = SOME zs
        ==> xor_bytes (DROP n xs) (DROP n ys) = SOME (DROP n zs)`
     (fun th -> REPEAT GEN_TAC THEN MATCH_ACCEPT_TAC th) THEN
   LIST_INDUCT_TAC THENL
    [REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [xb] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[injectivity "option"] THEN
     DISCH_THEN(SUBST1_TAC o SYM) THEN
     REWRITE_TAC[DROP] THEN
     GEN_REWRITE_TAC LAND_CONV [xb] THEN
     MATCH_REDUCE_TAC THEN REWRITE_TAC[];
     GEN_TAC THEN
     (fun (asl,w as gl) ->
        let ysv = fst(dest_forall w) in
        (X_GEN_TAC ysv THEN
         STRUCT_CASES_TAC(ISPEC ysv list_CASES_v)) gl) THEN
     GEN_TAC THEN
     GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [xb] THEN
     EVERY_CASE_TAC THEN
     REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
     TRY(DISCH_THEN(SUBST1_TAC o SYM)) THEN
     REWRITE_TAC[DROP] THEN
     COND_CASES_TAC THEN ASM_REWRITE_TAC[] THENL
      [GEN_REWRITE_TAC LAND_CONV [xb] THEN
       ASM_REWRITE_TAC[] THEN MATCH_REDUCE_TAC THEN REWRITE_TAC[];
       FIRST_ASSUM(fun st -> FIRST_ASSUM(fun ih ->
         MATCH_ACCEPT_TAC(MATCH_MP ih st)))]]));;

(* [local] *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let xor_bytes_xor_words = prove
 (cake_as_vars (fun () ->
    `!zs1 zs2 vals1 vals2 res_vals.
       xor_bytes vals1 vals2 = SOME res_vals /\ good_dimindex (:'a)
         /\
       EVERY (\w. w = (n2w 0)) zs1 /\ EVERY (\w. w = (n2w 0)) zs2
         /\
       LENGTH zs1 = LENGTH vals1 DIV (dimindex (:'a) DIV 8) + 1 /\
       LENGTH zs2 = LENGTH vals2 DIV (dimindex (:'a) DIV 8) + 1 ==>
       xor_words (write_bytes vals1 zs1 be)
                 (write_bytes vals2 zs2 be) =
       SOME (write_bytes res_vals zs2 be:('a word) list)`),
  (* the induction of the source on the first list of words: the
     first word of both takes the bytes that fit in a word, and the
     xor of those two words is the word of the xor of the bytes
     (xor_bytes_bytes_to_word).  For the rest, either there are
     bytes left, and the induction hypothesis says it of them (with
     the length of a list of words one shorter, which is what
     DIV_SUB_STEP is for), or the bytes fitted in the first word,
     and
     then there is no word left and the two lists of the rest are
     the same list *)
  ((* the induction hypothesis is the assumption that concludes an
      equation, and the assumption about xor_bytes is the one that
      the lemmas about it are applied to *)
   let find_ih asl =
     snd (find (fun (_,th) ->
       let b = snd(strip_forall(concl th)) in
       is_imp b && is_eq (rand b)) asl) in
   let is_xb th =
     is_eq (concl th) && hd_is "xor_bytes" (lhs (concl th)) in
   let nil_of t = mk_list([], hd (snd (dest_type (type_of t)))) in
   let TAIL_TAC =
     W(fun (asl,w) ->
       let ws = snd (strip_comb (lhs w)) in
       let a1 = snd (strip_comb (el 0 ws)) in
       let k = rand (rator (el 0 a1)) in
       let v1 = rand (el 0 a1) in
       ASM_CASES_TAC (mk_binop `(<=):num->num->bool` k
                        (list_mk_icomb "LENGTH" [v1]))) THENL
      [(* the rest of the bytes is the rest of the words *)
       W(fun (asl,w) ->
         let ws = snd (strip_comb (lhs w)) in
         let a1 = snd (strip_comb (el 0 ws)) in
         let a2 = snd (strip_comb (el 1 ws)) in
         let k = rand (rator (el 0 a1)) in
         let v2 = rand (el 0 a2) in
         SUBGOAL_THEN (mk_binop `(<=):num->num->bool` k
                         (list_mk_icomb "LENGTH" [v2])) ASSUME_TAC THENL
          [ASM_ARITH_TAC; ALL_TAC]) THEN
       W(fun (asl,w) ->
         let ih = find_ih asl in
         let ws = snd (strip_comb (lhs w)) in
         let a1 = snd (strip_comb (el 0 ws)) in
         let a2 = snd (strip_comb (el 1 ws)) in
         let dr = el 0 (snd (strip_comb (rand (rhs w)))) in
         let ih' = SPECL [el 1 a2; el 0 a1; el 0 a2; dr] ih in
         SUBGOAL_THEN (lhand (concl ih'))
           (fun th -> ACCEPT_TAC (MP ih' th))) THEN
       REPEAT CONJ_TAC THEN
       TRY (FIRST_ASSUM ACCEPT_TAC) THEN
       TRY (W(fun (asl,w) ->
         let k = rand (rator (find_term (hd_is "DROP") w)) in
         FIRST_ASSUM (fun h ->
           ACCEPT_TAC (MATCH_MP (SPEC k xor_bytes_drop) h)))) THEN
       REWRITE_TAC[LENGTH_DROP] THEN
       ASM_SIMP_TAC[DIV_SUB_STEP] THEN ASM_ARITH_TAC;
       (* or the bytes fit in the first word, and there is no word
          left *)
       W(fun (asl,w) ->
         let ws = snd (strip_comb (lhs w)) in
         let a1 = snd (strip_comb (el 0 ws)) in
         let k = rand (rator (el 0 a1)) in
         let v1 = rand (el 0 a1) in
         let t1 = el 1 a1 in
         SUBGOAL_THEN (mk_eq (t1, nil_of t1)) SUBST_ALL_TAC THENL
          [REWRITE_TAC[GSYM LENGTH_EQ_NIL] THEN
           SUBGOAL_THEN (mk_binop `(<):num->num->bool`
                           (list_mk_icomb "LENGTH" [v1]) k)
             (fun lt -> ASSUME_TAC (MATCH_MP DIV_LT lt)) THENL
            [ASM_ARITH_TAC; ALL_TAC] THEN
           ASM_ARITH_TAC;
           ALL_TAC]) THEN
       REWRITE_TAC[write_bytes_def] THEN
       ONCE_REWRITE_TAC[xor_words_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[injectivity "option"] THEN
       W(fun (asl,w) ->
         let k = rand (rator (find_term (hd_is "DROP") w)) in
         FIRST_ASSUM (fun h ->
           if not (is_xb h) then fail() else
           let v1 = el 0 (snd (strip_comb (lhs (concl h)))) in
           MP_TAC (MATCH_MP (SPEC k xor_bytes_drop) h) THEN
           SUBGOAL_THEN (mk_eq (list_mk_icomb "DROP" [k; v1],
                                nil_of v1)) SUBST1_TAC THENL
            [REWRITE_TAC[DROP_NIL] THEN ASM_ARITH_TAC; ALL_TAC])) THEN
       ONCE_REWRITE_TAC[xor_bytes_def] THEN MATCH_REDUCE_TAC THEN
       REWRITE_TAC[injectivity "option"] THEN
       DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[]] in
   (* a list of words of the length that the statement asks for is
      not empty *)
   LIST_INDUCT_TAC THENL
    [REPEAT GEN_TAC THEN
     REWRITE_TAC[LENGTH; ARITH_RULE `(0 = n + 1) <=> F`];
     ALL_TAC] THEN
   REPEAT GEN_TAC THEN
   LIST_CASES_TAC ["zs2"] THENL
    [REWRITE_TAC[LENGTH; ARITH_RULE `(0 = n + 1) <=> F`];
     ALL_TAC] THEN
   REWRITE_TAC[write_bytes_def; LENGTH; ALL] THEN
   CONV_TAC(DEPTH_CONV let_CONV) THEN
   ONCE_REWRITE_TAC[xor_words_def] THEN MATCH_REDUCE_TAC THEN
   STRIP_TAC THEN VAR_EQ_TAC THEN
   FIRST_ASSUM (fun h ->
     if is_xb h then STRIP_ASSUME_TAC (MATCH_MP xor_bytes_length h)
     else fail()) THEN
   (* a word holds at least one byte *)
   W(fun (asl,w) ->
     let k = rand (rator (find_term (hd_is "DROP") w)) in
     SUBGOAL_THEN (mk_binop `(<):num->num->bool` `0` k)
       ASSUME_TAC THENL
      [FIRST_ASSUM (fun gd ->
         if hd_is "good_dimindex" (concl gd) then MP_TAC gd
         else fail()) THEN
       REWRITE_TAC[good_dimindex_def] THEN
       DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
       CONV_TAC NUM_REDUCE_CONV;
       ALL_TAC]) THEN
   W(fun (asl,w) ->
     let xw = find_term (fun tm -> hd_is "xor_words" tm &&
                length(snd(strip_comb tm)) = 2) w in
     let tl = rand (rand (rhs w)) in
     SUBGOAL_THEN (mk_eq (xw, list_mk_icomb "SOME" [tl]))
       SUBST1_TAC THENL
      [TAIL_TAC; ALL_TAC]) THEN
   (* and the first word is the xor of the first words *)
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
   TRY (CONV_TAC(REDEPTH_CONV UNWIND_CONV)) THEN
   REWRITE_TAC[EXISTS_UNIQUE_REFL; SELECT_REFL;
               distinctness "option"; injectivity "option"] THEN
   REWRITE_TAC[CONS_11] THEN
   FIRST_ASSUM (fun h ->
     MATCH_ACCEPT_TAC
       (GEN_ALL (MATCH_MP xor_bytes_bytes_to_word h)))));;

(* xor_bytes_xor_words *)
(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let data_to_word_memoryProof_xor_bytes_xor_words = prove
 (cake_as_vars (fun () ->
    `xor_bytes vals1 vals2 = SOME res_vals /\ good_dimindex (:'a) ==>
     xor_words (write_bytes vals1 (make_zeros vals1) be)
               (write_bytes vals2 (make_zeros vals2) be) =
     SOME (write_bytes res_vals (make_zeros vals2) be:('a word)
       list)`),
  (* the zeroes of make_zeros are as many as the lemma above asks
     for, and they are all zero *)
  (let all_zero = prove
    (`!n. ALL (\w. w = ((n2w 0):(N)word)) (REPLICATE n (n2w 0))`,
     INDUCT_TAC THEN ASM_REWRITE_TAC[REPLICATE; ALL]) in
   STRIP_TAC THEN MATCH_MP_TAC xor_bytes_xor_words THEN
   ASM_REWRITE_TAC[make_zeros_def; all_zero;
                   LENGTH_REPLICATE]));;

let xor_words_word_list = prove
 (`!vals1 vals2 res_vals a1 a2 be' frame m.
     xor_words vals1 vals2 = SOME res_vals /\
     good_dimindex (:'a) /\ LENGTH vals1 < dimword (:'a) /\
     (misc_word_list a1 (MAP wordLang_Word vals1) *
      misc_word_list a2 (MAP wordLang_Word vals2) *
      frame) (fun2set (m,dm)) ==>
     (?m1.
       (misc_word_list a1 (MAP wordLang_Word vals1) *
        misc_word_list a2 (MAP wordLang_Word res_vals) *
        frame) (fun2set (m1,(dm:'a word->bool))) /\
       word_xor_bytes a1 a2 (n2w (LENGTH vals1)) dm m = SOME m1)`,
(* the words of the second list become the exclusive or of the two,
   two words to a step: the induction is the strong one on the
   length of the first list that the source does, and the cases of
   the step are its cases -- no word at all (the test of
   word_xor_bytes says the length is below two and it is zero, so
   the memory stands), one word (one cell of each list is read and
   the cell of the second written) and two words and more (two
   cells of each are read, the two of the second are written, and
   the induction hypothesis does the rest with the four cells and
   the frame of the statement as its own frame).  The reads are
   read_fun2set and the writes write_fun2set, where the source has
   SEP_R_TAC and SEP_W_TAC; what the test of the step compares are
   words of lengths below the dimword, which good_dimindex gives,
   and the length of the rest is the one of the step less two *)
  ((let hd_is n t =
     (try fst(dest_const(fst(strip_comb t))) = n
      with Failure _ -> false) in
  let rec facs t =
    if hd_is "STAR" t then
      let args = snd(strip_comb t) in
      facs (el 0 args) @ facs (el 1 args)
    else [t] in
  let grab asl p =
    tryfind (fun (_,th) ->
      if (try p th with Failure _ -> false) then th else fail())
      asl in
  (* a factor of a separating product brought to the front *)
  let front sp cell =
    let pred = rator (concl sp) in
    let fs = facs pred in
    let rest = filter (fun t -> not (t = cell)) fs in
    let st = fst(strip_comb pred) in
    let mk x y = mk_comb(mk_comb(st,x),y) in
    let target = mk cell (end_itlist mk rest) in
    let eq = prove (mk_eq (pred,target),
              REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
    REWRITE_RULE[eq] sp in
  let cellat a sp =
    find (fun t -> hd_is "set_sep_one" t &&
                   fst(dest_pair (rand t)) = a)
      (facs (rator (concl sp))) in
  (* what the cell at an address says, and the write into it *)
  let rd a sp = MATCH_MP read_fun2set (front sp (cellat a sp)) in
  let wr a v sp =
    SPEC v (MATCH_MP write_fun2set (front sp (cellat a sp))) in
  let isw = prove
   (`isWord (wordLang_Word w) = T /\
     theWord (wordLang_Word w) = w`,
    CONJ_TAC THENL
     [REWRITE_TAC[isWord_def] THEN MATCH_REDUCE_TAC;
      REWRITE_TAC[theWord_def]]) in
  let addr2 = WORD_RULE
    `!(a:(N)word). (a + bytes_in_word) + bytes_in_word =
                   a + n2w 2 * bytes_in_word` in
  (* the strong induction on the length of the first list *)
  let strong = prove
   (`!P. (!vals1. (!ys. LENGTH ys < LENGTH vals1 ==> P ys)
                  ==> P vals1)
         ==> !vals1:(A)list. P vals1`,
    GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `!n vals1:(A)list. LENGTH vals1 = n ==> P vals1`
      (fun th -> MESON_TAC[th]) THEN
    MATCH_MP_TAC num_WF THEN ASM_MESON_TAC[]) in
  (* the word of a length and the two of the test *)
  let gdw = prove
   (`good_dimindex (:'a) ==> 2 < dimword (:'a)`,
    REWRITE_TAC[good_dimindex_def; dimword] THEN
    DISCH_THEN (DISJ_CASES_THEN SUBST1_TAC) THEN
    CONV_TAC NUM_REDUCE_CONV) in
  let islo = prove
   (`!n. n < 2 /\ 2 < dimword (:'a)
         ==> ((n2w n):'a word) <+ n2w 2`,
    GEN_TAC THEN REWRITE_TAC[dimword] THEN STRIP_TAC THEN
    REWRITE_TAC[WORD_ULT] THEN
    SUBGOAL_THEN `w2n ((n2w n):'a word) = n /\
                  w2n ((n2w 2):'a word) = 2`
      (fun th -> REWRITE_TAC[th]) THENL
     [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    ASM_ARITH_TAC) in
  let notlo = prove
   (`!n. 2 <= n /\ n < dimword (:'a)
         ==> ~(((n2w n):'a word) <+ n2w 2)`,
    GEN_TAC THEN REWRITE_TAC[dimword] THEN STRIP_TAC THEN
    REWRITE_TAC[WORD_ULT] THEN
    SUBGOAL_THEN `w2n ((n2w n):'a word) = n /\
                  w2n ((n2w 2):'a word) = 2`
      (fun th -> REWRITE_TAC[th]) THENL
     [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    ASM_ARITH_TAC) in
  let notzero = prove
   (`!n. 0 < n /\ n < dimword (:'a)
         ==> ~(((n2w n):'a word) = n2w 0)`,
    GEN_TAC THEN REWRITE_TAC[dimword] THEN STRIP_TAC THEN
    REWRITE_TAC[GSYM VAL_EQ] THEN
    SUBGOAL_THEN `w2n ((n2w n):'a word) = n /\
                  w2n ((n2w 0):'a word) = 0`
      (fun th -> REWRITE_TAC[th]) THENL
     [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    ASM_ARITH_TAC) in
  let sub2 = prove
   (`!n. 2 <= n ==> ((n2w n):'a word) - n2w 2 = n2w (n - 2)`,
    REPEAT STRIP_TAC THEN ASM_SIMP_TAC[WORD_SUB]) in
  (* the facts of a length that the step of the test wants *)
  let lenfacts =
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      ASSUME_TAC (MATCH_MP gdw gd)) in
  MATCH_MP_TAC strong THEN
  GEN_TAC THEN DISCH_TAC THEN
  REPEAT GEN_TAC THEN
  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  lenfacts THEN
  CASES_ON_NAME "vals1" THENL
   [(* the empty list: there is nothing to write *)
    FIRST_X_ASSUM (fun xw ->
      if not (try hd_is "xor_words" (lhs (concl xw))
              with Failure _ -> false) then fail() else
      MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[injectivity "option"] THEN
    DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
    FIRST_ASSUM (fun sep ->
      if not (try hd_is "STAR" (rator (concl sep))
              with Failure _ -> false) then fail() else
      EXISTS_TAC (fst (dest_pair (rand (rand (concl sep)))))) THEN
    CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[word_xor_bytes_def] THEN
    W(fun (asl,gl) ->
      let dw = grab asl (fun th ->
        try hd_is "<" (concl th) && hd_is "dimword" (rand (concl th))
        with Failure _ -> false) in
      REWRITE_TAC[MATCH_MP islo (CONJ (ARITH_RULE `0 < 2`) dw)]) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  CASES_ON_NAME "vals2" THENL
   [(* the second list is as long, so it is not empty *)
    FIRST_X_ASSUM (fun xw ->
      if not (try hd_is "xor_words" (lhs (concl xw))
              with Failure _ -> false) then fail() else
      MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[distinctness "option"];
    ALL_TAC] THEN
  (* the first words of the two lists *)
  FIRST_X_ASSUM (fun xw ->
    if not (try hd_is "xor_words" (lhs (concl xw))
            with Failure _ -> false) then fail() else
    MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
  SAFE_MATCH_REDUCE_TAC THEN
  W(fun (asl,gl) ->
    CASES_ON_TAC (find_term (hd_is "xor_words") gl)) THEN
  SAFE_MATCH_REDUCE_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[LENGTH]) THEN
  REWRITE_TAC[MAP; word_list_def; STAR_ASSOC] THEN
  RULE_ASSUM_TRY (REWRITE_RULE[MAP; word_list_def; STAR_ASSOC]) THEN
  (* the tail of the first list: one word, or two and more *)
  W(fun (asl,gl) ->
    let xw = grab asl (fun th ->
      try hd_is "xor_words" (lhs (concl th))
      with Failure _ -> false) in
    CASES_ON_TAC (el 0 (snd(strip_comb (lhs (concl xw)))))) THENL
   [(* one word: one cell is read and one written *)
    FIRST_X_ASSUM (fun xw ->
      if not (try hd_is "xor_words" (lhs (concl xw))
              with Failure _ -> false) then fail() else
      MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[injectivity "option"] THEN
    DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
    REWRITE_TAC[MAP; word_list_def; emp_STAR; STAR_emp;
                STAR_ASSOC] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[MAP; word_list_def; emp_STAR;
                                 STAR_emp; STAR_ASSOC]) THEN
    W(fun (asl,gl) ->
      let sep = grab asl (fun th ->
        try hd_is "STAR" (rator (concl th))
        with Failure _ -> false) in
      let cs = filter (hd_is "set_sep_one")
                 (facs (rator (concl sep))) in
      let a1a = fst (dest_pair (rand (el 0 cs))) in
      let a2a = fst (dest_pair (rand (el 1 cs))) in
      let gcs = filter (hd_is "set_sep_one")
                  (facs (rator (lhand (snd (strip_exists gl))))) in
      let nv = snd (dest_pair (rand (find (fun t ->
                 fst (dest_pair (rand t)) = a2a) gcs))) in
      let wth = wr a2a nv sep in
      MAP_EVERY STRIP_ASSUME_TAC [rd a1a sep; rd a2a sep] THEN
      ASSUME_TAC wth THEN
      EXISTS_TAC (fst (dest_pair (rand (rand (concl wth)))))) THEN
    CONJ_TAC THENL
     [W(fun (asl,gl) ->
        let pred = rator gl in
        FIRST_ASSUM (fun wth ->
          let wp = rator (concl wth) in
          if not (hd_is "STAR" wp) then fail() else
          if not (rand (concl wth) = rand gl) then fail() else
          let eq = prove (mk_eq (pred,wp),
                    REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
          ACCEPT_TAC (REWRITE_RULE[GSYM eq] wth)));
      ALL_TAC] THEN
    REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
    ONCE_REWRITE_TAC[word_xor_bytes_def] THEN
    W(fun (asl,gl) ->
      let dw = grab asl (fun th ->
        try hd_is "<" (concl th) && hd_is "dimword" (rand (concl th))
        with Failure _ -> false) in
      let dw1 = MATCH_MP (ARITH_RULE `!d. 2 < d ==> 1 < d`) dw in
      REWRITE_TAC[MATCH_MP islo (CONJ (ARITH_RULE `1 < 2`) dw);
                  MATCH_MP notzero
                    (CONJ (ARITH_RULE `0 < 1`) dw1)]) THEN
    REWRITE_TAC[read_word_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    ASM_REWRITE_TAC[isw];
    (* two words and more: two cells are written and what is left
       is the induction hypothesis *)
    (* the second list is as long, so its tail is not empty *)
    W(fun (asl,gl) ->
      let xw = grab asl (fun th ->
        try hd_is "xor_words" (lhs (concl th))
        with Failure _ -> false) in
      CASES_ON_TAC (el 1 (snd(strip_comb (lhs (concl xw)))))) THENL
     [FIRST_X_ASSUM (fun xw ->
        if not (try hd_is "xor_words" (lhs (concl xw))
                with Failure _ -> false) then fail() else
        MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
      SAFE_MATCH_REDUCE_TAC THEN
      REWRITE_TAC[distinctness "option"];
      ALL_TAC] THEN
    (* the second words of the two lists *)
    FIRST_X_ASSUM (fun xw ->
      if not (try hd_is "xor_words" (lhs (concl xw))
              with Failure _ -> false) then fail() else
      MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    W(fun (asl,gl) ->
      CASES_ON_TAC (find_term (hd_is "xor_words") gl)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
    DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
    REWRITE_TAC[MAP; word_list_def; STAR_ASSOC; addr2] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[MAP; word_list_def; STAR_ASSOC;
                                 addr2]) THEN
    (* the four cells of the step, read and then written *)
    W(fun (asl,gl) ->
      let sep = grab asl (fun th ->
        try hd_is "STAR" (rator (concl th)) &&
            is_var (fst (dest_pair (rand (rand (concl th))))) &&
            length (filter (hd_is "set_sep_one")
                     (facs (rator (concl th)))) = 4
        with Failure _ -> false) in
      let adr c = fst (dest_pair (rand c)) in
      let cs = filter (hd_is "set_sep_one")
                 (facs (rator (concl sep))) in
      let gcs = filter (hd_is "set_sep_one")
                  (facs (rator (lhand (snd (strip_exists gl))))) in
      let nvat a = snd (dest_pair (rand (find (fun t ->
                     adr t = a) gcs))) in
      let a2a = adr (el 2 cs) in
      let a2b = adr (el 3 cs) in
      let w1 = wr a2a (nvat a2a) sep in
      let w2 = wr a2b (nvat a2b) w1 in
      MAP_EVERY STRIP_ASSUME_TAC
        (map (fun c -> rd (adr c) sep) cs) THEN
      ASSUME_TAC w2) THEN
    (* and the rest of the two lists is the hypothesis *)
    W(fun (asl,gl) ->
      let sep = grab asl (fun th ->
        try hd_is "STAR" (rator (concl th)) &&
            not (is_var (fst (dest_pair (rand (rand (concl th))))))
        with Failure _ -> false) in
      let st = fst (strip_comb (rator (concl sep))) in
      let mk x y = mk_comb (mk_comb (st,x),y) in
      let fs = facs (rator (concl sep)) in
      let wls = filter (hd_is "misc_word_list") fs in
      let others = filter (fun t -> not (mem t wls)) fs in
      let want = mk (mk (el 0 wls) (el 1 wls))
                   (end_itlist mk others) in
      let eq = prove (mk_eq (rator (concl sep), want),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      let sep2 = REWRITE_RULE[eq] sep in
      let ih = grab asl (fun th ->
        is_forall (concl th) &&
        can (find_term (hd_is "word_xor_bytes")) (concl th)) in
      let lst = rand (rand (el 0 wls)) in
      let xw = grab asl (fun th ->
        try hd_is "xor_words" (lhs (concl th)) &&
            el 0 (snd(strip_comb (lhs (concl th)))) = lst
        with Failure _ -> false) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let bnd = grab asl (fun th ->
        try hd_is "<" (concl th) &&
            hd_is "dimword" (rand (concl th)) &&
            not (hd_is "NUMERAL" (lhand (concl th)))
        with Failure _ -> false) in
      let lt = prove (mk_binop `(<):num->num->bool`
                  (mk_icomb (`LENGTH`,lst)) (lhand (concl bnd)),
                REWRITE_TAC[LENGTH] THEN ARITH_TAC) in
      let ltd = MATCH_MP (ARITH_RULE
                  `!a b c:num. a < b /\ b < c ==> a < c`)
                  (CONJ lt bnd) in
      let bound = rand (lhand (snd (strip_forall (concl ih)))) in
      let ihi = MP (SPEC lst ih)
                  (prove (mk_binop `(<):num->num->bool`
                     (mk_icomb (`LENGTH`,lst)) bound,
                   REWRITE_TAC[LENGTH] THEN ARITH_TAC)) in
      MP_TAC (MATCH_MP (GEN_ALL ihi)
                (CONJ xw (CONJ gd (CONJ ltd sep2))))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    W(fun (asl,gl) ->
      let wx = grab asl (fun th ->
        try hd_is "word_xor_bytes" (lhs (concl th))
        with Failure _ -> false) in
      EXISTS_TAC (rand (rhs (concl wx)))) THEN
    CONJ_TAC THENL
     [W(fun (asl,gl) ->
        let pred = rator gl in
        FIRST_ASSUM (fun sth ->
          let sp = rator (concl sth) in
          if not (hd_is "STAR" sp) then fail() else
          if not (rand (concl sth) = rand gl) then fail() else
          let eq = prove (mk_eq (pred,sp),
                    REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
          ACCEPT_TAC (REWRITE_RULE[GSYM eq] sth)));
      ALL_TAC] THEN
    REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[word_xor_bytes_def] THEN
    ASM_REWRITE_TAC[read_word_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    ASM_REWRITE_TAC[isw] THEN
    W(fun (asl,gl) ->
      let bnd = grab asl (fun th ->
        try hd_is "<" (concl th) &&
            hd_is "dimword" (rand (concl th)) &&
            not (hd_is "NUMERAL" (lhand (concl th)))
        with Failure _ -> false) in
      let bnd2 = REWRITE_RULE[LENGTH] bnd in
      let n = lhand (concl bnd2) in
      let ge2 = prove (mk_binop `(<=):num->num->bool` `2` n,
