  (* the facts of a length that the step of the test wants *)
  let lenfacts =
    W(fun (asl,gl) ->
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      ASSUME_TAC (MATCH_MP gdw gd)) in
  MATCH_MP_TAC strong THEN
  GEN_TAC THEN DISCH_TAC THEN
  REPEAT GEN_TAC THEN
  DISCH_THEN (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  lenfacts THEN
  CASES_ON_NAME "vals1" THENL
   [(* the empty list: there is nothing to write *)
    FIRST_X_ASSUM (fun xw ->
      if not (try hd_is "xor_words" (lhs (concl xw))
              with Failure _ -> false) then fail() else
      MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[injectivity "option"] THEN
    DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
    FIRST_ASSUM (fun sep ->
      if not (try hd_is "STAR" (rator (concl sep))
              with Failure _ -> false) then fail() else
      EXISTS_TAC (fst (dest_pair (rand (rand (concl sep)))))) THEN
    CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[word_xor_bytes_def] THEN
    W(fun (asl,gl) ->
      let dw = grab asl (fun th ->
        try hd_is "<" (concl th) && hd_is "dimword" (rand (concl th))
        with Failure _ -> false) in
      REWRITE_TAC[MATCH_MP islo (CONJ (ARITH_RULE `0 < 2`) dw)]) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  (* the first words of the two lists *)
  FIRST_X_ASSUM (fun xw ->
    if not (try hd_is "xor_words" (lhs (concl xw))
            with Failure _ -> false) then fail() else
    MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
  SAFE_MATCH_REDUCE_TAC THEN
  W(fun (asl,gl) ->
    CASES_ON_TAC (find_term (hd_is "xor_words") gl)) THEN
  SAFE_MATCH_REDUCE_TAC THEN
  REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
  DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
  RULE_ASSUM_TRY (REWRITE_RULE[LENGTH]) THEN
  REWRITE_TAC[MAP; word_list_def; STAR_ASSOC] THEN
  RULE_ASSUM_TRY (REWRITE_RULE[MAP; word_list_def; STAR_ASSOC]) THEN
  (* the tail of the first list: one word, or two and more *)
  W(fun (asl,gl) ->
    let xw = grab asl (fun th ->
      try hd_is "xor_words" (lhs (concl th))
      with Failure _ -> false) in
    CASES_ON_TAC (el 0 (snd(strip_comb (lhs (concl xw)))))) THENL
   [(* one word: one cell is read and one written *)
    FIRST_X_ASSUM (fun xw ->
      if not (try hd_is "xor_words" (lhs (concl xw))
              with Failure _ -> false) then fail() else
      MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[injectivity "option"] THEN
    DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
    REWRITE_TAC[MAP; word_list_def; emp_STAR; STAR_emp;
                STAR_ASSOC] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[MAP; word_list_def; emp_STAR;
                                 STAR_emp; STAR_ASSOC]) THEN
    W(fun (asl,gl) ->
      let sep = grab asl (fun th ->
        try hd_is "STAR" (rator (concl th))
        with Failure _ -> false) in
      let cs = filter (hd_is "set_sep_one")
                 (facs (rator (concl sep))) in
      let a1a = fst (dest_pair (rand (el 0 cs))) in
      let gcs = filter (hd_is "set_sep_one")
                  (facs (rator (lhand (snd (strip_exists gl))))) in
      let nv = snd (dest_pair (rand (find (fun t ->
                 fst (dest_pair (rand t)) = a1a) gcs))) in
      let wth = wr a1a nv sep in
      STRIP_ASSUME_TAC (rd a1a sep) THEN
      ASSUME_TAC wth THEN
      EXISTS_TAC (fst (dest_pair (rand (rand (concl wth)))))) THEN
    CONJ_TAC THENL
     [W(fun (asl,gl) ->
        let pred = rator gl in
        FIRST_ASSUM (fun wth ->
          let wp = rator (concl wth) in
          if not (hd_is "STAR" wp) then fail() else
          if not (rand (concl wth) = rand gl) then fail() else
          let eq = prove (mk_eq (pred,wp),
                    REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
          ACCEPT_TAC (REWRITE_RULE[GSYM eq] wth)));
      ALL_TAC] THEN
    REWRITE_TAC[LENGTH] THEN CONV_TAC NUM_REDUCE_CONV THEN
    ONCE_REWRITE_TAC[word_xor_bytes_def] THEN
    W(fun (asl,gl) ->
      let dw = grab asl (fun th ->
        try hd_is "<" (concl th) && hd_is "dimword" (rand (concl th))
        with Failure _ -> false) in
      let dw1 = MATCH_MP (ARITH_RULE `!d. 2 < d ==> 1 < d`) dw in
      REWRITE_TAC[MATCH_MP islo (CONJ (ARITH_RULE `1 < 2`) dw);
                  MATCH_MP notzero
                    (CONJ (ARITH_RULE `0 < 1`) dw1)]) THEN
    REWRITE_TAC[read_word_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    ASM_REWRITE_TAC[isw];
    (* two words and more: two cells are written and what is left
       is the induction hypothesis *)
    (* the second words of the two lists *)
    FIRST_X_ASSUM (fun xw ->
      if not (try hd_is "xor_words" (lhs (concl xw))
              with Failure _ -> false) then fail() else
      MP_TAC (ONCE_REWRITE_RULE[xor_words_def] xw)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    W(fun (asl,gl) ->
      CASES_ON_TAC (find_term (hd_is "xor_words") gl)) THEN
    SAFE_MATCH_REDUCE_TAC THEN
    REWRITE_TAC[distinctness "option"; injectivity "option"] THEN
    DISCH_THEN (SUBST_ALL_TAC o SYM) THEN
    REWRITE_TAC[MAP; word_list_def; STAR_ASSOC; addr2] THEN
    RULE_ASSUM_TRY (REWRITE_RULE[MAP; word_list_def; STAR_ASSOC;
                                 addr2]) THEN
    (* the four cells of the step, read and then written *)
    W(fun (asl,gl) ->
      let sep = grab asl (fun th ->
        try hd_is "STAR" (rator (concl th)) &&
            is_var (fst (dest_pair (rand (rand (concl th))))) &&
            length (filter (hd_is "set_sep_one")
                     (facs (rator (concl th)))) = 2
        with Failure _ -> false) in
      let adr c = fst (dest_pair (rand c)) in
      let cs = filter (hd_is "set_sep_one")
                 (facs (rator (concl sep))) in
      let gcs = filter (hd_is "set_sep_one")
                  (facs (rator (lhand (snd (strip_exists gl))))) in
      let nvat a = snd (dest_pair (rand (find (fun t ->
                     adr t = a) gcs))) in
      let a2a = adr (el 0 cs) in
      let a2b = adr (el 1 cs) in
      let w1 = wr a2a (nvat a2a) sep in
      let w2 = wr a2b (nvat a2b) w1 in
      MAP_EVERY STRIP_ASSUME_TAC
        (map (fun c -> rd (adr c) sep) cs) THEN
      ASSUME_TAC w2) THEN
    (* and the rest of the two lists is the hypothesis *)
    W(fun (asl,gl) ->
      let sep = grab asl (fun th ->
        try hd_is "STAR" (rator (concl th)) &&
            not (is_var (fst (dest_pair (rand (rand (concl th))))))
        with Failure _ -> false) in
      let st = fst (strip_comb (rator (concl sep))) in
      let mk x y = mk_comb (mk_comb (st,x),y) in
      let fs = facs (rator (concl sep)) in
      let wls = filter (hd_is "misc_word_list") fs in
      let others = filter (fun t -> not (mem t wls)) fs in
      let want = mk (el 0 wls) (end_itlist mk others) in
      let eq = prove (mk_eq (rator (concl sep), want),
                REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
      let sep2 = REWRITE_RULE[eq] sep in
      let ih = grab asl (fun th ->
        is_forall (concl th) &&
        can (find_term (hd_is "word_xor_bytes")) (concl th)) in
      let lst = rand (rand (el 0 wls)) in
      let xw = grab asl (fun th ->
        try hd_is "xor_words" (lhs (concl th)) &&
            el 0 (snd(strip_comb (lhs (concl th)))) = lst
        with Failure _ -> false) in
      let gd = grab asl (fun th ->
        hd_is "good_dimindex" (concl th)) in
      let bnd = grab asl (fun th ->
        try hd_is "<" (concl th) &&
            hd_is "dimword" (rand (concl th)) &&
            not (hd_is "NUMERAL" (lhand (concl th)))
        with Failure _ -> false) in
      let lt = prove (mk_binop `(<):num->num->bool`
                  (mk_icomb (`LENGTH`,lst)) (lhand (concl bnd)),
                REWRITE_TAC[LENGTH] THEN ARITH_TAC) in
      let ltd = MATCH_MP (ARITH_RULE
                  `!a b c:num. a < b /\ b < c ==> a < c`)
                  (CONJ lt bnd) in
      let bound = rand (lhand (snd (strip_forall (concl ih)))) in
      let ihi = MP (SPEC lst ih)
                  (prove (mk_binop `(<):num->num->bool`
                     (mk_icomb (`LENGTH`,lst)) bound,
                   REWRITE_TAC[LENGTH] THEN ARITH_TAC)) in
      MP_TAC (MATCH_MP (GEN_ALL ihi)
                (CONJ xw (CONJ gd (CONJ ltd sep2))))) THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN
    W(fun (asl,gl) ->
      let wx = grab asl (fun th ->
        try hd_is "word_xor_bytes" (lhs (concl th))
        with Failure _ -> false) in
      EXISTS_TAC (rand (rhs (concl wx)))) THEN
    CONJ_TAC THENL
     [W(fun (asl,gl) ->
        let pred = rator gl in
        FIRST_ASSUM (fun sth ->
          let sp = rator (concl sth) in
          if not (hd_is "STAR" sp) then fail() else
          if not (rand (concl sth) = rand gl) then fail() else
          let eq = prove (mk_eq (pred,sp),
                    REWRITE_TAC[STAR_AC; emp_STAR; STAR_emp]) in
          ACCEPT_TAC (REWRITE_RULE[GSYM eq] sth)));
      ALL_TAC] THEN
    REWRITE_TAC[LENGTH] THEN
    ONCE_REWRITE_TAC[word_xor_bytes_def] THEN
    ASM_REWRITE_TAC[read_word_def] THEN
    CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
    ASM_REWRITE_TAC[isw] THEN
    W(fun (asl,gl) ->
      let bnd = grab asl (fun th ->
        try hd_is "<" (concl th) &&
            hd_is "dimword" (rand (concl th)) &&
            not (hd_is "NUMERAL" (lhand (concl th)))
        with Failure _ -> false) in
      let bnd2 = REWRITE_RULE[LENGTH] bnd in
      let n = lhand (concl bnd2) in
      let ge2 = prove (mk_binop `(<=):num->num->bool` `2` n,
                  REWRITE_TAC[LENGTH] THEN ARITH_TAC) in
      REWRITE_TAC[MATCH_MP notlo (CONJ ge2 bnd2);
                  MATCH_MP sub2 ge2]) THEN
    REWRITE_TAC[ARITH_RULE `!k. SUC (SUC k) - 2 = k`] THEN
    ASM_REWRITE_TAC[]])));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let xor_bytes_word_list = prove
 (cake_as_vars (fun () ->
    `!a1 a2 be' frame.
       xor_bytes vals1 vals2 = SOME res_vals /\
       good_dimindex (:'a) /\ LENGTH (make_zeros vals1:('a word)
         list) < dimword (:'a) /\
       (misc_word_list a1 (MAP wordLang_Word (write_bytes vals1
         (make_zeros vals1) be')) *
        misc_word_list a2 (MAP wordLang_Word (write_bytes vals2
          (make_zeros vals2) be')) *
        frame) (fun2set (m,dm)) ==>
       (?m1.
         (misc_word_list a1 (MAP wordLang_Word (write_bytes vals1
           (make_zeros vals1:('a word) list) be')) *
          misc_word_list a2 (MAP wordLang_Word (write_bytes
            res_vals (make_zeros vals2:('a word) list) be')) *
          frame) (fun2set (m1,(dm:'a word->bool))) /\
         word_xor_bytes a1 a2 (n2w (LENGTH (make_zeros vals1:('a
           word) list))) dm m = SOME m1)`),
  (* the words of the two byte lists are as many as the zeroes, so
     xor_words_word_list is about them, and the xor of the two is
     the one of the result by xor_bytes_xor_words *)
  (REPEAT GEN_TAC THEN STRIP_TAC THEN
   ONCE_REWRITE_TAC[GSYM (ISPECL
     [`make_zeros vals1:('a word)list`; `vals1:(word8)list`;
      `be':bool`] LENGTH_write_bytes)] THEN
   MATCH_MP_TAC xor_words_word_list THEN
   EXISTS_TAC `write_bytes vals2 (make_zeros vals2:('a word)list)
                 be'` THEN
   ASM_REWRITE_TAC[LENGTH_write_bytes] THEN
   MATCH_MP_TAC data_to_word_memoryProof_xor_bytes_xor_words THEN
   ASM_REWRITE_TAC[]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let xor_bytes_word_list_alias = prove
 (cake_as_vars (fun () ->
    `!a1 be' frame.
       xor_bytes vals1 vals1 = SOME res_vals1 /\
       good_dimindex (:'a) /\ LENGTH (make_zeros vals1:('a word)
         list) < dimword (:'a) /\
       (misc_word_list a1 (MAP wordLang_Word (write_bytes vals1
         (make_zeros vals1) be')) *
        frame) (fun2set (m,dm)) ==>
       (?m1.
         (misc_word_list a1 (MAP wordLang_Word (write_bytes
           res_vals1 (make_zeros vals1:('a word) list) be')) *
          frame) (fun2set (m1,(dm:'a word->bool))) /\
         word_xor_bytes a1 a1 (n2w (LENGTH (make_zeros vals1:('a
           word) list))) dm m = SOME m1)`),
  (* and the same where the two lists are one *)
  (REPEAT GEN_TAC THEN STRIP_TAC THEN
   ONCE_REWRITE_TAC[GSYM (ISPECL
     [`make_zeros vals1:('a word)list`; `vals1:(word8)list`;
      `be':bool`] LENGTH_write_bytes)] THEN
   MATCH_MP_TAC xor_words_word_list_alias THEN
   ASM_REWRITE_TAC[LENGTH_write_bytes] THEN
   MATCH_MP_TAC data_to_word_memoryProof_xor_bytes_xor_words THEN
   ASM_REWRITE_TAC[]));;

(* HOL4 data_to_word_memoryProofScript.sml:18637-18644: code that the
   source has in a comment *)

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let el_length_Bytes = prove
 (cake_as_vars (fun () ->
    `el_length (Bytes be fl vals zeros) = LENGTH zeros + 1`),
  (REWRITE_TAC[bytes_def] THEN
   CONV_TAC(ONCE_DEPTH_CONV let_CONV) THEN
   REWRITE_TAC[el_length_def; LENGTH_write_bytes]));;

let blocks_unique_insert_ByteArray2 = prove
 (`blocks_unique ts
     (all_vs refs (RefPtr bl1 p1 :: RefPtr bl2 p2 :: MAP FST vars))
       ==>
     blocks_unique ts
       (all_vs (insert p2 (ByteArray fl2 res_vals) refs)
          (RefPtr bl1 p1 :: RefPtr bl2 p2 :: MAP FST vars))`,
  (* a ByteArray holds no value of the language, so the insert adds
     no Block *)
  (let li = prove
    (`!k1 k2 v (t:(A)spt) y.
        (sptree_lookup k1 (sptree_insert k2 v t) = SOME y) <=>
        (k1 = k2 /\ v = y) \/
        (~(k1 = k2) /\ sptree_lookup k1 t = SOME y)`,
     REPEAT GEN_TAC THEN REWRITE_TAC[lookup_insert] THEN
     COND_CASES_TAC THEN
     ASM_REWRITE_TAC[injectivity "option"] THEN CONV_TAC TAUT) in
   let inc = prove
    (`!refs p2 fl2 res_vals s t a q.
        Block t a q IN
          all_vs (insert p2 (ByteArray fl2 res_vals) refs) s ==>
        Block t a q IN all_vs refs s`,
     REWRITE_TAC[all_vs_def; IN_UNION; IN_ELIM_THM; li;
                 distinctness "bvlSem_ref";
                 injectivity "bvlSem_ref"] THEN MESON_TAC[]) in
   REWRITE_TAC[blocks_unique_def] THEN DISCH_TAC THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
   REPEAT CONJ_TAC THEN ASM_MESON_TAC[inc]));;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_xor_bytes = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((RefPtr bl1 p1,(v1:'a word_loc)) :: (RefPtr bl2 p2,(v2:'a
         word_loc)) :: vars) /\
     lookup p1 refs = SOME (ByteArray fl1 vals1) /\
     lookup p2 refs = SOME (ByteArray fl2 vals2) /\
     xor_bytes vals1 vals2 = SOME res_vals /\
     good_dimindex (:'a) ==>
     (?w1 a1 w2 a2 x1 m1.
       v1 = wordLang_Word w1 /\
       v2 = wordLang_Word w2 /\
       get_real_addr c st w1 = SOME a1 /\
       get_real_addr c st w2 = SOME a2 /\
       m a1 = wordLang_Word x1 /\ a1 IN dm /\
       word_xor_bytes (a1 + bytes_in_word) (a2 + bytes_in_word)
                      (decode_length c x1) dm m = SOME m1 /\
       memory_rel c be ts (insert p2 (ByteArray fl2 res_vals) refs)
         sp st m1 dm
         ((RefPtr bl1 p1,(v1:'a word_loc)) :: (RefPtr bl2
           p2,(v2:'a word_loc)) :: vars))`),
  (* the attempt: the proof of the source names get_real_addr_def,
     memory_rel_tl, memory_rel_ByteArray_IMP, make_zeros_def,
     dimword, good_dimindex_def.  What is here rewrites with them
     and closes by arithmetic, and the cheat is behind it until the
     proof is written.  A MESON over them is what the next round
     adds; it costs a load ten minutes to have it in every attempt
     and it closed none of them *)
  (ATTEMPT_TAC 2
    (REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
     ASM_REWRITE_TAC[get_real_addr_def; memory_rel_tl;
       memory_rel_ByteArray_IMP; make_zeros_def; dimword;
       good_dimindex_def] THEN
     TRY ASM_ARITH_TAC)));;

(* --------- str_cmp --------- *)

let word_str_cmp_loop_def = cake_define
  `word_str_cmp_loop (a1:'a word) (a2:'a word) r1 r2 (len:'a word) dm m
  be' ck =
     (if ck = 0 then NONE else
     if len = bytes_in_word then
       SOME (r1,r2) else
       match mem_load_byte_aux m dm be' a1 with NONE -> NONE | SOME
         b1 ->
       (match mem_load_byte_aux m dm be' a2 with NONE -> NONE | SOME
         b2 ->
         (if b1 = b2 then
           word_str_cmp_loop (a1 + (n2w 1)) (a2 + (n2w 1)) r1 r2 (len
             - (n2w 1)) dm m be' (ck - (1:num)) else
           SOME (w2w b1,w2w b2))))`;;

let word_str_cmp_def = cake_define
  `word_str_cmp b (a1:'a word) (a2:'a word) dm m be' c =
     (let k = (dimindex (:'a) - data_to_word_config_len_size c -
       backend_common_word_shift (:'a)) in
       if a1 IN dm /\ a2 IN dm /\ isWord (m a1) /\ isWord (m a2) then
         let l1 = (theWord (m a1) >>> k) in
         let l2 = (theWord (m a2) >>> k) in
           if b then
             (if ~(l1 = l2) then SOME (l1,l2) else
                word_str_cmp_loop (a1 + bytes_in_word) (a2 +
                  bytes_in_word) l1 l1 l1 dm m be' (dimword (:'a))) else
             (let l = n2w (MIN (w2n l1) (w2n l2)) in
                word_str_cmp_loop (a1 + bytes_in_word) (a2 +
                  bytes_in_word) l1 l2 l dm m be' (dimword (:'a)))
                  else NONE)`;;

let find_diff_def = cake_define_list
  [`find_diff [] [] r1 r2 = (r1,r2)`;
   `find_diff (x :: xs) (y :: ys) r1 r2 = (if x = y then find_diff
  xs ys r1 r2 else (w2w x,w2w y))`];;

(* the port's own: what a loop over the bytes of a string needs.
   Four word equations say where the next byte is and what the
   counter of the loop becomes (wsl_add0, wsl_zero, wsl_addr and
   wsl_down), wsl_ne says that the length the loop counts down is
   not the one it stops at while it is below the word size, and
   loads_cons is what HOL4 gets from `first_assum dxrule`: the
   head of the list is the byte at the address, and the tail is
   what the induction is about *)

let wsl_add0 = prove
 (`!(a:'a word). a + n2w 0 = a`,
  CONV_TAC WORD_RULE);;

let wsl_zero = prove
 (`!(w:'a word). n2w 0 + w = w`,
  CONV_TAC WORD_RULE);;

let wsl_down = prove
 (`!(w:'a word) n. (n2w (SUC n) + w) - n2w 1 = n2w n + w`,
  REWRITE_TAC[ADD1; WORD_ADD] THEN CONV_TAC WORD_RULE);;

let wsl_addr = prove
 (`!(a:'a word) i. a + n2w (SUC i) = (a + n2w 1) + n2w i`,
  REWRITE_TAC[ADD1; WORD_ADD] THEN CONV_TAC WORD_RULE);;

let wsl_ne = prove
 (`!(w:'a word) n. n < dimword (:'a) ==> (n2w n + w = w <=> n = 0)`,
  REPEAT STRIP_TAC THEN
   SUBGOAL_THEN `(n2w n + w:'a word = w) <=> (n2w n:'a word) = n2w 0`
     SUBST1_TAC THENL
    [CONV_TAC WORD_RULE;
     ASM_SIMP_TAC[WORD_EQ_0; GSYM dimword]]);;

let wsl_nil = prove
 (`!(l:A list). TAKE 0 l = []`,
  LIST_INDUCT_TAC THEN REWRITE_TAC[TAKE]);;

let loads_cons = prove
 (`!m dm be' (a:'a word) h t.
    (!i. i < LENGTH (CONS h t) ==>
         mem_load_byte_aux m dm be' (a + n2w i) =
         SOME (EL i (CONS h t)))
    ==> mem_load_byte_aux m dm be' a = SOME h /\
        (!i. i < LENGTH t ==>
             mem_load_byte_aux m dm be' ((a + n2w 1) + n2w i) =
             SOME (EL i t))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN CONJ_TAC THENL
    [FIRST_ASSUM (MP_TAC o SPEC `0`) THEN
     REWRITE_TAC[LENGTH; EL; HD; LT_0; wsl_add0] THEN
     DISCH_THEN ACCEPT_TAC;
     GEN_TAC THEN DISCH_TAC THEN
     ONCE_REWRITE_TAC[GSYM wsl_addr] THEN
     ASM_SIMP_TAC[LENGTH; LT_SUC; EL; TL]]);;

let word_str_loop_thm = prove
 (`!k a1 a2 r1 r2 dm m be' d vals1 vals2.
     (!i. i < LENGTH vals1 ==> mem_load_byte_aux m dm be' (a1 + n2w
       i) = SOME (EL i vals1)) /\
     (!i. i < LENGTH vals2 ==> mem_load_byte_aux m dm be' (a2 + n2w
       i) = SOME (EL i vals2)) /\
     k <= LENGTH vals1 /\
     k <= LENGTH vals2 /\
     k < d /\ d <= dimword (:'a) ==>
     word_str_cmp_loop a1 a2 r1 r2 (n2w k + (bytes_in_word:'a word))
       dm m be' d =
     SOME (find_diff (TAKE k vals1) (TAKE k vals2) r1 r2)`,
(* the proof of the source is an induction on the number of bytes
   the loop has still to read.  At nought the length is the one
   the loop stops at and both lists are taken to nothing; at a
   step the cells at the two addresses are the heads of the lists
   (loads_cons), the loop reads them and goes on with the tails
   while they agree, and find_diff does the same *)
  (INDUCT_TAC THENL
   [(* the loop is at the length it stops at *)
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    ONCE_REWRITE_TAC[word_str_cmp_loop_def] THEN
    SUBGOAL_THEN `~(d = 0)` ASSUME_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[wsl_zero; wsl_nil; find_diff_def];
    (* both lists have a cell to read *)
    REPEAT GEN_TAC THEN
    CASES_BY_NAME "vals1" THENL
     [REWRITE_TAC[LENGTH; ARITH_RULE `~(SUC k <= 0)`];
      CASES_BY_NAME "vals2" THENL
       [REWRITE_TAC[LENGTH; ARITH_RULE `~(SUC k <= 0)`];
        STRIP_TAC THEN
        (* the head of each list is what the loop reads, and the
           tail is what the induction is about *)
        REPEAT (FIRST_X_ASSUM (fun th ->
          if is_forall (concl th)
          then STRIP_ASSUME_TAC (MATCH_MP loads_cons th)
          else fail())) THEN
        REWRITE_TAC[TAKE; NOT_SUC; SUC_SUB1; find_diff_def] THEN
        ONCE_REWRITE_TAC[word_str_cmp_loop_def] THEN
        SUBGOAL_THEN `SUC k < dimword (:'a)` ASSUME_TAC THENL
         [ASM_ARITH_TAC; ALL_TAC] THEN
        SUBGOAL_THEN `~(d = 0)` ASSUME_TAC THENL
         [ASM_ARITH_TAC; ALL_TAC] THEN
        ASM_SIMP_TAC[wsl_ne; NOT_SUC] THEN
        TRY SAFE_MATCH_REDUCE_TAC THEN ASM_REWRITE_TAC[] THEN
        TRY SAFE_MATCH_REDUCE_TAC THEN
        COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
        (* and the loop goes on with the tails *)
        REWRITE_TAC[wsl_down] THEN
        FIRST_ASSUM MATCH_MP_TAC THEN
        RULE_ASSUM_TAC (REWRITE_RULE[LENGTH]) THEN
        REPEAT CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
          ASM_ARITH_TAC; ASM_ARITH_TAC; ASM_ARITH_TAC;
          ASM_ARITH_TAC]]]]));;

(* [local] *)
let compoare_aux_append_xs = prove
 (`!zs z xs ys r.
     LENGTH xs <= LENGTH ys ==>
     compare_aux (implode (z :: (zs ++ xs)))
                 (implode (z :: (zs ++ ys))) r (LENGTH zs + 1)
                   (STRLEN xs) =
     compare_aux (implode (zs ++ xs)) (implode (zs ++ ys)) r
       (LENGTH zs) (STRLEN xs)`,
  (* the same character in front of both strings and the index one
     further on compare the same characters: the induction is on the
     length that is left to compare, and the premise about the two
     lengths is not needed *)
  (let shift_lemma = prove
    (`!len start r (zz:char) l1 l2.
        compare_aux (implode (CONS zz l1)) (implode (CONS zz l2)) r
          (start + 1) len =
        compare_aux (implode l1) (implode l2) r start len`,
     let el_suc = prove
      (`!n h (t:A list). EL (n + 1) (CONS h t) = EL n t`,
       REWRITE_TAC[GSYM ADD1; EL; TL]) in
     INDUCT_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[compare_aux_def] THEN
     REWRITE_TAC[NOT_SUC; SUC_SUB1; strsub_def; el_suc] THEN
     ASM_REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN DISCH_TAC THEN MATCH_ACCEPT_TAC shift_lemma));;

(* [local] *)
let compoare_aux_append_ys = prove
 (`!zs z xs ys r.
     LENGTH ys <= LENGTH xs ==>
     compare_aux (implode (z :: (zs ++ xs)))
                 (implode (z :: (zs ++ ys))) r (LENGTH zs + 1)
                   (STRLEN ys) =
     compare_aux (implode (zs ++ xs)) (implode (zs ++ ys)) r
       (LENGTH zs) (STRLEN ys)`,
  (* and the same of the shorter second string *)
  (let shift_lemma = prove
    (`!len start r (zz:char) l1 l2.
        compare_aux (implode (CONS zz l1)) (implode (CONS zz l2)) r
          (start + 1) len =
        compare_aux (implode l1) (implode l2) r start len`,
     let el_suc = prove
      (`!n h (t:A list). EL (n + 1) (CONS h t) = EL n t`,
       REWRITE_TAC[GSYM ADD1; EL; TL]) in
     INDUCT_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[compare_aux_def] THEN
     REWRITE_TAC[NOT_SUC; SUC_SUB1; strsub_def; el_suc] THEN
     ASM_REWRITE_TAC[]) in
   REPEAT GEN_TAC THEN DISCH_TAC THEN MATCH_ACCEPT_TAC shift_lemma));;

let compare_same = prove
 (`compare (implode (x :: xs)) (implode (x :: ys)) =
   compare (implode xs) (implode ys)`,
  (* the first characters are the same, so the comparison steps over
     them: the index goes up by one, which the shift of
     compoare_aux_append_xs takes off again, and the lengths are one
     less on both sides *)
  (let shift_lemma = prove
    (`!len start r (zz:char) l1 l2.
        compare_aux (implode (CONS zz l1)) (implode (CONS zz l2)) r
          (start + 1) len =
        compare_aux (implode l1) (implode l2) r start len`,
     let el_suc = prove
      (`!n h (t:A list). EL (n + 1) (CONS h t) = EL n t`,
       REWRITE_TAC[GSYM ADD1; EL; TL]) in
     INDUCT_TAC THEN REPEAT GEN_TAC THEN
     ONCE_REWRITE_TAC[compare_aux_def] THEN
     REWRITE_TAC[NOT_SUC; SUC_SUB1; strsub_def; el_suc] THEN
     ASM_REWRITE_TAC[]) in
   let first_eq = prove
    (`!r (zz:char) l1 l2 n.
        compare_aux (implode (CONS zz l1)) (implode (CONS zz l2)) r 0
          (SUC n) =
        compare_aux (implode l1) (implode l2) r 0 n`,
     REPEAT GEN_TAC THEN
     GEN_REWRITE_TAC LAND_CONV [compare_aux_def] THEN
     REWRITE_TAC[NOT_SUC; SUC_SUB1; strsub_def; EL; HD;
                 char_lt; LT_REFL; shift_lemma]) in
   REWRITE_TAC[mlstring_compare_def; strlen_def;
               LENGTH; LT_SUC; first_eq]));;

let str_cmp_cons = prove
 (`str_cmp b cmp (implode (x :: xs)) (implode (x :: ys)) =
   str_cmp b cmp (implode xs) (implode ys)`,
  (* each of the eight comparisons is the one of mlstring_compare,
     which compare_same takes off the first character, or a
     comparison of the lengths, which are one less *)
  (REWRITE_TAC[str_cmp_def] THEN
   CASES_ON_NAME "b" THEN CASES_ON_NAME "cmp" THEN
   MATCH_REDUCE_TAC THEN
   REWRITE_TAC[mlstring_lt_def; mlstring_le_def;
               mlstring_gt_def; mlstring_ge_def;
               fast_lt_def; fast_le_def;
               fast_gt_def; fast_ge_def;
               compare_same; strlen_def;
               LENGTH; SUC_INJ; LT_SUC; LE_SUC;
               GT; GE; ARITH_RULE `SUC m >= SUC n <=> m >= n`;
               ARITH_RULE `SUC m > SUC n <=> m > n`]));;

(* the port's own: what the comparison of two strings of bytes
   needs of the characters.  HOL4's EVAL_TAC computes with ORD and
   CHR, and what that comes to here is ord_chr, the one fact that
   the eight bits of a character of the port spell the number it
   came from; ord_chr_w2n is its instance at a byte, w2w_val_8 says
   that a byte keeps its value in a word of the target, and lt_asym
   is what a case of LT_CASES leaves to say *)

let ord_chr = prove
 (`!n. n < 256 ==> ORD (CHR n) = n`,
  REWRITE_TAC[CHR; ORD] THEN CONV_TAC EXPAND_CASES_CONV THEN
   CONV_TAC NUM_REDUCE_CONV);;

let ord_chr_w2n = prove
 (`!(w:word8). ORD (CHR (w2n w)) = w2n w`,
  GEN_TAC THEN MATCH_MP_TAC ord_chr THEN
   MP_TAC (ISPEC `w:word8` VAL_BOUND) THEN
   REWRITE_TAC[DIMINDEX_8] THEN CONV_TAC NUM_REDUCE_CONV THEN
   DISCH_THEN ACCEPT_TAC);;

let w2w_val_8 = prove
 (`!(w:word8). good_dimindex (:'a) ==>
    w2n ((w2w:word8->'a word) w) = w2n w`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC VAL_WORD_ZX THEN
   REWRITE_TAC[DIMINDEX_8] THEN
   FIRST_ASSUM (MP_TAC o REWRITE_RULE[good_dimindex_def]) THEN
   ARITH_TAC);;

let lt_asym = prove
 (`!a b:num. a < b ==> ~(b < a)`,
  ARITH_TAC);;

let find_diff_str_cmp_thm1 = prove
 (`!vals1 vals2.
     LENGTH (vals1:word8 list) = LENGTH (vals2:word8 list) /\
     good_dimindex (:'a) ==>
     (?(r1:'a word) (r2:'a word).
       find_diff vals1 vals2 (n2w l) (n2w l) = (r1,r2) /\
       (str_cmp T cmp (implode (MAP (CHR o w2n) vals1)) (implode (MAP
         (CHR o w2n) vals2)) <=>
        num_cmp cmp (w2n r1) (w2n r2)))`,
(* the proof of the source is an induction on the first list.  Two
   empty lists compare equal and the two accumulators are the same
   number, so each of the four comparisons holds of the one exactly
   when it holds of the other; with a byte in front of each, either
   the two bytes are the same, and then str_cmp_cons steps over
   them and find_diff does too, which is the induction hypothesis,
   or they differ, and then the first character decides the
   comparison of the strings and the two bytes decide the
   comparison of the numbers *)
  (LIST_INDUCT_TAC THEN GEN_TAC THENL
   [(* both lists are empty: the strings compare equal, and so do
       the two accumulators *)
    STRIP_TAC THEN
    FIRST_ASSUM (fun th ->
      SUBST_ALL_TAC (REWRITE_RULE[LENGTH_EQ_NIL]
        (SYM (REWRITE_RULE[LENGTH] th)))) THEN
    MAP_EVERY EXISTS_TAC [`(n2w l):'a word`; `(n2w l):'a word`] THEN
    REWRITE_TAC[find_diff_def; MAP; PAIR_EQ] THEN
    CASES_ON_NAME "cmp" THEN
    REWRITE_TAC[str_cmp_def] THEN MATCH_REDUCE_TAC THEN
    REWRITE_TAC[fast_lt_def; fast_le_def; fast_gt_def; fast_ge_def;
                mlstring_lt_def; mlstring_le_def; mlstring_gt_def;
                mlstring_ge_def; mlstring_compare_def; strlen_def;
                LENGTH; LT_REFL] THEN
    ONCE_REWRITE_TAC[compare_aux_def] THEN
    REWRITE_TAC[num_cmp_def; distinctness "ordering"; LE_REFL;
                LT_REFL; GT; GE];
    (* the two lists have a first byte each *)
    CASES_BY_NAME "vals2" THENL
     [REWRITE_TAC[LENGTH; NOT_SUC];
      STRIP_TAC THEN
      RULE_ASSUM_TAC (REWRITE_RULE[LENGTH; SUC_INJ]) THEN
      (* the two first bytes, out of the call of find_diff *)
      W(fun (asl,w) ->
        let fd = find_term (hd_is "find_diff")
                   (snd (strip_exists w)) in
        let args = snd (strip_comb fd) in
        ASM_CASES_TAC (mk_eq (hd (snd (strip_comb (el 0 args))),
                              hd (snd (strip_comb (el 1 args))))))
        THENL
       [(* they agree: the comparison steps over them, and so does
           find_diff, so the induction hypothesis is what is left *)
        FIRST_X_ASSUM (fun th ->
          if (try is_var (lhs (concl th)) with Failure _ -> false)
          then SUBST_ALL_TAC th else fail()) THEN
        REWRITE_TAC[find_diff_def; MAP; o_THM; str_cmp_cons] THEN
        FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        (* they differ, and the first one decides the comparison *)
        ASM_REWRITE_TAC[find_diff_def; MAP; o_THM] THEN
        W(fun (asl,w) ->
          let ps = tparts (lhand (hd (conjuncts
                     (snd (strip_exists w))))) in
          MAP_EVERY EXISTS_TAC [el 0 ps; el 1 ps]) THEN
        REWRITE_TAC[PAIR_EQ] THEN
        (* the two bytes differ as numbers, and a byte is a number
           of the word size *)
        RULE_ASSUM_TRY (REWRITE_RULE[GSYM VAL_EQ]) THEN
        FIRST_ASSUM (fun gd ->
          REWRITE_TAC[MATCH_MP (SPEC_ALL w2w_val_8) gd]) THEN
        CASES_ON_NAME "cmp" THEN
        REWRITE_TAC[str_cmp_def] THEN MATCH_REDUCE_TAC THEN
        REWRITE_TAC[fast_lt_def; fast_le_def; fast_gt_def;
                    fast_ge_def; mlstring_lt_def; mlstring_le_def;
                    mlstring_gt_def; mlstring_ge_def;
                    mlstring_compare_def; strlen_def; LENGTH;
                    LENGTH_MAP] THEN
        ASM_REWRITE_TAC[LT_REFL] THEN
        ONCE_REWRITE_TAC[compare_aux_def] THEN
        REWRITE_TAC[NOT_SUC; strsub_def; EL; HD; char_lt;
                    ord_chr_w2n] THEN
        REWRITE_TAC[num_cmp_def; GT; GE] THEN
        FIRST_ASSUM (fun ne ->
          let (a,b) = dest_eq (rand (concl ne)) in
          STRIP_ASSUME_TAC (SPECL [a; b] LT_CASES)) THEN
        FIRST
         [CONTRA_TAC;
          FIRST_ASSUM (fun th ->
            ASSUME_TAC (MATCH_MP lt_asym th)) THEN
          ASM_REWRITE_TAC[distinctness "ordering"] THEN
          ASM_ARITH_TAC]]]]));;

let MIN_SUC_SUC = prove
 (`MIN (SUC m) (SUC n) = SUC (MIN m n)`,
  (ARITH_TAC));;

(* the port's own: the three things the statement below needs of
   numbers.  The two MIN clauses and MIN_SUC_SUC above are what
   HOL4's simplifier knows of MIN; and acc_step is the step of the
   two accumulators -- a byte more in front of the list is one
   more on the counter *)

let min_0l = prove
 (`!n. MIN 0 n = 0`,
  REWRITE_TAC[MIN; LE_0]);;

let min_0r = prove
 (`!n. MIN n 0 = 0`,
  GEN_TAC THEN REWRITE_TAC[MIN] THEN
  COND_CASES_TAC THEN ASM_ARITH_TAC);;

let acc_step = prove
 (`!k n s. k + (SUC n + s) = (k + 1) + (n + s)`,
  ARITH_TAC);;

let find_diff_str_cmp_thm2 = prove
 (`!k vals1 vals2 l1 l2.
     Abbrev (l1 = LENGTH vals1 + 2 EXP backend_common_word_shift
       (:'a)) /\
     Abbrev (l2 = LENGTH vals2 + 2 EXP backend_common_word_shift
       (:'a)) /\
     k + l1 < dimword (:'a) /\ k + l2 < dimword (:'a) /\
       good_dimindex (:'a) ==>
     (?(r1:'a word) (r2:'a word).
       find_diff (TAKE (MIN (LENGTH vals1) (LENGTH vals2))
         (vals1:word8 list))
                 (TAKE (MIN (LENGTH vals1) (LENGTH vals2)) vals2)
                 (n2w (k + l1))
                 (n2w (k + l2)) = (r1,r2) /\
       (str_cmp F cmp (implode (MAP (CHR o w2n) vals1))
                      (implode (MAP (CHR o w2n) vals2)) <=>
        num_cmp cmp (w2n r1) (w2n r2)))`,
(* the proof of the source is an induction on the first list, with
   four cases.  Two empty lists give the same word twice; one empty
   list gives the shorter string and the smaller word, whichever it
   is; and with a byte in front of each, either the two bytes agree
   and str_cmp_cons and the induction hypothesis one byte further
   on (acc_step) do the rest, or they differ and the first
   character decides the comparison whatever the two lengths are,
   which is why the three branches of mlstring_compare all give the
   same answer here *)
  ((* the hypotheses of the statement, with the two abbreviations
     put in and the lengths of the two lists worked out *)
  let prep =
    STRIP_TAC THEN
    REPEAT (FIRST_X_ASSUM (fun th ->
      if (try is_var (lhs (concl th)) with Failure _ -> false)
      then SUBST_ALL_TAC th else fail())) THEN
    RULE_ASSUM_TAC (REWRITE_RULE[LENGTH]) THEN
    REWRITE_TAC[LENGTH; min_0l; min_0r; MIN_SUC_SUC; TAKE;
                NOT_SUC; SUC_SUB1; find_diff_def] in
  (* the two words that find_diff returns *)
  let pick_pair =
    W(fun (asl,w) ->
      let ps = tparts (lhand (hd (conjuncts
                 (snd (strip_exists w))))) in
      MAP_EVERY EXISTS_TAC [el 0 ps; el 1 ps]) THEN
    REWRITE_TAC[PAIR_EQ] in
  (* each of the four comparisons, down to the comparison of the
     two strings that mlstring_compare makes *)
  let cmp_cases =
    CASES_ON_NAME "cmp" THEN
    REWRITE_TAC[str_cmp_def] THEN MATCH_REDUCE_TAC THEN
    REWRITE_TAC[mlstring_lt_def; mlstring_le_def; mlstring_gt_def;
                mlstring_ge_def; mlstring_compare_def; strlen_def;
                MAP; o_THM; LENGTH; LENGTH_MAP; num_cmp_def;
                GT; GE] in
  REWRITE_TAC[abbrev_def] THEN
  ONCE_REWRITE_TAC[SWAP_FORALL_THM] THEN
  LIST_INDUCT_TAC THEN REPEAT GEN_TAC THEN
  CASES_BY_NAME "vals2" THENL
   [(* both lists are empty: the two words are the same *)
    prep THEN pick_pair THEN cmp_cases THEN
    REWRITE_TAC[LT_REFL] THEN
    ONCE_REWRITE_TAC[compare_aux_def] THEN
    REWRITE_TAC[distinctness "ordering"; LT_REFL; LE_REFL];
    (* the first list is empty, so it is the smaller string, and
       its word is the smaller number *)
    prep THEN pick_pair THEN
    ASM_SIMP_TAC[val_n2w_lt] THEN cmp_cases THEN
    REWRITE_TAC[LT_0; ARITH_RULE `~(SUC n < 0)`] THEN
    ONCE_REWRITE_TAC[compare_aux_def] THEN
    REWRITE_TAC[distinctness "ordering"] THEN ARITH_TAC;
    (* the second list is empty, so the first is the greater
       string and its word is the greater number *)
    prep THEN pick_pair THEN
    ASM_SIMP_TAC[val_n2w_lt] THEN cmp_cases THEN
    REWRITE_TAC[LT_0; ARITH_RULE `~(SUC n < 0)`] THEN
    ONCE_REWRITE_TAC[compare_aux_def] THEN
    REWRITE_TAC[distinctness "ordering"] THEN ARITH_TAC;
    (* both lists have a byte each *)
    prep THEN
    W(fun (asl,w) ->
      (* this file binds is_cond to something else of its own
         (line 36808), so the test for a conditional is here *)
      let a_cond t =
        try fst (dest_const (fst (strip_comb t))) = "COND"
        with Failure _ -> false in
      let c = find_term a_cond (snd (strip_exists w)) in
      ASM_CASES_TAC (el 0 (snd (strip_comb c)))) THENL
     [(* the two bytes agree: the comparison steps over them and
         find_diff goes on with the tails, one byte further on *)
      FIRST_X_ASSUM (fun th ->
        if (try is_var (lhs (concl th)) with Failure _ -> false)
        then SUBST_ALL_TAC th else fail()) THEN
      REWRITE_TAC[MAP; o_THM; str_cmp_cons; acc_step] THEN
      FIRST_ASSUM MATCH_MP_TAC THEN
      REPEAT CONJ_TAC THENL
       [REFL_TAC; REFL_TAC; ASM_ARITH_TAC; ASM_ARITH_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      (* they differ, and the first character decides the
         comparison, whatever the two lengths are *)
      ASM_REWRITE_TAC[] THEN pick_pair THEN
      RULE_ASSUM_TRY (REWRITE_RULE[GSYM VAL_EQ]) THEN
      FIRST_ASSUM (fun gd ->
        REWRITE_TAC[MATCH_MP (SPEC_ALL w2w_val_8) gd]) THEN
      cmp_cases THEN
      GEN_REWRITE_TAC ONCE_DEPTH_CONV [compare_aux_def] THEN
      REWRITE_TAC[NOT_SUC; strsub_def; EL; HD; char_lt;
                  ord_chr_w2n] THEN
      FIRST_ASSUM (fun ne ->
        let (a,b) = dest_eq (rand (concl ne)) in
        STRIP_ASSUME_TAC (SPECL [a; b] LT_CASES)) THEN
      FIRST
       [CONTRA_TAC;
        FIRST_ASSUM (fun th ->
          ASSUME_TAC (MATCH_MP lt_asym th)) THEN
        ASM_REWRITE_TAC[distinctness "ordering"; COND_ID] THEN
        ASM_ARITH_TAC]]]));;

(* the port's own: what the comparison of two byte arrays needs of
   the header and of the address arithmetic.  header_shift is the
   one place where the two word sizes are taken apart: what
   memory_rel_ByteArray_IMP says of the header is a conditional on
   dimindex, and this turns it into the length plus 2 EXP the word
   shift, whichever the word size is, so that nothing after it has
   to case split again.  biw_shift and len_plus are the same step
   for bytes_in_word, min_shift for the shorter of two lengths,
   take_all and take_all_eq for the whole of a list, and n2w_11_lt
   says that two numbers below the word size make the same word
   only when they are the same *)

let take_all = prove
 (`!(l:A list). TAKE (LENGTH l) l = l`,
  GEN_TAC THEN
  MP_TAC (ISPECL [`l:A list`; `[]:A list`] TAKE_LENGTH_APPEND) THEN
  REWRITE_TAC[APPEND_NIL]);;

let take_all_eq = prove
 (`!(l1:A list) l2.
     LENGTH l1 = LENGTH l2 ==> TAKE (LENGTH l1) l2 = l2`,
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[take_all]);;

let min_shift = prove
 (`!a b s. MIN (a + s) (b + s) = MIN a b + s`,
  ARITH_TAC);;

let biw_shift = prove
 (`good_dimindex (:'a) ==>
  (bytes_in_word:'a word) =
  n2w (2 EXP backend_common_word_shift (:'a))`,
  REWRITE_TAC[good_dimindex_def; bytes_in_word_def;
              word_shift_def] THEN
  STRIP_TAC THEN FIRST_X_ASSUM SUBST1_TAC THEN
  REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV);;

let len_plus = prove
 (`!n. good_dimindex (:'a) ==>
    n2w n + (bytes_in_word:'a word) =
    n2w (n + 2 EXP backend_common_word_shift (:'a))`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[biw_shift; WORD_ADD]);;

let header_shift = prove
 (`good_dimindex (:'a) /\
  (if dimindex (:'a) = 32 then
     n + 4 < 2 EXP (dimindex (:'a) - 3) /\
     (x:'a word) >>> (dimindex (:'a) -
       data_to_word_config_len_size c - 2) = n2w (n + 4)
   else
     n + 8 < 2 EXP (dimindex (:'a) - 3) /\
     x >>> (dimindex (:'a) -
       data_to_word_config_len_size c - 3) = n2w (n + 8))
  ==> x >>> (dimindex (:'a) - data_to_word_config_len_size c -
             backend_common_word_shift (:'a)) =
      n2w (n + 2 EXP backend_common_word_shift (:'a)) /\
      n + 2 EXP backend_common_word_shift (:'a) < dimword (:'a)`,
  REWRITE_TAC[good_dimindex_def; word_shift_def; dimword] THEN
  STRIP_TAC THEN
  FIRST_X_ASSUM (fun dd ->
    if is_eq (concl dd) then SUBST_ALL_TAC dd else fail()) THEN
  RULE_ASSUM_TAC (CONV_RULE NUM_REDUCE_CONV o REWRITE_RULE[]) THEN
  REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

(* the names of record fields that this statement uses for
   variables of its own are read as variables *)
let memory_rel_str_cmp = prove
 (cake_as_vars (fun () ->
    `memory_rel c be ts refs sp st m dm
       ((RefPtr bl1 p1,(v1:'a word_loc)) :: (RefPtr bl2 p2,(v2:'a
         word_loc)) :: vars) /\
     lookup p1 refs = SOME (ByteArray fl1 vals1) /\
     lookup p2 refs = SOME (ByteArray fl2 vals2) /\
     good_dimindex (:'a) ==>
     (?w1 a1 w2 a2 x1 m1 r1 r2.
       v1 = wordLang_Word w1 /\
       v2 = wordLang_Word w2 /\
       get_real_addr c st w1 = SOME a1 /\
       get_real_addr c st w2 = SOME a2 /\
       word_str_cmp b a1 a2 dm m be c = SOME (r1,r2) /\
       str_cmp b cmp (implode (MAP (CHR o w2n) vals1))
                     (implode (MAP (CHR o w2n) vals2)) =
       semanticPrimitives_num_cmp cmp (w2n r1) (w2n r2))`),
(* the proof of the source takes the two byte arrays out of the
   memory (memory_rel_ByteArray_IMP, twice, with memory_rel_tl in
   between), reads the length of each off its header
   (header_shift), and then word_str_cmp is the loop of
   word_str_loop_thm: for the fast comparison over both strings if
   the two lengths are the same and nothing at all if they are not,
   and for the slow one to the shorter of the two.  What is left of
   the comparison of the strings is the first of the two lemmas
   above in the one case and the second of them at nought in the
   other *)
  ((* this file binds is_cond to something else of its own (line
     36808), so the test for a conditional is here *)
  let a_cond t =
    try fst (dest_const (fst (strip_comb t))) = "COND"
    with Failure _ -> false in
  (* what the memory holds for a byte array *)
  let byte_array =
    FIRST_ASSUM (fun mr -> FIRST_ASSUM (fun lk ->
      FIRST_ASSUM (fun gd ->
        STRIP_ASSUME_TAC (MATCH_MP memory_rel_ByteArray_IMP
          (CONJ mr (CONJ lk gd)))))) in
  (* the header of each, shifted down, is the length plus the word
     size, whichever the word size is *)
  let header =
    REPEAT (FIRST_X_ASSUM (fun cd ->
      if not (a_cond (concl cd)) then fail() else
      FIRST_ASSUM (fun gd ->
        STRIP_ASSUME_TAC (MATCH_MP header_shift (CONJ gd cd))))) in
  (* the loop of the comparison, at the number of bytes it reads *)
  let loop_at k =
    W(fun (asl,w) ->
      let lp = find_term (fun t ->
                 hd_is "word_str_cmp_loop" t &&
                 length (snd (strip_comb t)) = 9)
                 (snd (strip_exists w)) in
      let g = snd (strip_comb lp) in
      MP_TAC (ISPECL [k; el 0 g; el 1 g; el 2 g; el 3 g; el 5 g;
                     el 6 g; el 7 g; el 8 g; var_by_name "vals1"
                     (asl,w); var_by_name "vals2" (asl,w)]
                word_str_loop_thm)) in
  STRIP_TAC THEN byte_array THEN
  FIRST_ASSUM (fun mr -> ASSUME_TAC (MATCH_MP memory_rel_tl mr)) THEN
  byte_array THEN header THEN
  (* the two words and the two addresses *)
  W(fun (asl,w as gl) ->
    let vs = fst (strip_exists w) in
    let wof v = rand (rand (concl (the_asm (fun c ->
                  try is_eq c && lhs c = v with Failure _ -> false)
                  gl))) in
    let aof wd = rand (rand (concl (the_asm (fun c ->
                  try is_eq c && hd_is "get_real_addr" (lhs c) &&
                      el 2 (snd (strip_comb (lhs c))) = wd
                  with Failure _ -> false) gl))) in
    let w1 = wof (var_by_name "v1" gl)
    and w2 = wof (var_by_name "v2" gl) in
    MAP_EVERY EXISTS_TAC
      [w1; aof w1; w2; aof w2; el 4 vs; el 5 vs]) THEN
  ASM_REWRITE_TAC[word_str_cmp_def] THEN
  CONV_TAC (TOP_DEPTH_CONV let_CONV) THEN
  ASM_REWRITE_TAC[isWord_def; theWord_def] THEN
  TRY SAFE_MATCH_REDUCE_TAC THEN
  ASM_SIMP_TAC[val_n2w_lt; n2w_11_lt; min_shift] THEN
  ASM_CASES_TAC `b:bool` THEN ASM_REWRITE_TAC[] THENL
   [(* the fast comparison, and the two lengths are the same: the
       loop runs over both strings *)
    ASM_CASES_TAC
      `LENGTH (vals1:word8 list) = LENGTH (vals2:word8 list)` THENL
     [SUBGOAL_THEN
        `~(~(LENGTH (vals1:word8 list) +
             2 EXP backend_common_word_shift (:'a) =
             LENGTH (vals2:word8 list) +
             2 EXP backend_common_word_shift (:'a)))`
        (fun th -> REWRITE_TAC[th]) THENL
       [ASM_ARITH_TAC; ALL_TAC] THEN
      loop_at `LENGTH (vals1:word8 list)` THEN
      ANTS_TAC THENL
       [REWRITE_TAC[GSYM WORD_ADD_ASSOC] THEN
        REPEAT CONJ_TAC THEN
        TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
        ASM_ARITH_TAC;
        ALL_TAC] THEN
      ASM_SIMP_TAC[len_plus; take_all; take_all_eq] THEN
      DISCH_THEN SUBST1_TAC THEN
      REWRITE_TAC[injectivity "option"] THEN
      MATCH_MP_TAC find_diff_str_cmp_thm1 THEN ASM_REWRITE_TAC[];
      (* and they are not: the longer string is the greater one,
         and so is its word *)
      SUBGOAL_THEN
        `~(LENGTH (vals1:word8 list) +
           2 EXP backend_common_word_shift (:'a) =
           LENGTH (vals2:word8 list) +
           2 EXP backend_common_word_shift (:'a))`
        (fun th -> REWRITE_TAC[th]) THENL
       [ASM_ARITH_TAC; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC
        [`n2w (LENGTH (vals1:word8 list) +
               2 EXP backend_common_word_shift (:'a)):'a word`;
         `n2w (LENGTH (vals2:word8 list) +
               2 EXP backend_common_word_shift (:'a)):'a word`] THEN
      REWRITE_TAC[] THEN
      ASM_SIMP_TAC[val_n2w_lt] THEN
      CASES_ON_NAME "cmp" THEN
      REWRITE_TAC[str_cmp_def] THEN MATCH_REDUCE_TAC THEN
      REWRITE_TAC[fast_lt_def; fast_le_def; fast_gt_def;
                  fast_ge_def; strlen_def; LENGTH_MAP;
                  num_cmp_def; GT; GE] THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    (* the slow comparison: the loop runs to the shorter of the
       two, and what is left is the second of the two lemmas *)
    loop_at `MIN (LENGTH (vals1:word8 list))
                 (LENGTH (vals2:word8 list))` THEN
    ANTS_TAC THENL
     [REWRITE_TAC[GSYM WORD_ADD_ASSOC] THEN
      REPEAT CONJ_TAC THEN
      TRY (SOLVED (FIRST_ASSUM ACCEPT_TAC)) THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    ASM_SIMP_TAC[len_plus] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[injectivity "option"] THEN
    MP_TAC (ISPECL [`0`; `vals1:word8 list`; `vals2:word8 list`;
                   `LENGTH (vals1:word8 list) +
                    2 EXP backend_common_word_shift (:'a)`;
                   `LENGTH (vals2:word8 list) +
                    2 EXP backend_common_word_shift (:'a)`]
              find_diff_str_cmp_thm2) THEN
    REWRITE_TAC[abbrev_def; ADD_CLAUSES] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      DISCH_THEN ACCEPT_TAC]]));;

